-- Immutable CloudTMS TEST function snapshot, page 11.
-- Generated from pg_get_functiondef; definitions only, with function body checks deferred for forward references.
-- Do not edit an applied baseline page. Add or replace routine authority in supabase/repeatable.

\set ON_ERROR_STOP on
set check_function_bodies = off;
set search_path = pg_catalog, public, extensions;

-- pay_preview_candidate_collect_scope(jsonb,uuid,jsonb,integer)
CREATE OR REPLACE FUNCTION public.pay_preview_candidate_collect_scope(p_context_json jsonb, p_candidate_id uuid DEFAULT NULL::uuid, p_cursor_json jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "plpgsql_check.mode" TO 'disabled'
AS $function$
declare
  v_context_matches boolean := false;
  v_context_row_count integer := 0;
  v_context_json jsonb := coalesce(p_context_json, '{}'::jsonb);
  v_candidate_id uuid := p_candidate_id;
  v_pay_date date;
  v_week_ending_cutoff date;
  v_client_id uuid := null::uuid;
  v_actor_user_id uuid := null::uuid;
  v_week_start date;
  v_today_uk date;
  v_pay_eligibility_months_back int := 6;
  v_pay_eligibility_weeks_ahead int := 2;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_vat_rate_pct numeric;
  v_erni_pct numeric;
  v_rail_provider_default text;
  v_rail_env_default text;
  v_rail_supports_scheduling boolean := false;
  v_rail_supports_name_check boolean := false;
  v_rail_supports_auto_execute boolean := false;
  v_default_schedule_umbrella_local text;
  v_default_schedule_paye_local text;
  v_funds_warning_hours_json jsonb := '[]'::jsonb;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;
  v_refresh_scope_kind text := NULL;
  v_effective_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_targeted_timesheet_ids_requested_json jsonb := '[]'::jsonb;
  v_linked_timesheet_ids_requested_json jsonb := '[]'::jsonb;
  v_pay_channel_scope text := 'ALL';
  v_candidate_pay_method text := NULL::text;
  v_target_pay_batch_id_raw text := NULL::text;
  v_target_pay_batch_id uuid := NULL::uuid;
  v_target_operation_source_key text := NULL::text;
  v_source_build_mode boolean := false;
  v_source_build_requested_scope_kind text := NULL::text;
  v_source_build_actual_scope_kind text := NULL::text;
  v_source_build_cursor_in_json jsonb := NULL::jsonb;
  v_source_build_cursor_out_json jsonb := NULL::jsonb;
  v_source_build_page_limit integer := 100;
  v_source_build_last_timesheet_id uuid := NULL::uuid;
  v_source_build_next_timesheet_id uuid := NULL::uuid;
  v_source_build_target_page_count integer := 0;
  v_source_build_target_total_count integer := 0;
  v_source_build_has_more boolean := false;
  v_source_build_targeted_payload_received boolean := false;
  v_source_build_fallback_used boolean := false;
  v_source_build_fallback_reason text := NULL::text;
  v_source_build_allow_full_fallback boolean := false;
  v_source_build_candidate_filter_applied_early boolean := false;
  v_source_build_timesheet_filter_applied_early boolean := false;
  v_source_build_large_aggregation_avoided boolean := false;
  v_source_build_collect_started_at timestamptz := clock_timestamp();
  v_source_build_collect_elapsed_ms numeric := 0;
  v_lifecycle_reconciliation_mode boolean := false;
  v_historic_metadata_allowed boolean := false;
  v_signed_finance_reconciliation boolean := false;
  v_exclude_lifecycle_ineligible_current_payability boolean := false;
  v_authoritative_timesheet_scope boolean := false;
  v_internal_reconciliation_requested boolean := false;
  v_internal_reconciliation_authorised boolean := false;
  v_current_internal_authority_token text := NULL::text;
begin
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'p_context_json must be a JSON object';
  end if;


  v_source_build_mode := (
    LOWER(BTRIM(COALESCE(
      v_context_json->>'source_build_mode',
      v_context_json->>'workbench_source_build_mode',
      v_context_json #>> '{source_build,enabled}',
      v_context_json #>> '{workbench,source_build_mode}',
      ''
    ))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR UPPER(BTRIM(COALESCE(
      v_context_json->>'job_type',
      v_context_json #>> '{job,type}',
      v_context_json #>> '{source_build,job_type}',
      v_context_json #>> '{workbench,job_type}',
      ''
    ))) = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
  );

  v_lifecycle_reconciliation_mode := LOWER(BTRIM(COALESCE(
    v_context_json->>'lifecycle_reconciliation_mode',
    v_context_json #>> '{preview_decisions_json,lifecycle_reconciliation_mode}',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_historic_metadata_allowed := LOWER(BTRIM(COALESCE(
    v_context_json->>'historic_metadata_allowed',
    v_context_json #>> '{preview_decisions_json,historic_metadata_allowed}',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_signed_finance_reconciliation := LOWER(BTRIM(COALESCE(
    v_context_json->>'signed_finance_reconciliation',
    v_context_json #>> '{preview_decisions_json,signed_finance_reconciliation}',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_exclude_lifecycle_ineligible_current_payability := LOWER(BTRIM(COALESCE(
    v_context_json->>'exclude_lifecycle_ineligible_current_payability',
    v_context_json #>> '{preview_decisions_json,exclude_lifecycle_ineligible_current_payability}',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_authoritative_timesheet_scope := LOWER(BTRIM(COALESCE(
    v_context_json->>'authoritative_timesheet_scope',
    v_context_json #>> '{preview_decisions_json,authoritative_timesheet_scope}',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_internal_reconciliation_requested :=
    v_source_build_mode
    OR v_lifecycle_reconciliation_mode
    OR v_historic_metadata_allowed
    OR v_signed_finance_reconciliation
    OR v_exclude_lifecycle_ineligible_current_payability
    OR v_authoritative_timesheet_scope;

  v_current_internal_authority_token := NULLIF(BTRIM(COALESCE(
    current_setting('cloudtms.pay_workbench_overpayment_sync_token', true),
    ''
  )), '');

  v_internal_reconciliation_authorised :=
    v_internal_reconciliation_requested
    AND v_source_build_mode
    AND v_current_internal_authority_token IS NOT NULL;

  IF v_internal_reconciliation_requested
     AND v_internal_reconciliation_authorised IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_PREVIEW_COLLECT_SCOPE_INTERNAL_AUTHORITY_REQUIRED'
      USING ERRCODE = '42501',
            DETAIL = jsonb_build_object(
              'source_build_mode', COALESCE(v_source_build_mode, false),
              'transaction_authority_present', v_current_internal_authority_token IS NOT NULL,
              'lifecycle_reconciliation_mode', v_lifecycle_reconciliation_mode,
              'historic_metadata_allowed', v_historic_metadata_allowed,
              'signed_finance_reconciliation', v_signed_finance_reconciliation,
              'exclude_lifecycle_ineligible_current_payability', v_exclude_lifecycle_ineligible_current_payability,
              'authoritative_timesheet_scope', v_authoritative_timesheet_scope
            )::text;
  END IF;

  IF v_historic_metadata_allowed
     AND (
       v_authoritative_timesheet_scope IS NOT TRUE
       OR UPPER(BTRIM(COALESCE(
         v_context_json->>'refresh_scope_kind',
         v_context_json #>> '{preview_decisions_json,refresh_scope_kind}',
         ''
       ))) <> 'TARGETED_TIMESHEETS'
     ) THEN
    RAISE EXCEPTION 'PAY_PREVIEW_COLLECT_SCOPE_HISTORIC_METADATA_SCOPE_INVALID'
      USING ERRCODE = '22023',
            DETAIL = jsonb_build_object(
              'authoritative_timesheet_scope', v_authoritative_timesheet_scope,
              'refresh_scope_kind', COALESCE(
                v_context_json->>'refresh_scope_kind',
                v_context_json #>> '{preview_decisions_json,refresh_scope_kind}'
              )
            )::text;
  END IF;

  v_source_build_cursor_in_json := COALESCE(
    p_cursor_json,
    v_context_json->'source_cursor',
    v_context_json #> '{source_build,cursor}',
    v_context_json #> '{workbench,source_cursor}',
    NULL::jsonb
  );

  IF NULLIF(BTRIM(COALESCE(
       v_context_json->>'source_page_limit',
       v_context_json #>> '{source_build,limit}',
       v_context_json #>> '{workbench,source_build_limit}',
       ''
     )), '') ~ '^[0-9]+$' THEN
    v_source_build_page_limit := LEAST(
      GREATEST(
        NULLIF(BTRIM(COALESCE(
          v_context_json->>'source_page_limit',
          v_context_json #>> '{source_build,limit}',
          v_context_json #>> '{workbench,source_build_limit}',
          ''
        )), '')::integer,
        1
      ),
      100
    );
  ELSE
    v_source_build_page_limit := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  END IF;

  IF COALESCE(v_source_build_cursor_in_json->>'last_timesheet_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_source_build_last_timesheet_id := (v_source_build_cursor_in_json->>'last_timesheet_id')::uuid;
  END IF;

  v_source_build_allow_full_fallback := LOWER(BTRIM(COALESCE(
    v_context_json->>'source_build_allow_full_fallback',
    v_context_json #>> '{source_build,allow_full_fallback}',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');


  /*
    5.3 PAGE mode: when no single candidate is supplied, this function acts as a
    bounded pre-draft scope collector. It returns one candidate page only and
    never aggregates all candidate ids for workbench open.
  */
  IF v_candidate_id IS NULL THEN
    RETURN public.pay_preview_build_context(
      p_pay_date => NULLIF(BTRIM(COALESCE(v_context_json->>'pay_date', '')), '')::date,
      p_week_ending_cutoff => NULLIF(BTRIM(COALESCE(v_context_json->>'week_ending_cutoff_date', v_context_json->>'week_ending_cutoff', '')), '')::date,
      p_actor_user_id => CASE
        WHEN NULLIF(BTRIM(COALESCE(v_context_json #>> '{filters,actor_user_id}', v_context_json->>'actor_user_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(v_context_json #>> '{filters,actor_user_id}', v_context_json->>'actor_user_id', '')), '')::uuid
        ELSE NULL::uuid
      END,
      p_candidate_id => NULL::uuid,
      p_client_id => CASE
        WHEN NULLIF(BTRIM(COALESCE(v_context_json #>> '{filters,client_id}', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(v_context_json #>> '{filters,client_id}', '')), '')::uuid
        ELSE NULL::uuid
      END,
      p_preview_decisions_json => COALESCE(v_context_json->'preview_decisions_json', '{}'::jsonb)
        || jsonb_build_object(
          'preview_context_mode', 'PAGE',
          'scope_limit', LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100),
          'scope_cursor', COALESCE(p_cursor_json, NULL::jsonb)
        )
    );
  END IF;


  v_pay_date := nullif(btrim(coalesce(v_context_json->>'pay_date', '')), '')::date;
  v_week_ending_cutoff := DATE '9999-12-31';
  v_client_id := nullif(btrim(coalesce(v_context_json #>> '{filters,client_id}', '')), '')::uuid;
  v_week_start := nullif(btrim(coalesce(v_context_json->>'pay_week_start', '')), '')::date;
  v_today_uk := coalesce(nullif(btrim(coalesce(v_context_json #>> '{eligibility,today_uk}', '')), '')::date, (now() at time zone 'Europe/London')::date);
  v_eligibility_from_date := nullif(btrim(coalesce(v_context_json #>> '{eligibility,from_date}', '')), '')::date;
  v_eligibility_to_date := nullif(btrim(coalesce(v_context_json #>> '{eligibility,to_date}', '')), '')::date;
  v_pay_eligibility_months_back := coalesce(nullif(btrim(coalesce(v_context_json #>> '{eligibility,months_back}', '')), '')::int, 6);
  v_pay_eligibility_weeks_ahead := coalesce(nullif(btrim(coalesce(v_context_json #>> '{eligibility,weeks_ahead}', '')), '')::int, 2);
  v_vat_rate_pct := nullif(btrim(coalesce(v_context_json #>> '{finance,vat_rate_pct}', '')), '')::numeric;
  v_erni_pct := nullif(btrim(coalesce(v_context_json #>> '{finance,erni_pct}', '')), '')::numeric;
  v_rail_provider_default := nullif(btrim(coalesce(v_context_json #>> '{settings,rail,provider_default}', '')), '');
  v_rail_env_default := nullif(btrim(coalesce(v_context_json #>> '{settings,rail,env_default}', '')), '');
  v_rail_supports_scheduling := coalesce((v_context_json #>> '{settings,rail,supports_scheduling}')::boolean, false);
  v_rail_supports_name_check := coalesce((v_context_json #>> '{settings,rail,supports_name_check}')::boolean, false);
  v_rail_supports_auto_execute := coalesce((v_context_json #>> '{settings,rail,supports_auto_execute}')::boolean, false);
  v_default_schedule_umbrella_local := nullif(btrim(coalesce(v_context_json #>> '{settings,schedule_defaults,umbrella_local}', '')), '');
  v_default_schedule_paye_local := nullif(btrim(coalesce(v_context_json #>> '{settings,schedule_defaults,paye_local}', '')), '');
  v_funds_warning_hours_json := case when jsonb_typeof(v_context_json #> '{settings,funds_warning_hours_json}') = 'array' then coalesce(v_context_json #> '{settings,funds_warning_hours_json}', '[]'::jsonb) else '[]'::jsonb end;
  v_need_name_check := coalesce((v_context_json #>> '{settings,rail,need_name_check}')::boolean, false);
  v_requires_payee_map := coalesce((v_context_json #>> '{settings,rail,requires_payee_map}')::boolean, false);
  v_paye_guardrails := case when jsonb_typeof(v_context_json->'paye_guardrails') = 'object' then coalesce(v_context_json->'paye_guardrails', '{}'::jsonb) else '{}'::jsonb end;

  v_pay_channel_scope := NULLIF(UPPER(BTRIM(COALESCE(
    v_context_json->>'pay_channel_scope',
    v_context_json #>> '{filters,pay_channel_scope}',
    v_context_json #>> '{preview_decisions_json,pay_channel_scope}',
    'ALL'
  ))), '');
  IF v_pay_channel_scope NOT IN ('PAYE', 'UMBRELLA', 'ALL', 'LOANS') THEN
    v_pay_channel_scope := 'ALL';
  END IF;

  v_target_pay_batch_id_raw := NULLIF(BTRIM(COALESCE(
    v_context_json->>'target_pay_batch_id',
    v_context_json->>'pay_batch_id',
    v_context_json->>'draft_pay_batch_id',
    v_context_json #>> '{preview_decisions_json,target_pay_batch_id}',
    v_context_json #>> '{preview_decisions_json,pay_batch_id}',
    ''
  )), '');
  IF v_target_pay_batch_id_raw ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_target_pay_batch_id := v_target_pay_batch_id_raw::uuid;
  END IF;

  v_target_operation_source_key := NULLIF(BTRIM(COALESCE(
    v_context_json->>'target_operation_source_key',
    v_context_json #>> '{preview_decisions_json,target_operation_source_key}',
    ''
  )), '');

  SELECT UPPER(NULLIF(BTRIM(COALESCE(public.candidates.pay_method, '')), ''))
  INTO v_candidate_pay_method
  FROM public.candidates
  WHERE public.candidates.id = v_candidate_id;

  v_refresh_scope_kind := NULLIF(UPPER(BTRIM(COALESCE(v_context_json->>'refresh_scope_kind', v_context_json #>> '{preview_decisions_json,refresh_scope_kind}', ''))), '');
  IF v_refresh_scope_kind NOT IN ('TARGETED_TIMESHEETS', 'CANDIDATE_FULL_LIVE') THEN
    v_refresh_scope_kind := NULL;
  END IF;

  SELECT COALESCE(jsonb_agg(targeted_scope_ids.targeted_timesheet_id ORDER BY targeted_scope_ids.targeted_timesheet_id), '[]'::jsonb)
  INTO v_targeted_timesheet_ids_json
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(targeted_scope_values.targeted_timesheet_id_raw), '') AS targeted_timesheet_id
    FROM (
      SELECT targeted_scope_array.value AS targeted_timesheet_id_raw
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_context_json->'targeted_timesheet_ids') = 'array' THEN v_context_json->'targeted_timesheet_ids'
          WHEN jsonb_typeof(v_context_json->'targeted_timesheet_ids') = 'string' THEN jsonb_build_array(v_context_json->>'targeted_timesheet_ids')
          WHEN jsonb_typeof(v_context_json #> '{preview_decisions_json,targeted_timesheet_ids}') = 'array' THEN v_context_json #> '{preview_decisions_json,targeted_timesheet_ids}'
          WHEN jsonb_typeof(v_context_json #> '{preview_decisions_json,targeted_timesheet_ids}') = 'string' THEN jsonb_build_array(v_context_json #>> '{preview_decisions_json,targeted_timesheet_ids}')
          ELSE '[]'::jsonb
        END
      ) AS targeted_scope_array(value)
    ) AS targeted_scope_values
    WHERE NULLIF(BTRIM(targeted_scope_values.targeted_timesheet_id_raw), '') IS NOT NULL
  ) AS targeted_scope_ids;

  SELECT COALESCE(jsonb_agg(linked_scope_ids.linked_timesheet_id ORDER BY linked_scope_ids.linked_timesheet_id), '[]'::jsonb)
  INTO v_linked_timesheet_ids_json
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(linked_scope_values.linked_timesheet_id_raw), '') AS linked_timesheet_id
    FROM (
      SELECT linked_scope_array.value AS linked_timesheet_id_raw
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_context_json->'linked_timesheet_ids') = 'array' THEN v_context_json->'linked_timesheet_ids'
          WHEN jsonb_typeof(v_context_json->'linked_timesheet_ids') = 'string' THEN jsonb_build_array(v_context_json->>'linked_timesheet_ids')
          WHEN jsonb_typeof(v_context_json #> '{preview_decisions_json,linked_timesheet_ids}') = 'array' THEN v_context_json #> '{preview_decisions_json,linked_timesheet_ids}'
          WHEN jsonb_typeof(v_context_json #> '{preview_decisions_json,linked_timesheet_ids}') = 'string' THEN jsonb_build_array(v_context_json #>> '{preview_decisions_json,linked_timesheet_ids}')
          ELSE '[]'::jsonb
        END
      ) AS linked_scope_array(value)
    ) AS linked_scope_values
    WHERE NULLIF(BTRIM(linked_scope_values.linked_timesheet_id_raw), '') IS NOT NULL
  ) AS linked_scope_ids;


  v_targeted_timesheet_ids_requested_json := CASE
    WHEN jsonb_typeof(v_context_json->'targeted_timesheet_ids_requested') = 'array' THEN v_context_json->'targeted_timesheet_ids_requested'
    WHEN jsonb_typeof(v_context_json #> '{preview_decisions_json,targeted_timesheet_ids_requested}') = 'array' THEN v_context_json #> '{preview_decisions_json,targeted_timesheet_ids_requested}'
    ELSE COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)
  END;

  v_linked_timesheet_ids_requested_json := CASE
    WHEN jsonb_typeof(v_context_json->'linked_timesheet_ids_requested') = 'array' THEN v_context_json->'linked_timesheet_ids_requested'
    WHEN jsonb_typeof(v_context_json #> '{preview_decisions_json,linked_timesheet_ids_requested}') = 'array' THEN v_context_json #> '{preview_decisions_json,linked_timesheet_ids_requested}'
    ELSE COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)
  END;

  v_source_build_requested_scope_kind := COALESCE(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE');
  v_source_build_targeted_payload_received := (
    jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) > 0
    OR jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) > 0
  );

  IF COALESCE(v_source_build_mode, false) = true
     AND v_refresh_scope_kind = 'TARGETED_TIMESHEETS'
     AND (
       jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) > 0
       OR jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) > 0
     ) THEN
    WITH source_requested_ids AS (
      SELECT
        'TARGETED'::text AS source_scope_kind,
        NULLIF(BTRIM(target_values.value), '')::uuid AS timesheet_id
      FROM jsonb_array_elements_text(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) AS target_values(value)
      WHERE NULLIF(BTRIM(target_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'

      UNION ALL

      SELECT
        'LINKED'::text AS source_scope_kind,
        NULLIF(BTRIM(linked_values.value), '')::uuid AS timesheet_id
      FROM jsonb_array_elements_text(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) AS linked_values(value)
      WHERE NULLIF(BTRIM(linked_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ),
    source_requested_dedup AS (
      SELECT DISTINCT ON (source_requested_ids.timesheet_id)
        source_requested_ids.source_scope_kind,
        source_requested_ids.timesheet_id
      FROM source_requested_ids
      WHERE source_requested_ids.timesheet_id IS NOT NULL
      ORDER BY
        source_requested_ids.timesheet_id,
        CASE WHEN source_requested_ids.source_scope_kind = 'TARGETED' THEN 0 ELSE 1 END
    ),
    source_remaining_ids AS (
      SELECT
        source_requested_dedup.source_scope_kind,
        source_requested_dedup.timesheet_id
      FROM source_requested_dedup
      WHERE v_source_build_last_timesheet_id IS NULL
         OR source_requested_dedup.timesheet_id > v_source_build_last_timesheet_id
    ),
    source_page AS (
      SELECT
        source_remaining_ids.source_scope_kind,
        source_remaining_ids.timesheet_id
      FROM source_remaining_ids
      ORDER BY source_remaining_ids.timesheet_id
      LIMIT v_source_build_page_limit
    )
    SELECT
      COALESCE(
        jsonb_agg(source_page.timesheet_id ORDER BY source_page.timesheet_id)
          FILTER (WHERE source_page.source_scope_kind = 'TARGETED'),
        '[]'::jsonb
      ),
      COALESCE(
        jsonb_agg(source_page.timesheet_id ORDER BY source_page.timesheet_id)
          FILTER (WHERE source_page.source_scope_kind = 'LINKED'),
        '[]'::jsonb
      ),
      count(source_page.timesheet_id)::integer,
      COALESCE((SELECT count(*)::integer FROM source_remaining_ids), 0),
      (
        SELECT ordered_source_page.timesheet_id
        FROM source_page AS ordered_source_page
        ORDER BY ordered_source_page.timesheet_id DESC
        LIMIT 1
      )
    INTO
      v_targeted_timesheet_ids_json,
      v_linked_timesheet_ids_json,
      v_source_build_target_page_count,
      v_source_build_target_total_count,
      v_source_build_next_timesheet_id
    FROM source_page;

    v_targeted_timesheet_ids_requested_json := COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb);
    v_linked_timesheet_ids_requested_json := COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb);
    v_source_build_has_more := v_source_build_target_total_count > v_source_build_target_page_count;
    v_source_build_cursor_out_json := CASE
      WHEN v_source_build_next_timesheet_id IS NULL THEN NULL::jsonb
      ELSE jsonb_build_object(
        'last_timesheet_id', v_source_build_next_timesheet_id::text,
        'source_page_limit', v_source_build_page_limit,
        'requested_refresh_scope_kind', v_source_build_requested_scope_kind
      )
    END;
    v_source_build_candidate_filter_applied_early := true;
    v_source_build_timesheet_filter_applied_early := true;
    v_source_build_large_aggregation_avoided := true;
  ELSIF COALESCE(v_source_build_mode, false) = true
        AND COALESCE(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE') = 'CANDIDATE_FULL_LIVE'
        AND v_candidate_id IS NOT NULL THEN
    WITH retained_finance_cases AS (
      SELECT retained_case.id AS finance_case_id,
             retained_case.linked_timesheet_id
      FROM public.pay_advances AS retained_case
      WHERE retained_case.candidate_id = v_candidate_id
        AND retained_case.linked_timesheet_id IS NOT NULL
        AND (
          retained_case.advance_kind IN (
            'OVERPAYMENT'::public.pay_advance_kind_enum,
            'UNDERPAYMENT'::public.pay_advance_kind_enum
          )
          OR retained_case.case_type IN (
            'OVERPAYMENT'::public.pay_finance_case_type_enum,
            'UNDERPAYMENT'::public.pay_finance_case_type_enum
          )
        )
        AND (
          (
            retained_case.status IN (
              'ACTIVE'::public.pay_advance_status_enum,
              'PAUSED'::public.pay_advance_status_enum
            )
            AND ROUND(COALESCE(retained_case.outstanding_amount, 0), 2) > 0
          )
          OR EXISTS (
            SELECT 1
            FROM public.pay_finance_case_components AS retained_component
            WHERE retained_component.finance_case_id = retained_case.id
              AND retained_component.candidate_id = v_candidate_id
              AND (
                retained_component.closed_at_utc IS NULL
                OR ROUND(COALESCE(retained_component.remaining_source_amount, 0), 2) > 0
              )
          )
          OR EXISTS (
            SELECT 1
            FROM public.pay_advance_reservations AS retained_reservation
            WHERE retained_reservation.finance_case_id = retained_case.id
              AND UPPER(BTRIM(COALESCE(retained_reservation.status, ''))) IN ('RESERVED', 'COMMITTED', 'SETTLED')
              AND retained_reservation.released_at_utc IS NULL
          )
          OR EXISTS (
            SELECT 1
            FROM public.pay_batch_items AS retained_item
            JOIN public.pay_batch_candidates AS retained_candidate
              ON retained_candidate.id = retained_item.pay_batch_candidate_id
             AND retained_candidate.candidate_id = v_candidate_id
            WHERE retained_item.finance_case_id = retained_case.id
              AND retained_item.is_voided IS NOT TRUE
          )
          OR EXISTS (
            SELECT 1
            FROM public.pay_payment_correction_items AS retained_correction
            WHERE retained_correction.finance_case_id = retained_case.id
              AND retained_correction.candidate_id = v_candidate_id
              AND retained_correction.status = 'APPLIED'
          )
        )
    ),
    candidate_source_seed AS (
      SELECT candidate_scope_financials.timesheet_id
      FROM public.timesheets_financials AS candidate_scope_financials
      JOIN public.timesheets AS candidate_scope_timesheets
        ON candidate_scope_timesheets.timesheet_id = candidate_scope_financials.timesheet_id
      JOIN public.candidates AS candidate_scope_candidates
        ON candidate_scope_candidates.id = candidate_scope_financials.candidate_id
      WHERE candidate_scope_financials.is_current = true
        AND candidate_scope_financials.candidate_id = v_candidate_id
        AND COALESCE(candidate_scope_financials.pay_on_hold, false) = false
        AND COALESCE(candidate_scope_financials.has_rate_issue, false) = false
        AND COALESCE(candidate_scope_financials.has_pay_channel_issue, false) = false
        AND UPPER(COALESCE(candidate_scope_financials.processing_status::text, '')) NOT IN (
          'UNASSIGNED',
          'CLIENT_UNRESOLVED',
          'RATE_MISSING',
          'PAY_CHANNEL_MISSING'
        )
        AND UPPER(COALESCE(candidate_scope_candidates.pay_method, '')) IN ('PAYE', 'UMBRELLA')
        AND (
          v_pay_channel_scope = 'ALL'
          OR UPPER(COALESCE(candidate_scope_candidates.pay_method, '')) = v_pay_channel_scope
        )
        AND (v_client_id IS NULL OR candidate_scope_financials.client_id = v_client_id)
        AND (
          (
            candidate_scope_timesheets.authorised_at_server IS NOT NULL
            AND candidate_scope_timesheets.revoked_at IS NULL
            AND candidate_scope_timesheets.archived_at_utc IS NULL
          )
          OR EXISTS (
            SELECT 1
            FROM public.timesheet_payment_overrides AS candidate_scope_overrides
            WHERE candidate_scope_overrides.timesheet_id = candidate_scope_financials.timesheet_id
              AND candidate_scope_overrides.candidate_id = v_candidate_id
              AND candidate_scope_overrides.cleared_at_utc IS NULL
              AND candidate_scope_overrides.consumed_at_utc IS NULL
              AND candidate_scope_overrides.consumed_by_pay_batch_id IS NULL
              AND UPPER(COALESCE(candidate_scope_overrides.override_type, '')) = 'ADVANCE_THIS_PAYMENT'
          )
        )

      UNION

      SELECT retained_finance_cases.linked_timesheet_id
      FROM retained_finance_cases

      UNION

      SELECT retained_component.linked_timesheet_id
      FROM public.pay_finance_case_components AS retained_component
      JOIN retained_finance_cases
        ON retained_finance_cases.finance_case_id = retained_component.finance_case_id
      WHERE retained_component.candidate_id = v_candidate_id
        AND retained_component.linked_timesheet_id IS NOT NULL

      UNION

      SELECT retained_item.timesheet_id
      FROM public.pay_batch_items AS retained_item
      JOIN public.pay_batch_candidates AS retained_candidate
        ON retained_candidate.id = retained_item.pay_batch_candidate_id
       AND retained_candidate.candidate_id = v_candidate_id
      JOIN retained_finance_cases
        ON retained_finance_cases.finance_case_id = retained_item.finance_case_id
      WHERE retained_item.timesheet_id IS NOT NULL
        AND retained_item.is_voided IS NOT TRUE

      UNION

      SELECT retained_correction.timesheet_id
      FROM public.pay_payment_correction_items AS retained_correction
      JOIN retained_finance_cases
        ON retained_finance_cases.finance_case_id = retained_correction.finance_case_id
      WHERE retained_correction.candidate_id = v_candidate_id
        AND retained_correction.timesheet_id IS NOT NULL
        AND retained_correction.status = 'APPLIED'

      UNION

      SELECT forced_source_timesheet.timesheet_id
      FROM (
        SELECT NULLIF(BTRIM(forced_source_values.value), '')::uuid AS timesheet_id
        FROM jsonb_array_elements_text(
          CASE
            WHEN v_internal_reconciliation_authorised IS TRUE
             AND jsonb_typeof(v_context_json->'source_build_force_include_timesheet_ids') = 'array'
              THEN v_context_json->'source_build_force_include_timesheet_ids'
            ELSE '[]'::jsonb
          END
        ) WITH ORDINALITY AS forced_source_values(value, position)
        WHERE forced_source_values.position <= 500
          AND NULLIF(BTRIM(forced_source_values.value), '') ~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ) AS forced_source_timesheet
      JOIN public.timesheets AS forced_candidate_timesheet
        ON forced_candidate_timesheet.timesheet_id = forced_source_timesheet.timesheet_id
      WHERE EXISTS (
        SELECT 1
        FROM public.timesheets_financials AS forced_candidate_financials
        WHERE forced_candidate_financials.timesheet_id = forced_source_timesheet.timesheet_id
          AND forced_candidate_financials.candidate_id = v_candidate_id
      )
    ),
    candidate_source_timesheets AS (
      SELECT DISTINCT candidate_source_seed.timesheet_id
      FROM candidate_source_seed
      WHERE candidate_source_seed.timesheet_id IS NOT NULL
        AND (
          v_source_build_last_timesheet_id IS NULL
          OR candidate_source_seed.timesheet_id > v_source_build_last_timesheet_id
        )
    ),
    candidate_source_page AS (
      SELECT candidate_source_timesheets.timesheet_id
      FROM candidate_source_timesheets
      ORDER BY candidate_source_timesheets.timesheet_id
      LIMIT v_source_build_page_limit
    )
    SELECT
      COALESCE(jsonb_agg(candidate_source_page.timesheet_id ORDER BY candidate_source_page.timesheet_id), '[]'::jsonb),
      count(candidate_source_page.timesheet_id)::integer,
      COALESCE((SELECT count(*)::integer FROM candidate_source_timesheets), 0),
      (
        SELECT ordered_candidate_source_page.timesheet_id
        FROM candidate_source_page AS ordered_candidate_source_page
        ORDER BY ordered_candidate_source_page.timesheet_id DESC
        LIMIT 1
      )
    INTO
      v_targeted_timesheet_ids_json,
      v_source_build_target_page_count,
      v_source_build_target_total_count,
      v_source_build_next_timesheet_id
    FROM candidate_source_page;

    v_targeted_timesheet_ids_requested_json := COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb);
    v_linked_timesheet_ids_json := '[]'::jsonb;
    v_linked_timesheet_ids_requested_json := '[]'::jsonb;
    v_refresh_scope_kind := 'TARGETED_TIMESHEETS';
    v_source_build_has_more := v_source_build_target_total_count > v_source_build_target_page_count;
    v_source_build_cursor_out_json := CASE
      WHEN v_source_build_next_timesheet_id IS NULL THEN NULL::jsonb
      ELSE jsonb_build_object(
        'last_timesheet_id', v_source_build_next_timesheet_id::text,
        'source_page_limit', v_source_build_page_limit,
        'requested_refresh_scope_kind', v_source_build_requested_scope_kind
      )
    END;
    v_source_build_candidate_filter_applied_early := true;
    v_source_build_timesheet_filter_applied_early := true;
    v_source_build_large_aggregation_avoided := true;
    v_authoritative_timesheet_scope := v_internal_reconciliation_authorised IS TRUE
      AND jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) > 0;
    v_historic_metadata_allowed := v_signed_finance_reconciliation IS TRUE
      AND v_authoritative_timesheet_scope IS TRUE;
  END IF;

  IF COALESCE(v_source_build_mode, false) = true
     AND v_source_build_requested_scope_kind = 'TARGETED_TIMESHEETS'
     AND jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) = 0
     AND jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) = 0 THEN
    IF COALESCE(v_source_build_targeted_payload_received, false) = true THEN
      v_effective_refresh_scope_kind := 'TARGETED_TIMESHEETS';
    ELSIF v_source_build_allow_full_fallback = true THEN
      v_source_build_fallback_used := true;
      v_source_build_fallback_reason := COALESCE(
        NULLIF(BTRIM(v_context_json->>'source_build_fallback_reason'), ''),
        NULLIF(BTRIM(v_context_json #>> '{source_build,fallback_reason}'), ''),
        'TARGETED_TIMESHEETS_REQUESTED_WITHOUT_TARGET_IDS'
      );
      v_effective_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
    ELSE
      RAISE EXCEPTION 'SOURCE_BUILD_TARGETED_TIMESHEETS_REQUIRES_TARGET_IDS'
        USING DETAIL = 'WORKBENCH_CANDIDATE_SOURCE_BUILD TARGETED_TIMESHEETS requires targeted_timesheet_ids or linked_timesheet_ids unless source_build_allow_full_fallback is true.';
    END IF;
  ELSIF v_refresh_scope_kind = 'TARGETED_TIMESHEETS'
        AND jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) = 0
        AND jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) = 0
        AND COALESCE(v_source_build_mode, false) = false THEN
    v_effective_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
  ELSE
    v_effective_refresh_scope_kind := COALESCE(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE');
  END IF;

  v_source_build_actual_scope_kind := v_effective_refresh_scope_kind;

  IF COALESCE(v_source_build_mode, false) = true
     AND v_effective_refresh_scope_kind = 'TARGETED_TIMESHEETS'
     AND (
       jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) > 0
       OR jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) > 0
     ) THEN
    v_source_build_candidate_filter_applied_early := true;
    v_source_build_timesheet_filter_applied_early := true;
    v_source_build_large_aggregation_avoided := true;
  END IF;

  if v_pay_date is null then
    raise exception 'pay_date missing from p_context_json';
  end if;

  if v_week_start is null then
    raise exception 'pay_week_start missing from p_context_json';
  end if;

  if v_eligibility_from_date is null or v_eligibility_to_date is null then
    raise exception 'eligibility window missing from p_context_json';
  end if;

  if v_vat_rate_pct is null or v_erni_pct is null then
    raise exception 'finance window values missing from p_context_json';
  end if;

  if v_rail_provider_default is null or v_rail_env_default is null then
    raise exception 'rail defaults missing from p_context_json';
  end if;

  drop table if exists pg_temp.pay_preview_candidate_context, pg_temp.targeted_refresh_requested_timesheet_ids, pg_temp.linked_refresh_requested_timesheet_ids, pg_temp.targeted_refresh_rotation_scope, pg_temp.targeted_refresh_scope_projection, pg_temp.targeted_refresh_timesheet_ids, pg_temp.linked_refresh_timesheet_ids, pg_temp.targeted_refresh_family_timesheet_ids, pg_temp.linked_refresh_family_timesheet_ids, pg_temp.targeted_refresh_all_family_timesheet_ids, pg_temp.targeted_refresh_all_family_projection, pg_temp.targeted_refresh_all_baseline_projection, pg_temp.targeted_refresh_all_timesheet_ids, pg_temp.active_snoozes, pg_temp.active_timesheet_payment_snoozes, pg_temp.active_segment_snoozes, pg_temp.active_timesheet_payment_overrides, pg_temp.force_include, pg_temp.reserved_batch_items, pg_temp.reserved_by_source_ref, pg_temp.reserved_total_by_timesheet, pg_temp.reserved_segment_key_map, pg_temp.reserved_segment_sums, pg_temp.reserved_preview_segment_ords, pg_temp.reserved_additional_by_code, pg_temp.eligible_tsfin, pg_temp.debted_overpayment_cases, pg_temp.umb_map, pg_temp.adjustment_family_projection, pg_temp.adj, pg_temp.ts_current, pg_temp.targeted_baseline_only_ts_current, pg_temp.active_settled_artifact_components, pg_temp.active_settled_artifact_baseline_by_timesheet, pg_temp.ts_baseline, pg_temp.finance_case_baseline_scope, pg_temp.manual_adjustment_carry_forward_scope, pg_temp.segment_status, pg_temp.blocked_items_all, pg_temp.blocked_items, pg_temp.blocked_items_snoozed, pg_temp.do_not_pay_all, pg_temp.do_not_pay_items, pg_temp.do_not_pay_items_snoozed, pg_temp.ts_deltas, pg_temp.ts_itemised, pg_temp.worked_time_current_segment_rows, pg_temp.worked_time_baseline_segment_rows, pg_temp.worked_time_current_ranked, pg_temp.worked_time_baseline_ranked, pg_temp.worked_time_bucket_ids, pg_temp.worked_time_bucket_agg, pg_temp.worked_time_bucket_calc, pg_temp.worked_time_bucket_alloc, pg_temp.worked_time_bucket_effective, pg_temp.worked_time_bucket_component_rows, pg_temp.worked_time_key_totals, pg_temp.worked_time_bucket_component_sums, pg_temp.worked_time_amount_fallback_rows, pg_temp.timesheet_component_rows, pg_temp.timesheet_component_match_rows, pg_temp.transient_timesheet_component_rows, pg_temp.transient_timesheet_component_review_rows, pg_temp.timesheet_case_actionable_basis, pg_temp.timesheet_live_scope, pg_temp.timesheet_linked_scope_counts, pg_temp.transient_timesheet_component_review_rows_effective, pg_temp.timesheet_case_rollup, pg_temp.finance_candidate_seed, pg_temp.candidate_base, pg_temp.timesheet_candidate_rollup, pg_temp.candidate_rollup, pg_temp.blocked_counts, pg_temp.do_not_pay_counts, pg_temp.loan_due, pg_temp.overpayment_balances, pg_temp.loan_due_this_week, pg_temp.loan_repaid_wtd, pg_temp.paid_wtd_before, pg_temp.cand_enriched, pg_temp.payee_baseline_rows, pg_temp.payees_src, pg_temp.payees, pg_temp.payees_enriched, pg_temp.payees_json, pg_temp.cand_payee0, pg_temp.cand_payee, pg_temp.timesheet_case_rollup_effective, pg_temp.finance_case_repaid_wtd, pg_temp.finance_case_recovery_rows_base, pg_temp.manual_debt_recovery_rows, pg_temp.manual_debt_recovery_allocations, pg_temp.manual_debt_recovery_totals, pg_temp.overpayment_recovery_rows, pg_temp.overpayment_recovery_allocations, pg_temp.overpayment_recovery_totals, pg_temp.payment_advance_recovery_rows, pg_temp.payment_advance_recovery_allocations, pg_temp.finance_case_protected_allocations, pg_temp.finance_case_payee_readiness, pg_temp.finance_case_component_rows, pg_temp.finance_case_component_review_rows, pg_temp.finance_case_component_review_rows_effective, pg_temp.finance_case_due_source_amounts, pg_temp.finance_case_component_due_source_base, pg_temp.finance_case_component_due_source_shares, pg_temp.finance_case_component_due_source_allocations, pg_temp.finance_case_component_due_preview_base, pg_temp.finance_case_component_due_preview_allocations, pg_temp.finance_case_taxable_manual_debt_resolution, pg_temp.finance_case_resolution_rollup, pg_temp.canonical_timesheet_lines, pg_temp.timesheet_active_segment_snooze_meta, pg_temp.canonical_timesheet_segment_rows, pg_temp.canonical_timesheet_segment_rollup, pg_temp.canonical_timesheet_presentation_seed, pg_temp.canonical_timesheet_presentation_state, pg_temp.canonical_timesheet_presentation_rows, pg_temp.finance_case_lines, pg_temp.timesheet_canonical_preview_lines, pg_temp.canonical_preview_lines, pg_temp.candidate_preview_line_rollup, pg_temp.candidate_preview_timesheet_rollup, pg_temp.summary_json, pg_temp.timesheet_case_states_flat, pg_temp.finance_case_states_flat, pg_temp.candidate_case_states_flat, pg_temp.candidate_case_states, pg_temp.case_resolution_states_json, pg_temp.finance_candidate_totals, pg_temp.candidate_finance_itemisation, pg_temp.paye_summary_breakdown_json, pg_temp.timesheet_baseline_component_rows, pg_temp.finance_baseline_component_rows, pg_temp.baseline_component_rows_json;

  create temporary table pay_preview_candidate_context on commit drop as
    select
      v_context_json as context_json,
      v_candidate_id as candidate_id,
      v_pay_date as pay_date,
      v_week_ending_cutoff as week_ending_cutoff,
      v_client_id as client_id,
      v_actor_user_id as actor_user_id,
      v_week_start as week_start,
      v_today_uk as today_uk,
      v_pay_eligibility_months_back as pay_eligibility_months_back,
      v_pay_eligibility_weeks_ahead as pay_eligibility_weeks_ahead,
      v_eligibility_from_date as eligibility_from_date,
      v_eligibility_to_date as eligibility_to_date,
      v_vat_rate_pct as vat_rate_pct,
      v_erni_pct as erni_pct,
      v_rail_provider_default as rail_provider_default,
      v_rail_env_default as rail_env_default,
      v_rail_supports_scheduling as rail_supports_scheduling,
      v_rail_supports_name_check as rail_supports_name_check,
      v_rail_supports_auto_execute as rail_supports_auto_execute,
      v_default_schedule_umbrella_local as default_schedule_umbrella_local,
      v_default_schedule_paye_local as default_schedule_paye_local,
      v_funds_warning_hours_json as funds_warning_hours_json,
      v_need_name_check as need_name_check,
      v_requires_payee_map as requires_payee_map,
      v_paye_guardrails as paye_guardrails,
      v_effective_refresh_scope_kind as refresh_scope_kind,
      v_targeted_timesheet_ids_json as targeted_timesheet_ids_json,
      v_linked_timesheet_ids_json as linked_timesheet_ids_json,
      v_lifecycle_reconciliation_mode as lifecycle_reconciliation_mode,
      v_historic_metadata_allowed as historic_metadata_allowed,
      v_signed_finance_reconciliation as signed_finance_reconciliation,
      v_exclude_lifecycle_ineligible_current_payability as exclude_lifecycle_ineligible_current_payability,
      v_authoritative_timesheet_scope as authoritative_timesheet_scope
  ;

  create temporary table targeted_refresh_requested_timesheet_ids on commit drop as
    select distinct
      nullif(btrim(targeted_scope_array.value), '')::uuid as timesheet_id
    from jsonb_array_elements_text(coalesce(v_targeted_timesheet_ids_requested_json, '[]'::jsonb)) as targeted_scope_array(value)
    where nullif(btrim(targeted_scope_array.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ;

  create temporary table linked_refresh_requested_timesheet_ids on commit drop as
    select distinct
      nullif(btrim(linked_scope_array.value), '')::uuid as timesheet_id
    from jsonb_array_elements_text(coalesce(v_linked_timesheet_ids_requested_json, '[]'::jsonb)) as linked_scope_array(value)
    where nullif(btrim(linked_scope_array.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ;

  create temporary table targeted_refresh_rotation_scope on commit drop as
    select
      requested_scope.source_scope_kind,
      requested_scope.requested_timesheet_id as source_requested_timesheet_id,
      rotation_scope_rows.requested_timesheet_id,
      rotation_scope_rows.booking_id,
      rotation_scope_rows.canonical_timesheet_id,
      rotation_scope_rows.family_timesheet_id,
      rotation_scope_rows.family_is_current,
      rotation_scope_rows.family_version,
      rotation_scope_rows.requested_is_canonical
    from (
      select 'TARGETED'::text as source_scope_kind, targeted_requested.timesheet_id as requested_timesheet_id
      from targeted_refresh_requested_timesheet_ids as targeted_requested
      union
      select 'LINKED'::text as source_scope_kind, linked_requested.timesheet_id as requested_timesheet_id
      from linked_refresh_requested_timesheet_ids as linked_requested
      union
      select 'TARGETED'::text as source_scope_kind, nullif(btrim(targeted_context_values.value), '')::uuid as requested_timesheet_id
      from jsonb_array_elements_text(coalesce(v_targeted_timesheet_ids_json, '[]'::jsonb)) as targeted_context_values(value)
      where nullif(btrim(targeted_context_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      union
      select 'LINKED'::text as source_scope_kind, nullif(btrim(linked_context_values.value), '')::uuid as requested_timesheet_id
      from jsonb_array_elements_text(coalesce(v_linked_timesheet_ids_json, '[]'::jsonb)) as linked_context_values(value)
      where nullif(btrim(linked_context_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) as requested_scope
    join public._pay_timesheet_rotation_scope(
      (
        select coalesce(
          array_agg(distinct all_requested_scope.requested_timesheet_id order by all_requested_scope.requested_timesheet_id),
          array[]::uuid[]
        )
        from (
          select targeted_requested.timesheet_id as requested_timesheet_id
          from targeted_refresh_requested_timesheet_ids as targeted_requested
          union
          select linked_requested.timesheet_id as requested_timesheet_id
          from linked_refresh_requested_timesheet_ids as linked_requested
          union
          select nullif(btrim(targeted_context_values.value), '')::uuid as requested_timesheet_id
          from jsonb_array_elements_text(coalesce(v_targeted_timesheet_ids_json, '[]'::jsonb)) as targeted_context_values(value)
          where nullif(btrim(targeted_context_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          union
          select nullif(btrim(linked_context_values.value), '')::uuid as requested_timesheet_id
          from jsonb_array_elements_text(coalesce(v_linked_timesheet_ids_json, '[]'::jsonb)) as linked_context_values(value)
          where nullif(btrim(linked_context_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        ) as all_requested_scope
        where all_requested_scope.requested_timesheet_id is not null
      )
    ) as rotation_scope_rows
      on rotation_scope_rows.requested_timesheet_id = requested_scope.requested_timesheet_id
  ;

  create temporary table targeted_refresh_scope_projection on commit drop as
    select distinct
      targeted_refresh_rotation_scope.source_scope_kind,
      targeted_refresh_rotation_scope.source_requested_timesheet_id,
      coalesce(targeted_refresh_rotation_scope.canonical_timesheet_id, targeted_refresh_rotation_scope.source_requested_timesheet_id) as canonical_timesheet_id,
      targeted_refresh_rotation_scope.family_timesheet_id,
      targeted_refresh_rotation_scope.family_is_current,
      targeted_refresh_rotation_scope.family_version,
      targeted_refresh_rotation_scope.booking_id,
      coalesce(targeted_refresh_rotation_scope.requested_is_canonical, false) as requested_is_canonical
    from targeted_refresh_rotation_scope
    where targeted_refresh_rotation_scope.source_requested_timesheet_id is not null
      and targeted_refresh_rotation_scope.family_timesheet_id is not null
  ;

  create temporary table targeted_refresh_timesheet_ids on commit drop as
    select distinct
      targeted_refresh_scope_projection.canonical_timesheet_id as timesheet_id
    from targeted_refresh_scope_projection
    where targeted_refresh_scope_projection.source_scope_kind = 'TARGETED'
      and targeted_refresh_scope_projection.canonical_timesheet_id is not null
  ;

  create temporary table linked_refresh_timesheet_ids on commit drop as
    select distinct
      targeted_refresh_scope_projection.canonical_timesheet_id as timesheet_id
    from targeted_refresh_scope_projection
    where targeted_refresh_scope_projection.source_scope_kind = 'LINKED'
      and targeted_refresh_scope_projection.canonical_timesheet_id is not null
  ;

  create temporary table targeted_refresh_family_timesheet_ids on commit drop as
    select distinct
      targeted_refresh_scope_projection.family_timesheet_id
    from targeted_refresh_scope_projection
    where targeted_refresh_scope_projection.source_scope_kind = 'TARGETED'
      and targeted_refresh_scope_projection.family_timesheet_id is not null
  ;

  create temporary table linked_refresh_family_timesheet_ids on commit drop as
    select distinct
      targeted_refresh_scope_projection.family_timesheet_id
    from targeted_refresh_scope_projection
    where targeted_refresh_scope_projection.source_scope_kind = 'LINKED'
      and targeted_refresh_scope_projection.family_timesheet_id is not null
  ;

  create temporary table targeted_refresh_all_family_timesheet_ids on commit drop as
    select distinct targeted_refresh_family_timesheet_ids.family_timesheet_id
    from targeted_refresh_family_timesheet_ids
    union
    select distinct linked_refresh_family_timesheet_ids.family_timesheet_id
    from linked_refresh_family_timesheet_ids
  ;

  create temporary table targeted_refresh_all_family_projection on commit drop as
    select distinct
      targeted_refresh_scope_projection.canonical_timesheet_id,
      targeted_refresh_scope_projection.family_timesheet_id,
      targeted_refresh_scope_projection.family_is_current,
      targeted_refresh_scope_projection.family_version,
      targeted_refresh_scope_projection.booking_id
    from targeted_refresh_scope_projection
    where targeted_refresh_scope_projection.canonical_timesheet_id is not null
      and targeted_refresh_scope_projection.family_timesheet_id is not null
  ;

  create temporary table targeted_refresh_all_baseline_projection on commit drop as
    select distinct on (targeted_refresh_all_family_projection.canonical_timesheet_id)
      targeted_refresh_all_family_projection.canonical_timesheet_id,
      targeted_refresh_all_family_projection.family_timesheet_id,
      targeted_refresh_all_family_projection.family_is_current,
      targeted_refresh_all_family_projection.family_version,
      targeted_refresh_all_family_projection.booking_id
    from targeted_refresh_all_family_projection
    join public.timesheet_pay_state as baseline_projection_state
      on baseline_projection_state.timesheet_id = targeted_refresh_all_family_projection.family_timesheet_id
    order by
      targeted_refresh_all_family_projection.canonical_timesheet_id,
      (targeted_refresh_all_family_projection.family_timesheet_id = targeted_refresh_all_family_projection.canonical_timesheet_id) desc,
      targeted_refresh_all_family_projection.family_is_current desc nulls last,
      targeted_refresh_all_family_projection.family_version desc nulls last,
      targeted_refresh_all_family_projection.family_timesheet_id
  ;

  create temporary table targeted_refresh_all_timesheet_ids on commit drop as
    select distinct x.timesheet_id
    from (
      select trti.timesheet_id
      from targeted_refresh_timesheet_ids trti
      union
      select lrti.timesheet_id
      from linked_refresh_timesheet_ids lrti
    ) as x
    where x.timesheet_id is not null
  ;
  create temporary table active_snoozes on commit drop as
        select
          s.id as snooze_id,
          s.candidate_id,
          s.timesheet_id,
          s.booking_id,
          s.segment_id,
          s.segment_stable_key,
          s.source_ref,
          upper(coalesce(s.snooze_kind,'')) as snooze_kind,
          s.snooze_until_date,
          s.note
        from public.pay_item_snoozes s
        where s.cleared_at_utc is null
          and s.cancelled_at_utc is null
          and s.candidate_id = v_candidate_id
          and (
            s.snooze_until_date is null
            or s.snooze_until_date >= v_today_uk
          )
          and (
            v_effective_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            or s.timesheet_id in (select trti.timesheet_id from targeted_refresh_timesheet_ids trti)
            or s.timesheet_id in (select lrti.timesheet_id from linked_refresh_timesheet_ids lrti)
            or s.timesheet_id in (select trf.family_timesheet_id from targeted_refresh_all_family_timesheet_ids trf)
            or (
              s.booking_id is not null
              and exists (
                select 1
                from public.timesheets ts_scope
                where ts_scope.booking_id = s.booking_id
                  and (
                    ts_scope.timesheet_id in (select trti.timesheet_id from targeted_refresh_timesheet_ids trti)
                    or ts_scope.timesheet_id in (select lrti.timesheet_id from linked_refresh_timesheet_ids lrti)
                  )
              )
            )
            or (s.timesheet_id is null and s.booking_id is null)
          )
  
  ;

  create temporary table active_timesheet_payment_snoozes on commit drop as
        select
          s.candidate_id,
          s.timesheet_id,
          s.booking_id,
          s.snooze_id,
          s.snooze_until_date,
          s.note
        from active_snoozes s
        where s.source_ref is null
          and s.segment_id is null
          and s.segment_stable_key is null
          and s.snooze_kind = 'TIMESHEET_PAYMENT'
  
  ;

  create temporary table active_segment_snoozes on commit drop as
        select
          s.candidate_id,
          s.timesheet_id,
          s.booking_id,
          s.segment_id,
          coalesce(s.segment_stable_key, s.segment_id) as segment_stable_key,
          s.snooze_kind,
          s.snooze_id,
          s.snooze_until_date,
          s.note
        from active_snoozes s
        where s.source_ref is null
          and (s.segment_stable_key is not null or s.segment_id is not null)
          and s.snooze_kind in ('DO_NOT_PAY','BLOCKED_TIMESHEET')
  
  ;

  create temporary table active_timesheet_payment_overrides on commit drop as
        select
          coalesce(tpo_family_projection.canonical_timesheet_id, tpo.timesheet_id) as timesheet_id,
          tpo.candidate_id,
          tpo.id as override_id,
          tpo.reason as override_reason,
          tpo.created_at_utc
        from public.timesheet_payment_overrides tpo
        left join targeted_refresh_all_family_projection as tpo_family_projection
          on tpo_family_projection.family_timesheet_id = tpo.timesheet_id
        where tpo.cleared_at_utc is null
          and tpo.consumed_at_utc is null
          and tpo.consumed_by_pay_batch_id is null
          and upper(coalesce(tpo.override_type,'')) = 'ADVANCE_THIS_PAYMENT'
          and tpo.candidate_id = v_candidate_id
          and (
            v_effective_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            or tpo.timesheet_id in (select trti.timesheet_id from targeted_refresh_timesheet_ids trti)
            or tpo.timesheet_id in (select lrti.timesheet_id from linked_refresh_timesheet_ids lrti)
            or tpo.timesheet_id in (select trf.family_timesheet_id from targeted_refresh_all_family_timesheet_ids trf)
          )
  
  ;

  create temporary table force_include on commit drop as
        select distinct
          coalesce(tpo_family_projection.canonical_timesheet_id, tpo.timesheet_id) as timesheet_id
        from public.timesheet_payment_overrides tpo
        left join targeted_refresh_all_family_projection as tpo_family_projection
          on tpo_family_projection.family_timesheet_id = tpo.timesheet_id
        where tpo.cleared_at_utc is null
          and tpo.consumed_at_utc is null
          and tpo.consumed_by_pay_batch_id is null
          and upper(coalesce(tpo.override_type,'')) = 'ADVANCE_THIS_PAYMENT'
          and tpo.timesheet_id is not null
          and tpo.candidate_id = v_candidate_id
          and (
            v_effective_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            or tpo.timesheet_id in (select trti.timesheet_id from targeted_refresh_timesheet_ids trti)
            or tpo.timesheet_id in (select lrti.timesheet_id from linked_refresh_timesheet_ids lrti)
            or tpo.timesheet_id in (select trf.family_timesheet_id from targeted_refresh_all_family_timesheet_ids trf)
          )
  
  ;

  create temporary table reserved_batch_items on commit drop as
        -- Items are considered "reserved" if they belong to an ACTIVE (non-cancelled, non-settled) batch.
        -- Policy X/source-target rule: entitlement reservations must subtract the positive ORIGINAL SOURCE
        -- entitlement amount, not the resolved target payout amount. Finance bookkeeping item types are excluded.
        -- Rotation rule: discover candidate/scoped reservation items by family id, project them to the canonical
        -- current timesheet id for pre-draft preview, and resolve artifact keys in one set-based helper call.
        with reserved_batch_item_candidates as (
          select distinct
            reserved_pay_batch_item.id as pay_batch_item_id,
            reserved_pay_batch_candidate.pay_batch_id as pay_batch_id,
            reserved_pay_batch_item.timesheet_id as source_timesheet_id,
            reserved_pay_batch_item.segment_key as segment_key,
            reserved_pay_batch_item.source_ref as source_ref,
            reserved_pay_batch_item.item_type as item_type,
            round(public._pay_batch_item_source_reservation_amount_ex_vat(reserved_pay_batch_item.id), 2) as amount_ex_vat
          from public.pay_batch_items as reserved_pay_batch_item
          join public.pay_batch_candidates as reserved_pay_batch_candidate
            on reserved_pay_batch_candidate.id = reserved_pay_batch_item.pay_batch_candidate_id
          join public.pay_batches as reserved_pay_batch
            on reserved_pay_batch.id = reserved_pay_batch_candidate.pay_batch_id
          left join public.pay_bank_transfers as reserved_pay_bank_transfer
            on reserved_pay_bank_transfer.id = reserved_pay_batch_item.pay_bank_transfer_id
          where reserved_pay_batch_item.timesheet_id is not null
            and reserved_pay_batch_candidate.candidate_id = v_candidate_id
            and (
              v_effective_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
              or reserved_pay_batch_item.timesheet_id in (
                select targeted_family_scope.family_timesheet_id
                from targeted_refresh_all_family_timesheet_ids as targeted_family_scope
              )
            )
            and upper(coalesce(reserved_pay_batch_item.pay_channel,'')) in ('PAYE','UMBRELLA')
            and reserved_pay_batch_item.item_type in ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
            and public._pay_batch_item_source_reservation_amount_ex_vat(reserved_pay_batch_item.id) is not null
            and coalesce(reserved_pay_batch_item.is_voided, false) = false
            and not exists (
              select 1
              from public.pay_payment_correction_items as applied_corrections
              where applied_corrections.pay_batch_item_id = reserved_pay_batch_item.id
                and applied_corrections.status = 'APPLIED'
                and applied_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
            )
            and not (
              upper(btrim(coalesce(reserved_pay_batch_candidate.settlement_status, ''))) = 'SETTLED'
              or reserved_pay_batch_candidate.settled_at_utc is not null
              or upper(btrim(coalesce(reserved_pay_bank_transfer.status, ''))) = 'COMPLETED'
              or reserved_pay_bank_transfer.completed_at_utc is not null
            )
            and (
              public._pay_batch_status_is_active_reservation(reserved_pay_batch.status)
              or exists (
                select 1
                from public.pay_payment_correction_requests as open_correction_requests
                join lateral public._pay_payment_correction_selected_items(
                  open_correction_requests.pay_batch_id,
                  case
                    when jsonb_typeof(open_correction_requests.plan_json->'selected_pay_batch_item_ids') = 'array' then
                      coalesce(open_correction_requests.selection_json, '{}'::jsonb)
                      || jsonb_build_object(
                        'pay_batch_item_ids', open_correction_requests.plan_json->'selected_pay_batch_item_ids',
                        'expected_pay_batch_item_ids', open_correction_requests.plan_json->'selected_pay_batch_item_ids'
                      )
                    when jsonb_typeof(open_correction_requests.plan_json#>'{selection,selected_pay_batch_item_ids}') = 'array' then
                      coalesce(open_correction_requests.selection_json, '{}'::jsonb)
                      || jsonb_build_object(
                        'pay_batch_item_ids', open_correction_requests.plan_json#>'{selection,selected_pay_batch_item_ids}',
                        'expected_pay_batch_item_ids', open_correction_requests.plan_json#>'{selection,selected_pay_batch_item_ids}'
                      )
                    when jsonb_typeof(open_correction_requests.plan_json#>'{selection,pay_batch_item_ids}') = 'array' then
                      coalesce(open_correction_requests.selection_json, '{}'::jsonb)
                      || jsonb_build_object(
                        'pay_batch_item_ids', open_correction_requests.plan_json#>'{selection,pay_batch_item_ids}',
                        'expected_pay_batch_item_ids', open_correction_requests.plan_json#>'{selection,pay_batch_item_ids}'
                      )
                    else
                      coalesce(open_correction_requests.selection_json, '{}'::jsonb)
                  end,
                  false
                ) as open_correction_selected_items
                  on open_correction_selected_items.pay_batch_id = open_correction_requests.pay_batch_id
                where open_correction_requests.pay_batch_id = reserved_pay_batch_candidate.pay_batch_id
                  and open_correction_requests.status in ('REQUESTED','AWAITING_AUTHORISATION','AUTHORISED','EXPANDED','PROCESSING','BLOCKED')
                  and open_correction_requests.correction_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY')
                  and open_correction_selected_items.pay_batch_item_id = reserved_pay_batch_item.id
              )
              or exists (
                select 1
                from public.pay_bank_transfer_events as unresolved_terminal_failure_events
                where unresolved_terminal_failure_events.pay_batch_id = reserved_pay_batch_candidate.pay_batch_id
                  and unresolved_terminal_failure_events.pay_bank_transfer_id = reserved_pay_batch_item.pay_bank_transfer_id
                  and unresolved_terminal_failure_events.mapping_status = 'MATCHED'
                  and unresolved_terminal_failure_events.normalised_state in ('FAILED','DECLINED','REJECTED','CANCELLED')
                  and not exists (
                    select 1
                    from public.pay_payment_correction_items as applied_failure_corrections
                    where applied_failure_corrections.pay_batch_item_id = reserved_pay_batch_item.id
                      and applied_failure_corrections.status = 'APPLIED'
                      and applied_failure_corrections.correction_item_kind in ('NO_MONEY_UNWIND','PRE_BANK_CANCEL','SETTLED_REVERSAL')
                  )
              )
            )
        ),
        reserved_batch_item_rotation_scope as (
          select
            rotation_scope_rows.requested_timesheet_id,
            rotation_scope_rows.canonical_timesheet_id,
            rotation_scope_rows.family_timesheet_id,
            rotation_scope_rows.family_is_current,
            rotation_scope_rows.family_version
          from public._pay_timesheet_rotation_scope(
            (
              select coalesce(
                array_agg(distinct reserved_batch_item_candidates.source_timesheet_id order by reserved_batch_item_candidates.source_timesheet_id),
                array[]::uuid[]
              )
              from reserved_batch_item_candidates
              where reserved_batch_item_candidates.source_timesheet_id is not null
            )
          ) as rotation_scope_rows
        ),
        reserved_batch_item_projection as (
          select distinct on (reserved_batch_item_rotation_scope.requested_timesheet_id)
            reserved_batch_item_rotation_scope.requested_timesheet_id as requested_timesheet_id,
            coalesce(
              reserved_batch_item_rotation_scope.canonical_timesheet_id,
              reserved_batch_item_rotation_scope.requested_timesheet_id
            ) as projected_timesheet_id
          from reserved_batch_item_rotation_scope
          where reserved_batch_item_rotation_scope.requested_timesheet_id is not null
          order by
            reserved_batch_item_rotation_scope.requested_timesheet_id,
            reserved_batch_item_rotation_scope.family_is_current desc nulls last,
            reserved_batch_item_rotation_scope.family_version desc nulls last,
            reserved_batch_item_rotation_scope.family_timesheet_id
        ),
        reserved_batch_item_projected as (
          select
            reserved_batch_item_candidates.pay_batch_item_id,
            reserved_batch_item_candidates.pay_batch_id,
            coalesce(
              reserved_batch_item_projection.projected_timesheet_id,
              reserved_batch_item_candidates.source_timesheet_id
            ) as projected_timesheet_id,
            reserved_batch_item_candidates.segment_key,
            reserved_batch_item_candidates.source_ref,
            reserved_batch_item_candidates.item_type,
            reserved_batch_item_candidates.amount_ex_vat
          from reserved_batch_item_candidates
          left join reserved_batch_item_projection
            on reserved_batch_item_projection.requested_timesheet_id = reserved_batch_item_candidates.source_timesheet_id
        ),
        reserved_batch_item_id_array as (
          select
            case
              when count(*) = 0 then array['00000000-0000-0000-0000-000000000000'::uuid]
              else array_agg(reserved_batch_item_projected.pay_batch_item_id order by reserved_batch_item_projected.pay_batch_item_id)
            end as pay_batch_item_ids
          from reserved_batch_item_projected
        ),
        reserved_batch_item_components as (
          select distinct
            economic_component_rows.pay_batch_item_id,
            economic_component_rows.key_type,
            economic_component_rows.key_value,
            economic_component_rows.key_resolution_source,
            economic_component_rows.key_resolution_failure_reason
          from reserved_batch_item_id_array
          join lateral public._pay_batch_item_economic_components(
            p_pay_batch_id => null::uuid,
            p_pay_batch_item_ids => reserved_batch_item_id_array.pay_batch_item_ids
          ) as economic_component_rows
            on true
        )
        select
          reserved_batch_item_projected.pay_batch_item_id as pay_batch_item_id,
          reserved_batch_item_projected.pay_batch_id as pay_batch_id,
          reserved_batch_item_projected.projected_timesheet_id as timesheet_id,
          reserved_batch_item_projected.segment_key as segment_key,
          -- Normalise segment_id (some legacy items store it in source_ref 'seg:<id>')
          nullif(
            btrim(coalesce(
              case
                when nullif(btrim(coalesce(reserved_batch_item_projected.segment_key,'')), '') is not null then reserved_batch_item_projected.segment_key
                when nullif(btrim(coalesce(reserved_batch_item_projected.source_ref,'')), '') like 'seg:%' then split_part(reserved_batch_item_projected.source_ref, ':', 2)
                else null
              end,
              ''
            )),
            ''
          ) as segment_id_norm,
          reserved_batch_item_projected.source_ref as source_ref,
          reserved_batch_item_projected.item_type as item_type,
          reserved_batch_item_components.key_type as component_key_type,
          reserved_batch_item_components.key_value as component_key_value,
          reserved_batch_item_components.key_resolution_source as key_resolution_source,
          reserved_batch_item_components.key_resolution_failure_reason as key_resolution_failure_reason,
          reserved_batch_item_projected.amount_ex_vat as amount_ex_vat
        from reserved_batch_item_projected
        left join reserved_batch_item_components
          on reserved_batch_item_components.pay_batch_item_id = reserved_batch_item_projected.pay_batch_item_id

  ;

  create temporary table reserved_by_source_ref on commit drop as
        select
          rbi.timesheet_id,
          rbi.source_ref,
          round(sum(rbi.amount_ex_vat),2) as reserved_amount_ex_vat
        from reserved_batch_items rbi
        where rbi.source_ref is not null
          and btrim(coalesce(rbi.source_ref,'')) <> ''
        group by rbi.timesheet_id, rbi.source_ref
  
  ;

  create temporary table reserved_total_by_timesheet on commit drop as
        select
          rbi.timesheet_id,
          round(sum(rbi.amount_ex_vat),2) as reserved_total_ex_vat
        from reserved_batch_items rbi
        group by rbi.timesheet_id
  
  ;

  create temporary table reserved_segment_key_map on commit drop as
        select
          rbi.timesheet_id,
          rbi.segment_id_norm as segment_id_norm,
          rbi.component_key_type as component_key_type,
          rbi.component_key_value as component_key_value
        from reserved_batch_items rbi
        where rbi.item_type = 'SEGMENT_DELTA'
          and rbi.component_key_type in ('TS_DAY','TS_TOTAL')
          and rbi.component_key_value is not null
          and btrim(coalesce(rbi.component_key_value,'')) <> ''
          and (rbi.component_key_type <> 'TS_DAY' or rbi.component_key_value ~ '^\d{4}-\d{2}-\d{2}$')
  
  ;

  create temporary table reserved_segment_sums on commit drop as
        select
          rbi.timesheet_id,
          rbi.component_key_type,
          rbi.component_key_value,
          round(sum(rbi.amount_ex_vat),2) as reserved_amount_ex_vat
        from reserved_batch_items rbi
        where rbi.item_type = 'SEGMENT_DELTA'
          and rbi.component_key_type in ('TS_DAY','TS_TOTAL')
          and rbi.component_key_value is not null
          and btrim(coalesce(rbi.component_key_value,'')) <> ''
          and (rbi.component_key_type <> 'TS_DAY' or rbi.component_key_value ~ '^\d{4}-\d{2}-\d{2}$')
        group by rbi.timesheet_id, rbi.component_key_type, rbi.component_key_value
  
  ;

  create temporary table reserved_preview_segment_ords on commit drop as
        select
          rbi.timesheet_id,
          case
            when coalesce(split_part(coalesce(rbi.source_ref,''), ':', 3), '') ~ '^\d+$'
              then split_part(rbi.source_ref, ':', 3)::int
            else null
          end as preview_seg_ord,
          round(sum(rbi.amount_ex_vat),2) as reserved_amount_ex_vat
        from reserved_batch_items rbi
        where rbi.item_type = 'ADJUSTMENT_DELTA'
          and rbi.source_ref is not null
          and btrim(coalesce(rbi.source_ref,'')) like 'preview_seg:%'
        group by
          rbi.timesheet_id,
          case
            when coalesce(split_part(coalesce(rbi.source_ref,''), ':', 3), '') ~ '^\d+$'
              then split_part(rbi.source_ref, ':', 3)::int
            else null
          end
  
  ;

  create temporary table reserved_additional_by_code on commit drop as
        select
          rbi.timesheet_id,
          nullif(btrim(coalesce(bd.bucket_code,'')), '') as code,
          round(
            sum(
              case
                when nullif(btrim(coalesce(bd.meta_json->>'source_amount_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$'
                  then abs((nullif(btrim(coalesce(bd.meta_json->>'source_amount_ex_vat','')), ''))::numeric)
                when nullif(btrim(coalesce(bd.meta_json->>'source_pay_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$'
                  then abs((nullif(btrim(coalesce(bd.meta_json->>'source_pay_ex_vat','')), ''))::numeric)
                else abs(coalesce(bd.amount_ex_vat,0))
              end
            ),
            2
          ) as reserved_amount_ex_vat
        from reserved_batch_items rbi
        join public.pay_batch_item_breakdowns bd
          on bd.pay_batch_item_id = rbi.pay_batch_item_id
        where rbi.item_type in ('ADJUSTMENT_DELTA','SEGMENT_DELTA')
          and bd.line_kind = 'ADDITIONAL_UNIT'
          and bd.bucket_code is not null
          and btrim(coalesce(bd.bucket_code,'')) <> ''
        group by rbi.timesheet_id, nullif(btrim(coalesce(bd.bucket_code,'')), '')
  
  ;

  create temporary table eligible_tsfin on commit drop as
        select
          tf.id as tsfin_id,
          tf.timesheet_id,
          tf.candidate_id,
          tf.client_id,
          ts.booking_id as ts_booking_id,
          coalesce(tf.role, con.role, ts.job_title_norm) as ts_role,
          coalesce(tf.band, con.band, ts.band) as ts_band,

          ts.week_ending_date as ts_week_ending_date,
          cl.name as ts_client_name,

          upper(coalesce(tf.pay_method,'')) as ts_pay_method,
          upper(coalesce(c.pay_method,'')) as cand_pay_method,

          c.tms_ref as cand_tms_ref,
          c.display_name as cand_display_name,

          c.umbrella_id as cand_umbrella_id,

          -- ✅ Bank readiness (candidate)
          c.bank_details_hash as cand_bank_hash,

          ts.reference_number,
          case when coalesce(con.overrideclientsettings,false) = true then coalesce(con.require_reference_to_pay,false) else coalesce(cs.pay_reference_required,false) end as require_reference_to_pay,

          -- Timesheet advance: force-include even if unauthorised/outside window
          (fi.timesheet_id is not null) as is_forced_advance,

          tf.invoice_breakdown_json,

          ts.sheet_scope as ts_sheet_scope,
          ts.worked_start_iso as ts_worked_start_iso,
          ts.worked_end_iso as ts_worked_end_iso,
          ts.break_start_iso as ts_break_start_iso,
          ts.break_end_iso as ts_break_end_iso,
          ts.break_minutes as ts_break_minutes,
          ts.actual_schedule_json as ts_actual_schedule_json,
          tf.worked_start_iso as tf_worked_start_iso,
          tf.worked_end_iso as tf_worked_end_iso,
          tf.break_start_iso as tf_break_start_iso,
          tf.break_end_iso as tf_break_end_iso,
          tf.break_minutes as tf_break_minutes,
          tf.actual_schedule_json as tf_actual_schedule_json,
          coalesce(tf.worked_start_iso, ts.worked_start_iso) as effective_worked_start_iso,
          coalesce(tf.worked_end_iso, ts.worked_end_iso) as effective_worked_end_iso,
          coalesce(tf.break_start_iso, ts.break_start_iso) as effective_break_start_iso,
          coalesce(tf.break_end_iso, ts.break_end_iso) as effective_break_end_iso,
          coalesce(tf.break_minutes, ts.break_minutes) as effective_break_minutes,
          case
            when jsonb_typeof(tf.actual_schedule_json) = 'object' then tf.actual_schedule_json
            when jsonb_typeof(tf.actual_schedule_json) = 'array' then (
              select tf_sched_item.value
              from jsonb_array_elements(tf.actual_schedule_json) as tf_sched_item(value)
              where tf_sched_item.value is not null
                and jsonb_typeof(tf_sched_item.value) = 'object'
              limit 1
            )
            when jsonb_typeof(ts.actual_schedule_json) = 'object' then ts.actual_schedule_json
            when jsonb_typeof(ts.actual_schedule_json) = 'array' then (
              select ts_sched_item.value
              from jsonb_array_elements(ts.actual_schedule_json) as ts_sched_item(value)
              where ts_sched_item.value is not null
                and jsonb_typeof(ts_sched_item.value) = 'object'
              limit 1
            )
            else null::jsonb
          end as effective_daily_schedule_json,

          tf.total_hours,
          tf.total_pay_ex_vat,
          tf.total_charge_ex_vat,

          tf.hours_day,
          tf.hours_night,
          tf.hours_sat,
          tf.hours_sun,
          tf.hours_bh,
          tf.pay_day,
          tf.pay_night,
          tf.pay_sat,
          tf.pay_sun,
          tf.pay_bh,
          tf.charge_day,
          tf.charge_night,
          tf.charge_sat,
          tf.charge_sun,
          tf.charge_bh,

          -- ✅ Use TSFIN canonical totals for additional units
          tf.additional_pay_ex_vat,
          tf.additional_charge_ex_vat,
          tf.additional_units_json,

          tf.expenses_pay_ex_vat,
          tf.expenses_charge_ex_vat,
          tf.travel_pay_ex_vat,
          tf.travel_charge_ex_vat,
          tf.accommodation_pay_ex_vat,
          tf.accommodation_charge_ex_vat,
          tf.other_pay_ex_vat,
          tf.other_charge_ex_vat,
          tf.mileage_pay_ex_vat,
          tf.mileage_charge_ex_vat,

          -- Baseline snapshot (settled)
          tps.last_settled_snapshot_json,
          tps.last_settled_signature,
          coalesce(
            tps.last_settled_signature,
            md5(coalesce(tps.last_settled_snapshot_json::text, '{}'))
          ) as effective_last_settled_signature,

          ts.authorised_at_server,
          tf.pay_on_hold,
          tf.has_rate_issue,
          tf.has_pay_channel_issue,
          tf.processing_status
        from public.timesheets_financials tf
        join public.timesheets ts
          on ts.timesheet_id = tf.timesheet_id
        join public.clients cl
          on cl.id = tf.client_id
        left join public.contracts con
          on con.id = ts.contract_id
        left join public.client_settings cs
          on cs.client_id = tf.client_id
        join public.candidates c
          on c.id = tf.candidate_id
        left join public.timesheet_pay_state tps
          on tps.timesheet_id = tf.timesheet_id
        left join force_include fi
          on fi.timesheet_id = tf.timesheet_id
        where tf.is_current = true
          and ts.archived_at_utc is null
          and coalesce(tf.pay_on_hold,false) = false
          and coalesce(tf.has_rate_issue,false) = false
          and coalesce(tf.has_pay_channel_issue,false) = false
          and upper(coalesce(tf.processing_status::text,'')) not in ('UNASSIGNED','CLIENT_UNRESOLVED','RATE_MISSING','PAY_CHANNEL_MISSING')
          and upper(coalesce(c.pay_method,'')) in ('PAYE','UMBRELLA')

          -- ✅ Eligibility: targeted rows only for TARGETED_TIMESHEETS; current live authorised rows / force include for CANDIDATE_FULL_LIVE
          and (
            (
              v_effective_refresh_scope_kind = 'TARGETED_TIMESHEETS'
              and (
                (
                  tf.timesheet_id in (select trti.timesheet_id from targeted_refresh_timesheet_ids trti)
                  or tf.timesheet_id in (select lrti.timesheet_id from linked_refresh_timesheet_ids lrti)
                )
                and (
                  (
                    ts.authorised_at_server is not null
                    and ts.revoked_at is null
                  )
                  or fi.timesheet_id is not null
                )
              )
            )
            or (
              v_effective_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
              and (
                (
                  ts.authorised_at_server is not null
                  and ts.revoked_at is null
                )
                or fi.timesheet_id is not null
              )
            )
          )

          -- ✅ Optional filters (default ALL/ALL when NULL)
          and (v_candidate_id is null or tf.candidate_id = v_candidate_id)
          and (v_client_id is null or tf.client_id = v_client_id)
  
  ;

  create temporary table debted_overpayment_cases on commit drop as
        select
          pa.candidate_id,
          coalesce(pay_advance_family_projection.canonical_timesheet_id, pa.linked_timesheet_id) as timesheet_id,
          pa.baseline_signature
        from public.pay_advances pa
        left join targeted_refresh_all_family_projection as pay_advance_family_projection
          on pay_advance_family_projection.family_timesheet_id = pa.linked_timesheet_id
        where pa.advance_kind = 'OVERPAYMENT'::public.pay_advance_kind_enum
          and pa.status in ('ACTIVE'::public.pay_advance_status_enum, 'PAID_OFF'::public.pay_advance_status_enum)
          and pa.candidate_id = v_candidate_id
          and pa.linked_timesheet_id is not null
          and (
            v_effective_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            or pa.linked_timesheet_id in (select trti.timesheet_id from targeted_refresh_timesheet_ids trti)
            or pa.linked_timesheet_id in (select lrti.timesheet_id from linked_refresh_timesheet_ids lrti)
            or pa.linked_timesheet_id in (select trf.family_timesheet_id from targeted_refresh_all_family_timesheet_ids trf)
          )
        group by
          pa.candidate_id,
          coalesce(pay_advance_family_projection.canonical_timesheet_id, pa.linked_timesheet_id),
          pa.baseline_signature
  
  ;

  create temporary table umb_map on commit drop as
        select
          u.id as umbrella_id,
          coalesce(u.enabled,false) as umb_enabled,
          coalesce(u.vat_chargeable,false) as vat_chargeable,
          -- ✅ Bank readiness (umbrella)
          u.bank_details_hash as umb_bank_hash
        from public.umbrellas u
  
  ;

  create temporary table adjustment_family_projection on commit drop as
        with eligible_current_timesheet_ids as (
          select distinct
            eligible_tsfin.timesheet_id as timesheet_id
          from eligible_tsfin
          where eligible_tsfin.timesheet_id is not null
        ),
        full_live_rotation_scope as (
          select
            full_live_scope.requested_timesheet_id,
            full_live_scope.canonical_timesheet_id,
            full_live_scope.family_timesheet_id,
            full_live_scope.family_is_current,
            full_live_scope.family_version,
            full_live_scope.booking_id
          from public._pay_timesheet_rotation_scope(
            case
              when v_effective_refresh_scope_kind = 'CANDIDATE_FULL_LIVE' then (
                select coalesce(
                  array_agg(distinct eligible_current_timesheet_ids.timesheet_id order by eligible_current_timesheet_ids.timesheet_id),
                  array[]::uuid[]
                )
                from eligible_current_timesheet_ids
              )
              else array[]::uuid[]
            end
          ) as full_live_scope
        )
        select distinct
          adjustment_projection_rows.canonical_timesheet_id,
          adjustment_projection_rows.family_timesheet_id
        from (
          select
            eligible_tsfin.timesheet_id as canonical_timesheet_id,
            targeted_refresh_all_family_projection.family_timesheet_id as family_timesheet_id
          from eligible_tsfin
          join targeted_refresh_all_family_projection
            on targeted_refresh_all_family_projection.canonical_timesheet_id = eligible_tsfin.timesheet_id
          where v_effective_refresh_scope_kind = 'TARGETED_TIMESHEETS'
            and eligible_tsfin.timesheet_id is not null
            and targeted_refresh_all_family_projection.family_timesheet_id is not null

          union all

          select
            coalesce(full_live_rotation_scope.canonical_timesheet_id, full_live_rotation_scope.requested_timesheet_id) as canonical_timesheet_id,
            full_live_rotation_scope.family_timesheet_id as family_timesheet_id
          from full_live_rotation_scope
          join eligible_current_timesheet_ids
            on eligible_current_timesheet_ids.timesheet_id = full_live_rotation_scope.requested_timesheet_id
          where v_effective_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
            and coalesce(full_live_rotation_scope.canonical_timesheet_id, full_live_rotation_scope.requested_timesheet_id) is not null
            and full_live_rotation_scope.family_timesheet_id is not null
        ) as adjustment_projection_rows
        where adjustment_projection_rows.canonical_timesheet_id is not null
          and adjustment_projection_rows.family_timesheet_id is not null
  
  ;

  create temporary table adj on commit drop as
        select distinct on (
          adjustment_family_projection.canonical_timesheet_id,
          adjustment_rows.id
        )
          adjustment_rows.id as adj_id,
          adjustment_family_projection.canonical_timesheet_id as timesheet_id,
          adjustment_rows.timesheet_id as source_timesheet_id,
          adjustment_rows.candidate_id,
          adjustment_rows.created_at as adjustment_created_at,
          round(coalesce(adjustment_rows.delta_pay_ex_vat,0),2) as delta_pay_ex_vat
        from adjustment_family_projection
        join public.ts_pay_adjustments as adjustment_rows
          on adjustment_rows.timesheet_id = adjustment_family_projection.family_timesheet_id
        where adjustment_rows.as_advance = false
          and adjustment_rows.timesheet_id is not null
          and adjustment_rows.id is not null
          and adjustment_rows.candidate_id = v_candidate_id
        order by
          adjustment_family_projection.canonical_timesheet_id,
          adjustment_rows.id,
          adjustment_rows.created_at nulls last,
          adjustment_rows.timesheet_id
  
  ;

  create temporary table ts_current on commit drop as
        select
          e.candidate_id,
          e.timesheet_id,
          e.tsfin_id,
          e.client_id,
          e.ts_booking_id,
          e.ts_role,
          e.ts_band,
          e.ts_week_ending_date,
          e.ts_client_name,
          e.ts_pay_method,
          e.cand_pay_method,
          e.cand_tms_ref,
          e.cand_display_name,
          e.cand_umbrella_id,
          e.cand_bank_hash,
          e.reference_number,
          e.require_reference_to_pay,
          coalesce(e.is_forced_advance,false) as is_forced_advance,

          coalesce(um.vat_chargeable,false) as umb_vat_chargeable,
          coalesce(um.umb_enabled,false) as umb_enabled,
          um.umb_bank_hash,

          -- ✅ segments retain stable segment identity for preview/snooze matching
          case
            when e.invoice_breakdown_json is not null
             and jsonb_typeof(e.invoice_breakdown_json) = 'object'
             and upper(coalesce(e.invoice_breakdown_json->>'mode','')) = 'SEGMENTS'
             and jsonb_typeof(e.invoice_breakdown_json->'segments') = 'array'
            then (
              select coalesce(jsonb_agg(
                jsonb_build_object(
                  'segment_id', nullif(btrim(coalesce(seg->>'segment_id','')), ''),
                  'pay_amount', round(coalesce(nullif(seg->>'pay_amount','')::numeric,0),2),
                  'charge_amount', round(coalesce(nullif(seg->>'charge_amount','')::numeric, nullif(seg->>'charge_ex_vat','')::numeric,0),2),
                  'units', coalesce(nullif(seg->>'units','')::numeric, nullif(seg->>'hours','')::numeric),
                  'hours', coalesce(nullif(seg->>'hours','')::numeric, nullif(seg->>'units','')::numeric),
                  'hours_day', coalesce(nullif(seg->>'hours_day','')::numeric, 0),
                  'hours_night', coalesce(nullif(seg->>'hours_night','')::numeric, 0),
                  'hours_sat', coalesce(nullif(seg->>'hours_sat','')::numeric, 0),
                  'hours_sun', coalesce(nullif(seg->>'hours_sun','')::numeric, 0),
                  'hours_bh', coalesce(nullif(seg->>'hours_bh','')::numeric, 0),
                  'exclude_from_pay', coalesce(nullif(seg->>'exclude_from_pay','')::boolean, false),
                  'ref_num', nullif(btrim(coalesce(seg->>'ref_num','')), ''),
                  'nhsp_shift_id', nullif(btrim(coalesce(seg->>'nhsp_shift_id','')), ''),
                  'shift_id', coalesce(
                    nullif(btrim(coalesce(seg->>'shift_id','')), ''),
                    nullif(btrim(coalesce(seg->>'nhsp_shift_id','')), '')
                  ),
                  'external_row_key', nullif(btrim(coalesce(seg->>'external_row_key','')), ''),
                  'hr_request_id', nullif(btrim(coalesce(seg->>'hr_request_id','')), ''),
                  'request_id', coalesce(
                    nullif(btrim(coalesce(seg->>'request_id','')), ''),
                    nullif(btrim(coalesce(seg->>'hr_request_id','')), '')
                  ),
                  'source_system', nullif(btrim(coalesce(seg->>'source_system','')), ''),
                  'latest_import_id', nullif(btrim(coalesce(seg->>'latest_import_id','')), ''),
                  'date', nullif(btrim(coalesce(seg->>'date','')), ''),
                  'segment_key', nullif(btrim(coalesce(seg->>'segment_key','')), ''),
                  'segment_stable_key', coalesce(
                    nullif(btrim(coalesce(seg->>'segment_stable_key','')), ''),
                    nullif(btrim(coalesce(seg->>'segment_id','')), ''),
                    nullif(btrim(coalesce(seg->>'segment_key','')), ''),
                    nullif(btrim(coalesce(seg->>'date','')), ''),
                    nullif(btrim(coalesce(seg->>'ref_num','')), '')
                  ),
                  'start_utc', nullif(btrim(coalesce(seg->>'start_utc','')), ''),
                  'end_utc', nullif(btrim(coalesce(seg->>'end_utc','')), ''),
                  'start', case
                    when nullif(btrim(coalesce(seg->>'start','')), '') is not null then nullif(btrim(coalesce(seg->>'start','')), '')
                    when nullif(btrim(coalesce(seg->>'start_utc','')), '') is not null then to_char(((seg->>'start_utc')::timestamptz at time zone 'Europe/London'), 'HH24:MI')
                    else null
                  end,
                  'end', case
                    when nullif(btrim(coalesce(seg->>'end','')), '') is not null then nullif(btrim(coalesce(seg->>'end','')), '')
                    when nullif(btrim(coalesce(seg->>'end_utc','')), '') is not null then to_char(((seg->>'end_utc')::timestamptz at time zone 'Europe/London'), 'HH24:MI')
                    else null
                  end,
                  'break_start', nullif(btrim(coalesce(seg->>'break_start','')), ''),
                  'break_end', nullif(btrim(coalesce(seg->>'break_end','')), ''),
                  'break_mins', coalesce(nullif(seg->>'break_mins','')::numeric, nullif(seg->>'break_minutes','')::numeric),
                  'breaks', case when jsonb_typeof(seg->'breaks') = 'array' then seg->'breaks' else '[]'::jsonb end,
                  'client_name', e.ts_client_name,
                  'role', e.ts_role,
                  'band', e.ts_band
                )
              ), '[]'::jsonb)
              from jsonb_array_elements(e.invoice_breakdown_json->'segments') seg
              where seg is not null and jsonb_typeof(seg)='object'
            )
            else case
              when upper(coalesce(e.ts_sheet_scope::text,'')) = 'DAILY'
              then jsonb_build_array(
                jsonb_build_object(
                  'segment_id', ('ts:' || e.timesheet_id::text),
                  'pay_amount', round(coalesce(e.total_pay_ex_vat,0),2),
                  'charge_amount', round(coalesce(e.total_charge_ex_vat,0),2),
                  'units', e.total_hours,
                  'hours', e.total_hours,
                  'hours_day', coalesce(e.hours_day, 0),
                  'hours_night', coalesce(e.hours_night, 0),
                  'hours_sat', coalesce(e.hours_sat, 0),
                  'hours_sun', coalesce(e.hours_sun, 0),
                  'hours_bh', coalesce(e.hours_bh, 0),
                  'exclude_from_pay', false,
                  'ref_num', nullif(btrim(coalesce(e.reference_number,'')), ''),
                  'date', case
                    when e.effective_worked_start_iso is not null then ((e.effective_worked_start_iso at time zone 'Europe/London')::date)::text
                    else coalesce(
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'date','')), ''),
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'work_date','')), ''),
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'ymd','')), ''),
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'date_ymd','')), '')
                    )
                  end,
                  'segment_key', ('ts:' || e.timesheet_id::text),
                  'segment_stable_key', ('timesheet:' || coalesce(e.ts_booking_id, e.timesheet_id::text)),
                  'start_utc', case
                    when e.effective_worked_start_iso is not null then e.effective_worked_start_iso::text
                    else null
                  end,
                  'end_utc', case
                    when e.effective_worked_end_iso is not null then e.effective_worked_end_iso::text
                    else null
                  end,
                  'start', case
                    when e.effective_worked_start_iso is not null then to_char((e.effective_worked_start_iso at time zone 'Europe/London'), 'HH24:MI')
                    else coalesce(
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'start','')), ''),
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'worked_start','')), '')
                    )
                  end,
                  'end', case
                    when e.effective_worked_end_iso is not null then to_char((e.effective_worked_end_iso at time zone 'Europe/London'), 'HH24:MI')
                    else coalesce(
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'end','')), ''),
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'worked_end','')), '')
                    )
                  end,
                  'break_start', case
                    when e.effective_break_start_iso is not null then to_char((e.effective_break_start_iso at time zone 'Europe/London'), 'HH24:MI')
                    else nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_start','')), '')
                  end,
                  'break_end', case
                    when e.effective_break_end_iso is not null then to_char((e.effective_break_end_iso at time zone 'Europe/London'), 'HH24:MI')
                    else nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_end','')), '')
                  end,
                  'break_mins', coalesce(
                    e.effective_break_minutes::numeric,
                    nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_minutes','')), '')::numeric,
                    nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_mins','')), '')::numeric,
                    nullif(btrim(coalesce(e.effective_daily_schedule_json->>'breakMinutes','')), '')::numeric,
                    nullif(btrim(coalesce(e.effective_daily_schedule_json->>'breakMin','')), '')::numeric,
                    case
                      when e.effective_break_start_iso is not null and e.effective_break_end_iso is not null
                        then greatest(
                          0::numeric,
                          round((extract(epoch from (e.effective_break_end_iso - e.effective_break_start_iso)) / 60.0)::numeric, 0)
                        )
                      else null::numeric
                    end
                  ),
                  'breaks', case
                    when jsonb_typeof(e.effective_daily_schedule_json->'breaks') = 'array' then e.effective_daily_schedule_json->'breaks'
                    when e.effective_break_start_iso is not null and e.effective_break_end_iso is not null
                      then jsonb_build_array(
                        jsonb_build_object(
                          'start', to_char((e.effective_break_start_iso at time zone 'Europe/London'), 'HH24:MI'),
                          'end', to_char((e.effective_break_end_iso at time zone 'Europe/London'), 'HH24:MI'),
                          'break_mins', coalesce(
                            e.effective_break_minutes::numeric,
                            case
                              when e.effective_break_start_iso is not null and e.effective_break_end_iso is not null
                                then greatest(
                                  0::numeric,
                                  round((extract(epoch from (e.effective_break_end_iso - e.effective_break_start_iso)) / 60.0)::numeric, 0)
                                )
                              else null::numeric
                            end
                          )
                        )
                      )
                    when nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_start','')), '') is not null
                     and nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_end','')), '') is not null
                      then jsonb_build_array(
                        jsonb_build_object(
                          'start', nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_start','')), ''),
                          'end', nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_end','')), ''),
                          'break_mins', coalesce(
                            e.effective_break_minutes::numeric,
                            nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_minutes','')), '')::numeric,
                            nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_mins','')), '')::numeric,
                            nullif(btrim(coalesce(e.effective_daily_schedule_json->>'breakMinutes','')), '')::numeric,
                            nullif(btrim(coalesce(e.effective_daily_schedule_json->>'breakMin','')), '')::numeric
                          )
                        )
                      )
                    else '[]'::jsonb
                  end,
                  'client_name', e.ts_client_name,
                  'role', e.ts_role,
                  'band', e.ts_band
                )
              )
              else jsonb_build_array(
                jsonb_build_object(
                  'segment_id', ('ts:' || e.timesheet_id::text),
                  'pay_amount', round(coalesce(e.total_pay_ex_vat,0),2),
                  'charge_amount', round(coalesce(e.total_charge_ex_vat,0),2),
                  'units', e.total_hours,
                  'hours', e.total_hours,
                  'hours_day', coalesce(e.hours_day, 0),
                  'hours_night', coalesce(e.hours_night, 0),
                  'hours_sat', coalesce(e.hours_sat, 0),
                  'hours_sun', coalesce(e.hours_sun, 0),
                  'hours_bh', coalesce(e.hours_bh, 0),
                  'exclude_from_pay', false,
                  'ref_num', nullif(btrim(coalesce(e.reference_number,'')), ''),
                  'date', null,
                  'segment_key', ('ts:' || e.timesheet_id::text),
                  'segment_stable_key', ('timesheet:' || coalesce(e.ts_booking_id, e.timesheet_id::text)),
                  'start_utc', null,
                  'end_utc', null,
                  'start', null,
                  'end', null,
                  'break_start', null,
                  'break_end', null,
                  'break_mins', null,
                  'breaks', '[]'::jsonb,
                  'client_name', e.ts_client_name,
                  'role', e.ts_role,
                  'band', e.ts_band
                )
              )
            end
          end as current_segments_json,

          round(coalesce(e.total_hours,0),2) as total_hours,
          round(coalesce(e.total_pay_ex_vat,0),2) as total_pay_ex_vat,
          round(coalesce(e.total_charge_ex_vat,0),2) as total_charge_ex_vat,
          round(coalesce(e.hours_day,0),6) as hours_day,
          round(coalesce(e.hours_night,0),6) as hours_night,
          round(coalesce(e.hours_sat,0),6) as hours_sat,
          round(coalesce(e.hours_sun,0),6) as hours_sun,
          round(coalesce(e.hours_bh,0),6) as hours_bh,
          case when e.pay_day is null then null else round(e.pay_day,6) end as pay_day,
          case when e.pay_night is null then null else round(e.pay_night,6) end as pay_night,
          case when e.pay_sat is null then null else round(e.pay_sat,6) end as pay_sat,
          case when e.pay_sun is null then null else round(e.pay_sun,6) end as pay_sun,
          case when e.pay_bh is null then null else round(e.pay_bh,6) end as pay_bh,
          case when e.charge_day is null then null else round(e.charge_day,6) end as charge_day,
          case when e.charge_night is null then null else round(e.charge_night,6) end as charge_night,
          case when e.charge_sat is null then null else round(e.charge_sat,6) end as charge_sat,
          case when e.charge_sun is null then null else round(e.charge_sun,6) end as charge_sun,
          case when e.charge_bh is null then null else round(e.charge_bh,6) end as charge_bh,
          coalesce(e.additional_units_json, '{}'::jsonb) as current_additional_units_json,

          -- Canonical additional truth is the TSFIN top-level additional bucket plus
          -- additional_units_json. SEGMENTS invoice_breakdown_json.additional is not a
          -- Banking Pay entitlement source: in expense-only manual rows it can be a
          -- catch-all presentation artefact for non-segment totals.
          round(coalesce(e.additional_pay_ex_vat,0),2) as current_additional_pay_ex_vat,
          round(coalesce(e.additional_charge_ex_vat,0),2) as current_additional_charge_ex_vat,
          round(coalesce(e.expenses_pay_ex_vat,0),2) as current_expenses_pay_ex_vat,
          round(coalesce(e.expenses_charge_ex_vat,0),2) as current_expenses_charge_ex_vat,
          round(coalesce(e.travel_pay_ex_vat,0),2) as current_travel_pay_ex_vat,
          round(coalesce(e.travel_charge_ex_vat,0),2) as current_travel_charge_ex_vat,
          round(coalesce(e.accommodation_pay_ex_vat,0),2) as current_accommodation_pay_ex_vat,
          round(coalesce(e.accommodation_charge_ex_vat,0),2) as current_accommodation_charge_ex_vat,
          round(coalesce(e.other_pay_ex_vat,0),2) as current_other_pay_ex_vat,
          round(coalesce(e.other_charge_ex_vat,0),2) as current_other_charge_ex_vat,
          round(coalesce(e.mileage_pay_ex_vat,0),2) as current_mileage_pay_ex_vat,
          round(coalesce(e.mileage_charge_ex_vat,0),2) as current_mileage_charge_ex_vat,

          coalesce(
            (
              select jsonb_agg(
                jsonb_build_object(
                  'id', a.adj_id::text,
                  'delta_pay_ex_vat', a.delta_pay_ex_vat
                )
                order by a.adjustment_created_at nulls last, a.adj_id
              )
              from adj a
              where a.timesheet_id = e.timesheet_id
            ),
            '[]'::jsonb
          ) as current_adjustments_json,

          e.last_settled_snapshot_json,
          e.effective_last_settled_signature as baseline_signature,
          (doc.timesheet_id is not null) as has_active_overpayment_case
        from eligible_tsfin e
        left join umb_map um
          on um.umbrella_id = e.cand_umbrella_id
        left join debted_overpayment_cases doc
          on doc.candidate_id = e.candidate_id
         and doc.timesheet_id = e.timesheet_id
         and coalesce(doc.baseline_signature, '') = coalesce(e.effective_last_settled_signature, '')
  
  ;

  create temporary table targeted_baseline_only_ts_current on commit drop as
        select
          coalesce(tf_any.candidate_id, v_candidate_id) as candidate_id,
          tri.canonical_timesheet_id as timesheet_id,
          tf_any.id as tsfin_id,
          tf_any.client_id as client_id,
          ts.booking_id as ts_booking_id,
          coalesce(tf_any.role, con.role, ts.job_title_norm) as ts_role,
          coalesce(tf_any.band, con.band, ts.band) as ts_band,
          ts.week_ending_date as ts_week_ending_date,
          cl.name as ts_client_name,
          upper(coalesce(tf_any.pay_method, cand.pay_method, '')) as ts_pay_method,
          upper(coalesce(cand.pay_method, '')) as cand_pay_method,
          cand.tms_ref as cand_tms_ref,
          cand.display_name as cand_display_name,
          cand.umbrella_id as cand_umbrella_id,
          cand.bank_details_hash as cand_bank_hash,
          ts.reference_number,
          case when coalesce(con.overrideclientsettings,false) = true then coalesce(con.require_reference_to_pay,false) else coalesce(cs.pay_reference_required,false) end as require_reference_to_pay,
          false as is_forced_advance,
          coalesce(um.vat_chargeable,false) as umb_vat_chargeable,
          coalesce(um.umb_enabled,false) as umb_enabled,
          um.umb_bank_hash,
          case
            when upper(coalesce(ts.sheet_scope::text,'')) = 'DAILY'
            then jsonb_build_array(
              jsonb_build_object(
                'segment_id', ('ts:' || tri.canonical_timesheet_id::text),
                'pay_amount', 0,
                'charge_amount', 0,
                'units', 0,
                'hours', 0,
                'hours_day', 0,
                'hours_night', 0,
                'hours_sat', 0,
                'hours_sun', 0,
                'hours_bh', 0,
                'exclude_from_pay', false,
                'ref_num', nullif(btrim(coalesce(ts.reference_number,'')), ''),
                'date', case
                  when daily_sched.effective_worked_start_iso is not null then ((daily_sched.effective_worked_start_iso at time zone 'Europe/London')::date)::text
                  else coalesce(
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'date','')), ''),
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'work_date','')), ''),
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'ymd','')), ''),
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'date_ymd','')), '')
                  )
                end,
                'segment_key', ('ts:' || tri.canonical_timesheet_id::text),
                'segment_stable_key', ('timesheet:' || coalesce(ts.booking_id, tri.canonical_timesheet_id::text)),
                'start_utc', case
                  when daily_sched.effective_worked_start_iso is not null then daily_sched.effective_worked_start_iso::text
                  else null
                end,
                'end_utc', case
                  when daily_sched.effective_worked_end_iso is not null then daily_sched.effective_worked_end_iso::text
                  else null
                end,
                'start', case
                  when daily_sched.effective_worked_start_iso is not null then to_char((daily_sched.effective_worked_start_iso at time zone 'Europe/London'), 'HH24:MI')
                  else coalesce(
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'start','')), ''),
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'worked_start','')), '')
                  )
                end,
                'end', case
                  when daily_sched.effective_worked_end_iso is not null then to_char((daily_sched.effective_worked_end_iso at time zone 'Europe/London'), 'HH24:MI')
                  else coalesce(
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'end','')), ''),
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'worked_end','')), '')
                  )
                end,
                'break_start', case
                  when daily_sched.effective_break_start_iso is not null then to_char((daily_sched.effective_break_start_iso at time zone 'Europe/London'), 'HH24:MI')
                  else nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_start','')), '')
                end,
                'break_end', case
                  when daily_sched.effective_break_end_iso is not null then to_char((daily_sched.effective_break_end_iso at time zone 'Europe/London'), 'HH24:MI')
                  else nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_end','')), '')
                end,
                'break_mins', coalesce(
                  daily_sched.effective_break_minutes::numeric,
                  nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_minutes','')), '')::numeric,
                  nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_mins','')), '')::numeric,
                  nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'breakMinutes','')), '')::numeric,
                  nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'breakMin','')), '')::numeric,
                  case
                    when daily_sched.effective_break_start_iso is not null and daily_sched.effective_break_end_iso is not null
                      then greatest(
                        0::numeric,
                        round((extract(epoch from (daily_sched.effective_break_end_iso - daily_sched.effective_break_start_iso)) / 60.0)::numeric, 0)
                      )
                    else null::numeric
                  end
                ),
                'breaks', case
                  when jsonb_typeof(daily_sched.effective_daily_schedule_json->'breaks') = 'array' then daily_sched.effective_daily_schedule_json->'breaks'
                  when daily_sched.effective_break_start_iso is not null and daily_sched.effective_break_end_iso is not null
                    then jsonb_build_array(
                      jsonb_build_object(
                        'start', to_char((daily_sched.effective_break_start_iso at time zone 'Europe/London'), 'HH24:MI'),
                        'end', to_char((daily_sched.effective_break_end_iso at time zone 'Europe/London'), 'HH24:MI'),
                        'break_mins', coalesce(
                          daily_sched.effective_break_minutes::numeric,
                          case
                            when daily_sched.effective_break_start_iso is not null and daily_sched.effective_break_end_iso is not null
                              then greatest(
                                0::numeric,
                                round((extract(epoch from (daily_sched.effective_break_end_iso - daily_sched.effective_break_start_iso)) / 60.0)::numeric, 0)
                              )
                            else null::numeric
                          end
                        )
                      )
                    )
                  when nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_start','')), '') is not null
                   and nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_end','')), '') is not null
                    then jsonb_build_array(
                      jsonb_build_object(
                        'start', nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_start','')), ''),
                        'end', nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_end','')), ''),
                        'break_mins', coalesce(
                          daily_sched.effective_break_minutes::numeric,
                          nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_minutes','')), '')::numeric,
                          nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_mins','')), '')::numeric,
                          nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'breakMinutes','')), '')::numeric,
                          nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'breakMin','')), '')::numeric
                        )
                      )
                    )
                  else '[]'::jsonb
                end,
                'client_name', cl.name,
                'role', coalesce(tf_any.role, con.role, ts.job_title_norm),
                'band', coalesce(tf_any.band, con.band, ts.band)
              )
            )
            else jsonb_build_array(
              jsonb_build_object(
                'segment_id', ('ts:' || tri.canonical_timesheet_id::text),
                'pay_amount', 0,
                'charge_amount', 0,
                'units', 0,
                'hours', 0,
                'hours_day', 0,
                'hours_night', 0,
                'hours_sat', 0,
                'hours_sun', 0,
                'hours_bh', 0,
                'exclude_from_pay', false,
                'ref_num', nullif(btrim(coalesce(ts.reference_number,'')), ''),
                'date', null,
                'segment_key', ('ts:' || tri.canonical_timesheet_id::text),
                'segment_stable_key', ('timesheet:' || coalesce(ts.booking_id, tri.canonical_timesheet_id::text)),
                'start_utc', null,
                'end_utc', null,
                'start', null,
                'end', null,
                'break_start', null,
                'break_end', null,
                'break_mins', null,
                'breaks', '[]'::jsonb,
                'client_name', cl.name,
                'role', coalesce(tf_any.role, con.role, ts.job_title_norm),
                'band', coalesce(tf_any.band, con.band, ts.band)
              )
            )
          end as current_segments_json,
          0::numeric as total_hours,
          0::numeric as total_pay_ex_vat,
          0::numeric as total_charge_ex_vat,
          0::numeric as hours_day,
          0::numeric as hours_night,
          0::numeric as hours_sat,
          0::numeric as hours_sun,
          0::numeric as hours_bh,
          null::numeric as pay_day,
          null::numeric as pay_night,
          null::numeric as pay_sat,
          null::numeric as pay_sun,
          null::numeric as pay_bh,
          null::numeric as charge_day,
          null::numeric as charge_night,
          null::numeric as charge_sat,
          null::numeric as charge_sun,
          null::numeric as charge_bh,
          '{}'::jsonb as current_additional_units_json,
          0::numeric as current_additional_pay_ex_vat,
          0::numeric as current_additional_charge_ex_vat,
          0::numeric as current_expenses_pay_ex_vat,
          0::numeric as current_expenses_charge_ex_vat,
          0::numeric as current_travel_pay_ex_vat,
          0::numeric as current_travel_charge_ex_vat,
          0::numeric as current_accommodation_pay_ex_vat,
          0::numeric as current_accommodation_charge_ex_vat,
          0::numeric as current_other_pay_ex_vat,
          0::numeric as current_other_charge_ex_vat,
          0::numeric as current_mileage_pay_ex_vat,
          0::numeric as current_mileage_charge_ex_vat,
          '[]'::jsonb as current_adjustments_json,
          tps.last_settled_snapshot_json,
          coalesce(
            tps.last_settled_signature,
            md5(coalesce(tps.last_settled_snapshot_json::text, '{}'))
          ) as baseline_signature,
          (doc.timesheet_id is not null) as has_active_overpayment_case
        from targeted_refresh_all_baseline_projection tri
        join public.timesheet_pay_state tps
          on tps.timesheet_id = tri.family_timesheet_id
        left join lateral (
          select tf.*
          from public.timesheets_financials tf
          where tf.timesheet_id = tri.canonical_timesheet_id
          order by tf.is_current desc, tf.computed_at_utc desc nulls last, tf.id desc
          limit 1
        ) tf_any on true
        join public.candidates cand
          on cand.id = coalesce(tf_any.candidate_id, v_candidate_id)
        left join public.timesheets ts
          on ts.timesheet_id = tri.canonical_timesheet_id
        left join lateral (
          select
            coalesce(tf_any.worked_start_iso, ts.worked_start_iso) as effective_worked_start_iso,
            coalesce(tf_any.worked_end_iso, ts.worked_end_iso) as effective_worked_end_iso,
            coalesce(tf_any.break_start_iso, ts.break_start_iso) as effective_break_start_iso,
            coalesce(tf_any.break_end_iso, ts.break_end_iso) as effective_break_end_iso,
            coalesce(tf_any.break_minutes, ts.break_minutes) as effective_break_minutes,
            case
              when jsonb_typeof(tf_any.actual_schedule_json) = 'object' then tf_any.actual_schedule_json
              when jsonb_typeof(tf_any.actual_schedule_json) = 'array' then (
                select tf_sched_item.value
                from jsonb_array_elements(tf_any.actual_schedule_json) as tf_sched_item(value)
                where tf_sched_item.value is not null
                  and jsonb_typeof(tf_sched_item.value) = 'object'
                limit 1
              )
              when jsonb_typeof(ts.actual_schedule_json) = 'object' then ts.actual_schedule_json
              when jsonb_typeof(ts.actual_schedule_json) = 'array' then (
                select ts_sched_item.value
                from jsonb_array_elements(ts.actual_schedule_json) as ts_sched_item(value)
                where ts_sched_item.value is not null
                  and jsonb_typeof(ts_sched_item.value) = 'object'
                limit 1
              )
              else null::jsonb
            end as effective_daily_schedule_json
        ) daily_sched on true
        left join public.contracts con
          on con.id = ts.contract_id
        left join public.client_settings cs
          on cs.client_id = tf_any.client_id
        left join public.clients cl
          on cl.id = tf_any.client_id
        left join umb_map um
          on um.umbrella_id = cand.umbrella_id
        left join debted_overpayment_cases doc
          on doc.candidate_id = coalesce(tf_any.candidate_id, v_candidate_id)
         and doc.timesheet_id = tri.canonical_timesheet_id
         and coalesce(doc.baseline_signature, '') = coalesce(tps.last_settled_signature, md5(coalesce(tps.last_settled_snapshot_json::text, '{}')))
        where v_effective_refresh_scope_kind = 'TARGETED_TIMESHEETS'
          and (
            tps.last_settled_snapshot_json is not null
            or tps.last_settled_signature is not null
            or tps.last_settled_pay_batch_id is not null
            or tps.last_settled_at_utc is not null
          )
          and not exists (
            select 1
            from ts_current cur
            where cur.timesheet_id = tri.canonical_timesheet_id
          )
  ;

  create temporary table active_settled_artifact_components on commit drop as
        select
          active_settled_components.timesheet_id,
          active_settled_components.key_type,
          active_settled_components.key_value,
          active_settled_components.amount_ex_vat,
          active_settled_components.amount_inc_vat
        from public._pay_active_settled_components(
          ARRAY(
            select distinct active_baseline_scope.timesheet_id
            from (
              select ts_current.timesheet_id
              from ts_current
              where ts_current.timesheet_id is not null
              union
              select targeted_baseline_only_ts_current.timesheet_id
              from targeted_baseline_only_ts_current
              where targeted_baseline_only_ts_current.timesheet_id is not null
            ) as active_baseline_scope
          )
        ) as active_settled_components
        where active_settled_components.timesheet_id is not null
          and active_settled_components.key_type is not null
          and active_settled_components.key_value is not null
  ;

  create temporary table active_settled_artifact_baseline_by_timesheet on commit drop as
        select
          active_settled_artifact_components.timesheet_id,
          coalesce(
            jsonb_agg(
              jsonb_build_object(
                'key_type', active_settled_artifact_components.key_type,
                'key_value', active_settled_artifact_components.key_value,
                'amount_ex_vat', active_settled_artifact_components.amount_ex_vat,
                'amount_inc_vat', active_settled_artifact_components.amount_inc_vat,
                'baseline_source', 'ACTIVE_SETTLED_ARTIFACT'
              )
              order by active_settled_artifact_components.key_type, active_settled_artifact_components.key_value
            ),
            '[]'::jsonb
          ) as active_settled_components_json,
          round(coalesce(sum(coalesce(active_settled_artifact_components.amount_ex_vat, 0)), 0), 2)::numeric as active_settled_amount_ex_vat,
          round(coalesce(sum(coalesce(active_settled_artifact_components.amount_inc_vat, 0)), 0), 2)::numeric as active_settled_amount_inc_vat,
          count(*)::int as active_settled_component_count
        from active_settled_artifact_components
        group by active_settled_artifact_components.timesheet_id
  ;

  create temporary table ts_baseline on commit drop as
        select
          t.candidate_id,
          t.timesheet_id,
          t.client_id,
          t.ts_booking_id,
          t.ts_role,
          t.ts_band,
          t.ts_week_ending_date,
          t.ts_client_name,
          t.ts_pay_method,
          t.cand_pay_method,
          t.cand_tms_ref,
          t.cand_display_name,
          t.cand_umbrella_id,
          t.umb_enabled,
          t.umb_vat_chargeable,
          t.require_reference_to_pay,
          t.is_forced_advance,

          -- ✅ bank readiness propagation
          t.cand_bank_hash,
          t.umb_bank_hash,

          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then
              jsonb_build_object(
                'baseline_source', 'ACTIVE_SETTLED_ARTIFACT',
                'active_settled_artifact_components', coalesce(active_settled_artifact_baseline.active_settled_components_json, '[]'::jsonb),
                'active_settled_amount_ex_vat', coalesce(active_settled_artifact_baseline.active_settled_amount_ex_vat, 0),
                'active_settled_amount_inc_vat', coalesce(active_settled_artifact_baseline.active_settled_amount_inc_vat, 0),
                'legacy_timesheet_pay_state_snapshot_json', coalesce(t.last_settled_snapshot_json, '{}'::jsonb)
              )
            else coalesce(t.last_settled_snapshot_json, '{}'::jsonb)
          end as base_json,
          coalesce(active_settled_artifact_baseline.active_settled_components_json, '[]'::jsonb) as active_settled_artifact_components_json,
          coalesce(active_settled_artifact_baseline.active_settled_component_count, 0)::int as active_settled_artifact_component_count,
          coalesce(active_settled_artifact_baseline.active_settled_amount_ex_vat, 0)::numeric as active_settled_artifact_amount_ex_vat,
          coalesce(active_settled_artifact_baseline.active_settled_amount_inc_vat, 0)::numeric as active_settled_artifact_amount_inc_vat,
          (coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0) as has_active_settled_artifact_baseline,
          t.baseline_signature,
          coalesce(t.has_active_overpayment_case,false) as has_active_overpayment_case,

          coalesce(t.current_segments_json, '[]'::jsonb) as current_segments_json,
          coalesce(t.current_adjustments_json, '[]'::jsonb) as current_adjustments_json,

          t.total_hours,
          t.total_pay_ex_vat,
          t.total_charge_ex_vat,
          t.hours_day,
          t.hours_night,
          t.hours_sat,
          t.hours_sun,
          t.hours_bh,
          t.pay_day,
          t.pay_night,
          t.pay_sat,
          t.pay_sun,
          t.pay_bh,
          t.charge_day,
          t.charge_night,
          t.charge_sat,
          t.charge_sun,
          t.charge_bh,
          t.hours_day as cur_hours_day,
          t.hours_night as cur_hours_night,
          t.hours_sat as cur_hours_sat,
          t.hours_sun as cur_hours_sun,
          t.hours_bh as cur_hours_bh,
          t.pay_day as cur_pay_day,
          t.pay_night as cur_pay_night,
          t.pay_sat as cur_pay_sat,
          t.pay_sun as cur_pay_sun,
          t.pay_bh as cur_pay_bh,
          t.charge_day as cur_charge_day,
          t.charge_night as cur_charge_night,
          t.charge_sat as cur_charge_sat,
          t.charge_sun as cur_charge_sun,
          t.charge_bh as cur_charge_bh,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then 0::numeric
            when coalesce(t.last_settled_snapshot_json->>'hours_day', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,day}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'hours_day')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,day}')::numeric), 6)
            else 0::numeric
          end as bas_hours_day,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then 0::numeric
            when coalesce(t.last_settled_snapshot_json->>'hours_night', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,night}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'hours_night')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,night}')::numeric), 6)
            else 0::numeric
          end as bas_hours_night,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then 0::numeric
            when coalesce(t.last_settled_snapshot_json->>'hours_sat', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,sat}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'hours_sat')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,sat}')::numeric), 6)
            else 0::numeric
          end as bas_hours_sat,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then 0::numeric
            when coalesce(t.last_settled_snapshot_json->>'hours_sun', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,sun}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'hours_sun')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,sun}')::numeric), 6)
            else 0::numeric
          end as bas_hours_sun,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then 0::numeric
            when coalesce(t.last_settled_snapshot_json->>'hours_bh', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,bh}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'hours_bh')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,bh}')::numeric), 6)
            else 0::numeric
          end as bas_hours_bh,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'pay_day', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,day}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'pay_day')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,day}')::numeric), 6)
            else null::numeric
          end as bas_pay_day,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'pay_night', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,night}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'pay_night')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,night}')::numeric), 6)
            else null::numeric
          end as bas_pay_night,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'pay_sat', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,sat}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'pay_sat')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,sat}')::numeric), 6)
            else null::numeric
          end as bas_pay_sat,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'pay_sun', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,sun}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'pay_sun')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,sun}')::numeric), 6)
            else null::numeric
          end as bas_pay_sun,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'pay_bh', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,bh}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'pay_bh')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,bh}')::numeric), 6)
            else null::numeric
          end as bas_pay_bh,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'charge_day', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,day}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'charge_day')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,day}')::numeric), 6)
            else null::numeric
          end as bas_charge_day,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'charge_night', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,night}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'charge_night')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,night}')::numeric), 6)
            else null::numeric
          end as bas_charge_night,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'charge_sat', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,sat}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'charge_sat')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,sat}')::numeric), 6)
            else null::numeric
          end as bas_charge_sat,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'charge_sun', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,sun}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'charge_sun')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,sun}')::numeric), 6)
            else null::numeric
          end as bas_charge_sun,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'charge_bh', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,bh}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'charge_bh')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,bh}')::numeric), 6)
            else null::numeric
          end as bas_charge_bh,
          t.current_additional_pay_ex_vat,
          t.current_additional_charge_ex_vat,
          t.current_additional_units_json,
          t.current_expenses_pay_ex_vat,
          t.current_expenses_charge_ex_vat,
          t.current_travel_pay_ex_vat,
          t.current_travel_charge_ex_vat,
          t.current_accommodation_pay_ex_vat,
          t.current_accommodation_charge_ex_vat,
          t.current_other_pay_ex_vat,
          t.current_other_charge_ex_vat,
          t.current_mileage_pay_ex_vat,
          t.current_mileage_charge_ex_vat
        from (
          select * from ts_current
          union all
          select * from targeted_baseline_only_ts_current
        ) t
        left join active_settled_artifact_baseline_by_timesheet as active_settled_artifact_baseline
          on active_settled_artifact_baseline.timesheet_id = t.timesheet_id
  
  ;

  create temporary table finance_case_baseline_scope on commit drop as
        select
          vfcr.*
        from public.v_finance_cases_register vfcr
        where vfcr.case_type in (
          'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
          'OVERPAYMENT'::public.pay_finance_case_type_enum,
          'UNDERPAYMENT'::public.pay_finance_case_type_enum,
          'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
          'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
        )
          and upper(coalesce(vfcr.status::text,'')) = 'ACTIVE'
          and coalesce(vfcr.outstanding_amount,0) > 0
          and (
            (
              vfcr.case_type in (
                'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
                'UNDERPAYMENT'::public.pay_finance_case_type_enum,
                'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
              )
              and (
                upper(coalesce(vfcr.payout_status::text,'')) <> 'PAID'
                or vfcr.next_due_week_start is null
                or vfcr.next_due_week_start <= v_week_start
              )
            )
            or (
              vfcr.case_type in (
                'OVERPAYMENT'::public.pay_finance_case_type_enum,
                'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum
              )
              and (
                vfcr.next_due_week_start is null
                or vfcr.next_due_week_start <= v_week_start
              )
            )
            or (
              vfcr.case_type in (
                'OVERPAYMENT'::public.pay_finance_case_type_enum,
                'UNDERPAYMENT'::public.pay_finance_case_type_enum,
                'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
                'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
              )
              and exists (
                select 1
                from public.pay_finance_case_components as pfc_restructure_scope
                join public.candidates as c_restructure_scope
                  on c_restructure_scope.id = pfc_restructure_scope.candidate_id
                where pfc_restructure_scope.finance_case_id = vfcr.finance_case_id
                  and pfc_restructure_scope.closed_at_utc is null
                  and pfc_restructure_scope.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
                  and round(coalesce(pfc_restructure_scope.remaining_source_amount, 0), 2) > 0
                  and upper(coalesce(pfc_restructure_scope.source_pay_method, '')) in ('PAYE', 'UMBRELLA')
                  and upper(coalesce(c_restructure_scope.pay_method, '')) in ('PAYE', 'UMBRELLA')
                  and upper(coalesce(pfc_restructure_scope.source_pay_method, '')) <> upper(coalesce(c_restructure_scope.pay_method, ''))
                  and (
                    coalesce(pfc_restructure_scope.is_resolution_stale, false) = true
                    or nullif(btrim(coalesce(pfc_restructure_scope.saved_target_pay_method, '')), '') is null
                    or upper(coalesce(pfc_restructure_scope.saved_target_pay_method, '')) <> upper(coalesce(c_restructure_scope.pay_method, ''))
                  )
              )
            )
          )
          and (v_candidate_id is null or vfcr.candidate_id = v_candidate_id)
          and (v_client_id is null or vfcr.client_id = v_client_id)
          and (
            v_effective_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            or vfcr.linked_timesheet_id is null
            or vfcr.linked_timesheet_id in (select trti.timesheet_id from targeted_refresh_timesheet_ids trti)
            or vfcr.linked_timesheet_id in (select lrti.timesheet_id from linked_refresh_timesheet_ids lrti)
            or vfcr.linked_timesheet_id in (select trf.family_timesheet_id from targeted_refresh_all_family_timesheet_ids trf)
          )
  ;



  create temporary table manual_adjustment_carry_forward_scope on commit drop as
        select
          carry_forward_rows.id,
          carry_forward_rows.source_pay_batch_id,
          carry_forward_rows.source_pay_batch_item_id,
          carry_forward_rows.source_pay_bank_transfer_id,
          carry_forward_rows.source_pay_batch_candidate_id,
          carry_forward_rows.source_correction_request_id,
          carry_forward_rows.source_correction_work_item_id,
          carry_forward_rows.candidate_id,
          carry_forward_rows.umbrella_id,
          carry_forward_rows.client_id,
          carry_forward_rows.timesheet_id,
          carry_forward_rows.pay_channel,
          carry_forward_rows.adjustment_direction,
          carry_forward_rows.amount_ex_vat,
          carry_forward_rows.amount_vat,
          carry_forward_rows.amount_inc_vat,
          carry_forward_rows.amount_basis,
          carry_forward_rows.paye_treatment,
          carry_forward_rows.tax_treatment_json,
          carry_forward_rows.description,
          carry_forward_rows.reason,
          carry_forward_rows.source_ref,
          carry_forward_rows.source_operation_source_key,
          carry_forward_rows.source_snapshot_json,
          carry_forward_rows.status,
          carry_forward_rows.target_pay_batch_id,
          carry_forward_rows.target_pay_batch_item_id,
          carry_forward_rows.target_operation_source_key,
          carry_forward_rows.created_at_utc,
          carry_forward_rows.updated_at_utc,
          carry_forward_rows.reserved_at_utc,
          carry_forward_rows.consumed_at_utc,
          carry_forward_rows.released_at_utc,
          carry_forward_rows.cancelled_at_utc,
          carry_forward_rows.status_reason,
          COALESCE(source_batch_rows.execution_commit_ref, carry_forward_rows.source_pay_batch_id::text) AS source_batch_ref
        from public.pay_manual_adjustment_carry_forwards as carry_forward_rows
        left join public.pay_batches as source_batch_rows
          on source_batch_rows.id = carry_forward_rows.source_pay_batch_id
        where carry_forward_rows.candidate_id = v_candidate_id
          and upper(btrim(coalesce(carry_forward_rows.status, ''))) in ('PENDING_CARRY_FORWARD', 'RESERVED_IN_DRAFT')
          and upper(btrim(coalesce(carry_forward_rows.status, ''))) not in ('CONSUMED_IN_BATCH', 'CANCELLED', 'SUPERSEDED', 'NEEDS_REVIEW')
          and (
            (
              upper(btrim(coalesce(carry_forward_rows.status, ''))) = 'PENDING_CARRY_FORWARD'
              and carry_forward_rows.target_pay_batch_id is null
              and carry_forward_rows.target_pay_batch_item_id is null
              and nullif(btrim(coalesce(carry_forward_rows.target_operation_source_key, '')), '') is null
            )
            or (
              upper(btrim(coalesce(carry_forward_rows.status, ''))) = 'RESERVED_IN_DRAFT'
              and (
                (v_target_pay_batch_id is not null and carry_forward_rows.target_pay_batch_id = v_target_pay_batch_id)
                or (
                  v_target_operation_source_key is not null
                  and nullif(btrim(coalesce(carry_forward_rows.target_operation_source_key, '')), '') = v_target_operation_source_key
                )
              )
            )
          )
          and (
            (
              v_pay_channel_scope = 'ALL'
              and (
                v_candidate_pay_method is null
                or upper(btrim(coalesce(carry_forward_rows.pay_channel, ''))) = v_candidate_pay_method
              )
            )
            or (
              v_pay_channel_scope <> 'ALL'
              and upper(btrim(coalesce(carry_forward_rows.pay_channel, ''))) = v_pay_channel_scope
            )
          )
  ;

  v_source_build_collect_elapsed_ms := round((extract(epoch from (clock_timestamp() - v_source_build_collect_started_at)) * 1000.0)::numeric, 3);

  return jsonb_build_object(
    'candidate_id', v_candidate_id::text,
    'refresh_scope_kind', v_effective_refresh_scope_kind,
    'targeted_timesheet_ids', v_targeted_timesheet_ids_json,
    'linked_timesheet_ids', v_linked_timesheet_ids_json,
    'ts_baseline_count', (select count(*)::int from ts_baseline),
    'finance_case_scope_count', (select count(*)::int from finance_case_baseline_scope),
    'manual_adjustment_carry_forward_count', (select count(*)::int from manual_adjustment_carry_forward_scope),
    'active_snooze_count', (select count(*)::int from active_snoozes),
    'source_build_collect_diagnostics', jsonb_build_object(
      'source_build_mode', COALESCE(v_source_build_mode, false),
      'requested_refresh_scope_kind', COALESCE(v_source_build_requested_scope_kind, 'CANDIDATE_FULL_LIVE'),
      'actual_refresh_scope_kind', COALESCE(v_source_build_actual_scope_kind, v_effective_refresh_scope_kind),
      'targeted_payload_received', COALESCE(v_source_build_targeted_payload_received, false),
      'targeted_timesheet_count', jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)),
      'linked_timesheet_count', jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)),
      'candidate_filter_applied_early', COALESCE(v_source_build_candidate_filter_applied_early, false),
      'timesheet_filter_applied_early', COALESCE(v_source_build_timesheet_filter_applied_early, false),
      'fallback_used', COALESCE(v_source_build_fallback_used, false),
      'fallback_reason', v_source_build_fallback_reason,
      'source_page_limit', v_source_build_page_limit,
      'source_page_count', v_source_build_target_page_count,
      'source_remaining_after_cursor_count', v_source_build_target_total_count,
      'cursor_in', COALESCE(v_source_build_cursor_in_json, 'null'::jsonb),
      'cursor_out', COALESCE(v_source_build_cursor_out_json, 'null'::jsonb),
      'cursor_advanced', (v_source_build_next_timesheet_id IS NOT NULL),
      'has_more', COALESCE(v_source_build_has_more, false),
      'large_aggregation_avoided', COALESCE(v_source_build_large_aggregation_avoided, false),
      'collect_elapsed_ms', v_source_build_collect_elapsed_ms,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    )
    || jsonb_build_object(
      'lifecycle_reconciliation_mode', v_lifecycle_reconciliation_mode,
      'historic_metadata_allowed', v_historic_metadata_allowed,
      'signed_finance_reconciliation', v_signed_finance_reconciliation,
      'exclude_lifecycle_ineligible_current_payability', v_exclude_lifecycle_ineligible_current_payability,
      'authoritative_timesheet_scope', v_authoritative_timesheet_scope,
      'internal_reconciliation_authorised', v_internal_reconciliation_authorised
    )
  );
end;
$function$;

-- pay_preview(date,date,uuid,uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_preview(p_pay_date date, p_week_ending_cutoff date, p_actor_user_id uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_client_id uuid DEFAULT NULL::uuid, p_preview_decisions_json jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_context_json jsonb := '{}'::jsonb;
  v_scope_candidate_ids jsonb := '[]'::jsonb;
  v_candidate_rollups_json jsonb := '[]'::jsonb;
  v_scope_candidate_id_text text := '';
  v_candidate_baseline_json jsonb := '{}'::jsonb;
  v_candidate_effective_json jsonb := '{}'::jsonb;
  v_candidate_rollup_json jsonb := '{}'::jsonb;
begin
  v_context_json := public.pay_preview_build_context(
    p_pay_date => p_pay_date,
    p_week_ending_cutoff => p_week_ending_cutoff,
    p_actor_user_id => p_actor_user_id,
    p_candidate_id => p_candidate_id,
    p_client_id => p_client_id,
    p_preview_decisions_json => p_preview_decisions_json
  );

  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'pay_preview_build_context(...) must return a JSON object';
  end if;

  v_scope_candidate_ids := case
    when jsonb_typeof(v_context_json->'scope_candidate_ids') = 'array' then coalesce(v_context_json->'scope_candidate_ids', '[]'::jsonb)
    else '[]'::jsonb
  end;

  for v_scope_candidate_id_text in
    select btrim(scope_candidate.value)
    from jsonb_array_elements_text(v_scope_candidate_ids) as scope_candidate(value)
    where btrim(scope_candidate.value) <> ''
    order by btrim(scope_candidate.value)
  loop
    v_candidate_baseline_json := public.pay_preview_build_candidate_baseline(
      p_context_json => v_context_json,
      p_candidate_id => v_scope_candidate_id_text::uuid
    );

    v_candidate_effective_json := public.pay_preview_apply_candidate_overlay(
      p_candidate_baseline_json => v_candidate_baseline_json,
      p_case_resolutions_json => coalesce(v_context_json->'preview_case_resolutions', '{}'::jsonb),
      p_overrides_json => coalesce(v_context_json->'preview_decisions_json', '{}'::jsonb)
    );

    v_candidate_rollup_json := public.pay_preview_build_candidate_rollup(
      p_context_json => v_context_json,
      p_candidate_effective_json => v_candidate_effective_json
    );

    v_candidate_rollups_json := v_candidate_rollups_json || jsonb_build_array(v_candidate_rollup_json);
  end loop;

  return public.pay_preview_assemble_payload(
    p_context_json => v_context_json,
    p_candidate_rollups_json => v_candidate_rollups_json
  );
end;
$function$;

-- pay_provider_submit_chunk_diagnostic_finalise(uuid,uuid,uuid,uuid,text,jsonb)
CREATE OR REPLACE FUNCTION public.pay_provider_submit_chunk_diagnostic_finalise(p_operation_id uuid, p_pay_batch_id uuid DEFAULT NULL::uuid, p_chunk_id uuid DEFAULT NULL::uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_reason_code text DEFAULT NULL::text, p_failure_error_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_reason_code text := upper(btrim(coalesce(p_reason_code, 'PROVIDER_CHUNK_FINALISE')));
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_chunk_row public.banking_pay_operation_chunks%ROWTYPE;
  v_effective_pay_batch_id uuid := NULL::uuid;
  v_scope_count integer := 0;
  v_transfer_count integer := 0;
  v_accepted_count integer := 0;
  v_rejected_count integer := 0;
  v_unknown_count integer := 0;
  v_review_required_count integer := 0;
  v_remaining_running_count integer := 0;
  v_provider_message text := NULL::text;
  v_chunk_finish_status text := 'COMPLETE';
  v_manual_review_required boolean := false;
  v_transfer_scope_ids jsonb := '[]'::jsonb;
  v_result_json jsonb := '{}'::jsonb;
  v_error_json jsonb := '{}'::jsonb;
BEGIN
  PERFORM set_config('lock_timeout', '3s', true);
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PROVIDER_CHUNK_FINALISE_OPERATION_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_CHUNK_FINALISE_OPERATION_ID_REQUIRED')::text;
  END IF;

  IF p_chunk_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PROVIDER_CHUNK_FINALISE_CHUNK_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_CHUNK_FINALISE_CHUNK_ID_REQUIRED', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF p_failure_error_json IS NOT NULL AND jsonb_typeof(p_failure_error_json) <> 'object' THEN
    RAISE EXCEPTION 'PAY_PROVIDER_CHUNK_FINALISE_ERROR_JSON_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_CHUNK_FINALISE_ERROR_JSON_MUST_BE_OBJECT')::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_PROVIDER_CHUNK_FINALISE_OPERATION_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_CHUNK_FINALISE_OPERATION_NOT_FOUND', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF upper(btrim(coalesce(v_operation_row.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION 'PAY_PROVIDER_CHUNK_FINALISE_OPERATION_TYPE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_CHUNK_FINALISE_OPERATION_TYPE_INVALID', 'operation_id', p_operation_id::text, 'operation_type', v_operation_row.operation_type)::text;
  END IF;

  v_effective_pay_batch_id := coalesce(p_pay_batch_id, v_operation_row.pay_batch_id);

  IF v_effective_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PROVIDER_CHUNK_FINALISE_PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_CHUNK_FINALISE_PAY_BATCH_ID_REQUIRED', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> v_effective_pay_batch_id THEN
    RAISE EXCEPTION 'PAY_PROVIDER_CHUNK_FINALISE_OPERATION_BATCH_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_CHUNK_FINALISE_OPERATION_BATCH_MISMATCH', 'operation_id', p_operation_id::text, 'pay_batch_id', v_effective_pay_batch_id::text, 'operation_pay_batch_id', v_operation_row.pay_batch_id::text)::text;
  END IF;

  SELECT chunk_row.*
  INTO v_chunk_row
  FROM public.banking_pay_operation_chunks AS chunk_row
  WHERE chunk_row.id = p_chunk_id
    AND chunk_row.operation_id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_PROVIDER_CHUNK_FINALISE_CHUNK_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_CHUNK_FINALISE_CHUNK_NOT_FOUND', 'operation_id', p_operation_id::text, 'chunk_id', p_chunk_id::text)::text;
  END IF;

  IF NOT (upper(btrim(coalesce(v_chunk_row.phase, ''))) = 'SUBMIT_PROVIDER_TRANSFERS' OR upper(btrim(coalesce(v_chunk_row.chunk_type, ''))) = 'TRANSFER_SUBMIT') THEN
    RAISE EXCEPTION 'PAY_PROVIDER_CHUNK_FINALISE_NOT_PROVIDER_SUBMIT_CHUNK'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_CHUNK_FINALISE_NOT_PROVIDER_SUBMIT_CHUNK', 'operation_id', p_operation_id::text, 'chunk_id', p_chunk_id::text, 'phase', v_chunk_row.phase, 'chunk_type', v_chunk_row.chunk_type)::text;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_provider_finalise_scope;
  CREATE TEMPORARY TABLE pg_temp.tmp_provider_finalise_scope ON COMMIT DROP AS
  SELECT scope_row.id AS transfer_scope_id,
         scope_row.pay_bank_transfer_id,
         upper(btrim(coalesce(scope_row.provider_submit_state, ''))) AS provider_submit_state,
         coalesce(scope_row.provider_review_required, false) AS provider_review_required,
         scope_row.provider_unsafe_reason,
         upper(btrim(coalesce(scope_row.status, ''))) AS scope_status
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = v_effective_pay_batch_id
    AND scope_row.provider_submit_chunk_id = p_chunk_id
  FOR UPDATE;

  SELECT count(*)::integer,
         count(*) FILTER (WHERE finalise_scope.pay_bank_transfer_id IS NOT NULL)::integer,
         count(*) FILTER (WHERE finalise_scope.provider_submit_state IN ('PROVIDER_ACCEPTED', 'CHUNK_FINALISED') OR finalise_scope.scope_status IN ('SUBMITTED', 'COMPLETED'))::integer,
         count(*) FILTER (WHERE finalise_scope.provider_submit_state = 'PROVIDER_REJECTED')::integer,
         count(*) FILTER (WHERE finalise_scope.provider_submit_state = 'PROVIDER_UNKNOWN')::integer,
         count(*) FILTER (WHERE finalise_scope.provider_review_required IS TRUE OR finalise_scope.provider_submit_state = 'REVIEW_REQUIRED')::integer,
         coalesce(jsonb_agg(to_jsonb(finalise_scope.transfer_scope_id::text) ORDER BY finalise_scope.transfer_scope_id), '[]'::jsonb)
  INTO v_scope_count,
       v_transfer_count,
       v_accepted_count,
       v_rejected_count,
       v_unknown_count,
       v_review_required_count,
       v_transfer_scope_ids
  FROM pg_temp.tmp_provider_finalise_scope AS finalise_scope;

  IF coalesce(v_scope_count, 0) <= 0 THEN
    RAISE EXCEPTION 'PAY_PROVIDER_CHUNK_FINALISE_NO_SCOPE_FOR_CHUNK'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_CHUNK_FINALISE_NO_SCOPE_FOR_CHUNK', 'operation_id', p_operation_id::text, 'chunk_id', p_chunk_id::text)::text;
  END IF;

  v_manual_review_required := coalesce(v_review_required_count, 0) > 0 OR coalesce(v_unknown_count, 0) > 0;
  v_provider_message := nullif(btrim(coalesce(
    p_failure_error_json->>'message',
    p_failure_error_json->>'provider_error_message_redacted',
    v_chunk_row.result_json->>'message',
    v_chunk_row.error_json->>'message',
    NULL::text
  )), '');

  IF coalesce(v_rejected_count, 0) > 0 OR coalesce(v_unknown_count, 0) > 0 OR coalesce(v_review_required_count, 0) > 0 THEN
    v_chunk_finish_status := 'FAILED';
  ELSE
    v_chunk_finish_status := 'COMPLETE';
  END IF;

  v_result_json := jsonb_strip_nulls(
    coalesce(v_chunk_row.result_json, '{}'::jsonb)
    || jsonb_build_object(
      'provider_chunk_finalised', true,
      'provider_chunk_finalised_at_utc', v_now::text,
      'provider_chunk_finalise_reason_code', v_reason_code,
      'transfer_scope_count', coalesce(v_scope_count, 0),
      'transfer_count', coalesce(v_transfer_count, 0),
      'accepted_count', coalesce(v_accepted_count, 0),
      'rejected_count', coalesce(v_rejected_count, 0),
      'unknown_count', coalesce(v_unknown_count, 0),
      'review_required_count', coalesce(v_review_required_count, 0),
      'last_provider_message', v_provider_message
    )
  );

  v_error_json := CASE
    WHEN v_chunk_finish_status = 'FAILED' THEN jsonb_strip_nulls(
      coalesce(v_chunk_row.error_json, '{}'::jsonb)
      || jsonb_build_object(
        'code', CASE WHEN v_manual_review_required THEN 'PROVIDER_CHUNK_REVIEW_REQUIRED' ELSE 'PROVIDER_CHUNK_REJECTED' END,
        'message', coalesce(v_provider_message, 'Provider chunk requires review or failed outcome handling.'),
        'provider_chunk_finalised_at_utc', v_now::text,
        'provider_chunk_finalise_reason_code', v_reason_code,
        'failure_error_json', coalesce(p_failure_error_json, '{}'::jsonb)
      )
    )
    ELSE v_chunk_row.error_json
  END;

  UPDATE public.banking_pay_operation_chunks AS chunk_update
  SET status = v_chunk_finish_status,
      result_json = v_result_json,
      error_json = v_error_json,
      completed_count = CASE WHEN v_chunk_finish_status = 'COMPLETE' THEN greatest(coalesce(chunk_update.completed_count, 0), coalesce(v_transfer_count, chunk_update.unit_count, 0)) ELSE coalesce(chunk_update.completed_count, 0) END,
      failed_count = CASE WHEN v_chunk_finish_status = 'FAILED' THEN greatest(coalesce(chunk_update.failed_count, 0), greatest(coalesce(v_rejected_count, 0) + coalesce(v_unknown_count, 0) + coalesce(v_review_required_count, 0), 1)) ELSE coalesce(chunk_update.failed_count, 0) END,
      completed_at_utc = coalesce(chunk_update.completed_at_utc, v_now),
      updated_at_utc = v_now
  WHERE chunk_update.id = p_chunk_id
    AND chunk_update.operation_id = p_operation_id;

  IF v_chunk_finish_status = 'FAILED' OR v_manual_review_required THEN
    UPDATE public.banking_pay_operation_transfer_scope AS scope_update
    SET provider_review_required = true,
        provider_submit_ready = false,
        provider_submit_state = CASE
          WHEN upper(btrim(coalesce(scope_update.provider_submit_state, ''))) IN ('PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED') THEN scope_update.provider_submit_state
          ELSE 'REVIEW_REQUIRED'
        END,
        provider_unsafe_reason = coalesce(nullif(btrim(scope_update.provider_unsafe_reason), ''), CASE WHEN coalesce(v_unknown_count, 0) > 0 THEN 'PROVIDER_UNKNOWN' ELSE 'PROVIDER_CHUNK_FINALISE_FAILED' END),
        updated_at_utc = v_now
    WHERE scope_update.id IN (SELECT finalise_scope.transfer_scope_id FROM pg_temp.tmp_provider_finalise_scope AS finalise_scope)
      AND scope_update.operation_id = p_operation_id;

    UPDATE public.banking_pay_operations AS operation_update
    SET status = 'REVIEW_REQUIRED',
        runner_state = 'REVIEW_REQUIRED',
        requires_user_action = true,
        resume_reason = coalesce(nullif(btrim(operation_update.resume_reason), ''), 'PROVIDER_CHUNK_REVIEW_REQUIRED'),
        progress_json = jsonb_strip_nulls(coalesce(operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
          'last_provider_chunk_finalised_at_utc', v_now::text,
          'last_provider_chunk_id', p_chunk_id::text,
          'last_provider_chunk_status', v_chunk_finish_status,
          'last_provider_message', v_provider_message,
          'provider_review_required', true
        )),
        updated_at_utc = v_now
    WHERE operation_update.id = p_operation_id;
  ELSE
    UPDATE public.banking_pay_operation_transfer_scope AS scope_update
    SET provider_submit_state = CASE WHEN upper(btrim(coalesce(scope_update.provider_submit_state, ''))) = 'PROVIDER_ACCEPTED' THEN 'CHUNK_FINALISED' ELSE scope_update.provider_submit_state END,
        updated_at_utc = v_now
    WHERE scope_update.id IN (SELECT finalise_scope.transfer_scope_id FROM pg_temp.tmp_provider_finalise_scope AS finalise_scope)
      AND scope_update.operation_id = p_operation_id;

    SELECT count(*)::integer
    INTO v_remaining_running_count
    FROM public.banking_pay_operation_chunks AS remaining_chunk
    WHERE remaining_chunk.operation_id = p_operation_id
      AND (remaining_chunk.phase = 'SUBMIT_PROVIDER_TRANSFERS' OR remaining_chunk.chunk_type = 'TRANSFER_SUBMIT')
      AND upper(btrim(coalesce(remaining_chunk.status, ''))) IN ('PENDING', 'RUNNING');

    UPDATE public.banking_pay_operations AS operation_update
    SET runner_state = CASE WHEN coalesce(v_remaining_running_count, 0) > 0 THEN operation_update.runner_state ELSE 'RUNNABLE' END,
        run_after_utc = CASE WHEN coalesce(v_remaining_running_count, 0) > 0 THEN operation_update.run_after_utc ELSE v_now END,
        progress_json = jsonb_strip_nulls(coalesce(operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
          'last_provider_chunk_finalised_at_utc', v_now::text,
          'last_provider_chunk_id', p_chunk_id::text,
          'last_provider_chunk_status', v_chunk_finish_status,
          'remaining_provider_submit_chunk_count', coalesce(v_remaining_running_count, 0)
        )),
        updated_at_utc = v_now
    WHERE operation_update.id = p_operation_id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', v_effective_pay_batch_id::text,
    'chunk_id', p_chunk_id::text,
    'finalised_chunk_count', 1,
    'finalised_chunk_ids', jsonb_build_array(p_chunk_id::text),
    'chunk_status', v_chunk_finish_status,
    'provider_submit_diagnostic_used', false,
    'operation_wide_finalise', false,
    'transfer_scope_ids', coalesce(v_transfer_scope_ids, '[]'::jsonb),
    'transfer_scope_count', coalesce(v_scope_count, 0),
    'transfer_count', coalesce(v_transfer_count, 0),
    'accepted_count', coalesce(v_accepted_count, 0),
    'rejected_count', coalesce(v_rejected_count, 0),
    'unknown_count', coalesce(v_unknown_count, 0),
    'review_required_count', coalesce(v_review_required_count, 0),
    'manual_resolution_required', coalesce(v_manual_review_required, false),
    'last_provider_message', v_provider_message,
    'reason_code', v_reason_code,
    'server_utc', v_now::text
  );
END;
$function$;

-- pay_provider_submit_chunk_stage_record(uuid,uuid,uuid,jsonb,text,jsonb,uuid)
CREATE OR REPLACE FUNCTION public.pay_provider_submit_chunk_stage_record(p_operation_id uuid, p_pay_batch_id uuid, p_chunk_id uuid, p_transfer_ids jsonb DEFAULT '[]'::jsonb, p_stage text DEFAULT NULL::text, p_provider_submit_diagnostic jsonb DEFAULT '{}'::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_stage text := upper(btrim(coalesce(p_stage, p_provider_submit_diagnostic->>'stage', p_provider_submit_diagnostic->>'provider_call_stage', '')));
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_chunk_row public.banking_pay_operation_chunks%ROWTYPE;
  v_diag jsonb := '{}'::jsonb;
  v_transfer_scope_ids_json jsonb := '[]'::jsonb;
  v_scope_count integer := 0;
  v_transfer_count integer := 0;
  v_new_chunk_status text := 'RUNNING';
  v_scope_provider_state text := NULL::text;
  v_transfer_rail_state text := NULL::text;
  v_provider_transaction_id text := NULL::text;
  v_request_id text := NULL::text;
  v_idempotency_key text := NULL::text;
  v_provider_error_json jsonb := NULL::jsonb;
  v_provider_response_json jsonb := NULL::jsonb;
  v_attempt_state text := NULL::text;
  v_attempt_rows integer := 0;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_OPERATION_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_OPERATION_ID_REQUIRED')::text;
  END IF;

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_PAY_BATCH_ID_REQUIRED', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF p_chunk_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_CHUNK_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_CHUNK_ID_REQUIRED', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF p_provider_submit_diagnostic IS NOT NULL AND jsonb_typeof(p_provider_submit_diagnostic) <> 'object' THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_DIAGNOSTIC_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_DIAGNOSTIC_MUST_BE_OBJECT', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF v_stage IS NULL OR v_stage = '' THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_REQUIRED', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF v_stage NOT IN (
    'CLAIMED',
    'REQUEST_PREPARING',
    'REQUEST_SENDING',
    'REQUEST_SENT_LOCAL',
    'PROVIDER_ACCEPTED',
    'PROVIDER_REJECTED',
    'PROVIDER_UNKNOWN',
    'REVIEW_REQUIRED',
    'CHUNK_FINALISED'
  ) THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_INVALID', 'operation_id', p_operation_id::text, 'stage', v_stage)::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_OPERATION_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_OPERATION_NOT_FOUND', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF upper(btrim(coalesce(v_operation_row.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_OPERATION_TYPE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_OPERATION_TYPE_INVALID', 'operation_id', p_operation_id::text, 'operation_type', v_operation_row.operation_type)::text;
  END IF;

  IF v_operation_row.pay_batch_id IS NULL OR v_operation_row.pay_batch_id <> p_pay_batch_id THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_OPERATION_BATCH_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_OPERATION_BATCH_MISMATCH', 'operation_id', p_operation_id::text, 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  SELECT chunk_row.*
  INTO v_chunk_row
  FROM public.banking_pay_operation_chunks AS chunk_row
  WHERE chunk_row.id = p_chunk_id
    AND chunk_row.operation_id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_CHUNK_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_CHUNK_NOT_FOUND', 'chunk_id', p_chunk_id::text)::text;
  END IF;

  IF NOT (upper(btrim(coalesce(v_chunk_row.phase, ''))) = 'SUBMIT_PROVIDER_TRANSFERS' OR upper(btrim(coalesce(v_chunk_row.chunk_type, ''))) = 'TRANSFER_SUBMIT') THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_NOT_TRANSFER_SUBMIT_CHUNK'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_NOT_TRANSFER_SUBMIT_CHUNK', 'chunk_id', p_chunk_id::text, 'phase', v_chunk_row.phase, 'chunk_type', v_chunk_row.chunk_type)::text;
  END IF;

  v_diag := coalesce(p_provider_submit_diagnostic, '{}'::jsonb)
    - 'access_token'
    - 'authorization'
    - 'Authorization'
    - 'bearer_token'
    - 'token'
    - 'account_number'
    - 'sort_code'
    - 'iban'
    - 'source_account_number'
    - 'beneficiary_account_number';

  DROP TABLE IF EXISTS pg_temp.tmp_provider_stage_scope;
  CREATE TEMPORARY TABLE pg_temp.tmp_provider_stage_scope ON COMMIT DROP AS
  SELECT scope_row.id AS transfer_scope_id,
         scope_row.pay_bank_transfer_id,
         scope_row.provider_submit_state AS previous_state,
         COALESCE(NULLIF(BTRIM(scope_row.provider_idempotency_key), ''), NULLIF(BTRIM(transfer_row.request_id), ''), 'scope:' || scope_row.id::text) AS provider_idempotency_key,
         COALESCE(NULLIF(BTRIM(scope_row.provider_request_id), ''), NULLIF(BTRIM(transfer_row.request_id), '')) AS provider_request_id
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  JOIN public.pay_bank_transfers AS transfer_row
    ON transfer_row.id = scope_row.pay_bank_transfer_id
   AND transfer_row.pay_batch_id = scope_row.pay_batch_id
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = p_pay_batch_id
    AND scope_row.provider_submit_chunk_id = p_chunk_id
  FOR UPDATE OF scope_row, transfer_row;

  SELECT count(*)::integer,
         count(*) FILTER (WHERE stage_scope.pay_bank_transfer_id IS NOT NULL)::integer,
         coalesce(jsonb_agg(to_jsonb(stage_scope.transfer_scope_id::text) ORDER BY stage_scope.transfer_scope_id), '[]'::jsonb)
  INTO v_scope_count,
       v_transfer_count,
       v_transfer_scope_ids_json
  FROM pg_temp.tmp_provider_stage_scope AS stage_scope;

  IF coalesce(v_scope_count, 0) <= 0 THEN
    RAISE EXCEPTION 'PAY_PROVIDER_STAGE_NO_SCOPE_FOR_CHUNK'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PROVIDER_STAGE_NO_SCOPE_FOR_CHUNK', 'operation_id', p_operation_id::text, 'chunk_id', p_chunk_id::text)::text;
  END IF;

  v_provider_transaction_id := nullif(btrim(coalesce(v_diag->>'provider_transaction_id', v_diag->>'provider_payment_id', v_diag->>'rail_tx_id', '')), '');
  v_request_id := nullif(btrim(coalesce(v_diag->>'request_id', v_diag->>'local_provider_request_id', '')), '');
  v_idempotency_key := nullif(btrim(coalesce(v_diag->>'idempotency_key', v_request_id, '')), '');
  v_provider_response_json := CASE WHEN jsonb_typeof(v_diag->'provider_response_redacted') = 'object' THEN v_diag->'provider_response_redacted' ELSE NULL::jsonb END;
  v_provider_error_json := CASE WHEN jsonb_typeof(v_diag->'provider_error_redacted') = 'object' THEN v_diag->'provider_error_redacted' ELSE NULL::jsonb END;

  v_scope_provider_state := v_stage;
  v_transfer_rail_state := CASE v_stage
    WHEN 'PROVIDER_ACCEPTED' THEN 'ACCEPTED'
    WHEN 'PROVIDER_REJECTED' THEN 'REJECTED'
    WHEN 'PROVIDER_UNKNOWN' THEN 'UNKNOWN'
    WHEN 'REQUEST_SENT_LOCAL' THEN 'REQUEST_SENT_LOCAL'
    WHEN 'REQUEST_SENDING' THEN 'REQUEST_SENDING'
    ELSE NULL::text
  END;

  v_new_chunk_status := CASE
    WHEN v_stage IN ('PROVIDER_ACCEPTED', 'PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED', 'CHUNK_FINALISED') THEN 'COMPLETE'
    ELSE 'RUNNING'
  END;

  UPDATE public.banking_pay_operation_transfer_scope AS scope_update
  SET provider_submit_state = v_scope_provider_state,
      provider_submit_ready = false,
      provider_review_required = v_stage IN ('PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED'),
      provider_unsafe_reason = CASE
        WHEN v_stage = 'PROVIDER_REJECTED' THEN 'PROVIDER_REJECTED'
        WHEN v_stage = 'PROVIDER_UNKNOWN' THEN 'PROVIDER_UNKNOWN'
        WHEN v_stage = 'REVIEW_REQUIRED' THEN coalesce(nullif(btrim(v_diag->>'review_reason_code'), ''), 'REVIEW_REQUIRED')
        ELSE NULL::text
      END,
      provider_idempotency_key = COALESCE(v_idempotency_key, scope_update.provider_idempotency_key),
      provider_request_id = COALESCE(v_request_id, scope_update.provider_request_id),
      provider_transaction_id = CASE WHEN v_stage = 'PROVIDER_ACCEPTED' THEN COALESCE(v_provider_transaction_id, scope_update.provider_transaction_id) ELSE scope_update.provider_transaction_id END,
      provider_request_prepared_at_utc = CASE WHEN v_stage = 'REQUEST_PREPARING' THEN COALESCE(scope_update.provider_request_prepared_at_utc, v_now) ELSE scope_update.provider_request_prepared_at_utc END,
      provider_request_sending_at_utc = CASE WHEN v_stage = 'REQUEST_SENDING' THEN COALESCE(scope_update.provider_request_sending_at_utc, v_now) ELSE scope_update.provider_request_sending_at_utc END,
      provider_request_sent_at_utc = CASE WHEN v_stage IN ('REQUEST_SENT_LOCAL', 'PROVIDER_ACCEPTED', 'PROVIDER_REJECTED', 'PROVIDER_UNKNOWN') THEN COALESCE(scope_update.provider_request_sent_at_utc, v_now) ELSE scope_update.provider_request_sent_at_utc END,
      provider_response_at_utc = CASE WHEN v_stage IN ('PROVIDER_ACCEPTED', 'PROVIDER_REJECTED', 'PROVIDER_UNKNOWN') THEN COALESCE(scope_update.provider_response_at_utc, v_now) ELSE scope_update.provider_response_at_utc END,
      provider_submission_status = v_stage,
      status = CASE
        WHEN v_stage = 'PROVIDER_ACCEPTED' THEN 'SUBMITTED'
        WHEN v_stage IN ('PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED') THEN 'FAILED'
        ELSE scope_update.status
      END,
      updated_at_utc = v_now
  WHERE scope_update.id IN (SELECT stage_scope.transfer_scope_id FROM pg_temp.tmp_provider_stage_scope AS stage_scope);

  UPDATE public.pay_bank_transfers AS transfer_update
  SET request_id = coalesce(nullif(btrim(transfer_update.request_id), ''), v_request_id),
      rail_tx_id = CASE WHEN v_stage = 'PROVIDER_ACCEPTED' THEN coalesce(nullif(btrim(transfer_update.rail_tx_id), ''), v_provider_transaction_id) ELSE transfer_update.rail_tx_id END,
      rail_state = coalesce(v_transfer_rail_state, transfer_update.rail_state),
      rail_meta_json = jsonb_strip_nulls(coalesce(transfer_update.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
        'provider_stage', v_stage,
        'provider_stage_recorded_at_utc', v_now::text,
        'provider_transaction_id_present', v_provider_transaction_id IS NOT NULL,
        'request_id_present', v_request_id IS NOT NULL,
        'operation_id', p_operation_id::text,
        'chunk_id', p_chunk_id::text
      )),
      failed_reason = CASE WHEN v_stage = 'PROVIDER_REJECTED' THEN coalesce(nullif(btrim(v_diag->>'provider_error_message_redacted'), ''), 'PROVIDER_REJECTED') ELSE transfer_update.failed_reason END
  FROM pg_temp.tmp_provider_stage_scope AS stage_scope
  WHERE transfer_update.id = stage_scope.pay_bank_transfer_id
    AND transfer_update.pay_batch_id = p_pay_batch_id;

  UPDATE public.banking_pay_operation_chunks AS chunk_update
  SET status = v_new_chunk_status,
      result_json = jsonb_strip_nulls(coalesce(chunk_update.result_json, '{}'::jsonb) || jsonb_build_object(
        'provider_stage', v_stage,
        'provider_stage_recorded_at_utc', v_now::text,
        'provider_submission_status', v_scope_provider_state,
        'transfer_scope_ids', coalesce(v_transfer_scope_ids_json, '[]'::jsonb),
        'provider_request_sent', v_stage IN ('REQUEST_SENT_LOCAL', 'PROVIDER_ACCEPTED', 'PROVIDER_REJECTED', 'PROVIDER_UNKNOWN'),
        'provider_response_present', v_stage IN ('PROVIDER_ACCEPTED', 'PROVIDER_REJECTED', 'PROVIDER_UNKNOWN'),
        'provider_transaction_id_present', v_provider_transaction_id IS NOT NULL,
        'request_id_present', v_request_id IS NOT NULL
      )),
      completed_count = CASE WHEN v_new_chunk_status = 'COMPLETE' AND v_stage = 'PROVIDER_ACCEPTED' THEN coalesce(chunk_update.unit_count, v_scope_count, 0) ELSE chunk_update.completed_count END,
      failed_count = CASE WHEN v_stage IN ('PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED') THEN coalesce(chunk_update.unit_count, v_scope_count, 0) ELSE chunk_update.failed_count END,
      completed_at_utc = CASE WHEN v_new_chunk_status = 'COMPLETE' THEN coalesce(chunk_update.completed_at_utc, v_now) ELSE chunk_update.completed_at_utc END,
      updated_at_utc = v_now
  WHERE chunk_update.id = p_chunk_id
    AND chunk_update.operation_id = p_operation_id;

  UPDATE public.banking_pay_operations AS operation_update
  SET status = CASE WHEN v_stage IN ('PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED') THEN 'REVIEW_REQUIRED' ELSE operation_update.status END,
      runner_state = CASE WHEN v_stage IN ('PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED') THEN 'REVIEW_REQUIRED' ELSE operation_update.runner_state END,
      requires_user_action = CASE WHEN v_stage IN ('PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED') THEN true ELSE operation_update.requires_user_action END,
      resume_reason = CASE WHEN v_stage IN ('PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED') THEN 'PROVIDER_SUBMIT_REVIEW_REQUIRED' ELSE operation_update.resume_reason END,
      progress_json = jsonb_strip_nulls(coalesce(operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
        'provider_submit_stage_last_recorded', v_stage,
        'provider_submit_stage_last_recorded_at_utc', v_now::text,
        'last_provider_submit_chunk_id', p_chunk_id::text,
        'provider_submission_status', v_scope_provider_state,
        'transfer_scope_count', coalesce(v_scope_count, 0)
      )),
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  v_attempt_state := CASE
    WHEN v_stage = 'PROVIDER_ACCEPTED' THEN 'PROVIDER_ACCEPTED'
    WHEN v_stage = 'PROVIDER_REJECTED' THEN 'PROVIDER_REJECTED'
    WHEN v_stage IN ('PROVIDER_UNKNOWN', 'REVIEW_REQUIRED') THEN 'PROVIDER_UNKNOWN'
    ELSE v_stage
  END;

  SELECT count(*)::integer
  INTO v_attempt_rows
  FROM (
    SELECT public.banking_pay_operation_provider_attempt_record(
      p_operation_id => p_operation_id,
      p_pay_batch_id => p_pay_batch_id,
      p_transfer_scope_id => stage_scope.transfer_scope_id,
      p_provider_chunk_id => p_chunk_id,
      p_idempotency_key => COALESCE(v_idempotency_key, stage_scope.provider_idempotency_key),
      p_request_id => COALESCE(v_request_id, stage_scope.provider_request_id),
      p_provider_transaction_id => v_provider_transaction_id,
      p_previous_state => stage_scope.previous_state,
      p_new_state => v_attempt_state,
      p_lease_owner => v_chunk_row.locked_by,
      p_request_json => NULL::jsonb,
      p_response_json => v_provider_response_json,
      p_error_json => v_provider_error_json,
      p_actor_user_id => p_actor_user_id
    ) AS attempt_result
    FROM pg_temp.tmp_provider_stage_scope AS stage_scope
  ) AS attempt_calls;

  RETURN jsonb_build_object(
    'ok', true,
    'recorded', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', p_pay_batch_id::text,
    'chunk_id', p_chunk_id::text,
    'stage', v_stage,
    'transfer_scope_ids', coalesce(v_transfer_scope_ids_json, '[]'::jsonb),
    'transfer_scope_count', coalesce(v_scope_count, 0),
    'transfer_count', coalesce(v_transfer_count, 0),
    'attempt_rows_recorded', coalesce(v_attempt_rows, 0),
    'legacy_transfer_ids_ignored', p_transfer_ids IS NOT NULL AND jsonb_typeof(p_transfer_ids) = 'array' AND jsonb_array_length(p_transfer_ids) > 0,
    'provider_submission_status', v_scope_provider_state,
    'provider_transaction_id_present', v_provider_transaction_id IS NOT NULL,
    'request_id_present', v_request_id IS NOT NULL,
    'recorded_at_utc', v_now::text
  );
END;
$function$;

-- pay_provider_submit_diagnostic_get(uuid,uuid,uuid,uuid,boolean,text)
CREATE OR REPLACE FUNCTION public.pay_provider_submit_diagnostic_get(p_pay_batch_id uuid DEFAULT NULL::uuid, p_operation_id uuid DEFAULT NULL::uuid, p_transfer_id uuid DEFAULT NULL::uuid, p_chunk_id uuid DEFAULT NULL::uuid, p_counts_only boolean DEFAULT false, p_provider_diagnostic_context text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_uuid_regex text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_effective_pay_batch_id uuid := p_pay_batch_id;
  v_batch_id_from_scope uuid := NULL::uuid;
  v_operation_count integer := 0;
  v_chunk_count integer := 0;
  v_transfer_count integer := 0;
  v_active_auth_request_count integer := 0;
  v_provider_acceptance_evidence_count integer := 0;
  v_provider_response_present_count integer := 0;
  v_provider_request_sent_count integer := 0;
  v_provider_submission_unknown_count integer := 0;
  v_stale_empty_submit_chunk_count integer := 0;
  v_stale_unresolved_submit_chunk_count integer := 0;
  v_request_sent_no_response_count integer := 0;
  v_unfinalised_submit_chunk_count integer := 0;
  v_provider_submission_rejected_count integer := 0;
  v_provider_submission_accepted_count integer := 0;
  v_provider_submission_blocked_pre_call_count integer := 0;
  v_provider_submission_malformed_response_count integer := 0;
  v_mixed_provider_submit_outcome boolean := false;
  v_payment_provider_review_required boolean := false;
  v_provider_submit_actual_context boolean := false;
  v_operation_review_required boolean := false;
  v_provider_submission_status text := 'NO_PROVIDER_SUBMISSION_ATTEMPTED';
  v_review_reason_code text := 'NO_PROVIDER_SUBMIT_ATTEMPT';
  v_provider_call_stage text := 'NO_PROVIDER_SUBMIT_ATTEMPT';
  v_provider_submission_attempted boolean := false;
  v_provider_request_sent boolean := false;
  v_provider_response_received boolean := false;
  v_provider_response_present boolean := false;
  v_provider_submission_accepted boolean := false;
  v_provider_submission_rejected boolean := false;
  v_provider_submission_failed boolean := false;
  v_provider_submission_unknown boolean := false;
  v_provider_acceptance_evidence_present boolean := false;
  v_stale_submit_chunk boolean := false;
  v_unfinalised_submit_chunk boolean := false;
  v_chunk_lock_expired boolean := false;
  v_manual_resolution_required boolean := false;
  v_safe_retry_available boolean := false;
  v_automatic_retry_blocked boolean := false;
  v_retry_blocked_reason text := NULL::text;
  v_recommended_action text := 'No provider submission attempt has been recorded for this scope.';
  v_operation_ids jsonb := '[]'::jsonb;
  v_current_operation_ids jsonb := '[]'::jsonb;
  v_related_operation_ids jsonb := '[]'::jsonb;
  v_diagnostic_operation_id text := NULL::text;
  v_chunk_ids jsonb := '[]'::jsonb;
  v_transfer_ids jsonb := '[]'::jsonb;
  v_transfer_scope_ids jsonb := '[]'::jsonb;
  v_auth_request_ids jsonb := '[]'::jsonb;
  v_primary_operation_id text := NULL::text;
  v_primary_chunk_id text := NULL::text;
  v_primary_transfer_id text := NULL::text;
  v_primary_transfer_scope_id text := NULL::text;
  v_primary_auth_request_id text := NULL::text;
  v_primary_rail_provider text := NULL::text;
  v_primary_rail_env text := NULL::text;
  v_primary_rail_tx_id text := NULL::text;
  v_primary_rail_state text := NULL::text;
  v_primary_provider_transaction_id text := NULL::text;
  v_primary_provider_reference text := NULL::text;
  v_primary_provider_state text := NULL::text;
  v_primary_request_id text := NULL::text;
  v_primary_idempotency_key text := NULL::text;
  v_primary_local_provider_request_id text := NULL::text;
  v_primary_provider_http_status text := NULL::text;
  v_primary_provider_error_code text := NULL::text;
  v_primary_provider_error_message_redacted text := NULL::text;
  v_primary_provider_response_redacted jsonb := NULL::jsonb;
  v_primary_provider_error_redacted jsonb := NULL::jsonb;
  v_chunk_started_at_utc text := NULL::text;
  v_chunk_completed_at_utc text := NULL::text;
  v_chunk_lock_expires_at_utc text := NULL::text;
  v_provider_submit_diagnostic jsonb := '{}'::jsonb;
  v_counts jsonb := '{}'::jsonb;
  v_ids jsonb := '{}'::jsonb;
  v_batch_level_cleaned_local_blocked_pre_call_neutralised boolean := false;
  v_provider_diagnostic_context text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_provider_diagnostic_context, '')), ''), '-', '_'));
BEGIN
  IF p_pay_batch_id IS NULL AND p_operation_id IS NULL AND p_transfer_id IS NULL AND p_chunk_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
      'code', 'IDENTIFIER_REQUIRED',
      'message', 'pay_provider_submit_diagnostic_get: at least one identifier is required'
    )::text USING ERRCODE = 'P0001';
  END IF;


  IF v_provider_diagnostic_context IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
      'code', 'PROVIDER_DIAGNOSTIC_CONTEXT_REQUIRED',
      'message', 'pay_provider_submit_diagnostic_get requires an explicit provider diagnostic context.'
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_provider_diagnostic_context IN (
    'PROVIDER_STAGE_RECORD',
    'PAY_PROVIDER_SUBMIT_CHUNK_STAGE_RECORD',
    'PROVIDER_SUBMIT_STAGE_RECORD',
    'OPERATION_GET',
    'BATCH_LIST',
    'PAY_BATCHES_LIST',
    'LIST',
    'BOOTSTRAP',
    'BATCH_BOOTSTRAP',
    'PAY_BATCH_GET_BOOTSTRAP_ONLY',
    'OVERVIEW',
    'BATCH_OVERVIEW',
    'PREVIEW_OPEN',
    'PROGRESS_POLLING',
    'OPERATION_PROGRESS',
    'EXECUTION_HOT_PATH',
    'EXECUTION_WORKER',
    'OPERATION_WORKER',
    'PROVIDER_SUBMIT_CHUNK',
    'PROVIDER_SUBMIT_STAGE',
    'OPERATION_ADVANCE',
    'PAY_EXECUTE_BANK'
  ) THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
      'code', 'PROVIDER_DIAGNOSTIC_CONTEXT_NOT_ALLOWED',
      'context', v_provider_diagnostic_context,
      'message', 'Provider submit diagnostics are blocked from provider stage record, operation GET/progress, list, bootstrap, Overview, preview, progress polling, and execution hot paths.'
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_provider_diagnostic_context NOT IN (
    'PROVIDER_DIAGNOSTIC_TAB',
    'PROVIDER_DIAGNOSTIC_ACTION',
    'EXPLICIT_PROVIDER_DIAGNOSTIC',
    'USER_TRIGGERED_PROVIDER_DIAGNOSTIC',
    'PROVIDER_REVIEW',
    'PROVIDER_REPAIR',
    'PAYMENT_ISSUES_PROVIDER_DIAGNOSTIC',
    'CURRENT_PAYMENT_STATUS_PROVIDER_DETAIL'
  ) THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
      'code', 'PROVIDER_DIAGNOSTIC_CONTEXT_NOT_EXPLICIT',
      'context', v_provider_diagnostic_context,
      'message', 'Provider submit diagnostics are only allowed from an explicit provider diagnostics tab/action or provider review/repair flow.'
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF p_pay_batch_id IS NOT NULL THEN
    PERFORM 1 FROM public.pay_batches AS batch_check WHERE batch_check.id = p_pay_batch_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'PAY_BATCH_NOT_FOUND',
        'message', 'pay_provider_submit_diagnostic_get: pay batch not found',
        'pay_batch_id', p_pay_batch_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF p_operation_id IS NOT NULL THEN
    SELECT operation_row.pay_batch_id
    INTO v_batch_id_from_scope
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'OPERATION_NOT_FOUND',
        'message', 'pay_provider_submit_diagnostic_get: operation not found',
        'operation_id', p_operation_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
    IF v_effective_pay_batch_id IS NULL THEN
      v_effective_pay_batch_id := v_batch_id_from_scope;
    ELSIF v_batch_id_from_scope IS NOT NULL AND v_effective_pay_batch_id <> v_batch_id_from_scope THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'OPERATION_BATCH_MISMATCH',
        'message', 'pay_provider_submit_diagnostic_get: operation does not belong to supplied pay batch',
        'operation_id', p_operation_id::text,
        'operation_pay_batch_id', v_batch_id_from_scope::text,
        'pay_batch_id', v_effective_pay_batch_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF p_transfer_id IS NOT NULL THEN
    SELECT transfer_row.pay_batch_id
    INTO v_batch_id_from_scope
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.id = p_transfer_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'TRANSFER_NOT_FOUND',
        'message', 'pay_provider_submit_diagnostic_get: transfer not found',
        'transfer_id', p_transfer_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
    IF v_effective_pay_batch_id IS NULL THEN
      v_effective_pay_batch_id := v_batch_id_from_scope;
    ELSIF v_effective_pay_batch_id <> v_batch_id_from_scope THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'TRANSFER_BATCH_MISMATCH',
        'message', 'pay_provider_submit_diagnostic_get: transfer does not belong to supplied pay batch',
        'transfer_id', p_transfer_id::text,
        'transfer_pay_batch_id', v_batch_id_from_scope::text,
        'pay_batch_id', v_effective_pay_batch_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF p_chunk_id IS NOT NULL THEN
    SELECT operation_row.pay_batch_id
    INTO v_batch_id_from_scope
    FROM public.banking_pay_operation_chunks AS chunk_row
    JOIN public.banking_pay_operations AS operation_row
      ON operation_row.id = chunk_row.operation_id
    WHERE chunk_row.id = p_chunk_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'CHUNK_NOT_FOUND',
        'message', 'pay_provider_submit_diagnostic_get: chunk not found',
        'chunk_id', p_chunk_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
    IF v_effective_pay_batch_id IS NULL THEN
      v_effective_pay_batch_id := v_batch_id_from_scope;
    ELSIF v_batch_id_from_scope IS NOT NULL AND v_effective_pay_batch_id <> v_batch_id_from_scope THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'CHUNK_BATCH_MISMATCH',
        'message', 'pay_provider_submit_diagnostic_get: chunk operation does not belong to supplied pay batch',
        'chunk_id', p_chunk_id::text,
        'chunk_pay_batch_id', v_batch_id_from_scope::text,
        'pay_batch_id', v_effective_pay_batch_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;



  PERFORM set_config('lock_timeout', '3s', true);

  IF p_operation_id IS NOT NULL AND COALESCE(p_counts_only, false) IS TRUE THEN
    DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_exact_chunks;
    CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_exact_chunks (
      chunk_id uuid PRIMARY KEY,
      operation_id uuid NOT NULL,
      pay_batch_id uuid,
      phase text,
      chunk_type text,
      sequence_no integer,
      status text,
      payload_json jsonb,
      result_json jsonb,
      error_json jsonb,
      unit_count integer,
      completed_count integer,
      failed_count integer,
      locked_by text,
      lock_expires_at_utc timestamptz,
      started_at_utc timestamptz,
      completed_at_utc timestamptz,
      created_at_utc timestamptz,
      updated_at_utc timestamptz
    ) ON COMMIT DROP;

    INSERT INTO pg_temp.tmp_provider_submit_exact_chunks (
      chunk_id,
      operation_id,
      pay_batch_id,
      phase,
      chunk_type,
      sequence_no,
      status,
      payload_json,
      result_json,
      error_json,
      unit_count,
      completed_count,
      failed_count,
      locked_by,
      lock_expires_at_utc,
      started_at_utc,
      completed_at_utc,
      created_at_utc,
      updated_at_utc
    )
    SELECT chunk_row.id,
           chunk_row.operation_id,
           v_effective_pay_batch_id,
           chunk_row.phase,
           chunk_row.chunk_type,
           chunk_row.sequence_no,
           chunk_row.status,
           COALESCE(chunk_row.payload_json, '{}'::jsonb),
           chunk_row.result_json,
           chunk_row.error_json,
           chunk_row.unit_count,
           chunk_row.completed_count,
           chunk_row.failed_count,
           chunk_row.locked_by,
           chunk_row.lock_expires_at_utc,
           chunk_row.started_at_utc,
           chunk_row.completed_at_utc,
           chunk_row.created_at_utc,
           chunk_row.updated_at_utc
    FROM public.banking_pay_operation_chunks AS chunk_row
    WHERE chunk_row.operation_id = p_operation_id
      AND (chunk_row.phase = 'SUBMIT_PROVIDER_TRANSFERS' OR chunk_row.chunk_type = 'TRANSFER_SUBMIT')
      AND (p_chunk_id IS NULL OR chunk_row.id = p_chunk_id)
    ORDER BY chunk_row.sequence_no, chunk_row.created_at_utc NULLS FIRST, chunk_row.id
    ON CONFLICT (chunk_id) DO NOTHING;

    IF p_chunk_id IS NOT NULL AND NOT EXISTS (
      SELECT 1
      FROM pg_temp.tmp_provider_submit_exact_chunks AS exact_chunk_check
      WHERE exact_chunk_check.chunk_id = p_chunk_id
    ) THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'CHUNK_NOT_FOUND_FOR_OPERATION',
        'message', 'pay_provider_submit_diagnostic_get: chunk does not belong to supplied operation/provider-submit scope',
        'operation_id', p_operation_id::text,
        'chunk_id', p_chunk_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_exact_transfer_ids;
    CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_exact_transfer_ids (
      transfer_id uuid PRIMARY KEY
    ) ON COMMIT DROP;

    INSERT INTO pg_temp.tmp_provider_submit_exact_transfer_ids (transfer_id)
    SELECT DISTINCT operation_scope.pay_bank_transfer_id
    FROM public.banking_pay_operation_transfer_scope AS operation_scope
    WHERE p_chunk_id IS NULL
      AND operation_scope.operation_id = p_operation_id
      AND (v_effective_pay_batch_id IS NULL OR operation_scope.pay_batch_id = v_effective_pay_batch_id)
      AND operation_scope.pay_bank_transfer_id IS NOT NULL
      AND (p_transfer_id IS NULL OR operation_scope.pay_bank_transfer_id = p_transfer_id)
    ON CONFLICT DO NOTHING;

    INSERT INTO pg_temp.tmp_provider_submit_exact_transfer_ids (transfer_id)
    SELECT transfer_row.id
    FROM public.pay_bank_transfers AS transfer_row
    WHERE p_chunk_id IS NOT NULL
      AND p_transfer_id IS NOT NULL
      AND transfer_row.id = p_transfer_id
      AND (v_effective_pay_batch_id IS NULL OR transfer_row.pay_batch_id = v_effective_pay_batch_id)
      AND EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_transfer_scope AS operation_scope_check
        WHERE operation_scope_check.operation_id = p_operation_id
          AND (v_effective_pay_batch_id IS NULL OR operation_scope_check.pay_batch_id = v_effective_pay_batch_id)
          AND operation_scope_check.pay_bank_transfer_id = transfer_row.id
      )
    ON CONFLICT DO NOTHING;

    INSERT INTO pg_temp.tmp_provider_submit_exact_transfer_ids (transfer_id)
    SELECT DISTINCT transfer_uuid.transfer_id
    FROM pg_temp.tmp_provider_submit_exact_chunks AS selected_chunk
    CROSS JOIN LATERAL (
      SELECT transfer_id_element.value AS transfer_id_text
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(selected_chunk.payload_json->'transfer_ids') = 'array' THEN selected_chunk.payload_json->'transfer_ids' ELSE '[]'::jsonb END) AS transfer_id_element(value)
      UNION ALL
      SELECT COALESCE(transfer_payload.value->>'pay_bank_transfer_id', transfer_payload.value->>'transfer_id', transfer_payload.value->>'id') AS transfer_id_text
      FROM jsonb_array_elements(CASE WHEN jsonb_typeof(selected_chunk.payload_json->'transfers') = 'array' THEN selected_chunk.payload_json->'transfers' ELSE '[]'::jsonb END) AS transfer_payload(value)
    ) AS transfer_text
    CROSS JOIN LATERAL (
      SELECT transfer_text.transfer_id_text::uuid AS transfer_id
      WHERE NULLIF(BTRIM(COALESCE(transfer_text.transfer_id_text, '')), '') ~* v_uuid_regex
    ) AS transfer_uuid
    JOIN public.pay_bank_transfers AS transfer_row
      ON transfer_row.id = transfer_uuid.transfer_id
     AND (v_effective_pay_batch_id IS NULL OR transfer_row.pay_batch_id = v_effective_pay_batch_id)
    WHERE p_transfer_id IS NULL OR transfer_uuid.transfer_id = p_transfer_id
    ON CONFLICT DO NOTHING;

    IF p_transfer_id IS NOT NULL AND NOT EXISTS (
      SELECT 1
      FROM pg_temp.tmp_provider_submit_exact_transfer_ids AS exact_transfer_check
      WHERE exact_transfer_check.transfer_id = p_transfer_id
    ) THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'TRANSFER_NOT_FOUND_FOR_OPERATION',
        'message', 'pay_provider_submit_diagnostic_get: transfer does not belong to the supplied operation/provider-submit scope',
        'operation_id', p_operation_id::text,
        'transfer_id', p_transfer_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_exact_transfers;
    CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_exact_transfers (
      transfer_id uuid PRIMARY KEY,
      pay_batch_id uuid NOT NULL,
      status text,
      rail_provider text,
      rail_env text,
      request_id text,
      rail_tx_id text,
      rail_state text,
      rail_meta_json jsonb,
      payment_reference text,
      created_at_utc timestamptz
    ) ON COMMIT DROP;

    INSERT INTO pg_temp.tmp_provider_submit_exact_transfers (
      transfer_id,
      pay_batch_id,
      status,
      rail_provider,
      rail_env,
      request_id,
      rail_tx_id,
      rail_state,
      rail_meta_json,
      payment_reference,
      created_at_utc
    )
    SELECT transfer_row.id,
           transfer_row.pay_batch_id,
           transfer_row.status,
           transfer_row.rail_provider,
           transfer_row.rail_env,
           transfer_row.request_id,
           transfer_row.rail_tx_id,
           transfer_row.rail_state,
           COALESCE(transfer_row.rail_meta_json, '{}'::jsonb),
           transfer_row.payment_reference,
           transfer_row.created_at_utc
    FROM public.pay_bank_transfers AS transfer_row
    JOIN pg_temp.tmp_provider_submit_exact_transfer_ids AS exact_transfer_id
      ON exact_transfer_id.transfer_id = transfer_row.id
    WHERE v_effective_pay_batch_id IS NULL OR transfer_row.pay_batch_id = v_effective_pay_batch_id
    ON CONFLICT (transfer_id) DO NOTHING;

    DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_exact_markers;
    CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_exact_markers (
      source_kind text NOT NULL,
      source_id text,
      chunk_id uuid,
      transfer_id uuid,
      provider_submission_status text,
      review_reason_code text,
      provider_request_sent boolean NOT NULL DEFAULT false,
      provider_response_present boolean NOT NULL DEFAULT false,
      provider_response_received boolean NOT NULL DEFAULT false,
      provider_accepted boolean NOT NULL DEFAULT false,
      provider_rejected boolean NOT NULL DEFAULT false,
      provider_unknown boolean NOT NULL DEFAULT false,
      provider_malformed boolean NOT NULL DEFAULT false,
      provider_blocked_pre_call boolean NOT NULL DEFAULT false,
      unfinalised_submit_chunk boolean NOT NULL DEFAULT false,
      marker_json jsonb NOT NULL DEFAULT '{}'::jsonb
    ) ON COMMIT DROP;

    INSERT INTO pg_temp.tmp_provider_submit_exact_markers (
      source_kind,
      source_id,
      chunk_id,
      transfer_id,
      provider_submission_status,
      review_reason_code,
      provider_request_sent,
      provider_response_present,
      provider_response_received,
      provider_accepted,
      provider_rejected,
      provider_unknown,
      provider_malformed,
      provider_blocked_pre_call,
      unfinalised_submit_chunk,
      marker_json
    )
    SELECT 'chunk_diagnostic'::text,
           selected_chunk.chunk_id::text,
           selected_chunk.chunk_id,
           exact_chunk_transfer.transfer_id,
           upper(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_status', chunk_diag.provider_submit_diagnostic->>'outcome_code', ''))),
           upper(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))),
           lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_request_sent', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_request_sent_confirmed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_called', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_request_dispatched_at_utc', chunk_diag.provider_submit_diagnostic->>'request_sent_at_utc', '')), '') IS NOT NULL,
           lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_response_present', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_response_received', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'response_received_at_utc', chunk_diag.provider_submit_diagnostic->>'provider_http_status', chunk_diag.provider_submit_diagnostic->>'provider_error_code', '')), '') IS NOT NULL,
           lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_response_received', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'response_received_at_utc', '')), '') IS NOT NULL,
           upper(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_status', chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT', 'ACCEPTED', 'PROVIDER_ACCEPTED', 'PROVIDER_ACCEPTED_PAYMENT')
             OR lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_accepted', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_acceptance_evidence_present', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_acceptance_evidence_count', chunk_diag.provider_submit_diagnostic->>'providerAcceptanceEvidenceCount', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_acceptance_evidence_count', chunk_diag.provider_submit_diagnostic->>'providerAcceptanceEvidenceCount', '0'))::integer ELSE 0 END > 0
             OR NULLIF(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'rail_tx_id', chunk_diag.provider_submit_diagnostic->>'provider_transaction_id', chunk_diag.provider_submit_diagnostic->>'provider_payment_id', chunk_diag.provider_submit_diagnostic->>'provider_reference', '')), '') IS NOT NULL,
           upper(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_status', chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_REJECTED_PAYMENT', 'REJECTED', 'DECLINED')
             OR lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_rejected', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_rejection_count', chunk_diag.provider_submit_diagnostic->>'providerRejectionCount', chunk_diag.provider_submit_diagnostic->>'provider_submission_rejected_count', chunk_diag.provider_submit_diagnostic->>'providerSubmissionRejectedCount', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_rejection_count', chunk_diag.provider_submit_diagnostic->>'providerRejectionCount', chunk_diag.provider_submit_diagnostic->>'provider_submission_rejected_count', chunk_diag.provider_submit_diagnostic->>'providerSubmissionRejectedCount', '0'))::integer ELSE 0 END > 0,
           upper(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_status', chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'PROVIDER_REQUEST_SENT_NO_RESPONSE')
             OR lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_unknown', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_unknown_count', chunk_diag.provider_submit_diagnostic->>'providerUnknownCount', chunk_diag.provider_submit_diagnostic->>'provider_submission_unknown_count', chunk_diag.provider_submit_diagnostic->>'providerSubmissionUnknownCount', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_unknown_count', chunk_diag.provider_submit_diagnostic->>'providerUnknownCount', chunk_diag.provider_submit_diagnostic->>'provider_submission_unknown_count', chunk_diag.provider_submit_diagnostic->>'providerSubmissionUnknownCount', '0'))::integer ELSE 0 END > 0,
           upper(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_status', chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))) IN ('PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'MALFORMED', 'MALFORMED_RESPONSE', 'PROVIDER_RESPONSE_MALFORMED'),
           upper(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_status', chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))) IN ('PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'),
           upper(BTRIM(COALESCE(selected_chunk.status, ''))) = 'RUNNING'
             AND (selected_chunk.lock_expires_at_utc IS NULL OR selected_chunk.lock_expires_at_utc <= v_now),
           jsonb_strip_nulls(COALESCE(chunk_diag.provider_submit_diagnostic, '{}'::jsonb) || jsonb_build_object('chunk_id', selected_chunk.chunk_id::text))
    FROM pg_temp.tmp_provider_submit_exact_chunks AS selected_chunk
    LEFT JOIN LATERAL (
      SELECT COALESCE(
        CASE WHEN jsonb_typeof(selected_chunk.error_json->'provider_submit_diagnostic') = 'object' THEN selected_chunk.error_json->'provider_submit_diagnostic' ELSE NULL::jsonb END,
        CASE WHEN jsonb_typeof(selected_chunk.result_json->'provider_submit_diagnostic') = 'object' THEN selected_chunk.result_json->'provider_submit_diagnostic' ELSE NULL::jsonb END,
        CASE WHEN jsonb_typeof(selected_chunk.payload_json->'provider_submit_diagnostic') = 'object' THEN selected_chunk.payload_json->'provider_submit_diagnostic' ELSE NULL::jsonb END,
        '{}'::jsonb
      ) AS provider_submit_diagnostic
    ) AS chunk_diag ON true
    LEFT JOIN LATERAL (
      SELECT exact_transfer.transfer_id
      FROM pg_temp.tmp_provider_submit_exact_transfer_ids AS exact_transfer
      ORDER BY exact_transfer.transfer_id
      LIMIT 1
    ) AS exact_chunk_transfer ON true
    WHERE COALESCE(chunk_diag.provider_submit_diagnostic, '{}'::jsonb) <> '{}'::jsonb
       OR upper(BTRIM(COALESCE(selected_chunk.status, ''))) = 'RUNNING';

    INSERT INTO pg_temp.tmp_provider_submit_exact_markers (
      source_kind,
      source_id,
      chunk_id,
      transfer_id,
      provider_submission_status,
      review_reason_code,
      provider_request_sent,
      provider_response_present,
      provider_response_received,
      provider_accepted,
      provider_rejected,
      provider_unknown,
      provider_malformed,
      provider_blocked_pre_call,
      unfinalised_submit_chunk,
      marker_json
    )
    SELECT 'transfer_meta'::text,
           selected_transfer.transfer_id::text,
           NULL::uuid,
           selected_transfer.transfer_id,
           upper(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))),
           upper(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))),
           lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent_confirmed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_called}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_dispatched_at_utc}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,request_sent_at_utc}', '')), '') IS NOT NULL,
           lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_received}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,response_received_at_utc}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_http_status}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_error_code}', '')), '') IS NOT NULL,
           lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_received}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,response_received_at_utc}', '')), '') IS NOT NULL,
           upper(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT', 'ACCEPTED', 'PROVIDER_ACCEPTED', 'PROVIDER_ACCEPTED_PAYMENT')
             OR lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_accepted}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerAcceptanceEvidenceCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerAcceptanceEvidenceCount}', '0'))::integer ELSE 0 END > 0
             OR NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,rail_tx_id}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_payment_id}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_reference}', '')), '') IS NOT NULL,
           upper(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_REJECTED_PAYMENT', 'REJECTED', 'DECLINED')
             OR lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_rejected}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_rejection_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerRejectionCount}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_rejected_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerSubmissionRejectedCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_rejection_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerRejectionCount}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_rejected_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerSubmissionRejectedCount}', '0'))::integer ELSE 0 END > 0,
           upper(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'PROVIDER_REQUEST_SENT_NO_RESPONSE')
             OR lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_unknown}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_unknown_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerUnknownCount}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_unknown_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerSubmissionUnknownCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_unknown_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerUnknownCount}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_unknown_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerSubmissionUnknownCount}', '0'))::integer ELSE 0 END > 0,
           upper(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'MALFORMED', 'MALFORMED_RESPONSE', 'PROVIDER_RESPONSE_MALFORMED'),
           upper(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'),
           false,
           jsonb_strip_nulls(COALESCE(selected_transfer.rail_meta_json->'provider_submit_diagnostic', '{}'::jsonb) || jsonb_build_object('transfer_id', selected_transfer.transfer_id::text))
    FROM pg_temp.tmp_provider_submit_exact_transfers AS selected_transfer
    WHERE COALESCE(selected_transfer.rail_meta_json->'provider_submit_diagnostic', '{}'::jsonb) <> '{}'::jsonb
       OR NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, selected_transfer.rail_state, '')), '') IS NOT NULL;

    INSERT INTO pg_temp.tmp_provider_submit_exact_markers (
      source_kind,
      source_id,
      chunk_id,
      transfer_id,
      provider_submission_status,
      review_reason_code,
      provider_request_sent,
      provider_response_present,
      provider_response_received,
      provider_accepted,
      provider_rejected,
      provider_unknown,
      provider_malformed,
      provider_blocked_pre_call,
      unfinalised_submit_chunk,
      marker_json
    )
    SELECT 'transfer_event'::text,
           transfer_event.id::text,
           NULL::uuid,
           transfer_event.pay_bank_transfer_id,
           upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.normalised_state, transfer_event.provider_state, ''))),
           upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', transfer_event.raw_payload #>> '{review_reason_code}', ''))),
           upper(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_request_sent}', transfer_event.raw_payload #>> '{provider_request_sent}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_request_sent_confirmed}', transfer_event.raw_payload #>> '{provider_request_sent_confirmed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_called}', transfer_event.raw_payload #>> '{provider_called}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_request_dispatched_at_utc}', transfer_event.raw_payload #>> '{provider_request_dispatched_at_utc}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,request_sent_at_utc}', transfer_event.raw_payload #>> '{request_sent_at_utc}', '')), '') IS NOT NULL,
           upper(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_response_present}', transfer_event.raw_payload #>> '{provider_response_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_response_received}', transfer_event.raw_payload #>> '{provider_response_received}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,response_received_at_utc}', transfer_event.raw_payload #>> '{response_received_at_utc}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_http_status}', transfer_event.raw_payload #>> '{provider_http_status}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_error_code}', transfer_event.raw_payload #>> '{provider_error_code}', '')), '') IS NOT NULL,
           upper(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_response_received}', transfer_event.raw_payload #>> '{provider_response_received}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,response_received_at_utc}', transfer_event.raw_payload #>> '{response_received_at_utc}', '')), '') IS NOT NULL,
           upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', transfer_event.raw_payload #>> '{review_reason_code}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.normalised_state, transfer_event.provider_state, ''))) IN ('PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT', 'PROVIDER_SUBMISSION_ACCEPTED', 'ACCEPTED', 'PROVIDER_ACCEPTED', 'PROVIDER_ACCEPTED_PAYMENT', 'SUBMITTED', 'SENT', 'PROCESSING', 'PENDING', 'COMPLETED', 'COMMITTED', 'SETTLED', 'PAID', 'EXECUTED')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_accepted}', transfer_event.raw_payload #>> '{provider_submission_accepted}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_acceptance_evidence_present}', transfer_event.raw_payload #>> '{provider_acceptance_evidence_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_acceptance_evidence_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerAcceptanceEvidenceCount}', transfer_event.raw_payload #>> '{provider_acceptance_evidence_count}', transfer_event.raw_payload #>> '{providerAcceptanceEvidenceCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_acceptance_evidence_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerAcceptanceEvidenceCount}', transfer_event.raw_payload #>> '{provider_acceptance_evidence_count}', transfer_event.raw_payload #>> '{providerAcceptanceEvidenceCount}', '0'))::integer ELSE 0 END > 0,
           upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', transfer_event.raw_payload #>> '{review_reason_code}', transfer_event.normalised_state, transfer_event.provider_state, ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_REJECTED_PAYMENT', 'REJECTED', 'DECLINED', 'FAILED', 'ERROR')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_rejected}', transfer_event.raw_payload #>> '{provider_submission_rejected}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_rejection_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerRejectionCount}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_rejected_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerSubmissionRejectedCount}', transfer_event.raw_payload #>> '{provider_rejection_count}', transfer_event.raw_payload #>> '{providerRejectionCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_rejection_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerRejectionCount}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_rejected_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerSubmissionRejectedCount}', transfer_event.raw_payload #>> '{provider_rejection_count}', transfer_event.raw_payload #>> '{providerRejectionCount}', '0'))::integer ELSE 0 END > 0,
           upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', transfer_event.raw_payload #>> '{review_reason_code}', ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'PROVIDER_REQUEST_SENT_NO_RESPONSE')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_unknown}', transfer_event.raw_payload #>> '{provider_submission_unknown}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_unknown_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerUnknownCount}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_unknown_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerSubmissionUnknownCount}', transfer_event.raw_payload #>> '{provider_unknown_count}', transfer_event.raw_payload #>> '{providerUnknownCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_unknown_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerUnknownCount}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_unknown_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerSubmissionUnknownCount}', transfer_event.raw_payload #>> '{provider_unknown_count}', transfer_event.raw_payload #>> '{providerUnknownCount}', '0'))::integer ELSE 0 END > 0,
           upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', transfer_event.raw_payload #>> '{review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'MALFORMED', 'MALFORMED_RESPONSE', 'PROVIDER_RESPONSE_MALFORMED'),
           upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', transfer_event.raw_payload #>> '{review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'),
           false,
           jsonb_strip_nulls(COALESCE(transfer_event.raw_payload, '{}'::jsonb) || jsonb_build_object(
             'pay_bank_transfer_event_id', transfer_event.id::text,
             'event_source', transfer_event.event_source,
             'normalised_state', transfer_event.normalised_state,
             'provider_state', transfer_event.provider_state
           ))
    FROM public.pay_bank_transfer_events AS transfer_event
    JOIN pg_temp.tmp_provider_submit_exact_transfers AS selected_transfer
      ON selected_transfer.transfer_id = transfer_event.pay_bank_transfer_id
    WHERE transfer_event.pay_bank_transfer_id IS NOT NULL;

    SELECT COUNT(*)::integer INTO v_operation_count FROM public.banking_pay_operations AS exact_operation WHERE exact_operation.id = p_operation_id;
    SELECT COUNT(*)::integer INTO v_chunk_count FROM pg_temp.tmp_provider_submit_exact_chunks AS selected_chunk;
    SELECT COUNT(*)::integer INTO v_transfer_count FROM pg_temp.tmp_provider_submit_exact_transfers AS selected_transfer;

    SELECT COUNT(DISTINCT COALESCE(marker.transfer_id::text, marker.chunk_id::text, marker.source_id)) FILTER (WHERE marker.provider_accepted)::integer,
           COUNT(DISTINCT COALESCE(marker.transfer_id::text, marker.chunk_id::text, marker.source_id)) FILTER (WHERE marker.provider_response_present OR marker.provider_response_received)::integer,
           COUNT(DISTINCT COALESCE(marker.transfer_id::text, marker.chunk_id::text, marker.source_id)) FILTER (WHERE marker.provider_request_sent OR marker.provider_response_present OR marker.provider_response_received)::integer,
           COUNT(DISTINCT COALESCE(marker.transfer_id::text, marker.chunk_id::text, marker.source_id)) FILTER (WHERE marker.provider_unknown)::integer,
           COUNT(DISTINCT COALESCE(marker.transfer_id::text, marker.chunk_id::text, marker.source_id)) FILTER (WHERE marker.provider_rejected)::integer,
           COUNT(DISTINCT COALESCE(marker.transfer_id::text, marker.chunk_id::text, marker.source_id)) FILTER (WHERE marker.provider_blocked_pre_call)::integer,
           COUNT(DISTINCT COALESCE(marker.transfer_id::text, marker.chunk_id::text, marker.source_id)) FILTER (WHERE marker.provider_malformed)::integer,
           COUNT(DISTINCT marker.chunk_id) FILTER (WHERE marker.unfinalised_submit_chunk)::integer,
           COALESCE(BOOL_OR(marker.unfinalised_submit_chunk), false)
    INTO v_provider_acceptance_evidence_count,
         v_provider_response_present_count,
         v_provider_request_sent_count,
         v_provider_submission_unknown_count,
         v_provider_submission_rejected_count,
         v_provider_submission_blocked_pre_call_count,
         v_provider_submission_malformed_response_count,
         v_unfinalised_submit_chunk_count,
         v_chunk_lock_expired
    FROM pg_temp.tmp_provider_submit_exact_markers AS marker;

    v_provider_submission_accepted_count := COALESCE(v_provider_acceptance_evidence_count, 0);
    v_stale_unresolved_submit_chunk_count := CASE
      WHEN COALESCE(v_unfinalised_submit_chunk_count, 0) > 0
        AND COALESCE(v_provider_response_present_count, 0) = 0
        AND COALESCE(v_provider_acceptance_evidence_count, 0) = 0 THEN v_unfinalised_submit_chunk_count
      ELSE 0
    END;
    v_stale_empty_submit_chunk_count := v_stale_unresolved_submit_chunk_count;
    v_request_sent_no_response_count := CASE
      WHEN COALESCE(v_provider_request_sent_count, 0) > 0
        AND COALESCE(v_provider_response_present_count, 0) = 0
        AND COALESCE(v_provider_acceptance_evidence_count, 0) = 0 THEN v_provider_request_sent_count
      ELSE 0
    END;

    SELECT COALESCE(jsonb_agg(to_jsonb(selected_chunk.chunk_id::text) ORDER BY selected_chunk.sequence_no NULLS LAST, selected_chunk.created_at_utc NULLS FIRST, selected_chunk.chunk_id), '[]'::jsonb),
           MIN(selected_chunk.chunk_id::text),
           MIN(selected_chunk.started_at_utc)::text,
           MIN(selected_chunk.completed_at_utc)::text,
           MIN(selected_chunk.lock_expires_at_utc)::text
    INTO v_chunk_ids,
         v_primary_chunk_id,
         v_chunk_started_at_utc,
         v_chunk_completed_at_utc,
         v_chunk_lock_expires_at_utc
    FROM pg_temp.tmp_provider_submit_exact_chunks AS selected_chunk;

    SELECT COALESCE(jsonb_agg(to_jsonb(selected_transfer.transfer_id::text) ORDER BY selected_transfer.transfer_id), '[]'::jsonb),
           MIN(selected_transfer.transfer_id::text),
           MIN(selected_transfer.rail_provider),
           MIN(selected_transfer.rail_env),
           MIN(NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '')),
           MIN(NULLIF(BTRIM(COALESCE(selected_transfer.rail_state, '')), '')),
           MIN(NULLIF(BTRIM(COALESCE(selected_transfer.request_id, '')), ''))
    INTO v_transfer_ids,
         v_primary_transfer_id,
         v_primary_rail_provider,
         v_primary_rail_env,
         v_primary_rail_tx_id,
         v_primary_rail_state,
         v_primary_request_id
    FROM pg_temp.tmp_provider_submit_exact_transfers AS selected_transfer;

    SELECT COALESCE(jsonb_agg(to_jsonb(operation_scope.id::text) ORDER BY operation_scope.id), '[]'::jsonb),
           MIN(operation_scope.id::text)
    INTO v_transfer_scope_ids,
         v_primary_transfer_scope_id
    FROM public.banking_pay_operation_transfer_scope AS operation_scope
    WHERE operation_scope.operation_id = p_operation_id
      AND (v_effective_pay_batch_id IS NULL OR operation_scope.pay_batch_id = v_effective_pay_batch_id)
      AND (p_transfer_id IS NULL OR operation_scope.pay_bank_transfer_id = p_transfer_id)
      AND (
        p_chunk_id IS NULL
        OR EXISTS (
          SELECT 1
          FROM pg_temp.tmp_provider_submit_exact_transfer_ids AS exact_transfer_scope
          WHERE exact_transfer_scope.transfer_id = operation_scope.pay_bank_transfer_id
        )
      );

    SELECT COUNT(*)::integer,
           COALESCE(jsonb_agg(to_jsonb(auth_request.id::text) ORDER BY auth_request.created_at_utc NULLS LAST, auth_request.id), '[]'::jsonb),
           MIN(auth_request.id::text)
    INTO v_active_auth_request_count,
         v_auth_request_ids,
         v_primary_auth_request_id
    FROM public.pay_batch_auth_requests AS auth_request
    WHERE v_effective_pay_batch_id IS NOT NULL
      AND auth_request.pay_batch_id = v_effective_pay_batch_id
      AND upper(BTRIM(COALESCE(auth_request.state, ''))) IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED')
      AND auth_request.execution_intent_json->>'operation_id' = p_operation_id::text;

    v_diagnostic_operation_id := p_operation_id::text;
    v_primary_operation_id := p_operation_id::text;
    v_current_operation_ids := jsonb_build_array(p_operation_id::text);
    v_related_operation_ids := '[]'::jsonb;
    v_operation_ids := jsonb_build_array(p_operation_id::text);

    SELECT marker.marker_json->>'provider_transaction_id',
           marker.marker_json->>'provider_reference',
           marker.marker_json->>'provider_state',
           COALESCE(marker.marker_json->>'request_id', v_primary_request_id),
           COALESCE(marker.marker_json->>'idempotency_key', v_primary_request_id),
           marker.marker_json->>'local_provider_request_id',
           marker.marker_json->>'provider_http_status',
           marker.marker_json->>'provider_error_code',
           marker.marker_json->>'provider_error_message_redacted',
           marker.marker_json->'provider_response_redacted',
           marker.marker_json->'provider_error_redacted'
    INTO v_primary_provider_transaction_id,
         v_primary_provider_reference,
         v_primary_provider_state,
         v_primary_request_id,
         v_primary_idempotency_key,
         v_primary_local_provider_request_id,
         v_primary_provider_http_status,
         v_primary_provider_error_code,
         v_primary_provider_error_message_redacted,
         v_primary_provider_response_redacted,
         v_primary_provider_error_redacted
    FROM pg_temp.tmp_provider_submit_exact_markers AS marker
    WHERE marker.provider_accepted OR marker.provider_rejected OR marker.provider_response_present OR marker.provider_request_sent
    ORDER BY CASE WHEN marker.provider_accepted THEN 0 WHEN marker.provider_rejected THEN 1 WHEN marker.provider_response_present THEN 2 ELSE 3 END,
             marker.source_kind,
             marker.source_id
    LIMIT 1;

    v_provider_submit_actual_context := COALESCE(v_chunk_count, 0) > 0
      OR COALESCE(v_transfer_count, 0) > 0
      OR COALESCE(v_provider_acceptance_evidence_count, 0) > 0
      OR COALESCE(v_provider_response_present_count, 0) > 0
      OR COALESCE(v_provider_request_sent_count, 0) > 0
      OR COALESCE(v_provider_submission_unknown_count, 0) > 0
      OR COALESCE(v_provider_submission_rejected_count, 0) > 0
      OR COALESCE(v_provider_submission_malformed_response_count, 0) > 0
      OR COALESCE(v_unfinalised_submit_chunk_count, 0) > 0;

    v_mixed_provider_submit_outcome := COALESCE(v_provider_acceptance_evidence_count, 0) > 0
      AND (
        COALESCE(v_provider_submission_rejected_count, 0) > 0
        OR COALESCE(v_provider_submission_malformed_response_count, 0) > 0
        OR COALESCE(v_provider_submission_unknown_count, 0) > 0
        OR COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0
        OR COALESCE(v_request_sent_no_response_count, 0) > 0
        OR COALESCE(v_transfer_count, 0) > COALESCE(v_provider_acceptance_evidence_count, 0)
      );

    IF COALESCE(v_provider_acceptance_evidence_count, 0) > 0 THEN
      v_provider_submission_status := 'PROVIDER_SUBMISSION_ACCEPTED';
      v_review_reason_code := CASE WHEN v_mixed_provider_submit_outcome THEN 'MIXED_PROVIDER_SUBMIT_OUTCOME' ELSE 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT' END;
      v_provider_call_stage := 'PROVIDER_RESPONSE_RECEIVED';
      v_provider_submission_attempted := true;
      v_provider_request_sent := true;
      v_provider_response_received := true;
      v_provider_response_present := true;
      v_provider_submission_accepted := true;
      v_provider_acceptance_evidence_present := true;
      v_manual_resolution_required := COALESCE(v_mixed_provider_submit_outcome, false);
      v_safe_retry_available := false;
      v_automatic_retry_blocked := true;
      v_retry_blocked_reason := CASE WHEN v_mixed_provider_submit_outcome THEN 'PROVIDER_SUBMISSION_MIXED_OUTCOME' ELSE 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT' END;
      v_recommended_action := CASE WHEN v_mixed_provider_submit_outcome THEN 'Provider acceptance evidence exists for at least one transfer, but not all outcomes are resolved. Reconcile before retry.' ELSE 'Provider acceptance evidence exists. Do not retry unless reconciled.' END;
    ELSIF COALESCE(v_provider_submission_rejected_count, 0) > 0 THEN
      v_provider_submission_status := 'PROVIDER_SUBMISSION_REJECTED';
      v_review_reason_code := 'PROVIDER_REJECTED_PAYMENT';
      v_provider_call_stage := 'PROVIDER_RESPONSE_RECEIVED';
      v_provider_submission_attempted := true;
      v_provider_request_sent := true;
      v_provider_response_received := true;
      v_provider_response_present := true;
      v_provider_submission_rejected := true;
      v_provider_submission_failed := true;
      v_manual_resolution_required := false;
      v_safe_retry_available := false;
      v_automatic_retry_blocked := true;
      v_retry_blocked_reason := 'PROVIDER_SUBMISSION_REJECTED';
      v_recommended_action := 'Review the provider rejection/error and retry only after correction.';
    ELSIF COALESCE(v_provider_submission_malformed_response_count, 0) > 0 THEN
      v_provider_submission_status := 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE';
      v_review_reason_code := 'PROVIDER_RESPONSE_MALFORMED';
      v_provider_submission_attempted := true;
      v_provider_request_sent := true;
      v_provider_response_received := true;
      v_provider_response_present := true;
      v_provider_submission_unknown := true;
      v_manual_resolution_required := true;
      v_safe_retry_available := false;
      v_automatic_retry_blocked := true;
      v_retry_blocked_reason := 'PROVIDER_RESPONSE_MALFORMED';
      v_recommended_action := 'Provider returned an unusable response. Check bank records before retry.';
    ELSIF COALESCE(v_provider_submission_unknown_count, 0) > 0 OR COALESCE(v_request_sent_no_response_count, 0) > 0 OR (COALESCE(v_provider_request_sent_count, 0) > 0 AND COALESCE(v_provider_response_present_count, 0) = 0) THEN
      v_provider_submission_status := 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME';
      v_review_reason_code := 'PROVIDER_REQUEST_SENT_NO_RESPONSE';
      v_provider_submission_attempted := true;
      v_provider_request_sent := true;
      v_provider_response_received := false;
      v_provider_response_present := false;
      v_provider_submission_unknown := true;
      v_manual_resolution_required := true;
      v_safe_retry_available := false;
      v_automatic_retry_blocked := true;
      v_retry_blocked_reason := 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME';
      v_recommended_action := 'Provider request may have been sent, but no usable response was recorded. Check bank records before retry.';
    ELSIF COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0 OR COALESCE(v_unfinalised_submit_chunk_count, 0) > 0 THEN
      v_provider_submission_status := 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK';
      v_review_reason_code := 'STALE_RUNNING_PROVIDER_SUBMIT_CHUNK';
      v_provider_call_stage := 'STALE_RUNNING_PROVIDER_SUBMIT_CHUNK';
      v_provider_submission_unknown := true;
      v_stale_submit_chunk := true;
      v_unfinalised_submit_chunk := true;
      v_manual_resolution_required := true;
      v_safe_retry_available := false;
      v_automatic_retry_blocked := true;
      v_retry_blocked_reason := 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK';
      v_recommended_action := 'Check bank records before retry. If no payment was made, record manual no-payment confirmation and reset for retry.';
    ELSIF COALESCE(v_provider_submission_blocked_pre_call_count, 0) > 0 THEN
      v_provider_submission_status := 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL';
      v_review_reason_code := 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL';
      v_provider_submission_attempted := false;
      v_provider_request_sent := false;
      v_provider_response_received := false;
      v_provider_response_present := false;
      v_provider_submission_failed := true;
      v_manual_resolution_required := false;
      v_safe_retry_available := true;
      v_retry_blocked_reason := NULL::text;
      v_recommended_action := 'Provider was not called. Fix the local blocker and retry if cleanup allows.';
    ELSE
      v_provider_submission_status := 'NO_PROVIDER_SUBMISSION_ATTEMPTED';
      v_review_reason_code := 'NO_PROVIDER_SUBMIT_ATTEMPT';
      v_provider_call_stage := 'NO_PROVIDER_SUBMIT_ATTEMPT';
      v_provider_submission_attempted := false;
      v_provider_request_sent := false;
      v_provider_response_received := false;
      v_provider_response_present := false;
      v_manual_resolution_required := false;
      v_safe_retry_available := true;
      v_recommended_action := 'No provider submission attempt has been recorded for this scope.';
    END IF;

    v_payment_provider_review_required := COALESCE(v_provider_submit_actual_context, false) IS TRUE
      AND v_provider_submission_status IN (
        'PROVIDER_SUBMISSION_ACCEPTED',
        'PROVIDER_SUBMISSION_REJECTED',
        'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
        'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
        'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK'
      );

    v_counts := jsonb_build_object(
      'operation_count', COALESCE(v_operation_count, 0),
      'chunk_count', COALESCE(v_chunk_count, 0),
      'transfer_count', COALESCE(v_transfer_count, 0),
      'active_auth_request_count', COALESCE(v_active_auth_request_count, 0),
      'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
      'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
      'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
      'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
      'stale_empty_submit_chunk_count', COALESCE(v_stale_empty_submit_chunk_count, 0),
      'request_sent_no_response_count', COALESCE(v_request_sent_no_response_count, 0),
      'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
      'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
      'provider_submission_accepted_count', COALESCE(v_provider_submission_accepted_count, 0),
      'provider_submission_blocked_pre_call_count', COALESCE(v_provider_submission_blocked_pre_call_count, 0),
      'provider_submission_malformed_response_count', COALESCE(v_provider_submission_malformed_response_count, 0),
      'mixed_provider_submit_outcome', COALESCE(v_mixed_provider_submit_outcome, false),
      'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
      'provider_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_attempt_or_evidence_count', COALESCE(v_provider_request_sent_count, 0) + COALESCE(v_provider_response_present_count, 0) + COALESCE(v_provider_acceptance_evidence_count, 0),
      'attempted_but_unproven_count', COALESCE(v_provider_submission_unknown_count, 0)
    );

    v_ids := jsonb_build_object(
      'operation_id', v_diagnostic_operation_id,
      'operation_ids', COALESCE(v_current_operation_ids, '[]'::jsonb),
      'related_operation_ids', COALESCE(v_related_operation_ids, '[]'::jsonb),
      'chunk_ids', COALESCE(v_chunk_ids, '[]'::jsonb),
      'transfer_ids', COALESCE(v_transfer_ids, '[]'::jsonb),
      'transfer_scope_ids', COALESCE(v_transfer_scope_ids, '[]'::jsonb),
      'auth_request_ids', COALESCE(v_auth_request_ids, '[]'::jsonb)
    );

    v_provider_submit_diagnostic := jsonb_build_object(
      'diagnostic_version', 1,
      'diagnostic_source', 'EXACT_OPERATION_COUNTS_ONLY',
      'generated_at_utc', v_now::text,
      'review_reason_code', v_review_reason_code,
      'provider_submission_status', v_provider_submission_status,
      'provider_call_stage', v_provider_call_stage,
      'provider_submission_attempted', v_provider_submission_attempted,
      'provider_request_sent', v_provider_request_sent,
      'provider_response_received', v_provider_response_received,
      'provider_response_present', v_provider_response_present,
      'provider_submission_accepted', v_provider_submission_accepted,
      'provider_submission_rejected', v_provider_submission_rejected,
      'provider_submission_failed', v_provider_submission_failed,
      'provider_submission_unknown', v_provider_submission_unknown,
      'provider_acceptance_evidence_present', v_provider_acceptance_evidence_present,
      'mixed_provider_submit_outcome', COALESCE(v_mixed_provider_submit_outcome, false),
      'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
      'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
      'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
      'provider_submission_malformed_response_count', COALESCE(v_provider_submission_malformed_response_count, 0),
      'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
      'stale_submit_chunk', v_stale_submit_chunk,
      'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
      'stale_empty_submit_chunk_count', COALESCE(v_stale_empty_submit_chunk_count, 0),
      'request_sent_no_response_count', COALESCE(v_request_sent_no_response_count, 0),
      'unfinalised_submit_chunk', v_unfinalised_submit_chunk,
      'chunk_lock_expired', COALESCE(v_chunk_lock_expired, false),
      'chunk_started_at_utc', v_chunk_started_at_utc,
      'chunk_completed_at_utc', v_chunk_completed_at_utc,
      'chunk_lock_expires_at_utc', v_chunk_lock_expires_at_utc,
      'manual_resolution_required', v_manual_resolution_required,
      'safe_retry_available', v_safe_retry_available,
      'automatic_retry_blocked', v_automatic_retry_blocked,
      'retry_blocked_reason', v_retry_blocked_reason,
      'recommended_action', v_recommended_action
    )
    || jsonb_build_object(
      'pay_batch_id', CASE WHEN v_effective_pay_batch_id IS NULL THEN NULL ELSE v_effective_pay_batch_id::text END,
      'operation_id', v_diagnostic_operation_id,
      'operation_ids', COALESCE(v_current_operation_ids, '[]'::jsonb),
      'related_operation_ids', COALESCE(v_related_operation_ids, '[]'::jsonb),
      'chunk_id', v_primary_chunk_id,
      'chunk_ids', v_chunk_ids,
      'transfer_id', v_primary_transfer_id,
      'transfer_ids', v_transfer_ids,
      'transfer_scope_id', v_primary_transfer_scope_id,
      'transfer_scope_ids', v_transfer_scope_ids,
      'auth_request_id', v_primary_auth_request_id,
      'auth_request_ids', v_auth_request_ids,
      'rail_provider', v_primary_rail_provider,
      'rail_env', v_primary_rail_env,
      'rail_tx_id', v_primary_rail_tx_id,
      'rail_state', v_primary_rail_state,
      'provider_transaction_id', v_primary_provider_transaction_id,
      'provider_reference', v_primary_provider_reference,
      'provider_state', v_primary_provider_state,
      'request_id', v_primary_request_id,
      'idempotency_key', v_primary_idempotency_key,
      'local_provider_request_id', v_primary_local_provider_request_id,
      'provider_http_status', v_primary_provider_http_status,
      'provider_error_code', v_primary_provider_error_code,
      'provider_error_message_redacted', v_primary_provider_error_message_redacted,
      'provider_response_redacted', v_primary_provider_response_redacted,
      'provider_error_redacted', v_primary_provider_error_redacted
    );
    RETURN jsonb_build_object(
      'ok', true,
      'provider_submit_diagnostic', v_provider_submit_diagnostic,
      'provider_submission_status', v_provider_submission_status,
      'review_reason_code', v_review_reason_code,
      'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
      'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
      'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
      'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
      'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
      'stale_empty_submit_chunk_count', COALESCE(v_stale_empty_submit_chunk_count, 0),
      'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
      'manual_resolution_required', v_manual_resolution_required,
      'safe_retry_available', v_safe_retry_available,
      'recommended_action', v_recommended_action,
      'mixed_provider_submit_outcome', COALESCE(v_mixed_provider_submit_outcome, false),
      'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
      'counts', v_counts,
      'ids', v_ids,
      'chunk_ids', COALESCE(v_chunk_ids, '[]'::jsonb),
      'transfer_ids', COALESCE(v_transfer_ids, '[]'::jsonb),
      'provider_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_attempt_or_evidence_count', COALESCE(v_provider_request_sent_count, 0) + COALESCE(v_provider_response_present_count, 0) + COALESCE(v_provider_acceptance_evidence_count, 0),
      'attempted_but_unproven_count', COALESCE(v_provider_submission_unknown_count, 0),
      'counts_only', true,
      'exact_scope_mode', true
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_diagnostic_operations;
  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_diagnostic_chunks;
  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids;
  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_diagnostic_transfers;
  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_diagnostic_sources;
  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_diagnostic_transfer_flags;
  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_diagnostic_chunk_flags;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_diagnostic_operations (
    operation_id uuid PRIMARY KEY,
    pay_batch_id uuid,
    operation_status text,
    operation_phase text,
    progress_json jsonb,
    result_json jsonb,
    error_json jsonb,
    created_at_utc timestamptz,
    updated_at_utc timestamptz
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_operations (
    operation_id,
    pay_batch_id,
    operation_status,
    operation_phase,
    progress_json,
    result_json,
    error_json,
    created_at_utc,
    updated_at_utc
  )
  SELECT operation_row.id,
         operation_row.pay_batch_id,
         operation_row.status,
         operation_row.phase,
         COALESCE(operation_row.progress_json, '{}'::jsonb),
         operation_row.result_json,
         operation_row.error_json,
         operation_row.created_at_utc,
         operation_row.updated_at_utc
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.operation_type IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
    AND (
      (p_operation_id IS NOT NULL AND operation_row.id = p_operation_id)
      OR (v_effective_pay_batch_id IS NOT NULL AND operation_row.pay_batch_id = v_effective_pay_batch_id)
      OR (p_chunk_id IS NOT NULL AND EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_chunks AS chunk_filter
        WHERE chunk_filter.id = p_chunk_id
          AND chunk_filter.operation_id = operation_row.id
      ))
    )
  ON CONFLICT (operation_id) DO NOTHING;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_diagnostic_chunks (
    chunk_id uuid PRIMARY KEY,
    operation_id uuid NOT NULL,
    pay_batch_id uuid,
    phase text NOT NULL,
    chunk_type text NOT NULL,
    sequence_no integer NOT NULL,
    status text NOT NULL,
    payload_json jsonb NOT NULL,
    result_json jsonb,
    error_json jsonb,
    unit_count integer NOT NULL,
    completed_count integer NOT NULL,
    failed_count integer NOT NULL,
    locked_by text,
    lock_expires_at_utc timestamptz,
    created_at_utc timestamptz NOT NULL,
    started_at_utc timestamptz,
    completed_at_utc timestamptz,
    updated_at_utc timestamptz NOT NULL
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_chunks (
    chunk_id,
    operation_id,
    pay_batch_id,
    phase,
    chunk_type,
    sequence_no,
    status,
    payload_json,
    result_json,
    error_json,
    unit_count,
    completed_count,
    failed_count,
    locked_by,
    lock_expires_at_utc,
    created_at_utc,
    started_at_utc,
    completed_at_utc,
    updated_at_utc
  )
  SELECT chunk_row.id,
         chunk_row.operation_id,
         operation_row.pay_batch_id,
         chunk_row.phase,
         chunk_row.chunk_type,
         chunk_row.sequence_no,
         chunk_row.status,
         COALESCE(chunk_row.payload_json, '{}'::jsonb),
         chunk_row.result_json,
         chunk_row.error_json,
         chunk_row.unit_count,
         chunk_row.completed_count,
         chunk_row.failed_count,
         chunk_row.locked_by,
         chunk_row.lock_expires_at_utc,
         chunk_row.created_at_utc,
         chunk_row.started_at_utc,
         chunk_row.completed_at_utc,
         chunk_row.updated_at_utc
  FROM public.banking_pay_operation_chunks AS chunk_row
  JOIN public.banking_pay_operations AS operation_row
    ON operation_row.id = chunk_row.operation_id
  WHERE operation_row.operation_type IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
    AND (chunk_row.phase = 'SUBMIT_PROVIDER_TRANSFERS' OR chunk_row.chunk_type = 'TRANSFER_SUBMIT')
    AND (
      (p_chunk_id IS NOT NULL AND chunk_row.id = p_chunk_id)
      OR (p_operation_id IS NOT NULL AND chunk_row.operation_id = p_operation_id)
      OR EXISTS (
        SELECT 1
        FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation
        WHERE selected_operation.operation_id = chunk_row.operation_id
      )
    )
  ON CONFLICT (chunk_id) DO NOTHING;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids (
    chunk_id uuid NOT NULL,
    transfer_id uuid NOT NULL,
    PRIMARY KEY (chunk_id, transfer_id)
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids (chunk_id, transfer_id)
  SELECT DISTINCT selected_chunk.chunk_id,
                  transfer_id_text.value::uuid
  FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
  CROSS JOIN LATERAL jsonb_array_elements_text(
    CASE
      WHEN jsonb_typeof(selected_chunk.payload_json->'transfer_ids') = 'array' THEN selected_chunk.payload_json->'transfer_ids'
      ELSE '[]'::jsonb
    END
  ) AS transfer_id_text(value)
  WHERE transfer_id_text.value ~* v_uuid_regex
  ON CONFLICT DO NOTHING;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids (chunk_id, transfer_id)
  SELECT DISTINCT selected_chunk.chunk_id,
                  transfer_id_text.value::uuid
  FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
  CROSS JOIN LATERAL jsonb_array_elements(
    CASE
      WHEN jsonb_typeof(selected_chunk.payload_json->'transfers') = 'array' THEN selected_chunk.payload_json->'transfers'
      ELSE '[]'::jsonb
    END
  ) AS transfer_payload(value)
  CROSS JOIN LATERAL (
    SELECT COALESCE(
      NULLIF(BTRIM(COALESCE(transfer_payload.value->>'pay_bank_transfer_id', '')), ''),
      NULLIF(BTRIM(COALESCE(transfer_payload.value->>'transfer_id', '')), '')
    ) AS value
  ) AS transfer_id_text
  WHERE transfer_id_text.value ~* v_uuid_regex
  ON CONFLICT DO NOTHING;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_diagnostic_transfers (
    transfer_id uuid PRIMARY KEY,
    pay_batch_id uuid NOT NULL,
    status text NOT NULL,
    rail_provider text NOT NULL,
    rail_env text NOT NULL,
    request_id text,
    rail_tx_id text,
    rail_state text,
    rail_meta_json jsonb,
    payment_reference text,
    created_at_utc timestamptz NOT NULL
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_transfers (
    transfer_id,
    pay_batch_id,
    status,
    rail_provider,
    rail_env,
    request_id,
    rail_tx_id,
    rail_state,
    rail_meta_json,
    payment_reference,
    created_at_utc
  )
  SELECT transfer_row.id,
         transfer_row.pay_batch_id,
         transfer_row.status,
         transfer_row.rail_provider,
         transfer_row.rail_env,
         transfer_row.request_id,
         transfer_row.rail_tx_id,
         transfer_row.rail_state,
         transfer_row.rail_meta_json,
         transfer_row.payment_reference,
         transfer_row.created_at_utc
  FROM public.pay_bank_transfers AS transfer_row
  WHERE (p_transfer_id IS NOT NULL AND transfer_row.id = p_transfer_id)
     OR EXISTS (
       SELECT 1
       FROM pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids AS selected_chunk_transfer
       WHERE selected_chunk_transfer.transfer_id = transfer_row.id
     )
     OR (
       p_transfer_id IS NULL
       AND p_chunk_id IS NULL
       AND v_effective_pay_batch_id IS NOT NULL
       AND transfer_row.pay_batch_id = v_effective_pay_batch_id
     )
  ON CONFLICT (transfer_id) DO NOTHING;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_diagnostic_sources (
    source_type text NOT NULL,
    operation_id uuid,
    chunk_id uuid,
    transfer_id uuid,
    event_id uuid,
    diagnostic jsonb NOT NULL,
    provider_submission_status text,
    review_reason_code text,
    provider_call_stage text,
    provider_submission_attempted boolean NOT NULL DEFAULT false,
    provider_request_sent boolean NOT NULL DEFAULT false,
    provider_response_received boolean NOT NULL DEFAULT false,
    provider_response_present boolean NOT NULL DEFAULT false,
    provider_submission_accepted boolean NOT NULL DEFAULT false,
    provider_submission_rejected boolean NOT NULL DEFAULT false,
    provider_submission_failed boolean NOT NULL DEFAULT false,
    provider_submission_unknown boolean NOT NULL DEFAULT false,
    provider_acceptance_evidence_present boolean NOT NULL DEFAULT false,
    manual_resolution_required boolean NOT NULL DEFAULT false,
    safe_retry_available boolean NOT NULL DEFAULT false,
    provider_http_status text,
    provider_error_code text,
    provider_error_message_redacted text,
    provider_transaction_id text,
    provider_reference text,
    provider_state text,
    rail_tx_id text,
    rail_state text,
    request_id text,
    idempotency_key text,
    local_provider_request_id text,
    provider_response_redacted jsonb,
    provider_error_redacted jsonb
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_sources (
    source_type,
    operation_id,
    chunk_id,
    transfer_id,
    event_id,
    diagnostic,
    provider_submission_status,
    review_reason_code,
    provider_call_stage,
    provider_submission_attempted,
    provider_request_sent,
    provider_response_received,
    provider_response_present,
    provider_submission_accepted,
    provider_submission_rejected,
    provider_submission_failed,
    provider_submission_unknown,
    provider_acceptance_evidence_present,
    manual_resolution_required,
    safe_retry_available,
    provider_http_status,
    provider_error_code,
    provider_error_message_redacted,
    provider_transaction_id,
    provider_reference,
    provider_state,
    rail_tx_id,
    rail_state,
    request_id,
    idempotency_key,
    local_provider_request_id,
    provider_response_redacted,
    provider_error_redacted
  )
  WITH raw_diagnostics AS (
    SELECT 'operation_progress'::text AS source_type,
           selected_operation.operation_id,
           NULL::uuid AS chunk_id,
           NULL::uuid AS transfer_id,
           NULL::uuid AS event_id,
           selected_operation.progress_json->'provider_submit_diagnostic' AS diagnostic
    FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation
    WHERE jsonb_typeof(selected_operation.progress_json->'provider_submit_diagnostic') = 'object'
    UNION ALL
    SELECT 'operation_result'::text,
           selected_operation.operation_id,
           NULL::uuid,
           NULL::uuid,
           NULL::uuid,
           selected_operation.result_json->'provider_submit_diagnostic'
    FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation
    WHERE jsonb_typeof(selected_operation.result_json->'provider_submit_diagnostic') = 'object'
    UNION ALL
    SELECT 'operation_error'::text,
           selected_operation.operation_id,
           NULL::uuid,
           NULL::uuid,
           NULL::uuid,
           selected_operation.error_json->'provider_submit_diagnostic'
    FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation
    WHERE jsonb_typeof(selected_operation.error_json->'provider_submit_diagnostic') = 'object'
    UNION ALL
    SELECT 'chunk_result'::text,
           selected_chunk.operation_id,
           selected_chunk.chunk_id,
           selected_chunk_transfer.transfer_id,
           NULL::uuid,
           selected_chunk.result_json->'provider_submit_diagnostic'
    FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
    LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids AS selected_chunk_transfer
      ON selected_chunk_transfer.chunk_id = selected_chunk.chunk_id
    WHERE jsonb_typeof(selected_chunk.result_json->'provider_submit_diagnostic') = 'object'
    UNION ALL
    SELECT 'chunk_error'::text,
           selected_chunk.operation_id,
           selected_chunk.chunk_id,
           selected_chunk_transfer.transfer_id,
           NULL::uuid,
           selected_chunk.error_json->'provider_submit_diagnostic'
    FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
    LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids AS selected_chunk_transfer
      ON selected_chunk_transfer.chunk_id = selected_chunk.chunk_id
    WHERE jsonb_typeof(selected_chunk.error_json->'provider_submit_diagnostic') = 'object'
    UNION ALL
    SELECT 'transfer_meta'::text,
           NULL::uuid,
           NULL::uuid,
           selected_transfer.transfer_id,
           NULL::uuid,
           selected_transfer.rail_meta_json->'provider_submit_diagnostic'
    FROM pg_temp.tmp_provider_submit_diagnostic_transfers AS selected_transfer
    WHERE jsonb_typeof(selected_transfer.rail_meta_json->'provider_submit_diagnostic') = 'object'
    UNION ALL
    SELECT 'transfer_event'::text,
           NULL::uuid,
           NULL::uuid,
           transfer_event.pay_bank_transfer_id,
           transfer_event.id,
           transfer_event.raw_payload->'provider_submit_diagnostic'
    FROM public.pay_bank_transfer_events AS transfer_event
    WHERE jsonb_typeof(transfer_event.raw_payload->'provider_submit_diagnostic') = 'object'
      AND EXISTS (
        SELECT 1
        FROM pg_temp.tmp_provider_submit_diagnostic_transfers AS selected_transfer
        WHERE selected_transfer.transfer_id = transfer_event.pay_bank_transfer_id
      )
  )
  SELECT raw_diagnostics.source_type,
         raw_diagnostics.operation_id,
         raw_diagnostics.chunk_id,
         raw_diagnostics.transfer_id,
         raw_diagnostics.event_id,
         raw_diagnostics.diagnostic,
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_submission_status', raw_diagnostics.diagnostic->>'outcome_code', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'review_reason_code', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_call_stage', '')), ''),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_submission_attempted', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_request_sent', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_response_received', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_response_present', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_submission_accepted', raw_diagnostics.diagnostic->>'provider_accepted', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_submission_rejected', raw_diagnostics.diagnostic->>'provider_rejected', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_submission_failed', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_submission_unknown', raw_diagnostics.diagnostic->>'provider_unknown', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_acceptance_evidence_present', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'manual_resolution_required', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'safe_retry_available', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_http_status', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_error_code', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_error_message_redacted', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_transaction_id', raw_diagnostics.diagnostic->>'provider_payment_id', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_reference', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_state', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'rail_tx_id', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'rail_state', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'request_id', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'idempotency_key', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'local_provider_request_id', '')), ''),
         raw_diagnostics.diagnostic->'provider_response_redacted',
         raw_diagnostics.diagnostic->'provider_error_redacted'
  FROM raw_diagnostics
  WHERE jsonb_typeof(raw_diagnostics.diagnostic) = 'object'
    AND raw_diagnostics.diagnostic <> '{}'::jsonb;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_diagnostic_transfer_flags (
    transfer_id uuid PRIMARY KEY,
    has_provider_acceptance_evidence boolean NOT NULL DEFAULT false,
    has_provider_response boolean NOT NULL DEFAULT false,
    has_provider_request_sent boolean NOT NULL DEFAULT false,
    has_provider_rejection boolean NOT NULL DEFAULT false,
    has_provider_unknown boolean NOT NULL DEFAULT false,
    has_provider_blocked_pre_call boolean NOT NULL DEFAULT false,
    has_provider_malformed_response boolean NOT NULL DEFAULT false
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_transfer_flags (
    transfer_id,
    has_provider_acceptance_evidence,
    has_provider_response,
    has_provider_request_sent,
    has_provider_rejection,
    has_provider_unknown,
    has_provider_blocked_pre_call,
    has_provider_malformed_response
  )
  SELECT selected_transfer.transfer_id,
         (
           (
             NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '') IS NOT NULL
             AND NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '') <> selected_transfer.transfer_id::text
             AND NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.request_id, '')), ''), '__NO_REQUEST_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__')
             AND UPPER(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
           )
           OR COALESCE(BOOL_OR(
             NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') IS NOT NULL
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> selected_transfer.transfer_id::text
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN selected_source.operation_id IS NULL THEN NULL::text ELSE selected_source.operation_id::text END, '__NO_SOURCE_OPERATION_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN selected_source.chunk_id IS NULL THEN NULL::text ELSE selected_source.chunk_id::text END, '__NO_SOURCE_CHUNK_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.request_id, '')), ''), '__NO_REQUEST_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
             AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
             AND selected_source.provider_submission_rejected IS NOT TRUE
             AND selected_source.provider_submission_failed IS NOT TRUE
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__')
           ), false)
           OR COALESCE(BOOL_OR(
             NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') IS NOT NULL
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> selected_transfer.transfer_id::text
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN selected_source.operation_id IS NULL THEN NULL::text ELSE selected_source.operation_id::text END, '__NO_SOURCE_OPERATION_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN selected_source.chunk_id IS NULL THEN NULL::text ELSE selected_source.chunk_id::text END, '__NO_SOURCE_CHUNK_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.request_id, '')), ''), '__NO_REQUEST_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
             AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
             AND selected_source.provider_submission_rejected IS NOT TRUE
             AND selected_source.provider_submission_failed IS NOT TRUE
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__')
           ), false)
           OR COALESCE(BOOL_OR(
                upper(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')
                AND upper(BTRIM(COALESCE(transfer_event.normalised_state, transfer_event.provider_state, ''))) NOT IN ('REJECTED', 'FAILED', 'ERROR', 'DECLINED', 'CANCELLED', 'CANCELED', 'MALFORMED', 'UNKNOWN')
                AND EXISTS (
                  SELECT 1
                  FROM (VALUES
                    (transfer_event.provider_event_id),
                    (transfer_event.provider_reference),
                    (transfer_event.raw_payload #>> '{provider_transaction_id}'),
                    (transfer_event.raw_payload #>> '{provider_payment_id}'),
                    (transfer_event.raw_payload #>> '{payment_id}'),
                    (transfer_event.raw_payload #>> '{external_payment_id}'),
                    (transfer_event.raw_payload #>> '{revolut_payment_id}'),
                    (transfer_event.raw_payload #>> '{rail_tx_id}'),
                    (transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_transaction_id}'),
                    (transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_payment_id}'),
                    (transfer_event.raw_payload #>> '{provider_submit_diagnostic,rail_tx_id}'),
                    (transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_reference}')
                  ) AS provider_identifier(identifier_value)
                  WHERE NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') IS NOT NULL
                    AND NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') <> selected_transfer.transfer_id::text
                    AND NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
                    AND NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__')
                    AND NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.request_id, '')), ''), '__NO_REQUEST_ID__')
                    AND NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__')
                    AND NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(transfer_event.idempotency_key, '')), ''), '__NO_EVENT_IDEMPOTENCY_KEY__')
                )
              ), false)
         ),
         (
           COALESCE(BOOL_OR(selected_source.provider_response_received OR selected_source.provider_response_present), false)
           OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')), false)
           OR COALESCE(BOOL_OR(
             NULLIF(BTRIM(COALESCE(selected_source.provider_http_status, selected_source.provider_error_code, '')), '') IS NOT NULL
             AND NOT (
               UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
               AND selected_source.provider_submission_attempted IS NOT TRUE
               AND selected_source.provider_request_sent IS NOT TRUE
               AND selected_source.provider_response_received IS NOT TRUE
               AND selected_source.provider_response_present IS NOT TRUE
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, selected_source.provider_reference, '')), '') IS NULL
               AND UPPER(BTRIM(COALESCE(selected_source.provider_error_code, ''))) IN ('PROVIDER_SUBMIT_STAGE_RECORD_FAILED', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL')
             )
           ), false)
           OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')), false)
         ),
         (
           COALESCE(BOOL_OR(selected_source.provider_request_sent), false)
           OR COALESCE(BOOL_OR(selected_source.provider_response_received OR selected_source.provider_response_present), false)
           OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME')), false)
           OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')), false)
           OR NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '') IS NOT NULL
         ),
         (
           COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED')), false)
           OR COALESCE(BOOL_OR(selected_source.provider_submission_rejected
             OR (
               selected_source.provider_submission_failed
               AND NOT (
                 upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
                 AND selected_source.provider_submission_attempted IS NOT TRUE
                 AND selected_source.provider_request_sent IS NOT TRUE
                 AND selected_source.provider_response_received IS NOT TRUE
                 AND selected_source.provider_response_present IS NOT TRUE
                 AND selected_source.provider_submission_accepted IS NOT TRUE
                 AND selected_source.provider_submission_rejected IS NOT TRUE
                 AND selected_source.provider_submission_unknown IS NOT TRUE
                 AND selected_source.provider_acceptance_evidence_present IS NOT TRUE
                 AND NULLIF(BTRIM(COALESCE(
                   selected_source.provider_transaction_id,
                   selected_source.rail_tx_id,
                   selected_source.provider_reference,
                   selected_source.provider_state,
                   selected_source.provider_http_status,
                   ''
                 )), '') IS NULL
                 AND (
                   NULLIF(BTRIM(COALESCE(selected_source.provider_error_code, '')), '') IS NULL
                   OR upper(BTRIM(COALESCE(selected_source.provider_error_code, ''))) IN (
                     'PROVIDER_SUBMIT_STAGE_RECORD_FAILED',
                     'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'
                   )
                 )
               )
             )), false)
           OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(transfer_event.normalised_state, transfer_event.provider_state, ''))) IN ('REJECTED', 'FAILED', 'ERROR', 'DECLINED', 'CANCELLED', 'CANCELED')), false)
           OR COALESCE(BOOL_OR(CASE WHEN NULLIF(BTRIM(COALESCE(selected_source.provider_http_status, '')), '') ~ '^[0-9]+$' THEN selected_source.provider_http_status::integer >= 400 ELSE false END), false)
         ),
         (
           COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')), false)
           OR COALESCE(BOOL_OR(selected_source.provider_submission_unknown), false)
         ),
         (
           COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'), false)
           OR COALESCE(BOOL_OR(
             upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'NO_PROVIDER_SUBMISSION_ATTEMPTED'
             AND selected_source.provider_submission_attempted IS FALSE
             AND selected_source.provider_request_sent IS FALSE
             AND selected_source.provider_response_received IS FALSE
             AND selected_source.provider_response_present IS FALSE
           ), false)
         ),
         (
           COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE'), false)
         )
  FROM pg_temp.tmp_provider_submit_diagnostic_transfers AS selected_transfer
  LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_sources AS selected_source
    ON selected_source.transfer_id = selected_transfer.transfer_id
  LEFT JOIN public.pay_bank_transfer_events AS transfer_event
    ON transfer_event.pay_bank_transfer_id = selected_transfer.transfer_id
  GROUP BY selected_transfer.transfer_id,
           selected_transfer.request_id,
           selected_transfer.payment_reference,
           selected_transfer.rail_tx_id
  ON CONFLICT (transfer_id) DO NOTHING;

  UPDATE pg_temp.tmp_provider_submit_diagnostic_transfer_flags AS transfer_flag_update
  SET has_provider_unknown = true
  WHERE transfer_flag_update.has_provider_request_sent IS TRUE
    AND transfer_flag_update.has_provider_response IS NOT TRUE
    AND transfer_flag_update.has_provider_acceptance_evidence IS NOT TRUE;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_diagnostic_chunk_flags (
    chunk_id uuid PRIMARY KEY,
    has_provider_acceptance_evidence boolean NOT NULL DEFAULT false,
    has_provider_response boolean NOT NULL DEFAULT false,
    has_provider_request_sent boolean NOT NULL DEFAULT false,
    has_provider_rejection boolean NOT NULL DEFAULT false,
    has_provider_unknown boolean NOT NULL DEFAULT false,
    has_provider_blocked_pre_call boolean NOT NULL DEFAULT false,
    has_provider_malformed_response boolean NOT NULL DEFAULT false,
    has_durable_provider_request_impossible boolean NOT NULL DEFAULT false,
    is_stale_unresolved boolean NOT NULL DEFAULT false,
    is_stale_request_sent_no_response boolean NOT NULL DEFAULT false,
    is_stale_claim_or_pre_call_only boolean NOT NULL DEFAULT false
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_chunk_flags (
    chunk_id,
    has_provider_acceptance_evidence,
    has_provider_response,
    has_provider_request_sent,
    has_provider_rejection,
    has_provider_unknown,
    has_provider_blocked_pre_call,
    has_provider_malformed_response,
    has_durable_provider_request_impossible,
    is_stale_unresolved,
    is_stale_request_sent_no_response,
    is_stale_claim_or_pre_call_only
  )
  SELECT chunk_eval.chunk_id,
         chunk_eval.has_provider_acceptance_evidence,
         chunk_eval.has_provider_response,
         chunk_eval.has_provider_request_sent,
         chunk_eval.has_provider_rejection,
         chunk_eval.has_provider_unknown OR (chunk_eval.is_stale_unresolved AND chunk_eval.has_provider_request_sent),
         chunk_eval.has_provider_blocked_pre_call,
         chunk_eval.has_provider_malformed_response,
         chunk_eval.has_durable_provider_request_impossible,
         chunk_eval.is_stale_unresolved,
         chunk_eval.is_stale_unresolved AND chunk_eval.has_provider_request_sent,
         chunk_eval.is_stale_unresolved AND chunk_eval.has_provider_request_sent IS NOT TRUE
  FROM (
    SELECT selected_chunk.chunk_id,
           (
             COALESCE(BOOL_OR(transfer_flag.has_provider_acceptance_evidence), false)
             OR COALESCE(BOOL_OR(
               NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(selected_source.chunk_id::text, '__NO_CHUNK_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN selected_source.operation_id IS NULL THEN NULL::text ELSE selected_source.operation_id::text END, '__NO_SOURCE_OPERATION_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN selected_source.chunk_id IS NULL THEN NULL::text ELSE selected_source.chunk_id::text END, '__NO_SOURCE_CHUNK_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.request_id, '')), ''), '__NO_REQUEST_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
               AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
               AND selected_source.provider_submission_rejected IS NOT TRUE
               AND selected_source.provider_submission_failed IS NOT TRUE
             ), false)
             OR COALESCE(BOOL_OR(
               NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(selected_source.chunk_id::text, '__NO_CHUNK_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN selected_source.operation_id IS NULL THEN NULL::text ELSE selected_source.operation_id::text END, '__NO_SOURCE_OPERATION_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN selected_source.chunk_id IS NULL THEN NULL::text ELSE selected_source.chunk_id::text END, '__NO_SOURCE_CHUNK_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.request_id, '')), ''), '__NO_REQUEST_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
               AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
               AND selected_source.provider_submission_rejected IS NOT TRUE
               AND selected_source.provider_submission_failed IS NOT TRUE
             ), false)
           ) AS has_provider_acceptance_evidence,
           (
             COALESCE(BOOL_OR(transfer_flag.has_provider_response), false)
             OR COALESCE(BOOL_OR(selected_source.provider_response_received OR selected_source.provider_response_present), false)
             OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')), false)
             OR COALESCE(BOOL_OR(
             NULLIF(BTRIM(COALESCE(selected_source.provider_http_status, selected_source.provider_error_code, '')), '') IS NOT NULL
             AND NOT (
               UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
               AND selected_source.provider_submission_attempted IS NOT TRUE
               AND selected_source.provider_request_sent IS NOT TRUE
               AND selected_source.provider_response_received IS NOT TRUE
               AND selected_source.provider_response_present IS NOT TRUE
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, selected_source.provider_reference, '')), '') IS NULL
               AND UPPER(BTRIM(COALESCE(selected_source.provider_error_code, ''))) IN ('PROVIDER_SUBMIT_STAGE_RECORD_FAILED', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL')
             )
           ), false)
           ) AS has_provider_response,
           (
             COALESCE(BOOL_OR(transfer_flag.has_provider_request_sent), false)
             OR COALESCE(BOOL_OR(selected_source.provider_request_sent), false)
             OR COALESCE(BOOL_OR(selected_source.provider_response_received OR selected_source.provider_response_present), false)
             OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE')), false)
             OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_call_stage, ''))) IN ('PROVIDER_PAYMENT_CREATE_REQUEST_SENT', 'PROVIDER_PAYMENT_CREATE_RESPONSE_RECEIVED', 'PROVIDER_PAYMENT_CREATE_ACCEPTED', 'PROVIDER_PAYMENT_CREATE_REJECTED', 'PROVIDER_PAYMENT_CREATE_UNKNOWN', 'PROVIDER_PAYMENT_CREATE_MALFORMED', 'RAIL_UPDATE_APPLY_STARTED', 'RAIL_UPDATE_APPLY_FAILED')), false)
           ) AS has_provider_request_sent,
           (
             COALESCE(BOOL_OR(transfer_flag.has_provider_rejection), false)
             OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED')), false)
             OR COALESCE(BOOL_OR(selected_source.provider_submission_rejected
             OR (
               selected_source.provider_submission_failed
               AND NOT (
                 upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
                 AND selected_source.provider_submission_attempted IS NOT TRUE
                 AND selected_source.provider_request_sent IS NOT TRUE
                 AND selected_source.provider_response_received IS NOT TRUE
                 AND selected_source.provider_response_present IS NOT TRUE
                 AND selected_source.provider_submission_accepted IS NOT TRUE
                 AND selected_source.provider_submission_rejected IS NOT TRUE
                 AND selected_source.provider_submission_unknown IS NOT TRUE
                 AND selected_source.provider_acceptance_evidence_present IS NOT TRUE
                 AND NULLIF(BTRIM(COALESCE(
                   selected_source.provider_transaction_id,
                   selected_source.rail_tx_id,
                   selected_source.provider_reference,
                   selected_source.provider_state,
                   selected_source.provider_http_status,
                   ''
                 )), '') IS NULL
                 AND (
                   NULLIF(BTRIM(COALESCE(selected_source.provider_error_code, '')), '') IS NULL
                   OR upper(BTRIM(COALESCE(selected_source.provider_error_code, ''))) IN (
                     'PROVIDER_SUBMIT_STAGE_RECORD_FAILED',
                     'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'
                   )
                 )
               )
             )), false)
             OR COALESCE(BOOL_OR(CASE WHEN NULLIF(BTRIM(COALESCE(selected_source.provider_http_status, '')), '') ~ '^[0-9]+$' THEN selected_source.provider_http_status::integer >= 400 ELSE false END), false)
           ) AS has_provider_rejection,
           (
             COALESCE(BOOL_OR(transfer_flag.has_provider_unknown), false)
             OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')), false)
             OR COALESCE(BOOL_OR(selected_source.provider_submission_unknown), false)
           ) AS has_provider_unknown,
           (
             COALESCE(BOOL_OR(transfer_flag.has_provider_blocked_pre_call), false)
             OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'), false)
           ) AS has_provider_blocked_pre_call,
           (
             COALESCE(BOOL_OR(transfer_flag.has_provider_malformed_response), false)
             OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE'), false)
           ) AS has_provider_malformed_response,
           COALESCE(BOOL_OR(
             lower(BTRIM(COALESCE(selected_source.diagnostic->>'provider_request_impossible', selected_source.diagnostic->>'durable_provider_request_impossible', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
           ), false) AS has_durable_provider_request_impossible,
           (
             upper(BTRIM(COALESCE(selected_chunk.status, ''))) = 'RUNNING'
             AND upper(BTRIM(COALESCE(selected_chunk.chunk_type, ''))) = 'TRANSFER_SUBMIT'
             AND selected_chunk.completed_at_utc IS NULL
             AND (selected_chunk.lock_expires_at_utc IS NULL OR selected_chunk.lock_expires_at_utc < v_now)
             AND NOT (
               COALESCE(BOOL_OR(transfer_flag.has_provider_acceptance_evidence), false)
               OR COALESCE(BOOL_OR(
                 NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') IS NOT NULL
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(selected_source.chunk_id::text, '__NO_CHUNK_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN selected_source.operation_id IS NULL THEN NULL::text ELSE selected_source.operation_id::text END, '__NO_SOURCE_OPERATION_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID_PARAM__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.request_id, '')), ''), '__NO_REQUEST_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
                 AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
                 AND selected_source.provider_submission_rejected IS NOT TRUE
                 AND selected_source.provider_submission_failed IS NOT TRUE
               ), false)
               OR COALESCE(BOOL_OR(
                 NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') IS NOT NULL
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(selected_source.chunk_id::text, '__NO_CHUNK_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN selected_source.operation_id IS NULL THEN NULL::text ELSE selected_source.operation_id::text END, '__NO_SOURCE_OPERATION_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID_PARAM__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.request_id, '')), ''), '__NO_REQUEST_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
                 AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
                 AND selected_source.provider_submission_rejected IS NOT TRUE
                 AND selected_source.provider_submission_failed IS NOT TRUE
               ), false)
             )
             AND NOT (
               COALESCE(BOOL_OR(transfer_flag.has_provider_response), false)
               OR COALESCE(BOOL_OR(selected_source.provider_response_received OR selected_source.provider_response_present), false)
               OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')), false)
               OR COALESCE(BOOL_OR(
             NULLIF(BTRIM(COALESCE(selected_source.provider_http_status, selected_source.provider_error_code, '')), '') IS NOT NULL
             AND NOT (
               UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
               AND selected_source.provider_submission_attempted IS NOT TRUE
               AND selected_source.provider_request_sent IS NOT TRUE
               AND selected_source.provider_response_received IS NOT TRUE
               AND selected_source.provider_response_present IS NOT TRUE
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, selected_source.provider_reference, '')), '') IS NULL
               AND UPPER(BTRIM(COALESCE(selected_source.provider_error_code, ''))) IN ('PROVIDER_SUBMIT_STAGE_RECORD_FAILED', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL')
             )
           ), false)
             )
             AND COALESCE(BOOL_OR(
               lower(BTRIM(COALESCE(selected_source.diagnostic->>'provider_request_impossible', selected_source.diagnostic->>'durable_provider_request_impossible', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
             ), false) IS NOT TRUE
           ) AS is_stale_unresolved
    FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
    LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids AS selected_chunk_transfer
      ON selected_chunk_transfer.chunk_id = selected_chunk.chunk_id
    LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_transfer_flags AS transfer_flag
      ON transfer_flag.transfer_id = selected_chunk_transfer.transfer_id
    LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_sources AS selected_source
      ON selected_source.chunk_id = selected_chunk.chunk_id
    GROUP BY selected_chunk.chunk_id,
             selected_chunk.status,
             selected_chunk.chunk_type,
             selected_chunk.completed_at_utc,
             selected_chunk.lock_expires_at_utc
  ) AS chunk_eval
  ON CONFLICT (chunk_id) DO NOTHING;

  SELECT COUNT(*)::integer INTO v_operation_count FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation;
  SELECT COUNT(*)::integer INTO v_chunk_count FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk;
  SELECT COUNT(*)::integer INTO v_transfer_count FROM pg_temp.tmp_provider_submit_diagnostic_transfers AS selected_transfer;

  SELECT COUNT(*) FILTER (WHERE transfer_flag.has_provider_acceptance_evidence)::integer,
         COUNT(*) FILTER (WHERE transfer_flag.has_provider_response)::integer,
         COUNT(*) FILTER (WHERE transfer_flag.has_provider_request_sent)::integer,
         COUNT(*) FILTER (WHERE transfer_flag.has_provider_unknown)::integer,
         COUNT(*) FILTER (WHERE transfer_flag.has_provider_rejection)::integer,
         COUNT(*) FILTER (WHERE transfer_flag.has_provider_acceptance_evidence)::integer,
         COUNT(*) FILTER (WHERE transfer_flag.has_provider_blocked_pre_call)::integer,
         COUNT(*) FILTER (WHERE transfer_flag.has_provider_malformed_response)::integer
  INTO v_provider_acceptance_evidence_count,
       v_provider_response_present_count,
       v_provider_request_sent_count,
       v_provider_submission_unknown_count,
       v_provider_submission_rejected_count,
       v_provider_submission_accepted_count,
       v_provider_submission_blocked_pre_call_count,
       v_provider_submission_malformed_response_count
  FROM pg_temp.tmp_provider_submit_diagnostic_transfer_flags AS transfer_flag;

  SELECT GREATEST(COALESCE(v_provider_acceptance_evidence_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_acceptance_evidence), 0))::integer,
         GREATEST(COALESCE(v_provider_response_present_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_response), 0))::integer,
         GREATEST(COALESCE(v_provider_request_sent_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_request_sent), 0))::integer,
         GREATEST(COALESCE(v_provider_submission_unknown_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_unknown OR chunk_flag.is_stale_unresolved), 0))::integer,
         GREATEST(COALESCE(v_provider_submission_rejected_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_rejection), 0))::integer,
         GREATEST(COALESCE(v_provider_submission_accepted_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_acceptance_evidence), 0))::integer,
         GREATEST(COALESCE(v_provider_submission_blocked_pre_call_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_blocked_pre_call), 0))::integer,
         GREATEST(COALESCE(v_provider_submission_malformed_response_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_malformed_response), 0))::integer,
         COALESCE(COUNT(*) FILTER (WHERE chunk_flag.is_stale_unresolved), 0)::integer,
         COALESCE(COUNT(*) FILTER (WHERE chunk_flag.is_stale_request_sent_no_response), 0)::integer,
         COALESCE(COUNT(*) FILTER (WHERE upper(BTRIM(COALESCE(selected_chunk.status, ''))) = 'RUNNING'), 0)::integer,
         COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_chunk.status, ''))) = 'RUNNING' AND (selected_chunk.lock_expires_at_utc IS NULL OR selected_chunk.lock_expires_at_utc < v_now)), false)
  INTO v_provider_acceptance_evidence_count,
       v_provider_response_present_count,
       v_provider_request_sent_count,
       v_provider_submission_unknown_count,
       v_provider_submission_rejected_count,
       v_provider_submission_accepted_count,
       v_provider_submission_blocked_pre_call_count,
       v_provider_submission_malformed_response_count,
       v_stale_unresolved_submit_chunk_count,
       v_request_sent_no_response_count,
       v_unfinalised_submit_chunk_count,
       v_chunk_lock_expired
  FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
  LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_chunk_flags AS chunk_flag
    ON chunk_flag.chunk_id = selected_chunk.chunk_id;

  v_stale_empty_submit_chunk_count := COALESCE(v_stale_unresolved_submit_chunk_count, 0);

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_operation.operation_id::text) ORDER BY selected_operation.operation_id), '[]'::jsonb),
         MIN(selected_operation.operation_id::text)
  INTO v_operation_ids,
       v_primary_operation_id
  FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation;

  IF p_operation_id IS NOT NULL THEN
    v_diagnostic_operation_id := p_operation_id::text;
  ELSIF p_chunk_id IS NOT NULL THEN
    SELECT selected_chunk.operation_id::text
    INTO v_diagnostic_operation_id
    FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
    WHERE selected_chunk.chunk_id = p_chunk_id
    LIMIT 1;
  ELSE
    v_diagnostic_operation_id := NULL::text;
  END IF;

  IF v_diagnostic_operation_id IS NOT NULL THEN
    v_primary_operation_id := v_diagnostic_operation_id;
    v_current_operation_ids := jsonb_build_array(v_diagnostic_operation_id);

    SELECT COALESCE(jsonb_agg(to_jsonb(related_operation.value) ORDER BY related_operation.value), '[]'::jsonb)
    INTO v_related_operation_ids
    FROM (
      SELECT DISTINCT selected_operation.operation_id::text AS value
      FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation
      WHERE selected_operation.operation_id::text <> v_diagnostic_operation_id
    ) AS related_operation;
  ELSE
    v_current_operation_ids := '[]'::jsonb;
    v_related_operation_ids := COALESCE(v_operation_ids, '[]'::jsonb);
  END IF;

  SELECT COALESCE(BOOL_OR(UPPER(BTRIM(COALESCE(selected_operation.operation_status, ''))) = 'REVIEW_REQUIRED'), false)
  INTO v_operation_review_required
  FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation;

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_chunk.chunk_id::text) ORDER BY selected_chunk.chunk_id), '[]'::jsonb),
         MIN(selected_chunk.chunk_id::text),
         MIN(selected_chunk.started_at_utc)::text,
         MIN(selected_chunk.completed_at_utc)::text,
         MIN(selected_chunk.lock_expires_at_utc)::text
  INTO v_chunk_ids,
       v_primary_chunk_id,
       v_chunk_started_at_utc,
       v_chunk_completed_at_utc,
       v_chunk_lock_expires_at_utc
  FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk;

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_transfer.transfer_id::text) ORDER BY selected_transfer.transfer_id), '[]'::jsonb),
         MIN(selected_transfer.transfer_id::text),
         MIN(selected_transfer.rail_provider),
         MIN(selected_transfer.rail_env),
         MIN(NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '')),
         MIN(NULLIF(BTRIM(COALESCE(selected_transfer.rail_state, '')), '')),
         MIN(NULLIF(BTRIM(COALESCE(selected_transfer.request_id, '')), ''))
  INTO v_transfer_ids,
       v_primary_transfer_id,
       v_primary_rail_provider,
       v_primary_rail_env,
       v_primary_rail_tx_id,
       v_primary_rail_state,
       v_primary_request_id
  FROM pg_temp.tmp_provider_submit_diagnostic_transfers AS selected_transfer;

  SELECT selected_source.provider_transaction_id,
         selected_source.provider_reference,
         selected_source.provider_state,
         COALESCE(selected_source.request_id, v_primary_request_id),
         COALESCE(selected_source.idempotency_key, v_primary_request_id),
         selected_source.local_provider_request_id,
         selected_source.provider_http_status,
         selected_source.provider_error_code,
         selected_source.provider_error_message_redacted,
         selected_source.provider_response_redacted,
         selected_source.provider_error_redacted,
         COALESCE(selected_source.provider_call_stage, v_provider_call_stage)
  INTO v_primary_provider_transaction_id,
       v_primary_provider_reference,
       v_primary_provider_state,
       v_primary_request_id,
       v_primary_idempotency_key,
       v_primary_local_provider_request_id,
       v_primary_provider_http_status,
       v_primary_provider_error_code,
       v_primary_provider_error_message_redacted,
       v_primary_provider_response_redacted,
       v_primary_provider_error_redacted,
       v_provider_call_stage
  FROM pg_temp.tmp_provider_submit_diagnostic_sources AS selected_source
  WHERE NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.provider_reference, selected_source.provider_state, selected_source.provider_error_code, selected_source.request_id, selected_source.idempotency_key, selected_source.provider_call_stage, '')), '') IS NOT NULL
  ORDER BY CASE
             WHEN (
               NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.request_id, '')), ''), '__NO_REQUEST_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
               AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
               AND selected_source.provider_submission_rejected IS NOT TRUE
               AND selected_source.provider_submission_failed IS NOT TRUE
             ) OR (
               NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.request_id, '')), ''), '__NO_REQUEST_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
               AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
               AND selected_source.provider_submission_rejected IS NOT TRUE
               AND selected_source.provider_submission_failed IS NOT TRUE
             ) THEN 0
             WHEN selected_source.provider_response_present OR selected_source.provider_response_received THEN 1
             WHEN selected_source.provider_request_sent THEN 2
             ELSE 3
           END,
           selected_source.source_type
  LIMIT 1;

  IF v_primary_idempotency_key IS NULL THEN
    v_primary_idempotency_key := v_primary_request_id;
  END IF;

  IF v_primary_provider_reference IS NOT NULL
     AND v_primary_provider_reference IN (
       COALESCE(v_primary_request_id, '__NO_REQUEST_ID__'),
       COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__'),
       COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__'),
       COALESCE(v_primary_idempotency_key, '__NO_IDEMPOTENCY_KEY__'),
       COALESCE(v_primary_local_provider_request_id, '__NO_LOCAL_PROVIDER_REQUEST_ID__'),
       COALESCE(v_primary_transfer_id, '__NO_TRANSFER_ID__')
     ) THEN
    v_primary_provider_reference := NULL::text;
  END IF;

  IF v_primary_provider_transaction_id IS NOT NULL
     AND v_primary_provider_transaction_id IN (
       COALESCE(v_primary_request_id, '__NO_REQUEST_ID__'),
       COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__'),
       COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__'),
       COALESCE(v_primary_idempotency_key, '__NO_IDEMPOTENCY_KEY__'),
       COALESCE(v_primary_local_provider_request_id, '__NO_LOCAL_PROVIDER_REQUEST_ID__'),
       COALESCE(v_primary_transfer_id, '__NO_TRANSFER_ID__')
     ) THEN
    v_primary_provider_transaction_id := NULL::text;
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(scope_values.transfer_scope_id::text) ORDER BY scope_values.transfer_scope_id), '[]'::jsonb),
         MIN(scope_values.transfer_scope_id::text)
  INTO v_transfer_scope_ids,
       v_primary_transfer_scope_id
  FROM (
    SELECT DISTINCT transfer_scope.id AS transfer_scope_id
    FROM public.banking_pay_operation_transfer_scope AS transfer_scope
    WHERE (
        EXISTS (
          SELECT 1
          FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation
          WHERE selected_operation.operation_id = transfer_scope.operation_id
        )
        OR (v_effective_pay_batch_id IS NOT NULL AND transfer_scope.pay_batch_id = v_effective_pay_batch_id)
      )
      AND (p_transfer_id IS NULL OR transfer_scope.pay_bank_transfer_id = p_transfer_id)
  ) AS scope_values;

  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(to_jsonb(auth_values.auth_request_id::text) ORDER BY auth_values.auth_request_id), '[]'::jsonb),
         MIN(auth_values.auth_request_id::text)
  INTO v_active_auth_request_count,
       v_auth_request_ids,
       v_primary_auth_request_id
  FROM (
    SELECT DISTINCT auth_request.id AS auth_request_id
    FROM public.pay_batch_auth_requests AS auth_request
    WHERE v_effective_pay_batch_id IS NOT NULL
      AND auth_request.pay_batch_id = v_effective_pay_batch_id
      AND upper(BTRIM(COALESCE(auth_request.state, ''))) IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED')
      AND (p_operation_id IS NULL OR auth_request.execution_intent_json->>'operation_id' = p_operation_id::text)
  ) AS auth_values;

  IF p_operation_id IS NULL
     AND p_transfer_id IS NULL
     AND p_chunk_id IS NULL
     AND v_effective_pay_batch_id IS NOT NULL
     AND COALESCE(v_transfer_count, 0) = 0
     AND COALESCE(jsonb_array_length(v_transfer_ids), 0) = 0
     AND COALESCE(jsonb_array_length(v_transfer_scope_ids), 0) = 0
     AND COALESCE(v_active_auth_request_count, 0) = 0
     AND COALESCE(v_provider_acceptance_evidence_count, 0) = 0
     AND COALESCE(v_provider_response_present_count, 0) = 0
     AND COALESCE(v_provider_request_sent_count, 0) = 0
     AND COALESCE(v_provider_submission_unknown_count, 0) = 0
     AND COALESCE(v_stale_unresolved_submit_chunk_count, 0) = 0
     AND COALESCE(v_unfinalised_submit_chunk_count, 0) = 0
     AND COALESCE(v_provider_submission_rejected_count, 0) = 0
     AND COALESCE(v_provider_submission_malformed_response_count, 0) = 0
     AND COALESCE(v_provider_submission_blocked_pre_call_count, 0) > 0
     AND NOT EXISTS (
       SELECT 1
       FROM public.pay_bank_transfer_events AS batch_provider_event
       WHERE batch_provider_event.pay_batch_id = v_effective_pay_batch_id
         AND upper(BTRIM(COALESCE(batch_provider_event.event_source, ''))) IN (
           'PROVIDER_RESPONSE',
           'PROVIDER_POLL',
           'PROVIDER_WEBHOOK',
           'WEBHOOK',
           'POLL',
           'RAIL_PROVIDER',
           'PROVIDER',
           'PROVIDER_SETTLEMENT',
           'RAIL_PROVIDER_SETTLEMENT'
         )
     )
     AND NOT EXISTS (
       SELECT 1
       FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
       LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_chunk_flags AS selected_chunk_flag
         ON selected_chunk_flag.chunk_id = selected_chunk.chunk_id
       WHERE upper(BTRIM(COALESCE(selected_chunk.status, ''))) NOT IN ('COMPLETE', 'FAILED', 'SKIPPED', 'CANCELLED', 'CANCELED')
          OR COALESCE(selected_chunk_flag.has_provider_blocked_pre_call, false) IS NOT TRUE
          OR COALESCE(selected_chunk_flag.has_provider_acceptance_evidence, false) IS TRUE
          OR COALESCE(selected_chunk_flag.has_provider_response, false) IS TRUE
          OR COALESCE(selected_chunk_flag.has_provider_request_sent, false) IS TRUE
          OR COALESCE(selected_chunk_flag.has_provider_rejection, false) IS TRUE
          OR COALESCE(selected_chunk_flag.has_provider_unknown, false) IS TRUE
          OR COALESCE(selected_chunk_flag.has_provider_malformed_response, false) IS TRUE
          OR COALESCE(selected_chunk_flag.is_stale_unresolved, false) IS TRUE
          OR COALESCE(selected_chunk_flag.is_stale_request_sent_no_response, false) IS TRUE
     )
     AND NOT EXISTS (
       SELECT 1
       FROM pg_temp.tmp_provider_submit_diagnostic_sources AS selected_source
       WHERE selected_source.provider_submission_attempted IS TRUE
          OR selected_source.provider_request_sent IS TRUE
          OR selected_source.provider_response_received IS TRUE
          OR selected_source.provider_response_present IS TRUE
          OR selected_source.provider_submission_accepted IS TRUE
          OR selected_source.provider_submission_rejected IS TRUE
          OR (
            selected_source.provider_submission_failed IS TRUE
            AND NOT (
              upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
              AND selected_source.provider_submission_attempted IS NOT TRUE
              AND selected_source.provider_request_sent IS NOT TRUE
              AND selected_source.provider_response_received IS NOT TRUE
              AND selected_source.provider_response_present IS NOT TRUE
              AND selected_source.provider_submission_accepted IS NOT TRUE
              AND selected_source.provider_submission_rejected IS NOT TRUE
              AND selected_source.provider_submission_unknown IS NOT TRUE
              AND selected_source.provider_acceptance_evidence_present IS NOT TRUE
              AND NULLIF(BTRIM(COALESCE(
                selected_source.provider_transaction_id,
                selected_source.rail_tx_id,
                selected_source.provider_reference,
                selected_source.provider_state,
                selected_source.provider_http_status,
                ''
              )), '') IS NULL
              AND (
                NULLIF(BTRIM(COALESCE(selected_source.provider_error_code, '')), '') IS NULL
                OR upper(BTRIM(COALESCE(selected_source.provider_error_code, ''))) IN (
                  'PROVIDER_SUBMIT_STAGE_RECORD_FAILED',
                  'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'
                )
              )
            )
          )
          OR selected_source.provider_submission_unknown IS TRUE
          OR selected_source.provider_acceptance_evidence_present IS TRUE
          OR upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN (
            'PROVIDER_SUBMISSION_ACCEPTED',
            'PROVIDER_SUBMISSION_REJECTED',
            'PROVIDER_SUBMISSION_FAILED',
            'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
            'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
            'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK',
            'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID'
          )
          OR NULLIF(BTRIM(COALESCE(
            selected_source.provider_transaction_id,
            selected_source.rail_tx_id,
            selected_source.provider_reference,
            selected_source.provider_state,
            selected_source.provider_http_status,
            ''
          )), '') IS NOT NULL
          OR (
            NULLIF(BTRIM(COALESCE(selected_source.provider_error_code, '')), '') IS NOT NULL
            AND NOT (
              upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
              AND upper(BTRIM(COALESCE(selected_source.provider_error_code, ''))) IN (
                'PROVIDER_SUBMIT_STAGE_RECORD_FAILED',
                'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'
              )
            )
          )
     ) THEN
    v_batch_level_cleaned_local_blocked_pre_call_neutralised := true;

    v_operation_count := 0;
    v_chunk_count := 0;
    v_provider_submission_blocked_pre_call_count := 0;
    v_provider_submission_status := 'NO_PROVIDER_SUBMISSION_ATTEMPTED';
    v_review_reason_code := 'NO_PROVIDER_SUBMIT_ATTEMPT';
    v_provider_call_stage := 'NO_PROVIDER_SUBMIT_ATTEMPT';
    v_provider_submission_attempted := false;
    v_provider_request_sent := false;
    v_provider_response_received := false;
    v_provider_response_present := false;
    v_provider_submission_accepted := false;
    v_provider_submission_rejected := false;
    v_provider_submission_failed := false;
    v_provider_submission_unknown := false;
    v_provider_acceptance_evidence_present := false;
    v_stale_submit_chunk := false;
    v_unfinalised_submit_chunk := false;
    v_chunk_lock_expired := false;
    v_manual_resolution_required := false;
    v_safe_retry_available := false;
    v_automatic_retry_blocked := false;
    v_retry_blocked_reason := NULL::text;
    v_recommended_action := 'No provider submission attempt has been recorded for this scope.';

    v_operation_ids := '[]'::jsonb;
    v_current_operation_ids := '[]'::jsonb;
    v_related_operation_ids := '[]'::jsonb;
    v_diagnostic_operation_id := NULL::text;
    v_chunk_ids := '[]'::jsonb;
    v_primary_operation_id := NULL::text;
    v_primary_chunk_id := NULL::text;
    v_primary_request_id := NULL::text;
    v_primary_idempotency_key := NULL::text;
    v_primary_local_provider_request_id := NULL::text;
    v_primary_provider_http_status := NULL::text;
    v_primary_provider_error_code := NULL::text;
    v_primary_provider_error_message_redacted := NULL::text;
    v_primary_provider_response_redacted := NULL::jsonb;
    v_primary_provider_error_redacted := NULL::jsonb;
    v_chunk_started_at_utc := NULL::text;
    v_chunk_completed_at_utc := NULL::text;
    v_chunk_lock_expires_at_utc := NULL::text;
  END IF;

  v_provider_submit_actual_context := (
    COALESCE(v_operation_count, 0) > 0
    OR COALESCE(v_chunk_count, 0) > 0
    OR COALESCE(v_transfer_count, 0) > 0
    OR COALESCE(v_provider_acceptance_evidence_count, 0) > 0
    OR COALESCE(v_provider_response_present_count, 0) > 0
    OR COALESCE(v_provider_request_sent_count, 0) > 0
    OR COALESCE(v_provider_submission_unknown_count, 0) > 0
    OR COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0
    OR COALESCE(v_unfinalised_submit_chunk_count, 0) > 0
    OR COALESCE(v_provider_submission_rejected_count, 0) > 0
    OR COALESCE(v_provider_submission_malformed_response_count, 0) > 0
  );

  v_mixed_provider_submit_outcome := (
    COALESCE(v_provider_acceptance_evidence_count, 0) > 0
    AND (
      COALESCE(v_provider_submission_unknown_count, 0) > 0
      OR COALESCE(v_provider_submission_rejected_count, 0) > 0
      OR COALESCE(v_provider_submission_malformed_response_count, 0) > 0
      OR COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0
      OR COALESCE(v_request_sent_no_response_count, 0) > 0
      OR (
        COALESCE(v_unfinalised_submit_chunk_count, 0) > 0
        AND (COALESCE(v_operation_review_required, false) IS TRUE OR COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0)
      )
      OR (
        COALESCE(v_transfer_count, 0) > COALESCE(v_provider_acceptance_evidence_count, 0)
        AND (
          COALESCE(v_operation_review_required, false) IS TRUE
          OR COALESCE(v_provider_submission_unknown_count, 0) > 0
          OR COALESCE(v_provider_submission_rejected_count, 0) > 0
          OR COALESCE(v_provider_submission_malformed_response_count, 0) > 0
          OR COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0
        )
      )
    )
  );

  IF COALESCE(v_provider_acceptance_evidence_count, 0) > 0 THEN
    v_provider_submission_status := 'PROVIDER_SUBMISSION_ACCEPTED';
    v_review_reason_code := 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT';
    v_provider_call_stage := COALESCE(v_provider_call_stage, 'PROVIDER_RESPONSE_RECEIVED');
    v_provider_submission_attempted := true;
    v_provider_request_sent := true;
    v_provider_response_received := true;
    v_provider_response_present := true;
    v_provider_submission_accepted := true;
    v_provider_acceptance_evidence_present := true;
    v_stale_submit_chunk := COALESCE(v_stale_empty_submit_chunk_count, 0) > 0;
    v_unfinalised_submit_chunk := COALESCE(v_unfinalised_submit_chunk_count, 0) > 0;
    v_manual_resolution_required := false;
    v_safe_retry_available := false;
    v_automatic_retry_blocked := true;
    v_retry_blocked_reason := 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT';
    v_recommended_action := 'Provider acceptance evidence exists. Do not retry unless reconciled.';
  ELSIF COALESCE(v_provider_submission_malformed_response_count, 0) > 0 THEN
    v_provider_submission_status := 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE';
    v_review_reason_code := 'PROVIDER_RESPONSE_MALFORMED';
    v_provider_submission_attempted := true;
    v_provider_request_sent := true;
    v_provider_response_received := true;
    v_provider_response_present := true;
    v_provider_submission_unknown := true;
    v_manual_resolution_required := true;
    v_safe_retry_available := false;
    v_automatic_retry_blocked := true;
    v_retry_blocked_reason := 'PROVIDER_RESPONSE_MALFORMED';
    v_recommended_action := 'Provider returned an unusable response. Check Revolut/bank records before retry.';
  ELSIF COALESCE(v_provider_submission_unknown_count, 0) > 0
     AND COALESCE(v_stale_unresolved_submit_chunk_count, 0) = 0 THEN
    v_provider_submission_status := 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME';
    v_review_reason_code := 'PROVIDER_REQUEST_SENT_NO_RESPONSE';
    v_provider_submission_attempted := true;
    v_provider_request_sent := true;
    v_provider_response_received := false;
    v_provider_response_present := false;
    v_provider_submission_unknown := true;
    v_manual_resolution_required := true;
    v_safe_retry_available := false;
    v_automatic_retry_blocked := true;
    v_retry_blocked_reason := 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME';
    v_recommended_action := 'Provider request may have been sent, but no usable response was recorded. Check Revolut/bank records before retry.';
  ELSIF COALESCE(v_request_sent_no_response_count, 0) > 0
     OR (
       COALESCE(v_provider_request_sent_count, 0) > 0
       AND COALESCE(v_provider_response_present_count, 0) = 0
       AND COALESCE(v_provider_acceptance_evidence_count, 0) = 0
     ) THEN
    v_provider_submission_status := 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME';
    v_review_reason_code := 'PROVIDER_REQUEST_SENT_NO_RESPONSE';
    v_provider_submission_attempted := true;
    v_provider_request_sent := true;
    v_provider_response_received := false;
    v_provider_response_present := false;
    v_provider_submission_unknown := true;
    v_stale_submit_chunk := COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0;
    v_unfinalised_submit_chunk := COALESCE(v_unfinalised_submit_chunk_count, 0) > 0;
    v_manual_resolution_required := true;
    v_safe_retry_available := false;
    v_automatic_retry_blocked := true;
    v_retry_blocked_reason := 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME';
    v_recommended_action := 'Provider request may have been sent, but no usable response was recorded. Check Revolut/bank records before retry.';
  ELSIF COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0 THEN
    v_provider_submission_status := 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK';
    v_review_reason_code := 'STALE_RUNNING_PROVIDER_SUBMIT_CHUNK';
    v_provider_call_stage := COALESCE(v_provider_call_stage, 'STALE_RUNNING_PROVIDER_SUBMIT_CHUNK');
    v_provider_submission_attempted := NULL::boolean;
    v_provider_request_sent := NULL::boolean;
    v_provider_response_received := false;
    v_provider_response_present := false;
    v_provider_submission_unknown := true;
    v_stale_submit_chunk := true;
    v_unfinalised_submit_chunk := true;
    v_manual_resolution_required := true;
    v_safe_retry_available := false;
    v_automatic_retry_blocked := true;
    v_retry_blocked_reason := 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK';
    v_recommended_action := 'Check Revolut/bank records before retry. If no payment was made, record manual no-payment confirmation and reset for retry.';
  ELSIF COALESCE(v_provider_submission_rejected_count, 0) > 0 THEN
    v_provider_submission_status := 'PROVIDER_SUBMISSION_REJECTED';
    v_review_reason_code := 'PROVIDER_REJECTED_PAYMENT';
    v_provider_submission_attempted := true;
    v_provider_request_sent := true;
    v_provider_response_received := true;
    v_provider_response_present := true;
    v_provider_submission_rejected := true;
    v_provider_submission_failed := true;
    v_manual_resolution_required := false;
    v_safe_retry_available := false;
    v_recommended_action := 'Review the provider rejection/error and retry only after correction.';
  ELSIF COALESCE(v_provider_submission_blocked_pre_call_count, 0) > 0 THEN
    v_provider_submission_status := 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL';
    v_review_reason_code := 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL';
    v_provider_submission_attempted := false;
    v_provider_request_sent := false;
    v_provider_response_received := false;
    v_provider_response_present := false;
    v_provider_submission_failed := true;
    v_recommended_action := 'Provider was not called. Fix the local blocker and retry if cleanup allows.';
  END IF;

  IF COALESCE(v_mixed_provider_submit_outcome, false) IS TRUE THEN
    v_review_reason_code := 'MIXED_PROVIDER_SUBMIT_OUTCOME';
    v_provider_submission_unknown := true;
    v_provider_submission_rejected := COALESCE(v_provider_submission_rejected_count, 0) > 0;
    v_provider_submission_failed := COALESCE(v_provider_submission_rejected_count, 0) > 0 OR COALESCE(v_provider_submission_malformed_response_count, 0) > 0;
    v_manual_resolution_required := true;
    v_safe_retry_available := false;
    v_automatic_retry_blocked := true;
    v_retry_blocked_reason := 'PROVIDER_SUBMISSION_MIXED_OUTCOME';
    v_recommended_action := 'Provider acceptance evidence exists for at least one transfer, but not all provider-submit outcomes are resolved. Reconcile accepted provider transfer(s) and unresolved/rejected/malformed transfer(s) before retry.';
  END IF;

  v_payment_provider_review_required := (
    COALESCE(v_provider_submit_actual_context, false) IS TRUE
    AND v_provider_submission_status <> 'MANUAL_RESOLVED_NO_PAYMENT_MADE'
    AND (
      COALESCE(v_mixed_provider_submit_outcome, false) IS TRUE
      OR v_provider_submission_status IN (
        'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK',
        'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
        'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
        'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID',
        'PROVIDER_SUBMISSION_REJECTED',
        'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
      )
      OR (
        v_provider_submission_status = 'PROVIDER_SUBMISSION_ACCEPTED'
        AND COALESCE(v_operation_review_required, false) IS TRUE
      )
    )
  );

  v_counts := jsonb_build_object(
    'operation_count', COALESCE(v_operation_count, 0),
    'chunk_count', COALESCE(v_chunk_count, 0),
    'transfer_count', COALESCE(v_transfer_count, 0),
    'active_auth_request_count', COALESCE(v_active_auth_request_count, 0),
    'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
    'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
    'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
    'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
    'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
    'stale_empty_submit_chunk_count', COALESCE(v_stale_empty_submit_chunk_count, 0),
    'request_sent_no_response_count', COALESCE(v_request_sent_no_response_count, 0),
    'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
    'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
    'provider_submission_accepted_count', COALESCE(v_provider_submission_accepted_count, 0),
    'provider_submission_blocked_pre_call_count', COALESCE(v_provider_submission_blocked_pre_call_count, 0),
    'provider_submission_malformed_response_count', COALESCE(v_provider_submission_malformed_response_count, 0),
    'mixed_provider_submit_outcome', COALESCE(v_mixed_provider_submit_outcome, false),
    'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
    'operation_review_required', COALESCE(v_operation_review_required, false),
    'provider_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
    'provider_attempt_or_evidence_count', COALESCE(v_provider_request_sent_count, 0) + COALESCE(v_provider_response_present_count, 0) + COALESCE(v_provider_acceptance_evidence_count, 0),
    'attempted_but_unproven_count', COALESCE(v_provider_submission_unknown_count, 0)
  );

  v_ids := jsonb_build_object(
    'operation_id', v_diagnostic_operation_id,
    'operation_ids', COALESCE(v_current_operation_ids, '[]'::jsonb),
    'related_operation_ids', COALESCE(v_related_operation_ids, '[]'::jsonb),
    'chunk_ids', COALESCE(v_chunk_ids, '[]'::jsonb),
    'transfer_ids', COALESCE(v_transfer_ids, '[]'::jsonb),
    'transfer_scope_ids', COALESCE(v_transfer_scope_ids, '[]'::jsonb),
    'auth_request_ids', COALESCE(v_auth_request_ids, '[]'::jsonb)
  );

  v_provider_submit_diagnostic := jsonb_build_object(
    'diagnostic_version', 1,
    'generated_at_utc', v_now::text,
    'review_reason_code', v_review_reason_code,
    'provider_submission_status', v_provider_submission_status,
    'provider_call_stage', v_provider_call_stage,
    'provider_submission_attempted', v_provider_submission_attempted,
    'provider_request_sent', v_provider_request_sent,
    'provider_response_received', v_provider_response_received,
    'provider_response_present', v_provider_response_present,
    'provider_submission_accepted', v_provider_submission_accepted,
    'provider_submission_rejected', v_provider_submission_rejected,
    'provider_submission_failed', v_provider_submission_failed,
    'provider_submission_unknown', v_provider_submission_unknown,
    'provider_acceptance_evidence_present', v_provider_acceptance_evidence_present,
    'mixed_provider_submit_outcome', COALESCE(v_mixed_provider_submit_outcome, false),
    'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
    'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
    'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
    'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
    'provider_submission_malformed_response_count', COALESCE(v_provider_submission_malformed_response_count, 0),
    'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
    'stale_submit_chunk', v_stale_submit_chunk,
    'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
    'stale_empty_submit_chunk_count', COALESCE(v_stale_empty_submit_chunk_count, 0),
    'request_sent_no_response_count', COALESCE(v_request_sent_no_response_count, 0),
    'unfinalised_submit_chunk', v_unfinalised_submit_chunk,
    'chunk_lock_expired', COALESCE(v_chunk_lock_expired, false),
    'chunk_started_at_utc', v_chunk_started_at_utc,
    'chunk_completed_at_utc', v_chunk_completed_at_utc
  )
  || jsonb_build_object(
    'chunk_lock_expires_at_utc', v_chunk_lock_expires_at_utc,
    'manual_resolution_required', v_manual_resolution_required,
    'safe_retry_available', v_safe_retry_available,
    'automatic_retry_blocked', v_automatic_retry_blocked,
    'retry_blocked_reason', v_retry_blocked_reason,
    'recommended_action', v_recommended_action,
    'pay_batch_id', CASE WHEN v_effective_pay_batch_id IS NULL THEN NULL ELSE v_effective_pay_batch_id::text END,
    'operation_id', v_diagnostic_operation_id,
    'operation_ids', COALESCE(v_current_operation_ids, '[]'::jsonb),
    'related_operation_ids', COALESCE(v_related_operation_ids, '[]'::jsonb),
    'chunk_id', v_primary_chunk_id,
    'chunk_ids', v_chunk_ids,
    'transfer_id', v_primary_transfer_id,
    'transfer_ids', v_transfer_ids,
    'transfer_scope_id', v_primary_transfer_scope_id,
    'transfer_scope_ids', v_transfer_scope_ids,
    'auth_request_id', v_primary_auth_request_id,
    'auth_request_ids', v_auth_request_ids,
    'rail_provider', v_primary_rail_provider,
    'rail_env', v_primary_rail_env,
    'rail_tx_id', v_primary_rail_tx_id,
    'rail_state', v_primary_rail_state,
    'provider_transaction_id', v_primary_provider_transaction_id,
    'provider_reference', v_primary_provider_reference,
    'provider_state', v_primary_provider_state,
    'request_id', v_primary_request_id,
    'idempotency_key', v_primary_idempotency_key,
    'local_provider_request_id', v_primary_local_provider_request_id,
    'provider_http_status', v_primary_provider_http_status,
    'provider_error_code', v_primary_provider_error_code,
    'provider_error_message_redacted', v_primary_provider_error_message_redacted,
    'provider_response_redacted', v_primary_provider_response_redacted,
    'provider_error_redacted', v_primary_provider_error_redacted
  );

  RETURN jsonb_build_object(
    'ok', true,
    'provider_submit_diagnostic', v_provider_submit_diagnostic,
    'provider_submission_status', v_provider_submission_status,
    'review_reason_code', v_review_reason_code,
    'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
    'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
    'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
    'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
    'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
    'provider_submission_malformed_response_count', COALESCE(v_provider_submission_malformed_response_count, 0),
    'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
    'stale_empty_submit_chunk_count', COALESCE(v_stale_empty_submit_chunk_count, 0),
    'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
    'manual_resolution_required', v_manual_resolution_required,
    'safe_retry_available', v_safe_retry_available,
    'recommended_action', v_recommended_action,
    'mixed_provider_submit_outcome', COALESCE(v_mixed_provider_submit_outcome, false),
    'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
    'counts', v_counts,
    'ids', v_ids,
    'provider_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
    'provider_attempt_or_evidence_count', COALESCE(v_provider_request_sent_count, 0) + COALESCE(v_provider_response_present_count, 0) + COALESCE(v_provider_acceptance_evidence_count, 0),
    'attempted_but_unproven_count', COALESCE(v_provider_submission_unknown_count, 0),
    'counts_only', COALESCE(p_counts_only, false)
  );

END;
$function$;

-- pay_reconcile_external_payment(uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_reconcile_external_payment(p_actor_user_id uuid, p_payload_json jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pay_date date := NULL;
  v_payment_reference text := NULL;
  v_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_duplicate_timesheet_ids jsonb := '[]'::jsonb;
  v_missing_timesheet_ids jsonb := '[]'::jsonb;
  v_timesheet_count integer := 0;
  v_candidate_count integer := 0;
  v_response jsonb := '{}'::jsonb;
BEGIN
  IF p_payload_json IS NULL OR jsonb_typeof(p_payload_json) <> 'object' THEN
    RAISE EXCEPTION 'pay_reconcile_external_payment: payload_json must be an object';
  END IF;

  IF NULLIF(btrim(coalesce(p_payload_json->>'pay_date', '')), '') IS NOT NULL THEN
    BEGIN
      v_pay_date := (p_payload_json->>'pay_date')::date;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'pay_reconcile_external_payment: payload.pay_date is not a valid date (YYYY-MM-DD)';
    END;
  END IF;

  v_payment_reference := NULLIF(
    btrim(
      coalesce(
        p_payload_json->>'payment_reference',
        p_payload_json->>'bulk_reference',
        p_payload_json->>'bank_reference',
        ''
      )
    ),
    ''
  );

  IF p_payload_json ? 'timesheet_ids' THEN
    IF jsonb_typeof(p_payload_json->'timesheet_ids') <> 'array' THEN
      RAISE EXCEPTION 'pay_reconcile_external_payment: payload.timesheet_ids must be an array of UUID strings when supplied';
    END IF;

    SELECT coalesce(array_agg((external_reconcile_timesheet_ids.timesheet_id_text)::uuid), ARRAY[]::uuid[])
    INTO v_timesheet_ids
    FROM jsonb_array_elements_text(p_payload_json->'timesheet_ids') AS external_reconcile_timesheet_ids(timesheet_id_text)
    WHERE NULLIF(btrim(external_reconcile_timesheet_ids.timesheet_id_text), '') IS NOT NULL;

    SELECT coalesce(jsonb_agg(duplicate_timesheet_rows.timesheet_id::text ORDER BY duplicate_timesheet_rows.timesheet_id::text), '[]'::jsonb)
    INTO v_duplicate_timesheet_ids
    FROM (
      SELECT supplied_duplicate_timesheet_rows.timesheet_id
      FROM unnest(v_timesheet_ids) AS supplied_duplicate_timesheet_rows(timesheet_id)
      GROUP BY supplied_duplicate_timesheet_rows.timesheet_id
      HAVING count(*) > 1
    ) AS duplicate_timesheet_rows;

    IF jsonb_array_length(v_duplicate_timesheet_ids) > 0 THEN
      RAISE EXCEPTION 'pay_reconcile_external_payment: duplicate timesheet_ids %', v_duplicate_timesheet_ids::text;
    END IF;

    SELECT coalesce(jsonb_agg(missing_timesheet_rows.timesheet_id::text ORDER BY missing_timesheet_rows.timesheet_id::text), '[]'::jsonb)
    INTO v_missing_timesheet_ids
    FROM (
      SELECT supplied_timesheet_rows.timesheet_id
      FROM unnest(v_timesheet_ids) AS supplied_timesheet_rows(timesheet_id)
      LEFT JOIN public.timesheets AS current_timesheets
        ON current_timesheets.timesheet_id = supplied_timesheet_rows.timesheet_id
       AND current_timesheets.is_current = true
      WHERE current_timesheets.timesheet_id IS NULL
    ) AS missing_timesheet_rows;

    IF jsonb_array_length(v_missing_timesheet_ids) > 0 THEN
      RAISE EXCEPTION 'pay_reconcile_external_payment: timesheet(s) not found or not current %', v_missing_timesheet_ids::text;
    END IF;

    SELECT count(DISTINCT supplied_timesheet_rows.timesheet_id)::integer
    INTO v_timesheet_count
    FROM unnest(v_timesheet_ids) AS supplied_timesheet_rows(timesheet_id);

    SELECT count(DISTINCT current_financials.candidate_id)::integer
    INTO v_candidate_count
    FROM public.timesheets_financials AS current_financials
    WHERE current_financials.is_current = true
      AND current_financials.timesheet_id = ANY(v_timesheet_ids);
  END IF;

  v_response := jsonb_build_object(
    'ok', false,
    'classification', 'AMBIGUOUS_REVIEW_REQUIRED',
    'recommended_action', 'USE_NORMAL_BATCH_MANUAL_SETTLEMENT',
    'can_apply', false,
    'auto_correction_allowed', false,
    'legacy_no_artifact_batch', true,
    'message', 'USE_PAYMENT_CORRECTION_FLOW: External payment reconciliation must be backfilled into proper Banking Pay batch artifacts, then settled through manual settlement confirmation so pay_bank_event_ingest and pay_settle_rail can preserve frozen correction evidence. Legacy no-artifact reconciliation is AMBIGUOUS_REVIEW_REQUIRED and cannot auto-correct.',
    'pay_date', CASE WHEN v_pay_date IS NULL THEN NULL ELSE v_pay_date::text END,
    'payment_reference', v_payment_reference,
    'timesheet_count', v_timesheet_count,
    'candidate_count', v_candidate_count,
    'hard_blockers', jsonb_build_array(
      jsonb_build_object(
        'code', 'USE_PAYMENT_CORRECTION_FLOW',
        'message', 'Legacy external reconciliation is classified as AMBIGUOUS_REVIEW_REQUIRED. Backfill/create a normal Banking Pay batch and confirm settlement manually so the event/correction artifact path is preserved.'
      )
    )
  );

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_RECONCILE_EXTERNAL_PAYMENT_BLOCKED_LEGACY_NO_ARTIFACT',
    v_response,
    'pay_batch',
    COALESCE(v_payment_reference, 'NO_PAYMENT_REFERENCE'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  RAISE EXCEPTION 'USE_PAYMENT_CORRECTION_FLOW: External payment reconciliation must be backfilled into proper Banking Pay batch artifacts before correction can be applied.'
    USING ERRCODE = 'P0001',
          DETAIL = v_response::text;

  RETURN v_response;
END;
$function$;

-- pay_remittance_build(uuid,text,uuid,jsonb,integer,jsonb)
CREATE OR REPLACE FUNCTION public.pay_remittance_build(p_pay_batch_id uuid, p_scope text DEFAULT 'ALL'::text, p_operation_id uuid DEFAULT NULL::uuid, p_remittance_scope_ids jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT NULL::integer, p_cursor_json jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_scope text := upper(btrim(coalesce(p_scope, 'ALL')));
  v_batch record;

  v_jobs_umb jsonb := '[]'::jsonb;
  v_jobs_paye jsonb := '[]'::jsonb;
  v_jobs_cand_umb_copy jsonb := '[]'::jsonb;

  -- ✅ Remittance settings (single-row settings_defaults)
  v_remittance_includes_json jsonb := null;
  v_remittance_header_message text := null;
  v_remittance_footer_message text := null;

  -- ✅ New defaults
  v_sd_paye_remittances_enabled boolean := false;
  v_sd_remittances_detailed_breakdown boolean := false;
  v_sd_remittance_receive_when_umbrella_paid boolean := false;

  -- ✅ derived defaults for config evaluation
  v_missing_scope text := 'WEEKLY';
  v_unknown_item_type_default boolean := true;
  v_unknown_item_type_default_text text := 'true';

  v_operation_mode boolean := false;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_limit integer := 100;
  v_cursor_scope_id uuid := null;
  v_requested_scope_count integer := 0;
  v_matched_scope_count integer := 0;
  v_selected_scope_count integer := 0;
  v_known_scope_count integer := 0;
  v_next_cursor_json jsonb := null;
  v_operation_jobs jsonb := '[]'::jsonb;
  v_operation_scope_ids jsonb := '[]'::jsonb;
  v_legacy_scope_count integer := 0;
begin
  if p_pay_batch_id is null then
    raise exception 'pay_remittance_build: pay_batch_id is required';
  end if;

  if v_scope not in ('ALL','PAYE','UMBRELLA') then
    raise exception 'pay_remittance_build: invalid scope "%". Expected ALL|PAYE|UMBRELLA.', v_scope;
  end if;

  v_operation_mode := (p_operation_id IS NOT NULL OR p_remittance_scope_ids IS NOT NULL OR p_limit IS NOT NULL OR p_cursor_json IS NOT NULL);

  IF v_operation_mode THEN
    IF p_operation_id IS NULL THEN
      RAISE EXCEPTION 'pay_remittance_build operation mode requires p_operation_id';
    END IF;

    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'pay_remittance_build: operation % not found', p_operation_id;
    END IF;

    IF v_operation_row.operation_type NOT IN ('REMITTANCE_QUEUE', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLEMENT') THEN
      RAISE EXCEPTION 'pay_remittance_build: operation % is not remittance-capable', p_operation_id;
    END IF;

    IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
      RAISE EXCEPTION 'pay_remittance_build: operation % is for pay batch %, not %', p_operation_id, v_operation_row.pay_batch_id, p_pay_batch_id;
    END IF;

    SELECT
      pb.id,
      pb.pay_date,
      pb.authoritative_payment_date,
      pb.authoritative_payment_date_source,
      pb.status,
      pb.bulk_reference,
      pb.banking_system_snapshot,
      pb.external_paye_system_snapshot,
      pb.execution_commit_state,
      pb.execution_commit_ref,
      pb.execution_committed_at_utc
    INTO v_batch
    FROM public.pay_batches AS pb
    WHERE pb.id = p_pay_batch_id;

    IF v_batch.id IS NULL THEN
      RAISE EXCEPTION 'pay_remittance_build: pay batch % not found.', p_pay_batch_id;
    END IF;

    IF v_operation_row.pay_batch_id IS NULL THEN
      UPDATE public.banking_pay_operations AS operation_update
      SET pay_batch_id = p_pay_batch_id,
          updated_at_utc = now()
      WHERE operation_update.id = p_operation_id
        AND operation_update.pay_batch_id IS NULL;
    END IF;

    v_limit := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 1000);

    IF p_cursor_json IS NOT NULL
       AND jsonb_typeof(p_cursor_json) = 'object'
       AND COALESCE(p_cursor_json->>'last_remittance_scope_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_cursor_scope_id := (p_cursor_json->>'last_remittance_scope_id')::uuid;
    END IF;

    IF p_remittance_scope_ids IS NOT NULL THEN
      IF jsonb_typeof(p_remittance_scope_ids) <> 'array' THEN
        RAISE EXCEPTION 'pay_remittance_build operation mode requires p_remittance_scope_ids to be a JSON array when supplied';
      END IF;

      WITH requested_scope AS (
        SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS remittance_scope_id
        FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
        WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      )
      SELECT COUNT(*)::integer
      INTO v_requested_scope_count
      FROM requested_scope;

      IF v_requested_scope_count <> jsonb_array_length(p_remittance_scope_ids) THEN
        RAISE EXCEPTION 'pay_remittance_build operation mode received invalid or duplicate remittance scope ids';
      END IF;

      WITH requested_scope AS (
        SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS remittance_scope_id
        FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
        WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ), selected_scope AS (
        SELECT scope_row.*
        FROM public.banking_pay_operation_remittance_scope AS scope_row
        JOIN requested_scope
          ON requested_scope.remittance_scope_id = scope_row.id
        WHERE scope_row.operation_id = p_operation_id
          AND scope_row.pay_batch_id = p_pay_batch_id
      ), job_rows AS (
        SELECT
          selected_scope.id,
          selected_scope.status,
          selected_scope.pay_batch_candidate_id,
          selected_scope.candidate_id,
          selected_scope.recipient_kind,
          selected_scope.recipient_id,
          selected_scope.remittance_type,
          selected_scope.deterministic_outbox_key,
          selected_scope.payload_json,
          selected_scope.outbox_id,
          CASE
            WHEN upper(coalesce(selected_scope.recipient_kind, '')) = 'CANDIDATE' THEN candidate_row.email
            WHEN upper(coalesce(selected_scope.recipient_kind, '')) = 'UMBRELLA' THEN umbrella_row.remittance_email
            ELSE NULL::text
          END AS recipient_email,
          CASE
            WHEN upper(coalesce(selected_scope.recipient_kind, '')) = 'CANDIDATE' THEN candidate_row.display_name
            WHEN upper(coalesce(selected_scope.recipient_kind, '')) = 'UMBRELLA' THEN umbrella_row.name
            ELSE NULL::text
          END AS recipient_name
        FROM selected_scope
        LEFT JOIN public.candidates AS candidate_row
          ON upper(coalesce(selected_scope.recipient_kind, '')) = 'CANDIDATE'
         AND candidate_row.id = selected_scope.recipient_id
        LEFT JOIN public.umbrellas AS umbrella_row
          ON upper(coalesce(selected_scope.recipient_kind, '')) = 'UMBRELLA'
         AND umbrella_row.id = selected_scope.recipient_id
      )
      SELECT COUNT(*)::integer,
             COALESCE(jsonb_agg(to_jsonb(job_rows.id::text) ORDER BY job_rows.id::text), '[]'::jsonb),
             COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
               'job_kind', job_rows.remittance_type,
               'operation_id', p_operation_id::text,
               'pay_batch_id', p_pay_batch_id::text,
               'remittance_scope_id', job_rows.id::text,
               'deterministic_outbox_key', job_rows.deterministic_outbox_key,
               'status', job_rows.status,
               'outbox_id', CASE WHEN job_rows.outbox_id IS NULL THEN NULL ELSE job_rows.outbox_id::text END,
               'recipient', jsonb_strip_nulls(jsonb_build_object(
                 'entity_kind', lower(coalesce(job_rows.recipient_kind, '')),
                 'entity_id', CASE WHEN job_rows.recipient_id IS NULL THEN NULL ELSE job_rows.recipient_id::text END,
                 'candidate_id', CASE WHEN upper(coalesce(job_rows.recipient_kind, '')) = 'CANDIDATE' AND job_rows.recipient_id IS NOT NULL THEN job_rows.recipient_id::text ELSE NULL END,
                 'umbrella_id', CASE WHEN upper(coalesce(job_rows.recipient_kind, '')) = 'UMBRELLA' AND job_rows.recipient_id IS NOT NULL THEN job_rows.recipient_id::text ELSE NULL END,
                 'name', job_rows.recipient_name,
                 'email', job_rows.recipient_email,
                 'remittance_email', job_rows.recipient_email
               )),
               'payment_scope_json', jsonb_strip_nulls(COALESCE(job_rows.payload_json, '{}'::jsonb) || jsonb_build_object(
                 'pay_batch_id', p_pay_batch_id::text,
                 'operation_id', p_operation_id::text,
                 'remittance_scope_id', job_rows.id::text,
                 'deterministic_outbox_key', job_rows.deterministic_outbox_key,
                 'remittance_type', job_rows.remittance_type
               )),
               'remittance_payload_version', 2,
               'payload_hash', md5(jsonb_strip_nulls(COALESCE(job_rows.payload_json, '{}'::jsonb) || jsonb_build_object(
                 'pay_batch_id', p_pay_batch_id::text,
                 'operation_id', p_operation_id::text,
                 'remittance_scope_id', job_rows.id::text,
                 'deterministic_outbox_key', job_rows.deterministic_outbox_key,
                 'remittance_type', job_rows.remittance_type
               ))::text),
               'pay_date', CASE WHEN COALESCE(v_batch.authoritative_payment_date, v_batch.pay_date) IS NULL THEN NULL ELSE COALESCE(v_batch.authoritative_payment_date, v_batch.pay_date)::text END,
               'authoritative_payment_date', CASE WHEN v_batch.authoritative_payment_date IS NULL THEN NULL ELSE v_batch.authoritative_payment_date::text END,
               'authoritative_payment_date_source', v_batch.authoritative_payment_date_source,
               'bulk_reference', v_batch.bulk_reference,
               'candidate_id', CASE WHEN job_rows.candidate_id IS NULL THEN NULL ELSE job_rows.candidate_id::text END,
               'pay_batch_candidate_ids', CASE WHEN job_rows.pay_batch_candidate_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(job_rows.pay_batch_candidate_id::text) END,
               'candidate', COALESCE((
                 SELECT jsonb_strip_nulls(jsonb_build_object(
                   'candidate_id', candidate_label.id::text,
                   'stable_candidate_key', candidate_label.id::text,
                   'tms_ref', candidate_label.tms_ref,
                   'candidate_tms_ref', candidate_label.tms_ref,
                   'works_number', candidate_label.tms_ref,
                   'display_name', candidate_label.display_name,
                   'candidate_display_name', candidate_label.display_name,
                   'email', candidate_label.email
                 ))
                 FROM public.candidates AS candidate_label
                 WHERE candidate_label.id = job_rows.candidate_id
                 LIMIT 1
               ), '{}'::jsonb),
               'umbrella', COALESCE((
                 SELECT jsonb_strip_nulls(jsonb_build_object(
                   'umbrella_id', umbrella_label.id::text,
                   'name', umbrella_label.name,
                   'remittance_email', umbrella_label.remittance_email
                 ))
                 FROM public.umbrellas AS umbrella_label
                 WHERE upper(coalesce(job_rows.recipient_kind, '')) = 'UMBRELLA'
                   AND umbrella_label.id = job_rows.recipient_id
                 LIMIT 1
               ), '{}'::jsonb),
               'summary', jsonb_strip_nulls(jsonb_build_object(
                 'payment_amount', round(COALESCE(NULLIF(job_rows.payload_json->>'total_amount', '')::numeric, 0), 2),
                 'total_amount', round(COALESCE(NULLIF(job_rows.payload_json->>'total_amount', '')::numeric, 0), 2),
                 'currency', 'GBP',
                 'item_count', COALESCE(NULLIF(job_rows.payload_json->>'item_count', '')::integer, 0),
                 'final_payable', round(COALESCE(NULLIF(job_rows.payload_json->>'total_amount', '')::numeric, 0), 2)
               )),
               'pay_batch_item_ids', COALESCE(job_rows.payload_json->'pay_batch_item_ids', '[]'::jsonb),
               'pay_bank_transfer_ids', COALESCE((
                 SELECT jsonb_agg(DISTINCT transfer_ids.transfer_id_text ORDER BY transfer_ids.transfer_id_text)
                 FROM (
                   SELECT transfer_row.id::text AS transfer_id_text
                   FROM public.pay_bank_transfers AS transfer_row
                   WHERE transfer_row.pay_batch_id = p_pay_batch_id
                     AND (
                       transfer_row.id::text = NULLIF(job_rows.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')
                       OR EXISTS (
                         SELECT 1
                         FROM jsonb_array_elements(COALESCE(job_rows.payload_json->'pay_batch_item_ids', '[]'::jsonb)) AS item_id(value)
                         JOIN public.pay_batch_items AS item_row
                           ON item_row.id = (item_id.value #>> '{}')::uuid
                         WHERE (item_id.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                           AND item_row.pay_bank_transfer_id = transfer_row.id
                       )
                     )
                 ) AS transfer_ids
               ), '[]'::jsonb),
               'transfers', COALESCE((
                 SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                   'transfer_id', transfer_row.id::text,
                   'pay_bank_transfer_id', transfer_row.id::text,
                   'candidate_id', CASE WHEN transfer_row.candidate_id IS NULL THEN NULL ELSE transfer_row.candidate_id::text END,
                   'umbrella_id', CASE WHEN transfer_row.umbrella_id IS NULL THEN NULL ELSE transfer_row.umbrella_id::text END,
                   'pay_channel', transfer_row.pay_channel,
                   'amount', transfer_row.amount,
                   'currency', COALESCE(NULLIF(BTRIM(COALESCE(transfer_row.currency, '')), ''), 'GBP'),
                   'status', transfer_row.status,
                   'payment_reference', transfer_row.payment_reference,
                   'rail_tx_id', transfer_row.rail_tx_id,
                   'provider_transaction_id', COALESCE(transfer_row.rail_tx_id, transfer_row.rail_meta_json #>> '{provider_transaction_id}', transfer_row.rail_meta_json #>> '{transaction_id}', transfer_row.rail_meta_json #>> '{provider_payment_id}'),
                   'rail_state', transfer_row.rail_state,
                   'completed_at_utc', CASE WHEN transfer_row.completed_at_utc IS NULL THEN NULL ELSE transfer_row.completed_at_utc::text END,
                   'rail_meta_json', transfer_row.rail_meta_json
                 )) ORDER BY transfer_row.id::text)
                 FROM public.pay_bank_transfers AS transfer_row
                 WHERE transfer_row.pay_batch_id = p_pay_batch_id
                   AND (
                     transfer_row.id::text = NULLIF(job_rows.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')
                     OR EXISTS (
                       SELECT 1
                       FROM jsonb_array_elements(COALESCE(job_rows.payload_json->'pay_batch_item_ids', '[]'::jsonb)) AS item_id(value)
                       JOIN public.pay_batch_items AS item_row
                         ON item_row.id = (item_id.value #>> '{}')::uuid
                       WHERE (item_id.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                         AND item_row.pay_bank_transfer_id = transfer_row.id
                     )
                   )
               ), '[]'::jsonb),
               'lines', COALESCE((
                 SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                   'pay_batch_item_id', item_row.id::text,
                   'pay_batch_item_breakdown_id', CASE WHEN breakdown_row.id IS NULL THEN NULL ELSE breakdown_row.id::text END,
                   'pay_batch_candidate_id', item_row.pay_batch_candidate_id::text,
                   'candidate_id', CASE WHEN candidate_row.candidate_id IS NULL THEN NULL ELSE candidate_row.candidate_id::text END,
                   'timesheet_id', CASE WHEN item_row.timesheet_id IS NULL THEN NULL ELSE item_row.timesheet_id::text END,
                   'pay_bank_transfer_id', CASE WHEN item_row.pay_bank_transfer_id IS NULL THEN NULL ELSE item_row.pay_bank_transfer_id::text END,
                   'item_type', item_row.item_type,
                   'description', item_row.description,
                   'source_ref', item_row.source_ref,
                   'pay_channel', item_row.pay_channel,
                   'line_kind', COALESCE(breakdown_row.line_kind, item_row.item_type),
                   'bucket_code', COALESCE(
                     NULLIF(UPPER(BTRIM(COALESCE(breakdown_row.bucket_code, ''))), ''),
                     CASE WHEN component_probe.component_json IS NULL THEN NULL ELSE NULLIF(UPPER(BTRIM(COALESCE(component_probe.component_json->>'bucket_code', component_probe.component_json #>> '{source_basis_json,bucket_code}', component_probe.component_json->>'label', ''))), '') END
                   ),
                   'unit', CASE
                     WHEN component_probe.component_json IS NOT NULL
                      AND (
                        NULLIF(BTRIM(COALESCE(breakdown_row.unit_name, '')), '') IS NULL
                        OR UPPER(BTRIM(COALESCE(breakdown_row.unit_name, ''))) IN ('SEGMENT_DELTA','TIMESHEET PAY','TIMESHEET_PAY','TIMESHEET_PAYMENT','TS_BUCKET')
                      ) THEN COALESCE(
                        NULLIF(BTRIM(component_probe.component_json->>'label'), ''),
                        NULLIF(UPPER(BTRIM(component_probe.component_json->>'bucket_code')), ''),
                        NULLIF(UPPER(BTRIM(component_probe.component_json #>> '{source_basis_json,bucket_code}')), ''),
                        breakdown_row.unit_name
                      )
                     ELSE breakdown_row.unit_name
                   END,
                   'quantity', CASE
                     WHEN component_probe.component_json IS NOT NULL
                      AND breakdown_row.units IS NULL
                      AND COALESCE(component_probe.component_json->>'target_units', component_probe.component_json->>'source_units', component_probe.component_json #>> '{source_basis_json,source_units}', component_probe.component_json #>> '{source_basis_json,units}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
                       THEN COALESCE(component_probe.component_json->>'target_units', component_probe.component_json->>'source_units', component_probe.component_json #>> '{source_basis_json,source_units}', component_probe.component_json #>> '{source_basis_json,units}')::numeric
                     ELSE breakdown_row.units
                   END,
                   'rate', CASE
                     WHEN component_probe.component_json IS NOT NULL
                      AND breakdown_row.rate IS NULL
                      AND COALESCE(component_probe.component_json->>'target_rate', component_probe.component_json->>'source_rate', component_probe.component_json #>> '{source_basis_json,source_rate}', component_probe.component_json #>> '{source_basis_json,rate}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
                       THEN COALESCE(component_probe.component_json->>'target_rate', component_probe.component_json->>'source_rate', component_probe.component_json #>> '{source_basis_json,source_rate}', component_probe.component_json #>> '{source_basis_json,rate}')::numeric
                     ELSE breakdown_row.rate
                   END,
                   'total_ex_vat', COALESCE(breakdown_row.amount_ex_vat, item_row.amount_ex_vat),
                   'total_vat', COALESCE(breakdown_row.amount_vat, item_row.amount_vat),
                   'total_inc_vat', COALESCE(breakdown_row.amount_inc_vat, item_row.amount_inc_vat),
                   'is_deduction', item_row.item_type IN ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY')
                 )) ORDER BY item_row.id::text, breakdown_row.id::text NULLS LAST)
                 FROM jsonb_array_elements(COALESCE(job_rows.payload_json->'pay_batch_item_ids', '[]'::jsonb)) AS item_id(value)
                 JOIN public.pay_batch_items AS item_row
                   ON item_row.id = (item_id.value #>> '{}')::uuid
                 JOIN public.pay_batch_candidates AS candidate_row
                   ON candidate_row.id = item_row.pay_batch_candidate_id
                  AND candidate_row.pay_batch_id = p_pay_batch_id
                 LEFT JOIN public.pay_batch_item_breakdowns AS breakdown_row
                   ON breakdown_row.pay_batch_item_id = item_row.id
                 LEFT JOIN LATERAL (
                   SELECT component_entry.component_json
                   FROM jsonb_array_elements(
                     CASE
                       WHEN jsonb_typeof(breakdown_row.meta_json->'resolution_payload_json'->'case_components') = 'array'
                         THEN breakdown_row.meta_json->'resolution_payload_json'->'case_components'
                       ELSE '[]'::jsonb
                     END
                   ) WITH ORDINALITY AS component_entry(component_json, component_ordinal)
                   WHERE component_entry.component_json IS NOT NULL
                     AND jsonb_typeof(component_entry.component_json) = 'object'
                     AND (
                       NULLIF(BTRIM(COALESCE(component_entry.component_json->>'label', '')), '') IS NOT NULL
                       OR NULLIF(BTRIM(COALESCE(component_entry.component_json->>'bucket_code', component_entry.component_json #>> '{source_basis_json,bucket_code}', '')), '') IS NOT NULL
                       OR COALESCE(component_entry.component_json->>'target_units', component_entry.component_json->>'source_units', component_entry.component_json #>> '{source_basis_json,source_units}', component_entry.component_json #>> '{source_basis_json,units}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
                       OR COALESCE(component_entry.component_json->>'target_rate', component_entry.component_json->>'source_rate', component_entry.component_json #>> '{source_basis_json,source_rate}', component_entry.component_json #>> '{source_basis_json,rate}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
                     )
                   ORDER BY component_entry.component_ordinal
                   LIMIT 1
                 ) AS component_probe
                   ON upper(coalesce(breakdown_row.line_kind,'')) = 'TS_BUCKET'
                  AND NULLIF(BTRIM(COALESCE(breakdown_row.bucket_code, '')), '') IS NULL
                  AND breakdown_row.units IS NULL
                  AND breakdown_row.rate IS NULL
                  AND (
                    NULLIF(BTRIM(COALESCE(breakdown_row.unit_name, '')), '') IS NULL
                    OR UPPER(BTRIM(COALESCE(breakdown_row.unit_name, ''))) IN ('SEGMENT_DELTA','TIMESHEET PAY','TIMESHEET_PAY','TIMESHEET_PAYMENT','TS_BUCKET')
                  )
                 WHERE (item_id.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                   AND COALESCE(item_row.is_voided, false) = false
               ), '[]'::jsonb),
               'payload_json', job_rows.payload_json
             )) ORDER BY job_rows.id::text), '[]'::jsonb)
      INTO v_matched_scope_count,
           v_operation_scope_ids,
           v_operation_jobs
      FROM job_rows;

      IF v_matched_scope_count <> v_requested_scope_count THEN
        RAISE EXCEPTION 'pay_remittance_build operation mode one or more remittance scope ids do not belong to operation % and batch %', p_operation_id, p_pay_batch_id;
      END IF;

      v_selected_scope_count := v_matched_scope_count;
      v_known_scope_count := v_matched_scope_count;
      v_next_cursor_json := NULL::jsonb;
    ELSE
      WITH selected_scope AS (
        SELECT scope_row.*
        FROM public.banking_pay_operation_remittance_scope AS scope_row
        WHERE scope_row.operation_id = p_operation_id
          AND scope_row.pay_batch_id = p_pay_batch_id
          AND scope_row.status IN ('PENDING', 'FAILED')
          AND (v_cursor_scope_id IS NULL OR scope_row.id::text > v_cursor_scope_id::text)
        ORDER BY scope_row.id::text
        LIMIT v_limit
      ), job_rows AS (
        SELECT
          selected_scope.id,
          selected_scope.status,
          selected_scope.pay_batch_candidate_id,
          selected_scope.candidate_id,
          selected_scope.recipient_kind,
          selected_scope.recipient_id,
          selected_scope.remittance_type,
          selected_scope.deterministic_outbox_key,
          selected_scope.payload_json,
          selected_scope.outbox_id,
          CASE
            WHEN upper(coalesce(selected_scope.recipient_kind, '')) = 'CANDIDATE' THEN candidate_row.email
            WHEN upper(coalesce(selected_scope.recipient_kind, '')) = 'UMBRELLA' THEN umbrella_row.remittance_email
            ELSE NULL::text
          END AS recipient_email,
          CASE
            WHEN upper(coalesce(selected_scope.recipient_kind, '')) = 'CANDIDATE' THEN candidate_row.display_name
            WHEN upper(coalesce(selected_scope.recipient_kind, '')) = 'UMBRELLA' THEN umbrella_row.name
            ELSE NULL::text
          END AS recipient_name
        FROM selected_scope
        LEFT JOIN public.candidates AS candidate_row
          ON upper(coalesce(selected_scope.recipient_kind, '')) = 'CANDIDATE'
         AND candidate_row.id = selected_scope.recipient_id
        LEFT JOIN public.umbrellas AS umbrella_row
          ON upper(coalesce(selected_scope.recipient_kind, '')) = 'UMBRELLA'
         AND umbrella_row.id = selected_scope.recipient_id
      )
      SELECT COUNT(*)::integer,
             COALESCE(jsonb_agg(to_jsonb(job_rows.id::text) ORDER BY job_rows.id::text), '[]'::jsonb),
             COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
               'job_kind', job_rows.remittance_type,
               'operation_id', p_operation_id::text,
               'pay_batch_id', p_pay_batch_id::text,
               'remittance_scope_id', job_rows.id::text,
               'deterministic_outbox_key', job_rows.deterministic_outbox_key,
               'status', job_rows.status,
               'outbox_id', CASE WHEN job_rows.outbox_id IS NULL THEN NULL ELSE job_rows.outbox_id::text END,
               'recipient', jsonb_strip_nulls(jsonb_build_object(
                 'entity_kind', lower(coalesce(job_rows.recipient_kind, '')),
                 'entity_id', CASE WHEN job_rows.recipient_id IS NULL THEN NULL ELSE job_rows.recipient_id::text END,
                 'candidate_id', CASE WHEN upper(coalesce(job_rows.recipient_kind, '')) = 'CANDIDATE' AND job_rows.recipient_id IS NOT NULL THEN job_rows.recipient_id::text ELSE NULL END,
                 'umbrella_id', CASE WHEN upper(coalesce(job_rows.recipient_kind, '')) = 'UMBRELLA' AND job_rows.recipient_id IS NOT NULL THEN job_rows.recipient_id::text ELSE NULL END,
                 'name', job_rows.recipient_name,
                 'email', job_rows.recipient_email,
                 'remittance_email', job_rows.recipient_email
               )),
               'payment_scope_json', jsonb_strip_nulls(COALESCE(job_rows.payload_json, '{}'::jsonb) || jsonb_build_object(
                 'pay_batch_id', p_pay_batch_id::text,
                 'operation_id', p_operation_id::text,
                 'remittance_scope_id', job_rows.id::text,
                 'deterministic_outbox_key', job_rows.deterministic_outbox_key,
                 'remittance_type', job_rows.remittance_type
               )),
               'remittance_payload_version', 2,
               'payload_hash', md5(jsonb_strip_nulls(COALESCE(job_rows.payload_json, '{}'::jsonb) || jsonb_build_object(
                 'pay_batch_id', p_pay_batch_id::text,
                 'operation_id', p_operation_id::text,
                 'remittance_scope_id', job_rows.id::text,
                 'deterministic_outbox_key', job_rows.deterministic_outbox_key,
                 'remittance_type', job_rows.remittance_type
               ))::text),
               'pay_date', CASE WHEN COALESCE(v_batch.authoritative_payment_date, v_batch.pay_date) IS NULL THEN NULL ELSE COALESCE(v_batch.authoritative_payment_date, v_batch.pay_date)::text END,
               'authoritative_payment_date', CASE WHEN v_batch.authoritative_payment_date IS NULL THEN NULL ELSE v_batch.authoritative_payment_date::text END,
               'authoritative_payment_date_source', v_batch.authoritative_payment_date_source,
               'bulk_reference', v_batch.bulk_reference,
               'candidate_id', CASE WHEN job_rows.candidate_id IS NULL THEN NULL ELSE job_rows.candidate_id::text END,
               'pay_batch_candidate_ids', CASE WHEN job_rows.pay_batch_candidate_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(job_rows.pay_batch_candidate_id::text) END,
               'candidate', COALESCE((
                 SELECT jsonb_strip_nulls(jsonb_build_object(
                   'candidate_id', candidate_label.id::text,
                   'stable_candidate_key', candidate_label.id::text,
                   'tms_ref', candidate_label.tms_ref,
                   'candidate_tms_ref', candidate_label.tms_ref,
                   'works_number', candidate_label.tms_ref,
                   'display_name', candidate_label.display_name,
                   'candidate_display_name', candidate_label.display_name,
                   'email', candidate_label.email
                 ))
                 FROM public.candidates AS candidate_label
                 WHERE candidate_label.id = job_rows.candidate_id
                 LIMIT 1
               ), '{}'::jsonb),
               'umbrella', COALESCE((
                 SELECT jsonb_strip_nulls(jsonb_build_object(
                   'umbrella_id', umbrella_label.id::text,
                   'name', umbrella_label.name,
                   'remittance_email', umbrella_label.remittance_email
                 ))
                 FROM public.umbrellas AS umbrella_label
                 WHERE upper(coalesce(job_rows.recipient_kind, '')) = 'UMBRELLA'
                   AND umbrella_label.id = job_rows.recipient_id
                 LIMIT 1
               ), '{}'::jsonb),
               'summary', jsonb_strip_nulls(jsonb_build_object(
                 'payment_amount', round(COALESCE(NULLIF(job_rows.payload_json->>'total_amount', '')::numeric, 0), 2),
                 'total_amount', round(COALESCE(NULLIF(job_rows.payload_json->>'total_amount', '')::numeric, 0), 2),
                 'currency', 'GBP',
                 'item_count', COALESCE(NULLIF(job_rows.payload_json->>'item_count', '')::integer, 0),
                 'final_payable', round(COALESCE(NULLIF(job_rows.payload_json->>'total_amount', '')::numeric, 0), 2)
               )),
               'pay_batch_item_ids', COALESCE(job_rows.payload_json->'pay_batch_item_ids', '[]'::jsonb),
               'pay_bank_transfer_ids', COALESCE((
                 SELECT jsonb_agg(DISTINCT transfer_ids.transfer_id_text ORDER BY transfer_ids.transfer_id_text)
                 FROM (
                   SELECT transfer_row.id::text AS transfer_id_text
                   FROM public.pay_bank_transfers AS transfer_row
                   WHERE transfer_row.pay_batch_id = p_pay_batch_id
                     AND (
                       transfer_row.id::text = NULLIF(job_rows.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')
                       OR EXISTS (
                         SELECT 1
                         FROM jsonb_array_elements(COALESCE(job_rows.payload_json->'pay_batch_item_ids', '[]'::jsonb)) AS item_id(value)
                         JOIN public.pay_batch_items AS item_row
                           ON item_row.id = (item_id.value #>> '{}')::uuid
                         WHERE (item_id.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                           AND item_row.pay_bank_transfer_id = transfer_row.id
                       )
                     )
                 ) AS transfer_ids
               ), '[]'::jsonb),
               'transfers', COALESCE((
                 SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                   'transfer_id', transfer_row.id::text,
                   'pay_bank_transfer_id', transfer_row.id::text,
                   'candidate_id', CASE WHEN transfer_row.candidate_id IS NULL THEN NULL ELSE transfer_row.candidate_id::text END,
                   'umbrella_id', CASE WHEN transfer_row.umbrella_id IS NULL THEN NULL ELSE transfer_row.umbrella_id::text END,
                   'pay_channel', transfer_row.pay_channel,
                   'amount', transfer_row.amount,
                   'currency', COALESCE(NULLIF(BTRIM(COALESCE(transfer_row.currency, '')), ''), 'GBP'),
                   'status', transfer_row.status,
                   'payment_reference', transfer_row.payment_reference,
                   'rail_tx_id', transfer_row.rail_tx_id,
                   'provider_transaction_id', COALESCE(transfer_row.rail_tx_id, transfer_row.rail_meta_json #>> '{provider_transaction_id}', transfer_row.rail_meta_json #>> '{transaction_id}', transfer_row.rail_meta_json #>> '{provider_payment_id}'),
                   'rail_state', transfer_row.rail_state,
                   'completed_at_utc', CASE WHEN transfer_row.completed_at_utc IS NULL THEN NULL ELSE transfer_row.completed_at_utc::text END,
                   'rail_meta_json', transfer_row.rail_meta_json
                 )) ORDER BY transfer_row.id::text)
                 FROM public.pay_bank_transfers AS transfer_row
                 WHERE transfer_row.pay_batch_id = p_pay_batch_id
                   AND (
                     transfer_row.id::text = NULLIF(job_rows.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')
                     OR EXISTS (
                       SELECT 1
                       FROM jsonb_array_elements(COALESCE(job_rows.payload_json->'pay_batch_item_ids', '[]'::jsonb)) AS item_id(value)
                       JOIN public.pay_batch_items AS item_row
                         ON item_row.id = (item_id.value #>> '{}')::uuid
                       WHERE (item_id.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                         AND item_row.pay_bank_transfer_id = transfer_row.id
                     )
                   )
               ), '[]'::jsonb),
               'lines', COALESCE((
                 SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                   'pay_batch_item_id', item_row.id::text,
                   'pay_batch_item_breakdown_id', CASE WHEN breakdown_row.id IS NULL THEN NULL ELSE breakdown_row.id::text END,
                   'pay_batch_candidate_id', item_row.pay_batch_candidate_id::text,
                   'candidate_id', CASE WHEN candidate_row.candidate_id IS NULL THEN NULL ELSE candidate_row.candidate_id::text END,
                   'timesheet_id', CASE WHEN item_row.timesheet_id IS NULL THEN NULL ELSE item_row.timesheet_id::text END,
                   'pay_bank_transfer_id', CASE WHEN item_row.pay_bank_transfer_id IS NULL THEN NULL ELSE item_row.pay_bank_transfer_id::text END,
                   'item_type', item_row.item_type,
                   'description', item_row.description,
                   'source_ref', item_row.source_ref,
                   'pay_channel', item_row.pay_channel,
                   'line_kind', COALESCE(breakdown_row.line_kind, item_row.item_type),
                   'bucket_code', COALESCE(
                     NULLIF(UPPER(BTRIM(COALESCE(breakdown_row.bucket_code, ''))), ''),
                     CASE WHEN component_probe.component_json IS NULL THEN NULL ELSE NULLIF(UPPER(BTRIM(COALESCE(component_probe.component_json->>'bucket_code', component_probe.component_json #>> '{source_basis_json,bucket_code}', component_probe.component_json->>'label', ''))), '') END
                   ),
                   'unit', CASE
                     WHEN component_probe.component_json IS NOT NULL
                      AND (
                        NULLIF(BTRIM(COALESCE(breakdown_row.unit_name, '')), '') IS NULL
                        OR UPPER(BTRIM(COALESCE(breakdown_row.unit_name, ''))) IN ('SEGMENT_DELTA','TIMESHEET PAY','TIMESHEET_PAY','TIMESHEET_PAYMENT','TS_BUCKET')
                      ) THEN COALESCE(
                        NULLIF(BTRIM(component_probe.component_json->>'label'), ''),
                        NULLIF(UPPER(BTRIM(component_probe.component_json->>'bucket_code')), ''),
                        NULLIF(UPPER(BTRIM(component_probe.component_json #>> '{source_basis_json,bucket_code}')), ''),
                        breakdown_row.unit_name
                      )
                     ELSE breakdown_row.unit_name
                   END,
                   'quantity', CASE
                     WHEN component_probe.component_json IS NOT NULL
                      AND breakdown_row.units IS NULL
                      AND COALESCE(component_probe.component_json->>'target_units', component_probe.component_json->>'source_units', component_probe.component_json #>> '{source_basis_json,source_units}', component_probe.component_json #>> '{source_basis_json,units}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
                       THEN COALESCE(component_probe.component_json->>'target_units', component_probe.component_json->>'source_units', component_probe.component_json #>> '{source_basis_json,source_units}', component_probe.component_json #>> '{source_basis_json,units}')::numeric
                     ELSE breakdown_row.units
                   END,
                   'rate', CASE
                     WHEN component_probe.component_json IS NOT NULL
                      AND breakdown_row.rate IS NULL
                      AND COALESCE(component_probe.component_json->>'target_rate', component_probe.component_json->>'source_rate', component_probe.component_json #>> '{source_basis_json,source_rate}', component_probe.component_json #>> '{source_basis_json,rate}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
                       THEN COALESCE(component_probe.component_json->>'target_rate', component_probe.component_json->>'source_rate', component_probe.component_json #>> '{source_basis_json,source_rate}', component_probe.component_json #>> '{source_basis_json,rate}')::numeric
                     ELSE breakdown_row.rate
                   END,
                   'total_ex_vat', COALESCE(breakdown_row.amount_ex_vat, item_row.amount_ex_vat),
                   'total_vat', COALESCE(breakdown_row.amount_vat, item_row.amount_vat),
                   'total_inc_vat', COALESCE(breakdown_row.amount_inc_vat, item_row.amount_inc_vat),
                   'is_deduction', item_row.item_type IN ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY')
                 )) ORDER BY item_row.id::text, breakdown_row.id::text NULLS LAST)
                 FROM jsonb_array_elements(COALESCE(job_rows.payload_json->'pay_batch_item_ids', '[]'::jsonb)) AS item_id(value)
                 JOIN public.pay_batch_items AS item_row
                   ON item_row.id = (item_id.value #>> '{}')::uuid
                 JOIN public.pay_batch_candidates AS candidate_row
                   ON candidate_row.id = item_row.pay_batch_candidate_id
                  AND candidate_row.pay_batch_id = p_pay_batch_id
                 LEFT JOIN public.pay_batch_item_breakdowns AS breakdown_row
                   ON breakdown_row.pay_batch_item_id = item_row.id
                 LEFT JOIN LATERAL (
                   SELECT component_entry.component_json
                   FROM jsonb_array_elements(
                     CASE
                       WHEN jsonb_typeof(breakdown_row.meta_json->'resolution_payload_json'->'case_components') = 'array'
                         THEN breakdown_row.meta_json->'resolution_payload_json'->'case_components'
                       ELSE '[]'::jsonb
                     END
                   ) WITH ORDINALITY AS component_entry(component_json, component_ordinal)
                   WHERE component_entry.component_json IS NOT NULL
                     AND jsonb_typeof(component_entry.component_json) = 'object'
                     AND (
                       NULLIF(BTRIM(COALESCE(component_entry.component_json->>'label', '')), '') IS NOT NULL
                       OR NULLIF(BTRIM(COALESCE(component_entry.component_json->>'bucket_code', component_entry.component_json #>> '{source_basis_json,bucket_code}', '')), '') IS NOT NULL
                       OR COALESCE(component_entry.component_json->>'target_units', component_entry.component_json->>'source_units', component_entry.component_json #>> '{source_basis_json,source_units}', component_entry.component_json #>> '{source_basis_json,units}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
                       OR COALESCE(component_entry.component_json->>'target_rate', component_entry.component_json->>'source_rate', component_entry.component_json #>> '{source_basis_json,source_rate}', component_entry.component_json #>> '{source_basis_json,rate}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
                     )
                   ORDER BY component_entry.component_ordinal
                   LIMIT 1
                 ) AS component_probe
                   ON upper(coalesce(breakdown_row.line_kind,'')) = 'TS_BUCKET'
                  AND NULLIF(BTRIM(COALESCE(breakdown_row.bucket_code, '')), '') IS NULL
                  AND breakdown_row.units IS NULL
                  AND breakdown_row.rate IS NULL
                  AND (
                    NULLIF(BTRIM(COALESCE(breakdown_row.unit_name, '')), '') IS NULL
                    OR UPPER(BTRIM(COALESCE(breakdown_row.unit_name, ''))) IN ('SEGMENT_DELTA','TIMESHEET PAY','TIMESHEET_PAY','TIMESHEET_PAYMENT','TS_BUCKET')
                  )
                 WHERE (item_id.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                   AND COALESCE(item_row.is_voided, false) = false
               ), '[]'::jsonb),
               'payload_json', job_rows.payload_json
             )) ORDER BY job_rows.id::text), '[]'::jsonb),
             CASE
               WHEN COUNT(*) = 0 THEN NULL::jsonb
               ELSE jsonb_build_object('last_remittance_scope_id', max(job_rows.id::text))
             END
      INTO v_selected_scope_count,
           v_operation_scope_ids,
           v_operation_jobs,
           v_next_cursor_json
      FROM job_rows;

      SELECT COUNT(*)::integer
      INTO v_known_scope_count
      FROM public.banking_pay_operation_remittance_scope AS scope_count_row
      WHERE scope_count_row.operation_id = p_operation_id
        AND scope_count_row.pay_batch_id = p_pay_batch_id
        AND scope_count_row.status IN ('PENDING', 'FAILED');
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'operation_mode', true,
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'scope', v_scope,
      'pay_date', CASE WHEN COALESCE(v_batch.authoritative_payment_date, v_batch.pay_date) IS NULL THEN NULL ELSE COALESCE(v_batch.authoritative_payment_date, v_batch.pay_date)::text END,
      'authoritative_payment_date', CASE WHEN v_batch.authoritative_payment_date IS NULL THEN NULL ELSE v_batch.authoritative_payment_date::text END,
      'authoritative_payment_date_source', v_batch.authoritative_payment_date_source,
      'bulk_reference', v_batch.bulk_reference,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', CASE WHEN v_batch.execution_committed_at_utc IS NULL THEN NULL ELSE v_batch.execution_committed_at_utc::text END,
      'candidate_count_targeted', v_selected_scope_count,
      'scope_count', v_selected_scope_count,
      'known_count', v_known_scope_count,
      'remittance_payload_version', 2,
      'payload_render_version', 2,
      'remittance_scope_ids', v_operation_scope_ids,
      'next_cursor', v_next_cursor_json,
      'jobs', v_operation_jobs
    );
  END IF;

  -- ✅ Load remittance settings + new defaults (single row, id=1 semantics)
  select
    sd.remittance_includes_json,
    sd.remittance_header_message,
    sd.remittance_footer_message,
    coalesce(sd.paye_remittances_enabled,false) as paye_remittances_enabled,
    coalesce(sd.remittances_detailed_breakdown,false) as remittances_detailed_breakdown,
    coalesce(sd.remittance_receive_when_umbrella_paid,false) as remittance_receive_when_umbrella_paid
  into
    v_remittance_includes_json,
    v_remittance_header_message,
    v_remittance_footer_message,
    v_sd_paye_remittances_enabled,
    v_sd_remittances_detailed_breakdown,
    v_sd_remittance_receive_when_umbrella_paid
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  -- ✅ Normalize include config defaults (safe when config is NULL or not an object)
  if v_remittance_includes_json is not null and jsonb_typeof(v_remittance_includes_json) = 'object' then
    v_missing_scope := upper(btrim(coalesce(v_remittance_includes_json->'defaults'->>'missing_scope', 'WEEKLY')));

    v_unknown_item_type_default_text := lower(btrim(coalesce(v_remittance_includes_json->'defaults'->>'unknown_item_type', 'true')));
    v_unknown_item_type_default := (v_unknown_item_type_default_text in ('true','1','yes','y','on'));
  else
    v_missing_scope := 'WEEKLY';
    v_unknown_item_type_default := true;
  end if;

  if v_unknown_item_type_default then
    v_unknown_item_type_default_text := 'true';
  else
    v_unknown_item_type_default_text := 'false';
  end if;

  select
    pb.id,
    pb.pay_date,
    pb.authoritative_payment_date,
    pb.authoritative_payment_date_source,
    pb.status,
    pb.bulk_reference,
    pb.banking_system_snapshot,
    pb.external_paye_system_snapshot,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id;

  if v_batch.id is null then
    raise exception 'pay_remittance_build: pay batch % not found.', p_pay_batch_id;
  end if;

  SELECT COUNT(*)::integer
  INTO v_legacy_scope_count
  FROM public.pay_batch_candidates AS legacy_candidate_count
  WHERE legacy_candidate_count.pay_batch_id = p_pay_batch_id
    AND legacy_candidate_count.remittance_sent_at_utc IS NULL;

  IF COALESCE(v_legacy_scope_count, 0) > 250 THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_REMITTANCE_BUILD_OPERATION_REQUIRED',
      'code', 'REMITTANCE_OPERATION_REQUIRED',
      'message', 'pay_remittance_build legacy mode is limited to small batches; use the scalable remittance operation for this payment batch.',
      'pay_batch_id', p_pay_batch_id::text,
      'candidate_count', v_legacy_scope_count,
      'legacy_safe_threshold', 250
    )::text;
  END IF;

  -- ============================================================
  -- Umbrella remittance jobs (recipient = umbrella)
  -- HARD RULES:
  --  - generate only when umbrella transfers exist AND umbrella remittance_email exists
  --  - detailed_breakdown resolved from umbrella overrides vs settings_defaults
  --  - when detailed_breakdown=true and SEGMENT timesheet: include schedule rows (worked shifts only)
  --  - aggregate timesheets never include schedules
  --  - include canonical breakdown lines via pay_batch_item_breakdowns (no derived rates)
  -- ============================================================
  if v_scope in ('ALL','UMBRELLA') then
    with umb_transfers as (
      select
        pbt.id as transfer_id,
        pbt.pay_batch_id,
        pbt.candidate_id,
        pbt.umbrella_id,
        pbt.pay_channel,
        pbt.amount,
        pbt.currency,
        pbt.status,
        pbt.payment_reference,
        pbt.completed_at_utc,
        pbt.rail_tx_id,
        pbt.rail_state,
        pbt.rail_meta_json,
        pbt.failed_reason,
        (
          upper(coalesce(pbt.rail_state,'')) = 'PAYROLL_TESTING'
          or (
            pbt.rail_meta_json is not null
            and (pbt.rail_meta_json ? 'simulated')
            and lower(btrim(coalesce(pbt.rail_meta_json->>'simulated',''))) in ('true','1','yes','y','on')
          )
        ) as is_simulated
      from public.pay_bank_transfers pbt
      where pbt.pay_batch_id = p_pay_batch_id
        and upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA'
        and pbt.umbrella_id is not null
        and pbt.candidate_id is not null
    ),
    umb_roster as (
      select
        ut.umbrella_id,
        max(u.name) as umbrella_name,
        max(u.remittance_email) as remittance_email,
        bool_or(coalesce(u.remittance_overrides_enabled,false)) as umb_override_enabled,
        bool_or(coalesce(u.remittances_detailed_breakdown,false)) as umb_detail_enabled,
        bool_or(coalesce(ut.is_simulated,false)) as test_mode
      from umb_transfers ut
      join public.umbrellas u
        on u.id = ut.umbrella_id
      group by ut.umbrella_id
      having nullif(btrim(coalesce(max(u.remittance_email),'')),'') is not null
    ),
    umb_job_flags as (
      select
        ur.umbrella_id,
        case
          when ur.umb_override_enabled then ur.umb_detail_enabled
          else v_sd_remittances_detailed_breakdown
        end as detailed_breakdown
      from umb_roster ur
    ),
    umb_candidates as (
      select distinct
        ut.umbrella_id,
        ut.candidate_id
      from umb_transfers ut
    ),
    cand_meta as (
      select
        uc.umbrella_id,
        c.id as candidate_id,
        c.tms_ref as tms_ref,
        c.display_name as display_name,
        c.email as email
      from umb_candidates uc
      join public.candidates c
        on c.id = uc.candidate_id
    ),
    ts_scope_artifact as (
      select distinct on (tss.candidate_id, tss.timesheet_id)
        tss.candidate_id,
        tss.timesheet_id,
        case
          when tss.target_snapshot_json is not null
           and jsonb_typeof(tss.target_snapshot_json) = 'object'
           and jsonb_typeof(tss.target_snapshot_json->'segments') = 'array'
           and exists (
             select 1
             from jsonb_array_elements(tss.target_snapshot_json->'segments') s
             where s is not null
               and jsonb_typeof(s) = 'object'
               and nullif(btrim(coalesce(s->>'date','')),'') is not null
           )
          then 'DAILY'
          else 'WEEKLY'
        end as sheet_scope_norm
      from public.pay_batch_timesheet_snapshots tss
      where tss.pay_batch_id = p_pay_batch_id
        and upper(coalesce(tss.pay_channel,'')) = 'UMBRELLA'
      order by tss.candidate_id, tss.timesheet_id, tss.created_at_utc desc, tss.id desc
    ),
    cand_items as (
      select
        uc.umbrella_id,
        pbc.candidate_id,
        pbi.id as pay_batch_item_id,
        pbi.item_type,
        pbi.description,
        pbi.timesheet_id,
        pbi.segment_key,
        pbi.source_ref,
        pbi.amount_ex_vat,
        pbi.amount_vat,
        pbi.amount_inc_vat,
        pbi.pay_channel,
        pbi.umbrella_id as item_umbrella_id,
        upper(coalesce(tsa.sheet_scope_norm, v_missing_scope)) as sheet_scope_norm
      from umb_candidates uc
      join public.pay_batch_candidates pbc
        on pbc.pay_batch_id = p_pay_batch_id
       and pbc.candidate_id = uc.candidate_id
      join public.pay_batch_items pbi
        on pbi.pay_batch_candidate_id = pbc.id
      left join ts_scope_artifact tsa
        on tsa.candidate_id = pbc.candidate_id
       and tsa.timesheet_id = pbi.timesheet_id
      where upper(coalesce(pbi.pay_channel,'')) = 'UMBRELLA'
        and pbi.item_type <> 'DEBT_CREATED'
        and coalesce(pbi.is_voided,false) = false
        and (
          case
            when upper(coalesce(tsa.sheet_scope_norm, v_missing_scope)) = 'DAILY' then
              (case
                 when lower(coalesce(v_remittance_includes_json->'daily'->'include_item_types'->>pbi.item_type, v_unknown_item_type_default_text)) in ('true','1','yes','y','on')
                 then true else false end)
            else
              (case
                 when lower(coalesce(v_remittance_includes_json->'weekly'->'include_item_types'->>pbi.item_type, v_unknown_item_type_default_text)) in ('true','1','yes','y','on')
                 then true else false end)
          end
        )
    ),
    candidate_total_items as (
      select
        uc.umbrella_id,
        pbc.candidate_id,
        pbi.id as pay_batch_item_id,
        pbi.item_type,
        pbi.timesheet_id,
        pbi.amount_ex_vat,
        pbi.amount_vat,
        pbi.amount_inc_vat
      from umb_candidates uc
      join public.pay_batch_candidates pbc
        on pbc.pay_batch_id = p_pay_batch_id
       and pbc.candidate_id = uc.candidate_id
      join public.pay_batch_items pbi
        on pbi.pay_batch_candidate_id = pbc.id
      where upper(coalesce(pbi.pay_channel,'')) = 'UMBRELLA'
        and pbi.item_type <> 'DEBT_CREATED'
        and coalesce(pbi.is_voided,false) = false
    ),
    ts_meta as (
      select
        ci.umbrella_id,
        ci.candidate_id,
        ci.timesheet_id,
        ts.week_ending_date,
        ts.reference_number,
        ts.contract_id,
        nullif(btrim(coalesce(ts.job_title_norm,'')),'') as job_title_norm,
        nullif(btrim(coalesce(ts.band,'')),'') as band_norm
      from cand_items ci
      left join public.timesheets ts
        on ts.timesheet_id = ci.timesheet_id
       and ts.is_current = true
      where ci.timesheet_id is not null
      group by
        ci.umbrella_id, ci.candidate_id, ci.timesheet_id,
        ts.week_ending_date, ts.reference_number, ts.contract_id, ts.job_title_norm, ts.band
    ),
    ts_enrich as (
      select
        tm.umbrella_id,
        tm.candidate_id,
        tm.timesheet_id,
        tm.week_ending_date,
        tm.reference_number,
        vs.client_id as client_id,
        vs.client_name as client_name,
        upper(coalesce(tsa.sheet_scope_norm, v_missing_scope)) as sheet_scope,
        nullif(btrim(coalesce(ct.role, tm.job_title_norm)),'') as job_title,
        nullif(btrim(coalesce(ct.band, tm.band_norm)),'') as band
      from ts_meta tm
      left join public.contracts ct
        on ct.id = tm.contract_id
      left join public.v_timesheets_summary vs
        on vs.timesheet_id = tm.timesheet_id
      left join ts_scope_artifact tsa
        on tsa.candidate_id = tm.candidate_id
       and tsa.timesheet_id = tm.timesheet_id
    ),
    ts_snap as (
      select distinct on (
        tss.pay_batch_id,
        tss.candidate_id,
        tss.timesheet_id,
        upper(coalesce(tss.pay_channel,''))
      )
        tss.pay_batch_id,
        tss.timesheet_id,
        tss.candidate_id,
        tss.pay_channel,
        tss.base_snapshot_json,
        tss.target_snapshot_json
      from public.pay_batch_timesheet_snapshots tss
      where tss.pay_batch_id = p_pay_batch_id
        and upper(coalesce(tss.pay_channel,'')) = 'UMBRELLA'
      order by
        tss.pay_batch_id,
        tss.candidate_id,
        tss.timesheet_id,
        upper(coalesce(tss.pay_channel,'')),
        tss.created_at_utc desc,
        tss.id desc
    ),
    ts_class as (
      select
        te.umbrella_id,
        te.candidate_id,
        te.timesheet_id,
        te.week_ending_date,
        te.reference_number,
        te.client_id,
        te.client_name,
        te.sheet_scope,
        te.job_title,
        te.band,
        tsn.base_snapshot_json,
        tsn.target_snapshot_json,
        case
          when tsn.target_snapshot_json is not null
           and jsonb_typeof(tsn.target_snapshot_json) = 'object'
           and jsonb_typeof(tsn.target_snapshot_json->'segments') = 'array'
           and exists (
             select 1
             from jsonb_array_elements(tsn.target_snapshot_json->'segments') s
             where s is not null
               and jsonb_typeof(s)='object'
               and nullif(btrim(coalesce(s->>'date','')),'') is not null
           )
          then 'SEGMENT'
          else 'AGGREGATE'
        end as timesheet_render_mode,
        case
          when tsn.base_snapshot_json is null then 'Standard'
          when tsn.base_snapshot_json = '{}'::jsonb then 'Standard'
          when (
            exists (
              select 1
              from jsonb_array_elements(coalesce(tsn.base_snapshot_json->'segments','[]'::jsonb)) s
              where s is not null and jsonb_typeof(s)='object'
                and round(coalesce(nullif(s->>'pay_amount','')::numeric,0),2) <> 0
            )
            or round(coalesce(nullif(tsn.base_snapshot_json->>'additional_pay_ex_vat','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,expenses_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,travel_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,other_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0),2) <> 0
            or (
              jsonb_typeof(tsn.base_snapshot_json->'adjustments')='array'
              and jsonb_array_length(tsn.base_snapshot_json->'adjustments') > 0
            )
          )
          then 'Adjustment'
          else 'Standard'
        end as timesheet_type
      from ts_enrich te
      left join ts_snap tsn
        on tsn.timesheet_id = te.timesheet_id
       and tsn.candidate_id = te.candidate_id
    ),
    breakdown_raw as (
      select
        ci.umbrella_id,
        ci.candidate_id,
        ci.timesheet_id,
        ci.pay_batch_item_id,
        pbib.id as pay_batch_item_breakdown_id,
        pbib.line_kind,
        COALESCE(
          NULLIF(UPPER(BTRIM(COALESCE(pbib.bucket_code, ''))), ''),
          CASE WHEN component_probe.component_json IS NULL THEN NULL ELSE NULLIF(UPPER(BTRIM(COALESCE(component_probe.component_json->>'bucket_code', component_probe.component_json #>> '{source_basis_json,bucket_code}', component_probe.component_json->>'label', ''))), '') END
        ) as bucket_code,
        CASE
          WHEN component_probe.component_json IS NOT NULL
           AND (
             NULLIF(BTRIM(COALESCE(pbib.unit_name, '')), '') IS NULL
             OR UPPER(BTRIM(COALESCE(pbib.unit_name, ''))) IN ('SEGMENT_DELTA','TIMESHEET PAY','TIMESHEET_PAY','TIMESHEET_PAYMENT','TS_BUCKET')
           ) THEN COALESCE(
             NULLIF(BTRIM(component_probe.component_json->>'label'), ''),
             NULLIF(UPPER(BTRIM(component_probe.component_json->>'bucket_code')), ''),
             NULLIF(UPPER(BTRIM(component_probe.component_json #>> '{source_basis_json,bucket_code}')), ''),
             pbib.unit_name
           )
          ELSE pbib.unit_name
        END as unit_name,
        CASE
          WHEN component_probe.component_json IS NOT NULL
           AND pbib.units IS NULL
           AND COALESCE(component_probe.component_json->>'target_units', component_probe.component_json->>'source_units', component_probe.component_json #>> '{source_basis_json,source_units}', component_probe.component_json #>> '{source_basis_json,units}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN COALESCE(component_probe.component_json->>'target_units', component_probe.component_json->>'source_units', component_probe.component_json #>> '{source_basis_json,source_units}', component_probe.component_json #>> '{source_basis_json,units}')::numeric
          ELSE pbib.units
        END as units,
        CASE
          WHEN component_probe.component_json IS NOT NULL
           AND pbib.rate IS NULL
           AND COALESCE(component_probe.component_json->>'target_rate', component_probe.component_json->>'source_rate', component_probe.component_json #>> '{source_basis_json,source_rate}', component_probe.component_json #>> '{source_basis_json,rate}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN COALESCE(component_probe.component_json->>'target_rate', component_probe.component_json->>'source_rate', component_probe.component_json #>> '{source_basis_json,source_rate}', component_probe.component_json #>> '{source_basis_json,rate}')::numeric
          ELSE pbib.rate
        END as rate,
        pbib.amount_ex_vat,
        pbib.amount_vat,
        pbib.amount_inc_vat
      from cand_items ci
      join public.pay_batch_item_breakdowns pbib
        on pbib.pay_batch_item_id = ci.pay_batch_item_id
      left join lateral (
        select component_entry.component_json
        from jsonb_array_elements(
          case
            when jsonb_typeof(pbib.meta_json->'resolution_payload_json'->'case_components') = 'array'
              then pbib.meta_json->'resolution_payload_json'->'case_components'
            else '[]'::jsonb
          end
        ) with ordinality as component_entry(component_json, component_ordinal)
        where component_entry.component_json is not null
          and jsonb_typeof(component_entry.component_json) = 'object'
          and (
            NULLIF(BTRIM(COALESCE(component_entry.component_json->>'label', '')), '') IS NOT NULL
            OR NULLIF(BTRIM(COALESCE(component_entry.component_json->>'bucket_code', component_entry.component_json #>> '{source_basis_json,bucket_code}', '')), '') IS NOT NULL
            OR COALESCE(component_entry.component_json->>'target_units', component_entry.component_json->>'source_units', component_entry.component_json #>> '{source_basis_json,source_units}', component_entry.component_json #>> '{source_basis_json,units}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            OR COALESCE(component_entry.component_json->>'target_rate', component_entry.component_json->>'source_rate', component_entry.component_json #>> '{source_basis_json,source_rate}', component_entry.component_json #>> '{source_basis_json,rate}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          )
        order by component_entry.component_ordinal
        limit 1
      ) as component_probe
        on upper(coalesce(pbib.line_kind,'')) = 'TS_BUCKET'
       and NULLIF(BTRIM(COALESCE(pbib.bucket_code, '')), '') IS NULL
       and pbib.units IS NULL
       and pbib.rate IS NULL
       and (
         NULLIF(BTRIM(COALESCE(pbib.unit_name, '')), '') IS NULL
         OR UPPER(BTRIM(COALESCE(pbib.unit_name, ''))) IN ('SEGMENT_DELTA','TIMESHEET PAY','TIMESHEET_PAY','TIMESHEET_PAYMENT','TS_BUCKET')
       )
      where ci.timesheet_id is not null
    ),
    ts_unit_rows as (
      select
        br.umbrella_id,
        br.candidate_id,
        br.timesheet_id,
        array_remove(array_agg(distinct br.pay_batch_item_id::text), NULL::text) as pay_batch_item_ids,
        array_remove(array_agg(distinct br.pay_batch_item_breakdown_id::text), NULL::text) as pay_batch_item_breakdown_ids,
        br.line_kind,
        br.bucket_code,
        br.unit_name,
        br.rate,
        round(sum(coalesce(br.units,0)),2) as quantity,
        round(sum(coalesce(br.amount_ex_vat,0)),2) as total_ex_vat,
        round(sum(coalesce(br.amount_vat,0)),2) as total_vat,
        round(sum(coalesce(br.amount_inc_vat,0)),2) as total_inc_vat
      from breakdown_raw br
      group by br.umbrella_id, br.candidate_id, br.timesheet_id, br.line_kind, br.bucket_code, br.unit_name, br.rate
      having
        round(sum(coalesce(br.units,0)),2) <> 0
        or round(sum(coalesce(br.amount_ex_vat,0)),2) <> 0
        or round(sum(coalesce(br.amount_inc_vat,0)),2) <> 0
    ),
    ts_sections as (
      select
        tc.umbrella_id,
        tc.candidate_id,
        tc.timesheet_id,
        tc.week_ending_date,
        tc.reference_number,
        tc.client_id,
        tc.client_name,
        tc.job_title,
        tc.band,
        tc.timesheet_render_mode,
        tc.timesheet_type,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat
            )
            order by
              case upper(coalesce(r.bucket_code,''))
                when 'DAY' then 1
                when 'NIGHT' then 2
                when 'SAT' then 3
                when 'SUN' then 4
                when 'BH' then 5
                else 99
              end,
              coalesce(r.unit_name,'') asc,
              coalesce(r.rate,0) asc
          )
          filter (where upper(coalesce(r.line_kind,'')) = 'TS_BUCKET'),
          '[]'::jsonb
        ) as unit_rows,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat
            )
            order by coalesce(r.unit_name,'') asc, coalesce(r.rate,0) asc
          )
          filter (where upper(coalesce(r.line_kind,'')) = 'ADDITIONAL_UNIT'),
          '[]'::jsonb
        ) as additional_units_rows,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat
            )
            order by coalesce(r.unit_name,'') asc
          )
          filter (where upper(coalesce(r.line_kind,'')) in ('EXPENSE','MILEAGE')),
          '[]'::jsonb
        ) as expenses_rows,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat,
              'line_kind', case
                    when upper(coalesce(r.line_kind,'')) = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when upper(coalesce(r.line_kind,'')) = 'LOAN_PAYOUT' then 'PAYMENT_ADVANCE'
                    when upper(coalesce(r.line_kind,'')) = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_ADJUSTMENT'
                    when upper(coalesce(r.line_kind,'')) = 'UNDERPAYMENT_PAYMENT' then 'UNDERPAYMENT_PAYMENT'
                    when upper(coalesce(r.line_kind,'')) = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    when upper(coalesce(r.line_kind,'')) = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    else r.line_kind
                  end
            )
            order by coalesce(r.unit_name,'') asc
          )
          filter (where upper(coalesce(r.line_kind,'')) in ('ADJUSTMENT','CONVERSION_ADJ','LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','UNDERPAYMENT_PAYMENT','MANUAL_DEBT_RECOVERY','DEBT_CREATED')),
          '[]'::jsonb
        ) as other_rows,
        round(coalesce(sum(r.total_ex_vat),0),2) as totals_ex_vat,
        round(coalesce(sum(r.total_vat),0),2) as totals_vat,
        round(coalesce(sum(r.total_inc_vat),0),2) as totals_inc_vat,
        tc.base_snapshot_json,
        tc.target_snapshot_json
      from ts_class tc
      left join ts_unit_rows r
        on r.umbrella_id = tc.umbrella_id
       and r.candidate_id = tc.candidate_id
       and r.timesheet_id = tc.timesheet_id
      group by
        tc.umbrella_id,
        tc.candidate_id,
        tc.timesheet_id,
        tc.week_ending_date,
        tc.reference_number,
        tc.client_id,
        tc.client_name,
        tc.job_title,
        tc.band,
        tc.timesheet_render_mode,
        tc.timesheet_type,
        tc.base_snapshot_json,
        tc.target_snapshot_json
    ),
    ts_schedule_rows_all as (
      select
        ts.umbrella_id,
        ts.candidate_id,
        ts.timesheet_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'segment_id', nullif(btrim(coalesce(s->>'segment_id','')),''),
              'date', nullif(btrim(coalesce(s->>'date','')),''),
              'start_utc', nullif(btrim(coalesce(s->>'start_utc','')),''),
              'end_utc', nullif(btrim(coalesce(s->>'end_utc','')),''),
              'break_mins', coalesce(nullif(s->>'break_mins','')::numeric,0),
              'source_system', nullif(btrim(coalesce(s->>'source_system','')), ''),
              'external_row_key', nullif(btrim(coalesce(s->>'external_row_key','')), ''),
              'nhsp_shift_id', nullif(btrim(coalesce(s->>'nhsp_shift_id','')), ''),
              'shift_id', coalesce(
                nullif(btrim(coalesce(s->>'shift_id','')), ''),
                nullif(btrim(coalesce(s->>'nhsp_shift_id','')), '')
              ),
              'request_id', nullif(btrim(coalesce(s->>'request_id','')), ''),
              'hr_request_id', nullif(btrim(coalesce(s->>'hr_request_id','')), ''),
              'ref_num', nullif(btrim(coalesce(s->>'ref_num','')), ''),
              'breaks', coalesce(s->'breaks','[]'::jsonb)
            )
            order by
              nullif(btrim(coalesce(s->>'date','')),'') asc,
              nullif(btrim(coalesce(s->>'start_utc','')),'') asc,
              nullif(btrim(coalesce(s->>'segment_id','')),'') asc
          ),
          '[]'::jsonb
        ) as schedule_rows
      from ts_sections ts
      join lateral jsonb_array_elements(coalesce(ts.target_snapshot_json->'segments','[]'::jsonb)) s
        on ts.target_snapshot_json is not null
       and jsonb_typeof(ts.target_snapshot_json)='object'
      where ts.timesheet_render_mode = 'SEGMENT'
        and s is not null
        and jsonb_typeof(s)='object'
        and coalesce(nullif(s->>'exclude_from_pay','')::boolean,false) = false
        and (
          coalesce(nullif(s->>'hours_day','')::numeric,0)
          + coalesce(nullif(s->>'hours_night','')::numeric,0)
          + coalesce(nullif(s->>'hours_sat','')::numeric,0)
          + coalesce(nullif(s->>'hours_sun','')::numeric,0)
          + coalesce(nullif(s->>'hours_bh','')::numeric,0)
        ) > 0
      group by ts.umbrella_id, ts.candidate_id, ts.timesheet_id
    ),
    ts_schedule_changes_all as (
      select
        ts.umbrella_id,
        ts.candidate_id,
        ts.timesheet_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'segment_id', x.seg_id,
              'date', coalesce(x.before_seg->>'date', x.after_seg->>'date'),
              'before', jsonb_build_object(
                'start_utc', x.before_seg->>'start_utc',
                'end_utc', x.before_seg->>'end_utc',
                'break_mins', coalesce(nullif(x.before_seg->>'break_mins','')::numeric,0),
                'breaks', coalesce(x.before_seg->'breaks','[]'::jsonb),
                'exclude_from_pay', coalesce(nullif(x.before_seg->>'exclude_from_pay','')::boolean,false)
              ),
              'after', jsonb_build_object(
                'start_utc', x.after_seg->>'start_utc',
                'end_utc', x.after_seg->>'end_utc',
                'break_mins', coalesce(nullif(x.after_seg->>'break_mins','')::numeric,0),
                'breaks', coalesce(x.after_seg->'breaks','[]'::jsonb),
                'exclude_from_pay', coalesce(nullif(x.after_seg->>'exclude_from_pay','')::boolean,false)
              )
            )
            order by
              coalesce(x.before_seg->>'date', x.after_seg->>'date') asc,
              coalesce(x.before_seg->>'start_utc', x.after_seg->>'start_utc') asc,
              x.seg_id asc
          ),
          '[]'::jsonb
        ) as schedule_changes
      from (
        select
          ts0.umbrella_id,
          ts0.candidate_id,
          ts0.timesheet_id,
          nullif(btrim(coalesce(ids.s->>'segment_id','')),'') as seg_id,
          bseg.seg as before_seg,
          aseg.seg as after_seg
        from ts_sections ts0
        join lateral (
          select s
          from (
            select s0 as s from jsonb_array_elements(coalesce(ts0.base_snapshot_json->'segments','[]'::jsonb)) s0
            union all
            select s1 as s from jsonb_array_elements(coalesce(ts0.target_snapshot_json->'segments','[]'::jsonb)) s1
          ) u
          where u.s is not null and jsonb_typeof(u.s)='object'
        ) ids
          on ts0.timesheet_render_mode = 'SEGMENT'
         and ts0.timesheet_type = 'Adjustment'
        left join lateral (
          select s as seg
          from jsonb_array_elements(coalesce(ts0.base_snapshot_json->'segments','[]'::jsonb)) s
          where s is not null and jsonb_typeof(s)='object'
            and nullif(btrim(coalesce(s->>'segment_id','')),'') = nullif(btrim(coalesce(ids.s->>'segment_id','')),'')
          limit 1
        ) bseg on true
        left join lateral (
          select s as seg
          from jsonb_array_elements(coalesce(ts0.target_snapshot_json->'segments','[]'::jsonb)) s
          where s is not null and jsonb_typeof(s)='object'
            and nullif(btrim(coalesce(s->>'segment_id','')),'') = nullif(btrim(coalesce(ids.s->>'segment_id','')),'')
          limit 1
        ) aseg on true
      ) x
      join ts_sections ts
        on ts.umbrella_id = x.umbrella_id
       and ts.candidate_id = x.candidate_id
       and ts.timesheet_id = x.timesheet_id
      where x.seg_id is not null
        and (
          coalesce(x.before_seg->>'start_utc','') <> coalesce(x.after_seg->>'start_utc','')
          or coalesce(x.before_seg->>'end_utc','') <> coalesce(x.after_seg->>'end_utc','')
          or coalesce(nullif(x.before_seg->>'break_mins','')::numeric,0) <> coalesce(nullif(x.after_seg->>'break_mins','')::numeric,0)
          or coalesce(x.before_seg->'breaks','[]'::jsonb) <> coalesce(x.after_seg->'breaks','[]'::jsonb)
          or coalesce(nullif(x.before_seg->>'exclude_from_pay','')::boolean,false) <> coalesce(nullif(x.after_seg->>'exclude_from_pay','')::boolean,false)
        )
      group by ts.umbrella_id, ts.candidate_id, ts.timesheet_id
    ),
    cand_timesheets as (
      select
        ts.umbrella_id,
        ts.candidate_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', ts.candidate_id::text,
              'timesheet_id', ts.timesheet_id::text,
              'stable_timesheet_key', concat_ws('|', ts.candidate_id::text, ts.timesheet_id::text, coalesce(ts.week_ending_date::text,''), coalesce(ts.client_id::text,'')),
              'week_ending_date', case when ts.week_ending_date is null then null else ts.week_ending_date::text end,
              'reference_number', ts.reference_number,
              'client_id', case when ts.client_id is null then null else ts.client_id::text end,
              'client_name', ts.client_name,
              'job_title', ts.job_title,
              'band', ts.band,
              'timesheet_render_mode', ts.timesheet_render_mode,
              'timesheet_type', ts.timesheet_type,
              'frozen_gross_ex_vat', ts.totals_ex_vat,
              'frozen_vat', ts.totals_vat,
              'frozen_gross_inc_vat', ts.totals_inc_vat,
              'unit_rows', ts.unit_rows,
              'additional_units_rows', ts.additional_units_rows,
              'expenses_rows', ts.expenses_rows,
              'other_rows', ts.other_rows,
              'totals', jsonb_build_object(
                'total_ex_vat', ts.totals_ex_vat,
                'gross_ex_vat', ts.totals_ex_vat,
                'vat', ts.totals_vat,
                'gross_vat', ts.totals_vat,
                'total_inc_vat', ts.totals_inc_vat,
                'gross_inc_vat', ts.totals_inc_vat
              ),
              'schedule_rows', case
                when coalesce(ujf.detailed_breakdown,false) = true and ts.timesheet_render_mode = 'SEGMENT'
                  then coalesce(sr.schedule_rows,'[]'::jsonb)
                else '[]'::jsonb
              end,
              'schedule_changes', case
                when coalesce(ujf.detailed_breakdown,false) = true and ts.timesheet_render_mode = 'SEGMENT' and ts.timesheet_type = 'Adjustment'
                  then coalesce(sc.schedule_changes,'[]'::jsonb)
                else '[]'::jsonb
              end
            )
            order by ts.week_ending_date desc nulls last, ts.client_name nulls last, ts.reference_number nulls last, ts.timesheet_id
          ),
          '[]'::jsonb
        ) as timesheets_json
      from ts_sections ts
      join umb_job_flags ujf
        on ujf.umbrella_id = ts.umbrella_id
      left join ts_schedule_rows_all sr
        on sr.umbrella_id = ts.umbrella_id
       and sr.candidate_id = ts.candidate_id
       and sr.timesheet_id = ts.timesheet_id
      left join ts_schedule_changes_all sc
        on sc.umbrella_id = ts.umbrella_id
       and sc.candidate_id = ts.candidate_id
       and sc.timesheet_id = ts.timesheet_id
      group by ts.umbrella_id, ts.candidate_id
    ),
    candidate_frozen_totals as (
      select
        ci.umbrella_id,
        ci.candidate_id,
        (count(distinct ci.timesheet_id) filter (where ci.timesheet_id is not null))::integer as timesheet_count,
        count(distinct ci.pay_batch_item_id)::integer as item_count,
        round(coalesce(sum(
          case
            when ci.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then 0
            when coalesce(ci.amount_inc_vat,0) < 0 or coalesce(ci.amount_ex_vat,0) < 0 then 0
            else coalesce(ci.amount_ex_vat,0)
          end
        ),0),2) as gross_ex_vat,
        round(coalesce(sum(
          case
            when ci.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then 0
            when coalesce(ci.amount_inc_vat,0) < 0 or coalesce(ci.amount_ex_vat,0) < 0 then 0
            else coalesce(ci.amount_vat,0)
          end
        ),0),2) as gross_vat,
        round(coalesce(sum(
          case
            when ci.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then 0
            when coalesce(ci.amount_inc_vat,0) < 0 or coalesce(ci.amount_ex_vat,0) < 0 then 0
            else coalesce(ci.amount_inc_vat,0)
          end
        ),0),2) as gross_inc_vat,
        round(coalesce(sum(
          case
            when ci.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then abs(coalesce(ci.amount_ex_vat,0))
            when coalesce(ci.amount_ex_vat,0) < 0 then abs(coalesce(ci.amount_ex_vat,0))
            else 0
          end
        ),0),2) as deductions_ex_vat,
        round(coalesce(sum(
          case
            when ci.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then abs(coalesce(ci.amount_vat,0))
            when coalesce(ci.amount_vat,0) < 0 then abs(coalesce(ci.amount_vat,0))
            else 0
          end
        ),0),2) as deductions_vat,
        round(coalesce(sum(
          case
            when ci.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then abs(coalesce(ci.amount_inc_vat,0))
            when coalesce(ci.amount_inc_vat,0) < 0 then abs(coalesce(ci.amount_inc_vat,0))
            else 0
          end
        ),0),2) as deductions_inc_vat,
        round(coalesce(sum(coalesce(ci.amount_ex_vat,0)),0),2) as net_ex_vat,
        round(coalesce(sum(coalesce(ci.amount_vat,0)),0),2) as net_vat,
        round(coalesce(sum(coalesce(ci.amount_inc_vat,0)),0),2) as net_inc_vat
      from candidate_total_items ci
      group by ci.umbrella_id, ci.candidate_id
    ),
    candidate_payload as (
      select
        cm.umbrella_id,
        cm.candidate_id,
        jsonb_build_object(
          'candidate_id', cm.candidate_id::text,
          'stable_candidate_key', cm.candidate_id::text,
          'tms_ref', cm.tms_ref,
          'candidate_tms_ref', cm.tms_ref,
          'works_number', cm.tms_ref,
          'display_name', cm.display_name,
          'candidate_display_name', cm.display_name,
          'email', cm.email,
          'timesheets', coalesce(ct.timesheets_json,'[]'::jsonb),
          'totals', coalesce((
            select jsonb_build_object(
              'gross_preview', round(coalesce(pbc_tot.gross_preview,0),2),
              'overpayment_recovery_taken', round(coalesce(pbc_tot.overpayment_recovery_taken,0),2),
              'payment_advance_repayment_taken', round(coalesce(pbc_tot.loan_repayment_taken,0),2),
              'final_paid', round(coalesce(pbc_tot.net_bank_amount,0),2),
              'deductions_summary', jsonb_build_object(
                'gross_positive', round(coalesce(pbc_tot.gross_preview,0),2),
                'overpayment_recovery', round(coalesce(pbc_tot.overpayment_recovery_taken,0),2),
                'payment_advance_repayment', round(coalesce(pbc_tot.loan_repayment_taken,0),2),
                'total_deductions', round(coalesce(pbc_tot.overpayment_recovery_taken,0) + coalesce(pbc_tot.loan_repayment_taken,0),2),
                'final_payable', round(coalesce(pbc_tot.net_bank_amount,0),2),
                'has_deductions', (round(coalesce(pbc_tot.overpayment_recovery_taken,0) + coalesce(pbc_tot.loan_repayment_taken,0),2) > 0)
              )
            )
            from public.pay_batch_candidates pbc_tot
            where pbc_tot.pay_batch_id = p_pay_batch_id
              and pbc_tot.candidate_id = cm.candidate_id
            limit 1
          ), '{}'::jsonb),
          'frozen_totals', jsonb_build_object(
            'timesheet_count', coalesce(cft.timesheet_count, 0),
            'item_count', coalesce(cft.item_count, 0),
            'gross_ex_vat', round(coalesce(cft.gross_ex_vat,0),2),
            'vat', round(coalesce(cft.gross_vat,0),2),
            'gross_vat', round(coalesce(cft.gross_vat,0),2),
            'gross_inc_vat', round(coalesce(cft.gross_inc_vat,0),2),
            'deductions_ex_vat', round(coalesce(cft.deductions_ex_vat,0),2),
            'deductions_vat', round(coalesce(cft.deductions_vat,0),2),
            'deductions_inc_vat', round(coalesce(cft.deductions_inc_vat,0),2),
            'deductions_recoveries_ex_vat', round(coalesce(cft.deductions_ex_vat,0),2),
            'deductions_recoveries_vat', round(coalesce(cft.deductions_vat,0),2),
            'deductions_recoveries_inc_vat', round(coalesce(cft.deductions_inc_vat,0),2),
            'net_ex_vat', round(coalesce(cft.net_ex_vat,0),2),
            'net_vat', round(coalesce(cft.net_vat,0),2),
            'net_inc_vat', round(coalesce(cft.net_inc_vat,0),2),
            'final_payable', round(coalesce(cft.net_inc_vat,0),2)
          ),
          'non_timesheet_lines', coalesce((
            select coalesce(
              jsonb_agg(
                jsonb_build_object(
                  'pay_batch_item_id', pbi_nt.id::text,
                  'pay_batch_item_breakdown_id', pbib_nt.id::text,
                  'pay_batch_candidate_id', pbc_nt.id::text,
                  'candidate_id', pbc_nt.candidate_id::text,
                  'stable_line_key', concat_ws('|', pbc_nt.candidate_id::text, pbi_nt.id::text, pbib_nt.id::text, coalesce(pbi_nt.item_type,''), coalesce(pbi_nt.source_ref,''), coalesce(pbi_nt.finance_case_id::text,''), coalesce(pbib_nt.line_kind,''), coalesce(pbib_nt.bucket_code,''), coalesce(pbib_nt.unit_name,''), coalesce(pbib_nt.rate::text,''), coalesce(pbib_nt.amount_ex_vat::text,''), coalesce(pbib_nt.amount_vat::text,''), coalesce(pbib_nt.amount_inc_vat::text,'')),
                  'item_type', case
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 'PAYMENT_ADVANCE'
                    when pbi_nt.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_ADJUSTMENT'
                    when pbi_nt.item_type = 'UNDERPAYMENT_PAYMENT' then 'UNDERPAYMENT_PAYMENT'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    else pbi_nt.item_type
                  end,
                  'internal_item_type', pbi_nt.item_type,
                  'description', pbi_nt.description,
                  'line_kind', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 'PAYMENT_ADVANCE'
                    when pbi_nt.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_ADJUSTMENT'
                    when pbi_nt.item_type = 'UNDERPAYMENT_PAYMENT' then 'UNDERPAYMENT_PAYMENT'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    else pbib_nt.line_kind
                  end,
                  'line_label', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment Recovery'
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'Payment Advance Repayment'
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 'Payment Advance'
                    when pbi_nt.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual Credit Adjustment'
                    when pbi_nt.item_type = 'UNDERPAYMENT_PAYMENT' then 'Underpayment Payment'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'Manual Debt Recovery'
                    when nullif(btrim(coalesce(pa_fc.adjustment_comment,'')), '') is not null then pa_fc.adjustment_comment
                    when nullif(btrim(coalesce(pbib_nt.unit_name,'')), '') is not null then pbib_nt.unit_name
                    when nullif(btrim(coalesce(pbi_nt.description,'')), '') is not null then pbi_nt.description
                    else pbib_nt.line_kind
                  end,
                  'bucket_code', pbib_nt.bucket_code,
                  'unit', pbib_nt.unit_name,
                  'quantity', pbib_nt.units,
                  'rate', pbib_nt.rate,
                  'total_ex_vat', pbib_nt.amount_ex_vat,
                  'total_vat', pbib_nt.amount_vat,
                  'total_inc_vat', pbib_nt.amount_inc_vat,
                  'signed_amount_ex_vat', pbib_nt.amount_ex_vat,
                  'signed_amount_vat', pbib_nt.amount_vat,
                  'signed_amount_inc_vat', pbib_nt.amount_inc_vat,
                  'frozen_amount_ex_vat', pbib_nt.amount_ex_vat,
                  'frozen_amount_vat', pbib_nt.amount_vat,
                  'frozen_amount_inc_vat', pbib_nt.amount_inc_vat,
                  'is_deduction', (pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY')),
                  'deduction_kind', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    else null
                  end,
                  'deduction_amount_ex_vat', case
                    when pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then round(abs(coalesce(pbib_nt.amount_ex_vat,0)),2)
                    else null
                  end,
                  'deduction_amount_inc_vat', case
                    when pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then round(abs(coalesce(pbib_nt.amount_inc_vat,0)),2)
                    else null
                  end,
                  'source_ref', pbi_nt.source_ref,
                  'pay_channel', pbi_nt.pay_channel,
                  'routing_kind', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'routing_kind','')), ''),
                  'destination_label', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'destination_label','')), ''),
                  'payout_destination', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'destination_label','')), ''),
                  'masked_bank_account', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'masked_bank_account','')), ''),
                  'beneficiary_name', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'beneficiary_name','')), ''),
                  'bank_details_hash', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'bank_details_hash','')), ''),
                  'appears_on_umbrella_remittance', lower(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'appears_on_umbrella_remittance','false'))) in ('true','1','yes','y','on'),
                  'generates_candidate_payment_advice', lower(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'generates_candidate_payment_advice','false'))) in ('true','1','yes','y','on'),
                  'finance_case_id', case when coalesce(pbi_nt.finance_case_id, pa_fc.id) is null then null else coalesce(pbi_nt.finance_case_id, pa_fc.id)::text end,
                  'finance_case_type', case when pa_fc.case_type is null then null else pa_fc.case_type::text end,
                  'adjustment_comment', pa_fc.adjustment_comment,
                  'lifecycle_state', case when pa_fc.status is null then null else pa_fc.status::text end,
                  'payout_status', case when pa_fc.payout_status is null then null else pa_fc.payout_status::text end,
                  'remaining_amount', round(coalesce(pa_fc.outstanding_amount,0),2),
                  'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
                  'repayment_week_start', case when pbi_nt.repayment_week_start is null then null else pbi_nt.repayment_week_start::text end,
                  'overpayment_context', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY'
                     and pa_fc.id is not null
                     and upper(coalesce(pa_fc.case_type::text,'')) = 'OVERPAYMENT'
                     and upper(coalesce(pa_fc.status::text,'')) = 'ACTIVE'
                    then jsonb_build_object(
                      'source_timesheet_id', case when pa_fc.linked_timesheet_id is null then null else pa_fc.linked_timesheet_id::text end,
                      'shift_date', case when pa_fc.linked_shift_date is null then null else pa_fc.linked_shift_date::text end,
                      'original_paid_amount', round(coalesce(pa_fc.source_original_paid_amount, pa_fc.original_amount, 0),2),
                      'corrected_paid_amount', round(coalesce(pa_fc.source_corrected_paid_amount, greatest(coalesce(pa_fc.original_amount,0) - coalesce(pa_fc.outstanding_amount,0),0), 0),2),
                      'recovery_this_payment', round(abs(coalesce(pbib_nt.amount_ex_vat,0)),2),
                      'remaining_balance', round(coalesce(pa_fc.outstanding_amount,0),2)
                    )
                    else null
                  end
                )
                order by
                  case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 1
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 2
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 3
                    when pbi_nt.item_type = 'UNDERPAYMENT_PAYMENT' then 4
                    else 9
                  end,
                  coalesce(pbib_nt.line_kind,''),
                  coalesce(pbib_nt.unit_name,''),
                  coalesce(pbib_nt.rate,0)
              ),
              '[]'::jsonb
            )
            from public.pay_batch_candidates pbc_nt
            join public.pay_batch_items pbi_nt
              on pbi_nt.pay_batch_candidate_id = pbc_nt.id
            join public.pay_batch_item_breakdowns pbib_nt
              on pbib_nt.pay_batch_item_id = pbi_nt.id
            left join public.pay_advances pa_fc
              on (
                (pbi_nt.finance_case_id is not null and pa_fc.id = pbi_nt.finance_case_id)
                or (
                  pbi_nt.finance_case_id is null
                  and pbi_nt.source_ref is not null
                  and pbi_nt.source_ref = ('advance:' || pa_fc.id::text)
                )
              )
            where pbc_nt.pay_batch_id = p_pay_batch_id
              and pbc_nt.candidate_id = cm.candidate_id
              and upper(coalesce(pbi_nt.pay_channel,'')) = 'UMBRELLA'
              and pbi_nt.is_voided = false
              and pbi_nt.timesheet_id is null
              and pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','UNDERPAYMENT_PAYMENT','MANUAL_DEBT_RECOVERY')
          ), '[]'::jsonb)
        ) as candidate_json
      from cand_meta cm
      left join cand_timesheets ct
        on ct.umbrella_id = cm.umbrella_id
       and ct.candidate_id = cm.candidate_id
      left join candidate_frozen_totals cft
        on cft.umbrella_id = cm.umbrella_id
       and cft.candidate_id = cm.candidate_id
    ),
    umbrella_transfer_totals as (
      select
        ut.umbrella_id,
        round(coalesce(sum(coalesce(ut.amount,0)),0),2) as umbrella_total_amount,
        coalesce(max(nullif(btrim(coalesce(ut.currency,'')),'')), 'GBP') as currency,
        bool_or(coalesce(ut.is_simulated,false)) as transfer_test_mode,
        count(distinct ut.transfer_id)::integer as transfer_count,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'transfer_id', ut.transfer_id::text,
              'candidate_id', case when ut.candidate_id is null then null else ut.candidate_id::text end,
              'pay_channel', ut.pay_channel,
              'amount', ut.amount,
              'currency', ut.currency,
              'status', ut.status,
              'payment_reference', ut.payment_reference,
              'completed_at_utc', case when ut.completed_at_utc is null then null else ut.completed_at_utc::text end,
              'rail_tx_id', ut.rail_tx_id,
              'rail_state', ut.rail_state,
              'rail_meta_json', ut.rail_meta_json,
              'failed_reason', ut.failed_reason,
              'is_simulated', coalesce(ut.is_simulated,false)
            )
            order by ut.candidate_id, ut.transfer_id
          ),
          '[]'::jsonb
        ) as transfers_json
      from umb_transfers ut
      group by ut.umbrella_id
    ),
    umbrella_candidate_payloads as (
      select
        cp.umbrella_id,
        count(distinct cp.candidate_id)::integer as candidate_count,
        coalesce(
          jsonb_agg(cp.candidate_json order by (cp.candidate_json->>'display_name') nulls last, (cp.candidate_json->>'tms_ref') nulls last, cp.candidate_id),
          '[]'::jsonb
        ) as candidates_json
      from candidate_payload cp
      group by cp.umbrella_id
    ),
    umbrella_frozen_totals as (
      select
        cft.umbrella_id,
        coalesce(sum(coalesce(cft.timesheet_count,0)),0)::integer as timesheet_count,
        coalesce(sum(coalesce(cft.item_count,0)),0)::integer as item_count,
        round(coalesce(sum(coalesce(cft.gross_ex_vat,0)),0),2) as gross_ex_vat,
        round(coalesce(sum(coalesce(cft.gross_vat,0)),0),2) as gross_vat,
        round(coalesce(sum(coalesce(cft.gross_inc_vat,0)),0),2) as gross_inc_vat,
        round(coalesce(sum(coalesce(cft.deductions_ex_vat,0)),0),2) as deductions_ex_vat,
        round(coalesce(sum(coalesce(cft.deductions_vat,0)),0),2) as deductions_vat,
        round(coalesce(sum(coalesce(cft.deductions_inc_vat,0)),0),2) as deductions_inc_vat,
        round(coalesce(sum(coalesce(cft.net_ex_vat,0)),0),2) as net_ex_vat,
        round(coalesce(sum(coalesce(cft.net_vat,0)),0),2) as net_vat,
        round(coalesce(sum(coalesce(cft.net_inc_vat,0)),0),2) as net_inc_vat
      from candidate_frozen_totals cft
      group by cft.umbrella_id
    ),
    umb_job as (
      select
        ur.umbrella_id,
        ur.umbrella_name,
        ur.remittance_email,
        (coalesce(ur.test_mode,false) or coalesce(utt.transfer_test_mode,false)) as test_mode,
        ujf.detailed_breakdown,
        round(coalesce(utt.umbrella_total_amount,0),2) as umbrella_total_amount,
        coalesce(utt.currency, 'GBP') as currency,
        coalesce(utt.transfer_count,0) as transfer_count,
        coalesce(ucp.candidate_count,0) as candidate_count,
        coalesce(uft.timesheet_count,0) as timesheet_count,
        coalesce(uft.item_count,0) as item_count,
        round(coalesce(uft.gross_ex_vat,0),2) as gross_ex_vat,
        round(coalesce(uft.gross_vat,0),2) as gross_vat,
        round(coalesce(uft.gross_inc_vat,0),2) as gross_inc_vat,
        round(coalesce(uft.deductions_ex_vat,0),2) as deductions_ex_vat,
        round(coalesce(uft.deductions_vat,0),2) as deductions_vat,
        round(coalesce(uft.deductions_inc_vat,0),2) as deductions_inc_vat,
        round(coalesce(uft.net_ex_vat,0),2) as net_ex_vat,
        round(coalesce(uft.net_vat,0),2) as net_vat,
        round(coalesce(uft.net_inc_vat,0),2) as net_inc_vat,
        coalesce(utt.transfers_json,'[]'::jsonb) as transfers_json,
        coalesce(ucp.candidates_json,'[]'::jsonb) as candidates_json
      from umb_roster ur
      join umb_job_flags ujf
        on ujf.umbrella_id = ur.umbrella_id
      left join umbrella_transfer_totals utt
        on utt.umbrella_id = ur.umbrella_id
      left join umbrella_candidate_payloads ucp
        on ucp.umbrella_id = ur.umbrella_id
      left join umbrella_frozen_totals uft
        on uft.umbrella_id = ur.umbrella_id
    )
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'job_kind', 'UMBRELLA_REMITTANCE',
          'pay_batch_id', v_batch.id::text,
          'scope', 'UMBRELLA',
          'pay_date', case when coalesce(v_batch.authoritative_payment_date, v_batch.pay_date) is null then null else coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)::text end,
          'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
          'authoritative_payment_date_source', v_batch.authoritative_payment_date_source,
          'bulk_reference', v_batch.bulk_reference,
          'test_mode', coalesce(uj.test_mode,false),
          'detailed_breakdown', coalesce(uj.detailed_breakdown,false),
          'recipient', jsonb_build_object(
            'entity_kind', 'UMBRELLA',
            'umbrella_id', uj.umbrella_id::text,
            'name', uj.umbrella_name,
            'remittance_email', uj.remittance_email
          ),
          'summary', jsonb_build_object(
            'total_amount', uj.umbrella_total_amount,
            'currency', coalesce(uj.currency, 'GBP'),
            'transfer_count', coalesce(uj.transfer_count,0),
            'candidate_count', coalesce(uj.candidate_count,0),
            'timesheet_count', coalesce(uj.timesheet_count,0),
            'item_count', coalesce(uj.item_count,0),
            'gross_ex_vat', round(coalesce(uj.gross_ex_vat,0),2),
            'vat', round(coalesce(uj.gross_vat,0),2),
            'gross_vat', round(coalesce(uj.gross_vat,0),2),
            'gross_inc_vat', round(coalesce(uj.gross_inc_vat,0),2),
            'deductions_ex_vat', round(coalesce(uj.deductions_ex_vat,0),2),
            'deductions_vat', round(coalesce(uj.deductions_vat,0),2),
            'deductions_inc_vat', round(coalesce(uj.deductions_inc_vat,0),2),
            'deductions_recoveries_ex_vat', round(coalesce(uj.deductions_ex_vat,0),2),
            'deductions_recoveries_vat', round(coalesce(uj.deductions_vat,0),2),
            'deductions_recoveries_inc_vat', round(coalesce(uj.deductions_inc_vat,0),2),
            'net_ex_vat', round(coalesce(uj.net_ex_vat,0),2),
            'net_vat', round(coalesce(uj.net_vat,0),2),
            'net_inc_vat', round(coalesce(uj.net_inc_vat,0),2),
            'final_payable', uj.umbrella_total_amount,
            'frozen_item_net_inc_vat', round(coalesce(uj.net_inc_vat,0),2)
          ),
          'transfers', coalesce(uj.transfers_json,'[]'::jsonb),
          'candidates', coalesce(uj.candidates_json,'[]'::jsonb)
        )
        order by uj.umbrella_name nulls last, uj.umbrella_id
      ),
      '[]'::jsonb
    )
    into v_jobs_umb
    from umb_job uj;
  end if;

  -- ============================================================
  -- Candidate PAYE remittance jobs (recipient = candidate)
  -- LOCKED RULE:
  --  - generated only if effective receive is true:
  --    overrides? candidate.remittance_receive_enabled : settings_defaults.paye_remittances_enabled
  --  - detailed_breakdown resolved from candidate overrides vs settings_defaults
  -- ============================================================
  if v_scope in ('ALL','PAYE') then
    with paye_transfers as (
      select
        pbt.id as transfer_id,
        pbt.pay_batch_id,
        pbt.candidate_id,
        pbt.pay_channel,
        pbt.amount,
        pbt.currency,
        pbt.status,
        pbt.payment_reference,
        pbt.completed_at_utc,
        pbt.rail_tx_id,
        pbt.rail_state,
        pbt.rail_meta_json,
        pbt.failed_reason,
        (
          upper(coalesce(pbt.rail_state,'')) = 'PAYROLL_TESTING'
          or (
            pbt.rail_meta_json is not null
            and (pbt.rail_meta_json ? 'simulated')
            and lower(btrim(coalesce(pbt.rail_meta_json->>'simulated',''))) in ('true','1','yes','y','on')
          )
        ) as is_simulated
      from public.pay_bank_transfers pbt
      where pbt.pay_batch_id = p_pay_batch_id
        and upper(coalesce(pbt.pay_channel,'')) = 'PAYE'
        and pbt.candidate_id is not null
    ),
    cand_cfg as (
      select
        c.id as candidate_id,
        c.tms_ref,
        c.display_name,
        c.email,
        coalesce(c.remittance_overrides_enabled,false) as overrides_enabled,
        coalesce(c.remittance_receive_enabled,false) as paye_receive_enabled,
        coalesce(c.remittances_detailed_breakdown,false) as detailed_enabled
      from public.candidates c
      where c.id in (select distinct pt.candidate_id from paye_transfers pt)
    ),
    cand_effective as (
      select
        cc.*,
        (case when cc.overrides_enabled then cc.paye_receive_enabled else v_sd_paye_remittances_enabled end) as eff_paye_receive,
        (case when cc.overrides_enabled then cc.detailed_enabled else v_sd_remittances_detailed_breakdown end) as eff_detailed
      from cand_cfg cc
    ),
    cand_allowed as (
      select *
      from cand_effective ce
      where ce.eff_paye_receive = true
    ),
    ts_scope_artifact as (
      select distinct on (tss.candidate_id, tss.timesheet_id)
        tss.candidate_id,
        tss.timesheet_id,
        case
          when tss.target_snapshot_json is not null
           and jsonb_typeof(tss.target_snapshot_json) = 'object'
           and jsonb_typeof(tss.target_snapshot_json->'segments') = 'array'
           and exists (
             select 1
             from jsonb_array_elements(tss.target_snapshot_json->'segments') s
             where s is not null
               and jsonb_typeof(s) = 'object'
               and nullif(btrim(coalesce(s->>'date','')),'') is not null
           )
          then 'DAILY'
          else 'WEEKLY'
        end as sheet_scope_norm
      from public.pay_batch_timesheet_snapshots tss
      where tss.pay_batch_id = p_pay_batch_id
        and upper(coalesce(tss.pay_channel,'')) = 'PAYE'
      order by tss.candidate_id, tss.timesheet_id, tss.created_at_utc desc, tss.id desc
    ),
    cand_items as (
      select
        ca.candidate_id,
        pbi.id as pay_batch_item_id,
        pbi.item_type,
        pbi.description,
        pbi.timesheet_id,
        pbi.segment_key,
        pbi.source_ref,
        pbi.amount_ex_vat,
        pbi.amount_vat,
        pbi.amount_inc_vat,
        pbi.pay_channel
      from cand_allowed ca
      join public.pay_batch_candidates pbc
        on pbc.pay_batch_id = p_pay_batch_id
       and pbc.candidate_id = ca.candidate_id
      join public.pay_batch_items pbi
        on pbi.pay_batch_candidate_id = pbc.id
      left join ts_scope_artifact tsa
        on tsa.candidate_id = pbc.candidate_id
       and tsa.timesheet_id = pbi.timesheet_id
      where upper(coalesce(pbi.pay_channel,'')) = 'PAYE'
        and pbi.item_type <> 'DEBT_CREATED'
        and coalesce(pbi.is_voided,false) = false
        and (
          case
            when upper(coalesce(tsa.sheet_scope_norm, v_missing_scope)) = 'DAILY' then
              (case
                 when lower(coalesce(v_remittance_includes_json->'daily'->'include_item_types'->>pbi.item_type, v_unknown_item_type_default_text)) in ('true','1','yes','y','on')
                 then true else false end)
            else
              (case
                 when lower(coalesce(v_remittance_includes_json->'weekly'->'include_item_types'->>pbi.item_type, v_unknown_item_type_default_text)) in ('true','1','yes','y','on')
                 then true else false end)
          end
        )
    ),
    ts_meta as (
      select
        ci.candidate_id,
        ci.timesheet_id,
        ts.week_ending_date,
        ts.reference_number,
        ts.contract_id,
        nullif(btrim(coalesce(ts.job_title_norm,'')),'') as job_title_norm,
        nullif(btrim(coalesce(ts.band,'')),'') as band_norm
      from cand_items ci
      left join public.timesheets ts
        on ts.timesheet_id = ci.timesheet_id
       and ts.is_current = true
      where ci.timesheet_id is not null
      group by ci.candidate_id, ci.timesheet_id, ts.week_ending_date, ts.reference_number, ts.contract_id, ts.job_title_norm, ts.band
    ),
    ts_enrich as (
      select
        tm.candidate_id,
        tm.timesheet_id,
        tm.week_ending_date,
        tm.reference_number,
        vs.client_id as client_id,
        vs.client_name as client_name,
        upper(coalesce(tsa.sheet_scope_norm, v_missing_scope)) as sheet_scope,
        nullif(btrim(coalesce(ct.role, tm.job_title_norm)),'') as job_title,
        nullif(btrim(coalesce(ct.band, tm.band_norm)),'') as band
      from ts_meta tm
      left join public.contracts ct
        on ct.id = tm.contract_id
      left join public.v_timesheets_summary vs
        on vs.timesheet_id = tm.timesheet_id
      left join ts_scope_artifact tsa
        on tsa.candidate_id = tm.candidate_id
       and tsa.timesheet_id = tm.timesheet_id
    ),
    ts_snap as (
      select distinct on (
        tss.candidate_id,
        tss.timesheet_id,
        upper(coalesce(tss.pay_channel,''))
      )
        tss.timesheet_id,
        tss.candidate_id,
        tss.base_snapshot_json,
        tss.target_snapshot_json
      from public.pay_batch_timesheet_snapshots tss
      where tss.pay_batch_id = p_pay_batch_id
        and upper(coalesce(tss.pay_channel,'')) = 'PAYE'
      order by
        tss.candidate_id,
        tss.timesheet_id,
        upper(coalesce(tss.pay_channel,'')),
        tss.created_at_utc desc,
        tss.id desc
    ),
    ts_class as (
      select
        te.candidate_id,
        te.timesheet_id,
        te.week_ending_date,
        te.reference_number,
        te.client_id,
        te.client_name,
        te.sheet_scope,
        te.job_title,
        te.band,
        tsn.base_snapshot_json,
        tsn.target_snapshot_json,
        case
          when tsn.target_snapshot_json is not null
           and jsonb_typeof(tsn.target_snapshot_json) = 'object'
           and jsonb_typeof(tsn.target_snapshot_json->'segments') = 'array'
           and exists (
             select 1
             from jsonb_array_elements(tsn.target_snapshot_json->'segments') s
             where s is not null
               and jsonb_typeof(s)='object'
               and nullif(btrim(coalesce(s->>'date','')),'') is not null
           )
          then 'SEGMENT'
          else 'AGGREGATE'
        end as timesheet_render_mode,
        case
          when tsn.base_snapshot_json is null then 'Standard'
          when tsn.base_snapshot_json = '{}'::jsonb then 'Standard'
          when (
            exists (
              select 1
              from jsonb_array_elements(coalesce(tsn.base_snapshot_json->'segments','[]'::jsonb)) s
              where s is not null and jsonb_typeof(s)='object'
                and round(coalesce(nullif(s->>'pay_amount','')::numeric,0),2) <> 0
            )
            or round(coalesce(nullif(tsn.base_snapshot_json->>'additional_pay_ex_vat','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,expenses_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,travel_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,other_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0),2) <> 0
            or (
              jsonb_typeof(tsn.base_snapshot_json->'adjustments')='array'
              and jsonb_array_length(tsn.base_snapshot_json->'adjustments') > 0
            )
          )
          then 'Adjustment'
          else 'Standard'
        end as timesheet_type
      from ts_enrich te
      left join ts_snap tsn
        on tsn.timesheet_id = te.timesheet_id
       and tsn.candidate_id = te.candidate_id
    ),
    breakdown_raw as (
      select
        ci.candidate_id,
        ci.timesheet_id,
        ci.pay_batch_item_id,
        pbib.id as pay_batch_item_breakdown_id,
        pbib.line_kind,
        COALESCE(
          NULLIF(UPPER(BTRIM(COALESCE(pbib.bucket_code, ''))), ''),
          CASE WHEN component_probe.component_json IS NULL THEN NULL ELSE NULLIF(UPPER(BTRIM(COALESCE(component_probe.component_json->>'bucket_code', component_probe.component_json #>> '{source_basis_json,bucket_code}', component_probe.component_json->>'label', ''))), '') END
        ) as bucket_code,
        CASE
          WHEN component_probe.component_json IS NOT NULL
           AND (
             NULLIF(BTRIM(COALESCE(pbib.unit_name, '')), '') IS NULL
             OR UPPER(BTRIM(COALESCE(pbib.unit_name, ''))) IN ('SEGMENT_DELTA','TIMESHEET PAY','TIMESHEET_PAY','TIMESHEET_PAYMENT','TS_BUCKET')
           ) THEN COALESCE(
             NULLIF(BTRIM(component_probe.component_json->>'label'), ''),
             NULLIF(UPPER(BTRIM(component_probe.component_json->>'bucket_code')), ''),
             NULLIF(UPPER(BTRIM(component_probe.component_json #>> '{source_basis_json,bucket_code}')), ''),
             pbib.unit_name
           )
          ELSE pbib.unit_name
        END as unit_name,
        CASE
          WHEN component_probe.component_json IS NOT NULL
           AND pbib.units IS NULL
           AND COALESCE(component_probe.component_json->>'target_units', component_probe.component_json->>'source_units', component_probe.component_json #>> '{source_basis_json,source_units}', component_probe.component_json #>> '{source_basis_json,units}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN COALESCE(component_probe.component_json->>'target_units', component_probe.component_json->>'source_units', component_probe.component_json #>> '{source_basis_json,source_units}', component_probe.component_json #>> '{source_basis_json,units}')::numeric
          ELSE pbib.units
        END as units,
        CASE
          WHEN component_probe.component_json IS NOT NULL
           AND pbib.rate IS NULL
           AND COALESCE(component_probe.component_json->>'target_rate', component_probe.component_json->>'source_rate', component_probe.component_json #>> '{source_basis_json,source_rate}', component_probe.component_json #>> '{source_basis_json,rate}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN COALESCE(component_probe.component_json->>'target_rate', component_probe.component_json->>'source_rate', component_probe.component_json #>> '{source_basis_json,source_rate}', component_probe.component_json #>> '{source_basis_json,rate}')::numeric
          ELSE pbib.rate
        END as rate,
        pbib.amount_ex_vat,
        pbib.amount_vat,
        pbib.amount_inc_vat
      from cand_items ci
      join public.pay_batch_item_breakdowns pbib
        on pbib.pay_batch_item_id = ci.pay_batch_item_id
      left join lateral (
        select component_entry.component_json
        from jsonb_array_elements(
          case
            when jsonb_typeof(pbib.meta_json->'resolution_payload_json'->'case_components') = 'array'
              then pbib.meta_json->'resolution_payload_json'->'case_components'
            else '[]'::jsonb
          end
        ) with ordinality as component_entry(component_json, component_ordinal)
        where component_entry.component_json is not null
          and jsonb_typeof(component_entry.component_json) = 'object'
          and (
            NULLIF(BTRIM(COALESCE(component_entry.component_json->>'label', '')), '') IS NOT NULL
            OR NULLIF(BTRIM(COALESCE(component_entry.component_json->>'bucket_code', component_entry.component_json #>> '{source_basis_json,bucket_code}', '')), '') IS NOT NULL
            OR COALESCE(component_entry.component_json->>'target_units', component_entry.component_json->>'source_units', component_entry.component_json #>> '{source_basis_json,source_units}', component_entry.component_json #>> '{source_basis_json,units}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            OR COALESCE(component_entry.component_json->>'target_rate', component_entry.component_json->>'source_rate', component_entry.component_json #>> '{source_basis_json,source_rate}', component_entry.component_json #>> '{source_basis_json,rate}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          )
        order by component_entry.component_ordinal
        limit 1
      ) as component_probe
        on upper(coalesce(pbib.line_kind,'')) = 'TS_BUCKET'
       and NULLIF(BTRIM(COALESCE(pbib.bucket_code, '')), '') IS NULL
       and pbib.units IS NULL
       and pbib.rate IS NULL
       and (
         NULLIF(BTRIM(COALESCE(pbib.unit_name, '')), '') IS NULL
         OR UPPER(BTRIM(COALESCE(pbib.unit_name, ''))) IN ('SEGMENT_DELTA','TIMESHEET PAY','TIMESHEET_PAY','TIMESHEET_PAYMENT','TS_BUCKET')
       )
      where ci.timesheet_id is not null
    ),
    ts_unit_rows as (
      select
        br.candidate_id,
        br.timesheet_id,
        array_remove(array_agg(distinct br.pay_batch_item_id::text), NULL::text) as pay_batch_item_ids,
        array_remove(array_agg(distinct br.pay_batch_item_breakdown_id::text), NULL::text) as pay_batch_item_breakdown_ids,
        br.line_kind,
        br.bucket_code,
        br.unit_name,
        br.rate,
        round(sum(coalesce(br.units,0)),2) as quantity,
        round(sum(coalesce(br.amount_ex_vat,0)),2) as total_ex_vat,
        round(sum(coalesce(br.amount_vat,0)),2) as total_vat,
        round(sum(coalesce(br.amount_inc_vat,0)),2) as total_inc_vat
      from breakdown_raw br
      group by br.candidate_id, br.timesheet_id, br.line_kind, br.bucket_code, br.unit_name, br.rate
      having
        round(sum(coalesce(br.units,0)),2) <> 0
        or round(sum(coalesce(br.amount_ex_vat,0)),2) <> 0
        or round(sum(coalesce(br.amount_inc_vat,0)),2) <> 0
    ),
    ts_sections as (
      select
        tc.candidate_id,
        tc.timesheet_id,
        tc.week_ending_date,
        tc.reference_number,
        tc.client_id,
        tc.client_name,
        tc.job_title,
        tc.band,
        tc.timesheet_render_mode,
        tc.timesheet_type,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat
            )
            order by
              case upper(coalesce(r.bucket_code,''))
                when 'DAY' then 1
                when 'NIGHT' then 2
                when 'SAT' then 3
                when 'SUN' then 4
                when 'BH' then 5
                else 99
              end,
              coalesce(r.unit_name,'') asc,
              coalesce(r.rate,0) asc
          )
          filter (where upper(coalesce(r.line_kind,'')) = 'TS_BUCKET'),
          '[]'::jsonb
        ) as unit_rows,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat
            )
            order by coalesce(r.unit_name,'') asc, coalesce(r.rate,0) asc
          )
          filter (where upper(coalesce(r.line_kind,'')) = 'ADDITIONAL_UNIT'),
          '[]'::jsonb
        ) as additional_units_rows,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat
            )
            order by coalesce(r.unit_name,'') asc
          )
          filter (where upper(coalesce(r.line_kind,'')) in ('EXPENSE','MILEAGE')),
          '[]'::jsonb
        ) as expenses_rows,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat,
              'line_kind', case
                    when upper(coalesce(r.line_kind,'')) = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when upper(coalesce(r.line_kind,'')) = 'LOAN_PAYOUT' then 'PAYMENT_ADVANCE'
                    when upper(coalesce(r.line_kind,'')) = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_ADJUSTMENT'
                    when upper(coalesce(r.line_kind,'')) = 'UNDERPAYMENT_PAYMENT' then 'UNDERPAYMENT_PAYMENT'
                    when upper(coalesce(r.line_kind,'')) = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    when upper(coalesce(r.line_kind,'')) = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    else r.line_kind
                  end
            )
            order by coalesce(r.unit_name,'') asc
          )
          filter (where upper(coalesce(r.line_kind,'')) in ('ADJUSTMENT','CONVERSION_ADJ','LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','UNDERPAYMENT_PAYMENT','MANUAL_DEBT_RECOVERY','DEBT_CREATED')),
          '[]'::jsonb
        ) as other_rows,
        round(coalesce(sum(r.total_ex_vat),0),2) as totals_ex_vat,
        round(coalesce(sum(r.total_vat),0),2) as totals_vat,
        round(coalesce(sum(r.total_inc_vat),0),2) as totals_inc_vat,
        tc.base_snapshot_json,
        tc.target_snapshot_json
      from ts_class tc
      left join ts_unit_rows r
        on r.candidate_id = tc.candidate_id
       and r.timesheet_id = tc.timesheet_id
      group by
        tc.candidate_id,
        tc.timesheet_id,
        tc.week_ending_date,
        tc.reference_number,
        tc.client_id,
        tc.client_name,
        tc.job_title,
        tc.band,
        tc.timesheet_render_mode,
        tc.timesheet_type,
        tc.base_snapshot_json,
        tc.target_snapshot_json
    ),
    ts_schedule_rows_all as (
      select
        ts.candidate_id,
        ts.timesheet_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'segment_id', nullif(btrim(coalesce(s->>'segment_id','')),''),
              'date', nullif(btrim(coalesce(s->>'date','')),''),
              'start_utc', nullif(btrim(coalesce(s->>'start_utc','')),''),
              'end_utc', nullif(btrim(coalesce(s->>'end_utc','')),''),
              'break_mins', coalesce(nullif(s->>'break_mins','')::numeric,0),
              'source_system', nullif(btrim(coalesce(s->>'source_system','')), ''),
              'external_row_key', nullif(btrim(coalesce(s->>'external_row_key','')), ''),
              'nhsp_shift_id', nullif(btrim(coalesce(s->>'nhsp_shift_id','')), ''),
              'shift_id', coalesce(
                nullif(btrim(coalesce(s->>'shift_id','')), ''),
                nullif(btrim(coalesce(s->>'nhsp_shift_id','')), '')
              ),
              'request_id', nullif(btrim(coalesce(s->>'request_id','')), ''),
              'hr_request_id', nullif(btrim(coalesce(s->>'hr_request_id','')), ''),
              'ref_num', nullif(btrim(coalesce(s->>'ref_num','')), ''),
              'breaks', coalesce(s->'breaks','[]'::jsonb)
            )
            order by
              nullif(btrim(coalesce(s->>'date','')),'') asc,
              nullif(btrim(coalesce(s->>'start_utc','')),'') asc,
              nullif(btrim(coalesce(s->>'segment_id','')),'') asc
          ),
          '[]'::jsonb
        ) as schedule_rows
      from ts_sections ts
      join lateral jsonb_array_elements(coalesce(ts.target_snapshot_json->'segments','[]'::jsonb)) s
        on ts.target_snapshot_json is not null
       and jsonb_typeof(ts.target_snapshot_json)='object'
      where ts.timesheet_render_mode = 'SEGMENT'
        and s is not null
        and jsonb_typeof(s)='object'
        and coalesce(nullif(s->>'exclude_from_pay','')::boolean,false) = false
        and (
          coalesce(nullif(s->>'hours_day','')::numeric,0)
          + coalesce(nullif(s->>'hours_night','')::numeric,0)
          + coalesce(nullif(s->>'hours_sat','')::numeric,0)
          + coalesce(nullif(s->>'hours_sun','')::numeric,0)
          + coalesce(nullif(s->>'hours_bh','')::numeric,0)
        ) > 0
      group by ts.candidate_id, ts.timesheet_id
    ),
    ts_schedule_changes_all as (
      select
        ts.candidate_id,
        ts.timesheet_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'segment_id', x.seg_id,
              'date', coalesce(x.before_seg->>'date', x.after_seg->>'date'),
              'before', jsonb_build_object(
                'start_utc', x.before_seg->>'start_utc',
                'end_utc', x.before_seg->>'end_utc',
                'break_mins', coalesce(nullif(x.before_seg->>'break_mins','')::numeric,0),
                'breaks', coalesce(x.before_seg->'breaks','[]'::jsonb),
                'exclude_from_pay', coalesce(nullif(x.before_seg->>'exclude_from_pay','')::boolean,false)
              ),
              'after', jsonb_build_object(
                'start_utc', x.after_seg->>'start_utc',
                'end_utc', x.after_seg->>'end_utc',
                'break_mins', coalesce(nullif(x.after_seg->>'break_mins','')::numeric,0),
                'breaks', coalesce(x.after_seg->'breaks','[]'::jsonb),
                'exclude_from_pay', coalesce(nullif(x.after_seg->>'exclude_from_pay','')::boolean,false)
              )
            )
            order by
              coalesce(x.before_seg->>'date', x.after_seg->>'date') asc,
              coalesce(x.before_seg->>'start_utc', x.after_seg->>'start_utc') asc,
              x.seg_id asc
          ),
          '[]'::jsonb
        ) as schedule_changes
      from (
        select
          ts0.candidate_id,
          ts0.timesheet_id,
          nullif(btrim(coalesce(ids.s->>'segment_id','')),'') as seg_id,
          bseg.seg as before_seg,
          aseg.seg as after_seg
        from ts_sections ts0
        join lateral (
          select s
          from (
            select s0 as s from jsonb_array_elements(coalesce(ts0.base_snapshot_json->'segments','[]'::jsonb)) s0
            union all
            select s1 as s from jsonb_array_elements(coalesce(ts0.target_snapshot_json->'segments','[]'::jsonb)) s1
          ) u
          where u.s is not null and jsonb_typeof(u.s)='object'
        ) ids
          on ts0.timesheet_render_mode = 'SEGMENT'
         and ts0.timesheet_type = 'Adjustment'
        left join lateral (
          select s as seg
          from jsonb_array_elements(coalesce(ts0.base_snapshot_json->'segments','[]'::jsonb)) s
          where s is not null and jsonb_typeof(s)='object'
            and nullif(btrim(coalesce(s->>'segment_id','')),'') = nullif(btrim(coalesce(ids.s->>'segment_id','')),'')
          limit 1
        ) bseg on true
        left join lateral (
          select s as seg
          from jsonb_array_elements(coalesce(ts0.target_snapshot_json->'segments','[]'::jsonb)) s
          where s is not null and jsonb_typeof(s)='object'
            and nullif(btrim(coalesce(s->>'segment_id','')),'') = nullif(btrim(coalesce(ids.s->>'segment_id','')),'')
          limit 1
        ) aseg on true
      ) x
      join ts_sections ts
        on ts.candidate_id = x.candidate_id
       and ts.timesheet_id = x.timesheet_id
      where x.seg_id is not null
        and (
          coalesce(x.before_seg->>'start_utc','') <> coalesce(x.after_seg->>'start_utc','')
          or coalesce(x.before_seg->>'end_utc','') <> coalesce(x.after_seg->>'end_utc','')
          or coalesce(nullif(x.before_seg->>'break_mins','')::numeric,0) <> coalesce(nullif(x.after_seg->>'break_mins','')::numeric,0)
          or coalesce(x.before_seg->'breaks','[]'::jsonb) <> coalesce(x.after_seg->'breaks','[]'::jsonb)
          or coalesce(nullif(x.before_seg->>'exclude_from_pay','')::boolean,false) <> coalesce(nullif(x.after_seg->>'exclude_from_pay','')::boolean,false)
        )
      group by ts.candidate_id, ts.timesheet_id
    ),
    cand_timesheets as (
      select
        ts.candidate_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', ts.candidate_id::text,
              'timesheet_id', ts.timesheet_id::text,
              'stable_timesheet_key', concat_ws('|', ts.candidate_id::text, ts.timesheet_id::text, coalesce(ts.week_ending_date::text,''), coalesce(ts.client_id::text,'')),
              'week_ending_date', case when ts.week_ending_date is null then null else ts.week_ending_date::text end,
              'reference_number', ts.reference_number,
              'client_id', case when ts.client_id is null then null else ts.client_id::text end,
              'client_name', ts.client_name,
              'job_title', ts.job_title,
              'band', ts.band,
              'timesheet_render_mode', ts.timesheet_render_mode,
              'timesheet_type', ts.timesheet_type,
              'frozen_gross_ex_vat', ts.totals_ex_vat,
              'frozen_vat', ts.totals_vat,
              'frozen_gross_inc_vat', ts.totals_inc_vat,
              'unit_rows', ts.unit_rows,
              'additional_units_rows', ts.additional_units_rows,
              'expenses_rows', ts.expenses_rows,
              'other_rows', ts.other_rows,
              'totals', jsonb_build_object(
                'total_ex_vat', ts.totals_ex_vat,
                'gross_ex_vat', ts.totals_ex_vat,
                'vat', ts.totals_vat,
                'gross_vat', ts.totals_vat,
                'total_inc_vat', ts.totals_inc_vat,
                'gross_inc_vat', ts.totals_inc_vat
              ),
              'schedule_rows', case
                when coalesce(ca.eff_detailed,false) = true and ts.timesheet_render_mode = 'SEGMENT'
                  then coalesce(sr.schedule_rows,'[]'::jsonb)
                else '[]'::jsonb
              end,
              'schedule_changes', case
                when coalesce(ca.eff_detailed,false) = true and ts.timesheet_render_mode = 'SEGMENT' and ts.timesheet_type = 'Adjustment'
                  then coalesce(sc.schedule_changes,'[]'::jsonb)
                else '[]'::jsonb
              end
            )
            order by ts.week_ending_date desc nulls last, ts.client_name nulls last, ts.reference_number nulls last, ts.timesheet_id
          ),
          '[]'::jsonb
        ) as timesheets_json
      from ts_sections ts
      join cand_allowed ca
        on ca.candidate_id = ts.candidate_id
      left join ts_schedule_rows_all sr
        on sr.candidate_id = ts.candidate_id
       and sr.timesheet_id = ts.timesheet_id
      left join ts_schedule_changes_all sc
        on sc.candidate_id = ts.candidate_id
       and sc.timesheet_id = ts.timesheet_id
      group by ts.candidate_id
    ),
    cand_job as (
      select
        ca.candidate_id,
        ca.tms_ref,
        ca.display_name,
        ca.email,
        ca.eff_detailed,
        bool_or(coalesce(pt.is_simulated,false)) as test_mode,
        round(coalesce(sum(pt.amount),0),2) as total_amount,
        coalesce(ct.timesheets_json,'[]'::jsonb) as timesheets_json,
        coalesce(jsonb_agg(
          jsonb_build_object(
            'transfer_id', pt.transfer_id::text,
            'completed_at_utc', case when pt.completed_at_utc is null then null else pt.completed_at_utc::text end,
            'transfer', jsonb_build_object(
              'pay_channel', pt.pay_channel,
              'amount', pt.amount,
              'currency', pt.currency,
              'status', pt.status,
              'payment_reference', pt.payment_reference,
              'rail_tx_id', pt.rail_tx_id,
              'rail_state', pt.rail_state,
              'rail_meta_json', pt.rail_meta_json,
              'failed_reason', pt.failed_reason,
              'is_simulated', coalesce(pt.is_simulated,false)
            )
          )
          order by pt.transfer_id
        ), '[]'::jsonb) as transfers_json
      from cand_allowed ca
      join paye_transfers pt
        on pt.candidate_id = ca.candidate_id
      left join cand_timesheets ct
        on ct.candidate_id = ca.candidate_id
      group by ca.candidate_id, ca.tms_ref, ca.display_name, ca.email, ca.eff_detailed, ct.timesheets_json
    )
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'job_kind', 'PAYE_REMITTANCE',
          'pay_batch_id', v_batch.id::text,
          'scope', 'PAYE',
          'pay_date', case when coalesce(v_batch.authoritative_payment_date, v_batch.pay_date) is null then null else coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)::text end,
          'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
          'authoritative_payment_date_source', v_batch.authoritative_payment_date_source,
          'bulk_reference', v_batch.bulk_reference,
          'test_mode', coalesce(cj.test_mode,false),
          'detailed_breakdown', coalesce(cj.eff_detailed,false),
          'recipient', jsonb_build_object(
            'entity_kind', 'CANDIDATE',
            'candidate_id', cj.candidate_id::text,
            'stable_candidate_key', cj.candidate_id::text,
            'tms_ref', cj.tms_ref,
            'candidate_tms_ref', cj.tms_ref,
            'works_number', cj.tms_ref,
            'display_name', cj.display_name,
            'candidate_display_name', cj.display_name,
            'email', cj.email
          ),
          'summary', jsonb_build_object(
            'total_amount', cj.total_amount,
            'currency', 'GBP'
          ),
          'timesheets', coalesce(cj.timesheets_json,'[]'::jsonb),
          'transfers', coalesce(cj.transfers_json,'[]'::jsonb),
          'net_input', coalesce((
            select jsonb_build_object(
              'source', pni.source,
              'net_amount', pni.net_amount,
              'imported_at_utc', case when pni.imported_at_utc is null then null else pni.imported_at_utc::text end,
              'file_name', pni.file_name
            )
            from public.pay_batch_candidates pbc
            join public.pay_batch_paye_net_inputs pni
              on pni.pay_batch_candidate_id = pbc.id
            where pbc.pay_batch_id = p_pay_batch_id
              and pbc.candidate_id = cj.candidate_id
            order by pni.imported_at_utc desc
            limit 1
          ), null),
          'pay_totals', coalesce((
            select jsonb_build_object(
              'gross_preview', round(coalesce(pbc_tot.gross_preview,0),2),
              'overpayment_recovery_taken', round(coalesce(pbc_tot.overpayment_recovery_taken,0),2),
              'payment_advance_repayment_taken', round(coalesce(pbc_tot.loan_repayment_taken,0),2),
              'final_paid', round(coalesce(pbc_tot.net_bank_amount,0),2),
              'deductions_summary', jsonb_build_object(
                'gross_positive', round(coalesce(pbc_tot.gross_preview,0),2),
                'overpayment_recovery', round(coalesce(pbc_tot.overpayment_recovery_taken,0),2),
                'payment_advance_repayment', round(coalesce(pbc_tot.loan_repayment_taken,0),2),
                'total_deductions', round(coalesce(pbc_tot.overpayment_recovery_taken,0) + coalesce(pbc_tot.loan_repayment_taken,0),2),
                'final_payable', round(coalesce(pbc_tot.net_bank_amount,0),2),
                'has_deductions', (round(coalesce(pbc_tot.overpayment_recovery_taken,0) + coalesce(pbc_tot.loan_repayment_taken,0),2) > 0)
              )
            )
            from public.pay_batch_candidates pbc_tot
            where pbc_tot.pay_batch_id = p_pay_batch_id
              and pbc_tot.candidate_id = cj.candidate_id
            limit 1
          ), '{}'::jsonb),
          'frozen_totals', coalesce((
            select jsonb_build_object(
              'item_count', count(distinct pbi_ft.id)::integer,
              'gross_ex_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then 0 when coalesce(pbi_ft.amount_inc_vat,0) < 0 or coalesce(pbi_ft.amount_ex_vat,0) < 0 then 0 else coalesce(pbi_ft.amount_ex_vat,0) end),0),2),
              'vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then 0 when coalesce(pbi_ft.amount_inc_vat,0) < 0 or coalesce(pbi_ft.amount_ex_vat,0) < 0 then 0 else coalesce(pbi_ft.amount_vat,0) end),0),2),
              'gross_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then 0 when coalesce(pbi_ft.amount_inc_vat,0) < 0 or coalesce(pbi_ft.amount_ex_vat,0) < 0 then 0 else coalesce(pbi_ft.amount_vat,0) end),0),2),
              'gross_inc_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then 0 when coalesce(pbi_ft.amount_inc_vat,0) < 0 or coalesce(pbi_ft.amount_ex_vat,0) < 0 then 0 else coalesce(pbi_ft.amount_inc_vat,0) end),0),2),
              'deductions_ex_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then abs(coalesce(pbi_ft.amount_ex_vat,0)) when coalesce(pbi_ft.amount_ex_vat,0) < 0 then abs(coalesce(pbi_ft.amount_ex_vat,0)) else 0 end),0),2),
              'deductions_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then abs(coalesce(pbi_ft.amount_vat,0)) when coalesce(pbi_ft.amount_vat,0) < 0 then abs(coalesce(pbi_ft.amount_vat,0)) else 0 end),0),2),
              'deductions_inc_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then abs(coalesce(pbi_ft.amount_inc_vat,0)) when coalesce(pbi_ft.amount_inc_vat,0) < 0 then abs(coalesce(pbi_ft.amount_inc_vat,0)) else 0 end),0),2),
              'net_ex_vat', round(coalesce(sum(coalesce(pbi_ft.amount_ex_vat,0)),0),2),
              'net_vat', round(coalesce(sum(coalesce(pbi_ft.amount_vat,0)),0),2),
              'net_inc_vat', round(coalesce(sum(coalesce(pbi_ft.amount_inc_vat,0)),0),2),
              'final_payable', round(coalesce(sum(coalesce(pbi_ft.amount_inc_vat,0)),0),2)
            )
            from public.pay_batch_candidates pbc_ft
            join public.pay_batch_items pbi_ft
              on pbi_ft.pay_batch_candidate_id = pbc_ft.id
            where pbc_ft.pay_batch_id = p_pay_batch_id
              and pbc_ft.candidate_id = cj.candidate_id
              and pbi_ft.item_type <> 'DEBT_CREATED'
              and coalesce(pbi_ft.is_voided,false) = false
          ), '{}'::jsonb),
          'paye_net_advisory', coalesce((
            select jsonb_build_object(
              'original_net_input', (
                select pni2.net_amount
                from public.pay_batch_paye_net_inputs pni2
                where pni2.pay_batch_candidate_id = pbc_adv.id
                order by pni2.imported_at_utc desc
                limit 1
              ),
              'payment_advance_repayment_taken', round(coalesce(pbc_adv.loan_repayment_taken,0),2),
              'overpayment_recovery_taken', round(coalesce(pbc_adv.overpayment_recovery_taken,0),2),
              'final_net_paid', round(coalesce(pbc_adv.net_bank_amount,0),2)
            )
            from public.pay_batch_candidates pbc_adv
            where pbc_adv.pay_batch_id = p_pay_batch_id
              and pbc_adv.candidate_id = cj.candidate_id
            limit 1
          ), null),
          'non_timesheet_lines', coalesce((
            select coalesce(
              jsonb_agg(
                jsonb_build_object(
                  'pay_batch_item_id', pbi_nt.id::text,
                  'pay_batch_item_breakdown_id', pbib_nt.id::text,
                  'pay_batch_candidate_id', pbc_nt.id::text,
                  'candidate_id', pbc_nt.candidate_id::text,
                  'stable_line_key', concat_ws('|', pbc_nt.candidate_id::text, pbi_nt.id::text, pbib_nt.id::text, coalesce(pbi_nt.item_type,''), coalesce(pbi_nt.source_ref,''), coalesce(pbi_nt.finance_case_id::text,''), coalesce(pbib_nt.line_kind,''), coalesce(pbib_nt.bucket_code,''), coalesce(pbib_nt.unit_name,''), coalesce(pbib_nt.rate::text,''), coalesce(pbib_nt.amount_ex_vat::text,''), coalesce(pbib_nt.amount_vat::text,''), coalesce(pbib_nt.amount_inc_vat::text,'')),
                  'item_type', case
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 'PAYMENT_ADVANCE'
                    when pbi_nt.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_ADJUSTMENT'
                    when pbi_nt.item_type = 'UNDERPAYMENT_PAYMENT' then 'UNDERPAYMENT_PAYMENT'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    else pbi_nt.item_type
                  end,
                  'internal_item_type', pbi_nt.item_type,
                  'description', pbi_nt.description,
                  'line_kind', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 'PAYMENT_ADVANCE'
                    when pbi_nt.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_ADJUSTMENT'
                    when pbi_nt.item_type = 'UNDERPAYMENT_PAYMENT' then 'UNDERPAYMENT_PAYMENT'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    else pbib_nt.line_kind
                  end,
                  'line_label', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment Recovery'
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'Payment Advance Repayment'
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 'Payment Advance'
                    when pbi_nt.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual Credit Adjustment'
                    when pbi_nt.item_type = 'UNDERPAYMENT_PAYMENT' then 'Underpayment Payment'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'Manual Debt Recovery'
                    when nullif(btrim(coalesce(pa_fc.adjustment_comment,'')), '') is not null then pa_fc.adjustment_comment
                    when nullif(btrim(coalesce(pbib_nt.unit_name,'')), '') is not null then pbib_nt.unit_name
                    when nullif(btrim(coalesce(pbi_nt.description,'')), '') is not null then pbi_nt.description
                    else pbib_nt.line_kind
                  end,
                  'bucket_code', pbib_nt.bucket_code,
                  'unit', pbib_nt.unit_name,
                  'quantity', pbib_nt.units,
                  'rate', pbib_nt.rate,
                  'total_ex_vat', pbib_nt.amount_ex_vat,
                  'total_vat', pbib_nt.amount_vat,
                  'total_inc_vat', pbib_nt.amount_inc_vat,
                  'signed_amount_ex_vat', pbib_nt.amount_ex_vat,
                  'signed_amount_vat', pbib_nt.amount_vat,
                  'signed_amount_inc_vat', pbib_nt.amount_inc_vat,
                  'frozen_amount_ex_vat', pbib_nt.amount_ex_vat,
                  'frozen_amount_vat', pbib_nt.amount_vat,
                  'frozen_amount_inc_vat', pbib_nt.amount_inc_vat,
                  'is_deduction', (pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY')),
                  'deduction_kind', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    else null
                  end,
                  'deduction_amount_ex_vat', case
                    when pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then round(abs(coalesce(pbib_nt.amount_ex_vat,0)),2)
                    else null
                  end,
                  'deduction_amount_inc_vat', case
                    when pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then round(abs(coalesce(pbib_nt.amount_inc_vat,0)),2)
                    else null
                  end,
                  'source_ref', pbi_nt.source_ref,
                  'pay_channel', pbi_nt.pay_channel,
                  'routing_kind', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'routing_kind','')), ''),
                  'destination_label', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'destination_label','')), ''),
                  'payout_destination', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'destination_label','')), ''),
                  'masked_bank_account', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'masked_bank_account','')), ''),
                  'beneficiary_name', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'beneficiary_name','')), ''),
                  'bank_details_hash', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'bank_details_hash','')), ''),
                  'appears_on_umbrella_remittance', lower(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'appears_on_umbrella_remittance','false'))) in ('true','1','yes','y','on'),
                  'generates_candidate_payment_advice', lower(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'generates_candidate_payment_advice','false'))) in ('true','1','yes','y','on'),
                  'finance_case_id', case when coalesce(pbi_nt.finance_case_id, pa_fc.id) is null then null else coalesce(pbi_nt.finance_case_id, pa_fc.id)::text end,
                  'finance_case_type', case when pa_fc.case_type is null then null else pa_fc.case_type::text end,
                  'adjustment_comment', pa_fc.adjustment_comment,
                  'lifecycle_state', case when pa_fc.status is null then null else pa_fc.status::text end,
                  'payout_status', case when pa_fc.payout_status is null then null else pa_fc.payout_status::text end,
                  'remaining_amount', round(coalesce(pa_fc.outstanding_amount,0),2),
                  'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
                  'repayment_week_start', case when pbi_nt.repayment_week_start is null then null else pbi_nt.repayment_week_start::text end,
                  'overpayment_context', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY'
                     and pa_fc.id is not null
                     and upper(coalesce(pa_fc.case_type::text,'')) = 'OVERPAYMENT'
                     and upper(coalesce(pa_fc.status::text,'')) = 'ACTIVE'
                    then jsonb_build_object(
                      'source_timesheet_id', case when pa_fc.linked_timesheet_id is null then null else pa_fc.linked_timesheet_id::text end,
                      'shift_date', case when pa_fc.linked_shift_date is null then null else pa_fc.linked_shift_date::text end,
                      'original_paid_amount', round(coalesce(pa_fc.source_original_paid_amount, pa_fc.original_amount, 0),2),
                      'corrected_paid_amount', round(coalesce(pa_fc.source_corrected_paid_amount, greatest(coalesce(pa_fc.original_amount,0) - coalesce(pa_fc.outstanding_amount,0),0), 0),2),
                      'recovery_this_payment', round(abs(coalesce(pbib_nt.amount_ex_vat,0)),2),
                      'remaining_balance', round(coalesce(pa_fc.outstanding_amount,0),2)
                    )
                    else null
                  end
                )
                order by
                  case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 1
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 2
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 3
                    when pbi_nt.item_type = 'UNDERPAYMENT_PAYMENT' then 4
                    else 9
                  end,
                  coalesce(pbib_nt.line_kind,''),
                  coalesce(pbib_nt.unit_name,''),
                  coalesce(pbib_nt.rate,0)
              ),
              '[]'::jsonb
            )
            from public.pay_batch_candidates pbc_nt
            join public.pay_batch_items pbi_nt
              on pbi_nt.pay_batch_candidate_id = pbc_nt.id
            join public.pay_batch_item_breakdowns pbib_nt
              on pbib_nt.pay_batch_item_id = pbi_nt.id
            left join public.pay_advances pa_fc
              on (
                (pbi_nt.finance_case_id is not null and pa_fc.id = pbi_nt.finance_case_id)
                or (
                  pbi_nt.finance_case_id is null
                  and pbi_nt.source_ref is not null
                  and pbi_nt.source_ref = ('advance:' || pa_fc.id::text)
                )
              )
            where pbc_nt.pay_batch_id = p_pay_batch_id
              and pbc_nt.candidate_id = cj.candidate_id
              and upper(coalesce(pbi_nt.pay_channel,'')) = 'PAYE'
              and pbi_nt.is_voided = false
              and pbi_nt.timesheet_id is null
              and pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','UNDERPAYMENT_PAYMENT','MANUAL_DEBT_RECOVERY')
          ), '[]'::jsonb)
        )
        order by cj.display_name nulls last, cj.tms_ref nulls last, cj.candidate_id
      ),
      '[]'::jsonb
    )
    into v_jobs_paye
    from cand_job cj;
  end if;

  -- ============================================================
  -- Candidate umbrella-copy jobs (recipient=candidate; umbrella items only)
  -- LOCKED RULE:
  --  - generated only if effective receive_when_umbrella_paid is true:
  --    overrides? candidate.remittance_receive_when_umbrella_paid : settings_defaults.remittance_receive_when_umbrella_paid
  --  - detailed_breakdown resolved from candidate overrides vs settings_defaults
  -- ============================================================
  if v_scope in ('ALL','UMBRELLA') then
    with umb_transfers as (
      select
        pbt.id as transfer_id,
        pbt.pay_batch_id,
        pbt.candidate_id,
        pbt.umbrella_id,
        pbt.pay_channel,
        pbt.amount,
        pbt.currency,
        pbt.status,
        pbt.payment_reference,
        pbt.completed_at_utc,
        pbt.rail_tx_id,
        pbt.rail_state,
        pbt.rail_meta_json,
        pbt.failed_reason,
        (
          upper(coalesce(pbt.rail_state,'')) = 'PAYROLL_TESTING'
          or (
            pbt.rail_meta_json is not null
            and (pbt.rail_meta_json ? 'simulated')
            and lower(btrim(coalesce(pbt.rail_meta_json->>'simulated',''))) in ('true','1','yes','y','on')
          )
        ) as is_simulated
      from public.pay_bank_transfers pbt
      where pbt.pay_batch_id = p_pay_batch_id
        and upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA'
        and pbt.umbrella_id is not null
        and pbt.candidate_id is not null
    ),
    cand_cfg as (
      select
        c.id as candidate_id,
        c.tms_ref,
        c.display_name,
        c.email,
        coalesce(c.remittance_overrides_enabled,false) as overrides_enabled,
        coalesce(c.remittances_detailed_breakdown,false) as detailed_enabled,
        coalesce(c.remittance_receive_when_umbrella_paid,false) as umb_copy_enabled
      from public.candidates c
      where c.id in (select distinct ut.candidate_id from umb_transfers ut)
    ),
    cand_effective as (
      select
        cc.*,
        (case when cc.overrides_enabled then cc.umb_copy_enabled else v_sd_remittance_receive_when_umbrella_paid end) as eff_copy,
        (case when cc.overrides_enabled then cc.detailed_enabled else v_sd_remittances_detailed_breakdown end) as eff_detailed
      from cand_cfg cc
    ),
    cand_allowed as (
      select *
      from cand_effective ce
      where ce.eff_copy = true
    ),
    ts_scope_artifact as (
      select distinct on (tss.candidate_id, tss.timesheet_id)
        tss.candidate_id,
        tss.timesheet_id,
        case
          when tss.target_snapshot_json is not null
           and jsonb_typeof(tss.target_snapshot_json) = 'object'
           and jsonb_typeof(tss.target_snapshot_json->'segments') = 'array'
           and exists (
             select 1
             from jsonb_array_elements(tss.target_snapshot_json->'segments') s
             where s is not null
               and jsonb_typeof(s) = 'object'
               and nullif(btrim(coalesce(s->>'date','')),'') is not null
           )
          then 'DAILY'
          else 'WEEKLY'
        end as sheet_scope_norm
      from public.pay_batch_timesheet_snapshots tss
      where tss.pay_batch_id = p_pay_batch_id
        and upper(coalesce(tss.pay_channel,'')) = 'UMBRELLA'
      order by tss.candidate_id, tss.timesheet_id, tss.created_at_utc desc, tss.id desc
    ),
    cand_items as (
      select
        ca.candidate_id,
        pbi.id as pay_batch_item_id,
        pbi.item_type,
        pbi.description,
        pbi.timesheet_id,
        pbi.segment_key,
        pbi.source_ref,
        pbi.amount_ex_vat,
        pbi.amount_vat,
        pbi.amount_inc_vat,
        pbi.pay_channel
      from cand_allowed ca
      join public.pay_batch_candidates pbc
        on pbc.pay_batch_id = p_pay_batch_id
       and pbc.candidate_id = ca.candidate_id
      join public.pay_batch_items pbi
        on pbi.pay_batch_candidate_id = pbc.id
      left join ts_scope_artifact tsa
        on tsa.candidate_id = pbc.candidate_id
       and tsa.timesheet_id = pbi.timesheet_id
      where upper(coalesce(pbi.pay_channel,'')) = 'UMBRELLA'
        and pbi.item_type <> 'DEBT_CREATED'
        and coalesce(pbi.is_voided,false) = false
        and (
          case
            when upper(coalesce(tsa.sheet_scope_norm, v_missing_scope)) = 'DAILY' then
              (case
                 when lower(coalesce(v_remittance_includes_json->'daily'->'include_item_types'->>pbi.item_type, v_unknown_item_type_default_text)) in ('true','1','yes','y','on')
                 then true else false end)
            else
              (case
                 when lower(coalesce(v_remittance_includes_json->'weekly'->'include_item_types'->>pbi.item_type, v_unknown_item_type_default_text)) in ('true','1','yes','y','on')
                 then true else false end)
          end
        )
    ),
    ts_meta as (
      select
        ci.candidate_id,
        ci.timesheet_id,
        ts.week_ending_date,
        ts.reference_number,
        ts.contract_id,
        nullif(btrim(coalesce(ts.job_title_norm,'')),'') as job_title_norm,
        nullif(btrim(coalesce(ts.band,'')),'') as band_norm
      from cand_items ci
      left join public.timesheets ts
        on ts.timesheet_id = ci.timesheet_id
       and ts.is_current = true
      where ci.timesheet_id is not null
      group by ci.candidate_id, ci.timesheet_id, ts.week_ending_date, ts.reference_number, ts.contract_id, ts.job_title_norm, ts.band
    ),
    ts_enrich as (
      select
        tm.candidate_id,
        tm.timesheet_id,
        tm.week_ending_date,
        tm.reference_number,
        vs.client_id as client_id,
        vs.client_name as client_name,
        upper(coalesce(tsa.sheet_scope_norm, v_missing_scope)) as sheet_scope,
        nullif(btrim(coalesce(ct.role, tm.job_title_norm)),'') as job_title,
        nullif(btrim(coalesce(ct.band, tm.band_norm)),'') as band
      from ts_meta tm
      left join public.contracts ct
        on ct.id = tm.contract_id
      left join public.v_timesheets_summary vs
        on vs.timesheet_id = tm.timesheet_id
      left join ts_scope_artifact tsa
        on tsa.candidate_id = tm.candidate_id
       and tsa.timesheet_id = tm.timesheet_id
    ),
    ts_snap as (
      select distinct on (
        tss.candidate_id,
        tss.timesheet_id,
        upper(coalesce(tss.pay_channel,''))
      )
        tss.timesheet_id,
        tss.candidate_id,
        tss.base_snapshot_json,
        tss.target_snapshot_json
      from public.pay_batch_timesheet_snapshots tss
      where tss.pay_batch_id = p_pay_batch_id
        and upper(coalesce(tss.pay_channel,'')) = 'UMBRELLA'
      order by
        tss.candidate_id,
        tss.timesheet_id,
        upper(coalesce(tss.pay_channel,'')),
        tss.created_at_utc desc,
        tss.id desc
    ),
    ts_class as (
      select
        te.candidate_id,
        te.timesheet_id,
        te.week_ending_date,
        te.reference_number,
        te.client_id,
        te.client_name,
        te.sheet_scope,
        te.job_title,
        te.band,
        tsn.base_snapshot_json,
        tsn.target_snapshot_json,
        case
          when tsn.target_snapshot_json is not null
           and jsonb_typeof(tsn.target_snapshot_json) = 'object'
           and jsonb_typeof(tsn.target_snapshot_json->'segments') = 'array'
           and exists (
             select 1
             from jsonb_array_elements(tsn.target_snapshot_json->'segments') s
             where s is not null
               and jsonb_typeof(s)='object'
               and nullif(btrim(coalesce(s->>'date','')),'') is not null
           )
          then 'SEGMENT'
          else 'AGGREGATE'
        end as timesheet_render_mode,
        case
          when tsn.base_snapshot_json is null then 'Standard'
          when tsn.base_snapshot_json = '{}'::jsonb then 'Standard'
          when (
            exists (
              select 1
              from jsonb_array_elements(coalesce(tsn.base_snapshot_json->'segments','[]'::jsonb)) s
              where s is not null and jsonb_typeof(s)='object'
                and round(coalesce(nullif(s->>'pay_amount','')::numeric,0),2) <> 0
            )
            or round(coalesce(nullif(tsn.base_snapshot_json->>'additional_pay_ex_vat','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,expenses_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,travel_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,other_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0),2) <> 0
            or (
              jsonb_typeof(tsn.base_snapshot_json->'adjustments')='array'
              and jsonb_array_length(tsn.base_snapshot_json->'adjustments') > 0
            )
          )
          then 'Adjustment'
          else 'Standard'
        end as timesheet_type
      from ts_enrich te
      left join ts_snap tsn
        on tsn.timesheet_id = te.timesheet_id
       and tsn.candidate_id = te.candidate_id
    ),
    breakdown_raw as (
      select
        ci.candidate_id,
        ci.timesheet_id,
        ci.pay_batch_item_id,
        pbib.id as pay_batch_item_breakdown_id,
        pbib.line_kind,
        COALESCE(
          NULLIF(UPPER(BTRIM(COALESCE(pbib.bucket_code, ''))), ''),
          CASE WHEN component_probe.component_json IS NULL THEN NULL ELSE NULLIF(UPPER(BTRIM(COALESCE(component_probe.component_json->>'bucket_code', component_probe.component_json #>> '{source_basis_json,bucket_code}', component_probe.component_json->>'label', ''))), '') END
        ) as bucket_code,
        CASE
          WHEN component_probe.component_json IS NOT NULL
           AND (
             NULLIF(BTRIM(COALESCE(pbib.unit_name, '')), '') IS NULL
             OR UPPER(BTRIM(COALESCE(pbib.unit_name, ''))) IN ('SEGMENT_DELTA','TIMESHEET PAY','TIMESHEET_PAY','TIMESHEET_PAYMENT','TS_BUCKET')
           ) THEN COALESCE(
             NULLIF(BTRIM(component_probe.component_json->>'label'), ''),
             NULLIF(UPPER(BTRIM(component_probe.component_json->>'bucket_code')), ''),
             NULLIF(UPPER(BTRIM(component_probe.component_json #>> '{source_basis_json,bucket_code}')), ''),
             pbib.unit_name
           )
          ELSE pbib.unit_name
        END as unit_name,
        CASE
          WHEN component_probe.component_json IS NOT NULL
           AND pbib.units IS NULL
           AND COALESCE(component_probe.component_json->>'target_units', component_probe.component_json->>'source_units', component_probe.component_json #>> '{source_basis_json,source_units}', component_probe.component_json #>> '{source_basis_json,units}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN COALESCE(component_probe.component_json->>'target_units', component_probe.component_json->>'source_units', component_probe.component_json #>> '{source_basis_json,source_units}', component_probe.component_json #>> '{source_basis_json,units}')::numeric
          ELSE pbib.units
        END as units,
        CASE
          WHEN component_probe.component_json IS NOT NULL
           AND pbib.rate IS NULL
           AND COALESCE(component_probe.component_json->>'target_rate', component_probe.component_json->>'source_rate', component_probe.component_json #>> '{source_basis_json,source_rate}', component_probe.component_json #>> '{source_basis_json,rate}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN COALESCE(component_probe.component_json->>'target_rate', component_probe.component_json->>'source_rate', component_probe.component_json #>> '{source_basis_json,source_rate}', component_probe.component_json #>> '{source_basis_json,rate}')::numeric
          ELSE pbib.rate
        END as rate,
        pbib.amount_ex_vat,
        pbib.amount_vat,
        pbib.amount_inc_vat
      from cand_items ci
      join public.pay_batch_item_breakdowns pbib
        on pbib.pay_batch_item_id = ci.pay_batch_item_id
      left join lateral (
        select component_entry.component_json
        from jsonb_array_elements(
          case
            when jsonb_typeof(pbib.meta_json->'resolution_payload_json'->'case_components') = 'array'
              then pbib.meta_json->'resolution_payload_json'->'case_components'
            else '[]'::jsonb
          end
        ) with ordinality as component_entry(component_json, component_ordinal)
        where component_entry.component_json is not null
          and jsonb_typeof(component_entry.component_json) = 'object'
          and (
            NULLIF(BTRIM(COALESCE(component_entry.component_json->>'label', '')), '') IS NOT NULL
            OR NULLIF(BTRIM(COALESCE(component_entry.component_json->>'bucket_code', component_entry.component_json #>> '{source_basis_json,bucket_code}', '')), '') IS NOT NULL
            OR COALESCE(component_entry.component_json->>'target_units', component_entry.component_json->>'source_units', component_entry.component_json #>> '{source_basis_json,source_units}', component_entry.component_json #>> '{source_basis_json,units}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            OR COALESCE(component_entry.component_json->>'target_rate', component_entry.component_json->>'source_rate', component_entry.component_json #>> '{source_basis_json,source_rate}', component_entry.component_json #>> '{source_basis_json,rate}', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          )
        order by component_entry.component_ordinal
        limit 1
      ) as component_probe
        on upper(coalesce(pbib.line_kind,'')) = 'TS_BUCKET'
       and NULLIF(BTRIM(COALESCE(pbib.bucket_code, '')), '') IS NULL
       and pbib.units IS NULL
       and pbib.rate IS NULL
       and (
         NULLIF(BTRIM(COALESCE(pbib.unit_name, '')), '') IS NULL
         OR UPPER(BTRIM(COALESCE(pbib.unit_name, ''))) IN ('SEGMENT_DELTA','TIMESHEET PAY','TIMESHEET_PAY','TIMESHEET_PAYMENT','TS_BUCKET')
       )
      where ci.timesheet_id is not null
    ),
    ts_unit_rows as (
      select
        br.candidate_id,
        br.timesheet_id,
        array_remove(array_agg(distinct br.pay_batch_item_id::text), NULL::text) as pay_batch_item_ids,
        array_remove(array_agg(distinct br.pay_batch_item_breakdown_id::text), NULL::text) as pay_batch_item_breakdown_ids,
        br.line_kind,
        br.bucket_code,
        br.unit_name,
        br.rate,
        round(sum(coalesce(br.units,0)),2) as quantity,
        round(sum(coalesce(br.amount_ex_vat,0)),2) as total_ex_vat,
        round(sum(coalesce(br.amount_vat,0)),2) as total_vat,
        round(sum(coalesce(br.amount_inc_vat,0)),2) as total_inc_vat
      from breakdown_raw br
      group by br.candidate_id, br.timesheet_id, br.line_kind, br.bucket_code, br.unit_name, br.rate
      having
        round(sum(coalesce(br.units,0)),2) <> 0
        or round(sum(coalesce(br.amount_ex_vat,0)),2) <> 0
        or round(sum(coalesce(br.amount_inc_vat,0)),2) <> 0
    ),
    ts_sections as (
      select
        tc.candidate_id,
        tc.timesheet_id,
        tc.week_ending_date,
        tc.reference_number,
        tc.client_id,
        tc.client_name,
        tc.job_title,
        tc.band,
        tc.timesheet_render_mode,
        tc.timesheet_type,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat
            )
            order by
              case upper(coalesce(r.bucket_code,''))
                when 'DAY' then 1
                when 'NIGHT' then 2
                when 'SAT' then 3
                when 'SUN' then 4
                when 'BH' then 5
                else 99
              end,
              coalesce(r.unit_name,'') asc,
              coalesce(r.rate,0) asc
          )
          filter (where upper(coalesce(r.line_kind,'')) = 'TS_BUCKET'),
          '[]'::jsonb
        ) as unit_rows,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat
            )
            order by coalesce(r.unit_name,'') asc, coalesce(r.rate,0) asc
          )
          filter (where upper(coalesce(r.line_kind,'')) = 'ADDITIONAL_UNIT'),
          '[]'::jsonb
        ) as additional_units_rows,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat
            )
            order by coalesce(r.unit_name,'') asc
          )
          filter (where upper(coalesce(r.line_kind,'')) in ('EXPENSE','MILEAGE')),
          '[]'::jsonb
        ) as expenses_rows,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat,
              'line_kind', case
                    when upper(coalesce(r.line_kind,'')) = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when upper(coalesce(r.line_kind,'')) = 'LOAN_PAYOUT' then 'PAYMENT_ADVANCE'
                    when upper(coalesce(r.line_kind,'')) = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_ADJUSTMENT'
                    when upper(coalesce(r.line_kind,'')) = 'UNDERPAYMENT_PAYMENT' then 'UNDERPAYMENT_PAYMENT'
                    when upper(coalesce(r.line_kind,'')) = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    when upper(coalesce(r.line_kind,'')) = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    else r.line_kind
                  end
            )
            order by coalesce(r.unit_name,'') asc
          )
          filter (where upper(coalesce(r.line_kind,'')) in ('ADJUSTMENT','CONVERSION_ADJ','LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','UNDERPAYMENT_PAYMENT','MANUAL_DEBT_RECOVERY','DEBT_CREATED')),
          '[]'::jsonb
        ) as other_rows,
        round(coalesce(sum(r.total_ex_vat),0),2) as totals_ex_vat,
        round(coalesce(sum(r.total_vat),0),2) as totals_vat,
        round(coalesce(sum(r.total_inc_vat),0),2) as totals_inc_vat,
        tc.base_snapshot_json,
        tc.target_snapshot_json
      from ts_class tc
      left join ts_unit_rows r
        on r.candidate_id = tc.candidate_id
       and r.timesheet_id = tc.timesheet_id
      group by
        tc.candidate_id,
        tc.timesheet_id,
        tc.week_ending_date,
        tc.reference_number,
        tc.client_id,
        tc.client_name,
        tc.job_title,
        tc.band,
        tc.timesheet_render_mode,
        tc.timesheet_type,
        tc.base_snapshot_json,
        tc.target_snapshot_json
    ),
    ts_schedule_rows_all as (
      select
        ts.candidate_id,
        ts.timesheet_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'segment_id', nullif(btrim(coalesce(s->>'segment_id','')),''),
              'date', nullif(btrim(coalesce(s->>'date','')),''),
              'start_utc', nullif(btrim(coalesce(s->>'start_utc','')),''),
              'end_utc', nullif(btrim(coalesce(s->>'end_utc','')),''),
              'break_mins', coalesce(nullif(s->>'break_mins','')::numeric,0),
              'source_system', nullif(btrim(coalesce(s->>'source_system','')), ''),
              'external_row_key', nullif(btrim(coalesce(s->>'external_row_key','')), ''),
              'nhsp_shift_id', nullif(btrim(coalesce(s->>'nhsp_shift_id','')), ''),
              'shift_id', coalesce(
                nullif(btrim(coalesce(s->>'shift_id','')), ''),
                nullif(btrim(coalesce(s->>'nhsp_shift_id','')), '')
              ),
              'request_id', nullif(btrim(coalesce(s->>'request_id','')), ''),
              'hr_request_id', nullif(btrim(coalesce(s->>'hr_request_id','')), ''),
              'ref_num', nullif(btrim(coalesce(s->>'ref_num','')), ''),
              'breaks', coalesce(s->'breaks','[]'::jsonb)
            )
            order by
              nullif(btrim(coalesce(s->>'date','')),'') asc,
              nullif(btrim(coalesce(s->>'start_utc','')),'') asc,
              nullif(btrim(coalesce(s->>'segment_id','')),'') asc
          ),
          '[]'::jsonb
        ) as schedule_rows
      from ts_sections ts
      join lateral jsonb_array_elements(coalesce(ts.target_snapshot_json->'segments','[]'::jsonb)) s
        on ts.target_snapshot_json is not null
       and jsonb_typeof(ts.target_snapshot_json)='object'
      where ts.timesheet_render_mode = 'SEGMENT'
        and s is not null
        and jsonb_typeof(s)='object'
        and coalesce(nullif(s->>'exclude_from_pay','')::boolean,false) = false
        and (
          coalesce(nullif(s->>'hours_day','')::numeric,0)
          + coalesce(nullif(s->>'hours_night','')::numeric,0)
          + coalesce(nullif(s->>'hours_sat','')::numeric,0)
          + coalesce(nullif(s->>'hours_sun','')::numeric,0)
          + coalesce(nullif(s->>'hours_bh','')::numeric,0)
        ) > 0
      group by ts.candidate_id, ts.timesheet_id
    ),
    ts_schedule_changes_all as (
      select
        ts.candidate_id,
        ts.timesheet_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'segment_id', x.seg_id,
              'date', coalesce(x.before_seg->>'date', x.after_seg->>'date'),
              'before', jsonb_build_object(
                'start_utc', x.before_seg->>'start_utc',
                'end_utc', x.before_seg->>'end_utc',
                'break_mins', coalesce(nullif(x.before_seg->>'break_mins','')::numeric,0),
                'breaks', coalesce(x.before_seg->'breaks','[]'::jsonb),
                'exclude_from_pay', coalesce(nullif(x.before_seg->>'exclude_from_pay','')::boolean,false)
              ),
              'after', jsonb_build_object(
                'start_utc', x.after_seg->>'start_utc',
                'end_utc', x.after_seg->>'end_utc',
                'break_mins', coalesce(nullif(x.after_seg->>'break_mins','')::numeric,0),
                'breaks', coalesce(x.after_seg->'breaks','[]'::jsonb),
                'exclude_from_pay', coalesce(nullif(x.after_seg->>'exclude_from_pay','')::boolean,false)
              )
            )
            order by
              coalesce(x.before_seg->>'date', x.after_seg->>'date') asc,
              coalesce(x.before_seg->>'start_utc', x.after_seg->>'start_utc') asc,
              x.seg_id asc
          ),
          '[]'::jsonb
        ) as schedule_changes
      from (
        select
          ts0.candidate_id,
          ts0.timesheet_id,
          nullif(btrim(coalesce(ids.s->>'segment_id','')),'') as seg_id,
          bseg.seg as before_seg,
          aseg.seg as after_seg
        from ts_sections ts0
        join lateral (
          select s
          from (
            select s0 as s from jsonb_array_elements(coalesce(ts0.base_snapshot_json->'segments','[]'::jsonb)) s0
            union all
            select s1 as s from jsonb_array_elements(coalesce(ts0.target_snapshot_json->'segments','[]'::jsonb)) s1
          ) u
          where u.s is not null and jsonb_typeof(u.s)='object'
        ) ids
          on ts0.timesheet_render_mode = 'SEGMENT'
         and ts0.timesheet_type = 'Adjustment'
        left join lateral (
          select s as seg
          from jsonb_array_elements(coalesce(ts0.base_snapshot_json->'segments','[]'::jsonb)) s
          where s is not null and jsonb_typeof(s)='object'
            and nullif(btrim(coalesce(s->>'segment_id','')),'') = nullif(btrim(coalesce(ids.s->>'segment_id','')),'')
          limit 1
        ) bseg on true
        left join lateral (
          select s as seg
          from jsonb_array_elements(coalesce(ts0.target_snapshot_json->'segments','[]'::jsonb)) s
          where s is not null and jsonb_typeof(s)='object'
            and nullif(btrim(coalesce(s->>'segment_id','')),'') = nullif(btrim(coalesce(ids.s->>'segment_id','')),'')
          limit 1
        ) aseg on true
      ) x
      join ts_sections ts
        on ts.candidate_id = x.candidate_id
       and ts.timesheet_id = x.timesheet_id
      where x.seg_id is not null
        and (
          coalesce(x.before_seg->>'start_utc','') <> coalesce(x.after_seg->>'start_utc','')
          or coalesce(x.before_seg->>'end_utc','') <> coalesce(x.after_seg->>'end_utc','')
          or coalesce(nullif(x.before_seg->>'break_mins','')::numeric,0) <> coalesce(nullif(x.after_seg->>'break_mins','')::numeric,0)
          or coalesce(x.before_seg->'breaks','[]'::jsonb) <> coalesce(x.after_seg->'breaks','[]'::jsonb)
          or coalesce(nullif(x.before_seg->>'exclude_from_pay','')::boolean,false) <> coalesce(nullif(x.after_seg->>'exclude_from_pay','')::boolean,false)
        )
      group by ts.candidate_id, ts.timesheet_id
    ),
    cand_timesheets as (
      select
        ts.candidate_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', ts.candidate_id::text,
              'timesheet_id', ts.timesheet_id::text,
              'stable_timesheet_key', concat_ws('|', ts.candidate_id::text, ts.timesheet_id::text, coalesce(ts.week_ending_date::text,''), coalesce(ts.client_id::text,'')),
              'week_ending_date', case when ts.week_ending_date is null then null else ts.week_ending_date::text end,
              'reference_number', ts.reference_number,
              'client_id', case when ts.client_id is null then null else ts.client_id::text end,
              'client_name', ts.client_name,
              'job_title', ts.job_title,
              'band', ts.band,
              'timesheet_render_mode', ts.timesheet_render_mode,
              'timesheet_type', ts.timesheet_type,
              'frozen_gross_ex_vat', ts.totals_ex_vat,
              'frozen_vat', ts.totals_vat,
              'frozen_gross_inc_vat', ts.totals_inc_vat,
              'unit_rows', ts.unit_rows,
              'additional_units_rows', ts.additional_units_rows,
              'expenses_rows', ts.expenses_rows,
              'other_rows', ts.other_rows,
              'totals', jsonb_build_object(
                'total_ex_vat', ts.totals_ex_vat,
                'gross_ex_vat', ts.totals_ex_vat,
                'vat', ts.totals_vat,
                'gross_vat', ts.totals_vat,
                'total_inc_vat', ts.totals_inc_vat,
                'gross_inc_vat', ts.totals_inc_vat
              ),
              'schedule_rows', case
                when coalesce(ca.eff_detailed,false) = true and ts.timesheet_render_mode = 'SEGMENT'
                  then coalesce(sr.schedule_rows,'[]'::jsonb)
                else '[]'::jsonb
              end,
              'schedule_changes', case
                when coalesce(ca.eff_detailed,false) = true and ts.timesheet_render_mode = 'SEGMENT' and ts.timesheet_type = 'Adjustment'
                  then coalesce(sc.schedule_changes,'[]'::jsonb)
                else '[]'::jsonb
              end
            )
            order by ts.week_ending_date desc nulls last, ts.client_name nulls last, ts.reference_number nulls last, ts.timesheet_id
          ),
          '[]'::jsonb
        ) as timesheets_json
      from ts_sections ts
      join cand_allowed ca
        on ca.candidate_id = ts.candidate_id
      left join ts_schedule_rows_all sr
        on sr.candidate_id = ts.candidate_id
       and sr.timesheet_id = ts.timesheet_id
      left join ts_schedule_changes_all sc
        on sc.candidate_id = ts.candidate_id
       and sc.timesheet_id = ts.timesheet_id
      group by ts.candidate_id
    ),
    cand_job as (
      select
        ca.candidate_id,
        ca.tms_ref,
        ca.display_name,
        ca.email,
        ca.eff_detailed,
        bool_or(coalesce(ut.is_simulated,false)) as test_mode,
        round(coalesce(sum(ut.amount),0),2) as total_amount,
        coalesce(ct.timesheets_json,'[]'::jsonb) as timesheets_json,
        coalesce(jsonb_agg(
          jsonb_build_object(
            'transfer_id', ut.transfer_id::text,
            'completed_at_utc', case when ut.completed_at_utc is null then null else ut.completed_at_utc::text end,
            'transfer', jsonb_build_object(
              'pay_channel', ut.pay_channel,
              'amount', ut.amount,
              'currency', ut.currency,
              'status', ut.status,
              'payment_reference', ut.payment_reference,
              'rail_tx_id', ut.rail_tx_id,
              'rail_state', ut.rail_state,
              'rail_meta_json', ut.rail_meta_json,
              'failed_reason', ut.failed_reason,
              'is_simulated', coalesce(ut.is_simulated,false)
            )
          )
          order by ut.transfer_id
        ), '[]'::jsonb) as transfers_json
      from cand_allowed ca
      join umb_transfers ut
        on ut.candidate_id = ca.candidate_id
      left join cand_timesheets ct
        on ct.candidate_id = ca.candidate_id
      group by ca.candidate_id, ca.tms_ref, ca.display_name, ca.email, ca.eff_detailed, ct.timesheets_json
    )
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'job_kind', 'CANDIDATE_UMBRELLA_COPY_REMITTANCE',
          'pay_batch_id', v_batch.id::text,
          'scope', 'UMBRELLA',
          'pay_date', case when coalesce(v_batch.authoritative_payment_date, v_batch.pay_date) is null then null else coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)::text end,
          'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
          'authoritative_payment_date_source', v_batch.authoritative_payment_date_source,
          'bulk_reference', v_batch.bulk_reference,
          'test_mode', coalesce(cj.test_mode,false),
          'detailed_breakdown', coalesce(cj.eff_detailed,false),
          'recipient', jsonb_build_object(
            'entity_kind', 'CANDIDATE',
            'candidate_id', cj.candidate_id::text,
            'stable_candidate_key', cj.candidate_id::text,
            'tms_ref', cj.tms_ref,
            'candidate_tms_ref', cj.tms_ref,
            'works_number', cj.tms_ref,
            'display_name', cj.display_name,
            'candidate_display_name', cj.display_name,
            'email', cj.email
          ),
          'summary', jsonb_build_object(
            'total_amount', cj.total_amount,
            'currency', 'GBP'
          ),
          'timesheets', coalesce(cj.timesheets_json,'[]'::jsonb),
          'transfers', coalesce(cj.transfers_json,'[]'::jsonb),
          'pay_totals', coalesce((
            select jsonb_build_object(
              'gross_preview', round(coalesce(pbc_tot.gross_preview,0),2),
              'overpayment_recovery_taken', round(coalesce(pbc_tot.overpayment_recovery_taken,0),2),
              'payment_advance_repayment_taken', round(coalesce(pbc_tot.loan_repayment_taken,0),2),
              'final_paid', round(coalesce(pbc_tot.net_bank_amount,0),2),
              'deductions_summary', jsonb_build_object(
                'gross_positive', round(coalesce(pbc_tot.gross_preview,0),2),
                'overpayment_recovery', round(coalesce(pbc_tot.overpayment_recovery_taken,0),2),
                'payment_advance_repayment', round(coalesce(pbc_tot.loan_repayment_taken,0),2),
                'total_deductions', round(coalesce(pbc_tot.overpayment_recovery_taken,0) + coalesce(pbc_tot.loan_repayment_taken,0),2),
                'final_payable', round(coalesce(pbc_tot.net_bank_amount,0),2),
                'has_deductions', (round(coalesce(pbc_tot.overpayment_recovery_taken,0) + coalesce(pbc_tot.loan_repayment_taken,0),2) > 0)
              )
            )
            from public.pay_batch_candidates pbc_tot
            where pbc_tot.pay_batch_id = p_pay_batch_id
              and pbc_tot.candidate_id = cj.candidate_id
            limit 1
          ), '{}'::jsonb),
          'frozen_totals', coalesce((
            select jsonb_build_object(
              'item_count', count(distinct pbi_ft.id)::integer,
              'gross_ex_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then 0 when coalesce(pbi_ft.amount_inc_vat,0) < 0 or coalesce(pbi_ft.amount_ex_vat,0) < 0 then 0 else coalesce(pbi_ft.amount_ex_vat,0) end),0),2),
              'vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then 0 when coalesce(pbi_ft.amount_inc_vat,0) < 0 or coalesce(pbi_ft.amount_ex_vat,0) < 0 then 0 else coalesce(pbi_ft.amount_vat,0) end),0),2),
              'gross_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then 0 when coalesce(pbi_ft.amount_inc_vat,0) < 0 or coalesce(pbi_ft.amount_ex_vat,0) < 0 then 0 else coalesce(pbi_ft.amount_vat,0) end),0),2),
              'gross_inc_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then 0 when coalesce(pbi_ft.amount_inc_vat,0) < 0 or coalesce(pbi_ft.amount_ex_vat,0) < 0 then 0 else coalesce(pbi_ft.amount_inc_vat,0) end),0),2),
              'deductions_ex_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then abs(coalesce(pbi_ft.amount_ex_vat,0)) when coalesce(pbi_ft.amount_ex_vat,0) < 0 then abs(coalesce(pbi_ft.amount_ex_vat,0)) else 0 end),0),2),
              'deductions_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then abs(coalesce(pbi_ft.amount_vat,0)) when coalesce(pbi_ft.amount_vat,0) < 0 then abs(coalesce(pbi_ft.amount_vat,0)) else 0 end),0),2),
              'deductions_inc_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then abs(coalesce(pbi_ft.amount_inc_vat,0)) when coalesce(pbi_ft.amount_inc_vat,0) < 0 then abs(coalesce(pbi_ft.amount_inc_vat,0)) else 0 end),0),2),
              'net_ex_vat', round(coalesce(sum(coalesce(pbi_ft.amount_ex_vat,0)),0),2),
              'net_vat', round(coalesce(sum(coalesce(pbi_ft.amount_vat,0)),0),2),
              'net_inc_vat', round(coalesce(sum(coalesce(pbi_ft.amount_inc_vat,0)),0),2),
              'final_payable', round(coalesce(sum(coalesce(pbi_ft.amount_inc_vat,0)),0),2)
            )
            from public.pay_batch_candidates pbc_ft
            join public.pay_batch_items pbi_ft
              on pbi_ft.pay_batch_candidate_id = pbc_ft.id
            where pbc_ft.pay_batch_id = p_pay_batch_id
              and pbc_ft.candidate_id = cj.candidate_id
              and pbi_ft.item_type <> 'DEBT_CREATED'
              and coalesce(pbi_ft.is_voided,false) = false
          ), '{}'::jsonb),
          'non_timesheet_lines', coalesce((
            select coalesce(
              jsonb_agg(
                jsonb_build_object(
                  'pay_batch_item_id', pbi_nt.id::text,
                  'pay_batch_item_breakdown_id', pbib_nt.id::text,
                  'pay_batch_candidate_id', pbc_nt.id::text,
                  'candidate_id', pbc_nt.candidate_id::text,
                  'stable_line_key', concat_ws('|', pbc_nt.candidate_id::text, pbi_nt.id::text, pbib_nt.id::text, coalesce(pbi_nt.item_type,''), coalesce(pbi_nt.source_ref,''), coalesce(pbi_nt.finance_case_id::text,''), coalesce(pbib_nt.line_kind,''), coalesce(pbib_nt.bucket_code,''), coalesce(pbib_nt.unit_name,''), coalesce(pbib_nt.rate::text,''), coalesce(pbib_nt.amount_ex_vat::text,''), coalesce(pbib_nt.amount_vat::text,''), coalesce(pbib_nt.amount_inc_vat::text,'')),
                  'item_type', case
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 'PAYMENT_ADVANCE'
                    when pbi_nt.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_ADJUSTMENT'
                    when pbi_nt.item_type = 'UNDERPAYMENT_PAYMENT' then 'UNDERPAYMENT_PAYMENT'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    else pbi_nt.item_type
                  end,
                  'internal_item_type', pbi_nt.item_type,
                  'description', pbi_nt.description,
                  'line_kind', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 'PAYMENT_ADVANCE'
                    when pbi_nt.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_ADJUSTMENT'
                    when pbi_nt.item_type = 'UNDERPAYMENT_PAYMENT' then 'UNDERPAYMENT_PAYMENT'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    else pbib_nt.line_kind
                  end,
                  'line_label', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment Recovery'
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'Payment Advance Repayment'
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 'Payment Advance'
                    when pbi_nt.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual Credit Adjustment'
                    when pbi_nt.item_type = 'UNDERPAYMENT_PAYMENT' then 'Underpayment Payment'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'Manual Debt Recovery'
                    when nullif(btrim(coalesce(pa_fc.adjustment_comment,'')), '') is not null then pa_fc.adjustment_comment
                    when nullif(btrim(coalesce(pbib_nt.unit_name,'')), '') is not null then pbib_nt.unit_name
                    when nullif(btrim(coalesce(pbi_nt.description,'')), '') is not null then pbi_nt.description
                    else pbib_nt.line_kind
                  end,
                  'bucket_code', pbib_nt.bucket_code,
                  'unit', pbib_nt.unit_name,
                  'quantity', pbib_nt.units,
                  'rate', pbib_nt.rate,
                  'total_ex_vat', pbib_nt.amount_ex_vat,
                  'total_vat', pbib_nt.amount_vat,
                  'total_inc_vat', pbib_nt.amount_inc_vat,
                  'signed_amount_ex_vat', pbib_nt.amount_ex_vat,
                  'signed_amount_vat', pbib_nt.amount_vat,
                  'signed_amount_inc_vat', pbib_nt.amount_inc_vat,
                  'frozen_amount_ex_vat', pbib_nt.amount_ex_vat,
                  'frozen_amount_vat', pbib_nt.amount_vat,
                  'frozen_amount_inc_vat', pbib_nt.amount_inc_vat,
                  'is_deduction', (pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY')),
                  'deduction_kind', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    else null
                  end,
                  'deduction_amount_ex_vat', case
                    when pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then round(abs(coalesce(pbib_nt.amount_ex_vat,0)),2)
                    else null
                  end,
                  'deduction_amount_inc_vat', case
                    when pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then round(abs(coalesce(pbib_nt.amount_inc_vat,0)),2)
                    else null
                  end,
                  'source_ref', pbi_nt.source_ref,
                  'pay_channel', pbi_nt.pay_channel,
                  'routing_kind', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'routing_kind','')), ''),
                  'destination_label', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'destination_label','')), ''),
                  'payout_destination', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'destination_label','')), ''),
                  'masked_bank_account', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'masked_bank_account','')), ''),
                  'beneficiary_name', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'beneficiary_name','')), ''),
                  'bank_details_hash', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'bank_details_hash','')), ''),
                  'appears_on_umbrella_remittance', lower(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'appears_on_umbrella_remittance','false'))) in ('true','1','yes','y','on'),
                  'generates_candidate_payment_advice', lower(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'generates_candidate_payment_advice','false'))) in ('true','1','yes','y','on'),
                  'finance_case_id', case when coalesce(pbi_nt.finance_case_id, pa_fc.id) is null then null else coalesce(pbi_nt.finance_case_id, pa_fc.id)::text end,
                  'finance_case_type', case when pa_fc.case_type is null then null else pa_fc.case_type::text end,
                  'adjustment_comment', pa_fc.adjustment_comment,
                  'lifecycle_state', case when pa_fc.status is null then null else pa_fc.status::text end,
                  'payout_status', case when pa_fc.payout_status is null then null else pa_fc.payout_status::text end,
                  'remaining_amount', round(coalesce(pa_fc.outstanding_amount,0),2),
                  'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
                  'repayment_week_start', case when pbi_nt.repayment_week_start is null then null else pbi_nt.repayment_week_start::text end,
                  'overpayment_context', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY'
                     and pa_fc.id is not null
                     and upper(coalesce(pa_fc.case_type::text,'')) = 'OVERPAYMENT'
                     and upper(coalesce(pa_fc.status::text,'')) = 'ACTIVE'
                    then jsonb_build_object(
                      'source_timesheet_id', case when pa_fc.linked_timesheet_id is null then null else pa_fc.linked_timesheet_id::text end,
                      'shift_date', case when pa_fc.linked_shift_date is null then null else pa_fc.linked_shift_date::text end,
                      'original_paid_amount', round(coalesce(pa_fc.source_original_paid_amount, pa_fc.original_amount, 0),2),
                      'corrected_paid_amount', round(coalesce(pa_fc.source_corrected_paid_amount, greatest(coalesce(pa_fc.original_amount,0) - coalesce(pa_fc.outstanding_amount,0),0), 0),2),
                      'recovery_this_payment', round(abs(coalesce(pbib_nt.amount_ex_vat,0)),2),
                      'remaining_balance', round(coalesce(pa_fc.outstanding_amount,0),2)
                    )
                    else null
                  end
                )
                order by
                  case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 1
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 2
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 3
                    when pbi_nt.item_type = 'UNDERPAYMENT_PAYMENT' then 4
                    else 9
                  end,
                  coalesce(pbib_nt.line_kind,''),
                  coalesce(pbib_nt.unit_name,''),
                  coalesce(pbib_nt.rate,0)
              ),
              '[]'::jsonb
            )
            from public.pay_batch_candidates pbc_nt
            join public.pay_batch_items pbi_nt
              on pbi_nt.pay_batch_candidate_id = pbc_nt.id
            join public.pay_batch_item_breakdowns pbib_nt
              on pbib_nt.pay_batch_item_id = pbi_nt.id
            left join public.pay_advances pa_fc
              on (
                (pbi_nt.finance_case_id is not null and pa_fc.id = pbi_nt.finance_case_id)
                or (
                  pbi_nt.finance_case_id is null
                  and pbi_nt.source_ref is not null
                  and pbi_nt.source_ref = ('advance:' || pa_fc.id::text)
                )
              )
            where pbc_nt.pay_batch_id = p_pay_batch_id
              and pbc_nt.candidate_id = cj.candidate_id
              and upper(coalesce(pbi_nt.pay_channel,'')) = 'UMBRELLA'
              and pbi_nt.is_voided = false
              and pbi_nt.timesheet_id is null
              and pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','UNDERPAYMENT_PAYMENT','MANUAL_DEBT_RECOVERY')
          ), '[]'::jsonb)
        )
        order by cj.display_name nulls last, cj.tms_ref nulls last, cj.candidate_id
      ),
      '[]'::jsonb
    )
    into v_jobs_cand_umb_copy
    from cand_job cj;
  end if;

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', v_batch.id::text,
    'scope', v_scope,
    'pay_date', case when coalesce(v_batch.authoritative_payment_date, v_batch.pay_date) is null then null else coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)::text end,
          'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
          'authoritative_payment_date_source', v_batch.authoritative_payment_date_source,
    'bulk_reference', v_batch.bulk_reference,
    'execution_commit_state', v_batch.execution_commit_state,
    'execution_commit_ref', v_batch.execution_commit_ref,
    'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end,
    'remittance_header_message', v_remittance_header_message,
    'remittance_footer_message', v_remittance_footer_message,
    'jobs', (coalesce(v_jobs_umb,'[]'::jsonb) || coalesce(v_jobs_paye,'[]'::jsonb) || coalesce(v_jobs_cand_umb_copy,'[]'::jsonb))
  );
end;
$function$;

-- pay_remittance_mark_sent(uuid,text,jsonb,uuid)
CREATE OR REPLACE FUNCTION public.pay_remittance_mark_sent(p_pay_batch_id uuid, p_scope text, p_results_json jsonb, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_scope text := upper(btrim(coalesce(p_scope, 'ALL')));
  v_batch_exists boolean := false;
  v_now timestamptz := now();
  v_results jsonb := case
    when p_results_json is null then '{}'::jsonb
    when jsonb_typeof(p_results_json) = 'object' then p_results_json
    else jsonb_build_object('raw', p_results_json)
  end;
  v_input_message_kind text := upper(btrim(coalesce(v_results->>'message_kind', 'REMITTANCE')));
  v_message_kind text := null;
  v_audit_action text := null;
  v_audit_reason text := null;
  v_audit_id uuid;

  v_has_remittance_result boolean := false;
  v_has_payout_notice_result boolean := false;
  v_remittance_result jsonb := '{}'::jsonb;
  v_payout_notice_result jsonb := '{}'::jsonb;
  v_communication_mode text := 'NONE';

  v_item jsonb;
  v_item_payee_kind text;
  v_item_candidate_id_text text;
  v_item_umbrella_id_text text;
  v_item_candidate_id uuid;
  v_item_umbrella_id uuid;
  v_item_trigger_status text;
  v_item_error_text text;
  v_item_has_job boolean;

  v_success_count integer := 0;
  v_failure_count integer := 0;
  v_no_result_count integer := 0;

  v_remittance_success_count integer := 0;
  v_remittance_failure_count integer := 0;
  v_remittance_no_result_count integer := 0;
  v_remittance_unmatched_queued_count integer := 0;
  v_remittance_unmatched_skipped_count integer := 0;

  v_payout_notice_success_count integer := 0;
  v_payout_notice_failure_count integer := 0;
  v_payout_notice_no_result_count integer := 0;
  v_payout_notice_unmatched_queued_count integer := 0;
  v_payout_notice_unmatched_skipped_count integer := 0;
begin
  if p_pay_batch_id is null then
    raise exception 'pay_remittance_mark_sent: pay_batch_id is required';
  end if;

  if p_actor_user_id is null then
    raise exception 'pay_remittance_mark_sent: actor_user_id is required';
  end if;

  if v_scope not in ('ALL','PAYE','UMBRELLA') then
    raise exception 'pay_remittance_mark_sent: invalid scope "%". Expected ALL|PAYE|UMBRELLA.', v_scope;
  end if;

  select exists (
    select 1
    from public.pay_batches pb
    where pb.id = p_pay_batch_id
  )
  into v_batch_exists;

  if v_batch_exists is false then
    raise exception 'pay_remittance_mark_sent: pay batch % not found.', p_pay_batch_id;
  end if;

  if jsonb_typeof(v_results->'remittance_result') = 'object' then
    v_has_remittance_result := true;
    v_remittance_result := coalesce(v_results->'remittance_result', '{}'::jsonb);
  end if;

  if jsonb_typeof(v_results->'payout_notice_result') = 'object' then
    v_has_payout_notice_result := true;
    v_payout_notice_result := coalesce(v_results->'payout_notice_result', '{}'::jsonb);
  end if;

  if v_has_remittance_result is false and v_has_payout_notice_result is false then
    if v_input_message_kind = 'PAYOUT_NOTICE' then
      v_has_payout_notice_result := true;
      v_payout_notice_result := v_results;
    else
      v_has_remittance_result := true;
      v_remittance_result := v_results;
    end if;
  end if;

  if v_has_remittance_result and v_has_payout_notice_result then
    v_communication_mode := 'MIXED';
    v_message_kind := 'MIXED';
    v_audit_action := 'PAY_BATCH_COMMUNICATIONS_SENT';
    v_audit_reason := 'communications_mark_sent';
  elsif v_has_payout_notice_result then
    v_communication_mode := 'PAYOUT_NOTICE';
    v_message_kind := 'PAYOUT_NOTICE';
    v_audit_action := 'PAY_PAYOUT_NOTICE_SENT';
    v_audit_reason := 'payout_notice_mark_sent';
  else
    v_communication_mode := 'REMITTANCE';
    v_message_kind := 'REMITTANCE';
    v_audit_action := 'PAY_REMITTANCE_SENT';
    v_audit_reason := 'remittance_mark_sent';
  end if;

  drop table if exists pg_temp._tmp_mark_sent_target_candidates;
  create temporary table pg_temp._tmp_mark_sent_target_candidates (
    pay_batch_candidate_id uuid primary key,
    candidate_id uuid not null,
    target_from_remittance boolean not null default false,
    target_from_payout_notice boolean not null default false
  ) on commit drop;

  if v_has_remittance_result then
    insert into pg_temp._tmp_mark_sent_target_candidates(
      pay_batch_candidate_id,
      candidate_id,
      target_from_remittance,
      target_from_payout_notice
    )
    select
      pbc.id,
      pbc.candidate_id,
      true,
      false
    from public.pay_batch_candidates pbc
    where pbc.pay_batch_id = p_pay_batch_id
      and exists (
        select 1
        from public.pay_batch_items pbi
        where pbi.pay_batch_candidate_id = pbc.id
          and pbi.item_type <> 'DEBT_CREATED'
          and coalesce(pbi.is_voided, false) = false
          and (
            v_scope = 'ALL'
            or upper(coalesce(pbi.pay_channel, '')) = v_scope
          )
          and not (
            pbi.finance_case_id is not null
            and pbi.item_type in ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
            and jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
            and upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
            and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) in ('true', '1', 'yes', 'y', 'on')
            and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'generates_candidate_payment_advice', 'false'))) in ('true', '1', 'yes', 'y', 'on')
          )
      )
    on conflict (pay_batch_candidate_id)
    do update set
      target_from_remittance = true;
  end if;

  if v_has_payout_notice_result then
    if jsonb_typeof(v_payout_notice_result->'candidate_results') = 'array' then
      insert into pg_temp._tmp_mark_sent_target_candidates(
        pay_batch_candidate_id,
        candidate_id,
        target_from_remittance,
        target_from_payout_notice
      )
      select
        pbc.id,
        pbc.candidate_id,
        false,
        true
      from public.pay_batch_candidates pbc
      where pbc.pay_batch_id = p_pay_batch_id
        and exists (
          select 1
          from jsonb_array_elements(v_payout_notice_result->'candidate_results') as cr(value)
          where nullif(btrim(coalesce(cr.value->>'candidate_id', '')), '') = pbc.candidate_id::text
        )
      on conflict (pay_batch_candidate_id)
      do update set
        target_from_payout_notice = true;
    else
      insert into pg_temp._tmp_mark_sent_target_candidates(
        pay_batch_candidate_id,
        candidate_id,
        target_from_remittance,
        target_from_payout_notice
      )
      select
        pbc.id,
        pbc.candidate_id,
        false,
        true
      from public.pay_batch_candidates pbc
      where pbc.pay_batch_id = p_pay_batch_id
        and exists (
          select 1
          from public.pay_batch_items pbi
          where pbi.pay_batch_candidate_id = pbc.id
            and coalesce(pbi.is_voided, false) = false
            and pbi.finance_case_id is not null
            and pbi.item_type in ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
            and (
              v_scope = 'ALL'
              or upper(coalesce(pbi.pay_channel, '')) = v_scope
            )
            and jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
            and upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
            and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) in ('true', '1', 'yes', 'y', 'on')
            and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'generates_candidate_payment_advice', 'false'))) in ('true', '1', 'yes', 'y', 'on')
        )
      on conflict (pay_batch_candidate_id)
      do update set
        target_from_payout_notice = true;
    end if;
  end if;

  drop table if exists pg_temp._tmp_mark_sent_events;
  create temporary table pg_temp._tmp_mark_sent_events (
    candidate_id uuid not null,
    comm_kind text not null,
    outcome text not null,
    trigger_status text null,
    error_text text null
  ) on commit drop;

  if v_has_remittance_result and jsonb_typeof(v_remittance_result->'candidate_results') = 'array' then
    for v_item in
      select cr.value
      from jsonb_array_elements(v_remittance_result->'candidate_results') as cr(value)
    loop
      v_item_candidate_id_text := nullif(btrim(coalesce(v_item->>'candidate_id', '')), '');
      v_item_candidate_id := null;
      v_item_has_job := lower(btrim(coalesce(v_item->>'has_job', 'false'))) in ('true', '1', 'yes', 'y', 'on');
      v_item_trigger_status := upper(btrim(coalesce(v_item->>'trigger_status', 'NO_QUEUEABLE_JOB')));

      if v_item_candidate_id_text is not null then
        begin
          v_item_candidate_id := v_item_candidate_id_text::uuid;
        exception when invalid_text_representation then
          v_item_candidate_id := null;
        end;
      end if;

