      v_item_candidate_id_text := nullif(
        btrim(
          coalesce(
            v_item->>'candidate_id',
            case when v_item_payee_kind = 'CANDIDATE' then v_item->>'payee_entity_id' else null end
          )
        ),
        ''
      );
      v_item_umbrella_id_text := nullif(
        btrim(
          coalesce(
            v_item->>'umbrella_id',
            case when v_item_payee_kind = 'UMBRELLA' then v_item->>'payee_entity_id' else null end
          )
        ),
        ''
      );
      v_item_candidate_id := null;
      v_item_umbrella_id := null;
      v_item_trigger_status := upper(btrim(coalesce(v_item->>'trigger_status', 'SENT_VIA_MAIL_OUTBOX')));

      if v_item_candidate_id_text is not null then
        begin
          v_item_candidate_id := v_item_candidate_id_text::uuid;
        exception when invalid_text_representation then
          v_item_candidate_id := null;
        end;
      end if;

      if v_item_umbrella_id_text is not null then
        begin
          v_item_umbrella_id := v_item_umbrella_id_text::uuid;
        exception when invalid_text_representation then
          v_item_umbrella_id := null;
        end;
      end if;

      if v_item_candidate_id is not null then
        insert into pg_temp._tmp_mark_sent_events(candidate_id, comm_kind, outcome, trigger_status, error_text)
        select
          tc.candidate_id,
          'PAYOUT_NOTICE',
          'SUCCESS',
          v_item_trigger_status,
          null
        from pg_temp._tmp_mark_sent_target_candidates tc
        where tc.candidate_id = v_item_candidate_id
          and tc.target_from_payout_notice = true;
      elsif v_item_payee_kind = 'UMBRELLA' and v_item_umbrella_id is not null then
        insert into pg_temp._tmp_mark_sent_events(candidate_id, comm_kind, outcome, trigger_status, error_text)
        select distinct
          tc.candidate_id,
          'PAYOUT_NOTICE',
          'SUCCESS',
          v_item_trigger_status,
          null
        from pg_temp._tmp_mark_sent_target_candidates tc
        join public.pay_batch_candidates pbc
          on pbc.id = tc.pay_batch_candidate_id
        join public.pay_batch_items pbi
          on pbi.pay_batch_candidate_id = pbc.id
        where pbc.pay_batch_id = p_pay_batch_id
          and tc.target_from_payout_notice = true
          and pbi.item_type <> 'DEBT_CREATED'
          and coalesce(pbi.is_voided, false) = false
          and (
            v_scope = 'ALL'
            or upper(coalesce(pbi.pay_channel, '')) = v_scope
          )
          and pbi.umbrella_id = v_item_umbrella_id
          and not (
            pbi.finance_case_id is not null
            and pbi.item_type in ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
            and jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
            and upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
            and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) in ('true', '1', 'yes', 'y', 'on')
            and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'generates_candidate_payment_advice', 'false'))) in ('true', '1', 'yes', 'y', 'on')
          );
      else
        v_payout_notice_unmatched_queued_count := v_payout_notice_unmatched_queued_count + 1;
      end if;
    end loop;
  end if;

  if v_has_payout_notice_result and (
    jsonb_typeof(v_payout_notice_result->'failed') = 'array'
    or jsonb_typeof(v_payout_notice_result->'failures') = 'array'
  ) then
    for v_item in
      select q.value
      from jsonb_array_elements(
        case when jsonb_typeof(v_payout_notice_result->'failed') = 'array' then v_payout_notice_result->'failed' else '[]'::jsonb end
      ) as q(value)
      union all
      select q.value
      from jsonb_array_elements(
        case when jsonb_typeof(v_payout_notice_result->'failures') = 'array' then v_payout_notice_result->'failures' else '[]'::jsonb end
      ) as q(value)
    loop
      v_item_payee_kind := upper(btrim(coalesce(v_item->>'payee_entity_kind', '')));
      v_item_candidate_id_text := nullif(
        btrim(
          coalesce(
            v_item->>'candidate_id',
            case when v_item_payee_kind = 'CANDIDATE' then v_item->>'payee_entity_id' else null end
          )
        ),
        ''
      );
      v_item_umbrella_id_text := nullif(
        btrim(
          coalesce(
            v_item->>'umbrella_id',
            case when v_item_payee_kind = 'UMBRELLA' then v_item->>'payee_entity_id' else null end
          )
        ),
        ''
      );
      v_item_candidate_id := null;
      v_item_umbrella_id := null;
      v_item_trigger_status := upper(btrim(coalesce(v_item->>'trigger_status', v_item->>'reason', 'MAIL_OUTBOX_SEND_FAILED')));
      v_item_error_text := left(coalesce(nullif(btrim(coalesce(v_item->>'error', '')), ''), nullif(btrim(coalesce(v_item->>'reason', '')), ''), 'MAIL_OUTBOX_SEND_FAILED'), 1000);

      if v_item_candidate_id_text is not null then
        begin
          v_item_candidate_id := v_item_candidate_id_text::uuid;
        exception when invalid_text_representation then
          v_item_candidate_id := null;
        end;
      end if;

      if v_item_umbrella_id_text is not null then
        begin
          v_item_umbrella_id := v_item_umbrella_id_text::uuid;
        exception when invalid_text_representation then
          v_item_umbrella_id := null;
        end;
      end if;

      if v_item_candidate_id is not null then
        insert into pg_temp._tmp_mark_sent_events(candidate_id, comm_kind, outcome, trigger_status, error_text)
        select
          tc.candidate_id,
          'PAYOUT_NOTICE',
          'FAILURE',
          v_item_trigger_status,
          v_item_error_text
        from pg_temp._tmp_mark_sent_target_candidates tc
        where tc.candidate_id = v_item_candidate_id
          and tc.target_from_payout_notice = true;
      elsif v_item_payee_kind = 'UMBRELLA' and v_item_umbrella_id is not null then
        insert into pg_temp._tmp_mark_sent_events(candidate_id, comm_kind, outcome, trigger_status, error_text)
        select distinct
          tc.candidate_id,
          'PAYOUT_NOTICE',
          'FAILURE',
          v_item_trigger_status,
          v_item_error_text
        from pg_temp._tmp_mark_sent_target_candidates tc
        join public.pay_batch_candidates pbc
          on pbc.id = tc.pay_batch_candidate_id
        join public.pay_batch_items pbi
          on pbi.pay_batch_candidate_id = pbc.id
        where pbc.pay_batch_id = p_pay_batch_id
          and tc.target_from_payout_notice = true
          and pbi.item_type <> 'DEBT_CREATED'
          and coalesce(pbi.is_voided, false) = false
          and (
            v_scope = 'ALL'
            or upper(coalesce(pbi.pay_channel, '')) = v_scope
          )
          and pbi.umbrella_id = v_item_umbrella_id
          and not (
            pbi.finance_case_id is not null
            and pbi.item_type in ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
            and jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
            and upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
            and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) in ('true', '1', 'yes', 'y', 'on')
            and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'generates_candidate_payment_advice', 'false'))) in ('true', '1', 'yes', 'y', 'on')
          );
      else
        v_payout_notice_unmatched_skipped_count := v_payout_notice_unmatched_skipped_count + 1;
      end if;
    end loop;
  end if;

  if v_has_payout_notice_result and jsonb_typeof(v_payout_notice_result->'skipped') = 'array' then
    for v_item in
      select s.value
      from jsonb_array_elements(v_payout_notice_result->'skipped') as s(value)
    loop
      v_item_payee_kind := upper(btrim(coalesce(v_item->>'payee_entity_kind', 'CANDIDATE')));
      v_item_candidate_id_text := nullif(
        btrim(
          coalesce(
            v_item->>'candidate_id',
            case when v_item_payee_kind = 'CANDIDATE' then v_item->>'payee_entity_id' else null end
          )
        ),
        ''
      );
      v_item_umbrella_id_text := nullif(
        btrim(
          coalesce(
            v_item->>'umbrella_id',
            case when v_item_payee_kind = 'UMBRELLA' then v_item->>'payee_entity_id' else null end
          )
        ),
        ''
      );
      v_item_candidate_id := null;
      v_item_umbrella_id := null;
      v_item_trigger_status := upper(btrim(coalesce(v_item->>'trigger_status', v_item->>'reason', 'SEND_SKIPPED')));
      v_item_error_text := left(coalesce(nullif(btrim(coalesce(v_item->>'error', '')), ''), nullif(btrim(coalesce(v_item->>'reason', '')), ''), 'SEND_SKIPPED'), 1000);

      if v_item_candidate_id_text is not null then
        begin
          v_item_candidate_id := v_item_candidate_id_text::uuid;
        exception when invalid_text_representation then
          v_item_candidate_id := null;
        end;
      end if;

      if v_item_umbrella_id_text is not null then
        begin
          v_item_umbrella_id := v_item_umbrella_id_text::uuid;
        exception when invalid_text_representation then
          v_item_umbrella_id := null;
        end;
      end if;

      if v_item_candidate_id is not null then
        insert into pg_temp._tmp_mark_sent_events(candidate_id, comm_kind, outcome, trigger_status, error_text)
        select
          tc.candidate_id,
          'PAYOUT_NOTICE',
          'FAILURE',
          v_item_trigger_status,
          v_item_error_text
        from pg_temp._tmp_mark_sent_target_candidates tc
        where tc.candidate_id = v_item_candidate_id
          and tc.target_from_payout_notice = true;
      elsif v_item_payee_kind = 'UMBRELLA' and v_item_umbrella_id is not null then
        insert into pg_temp._tmp_mark_sent_events(candidate_id, comm_kind, outcome, trigger_status, error_text)
        select distinct
          tc.candidate_id,
          'PAYOUT_NOTICE',
          'FAILURE',
          v_item_trigger_status,
          v_item_error_text
        from pg_temp._tmp_mark_sent_target_candidates tc
        join public.pay_batch_candidates pbc
          on pbc.id = tc.pay_batch_candidate_id
        join public.pay_batch_items pbi
          on pbi.pay_batch_candidate_id = pbc.id
        where pbc.pay_batch_id = p_pay_batch_id
          and tc.target_from_payout_notice = true
          and coalesce(pbi.is_voided, false) = false
          and pbi.finance_case_id is not null
          and pbi.item_type in ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
          and (
            v_scope = 'ALL'
            or upper(coalesce(pbi.pay_channel, '')) = v_scope
          )
          and pbi.umbrella_id = v_item_umbrella_id
          and jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
          and upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
          and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) in ('true', '1', 'yes', 'y', 'on')
          and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'generates_candidate_payment_advice', 'false'))) in ('true', '1', 'yes', 'y', 'on');
      else
        v_payout_notice_unmatched_skipped_count := v_payout_notice_unmatched_skipped_count + 1;
      end if;
    end loop;
  end if;

  drop table if exists pg_temp._tmp_mark_sent_agg;
  create temporary table pg_temp._tmp_mark_sent_agg (
    pay_batch_candidate_id uuid primary key,
    candidate_id uuid not null,
    target_from_remittance boolean not null,
    target_from_payout_notice boolean not null,
    has_success boolean not null,
    has_success_remittance boolean not null,
    has_success_payout_notice boolean not null,
    success_trigger_status text null,
    failure_trigger_status text null,
    failure_error text null,
    remittance_success_trigger_status text null,
    payout_notice_success_trigger_status text null,
    remittance_failure_trigger_status text null,
    payout_notice_failure_trigger_status text null,
    remittance_failure_error text null,
    payout_notice_failure_error text null
  ) on commit drop;

  insert into pg_temp._tmp_mark_sent_agg(
    pay_batch_candidate_id,
    candidate_id,
    target_from_remittance,
    target_from_payout_notice,
    has_success,
    has_success_remittance,
    has_success_payout_notice,
    success_trigger_status,
    failure_trigger_status,
    failure_error,
    remittance_success_trigger_status,
    payout_notice_success_trigger_status,
    remittance_failure_trigger_status,
    payout_notice_failure_trigger_status,
    remittance_failure_error,
    payout_notice_failure_error
  )
  select
    tc.pay_batch_candidate_id,
    tc.candidate_id,
    tc.target_from_remittance,
    tc.target_from_payout_notice,
    (
      exists (
        select 1
        from pg_temp._tmp_mark_sent_events evs
        where evs.candidate_id = tc.candidate_id
          and evs.outcome = 'SUCCESS'
      )
    ) as has_success,
    (
      exists (
        select 1
        from pg_temp._tmp_mark_sent_events evs
        where evs.candidate_id = tc.candidate_id
          and evs.comm_kind = 'REMITTANCE'
          and evs.outcome = 'SUCCESS'
      )
    ) as has_success_remittance,
    (
      exists (
        select 1
        from pg_temp._tmp_mark_sent_events evs
        where evs.candidate_id = tc.candidate_id
          and evs.comm_kind = 'PAYOUT_NOTICE'
          and evs.outcome = 'SUCCESS'
      )
    ) as has_success_payout_notice,
    case
      when (
        exists (
          select 1
          from pg_temp._tmp_mark_sent_events evs
          where evs.candidate_id = tc.candidate_id
            and evs.comm_kind = 'REMITTANCE'
            and evs.outcome = 'SUCCESS'
        )
      )
       and (
        exists (
          select 1
          from pg_temp._tmp_mark_sent_events evs
          where evs.candidate_id = tc.candidate_id
            and evs.comm_kind = 'PAYOUT_NOTICE'
            and evs.outcome = 'SUCCESS'
        )
      )
        then 'REMITTANCE_AND_PAYOUT_NOTICE_SENT'
      when (
        exists (
          select 1
          from pg_temp._tmp_mark_sent_events evs
          where evs.candidate_id = tc.candidate_id
            and evs.comm_kind = 'REMITTANCE'
            and evs.outcome = 'SUCCESS'
        )
      )
        then coalesce(
          (
            select evs2.trigger_status
            from pg_temp._tmp_mark_sent_events evs2
            where evs2.candidate_id = tc.candidate_id
              and evs2.comm_kind = 'REMITTANCE'
              and evs2.outcome = 'SUCCESS'
              and nullif(btrim(coalesce(evs2.trigger_status, '')), '') is not null
            order by evs2.trigger_status
            limit 1
          ),
          'SENT_VIA_MAIL_OUTBOX'
        )
      when (
        exists (
          select 1
          from pg_temp._tmp_mark_sent_events evs
          where evs.candidate_id = tc.candidate_id
            and evs.comm_kind = 'PAYOUT_NOTICE'
            and evs.outcome = 'SUCCESS'
        )
      )
        then coalesce(
          (
            select evs2.trigger_status
            from pg_temp._tmp_mark_sent_events evs2
            where evs2.candidate_id = tc.candidate_id
              and evs2.comm_kind = 'PAYOUT_NOTICE'
              and evs2.outcome = 'SUCCESS'
              and nullif(btrim(coalesce(evs2.trigger_status, '')), '') is not null
            order by evs2.trigger_status
            limit 1
          ),
          'SENT_VIA_MAIL_OUTBOX'
        )
      else null
    end as success_trigger_status,
    case
      when (
        exists (
          select 1
          from pg_temp._tmp_mark_sent_events evs
          where evs.candidate_id = tc.candidate_id
            and evs.outcome = 'SUCCESS'
        )
      )
        then null
      when tc.target_from_remittance and tc.target_from_payout_notice then
        case
          when coalesce(
            (
              select evf.trigger_status
              from pg_temp._tmp_mark_sent_events evf
              where evf.candidate_id = tc.candidate_id
                and evf.comm_kind = 'REMITTANCE'
                and evf.outcome = 'FAILURE'
                and nullif(btrim(coalesce(evf.trigger_status, '')), '') is not null
              order by evf.trigger_status
              limit 1
            ),
            'NO_RESULT_RECORDED'
          ) <> 'NO_RESULT_RECORDED'
           and coalesce(
            (
              select evf.trigger_status
              from pg_temp._tmp_mark_sent_events evf
              where evf.candidate_id = tc.candidate_id
                and evf.comm_kind = 'PAYOUT_NOTICE'
                and evf.outcome = 'FAILURE'
                and nullif(btrim(coalesce(evf.trigger_status, '')), '') is not null
              order by evf.trigger_status
              limit 1
            ),
            'NO_RESULT_RECORDED'
          ) <> 'NO_RESULT_RECORDED'
            then 'REMITTANCE_AND_PAYOUT_NOTICE_FAILED'
          when coalesce(
            (
              select evf.trigger_status
              from pg_temp._tmp_mark_sent_events evf
              where evf.candidate_id = tc.candidate_id
                and evf.comm_kind = 'REMITTANCE'
                and evf.outcome = 'FAILURE'
                and nullif(btrim(coalesce(evf.trigger_status, '')), '') is not null
              order by evf.trigger_status
              limit 1
            ),
            'NO_RESULT_RECORDED'
          ) <> 'NO_RESULT_RECORDED'
            then coalesce(
              (
                select evf.trigger_status
                from pg_temp._tmp_mark_sent_events evf
                where evf.candidate_id = tc.candidate_id
                  and evf.comm_kind = 'REMITTANCE'
                  and evf.outcome = 'FAILURE'
                  and nullif(btrim(coalesce(evf.trigger_status, '')), '') is not null
                order by evf.trigger_status
                limit 1
              ),
              'NO_RESULT_RECORDED'
            )
          when coalesce(
            (
              select evf.trigger_status
              from pg_temp._tmp_mark_sent_events evf
              where evf.candidate_id = tc.candidate_id
                and evf.comm_kind = 'PAYOUT_NOTICE'
                and evf.outcome = 'FAILURE'
                and nullif(btrim(coalesce(evf.trigger_status, '')), '') is not null
              order by evf.trigger_status
              limit 1
            ),
            'NO_RESULT_RECORDED'
          ) <> 'NO_RESULT_RECORDED'
            then coalesce(
              (
                select evf.trigger_status
                from pg_temp._tmp_mark_sent_events evf
                where evf.candidate_id = tc.candidate_id
                  and evf.comm_kind = 'PAYOUT_NOTICE'
                  and evf.outcome = 'FAILURE'
                  and nullif(btrim(coalesce(evf.trigger_status, '')), '') is not null
                order by evf.trigger_status
                limit 1
              ),
              'NO_RESULT_RECORDED'
            )
          else 'NO_RESULT_RECORDED'
        end
      when tc.target_from_remittance then
        coalesce(
          (
            select evf.trigger_status
            from pg_temp._tmp_mark_sent_events evf
            where evf.candidate_id = tc.candidate_id
              and evf.comm_kind = 'REMITTANCE'
              and evf.outcome = 'FAILURE'
              and nullif(btrim(coalesce(evf.trigger_status, '')), '') is not null
            order by evf.trigger_status
            limit 1
          ),
          'NO_RESULT_RECORDED'
        )
      when tc.target_from_payout_notice then
        coalesce(
          (
            select evf.trigger_status
            from pg_temp._tmp_mark_sent_events evf
            where evf.candidate_id = tc.candidate_id
              and evf.comm_kind = 'PAYOUT_NOTICE'
              and evf.outcome = 'FAILURE'
              and nullif(btrim(coalesce(evf.trigger_status, '')), '') is not null
            order by evf.trigger_status
            limit 1
          ),
          'NO_RESULT_RECORDED'
        )
      else 'NO_RESULT_RECORDED'
    end as failure_trigger_status,
    case
      when (
        exists (
          select 1
          from pg_temp._tmp_mark_sent_events evs
          where evs.candidate_id = tc.candidate_id
            and evs.outcome = 'SUCCESS'
        )
      )
        then null
      else left(
        coalesce(
          (
            select string_agg(errs.err_txt, ' | ')
            from (
              select distinct nullif(btrim(coalesce(evf2.error_text, '')), '') as err_txt
              from pg_temp._tmp_mark_sent_events evf2
              where evf2.candidate_id = tc.candidate_id
                and evf2.outcome = 'FAILURE'
                and nullif(btrim(coalesce(evf2.error_text, '')), '') is not null
              order by err_txt
            ) errs
          ),
          'NO_RESULT_RECORDED'
        ),
        1000
      )
    end as failure_error,
    (
      select evs2.trigger_status
      from pg_temp._tmp_mark_sent_events evs2
      where evs2.candidate_id = tc.candidate_id
        and evs2.comm_kind = 'REMITTANCE'
        and evs2.outcome = 'SUCCESS'
        and nullif(btrim(coalesce(evs2.trigger_status, '')), '') is not null
      order by evs2.trigger_status
      limit 1
    ) as remittance_success_trigger_status,
    (
      select evs2.trigger_status
      from pg_temp._tmp_mark_sent_events evs2
      where evs2.candidate_id = tc.candidate_id
        and evs2.comm_kind = 'PAYOUT_NOTICE'
        and evs2.outcome = 'SUCCESS'
        and nullif(btrim(coalesce(evs2.trigger_status, '')), '') is not null
      order by evs2.trigger_status
      limit 1
    ) as payout_notice_success_trigger_status,
    coalesce(
      (
        select evf.trigger_status
        from pg_temp._tmp_mark_sent_events evf
        where evf.candidate_id = tc.candidate_id
          and evf.comm_kind = 'REMITTANCE'
          and evf.outcome = 'FAILURE'
          and nullif(btrim(coalesce(evf.trigger_status, '')), '') is not null
        order by evf.trigger_status
        limit 1
      ),
      case when tc.target_from_remittance then 'NO_RESULT_RECORDED' else null end
    ) as remittance_failure_trigger_status,
    coalesce(
      (
        select evf.trigger_status
        from pg_temp._tmp_mark_sent_events evf
        where evf.candidate_id = tc.candidate_id
          and evf.comm_kind = 'PAYOUT_NOTICE'
          and evf.outcome = 'FAILURE'
          and nullif(btrim(coalesce(evf.trigger_status, '')), '') is not null
        order by evf.trigger_status
        limit 1
      ),
      case when tc.target_from_payout_notice then 'NO_RESULT_RECORDED' else null end
    ) as payout_notice_failure_trigger_status,
    left(
      coalesce(
        (
          select string_agg(errs.err_txt, ' | ')
          from (
            select distinct nullif(btrim(coalesce(evf2.error_text, '')), '') as err_txt
            from pg_temp._tmp_mark_sent_events evf2
            where evf2.candidate_id = tc.candidate_id
              and evf2.comm_kind = 'REMITTANCE'
              and evf2.outcome = 'FAILURE'
              and nullif(btrim(coalesce(evf2.error_text, '')), '') is not null
            order by err_txt
          ) errs
        ),
        case when tc.target_from_remittance then 'NO_RESULT_RECORDED' else null end
      ),
      1000
    ) as remittance_failure_error,
    left(
      coalesce(
        (
          select string_agg(errs.err_txt, ' | ')
          from (
            select distinct nullif(btrim(coalesce(evf2.error_text, '')), '') as err_txt
            from pg_temp._tmp_mark_sent_events evf2
            where evf2.candidate_id = tc.candidate_id
              and evf2.comm_kind = 'PAYOUT_NOTICE'
              and evf2.outcome = 'FAILURE'
              and nullif(btrim(coalesce(evf2.error_text, '')), '') is not null
            order by err_txt
          ) errs
        ),
        case when tc.target_from_payout_notice then 'NO_RESULT_RECORDED' else null end
      ),
      1000
    ) as payout_notice_failure_error
  from pg_temp._tmp_mark_sent_target_candidates tc;

  update public.pay_batch_candidates pbc
  set
    remittance_sent_at_utc = coalesce(pbc.remittance_sent_at_utc, v_now),
    remittance_sent_by_user_id = coalesce(pbc.remittance_sent_by_user_id, p_actor_user_id),
    remittance_trigger_status = agg.remittance_success_trigger_status,
    last_remittance_error = null,
    updated_at = v_now
  from pg_temp._tmp_mark_sent_agg agg
  where pbc.id = agg.pay_batch_candidate_id
    and agg.target_from_remittance = true
    and agg.has_success_remittance = true;

  update public.pay_batch_candidates pbc
  set
    remittance_trigger_status = agg.remittance_failure_trigger_status,
    last_remittance_error = agg.remittance_failure_error,
    updated_at = v_now
  from pg_temp._tmp_mark_sent_agg agg
  where pbc.id = agg.pay_batch_candidate_id
    and agg.target_from_remittance = true
    and agg.has_success_remittance = false
    and agg.remittance_failure_trigger_status <> 'NO_RESULT_RECORDED';

  update public.pay_batch_candidates pbc
  set
    remittance_trigger_status = coalesce(
      (
        select evq.trigger_status
        from pg_temp._tmp_mark_sent_events evq
        where evq.candidate_id = pbc.candidate_id
          and evq.comm_kind = 'REMITTANCE'
          and evq.outcome = 'QUEUED'
          and nullif(btrim(coalesce(evq.trigger_status, '')), '') is not null
        order by evq.trigger_status
        limit 1
      ),
      pbc.remittance_trigger_status
    ),
    last_remittance_error = null,
    updated_at = v_now
  from pg_temp._tmp_mark_sent_agg agg
  where pbc.id = agg.pay_batch_candidate_id
    and agg.target_from_remittance = true
    and agg.has_success_remittance = false
    and agg.remittance_failure_trigger_status = 'NO_RESULT_RECORDED'
    and exists (
      select 1
      from pg_temp._tmp_mark_sent_events evq2
      where evq2.candidate_id = pbc.candidate_id
        and evq2.comm_kind = 'REMITTANCE'
        and evq2.outcome = 'QUEUED'
    );

  select count(*)::int
  into v_success_count
  from pg_temp._tmp_mark_sent_agg agg
  where agg.has_success = true;

  select count(*)::int
  into v_failure_count
  from pg_temp._tmp_mark_sent_agg agg
  where agg.has_success = false
    and (agg.target_from_remittance = true or agg.target_from_payout_notice = true)
    and agg.failure_trigger_status <> 'NO_RESULT_RECORDED';

  select count(*)::int
  into v_no_result_count
  from pg_temp._tmp_mark_sent_agg agg
  where agg.has_success = false
    and agg.failure_trigger_status = 'NO_RESULT_RECORDED'
    and not exists (
      select 1
      from pg_temp._tmp_mark_sent_events evq
      where evq.candidate_id = agg.candidate_id
        and evq.outcome = 'QUEUED'
    );

  select count(*)::int
  into v_remittance_success_count
  from pg_temp._tmp_mark_sent_agg agg
  where agg.target_from_remittance = true
    and agg.has_success_remittance = true;

  select count(*)::int
  into v_remittance_failure_count
  from pg_temp._tmp_mark_sent_agg agg
  where agg.target_from_remittance = true
    and agg.has_success_remittance = false
    and agg.remittance_failure_trigger_status <> 'NO_RESULT_RECORDED';

  select count(*)::int
  into v_remittance_no_result_count
  from pg_temp._tmp_mark_sent_agg agg
  where agg.target_from_remittance = true
    and agg.has_success_remittance = false
    and agg.remittance_failure_trigger_status = 'NO_RESULT_RECORDED';

  select count(*)::int
  into v_payout_notice_success_count
  from pg_temp._tmp_mark_sent_agg agg
  where agg.target_from_payout_notice = true
    and agg.has_success_payout_notice = true;

  select count(*)::int
  into v_payout_notice_failure_count
  from pg_temp._tmp_mark_sent_agg agg
  where agg.target_from_payout_notice = true
    and agg.has_success_payout_notice = false
    and agg.payout_notice_failure_trigger_status <> 'NO_RESULT_RECORDED';

  select count(*)::int
  into v_payout_notice_no_result_count
  from pg_temp._tmp_mark_sent_agg agg
  where agg.target_from_payout_notice = true
    and agg.has_success_payout_notice = false
    and agg.payout_notice_failure_trigger_status = 'NO_RESULT_RECORDED';

  insert into public.audit_events(
    actor_user_id,
    object_type,
    object_id_text,
    action,
    before_json,
    after_json,
    reason
  )
  values (
    p_actor_user_id,
    'pay_batch',
    p_pay_batch_id::text,
    v_audit_action,
    null,
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id::text,
      'scope', v_scope,
      'message_kind', v_message_kind,
      'communication_mode', v_communication_mode,
      'success_count', v_success_count,
      'failure_count', v_failure_count,
      'no_result_count', v_no_result_count,
      'remittance_result', jsonb_build_object(
        'included', v_has_remittance_result,
        'success_count', v_remittance_success_count,
        'failure_count', v_remittance_failure_count,
        'no_result_count', v_remittance_no_result_count,
        'unmatched_queued_count', v_remittance_unmatched_queued_count,
        'unmatched_skipped_count', v_remittance_unmatched_skipped_count,
        'results', case when v_has_remittance_result then coalesce(v_remittance_result, '{}'::jsonb) else null end
      ),
      'payout_notice_result', jsonb_build_object(
        'included', v_has_payout_notice_result,
        'success_count', v_payout_notice_success_count,
        'failure_count', v_payout_notice_failure_count,
        'no_result_count', v_payout_notice_no_result_count,
        'unmatched_queued_count', v_payout_notice_unmatched_queued_count,
        'unmatched_skipped_count', v_payout_notice_unmatched_skipped_count,
        'results', case when v_has_payout_notice_result then coalesce(v_payout_notice_result, '{}'::jsonb) else null end
      ),
      'results', coalesce(v_results, '{}'::jsonb)
    ),
    v_audit_reason
  )
  returning id into v_audit_id;

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'scope', v_scope,
    'message_kind', v_message_kind,
    'communication_mode', v_communication_mode,
    'success_count', v_success_count,
    'failure_count', v_failure_count,
    'no_result_count', v_no_result_count,
    'remittance_result', jsonb_build_object(
      'included', v_has_remittance_result,
      'success_count', v_remittance_success_count,
      'failure_count', v_remittance_failure_count,
      'no_result_count', v_remittance_no_result_count,
      'unmatched_queued_count', v_remittance_unmatched_queued_count,
      'unmatched_skipped_count', v_remittance_unmatched_skipped_count
    ),
    'payout_notice_result', jsonb_build_object(
      'included', v_has_payout_notice_result,
      'success_count', v_payout_notice_success_count,
      'failure_count', v_payout_notice_failure_count,
      'no_result_count', v_payout_notice_no_result_count,
      'unmatched_queued_count', v_payout_notice_unmatched_queued_count,
      'unmatched_skipped_count', v_payout_notice_unmatched_skipped_count
    ),
    'audit_event_id', v_audit_id::text
  );
end;
$function$;

-- pay_remittance_maybe_queue_for_trigger(uuid,text,text,uuid,boolean,uuid,boolean)
CREATE OR REPLACE FUNCTION public.pay_remittance_maybe_queue_for_trigger(p_pay_batch_id uuid, p_trigger text, p_scope text DEFAULT 'ALL'::text, p_actor_user_id uuid DEFAULT NULL::uuid, p_only_confirmed boolean DEFAULT false, p_root_operation_id uuid DEFAULT NULL::uuid, p_operation_mode boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch public.pay_batches%rowtype;
  v_trigger text;
  v_scope text;
  v_timing_setting text := 'ON_EXECUTION';
  v_effective_actor_user_id uuid;
  v_is_loans_batch boolean := false;
  v_suppress_remittances boolean := false;
  v_suppress_reasons jsonb := '[]'::jsonb;
  v_auth_suppress_count integer := 0;
  v_queue_result jsonb := '{}'::jsonb;
  v_has_remittance_operation_overload boolean := false;
  v_has_finance_operation_overload boolean := false;
  v_has_remittance_confirmed_overload boolean := false;
  v_has_finance_confirmed_overload boolean := false;
  v_has_remittance_legacy_function boolean := false;
  v_has_finance_legacy_function boolean := false;
  v_dispatch_required boolean := false;
  v_job_count integer := 0;
  v_operation_start record;
  v_operation_kind text := null;
  v_operation_idempotency_key text := null;
  v_operation_input_json jsonb := '{}'::jsonb;
  v_operation_config_json jsonb := '{}'::jsonb;
  v_operation_config_snapshot_status text := 'created_or_reused';
  v_operation_runner_repair_count integer := 0;
  v_batch_candidate_count integer := 0;
  v_large_batch_threshold integer := 100;
BEGIN
  v_trigger := upper(nullif(btrim(COALESCE(p_trigger, '')), ''));
  v_scope := upper(nullif(btrim(COALESCE(p_scope, 'ALL')), ''));

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_REMITTANCE_MAYBE_QUEUE_FOR_TRIGGER_START',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'trigger', v_trigger,
      'scope', v_scope,
      'actor_user_id', p_actor_user_id,
      'only_confirmed', COALESCE(p_only_confirmed, false)
    ),
    'pay_remittance',
    COALESCE(p_pay_batch_id::text, 'NO_BATCH_ID'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  IF v_trigger NOT IN ('ON_EXECUTION', 'ON_PAYMENT_CONFIRMED') THEN
    RAISE EXCEPTION 'UNSUPPORTED_REMITTANCE_QUEUE_TRIGGER'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'UNSUPPORTED_REMITTANCE_QUEUE_TRIGGER',
              'trigger', p_trigger,
              'supported_triggers', jsonb_build_array('ON_EXECUTION', 'ON_PAYMENT_CONFIRMED')
            )::text;
  END IF;

  IF v_scope NOT IN ('ALL', 'PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'UNSUPPORTED_REMITTANCE_QUEUE_SCOPE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'UNSUPPORTED_REMITTANCE_QUEUE_SCOPE',
              'scope', p_scope,
              'supported_scopes', jsonb_build_array('ALL', 'PAYE', 'UMBRELLA')
            )::text;
  END IF;

  SELECT public.pay_batches.*
  INTO v_batch
  FROM public.pay_batches
  WHERE public.pay_batches.id = p_pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id
            )::text;
  END IF;

  v_effective_actor_user_id := COALESCE(p_actor_user_id, v_batch.created_by_user_id);
  v_is_loans_batch := upper(btrim(COALESCE(v_batch.batch_kind_fixed, ''))) IN ('LOANS', 'LOAN', 'FINANCE_PAYOUTS', 'PAYOUTS');

  SELECT COALESCE(NULLIF(btrim(public.settings_defaults.payment_remittance_send_timing), ''), 'ON_EXECUTION')
  INTO v_timing_setting
  FROM public.settings_defaults
  ORDER BY public.settings_defaults.id
  LIMIT 1;

  v_timing_setting := upper(COALESCE(NULLIF(btrim(v_timing_setting), ''), 'ON_EXECUTION'));

  IF v_timing_setting NOT IN ('ON_EXECUTION', 'ON_PAYMENT_CONFIRMED') THEN
    v_timing_setting := 'ON_EXECUTION';
  END IF;

  IF v_timing_setting <> v_trigger THEN
    RETURN jsonb_build_object(
      'ok', true,
      'queued', false,
      'deferred', true,
      'suppressed', false,
      'dispatch_required', false,
      'requires_remittance_operation', false,
      'trigger_status', 'DEFERRED_BY_CONFIGURED_TIMING',
      'operation_mode', COALESCE(p_operation_mode, false),
      'operation_idempotency_key', NULL::text,
      'already_exists', false,
      'operation_created', false,
      'operation_reused', false,
      'child_operation_id', NULL::text,
      'operation_id', NULL::text,
      'trigger', v_trigger,
      'configured_timing', v_timing_setting,
      'pay_batch_id', p_pay_batch_id,
      'scope', v_scope,
      'only_confirmed', COALESCE(p_only_confirmed, false),
      'message', 'Remittance/payout notice queueing deferred because configured timing does not match this trigger.'
    );
  END IF;

  IF lower(btrim(COALESCE(v_batch.execution_intent_json->>'suppress_remittances', 'false'))) IN ('true', '1', 'yes', 'y', 'on') THEN
    v_suppress_remittances := true;
    v_suppress_reasons := v_suppress_reasons || jsonb_build_array('batch.execution_intent_json.suppress_remittances');
  END IF;

  IF lower(btrim(COALESCE(v_batch.settlement_confirmation_json->>'suppress_remittances', 'false'))) IN ('true', '1', 'yes', 'y', 'on') THEN
    v_suppress_remittances := true;
    v_suppress_reasons := v_suppress_reasons || jsonb_build_array('batch.settlement_confirmation_json.suppress_remittances');
  END IF;

  IF lower(btrim(COALESCE(v_batch.execution_intent_json->>'suppress_remittances_pending', 'false'))) IN ('true', '1', 'yes', 'y', 'on') THEN
    v_suppress_remittances := true;
    v_suppress_reasons := v_suppress_reasons || jsonb_build_array('batch.execution_intent_json.suppress_remittances_pending');
  END IF;

  IF lower(btrim(COALESCE(v_batch.settlement_confirmation_json->>'suppress_remittances_pending', 'false'))) IN ('true', '1', 'yes', 'y', 'on') THEN
    v_suppress_remittances := true;
    v_suppress_reasons := v_suppress_reasons || jsonb_build_array('batch.settlement_confirmation_json.suppress_remittances_pending');
  END IF;

  SELECT count(*)::integer
  INTO v_auth_suppress_count
  FROM public.pay_batch_auth_requests AS active_auth_requests
  WHERE active_auth_requests.pay_batch_id = p_pay_batch_id
    AND active_auth_requests.finalised_at_utc IS NULL
    AND (
      lower(btrim(COALESCE(active_auth_requests.execution_intent_json->>'suppress_remittances', 'false'))) IN ('true', '1', 'yes', 'y', 'on')
      OR lower(btrim(COALESCE(active_auth_requests.execution_intent_json->>'suppress_remittances_pending', 'false'))) IN ('true', '1', 'yes', 'y', 'on')
    );

  IF v_auth_suppress_count > 0 THEN
    v_suppress_remittances := true;
    v_suppress_reasons := v_suppress_reasons || jsonb_build_array('active_auth_request.execution_intent_json.suppress_remittances');
  END IF;

  IF v_suppress_remittances THEN
    RETURN jsonb_build_object(
      'ok', true,
      'queued', false,
      'deferred', false,
      'suppressed', true,
      'dispatch_required', false,
      'requires_remittance_operation', false,
      'trigger_status', 'SUPPRESSED_BY_EXECUTION_OR_SETTLEMENT_INTENT',
      'operation_mode', COALESCE(p_operation_mode, false),
      'operation_idempotency_key', NULL::text,
      'already_exists', false,
      'operation_created', false,
      'operation_reused', false,
      'child_operation_id', NULL::text,
      'operation_id', NULL::text,
      'trigger', v_trigger,
      'configured_timing', v_timing_setting,
      'pay_batch_id', p_pay_batch_id,
      'scope', v_scope,
      'only_confirmed', COALESCE(p_only_confirmed, false),
      'suppress_reasons', v_suppress_reasons,
      'message', 'Remittance/payout notice queueing suppressed by execution or settlement intent.'
    );
  END IF;

  IF v_effective_actor_user_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'queued', false,
      'deferred', false,
      'suppressed', false,
      'dispatch_required', false,
      'requires_remittance_operation', false,
      'trigger_status', 'ACTOR_USER_ID_REQUIRED_FOR_QUEUE_STAGE',
      'operation_mode', COALESCE(p_operation_mode, false),
      'operation_idempotency_key', NULL::text,
      'already_exists', false,
      'operation_created', false,
      'operation_reused', false,
      'child_operation_id', NULL::text,
      'operation_id', NULL::text,
      'trigger', v_trigger,
      'configured_timing', v_timing_setting,
      'pay_batch_id', p_pay_batch_id,
      'scope', v_scope,
      'only_confirmed', COALESCE(p_only_confirmed, false),
      'error', 'ACTOR_USER_ID_REQUIRED_FOR_QUEUE_STAGE',
      'message', 'Queue-stage RPC requires an actor user id and none was supplied or available from the batch creator.'
    );
  END IF;

  IF COALESCE(p_operation_mode, false) THEN
    v_operation_kind := CASE WHEN v_is_loans_batch THEN 'PAYOUT_NOTICE' ELSE 'REMITTANCE' END;
    v_operation_idempotency_key := 'remittance-queue:batch:' || p_pay_batch_id::text
      || ':trigger:' || v_trigger
      || ':scope:' || v_scope
      || ':only-confirmed:' || CASE WHEN COALESCE(p_only_confirmed, false) THEN 'true' ELSE 'false' END
      || ':kind:' || v_operation_kind
      || ':root:' || COALESCE(p_root_operation_id::text, 'none');

    v_operation_input_json := jsonb_build_object(
      'pay_batch_id', p_pay_batch_id::text,
      'trigger', v_trigger,
      'configured_timing', v_timing_setting,
      'scope', v_scope,
      'only_confirmed', COALESCE(p_only_confirmed, false),
      'message_kind', v_operation_kind,
      'is_loans_batch', v_is_loans_batch,
      'root_operation_id', CASE WHEN p_root_operation_id IS NULL THEN NULL ELSE p_root_operation_id::text END,
      'source_rpc', 'pay_remittance_maybe_queue_for_trigger',
      'backend_runner_owned', true,
      'server_runnable', true,
      'frontend_completion_required', false
    );

    WITH operation_config_plan AS (
      SELECT *
      FROM (
        VALUES
          ('queue_remittance_chunks', 'REMITTANCE_QUEUE', 'QUEUE_REMITTANCE_CHUNKS', 'REMITTANCE'),
          ('queue_payout_notice_chunks', 'REMITTANCE_QUEUE', 'QUEUE_PAYOUT_NOTICE_CHUNKS', 'PAYOUT_NOTICE')
      ) AS config_plan(config_key, operation_type, phase, chunk_type)
    ), operation_config_rows AS (
      SELECT
        operation_config_plan.config_key,
        operation_config_plan.operation_type,
        operation_config_plan.phase,
        operation_config_plan.chunk_type,
        operation_config_get.chunk_size,
        operation_config_get.min_chunk_size,
        operation_config_get.max_chunk_size,
        operation_config_get.max_advance_ms,
        operation_config_get.lock_seconds
      FROM operation_config_plan
      CROSS JOIN LATERAL public.banking_pay_operation_config_get(
        p_operation_type => operation_config_plan.operation_type,
        p_phase => operation_config_plan.phase,
        p_chunk_type => operation_config_plan.chunk_type
      ) AS operation_config_get
    )
    SELECT jsonb_build_object(
      'source', 'pay_remittance_maybe_queue_for_trigger',
      'source_rpc', 'pay_remittance_maybe_queue_for_trigger',
      'version', 1,
      'operation_type', 'REMITTANCE_QUEUE',
      'server_runnable', true,
      'backend_runner_owned', true,
      'frontend_completion_required', false,
      'operation_created_for_backend_runner', true,
      'snapshotted_at_utc', now()::text,
      'lock_seconds', COALESCE(max(operation_config_rows.lock_seconds), 60),
      'max_advance_ms', COALESCE(max(operation_config_rows.max_advance_ms), 15000),
      'chunks', COALESCE(jsonb_object_agg(
        operation_config_rows.config_key,
        jsonb_build_object(
          'operation_type', operation_config_rows.operation_type,
          'phase', operation_config_rows.phase,
          'chunk_type', operation_config_rows.chunk_type,
          'chunk_size', operation_config_rows.chunk_size,
          'min_chunk_size', operation_config_rows.min_chunk_size,
          'max_chunk_size', operation_config_rows.max_chunk_size,
          'max_advance_ms', operation_config_rows.max_advance_ms,
          'lock_seconds', operation_config_rows.lock_seconds
        )
        ORDER BY operation_config_rows.config_key
      ), '{}'::jsonb)
    )
    INTO v_operation_config_json
    FROM operation_config_rows;

    v_operation_config_json := COALESCE(v_operation_config_json, '{}'::jsonb) || jsonb_build_object(
      'remittance_chunk_size', COALESCE(NULLIF(v_operation_config_json #>> '{chunks,queue_remittance_chunks,chunk_size}', '')::integer, 100),
      'payout_notice_chunk_size', COALESCE(NULLIF(v_operation_config_json #>> '{chunks,queue_payout_notice_chunks,chunk_size}', '')::integer, 100),
      'server_runnable', true,
      'backend_runner_owned', true,
      'frontend_completion_required', false,
      'operation_created_for_backend_runner', true,
      'source_rpc', 'pay_remittance_maybe_queue_for_trigger',
      'run_after_utc', now()::text
    );

    SELECT operation_start_row.*
    INTO v_operation_start
    FROM public.banking_pay_operation_start(
      p_operation_type => 'REMITTANCE_QUEUE',
      p_actor_user_id => v_effective_actor_user_id,
      p_idempotency_key => v_operation_idempotency_key,
      p_workbench_session_id => NULL::uuid,
      p_pay_batch_id => p_pay_batch_id,
      p_root_operation_id => p_root_operation_id,
      p_input_json => v_operation_input_json,
      p_config_json => v_operation_config_json
    ) AS operation_start_row;


    UPDATE public.banking_pay_operations AS remittance_operation_update
    SET config_json = jsonb_strip_nulls(COALESCE(remittance_operation_update.config_json, '{}'::jsonb) || v_operation_config_json || jsonb_build_object(
          'server_runnable', true,
          'backend_runner_owned', true,
          'frontend_completion_required', false,
          'operation_created_for_backend_runner', true,
          'source_rpc', 'pay_remittance_maybe_queue_for_trigger',
          'run_after_utc', COALESCE(remittance_operation_update.run_after_utc, now())::text
        )),
        progress_json = jsonb_strip_nulls(COALESCE(remittance_operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
          'server_runnable', true,
          'backend_runner_owned', true,
          'frontend_completion_required', false,
          'operation_created_for_backend_runner', true,
          'operation_reused_for_backend_runner', COALESCE(v_operation_start.is_existing, false),
          'runner_flags_repaired_at_utc', now()::text,
          'source_rpc', 'pay_remittance_maybe_queue_for_trigger',
          'run_after_utc', COALESCE(remittance_operation_update.run_after_utc, now())::text
        )),
        runner_state = 'RUNNABLE',
        requires_user_action = false,
        run_after_utc = COALESCE(remittance_operation_update.run_after_utc, now()),
        updated_at_utc = now()
    WHERE remittance_operation_update.id = v_operation_start.operation_id
      AND upper(btrim(coalesce(remittance_operation_update.status, ''))) NOT IN ('COMPLETE', 'COMPLETED', 'FAILED', 'CANCELLED', 'CANCELED', 'ERROR', 'REVIEW_REQUIRED')
      AND (
        upper(btrim(coalesce(remittance_operation_update.runner_state, ''))) <> 'RUNNABLE'
        OR remittance_operation_update.run_after_utc IS NULL
        OR lower(btrim(coalesce(remittance_operation_update.config_json->>'backend_runner_owned', remittance_operation_update.config_json->>'backendRunnerOwned', remittance_operation_update.progress_json->>'backend_runner_owned', remittance_operation_update.progress_json->>'backendRunnerOwned', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        OR lower(btrim(coalesce(remittance_operation_update.config_json->>'frontend_completion_required', remittance_operation_update.config_json->>'frontendCompletionRequired', remittance_operation_update.progress_json->>'frontend_completion_required', remittance_operation_update.progress_json->>'frontendCompletionRequired', 'true'))) NOT IN ('false', 'f', '0', 'no', 'n', 'off')
        OR lower(btrim(coalesce(remittance_operation_update.config_json->>'server_runnable', remittance_operation_update.config_json->>'serverRunnable', remittance_operation_update.progress_json->>'server_runnable', remittance_operation_update.progress_json->>'serverRunnable', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
      );

    GET DIAGNOSTICS v_operation_runner_repair_count = ROW_COUNT;

    v_operation_config_snapshot_status := CASE
      WHEN COALESCE(v_operation_runner_repair_count, 0) > 0 AND COALESCE(v_operation_start.is_existing, false) THEN 'reused_repaired'
      WHEN COALESCE(v_operation_runner_repair_count, 0) > 0 THEN 'created_repaired'
      WHEN v_operation_start.config_json IS NULL OR v_operation_start.config_json = '{}'::jsonb THEN 'repaired'
      WHEN v_operation_start.is_existing THEN 'reused'
      ELSE 'created'
    END;

    IF v_operation_config_snapshot_status = 'repaired' THEN
      UPDATE public.banking_pay_operations AS operation_update
      SET config_json = v_operation_config_json,
          progress_json = COALESCE(operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
            'config_snapshot_status', 'repaired',
            'config_snapshot_repaired_at_utc', now()::text,
            'config_snapshot_source', 'pay_remittance_maybe_queue_for_trigger'
          ),
          updated_at_utc = now()
      WHERE operation_update.id = v_operation_start.operation_id
        AND (operation_update.config_json IS NULL OR operation_update.config_json = '{}'::jsonb);
    END IF;

    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_REMITTANCE_MAYBE_QUEUE_FOR_TRIGGER_OPERATION_STARTED',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id,
        'trigger', v_trigger,
        'configured_timing', v_timing_setting,
        'scope', v_scope,
        'only_confirmed', COALESCE(p_only_confirmed, false),
        'is_loans_batch', v_is_loans_batch,
        'message_kind', v_operation_kind,
        'operation_id', v_operation_start.operation_id,
        'operation_status', v_operation_start.status,
        'operation_phase', v_operation_start.phase,
        'operation_config_snapshot_status', v_operation_config_snapshot_status,
        'operation_runner_repair_count', COALESCE(v_operation_runner_repair_count, 0),
        'server_runnable', true,
        'backend_runner_owned', true,
        'frontend_completion_required', false,
        'operation_idempotency_key', v_operation_idempotency_key,
        'already_exists', COALESCE(v_operation_start.is_existing, false),
        'operation_created', COALESCE(v_operation_start.is_existing, false) = false,
        'operation_reused', COALESCE(v_operation_start.is_existing, false) = true,
        'root_operation_id', p_root_operation_id
      ),
      'pay_remittance',
      p_pay_batch_id::text,
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RETURN jsonb_build_object(
      'ok', true,
      'queued', true,
      'operation_queued', true,
      'deferred', false,
      'suppressed', false,
      'dispatch_required', true,
      'advance_inline_allowed', true,
      'requires_remittance_operation', true,
      'server_runnable', true,
      'backend_runner_owned', true,
      'frontend_completion_required', false,
      'runner_flags_repaired', COALESCE(v_operation_runner_repair_count, 0) > 0,
      'trigger_status', CASE WHEN COALESCE(v_operation_runner_repair_count, 0) > 0 AND COALESCE(v_operation_start.is_existing, false) THEN 'REMITTANCE_QUEUE_OPERATION_REUSED_REPAIRED' WHEN COALESCE(v_operation_start.is_existing, false) THEN 'REMITTANCE_QUEUE_OPERATION_REUSED' ELSE 'REMITTANCE_QUEUE_OPERATION_STARTED' END,
      'operation_mode', true,
      'operation_idempotency_key', v_operation_idempotency_key,
      'already_exists', COALESCE(v_operation_start.is_existing, false),
      'operation_created', COALESCE(v_operation_start.is_existing, false) = false,
      'operation_reused', COALESCE(v_operation_start.is_existing, false) = true,
      'child_operation_id', v_operation_start.operation_id::text,
      'trigger', v_trigger,
      'configured_timing', v_timing_setting,
      'pay_batch_id', p_pay_batch_id,
      'scope', v_scope,
      'only_confirmed', COALESCE(p_only_confirmed, false),
      'is_loans_batch', v_is_loans_batch,
      'message_kind', v_operation_kind,
      'effective_actor_user_id', v_effective_actor_user_id,
      'operation_id', v_operation_start.operation_id::text,
      'operation_type', v_operation_start.operation_type,
      'operation_status', v_operation_start.status,
      'operation_phase', v_operation_start.phase,
      'operation_config_snapshot_status', v_operation_config_snapshot_status,
      'operation_runner_repair_count', COALESCE(v_operation_runner_repair_count, 0),
      'run_after_utc', now()::text,
      'root_operation_id', CASE WHEN p_root_operation_id IS NULL THEN NULL ELSE p_root_operation_id::text END,
      'queue_result', jsonb_build_object(
        'ok', true,
        'operation_mode', true,
        'trigger', v_trigger,
        'configured_timing', v_timing_setting,
        'scope', v_scope,
        'only_confirmed', COALESCE(p_only_confirmed, false),
        'operation_idempotency_key', v_operation_idempotency_key,
        'already_exists', COALESCE(v_operation_start.is_existing, false),
        'operation_created', COALESCE(v_operation_start.is_existing, false) = false,
        'operation_reused', COALESCE(v_operation_start.is_existing, false) = true,
        'child_operation_id', v_operation_start.operation_id::text,
        'operation_id', v_operation_start.operation_id::text,
        'operation_type', v_operation_start.operation_type,
        'status', v_operation_start.status,
        'phase', v_operation_start.phase,
        'operation_config_snapshot_status', v_operation_config_snapshot_status,
        'pay_batch_id', p_pay_batch_id::text,
        'message_kind', v_operation_kind,
        'trigger_status', CASE WHEN COALESCE(v_operation_runner_repair_count, 0) > 0 AND COALESCE(v_operation_start.is_existing, false) THEN 'REMITTANCE_QUEUE_OPERATION_REUSED_REPAIRED' WHEN COALESCE(v_operation_start.is_existing, false) THEN 'REMITTANCE_QUEUE_OPERATION_REUSED' ELSE 'REMITTANCE_QUEUE_OPERATION_STARTED' END,
        'dispatch_required', true,
        'advance_inline_allowed', true,
        'requires_remittance_operation', true,
        'server_runnable', true,
        'backend_runner_owned', true,
        'frontend_completion_required', false,
        'runner_flags_repaired', COALESCE(v_operation_runner_repair_count, 0) > 0,
        'operation_queued', true,
        'job_count', 0,
        'jobs', '[]'::jsonb
      )
    );
  END IF;

  SELECT count(*)::integer
  INTO v_batch_candidate_count
  FROM public.pay_batch_candidates AS batch_candidate_count_row
  WHERE batch_candidate_count_row.pay_batch_id = p_pay_batch_id;

  IF v_batch_candidate_count > v_large_batch_threshold THEN
    v_operation_kind := CASE WHEN v_is_loans_batch THEN 'PAYOUT_NOTICE' ELSE 'REMITTANCE' END;

    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_REMITTANCE_MAYBE_QUEUE_FOR_TRIGGER_OPERATION_REQUIRED_FOR_LARGE_BATCH',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id,
        'trigger', v_trigger,
        'configured_timing', v_timing_setting,
        'scope', v_scope,
        'only_confirmed', COALESCE(p_only_confirmed, false),
        'is_loans_batch', v_is_loans_batch,
        'message_kind', v_operation_kind,
        'batch_candidate_count', v_batch_candidate_count,
        'large_batch_threshold', v_large_batch_threshold
      ),
      'pay_remittance',
      p_pay_batch_id::text,
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RETURN jsonb_build_object(
      'ok', true,
      'queued', false,
      'operation_queued', false,
      'deferred', false,
      'suppressed', false,
      'dispatch_required', false,
      'requires_remittance_operation', true,
      'trigger_status', 'REMITTANCE_QUEUE_OPERATION_REQUIRED_FOR_LARGE_BATCH',
      'operation_mode', false,
      'operation_idempotency_key', NULL::text,
      'already_exists', false,
      'operation_created', false,
      'operation_reused', false,
      'child_operation_id', NULL::text,
      'operation_id', NULL::text,
      'operation_status', NULL::text,
      'operation_phase', NULL::text,
      'trigger', v_trigger,
      'configured_timing', v_timing_setting,
      'pay_batch_id', p_pay_batch_id,
      'scope', v_scope,
      'only_confirmed', COALESCE(p_only_confirmed, false),
      'is_loans_batch', v_is_loans_batch,
      'message_kind', v_operation_kind,
      'effective_actor_user_id', v_effective_actor_user_id,
      'batch_candidate_count', v_batch_candidate_count,
      'large_batch_threshold', v_large_batch_threshold,
      'message', 'Large payment batches must queue remittances through a REMITTANCE_QUEUE operation.',
      'queue_result', jsonb_build_object(
        'ok', true,
        'operation_required', true,
        'operation_mode', false,
        'operation_idempotency_key', NULL::text,
        'already_exists', false,
        'operation_created', false,
        'operation_reused', false,
        'child_operation_id', NULL::text,
        'trigger_status', 'REMITTANCE_QUEUE_OPERATION_REQUIRED_FOR_LARGE_BATCH',
        'message_kind', v_operation_kind,
        'dispatch_required', false,
        'job_count', 0
      )
    );
  END IF;

  v_has_remittance_operation_overload := to_regprocedure('public.pay_remittance_queue_commit_stage(uuid,text,uuid,boolean,uuid,jsonb)') IS NOT NULL;
  v_has_finance_operation_overload := to_regprocedure('public.pay_finance_payout_notice_queue_commit_stage(uuid,uuid,boolean,uuid,jsonb)') IS NOT NULL;
  v_has_remittance_confirmed_overload := to_regprocedure('public.pay_remittance_queue_commit_stage(uuid,text,uuid,boolean)') IS NOT NULL;
  v_has_finance_confirmed_overload := to_regprocedure('public.pay_finance_payout_notice_queue_commit_stage(uuid,uuid,boolean)') IS NOT NULL;
  v_has_remittance_legacy_function := to_regprocedure('public.pay_remittance_queue_commit_stage(uuid,text,uuid)') IS NOT NULL;
  v_has_finance_legacy_function := to_regprocedure('public.pay_finance_payout_notice_queue_commit_stage(uuid,uuid)') IS NOT NULL;

  IF v_is_loans_batch THEN
    IF v_has_finance_operation_overload THEN
      EXECUTE 'SELECT public.pay_finance_payout_notice_queue_commit_stage($1, $2, $3, NULL::uuid, NULL::jsonb)'
      INTO v_queue_result
      USING p_pay_batch_id, v_effective_actor_user_id, COALESCE(p_only_confirmed, false);
    ELSIF v_has_finance_confirmed_overload THEN
      EXECUTE 'SELECT public.pay_finance_payout_notice_queue_commit_stage($1, $2, $3)'
      INTO v_queue_result
      USING p_pay_batch_id, v_effective_actor_user_id, COALESCE(p_only_confirmed, false);
    ELSIF COALESCE(p_only_confirmed, false) THEN
      v_queue_result := jsonb_build_object(
        'ok', true,
        'trigger_status', 'CONFIRMED_ONLY_QUEUE_STAGE_OVERLOAD_NOT_INSTALLED',
        'message_kind', 'PAYOUT_NOTICE',
        'automatic_commit_stage', true,
        'dispatch_required', false,
        'pay_batch_id', p_pay_batch_id,
        'job_count', 0,
        'jobs', '[]'::jsonb,
        'message', 'Confirmed-only finance payout notice queue-stage overload is not installed yet.'
      );
    ELSIF v_has_finance_legacy_function THEN
      EXECUTE 'SELECT public.pay_finance_payout_notice_queue_commit_stage($1, $2)'
      INTO v_queue_result
      USING p_pay_batch_id, v_effective_actor_user_id;
    ELSE
      v_queue_result := jsonb_build_object(
        'ok', false,
        'trigger_status', 'PAYOUT_NOTICE_QUEUE_STAGE_FUNCTION_MISSING',
        'message_kind', 'PAYOUT_NOTICE',
        'dispatch_required', false,
        'pay_batch_id', p_pay_batch_id,
        'job_count', 0,
        'jobs', '[]'::jsonb,
        'error', 'pay_finance_payout_notice_queue_commit_stage function not found'
      );
    END IF;
  ELSE
    IF v_has_remittance_operation_overload THEN
      EXECUTE 'SELECT public.pay_remittance_queue_commit_stage($1, $2, $3, $4, NULL::uuid, NULL::jsonb)'
      INTO v_queue_result
      USING p_pay_batch_id, v_scope, v_effective_actor_user_id, COALESCE(p_only_confirmed, false);
    ELSIF v_has_remittance_confirmed_overload THEN
      EXECUTE 'SELECT public.pay_remittance_queue_commit_stage($1, $2, $3, $4)'
      INTO v_queue_result
      USING p_pay_batch_id, v_scope, v_effective_actor_user_id, COALESCE(p_only_confirmed, false);
    ELSIF COALESCE(p_only_confirmed, false) THEN
      v_queue_result := jsonb_build_object(
        'ok', true,
        'trigger_status', 'CONFIRMED_ONLY_QUEUE_STAGE_OVERLOAD_NOT_INSTALLED',
        'message_kind', 'REMITTANCE',
        'automatic_commit_stage', true,
        'dispatch_required', false,
        'pay_batch_id', p_pay_batch_id,
        'scope', v_scope,
        'job_count', 0,
        'jobs', '[]'::jsonb,
        'message', 'Confirmed-only remittance queue-stage overload is not installed yet.'
      );
    ELSIF v_has_remittance_legacy_function THEN
      EXECUTE 'SELECT public.pay_remittance_queue_commit_stage($1, $2, $3)'
      INTO v_queue_result
      USING p_pay_batch_id, v_scope, v_effective_actor_user_id;
    ELSE
      v_queue_result := jsonb_build_object(
        'ok', false,
        'trigger_status', 'REMITTANCE_QUEUE_STAGE_FUNCTION_MISSING',
        'message_kind', 'REMITTANCE',
        'dispatch_required', false,
        'pay_batch_id', p_pay_batch_id,
        'scope', v_scope,
        'job_count', 0,
        'jobs', '[]'::jsonb,
        'error', 'pay_remittance_queue_commit_stage function not found'
      );
    END IF;
  END IF;

  v_dispatch_required := COALESCE((v_queue_result->>'dispatch_required')::boolean, false);
  v_job_count := COALESCE((v_queue_result->>'job_count')::integer, 0);

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_REMITTANCE_MAYBE_QUEUE_FOR_TRIGGER_RESULT',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'trigger', v_trigger,
      'configured_timing', v_timing_setting,
      'scope', v_scope,
      'only_confirmed', COALESCE(p_only_confirmed, false),
      'is_loans_batch', v_is_loans_batch,
      'dispatch_required', v_dispatch_required,
      'job_count', v_job_count,
      'queue_result_status', v_queue_result->>'trigger_status'
    ),
    'pay_remittance',
    p_pay_batch_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  RETURN jsonb_build_object(
    'ok', COALESCE((v_queue_result->>'ok')::boolean, true),
    'queued', v_dispatch_required,
    'deferred', false,
    'suppressed', false,
    'dispatch_required', v_dispatch_required,
    'requires_remittance_operation', false,
    'trigger_status', COALESCE(NULLIF(btrim(COALESCE(v_queue_result->>'trigger_status', '')), ''), 'REMITTANCE_QUEUE_STAGE_PROCESSED'),
    'operation_mode', false,
    'operation_idempotency_key', NULL::text,
    'already_exists', false,
    'operation_created', false,
    'operation_reused', false,
    'child_operation_id', NULL::text,
    'operation_id', NULL::text,
    'trigger', v_trigger,
    'configured_timing', v_timing_setting,
    'pay_batch_id', p_pay_batch_id,
    'scope', v_scope,
    'only_confirmed', COALESCE(p_only_confirmed, false),
    'is_loans_batch', v_is_loans_batch,
    'effective_actor_user_id', v_effective_actor_user_id,
    'queue_result', COALESCE(v_queue_result, '{}'::jsonb)
  );

EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_REMITTANCE_MAYBE_QUEUE_FOR_TRIGGER_ERROR',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id,
        'trigger', p_trigger,
        'scope', p_scope,
        'only_confirmed', COALESCE(p_only_confirmed, false),
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_remittance',
      COALESCE(p_pay_batch_id::text, 'NO_BATCH_ID'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RAISE;
END;
$function$;

-- pay_remittance_queue_commit_stage(uuid,text,uuid,boolean,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_remittance_queue_commit_stage(p_pay_batch_id uuid, p_scope text, p_actor_user_id uuid, p_only_confirmed boolean DEFAULT false, p_operation_id uuid DEFAULT NULL::uuid, p_remittance_scope_ids jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_scope text := upper(btrim(coalesce(p_scope, 'ALL')));
  v_batch record;
  v_build_result jsonb := '{}'::jsonb;
  v_build_jobs jsonb := '[]'::jsonb;
  v_filtered_jobs jsonb := '[]'::jsonb;
  v_candidate_results jsonb := '[]'::jsonb;
  v_job_results jsonb := '[]'::jsonb;

  v_job jsonb;
  v_work_job jsonb;
  v_job_kind text;
  v_recipient_kind text;
  v_recipient_email text;
  v_candidate_id_text text;
  v_candidate_id uuid;
  v_umbrella_id_text text;
  v_umbrella_id uuid;

  v_pruned_candidates jsonb := '[]'::jsonb;
  v_candidate_json jsonb;
  v_candidate_work_json jsonb;
  v_pruned_non_timesheet_lines jsonb := '[]'::jsonb;
  v_pruned_transfers jsonb := '[]'::jsonb;
  v_pruned_timesheets jsonb := '[]'::jsonb;
  v_candidate_excluded_transfer_total numeric := 0;
  v_job_excluded_transfer_total numeric := 0;
  v_original_job_total numeric := 0;
  v_pruned_total_amount numeric := 0;
  v_final_paid_amount numeric := 0;

  v_target_candidate_count integer := 0;
  v_ready_candidate_count integer := 0;
  v_job_count integer := 0;
  v_trigger_status text := null;
  v_execution_intent_json jsonb := '{}'::jsonb;
  v_settlement_confirmation_json jsonb := '{}'::jsonb;
  v_suppress_remittances boolean := false;
  v_only_confirmed boolean := coalesce(p_only_confirmed, false);

  v_operation_mode boolean := false;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_requested_scope_count integer := 0;
  v_matched_scope_count integer := 0;
  v_already_queued_count integer := 0;
  v_inserted_outbox_count integer := 0;
  v_reused_outbox_count integer := 0;
  v_skipped_count integer := 0;
  v_failed_count integer := 0;
  v_remaining_count integer := 0;
  v_has_more boolean := false;
  v_operation_scope_ids jsonb := '[]'::jsonb;
  v_operation_job_results jsonb := '[]'::jsonb;
  v_legacy_scope_count integer := 0;
begin
  if p_pay_batch_id is null then
    raise exception 'pay_remittance_queue_commit_stage: pay_batch_id is required';
  end if;

  if p_actor_user_id is null then
    raise exception 'pay_remittance_queue_commit_stage: actor_user_id is required';
  end if;

  if v_scope not in ('ALL', 'PAYE', 'UMBRELLA') then
    raise exception 'pay_remittance_queue_commit_stage: invalid scope "%". Expected ALL|PAYE|UMBRELLA.', v_scope;
  end if;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_REMITTANCE_QUEUE_COMMIT_STAGE_START',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'scope', v_scope,
      'only_confirmed', COALESCE(p_only_confirmed, false)
    ),
    'pay_remittance',
    p_pay_batch_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  select
    pb.id,
    pb.status,
    pb.batch_kind_fixed,
    pb.pay_date,
    pb.authoritative_payment_date,
    pb.authoritative_payment_date_source,
    pb.bulk_reference,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc,
    pb.execution_intent_json,
    pb.settlement_confirmation_json
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  limit 1;

  if v_batch.id is null then
    raise exception 'pay_remittance_queue_commit_stage: pay batch % not found.', p_pay_batch_id;
  end if;

  if v_batch.execution_intent_json is not null and jsonb_typeof(v_batch.execution_intent_json) = 'object' then
    v_execution_intent_json := v_batch.execution_intent_json;
  else
    v_execution_intent_json := '{}'::jsonb;
  end if;

  if v_batch.settlement_confirmation_json is not null and jsonb_typeof(v_batch.settlement_confirmation_json) = 'object' then
    v_settlement_confirmation_json := v_batch.settlement_confirmation_json;
  else
    v_settlement_confirmation_json := '{}'::jsonb;
  end if;

  v_suppress_remittances := lower(btrim(coalesce(
    v_settlement_confirmation_json->>'suppress_remittances',
    v_execution_intent_json->>'suppress_remittances',
    'false'
  ))) in ('true','1','yes','y','on');

  v_operation_mode := (p_operation_id IS NOT NULL OR p_remittance_scope_ids IS NOT NULL);

  IF v_operation_mode THEN
    IF p_operation_id IS NULL THEN
      RAISE EXCEPTION 'pay_remittance_queue_commit_stage operation mode requires p_operation_id';
    END IF;
    IF p_remittance_scope_ids IS NULL OR jsonb_typeof(p_remittance_scope_ids) <> 'array' OR jsonb_array_length(p_remittance_scope_ids) = 0 THEN
      RAISE EXCEPTION 'pay_remittance_queue_commit_stage operation mode requires non-empty p_remittance_scope_ids';
    END IF;

    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'pay_remittance_queue_commit_stage: operation % not found', p_operation_id;
    END IF;

    IF v_operation_row.operation_type NOT IN ('REMITTANCE_QUEUE', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLEMENT') THEN
      RAISE EXCEPTION 'pay_remittance_queue_commit_stage: operation % is not remittance-capable', p_operation_id;
    END IF;

    IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
      RAISE EXCEPTION 'pay_remittance_queue_commit_stage: operation % is for pay batch %, not %', p_operation_id, v_operation_row.pay_batch_id, p_pay_batch_id;
    END IF;

    IF v_operation_row.actor_user_id IS NOT NULL AND v_operation_row.actor_user_id <> p_actor_user_id THEN
      RAISE EXCEPTION 'pay_remittance_queue_commit_stage: operation % belongs to a different actor', p_operation_id;
    END IF;

    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS remittance_scope_id
      FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    )
    SELECT COUNT(*)::integer
    INTO v_requested_scope_count
    FROM requested_scope;

    IF v_requested_scope_count <> jsonb_array_length(p_remittance_scope_ids) THEN
      RAISE EXCEPTION 'pay_remittance_queue_commit_stage operation mode received invalid or duplicate remittance scope ids';
    END IF;

    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS remittance_scope_id
      FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), selected_scope AS (
      SELECT scope_row.*
      FROM public.banking_pay_operation_remittance_scope AS scope_row
      JOIN requested_scope
        ON requested_scope.remittance_scope_id = scope_row.id
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
      FOR UPDATE OF scope_row
    )
    SELECT COUNT(*)::integer,
           COUNT(*) FILTER (WHERE selected_scope.status = 'QUEUED')::integer,
           COUNT(*) FILTER (WHERE selected_scope.status = 'SKIPPED')::integer,
           COUNT(*) FILTER (WHERE selected_scope.status = 'FAILED')::integer,
           COALESCE(jsonb_agg(to_jsonb(selected_scope.id::text) ORDER BY selected_scope.id::text), '[]'::jsonb)
    INTO v_matched_scope_count,
         v_already_queued_count,
         v_skipped_count,
         v_failed_count,
         v_operation_scope_ids
    FROM selected_scope;

    IF v_matched_scope_count <> v_requested_scope_count THEN
      RAISE EXCEPTION 'pay_remittance_queue_commit_stage operation mode one or more remittance scope ids do not belong to operation % and batch %', p_operation_id, p_pay_batch_id;
    END IF;

    IF v_suppress_remittances = true THEN
      WITH requested_scope AS (
        SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS remittance_scope_id
        FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
        WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ), skipped_scope AS (
        UPDATE public.banking_pay_operation_remittance_scope AS scope_update
        SET status = 'SKIPPED',
            payload_json = jsonb_strip_nulls(COALESCE(scope_update.payload_json, '{}'::jsonb) || jsonb_build_object(
              'skip_reason', 'SUPPRESSED_BY_EXECUTION_INTENT',
              'skipped_at_utc', now()::text
            )),
            updated_at_utc = now()
        FROM requested_scope
        WHERE scope_update.id = requested_scope.remittance_scope_id
          AND scope_update.operation_id = p_operation_id
          AND scope_update.pay_batch_id = p_pay_batch_id
          AND scope_update.status IN ('PENDING', 'FAILED')
        RETURNING scope_update.id
      ), selected_scope_after AS (
        SELECT scope_row.status
        FROM public.banking_pay_operation_remittance_scope AS scope_row
        JOIN requested_scope
          ON requested_scope.remittance_scope_id = scope_row.id
        WHERE scope_row.operation_id = p_operation_id
          AND scope_row.pay_batch_id = p_pay_batch_id
      )
      SELECT COUNT(*) FILTER (WHERE selected_scope_after.status = 'QUEUED')::integer,
             COUNT(*) FILTER (WHERE selected_scope_after.status = 'SKIPPED')::integer,
             COUNT(*) FILTER (WHERE selected_scope_after.status = 'FAILED')::integer
      INTO v_already_queued_count,
           v_skipped_count,
           v_failed_count
      FROM selected_scope_after;

      SELECT COUNT(*)::integer
      INTO v_remaining_count
      FROM public.banking_pay_operation_remittance_scope AS remaining_scope
      WHERE remaining_scope.operation_id = p_operation_id
        AND remaining_scope.pay_batch_id = p_pay_batch_id
        AND remaining_scope.status = 'PENDING';

      v_has_more := COALESCE(v_remaining_count, 0) > 0;

      UPDATE public.banking_pay_operations AS operation_update
      SET pay_batch_id = p_pay_batch_id,
          updated_at_utc = now()
      WHERE operation_update.id = p_operation_id
        AND operation_update.pay_batch_id IS NULL;

      RETURN jsonb_build_object(
        'ok', true,
        'operation_mode', true,
        'operation_id', p_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'trigger', coalesce(v_operation_row.input_json->>'trigger', CASE WHEN v_only_confirmed THEN 'ON_PAYMENT_CONFIRMED' ELSE 'ON_EXECUTION' END),
        'configured_timing', v_operation_row.input_json->>'configured_timing',
        'only_confirmed', v_only_confirmed,
        'trigger_status', 'SUPPRESSED_BY_EXECUTION_INTENT',
        'message_kind', 'REMITTANCE',
        'queued_count', 0,
        'reused_count', COALESCE(v_already_queued_count, 0),
        'skipped_count', COALESCE(v_skipped_count, 0),
        'failed_count', COALESCE(v_failed_count, 0),
        'remaining', COALESCE(v_remaining_count, 0),
        'has_more', v_has_more,
        'dispatch_required', false
      );
    END IF;

    DROP TABLE IF EXISTS pg_temp.tmp_operation_remittance_targets;
    CREATE TEMPORARY TABLE pg_temp.tmp_operation_remittance_targets AS
    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS remittance_scope_id
      FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    )
    SELECT
      scope_row.id AS remittance_scope_id,
      scope_row.status,
      scope_row.pay_batch_candidate_id,
      scope_row.candidate_id,
      scope_row.recipient_kind,
      scope_row.recipient_id,
      scope_row.remittance_type,
      scope_row.deterministic_outbox_key,
      scope_row.payload_json,
      scope_row.outbox_id,
      CASE
        WHEN upper(coalesce(scope_row.recipient_kind, '')) = 'CANDIDATE' THEN candidate_row.email
        WHEN upper(coalesce(scope_row.recipient_kind, '')) = 'UMBRELLA' THEN umbrella_row.remittance_email
        ELSE NULL::text
      END AS recipient_email,
      CASE
        WHEN upper(coalesce(scope_row.recipient_kind, '')) = 'CANDIDATE' THEN candidate_row.display_name
        WHEN upper(coalesce(scope_row.recipient_kind, '')) = 'UMBRELLA' THEN umbrella_row.name
        ELSE NULL::text
      END AS recipient_name
    FROM public.banking_pay_operation_remittance_scope AS scope_row
    JOIN requested_scope
      ON requested_scope.remittance_scope_id = scope_row.id
    LEFT JOIN public.candidates AS candidate_row
      ON upper(coalesce(scope_row.recipient_kind, '')) = 'CANDIDATE'
     AND candidate_row.id = scope_row.recipient_id
    LEFT JOIN public.umbrellas AS umbrella_row
      ON upper(coalesce(scope_row.recipient_kind, '')) = 'UMBRELLA'
     AND umbrella_row.id = scope_row.recipient_id
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id;

    WITH skipped_missing_recipient AS (
      UPDATE public.banking_pay_operation_remittance_scope AS scope_update
      SET status = 'SKIPPED',
          payload_json = jsonb_strip_nulls(COALESCE(scope_update.payload_json, '{}'::jsonb) || jsonb_build_object(
            'skip_reason', 'MISSING_REMITTANCE_RECIPIENT_EMAIL',
            'skipped_at_utc', now()::text
          )),
          updated_at_utc = now()
      FROM pg_temp.tmp_operation_remittance_targets AS target_row
      WHERE scope_update.id = target_row.remittance_scope_id
        AND scope_update.status IN ('PENDING', 'FAILED')
        AND NULLIF(BTRIM(COALESCE(target_row.recipient_email, '')), '') IS NULL
      RETURNING scope_update.id
    )
    SELECT COALESCE(v_skipped_count, 0) + COUNT(*)::integer
    INTO v_skipped_count
    FROM skipped_missing_recipient;

    BEGIN
      v_build_result := public.pay_remittance_build(
        p_pay_batch_id,
        v_scope,
        p_operation_id,
        p_remittance_scope_ids,
        NULL::integer,
        NULL::jsonb
      );
    EXCEPTION
      WHEN OTHERS THEN
        UPDATE public.banking_pay_operation_remittance_scope AS scope_update
        SET status = 'FAILED',
            payload_json = jsonb_strip_nulls(COALESCE(scope_update.payload_json, '{}'::jsonb) || jsonb_build_object(
              'failure_reason', 'REMITTANCE_BUILD_ERROR',
              'failure_message', LEFT(COALESCE(SQLERRM, 'pay_remittance_build failed'), 1000),
              'failed_at_utc', now()::text
            )),
            updated_at_utc = now()
        WHERE scope_update.operation_id = p_operation_id
          AND scope_update.pay_batch_id = p_pay_batch_id
          AND scope_update.id IN (
            SELECT (scope_element.value #>> '{}')::uuid
            FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
            WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          )
          AND scope_update.status IN ('PENDING', 'FAILED');
        RAISE;
    END;

    IF COALESCE((v_build_result->>'ok')::boolean, false) IS NOT TRUE THEN
      UPDATE public.banking_pay_operation_remittance_scope AS scope_update
      SET status = 'FAILED',
          payload_json = jsonb_strip_nulls(COALESCE(scope_update.payload_json, '{}'::jsonb) || jsonb_build_object(
            'failure_reason', 'REMITTANCE_BUILD_NOT_OK',
            'failure_message', LEFT(COALESCE(NULLIF(BTRIM(COALESCE(v_build_result->>'error', '')), ''), 'pay_remittance_build returned not ok'), 1000),
            'failed_at_utc', now()::text
          )),
          updated_at_utc = now()
      WHERE scope_update.operation_id = p_operation_id
        AND scope_update.pay_batch_id = p_pay_batch_id
        AND scope_update.id IN (
          SELECT (scope_element.value #>> '{}')::uuid
          FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
          WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        )
        AND scope_update.status IN ('PENDING', 'FAILED');
      RAISE EXCEPTION 'pay_remittance_queue_commit_stage: pay_remittance_build returned not ok';
    END IF;

    v_build_jobs := CASE
      WHEN jsonb_typeof(v_build_result->'jobs') = 'array' THEN COALESCE(v_build_result->'jobs', '[]'::jsonb)
      ELSE '[]'::jsonb
    END;

    WITH valid_targets AS (
      SELECT target_row.*
      FROM pg_temp.tmp_operation_remittance_targets AS target_row
      WHERE target_row.status IN ('PENDING', 'FAILED')
        AND NULLIF(BTRIM(COALESCE(target_row.recipient_email, '')), '') IS NOT NULL
    ), upserted_outbox AS (
      INSERT INTO public.mail_outbox AS mail_insert (
        type,
        "to",
        cc,
        subject,
        body_html,
        body_text,
        attachments,
        status,
        created_at_utc,
        created_by,
        reference,
        recipient_kind,
        recipient_id,
        context_kind,
        context_id,
        email_type,
        importance,
        scheduled_for_utc,
        next_attempt_at_utc,
        payment_scope_json,
        deterministic_outbox_key
      )
      SELECT
        'REMITTANCE',
        valid_targets.recipient_email,
        NULL::text,
        CASE WHEN upper(coalesce(valid_targets.remittance_type, '')) = 'UMBRELLA_REMITTANCE'
             THEN 'Umbrella remittance - ' || COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), p_pay_batch_id::text)
             ELSE 'Payment remittance - ' || COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), p_pay_batch_id::text)
        END,
        COALESCE((
          SELECT
            '<p>Remittance advice for batch <strong>' || replace(replace(replace(COALESCE(NULLIF(BTRIM(COALESCE(render_job.job_json->>'bulk_reference', '')), ''), NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), p_pay_batch_id::text), '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '</strong></p>' ||
            '<p><strong>Payment date:</strong> ' || replace(replace(replace(COALESCE(NULLIF(BTRIM(COALESCE(render_job.job_json->>'pay_date', '')), ''), CASE WHEN COALESCE(v_batch.authoritative_payment_date, v_batch.pay_date) IS NULL THEN NULL ELSE COALESCE(v_batch.authoritative_payment_date, v_batch.pay_date)::text END, ''), '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '<br>' ||
            '<strong>Recipient:</strong> ' || replace(replace(replace(COALESCE(NULLIF(BTRIM(COALESCE(render_job.job_json #>> '{recipient,name}', '')), ''), NULLIF(BTRIM(COALESCE(render_job.job_json #>> '{recipient,display_name}', '')), ''), valid_targets.recipient_name, 'Recipient'), '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || ' (' || replace(replace(replace(valid_targets.recipient_email, '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || ')<br>' ||
            '<strong>Candidate:</strong> ' || replace(replace(replace(COALESCE(NULLIF(BTRIM(COALESCE(render_job.job_json #>> '{candidate,display_name}', '')), ''), NULLIF(BTRIM(COALESCE(render_job.job_json #>> '{candidate,candidate_display_name}', '')), ''), valid_targets.recipient_name, 'Candidate'), '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '<br>' ||
            '<strong>Amount:</strong> ' || replace(replace(replace(COALESCE(NULLIF(BTRIM(COALESCE(render_job.job_json #>> '{summary,currency}', '')), ''), 'GBP'), '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || ' ' || COALESCE(NULLIF(BTRIM(COALESCE(render_job.job_json #>> '{summary,total_amount}', render_job.job_json #>> '{summary,payment_amount}', valid_targets.payload_json->>'total_amount', '')), ''), '0') ||
            COALESCE((
              SELECT '<br><strong>Provider / payment reference:</strong> ' || replace(replace(replace(STRING_AGG(DISTINCT provider_ref.provider_ref_text, ', '), '&', '&amp;'), '<', '&lt;'), '>', '&gt;')
              FROM (
                SELECT NULLIF(BTRIM(COALESCE(transfer_rows.transfer_json->>'provider_transaction_id', transfer_rows.transfer_json->>'rail_tx_id', transfer_rows.transfer_json->>'payment_reference', '')), '') AS provider_ref_text
                FROM jsonb_array_elements(COALESCE(render_job.job_json->'transfers', '[]'::jsonb)) AS transfer_rows(transfer_json)
              ) AS provider_ref
              WHERE provider_ref.provider_ref_text IS NOT NULL
            ), '') ||
            '</p><p><strong>Breakdown</strong></p><ul>' ||
            COALESCE((
              SELECT STRING_AGG('<li>' || replace(replace(replace(line_text.line_value, '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '</li>', '' ORDER BY line_text.line_order)
              FROM (
                SELECT line_rows.line_order,
                       concat_ws(' - ',
                         NULLIF(BTRIM(COALESCE(line_rows.line_json->>'description', line_rows.line_json->>'line_label', line_rows.line_json->>'line_kind', line_rows.line_json->>'item_type', 'Line')), ''),
                         'Ex VAT ' || COALESCE(line_rows.line_json->>'total_ex_vat', line_rows.line_json->>'signed_amount_ex_vat', '0'),
                         'VAT ' || COALESCE(line_rows.line_json->>'total_vat', line_rows.line_json->>'signed_amount_vat', '0'),
                         'Inc VAT ' || COALESCE(line_rows.line_json->>'total_inc_vat', line_rows.line_json->>'signed_amount_inc_vat', '0')
                       ) AS line_value
                FROM jsonb_array_elements(COALESCE(render_job.job_json->'lines', render_job.job_json->'non_timesheet_lines', '[]'::jsonb)) WITH ORDINALITY AS line_rows(line_json, line_order)
              ) AS line_text
            ), '<li>No individual remittance lines were supplied for this payment.</li>') || '</ul>'
          FROM (
            SELECT COALESCE(build_job.value, valid_targets.payload_json, '{}'::jsonb) AS job_json
            FROM jsonb_array_elements(COALESCE(v_build_jobs, '[]'::jsonb)) AS build_job(value)
            WHERE build_job.value->>'remittance_scope_id' = valid_targets.remittance_scope_id::text
               OR build_job.value->>'deterministic_outbox_key' = valid_targets.deterministic_outbox_key
            ORDER BY CASE WHEN build_job.value->>'remittance_scope_id' = valid_targets.remittance_scope_id::text THEN 0 ELSE 1 END
            LIMIT 1
          ) AS render_job
        ), '<p>Remittance advice for batch <strong>' || COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), p_pay_batch_id::text) || '</strong></p>'),
        COALESCE((
          SELECT
            'Remittance advice' || E'\n' ||
            'Batch: ' || COALESCE(NULLIF(BTRIM(COALESCE(render_job.job_json->>'bulk_reference', '')), ''), NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), p_pay_batch_id::text) || E'\n' ||
            'Payment date: ' || COALESCE(NULLIF(BTRIM(COALESCE(render_job.job_json->>'pay_date', '')), ''), CASE WHEN COALESCE(v_batch.authoritative_payment_date, v_batch.pay_date) IS NULL THEN NULL ELSE COALESCE(v_batch.authoritative_payment_date, v_batch.pay_date)::text END, '') || E'\n' ||
            'Recipient: ' || COALESCE(NULLIF(BTRIM(COALESCE(render_job.job_json #>> '{recipient,name}', '')), ''), NULLIF(BTRIM(COALESCE(render_job.job_json #>> '{recipient,display_name}', '')), ''), valid_targets.recipient_name, 'Recipient') || ' <' || valid_targets.recipient_email || '>' || E'\n' ||
            'Candidate: ' || COALESCE(NULLIF(BTRIM(COALESCE(render_job.job_json #>> '{candidate,display_name}', '')), ''), NULLIF(BTRIM(COALESCE(render_job.job_json #>> '{candidate,candidate_display_name}', '')), ''), valid_targets.recipient_name, 'Candidate') || E'\n' ||
            'Amount: ' || COALESCE(NULLIF(BTRIM(COALESCE(render_job.job_json #>> '{summary,currency}', '')), ''), 'GBP') || ' ' || COALESCE(NULLIF(BTRIM(COALESCE(render_job.job_json #>> '{summary,total_amount}', render_job.job_json #>> '{summary,payment_amount}', valid_targets.payload_json->>'total_amount', '')), ''), '0') || E'\n' ||
            COALESCE((
              SELECT 'Provider / payment reference: ' || STRING_AGG(DISTINCT provider_ref.provider_ref_text, ', ') || E'\n'
              FROM (
                SELECT NULLIF(BTRIM(COALESCE(transfer_rows.transfer_json->>'provider_transaction_id', transfer_rows.transfer_json->>'rail_tx_id', transfer_rows.transfer_json->>'payment_reference', '')), '') AS provider_ref_text
                FROM jsonb_array_elements(COALESCE(render_job.job_json->'transfers', '[]'::jsonb)) AS transfer_rows(transfer_json)
              ) AS provider_ref
              WHERE provider_ref.provider_ref_text IS NOT NULL
            ), '') ||
            E'\nBreakdown\n' || COALESCE((
              SELECT STRING_AGG(line_text.line_value, E'\n' ORDER BY line_text.line_order)
              FROM (
                SELECT line_rows.line_order,
                       concat_ws(' - ',
                         NULLIF(BTRIM(COALESCE(line_rows.line_json->>'description', line_rows.line_json->>'line_label', line_rows.line_json->>'line_kind', line_rows.line_json->>'item_type', 'Line')), ''),
                         'Ex VAT ' || COALESCE(line_rows.line_json->>'total_ex_vat', line_rows.line_json->>'signed_amount_ex_vat', '0'),
                         'VAT ' || COALESCE(line_rows.line_json->>'total_vat', line_rows.line_json->>'signed_amount_vat', '0'),
                         'Inc VAT ' || COALESCE(line_rows.line_json->>'total_inc_vat', line_rows.line_json->>'signed_amount_inc_vat', '0')
                       ) AS line_value
                FROM jsonb_array_elements(COALESCE(render_job.job_json->'lines', render_job.job_json->'non_timesheet_lines', '[]'::jsonb)) WITH ORDINALITY AS line_rows(line_json, line_order)
              ) AS line_text
            ), 'No individual remittance lines were supplied for this payment.')
          FROM (
            SELECT COALESCE(build_job.value, valid_targets.payload_json, '{}'::jsonb) AS job_json
            FROM jsonb_array_elements(COALESCE(v_build_jobs, '[]'::jsonb)) AS build_job(value)
            WHERE build_job.value->>'remittance_scope_id' = valid_targets.remittance_scope_id::text
               OR build_job.value->>'deterministic_outbox_key' = valid_targets.deterministic_outbox_key
            ORDER BY CASE WHEN build_job.value->>'remittance_scope_id' = valid_targets.remittance_scope_id::text THEN 0 ELSE 1 END
            LIMIT 1
          ) AS render_job
        ), 'Remittance advice for batch ' || COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), p_pay_batch_id::text)),
        '[]'::jsonb,
        'QUEUED'::public.mail_status_enum,
        now(),
        p_actor_user_id,
        valid_targets.deterministic_outbox_key,
        lower(coalesce(valid_targets.recipient_kind, '')),
        valid_targets.recipient_id,
        'pay_batches',
        p_pay_batch_id,
        'html',
        'Normal',
        now(),
        now(),
        jsonb_strip_nulls(COALESCE(valid_targets.payload_json, '{}'::jsonb) || COALESCE((
          SELECT build_job.value
          FROM jsonb_array_elements(COALESCE(v_build_jobs, '[]'::jsonb)) AS build_job(value)
          WHERE build_job.value->>'remittance_scope_id' = valid_targets.remittance_scope_id::text
             OR build_job.value->>'deterministic_outbox_key' = valid_targets.deterministic_outbox_key
          ORDER BY CASE WHEN build_job.value->>'remittance_scope_id' = valid_targets.remittance_scope_id::text THEN 0 ELSE 1 END
          LIMIT 1
        ), '{}'::jsonb) || jsonb_build_object(
          'pay_batch_id', p_pay_batch_id::text,
          'operation_id', p_operation_id::text,
          'remittance_scope_id', valid_targets.remittance_scope_id::text,
          'deterministic_outbox_key', valid_targets.deterministic_outbox_key,
          'remittance_type', valid_targets.remittance_type,
          'recipient_kind', valid_targets.recipient_kind,
          'recipient_id', CASE WHEN valid_targets.recipient_id IS NULL THEN NULL ELSE valid_targets.recipient_id::text END,
          'render_status', 'RENDERED',
          'body_rendered', true,
          'payload_hash', md5((COALESCE(valid_targets.payload_json, '{}'::jsonb) || jsonb_build_object(
            'pay_batch_id', p_pay_batch_id::text,
            'operation_id', p_operation_id::text,
            'remittance_scope_id', valid_targets.remittance_scope_id::text,
            'deterministic_outbox_key', valid_targets.deterministic_outbox_key,
            'remittance_type', valid_targets.remittance_type
          ))::text),
          'attachment_count', 0,
          'render_version', 2
        )),
        valid_targets.deterministic_outbox_key
      FROM valid_targets
      ON CONFLICT (deterministic_outbox_key)
      DO UPDATE
      SET status = CASE WHEN mail_insert.status::text = 'FAILED' THEN 'QUEUED'::public.mail_status_enum ELSE mail_insert.status END,
          last_error = CASE WHEN mail_insert.status::text = 'FAILED' THEN NULL ELSE mail_insert.last_error END,
          failed_at = CASE WHEN mail_insert.status::text = 'FAILED' THEN NULL ELSE mail_insert.failed_at END,
          next_attempt_at_utc = CASE WHEN mail_insert.status::text = 'FAILED' THEN now() ELSE mail_insert.next_attempt_at_utc END,
          context_kind = CASE WHEN mail_insert.status::text = 'SENT' THEN mail_insert.context_kind ELSE EXCLUDED.context_kind END,
          context_id = CASE WHEN mail_insert.status::text = 'SENT' THEN mail_insert.context_id ELSE EXCLUDED.context_id END,
          body_html = CASE WHEN mail_insert.status::text = 'SENT' THEN mail_insert.body_html ELSE EXCLUDED.body_html END,
          body_text = CASE WHEN mail_insert.status::text = 'SENT' THEN mail_insert.body_text ELSE EXCLUDED.body_text END,
          attachments = CASE WHEN mail_insert.status::text = 'SENT' THEN mail_insert.attachments ELSE EXCLUDED.attachments END,
          recipient_kind = CASE WHEN mail_insert.status::text = 'SENT' THEN mail_insert.recipient_kind ELSE EXCLUDED.recipient_kind END,
          recipient_id = CASE WHEN mail_insert.status::text = 'SENT' THEN mail_insert.recipient_id ELSE EXCLUDED.recipient_id END,
          payment_scope_json = CASE WHEN mail_insert.status::text = 'SENT' THEN mail_insert.payment_scope_json ELSE EXCLUDED.payment_scope_json END
      RETURNING mail_insert.id,
                mail_insert.deterministic_outbox_key,
                mail_insert.status::text AS outbox_status,
                NULLIF(mail_insert.payment_scope_json->>'payload_hash', '') AS payload_hash,
                COALESCE(NULLIF(mail_insert.payment_scope_json->>'render_status', ''), 'RENDERED') AS render_status,
                COALESCE(NULLIF(mail_insert.payment_scope_json->>'attachment_count', '')::integer, 0) AS attachment_count,
                (xmax = 0) AS was_inserted
    ), updated_scope AS (
      UPDATE public.banking_pay_operation_remittance_scope AS scope_update
      SET status = 'QUEUED',
          outbox_id = upserted_outbox.id,
          payload_json = jsonb_strip_nulls(COALESCE(scope_update.payload_json, '{}'::jsonb) || jsonb_build_object(
            'outbox_id', upserted_outbox.id::text,
            'render_status', upserted_outbox.render_status,
            'payload_hash', upserted_outbox.payload_hash,
            'attachment_count', upserted_outbox.attachment_count,
            'queued_at_utc', now()::text
          )),
          updated_at_utc = now()
      FROM upserted_outbox
      WHERE scope_update.operation_id = p_operation_id
        AND scope_update.pay_batch_id = p_pay_batch_id
        AND scope_update.deterministic_outbox_key = upserted_outbox.deterministic_outbox_key
        AND scope_update.status IN ('PENDING', 'FAILED')
      RETURNING scope_update.id,
                scope_update.deterministic_outbox_key,
                scope_update.outbox_id,
                upserted_outbox.was_inserted,
                upserted_outbox.outbox_status,
                upserted_outbox.payload_hash,
                upserted_outbox.render_status,
                upserted_outbox.attachment_count
    )
    SELECT COUNT(*) FILTER (WHERE updated_scope.was_inserted)::integer,
           COUNT(*) FILTER (WHERE updated_scope.was_inserted IS NOT TRUE)::integer,
           COALESCE(jsonb_agg(jsonb_build_object(
             'remittance_scope_id', updated_scope.id::text,
             'deterministic_outbox_key', updated_scope.deterministic_outbox_key,
             'outbox_id', updated_scope.outbox_id::text,
             'outbox_status', updated_scope.outbox_status,
             'queued', true,
             'reused', (updated_scope.was_inserted IS NOT TRUE),
             'render_status', updated_scope.render_status,
             'payload_hash', updated_scope.payload_hash,
             'attachment_count', updated_scope.attachment_count
           ) ORDER BY updated_scope.id::text), '[]'::jsonb)
    INTO v_inserted_outbox_count,
         v_reused_outbox_count,
         v_operation_job_results
    FROM updated_scope;

    SELECT COUNT(*)::integer
    INTO v_remaining_count
    FROM public.banking_pay_operation_remittance_scope AS remaining_scope
    WHERE remaining_scope.operation_id = p_operation_id
      AND remaining_scope.pay_batch_id = p_pay_batch_id
      AND remaining_scope.status = 'PENDING';

    SELECT COUNT(*)::integer
    INTO v_failed_count
    FROM public.banking_pay_operation_remittance_scope AS failed_scope
    WHERE failed_scope.operation_id = p_operation_id
      AND failed_scope.pay_batch_id = p_pay_batch_id
      AND failed_scope.id IN (
        SELECT (scope_element.value #>> '{}')::uuid
        FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
        WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      )
      AND failed_scope.status = 'FAILED';

    v_has_more := COALESCE(v_remaining_count, 0) > 0;

    UPDATE public.banking_pay_operations AS operation_update
    SET pay_batch_id = p_pay_batch_id,
        updated_at_utc = now()
    WHERE operation_update.id = p_operation_id
      AND operation_update.pay_batch_id IS NULL;

    RETURN jsonb_build_object(
      'ok', true,
      'operation_mode', true,
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'trigger', coalesce(v_operation_row.input_json->>'trigger', CASE WHEN v_only_confirmed THEN 'ON_PAYMENT_CONFIRMED' ELSE 'ON_EXECUTION' END),
      'configured_timing', v_operation_row.input_json->>'configured_timing',
      'only_confirmed', v_only_confirmed,
      'trigger_status', CASE WHEN COALESCE(v_inserted_outbox_count, 0) + COALESCE(v_reused_outbox_count, 0) + COALESCE(v_already_queued_count, 0) > 0 THEN 'REMITTANCE_QUEUE_CHUNK_PROCESSED' ELSE 'NO_QUEUEABLE_REMITTANCE_SCOPE' END,
      'message_kind', 'REMITTANCE',
      'recipient_count', COALESCE(v_inserted_outbox_count, 0) + COALESCE(v_reused_outbox_count, 0) + COALESCE(v_already_queued_count, 0),
      'queued_count', COALESCE(v_inserted_outbox_count, 0),
      'reused_count', COALESCE(v_reused_outbox_count, 0) + COALESCE(v_already_queued_count, 0),
      'skipped_count', COALESCE(v_skipped_count, 0),
      'failed_count', COALESCE(v_failed_count, 0),
      'remaining', COALESCE(v_remaining_count, 0),
      'has_more', v_has_more,
      'dispatch_required', (COALESCE(v_inserted_outbox_count, 0) + COALESCE(v_reused_outbox_count, 0) + COALESCE(v_already_queued_count, 0) > 0),
      'outbox_ids', COALESCE((
        SELECT jsonb_agg(job_result.value->>'outbox_id' ORDER BY job_result.value->>'outbox_id')
        FROM jsonb_array_elements(COALESCE(v_operation_job_results, '[]'::jsonb)) AS job_result(value)
        WHERE NULLIF(BTRIM(COALESCE(job_result.value->>'outbox_id', '')), '') IS NOT NULL
      ), '[]'::jsonb),
      'deterministic_outbox_keys', COALESCE((
        SELECT jsonb_agg(job_result.value->>'deterministic_outbox_key' ORDER BY job_result.value->>'deterministic_outbox_key')
        FROM jsonb_array_elements(COALESCE(v_operation_job_results, '[]'::jsonb)) AS job_result(value)
        WHERE NULLIF(BTRIM(COALESCE(job_result.value->>'deterministic_outbox_key', '')), '') IS NOT NULL
      ), '[]'::jsonb),
      'attachment_count', COALESCE((
        SELECT SUM(COALESCE(NULLIF(BTRIM(COALESCE(job_result.value->>'attachment_count', '')), '')::integer, 0))::integer
        FROM jsonb_array_elements(COALESCE(v_operation_job_results, '[]'::jsonb)) AS job_result(value)
      ), 0),
      'render_status', CASE
        WHEN COALESCE(v_inserted_outbox_count, 0) + COALESCE(v_reused_outbox_count, 0) > 0 THEN 'RENDERED'
        ELSE 'NO_RENDERED_ROWS'
      END,
      'payload_hashes', COALESCE((
        SELECT jsonb_agg(job_result.value->>'payload_hash' ORDER BY job_result.value->>'payload_hash')
        FROM jsonb_array_elements(COALESCE(v_operation_job_results, '[]'::jsonb)) AS job_result(value)
        WHERE NULLIF(BTRIM(COALESCE(job_result.value->>'payload_hash', '')), '') IS NOT NULL
      ), '[]'::jsonb),
      'body_rendered', (COALESCE(v_inserted_outbox_count, 0) + COALESCE(v_reused_outbox_count, 0) > 0),
      'jobs', COALESCE(v_operation_job_results, '[]'::jsonb)
    );
  END IF;

  SELECT COUNT(*)::integer
  INTO v_legacy_scope_count
  FROM public.pay_batch_candidates AS legacy_candidate_count
  WHERE legacy_candidate_count.pay_batch_id = p_pay_batch_id
    AND legacy_candidate_count.remittance_sent_at_utc IS NULL;

  IF COALESCE(v_legacy_scope_count, 0) > 250 THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_REMITTANCE_QUEUE_COMMIT_STAGE_OPERATION_REQUIRED',
      'code', 'REMITTANCE_OPERATION_REQUIRED',
      'message', 'pay_remittance_queue_commit_stage legacy mode is limited to small batches; use the scalable remittance operation for this payment batch.',
      'pay_batch_id', p_pay_batch_id::text,
      'candidate_count', v_legacy_scope_count,
      'legacy_safe_threshold', 250
    )::text;
  END IF;

  if v_suppress_remittances = true then
    return jsonb_build_object(
      'ok', true,
      'trigger_status', 'SUPPRESSED_BY_EXECUTION_INTENT',
      'error', null,
      'message_kind', 'REMITTANCE',
      'automatic_commit_stage', true,
      'dispatch_required', false,
      'suppressed_by_execution_intent', true,
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end,
      'scope', v_scope,
      'candidate_count_targeted', 0,
      'candidate_count_ready', 0,
      'candidate_count_without_jobs', 0,
      'job_count', 0,
      'candidate_results', '[]'::jsonb,
      'job_results', '[]'::jsonb,
      'jobs', '[]'::jsonb
    );
  end if;

  drop table if exists pg_temp.tmp_commit_stage_excluded_finance_cases;
  create temporary table pg_temp.tmp_commit_stage_excluded_finance_cases(
    candidate_id uuid not null,
    finance_case_id uuid not null,
    primary key (candidate_id, finance_case_id)
  ) on commit drop;

  drop table if exists pg_temp.tmp_commit_stage_excluded_transfers;
  create temporary table pg_temp.tmp_commit_stage_excluded_transfers(
    transfer_id uuid primary key,
    candidate_id uuid not null,
    umbrella_id uuid null
  ) on commit drop;

  insert into pg_temp.tmp_commit_stage_excluded_finance_cases(
    candidate_id,
    finance_case_id
  )
  select distinct
    pbc.candidate_id,
    pbi.finance_case_id
  from public.pay_batch_candidates pbc
  join public.pay_batch_items pbi
    on pbi.pay_batch_candidate_id = pbc.id
  where pbc.pay_batch_id = p_pay_batch_id
    and pbc.remittance_sent_at_utc is null
    and coalesce(pbi.is_voided, false) = false
    and not exists (
      select 1
      from public.pay_payment_correction_items as ppc_excluded_finance_case_correction
      where ppc_excluded_finance_case_correction.pay_batch_item_id = pbi.id
        and ppc_excluded_finance_case_correction.status = 'APPLIED'
        and ppc_excluded_finance_case_correction.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
    )
    and pbi.finance_case_id is not null
    and pbi.item_type in ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
    and jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
    and upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
    and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) in ('true', '1', 'yes', 'y', 'on');

  insert into pg_temp.tmp_commit_stage_excluded_transfers(
    transfer_id,
    candidate_id,
    umbrella_id
  )
  select distinct
    pbi.pay_bank_transfer_id,
    pbc.candidate_id,
    pbi.umbrella_id
  from public.pay_batch_candidates pbc
  join public.pay_batch_items pbi
    on pbi.pay_batch_candidate_id = pbc.id
  where pbc.pay_batch_id = p_pay_batch_id
    and pbc.remittance_sent_at_utc is null
    and coalesce(pbi.is_voided, false) = false
    and not exists (
      select 1
      from public.pay_payment_correction_items as ppc_excluded_transfer_correction
      where ppc_excluded_transfer_correction.pay_batch_item_id = pbi.id
        and ppc_excluded_transfer_correction.status = 'APPLIED'
        and ppc_excluded_transfer_correction.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
    )
    and pbi.pay_bank_transfer_id is not null
    and pbi.item_type in ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
    and jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
    and upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
    and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) in ('true', '1', 'yes', 'y', 'on');

  drop table if exists pg_temp.tmp_commit_stage_target_candidates;
  create temporary table pg_temp.tmp_commit_stage_target_candidates(
    pay_batch_candidate_id uuid primary key,
    candidate_id uuid not null,
    candidate_display_name text null,
    candidate_tms_ref text null
  ) on commit drop;

  drop table if exists pg_temp.tmp_commit_stage_confirmed_items;
  create temporary table pg_temp.tmp_commit_stage_confirmed_items(
    pay_batch_item_id uuid primary key,
    pay_batch_candidate_id uuid not null,
    candidate_id uuid not null,
    pay_bank_transfer_id uuid null,
    umbrella_id uuid null,
    pay_channel text not null,
    item_type text not null,
    timesheet_id uuid null,
    finance_case_id uuid null,
    manual_adjustment_carry_forward_id uuid null,
    amount_inc_vat numeric null,
    transfer_group_key text null
  ) on commit drop;

  insert into pg_temp.tmp_commit_stage_confirmed_items(
    pay_batch_item_id,
    pay_batch_candidate_id,
    candidate_id,
    pay_bank_transfer_id,
    umbrella_id,
    pay_channel,
    item_type,
    timesheet_id,
    finance_case_id,
    manual_adjustment_carry_forward_id,
    amount_inc_vat,
    transfer_group_key
  )
  select distinct
    pbi.id,
    pbc.id,
    pbc.candidate_id,
    pbi.pay_bank_transfer_id,
    pbi.umbrella_id,
    upper(coalesce(pbi.pay_channel, '')),
    pbi.item_type,
    pbi.timesheet_id,
    pbi.finance_case_id,
    CASE
      WHEN NULLIF(BTRIM(COALESCE(pbi.source_ref, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN split_part(NULLIF(BTRIM(COALESCE(pbi.source_ref, '')), ''), ':', 2)::uuid
      WHEN NULLIF(BTRIM(COALESCE(pbi.operation_source_key, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN split_part(NULLIF(BTRIM(COALESCE(pbi.operation_source_key, '')), ''), ':', 2)::uuid
      WHEN NULLIF(BTRIM(COALESCE(pbi.frozen_source_basis_json->>'manual_adjustment_carry_forward_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN NULLIF(BTRIM(COALESCE(pbi.frozen_source_basis_json->>'manual_adjustment_carry_forward_id', '')), '')::uuid
      WHEN NULLIF(BTRIM(COALESCE(pbi.frozen_component_snapshot_json->>'manual_adjustment_carry_forward_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN NULLIF(BTRIM(COALESCE(pbi.frozen_component_snapshot_json->>'manual_adjustment_carry_forward_id', '')), '')::uuid
      ELSE NULL::uuid
    END AS manual_adjustment_carry_forward_id,
    pbi.amount_inc_vat,
    pbt_confirmed.transfer_group_key
  from public.pay_batch_candidates as pbc
  join public.pay_batch_items as pbi
    on pbi.pay_batch_candidate_id = pbc.id
  left join public.pay_bank_transfers as pbt_confirmed
    on pbt_confirmed.id = pbi.pay_bank_transfer_id
   and pbt_confirmed.pay_batch_id = p_pay_batch_id
  where pbc.pay_batch_id = p_pay_batch_id
    and (pbc.remittance_sent_at_utc is null or v_only_confirmed)
    and coalesce(pbi.is_voided, false) = false
    and pbi.item_type <> 'DEBT_CREATED'
    and not exists (
      select 1
      from public.pay_payment_correction_items as ppc_confirmed_scope_correction
      where ppc_confirmed_scope_correction.pay_batch_item_id = pbi.id
        and ppc_confirmed_scope_correction.status = 'APPLIED'
        and ppc_confirmed_scope_correction.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
    )
    and (
      (
        (v_scope = 'ALL' or v_scope = 'UMBRELLA')
        and upper(coalesce(pbi.pay_channel, '')) = 'UMBRELLA'
        and not (
          pbi.finance_case_id is not null
          and pbi.item_type in ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
          and jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
          and upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
          and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) in ('true', '1', 'yes', 'y', 'on')
        )
      )
      or (
        (v_scope = 'ALL' or v_scope = 'PAYE')
        and upper(coalesce(pbi.pay_channel, '')) = 'PAYE'
      )
    )
    and (
      v_only_confirmed = false
      or (
        (
          pbi.pay_bank_transfer_id is not null
          and exists (
            select 1
            from public._pay_rail_state_money_movement_classify(
              pbt_confirmed.status,
              pbt_confirmed.rail_state,
              '{}'::jsonb,
              coalesce(pbt_confirmed.rail_meta_json, '{}'::jsonb)
            ) as movement_classification
            where coalesce(movement_classification.is_final_money_moved, false) = true
          )
          and not exists (
            select 1
            from public.mail_outbox as already_scoped_remittance
            where already_scoped_remittance.status::text in ('QUEUED','SENT')
              and coalesce(already_scoped_remittance.payment_scope_json->>'pay_batch_id', '') = p_pay_batch_id::text
              and exists (
                select 1
                from jsonb_array_elements_text(coalesce(already_scoped_remittance.payment_scope_json->'pay_bank_transfer_ids', '[]'::jsonb)) as already_transfer_ids(transfer_id_text)
                where already_transfer_ids.transfer_id_text = pbi.pay_bank_transfer_id::text
              )
          )
        )
        or (
          pbi.pay_bank_transfer_id is null
          and pbc.remittance_sent_at_utc is null
          and (
            upper(btrim(coalesce(pbc.settlement_status, ''))) = 'SETTLED'
            or pbc.settled_at_utc is not null
          )
        )
      )
    );

  insert into pg_temp.tmp_commit_stage_excluded_transfers(
    transfer_id,
    candidate_id,
    umbrella_id
  )
  select distinct
    pbi_unconfirmed_scope.pay_bank_transfer_id,
    pbc_unconfirmed_scope.candidate_id,
    pbi_unconfirmed_scope.umbrella_id
  from public.pay_batch_candidates as pbc_unconfirmed_scope
  join public.pay_batch_items as pbi_unconfirmed_scope
    on pbi_unconfirmed_scope.pay_batch_candidate_id = pbc_unconfirmed_scope.id
  where pbc_unconfirmed_scope.pay_batch_id = p_pay_batch_id
    and v_only_confirmed
    and pbi_unconfirmed_scope.pay_bank_transfer_id is not null
    and coalesce(pbi_unconfirmed_scope.is_voided, false) = false
    and pbi_unconfirmed_scope.item_type <> 'DEBT_CREATED'
    and not exists (
      select 1
      from public.pay_payment_correction_items as ppc_unconfirmed_scope_correction
      where ppc_unconfirmed_scope_correction.pay_batch_item_id = pbi_unconfirmed_scope.id
        and ppc_unconfirmed_scope_correction.status = 'APPLIED'
        and ppc_unconfirmed_scope_correction.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
    )
    and (
      (
        (v_scope = 'ALL' or v_scope = 'UMBRELLA')
        and upper(coalesce(pbi_unconfirmed_scope.pay_channel, '')) = 'UMBRELLA'
        and not (
          pbi_unconfirmed_scope.finance_case_id is not null
          and pbi_unconfirmed_scope.item_type in ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
          and jsonb_typeof(pbi_unconfirmed_scope.payout_instruction_snapshot_json) = 'object'
          and upper(coalesce(pbi_unconfirmed_scope.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
          and lower(btrim(coalesce(pbi_unconfirmed_scope.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) in ('true', '1', 'yes', 'y', 'on')
        )
      )
      or (
        (v_scope = 'ALL' or v_scope = 'PAYE')
        and upper(coalesce(pbi_unconfirmed_scope.pay_channel, '')) = 'PAYE'
      )
    )
    and not exists (
      select 1
      from pg_temp.tmp_commit_stage_confirmed_items as confirmed_scope_item
      where confirmed_scope_item.pay_batch_item_id = pbi_unconfirmed_scope.id
    )
  on conflict (transfer_id) do nothing;

  insert into pg_temp.tmp_commit_stage_target_candidates(
    pay_batch_candidate_id,
    candidate_id,
    candidate_display_name,
    candidate_tms_ref
  )
  select distinct
    pbc.id,
    pbc.candidate_id,
    pbc.candidate_display_name,
    pbc.candidate_tms_ref
  from public.pay_batch_candidates as pbc
  where pbc.pay_batch_id = p_pay_batch_id
    and (pbc.remittance_sent_at_utc is null or v_only_confirmed)
    and exists (
      select 1
      from pg_temp.tmp_commit_stage_confirmed_items as confirmed_target_item
      where confirmed_target_item.pay_batch_candidate_id = pbc.id
    );

  select count(*)::int
  into v_target_candidate_count
  from pg_temp.tmp_commit_stage_target_candidates tc;

  if v_target_candidate_count = 0 then
    return jsonb_build_object(
      'ok', true,
      'trigger_status', 'NO_ELIGIBLE_UNSENT_CANDIDATES',
      'error', null,
      'message_kind', 'REMITTANCE',
      'automatic_commit_stage', true,
      'dispatch_required', false,
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end,
      'scope', v_scope,
      'pay_date', case when coalesce(v_batch.authoritative_payment_date, v_batch.pay_date) is null then null else coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)::text end,
      'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
      'authoritative_payment_date_source', v_batch.authoritative_payment_date_source,
      'bulk_reference', v_batch.bulk_reference,
      'candidate_count_targeted', 0,
      'candidate_count_ready', 0,
      'candidate_count_without_jobs', 0,
      'job_count', 0,
      'candidate_results', '[]'::jsonb,
      'job_results', '[]'::jsonb,
      'jobs', '[]'::jsonb
    );
  end if;

  begin
    v_build_result := public.pay_remittance_build(p_pay_batch_id, v_scope);
  exception when others then
    return jsonb_build_object(
      'ok', false,
      'trigger_status', 'REMITTANCE_BUILD_ERROR',
      'error', left(coalesce(SQLERRM, 'pay_remittance_build failed'), 1000),
      'message_kind', 'REMITTANCE',
      'automatic_commit_stage', true,
      'dispatch_required', false,
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end,
      'scope', v_scope,
      'candidate_count_targeted', v_target_candidate_count,
      'candidate_count_ready', 0,
      'candidate_count_without_jobs', v_target_candidate_count,
      'job_count', 0,
      'candidate_results', '[]'::jsonb,
      'job_results', '[]'::jsonb,
      'jobs', '[]'::jsonb
    );
  end;

  if coalesce((v_build_result->>'ok')::boolean, false) = false then
    return jsonb_build_object(
      'ok', false,
      'trigger_status', 'REMITTANCE_BUILD_ERROR',
      'error', left(coalesce(nullif(btrim(coalesce(v_build_result->>'error', '')), ''), 'pay_remittance_build returned not ok'), 1000),
      'message_kind', 'REMITTANCE',
      'automatic_commit_stage', true,
      'dispatch_required', false,
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end,
      'scope', v_scope,
      'candidate_count_targeted', v_target_candidate_count,
      'candidate_count_ready', 0,
      'candidate_count_without_jobs', v_target_candidate_count,
      'job_count', 0,
      'candidate_results', '[]'::jsonb,
      'job_results', '[]'::jsonb,
      'jobs', '[]'::jsonb
    );
  end if;

  v_build_jobs := case
    when jsonb_typeof(v_build_result->'jobs') = 'array' then coalesce(v_build_result->'jobs', '[]'::jsonb)
    else '[]'::jsonb
  end;

  drop table if exists pg_temp.tmp_commit_stage_job_map;
  create temporary table pg_temp.tmp_commit_stage_job_map(
    candidate_id uuid not null,
    job_kind text not null,
    recipient_kind text null,
    recipient_email text null,
    umbrella_id uuid null
  ) on commit drop;

  for v_job in
    select j.value
    from jsonb_array_elements(v_build_jobs) as j(value)
  loop
    v_work_job := v_job;
    v_job_kind := upper(btrim(coalesce(v_job->>'job_kind', '')));
    v_recipient_kind := nullif(btrim(coalesce(v_job #>> '{recipient,entity_kind}', '')), '');
    v_recipient_email := coalesce(
      nullif(btrim(coalesce(v_job #>> '{recipient,email}', '')), ''),
      nullif(btrim(coalesce(v_job #>> '{recipient,remittance_email}', '')), '')
    );

    if v_job_kind = 'UMBRELLA_REMITTANCE' then
      v_umbrella_id_text := nullif(btrim(coalesce(v_job #>> '{recipient,umbrella_id}', '')), '');
      v_umbrella_id := null;

      if v_umbrella_id_text is not null then
        begin
          v_umbrella_id := v_umbrella_id_text::uuid;
        exception when invalid_text_representation then
          v_umbrella_id := null;
        end;
      end if;

      v_pruned_candidates := '[]'::jsonb;
      v_job_excluded_transfer_total := 0;

      for v_candidate_json in
        select ca.value
        from jsonb_array_elements(coalesce(v_job->'candidates', '[]'::jsonb)) as ca(value)
      loop
        v_candidate_id_text := nullif(btrim(coalesce(v_candidate_json->>'candidate_id', '')), '');
        v_candidate_id := null;

        if v_candidate_id_text is not null then
          begin
            v_candidate_id := v_candidate_id_text::uuid;
          exception when invalid_text_representation then
            v_candidate_id := null;
          end;
        end if;

        if v_candidate_id is not null
           and exists (
             select 1
             from pg_temp.tmp_commit_stage_target_candidates tc
             where tc.candidate_id = v_candidate_id
           ) then
          v_candidate_work_json := v_candidate_json;

          select round(coalesce(sum(pbt.amount), 0), 2)
          into v_candidate_excluded_transfer_total
          from pg_temp.tmp_commit_stage_excluded_transfers et
          join public.pay_bank_transfers pbt
            on pbt.id = et.transfer_id
          where et.candidate_id = v_candidate_id
            and (
              v_umbrella_id is null
              or et.umbrella_id is null
              or et.umbrella_id = v_umbrella_id
            );

          v_job_excluded_transfer_total := round(coalesce(v_job_excluded_transfer_total, 0) + coalesce(v_candidate_excluded_transfer_total, 0), 2);

          select coalesce(jsonb_agg(nt.value order by nt.ord), '[]'::jsonb)
          into v_pruned_non_timesheet_lines
          from jsonb_array_elements(coalesce(v_candidate_json->'non_timesheet_lines', '[]'::jsonb)) with ordinality as nt(value, ord)
          where not (
            upper(coalesce(nt.value->>'internal_item_type', '')) in ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
            and nullif(btrim(coalesce(nt.value->>'finance_case_id', '')), '') is not null
            and exists (
              select 1
              from pg_temp.tmp_commit_stage_excluded_finance_cases ef
              where ef.candidate_id = v_candidate_id
                and ef.finance_case_id::text = btrim(nt.value->>'finance_case_id')
            )
          );

          v_candidate_work_json := jsonb_set(v_candidate_work_json, '{non_timesheet_lines}', coalesce(v_pruned_non_timesheet_lines, '[]'::jsonb), true);

          if v_only_confirmed then
            select coalesce(jsonb_agg(timesheet_rows.value order by timesheet_rows.ord), '[]'::jsonb)
            into v_pruned_timesheets
            from jsonb_array_elements(coalesce(v_candidate_work_json->'timesheets', '[]'::jsonb)) with ordinality as timesheet_rows(value, ord)
            where nullif(btrim(coalesce(timesheet_rows.value->>'timesheet_id', '')), '') is not null
              and exists (
                select 1
                from pg_temp.tmp_commit_stage_confirmed_items as confirmed_timesheet_item
                where confirmed_timesheet_item.candidate_id = v_candidate_id
                  and confirmed_timesheet_item.timesheet_id is not null
                  and confirmed_timesheet_item.timesheet_id::text = nullif(btrim(coalesce(timesheet_rows.value->>'timesheet_id', '')), '')
              )
              and not exists (
                select 1
                from public.pay_batch_items as mixed_timesheet_item
                join public.pay_batch_candidates as mixed_timesheet_candidate
                  on mixed_timesheet_candidate.id = mixed_timesheet_item.pay_batch_candidate_id
                where mixed_timesheet_candidate.pay_batch_id = p_pay_batch_id
                  and mixed_timesheet_candidate.candidate_id = v_candidate_id
                  and mixed_timesheet_item.timesheet_id is not null
                  and mixed_timesheet_item.timesheet_id::text = nullif(btrim(coalesce(timesheet_rows.value->>'timesheet_id', '')), '')
                  and coalesce(mixed_timesheet_item.is_voided, false) = false
                  and mixed_timesheet_item.item_type <> 'DEBT_CREATED'
                  and not exists (
                    select 1
                    from public.pay_payment_correction_items as mixed_timesheet_correction
                    where mixed_timesheet_correction.pay_batch_item_id = mixed_timesheet_item.id
                      and mixed_timesheet_correction.status = 'APPLIED'
                      and mixed_timesheet_correction.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
                  )
                  and not exists (
                    select 1
                    from pg_temp.tmp_commit_stage_confirmed_items as confirmed_mixed_timesheet_item
                    where confirmed_mixed_timesheet_item.pay_batch_item_id = mixed_timesheet_item.id
                  )
              );

            v_candidate_work_json := jsonb_set(v_candidate_work_json, '{timesheets}', coalesce(v_pruned_timesheets, '[]'::jsonb), true);

            select coalesce(jsonb_agg(non_timesheet_rows.value order by non_timesheet_rows.ord), '[]'::jsonb)
            into v_pruned_non_timesheet_lines
            from jsonb_array_elements(coalesce(v_candidate_work_json->'non_timesheet_lines', '[]'::jsonb)) with ordinality as non_timesheet_rows(value, ord)
            where (
                (
                  nullif(btrim(coalesce(non_timesheet_rows.value->>'finance_case_id', '')), '') is not null
                  and exists (
                    select 1
                    from pg_temp.tmp_commit_stage_confirmed_items as confirmed_finance_item
                    where confirmed_finance_item.candidate_id = v_candidate_id
                      and confirmed_finance_item.finance_case_id is not null
                      and confirmed_finance_item.finance_case_id::text = nullif(btrim(coalesce(non_timesheet_rows.value->>'finance_case_id', '')), '')
                  )
                )
                or (
                  nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), '') is not null
                  and exists (
                    select 1
                    from pg_temp.tmp_commit_stage_confirmed_items as confirmed_carry_forward_item
                    where confirmed_carry_forward_item.candidate_id = v_candidate_id
                      and confirmed_carry_forward_item.manual_adjustment_carry_forward_id is not null
                      and confirmed_carry_forward_item.manual_adjustment_carry_forward_id::text = nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), '')
                  )
                )
              )
              and not exists (
                select 1
                from public.pay_batch_items as mixed_finance_item
                join public.pay_batch_candidates as mixed_finance_candidate
                  on mixed_finance_candidate.id = mixed_finance_item.pay_batch_candidate_id
                where mixed_finance_candidate.pay_batch_id = p_pay_batch_id
                  and mixed_finance_candidate.candidate_id = v_candidate_id
                  and coalesce(mixed_finance_item.is_voided, false) = false
                  and mixed_finance_item.item_type <> 'DEBT_CREATED'
                  and (
                    (
                      nullif(btrim(coalesce(non_timesheet_rows.value->>'finance_case_id', '')), '') is not null
                      and mixed_finance_item.finance_case_id is not null
                      and mixed_finance_item.finance_case_id::text = nullif(btrim(coalesce(non_timesheet_rows.value->>'finance_case_id', '')), '')
                    )
                    or (
                      nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), '') is not null
                      and (
                        mixed_finance_item.source_ref = ('carry_forward:' || nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), ''))
                        or mixed_finance_item.operation_source_key = ('carry_forward:' || nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), ''))
                        or mixed_finance_item.frozen_source_basis_json->>'manual_adjustment_carry_forward_id' = nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), '')
                        or mixed_finance_item.frozen_component_snapshot_json->>'manual_adjustment_carry_forward_id' = nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), '')
                      )
                    )
                  )
                  and not exists (
                    select 1
                    from public.pay_payment_correction_items as mixed_finance_correction
                    where mixed_finance_correction.pay_batch_item_id = mixed_finance_item.id
                      and mixed_finance_correction.status = 'APPLIED'
                      and mixed_finance_correction.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
                  )
                  and not exists (
                    select 1
                    from pg_temp.tmp_commit_stage_confirmed_items as confirmed_mixed_finance_item
                    where confirmed_mixed_finance_item.pay_batch_item_id = mixed_finance_item.id
                  )
              );

            v_candidate_work_json := jsonb_set(v_candidate_work_json, '{non_timesheet_lines}', coalesce(v_pruned_non_timesheet_lines, '[]'::jsonb), true);

            if jsonb_typeof(v_candidate_work_json->'transfers') = 'array' then
              select coalesce(jsonb_agg(transfer_rows.value order by transfer_rows.ord), '[]'::jsonb)
              into v_pruned_transfers
              from jsonb_array_elements(coalesce(v_candidate_work_json->'transfers', '[]'::jsonb)) with ordinality as transfer_rows(value, ord)
              where nullif(btrim(coalesce(transfer_rows.value->>'transfer_id', '')), '') is not null
                and exists (
                  select 1
                  from pg_temp.tmp_commit_stage_confirmed_items as confirmed_transfer_item
                  where confirmed_transfer_item.candidate_id = v_candidate_id
                    and confirmed_transfer_item.pay_bank_transfer_id is not null
                    and confirmed_transfer_item.pay_bank_transfer_id::text = nullif(btrim(coalesce(transfer_rows.value->>'transfer_id', '')), '')
                );

              v_candidate_work_json := jsonb_set(v_candidate_work_json, '{transfers}', coalesce(v_pruned_transfers, '[]'::jsonb), true);
            end if;

            v_candidate_work_json := jsonb_set(
              v_candidate_work_json,
              '{confirmed_only_scope}',
              jsonb_build_object(
                'enabled', true,
                'granularity', 'TRANSFER_PAYMENT_GROUP_CONFIRMED_ITEMS',
                'pay_bank_transfer_ids', coalesce((
                  select jsonb_agg(distinct confirmed_scope_transfer.pay_bank_transfer_id::text)
                  from pg_temp.tmp_commit_stage_confirmed_items as confirmed_scope_transfer
                  where confirmed_scope_transfer.candidate_id = v_candidate_id
                    and confirmed_scope_transfer.pay_bank_transfer_id is not null
                ), '[]'::jsonb),
                'pay_batch_item_ids', coalesce((
                  select jsonb_agg(distinct confirmed_scope_item.pay_batch_item_id::text)
                  from pg_temp.tmp_commit_stage_confirmed_items as confirmed_scope_item
                  where confirmed_scope_item.candidate_id = v_candidate_id
                ), '[]'::jsonb)
              ),
              true
            );
          end if;

          if jsonb_typeof(v_candidate_work_json->'totals') = 'object' then
            if btrim(coalesce(v_candidate_work_json #>> '{totals,final_paid}', '')) ~ '^-?[0-9]+(\.[0-9]+)?$' then
              v_final_paid_amount := round(greatest((v_candidate_work_json #>> '{totals,final_paid}')::numeric - coalesce(v_candidate_excluded_transfer_total, 0), 0), 2);
              v_candidate_work_json := jsonb_set(v_candidate_work_json, '{totals,final_paid}', to_jsonb(v_final_paid_amount), true);
              if jsonb_typeof(v_candidate_work_json #> '{totals,deductions_summary}') = 'object' then
                v_candidate_work_json := jsonb_set(v_candidate_work_json, '{totals,deductions_summary,final_payable}', to_jsonb(v_final_paid_amount), true);
              end if;
            end if;
          end if;

          v_pruned_candidates := v_pruned_candidates || jsonb_build_array(v_candidate_work_json);

          insert into pg_temp.tmp_commit_stage_job_map(
            candidate_id,
            job_kind,
            recipient_kind,
            recipient_email,
            umbrella_id
          )
          values (
            v_candidate_id,
            v_job_kind,
            v_recipient_kind,
            v_recipient_email,
            v_umbrella_id
          );
        end if;
      end loop;

      if jsonb_array_length(v_pruned_candidates) > 0 then
        if btrim(coalesce(v_job #>> '{summary,total_amount}', '')) ~ '^-?[0-9]+(\.[0-9]+)?$' then
          v_original_job_total := (v_job #>> '{summary,total_amount}')::numeric;
        else
          v_original_job_total := 0;
        end if;

        v_pruned_total_amount := round(greatest(coalesce(v_original_job_total, 0) - coalesce(v_job_excluded_transfer_total, 0), 0), 2);

        v_work_job := jsonb_set(v_work_job, '{candidates}', v_pruned_candidates, true);
        v_work_job := jsonb_set(v_work_job, '{summary,total_amount}', to_jsonb(coalesce(v_pruned_total_amount, 0)), true);
        v_work_job := jsonb_set(
          v_work_job,
          '{queue_context}',
          jsonb_strip_nulls(jsonb_build_object(
            'context_kind', 'pay_batches',
            'context_id', p_pay_batch_id::text,
            'pay_batch_id', p_pay_batch_id::text,
            'scope', v_scope,
            'only_confirmed', v_only_confirmed,
            'confirmed_only_granularity', case when v_only_confirmed then 'TRANSFER_PAYMENT_GROUP_CONFIRMED_ITEMS' else null end,
            'job_kind', v_job_kind,
            'recipient_kind', v_recipient_kind,
            'umbrella_id', case when v_umbrella_id is null then null else v_umbrella_id::text end,
            'candidate_ids', coalesce((
              select jsonb_agg(nullif(btrim(coalesce(candidate_context.value->>'candidate_id', '')), '') order by nullif(btrim(coalesce(candidate_context.value->>'candidate_id', '')), ''))
              from jsonb_array_elements(coalesce(v_pruned_candidates, '[]'::jsonb)) as candidate_context(value)
              where nullif(btrim(coalesce(candidate_context.value->>'candidate_id', '')), '') is not null
            ), '[]'::jsonb),
            'payment_scope_json', jsonb_strip_nulls(jsonb_build_object(
              'notice_scope', 'UMBRELLA_GROUP',
              'pay_batch_id', p_pay_batch_id::text,
              'pay_batch_candidate_ids', coalesce((
                select jsonb_agg(distinct umbrella_scope_target_candidates.pay_batch_candidate_id::text)
                from pg_temp.tmp_commit_stage_target_candidates as umbrella_scope_target_candidates
                where exists (
                  select 1
                  from jsonb_array_elements(coalesce(v_pruned_candidates, '[]'::jsonb)) as umbrella_scope_candidate_json(value)
                  where nullif(btrim(coalesce(umbrella_scope_candidate_json.value->>'candidate_id', '')), '') = umbrella_scope_target_candidates.candidate_id::text
                )
              ), '[]'::jsonb),
              'candidate_ids', coalesce((
                select jsonb_agg(distinct umbrella_scope_candidate_ids.candidate_id_text)
                from (
                  select nullif(btrim(coalesce(umbrella_scope_candidate_json.value->>'candidate_id', '')), '') as candidate_id_text
                  from jsonb_array_elements(coalesce(v_pruned_candidates, '[]'::jsonb)) as umbrella_scope_candidate_json(value)
                  where nullif(btrim(coalesce(umbrella_scope_candidate_json.value->>'candidate_id', '')), '') is not null
                ) as umbrella_scope_candidate_ids
              ), '[]'::jsonb),
              'umbrella_ids', case when v_umbrella_id is null then '[]'::jsonb else jsonb_build_array(v_umbrella_id::text) end,
              'pay_bank_transfer_ids', coalesce((
                select jsonb_agg(distinct umbrella_scope_items.pay_bank_transfer_id::text)
                from public.pay_batch_items as umbrella_scope_items
                join public.pay_batch_candidates as umbrella_scope_candidates
                  on umbrella_scope_candidates.id = umbrella_scope_items.pay_batch_candidate_id
                where umbrella_scope_candidates.pay_batch_id = p_pay_batch_id
                  and umbrella_scope_items.pay_bank_transfer_id is not null
                  and coalesce(umbrella_scope_items.is_voided, false) = false
                  and upper(coalesce(umbrella_scope_items.pay_channel, '')) = 'UMBRELLA'
                  and (v_umbrella_id is null or umbrella_scope_items.umbrella_id = v_umbrella_id)
                  and exists (
                    select 1
                    from jsonb_array_elements(coalesce(v_pruned_candidates, '[]'::jsonb)) as umbrella_scope_candidate_json(value)
                    where nullif(btrim(coalesce(umbrella_scope_candidate_json.value->>'candidate_id', '')), '') = umbrella_scope_candidates.candidate_id::text
                  )
                  and not exists (
                    select 1
                    from public.pay_payment_correction_items as umbrella_scope_corrections
                    where umbrella_scope_corrections.pay_batch_item_id = umbrella_scope_items.id
                      and umbrella_scope_corrections.status = 'APPLIED'
                      and umbrella_scope_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
                  )
                  and (
                    v_only_confirmed = false
                    or exists (
                      select 1
                      from pg_temp.tmp_commit_stage_confirmed_items as umbrella_scope_confirmed_items
                      where umbrella_scope_confirmed_items.pay_batch_item_id = umbrella_scope_items.id
                    )
                  )
              ), '[]'::jsonb),
              'transfer_group_keys', coalesce((
                select jsonb_agg(distinct umbrella_scope_transfers.transfer_group_key)
                from public.pay_batch_items as umbrella_scope_transfer_items
                join public.pay_batch_candidates as umbrella_scope_transfer_candidates
                  on umbrella_scope_transfer_candidates.id = umbrella_scope_transfer_items.pay_batch_candidate_id
                join public.pay_bank_transfers as umbrella_scope_transfers
                  on umbrella_scope_transfers.id = umbrella_scope_transfer_items.pay_bank_transfer_id
                where umbrella_scope_transfer_candidates.pay_batch_id = p_pay_batch_id
                  and umbrella_scope_transfers.transfer_group_key is not null
                  and coalesce(umbrella_scope_transfer_items.is_voided, false) = false
                  and upper(coalesce(umbrella_scope_transfer_items.pay_channel, '')) = 'UMBRELLA'
                  and (v_umbrella_id is null or umbrella_scope_transfer_items.umbrella_id = v_umbrella_id)
                  and exists (
                    select 1
                    from jsonb_array_elements(coalesce(v_pruned_candidates, '[]'::jsonb)) as umbrella_scope_candidate_json(value)
                    where nullif(btrim(coalesce(umbrella_scope_candidate_json.value->>'candidate_id', '')), '') = umbrella_scope_transfer_candidates.candidate_id::text
                  )
                  and (
                    v_only_confirmed = false
                    or exists (
                      select 1
                      from pg_temp.tmp_commit_stage_confirmed_items as umbrella_scope_transfer_confirmed_items
                      where umbrella_scope_transfer_confirmed_items.pay_batch_item_id = umbrella_scope_transfer_items.id
                    )
                  )
              ), '[]'::jsonb),
              'pay_batch_item_ids', coalesce((
                select jsonb_agg(distinct umbrella_scope_item_ids.id::text)
                from public.pay_batch_items as umbrella_scope_item_ids
                join public.pay_batch_candidates as umbrella_scope_item_candidates
                  on umbrella_scope_item_candidates.id = umbrella_scope_item_ids.pay_batch_candidate_id
                where umbrella_scope_item_candidates.pay_batch_id = p_pay_batch_id
                  and coalesce(umbrella_scope_item_ids.is_voided, false) = false
                  and upper(coalesce(umbrella_scope_item_ids.pay_channel, '')) = 'UMBRELLA'
                  and (v_umbrella_id is null or umbrella_scope_item_ids.umbrella_id = v_umbrella_id)
                  and exists (
                    select 1
                    from jsonb_array_elements(coalesce(v_pruned_candidates, '[]'::jsonb)) as umbrella_scope_candidate_json(value)
                    where nullif(btrim(coalesce(umbrella_scope_candidate_json.value->>'candidate_id', '')), '') = umbrella_scope_item_candidates.candidate_id::text
                  )
                  and not exists (
                    select 1
                    from public.pay_payment_correction_items as umbrella_scope_item_corrections
                    where umbrella_scope_item_corrections.pay_batch_item_id = umbrella_scope_item_ids.id
                      and umbrella_scope_item_corrections.status = 'APPLIED'
                      and umbrella_scope_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
                  )
                  and (
                    v_only_confirmed = false
                    or exists (
                      select 1
                      from pg_temp.tmp_commit_stage_confirmed_items as umbrella_scope_item_confirmed_items
                      where umbrella_scope_item_confirmed_items.pay_batch_item_id = umbrella_scope_item_ids.id
                    )
                  )
              ), '[]'::jsonb),
              'pay_channels', jsonb_build_array('UMBRELLA')
            )),
            'reference', concat('pay_batch:', p_pay_batch_id::text, ':umbrella:', coalesce(v_umbrella_id::text, 'UNKNOWN'))
          )),
          true
        );
        v_work_job := jsonb_set(
          v_work_job,
          '{payment_scope_json}',
          coalesce(v_work_job #> '{queue_context,payment_scope_json}', '{}'::jsonb),
          true
        );

        v_filtered_jobs := v_filtered_jobs || jsonb_build_array(v_work_job);
      end if;
    elsif v_job_kind in ('PAYE_REMITTANCE', 'CANDIDATE_UMBRELLA_COPY_REMITTANCE') then
      v_candidate_id_text := nullif(btrim(coalesce(v_job #>> '{recipient,candidate_id}', '')), '');
      v_candidate_id := null;

      if v_candidate_id_text is not null then
        begin
          v_candidate_id := v_candidate_id_text::uuid;
        exception when invalid_text_representation then
          v_candidate_id := null;
        end;
      end if;

      if v_candidate_id is not null
         and v_recipient_email is not null
         and exists (
           select 1
           from pg_temp.tmp_commit_stage_target_candidates tc
           where tc.candidate_id = v_candidate_id
         ) then
        if v_only_confirmed then
          select round(coalesce(sum(pbt_excluded_candidate.amount), 0), 2)
          into v_candidate_excluded_transfer_total
          from pg_temp.tmp_commit_stage_excluded_transfers as excluded_candidate_transfer
          join public.pay_bank_transfers as pbt_excluded_candidate
            on pbt_excluded_candidate.id = excluded_candidate_transfer.transfer_id
          where excluded_candidate_transfer.candidate_id = v_candidate_id;

          if jsonb_typeof(v_work_job->'timesheets') = 'array' then
            select coalesce(jsonb_agg(timesheet_rows.value order by timesheet_rows.ord), '[]'::jsonb)
            into v_pruned_timesheets
            from jsonb_array_elements(coalesce(v_work_job->'timesheets', '[]'::jsonb)) with ordinality as timesheet_rows(value, ord)
            where nullif(btrim(coalesce(timesheet_rows.value->>'timesheet_id', '')), '') is not null
              and exists (
                select 1
                from pg_temp.tmp_commit_stage_confirmed_items as confirmed_timesheet_item
                where confirmed_timesheet_item.candidate_id = v_candidate_id
                  and confirmed_timesheet_item.timesheet_id is not null
                  and confirmed_timesheet_item.timesheet_id::text = nullif(btrim(coalesce(timesheet_rows.value->>'timesheet_id', '')), '')
              )
              and not exists (
                select 1
                from public.pay_batch_items as mixed_timesheet_item
                join public.pay_batch_candidates as mixed_timesheet_candidate
                  on mixed_timesheet_candidate.id = mixed_timesheet_item.pay_batch_candidate_id
                where mixed_timesheet_candidate.pay_batch_id = p_pay_batch_id
                  and mixed_timesheet_candidate.candidate_id = v_candidate_id
                  and mixed_timesheet_item.timesheet_id is not null
                  and mixed_timesheet_item.timesheet_id::text = nullif(btrim(coalesce(timesheet_rows.value->>'timesheet_id', '')), '')
                  and coalesce(mixed_timesheet_item.is_voided, false) = false
                  and mixed_timesheet_item.item_type <> 'DEBT_CREATED'
                  and not exists (
                    select 1
                    from public.pay_payment_correction_items as mixed_timesheet_correction
                    where mixed_timesheet_correction.pay_batch_item_id = mixed_timesheet_item.id
                      and mixed_timesheet_correction.status = 'APPLIED'
                      and mixed_timesheet_correction.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
                  )
                  and not exists (
                    select 1
                    from pg_temp.tmp_commit_stage_confirmed_items as confirmed_mixed_timesheet_item
                    where confirmed_mixed_timesheet_item.pay_batch_item_id = mixed_timesheet_item.id
                  )
              );

            v_work_job := jsonb_set(v_work_job, '{timesheets}', coalesce(v_pruned_timesheets, '[]'::jsonb), true);
          end if;

          if jsonb_typeof(v_work_job->'non_timesheet_lines') = 'array' then
            select coalesce(jsonb_agg(non_timesheet_rows.value order by non_timesheet_rows.ord), '[]'::jsonb)
            into v_pruned_non_timesheet_lines
            from jsonb_array_elements(coalesce(v_work_job->'non_timesheet_lines', '[]'::jsonb)) with ordinality as non_timesheet_rows(value, ord)
            where (
                (
                  nullif(btrim(coalesce(non_timesheet_rows.value->>'finance_case_id', '')), '') is not null
                  and exists (
                    select 1
                    from pg_temp.tmp_commit_stage_confirmed_items as confirmed_finance_item
                    where confirmed_finance_item.candidate_id = v_candidate_id
                      and confirmed_finance_item.finance_case_id is not null
                      and confirmed_finance_item.finance_case_id::text = nullif(btrim(coalesce(non_timesheet_rows.value->>'finance_case_id', '')), '')
                  )
                )
                or (
                  nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), '') is not null
                  and exists (
                    select 1
                    from pg_temp.tmp_commit_stage_confirmed_items as confirmed_carry_forward_item
                    where confirmed_carry_forward_item.candidate_id = v_candidate_id
                      and confirmed_carry_forward_item.manual_adjustment_carry_forward_id is not null
                      and confirmed_carry_forward_item.manual_adjustment_carry_forward_id::text = nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), '')
                  )
                )
              )
              and not exists (
                select 1
                from public.pay_batch_items as mixed_finance_item
                join public.pay_batch_candidates as mixed_finance_candidate
                  on mixed_finance_candidate.id = mixed_finance_item.pay_batch_candidate_id
                where mixed_finance_candidate.pay_batch_id = p_pay_batch_id
                  and mixed_finance_candidate.candidate_id = v_candidate_id
                  and coalesce(mixed_finance_item.is_voided, false) = false
                  and mixed_finance_item.item_type <> 'DEBT_CREATED'
                  and (
                    (
                      nullif(btrim(coalesce(non_timesheet_rows.value->>'finance_case_id', '')), '') is not null
                      and mixed_finance_item.finance_case_id is not null
                      and mixed_finance_item.finance_case_id::text = nullif(btrim(coalesce(non_timesheet_rows.value->>'finance_case_id', '')), '')
                    )
                    or (
                      nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), '') is not null
                      and (
                        mixed_finance_item.source_ref = ('carry_forward:' || nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), ''))
                        or mixed_finance_item.operation_source_key = ('carry_forward:' || nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), ''))
                        or mixed_finance_item.frozen_source_basis_json->>'manual_adjustment_carry_forward_id' = nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), '')
                        or mixed_finance_item.frozen_component_snapshot_json->>'manual_adjustment_carry_forward_id' = nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), '')
                      )
                    )
                  )
                  and not exists (
                    select 1
                    from public.pay_payment_correction_items as mixed_finance_correction
                    where mixed_finance_correction.pay_batch_item_id = mixed_finance_item.id
                      and mixed_finance_correction.status = 'APPLIED'
                      and mixed_finance_correction.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
                  )
                  and not exists (
                    select 1
                    from pg_temp.tmp_commit_stage_confirmed_items as confirmed_mixed_finance_item
                    where confirmed_mixed_finance_item.pay_batch_item_id = mixed_finance_item.id
                  )
              );

            v_work_job := jsonb_set(v_work_job, '{non_timesheet_lines}', coalesce(v_pruned_non_timesheet_lines, '[]'::jsonb), true);

          end if;

          if jsonb_typeof(v_work_job->'transfers') = 'array' then
            select coalesce(jsonb_agg(transfer_rows.value order by transfer_rows.ord), '[]'::jsonb)
            into v_pruned_transfers
            from jsonb_array_elements(coalesce(v_work_job->'transfers', '[]'::jsonb)) with ordinality as transfer_rows(value, ord)
            where nullif(btrim(coalesce(transfer_rows.value->>'transfer_id', '')), '') is not null
              and exists (
                select 1
                from pg_temp.tmp_commit_stage_confirmed_items as confirmed_transfer_item
                where confirmed_transfer_item.candidate_id = v_candidate_id
                  and confirmed_transfer_item.pay_bank_transfer_id is not null
                  and confirmed_transfer_item.pay_bank_transfer_id::text = nullif(btrim(coalesce(transfer_rows.value->>'transfer_id', '')), '')
              );

            v_work_job := jsonb_set(v_work_job, '{transfers}', coalesce(v_pruned_transfers, '[]'::jsonb), true);
          end if;

          select round(coalesce(sum(confirmed_transfer_amounts.amount), 0), 2)
          into v_final_paid_amount
          from (
            select distinct
              confirmed_transfer.pay_bank_transfer_id,
              pbt_confirmed_amount.amount
            from pg_temp.tmp_commit_stage_confirmed_items as confirmed_transfer
            join public.pay_bank_transfers as pbt_confirmed_amount
              on pbt_confirmed_amount.id = confirmed_transfer.pay_bank_transfer_id
            where confirmed_transfer.candidate_id = v_candidate_id
              and confirmed_transfer.pay_bank_transfer_id is not null
          ) as confirmed_transfer_amounts;

          if coalesce(v_final_paid_amount, 0) <= 0
             and btrim(coalesce(v_work_job #>> '{summary,total_amount}', '')) ~ '^-?[0-9]+(\.[0-9]+)?$' then
            v_final_paid_amount := round(greatest((v_work_job #>> '{summary,total_amount}')::numeric - coalesce(v_candidate_excluded_transfer_total, 0), 0), 2);
          end if;

          if coalesce(v_final_paid_amount, 0) >= 0 then
            v_work_job := jsonb_set(v_work_job, '{summary,total_amount}', to_jsonb(coalesce(v_final_paid_amount, 0)), true);
            if jsonb_typeof(v_work_job->'pay_totals') = 'object' then
              v_work_job := jsonb_set(v_work_job, '{pay_totals,final_paid}', to_jsonb(coalesce(v_final_paid_amount, 0)), true);
              if jsonb_typeof(v_work_job #> '{pay_totals,deductions_summary}') = 'object' then
                v_work_job := jsonb_set(v_work_job, '{pay_totals,deductions_summary,final_payable}', to_jsonb(coalesce(v_final_paid_amount, 0)), true);
              end if;
            end if;
          end if;

          v_work_job := jsonb_set(
            v_work_job,
            '{confirmed_only_scope}',
            jsonb_build_object(
              'enabled', true,
              'granularity', 'TRANSFER_PAYMENT_GROUP_CONFIRMED_ITEMS',
              'pay_bank_transfer_ids', coalesce((
                select jsonb_agg(distinct confirmed_scope_transfer.pay_bank_transfer_id::text)
                from pg_temp.tmp_commit_stage_confirmed_items as confirmed_scope_transfer
                where confirmed_scope_transfer.candidate_id = v_candidate_id
                  and confirmed_scope_transfer.pay_bank_transfer_id is not null
              ), '[]'::jsonb),
              'pay_batch_item_ids', coalesce((
                select jsonb_agg(distinct confirmed_scope_item.pay_batch_item_id::text)
                from pg_temp.tmp_commit_stage_confirmed_items as confirmed_scope_item
                where confirmed_scope_item.candidate_id = v_candidate_id
              ), '[]'::jsonb)
            ),
            true
          );
        end if;

        v_work_job := jsonb_set(
          v_work_job,
          '{queue_context}',
          jsonb_strip_nulls(jsonb_build_object(
            'context_kind', 'pay_batches',
            'context_id', p_pay_batch_id::text,
            'pay_batch_id', p_pay_batch_id::text,
            'scope', v_scope,
            'only_confirmed', v_only_confirmed,
            'confirmed_only_granularity', case when v_only_confirmed then 'TRANSFER_PAYMENT_GROUP_CONFIRMED_ITEMS' else null end,
            'job_kind', v_job_kind,
            'recipient_kind', v_recipient_kind,
            'candidate_id', v_candidate_id::text,
            'pay_batch_candidate_id', (
              select tc.pay_batch_candidate_id::text
              from pg_temp.tmp_commit_stage_target_candidates tc
              where tc.candidate_id = v_candidate_id
              order by tc.pay_batch_candidate_id
              limit 1
            ),
            'payment_scope_json', jsonb_strip_nulls(jsonb_build_object(
              'notice_scope', 'CANDIDATE',
              'pay_batch_id', p_pay_batch_id::text,
              'pay_batch_candidate_ids', coalesce((
                select jsonb_agg(distinct candidate_scope_target_candidates.pay_batch_candidate_id::text)
                from pg_temp.tmp_commit_stage_target_candidates as candidate_scope_target_candidates
                where candidate_scope_target_candidates.candidate_id = v_candidate_id
              ), '[]'::jsonb),
              'candidate_ids', jsonb_build_array(v_candidate_id::text),
              'umbrella_ids', coalesce((
                select jsonb_agg(distinct candidate_scope_items.umbrella_id::text)
                from public.pay_batch_items as candidate_scope_items
                join public.pay_batch_candidates as candidate_scope_candidates
                  on candidate_scope_candidates.id = candidate_scope_items.pay_batch_candidate_id
                where candidate_scope_candidates.pay_batch_id = p_pay_batch_id
                  and candidate_scope_candidates.candidate_id = v_candidate_id
                  and candidate_scope_items.umbrella_id is not null
                  and coalesce(candidate_scope_items.is_voided, false) = false
                  and not exists (
                    select 1
                    from public.pay_payment_correction_items as candidate_scope_umbrella_corrections
                    where candidate_scope_umbrella_corrections.pay_batch_item_id = candidate_scope_items.id
                      and candidate_scope_umbrella_corrections.status = 'APPLIED'
                      and candidate_scope_umbrella_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
                  )
                  and (
                    v_only_confirmed = false
                    or exists (
                      select 1
                      from pg_temp.tmp_commit_stage_confirmed_items as candidate_scope_umbrella_confirmed_items
                      where candidate_scope_umbrella_confirmed_items.pay_batch_item_id = candidate_scope_items.id
                    )
                  )
              ), '[]'::jsonb),
              'pay_bank_transfer_ids', coalesce((
                select jsonb_agg(distinct candidate_scope_items.pay_bank_transfer_id::text)
                from public.pay_batch_items as candidate_scope_items
                join public.pay_batch_candidates as candidate_scope_candidates
                  on candidate_scope_candidates.id = candidate_scope_items.pay_batch_candidate_id
                where candidate_scope_candidates.pay_batch_id = p_pay_batch_id
                  and candidate_scope_candidates.candidate_id = v_candidate_id
                  and candidate_scope_items.pay_bank_transfer_id is not null
                  and coalesce(candidate_scope_items.is_voided, false) = false
                  and not exists (
                    select 1
                    from public.pay_payment_correction_items as candidate_scope_transfer_corrections
                    where candidate_scope_transfer_corrections.pay_batch_item_id = candidate_scope_items.id
                      and candidate_scope_transfer_corrections.status = 'APPLIED'
                      and candidate_scope_transfer_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
                  )
                  and (
                    v_only_confirmed = false
                    or exists (
                      select 1
                      from pg_temp.tmp_commit_stage_confirmed_items as candidate_scope_transfer_confirmed_items
                      where candidate_scope_transfer_confirmed_items.pay_batch_item_id = candidate_scope_items.id
                    )
                  )
              ), '[]'::jsonb),
              'transfer_group_keys', coalesce((
                select jsonb_agg(distinct candidate_scope_transfers.transfer_group_key)
                from public.pay_batch_items as candidate_scope_transfer_items
                join public.pay_batch_candidates as candidate_scope_transfer_candidates
                  on candidate_scope_transfer_candidates.id = candidate_scope_transfer_items.pay_batch_candidate_id
                join public.pay_bank_transfers as candidate_scope_transfers
                  on candidate_scope_transfers.id = candidate_scope_transfer_items.pay_bank_transfer_id
                where candidate_scope_transfer_candidates.pay_batch_id = p_pay_batch_id
                  and candidate_scope_transfer_candidates.candidate_id = v_candidate_id
                  and candidate_scope_transfers.transfer_group_key is not null
                  and coalesce(candidate_scope_transfer_items.is_voided, false) = false
                  and (
                    v_only_confirmed = false
                    or exists (
                      select 1
                      from pg_temp.tmp_commit_stage_confirmed_items as candidate_scope_group_confirmed_items
                      where candidate_scope_group_confirmed_items.pay_batch_item_id = candidate_scope_transfer_items.id
                    )
                  )
              ), '[]'::jsonb),
              'pay_batch_item_ids', coalesce((
                select jsonb_agg(distinct candidate_scope_item_ids.id::text)
                from public.pay_batch_items as candidate_scope_item_ids
                join public.pay_batch_candidates as candidate_scope_item_candidates
                  on candidate_scope_item_candidates.id = candidate_scope_item_ids.pay_batch_candidate_id
                where candidate_scope_item_candidates.pay_batch_id = p_pay_batch_id
                  and candidate_scope_item_candidates.candidate_id = v_candidate_id
                  and coalesce(candidate_scope_item_ids.is_voided, false) = false
                  and not exists (
                    select 1
                    from public.pay_payment_correction_items as candidate_scope_item_corrections
                    where candidate_scope_item_corrections.pay_batch_item_id = candidate_scope_item_ids.id
                      and candidate_scope_item_corrections.status = 'APPLIED'
                      and candidate_scope_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
                  )
                  and (
                    v_only_confirmed = false
                    or exists (
                      select 1
                      from pg_temp.tmp_commit_stage_confirmed_items as candidate_scope_item_confirmed_items
                      where candidate_scope_item_confirmed_items.pay_batch_item_id = candidate_scope_item_ids.id
                    )
                  )
              ), '[]'::jsonb),
              'pay_channels', coalesce((
                select jsonb_agg(distinct upper(coalesce(candidate_scope_channels.pay_channel, '')))
                from public.pay_batch_items as candidate_scope_channels
                join public.pay_batch_candidates as candidate_scope_channel_candidates
                  on candidate_scope_channel_candidates.id = candidate_scope_channels.pay_batch_candidate_id
                where candidate_scope_channel_candidates.pay_batch_id = p_pay_batch_id
                  and candidate_scope_channel_candidates.candidate_id = v_candidate_id
                  and nullif(btrim(coalesce(candidate_scope_channels.pay_channel, '')), '') is not null
                  and (
                    v_only_confirmed = false
                    or exists (
                      select 1
                      from pg_temp.tmp_commit_stage_confirmed_items as candidate_scope_channel_confirmed_items
                      where candidate_scope_channel_confirmed_items.pay_batch_item_id = candidate_scope_channels.id
                    )
                  )
              ), '[]'::jsonb)
            )),
            'reference', concat('pay_batch:', p_pay_batch_id::text, ':candidate:', v_candidate_id::text)
          )),
          true
        );
        v_work_job := jsonb_set(
          v_work_job,
          '{payment_scope_json}',
          coalesce(v_work_job #> '{queue_context,payment_scope_json}', '{}'::jsonb),
          true
        );

        v_filtered_jobs := v_filtered_jobs || jsonb_build_array(v_work_job);

        insert into pg_temp.tmp_commit_stage_job_map(
          candidate_id,
          job_kind,
          recipient_kind,
          recipient_email,
          umbrella_id
        )
        values (
          v_candidate_id,
          v_job_kind,
          v_recipient_kind,
          v_recipient_email,
          null::uuid
        );
      end if;
    end if;
  end loop;

  select count(distinct jm.candidate_id)::int
  into v_ready_candidate_count
  from pg_temp.tmp_commit_stage_job_map jm;

  select jsonb_array_length(v_filtered_jobs)
  into v_job_count;

  if v_job_count > 0 then
    update public.pay_batch_candidates pbc
    set
      remittance_trigger_status = 'REMITTANCE_BUILD_READY',
      last_remittance_error = null,
      updated_at = now()
    where pbc.pay_batch_id = p_pay_batch_id
      and (pbc.remittance_sent_at_utc is null or v_only_confirmed)
      and exists (
        select 1
        from pg_temp.tmp_commit_stage_job_map jm
        where jm.candidate_id = pbc.candidate_id
      );

    v_trigger_status := 'REMITTANCE_BUILD_READY';
  else
    v_trigger_status := 'NO_QUEUEABLE_REMITTANCE_JOB';
  end if;

  select coalesce(
           jsonb_agg(
             jsonb_build_object(
               'pay_batch_candidate_id', tc.pay_batch_candidate_id::text,
               'candidate_id', tc.candidate_id::text,
               'candidate_display_name', tc.candidate_display_name,
               'candidate_tms_ref', tc.candidate_tms_ref,
               'has_job', exists (
                 select 1
                 from pg_temp.tmp_commit_stage_job_map jm
                 where jm.candidate_id = tc.candidate_id
               ),
               'job_kinds', coalesce(
                 (
                   select jsonb_agg(to_jsonb(jk.job_kind) order by jk.job_kind)
                   from (
                     select distinct jm2.job_kind
                     from pg_temp.tmp_commit_stage_job_map jm2
                     where jm2.candidate_id = tc.candidate_id
                   ) jk
                 ),
                 '[]'::jsonb
               ),
               'trigger_status',
                 case
                   when exists (
                     select 1
                     from pg_temp.tmp_commit_stage_job_map jm3
                     where jm3.candidate_id = tc.candidate_id
                   )
                   then 'REMITTANCE_BUILD_READY'
                   else 'NO_QUEUEABLE_REMITTANCE_JOB'
                 end
             )
             order by tc.candidate_display_name nulls last, tc.candidate_tms_ref nulls last, tc.candidate_id
           ),
           '[]'::jsonb
         )
  into v_candidate_results
  from pg_temp.tmp_commit_stage_target_candidates tc;

  select coalesce(
           jsonb_agg(
             jsonb_build_object(
               'job_kind', upper(btrim(coalesce(j.job->>'job_kind', ''))),
               'recipient_kind', nullif(btrim(coalesce(j.job #>> '{recipient,entity_kind}', '')), ''),
               'recipient_id',
                 case
                   when upper(btrim(coalesce(j.job #>> '{recipient,entity_kind}', ''))) = 'CANDIDATE'
                     then nullif(btrim(coalesce(j.job #>> '{recipient,candidate_id}', '')), '')
                   when upper(btrim(coalesce(j.job #>> '{recipient,entity_kind}', ''))) = 'UMBRELLA'
                     then nullif(btrim(coalesce(j.job #>> '{recipient,umbrella_id}', '')), '')
                   else null
                 end,
               'recipient_email', coalesce(
                 nullif(btrim(coalesce(j.job #>> '{recipient,email}', '')), ''),
                 nullif(btrim(coalesce(j.job #>> '{recipient,remittance_email}', '')), '')
               ),
               'candidate_ids',
                 case
                   when upper(btrim(coalesce(j.job->>'job_kind', ''))) = 'UMBRELLA_REMITTANCE'
                     then coalesce(
                       (
                         select jsonb_agg(to_jsonb(ci.candidate_id_text) order by ci.candidate_id_text)
                         from (
                           select nullif(btrim(coalesce(ca.value->>'candidate_id', '')), '') as candidate_id_text
                           from jsonb_array_elements(coalesce(j.job->'candidates', '[]'::jsonb)) as ca(value)
                           where nullif(btrim(coalesce(ca.value->>'candidate_id', '')), '') is not null
                         ) ci
                       ),
                       '[]'::jsonb
                     )
                   else
                     case
                       when nullif(btrim(coalesce(j.job #>> '{recipient,candidate_id}', '')), '') is null
                         then '[]'::jsonb
                       else jsonb_build_array(j.job #>> '{recipient,candidate_id}')
                     end
                 end,
               'candidate_count',
                 case
                   when upper(btrim(coalesce(j.job->>'job_kind', ''))) = 'UMBRELLA_REMITTANCE'
                     then jsonb_array_length(coalesce(j.job->'candidates', '[]'::jsonb))
                   when nullif(btrim(coalesce(j.job #>> '{recipient,candidate_id}', '')), '') is null
                     then 0
                   else 1
                 end
             )
             order by j.ord
           ),
           '[]'::jsonb
         )
  into v_job_results
  from jsonb_array_elements(v_filtered_jobs) with ordinality as j(job, ord);

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_REMITTANCE_QUEUE_COMMIT_STAGE_RESULT',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'scope', v_scope,
      'only_confirmed', COALESCE(p_only_confirmed, false),
      'confirmed_only_granularity', case when v_only_confirmed then 'TRANSFER_PAYMENT_GROUP_CONFIRMED_ITEMS' else 'NOT_APPLICABLE' end,
      'trigger_status', v_trigger_status,
      'candidate_count_targeted', v_target_candidate_count,
      'candidate_count_ready', v_ready_candidate_count,
      'job_count', v_job_count
    ),
    'pay_remittance',
    p_pay_batch_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  return jsonb_build_object(
    'ok', true,
    'trigger_status', v_trigger_status,
    'error', null,
    'message_kind', 'REMITTANCE',
    'automatic_commit_stage', true,
    'dispatch_required', (v_job_count > 0),
    'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end,
    'scope', v_scope,
    'only_confirmed', COALESCE(p_only_confirmed, false),
      'confirmed_only_granularity', case when v_only_confirmed then 'TRANSFER_PAYMENT_GROUP_CONFIRMED_ITEMS' else 'NOT_APPLICABLE' end,
    'pay_date', case when coalesce(v_batch.authoritative_payment_date, v_batch.pay_date) is null then null else coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)::text end,
    'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
    'authoritative_payment_date_source', v_batch.authoritative_payment_date_source,
    'bulk_reference', v_batch.bulk_reference,
    'candidate_count_targeted', v_target_candidate_count,
    'candidate_count_ready', v_ready_candidate_count,
    'candidate_count_without_jobs', greatest(v_target_candidate_count - v_ready_candidate_count, 0),
    'job_count', v_job_count,
    'candidate_results', coalesce(v_candidate_results, '[]'::jsonb),
    'job_results', coalesce(v_job_results, '[]'::jsonb),
    'jobs', coalesce(v_filtered_jobs, '[]'::jsonb)
  );
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_REMITTANCE_QUEUE_COMMIT_STAGE_ERROR',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id,
        'scope', v_scope,
        'only_confirmed', COALESCE(p_only_confirmed, false),
      'confirmed_only_granularity', case when v_only_confirmed then 'TRANSFER_PAYMENT_GROUP_CONFIRMED_ITEMS' else 'NOT_APPLICABLE' end,
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_remittance',
      COALESCE(p_pay_batch_id::text, 'NO_BATCH_ID'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
    RAISE;
end;
$function$;

-- pay_search(text,integer,integer)
CREATE OR REPLACE FUNCTION public.pay_search(p_query text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_q text := nullif(btrim(coalesce(p_query, '')), '');
  v_q_digits text := null;
  v_limit int := greatest(coalesce(p_limit, 20), 0);
  v_offset int := greatest(coalesce(p_offset, 0), 0);

  v_is_digits7 boolean := false;
  v_is_digits15 boolean := false;
  v_is_digits8 boolean := false;

  v_digits7_int int := null;
  v_amount_query numeric := null;

  v_batches jsonb := '[]'::jsonb;
  v_matches jsonb := '[]'::jsonb;
begin
  if v_q is null then
    return jsonb_build_object(
      'query', coalesce(p_query, ''),
      'query_digits', '',
      'batches', '[]'::jsonb,
      'matches', '[]'::jsonb
    );
  end if;

  v_q_digits := regexp_replace(v_q, '[^0-9]', '', 'g');

  v_is_digits7 := (length(v_q_digits) = 7);
  v_is_digits15 := (length(v_q_digits) = 15);
  v_is_digits8 := (length(v_q_digits) = 8);

  if v_is_digits7 then
    begin
      v_digits7_int := v_q_digits::int;
    exception when others then
      v_digits7_int := null;
    end;
  end if;

  -- numeric amount search (optional): allow "123" or "123.45" (strip commas/spaces)
  begin
    if regexp_replace(v_q, '[ ,]', '', 'g') ~ '^[0-9]+(\.[0-9]{1,2})?$' then
      v_amount_query := regexp_replace(v_q, '[ ,]', '', 'g')::numeric;
    end if;
  exception when others then
    v_amount_query := null;
  end;

  -- ---------------------------------------------------------
  -- BATCH matches
  -- ---------------------------------------------------------
  with batches_raw as (
    select
      pb.id as batch_id,
      pb.pay_date,
      pb.bulk_reference,
      pb.bulk_ref_num,
      pb.bulk_ref_date,
      pb.status,
      pb.total_bank_out,
      pb.total_debt_created
    from public.pay_batches pb
    where
      (
        -- 7 digits -> bulk_ref_num
        (v_is_digits7 and v_digits7_int is not null and pb.bulk_ref_num = v_digits7_int)
        or
        -- 15 digits -> bulk_reference (support digits-only or hyphenated storage)
        (v_is_digits15 and pb.bulk_reference is not null
          and (
            pb.bulk_reference = v_q_digits
            or regexp_replace(pb.bulk_reference, '[^0-9]', '', 'g') = v_q_digits
          )
        )
        or
        -- 8 digits -> DDMMYYYY match against bulk_ref_date or pay_date
        (v_is_digits8 and (
          to_char(pb.pay_date, 'DDMMYYYY') = v_q_digits
          or (pb.bulk_ref_date is not null and to_char(pb.bulk_ref_date, 'DDMMYYYY') = v_q_digits)
        ))
        or
        -- ISO date
        (v_q ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pb.pay_date = v_q::date)
        or
        -- free-text match against bulk_reference (if present)
        (not v_is_digits7 and not v_is_digits15 and not v_is_digits8
          and pb.bulk_reference is not null and pb.bulk_reference ilike ('%' || v_q || '%')
        )
      )
    order by pb.pay_date desc, pb.created_at_utc desc, pb.id desc
    offset v_offset
    limit v_limit
  )
  select coalesce(
    jsonb_agg(jsonb_build_object(
      'batch_id', br.batch_id,
      'pay_date', br.pay_date,
      'bulk_reference', br.bulk_reference,
      'status', br.status,
      'total_bank_out', br.total_bank_out,
      'total_debt_created', br.total_debt_created
    )),
    '[]'::jsonb
  )
  into v_batches
  from batches_raw br;

  -- ---------------------------------------------------------
  -- TRANSFER matches (and link back to batch bulk ref)
  -- ---------------------------------------------------------
  with matches_raw as (
    select
      pbt.id as transfer_id,
      pbt.pay_batch_id,
      pb.pay_date,
      pb.bulk_reference,
      pbt.pay_channel,
      pbt.amount,
      pbt.currency,
      pbt.status as transfer_status,
      pbt.payment_reference,

      pbt.candidate_id,
      c.display_name as candidate_display_name,
      c.first_name as candidate_first_name,
      c.last_name as candidate_last_name,

      pbt.umbrella_id,
      u.name as umbrella_name
    from public.pay_bank_transfers pbt
    join public.pay_batches pb
      on pb.id = pbt.pay_batch_id
    left join public.candidates c
      on c.id = pbt.candidate_id
    left join public.umbrellas u
      on u.id = pbt.umbrella_id
    where
      (
        -- 7 digits -> match batch bulk_ref_num
        (v_is_digits7 and v_digits7_int is not null and pb.bulk_ref_num = v_digits7_int)
        or
        -- 15 digits -> match batch bulk_reference (digits-only or hyphenated)
        (v_is_digits15 and pb.bulk_reference is not null
          and (
            pb.bulk_reference = v_q_digits
            or regexp_replace(pb.bulk_reference, '[^0-9]', '', 'g') = v_q_digits
          )
        )
        or
        -- 8 digits -> DDMMYYYY match against bulk_ref_date or pay_date
        (v_is_digits8 and (
          to_char(pb.pay_date, 'DDMMYYYY') = v_q_digits
          or (pb.bulk_ref_date is not null and to_char(pb.bulk_ref_date, 'DDMMYYYY') = v_q_digits)
        ))
        or
        -- ISO date
        (v_q ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pb.pay_date = v_q::date)
        or
        -- free-text against payment_reference, candidate, umbrella, or bulk_reference
        (
          not v_is_digits7 and not v_is_digits15 and not v_is_digits8 and
          (
            (pbt.payment_reference is not null and pbt.payment_reference ilike ('%' || v_q || '%'))
            or
            (pb.bulk_reference is not null and pb.bulk_reference ilike ('%' || v_q || '%'))
            or
            (u.name is not null and u.name ilike ('%' || v_q || '%'))
            or
            (c.display_name is not null and c.display_name ilike ('%' || v_q || '%'))
            or
            (trim(concat_ws(' ', c.first_name, c.last_name)) <> '' and trim(concat_ws(' ', c.first_name, c.last_name)) ilike ('%' || v_q || '%'))
            or
            (v_amount_query is not null and pbt.amount = v_amount_query)
          )
        )
      )
    order by pb.pay_date desc, pbt.id desc
    offset v_offset
    limit v_limit
  )
  select coalesce(
    jsonb_agg(jsonb_build_object(
      'transfer_id', mr.transfer_id,
      'pay_batch_id', mr.pay_batch_id,
      'pay_date', mr.pay_date,
      'bulk_reference', mr.bulk_reference,
      'pay_channel', mr.pay_channel,
      'amount', mr.amount,
      'currency', mr.currency,
      'transfer_status', mr.transfer_status,
      'payment_reference', mr.payment_reference,
      'candidate_id', mr.candidate_id,
      'candidate_name', coalesce(mr.candidate_display_name, nullif(btrim(concat_ws(' ', mr.candidate_first_name, mr.candidate_last_name)), '')),
      'umbrella_id', mr.umbrella_id,
      'umbrella_name', mr.umbrella_name
    )),
    '[]'::jsonb
  )
  into v_matches
  from matches_raw mr;

  return jsonb_build_object(
    'query', v_q,
    'query_digits', coalesce(v_q_digits, ''),
    'batches', v_batches,
    'matches', v_matches
  );
end;
$function$;

-- pay_set_paye_net_from_sage(uuid,text,uuid,text)
CREATE OR REPLACE FUNCTION public.pay_set_paye_net_from_sage(p_pay_batch_id uuid, p_csv_raw text, p_actor_user_id uuid, p_source_filename text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_lines text[];
  v_line text;
  v_fields text[];

  header_idx int := 0;
  i int := 0;

  works_col int := 0;
  net_col int := 0;

  works text;
  works_norm text;
  net_raw text;
  net_amt numeric;

  dup_check jsonb := '[]'::jsonb;

  v_matched jsonb := '[]'::jsonb;
  v_unknown jsonb := '[]'::jsonb;
  v_ambig jsonb := '[]'::jsonb;
  v_missing_net jsonb := '[]'::jsonb;

  v_applied_count int := 0;

  v_batch record;
  v_week_start date;
  v_batch_status_upper text := null;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_execution_commit_ref text := null;
  v_execution_committed_at_utc timestamptz := null;

  v_fresh jsonb := null;
  v_is_stale boolean := false;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_diff_sample jsonb := '[]'::jsonb;

  v_deleted_ded_items int := 0;
  v_deleted_ded_breakdowns int := 0;
  v_ins_overpay int := 0;
  v_ins_loan int := 0;
  v_ins_overpay_bd int := 0;
  v_ins_loan_bd int := 0;
  v_deleted_ded_reservations int := 0;
  v_ins_loan_res int := 0;
  v_upd_candidates int := 0;
  v_candidate_summaries jsonb := '[]'::jsonb;
begin
  perform public._ctms_assert_pay_batch_mutable_v1(p_pay_batch_id,'PAY_SET_PAYE_NET_FROM_SAGE');
  if p_pay_batch_id is null then
    raise exception 'pay_batch_id is required';
  end if;

  if p_actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  select
    pb.id,
    pb.status,
    pb.pay_date,
    pb.batch_kind_fixed,
    pb.cancelled_at_utc,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  for update;

  if v_batch.id is null then
    raise exception 'pay_batch not found';
  end if;

  if upper(btrim(coalesce(v_batch.batch_kind_fixed,''))) = 'LOANS' then
    raise exception 'PAYE_NET_NOT_APPLICABLE_FOR_LOANS_BATCH';
  end if;

  if v_batch.pay_date is null then
    raise exception 'pay_batch pay_date is required';
  end if;

  v_week_start := public._pay_week_start_monday(v_batch.pay_date);

  v_batch_status_upper := upper(btrim(coalesce(v_batch.status, '')));
  v_execution_commit_state := upper(btrim(coalesce(v_batch.execution_commit_state, 'NOT_SUBMITTED')));
  if v_execution_commit_state not in ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') then
    v_execution_commit_state := 'NOT_SUBMITTED';
  end if;
  v_execution_commit_ref := nullif(btrim(coalesce(v_batch.execution_commit_ref, '')), '');
  v_execution_committed_at_utc := v_batch.execution_committed_at_utc;

  if v_batch.cancelled_at_utc is not null
     or v_batch_status_upper in ('CANCELLED', 'CANCELED', 'SCHEDULED', 'SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED', 'EXECUTED', 'PAID', 'SETTLED')
     or v_execution_commit_state <> 'NOT_SUBMITTED'
     or v_execution_commit_ref is not null
     or v_execution_committed_at_utc is not null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SET_PAYE_NET_SAGE',
      'code', 'PAYE_NET_MUTATION_BLOCKED_BY_LIFECYCLE',
      'message', 'pay_set_paye_net_from_sage: PAYE net cannot be changed after the payment batch has crossed the execution/cancellation lifecycle boundary',
      'pay_batch_id', p_pay_batch_id::text,
      'status', v_batch.status,
      'cancelled_at_utc', case when v_batch.cancelled_at_utc is null then null else v_batch.cancelled_at_utc::text end,
      'execution_commit_state', v_execution_commit_state,
      'execution_commit_ref', v_execution_commit_ref,
      'execution_committed_at_utc', case when v_execution_committed_at_utc is null then null else v_execution_committed_at_utc::text end
    )::text;
  end if;

  v_fresh := public.pay_batch_validate_freshness(
    p_pay_batch_id => p_pay_batch_id,
    p_actor_user_id => p_actor_user_id,
    p_allow_large_full_scan => false
  );
  v_is_stale := coalesce((v_fresh->>'is_stale')::boolean, false);
  v_stale_reasons := coalesce(v_fresh->'stale_reasons', '[]'::jsonb);

  if v_is_stale = true then
    select coalesce(jsonb_agg(x.elem), '[]'::jsonb)
      into v_diff_sample
    from (
      select elem
      from jsonb_array_elements(coalesce(v_fresh->'diff','[]'::jsonb)) as elem
      limit 50
    ) x;

    raise exception '%', jsonb_build_object(
      'error', 'PAY_SET_PAYE_NET_SAGE',
      'code', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'FRESHNESS_REQUIRES_CHUNKED_VALIDATION' else 'BATCH_STALE' end,
      'message', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'pay_set_paye_net_from_sage: chunked freshness validation is required before changing PAYE net' else 'pay_set_paye_net_from_sage: batch is stale; regenerate draft before importing PAYE net' end,
      'pay_batch_id', p_pay_batch_id::text,
      'stale_reasons', v_stale_reasons,
      'diff', v_diff_sample
    )::text;
  end if;

  v_lines := regexp_split_to_array(coalesce(p_csv_raw,''), E'\\r?\\n');

  for i in 1..coalesce(array_length(v_lines,1),0) loop
    v_line := coalesce(v_lines[i],'');
    if btrim(v_line) = '' then continue; end if;

    v_fields := public._pay_csv_parse_line(v_line);

    works_col := 0;
    net_col := 0;

    for header_idx in 1..coalesce(array_length(v_fields,1),0) loop
      if lower(btrim(coalesce(v_fields[header_idx],''))) = lower('Works Number') then
        works_col := header_idx;
      end if;
      if lower(btrim(coalesce(v_fields[header_idx],''))) = lower('Net Pay') then
        net_col := header_idx;
      end if;
    end loop;

    if works_col > 0 and net_col > 0 then
      header_idx := i;
      exit;
    end if;
  end loop;

  if header_idx = 0 then
    raise exception 'SAGE_IMPORT_INVALID: header row with Works Number and Net Pay not found';
  end if;

  create temp table if not exists _tmp_sage_net (
    works_number text,
    works_norm text,
    net_amount numeric
  ) on commit drop;

  truncate table _tmp_sage_net;

  for i in (header_idx+1)..coalesce(array_length(v_lines,1),0) loop
    v_line := coalesce(v_lines[i],'');
    if btrim(v_line) = '' then continue; end if;

    v_fields := public._pay_csv_parse_line(v_line);

    works := public._pay_csv_trim_field(case when works_col <= array_length(v_fields,1) then v_fields[works_col] else null end);
    if works is null then
      continue;
    end if;

    if lower(works) = 'totals' then
      continue;
    end if;

    works_norm := upper(regexp_replace(btrim(coalesce(works,'')), '\s+', '', 'g'));
    if works_norm = '' then
      continue;
    end if;

    net_raw := public._pay_csv_trim_field(case when net_col <= array_length(v_fields,1) then v_fields[net_col] else null end);

    if net_raw is null or btrim(net_raw) = '' then
      insert into _tmp_sage_net(works_number, works_norm, net_amount)
      values (works, works_norm, null);
      continue;
    end if;

    net_raw := replace(net_raw, ',', '');
    net_raw := regexp_replace(net_raw, '[^0-9\\.-]', '', 'g');

    if net_raw is null or btrim(net_raw) = '' then
      insert into _tmp_sage_net(works_number, works_norm, net_amount)
      values (works, works_norm, null);
      continue;
    end if;

    begin
      net_amt := net_raw::numeric;
    exception when others then
      raise exception 'SAGE_IMPORT_INVALID: Net Pay not numeric for Works Number %', works;
    end;

    if net_amt < 0 then
      raise exception 'SAGE_IMPORT_INVALID: Net Pay negative for Works Number %', works;
    end if;

    insert into _tmp_sage_net(works_number, works_norm, net_amount)
    values (works, works_norm, round(net_amt,2));
  end loop;

  select coalesce(jsonb_agg(t.works_norm), '[]'::jsonb)
  into dup_check
  from (
    select sn.works_norm
    from _tmp_sage_net sn
    group by sn.works_norm
    having count(*) > 1
  ) t;

  if jsonb_array_length(dup_check) > 0 then
    raise exception 'SAGE_IMPORT_INVALID: duplicate Works Number(s) %', dup_check::text;
  end if;

  create temp table if not exists _tmp_batch_paye (
    candidate_id uuid,
    pay_batch_candidate_id uuid,
    tms_ref_norm text,
    ni_norm text
  ) on commit drop;

  truncate table _tmp_batch_paye;

  insert into _tmp_batch_paye(candidate_id, pay_batch_candidate_id, tms_ref_norm, ni_norm)
  select
    pbc.candidate_id,
    pbc.id,
    upper(regexp_replace(btrim(coalesce(pbc.candidate_tms_ref, c.tms_ref, '')), '\s+', '', 'g')) as tms_ref_norm,
    upper(regexp_replace(btrim(coalesce(c.ni_number, '')), '\s+', '', 'g')) as ni_norm
  from public.pay_batch_candidates pbc
  join public.candidates c on c.id = pbc.candidate_id
  where pbc.pay_batch_id = p_pay_batch_id
    and pbc.paye_state is not null;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'works_number', a.works_norm,
        'candidate_ids', a.candidate_ids
      )
    ),
    '[]'::jsonb
  )
  into v_ambig
  from (
    select
      sn.works_norm,
      jsonb_agg(distinct bp.candidate_id::text order by bp.candidate_id::text) as candidate_ids
    from _tmp_sage_net sn
    join _tmp_batch_paye bp
      on (bp.tms_ref_norm is not null and bp.tms_ref_norm <> '' and bp.tms_ref_norm = sn.works_norm)
      or (bp.ni_norm is not null and bp.ni_norm <> '' and bp.ni_norm = sn.works_norm)
    group by sn.works_norm
    having count(distinct bp.candidate_id) > 1
  ) a;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'works_number', sn.works_number,
        'works_norm', sn.works_norm
      )
    ),
    '[]'::jsonb
  )
  into v_unknown
  from _tmp_sage_net sn
  left join _tmp_batch_paye bp
    on (bp.tms_ref_norm is not null and bp.tms_ref_norm <> '' and bp.tms_ref_norm = sn.works_norm)
    or (bp.ni_norm is not null and bp.ni_norm <> '' and bp.ni_norm = sn.works_norm)
  where bp.candidate_id is null;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'works_number', sn.works_number,
        'works_norm', sn.works_norm,
        'candidate_id', bp.candidate_id::text,
        'pay_batch_candidate_id', bp.pay_batch_candidate_id::text
      )
    ),
    '[]'::jsonb
  )
  into v_missing_net
  from _tmp_sage_net sn
  join _tmp_batch_paye bp
    on (
      (bp.tms_ref_norm is not null and bp.tms_ref_norm <> '' and bp.tms_ref_norm = sn.works_norm)
      or (bp.ni_norm is not null and bp.ni_norm <> '' and bp.ni_norm = sn.works_norm)
    )
  where sn.net_amount is null
    and not exists (
      select 1
      from jsonb_array_elements(coalesce(v_ambig,'[]'::jsonb)) a
      where (a->>'works_number') = sn.works_norm
      limit 1
    );

  create temp table if not exists _tmp_sage_match (
    pay_batch_candidate_id uuid,
    net_amount numeric
  ) on commit drop;

  truncate table _tmp_sage_match;

  insert into _tmp_sage_match(pay_batch_candidate_id, net_amount)
  select
    bp.pay_batch_candidate_id,
    sn.net_amount
  from _tmp_sage_net sn
  join _tmp_batch_paye bp
    on (
      (bp.tms_ref_norm is not null and bp.tms_ref_norm <> '' and bp.tms_ref_norm = sn.works_norm)
      or (bp.ni_norm is not null and bp.ni_norm <> '' and bp.ni_norm = sn.works_norm)
    )
  where sn.net_amount is not null
    and not exists (
      select 1
      from jsonb_array_elements(coalesce(v_ambig,'[]'::jsonb)) a
      where (a->>'works_number') = sn.works_norm
      limit 1
    )
    and not exists (
      select 1
      from jsonb_array_elements(coalesce(v_unknown,'[]'::jsonb)) u
      where (u->>'works_norm') = sn.works_norm
      limit 1
    );

  select count(*)::int
  into v_applied_count
  from _tmp_sage_match sm;

  delete from public.pay_batch_paye_net_inputs pni
  using _tmp_sage_match sm
  where pni.pay_batch_candidate_id = sm.pay_batch_candidate_id
    and pni.source = 'SAGE_IMPORT';

  insert into public.pay_batch_paye_net_inputs(
    pay_batch_candidate_id, source, net_amount, imported_at_utc, file_name, file_hash
  )
  select
    sm.pay_batch_candidate_id,
    'SAGE_IMPORT',
    sm.net_amount,
    now(),
    p_source_filename,
    null
  from _tmp_sage_match sm;

  update public.pay_batch_candidates pbc
  set paye_state = case
    when exists (
      select 1
      from public.pay_batch_paye_net_inputs pni2
      where pni2.pay_batch_candidate_id = pbc.id
      limit 1
    ) then 'READY'
    else 'PENDING_NET'
  end
  where pbc.pay_batch_id = p_pay_batch_id
    and pbc.paye_state is not null;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'pay_batch_candidate_id', bp.pay_batch_candidate_id::text,
        'candidate_id', bp.candidate_id::text,
        'net_amount', sm.net_amount
      )
      order by bp.candidate_id::text
    ),
    '[]'::jsonb
  )
  into v_matched
  from _tmp_sage_match sm
  join _tmp_batch_paye bp
    on bp.pay_batch_candidate_id = sm.pay_batch_candidate_id;

  ---------------------------------------------------------------------------
  -- ✅ Recompute NET_DEDUCT items + net_bank_amount (PAYE candidates only)
  -- Gross-side recovery/addition items remain as created at draft time.
  ---------------------------------------------------------------------------
  create temp table if not exists _tmp_paye_scope (
    pay_batch_candidate_id uuid primary key,
    candidate_id uuid not null
  ) on commit drop;

  truncate table _tmp_paye_scope;

  insert into _tmp_paye_scope(pay_batch_candidate_id, candidate_id)
  select
    pbc3.id,
    pbc3.candidate_id
  from public.pay_batch_candidates pbc3
  where pbc3.pay_batch_id = p_pay_batch_id
    and pbc3.paye_state is not null;

  create temp table if not exists _tmp_ded_item_ids (
    id uuid primary key
  ) on commit drop;

  truncate table _tmp_ded_item_ids;

  insert into _tmp_ded_item_ids(id)
  select
    pbi_del.id
  from public.pay_batch_items pbi_del
  where pbi_del.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
    and pbi_del.item_type = 'LOAN_REPAYMENT';

  delete from public.pay_batch_item_breakdowns pbib_del
  using _tmp_ded_item_ids di
  where pbib_del.pay_batch_item_id = di.id;

  get diagnostics v_deleted_ded_breakdowns = row_count;

  delete from public.pay_advance_reservations par_del
  using _tmp_ded_item_ids di_res
  where par_del.pay_batch_item_id = di_res.id;

  get diagnostics v_deleted_ded_reservations = row_count;

  delete from public.pay_batch_items pbi_del2
  using _tmp_ded_item_ids di2
  where pbi_del2.id = di2.id;

  get diagnostics v_deleted_ded_items = row_count;

  update public.pay_batch_candidates pbc_aw
  set
    awaiting_net_amount = not exists (
      select 1
      from public.pay_batch_paye_net_inputs pni_aw
      where pni_aw.pay_batch_candidate_id = pbc_aw.id
      limit 1
    ),
    updated_at = now()
  where pbc_aw.id in (select s.pay_batch_candidate_id from _tmp_paye_scope s);

  with ins_loan_items as (
    insert into public.pay_batch_items (
      id,
      pay_batch_candidate_id,
      item_type,
      timesheet_id,
      segment_key,
      source_ref,
      amount_ex_vat,
      amount_vat,
      amount_inc_vat,
      repayment_week_start,
      pay_channel,
      umbrella_id,
      is_mismatch,
      is_voided,
      finance_case_id,
      reservation_id,
      paye_treatment,
      created_at,
      updated_at
    )
    with
    cand_scope as (
      select
        pbc.id as pay_batch_candidate_id,
        pbc.candidate_id,
        'PAYE'::text as pay_channel,
        null::uuid as umbrella_id,
        pbc.awaiting_net_amount,
        ni.net_amount::numeric(12,2) as paye_net_amount
      from public.pay_batch_candidates pbc
      join _tmp_paye_scope sc
        on sc.pay_batch_candidate_id = pbc.id
      left join lateral (
        select pni.net_amount
        from public.pay_batch_paye_net_inputs pni
        where pni.pay_batch_candidate_id = pbc.id
        order by pni.imported_at_utc desc
        limit 1
      ) ni on true
    ),
    cand_limits as (
      select
        cs.pay_batch_candidate_id,
        cs.candidate_id,
        cs.pay_channel,
        cs.umbrella_id,
        greatest(coalesce(cs.paye_net_amount, 0), 0)::numeric(12,2) as earnings_before_payment_advance_ex
      from cand_scope cs
      where cs.awaiting_net_amount = false
    ),
    paid_wtd as (
      select
        pbc2.candidate_id,
        round(sum(
          case
            when pbc2.net_bank_amount is not null then pbc2.net_bank_amount
            when pbc2.gross_preview is not null then pbc2.gross_preview
            else 0
          end
        ), 2)::numeric(12,2) as paid_wtd_before_ex
      from public.pay_batch_candidates pbc2
      join public.pay_batches pb2
        on pb2.id = pbc2.pay_batch_id
      where pb2.cancelled_at_utc is null
        and pb2.id <> p_pay_batch_id
        and coalesce(pb2.batch_kind_fixed, '') <> 'LOANS'
        and pb2.pay_date >= v_week_start
        and pb2.pay_date < (v_week_start + 7)
      group by pbc2.candidate_id
    ),
    cand_with_floor as (
      select
        cl.pay_batch_candidate_id,
        cl.candidate_id,
        cl.pay_channel,
        cl.umbrella_id,
        cl.earnings_before_payment_advance_ex,
        coalesce(pw.paid_wtd_before_ex, 0)::numeric(12,2) as paid_wtd_before_ex,
        coalesce(c.min_take_home_wtd, 0)::numeric(12,2) as floor_ex,
        round(
          greatest(
            least(
              cl.earnings_before_payment_advance_ex,
              (coalesce(pw.paid_wtd_before_ex, 0) + cl.earnings_before_payment_advance_ex) - coalesce(c.min_take_home_wtd, 0)
            ),
            0
          ),
          2
        )::numeric(12,2) as max_payment_advance_repayment_ex
      from cand_limits cl
      join public.candidates c
        on c.id = cl.candidate_id
      left join paid_wtd pw
        on pw.candidate_id = cl.candidate_id
      where cl.earnings_before_payment_advance_ex > 0
    ),
    payment_advances as (
      select
        pa.id as finance_case_id,
        pa.candidate_id,
        pa.outstanding_amount::numeric(12,2) as outstanding_amount,
        pa.weekly_due::numeric(12,2) as weekly_due,
        pa.start_week_start,
        pa.created_at
      from public.pay_advances pa
      where pa.case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum
        and pa.payout_status = 'PAID'::public.pay_advance_payout_status_enum
        and pa.status = 'ACTIVE'::public.pay_advance_status_enum
        and pa.outstanding_amount > 0
        and pa.weekly_due is not null
        and pa.weekly_due > 0
        and (pa.start_week_start is null or pa.start_week_start <= v_week_start)
    ),
    payment_advance_repaid_wtd as (
      select
        pbc2.candidate_id,
        replace(pbi2.source_ref, 'advance:', '')::uuid as finance_case_id,
        round(coalesce(sum(-pbi2.amount_ex_vat), 0), 2)::numeric(12,2) as repaid_wtd_ex
      from public.pay_batch_items pbi2
      join public.pay_batch_candidates pbc2
        on pbc2.id = pbi2.pay_batch_candidate_id
      join public.pay_batches pb2
        on pb2.id = pbc2.pay_batch_id
      where pbi2.item_type = 'LOAN_REPAYMENT'
        and pbi2.is_voided = false
        and pbi2.source_ref ~ '^advance:[0-9a-fA-F-]{36}$'
        and pbi2.repayment_week_start = v_week_start
        and pb2.cancelled_at_utc is null
        and pb2.id <> p_pay_batch_id
        and coalesce(pb2.batch_kind_fixed, '') <> 'LOANS'
      group by
        pbc2.candidate_id,
        replace(pbi2.source_ref, 'advance:', '')::uuid
    ),
    payment_advance_due as (
      select
        cwf.pay_batch_candidate_id,
        cwf.candidate_id,
        cwf.pay_channel,
        cwf.umbrella_id,
        cwf.max_payment_advance_repayment_ex,
        pa.finance_case_id,
        pa.outstanding_amount,
        pa.weekly_due,
        pa.start_week_start,
        pa.created_at,
        least(pa.weekly_due, pa.outstanding_amount)::numeric(12,2) as due_this_week_ex,
        greatest(
          least(pa.weekly_due, pa.outstanding_amount) - coalesce(parw.repaid_wtd_ex, 0),
          0
        )::numeric(12,2) as remaining_due_ex
      from cand_with_floor cwf
      join payment_advances pa
        on pa.candidate_id = cwf.candidate_id
      left join payment_advance_repaid_wtd parw
        on parw.candidate_id = cwf.candidate_id
       and parw.finance_case_id = pa.finance_case_id
      where cwf.max_payment_advance_repayment_ex > 0
        and greatest(
          least(pa.weekly_due, pa.outstanding_amount) - coalesce(parw.repaid_wtd_ex, 0),
          0
        ) > 0
    ),
    alloc_base as (
      select
        pad.candidate_id,
        pad.finance_case_id,
        pad.remaining_due_ex,
        pad.max_payment_advance_repayment_ex,
        sum(pad.remaining_due_ex) over (
          partition by pad.candidate_id
          order by pad.start_week_start nulls first, pad.created_at, pad.finance_case_id
          rows between unbounded preceding and 1 preceding
        )::numeric(12,2) as cum_before_ex
      from payment_advance_due pad
    ),
    alloc as (
      select
        pad2.pay_batch_candidate_id,
        pad2.pay_channel,
        pad2.umbrella_id,
        pad2.finance_case_id,
        least(
          pad2.remaining_due_ex,
          greatest(pad2.max_payment_advance_repayment_ex - coalesce(ab.cum_before_ex, 0), 0)
        )::numeric(12,2) as take_ex
      from payment_advance_due pad2
      join alloc_base ab
        on ab.finance_case_id = pad2.finance_case_id
    )
    select
      gen_random_uuid() as id,
      a.pay_batch_candidate_id,
      'LOAN_REPAYMENT' as item_type,
      null::uuid as timesheet_id,
      null::text as segment_key,
      ('advance:' || a.finance_case_id::text) as source_ref,
      (-a.take_ex)::numeric(12,2) as amount_ex_vat,
      (0)::numeric(12,2) as amount_vat,
      (-a.take_ex)::numeric(12,2) as amount_inc_vat,
      v_week_start as repayment_week_start,
      a.pay_channel as pay_channel,
      a.umbrella_id as umbrella_id,
      false as is_mismatch,
      false as is_voided,
      a.finance_case_id as finance_case_id,
      null::uuid as reservation_id,
      'NET_DEDUCT'::text as paye_treatment,
      now() as created_at,
      now() as updated_at
    from alloc a
    where a.take_ex > 0
    returning
      id,
      pay_batch_candidate_id,
      finance_case_id,
      repayment_week_start,
      amount_ex_vat,
      amount_vat,
      amount_inc_vat
  ),
  ins_loan_reservations as (
    insert into public.pay_advance_reservations (
      id,
      finance_case_id,
      pay_batch_id,
      pay_batch_candidate_id,
      pay_batch_item_id,
      reserved_amount,
      repayment_week_start,
      status,
      created_at_utc,
      committed_at_utc,
      settled_at_utc,
      released_at_utc,
      released_reason,
      created_by_user_id,
      updated_by_user_id
    )
    select
      gen_random_uuid() as id,
      ili.finance_case_id,
      p_pay_batch_id,
      ili.pay_batch_candidate_id,
      ili.id as pay_batch_item_id,
      abs(ili.amount_ex_vat)::numeric(12,2) as reserved_amount,
      ili.repayment_week_start,
      'RESERVED' as status,
      now() as created_at_utc,
      null::timestamptz as committed_at_utc,
      null::timestamptz as settled_at_utc,
      null::timestamptz as released_at_utc,
      null::text as released_reason,
      p_actor_user_id as created_by_user_id,
      p_actor_user_id as updated_by_user_id
    from ins_loan_items ili
    returning id, pay_batch_item_id
  ),
  upd_loan_items as (
    update public.pay_batch_items pbi_upd
    set
      reservation_id = ilr.id,
      updated_at = now()
    from ins_loan_reservations ilr
    where pbi_upd.id = ilr.pay_batch_item_id
    returning pbi_upd.id
  )
  insert into public.pay_batch_item_breakdowns(
    pay_batch_item_id,
    line_kind,
    bucket_code,
    unit_name,
    units,
    rate,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    meta_json
  )
  select
    ili.id,
    'LOAN_REPAYMENT',
    null,
    'Payment Advance repayment',
    null::numeric,
    null::numeric,
    ili.amount_ex_vat,
    ili.amount_vat,
    ili.amount_inc_vat,
    '{}'::jsonb
  from ins_loan_items ili;

  get diagnostics v_ins_loan_bd = row_count;

  select count(*)::int
  into v_ins_loan
  from public.pay_batch_items pbi_ct2
  where pbi_ct2.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
    and pbi_ct2.item_type = 'LOAN_REPAYMENT'
    and pbi_ct2.is_voided = false
    and pbi_ct2.repayment_week_start = v_week_start;

  select count(*)::int
  into v_ins_loan_res
  from public.pay_advance_reservations par_ct
  join public.pay_batch_items pbi_res
    on pbi_res.id = par_ct.pay_batch_item_id
  where par_ct.pay_batch_id = p_pay_batch_id
    and pbi_res.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
    and pbi_res.item_type = 'LOAN_REPAYMENT'
    and pbi_res.is_voided = false
    and par_ct.status = 'RESERVED';

  update public.pay_batch_candidates pbc_sum
  set
    awaiting_net_amount = not exists (
      select 1
      from public.pay_batch_paye_net_inputs pni4
      where pni4.pay_batch_candidate_id = pbc_sum.id
      limit 1
    ),
    overpayment_recovery_taken = coalesce((
      select round(sum(-pbi_s.amount_ex_vat), 2)
      from public.pay_batch_items pbi_s
      where pbi_s.pay_batch_candidate_id = pbc_sum.id
        and pbi_s.is_voided = false
        and pbi_s.item_type = 'OVERPAYMENT_RECOVERY'
    ), 0)::numeric(12,2),
    loan_repayment_taken = coalesce((
      select round(sum(-pbi_s2.amount_ex_vat), 2)
      from public.pay_batch_items pbi_s2
      where pbi_s2.pay_batch_candidate_id = pbc_sum.id
        and pbi_s2.is_voided = false
        and pbi_s2.item_type = 'LOAN_REPAYMENT'
    ), 0)::numeric(12,2),
    net_bank_amount = case
      when not exists (
        select 1
        from public.pay_batch_paye_net_inputs pni5
        where pni5.pay_batch_candidate_id = pbc_sum.id
        limit 1
      ) then null
      else greatest(
        round(
          coalesce((
            select pni_last.net_amount
            from public.pay_batch_paye_net_inputs pni_last
            where pni_last.pay_batch_candidate_id = pbc_sum.id
            order by pni_last.imported_at_utc desc
            limit 1
          ), 0)
          +
          coalesce((
            select round(coalesce(sum(
              case
                when pbi_d.is_voided = false and coalesce(pbi_d.paye_treatment, '') = 'NET_ADD'
                  then pbi_d.amount_ex_vat
                when pbi_d.is_voided = false and coalesce(pbi_d.paye_treatment, '') = 'NET_DEDUCT'
                  then pbi_d.amount_ex_vat
                else 0
              end
            ),0),2)
            from public.pay_batch_items pbi_d
            where pbi_d.pay_batch_candidate_id = pbc_sum.id
          ), 0),
          2
        ),
        0
      )::numeric(12,2)
    end,
    updated_at = now()
  where pbc_sum.id in (select s.pay_batch_candidate_id from _tmp_paye_scope s);

  get diagnostics v_upd_candidates = row_count;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'pay_batch_candidate_id', pbc_ret.id::text,
        'candidate_id', pbc_ret.candidate_id::text,
        'paye_state', pbc_ret.paye_state,
        'awaiting_net_amount', pbc_ret.awaiting_net_amount,
        'paye_net_amount', pni_ret.net_amount,
        'overpayment_recovery', coalesce(pbc_ret.overpayment_recovery_taken, 0)::numeric(12,2),
        'manual_debt_recovery', coalesce((
          select round(sum(-pbi_md.amount_ex_vat), 2)
          from public.pay_batch_items pbi_md
          where pbi_md.pay_batch_candidate_id = pbc_ret.id
            and pbi_md.is_voided = false
            and pbi_md.item_type = 'MANUAL_DEBT_RECOVERY'
        ), 0)::numeric(12,2),
        'loan_repayment', coalesce(pbc_ret.loan_repayment_taken, 0)::numeric(12,2),
        'payment_advance_repayment', coalesce(pbc_ret.loan_repayment_taken, 0)::numeric(12,2),
        'loan_payout_net_additions', coalesce((
          select round(sum(coalesce(pbi_np.amount_ex_vat, 0)), 2)
          from public.pay_batch_items pbi_np
          where pbi_np.pay_batch_candidate_id = pbc_ret.id
            and pbi_np.is_voided = false
            and pbi_np.item_type = 'LOAN_PAYOUT'
            and coalesce(pbi_np.paye_treatment, '') = 'NET_ADD'
        ), 0)::numeric(12,2),
        'manual_credit_net_additions', coalesce((
          select round(sum(coalesce(pbi_mc.amount_ex_vat, 0)), 2)
          from public.pay_batch_items pbi_mc
          where pbi_mc.pay_batch_candidate_id = pbc_ret.id
            and pbi_mc.is_voided = false
            and pbi_mc.item_type = 'MANUAL_CREDIT_PAYOUT'
            and coalesce(pbi_mc.paye_treatment, '') = 'NET_ADD'
        ), 0)::numeric(12,2),
        'manual_debt_net_deductions', coalesce((
          select round(sum(-pbi_mdn.amount_ex_vat), 2)
          from public.pay_batch_items pbi_mdn
          where pbi_mdn.pay_batch_candidate_id = pbc_ret.id
            and pbi_mdn.is_voided = false
            and pbi_mdn.item_type = 'MANUAL_DEBT_RECOVERY'
            and coalesce(pbi_mdn.paye_treatment, '') = 'NET_DEDUCT'
        ), 0)::numeric(12,2),
        'net_additions_total', coalesce((
          select round(sum(coalesce(pbi_na.amount_ex_vat, 0)), 2)
          from public.pay_batch_items pbi_na
          where pbi_na.pay_batch_candidate_id = pbc_ret.id
            and pbi_na.is_voided = false
            and coalesce(pbi_na.paye_treatment, '') = 'NET_ADD'
        ), 0)::numeric(12,2),
        'net_deductions_total', coalesce((
          select round(sum(-pbi_nd0.amount_ex_vat), 2)
          from public.pay_batch_items pbi_nd0
          where pbi_nd0.pay_batch_candidate_id = pbc_ret.id
            and pbi_nd0.is_voided = false
            and coalesce(pbi_nd0.paye_treatment, '') = 'NET_DEDUCT'
        ), 0)::numeric(12,2),
        'net_bank_amount', pbc_ret.net_bank_amount,
        'deductions_summary', jsonb_build_object(
          'imported_paye_net', greatest(coalesce(pni_ret.net_amount, 0), 0)::numeric(12,2),
          'gross_side_overpayment_recovery', coalesce(pbc_ret.overpayment_recovery_taken, 0)::numeric(12,2),
          'gross_side_manual_debt_recovery', coalesce((
            select round(sum(-pbi_md2.amount_ex_vat), 2)
            from public.pay_batch_items pbi_md2
            where pbi_md2.pay_batch_candidate_id = pbc_ret.id
              and pbi_md2.is_voided = false
              and pbi_md2.item_type = 'MANUAL_DEBT_RECOVERY'
              and coalesce(pbi_md2.paye_treatment, '') = 'GROSS_DEDUCT'
          ), 0)::numeric(12,2),
          'payment_advance_repayment', coalesce(pbc_ret.loan_repayment_taken, 0)::numeric(12,2),
          'loan_payout_net_additions', coalesce((
            select round(sum(coalesce(pbi_np2.amount_ex_vat, 0)), 2)
            from public.pay_batch_items pbi_np2
            where pbi_np2.pay_batch_candidate_id = pbc_ret.id
              and pbi_np2.is_voided = false
              and pbi_np2.item_type = 'LOAN_PAYOUT'
              and coalesce(pbi_np2.paye_treatment, '') = 'NET_ADD'
          ), 0)::numeric(12,2),
          'manual_credit_net_additions', coalesce((
            select round(sum(coalesce(pbi_mc2.amount_ex_vat, 0)), 2)
            from public.pay_batch_items pbi_mc2
            where pbi_mc2.pay_batch_candidate_id = pbc_ret.id
              and pbi_mc2.is_voided = false
              and pbi_mc2.item_type = 'MANUAL_CREDIT_PAYOUT'
              and coalesce(pbi_mc2.paye_treatment, '') = 'NET_ADD'
          ), 0)::numeric(12,2),
          'manual_debt_net_deductions', coalesce((
            select round(sum(-pbi_mdn2.amount_ex_vat), 2)
            from public.pay_batch_items pbi_mdn2
            where pbi_mdn2.pay_batch_candidate_id = pbc_ret.id
              and pbi_mdn2.is_voided = false
              and pbi_mdn2.item_type = 'MANUAL_DEBT_RECOVERY'
              and coalesce(pbi_mdn2.paye_treatment, '') = 'NET_DEDUCT'
          ), 0)::numeric(12,2),
          'net_additions_total', coalesce((
            select round(sum(coalesce(pbi_na2.amount_ex_vat, 0)), 2)
            from public.pay_batch_items pbi_na2
            where pbi_na2.pay_batch_candidate_id = pbc_ret.id
              and pbi_na2.is_voided = false
              and coalesce(pbi_na2.paye_treatment, '') = 'NET_ADD'
          ), 0)::numeric(12,2),
          'net_deductions_total', coalesce((
            select round(sum(-pbi_nd.amount_ex_vat), 2)
            from public.pay_batch_items pbi_nd
            where pbi_nd.pay_batch_candidate_id = pbc_ret.id
              and pbi_nd.is_voided = false
              and coalesce(pbi_nd.paye_treatment, '') = 'NET_DEDUCT'
          ), 0)::numeric(12,2),
          'final_bank', pbc_ret.net_bank_amount,
          'awaiting_net_amount', pbc_ret.awaiting_net_amount,
          'paye_net_amount', pni_ret.net_amount
        )
      )
      order by pbc_ret.candidate_id::text
    ),
    '[]'::jsonb
  )
  into v_candidate_summaries
  from public.pay_batch_candidates pbc_ret
  left join lateral (
    select pni_ret_inner.net_amount
    from public.pay_batch_paye_net_inputs pni_ret_inner
    where pni_ret_inner.pay_batch_candidate_id = pbc_ret.id
    order by pni_ret_inner.imported_at_utc desc
    limit 1
  ) pni_ret on true
  where pbc_ret.id in (select s.pay_batch_candidate_id from _tmp_paye_scope s);

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'source', 'SAGE_IMPORT',
    'applied_count', v_applied_count,
    'matched', v_matched,
    'missing_net', v_missing_net,
    'unknown', v_unknown,
    'ambiguous', v_ambig,
    'candidate_summaries', v_candidate_summaries,
    'recompute', jsonb_build_object(
      'deleted_deduction_items', v_deleted_ded_items,
      'deleted_deduction_breakdowns', v_deleted_ded_breakdowns,
      'deleted_net_deduct_reservations', v_deleted_ded_reservations,
      'inserted_overpayment_items', v_ins_overpay,
      'inserted_overpayment_breakdowns', v_ins_overpay_bd,
      'inserted_loan_items', v_ins_loan,
      'inserted_loan_breakdowns', v_ins_loan_bd,
      'inserted_loan_reservations', v_ins_loan_res,
      'updated_candidates', v_upd_candidates
    )
  );
end;
$function$;

-- pay_set_paye_net_manual(uuid,jsonb,uuid)
CREATE OR REPLACE FUNCTION public.pay_set_paye_net_manual(p_pay_batch_id uuid, p_entries_json jsonb, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_entries jsonb := coalesce(p_entries_json, '[]'::jsonb);

  v_dup jsonb := '[]'::jsonb;
  v_ambig jsonb := '[]'::jsonb;
  v_unmatched jsonb := '[]'::jsonb;

  v_updated_count int := 0;
  v_cleared_count int := 0;

  v_batch record;
  v_week_start date;
  v_batch_status_upper text := null;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_execution_commit_ref text := null;
  v_execution_committed_at_utc timestamptz := null;

  v_fresh jsonb := null;
  v_is_stale boolean := false;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_diff_sample jsonb := '[]'::jsonb;

  v_deleted_ded_items int := 0;
  v_deleted_ded_breakdowns int := 0;
  v_ins_overpay int := 0;
  v_ins_loan int := 0;
  v_ins_overpay_bd int := 0;
  v_ins_loan_bd int := 0;
  v_deleted_ded_reservations int := 0;
  v_deleted_manual_debt_breakdowns int := 0;
  v_released_manual_debt_reservations int := 0;
  v_voided_manual_debt_items int := 0;
  v_ins_manual_debt int := 0;
  v_ins_manual_debt_bd int := 0;
  v_ins_finance_reservations int := 0;
  v_upd_candidates int := 0;
  v_candidate_summaries jsonb := '[]'::jsonb;
begin
  perform public._ctms_assert_pay_batch_mutable_v1(p_pay_batch_id,'PAY_SET_PAYE_NET_MANUAL');
  if p_pay_batch_id is null then
    raise exception 'pay_batch_id is required';
  end if;

  if p_actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  if jsonb_typeof(v_entries) <> 'array' then
    raise exception 'entries must be an array';
  end if;

  select
    pb.id,
    pb.status,
    pb.pay_date,
    pb.batch_kind_fixed,
    pb.cancelled_at_utc,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  for update;

  if v_batch.id is null then
    raise exception 'pay_batch not found';
  end if;

  if upper(btrim(coalesce(v_batch.batch_kind_fixed,''))) = 'LOANS' then
    raise exception 'PAYE_NET_NOT_APPLICABLE_FOR_LOANS_BATCH';
  end if;

  if v_batch.pay_date is null then
    raise exception 'pay_batch pay_date is required';
  end if;

  v_week_start := public._pay_week_start_monday(v_batch.pay_date);

  v_batch_status_upper := upper(btrim(coalesce(v_batch.status, '')));
  v_execution_commit_state := upper(btrim(coalesce(v_batch.execution_commit_state, 'NOT_SUBMITTED')));
  if v_execution_commit_state not in ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') then
    v_execution_commit_state := 'NOT_SUBMITTED';
  end if;
  v_execution_commit_ref := nullif(btrim(coalesce(v_batch.execution_commit_ref, '')), '');
  v_execution_committed_at_utc := v_batch.execution_committed_at_utc;

  if v_batch.cancelled_at_utc is not null
     or v_batch_status_upper in ('CANCELLED', 'CANCELED', 'SCHEDULED', 'SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED', 'EXECUTED', 'PAID', 'SETTLED')
     or v_execution_commit_state <> 'NOT_SUBMITTED'
     or v_execution_commit_ref is not null
     or v_execution_committed_at_utc is not null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SET_PAYE_NET_MANUAL',
      'code', 'PAYE_NET_MUTATION_BLOCKED_BY_LIFECYCLE',
      'message', 'pay_set_paye_net_manual: PAYE net cannot be changed after the payment batch has crossed the execution/cancellation lifecycle boundary',
      'pay_batch_id', p_pay_batch_id::text,
      'status', v_batch.status,
      'cancelled_at_utc', case when v_batch.cancelled_at_utc is null then null else v_batch.cancelled_at_utc::text end,
      'execution_commit_state', v_execution_commit_state,
      'execution_commit_ref', v_execution_commit_ref,
      'execution_committed_at_utc', case when v_execution_committed_at_utc is null then null else v_execution_committed_at_utc::text end
    )::text;
  end if;

  v_fresh := public.pay_batch_validate_freshness(
    p_pay_batch_id => p_pay_batch_id,
    p_actor_user_id => p_actor_user_id,
    p_allow_large_full_scan => false
  );
  v_is_stale := coalesce((v_fresh->>'is_stale')::boolean, false);
  v_stale_reasons := coalesce(v_fresh->'stale_reasons', '[]'::jsonb);

  if v_is_stale = true then
    select coalesce(jsonb_agg(x.elem), '[]'::jsonb)
      into v_diff_sample
    from (
      select elem
      from jsonb_array_elements(coalesce(v_fresh->'diff','[]'::jsonb)) as elem
      limit 50
    ) x;

    raise exception '%', jsonb_build_object(
      'error', 'PAY_SET_PAYE_NET_MANUAL',
      'code', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'FRESHNESS_REQUIRES_CHUNKED_VALIDATION' else 'BATCH_STALE' end,
      'message', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'pay_set_paye_net_manual: chunked freshness validation is required before changing PAYE net' else 'pay_set_paye_net_manual: batch is stale; regenerate draft before setting PAYE net' end,
      'pay_batch_id', p_pay_batch_id::text,
      'stale_reasons', v_stale_reasons,
      'diff', v_diff_sample
    )::text;
  end if;

  create temp table if not exists _tmp_manual_net (
    pay_batch_candidate_id uuid,
    candidate_id uuid,
    works_raw text,
    works_norm text,
    net_amount numeric
  ) on commit drop;

  truncate table _tmp_manual_net;

  insert into _tmp_manual_net(pay_batch_candidate_id, candidate_id, works_raw, works_norm, net_amount)
  select
    nullif(e->>'pay_batch_candidate_id','')::uuid as pay_batch_candidate_id,
    nullif(e->>'candidate_id','')::uuid as candidate_id,
    nullif(btrim(e->>'tms_ref'), '') as works_raw,
    case
      when nullif(btrim(e->>'tms_ref'), '') is null then null
      else upper(regexp_replace(btrim(e->>'tms_ref'), '\s+', '', 'g'))
    end as works_norm,
    case
      when nullif(btrim(coalesce(e->>'net_amount','')), '') is null then null
      else round((nullif(btrim(coalesce(e->>'net_amount','')), '')::numeric), 2)
    end as net_amount
  from jsonb_array_elements(v_entries) e
  where e is not null and jsonb_typeof(e)='object';

  if exists (
    select 1
    from _tmp_manual_net mn
    where mn.pay_batch_candidate_id is null
      and mn.candidate_id is null
      and (mn.works_norm is null or mn.works_norm = '')
    limit 1
  ) then
    raise exception 'MANUAL_NET_INVALID: each entry must include pay_batch_candidate_id, candidate_id or tms_ref/NI (Works Number)';
  end if;

  if exists (
    select 1
    from _tmp_manual_net t
    where t.net_amount is not null
      and t.net_amount < 0
    limit 1
  ) then
    raise exception 'MANUAL_NET_INVALID: net_amount must be non-negative';
  end if;

  select coalesce(jsonb_agg(x), '[]'::jsonb)
  into v_dup
  from (
    select to_jsonb(
      case
        when mn.pay_batch_candidate_id is not null then ('PBC:' || mn.pay_batch_candidate_id::text)
        when mn.candidate_id is not null then ('CAND:' || mn.candidate_id::text)
        else ('WORKS:' || mn.works_norm)
      end
    ) as x
    from _tmp_manual_net mn
    group by
      case
        when mn.pay_batch_candidate_id is not null then ('PBC:' || mn.pay_batch_candidate_id::text)
        when mn.candidate_id is not null then ('CAND:' || mn.candidate_id::text)
        else ('WORKS:' || mn.works_norm)
      end
    having count(*) > 1
  ) d;

  if jsonb_array_length(v_dup) > 0 then
    raise exception 'MANUAL_NET_INVALID: duplicate entries %', v_dup::text;
  end if;

  create temp table if not exists _tmp_batch_paye2 (
    pay_batch_candidate_id uuid,
    candidate_id uuid,
    tms_ref_norm text,
    ni_norm text
  ) on commit drop;

  truncate table _tmp_batch_paye2;

  insert into _tmp_batch_paye2(pay_batch_candidate_id, candidate_id, tms_ref_norm, ni_norm)
  select
    pbc.id,
    pbc.candidate_id,
    upper(regexp_replace(btrim(coalesce(pbc.candidate_tms_ref, c.tms_ref, '')), '\s+', '', 'g')) as tms_ref_norm,
    upper(regexp_replace(btrim(coalesce(c.ni_number, '')), '\s+', '', 'g')) as ni_norm
  from public.pay_batch_candidates pbc
  join public.candidates c
    on c.id = pbc.candidate_id
  where pbc.pay_batch_id = p_pay_batch_id
    and pbc.paye_state is not null;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'works_number', a.works_norm,
        'candidate_ids', a.candidate_ids
      )
    ),
    '[]'::jsonb
  )
  into v_ambig
  from (
    select
      mn.works_norm,
      jsonb_agg(distinct bp.candidate_id::text order by bp.candidate_id::text) as candidate_ids
    from _tmp_manual_net mn
    join _tmp_batch_paye2 bp
      on mn.pay_batch_candidate_id is null
     and mn.candidate_id is null
     and mn.works_norm is not null
     and mn.works_norm <> ''
     and (
       (bp.tms_ref_norm is not null and bp.tms_ref_norm <> '' and bp.tms_ref_norm = mn.works_norm)
       or (bp.ni_norm is not null and bp.ni_norm <> '' and bp.ni_norm = mn.works_norm)
     )
    group by mn.works_norm
    having count(distinct bp.candidate_id) > 1
  ) a;

  if jsonb_array_length(v_ambig) > 0 then
    raise exception 'MANUAL_NET_INVALID: ambiguous Works Number(s) %', v_ambig::text;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'pay_batch_candidate_id', case when mn.pay_batch_candidate_id is null then null else mn.pay_batch_candidate_id::text end,
        'candidate_id', case when mn.candidate_id is null then null else mn.candidate_id::text end,
        'works_norm', mn.works_norm
      )
    ),
    '[]'::jsonb
  )
  into v_unmatched
  from _tmp_manual_net mn
  left join _tmp_batch_paye2 bp
    on (mn.pay_batch_candidate_id is not null and bp.pay_batch_candidate_id = mn.pay_batch_candidate_id)
    or (mn.pay_batch_candidate_id is null and mn.candidate_id is not null and bp.candidate_id = mn.candidate_id)
    or (
      mn.pay_batch_candidate_id is null
      and mn.candidate_id is null
      and mn.works_norm is not null
      and mn.works_norm <> ''
      and (
        (bp.tms_ref_norm is not null and bp.tms_ref_norm <> '' and bp.tms_ref_norm = mn.works_norm)
        or (bp.ni_norm is not null and bp.ni_norm <> '' and bp.ni_norm = mn.works_norm)
      )
    )
  where bp.pay_batch_candidate_id is null;

  if jsonb_array_length(v_unmatched) > 0 then
    raise exception 'MANUAL_NET_INVALID: entry candidate not found in pay batch PAYE candidates %', v_unmatched::text;
  end if;

  create temp table if not exists _tmp_manual_match (
    pay_batch_candidate_id uuid,
    net_amount numeric
  ) on commit drop;

  truncate table _tmp_manual_match;

  insert into _tmp_manual_match(pay_batch_candidate_id, net_amount)
  select
    bp.pay_batch_candidate_id,
    mn.net_amount
  from _tmp_manual_net mn
  join _tmp_batch_paye2 bp
    on mn.pay_batch_candidate_id is not null
   and bp.pay_batch_candidate_id = mn.pay_batch_candidate_id;

  insert into _tmp_manual_match(pay_batch_candidate_id, net_amount)
  select
    bp.pay_batch_candidate_id,
    mn.net_amount
  from _tmp_manual_net mn
  join _tmp_batch_paye2 bp
    on mn.pay_batch_candidate_id is null
   and mn.candidate_id is not null
   and bp.candidate_id = mn.candidate_id;

  insert into _tmp_manual_match(pay_batch_candidate_id, net_amount)
  select
    bp.pay_batch_candidate_id,
    mn.net_amount
  from _tmp_manual_net mn
  join _tmp_batch_paye2 bp
    on mn.pay_batch_candidate_id is null
   and mn.candidate_id is null
   and mn.works_norm is not null
   and mn.works_norm <> ''
   and (
     (bp.tms_ref_norm is not null and bp.tms_ref_norm <> '' and bp.tms_ref_norm = mn.works_norm)
     or (bp.ni_norm is not null and bp.ni_norm <> '' and bp.ni_norm = mn.works_norm)
   );

  if exists (
    select 1
    from _tmp_manual_match mm
    group by mm.pay_batch_candidate_id
    having count(*) > 1
    limit 1
  ) then
    raise exception 'MANUAL_NET_INVALID: duplicate resolved candidates in request (internal match collision)';
  end if;

  select count(*)::int
  into v_updated_count
  from _tmp_manual_match mm
  where mm.net_amount is not null;

  select count(*)::int
  into v_cleared_count
  from _tmp_manual_match mm
  where mm.net_amount is null;

  delete from public.pay_batch_paye_net_inputs pni
  using _tmp_manual_match mm
  where pni.pay_batch_candidate_id = mm.pay_batch_candidate_id
    and pni.source = 'MANUAL_ENTRY';

  insert into public.pay_batch_paye_net_inputs(
    pay_batch_candidate_id, source, net_amount, imported_at_utc, file_name, file_hash
  )
  select
    mm.pay_batch_candidate_id,
    'MANUAL_ENTRY',
    mm.net_amount,
    now(),
    null,
    null
  from _tmp_manual_match mm
  where mm.net_amount is not null;

  update public.pay_batch_candidates pbc
  set paye_state = case
    when exists (
      select 1
      from public.pay_batch_paye_net_inputs pni2
      where pni2.pay_batch_candidate_id = pbc.id
      limit 1
    ) then 'READY'
    else 'PENDING_NET'
  end
  where pbc.pay_batch_id = p_pay_batch_id
    and pbc.paye_state is not null;

  ---------------------------------------------------------------------------
  -- ✅ Recompute deductions + net_bank_amount (PAYE candidates only)
  ---------------------------------------------------------------------------
  create temp table if not exists _tmp_paye_scope (
    pay_batch_candidate_id uuid primary key,
    candidate_id uuid not null
  ) on commit drop;

  truncate table _tmp_paye_scope;

  insert into _tmp_paye_scope(pay_batch_candidate_id, candidate_id)
  select
    pbc3.id,
    pbc3.candidate_id
  from public.pay_batch_candidates pbc3
  where pbc3.pay_batch_id = p_pay_batch_id
    and pbc3.paye_state is not null;


  create temp table if not exists _tmp_recovery_templates (
    item_type text not null,
    pay_batch_candidate_id uuid not null,
    candidate_id uuid not null,
    finance_case_id uuid null,
    source_ref text null,
    pay_channel text null,
    umbrella_id uuid null,
    is_mismatch boolean null,
    paye_treatment text null,
    finance_component_id uuid null,
    frozen_component_snapshot_json jsonb null,
    frozen_component_key_type text null,
    frozen_component_key_value text null,
    frozen_component_classification public.pay_finance_component_classification_enum null,
    frozen_source_basis_json jsonb null,
    frozen_source_pay_method text null,
    frozen_target_pay_method text null,
    frozen_resolution_mode public.pay_finance_component_resolution_mode_enum null,
    frozen_resolution_payload_json jsonb null,
    frozen_resolution_result_json jsonb null,
    frozen_source_amount numeric(12,2) null,
    frozen_target_amount_ex_vat numeric(12,2) null,
    frozen_target_amount_vat numeric(12,2) null,
    frozen_target_amount_inc_vat numeric(12,2) null,
    payout_instruction_snapshot_json jsonb null,
    template_sort_at timestamptz null,
    sort_order integer not null,
    frozen_case_type text null,
    frozen_payout_status text null,
    frozen_remaining_source_amount numeric(12,2) not null,
    frozen_weekly_due_amount numeric(12,2) not null,
    frozen_next_due_week_start date null,
    minimum_earnings_threshold numeric(12,2) null,
    take_home_floor_override numeric(12,2) null,
    default_take_home_floor numeric(12,2) null
  ) on commit drop;

  truncate table _tmp_recovery_templates;

  insert into _tmp_recovery_templates (
    item_type,
    pay_batch_candidate_id,
    candidate_id,
    finance_case_id,
    source_ref,
    pay_channel,
    umbrella_id,
    is_mismatch,
    paye_treatment,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat,
    payout_instruction_snapshot_json,
    template_sort_at,
    sort_order,
    frozen_case_type,
    frozen_payout_status,
    frozen_remaining_source_amount,
    frozen_weekly_due_amount,
    frozen_next_due_week_start,
    minimum_earnings_threshold,
    take_home_floor_override,
    default_take_home_floor
  )
  select distinct on (
    pbi_rt.item_type,
    pbi_rt.pay_batch_candidate_id,
    coalesce(
      coalesce(
        pbi_rt.finance_case_id,
        case
          when pbi_rt.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi_rt.source_ref, 'advance:', '')::uuid
          else null::uuid
        end
      )::text,
      ''
    ),
    coalesce(pbi_rt.finance_component_id::text, ''),
    coalesce(pbi_rt.source_ref, '')
  )
    pbi_rt.item_type,
    pbi_rt.pay_batch_candidate_id,
    pbc_rt.candidate_id,
    coalesce(
      pbi_rt.finance_case_id,
      case
        when pbi_rt.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi_rt.source_ref, 'advance:', '')::uuid
        else null::uuid
      end
    ) as finance_case_id,
    pbi_rt.source_ref,
    pbi_rt.pay_channel,
    pbi_rt.umbrella_id,
    pbi_rt.is_mismatch,
    pbi_rt.paye_treatment,
    pbi_rt.finance_component_id,
    pbi_rt.frozen_component_snapshot_json,
    pbi_rt.frozen_component_key_type,
    pbi_rt.frozen_component_key_value,
    pbi_rt.frozen_component_classification,
    pbi_rt.frozen_source_basis_json,
    pbi_rt.frozen_source_pay_method,
    pbi_rt.frozen_target_pay_method,
    pbi_rt.frozen_resolution_mode,
    pbi_rt.frozen_resolution_payload_json,
    pbi_rt.frozen_resolution_result_json,
    round(coalesce(pbi_rt.frozen_source_amount, 0), 2)::numeric(12,2) as frozen_source_amount,
    round(coalesce(pbi_rt.frozen_target_amount_ex_vat, 0), 2)::numeric(12,2) as frozen_target_amount_ex_vat,
    round(coalesce(pbi_rt.frozen_target_amount_vat, 0), 2)::numeric(12,2) as frozen_target_amount_vat,
    round(coalesce(pbi_rt.frozen_target_amount_inc_vat, 0), 2)::numeric(12,2) as frozen_target_amount_inc_vat,
    pbi_rt.payout_instruction_snapshot_json,
    coalesce(pbi_rt.created_at, pbi_rt.updated_at, now()) as template_sort_at,
    case
      when nullif(btrim(coalesce(pbi_rt.frozen_source_basis_json->>'allocation_priority_order', pbi_rt.frozen_source_basis_json->>'sort_order', pbi_rt.frozen_resolution_payload_json->>'sort_order')), '') ~ '^-?[0-9]+$'
        then (coalesce(pbi_rt.frozen_source_basis_json->>'allocation_priority_order', pbi_rt.frozen_source_basis_json->>'sort_order', pbi_rt.frozen_resolution_payload_json->>'sort_order'))::integer
      else 2147483647
    end as sort_order,
    upper(coalesce(
      nullif(btrim(pbi_rt.frozen_source_basis_json->>'case_type'), ''),
      case pbi_rt.item_type
        when 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT'
        when 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE'
        when 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_ADJUSTMENT'
        else null
      end
    )) as frozen_case_type,
    upper(nullif(btrim(pbi_rt.frozen_source_basis_json->>'payout_status'), '')) as frozen_payout_status,
    round(greatest(
      coalesce(
        case
          when nullif(btrim(pbi_rt.frozen_component_snapshot_json->>'remaining_source_amount'), '') is not null then (pbi_rt.frozen_component_snapshot_json->>'remaining_source_amount')::numeric
          when nullif(btrim(pbi_rt.frozen_source_basis_json->>'remaining_source_amount'), '') is not null then (pbi_rt.frozen_source_basis_json->>'remaining_source_amount')::numeric
          when nullif(btrim(pbi_rt.frozen_source_basis_json->>'outstanding_amount'), '') is not null then (pbi_rt.frozen_source_basis_json->>'outstanding_amount')::numeric
          when nullif(btrim(pbi_rt.frozen_source_basis_json->>'amount'), '') is not null then abs((pbi_rt.frozen_source_basis_json->>'amount')::numeric)
          when pbi_rt.frozen_source_amount is not null then abs(pbi_rt.frozen_source_amount)
          else 0::numeric
        end,
        0::numeric
      ),
      0::numeric
    ), 2)::numeric(12,2) as frozen_remaining_source_amount,
    case
      when nullif(btrim(pbi_rt.frozen_source_basis_json->>'weekly_due'), '') is null then 0::numeric(12,2)
      else round(greatest(abs((pbi_rt.frozen_source_basis_json->>'weekly_due')::numeric), 0), 2)::numeric(12,2)
    end as frozen_weekly_due_amount,
    case
      when nullif(btrim(pbi_rt.frozen_source_basis_json->>'next_due_week_start'), '') is null then null::date
      else (pbi_rt.frozen_source_basis_json->>'next_due_week_start')::date
    end as frozen_next_due_week_start,
    case
      when nullif(btrim(pbi_rt.frozen_source_basis_json->>'minimum_earnings_threshold'), '') is null then null::numeric(12,2)
      else round(greatest((pbi_rt.frozen_source_basis_json->>'minimum_earnings_threshold')::numeric, 0), 2)::numeric(12,2)
    end as minimum_earnings_threshold,
    case
      when nullif(btrim(pbi_rt.frozen_source_basis_json->>'take_home_floor_override'), '') is null then null::numeric(12,2)
      else round(greatest((pbi_rt.frozen_source_basis_json->>'take_home_floor_override')::numeric, 0), 2)::numeric(12,2)
    end as take_home_floor_override,
    case
      when nullif(btrim(pbi_rt.frozen_source_basis_json->>'default_take_home_floor'), '') is null then null::numeric(12,2)
      else round(greatest((pbi_rt.frozen_source_basis_json->>'default_take_home_floor')::numeric, 0), 2)::numeric(12,2)
    end as default_take_home_floor
  from public.pay_batch_items pbi_rt
  join public.pay_batch_candidates pbc_rt
    on pbc_rt.id = pbi_rt.pay_batch_candidate_id
  where pbc_rt.pay_batch_id = p_pay_batch_id
    and pbi_rt.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY')
  order by
    pbi_rt.item_type,
    pbi_rt.pay_batch_candidate_id,
    coalesce(
      coalesce(
        pbi_rt.finance_case_id,
        case
          when pbi_rt.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi_rt.source_ref, 'advance:', '')::uuid
          else null::uuid
        end
      )::text,
      ''
    ),
    coalesce(pbi_rt.finance_component_id::text, ''),
    coalesce(pbi_rt.source_ref, ''),
    pbi_rt.is_voided desc,
    coalesce(pbi_rt.updated_at, pbi_rt.created_at) desc,
    pbi_rt.id desc;

  -- PAYE net is produced after gross-side deductions have already been sent
  -- through payroll. Reproject only net-side deductions here; the frozen gross
  -- items and their reservations must remain unchanged.
  create temp table if not exists _tmp_manual_debt_item_ids (
    id uuid primary key
  ) on commit drop;

  truncate table _tmp_manual_debt_item_ids;

  insert into _tmp_manual_debt_item_ids(id)
  select
    pbi_md_del.id
  from public.pay_batch_items pbi_md_del
  where pbi_md_del.pay_batch_candidate_id in (select sc_md_del.pay_batch_candidate_id from _tmp_paye_scope sc_md_del)
    and pbi_md_del.item_type = 'MANUAL_DEBT_RECOVERY'
    and upper(coalesce(pbi_md_del.paye_treatment, 'NET_DEDUCT')) not in ('GROSS_DEDUCT', 'GROSS_DEDUCTION', 'DEDUCT_GROSS')
    and pbi_md_del.is_voided = false;

  create temp table if not exists _tmp_ded_item_ids (
    id uuid primary key
  ) on commit drop;

  truncate table _tmp_ded_item_ids;

  insert into _tmp_ded_item_ids(id)
  select
    pbi_del.id
  from public.pay_batch_items pbi_del
  where pbi_del.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
    and pbi_del.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT')
    and upper(coalesce(pbi_del.paye_treatment, 'NET_DEDUCT')) not in ('GROSS_DEDUCT', 'GROSS_DEDUCTION', 'DEDUCT_GROSS')
    and pbi_del.is_voided = false;

  delete from public.pay_batch_item_breakdowns pbib_del
  using _tmp_ded_item_ids di
  where pbib_del.pay_batch_item_id = di.id;

  get diagnostics v_deleted_ded_breakdowns = row_count;

  delete from public.pay_batch_item_breakdowns pbib_md_del
  using _tmp_manual_debt_item_ids mdi_del
  where pbib_md_del.pay_batch_item_id = mdi_del.id;

  get diagnostics v_deleted_manual_debt_breakdowns = row_count;

  update public.pay_advance_reservations par_del
  set
    status = 'RELEASED',
    released_at_utc = now(),
    released_reason = 'PAYE_NET_REPROJECTION',
    updated_by_user_id = p_actor_user_id
  where par_del.pay_batch_item_id in (select di_res.id from _tmp_ded_item_ids di_res)
    and par_del.status = 'RESERVED';

  get diagnostics v_deleted_ded_reservations = row_count;

  update public.pay_advance_reservations par_md
  set
    status = 'RELEASED',
    released_at_utc = now(),
    released_reason = 'PAYE_NET_REPROJECTION',
    updated_by_user_id = p_actor_user_id
  where par_md.pay_batch_item_id in (select mdi_res.id from _tmp_manual_debt_item_ids mdi_res)
    and par_md.status = 'RESERVED';

  get diagnostics v_released_manual_debt_reservations = row_count;

  update public.pay_batch_items pbi_d_void
  set
    is_voided = true,
    reservation_id = null,
    updated_at = now()
  where pbi_d_void.id in (select di_void.id from _tmp_ded_item_ids di_void)
    and pbi_d_void.is_voided = false;

  v_deleted_ded_items := 0;

  update public.pay_batch_items pbi_md_void
  set
    is_voided = true,
    reservation_id = null,
    updated_at = now()
  where pbi_md_void.id in (select mdi_void.id from _tmp_manual_debt_item_ids mdi_void)
    and pbi_md_void.is_voided = false;

  get diagnostics v_voided_manual_debt_items = row_count;

  update public.pay_batch_candidates pbc_aw
  set
    awaiting_net_amount = not exists (
      select 1
      from public.pay_batch_paye_net_inputs pni_aw
      where pni_aw.pay_batch_candidate_id = pbc_aw.id
      limit 1
    ),
    updated_at = now()
  where pbc_aw.id in (select s.pay_batch_candidate_id from _tmp_paye_scope s);

  with ins_overpay as (
    insert into public.pay_batch_items (
      id,
      pay_batch_candidate_id,
      item_type,
      timesheet_id,
      segment_key,
      source_ref,
      amount_ex_vat,
      amount_vat,
      amount_inc_vat,
      repayment_week_start,
      pay_channel,
      umbrella_id,
      is_mismatch,
      is_voided,
      created_at,
      updated_at,
      finance_case_id,
      reservation_id,
      paye_treatment,
      finance_component_id,
      frozen_component_snapshot_json,
      frozen_component_key_type,
      frozen_component_key_value,
      frozen_component_classification,
      frozen_source_basis_json,
      frozen_source_pay_method,
      frozen_target_pay_method,
      frozen_resolution_mode,
      frozen_resolution_payload_json,
      frozen_resolution_result_json,
      frozen_source_amount,
      frozen_target_amount_ex_vat,
      frozen_target_amount_vat,
      frozen_target_amount_inc_vat,
      payout_instruction_snapshot_json
    )
    with cand_scope as (
      select
        pbc.id as pay_batch_candidate_id,
        pbc.candidate_id,
        pbc.awaiting_net_amount,
        greatest(coalesce(ni.net_amount, 0), 0)::numeric(12,2) as paye_net_amount
      from public.pay_batch_candidates pbc
      join _tmp_paye_scope sc
        on sc.pay_batch_candidate_id = pbc.id
      left join lateral (
        select pni.net_amount
        from public.pay_batch_paye_net_inputs pni
        where pni.pay_batch_candidate_id = pbc.id
        order by pni.imported_at_utc desc
        limit 1
      ) ni on true
    ),
    case_templates as (
      select distinct on (rt.pay_batch_candidate_id, rt.finance_case_id, coalesce(rt.finance_component_id::text, ''), coalesce(rt.source_ref, ''))
        rt.*
      from _tmp_recovery_templates rt
      where rt.item_type = 'OVERPAYMENT_RECOVERY'
        and rt.finance_case_id is not null
        and upper(coalesce(rt.paye_treatment, 'NET_DEDUCT')) not in ('GROSS_DEDUCT', 'GROSS_DEDUCTION', 'DEDUCT_GROSS')
      order by
        rt.pay_batch_candidate_id,
        rt.finance_case_id,
        coalesce(rt.finance_component_id::text, ''),
        coalesce(rt.source_ref, ''),
        rt.sort_order,
        rt.template_sort_at,
        rt.finance_component_id nulls last,
        rt.source_ref nulls last
    ),
    alloc_base as (
      select
        cs.pay_batch_candidate_id,
        ct.finance_case_id,
        ct.source_ref,
        ct.pay_channel,
        ct.umbrella_id,
        ct.is_mismatch,
        ct.paye_treatment,
        ct.finance_component_id,
        ct.frozen_component_snapshot_json,
        ct.frozen_component_key_type,
        ct.frozen_component_key_value,
        ct.frozen_component_classification,
        ct.frozen_source_basis_json,
        ct.frozen_source_pay_method,
        ct.frozen_target_pay_method,
        ct.frozen_resolution_mode,
        ct.frozen_resolution_payload_json,
        ct.frozen_resolution_result_json,
        ct.frozen_source_amount,
        ct.frozen_target_amount_ex_vat,
        ct.frozen_target_amount_vat,
        ct.frozen_target_amount_inc_vat,
        ct.payout_instruction_snapshot_json,
        ct.frozen_remaining_source_amount,
        ct.sort_order,
        ct.template_sort_at,
        cs.paye_net_amount as available_pool_ex,
        sum(ct.frozen_remaining_source_amount) over (
          partition by cs.pay_batch_candidate_id
          order by ct.sort_order, ct.template_sort_at, ct.finance_case_id, ct.finance_component_id, coalesce(ct.source_ref, '')
          rows between unbounded preceding and 1 preceding
        )::numeric(12,2) as cum_before_ex
      from cand_scope cs
      join case_templates ct
        on ct.pay_batch_candidate_id = cs.pay_batch_candidate_id
      where cs.awaiting_net_amount = false
        and ct.frozen_remaining_source_amount > 0
        and upper(coalesce(ct.frozen_case_type, 'OVERPAYMENT')) = 'OVERPAYMENT'
    ),
    alloc as (
      select
        ab.*,
        round(
          least(
            ab.frozen_remaining_source_amount,
            greatest(ab.available_pool_ex - coalesce(ab.cum_before_ex, 0), 0)
          ),
          2
        )::numeric(12,2) as take_ex
      from alloc_base ab
    )
    select
      gen_random_uuid() as id,
      a.pay_batch_candidate_id,
      'OVERPAYMENT_RECOVERY' as item_type,
      null::uuid as timesheet_id,
      null::text as segment_key,
      coalesce(a.source_ref, 'advance:' || a.finance_case_id::text) as source_ref,
      round(-a.take_ex, 2)::numeric(12,2) as amount_ex_vat,
      0::numeric(12,2) as amount_vat,
      round(-a.take_ex, 2)::numeric(12,2) as amount_inc_vat,
      v_week_start as repayment_week_start,
      coalesce(a.pay_channel, 'PAYE') as pay_channel,
      a.umbrella_id,
      coalesce(a.is_mismatch, false) as is_mismatch,
      false as is_voided,
      now() as created_at,
      now() as updated_at,
      a.finance_case_id,
      null::uuid as reservation_id,
      coalesce(a.paye_treatment, 'NET_DEDUCT') as paye_treatment,
      a.finance_component_id,
      a.frozen_component_snapshot_json,
      a.frozen_component_key_type,
      a.frozen_component_key_value,
      a.frozen_component_classification,
      a.frozen_source_basis_json,
      a.frozen_source_pay_method,
      coalesce(a.frozen_target_pay_method, coalesce(a.pay_channel, 'PAYE')) as frozen_target_pay_method,
      a.frozen_resolution_mode,
      a.frozen_resolution_payload_json,
      jsonb_strip_nulls(
        coalesce(a.frozen_resolution_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'target_amount_ex_vat', round(-a.take_ex, 2),
          'target_amount_vat', 0,
          'target_amount_inc_vat', round(-a.take_ex, 2)
        )
      ) as frozen_resolution_result_json,
      round(coalesce(a.take_ex, 0), 2)::numeric(12,2) as frozen_source_amount,
      round(-a.take_ex, 2)::numeric(12,2) as frozen_target_amount_ex_vat,
      0::numeric(12,2) as frozen_target_amount_vat,
      round(-a.take_ex, 2)::numeric(12,2) as frozen_target_amount_inc_vat,
      a.payout_instruction_snapshot_json
    from alloc a
    where a.take_ex > 0
    returning id, amount_ex_vat, amount_vat, amount_inc_vat
  )
  insert into public.pay_batch_item_breakdowns(
    pay_batch_item_id,
    line_kind,
    bucket_code,
    unit_name,
    units,
    rate,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    meta_json
  )
  select
    io.id,
    'OVERPAYMENT_RECOVERY',
    null,
    'Overpayment recovery',
    null::numeric,
    null::numeric,
    io.amount_ex_vat,
    io.amount_vat,
    io.amount_inc_vat,
    '{}'::jsonb
  from ins_overpay io;

  get diagnostics v_ins_overpay_bd = row_count;

  select count(*)::int
  into v_ins_overpay
  from public.pay_batch_items pbi_ct
  where pbi_ct.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
    and pbi_ct.item_type = 'OVERPAYMENT_RECOVERY'
    and pbi_ct.is_voided = false
    and pbi_ct.repayment_week_start = v_week_start;

  with ins_loan as (
    insert into public.pay_batch_items (
      id,
      pay_batch_candidate_id,
      item_type,
      timesheet_id,
      segment_key,
      source_ref,
      amount_ex_vat,
      amount_vat,
      amount_inc_vat,
      repayment_week_start,
      pay_channel,
      umbrella_id,
      is_mismatch,
      is_voided,
      created_at,
      updated_at,
      finance_case_id,
      reservation_id,
      paye_treatment,
      finance_component_id,
      frozen_component_snapshot_json,
      frozen_component_key_type,
      frozen_component_key_value,
      frozen_component_classification,
      frozen_source_basis_json,
      frozen_source_pay_method,
      frozen_target_pay_method,
      frozen_resolution_mode,
      frozen_resolution_payload_json,
      frozen_resolution_result_json,
      frozen_source_amount,
      frozen_target_amount_ex_vat,
      frozen_target_amount_vat,
      frozen_target_amount_inc_vat,
      payout_instruction_snapshot_json
    )
    with cand_scope as (
      select
        pbc.id as pay_batch_candidate_id,
        pbc.candidate_id,
        pbc.awaiting_net_amount,
        greatest(coalesce(ni.net_amount, 0), 0)::numeric(12,2) as paye_net_amount
      from public.pay_batch_candidates pbc
      join _tmp_paye_scope sc
        on sc.pay_batch_candidate_id = pbc.id
      left join lateral (
        select pni.net_amount
        from public.pay_batch_paye_net_inputs pni
        where pni.pay_batch_candidate_id = pbc.id
        order by pni.imported_at_utc desc
        limit 1
      ) ni on true
    ),
    overpay_current as (
      select
        pbi.pay_batch_candidate_id,
        round(sum(-pbi.amount_ex_vat), 2)::numeric(12,2) as overpayment_recovery_taken_ex
      from public.pay_batch_items pbi
      where pbi.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
        and pbi.is_voided = false
        and pbi.item_type = 'OVERPAYMENT_RECOVERY'
        and upper(coalesce(pbi.paye_treatment, 'NET_DEDUCT')) not in ('GROSS_DEDUCT', 'GROSS_DEDUCTION', 'DEDUCT_GROSS')
        and pbi.repayment_week_start = v_week_start
      group by pbi.pay_batch_candidate_id
    ),
    case_templates as (
      select distinct on (rt.pay_batch_candidate_id, rt.finance_case_id, coalesce(rt.finance_component_id::text, ''), coalesce(rt.source_ref, ''))
        rt.*
      from _tmp_recovery_templates rt
      where rt.item_type = 'LOAN_REPAYMENT'
        and rt.finance_case_id is not null
        and upper(coalesce(rt.paye_treatment, 'NET_DEDUCT')) not in ('GROSS_DEDUCT', 'GROSS_DEDUCTION', 'DEDUCT_GROSS')
      order by
        rt.pay_batch_candidate_id,
        rt.finance_case_id,
        coalesce(rt.finance_component_id::text, ''),
        coalesce(rt.source_ref, ''),
        rt.sort_order,
        rt.template_sort_at,
        rt.finance_component_id nulls last,
        rt.source_ref nulls last
    ),
    loan_seed as (
      select
        cs.pay_batch_candidate_id,
        cs.candidate_id,
        ct.finance_case_id,
        ct.source_ref,
        ct.pay_channel,
        ct.umbrella_id,
        ct.is_mismatch,
        ct.paye_treatment,
        ct.finance_component_id,
        ct.frozen_component_snapshot_json,
        ct.frozen_component_key_type,
        ct.frozen_component_key_value,
        ct.frozen_component_classification,
        ct.frozen_source_basis_json,
        ct.frozen_source_pay_method,
        ct.frozen_target_pay_method,
        ct.frozen_resolution_mode,
        ct.frozen_resolution_payload_json,
        ct.frozen_resolution_result_json,
        ct.frozen_source_amount,
        ct.frozen_target_amount_ex_vat,
        ct.frozen_target_amount_vat,
        ct.frozen_target_amount_inc_vat,
        ct.payout_instruction_snapshot_json,
        ct.frozen_remaining_source_amount,
        ct.sort_order,
        ct.template_sort_at,
        round(greatest(least(coalesce(ct.frozen_weekly_due_amount, ct.frozen_remaining_source_amount, 0::numeric(12,2)), ct.frozen_remaining_source_amount), 0), 2)::numeric(12,2) as nominal_due_amount,
        ct.minimum_earnings_threshold,
        ct.take_home_floor_override,
        round(greatest(cs.paye_net_amount - coalesce(oc.overpayment_recovery_taken_ex, 0), 0), 2)::numeric(12,2) as run_earnings_headroom_ex,
        round(greatest(cs.paye_net_amount - coalesce(oc.overpayment_recovery_taken_ex, 0), 0), 2)::numeric(12,2) as run_take_home_before_ex
      from cand_scope cs
      join case_templates ct
        on ct.pay_batch_candidate_id = cs.pay_batch_candidate_id
      left join overpay_current oc
        on oc.pay_batch_candidate_id = cs.pay_batch_candidate_id
      where cs.awaiting_net_amount = false
        and ct.frozen_remaining_source_amount > 0
        and upper(coalesce(ct.frozen_case_type, 'PAYMENT_ADVANCE')) = 'PAYMENT_ADVANCE'
        and upper(coalesce(ct.frozen_payout_status, 'PAID')) = 'PAID'
        and (ct.frozen_next_due_week_start is null or ct.frozen_next_due_week_start <= v_week_start)
        and round(greatest(least(coalesce(ct.frozen_weekly_due_amount, ct.frozen_remaining_source_amount, 0::numeric(12,2)), ct.frozen_remaining_source_amount), 0), 2) > 0
    ),
    loan_inputs as (
      select
        ls.pay_batch_candidate_id,
        ls.candidate_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'sort_order', ls.sort_order,
              'finance_case_id', ls.finance_case_id::text,
              'case_type', 'PAYMENT_ADVANCE',
              'payout_status', 'PAID',
              'nominal_due_amount', ls.nominal_due_amount,
              'minimum_earnings_threshold', ls.minimum_earnings_threshold,
              'take_home_floor_override', ls.take_home_floor_override
            )
            order by ls.sort_order, ls.template_sort_at, ls.finance_case_id
          ),
          '[]'::jsonb
        ) as recovery_rows_json,
        max(ls.run_earnings_headroom_ex)::numeric(12,2) as run_earnings_headroom_ex,
        max(ls.run_take_home_before_ex)::numeric(12,2) as run_take_home_before_ex
      from loan_seed ls
      group by ls.pay_batch_candidate_id, ls.candidate_id
    ),
    loan_alloc as (
      select
        li.pay_batch_candidate_id,
        li.candidate_id,
        lra.finance_case_id,
        round(coalesce(lra.protected_recoverable_amount, 0), 2)::numeric(12,2) as take_ex
      from loan_inputs li
      cross join lateral public._pay_finance_protected_recovery_allocate(
        li.recovery_rows_json,
        li.run_earnings_headroom_ex,
        li.run_take_home_before_ex,
        null::numeric
      ) lra
    )
    select
      gen_random_uuid() as id,
      ct.pay_batch_candidate_id,
      'LOAN_REPAYMENT' as item_type,
      null::uuid as timesheet_id,
      null::text as segment_key,
      coalesce(ct.source_ref, 'advance:' || la.finance_case_id::text) as source_ref,
      round(-la.take_ex, 2)::numeric(12,2) as amount_ex_vat,
      0::numeric(12,2) as amount_vat,
      round(-la.take_ex, 2)::numeric(12,2) as amount_inc_vat,
      v_week_start as repayment_week_start,
      coalesce(ct.pay_channel, 'PAYE') as pay_channel,
      ct.umbrella_id,
      coalesce(ct.is_mismatch, false) as is_mismatch,
      false as is_voided,
      now() as created_at,
      now() as updated_at,
      la.finance_case_id,
      null::uuid as reservation_id,
      coalesce(ct.paye_treatment, 'NET_DEDUCT') as paye_treatment,
      ct.finance_component_id,
      ct.frozen_component_snapshot_json,
      ct.frozen_component_key_type,
      ct.frozen_component_key_value,
      ct.frozen_component_classification,
      ct.frozen_source_basis_json,
      ct.frozen_source_pay_method,
      coalesce(ct.frozen_target_pay_method, coalesce(ct.pay_channel, 'PAYE')) as frozen_target_pay_method,
      ct.frozen_resolution_mode,
      ct.frozen_resolution_payload_json,
      jsonb_strip_nulls(
        coalesce(ct.frozen_resolution_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'target_amount_ex_vat', round(-la.take_ex, 2),
          'target_amount_vat', 0,
          'target_amount_inc_vat', round(-la.take_ex, 2)
        )
      ) as frozen_resolution_result_json,
      round(coalesce(la.take_ex, 0), 2)::numeric(12,2) as frozen_source_amount,
      round(-la.take_ex, 2)::numeric(12,2) as frozen_target_amount_ex_vat,
      0::numeric(12,2) as frozen_target_amount_vat,
      round(-la.take_ex, 2)::numeric(12,2) as frozen_target_amount_inc_vat,
      ct.payout_instruction_snapshot_json
    from loan_alloc la
    join case_templates ct
      on ct.pay_batch_candidate_id = la.pay_batch_candidate_id
     and ct.finance_case_id = la.finance_case_id
    where round(coalesce(la.take_ex, 0), 2) > 0
    returning id, amount_ex_vat, amount_vat, amount_inc_vat
  )
  insert into public.pay_batch_item_breakdowns(
    pay_batch_item_id,
    line_kind,
    bucket_code,
    unit_name,
    units,
    rate,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    meta_json
  )
  select
    il.id,
    'LOAN_REPAYMENT',
    null,
    'Loan repayment',
    null::numeric,
    null::numeric,
    il.amount_ex_vat,
    il.amount_vat,
    il.amount_inc_vat,
    '{}'::jsonb
  from ins_loan il;

  get diagnostics v_ins_loan_bd = row_count;

  select count(*)::int
  into v_ins_loan
  from public.pay_batch_items pbi_ct2
  where pbi_ct2.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
    and pbi_ct2.item_type = 'LOAN_REPAYMENT'
    and pbi_ct2.is_voided = false
    and pbi_ct2.repayment_week_start = v_week_start;

  with manual_debt_scope as (
    select
      pbc_md.id as pay_batch_candidate_id,
      pbc_md.candidate_id,
      round(greatest(coalesce(pbc_md.gross_preview, 0), 0), 2)::numeric(12,2) as run_earnings_headroom_ex,
      round(
        greatest(
          coalesce(pni_md.net_amount, 0)
          - coalesce((
              select round(sum(-pbi_ov.amount_ex_vat), 2)
              from public.pay_batch_items pbi_ov
              where pbi_ov.pay_batch_candidate_id = pbc_md.id
                and pbi_ov.is_voided = false
                and pbi_ov.item_type = 'OVERPAYMENT_RECOVERY'
                and upper(coalesce(pbi_ov.paye_treatment, 'NET_DEDUCT')) not in ('GROSS_DEDUCT', 'GROSS_DEDUCTION', 'DEDUCT_GROSS')
                and pbi_ov.repayment_week_start = v_week_start
            ), 0)
          - coalesce((
              select round(sum(-pbi_ln.amount_ex_vat), 2)
              from public.pay_batch_items pbi_ln
              where pbi_ln.pay_batch_candidate_id = pbc_md.id
                and pbi_ln.is_voided = false
                and pbi_ln.item_type = 'LOAN_REPAYMENT'
                and upper(coalesce(pbi_ln.paye_treatment, 'NET_DEDUCT')) not in ('GROSS_DEDUCT', 'GROSS_DEDUCTION', 'DEDUCT_GROSS')
                and pbi_ln.repayment_week_start = v_week_start
            ), 0),
          0
        ),
        2
      )::numeric(12,2) as run_take_home_before_ex,
      round(greatest(coalesce((
        select max(rt.default_take_home_floor)
        from _tmp_recovery_templates rt
        where rt.pay_batch_candidate_id = pbc_md.id
          and rt.item_type = 'MANUAL_DEBT_RECOVERY'
      ), 0), 0), 2)::numeric(12,2) as default_take_home_floor
    from public.pay_batch_candidates pbc_md
    join _tmp_paye_scope sc_md
      on sc_md.pay_batch_candidate_id = pbc_md.id
    left join lateral (
      select pni_md_inner.net_amount
      from public.pay_batch_paye_net_inputs pni_md_inner
      where pni_md_inner.pay_batch_candidate_id = pbc_md.id
      order by pni_md_inner.imported_at_utc desc
      limit 1
    ) pni_md on true
    where pbc_md.awaiting_net_amount = false
  ),
  manual_debt_case_templates as (
    select distinct on (rt.pay_batch_candidate_id, rt.finance_case_id, coalesce(rt.finance_component_id::text, ''), coalesce(rt.source_ref, ''))
      rt.*
    from _tmp_recovery_templates rt
    where rt.item_type = 'MANUAL_DEBT_RECOVERY'
      and rt.finance_case_id is not null
      and upper(coalesce(rt.paye_treatment, 'NET_DEDUCT')) not in ('GROSS_DEDUCT', 'GROSS_DEDUCTION', 'DEDUCT_GROSS')
    order by
      rt.pay_batch_candidate_id,
      rt.finance_case_id,
      coalesce(rt.finance_component_id::text, ''),
      coalesce(rt.source_ref, ''),
      rt.sort_order,
      rt.template_sort_at,
      rt.finance_component_id nulls last,
      rt.source_ref nulls last
  ),
  manual_debt_template_values as (
    select
      mds.pay_batch_candidate_id,
      mds.candidate_id,
      mdt.finance_case_id,
      mdt.template_sort_at,
      mds.run_earnings_headroom_ex,
      mds.run_take_home_before_ex,
      nullif(mds.default_take_home_floor, 0)::numeric(12,2) as default_take_home_floor,
      upper(coalesce(mdt.frozen_case_type, 'MANUAL_DEBT_ADJUSTMENT')) as frozen_case_type,
      mdt.frozen_next_due_week_start,
      mdt.minimum_earnings_threshold,
      mdt.take_home_floor_override,
      mdt.frozen_weekly_due_amount,
      mdt.frozen_remaining_source_amount,
      mdt.sort_order,
      sched_md.scheduled_due_amount,
      mdt.source_ref,
      mdt.pay_channel,
      mdt.umbrella_id,
      mdt.is_mismatch,
      mdt.paye_treatment,
      mdt.finance_component_id,
      mdt.frozen_component_snapshot_json,
      mdt.frozen_component_key_type,
      mdt.frozen_component_key_value,
      mdt.frozen_component_classification,
      mdt.frozen_source_basis_json,
      mdt.frozen_source_pay_method,
      mdt.frozen_target_pay_method,
      mdt.frozen_resolution_mode,
      mdt.frozen_resolution_payload_json,
      mdt.frozen_resolution_result_json,
      mdt.frozen_source_amount,
      mdt.frozen_target_amount_ex_vat,
      mdt.frozen_target_amount_vat,
      mdt.frozen_target_amount_inc_vat,
      mdt.payout_instruction_snapshot_json
    from manual_debt_scope mds
    join manual_debt_case_templates mdt
      on mdt.pay_batch_candidate_id = mds.pay_batch_candidate_id
    left join lateral (
      select
        round(greatest(abs((sched_item.value->>'amount')::numeric), 0), 2)::numeric(12,2) as scheduled_due_amount
      from jsonb_array_elements(
        case
          when jsonb_typeof(coalesce(mdt.frozen_source_basis_json->'schedule_json', '[]'::jsonb)) = 'array'
            then coalesce(mdt.frozen_source_basis_json->'schedule_json', '[]'::jsonb)
          else '[]'::jsonb
        end
      ) as sched_item(value)
      where nullif(btrim(sched_item.value->>'week_start'), '') is not null
        and (sched_item.value->>'week_start')::date = v_week_start
      limit 1
    ) sched_md on true
  ),
  manual_debt_seed as (
    select
      mdtv.pay_batch_candidate_id,
      mdtv.candidate_id,
      mdtv.finance_case_id,
      mdtv.template_sort_at,
      mdtv.sort_order,
      round(
        greatest(
          least(
            coalesce(mdtv.scheduled_due_amount, mdtv.frozen_weekly_due_amount, 0::numeric(12,2)),
            mdtv.frozen_remaining_source_amount
          ),
          0
        ),
        2
      )::numeric(12,2) as nominal_due_amount,
      mdtv.minimum_earnings_threshold,
      mdtv.take_home_floor_override,
      mdtv.run_earnings_headroom_ex,
      mdtv.run_take_home_before_ex,
      mdtv.default_take_home_floor
    from manual_debt_template_values mdtv
    where mdtv.frozen_case_type = 'MANUAL_DEBT_ADJUSTMENT'
      and mdtv.frozen_remaining_source_amount > 0
      and (mdtv.frozen_next_due_week_start is null or mdtv.frozen_next_due_week_start <= v_week_start)
      and round(
        greatest(
          least(
            coalesce(mdtv.scheduled_due_amount, mdtv.frozen_weekly_due_amount, 0::numeric(12,2)),
            mdtv.frozen_remaining_source_amount
          ),
          0
        ),
        2
      ) > 0
  ),
  manual_debt_inputs as (
    select
      mds.candidate_id,
      mds.pay_batch_candidate_id,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'sort_order', mds.sort_order,
            'finance_case_id', mds.finance_case_id::text,
            'case_type', 'MANUAL_DEBT_ADJUSTMENT',
            'payout_status', null,
            'nominal_due_amount', mds.nominal_due_amount,
            'minimum_earnings_threshold', mds.minimum_earnings_threshold,
            'take_home_floor_override', mds.take_home_floor_override
          )
          order by mds.sort_order, mds.template_sort_at, mds.finance_case_id
        ),
        '[]'::jsonb
      ) as recovery_rows_json,
      max(mds.run_earnings_headroom_ex)::numeric(12,2) as run_earnings_headroom_ex,
      max(mds.run_take_home_before_ex)::numeric(12,2) as run_take_home_before_ex,
      nullif(max(mds.default_take_home_floor), 0)::numeric(12,2) as default_take_home_floor
    from manual_debt_seed mds
    group by mds.candidate_id, mds.pay_batch_candidate_id
  ),
  manual_debt_alloc as (
    select
      mdi.pay_batch_candidate_id,
      mdi.candidate_id,
      mdra.finance_case_id,
      round(coalesce(mdra.protected_recoverable_amount, 0), 2)::numeric(12,2) as take_ex
    from manual_debt_inputs mdi
    cross join lateral public._pay_finance_protected_recovery_allocate(
      mdi.recovery_rows_json,
      mdi.run_earnings_headroom_ex,
      mdi.run_take_home_before_ex,
      mdi.default_take_home_floor
    ) mdra
  ),
  ins_manual_debt as (
    insert into public.pay_batch_items (
      id,
      pay_batch_candidate_id,
      item_type,
      timesheet_id,
      segment_key,
      source_ref,
      amount_ex_vat,
      amount_vat,
      amount_inc_vat,
      repayment_week_start,
      pay_channel,
      umbrella_id,
      is_mismatch,
      is_voided,
      created_at,
      updated_at,
      finance_case_id,
      reservation_id,
      paye_treatment,
      finance_component_id,
      frozen_component_snapshot_json,
      frozen_component_key_type,
      frozen_component_key_value,
      frozen_component_classification,
      frozen_source_basis_json,
      frozen_source_pay_method,
      frozen_target_pay_method,
      frozen_resolution_mode,
      frozen_resolution_payload_json,
      frozen_resolution_result_json,
      frozen_source_amount,
      frozen_target_amount_ex_vat,
      frozen_target_amount_vat,
      frozen_target_amount_inc_vat,
      payout_instruction_snapshot_json
    )
    select
      gen_random_uuid() as id,
      mdt.pay_batch_candidate_id,
      'MANUAL_DEBT_RECOVERY' as item_type,
      null::uuid as timesheet_id,
      null::text as segment_key,
      coalesce(mdt.source_ref, 'advance:' || mda.finance_case_id::text) as source_ref,
      round(-mda.take_ex, 2)::numeric(12,2) as amount_ex_vat,
      0::numeric(12,2) as amount_vat,
      round(-mda.take_ex, 2)::numeric(12,2) as amount_inc_vat,
      v_week_start as repayment_week_start,
      coalesce(mdt.pay_channel, 'PAYE') as pay_channel,
      mdt.umbrella_id,
      coalesce(mdt.is_mismatch, false) as is_mismatch,
      false as is_voided,
      now() as created_at,
      now() as updated_at,
      mda.finance_case_id,
      null::uuid as reservation_id,
      coalesce(mdt.paye_treatment, 'NET_DEDUCT') as paye_treatment,
      mdt.finance_component_id,
      mdt.frozen_component_snapshot_json,
      mdt.frozen_component_key_type,
      mdt.frozen_component_key_value,
      mdt.frozen_component_classification,
      mdt.frozen_source_basis_json,
      mdt.frozen_source_pay_method,
      coalesce(mdt.frozen_target_pay_method, coalesce(mdt.pay_channel, 'PAYE')) as frozen_target_pay_method,
      mdt.frozen_resolution_mode,
      mdt.frozen_resolution_payload_json,
      jsonb_strip_nulls(
        coalesce(mdt.frozen_resolution_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'target_amount_ex_vat', round(-mda.take_ex, 2),
          'target_amount_vat', 0,
          'target_amount_inc_vat', round(-mda.take_ex, 2)
        )
      ) as frozen_resolution_result_json,
      round(coalesce(mda.take_ex, 0), 2)::numeric(12,2) as frozen_source_amount,
      round(-mda.take_ex, 2)::numeric(12,2) as frozen_target_amount_ex_vat,
      0::numeric(12,2) as frozen_target_amount_vat,
      round(-mda.take_ex, 2)::numeric(12,2) as frozen_target_amount_inc_vat,
      mdt.payout_instruction_snapshot_json
    from manual_debt_alloc mda
    join manual_debt_case_templates mdt
      on mdt.pay_batch_candidate_id = mda.pay_batch_candidate_id
     and mdt.finance_case_id = mda.finance_case_id
    where round(coalesce(mda.take_ex, 0), 2) > 0
    returning id, amount_ex_vat, amount_vat, amount_inc_vat
  )
  insert into public.pay_batch_item_breakdowns(
    pay_batch_item_id,
    line_kind,
    bucket_code,
    unit_name,
    units,
    rate,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    meta_json
  )
  select
    imd.id,
    'MANUAL_DEBT_RECOVERY',
    null,
    'Manual debt recovery',
    null::numeric,
    null::numeric,
    imd.amount_ex_vat,
    imd.amount_vat,
    imd.amount_inc_vat,
    '{}'::jsonb
  from ins_manual_debt imd;

  get diagnostics v_ins_manual_debt_bd = row_count;

  select count(*)::int
  into v_ins_manual_debt
  from public.pay_batch_items pbi_ct3
  where pbi_ct3.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
    and pbi_ct3.item_type = 'MANUAL_DEBT_RECOVERY'
    and pbi_ct3.is_voided = false
    and pbi_ct3.repayment_week_start = v_week_start;

  with ins_finance_reservations as (
    insert into public.pay_advance_reservations (
      id,
      finance_case_id,
      pay_batch_id,
      pay_batch_candidate_id,
      pay_batch_item_id,
      reserved_amount,
      repayment_week_start,
      status,
      created_at_utc,
      committed_at_utc,
      settled_at_utc,
      released_at_utc,
      released_reason,
      created_by_user_id,
      updated_by_user_id,
      finance_component_id,
      frozen_component_snapshot_json,
      frozen_component_key_type,
      frozen_component_key_value,
      frozen_component_classification,
      frozen_source_basis_json,
      frozen_source_pay_method,
      frozen_target_pay_method,
      frozen_resolution_mode,
      frozen_resolution_payload_json,
      frozen_resolution_result_json,
      reserved_source_amount,
      frozen_rounded_target_amount
    )
    select
      gen_random_uuid() as id,
      pbi_fin.finance_case_id,
      p_pay_batch_id as pay_batch_id,
      pbi_fin.pay_batch_candidate_id,
      pbi_fin.id as pay_batch_item_id,
      round(abs(coalesce(pbi_fin.amount_ex_vat, 0)), 2)::numeric(12,2) as reserved_amount,
      pbi_fin.repayment_week_start,
      'RESERVED' as status,
      now() as created_at_utc,
      null::timestamptz as committed_at_utc,
      null::timestamptz as settled_at_utc,
      null::timestamptz as released_at_utc,
      null::text as released_reason,
      p_actor_user_id as created_by_user_id,
      p_actor_user_id as updated_by_user_id,
      pbi_fin.finance_component_id,
      pbi_fin.frozen_component_snapshot_json,
      pbi_fin.frozen_component_key_type,
      pbi_fin.frozen_component_key_value,
      pbi_fin.frozen_component_classification,
      pbi_fin.frozen_source_basis_json,
      pbi_fin.frozen_source_pay_method,
      pbi_fin.frozen_target_pay_method,
      pbi_fin.frozen_resolution_mode,
      pbi_fin.frozen_resolution_payload_json,
      pbi_fin.frozen_resolution_result_json,
      round(abs(coalesce(pbi_fin.frozen_source_amount, pbi_fin.amount_ex_vat, 0)), 2)::numeric(12,2) as reserved_source_amount,
      round(abs(coalesce(pbi_fin.frozen_target_amount_ex_vat, pbi_fin.amount_ex_vat, 0)), 2)::numeric(12,2) as frozen_rounded_target_amount
    from public.pay_batch_items pbi_fin
    where pbi_fin.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
      and pbi_fin.is_voided = false
      and pbi_fin.finance_case_id is not null
      and pbi_fin.reservation_id is null
      and pbi_fin.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY')
    returning id, pay_batch_item_id
  ),
  upd_finance_items as (
    update public.pay_batch_items pbi_upd
    set
      reservation_id = ifr.id,
      updated_at = now()
    from ins_finance_reservations ifr
    where pbi_upd.id = ifr.pay_batch_item_id
    returning pbi_upd.id
  )
  select count(*)::int
  into v_ins_finance_reservations
  from upd_finance_items;
  update public.pay_batch_candidates pbc_sum
  set
    awaiting_net_amount = not exists (
      select 1
      from public.pay_batch_paye_net_inputs pni4
      where pni4.pay_batch_candidate_id = pbc_sum.id
      limit 1
    ),
    overpayment_recovery_taken = coalesce((
      select round(sum(-pbi_s.amount_ex_vat), 2)
      from public.pay_batch_items pbi_s
      where pbi_s.pay_batch_candidate_id = pbc_sum.id
        and pbi_s.is_voided = false
        and pbi_s.item_type = 'OVERPAYMENT_RECOVERY'
    ), 0)::numeric(12,2),
    loan_repayment_taken = coalesce((
      select round(sum(-pbi_s2.amount_ex_vat), 2)
      from public.pay_batch_items pbi_s2
      where pbi_s2.pay_batch_candidate_id = pbc_sum.id
        and pbi_s2.is_voided = false
        and pbi_s2.item_type = 'LOAN_REPAYMENT'
    ), 0)::numeric(12,2),
    net_bank_amount = case
      when not exists (
        select 1
        from public.pay_batch_paye_net_inputs pni5
        where pni5.pay_batch_candidate_id = pbc_sum.id
        limit 1
      ) then null
      else greatest(
        round(
          coalesce((
            select pni_last.net_amount
            from public.pay_batch_paye_net_inputs pni_last
            where pni_last.pay_batch_candidate_id = pbc_sum.id
            order by pni_last.imported_at_utc desc
            limit 1
          ), 0)
          +
          coalesce((
            select round(coalesce(sum(
              case
                when pbi_d.is_voided = false and coalesce(pbi_d.paye_treatment, '') = 'NET_ADD'
                  then pbi_d.amount_ex_vat
                when pbi_d.is_voided = false and coalesce(pbi_d.paye_treatment, '') = 'NET_DEDUCT'
                  then pbi_d.amount_ex_vat
                else 0
              end
            ),0),2)
            from public.pay_batch_items pbi_d
            where pbi_d.pay_batch_candidate_id = pbc_sum.id
          ), 0),
          2
        ),
        0
      )::numeric(12,2)
    end,
    updated_at = now()
  where pbc_sum.id in (select s.pay_batch_candidate_id from _tmp_paye_scope s);

  get diagnostics v_upd_candidates = row_count;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'pay_batch_candidate_id', pbc_ret.id::text,
        'candidate_id', pbc_ret.candidate_id::text,
        'paye_state', pbc_ret.paye_state,
        'awaiting_net_amount', pbc_ret.awaiting_net_amount,
        'paye_net_amount', pni_ret.net_amount,
        'overpayment_recovery_taken', coalesce(pbc_ret.overpayment_recovery_taken, 0)::numeric(12,2),
        'loan_repayment_taken', coalesce(pbc_ret.loan_repayment_taken, 0)::numeric(12,2),
        'loan_payout_net_additions', coalesce((
          select round(sum(coalesce(pbi_np.amount_ex_vat, 0)), 2)
          from public.pay_batch_items pbi_np
          where pbi_np.pay_batch_candidate_id = pbc_ret.id
            and pbi_np.is_voided = false
            and pbi_np.item_type = 'LOAN_PAYOUT'
            and coalesce(pbi_np.paye_treatment, '') = 'NET_ADD'
        ), 0)::numeric(12,2),
        'manual_credit_net_additions', coalesce((
          select round(sum(coalesce(pbi_mc.amount_ex_vat, 0)), 2)
          from public.pay_batch_items pbi_mc
          where pbi_mc.pay_batch_candidate_id = pbc_ret.id
            and pbi_mc.is_voided = false
            and pbi_mc.item_type = 'MANUAL_CREDIT_PAYOUT'
            and coalesce(pbi_mc.paye_treatment, '') = 'NET_ADD'
        ), 0)::numeric(12,2),
        'manual_debt_net_deductions', coalesce((
          select round(sum(-pbi_mdn.amount_ex_vat), 2)
          from public.pay_batch_items pbi_mdn
          where pbi_mdn.pay_batch_candidate_id = pbc_ret.id
            and pbi_mdn.is_voided = false
            and pbi_mdn.item_type = 'MANUAL_DEBT_RECOVERY'
            and coalesce(pbi_mdn.paye_treatment, '') = 'NET_DEDUCT'
        ), 0)::numeric(12,2),
        'net_additions_total', coalesce((
          select round(sum(coalesce(pbi_na.amount_ex_vat, 0)), 2)
          from public.pay_batch_items pbi_na
          where pbi_na.pay_batch_candidate_id = pbc_ret.id
            and pbi_na.is_voided = false
            and coalesce(pbi_na.paye_treatment, '') = 'NET_ADD'
        ), 0)::numeric(12,2),
        'net_deductions_total', coalesce((
          select round(sum(-pbi_nd0.amount_ex_vat), 2)
          from public.pay_batch_items pbi_nd0
          where pbi_nd0.pay_batch_candidate_id = pbc_ret.id
            and pbi_nd0.is_voided = false
            and coalesce(pbi_nd0.paye_treatment, '') = 'NET_DEDUCT'
        ), 0)::numeric(12,2),
        'net_bank_amount', pbc_ret.net_bank_amount,
        'deductions_summary', jsonb_build_object(
          'gross_positive', greatest(coalesce(pni_ret.net_amount, 0), 0)::numeric(12,2),
          'overpayment_recovery', coalesce(pbc_ret.overpayment_recovery_taken, 0)::numeric(12,2),
          'loan_repayment', coalesce(pbc_ret.loan_repayment_taken, 0)::numeric(12,2),
          'loan_payout_net_additions', coalesce((
            select round(sum(coalesce(pbi_np2.amount_ex_vat, 0)), 2)
            from public.pay_batch_items pbi_np2
            where pbi_np2.pay_batch_candidate_id = pbc_ret.id
              and pbi_np2.is_voided = false
              and pbi_np2.item_type = 'LOAN_PAYOUT'
              and coalesce(pbi_np2.paye_treatment, '') = 'NET_ADD'
          ), 0)::numeric(12,2),
          'manual_credit_net_additions', coalesce((
            select round(sum(coalesce(pbi_mc2.amount_ex_vat, 0)), 2)
            from public.pay_batch_items pbi_mc2
            where pbi_mc2.pay_batch_candidate_id = pbc_ret.id
              and pbi_mc2.is_voided = false
              and pbi_mc2.item_type = 'MANUAL_CREDIT_PAYOUT'
              and coalesce(pbi_mc2.paye_treatment, '') = 'NET_ADD'
          ), 0)::numeric(12,2),
          'manual_debt_net_deductions', coalesce((
            select round(sum(-pbi_mdn2.amount_ex_vat), 2)
            from public.pay_batch_items pbi_mdn2
            where pbi_mdn2.pay_batch_candidate_id = pbc_ret.id
              and pbi_mdn2.is_voided = false
              and pbi_mdn2.item_type = 'MANUAL_DEBT_RECOVERY'
              and coalesce(pbi_mdn2.paye_treatment, '') = 'NET_DEDUCT'
          ), 0)::numeric(12,2),
          'net_additions_total', coalesce((
            select round(sum(coalesce(pbi_na2.amount_ex_vat, 0)), 2)
            from public.pay_batch_items pbi_na2
            where pbi_na2.pay_batch_candidate_id = pbc_ret.id
              and pbi_na2.is_voided = false
              and coalesce(pbi_na2.paye_treatment, '') = 'NET_ADD'
          ), 0)::numeric(12,2),
          'net_deductions_total', coalesce((
            select round(sum(-pbi_nd.amount_ex_vat), 2)
            from public.pay_batch_items pbi_nd
            where pbi_nd.pay_batch_candidate_id = pbc_ret.id
              and pbi_nd.is_voided = false
              and coalesce(pbi_nd.paye_treatment, '') = 'NET_DEDUCT'
          ), 0)::numeric(12,2),
          'final_payable', pbc_ret.net_bank_amount,
          'awaiting_net_amount', pbc_ret.awaiting_net_amount,
          'paye_net_amount', pni_ret.net_amount
        )
      )
      order by pbc_ret.candidate_id::text
    ),
    '[]'::jsonb
  )
  into v_candidate_summaries
  from public.pay_batch_candidates pbc_ret
  left join lateral (
    select pni_ret_inner.net_amount
    from public.pay_batch_paye_net_inputs pni_ret_inner
    where pni_ret_inner.pay_batch_candidate_id = pbc_ret.id
    order by pni_ret_inner.imported_at_utc desc
    limit 1
  ) pni_ret on true
  where pbc_ret.id in (select s.pay_batch_candidate_id from _tmp_paye_scope s);

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'source', 'MANUAL_ENTRY',
    'updated_count', v_updated_count,
    'cleared_count', v_cleared_count,
    'unmatched', '[]'::jsonb,
    'candidate_summaries', v_candidate_summaries,
    'recompute', jsonb_build_object(
      'deleted_deduction_items', v_deleted_ded_items,
      'deleted_deduction_breakdowns', v_deleted_ded_breakdowns,
      'deleted_manual_debt_breakdowns', v_deleted_manual_debt_breakdowns,
      'deleted_net_deduct_reservations', v_deleted_ded_reservations,
      'released_manual_debt_reservations', v_released_manual_debt_reservations,
      'voided_manual_debt_items', v_voided_manual_debt_items,
      'inserted_overpayment_items', v_ins_overpay,
      'inserted_overpayment_breakdowns', v_ins_overpay_bd,
      'inserted_loan_items', v_ins_loan,
      'inserted_loan_breakdowns', v_ins_loan_bd,
      'inserted_manual_debt_items', v_ins_manual_debt,
      'inserted_manual_debt_breakdowns', v_ins_manual_debt_bd,
      'inserted_finance_reservations', v_ins_finance_reservations,
      'updated_candidates', v_upd_candidates
    )
  );
end;
$function$;

-- pay_settle_manual_confirm(uuid,text,text,date,uuid,text,uuid,boolean,text,boolean,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_settle_manual_confirm(p_pay_batch_id uuid, p_scope text, p_bank_confirm_ref text, p_payment_date date, p_actor_user_id uuid, p_settlement_mode text DEFAULT 'CSV_SETTLEMENT'::text, p_auth_request_id uuid DEFAULT NULL::uuid, p_csv_uploaded_confirmed boolean DEFAULT false, p_external_settlement_comment text DEFAULT NULL::text, p_suppress_remittances boolean DEFAULT false, p_operation_id uuid DEFAULT NULL::uuid, p_settlement_scope_ids jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_scope text := upper(btrim(coalesce(p_scope,'ALL')));
  v_batch record;
  v_auth record;

  v_now timestamptz := now();
  v_settlement_mode text := upper(btrim(coalesce(p_settlement_mode, 'CSV_SETTLEMENT')));
  v_provider text := null;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_execution_commit_ref text := null;
  v_execution_committed_at_utc timestamptz := null;
  v_bank_confirm_ref text := nullif(btrim(coalesce(p_bank_confirm_ref, '')), '');
  v_external_settlement_comment text := nullif(btrim(coalesce(p_external_settlement_comment, '')), '');

  v_auth_intent jsonb := '{}'::jsonb;
  v_intent_mode text := null;
  v_intent_suppress_remittances boolean := false;
  v_intent_csv_uploaded_confirmed boolean := false;
  v_intent_bank_confirm_ref text := null;
  v_intent_external_comment text := null;
  v_intent_payment_date date := null;
  v_intent_payment_date_raw text := null;
  v_bank_csv_export_json jsonb := null;
  v_bank_csv_export_hash text := null;
  v_current_transfer_hash text := null;

  v_pending_count int := 0;
  v_external_submission_count int := 0;
  v_reservations_committed_count int := 0;
  v_reservations_committed_amount numeric := 0;
  v_settlement_json jsonb := '[]'::jsonb;
  v_settle_result jsonb := '{}'::jsonb;
  v_settlement_confirmation_json jsonb := '{}'::jsonb;
  v_worker_communications jsonb := '{}'::jsonb;
  v_remittance_queue_stage_result jsonb := '{}'::jsonb;
  v_manual_event_ingest_results jsonb := '[]'::jsonb;

  v_operation_mode boolean := false;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_execution_operation_row public.banking_pay_operations%ROWTYPE;
  v_requested_scope_count integer := 0;
  v_matched_scope_count integer := 0;
  v_settled_this_chunk integer := 0;
  v_reused_this_chunk integer := 0;
  v_failed_this_chunk integer := 0;
  v_remaining_scope_count integer := 0;
  v_has_more boolean := false;
  v_candidate_updates_count integer := 0;
  v_root_operation_input_json jsonb := '{}'::jsonb;
  v_operation_auth_intent_json jsonb := '{}'::jsonb;
  v_batch_intent_json jsonb := '{}'::jsonb;
  v_auth_locator_json jsonb := '{}'::jsonb;
  v_operation_auth_request_id uuid := NULL::uuid;
  v_operation_auth_state text := NULL::text;
  v_execution_operation_id uuid := NULL::uuid;
  v_auth_intent_operation_id uuid := NULL::uuid;
  v_batch_intent_operation_id uuid := NULL::uuid;
  v_auth_intent_auth_request_id uuid := NULL::uuid;
  v_batch_intent_auth_request_id uuid := NULL::uuid;
  v_server_owned_projection_proof boolean := false;
  v_batch_server_owned_projection_proof boolean := false;
  v_no_bank_payment_marker boolean := false;
  v_batch_no_bank_payment_marker boolean := false;
  v_allow_explicit_zero_no_bank_scopes_marker boolean := false;
  v_batch_allow_explicit_zero_no_bank_scopes_marker boolean := false;
  v_no_bank_scope_authorised boolean := false;
  v_no_bank_payment_execution_validated boolean := false;
  v_operation_projection_scope text := NULL::text;
  v_batch_projection_scope text := NULL::text;
  v_batch_intent_mode text := NULL::text;
  v_expected_paye_net_state_hash text := NULL::text;
  v_batch_expected_paye_net_state_hash text := NULL::text;
  v_expected_global_bank_payment_projection_hash text := NULL::text;
  v_batch_expected_global_bank_payment_projection_hash text := NULL::text;
  v_expected_scoped_paye_net_state_hash text := NULL::text;
  v_batch_expected_scoped_paye_net_state_hash text := NULL::text;
  v_expected_bank_payment_projection_hash text := NULL::text;
  v_batch_expected_bank_payment_projection_hash text := NULL::text;
  v_expected_missing_count integer := NULL::integer;
  v_batch_expected_missing_count integer := NULL::integer;
  v_expected_global_zero_count integer := NULL::integer;
  v_batch_expected_global_zero_count integer := NULL::integer;
  v_expected_global_positive_count integer := NULL::integer;
  v_batch_expected_global_positive_count integer := NULL::integer;
  v_expected_global_invalid_count integer := NULL::integer;
  v_batch_expected_global_invalid_count integer := NULL::integer;
  v_expected_scoped_missing_count integer := NULL::integer;
  v_batch_expected_scoped_missing_count integer := NULL::integer;
  v_expected_zero_count integer := NULL::integer;
  v_batch_expected_zero_count integer := NULL::integer;
  v_expected_positive_count integer := NULL::integer;
  v_batch_expected_positive_count integer := NULL::integer;
  v_expected_positive_total numeric(14,2) := NULL::numeric;
  v_batch_expected_positive_total numeric(14,2) := NULL::numeric;
  v_expected_scoped_invalid_count integer := NULL::integer;
  v_batch_expected_scoped_invalid_count integer := NULL::integer;
  v_scoped_no_transfer_marker boolean := false;
  v_batch_scoped_no_transfer_marker boolean := false;
  v_intent_csv_evidence_json jsonb := '{}'::jsonb;
  v_batch_csv_evidence_json jsonb := '{}'::jsonb;
  v_frozen_csv_validated boolean := false;
  v_frozen_csv_scope text := NULL::text;
  v_frozen_csv_paye_net_state_hash text := NULL::text;
  v_frozen_csv_bank_projection_hash text := NULL::text;
  v_frozen_csv_row_count integer := NULL::integer;
  v_frozen_csv_total numeric(14,2) := NULL::numeric;
  v_frozen_csv_zero_row boolean := false;
  v_frozen_csv_confirmation_kind text := NULL::text;
  v_current_paye_net_state_hash text := NULL::text;
  v_all_bank_payment_projection_hash text := NULL::text;
  v_current_scoped_paye_net_state_hash text := NULL::text;
  v_current_bank_payment_projection_hash text := NULL::text;
  v_current_missing_count integer := 0;
  v_global_zero_count integer := 0;
  v_global_positive_count integer := 0;
  v_global_invalid_count integer := 0;
  v_current_scoped_missing_count integer := 0;
  v_current_zero_count integer := 0;
  v_current_positive_count integer := 0;
  v_current_positive_total numeric(14,2) := 0;
  v_current_scoped_invalid_count integer := 0;
  v_current_projection_changed boolean := false;
  v_projection_diagnostic_json jsonb := '{}'::jsonb;
  v_operation_effective_payment_date date := NULL::date;
  v_batch_intent_payment_date date := NULL::date;
  v_batch_intent_payment_date_raw text := NULL::text;
  v_batch_intent_suppress_remittances boolean := false;
  v_batch_intent_csv_uploaded_confirmed boolean := false;
  v_batch_intent_bank_confirm_ref text := NULL::text;
  v_batch_intent_external_comment text := NULL::text;
  v_no_bank_settled_this_chunk integer := 0;
  v_no_bank_total_scope_count integer := 0;
  v_no_bank_eligible_scope_count integer := 0;
  v_no_bank_invalid_scope_count integer := 0;
  v_selected_no_bank_scope_count integer := 0;
  v_selected_eligible_no_bank_scope_count integer := 0;
  v_local_no_bank_commit_ref text := NULL::text;
  v_no_bank_transfer_scope_count integer := 0;
  v_no_bank_batch_transfer_count integer := 0;
  v_no_bank_transfer_event_count integer := 0;
  v_no_bank_provider_attempt_count integer := 0;
  v_total_scope_count integer := 0;
  v_successful_scope_count integer := 0;
  v_settled_scope_count integer := 0;
  v_skipped_scope_count integer := 0;
  v_transfer_backed_scope_count integer := 0;
  v_settled_transfer_backed_scope_count integer := 0;
  v_terminal_failed_scope_count integer := 0;
  v_pending_scope_count integer := 0;
  v_unknown_scope_count integer := 0;
  v_processor_failed_scope_count integer := 0;
  v_completed_transfer_count integer := 0;
  v_scope_settlement_complete boolean := false;
  v_all_scopes_terminal boolean := false;
  v_all_scopes_successful boolean := false;
  v_completed_with_failed_payments boolean := false;
  v_requires_full_batch_finalisation boolean := false;
  v_full_batch_finalisation_safe boolean := false;
  v_finalisation_idempotency_key text := NULL::text;
  v_finalisation_payload_hash text := NULL::text;
  v_operation_scope_state_json jsonb := '[]'::jsonb;
  v_proof_validation_outcome text := 'NOT_VALIDATED';
begin
  if p_pay_batch_id is null then
    raise exception 'pay_settle_manual_confirm: pay_batch_id is required';
  end if;
  if p_actor_user_id is null then
    raise exception 'pay_settle_manual_confirm: actor_user_id is required';
  end if;
  if v_scope not in ('ALL','PAYE','UMBRELLA') then
    raise exception 'pay_settle_manual_confirm: invalid scope (ALL|PAYE|UMBRELLA)';
  end if;
  if v_settlement_mode not in ('CSV_SETTLEMENT','EXTERNAL_SETTLEMENT') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'INVALID_SETTLEMENT_MODE',
      'message', 'pay_settle_manual_confirm: settlement_mode must be CSV_SETTLEMENT or EXTERNAL_SETTLEMENT',
      'pay_batch_id', p_pay_batch_id::text,
      'settlement_mode', v_settlement_mode
    )::text;
  end if;
  v_operation_mode := (p_operation_id IS NOT NULL OR p_settlement_scope_ids IS NOT NULL);

  IF v_operation_mode THEN
    IF p_operation_id IS NULL THEN
      RAISE EXCEPTION 'pay_settle_manual_confirm operation mode requires p_operation_id';
    END IF;
    IF p_settlement_scope_ids IS NULL
       OR JSONB_TYPEOF(p_settlement_scope_ids) <> 'array'
       OR JSONB_ARRAY_LENGTH(p_settlement_scope_ids) = 0 THEN
      RAISE EXCEPTION 'pay_settle_manual_confirm operation mode requires non-empty p_settlement_scope_ids';
    END IF;

    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'banking_pay_operations row % not found', p_operation_id;
    END IF;

    IF v_operation_row.operation_type NOT IN ('PAYMENT_SETTLEMENT', 'PAYMENT_EXECUTE') THEN
      RAISE EXCEPTION 'operation % is not a settlement-capable operation', p_operation_id;
    END IF;

    IF v_operation_row.pay_batch_id IS NOT NULL
       AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
      RAISE EXCEPTION 'operation % is for pay batch %, not %', p_operation_id, v_operation_row.pay_batch_id, p_pay_batch_id;
    END IF;

    IF v_operation_row.actor_user_id IS NOT NULL
       AND v_operation_row.actor_user_id <> p_actor_user_id THEN
      RAISE EXCEPTION 'operation % belongs to a different actor', p_operation_id;
    END IF;

    SELECT batch_row.*
    INTO v_batch
    FROM public.pay_batches AS batch_row
    WHERE batch_row.id = p_pay_batch_id
    FOR UPDATE;

    IF v_batch.id IS NULL THEN
      RAISE EXCEPTION 'pay_settle_manual_confirm: pay_batch not found';
    END IF;

    v_batch_intent_json := CASE
      WHEN JSONB_TYPEOF(v_batch.execution_intent_json) = 'object'
        THEN COALESCE(v_batch.execution_intent_json, '{}'::jsonb)
      ELSE '{}'::jsonb
    END;

    v_execution_operation_id := CASE
      WHEN UPPER(BTRIM(COALESCE(v_operation_row.operation_type, ''))) = 'PAYMENT_EXECUTE'
        THEN v_operation_row.id
      WHEN v_operation_row.root_operation_id IS NOT NULL
        THEN v_operation_row.root_operation_id
      WHEN NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'operation_id', '')), '')
           ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN (v_batch_intent_json->>'operation_id')::uuid
      ELSE NULL::uuid
    END;

    IF v_execution_operation_id IS NULL THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'EXECUTION_OPERATION_REQUIRED',
        'message', 'The settlement operation is not bound to a payment execution operation.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    SELECT execution_operation.*
    INTO v_execution_operation_row
    FROM public.banking_pay_operations AS execution_operation
    WHERE execution_operation.id = v_execution_operation_id
    FOR UPDATE;

    IF NOT FOUND
       OR v_execution_operation_row.pay_batch_id IS DISTINCT FROM p_pay_batch_id
       OR v_execution_operation_row.operation_type NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'EXECUTION_OPERATION_INVALID',
        'message', 'The resolved payment execution operation is missing or incompatible with this settlement operation.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'execution_operation_id', v_execution_operation_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    v_root_operation_input_json := COALESCE(v_execution_operation_row.input_json, '{}'::jsonb);
    v_auth_locator_json := COALESCE(v_operation_row.input_json, '{}'::jsonb)
      || CASE
           WHEN JSONB_TYPEOF(v_operation_row.input_json->'execution_intent_json') = 'object'
             THEN v_operation_row.input_json->'execution_intent_json'
           ELSE '{}'::jsonb
         END
      || v_root_operation_input_json
      || CASE
           WHEN JSONB_TYPEOF(v_root_operation_input_json->'execution_intent_json') = 'object'
             THEN v_root_operation_input_json->'execution_intent_json'
           ELSE '{}'::jsonb
         END
      || v_batch_intent_json;

    IF p_auth_request_id IS NOT NULL THEN
      v_operation_auth_request_id := p_auth_request_id;
    ELSIF NULLIF(BTRIM(COALESCE(
      v_auth_locator_json->>'auth_request_id',
      v_auth_locator_json->>'authRequestId',
      ''
    )), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_operation_auth_request_id := COALESCE(
        v_auth_locator_json->>'auth_request_id',
        v_auth_locator_json->>'authRequestId'
      )::uuid;
    END IF;

    IF v_operation_auth_request_id IS NULL THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'AUTHORISED_EXECUTION_INTENT_REQUIRED',
        'message', 'An authorised server-frozen execution intent is required before operation-mode manual settlement can continue.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'execution_operation_id', v_execution_operation_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    SELECT
      auth_request.state,
      CASE
        WHEN JSONB_TYPEOF(auth_request.execution_intent_json) = 'object'
          THEN COALESCE(auth_request.execution_intent_json, '{}'::jsonb)
        ELSE '{}'::jsonb
      END
    INTO
      v_operation_auth_state,
      v_operation_auth_intent_json
    FROM public.pay_batch_auth_requests AS auth_request
    WHERE auth_request.id = v_operation_auth_request_id
      AND auth_request.pay_batch_id = p_pay_batch_id
    FOR UPDATE;

    IF NOT FOUND
       OR UPPER(BTRIM(COALESCE(v_operation_auth_state, ''))) <> 'AUTHORISED'
       OR JSONB_TYPEOF(v_operation_auth_intent_json) <> 'object'
       OR v_operation_auth_intent_json = '{}'::jsonb THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'AUTHORISED_EXECUTION_INTENT_REQUIRED',
        'message', 'The payment auth request is missing, belongs to another batch, is not authorised, or has no execution intent.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'execution_operation_id', v_execution_operation_id::text,
        'auth_request_id', v_operation_auth_request_id::text,
        'auth_state', v_operation_auth_state
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF v_batch_intent_json = '{}'::jsonb THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'BATCH_EXECUTION_INTENT_REQUIRED',
        'message', 'The batch does not contain the server-frozen execution intent required for settlement.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'auth_request_id', v_operation_auth_request_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    v_auth_intent := v_operation_auth_intent_json;

    IF NULLIF(BTRIM(COALESCE(v_operation_auth_intent_json->>'operation_id', '')), '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_auth_intent_operation_id := (v_operation_auth_intent_json->>'operation_id')::uuid;
    END IF;
    IF NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'operation_id', '')), '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_batch_intent_operation_id := (v_batch_intent_json->>'operation_id')::uuid;
    END IF;
    IF NULLIF(BTRIM(COALESCE(v_operation_auth_intent_json->>'auth_request_id', '')), '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_auth_intent_auth_request_id := (v_operation_auth_intent_json->>'auth_request_id')::uuid;
    END IF;
    IF NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'auth_request_id', '')), '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_batch_intent_auth_request_id := (v_batch_intent_json->>'auth_request_id')::uuid;
    END IF;

    v_intent_mode := CASE
      WHEN UPPER(BTRIM(COALESCE(v_operation_auth_intent_json->>'execution_mode', ''))) IN ('STANDARD_BANK', 'BANK') THEN 'STANDARD_BANK'
      WHEN UPPER(BTRIM(COALESCE(v_operation_auth_intent_json->>'execution_mode', ''))) IN ('CSV', 'CSV_SETTLEMENT') THEN 'CSV_SETTLEMENT'
      WHEN UPPER(BTRIM(COALESCE(v_operation_auth_intent_json->>'execution_mode', ''))) IN ('EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'EXTERNAL_SETTLEMENT'
      ELSE UPPER(NULLIF(BTRIM(COALESCE(v_operation_auth_intent_json->>'execution_mode', '')), ''))
    END;
    v_batch_intent_mode := CASE
      WHEN UPPER(BTRIM(COALESCE(v_batch_intent_json->>'execution_mode', ''))) IN ('STANDARD_BANK', 'BANK') THEN 'STANDARD_BANK'
      WHEN UPPER(BTRIM(COALESCE(v_batch_intent_json->>'execution_mode', ''))) IN ('CSV', 'CSV_SETTLEMENT') THEN 'CSV_SETTLEMENT'
      WHEN UPPER(BTRIM(COALESCE(v_batch_intent_json->>'execution_mode', ''))) IN ('EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'EXTERNAL_SETTLEMENT'
      ELSE UPPER(NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'execution_mode', '')), ''))
    END;
    v_operation_projection_scope := UPPER(NULLIF(BTRIM(COALESCE(
      v_operation_auth_intent_json->>'pay_channel_scope',
      v_operation_auth_intent_json->>'scope',
      ''
    )), ''));
    v_batch_projection_scope := UPPER(NULLIF(BTRIM(COALESCE(
      v_batch_intent_json->>'pay_channel_scope',
      v_batch_intent_json->>'scope',
      ''
    )), ''));

    v_expected_paye_net_state_hash := NULLIF(BTRIM(COALESCE(
      v_operation_auth_intent_json->>'global_paye_net_state_hash',
      v_operation_auth_intent_json->>'paye_net_state_hash',
      ''
    )), '');
    v_batch_expected_paye_net_state_hash := NULLIF(BTRIM(COALESCE(
      v_batch_intent_json->>'global_paye_net_state_hash',
      v_batch_intent_json->>'paye_net_state_hash',
      ''
    )), '');
    v_expected_global_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(
      v_operation_auth_intent_json->>'global_bank_payment_projection_hash',
      ''
    )), '');
    v_batch_expected_global_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(
      v_batch_intent_json->>'global_bank_payment_projection_hash',
      ''
    )), '');
    v_expected_scoped_paye_net_state_hash := NULLIF(BTRIM(COALESCE(
      v_operation_auth_intent_json->>'scoped_paye_net_state_hash',
      ''
    )), '');
    v_batch_expected_scoped_paye_net_state_hash := NULLIF(BTRIM(COALESCE(
      v_batch_intent_json->>'scoped_paye_net_state_hash',
      ''
    )), '');
    v_expected_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(
      v_operation_auth_intent_json->>'scoped_bank_payment_projection_hash',
      v_operation_auth_intent_json->>'bank_payment_projection_hash',
      ''
    )), '');
    v_batch_expected_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(
      v_batch_intent_json->>'scoped_bank_payment_projection_hash',
      v_batch_intent_json->>'bank_payment_projection_hash',
      ''
    )), '');

    IF COALESCE(v_operation_auth_intent_json->>'global_missing_explicit_paye_input_count', v_operation_auth_intent_json->>'missing_explicit_paye_input_count', '') ~ '^[0-9]+$' THEN
      v_expected_missing_count := COALESCE(v_operation_auth_intent_json->>'global_missing_explicit_paye_input_count', v_operation_auth_intent_json->>'missing_explicit_paye_input_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'global_missing_explicit_paye_input_count', v_batch_intent_json->>'missing_explicit_paye_input_count', '') ~ '^[0-9]+$' THEN
      v_batch_expected_missing_count := COALESCE(v_batch_intent_json->>'global_missing_explicit_paye_input_count', v_batch_intent_json->>'missing_explicit_paye_input_count')::integer;
    END IF;
    IF COALESCE(v_operation_auth_intent_json->>'global_explicit_zero_count', v_operation_auth_intent_json->>'explicit_zero_count', '') ~ '^[0-9]+$' THEN
      v_expected_global_zero_count := COALESCE(v_operation_auth_intent_json->>'global_explicit_zero_count', v_operation_auth_intent_json->>'explicit_zero_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'global_explicit_zero_count', v_batch_intent_json->>'explicit_zero_count', '') ~ '^[0-9]+$' THEN
      v_batch_expected_global_zero_count := COALESCE(v_batch_intent_json->>'global_explicit_zero_count', v_batch_intent_json->>'explicit_zero_count')::integer;
    END IF;
    IF COALESCE(v_operation_auth_intent_json->>'global_positive_bank_payment_count', '') ~ '^[0-9]+$' THEN
      v_expected_global_positive_count := (v_operation_auth_intent_json->>'global_positive_bank_payment_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'global_positive_bank_payment_count', '') ~ '^[0-9]+$' THEN
      v_batch_expected_global_positive_count := (v_batch_intent_json->>'global_positive_bank_payment_count')::integer;
    END IF;
    IF COALESCE(v_operation_auth_intent_json->>'global_invalid_payment_row_count', '') ~ '^[0-9]+$' THEN
      v_expected_global_invalid_count := (v_operation_auth_intent_json->>'global_invalid_payment_row_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'global_invalid_payment_row_count', '') ~ '^[0-9]+$' THEN
      v_batch_expected_global_invalid_count := (v_batch_intent_json->>'global_invalid_payment_row_count')::integer;
    END IF;
    IF COALESCE(v_operation_auth_intent_json->>'scoped_missing_explicit_paye_input_count', '') ~ '^[0-9]+$' THEN
      v_expected_scoped_missing_count := (v_operation_auth_intent_json->>'scoped_missing_explicit_paye_input_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'scoped_missing_explicit_paye_input_count', '') ~ '^[0-9]+$' THEN
      v_batch_expected_scoped_missing_count := (v_batch_intent_json->>'scoped_missing_explicit_paye_input_count')::integer;
    END IF;
    IF COALESCE(v_operation_auth_intent_json->>'scoped_explicit_zero_count', '') ~ '^[0-9]+$' THEN
      v_expected_zero_count := (v_operation_auth_intent_json->>'scoped_explicit_zero_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'scoped_explicit_zero_count', '') ~ '^[0-9]+$' THEN
      v_batch_expected_zero_count := (v_batch_intent_json->>'scoped_explicit_zero_count')::integer;
    END IF;
    IF COALESCE(v_operation_auth_intent_json->>'scoped_positive_bank_payment_count', v_operation_auth_intent_json->>'positive_bank_payment_count', '') ~ '^[0-9]+$' THEN
      v_expected_positive_count := COALESCE(v_operation_auth_intent_json->>'scoped_positive_bank_payment_count', v_operation_auth_intent_json->>'positive_bank_payment_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'scoped_positive_bank_payment_count', v_batch_intent_json->>'positive_bank_payment_count', '') ~ '^[0-9]+$' THEN
      v_batch_expected_positive_count := COALESCE(v_batch_intent_json->>'scoped_positive_bank_payment_count', v_batch_intent_json->>'positive_bank_payment_count')::integer;
    END IF;
    IF COALESCE(v_operation_auth_intent_json->>'scoped_positive_bank_payment_total', v_operation_auth_intent_json->>'positive_bank_payment_total', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
      v_expected_positive_total := ROUND(COALESCE(v_operation_auth_intent_json->>'scoped_positive_bank_payment_total', v_operation_auth_intent_json->>'positive_bank_payment_total')::numeric, 2)::numeric(14,2);
    END IF;
    IF COALESCE(v_batch_intent_json->>'scoped_positive_bank_payment_total', v_batch_intent_json->>'positive_bank_payment_total', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
      v_batch_expected_positive_total := ROUND(COALESCE(v_batch_intent_json->>'scoped_positive_bank_payment_total', v_batch_intent_json->>'positive_bank_payment_total')::numeric, 2)::numeric(14,2);
    END IF;
    IF COALESCE(v_operation_auth_intent_json->>'scoped_invalid_payment_row_count', '') ~ '^[0-9]+$' THEN
      v_expected_scoped_invalid_count := (v_operation_auth_intent_json->>'scoped_invalid_payment_row_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'scoped_invalid_payment_row_count', '') ~ '^[0-9]+$' THEN
      v_batch_expected_scoped_invalid_count := (v_batch_intent_json->>'scoped_invalid_payment_row_count')::integer;
    END IF;

    v_server_owned_projection_proof := LOWER(BTRIM(COALESCE(v_operation_auth_intent_json->>'server_owned_payment_projection_proof', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_batch_server_owned_projection_proof := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'server_owned_payment_projection_proof', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_scoped_no_transfer_marker := LOWER(BTRIM(COALESCE(v_operation_auth_intent_json->>'scoped_no_transfer_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_batch_scoped_no_transfer_marker := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'scoped_no_transfer_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_no_bank_payment_marker := LOWER(BTRIM(COALESCE(v_operation_auth_intent_json->>'no_bank_payment_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_batch_no_bank_payment_marker := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'no_bank_payment_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_allow_explicit_zero_no_bank_scopes_marker := LOWER(BTRIM(COALESCE(v_operation_auth_intent_json->>'allow_explicit_zero_no_bank_scopes', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_batch_allow_explicit_zero_no_bank_scopes_marker := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'allow_explicit_zero_no_bank_scopes', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_intent_suppress_remittances := LOWER(BTRIM(COALESCE(v_operation_auth_intent_json->>'suppress_remittances', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_batch_intent_suppress_remittances := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'suppress_remittances', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_intent_csv_uploaded_confirmed := LOWER(BTRIM(COALESCE(v_operation_auth_intent_json->>'csv_uploaded_confirmed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_batch_intent_csv_uploaded_confirmed := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'csv_uploaded_confirmed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_intent_bank_confirm_ref := NULLIF(BTRIM(COALESCE(v_operation_auth_intent_json->>'csv_bank_confirm_ref', '')), '');
    v_batch_intent_bank_confirm_ref := NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'csv_bank_confirm_ref', '')), '');
    v_intent_external_comment := NULLIF(BTRIM(COALESCE(v_operation_auth_intent_json->>'external_settlement_comment', '')), '');
    v_batch_intent_external_comment := NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'external_settlement_comment', '')), '');
    v_intent_csv_evidence_json := CASE
      WHEN JSONB_TYPEOF(v_operation_auth_intent_json->'bank_csv_evidence') = 'object'
        THEN COALESCE(v_operation_auth_intent_json->'bank_csv_evidence', '{}'::jsonb)
      ELSE '{}'::jsonb
    END;
    v_batch_csv_evidence_json := CASE
      WHEN JSONB_TYPEOF(v_batch_intent_json->'bank_csv_evidence') = 'object'
        THEN COALESCE(v_batch_intent_json->'bank_csv_evidence', '{}'::jsonb)
      ELSE '{}'::jsonb
    END;

    v_intent_payment_date_raw := NULLIF(BTRIM(COALESCE(v_operation_auth_intent_json->>'payment_date', '')), '');
    v_batch_intent_payment_date_raw := NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'payment_date', '')), '');

    IF v_intent_payment_date_raw IS NOT NULL THEN
      BEGIN
        v_intent_payment_date := v_intent_payment_date_raw::date;
      EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
          'error', 'PAY_SETTLE_MANUAL_CONFIRM',
          'code', 'AUTH_INTENT_PAYMENT_DATE_INVALID',
          'message', 'The authorised frozen execution intent contains an invalid payment date.',
          'pay_batch_id', p_pay_batch_id::text,
          'operation_id', p_operation_id::text,
          'auth_request_id', v_operation_auth_request_id::text,
          'authorised_payment_date_raw', v_intent_payment_date_raw
        )::text USING ERRCODE = 'P0001';
      END;
    END IF;

    IF v_batch_intent_payment_date_raw IS NOT NULL THEN
      BEGIN
        v_batch_intent_payment_date := v_batch_intent_payment_date_raw::date;
      EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
          'error', 'PAY_SETTLE_MANUAL_CONFIRM',
          'code', 'BATCH_INTENT_PAYMENT_DATE_INVALID',
          'message', 'The batch execution intent contains an invalid payment date.',
          'pay_batch_id', p_pay_batch_id::text,
          'operation_id', p_operation_id::text,
          'batch_payment_date_raw', v_batch_intent_payment_date_raw
        )::text USING ERRCODE = 'P0001';
      END;
    END IF;

    IF v_auth_intent_operation_id IS NULL
       OR v_batch_intent_operation_id IS NULL
       OR v_auth_intent_operation_id <> v_execution_operation_id
       OR v_batch_intent_operation_id <> v_execution_operation_id
       OR v_auth_intent_operation_id <> v_batch_intent_operation_id
       OR v_auth_intent_auth_request_id IS DISTINCT FROM v_operation_auth_request_id
       OR v_batch_intent_auth_request_id IS DISTINCT FROM v_operation_auth_request_id
       OR v_intent_mode IS NULL
       OR v_intent_mode IS DISTINCT FROM v_batch_intent_mode
       OR v_operation_projection_scope IS NULL
       OR v_operation_projection_scope IS DISTINCT FROM v_batch_projection_scope
       OR v_expected_paye_net_state_hash IS NULL
       OR v_expected_paye_net_state_hash IS DISTINCT FROM v_batch_expected_paye_net_state_hash
       OR v_expected_global_bank_payment_projection_hash IS NULL
       OR v_expected_global_bank_payment_projection_hash IS DISTINCT FROM v_batch_expected_global_bank_payment_projection_hash
       OR v_expected_scoped_paye_net_state_hash IS NULL
       OR v_expected_scoped_paye_net_state_hash IS DISTINCT FROM v_batch_expected_scoped_paye_net_state_hash
       OR v_expected_bank_payment_projection_hash IS NULL
       OR v_expected_bank_payment_projection_hash IS DISTINCT FROM v_batch_expected_bank_payment_projection_hash
       OR v_expected_missing_count IS NULL
       OR v_expected_missing_count IS DISTINCT FROM v_batch_expected_missing_count
       OR v_expected_global_zero_count IS NULL
       OR v_expected_global_zero_count IS DISTINCT FROM v_batch_expected_global_zero_count
       OR v_expected_global_positive_count IS NULL
       OR v_expected_global_positive_count IS DISTINCT FROM v_batch_expected_global_positive_count
       OR v_expected_global_invalid_count IS NULL
       OR v_expected_global_invalid_count IS DISTINCT FROM v_batch_expected_global_invalid_count
       OR v_expected_scoped_missing_count IS NULL
       OR v_expected_scoped_missing_count IS DISTINCT FROM v_batch_expected_scoped_missing_count
       OR v_expected_zero_count IS NULL
       OR v_expected_zero_count IS DISTINCT FROM v_batch_expected_zero_count
       OR v_expected_positive_count IS NULL
       OR v_expected_positive_count IS DISTINCT FROM v_batch_expected_positive_count
       OR v_expected_positive_total IS NULL
       OR v_expected_positive_total IS DISTINCT FROM v_batch_expected_positive_total
       OR v_expected_scoped_invalid_count IS NULL
       OR v_expected_scoped_invalid_count IS DISTINCT FROM v_batch_expected_scoped_invalid_count
       OR v_server_owned_projection_proof IS NOT TRUE
       OR v_batch_server_owned_projection_proof IS NOT TRUE
       OR v_scoped_no_transfer_marker IS DISTINCT FROM v_batch_scoped_no_transfer_marker
       OR v_no_bank_payment_marker IS DISTINCT FROM v_batch_no_bank_payment_marker
       OR v_allow_explicit_zero_no_bank_scopes_marker IS DISTINCT FROM v_batch_allow_explicit_zero_no_bank_scopes_marker
       OR v_intent_suppress_remittances IS DISTINCT FROM v_batch_intent_suppress_remittances
       OR v_intent_payment_date IS DISTINCT FROM v_batch_intent_payment_date
       OR v_intent_csv_uploaded_confirmed IS DISTINCT FROM v_batch_intent_csv_uploaded_confirmed
       OR v_intent_bank_confirm_ref IS DISTINCT FROM v_batch_intent_bank_confirm_ref
       OR v_intent_external_comment IS DISTINCT FROM v_batch_intent_external_comment
       OR v_intent_csv_evidence_json IS DISTINCT FROM v_batch_csv_evidence_json THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'AUTH_BATCH_EXECUTION_INTENT_MISMATCH',
        'message', 'The authorised execution intent and batch execution intent are missing required server proof or are materially inconsistent.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'execution_operation_id', v_execution_operation_id::text,
        'auth_request_id', v_operation_auth_request_id::text,
        'authorised_execution_mode', v_intent_mode,
        'authorised_scope', v_operation_projection_scope
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF v_intent_mode IS DISTINCT FROM v_settlement_mode THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'AUTH_INTENT_MODE_MISMATCH',
        'message', 'The requested settlement mode does not match the authorised frozen execution intent.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'auth_request_id', v_operation_auth_request_id::text,
        'authorised_execution_mode', v_intent_mode,
        'requested_settlement_mode', v_settlement_mode
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF v_operation_projection_scope IS DISTINCT FROM v_scope THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'AUTH_INTENT_SCOPE_MISMATCH',
        'message', 'The requested settlement scope does not match the authorised frozen execution intent.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'auth_request_id', v_operation_auth_request_id::text,
        'authorised_scope', v_operation_projection_scope,
        'requested_scope', v_scope
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF COALESCE(p_suppress_remittances, false) IS DISTINCT FROM v_intent_suppress_remittances THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'SUPPRESS_REMITTANCES_INTENT_MISMATCH',
        'message', 'The suppress-remittances choice does not match the authorised frozen execution intent.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'auth_request_id', v_operation_auth_request_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF p_payment_date IS NOT NULL
       AND v_intent_payment_date IS NOT NULL
       AND p_payment_date IS DISTINCT FROM v_intent_payment_date THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'AUTH_INTENT_PAYMENT_DATE_MISMATCH',
        'message', 'The supplied payment date does not match the authorised frozen execution intent.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'auth_request_id', v_operation_auth_request_id::text,
        'authorised_payment_date', v_intent_payment_date::text,
        'requested_payment_date', p_payment_date::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    DROP TABLE IF EXISTS pg_temp.tmp_pay_settle_manual_projection_rows;
    CREATE TEMPORARY TABLE pg_temp.tmp_pay_settle_manual_projection_rows
    ON COMMIT DROP
    AS
    SELECT projection_row.*
    FROM public._pay_batch_bank_payment_projection_rows(
      p_pay_batch_id,
      'ALL'
    ) AS projection_row;

    DROP TABLE IF EXISTS pg_temp.tmp_pay_settle_manual_scoped_projection_rows;
    CREATE TEMPORARY TABLE pg_temp.tmp_pay_settle_manual_scoped_projection_rows
    ON COMMIT DROP
    AS
    SELECT projection_row.*
    FROM public._pay_batch_bank_payment_projection_rows(
      p_pay_batch_id,
      v_scope
    ) AS projection_row;

    SELECT
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'MISSING'
      )::integer,
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'ZERO'
      )::integer,
      COUNT(*) FILTER (WHERE projection_row.is_positive_bank_payment)::integer,
      COUNT(*) FILTER (
        WHERE (
          projection_row.paye_net_required IS TRUE
          AND COALESCE(projection_row.paye_net_classification, '') NOT IN ('MISSING', 'ZERO', 'POSITIVE')
        )
        OR (
          COALESCE(projection_row.paye_net_required, false) IS FALSE
          AND (
            projection_row.final_frozen_bank_amount IS NULL
            OR ROUND(projection_row.final_frozen_bank_amount, 2) <= 0
          )
        )
      )::integer,
      MAX(projection_row.paye_net_state_hash),
      MAX(projection_row.bank_payment_projection_hash)
    INTO
      v_current_missing_count,
      v_global_zero_count,
      v_global_positive_count,
      v_global_invalid_count,
      v_current_paye_net_state_hash,
      v_all_bank_payment_projection_hash
    FROM pg_temp.tmp_pay_settle_manual_projection_rows AS projection_row;

    SELECT
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'MISSING'
      )::integer,
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'ZERO'
      )::integer,
      COUNT(*) FILTER (WHERE projection_row.is_positive_bank_payment)::integer,
      ROUND(COALESCE(SUM(projection_row.amount) FILTER (WHERE projection_row.is_positive_bank_payment), 0), 2)::numeric(14,2),
      COUNT(*) FILTER (
        WHERE (
          projection_row.paye_net_required IS TRUE
          AND COALESCE(projection_row.paye_net_classification, '') NOT IN ('MISSING', 'ZERO', 'POSITIVE')
        )
        OR (
          COALESCE(projection_row.paye_net_required, false) IS FALSE
          AND (
            projection_row.final_frozen_bank_amount IS NULL
            OR ROUND(projection_row.final_frozen_bank_amount, 2) <= 0
          )
        )
      )::integer,
      MAX(projection_row.paye_net_state_hash),
      MAX(projection_row.bank_payment_projection_hash)
    INTO
      v_current_scoped_missing_count,
      v_current_zero_count,
      v_current_positive_count,
      v_current_positive_total,
      v_current_scoped_invalid_count,
      v_current_scoped_paye_net_state_hash,
      v_current_bank_payment_projection_hash
    FROM pg_temp.tmp_pay_settle_manual_scoped_projection_rows AS projection_row;

    v_current_missing_count := COALESCE(v_current_missing_count, 0);
    v_global_zero_count := COALESCE(v_global_zero_count, 0);
    v_global_positive_count := COALESCE(v_global_positive_count, 0);
    v_global_invalid_count := COALESCE(v_global_invalid_count, 0);
    v_current_scoped_missing_count := COALESCE(v_current_scoped_missing_count, 0);
    v_current_zero_count := COALESCE(v_current_zero_count, 0);
    v_current_positive_count := COALESCE(v_current_positive_count, 0);
    v_current_positive_total := ROUND(COALESCE(v_current_positive_total, 0), 2);
    v_current_scoped_invalid_count := COALESCE(v_current_scoped_invalid_count, 0);
    v_current_paye_net_state_hash := COALESCE(
      v_current_paye_net_state_hash,
      MD5(JSONB_BUILD_OBJECT('pay_batch_id', p_pay_batch_id::text, 'scope', 'ALL', 'rows', '[]'::jsonb)::text)
    );
    v_all_bank_payment_projection_hash := COALESCE(
      v_all_bank_payment_projection_hash,
      MD5(JSONB_BUILD_OBJECT('pay_batch_id', p_pay_batch_id::text, 'scope', 'ALL', 'rows', '[]'::jsonb)::text)
    );
    v_current_scoped_paye_net_state_hash := COALESCE(
      v_current_scoped_paye_net_state_hash,
      MD5(JSONB_BUILD_OBJECT('pay_batch_id', p_pay_batch_id::text, 'scope', v_scope, 'rows', '[]'::jsonb)::text)
    );
    v_current_bank_payment_projection_hash := COALESCE(
      v_current_bank_payment_projection_hash,
      MD5(JSONB_BUILD_OBJECT('pay_batch_id', p_pay_batch_id::text, 'scope', v_scope, 'rows', '[]'::jsonb)::text)
    );

    v_current_projection_changed := (
      v_expected_paye_net_state_hash IS DISTINCT FROM v_current_paye_net_state_hash
      OR v_expected_global_bank_payment_projection_hash IS DISTINCT FROM v_all_bank_payment_projection_hash
      OR v_expected_scoped_paye_net_state_hash IS DISTINCT FROM v_current_scoped_paye_net_state_hash
      OR v_expected_bank_payment_projection_hash IS DISTINCT FROM v_current_bank_payment_projection_hash
      OR v_expected_missing_count IS DISTINCT FROM v_current_missing_count
      OR v_expected_global_zero_count IS DISTINCT FROM v_global_zero_count
      OR v_expected_global_positive_count IS DISTINCT FROM v_global_positive_count
      OR v_expected_global_invalid_count IS DISTINCT FROM v_global_invalid_count
      OR v_expected_scoped_missing_count IS DISTINCT FROM v_current_scoped_missing_count
      OR v_expected_zero_count IS DISTINCT FROM v_current_zero_count
      OR v_expected_positive_count IS DISTINCT FROM v_current_positive_count
      OR ROUND(COALESCE(v_expected_positive_total, 0), 2) IS DISTINCT FROM ROUND(COALESCE(v_current_positive_total, 0), 2)
      OR v_expected_scoped_invalid_count IS DISTINCT FROM v_current_scoped_invalid_count
    );

    v_projection_diagnostic_json := JSONB_BUILD_OBJECT(
      'projection_changed_after_authorisation', v_current_projection_changed,
      'settlement_blocked_by_projection_change', false,
      'authorised_global_paye_net_state_hash', v_expected_paye_net_state_hash,
      'current_global_paye_net_state_hash', v_current_paye_net_state_hash,
      'authorised_global_bank_payment_projection_hash', v_expected_global_bank_payment_projection_hash,
      'current_global_bank_payment_projection_hash', v_all_bank_payment_projection_hash,
      'authorised_scoped_paye_net_state_hash', v_expected_scoped_paye_net_state_hash,
      'current_scoped_paye_net_state_hash', v_current_scoped_paye_net_state_hash,
      'authorised_scoped_bank_payment_projection_hash', v_expected_bank_payment_projection_hash,
      'current_scoped_bank_payment_projection_hash', v_current_bank_payment_projection_hash,
      'authorised_scope', v_scope,
      'diagnostic_generated_at_utc', v_now::text
    );

    v_no_bank_scope_authorised := v_allow_explicit_zero_no_bank_scopes_marker
      AND COALESCE(v_expected_missing_count, -1) = 0
      AND COALESCE(v_expected_zero_count, 0) > 0
      AND COALESCE(v_expected_scoped_invalid_count, -1) = 0;
    v_no_bank_payment_execution_validated := v_no_bank_payment_marker
      AND v_scoped_no_transfer_marker
      AND v_no_bank_scope_authorised
      AND COALESCE(v_expected_positive_count, -1) = 0
      AND COALESCE(v_expected_global_positive_count, -1) = 0
      AND COALESCE(v_expected_global_invalid_count, -1) = 0;
    v_local_no_bank_commit_ref := 'NO_BANK_PAYMENT:' || COALESCE(
      v_operation_auth_request_id::text,
      v_execution_operation_id::text,
      p_operation_id::text
    );
    v_proof_validation_outcome := CASE
      WHEN v_no_bank_payment_execution_validated THEN 'VALIDATED_NO_BANK_PAYMENT_FROM_AUTHORISED_INTENT'
      WHEN v_no_bank_scope_authorised AND COALESCE(v_expected_positive_count, 0) > 0 THEN 'VALIDATED_MIXED_ZERO_AND_TRANSFER_FROM_AUTHORISED_INTENT'
      WHEN v_no_bank_scope_authorised THEN 'VALIDATED_SCOPED_NO_TRANSFER_FROM_AUTHORISED_INTENT'
      ELSE 'VALIDATED_TRANSFER_BACKED_FROM_AUTHORISED_INTENT'
    END;

    IF v_no_bank_payment_execution_validated THEN
      SELECT COUNT(*)::integer
      INTO v_no_bank_transfer_scope_count
      FROM public.banking_pay_operation_transfer_scope AS transfer_scope_row
      WHERE transfer_scope_row.operation_id = v_execution_operation_id
        AND transfer_scope_row.pay_batch_id = p_pay_batch_id;

      SELECT COUNT(*)::integer
      INTO v_no_bank_batch_transfer_count
      FROM public.pay_bank_transfers AS transfer_row
      WHERE transfer_row.pay_batch_id = p_pay_batch_id;

      SELECT COUNT(*)::integer
      INTO v_no_bank_transfer_event_count
      FROM public.pay_bank_transfer_events AS transfer_event_row
      WHERE transfer_event_row.pay_batch_id = p_pay_batch_id;

      SELECT COUNT(*)::integer
      INTO v_no_bank_provider_attempt_count
      FROM public.banking_pay_operation_provider_attempts AS provider_attempt_row
      WHERE provider_attempt_row.operation_id = v_execution_operation_id;

      IF COALESCE(v_no_bank_transfer_scope_count, 0) <> 0
         OR COALESCE(v_no_bank_batch_transfer_count, 0) <> 0
         OR COALESCE(v_no_bank_transfer_event_count, 0) <> 0
         OR COALESCE(v_no_bank_provider_attempt_count, 0) <> 0 THEN
        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
          'error', 'PAY_SETTLE_MANUAL_CONFIRM',
          'code', 'NO_BANK_PAYMENT_EXECUTION_EVIDENCE_CONFLICT',
          'message', 'No-bank manual settlement cannot continue because transfer, transfer-event, or provider-submission evidence exists for the authorised all-zero execution.',
          'pay_batch_id', p_pay_batch_id::text,
          'operation_id', p_operation_id::text,
          'execution_operation_id', v_execution_operation_id::text,
          'transfer_scope_count', COALESCE(v_no_bank_transfer_scope_count, 0),
          'bank_transfer_count', COALESCE(v_no_bank_batch_transfer_count, 0),
          'bank_transfer_event_count', COALESCE(v_no_bank_transfer_event_count, 0),
          'provider_attempt_count', COALESCE(v_no_bank_provider_attempt_count, 0)
        )::text USING ERRCODE = 'P0001';
      END IF;
    END IF;

    IF v_settlement_mode = 'CSV_SETTLEMENT' THEN
      v_frozen_csv_validated := LOWER(BTRIM(COALESCE(v_intent_csv_evidence_json->>'validated', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
      v_frozen_csv_scope := UPPER(NULLIF(BTRIM(COALESCE(v_intent_csv_evidence_json->>'scope', '')), ''));
      v_frozen_csv_paye_net_state_hash := NULLIF(BTRIM(COALESCE(v_intent_csv_evidence_json->>'paye_net_state_hash', '')), '');
      v_frozen_csv_bank_projection_hash := NULLIF(BTRIM(COALESCE(v_intent_csv_evidence_json->>'bank_payment_projection_hash', '')), '');
      IF COALESCE(v_intent_csv_evidence_json->>'row_count', '') ~ '^[0-9]+$' THEN
        v_frozen_csv_row_count := (v_intent_csv_evidence_json->>'row_count')::integer;
      END IF;
      IF COALESCE(v_intent_csv_evidence_json->>'total_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
        v_frozen_csv_total := ROUND((v_intent_csv_evidence_json->>'total_amount')::numeric, 2)::numeric(14,2);
      END IF;
      v_frozen_csv_zero_row := LOWER(BTRIM(COALESCE(v_intent_csv_evidence_json->>'zero_row', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
      v_frozen_csv_confirmation_kind := UPPER(NULLIF(BTRIM(COALESCE(v_intent_csv_evidence_json->>'confirmation_kind', '')), ''));

      IF v_frozen_csv_validated IS NOT TRUE
         OR v_frozen_csv_scope IS DISTINCT FROM v_scope
         OR v_frozen_csv_paye_net_state_hash IS DISTINCT FROM v_expected_scoped_paye_net_state_hash
         OR v_frozen_csv_bank_projection_hash IS DISTINCT FROM v_expected_bank_payment_projection_hash
         OR v_frozen_csv_row_count IS NULL
         OR v_frozen_csv_row_count <> v_expected_positive_count
         OR v_frozen_csv_total IS NULL
         OR ROUND(v_frozen_csv_total, 2) <> ROUND(v_expected_positive_total, 2)
         OR v_frozen_csv_zero_row IS DISTINCT FROM (COALESCE(v_expected_positive_count, 0) = 0)
         OR LOWER(BTRIM(COALESCE(v_intent_csv_evidence_json->>'csv_uploaded_confirmed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
          'error', 'PAY_SETTLE_MANUAL_CONFIRM',
          'code', 'AUTHORISED_CSV_EVIDENCE_INVALID',
          'message', 'The authorised frozen Bank CSV evidence is missing or inconsistent with the authorised payment projection.',
          'pay_batch_id', p_pay_batch_id::text,
          'operation_id', p_operation_id::text,
          'auth_request_id', v_operation_auth_request_id::text,
          'authorised_scope', v_scope,
          'frozen_csv_scope', v_frozen_csv_scope,
          'frozen_csv_row_count', v_frozen_csv_row_count,
          'authorised_positive_count', v_expected_positive_count,
          'frozen_csv_total', v_frozen_csv_total,
          'authorised_positive_total', v_expected_positive_total
        )::text USING ERRCODE = 'P0001';
      END IF;

      IF COALESCE(p_csv_uploaded_confirmed, false) IS NOT TRUE
         OR v_intent_csv_uploaded_confirmed IS NOT TRUE THEN
        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
          'error', 'PAY_SETTLE_MANUAL_CONFIRM',
          'code', 'CSV_UPLOAD_CONFIRMATION_REQUIRED',
          'message', CASE
            WHEN COALESCE(v_expected_positive_count, 0) = 0
              THEN 'Confirm that the authorised zero-row Bank CSV was reviewed and that no bank upload or payment was required.'
            ELSE 'Confirm that the authorised CloudTMS Bank CSV was uploaded or processed with the bank.'
          END,
          'pay_batch_id', p_pay_batch_id::text,
          'operation_id', p_operation_id::text
        )::text USING ERRCODE = 'P0001';
      END IF;

      IF COALESCE(v_expected_positive_count, 0) > 0 AND v_bank_confirm_ref IS NULL THEN
        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
          'error', 'PAY_SETTLE_MANUAL_CONFIRM',
          'code', 'CSV_BANK_CONFIRM_REF_REQUIRED',
          'message', 'Positive CSV settlement requires the bank confirmation reference frozen at authorisation.',
          'pay_batch_id', p_pay_batch_id::text,
          'operation_id', p_operation_id::text
        )::text USING ERRCODE = 'P0001';
      END IF;

      IF v_bank_confirm_ref IS DISTINCT FROM v_intent_bank_confirm_ref
         OR v_bank_confirm_ref IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_intent_csv_evidence_json->>'csv_bank_confirm_ref', '')), '') THEN
        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
          'error', 'PAY_SETTLE_MANUAL_CONFIRM',
          'code', 'CSV_BANK_CONFIRM_REF_INTENT_MISMATCH',
          'message', 'The supplied bank confirmation reference does not match the authorised frozen execution intent.',
          'pay_batch_id', p_pay_batch_id::text,
          'operation_id', p_operation_id::text,
          'auth_request_id', v_operation_auth_request_id::text
        )::text USING ERRCODE = 'P0001';
      END IF;
    ELSE
      IF COALESCE(v_expected_positive_count, 0) > 0
         AND v_external_settlement_comment IS NULL THEN
        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
          'error', 'PAY_SETTLE_MANUAL_CONFIRM',
          'code', 'EXTERNAL_SETTLEMENT_COMMENT_REQUIRED',
          'message', 'Positive external settlement requires a mandatory comment.',
          'pay_batch_id', p_pay_batch_id::text,
          'operation_id', p_operation_id::text
        )::text USING ERRCODE = 'P0001';
      END IF;

      IF v_external_settlement_comment IS DISTINCT FROM v_intent_external_comment THEN
        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
          'error', 'PAY_SETTLE_MANUAL_CONFIRM',
          'code', 'EXTERNAL_SETTLEMENT_COMMENT_INTENT_MISMATCH',
          'message', 'The supplied external settlement comment does not match the authorised frozen execution intent.',
          'pay_batch_id', p_pay_batch_id::text,
          'operation_id', p_operation_id::text,
          'auth_request_id', v_operation_auth_request_id::text
        )::text USING ERRCODE = 'P0001';
      END IF;
    END IF;

    v_operation_effective_payment_date := COALESCE(
      v_intent_payment_date,
      v_batch.authoritative_payment_date,
      v_batch.pay_date
    );

    IF p_payment_date IS NOT NULL
       AND p_payment_date IS DISTINCT FROM v_operation_effective_payment_date THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'AUTH_INTENT_PAYMENT_DATE_MISMATCH',
        'message', 'The supplied payment date does not match the authorised accounting payment date.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'authorised_payment_date', v_operation_effective_payment_date::text,
        'requested_payment_date', p_payment_date::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF v_operation_effective_payment_date IS NULL THEN
      RAISE EXCEPTION 'pay_settle_manual_confirm: payment_date is required';
    END IF;

    IF COALESCE(v_expected_positive_count, 0) > 0 AND v_intent_payment_date IS NULL THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'AUTH_INTENT_PAYMENT_DATE_REQUIRED',
        'message', 'Positive manual settlement requires a valid payment date in the authorised execution intent.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'auth_request_id', v_operation_auth_request_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    DROP TABLE IF EXISTS pg_temp.tmp_pay_settle_manual_requested_scope_ids;
    CREATE TEMPORARY TABLE pg_temp.tmp_pay_settle_manual_requested_scope_ids (
      settlement_scope_id uuid PRIMARY KEY
    ) ON COMMIT DROP;

    INSERT INTO pg_temp.tmp_pay_settle_manual_requested_scope_ids (settlement_scope_id)
    SELECT DISTINCT (scope_element.value #>> '{}')::uuid
    FROM JSONB_ARRAY_ELEMENTS(p_settlement_scope_ids) AS scope_element(value)
    WHERE (scope_element.value #>> '{}')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

    SELECT COUNT(*)::integer
    INTO v_requested_scope_count
    FROM pg_temp.tmp_pay_settle_manual_requested_scope_ids AS requested_scope_id;

    IF v_requested_scope_count <> JSONB_ARRAY_LENGTH(p_settlement_scope_ids) THEN
      RAISE EXCEPTION 'p_settlement_scope_ids contains invalid or duplicate uuid values';
    END IF;

    PERFORM 1
    FROM public.banking_pay_operation_settlement_scope AS scope_row
    JOIN pg_temp.tmp_pay_settle_manual_requested_scope_ids AS requested_scope_id
      ON requested_scope_id.settlement_scope_id = scope_row.id
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id
    FOR UPDATE OF scope_row;

    SELECT
      COUNT(*)::integer,
      COUNT(*) FILTER (WHERE scope_row.status = 'SETTLED')::integer,
      COUNT(*) FILTER (WHERE scope_row.status = 'FAILED')::integer
    INTO
      v_matched_scope_count,
      v_reused_this_chunk,
      v_failed_this_chunk
    FROM public.banking_pay_operation_settlement_scope AS scope_row
    JOIN pg_temp.tmp_pay_settle_manual_requested_scope_ids AS requested_scope_id
      ON requested_scope_id.settlement_scope_id = scope_row.id
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id;

    IF v_matched_scope_count <> v_requested_scope_count THEN
      RAISE EXCEPTION 'one or more settlement scope ids do not belong to operation % and batch %', p_operation_id, p_pay_batch_id;
    END IF;

    DROP TABLE IF EXISTS pg_temp.tmp_pay_settle_manual_eligible_no_bank_scope;
    CREATE TEMPORARY TABLE pg_temp.tmp_pay_settle_manual_eligible_no_bank_scope
    ON COMMIT DROP
    AS
    WITH frozen_scope AS (
      SELECT
        scope_row.id AS settlement_scope_id,
        scope_row.status,
        scope_row.pay_batch_candidate_id,
        scope_row.candidate_id,
        scope_row.payload_json
      FROM public.banking_pay_operation_settlement_scope AS scope_row
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
        AND scope_row.status IN ('PENDING', 'SETTLED')
        AND scope_row.settlement_event_id IS NULL
        AND v_no_bank_scope_authorised
        AND UPPER(BTRIM(COALESCE(scope_row.pay_channel, ''))) = 'PAYE'
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'pay_batch_id', '')), '') = p_pay_batch_id::text
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'pay_batch_candidate_id', '')), '') = scope_row.pay_batch_candidate_id::text
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'candidate_id', '')), '') = scope_row.candidate_id::text
        AND UPPER(NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'pay_channel', '')), '')) = 'PAYE'
        AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'scope_kind', ''))) = 'NO_BANK_PAYMENT'
        AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_reason', ''))) = 'EXPLICIT_ZERO_PAYE'
        AND LOWER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_scope', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(scope_row.payload_json->>'server_owned_payment_projection_proof', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'pay_bank_transfer_id', '')), '') IS NULL
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')), '') IS NULL
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'execution_operation_id', '')), '') = v_execution_operation_id::text
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'settlement_operation_id', '')), '') = p_operation_id::text
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'auth_request_id', '')), '') = v_operation_auth_request_id::text
        AND UPPER(NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'authorised_execution_mode', '')), '')) IS NOT DISTINCT FROM v_intent_mode
        AND UPPER(NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'authorised_scope', scope_row.payload_json->>'projection_scope', '')), '')) IS NOT DISTINCT FROM v_scope
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'authorised_paye_net_state_hash', scope_row.payload_json->>'paye_net_state_hash', '')), '') = v_expected_paye_net_state_hash
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'global_bank_payment_projection_hash', '')), '') = v_expected_global_bank_payment_projection_hash
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'scoped_paye_net_state_hash', '')), '') = v_expected_scoped_paye_net_state_hash
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'authorised_bank_payment_projection_hash', scope_row.payload_json->>'bank_payment_projection_hash', '')), '') = v_expected_bank_payment_projection_hash
        AND (LOWER(BTRIM(COALESCE(scope_row.payload_json->>'scoped_no_transfer_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) = v_scoped_no_transfer_marker
        AND (LOWER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) = v_no_bank_payment_marker
        AND (LOWER(BTRIM(COALESCE(scope_row.payload_json->>'allow_explicit_zero_no_bank_scopes', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) = v_allow_explicit_zero_no_bank_scopes_marker
        AND COALESCE(scope_row.payload_json->>'authorised_missing_explicit_paye_input_count', '') ~ '^[0-9]+$'
        AND (scope_row.payload_json->>'authorised_missing_explicit_paye_input_count')::integer = v_expected_missing_count
        AND COALESCE(scope_row.payload_json->>'authorised_explicit_zero_count', '') ~ '^[0-9]+$'
        AND (scope_row.payload_json->>'authorised_explicit_zero_count')::integer = v_expected_global_zero_count
        AND COALESCE(scope_row.payload_json->>'authorised_global_positive_bank_payment_count', '') ~ '^[0-9]+$'
        AND (scope_row.payload_json->>'authorised_global_positive_bank_payment_count')::integer = v_expected_global_positive_count
        AND COALESCE(scope_row.payload_json->>'authorised_global_invalid_payment_row_count', '') ~ '^[0-9]+$'
        AND (scope_row.payload_json->>'authorised_global_invalid_payment_row_count')::integer = v_expected_global_invalid_count
        AND COALESCE(scope_row.payload_json->>'authorised_scoped_missing_explicit_paye_input_count', '') ~ '^[0-9]+$'
        AND (scope_row.payload_json->>'authorised_scoped_missing_explicit_paye_input_count')::integer = v_expected_scoped_missing_count
        AND COALESCE(scope_row.payload_json->>'authorised_scoped_explicit_zero_count', '') ~ '^[0-9]+$'
        AND (scope_row.payload_json->>'authorised_scoped_explicit_zero_count')::integer = v_expected_zero_count
        AND COALESCE(scope_row.payload_json->>'authorised_scoped_positive_bank_payment_count', '') ~ '^[0-9]+$'
        AND (scope_row.payload_json->>'authorised_scoped_positive_bank_payment_count')::integer = v_expected_positive_count
        AND COALESCE(scope_row.payload_json->>'authorised_scoped_invalid_payment_row_count', '') ~ '^[0-9]+$'
        AND (scope_row.payload_json->>'authorised_scoped_invalid_payment_row_count')::integer = v_expected_scoped_invalid_count
        AND JSONB_TYPEOF(scope_row.payload_json->'pay_batch_item_ids') = 'array'
        AND JSONB_ARRAY_LENGTH(scope_row.payload_json->'pay_batch_item_ids') > 0
        AND COALESCE(scope_row.payload_json->>'item_count', '') ~ '^[0-9]+$'
        AND (scope_row.payload_json->>'item_count')::integer = JSONB_ARRAY_LENGTH(scope_row.payload_json->'pay_batch_item_ids')
        AND NOT EXISTS (
          SELECT 1
          FROM JSONB_ARRAY_ELEMENTS_TEXT(scope_row.payload_json->'pay_batch_item_ids') AS item_element(item_id_text)
          WHERE item_element.item_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             OR NOT EXISTS (
               SELECT 1
               FROM public.pay_batch_items AS payload_item
               WHERE payload_item.id = CASE
                       WHEN item_element.item_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                         THEN item_element.item_id_text::uuid
                       ELSE NULL::uuid
                     END
                 AND payload_item.pay_batch_candidate_id = scope_row.pay_batch_candidate_id
                 AND UPPER(BTRIM(COALESCE(payload_item.pay_channel, ''))) = 'PAYE'
                 AND COALESCE(payload_item.is_voided, false) = false
                 AND COALESCE(payload_item.item_type, '') <> 'DEBT_CREATED'
                 AND payload_item.pay_bank_transfer_id IS NULL
             )
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_batch_items AS candidate_scope_item
          WHERE candidate_scope_item.pay_batch_candidate_id = scope_row.pay_batch_candidate_id
            AND UPPER(BTRIM(COALESCE(candidate_scope_item.pay_channel, ''))) = 'PAYE'
            AND COALESCE(candidate_scope_item.is_voided, false) = false
            AND COALESCE(candidate_scope_item.item_type, '') <> 'DEBT_CREATED'
            AND NOT (scope_row.payload_json->'pay_batch_item_ids' @> JSONB_BUILD_ARRAY(TO_JSONB(candidate_scope_item.id::text)))
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_batch_items AS linked_item
          WHERE linked_item.pay_batch_candidate_id = scope_row.pay_batch_candidate_id
            AND UPPER(BTRIM(COALESCE(linked_item.pay_channel, ''))) = 'PAYE'
            AND COALESCE(linked_item.is_voided, false) = false
            AND linked_item.pay_bank_transfer_id IS NOT NULL
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_transfer_scope AS transfer_scope_evidence
          WHERE transfer_scope_evidence.operation_id = v_execution_operation_id
            AND transfer_scope_evidence.pay_batch_id = p_pay_batch_id
            AND transfer_scope_evidence.candidate_id = scope_row.candidate_id
            AND UPPER(BTRIM(COALESCE(transfer_scope_evidence.pay_channel, ''))) = 'PAYE'
            AND (
              transfer_scope_evidence.pay_bank_transfer_id IS NOT NULL
              OR transfer_scope_evidence.provider_submit_attempt_count > 0
              OR transfer_scope_evidence.provider_request_sent_at_utc IS NOT NULL
              OR NULLIF(BTRIM(COALESCE(transfer_scope_evidence.provider_request_id, '')), '') IS NOT NULL
              OR NULLIF(BTRIM(COALESCE(transfer_scope_evidence.provider_transaction_id, '')), '') IS NOT NULL
            )
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_bank_transfers AS transfer_evidence
          WHERE transfer_evidence.pay_batch_id = p_pay_batch_id
            AND transfer_evidence.candidate_id = scope_row.candidate_id
            AND UPPER(BTRIM(COALESCE(transfer_evidence.pay_channel, ''))) = 'PAYE'
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_bank_transfer_events AS transfer_event_evidence
          LEFT JOIN public.pay_bank_transfers AS event_transfer_evidence
            ON event_transfer_evidence.id = transfer_event_evidence.pay_bank_transfer_id
          WHERE transfer_event_evidence.pay_batch_id = p_pay_batch_id
            AND transfer_event_evidence.candidate_id = scope_row.candidate_id
            AND (
              transfer_event_evidence.pay_bank_transfer_id IS NULL
              OR UPPER(BTRIM(COALESCE(event_transfer_evidence.pay_channel, ''))) = 'PAYE'
            )
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_provider_attempts AS provider_attempt_evidence
          JOIN public.banking_pay_operation_transfer_scope AS provider_attempt_scope
            ON provider_attempt_scope.id = provider_attempt_evidence.transfer_scope_id
          WHERE provider_attempt_evidence.operation_id = v_execution_operation_id
            AND provider_attempt_scope.pay_batch_id = p_pay_batch_id
            AND provider_attempt_scope.candidate_id = scope_row.candidate_id
            AND UPPER(BTRIM(COALESCE(provider_attempt_scope.pay_channel, ''))) = 'PAYE'
        )
    ), current_zero AS (
      SELECT DISTINCT
        projection_row.pay_batch_candidate_id,
        projection_row.candidate_id,
        projection_row.effective_paye_net_input_id
      FROM pg_temp.tmp_pay_settle_manual_scoped_projection_rows AS projection_row
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.id = projection_row.pay_batch_candidate_id
       AND batch_candidate.pay_batch_id = p_pay_batch_id
      WHERE projection_row.is_paye_net_state_row
        AND projection_row.pay_channel = 'PAYE'
        AND projection_row.has_effective_paye_input IS TRUE
        AND projection_row.effective_paye_net_input_id IS NOT NULL
        AND projection_row.paye_net_classification = 'ZERO'
        AND projection_row.final_frozen_bank_amount IS NOT NULL
        AND ROUND(projection_row.final_frozen_bank_amount, 2) = 0
        AND batch_candidate.net_bank_amount IS NOT NULL
        AND ROUND(batch_candidate.net_bank_amount, 2) = 0
    )
    SELECT
      frozen_scope.settlement_scope_id,
      frozen_scope.pay_batch_candidate_id,
      frozen_scope.candidate_id
    FROM frozen_scope
    LEFT JOIN current_zero
      ON current_zero.pay_batch_candidate_id = frozen_scope.pay_batch_candidate_id
     AND current_zero.candidate_id = frozen_scope.candidate_id
    WHERE frozen_scope.status = 'SETTLED'
       OR (
         frozen_scope.status = 'PENDING'
         AND current_zero.pay_batch_candidate_id IS NOT NULL
         AND NULLIF(BTRIM(COALESCE(frozen_scope.payload_json->>'effective_paye_net_input_id', '')), '') = current_zero.effective_paye_net_input_id::text
         AND COALESCE(frozen_scope.payload_json->>'net_bank_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
         AND ROUND((frozen_scope.payload_json->>'net_bank_amount')::numeric, 2) = 0
       );

    SELECT
      COUNT(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(scope_row.payload_json->>'scope_kind', ''))) = 'NO_BANK_PAYMENT'
          AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_reason', ''))) = 'EXPLICIT_ZERO_PAYE'
      )::integer,
      COUNT(eligible_scope.settlement_scope_id)::integer
    INTO
      v_selected_no_bank_scope_count,
      v_selected_eligible_no_bank_scope_count
    FROM public.banking_pay_operation_settlement_scope AS scope_row
    JOIN pg_temp.tmp_pay_settle_manual_requested_scope_ids AS requested_scope_id
      ON requested_scope_id.settlement_scope_id = scope_row.id
    LEFT JOIN pg_temp.tmp_pay_settle_manual_eligible_no_bank_scope AS eligible_scope
      ON eligible_scope.settlement_scope_id = scope_row.id
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id;

    IF COALESCE(v_selected_no_bank_scope_count, 0) <> COALESCE(v_selected_eligible_no_bank_scope_count, 0) THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'NO_BANK_SETTLEMENT_SCOPE_PROOF_INVALID',
        'message', 'One or more requested no-bank settlement scopes are not bound to the authorised execution proof or contain transfer/provider evidence.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'execution_operation_id', v_execution_operation_id::text,
        'auth_request_id', v_operation_auth_request_id::text,
        'requested_no_bank_scope_count', COALESCE(v_selected_no_bank_scope_count, 0),
        'eligible_no_bank_scope_count', COALESCE(v_selected_eligible_no_bank_scope_count, 0)
      )::text USING ERRCODE = 'P0001';
    END IF;

    WITH pending_scope AS (
      SELECT scope_row.*
      FROM public.banking_pay_operation_settlement_scope AS scope_row
      JOIN pg_temp.tmp_pay_settle_manual_requested_scope_ids AS requested_scope_id
        ON requested_scope_id.settlement_scope_id = scope_row.id
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
        AND scope_row.status = 'PENDING'
    ), payload_transfer AS (
      SELECT
        pending_scope.id AS settlement_scope_id,
        CASE
          WHEN COALESCE(pending_scope.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')
               ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN (pending_scope.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}')::uuid
          ELSE NULL::uuid
        END AS pay_bank_transfer_id
      FROM pending_scope
    ), payload_item_ids AS (
      SELECT
        pending_scope.id AS settlement_scope_id,
        (item_element.value #>> '{}')::uuid AS pay_batch_item_id
      FROM pending_scope
      CROSS JOIN LATERAL JSONB_ARRAY_ELEMENTS(
        CASE
          WHEN JSONB_TYPEOF(pending_scope.payload_json->'pay_batch_item_ids') = 'array'
            THEN pending_scope.payload_json->'pay_batch_item_ids'
          ELSE '[]'::jsonb
        END
      ) AS item_element(value)
      WHERE (item_element.value #>> '{}')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), scope_transfer_candidates AS (
      SELECT DISTINCT
        pending_scope.id AS settlement_scope_id,
        pending_scope.candidate_id,
        pending_scope.pay_channel,
        COALESCE(payload_transfer.pay_bank_transfer_id, batch_item.pay_bank_transfer_id) AS pay_bank_transfer_id
      FROM pending_scope
      LEFT JOIN payload_transfer
        ON payload_transfer.settlement_scope_id = pending_scope.id
      LEFT JOIN payload_item_ids
        ON payload_item_ids.settlement_scope_id = pending_scope.id
      LEFT JOIN public.pay_batch_items AS batch_item
        ON batch_item.id = payload_item_ids.pay_batch_item_id
      WHERE COALESCE(payload_transfer.pay_bank_transfer_id, batch_item.pay_bank_transfer_id) IS NOT NULL
    ), scope_transfers AS (
      SELECT DISTINCT
        scope_transfer_candidate.settlement_scope_id,
        transfer_row.id AS pay_bank_transfer_id
      FROM scope_transfer_candidates AS scope_transfer_candidate
      JOIN public.pay_bank_transfers AS transfer_row
        ON transfer_row.id = scope_transfer_candidate.pay_bank_transfer_id
       AND transfer_row.pay_batch_id = p_pay_batch_id
       AND transfer_row.candidate_id IS NOT DISTINCT FROM scope_transfer_candidate.candidate_id
       AND UPPER(BTRIM(COALESCE(transfer_row.pay_channel, '')))
           = UPPER(BTRIM(COALESCE(scope_transfer_candidate.pay_channel, '')))
    ), eligible_no_bank_scope AS (
      SELECT
        eligible_scope.settlement_scope_id,
        eligible_scope.pay_batch_candidate_id,
        eligible_scope.candidate_id
      FROM pg_temp.tmp_pay_settle_manual_eligible_no_bank_scope AS eligible_scope
      JOIN pending_scope
        ON pending_scope.id = eligible_scope.settlement_scope_id
    ), inserted_events AS (
      INSERT INTO public.pay_bank_transfer_events (
        pay_batch_id,
        pay_bank_transfer_id,
        candidate_id,
        umbrella_id,
        provider_key,
        provider_event_id,
        provider_reference,
        provider_state,
        normalised_state,
        event_source,
        event_time_utc,
        received_at_utc,
        amount,
        currency,
        mapping_status,
        movement_classification,
        correction_disposition,
        raw_payload,
        idempotency_key,
        mapping_method
      )
      SELECT
        p_pay_batch_id,
        scope_transfers.pay_bank_transfer_id,
        bank_transfer.candidate_id,
        bank_transfer.umbrella_id,
        COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.rail_provider, '')), ''), v_settlement_mode),
        'manual-settlement:' || p_operation_id::text || ':' || scope_transfers.settlement_scope_id::text || ':' || scope_transfers.pay_bank_transfer_id::text,
        COALESCE(v_bank_confirm_ref, 'manual-settlement:' || p_operation_id::text, bank_transfer.payment_reference, bank_transfer.request_id),
        CASE WHEN v_settlement_mode = 'CSV_SETTLEMENT' THEN 'CSV_MANUAL_CONFIRM' ELSE 'EXTERNAL_SETTLEMENT_CONFIRM' END,
        'COMPLETED',
        'MANUAL_CONFIRM',
        v_now,
        v_now,
        bank_transfer.amount,
        COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.currency, '')), ''), 'GBP'),
        'MATCHED',
        NULL::text,
        NULL::text,
        JSONB_STRIP_NULLS(JSONB_BUILD_OBJECT(
          'source_rpc', 'pay_settle_manual_confirm',
          'operation_id', p_operation_id::text,
          'settlement_scope_id', scope_transfers.settlement_scope_id::text,
          'settlement_mode', v_settlement_mode,
          'bank_confirm_ref', CASE WHEN v_settlement_mode = 'CSV_SETTLEMENT' THEN v_bank_confirm_ref ELSE NULL END,
          'external_settlement_comment', CASE WHEN v_settlement_mode = 'EXTERNAL_SETTLEMENT' THEN v_external_settlement_comment ELSE NULL END,
          'payment_date', v_operation_effective_payment_date::text,
          'suppress_remittances', COALESCE(p_suppress_remittances, false)
        )),
        'manual-settlement:' || p_operation_id::text || ':' || scope_transfers.settlement_scope_id::text || ':' || scope_transfers.pay_bank_transfer_id::text,
        'TRANSFER_ID'
      FROM scope_transfers
      JOIN public.pay_bank_transfers AS bank_transfer
        ON bank_transfer.id = scope_transfers.pay_bank_transfer_id
       AND bank_transfer.pay_batch_id = p_pay_batch_id
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.pay_bank_transfer_events AS existing_event
        WHERE existing_event.pay_batch_id = p_pay_batch_id
          AND existing_event.idempotency_key = 'manual-settlement:' || p_operation_id::text || ':' || scope_transfers.settlement_scope_id::text || ':' || scope_transfers.pay_bank_transfer_id::text
      )
      RETURNING
        public.pay_bank_transfer_events.id,
        public.pay_bank_transfer_events.idempotency_key
    ), all_events AS (
      SELECT
        scope_transfers.settlement_scope_id,
        inserted_event.id AS event_id
      FROM scope_transfers
      JOIN inserted_events AS inserted_event
        ON inserted_event.idempotency_key = 'manual-settlement:' || p_operation_id::text || ':' || scope_transfers.settlement_scope_id::text || ':' || scope_transfers.pay_bank_transfer_id::text

      UNION ALL

      SELECT
        scope_transfers.settlement_scope_id,
        existing_event.id AS event_id
      FROM scope_transfers
      JOIN public.pay_bank_transfer_events AS existing_event
        ON existing_event.pay_batch_id = p_pay_batch_id
       AND existing_event.idempotency_key = 'manual-settlement:' || p_operation_id::text || ':' || scope_transfers.settlement_scope_id::text || ':' || scope_transfers.pay_bank_transfer_id::text
    ), event_by_scope AS (
      SELECT
        all_events.settlement_scope_id,
        (ARRAY_AGG(all_events.event_id ORDER BY all_events.event_id))[1] AS event_id
      FROM all_events
      GROUP BY all_events.settlement_scope_id
    ), transfer_updates AS (
      UPDATE public.pay_bank_transfers AS transfer_update
      SET status = 'COMPLETED',
          rail_state = CASE WHEN v_settlement_mode = 'CSV_SETTLEMENT' THEN 'CSV_MANUAL_CONFIRM' ELSE 'EXTERNAL_SETTLEMENT_CONFIRM' END,
          rail_meta_json = JSONB_STRIP_NULLS(
            COALESCE(transfer_update.rail_meta_json, '{}'::jsonb)
            || JSONB_BUILD_OBJECT(
              'settlement_mode', v_settlement_mode,
              'manual_settlement_operation_id', p_operation_id::text,
              'bank_confirm_ref', CASE WHEN v_settlement_mode = 'CSV_SETTLEMENT' THEN v_bank_confirm_ref ELSE NULL END,
              'external_settlement_comment', CASE WHEN v_settlement_mode = 'EXTERNAL_SETTLEMENT' THEN v_external_settlement_comment ELSE NULL END,
              'payment_date', v_operation_effective_payment_date::text,
              'settled_at_utc', v_now::text,
              'settled_by_user_id', p_actor_user_id::text
            )
          ),
          completed_at_utc = COALESCE(transfer_update.completed_at_utc, v_now),
          failed_reason = NULL::text
      FROM scope_transfers
      WHERE transfer_update.id = scope_transfers.pay_bank_transfer_id
        AND transfer_update.pay_batch_id = p_pay_batch_id
        AND UPPER(COALESCE(transfer_update.status, '')) NOT IN ('COMPLETED', 'COMMITTED', 'SETTLED', 'PAID', 'EXECUTED')
      RETURNING transfer_update.id
    ), failed_scope_no_transfer AS (
      UPDATE public.banking_pay_operation_settlement_scope AS scope_update
      SET status = 'FAILED',
          payload_json = JSONB_STRIP_NULLS(
            COALESCE(scope_update.payload_json, '{}'::jsonb)
            || JSONB_BUILD_OBJECT(
              'settlement_failure_code', 'NO_PAY_BANK_TRANSFER_FOR_SCOPE',
              'settlement_failure_message', 'Settlement scope could not be settled because it does not resolve to a frozen pay_bank_transfer row.',
              'failed_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      FROM pending_scope
      WHERE scope_update.id = pending_scope.id
        AND NOT EXISTS (
          SELECT 1
          FROM scope_transfers
          WHERE scope_transfers.settlement_scope_id = pending_scope.id
        )
        AND NOT EXISTS (
          SELECT 1
          FROM eligible_no_bank_scope
          WHERE eligible_no_bank_scope.settlement_scope_id = pending_scope.id
        )
      RETURNING scope_update.id, scope_update.pay_batch_candidate_id
    ), settled_transfer_scope AS (
      UPDATE public.banking_pay_operation_settlement_scope AS scope_update
      SET status = 'SETTLED',
          settlement_event_id = COALESCE(scope_update.settlement_event_id, event_by_scope.event_id),
          updated_at_utc = v_now
      FROM pending_scope
      JOIN scope_transfers
        ON scope_transfers.settlement_scope_id = pending_scope.id
      JOIN event_by_scope
        ON event_by_scope.settlement_scope_id = pending_scope.id
      WHERE scope_update.id = pending_scope.id
      RETURNING scope_update.id, scope_update.pay_batch_candidate_id
    ), settled_no_bank_scope AS (
      UPDATE public.banking_pay_operation_settlement_scope AS scope_update
      SET status = 'SETTLED',
          settlement_event_id = NULL::uuid,
          payload_json = JSONB_STRIP_NULLS(
            COALESCE(scope_update.payload_json, '{}'::jsonb)
            || JSONB_BUILD_OBJECT(
              'no_bank_payment_scope', true,
              'no_bank_payment_execution', v_no_bank_payment_execution_validated,
              'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes_marker,
              'confirmation_mode', CASE
                WHEN v_no_bank_payment_execution_validated
                 AND v_settlement_mode = 'CSV_SETTLEMENT'
                  THEN 'NO_BANK_PAYMENT_REVIEW'
                WHEN v_no_bank_payment_execution_validated
                  THEN 'NO_BANK_PAYMENT_EXECUTION'
                ELSE 'EXPLICIT_ZERO_NO_BANK_SCOPE'
              END,
              'local_commit_reference', v_local_no_bank_commit_ref,
              'paye_net_state_hash', v_expected_paye_net_state_hash,
              'global_bank_payment_projection_hash', v_expected_global_bank_payment_projection_hash,
              'scoped_paye_net_state_hash', v_expected_scoped_paye_net_state_hash,
              'bank_payment_projection_hash', v_expected_bank_payment_projection_hash,
              'settlement_projection_diagnostic', v_projection_diagnostic_json,
              'projection_scope', v_scope,
              'execution_operation_id', v_execution_operation_id::text,
              'settlement_operation_id', p_operation_id::text,
              'auth_request_id', v_operation_auth_request_id::text,
              'authorised_execution_mode', v_intent_mode,
              'accounting_payment_date', v_operation_effective_payment_date::text,
              'settled_at_utc', v_now::text,
              'settled_by_user_id', p_actor_user_id::text
            )
          ),
          updated_at_utc = v_now
      FROM eligible_no_bank_scope
      WHERE scope_update.id = eligible_no_bank_scope.settlement_scope_id
      RETURNING scope_update.id, scope_update.pay_batch_candidate_id
    ), settled_scope AS (
      SELECT settled_transfer_scope.id, settled_transfer_scope.pay_batch_candidate_id
      FROM settled_transfer_scope
      UNION ALL
      SELECT settled_no_bank_scope.id, settled_no_bank_scope.pay_batch_candidate_id
      FROM settled_no_bank_scope
    ), candidate_base AS (
      SELECT settled_scope.pay_batch_candidate_id
      FROM settled_scope
      UNION
      SELECT scope_row.pay_batch_candidate_id
      FROM public.banking_pay_operation_settlement_scope AS scope_row
      JOIN pg_temp.tmp_pay_settle_manual_requested_scope_ids AS requested_scope_id
        ON requested_scope_id.settlement_scope_id = scope_row.id
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
        AND scope_row.status IN ('SETTLED', 'SKIPPED')
    ), candidate_complete AS (
      SELECT DISTINCT candidate_base.pay_batch_candidate_id
      FROM candidate_base
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_settlement_scope AS remaining_for_candidate
        WHERE remaining_for_candidate.operation_id = p_operation_id
          AND remaining_for_candidate.pay_batch_id = p_pay_batch_id
          AND remaining_for_candidate.pay_batch_candidate_id = candidate_base.pay_batch_candidate_id
          AND remaining_for_candidate.status NOT IN ('SETTLED', 'SKIPPED')
          AND NOT EXISTS (
            SELECT 1
            FROM settled_scope
            WHERE settled_scope.id = remaining_for_candidate.id
          )
      )
    ), candidate_updates AS (
      UPDATE public.pay_batch_candidates AS candidate_update
      SET settlement_status = 'SETTLED',
          settled_at_utc = COALESCE(candidate_update.settled_at_utc, v_now),
          settled_via = CASE
            WHEN EXISTS (
              SELECT 1
              FROM public.pay_batch_items AS candidate_item
              WHERE candidate_item.pay_batch_candidate_id = candidate_complete.pay_batch_candidate_id
                AND COALESCE(candidate_item.is_voided, false) = false
                AND candidate_item.pay_bank_transfer_id IS NOT NULL
            ) OR EXISTS (
              SELECT 1
              FROM public.banking_pay_operation_settlement_scope AS candidate_scope
              WHERE candidate_scope.operation_id = p_operation_id
                AND candidate_scope.pay_batch_id = p_pay_batch_id
                AND candidate_scope.pay_batch_candidate_id = candidate_complete.pay_batch_candidate_id
                AND NULLIF(BTRIM(COALESCE(candidate_scope.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')), '') IS NOT NULL
            ) THEN v_settlement_mode
            ELSE 'NO_BANK_PAYMENT'
          END,
          settled_note = COALESCE(
            candidate_update.settled_note,
            CASE
              WHEN EXISTS (
                SELECT 1
                FROM public.pay_batch_items AS candidate_item
                WHERE candidate_item.pay_batch_candidate_id = candidate_complete.pay_batch_candidate_id
                  AND COALESCE(candidate_item.is_voided, false) = false
                  AND candidate_item.pay_bank_transfer_id IS NOT NULL
              ) OR EXISTS (
                SELECT 1
                FROM public.banking_pay_operation_settlement_scope AS candidate_scope
                WHERE candidate_scope.operation_id = p_operation_id
                  AND candidate_scope.pay_batch_id = p_pay_batch_id
                  AND candidate_scope.pay_batch_candidate_id = candidate_complete.pay_batch_candidate_id
                  AND NULLIF(BTRIM(COALESCE(candidate_scope.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')), '') IS NOT NULL
              ) THEN CASE
                WHEN v_settlement_mode = 'CSV_SETTLEMENT' THEN v_bank_confirm_ref
                ELSE v_external_settlement_comment
              END
              ELSE v_local_no_bank_commit_ref
            END
          )
      FROM candidate_complete
      WHERE candidate_update.id = candidate_complete.pay_batch_candidate_id
      RETURNING candidate_update.id
    )
    SELECT
      (SELECT COUNT(*)::integer FROM settled_scope),
      COALESCE(v_failed_this_chunk, 0) + (SELECT COUNT(*)::integer FROM failed_scope_no_transfer),
      (SELECT COUNT(*)::integer FROM settled_no_bank_scope),
      (SELECT COUNT(*)::integer FROM candidate_updates)
    INTO
      v_settled_this_chunk,
      v_failed_this_chunk,
      v_no_bank_settled_this_chunk,
      v_candidate_updates_count;

    SELECT
      COUNT(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(scope_row.payload_json->>'scope_kind', ''))) = 'NO_BANK_PAYMENT'
          AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_reason', ''))) = 'EXPLICIT_ZERO_PAYE'
          AND scope_row.status <> 'SKIPPED'
      )::integer,
      COUNT(eligible_scope.settlement_scope_id)::integer
    INTO
      v_no_bank_total_scope_count,
      v_no_bank_eligible_scope_count
    FROM public.banking_pay_operation_settlement_scope AS scope_row
    LEFT JOIN pg_temp.tmp_pay_settle_manual_eligible_no_bank_scope AS eligible_scope
      ON eligible_scope.settlement_scope_id = scope_row.id
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id;

    v_no_bank_invalid_scope_count := GREATEST(
      COALESCE(v_no_bank_total_scope_count, 0) - COALESCE(v_no_bank_eligible_scope_count, 0),
      0
    );

    WITH scope_summary AS (
      SELECT
        COUNT(*)::integer AS total_scope_count,
        COUNT(*) FILTER (WHERE scope_row.status IN ('SETTLED', 'SKIPPED'))::integer AS successful_scope_count,
        COUNT(*) FILTER (WHERE scope_row.status = 'SETTLED')::integer AS settled_scope_count,
        COUNT(*) FILTER (WHERE scope_row.status = 'SKIPPED')::integer AS skipped_scope_count,
        COUNT(*) FILTER (
          WHERE NULLIF(BTRIM(COALESCE(scope_row.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')), '') IS NOT NULL
            AND scope_row.status <> 'SKIPPED'
        )::integer AS transfer_backed_scope_count,
        COUNT(*) FILTER (
          WHERE NULLIF(BTRIM(COALESCE(scope_row.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')), '') IS NOT NULL
            AND scope_row.status = 'SETTLED'
        )::integer AS settled_transfer_backed_scope_count,
        COUNT(*) FILTER (WHERE scope_row.status = 'FAILED')::integer AS terminal_failed_scope_count,
        COUNT(*) FILTER (WHERE scope_row.status = 'PENDING')::integer AS pending_scope_count,
        COUNT(*) FILTER (WHERE scope_row.status NOT IN ('SETTLED', 'SKIPPED', 'FAILED', 'PENDING'))::integer AS unknown_scope_count,
        COALESCE(
          JSONB_AGG(
            JSONB_BUILD_OBJECT(
              'scope_id', scope_row.id::text,
              'status', scope_row.status,
              'settlement_event_id', CASE WHEN scope_row.settlement_event_id IS NULL THEN NULL::text ELSE scope_row.settlement_event_id::text END,
              'scope_kind', scope_row.payload_json->>'scope_kind'
            )
            ORDER BY scope_row.id::text
          ),
          '[]'::jsonb
        ) AS scope_state_json
      FROM public.banking_pay_operation_settlement_scope AS scope_row
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
    ), completed_scope_transfer_ids AS (
      SELECT DISTINCT
        CASE
          WHEN COALESCE(scope_row.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')
               ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN (scope_row.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}')::uuid
          ELSE NULL::uuid
        END AS pay_bank_transfer_id
      FROM public.banking_pay_operation_settlement_scope AS scope_row
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
        AND scope_row.status = 'SETTLED'

      UNION

      SELECT DISTINCT batch_item.pay_bank_transfer_id
      FROM public.banking_pay_operation_settlement_scope AS scope_row
      CROSS JOIN LATERAL JSONB_ARRAY_ELEMENTS(
        CASE
          WHEN JSONB_TYPEOF(scope_row.payload_json->'pay_batch_item_ids') = 'array'
            THEN scope_row.payload_json->'pay_batch_item_ids'
          ELSE '[]'::jsonb
        END
      ) AS item_element(value)
      JOIN public.pay_batch_items AS batch_item
        ON batch_item.id = CASE
             WHEN (item_element.value #>> '{}')
                  ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
               THEN (item_element.value #>> '{}')::uuid
             ELSE NULL::uuid
           END
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
        AND scope_row.status = 'SETTLED'
        AND batch_item.pay_bank_transfer_id IS NOT NULL
    ), completed_transfer_summary AS (
      SELECT COUNT(DISTINCT transfer_row.id)::integer AS completed_transfer_count
      FROM completed_scope_transfer_ids AS completed_scope_transfer_id
      JOIN public.pay_bank_transfers AS transfer_row
        ON transfer_row.id = completed_scope_transfer_id.pay_bank_transfer_id
       AND transfer_row.pay_batch_id = p_pay_batch_id
      WHERE UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('COMPLETED', 'COMMITTED', 'SETTLED', 'PAID', 'EXECUTED')
         OR transfer_row.completed_at_utc IS NOT NULL
    )
    SELECT
      COALESCE(scope_summary.total_scope_count, 0),
      COALESCE(scope_summary.successful_scope_count, 0),
      COALESCE(scope_summary.settled_scope_count, 0),
      COALESCE(scope_summary.skipped_scope_count, 0),
      COALESCE(scope_summary.transfer_backed_scope_count, 0),
      COALESCE(scope_summary.settled_transfer_backed_scope_count, 0),
      COALESCE(scope_summary.terminal_failed_scope_count, 0),
      COALESCE(scope_summary.pending_scope_count, 0),
      COALESCE(scope_summary.unknown_scope_count, 0),
      COALESCE(completed_transfer_summary.completed_transfer_count, 0),
      scope_summary.scope_state_json
    INTO
      v_total_scope_count,
      v_successful_scope_count,
      v_settled_scope_count,
      v_skipped_scope_count,
      v_transfer_backed_scope_count,
      v_settled_transfer_backed_scope_count,
      v_terminal_failed_scope_count,
      v_pending_scope_count,
      v_unknown_scope_count,
      v_completed_transfer_count,
      v_operation_scope_state_json
    FROM scope_summary
    CROSS JOIN completed_transfer_summary;

    v_processor_failed_scope_count := 0;
    v_remaining_scope_count := COALESCE(v_pending_scope_count, 0) + COALESCE(v_unknown_scope_count, 0);
    v_has_more := COALESCE(v_pending_scope_count, 0) > 0;
    v_all_scopes_terminal := COALESCE(v_total_scope_count, 0) > 0
      AND COALESCE(v_pending_scope_count, 0) = 0
      AND COALESCE(v_unknown_scope_count, 0) = 0;
    v_all_scopes_successful := v_all_scopes_terminal
      AND COALESCE(v_terminal_failed_scope_count, 0) = 0
      AND COALESCE(v_successful_scope_count, 0) = COALESCE(v_total_scope_count, 0);
    v_completed_with_failed_payments := v_all_scopes_terminal
      AND COALESCE(v_terminal_failed_scope_count, 0) > 0;
    v_scope_settlement_complete := v_all_scopes_successful;
    v_requires_full_batch_finalisation := v_all_scopes_successful;
    v_full_batch_finalisation_safe := v_all_scopes_successful
      AND COALESCE(v_no_bank_invalid_scope_count, 0) = 0
      AND COALESCE(v_no_bank_total_scope_count, 0) = COALESCE(v_expected_zero_count, 0)
      AND COALESCE(v_settled_transfer_backed_scope_count, 0) = COALESCE(v_transfer_backed_scope_count, 0)
      AND (
        (
          COALESCE(v_expected_positive_count, 0) > 0
          AND COALESCE(v_transfer_backed_scope_count, 0) > 0
          AND COALESCE(v_completed_transfer_count, 0) > 0
        )
        OR (
          COALESCE(v_expected_positive_count, 0) = 0
          AND COALESCE(v_expected_zero_count, 0) > 0
          AND COALESCE(v_transfer_backed_scope_count, 0) = 0
          AND v_no_bank_payment_execution_validated
        )
      );

    v_finalisation_payload_hash := CASE
      WHEN v_requires_full_batch_finalisation THEN MD5(
        JSONB_STRIP_NULLS(
          JSONB_BUILD_OBJECT(
            'pay_batch_id', p_pay_batch_id::text,
            'operation_id', p_operation_id::text,
            'execution_operation_id', v_execution_operation_id::text,
            'auth_request_id', v_operation_auth_request_id::text,
            'settlement_mode', v_settlement_mode,
            'scope', v_scope,
            'scope_state', v_operation_scope_state_json,
            'successful_scope_count', COALESCE(v_successful_scope_count, 0),
            'settled_scope_count', COALESCE(v_settled_scope_count, 0),
            'skipped_scope_count', COALESCE(v_skipped_scope_count, 0),
            'terminal_failed_scope_count', COALESCE(v_terminal_failed_scope_count, 0),
            'pending_scope_count', COALESCE(v_pending_scope_count, 0),
            'unknown_scope_count', COALESCE(v_unknown_scope_count, 0),
            'completed_transfer_count', COALESCE(v_completed_transfer_count, 0),
            'transfer_backed_scope_count', COALESCE(v_transfer_backed_scope_count, 0),
            'no_bank_scope_count', COALESCE(v_no_bank_total_scope_count, 0),
            'no_bank_payment_execution', v_no_bank_payment_execution_validated,
            'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes_marker,
            'paye_net_state_hash', v_expected_paye_net_state_hash,
            'global_bank_payment_projection_hash', v_expected_global_bank_payment_projection_hash,
            'scoped_paye_net_state_hash', v_expected_scoped_paye_net_state_hash,
            'bank_payment_projection_hash', v_expected_bank_payment_projection_hash,
            'local_commit_reference', CASE
              WHEN v_no_bank_scope_authorised THEN v_local_no_bank_commit_ref
              ELSE NULL::text
            END
          )
        )::text
      )
      ELSE NULL::text
    END;
    v_finalisation_idempotency_key := CASE
      WHEN v_requires_full_batch_finalisation
        THEN 'rail-finalise:batch:' || p_pay_batch_id::text || ':operation:' || p_operation_id::text || ':hash:' || v_finalisation_payload_hash
      ELSE NULL::text
    END;

    UPDATE public.banking_pay_operations AS operation_update
    SET pay_batch_id = COALESCE(operation_update.pay_batch_id, p_pay_batch_id),
        progress_json = JSONB_STRIP_NULLS(
          COALESCE(operation_update.progress_json, '{}'::jsonb)
          || JSONB_BUILD_OBJECT(
            'scope_settlement_complete', v_scope_settlement_complete,
            'all_scopes_terminal', v_all_scopes_terminal,
            'all_scopes_successful', v_all_scopes_successful,
            'completed_with_failed_payments', v_completed_with_failed_payments,
            'total_scope_count', COALESCE(v_total_scope_count, 0),
            'successful_scope_count', COALESCE(v_successful_scope_count, 0),
            'skipped_scope_count', COALESCE(v_skipped_scope_count, 0),
            'transfer_backed_scope_count', COALESCE(v_transfer_backed_scope_count, 0),
            'settled_transfer_backed_scope_count', COALESCE(v_settled_transfer_backed_scope_count, 0),
            'terminal_failed_scope_count', COALESCE(v_terminal_failed_scope_count, 0),
            'pending_scope_count', COALESCE(v_pending_scope_count, 0),
            'unknown_scope_count', COALESCE(v_unknown_scope_count, 0),
            'completed_transfer_count', COALESCE(v_completed_transfer_count, 0),
            'no_bank_scope_count', COALESCE(v_no_bank_total_scope_count, 0),
            'scoped_no_transfer_execution', v_scoped_no_transfer_marker,
            'no_bank_payment_execution', v_no_bank_payment_execution_validated,
            'requires_full_batch_finalisation', v_requires_full_batch_finalisation,
            'full_batch_finalisation_safe', v_full_batch_finalisation_safe,
            'finalisation_idempotency_key', v_finalisation_idempotency_key,
            'finalisation_payload_hash', v_finalisation_payload_hash,
            'projection_diagnostic', v_projection_diagnostic_json,
            'scope_settlement_updated_at_utc', v_now::text
          )
        ),
        updated_at_utc = v_now
    WHERE operation_update.id = p_operation_id;

    RETURN JSONB_BUILD_OBJECT(
      'ok', true,
      'operation_mode', true,
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'settled_this_chunk', COALESCE(v_settled_this_chunk, 0),
      'reused_this_chunk', COALESCE(v_reused_this_chunk, 0),
      'failed_this_chunk', COALESCE(v_failed_this_chunk, 0),
      'no_bank_scopes_settled_this_chunk', COALESCE(v_no_bank_settled_this_chunk, 0),
      'remaining', COALESCE(v_remaining_scope_count, 0),
      'has_more', v_has_more,
      'scope_settlement_complete', v_scope_settlement_complete,
      'all_scopes_terminal', v_all_scopes_terminal,
      'all_scopes_successful', v_all_scopes_successful,
      'completed_with_failed_payments', v_completed_with_failed_payments,
      'total_scope_count', COALESCE(v_total_scope_count, 0),
      'successful_scope_count', COALESCE(v_successful_scope_count, 0),
      'settled_scope_count', COALESCE(v_settled_scope_count, 0),
      'skipped_scope_count', COALESCE(v_skipped_scope_count, 0),
      'transfer_backed_scope_count', COALESCE(v_transfer_backed_scope_count, 0),
      'settled_transfer_backed_scope_count', COALESCE(v_settled_transfer_backed_scope_count, 0),
      'terminal_failed_scope_count', COALESCE(v_terminal_failed_scope_count, 0),
      'pending_scope_count', COALESCE(v_pending_scope_count, 0),
      'unknown_scope_count', COALESCE(v_unknown_scope_count, 0),
      'processor_failed_scope_count', COALESCE(v_processor_failed_scope_count, 0),
      'completed_transfer_count', COALESCE(v_completed_transfer_count, 0),
      'no_bank_scope_count', COALESCE(v_no_bank_total_scope_count, 0),
      'requires_full_batch_finalisation', v_requires_full_batch_finalisation,
      'full_batch_finalisation_safe', v_full_batch_finalisation_safe,
      'finalisation_idempotency_key', v_finalisation_idempotency_key,
      'finalisation_payload_hash', v_finalisation_payload_hash
    )
    || JSONB_BUILD_OBJECT(
      'server_owned_payment_projection_proof', true,
      'proof_validation_outcome', v_proof_validation_outcome,
      'scoped_no_transfer_execution', v_scoped_no_transfer_marker,
      'no_bank_payment_execution', v_no_bank_payment_execution_validated,
      'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes_marker,
      'bank_csv_evidence', CASE WHEN v_settlement_mode = 'CSV_SETTLEMENT' THEN v_intent_csv_evidence_json ELSE NULL::jsonb END,
      'paye_net_state_hash', v_expected_paye_net_state_hash,
      'global_bank_payment_projection_hash', v_expected_global_bank_payment_projection_hash,
      'scoped_paye_net_state_hash', v_expected_scoped_paye_net_state_hash,
      'bank_payment_projection_hash', v_expected_bank_payment_projection_hash,
      'projection_diagnostic', v_projection_diagnostic_json,
      'local_commit_reference', CASE WHEN v_no_bank_scope_authorised THEN v_local_no_bank_commit_ref ELSE NULL::text END,
      'auth_request_id', v_operation_auth_request_id::text,
      'execution_operation_id', v_execution_operation_id::text,
      'settlement_operation_id', p_operation_id::text,
      'authorised_execution_mode', v_intent_mode,
      'projection_scope', v_scope,
      'missing_explicit_paye_input_count', v_expected_missing_count,
      'explicit_zero_count', v_expected_global_zero_count,
      'global_positive_bank_payment_count', v_expected_global_positive_count,
      'global_invalid_payment_row_count', v_expected_global_invalid_count,
      'scoped_missing_explicit_paye_input_count', v_expected_scoped_missing_count,
      'scoped_explicit_zero_count', v_expected_zero_count,
      'scoped_positive_bank_payment_count', v_expected_positive_count,
      'scoped_positive_bank_payment_total', v_expected_positive_total,
      'scoped_invalid_payment_row_count', v_expected_scoped_invalid_count,
      'accounting_payment_date', v_operation_effective_payment_date::text,
      'candidate_updates_count', COALESCE(v_candidate_updates_count, 0),
      'no_bank_invalid_scope_count', COALESCE(v_no_bank_invalid_scope_count, 0),
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'remittance_queued', false,
      'message', 'Manual settlement chunk processed; full batch finalisation and remittance queueing remain the responsibility of pay_settle_rail.'
    );
  END IF;

  if p_payment_date is null then
    raise exception 'pay_settle_manual_confirm: payment_date is required';
  end if;

  if p_auth_request_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'AUTH_REQUEST_REQUIRED',
      'message', 'pay_settle_manual_confirm: authorised auth_request_id is required; use the Execute modal settlement flow',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_SETTLE_MANUAL_CONFIRM_START',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'scope', v_scope,
      'settlement_mode', v_settlement_mode,
      'auth_request_id', p_auth_request_id,
      'payment_date', p_payment_date::text,
      'suppress_remittances', coalesce(p_suppress_remittances, false)
    ),
    'pay_batches',
    p_pay_batch_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  select
    pb.id,
    pb.status,
    pb.batch_kind_fixed,
    pb.rail_provider_snapshot,
    pb.rail_env_snapshot,
    pb.authoritative_payment_date,
    pb.authoritative_payment_date_source,
    pb.pay_date,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc,
    pb.bank_csv_export_json,
    pb.execution_intent_json,
    pb.settlement_confirmation_json
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  for update;

  if v_batch.id is null then
    raise exception 'pay_settle_manual_confirm: pay_batch not found';
  end if;

  select
    pbar.id,
    pbar.pay_batch_id,
    pbar.state,
    pbar.execution_intent_json
  into v_auth
  from public.pay_batch_auth_requests pbar
  where pbar.id = p_auth_request_id
  for update;

  if v_auth.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'AUTH_REQUEST_NOT_FOUND',
      'message', 'pay_settle_manual_confirm: auth_request not found',
      'pay_batch_id', p_pay_batch_id::text,
      'auth_request_id', p_auth_request_id::text
    )::text;
  end if;
  if v_auth.pay_batch_id is distinct from p_pay_batch_id then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'AUTH_REQUEST_BATCH_MISMATCH',
      'message', 'pay_settle_manual_confirm: auth_request does not belong to this pay batch',
      'pay_batch_id', p_pay_batch_id::text,
      'auth_request_id', p_auth_request_id::text
    )::text;
  end if;
  if upper(coalesce(v_auth.state,'')) <> 'AUTHORISED' then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'AUTH_REQUEST_NOT_AUTHORISED',
      'message', 'pay_settle_manual_confirm: auth_request must be AUTHORISED before settlement can complete',
      'pay_batch_id', p_pay_batch_id::text,
      'auth_request_id', p_auth_request_id::text,
      'auth_state', v_auth.state
    )::text;
  end if;

  if v_auth.execution_intent_json is not null and jsonb_typeof(v_auth.execution_intent_json) = 'object' then
    v_auth_intent := v_auth.execution_intent_json;
  elsif v_batch.execution_intent_json is not null and jsonb_typeof(v_batch.execution_intent_json) = 'object' then
    v_auth_intent := v_batch.execution_intent_json;
  else
    v_auth_intent := '{}'::jsonb;
  end if;

  v_intent_mode := upper(btrim(coalesce(v_auth_intent->>'execution_mode', '')));
  if v_intent_mode <> v_settlement_mode then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'AUTH_INTENT_MODE_MISMATCH',
      'message', 'pay_settle_manual_confirm: supplied settlement_mode does not match the authorised frozen execution intent',
      'pay_batch_id', p_pay_batch_id::text,
      'auth_request_id', p_auth_request_id::text,
      'authorised_execution_mode', v_intent_mode,
      'requested_settlement_mode', v_settlement_mode
    )::text;
  end if;

  v_intent_payment_date_raw := nullif(btrim(coalesce(v_auth_intent->>'payment_date', '')), '');
  if v_intent_payment_date_raw is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'AUTH_INTENT_PAYMENT_DATE_REQUIRED',
      'message', 'pay_settle_manual_confirm: authorised frozen execution intent must contain a valid payment_date',
      'pay_batch_id', p_pay_batch_id::text,
      'auth_request_id', p_auth_request_id::text,
      'authorised_payment_date', null,
      'requested_payment_date', case when p_payment_date is null then null else p_payment_date::text end,
      'settlement_mode', v_settlement_mode
    )::text;
  end if;

  begin
    v_intent_payment_date := v_intent_payment_date_raw::date;
  exception when others then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'AUTH_INTENT_PAYMENT_DATE_REQUIRED',
      'message', 'pay_settle_manual_confirm: authorised frozen execution intent must contain a valid payment_date',
      'pay_batch_id', p_pay_batch_id::text,
      'auth_request_id', p_auth_request_id::text,
      'authorised_payment_date', null,
      'authorised_payment_date_raw', v_intent_payment_date_raw,
      'requested_payment_date', case when p_payment_date is null then null else p_payment_date::text end,
      'settlement_mode', v_settlement_mode
    )::text;
  end;

  if p_payment_date is distinct from v_intent_payment_date then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'AUTH_INTENT_PAYMENT_DATE_MISMATCH',
      'message', 'pay_settle_manual_confirm: supplied payment_date does not match the authorised frozen execution intent',
      'pay_batch_id', p_pay_batch_id::text,
      'auth_request_id', p_auth_request_id::text,
      'authorised_payment_date', v_intent_payment_date::text,
      'requested_payment_date', case when p_payment_date is null then null else p_payment_date::text end,
      'settlement_mode', v_settlement_mode
    )::text;
  end if;

  v_intent_suppress_remittances := lower(btrim(coalesce(v_auth_intent->>'suppress_remittances', 'false'))) in ('true','1','yes','y','on');
  if coalesce(p_suppress_remittances, false) <> v_intent_suppress_remittances then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'SUPPRESS_REMITTANCES_INTENT_MISMATCH',
      'message', 'pay_settle_manual_confirm: suppress_remittances must match the authorised frozen execution intent',
      'pay_batch_id', p_pay_batch_id::text,
      'auth_request_id', p_auth_request_id::text,
      'authorised_suppress_remittances', v_intent_suppress_remittances,
      'requested_suppress_remittances', coalesce(p_suppress_remittances, false)
    )::text;
  end if;

  v_execution_commit_state := upper(btrim(coalesce(v_batch.execution_commit_state, 'NOT_SUBMITTED')));
  if v_execution_commit_state not in ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') then
    v_execution_commit_state := 'NOT_SUBMITTED';
  end if;
  v_execution_commit_ref := v_batch.execution_commit_ref;
  v_execution_committed_at_utc := v_batch.execution_committed_at_utc;

  if upper(coalesce(v_batch.status,'')) in ('COMMITTED','PAID','SETTLED','CANCELLED') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'BATCH_NOT_SETTLEABLE',
      'message', 'pay_settle_manual_confirm: batch status cannot be manually settled',
      'pay_batch_id', p_pay_batch_id::text,
      'status', v_batch.status
    )::text;
  end if;

  if v_execution_commit_state <> 'NOT_SUBMITTED' then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'EXECUTION_STATE_CONFLICT',
      'message', 'pay_settle_manual_confirm: batch has already crossed the native execution submission boundary',
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_execution_commit_state,
      'execution_commit_ref', v_execution_commit_ref,
      'execution_committed_at_utc', case when v_execution_committed_at_utc is null then null else v_execution_committed_at_utc::text end
    )::text;
  end if;

  v_provider := upper(btrim(coalesce(v_batch.rail_provider_snapshot, '')));
  if v_provider = 'REV' then
    v_provider := 'REVOLUT';
  end if;
  if v_provider = '' then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'MISSING_RAIL_PROVIDER',
      'message', 'pay_settle_manual_confirm: rail_provider_snapshot is required and blank provider is not treated as CSV',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;
  if v_provider not in ('REVOLUT','CSV') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'UNKNOWN_RAIL_PROVIDER',
      'message', 'pay_settle_manual_confirm: unsupported rail_provider_snapshot',
      'pay_batch_id', p_pay_batch_id::text,
      'rail_provider_snapshot', v_batch.rail_provider_snapshot
    )::text;
  end if;

  select count(*)::int
  into v_pending_count
  from public.pay_bank_transfers pbt_pending
  where pbt_pending.pay_batch_id = p_pay_batch_id
    and (v_scope = 'ALL' or upper(coalesce(pbt_pending.pay_channel,'')) = v_scope)
    and upper(coalesce(pbt_pending.status,'')) = 'PENDING';

  if v_pending_count = 0 then
    raise exception 'pay_settle_manual_confirm: no PENDING transfers found for batch % (scope=%)', p_pay_batch_id, v_scope;
  end if;

  select count(*)::int
  into v_external_submission_count
  from public.pay_bank_transfers pbt_ext
  where pbt_ext.pay_batch_id = p_pay_batch_id
    and (v_scope = 'ALL' or upper(coalesce(pbt_ext.pay_channel,'')) = v_scope)
    and upper(coalesce(pbt_ext.status,'')) <> 'BLOCKED'
    and (
      nullif(btrim(coalesce(pbt_ext.rail_tx_id,'')), '') is not null
      or upper(coalesce(pbt_ext.rail_state,'')) in ('SUBMITTED','QUEUED','ACCEPTED','SENT','PROCESSING','IN_FLIGHT','PENDING_SETTLEMENT','PENDING_CONFIRMATION','PENDING_SUBMISSION','COMPLETED','SETTLED','COMMITTED','PAID','EXECUTED')
      or lower(btrim(coalesce(pbt_ext.rail_meta_json->>'submitted','false'))) in ('true','1','yes','y','on')
      or lower(btrim(coalesce(pbt_ext.rail_meta_json->>'queued','false'))) in ('true','1','yes','y','on')
      or lower(btrim(coalesce(pbt_ext.rail_meta_json->>'accepted','false'))) in ('true','1','yes','y','on')
      or lower(btrim(coalesce(pbt_ext.rail_meta_json->>'sent','false'))) in ('true','1','yes','y','on')
      or lower(btrim(coalesce(pbt_ext.rail_meta_json->>'processing','false'))) in ('true','1','yes','y','on')
      or lower(btrim(coalesce(pbt_ext.rail_meta_json->>'completed','false'))) in ('true','1','yes','y','on')
      or lower(btrim(coalesce(pbt_ext.rail_meta_json->>'committed','false'))) in ('true','1','yes','y','on')
      or lower(btrim(coalesce(pbt_ext.rail_meta_json->>'settled','false'))) in ('true','1','yes','y','on')
      or lower(btrim(coalesce(pbt_ext.rail_meta_json->>'paid','false'))) in ('true','1','yes','y','on')
      or coalesce(
        nullif(btrim(coalesce(pbt_ext.rail_meta_json->>'provider_submission_id','')), ''),
        nullif(btrim(coalesce(pbt_ext.rail_meta_json->>'submission_id','')), ''),
        nullif(btrim(coalesce(pbt_ext.rail_meta_json->>'provider_transfer_id','')), ''),
        nullif(btrim(coalesce(pbt_ext.rail_meta_json->>'transfer_id','')), ''),
        nullif(btrim(coalesce(pbt_ext.rail_meta_json->>'external_transfer_id','')), ''),
        nullif(btrim(coalesce(pbt_ext.rail_meta_json->>'provider_payment_id','')), ''),
        nullif(btrim(coalesce(pbt_ext.rail_meta_json->>'payment_id','')), ''),
        nullif(btrim(coalesce(pbt_ext.rail_meta_json->>'external_payment_id','')), ''),
        nullif(btrim(coalesce(pbt_ext.rail_meta_json->>'transaction_id','')), ''),
        nullif(btrim(coalesce(pbt_ext.rail_meta_json->>'id','')), '')
      ) is not null
    );

  if v_external_submission_count > 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'EXTERNAL_SUBMISSION_EXISTS',
      'message', 'pay_settle_manual_confirm: non-native settlement cannot complete after native rail submission evidence exists',
      'pay_batch_id', p_pay_batch_id::text,
      'settlement_mode', v_settlement_mode,
      'external_submission_transfer_count', v_external_submission_count
    )::text;
  end if;

  select md5(coalesce(jsonb_agg(
    jsonb_build_object(
      'id', transfer_hash_rows.id,
      'candidate_id', transfer_hash_rows.candidate_id,
      'umbrella_id', transfer_hash_rows.umbrella_id,
      'pay_channel', transfer_hash_rows.pay_channel,
      'amount', transfer_hash_rows.amount,
      'currency', transfer_hash_rows.currency,
      'payment_reference', transfer_hash_rows.payment_reference,
      'payee_name', transfer_hash_rows.payee_name,
      'sort_code_digits', transfer_hash_rows.sort_code_digits,
      'account_number_digits', transfer_hash_rows.account_number_digits,
      'account_type', transfer_hash_rows.account_type,
      'bank_details_hash_snapshot', transfer_hash_rows.bank_details_hash_snapshot,
      'payee_entity_kind', transfer_hash_rows.payee_entity_kind,
      'payee_entity_id', transfer_hash_rows.payee_entity_id,
      'transfer_group_key', transfer_hash_rows.transfer_group_key
    )
    order by transfer_hash_rows.id
  )::text, '[]'))
  into v_current_transfer_hash
  from (
    select
      pbt_hash.id::text as id,
      case when pbt_hash.candidate_id is null then null else pbt_hash.candidate_id::text end as candidate_id,
      case when pbt_hash.umbrella_id is null then null else pbt_hash.umbrella_id::text end as umbrella_id,
      pbt_hash.pay_channel,
      round(pbt_hash.amount, 2) as amount,
      pbt_hash.currency,
      pbt_hash.payment_reference,
      pbt_hash.payee_name,
      regexp_replace(coalesce(pbt_hash.sort_code,''), '[^0-9]', '', 'g') as sort_code_digits,
      regexp_replace(coalesce(pbt_hash.account_number,''), '[^0-9]', '', 'g') as account_number_digits,
      pbt_hash.account_type,
      pbt_hash.bank_details_hash_snapshot,
      pbt_hash.payee_entity_kind,
      case when pbt_hash.payee_entity_id is null then null else pbt_hash.payee_entity_id::text end as payee_entity_id,
      pbt_hash.transfer_group_key
    from public.pay_bank_transfers pbt_hash
    where pbt_hash.pay_batch_id = p_pay_batch_id
      and (v_scope = 'ALL' or upper(coalesce(pbt_hash.pay_channel,'')) = v_scope)
      and upper(coalesce(pbt_hash.status,'')) = 'PENDING'
    order by pbt_hash.id
  ) transfer_hash_rows;

  if v_settlement_mode = 'CSV_SETTLEMENT' then
    v_bank_csv_export_json := v_batch.bank_csv_export_json;
    v_bank_csv_export_hash := nullif(btrim(coalesce(v_bank_csv_export_json->>'transfer_hash', '')), '');
    v_intent_csv_uploaded_confirmed := lower(btrim(coalesce(v_auth_intent->>'csv_uploaded_confirmed', 'false'))) in ('true','1','yes','y','on');
    v_intent_bank_confirm_ref := nullif(btrim(coalesce(v_auth_intent->>'csv_bank_confirm_ref', '')), '');

    if v_bank_csv_export_json is null or jsonb_typeof(v_bank_csv_export_json) <> 'object' or v_bank_csv_export_hash is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'CSV_EXPORT_REQUIRED',
        'message', 'pay_settle_manual_confirm: CSV settlement requires a CloudTMS-generated CSV banking file first',
        'pay_batch_id', p_pay_batch_id::text
      )::text;
    end if;
    if v_bank_csv_export_hash <> v_current_transfer_hash then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'CSV_REGENERATION_REQUIRED',
        'message', 'pay_settle_manual_confirm: generated CSV evidence does not match current frozen transfer rows',
        'pay_batch_id', p_pay_batch_id::text,
        'csv_export_hash', v_bank_csv_export_hash,
        'current_transfer_hash', v_current_transfer_hash
      )::text;
    end if;
    if coalesce(p_csv_uploaded_confirmed, false) = false or v_intent_csv_uploaded_confirmed = false then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'CSV_UPLOAD_CONFIRMATION_REQUIRED',
        'message', 'pay_settle_manual_confirm: CSV settlement requires confirmation that the CloudTMS CSV was uploaded/processed with the bank',
        'pay_batch_id', p_pay_batch_id::text
      )::text;
    end if;
    if v_bank_confirm_ref is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'CSV_BANK_CONFIRM_REF_REQUIRED',
        'message', 'pay_settle_manual_confirm: CSV settlement requires a bank confirmation reference',
        'pay_batch_id', p_pay_batch_id::text
      )::text;
    end if;
    if v_intent_bank_confirm_ref is not null and v_bank_confirm_ref <> v_intent_bank_confirm_ref then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'CSV_BANK_CONFIRM_REF_INTENT_MISMATCH',
        'message', 'pay_settle_manual_confirm: supplied bank confirmation reference does not match the authorised frozen intent',
        'pay_batch_id', p_pay_batch_id::text,
        'auth_request_id', p_auth_request_id::text
      )::text;
    end if;
  else
    v_intent_external_comment := nullif(btrim(coalesce(v_auth_intent->>'external_settlement_comment', '')), '');
    if v_external_settlement_comment is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'EXTERNAL_SETTLEMENT_COMMENT_REQUIRED',
        'message', 'pay_settle_manual_confirm: external settlement requires a mandatory comment',
        'pay_batch_id', p_pay_batch_id::text
      )::text;
    end if;
    if v_intent_external_comment is not null and v_external_settlement_comment <> v_intent_external_comment then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'EXTERNAL_SETTLEMENT_COMMENT_INTENT_MISMATCH',
        'message', 'pay_settle_manual_confirm: supplied external settlement comment does not match the authorised frozen intent',
        'pay_batch_id', p_pay_batch_id::text,
        'auth_request_id', p_auth_request_id::text
      )::text;
    end if;
  end if;

  v_settlement_confirmation_json := jsonb_strip_nulls(jsonb_build_object(
    'settlement_mode', v_settlement_mode,
    'settled_at_utc', v_now::text,
    'settled_by_user_id', p_actor_user_id::text,
    'payment_date', v_intent_payment_date::text,
    'bank_confirm_ref', case when v_settlement_mode = 'CSV_SETTLEMENT' then v_bank_confirm_ref else null end,
    'external_comment', case when v_settlement_mode = 'EXTERNAL_SETTLEMENT' then v_external_settlement_comment else null end,
    'csv_export_hash', case when v_settlement_mode = 'CSV_SETTLEMENT' then v_bank_csv_export_hash else null end,
    'suppress_remittances', v_intent_suppress_remittances,
    'remittances_suppressed_at_utc', case when v_intent_suppress_remittances then v_now::text else null end,
    'auth_request_id', p_auth_request_id::text,
    'scope', v_scope,
    'current_transfer_hash', v_current_transfer_hash
  ));

  update public.pay_batches pb2
  set
    authoritative_payment_date = v_intent_payment_date,
    authoritative_payment_date_source = case when v_settlement_mode = 'CSV_SETTLEMENT' then 'CSV_SETTLEMENT_PAYMENT_DATE' else 'EXTERNAL_SETTLEMENT_PAYMENT_DATE' end,
    pay_date = v_intent_payment_date,
    monzo_confirmed_at_utc = v_now,
    monzo_confirmed_by_user_id = p_actor_user_id,
    execution_commit_ref = coalesce(v_bank_confirm_ref, 'external-settlement:' || p_auth_request_id::text, pb2.execution_commit_ref),
    settlement_confirmation_json = coalesce(pb2.settlement_confirmation_json, '{}'::jsonb) || v_settlement_confirmation_json,
    execution_intent_json = coalesce(pb2.execution_intent_json, '{}'::jsonb) || v_auth_intent
  where pb2.id = p_pay_batch_id;

  update public.pay_advance_reservations par
  set
    status = 'COMMITTED',
    committed_at_utc = coalesce(par.committed_at_utc, v_now),
    updated_by_user_id = p_actor_user_id
  from public.pay_batch_items pbi
  where par.pay_batch_id = p_pay_batch_id
    and par.pay_batch_item_id = pbi.id
    and upper(coalesce(par.status,'')) = 'RESERVED'
    and (v_scope = 'ALL' or upper(coalesce(pbi.pay_channel,'')) = v_scope);

  get diagnostics v_reservations_committed_count = row_count;

  select round(coalesce(sum(par.reserved_amount),0),2)
  into v_reservations_committed_amount
  from public.pay_advance_reservations par
  join public.pay_batch_items pbi
    on pbi.id = par.pay_batch_item_id
  where par.pay_batch_id = p_pay_batch_id
    and upper(coalesce(par.status,'')) = 'COMMITTED'
    and (v_scope = 'ALL' or upper(coalesce(pbi.pay_channel,'')) = v_scope);

  insert into public.pay_finance_case_events(
    finance_case_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    reservation_id,
    before_json,
    after_json,
    reason,
    note
  )
  select
    par.finance_case_id,
    'RESERVATION_COMMITTED',
    v_now,
    p_actor_user_id,
    p_pay_batch_id,
    par.id,
    jsonb_build_object('reservation_status', 'RESERVED'),
    jsonb_build_object(
      'reservation_status', 'COMMITTED',
      'authoritative_payment_date', v_intent_payment_date::text,
      'scope', v_scope,
      'settlement_mode', v_settlement_mode,
      'auth_request_id', p_auth_request_id::text
    ),
    lower(v_settlement_mode) || '_commit',
    null
  from public.pay_advance_reservations par
  join public.pay_batch_items pbi
    on pbi.id = par.pay_batch_item_id
  where par.pay_batch_id = p_pay_batch_id
    and upper(coalesce(par.status,'')) = 'COMMITTED'
    and par.committed_at_utc = v_now
    and (v_scope = 'ALL' or upper(coalesce(pbi.pay_channel,'')) = v_scope);

  if v_bank_confirm_ref is not null then
    update public.pay_batch_items pbi
    set bank_reference = v_bank_confirm_ref
    from public.pay_bank_transfers pbt,
         public.pay_batch_candidates pbc
    where pbt.pay_batch_id = p_pay_batch_id
      and (v_scope = 'ALL' or upper(coalesce(pbt.pay_channel,'')) = v_scope)
      and upper(coalesce(pbt.status,'')) = 'PENDING'
      and pbc.id = pbi.pay_batch_candidate_id
      and pbc.pay_batch_id = p_pay_batch_id
      and pbi.pay_bank_transfer_id = pbt.id;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'transfer_id', pbt.id::text,
        'status', 'COMPLETED',
        'rail_tx_id', null,
        'rail_state', case when v_settlement_mode = 'CSV_SETTLEMENT' then 'CSV_MANUAL_CONFIRM' else 'EXTERNAL_SETTLEMENT_CONFIRM' end,
        'rail_meta_json', jsonb_strip_nulls(jsonb_build_object(
          'settlement_mode', v_settlement_mode,
          'bank_confirm_ref', case when v_settlement_mode = 'CSV_SETTLEMENT' then v_bank_confirm_ref else null end,
          'external_settlement_comment', case when v_settlement_mode = 'EXTERNAL_SETTLEMENT' then v_external_settlement_comment else null end,
          'payment_date', v_intent_payment_date::text,
          'confirmed_at_utc', v_now::text,
          'confirmed_by_user_id', p_actor_user_id::text,
          'auth_request_id', p_auth_request_id::text,
          'csv_export_hash', case when v_settlement_mode = 'CSV_SETTLEMENT' then v_bank_csv_export_hash else null end,
          'suppress_remittances', v_intent_suppress_remittances
        ))
      )
      order by pbt.pay_channel, pbt.amount desc, pbt.id
    ),
    '[]'::jsonb
  )
  into v_settlement_json
  from public.pay_bank_transfers pbt
  where pbt.pay_batch_id = p_pay_batch_id
    and (v_scope = 'ALL' or upper(coalesce(pbt.pay_channel,'')) = v_scope)
    and upper(coalesce(pbt.status,'')) = 'PENDING';

  v_settle_result := public.pay_settle_rail(p_pay_batch_id, v_settlement_json, p_actor_user_id);

  v_worker_communications := coalesce(v_settle_result->'worker_communications', '{}'::jsonb);
  v_remittance_queue_stage_result := coalesce(
    v_settle_result->'remittance_queue_stage_result',
    v_worker_communications->'remittance_queue_stage_result',
    v_worker_communications->'result',
    '{}'::jsonb
  );
  v_manual_event_ingest_results := coalesce(v_settle_result#>'{bank_event_ingest,results}', '[]'::jsonb);

  IF jsonb_array_length(coalesce(v_manual_event_ingest_results, '[]'::jsonb)) = 0 THEN
    SELECT coalesce(
      jsonb_agg(
        public.pay_bank_event_ingest(
          jsonb_build_object(
            'pay_batch_id', p_pay_batch_id::text,
            'pay_bank_transfer_id', pbt_manual_event.id::text,
            'provider_key', coalesce(nullif(btrim(coalesce(v_provider, '')), ''), 'MANUAL'),
            'provider_event_id', 'manual-confirm:' || p_auth_request_id::text || ':' || pbt_manual_event.id::text,
            'provider_reference', coalesce(v_bank_confirm_ref, 'external-settlement:' || p_auth_request_id::text, pbt_manual_event.payment_reference, pbt_manual_event.request_id, pbt_manual_event.rail_tx_id),
            'provider_state', case when v_settlement_mode = 'CSV_SETTLEMENT' then 'CSV_MANUAL_CONFIRM' else 'EXTERNAL_SETTLEMENT_CONFIRM' end,
            'normalised_state', 'COMPLETED',
            'event_source', 'MANUAL_CONFIRM',
            'event_time_utc', v_now::text,
            'amount', pbt_manual_event.amount,
            'currency', coalesce(nullif(btrim(coalesce(pbt_manual_event.currency, '')), ''), 'GBP'),
            'idempotency_key', 'MANUAL_CONFIRM|' || p_pay_batch_id::text || '|' || pbt_manual_event.id::text || '|COMPLETED|' || p_auth_request_id::text,
            'raw_payload', jsonb_strip_nulls(jsonb_build_object(
              'source_rpc', 'pay_settle_manual_confirm',
              'settlement_mode', v_settlement_mode,
              'bank_confirm_ref', case when v_settlement_mode = 'CSV_SETTLEMENT' then v_bank_confirm_ref else null end,
              'external_settlement_comment', case when v_settlement_mode = 'EXTERNAL_SETTLEMENT' then v_external_settlement_comment else null end,
              'payment_date', v_intent_payment_date::text,
              'auth_request_id', p_auth_request_id::text,
              'csv_export_hash', case when v_settlement_mode = 'CSV_SETTLEMENT' then v_bank_csv_export_hash else null end
            ))
          ),
          p_actor_user_id
        )
        order by pbt_manual_event.id
      ),
      '[]'::jsonb
    )
    INTO v_manual_event_ingest_results
    FROM public.pay_bank_transfers AS pbt_manual_event
    WHERE pbt_manual_event.pay_batch_id = p_pay_batch_id
      AND (v_scope = 'ALL' OR upper(coalesce(pbt_manual_event.pay_channel, '')) = v_scope)
      AND (
        upper(coalesce(pbt_manual_event.status, '')) = 'COMPLETED'
        OR pbt_manual_event.completed_at_utc IS NOT NULL
      );
  END IF;

  IF v_remittance_queue_stage_result IS NULL OR v_remittance_queue_stage_result = '{}'::jsonb THEN
    v_remittance_queue_stage_result := public.pay_remittance_maybe_queue_for_trigger(
      p_pay_batch_id => p_pay_batch_id,
      p_trigger => 'ON_PAYMENT_CONFIRMED',
      p_scope => 'ALL',
      p_actor_user_id => p_actor_user_id,
      p_only_confirmed => true
    );
    v_worker_communications := coalesce(v_worker_communications, '{}'::jsonb) || jsonb_build_object(
      'manual_confirm_fallback_queue_trigger_used', true,
      'remittance_queue_stage_result', v_remittance_queue_stage_result,
      'result', v_remittance_queue_stage_result,
      'dispatch_required', lower(btrim(coalesce(v_remittance_queue_stage_result->>'dispatch_required', 'false'))) in ('true','1','yes','y','on')
    );
  END IF;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_SETTLE_MANUAL_CONFIRM_RESULT',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'scope', v_scope,
      'settlement_mode', v_settlement_mode,
      'auth_request_id', p_auth_request_id,
      'settlement_json_count', jsonb_array_length(coalesce(v_settlement_json, '[]'::jsonb)),
      'reservations_committed_count', v_reservations_committed_count,
      'reservations_committed_amount', coalesce(v_reservations_committed_amount, 0),
      'manual_event_ingest_count', jsonb_array_length(coalesce(v_manual_event_ingest_results, '[]'::jsonb)),
      'remittance_queue_stage_result', v_remittance_queue_stage_result
    ),
    'pay_batches',
    p_pay_batch_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  return coalesce(v_settle_result, '{}'::jsonb)
    || jsonb_build_object(
      'authoritative_payment_date', v_intent_payment_date::text,
      'authoritative_payment_date_source', case when v_settlement_mode = 'CSV_SETTLEMENT' then 'CSV_SETTLEMENT_PAYMENT_DATE' else 'EXTERNAL_SETTLEMENT_PAYMENT_DATE' end,
      'settlement_mode', v_settlement_mode,
      'settlement_confirmation_json', (select pb3.settlement_confirmation_json from public.pay_batches pb3 where pb3.id = p_pay_batch_id),
      'execution_commit_state', (select pb3.execution_commit_state from public.pay_batches pb3 where pb3.id = p_pay_batch_id),
      'execution_commit_ref', (select pb3.execution_commit_ref from public.pay_batches pb3 where pb3.id = p_pay_batch_id),
      'execution_committed_at_utc', (select case when pb3.execution_committed_at_utc is null then null else pb3.execution_committed_at_utc::text end from public.pay_batches pb3 where pb3.id = p_pay_batch_id),
      'worker_communications', v_worker_communications,
      'remittance_queue_stage_result', v_remittance_queue_stage_result,
      'manual_event_ingest_results', v_manual_event_ingest_results,
      'bank_event_ingest', coalesce(v_settle_result->'bank_event_ingest', jsonb_build_object('count', jsonb_array_length(v_manual_event_ingest_results), 'results', v_manual_event_ingest_results)),
      'reservations_committed_count', v_reservations_committed_count,
      'reservations_committed_amount', coalesce(v_reservations_committed_amount,0)
    );
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_SETTLE_MANUAL_CONFIRM_ERROR',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id,
        'scope', v_scope,
        'settlement_mode', v_settlement_mode,
        'auth_request_id', p_auth_request_id,
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_batches',
      COALESCE(p_pay_batch_id::text, 'NO_BATCH_ID'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
    RAISE;
end;
$function$;

-- pay_settle_monzo(uuid,uuid,boolean)
CREATE OR REPLACE FUNCTION public.pay_settle_monzo(p_pay_batch_id uuid, p_actor_user_id uuid, p_confirmed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch record;
  v_guard_json jsonb := '{}'::jsonb;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_settle_monzo: pay_batch_id is required';
  END IF;

  IF p_confirmed IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION 'CONFIRM_REQUIRED';
  END IF;

  SELECT
    public.pay_batches.id,
    public.pay_batches.status,
    public.pay_batches.pay_date,
    public.pay_batches.banking_system_snapshot,
    public.pay_batches.external_paye_system_snapshot,
    public.pay_batches.rail_provider_snapshot,
    public.pay_batches.rail_env_snapshot,
    public.pay_batches.execution_commit_state,
    public.pay_batches.execution_commit_ref,
    public.pay_batches.execution_committed_at_utc,
    public.pay_batches.settlement_confirmation_json
  INTO v_batch
  FROM public.pay_batches
  WHERE public.pay_batches.id = p_pay_batch_id
  FOR UPDATE;

  IF v_batch.id IS NULL THEN
    RAISE EXCEPTION 'pay_settle_monzo: pay batch % not found', p_pay_batch_id;
  END IF;

  v_guard_json := jsonb_build_object(
    'error', 'USE_PAYMENT_CORRECTION_FLOW',
    'code', 'USE_PAYMENT_CORRECTION_FLOW',
    'message', 'pay_settle_monzo is deprecated because it bypasses the generic bank event ledger, no-money unwind, settled reversal, and remittance timing flow. Use pay_bank_event_ingest plus pay_settle_rail/pay_settle_manual_confirm instead.',
    'pay_batch_id', p_pay_batch_id::text,
    'status', v_batch.status,
    'pay_date', CASE WHEN v_batch.pay_date IS NULL THEN NULL ELSE v_batch.pay_date::text END,
    'banking_system_snapshot', v_batch.banking_system_snapshot,
    'external_paye_system_snapshot', v_batch.external_paye_system_snapshot,
    'rail_provider_snapshot', v_batch.rail_provider_snapshot,
    'rail_env_snapshot', v_batch.rail_env_snapshot,
    'execution_commit_state', v_batch.execution_commit_state,
    'execution_commit_ref', v_batch.execution_commit_ref,
    'execution_committed_at_utc', CASE WHEN v_batch.execution_committed_at_utc IS NULL THEN NULL ELSE v_batch.execution_committed_at_utc::text END
  );

  BEGIN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_SETTLE_MONZO_BLOCKED_USE_GENERIC_RAIL_FLOW',
      v_guard_json,
      'pay_batch',
      p_pay_batch_id::text,
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RAISE EXCEPTION '%', v_guard_json::text;
END;
$function$;

-- pay_settle_rail(uuid,jsonb,uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_settle_rail(p_pay_batch_id uuid, p_settlement_json jsonb, p_actor_user_id uuid, p_operation_id uuid DEFAULT NULL::uuid, p_settlement_scope_ids jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
 SET statement_timeout TO '6000ms'
 SET lock_timeout TO '1000ms'
AS $function$
declare
  v_batch record;

  v_now timestamptz := now();

  v_newly_settled_candidates jsonb := '[]'::jsonb;

  v_pending_transfers jsonb := '[]'::jsonb;
  v_failed_transfers  jsonb := '[]'::jsonb;
  v_returned_transfers jsonb := '[]'::jsonb;
  v_blocked_transfers jsonb := '[]'::jsonb;

  v_batch_status text;

  v_missing_timesheets jsonb := '[]'::jsonb;
  v_ambig_timesheets jsonb := '[]'::jsonb;

  v_adv_id uuid;
  v_old_sched jsonb;
  v_new_sched jsonb;
  v_old_out numeric;
  v_new_out numeric;
  v_old_next date;
  v_new_next date;
  v_total_taken numeric;
  v_case_type public.pay_finance_case_type_enum;
  v_min_earnings_threshold numeric;
  v_take_home_floor_override numeric;
  v_snooze_active boolean;
  v_active_snooze_report_count integer := 0;
  v_active_snooze_report_sample jsonb := '[]'::jsonb;
  v_date_context jsonb := '{}'::jsonb;
  v_today_uk date := NULL::date;
  v_was_cleared boolean;

  v_linked_transfer_ct int := 0;
  v_has_pos_net boolean := false;

  v_fresh jsonb := null;
  v_is_stale boolean := false;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_diff_sample jsonb := '[]'::jsonb;
  v_stored_freshness_status text := null;
  v_stored_freshness_result_hash text := null;
  v_stored_freshness_scope_hash text := null;
  v_stored_freshness_result_json jsonb := '{}'::jsonb;
  v_stored_freshness_operation_id uuid := null;

  v_overpay_patched_ct int := 0;
  v_payment_advance_recovery_patched_ct int := 0;
  v_manual_debt_patched_ct int := 0;
  v_payout_cases_marked_paid_ct int := 0;
  v_component_settled_count int := 0;
  v_component_settled_amount numeric := 0;
  v_component_unresolved_count int := 0;
  v_component_unresolved_amount numeric := 0;
  v_component_unresolved_json jsonb := '[]'::jsonb;
  v_component_reconciliation_bad jsonb := '[]'::jsonb;
  v_component_reconciliation_bad_ct int := 0;
  v_component_reconciliation_checked_ct int := 0;

  v_comm_result jsonb := '{}'::jsonb;
  v_comm_trigger_status text := null;
  v_comm_error text := null;
  v_worker_communications jsonb := '{}'::jsonb;
  v_catchup_needed boolean := false;
  v_changed_channel_audit record;
  v_changed_channel_audit_after_json jsonb := null;
  v_changed_channel_settled_ct int := 0;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_execution_commit_ref text := null;
  v_execution_committed_at_utc timestamptz := null;
  v_completed_transfer_count int := 0;
  v_detected_execution_commit_ref text := null;
  v_detected_execution_committed_at_utc timestamptz := null;
  v_execution_intent_json jsonb := '{}'::jsonb;
  v_settlement_confirmation_json jsonb := '{}'::jsonb;
  v_durably_finalised_candidate_ids jsonb := '[]'::jsonb;
  v_suppress_remittances boolean := false;
  v_settlement_mode text := 'STANDARD_BANK';
  v_effective_payment_date date := null;
  v_suppression_audit_json jsonb := '{}'::jsonb;
  v_bank_event_ingest_results jsonb := '[]'::jsonb;
  v_bank_event_ingest_count int := 0;

  v_operation_mode boolean := false;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_requested_scope_count integer := 0;
  v_matched_scope_count integer := 0;
  v_settled_this_chunk integer := 0;
  v_reused_this_chunk integer := 0;
  v_failed_this_chunk integer := 0;
  v_pending_this_chunk integer := 0;
  v_remaining_scope_count integer := 0;
  v_existing_failed_scope_count integer := 0;
  v_total_failed_scope_count integer := 0;
  v_duplicate_transfer_ids jsonb := '[]'::jsonb;
  v_out_of_scope_transfer_ids jsonb := '[]'::jsonb;
  v_has_more boolean := false;
  v_carry_forward_mark_result jsonb := '{}'::jsonb;
  v_consumed_carry_forward_count integer := 0;
  v_live_signal_result jsonb := '{}'::jsonb;
  v_scope_settlement_complete boolean := false;
  v_operation_completed_transfer_count integer := 0;
  v_successful_scope_count integer := 0;
  v_terminal_failed_scope_count integer := 0;
  v_pending_scope_count integer := 0;
  v_unknown_scope_count integer := 0;
  v_processor_failed_scope_count integer := 0;
  v_all_scopes_terminal boolean := false;
  v_all_scopes_successful boolean := false;
  v_completed_with_failed_payments boolean := false;
  v_batch_status_label text := null;
  v_requires_full_batch_finalisation boolean := false;
  v_full_batch_finalisation_safe boolean := false;
  v_finalisation_idempotency_key text := null;
  v_finalisation_payload_hash text := null;

  v_execution_operation_row public.banking_pay_operations%ROWTYPE;
  v_root_operation_input_json jsonb := '{}'::jsonb;
  v_operation_auth_intent_json jsonb := '{}'::jsonb;
  v_batch_intent_json jsonb := '{}'::jsonb;
  v_auth_locator_json jsonb := '{}'::jsonb;
  v_batch_intent_operation_id uuid := NULL::uuid;
  v_auth_intent_auth_request_id uuid := NULL::uuid;
  v_batch_intent_auth_request_id uuid := NULL::uuid;
  v_authorised_execution_mode text := NULL::text;
  v_batch_execution_mode text := NULL::text;
  v_batch_projection_scope text := NULL::text;
  v_server_owned_projection_proof boolean := false;
  v_batch_server_owned_projection_proof boolean := false;
  v_batch_no_bank_payment_marker boolean := false;
  v_batch_allow_explicit_zero_no_bank_scopes_marker boolean := false;
  v_batch_suppress_remittances boolean := false;
  v_expected_global_zero_count integer := NULL::integer;
  v_batch_expected_global_zero_count integer := NULL::integer;
  v_expected_global_positive_count integer := NULL::integer;
  v_batch_expected_global_positive_count integer := NULL::integer;
  v_expected_global_invalid_count integer := NULL::integer;
  v_batch_expected_global_invalid_count integer := NULL::integer;
  v_expected_scoped_missing_count integer := NULL::integer;
  v_batch_expected_scoped_missing_count integer := NULL::integer;
  v_expected_scoped_invalid_count integer := NULL::integer;
  v_batch_expected_scoped_invalid_count integer := NULL::integer;
  v_batch_expected_paye_net_state_hash text := NULL::text;
  v_expected_global_bank_payment_projection_hash text := NULL::text;
  v_batch_expected_global_bank_payment_projection_hash text := NULL::text;
  v_expected_scoped_paye_net_state_hash text := NULL::text;
  v_batch_expected_scoped_paye_net_state_hash text := NULL::text;
  v_batch_expected_bank_payment_projection_hash text := NULL::text;
  v_batch_expected_missing_count integer := NULL::integer;
  v_batch_expected_zero_count integer := NULL::integer;
  v_batch_expected_positive_count integer := NULL::integer;
  v_scoped_no_transfer_marker boolean := false;
  v_batch_scoped_no_transfer_marker boolean := false;
  v_authorised_payment_date date := NULL::date;
  v_batch_authorised_payment_date date := NULL::date;
  v_authorised_payment_date_raw text := NULL::text;
  v_batch_authorised_payment_date_raw text := NULL::text;
  v_total_scope_count integer := 0;
  v_no_bank_eligible_scope_count integer := 0;
  v_selected_no_bank_scope_count integer := 0;
  v_selected_eligible_no_bank_scope_count integer := 0;
  v_operation_scope_state_json jsonb := '[]'::jsonb;
  v_proof_validation_outcome text := 'NOT_VALIDATED';
  v_auth_request_candidate_count integer := 0;
  v_no_bank_settlement_operation_count integer := 0;
  v_explicit_settlement_operation_id uuid := NULL::uuid;
  v_no_bank_distinct_candidate_count integer := 0;
  v_positive_scope_count integer := 0;
  v_positive_nonterminal_scope_count integer := 0;
  v_positive_failed_scope_count integer := 0;
  v_operation_auth_request_id uuid := NULL::uuid;
  v_operation_auth_state text := NULL::text;

  v_execution_operation_id uuid := NULL::uuid;
  v_execution_operation_resolved_from_batch_intent boolean := false;
  v_auth_intent_operation_id uuid := NULL::uuid;
  v_no_bank_payment_marker boolean := false;
  v_allow_explicit_zero_no_bank_scopes_marker boolean := false;
  v_no_bank_scope_authorised boolean := false;
  v_no_bank_payment_execution_validated boolean := false;
  v_operation_projection_scope text := NULL::text;
  v_expected_paye_net_state_hash text := NULL::text;
  v_expected_bank_payment_projection_hash text := NULL::text;
  v_expected_missing_count integer := NULL::integer;
  v_expected_zero_count integer := NULL::integer;
  v_expected_positive_count integer := NULL::integer;
  v_current_paye_net_state_hash text := NULL::text;
  v_all_bank_payment_projection_hash text := NULL::text;
  v_current_scoped_paye_net_state_hash text := NULL::text;
  v_current_bank_payment_projection_hash text := NULL::text;
  v_current_missing_count integer := 0;
  v_global_zero_count integer := 0;
  v_global_positive_count integer := 0;
  v_global_invalid_count integer := 0;
  v_current_scoped_missing_count integer := 0;
  v_current_zero_count integer := 0;
  v_current_positive_count integer := 0;
  v_current_positive_total numeric(14,2) := 0;
  v_current_scoped_invalid_count integer := 0;
  v_current_projection_changed boolean := false;
  v_projection_diagnostic_json jsonb := '{}'::jsonb;
  v_operation_effective_payment_date date := NULL::date;
  v_no_bank_settled_this_chunk integer := 0;
  v_no_bank_total_scope_count integer := 0;
  v_local_no_bank_commit_ref text := NULL::text;
  v_no_bank_scope_artifact_count integer := 0;
  v_no_bank_batch_transfer_count integer := 0;
  v_no_bank_transfer_event_count integer := 0;
  v_no_bank_provider_attempt_count integer := 0;
  v_no_bank_settlement_operation_id uuid := NULL::uuid;
  v_settlement_operation_id uuid := NULL::uuid;
  v_settlement_operation_count integer := 0;
  v_related_settlement_operation_count integer := 0;
  v_bound_settlement_scope_count integer := 0;
  v_completed_transfer_total numeric(14,2) := 0;
  v_completed_transfer_ids jsonb := '[]'::jsonb;
  v_settlement_scope_ids jsonb := '[]'::jsonb;
  v_local_positive_commit_ref text := NULL::text;
  v_bank_confirm_ref text := NULL::text;
  v_submitted_to_bank boolean := false;
  v_provider_submission_required boolean := false;
  v_provider_submission_attempted boolean := false;
  v_local_settlement_evidence_only boolean := false;
  v_legacy_direct_settlement boolean := false;
  v_settlement_positive_scope_count integer := 0;
  v_settlement_positive_transfer_count integer := 0;
  v_settlement_missing_event_count integer := 0;
  v_settlement_nonterminal_scope_count integer := 0;
  v_settlement_failed_scope_count integer := 0;
  v_settlement_local_proof_invalid_count integer := 0;
  v_settlement_unmatched_transfer_count integer := 0;
  v_settlement_unmatched_scope_transfer_count integer := 0;
  v_no_bank_nonterminal_scope_count integer := 0;
  v_no_bank_failed_scope_count integer := 0;
  v_no_bank_invalid_scope_count integer := 0;
  v_no_bank_missing_scope_count integer := 0;
  v_unproved_missing_paye_candidate_count integer := 0;
  v_unproved_zero_paye_candidate_count integer := 0;
  v_mutation_guard jsonb := '{}'::jsonb;
  v_mutation_mode text := 'NEW_PAYMENT_ACTION';
begin
  BEGIN
    v_date_context := public.pay_banking_official_date_context_v1(NULL::timestamptz);
    v_today_uk := CASE
      WHEN COALESCE(v_date_context->>'london_current_date', '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
        THEN (v_date_context->>'london_current_date')::date
      ELSE NULL::date
    END;
    IF v_today_uk IS NULL THEN
      v_date_context := COALESCE(v_date_context, '{}'::jsonb) || jsonb_build_object(
        'ok', false,
        'code', 'PAY_SETTLE_RAIL_LONDON_DATE_UNAVAILABLE',
        'message', 'The current Europe/London business date could not be resolved for settlement diagnostics.'
      );
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_today_uk := NULL::date;
    v_date_context := jsonb_build_object(
      'ok', false,
      'code', 'PAY_SETTLE_RAIL_LONDON_DATE_UNAVAILABLE',
      'message', 'The current Europe/London business date could not be resolved for settlement diagnostics.',
      'technical_error', SQLERRM
    );
  END;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_SETTLE_RAIL_START',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'actor_user_id', p_actor_user_id,
      'settlement_row_count', CASE WHEN p_settlement_json IS NULL OR jsonb_typeof(p_settlement_json) <> 'array' THEN NULL ELSE jsonb_array_length(p_settlement_json) END
    ),
    'pay_batches',
    COALESCE(p_pay_batch_id::text, 'NO_BATCH_ID'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  if p_pay_batch_id is null then
    raise exception 'pay_settle_rail: pay_batch_id is required';
  end if;
  if p_settlement_json is null or jsonb_typeof(p_settlement_json) <> 'array' then
    raise exception 'pay_settle_rail: settlement_json must be a JSON array';
  end if;

  SELECT CASE
    WHEN p_operation_id IS NULL
     AND p_settlement_scope_ids IS NULL
     AND jsonb_array_length(p_settlement_json) > 0
     AND NOT EXISTS (
       SELECT 1
       FROM jsonb_array_elements(p_settlement_json) AS settlement_element(value)
       WHERE jsonb_typeof(settlement_element.value) <> 'object'
          OR NULLIF(btrim(COALESCE(settlement_element.value->>'bank_event_id', '')), '') IS NULL
     ) THEN 'AUTHORITATIVE_EVENT'
    ELSE 'NEW_PAYMENT_ACTION'
  END
  INTO v_mutation_mode;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'pay_settle_rail: actor_user_id is required';
  END IF;

  IF v_mutation_mode = 'AUTHORITATIVE_EVENT' AND EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_settlement_json) AS settlement_element(value)
    LEFT JOIN public.pay_bank_transfer_events AS authoritative_event
      ON authoritative_event.id::text = NULLIF(btrim(COALESCE(settlement_element.value->>'bank_event_id', '')), '')
     AND authoritative_event.pay_batch_id = p_pay_batch_id
     AND authoritative_event.pay_bank_transfer_id::text = NULLIF(btrim(COALESCE(
           settlement_element.value->>'transfer_id',
           settlement_element.value->>'pay_bank_transfer_id',
           ''
         )), '')
     AND authoritative_event.mapping_status = 'MATCHED'
     AND upper(btrim(COALESCE(authoritative_event.normalised_state, ''))) IN ('COMPLETED','PAID','SETTLED','SUCCESS','SUCCEEDED')
     AND upper(btrim(COALESCE(authoritative_event.event_source, ''))) IN (
       'PROVIDER_WEBHOOK','WEBHOOK','PROVIDER_POLL','POLL','PROVIDER_RESPONSE',
       'FAILED_WEBHOOK_REPLAY','RAIL_PROVIDER','PROVIDER','PROVIDER_SETTLEMENT',
       'BANK_EVENT','MANUAL_EVIDENCE','MANUAL_CONFIRM'
     )
    WHERE authoritative_event.id IS NULL
  ) THEN
    RAISE EXCEPTION 'PAY_SETTLE_RAIL_EVENT_AUTHORITY_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object(
        'code', 'EVENT_AUTHORITY_REQUIRED',
        'pay_batch_id', p_pay_batch_id,
        'message', 'Authoritative settlement requires an existing mapped terminal provider event for every transfer.'
      )::text;
  END IF;

  v_mutation_guard := private.pay_payment_mutation_guard_v1(
    p_pay_batch_id,
    NULL::uuid,
    v_mutation_mode
  );

  IF COALESCE((v_mutation_guard->>'ok')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION '%', COALESCE(v_mutation_guard->>'code', 'PAYMENT_CHANGE_IN_PROGRESS')
      USING ERRCODE = 'P0001', DETAIL = v_mutation_guard::text;
  END IF;

  v_operation_mode := (p_operation_id IS NOT NULL OR p_settlement_scope_ids IS NOT NULL);

  IF v_operation_mode THEN
    IF p_operation_id IS NULL THEN
      RAISE EXCEPTION 'pay_settle_rail operation mode requires p_operation_id';
    END IF;
    IF p_settlement_scope_ids IS NULL OR jsonb_typeof(p_settlement_scope_ids) <> 'array' OR jsonb_array_length(p_settlement_scope_ids) = 0 THEN
      RAISE EXCEPTION 'pay_settle_rail operation mode requires non-empty p_settlement_scope_ids';
    END IF;

    -- Resolve the execution binding without holding a row lock, then acquire
    -- canonical locks in root-execution -> requested-operation -> batch order.
    -- The requested operation and batch binding are re-read and revalidated after
    -- the canonical locks are held so an initial read can never become authority.
    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'banking_pay_operations row % not found', p_operation_id;
    END IF;

    IF v_operation_row.operation_type NOT IN ('PAYMENT_SETTLEMENT', 'PAYMENT_EXECUTE') THEN
      RAISE EXCEPTION 'operation % is not a settlement-capable operation', p_operation_id;
    END IF;

    IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
      RAISE EXCEPTION 'operation % is for pay batch %, not %', p_operation_id, v_operation_row.pay_batch_id, p_pay_batch_id;
    END IF;

    IF v_operation_row.actor_user_id IS NOT NULL AND v_operation_row.actor_user_id <> p_actor_user_id THEN
      RAISE EXCEPTION 'operation % belongs to a different actor', p_operation_id;
    END IF;

    IF UPPER(BTRIM(COALESCE(v_operation_row.operation_type, ''))) = 'PAYMENT_EXECUTE' THEN
      v_execution_operation_id := v_operation_row.id;
    ELSIF v_operation_row.root_operation_id IS NOT NULL THEN
      v_execution_operation_id := v_operation_row.root_operation_id;
    ELSE
      SELECT CASE
        WHEN JSONB_TYPEOF(pb.execution_intent_json) = 'object'
          THEN COALESCE(pb.execution_intent_json, '{}'::jsonb)
        ELSE '{}'::jsonb
      END
      INTO v_batch_intent_json
      FROM public.pay_batches AS pb
      WHERE pb.id = p_pay_batch_id;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'pay_settle_rail: pay_batch not found';
      END IF;

      IF NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'operation_id', '')), '')
           ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        v_execution_operation_id := (v_batch_intent_json->>'operation_id')::uuid;
        v_execution_operation_resolved_from_batch_intent := true;
      END IF;
    END IF;

    IF v_execution_operation_id IS NULL THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_RAIL',

        'code', 'EXECUTION_OPERATION_REQUIRED',
        'message', 'The settlement operation is not bound to a payment execution operation.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    SELECT execution_operation.*
    INTO v_execution_operation_row
    FROM public.banking_pay_operations AS execution_operation
    WHERE execution_operation.id = v_execution_operation_id
    FOR UPDATE;

    IF NOT FOUND
       OR v_execution_operation_row.pay_batch_id IS DISTINCT FROM p_pay_batch_id
       OR v_execution_operation_row.operation_type NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_RAIL',
        'code', 'EXECUTION_OPERATION_INVALID',
        'message', 'The resolved payment execution operation is missing or incompatible with this settlement operation.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'execution_operation_id', v_execution_operation_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF p_operation_id = v_execution_operation_id THEN
      v_operation_row := v_execution_operation_row;
    ELSE
      SELECT operation_row.*
      INTO v_operation_row
      FROM public.banking_pay_operations AS operation_row
      WHERE operation_row.id = p_operation_id
      FOR UPDATE;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'banking_pay_operations row % not found', p_operation_id;
      END IF;
    END IF;

    IF v_operation_row.operation_type NOT IN ('PAYMENT_SETTLEMENT', 'PAYMENT_EXECUTE') THEN
      RAISE EXCEPTION 'operation % is not a settlement-capable operation', p_operation_id;
    END IF;

    IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
      RAISE EXCEPTION 'operation % is for pay batch %, not %', p_operation_id, v_operation_row.pay_batch_id, p_pay_batch_id;
    END IF;

    IF v_operation_row.actor_user_id IS NOT NULL AND v_operation_row.actor_user_id <> p_actor_user_id THEN
      RAISE EXCEPTION 'operation % belongs to a different actor', p_operation_id;
    END IF;

    IF UPPER(BTRIM(COALESCE(v_operation_row.operation_type, ''))) = 'PAYMENT_EXECUTE' THEN
      IF v_operation_row.id IS DISTINCT FROM v_execution_operation_id THEN
        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
          'error', 'PAY_SETTLE_RAIL',
          'code', 'EXECUTION_OPERATION_BINDING_CHANGED',
          'message', 'The requested operation changed its execution-operation binding while rail settlement was acquiring its canonical locks.',
          'pay_batch_id', p_pay_batch_id::text,
          'operation_id', p_operation_id::text,
          'locked_execution_operation_id', v_execution_operation_id::text,
          'current_operation_type', v_operation_row.operation_type,
          'current_root_operation_id', CASE WHEN v_operation_row.root_operation_id IS NULL THEN NULL::text ELSE v_operation_row.root_operation_id::text END
        )::text USING ERRCODE = 'P0001';
      END IF;
    ELSIF v_operation_row.root_operation_id IS NOT NULL THEN
      IF v_operation_row.root_operation_id IS DISTINCT FROM v_execution_operation_id THEN
        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
          'error', 'PAY_SETTLE_RAIL',
          'code', 'EXECUTION_OPERATION_BINDING_CHANGED',
          'message', 'The settlement operation changed its execution-operation binding while rail settlement was acquiring its canonical locks.',
          'pay_batch_id', p_pay_batch_id::text,
          'operation_id', p_operation_id::text,
          'locked_execution_operation_id', v_execution_operation_id::text,
          'current_root_operation_id', v_operation_row.root_operation_id::text
        )::text USING ERRCODE = 'P0001';
      END IF;
    ELSE
      v_execution_operation_resolved_from_batch_intent := true;
    END IF;

    SELECT pb.*
    INTO v_batch
    FROM public.pay_batches AS pb
    WHERE pb.id = p_pay_batch_id
    FOR UPDATE;

    IF v_batch.id IS NULL THEN
      RAISE EXCEPTION 'pay_settle_rail: pay_batch not found';
    END IF;

    v_stored_freshness_status := upper(btrim(coalesce(v_batch.freshness_validation_status, '')));
    v_stored_freshness_result_hash := nullif(btrim(coalesce(v_batch.freshness_result_hash, '')), '');
    v_stored_freshness_scope_hash := nullif(btrim(coalesce(v_batch.freshness_scope_hash, '')), '');
    v_stored_freshness_result_json := coalesce(v_batch.freshness_result_json, '{}'::jsonb);
    v_stored_freshness_operation_id := v_batch.freshness_operation_id;
    v_execution_commit_state := UPPER(BTRIM(COALESCE(v_batch.execution_commit_state, 'NOT_SUBMITTED')));
    IF v_execution_commit_state NOT IN ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') THEN
      v_execution_commit_state := 'NOT_SUBMITTED';
    END IF;
    v_execution_commit_ref := v_batch.execution_commit_ref;
    v_execution_committed_at_utc := v_batch.execution_committed_at_utc;

    v_batch_intent_json := CASE
      WHEN JSONB_TYPEOF(v_batch.execution_intent_json) = 'object'
        THEN COALESCE(v_batch.execution_intent_json, '{}'::jsonb)
      ELSE '{}'::jsonb
    END;

    IF v_execution_operation_resolved_from_batch_intent
       AND (
         CASE
           WHEN NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'operation_id', '')), '')
                ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             THEN (v_batch_intent_json->>'operation_id')::uuid
           ELSE NULL::uuid
         END
       ) IS DISTINCT FROM v_execution_operation_id THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_RAIL',
        'code', 'EXECUTION_OPERATION_BINDING_CHANGED',
        'message', 'The batch execution-operation binding changed while rail settlement was acquiring its canonical locks.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'locked_execution_operation_id', v_execution_operation_id::text,
        'current_batch_execution_operation_id', NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'operation_id', '')), '')
      )::text USING ERRCODE = 'P0001';
    END IF;

    v_root_operation_input_json := COALESCE(v_execution_operation_row.input_json, '{}'::jsonb);
    v_auth_locator_json := COALESCE(v_operation_row.input_json, '{}'::jsonb)
      || CASE
           WHEN JSONB_TYPEOF(v_operation_row.input_json->'execution_intent_json') = 'object'
             THEN v_operation_row.input_json->'execution_intent_json'
           ELSE '{}'::jsonb
         END
      || v_root_operation_input_json
      || CASE
           WHEN JSONB_TYPEOF(v_root_operation_input_json->'execution_intent_json') = 'object'
             THEN v_root_operation_input_json->'execution_intent_json'
           ELSE '{}'::jsonb
         END
      || v_batch_intent_json;

    IF NULLIF(BTRIM(COALESCE(
      v_auth_locator_json->>'auth_request_id',
      v_auth_locator_json->>'authRequestId',
      ''
    )), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_operation_auth_request_id := COALESCE(
        v_auth_locator_json->>'auth_request_id',
        v_auth_locator_json->>'authRequestId'
      )::uuid;
    END IF;

    IF v_operation_auth_request_id IS NULL THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_RAIL',
        'code', 'AUTHORISED_EXECUTION_INTENT_REQUIRED',
        'message', 'An authorised server-frozen execution intent is required before operation-mode rail settlement can continue.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'execution_operation_id', v_execution_operation_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    SELECT
      auth_request.state,
      CASE
        WHEN JSONB_TYPEOF(auth_request.execution_intent_json) = 'object'
          THEN COALESCE(auth_request.execution_intent_json, '{}'::jsonb)
        ELSE '{}'::jsonb
      END
    INTO
      v_operation_auth_state,
      v_operation_auth_intent_json
    FROM public.pay_batch_auth_requests AS auth_request
    WHERE auth_request.id = v_operation_auth_request_id
      AND auth_request.pay_batch_id = p_pay_batch_id
    FOR UPDATE;


    IF NOT FOUND
       OR UPPER(BTRIM(COALESCE(v_operation_auth_state, ''))) <> 'AUTHORISED'
       OR JSONB_TYPEOF(v_operation_auth_intent_json) <> 'object'
       OR v_operation_auth_intent_json = '{}'::jsonb THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_RAIL',
        'code', 'AUTHORISED_EXECUTION_INTENT_REQUIRED',
        'message', 'The payment auth request is missing, belongs to another batch, is not authorised, or has no execution intent.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'execution_operation_id', v_execution_operation_id::text,
        'auth_request_id', v_operation_auth_request_id::text,
        'auth_state', v_operation_auth_state
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF v_batch_intent_json = '{}'::jsonb THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_RAIL',
        'code', 'BATCH_EXECUTION_INTENT_REQUIRED',
        'message', 'The batch does not contain the server-frozen execution intent required for settlement.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'auth_request_id', v_operation_auth_request_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF NULLIF(BTRIM(COALESCE(v_operation_auth_intent_json->>'operation_id', '')), '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_auth_intent_operation_id := (v_operation_auth_intent_json->>'operation_id')::uuid;
    END IF;
    IF NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'operation_id', '')), '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_batch_intent_operation_id := (v_batch_intent_json->>'operation_id')::uuid;
    END IF;
    IF NULLIF(BTRIM(COALESCE(v_operation_auth_intent_json->>'auth_request_id', '')), '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_auth_intent_auth_request_id := (v_operation_auth_intent_json->>'auth_request_id')::uuid;
    END IF;
    IF NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'auth_request_id', '')), '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_batch_intent_auth_request_id := (v_batch_intent_json->>'auth_request_id')::uuid;
    END IF;

    v_authorised_execution_mode := CASE
      WHEN UPPER(BTRIM(COALESCE(v_operation_auth_intent_json->>'execution_mode', ''))) IN ('STANDARD_BANK', 'BANK') THEN 'STANDARD_BANK'
      WHEN UPPER(BTRIM(COALESCE(v_operation_auth_intent_json->>'execution_mode', ''))) IN ('CSV', 'CSV_SETTLEMENT') THEN 'CSV_SETTLEMENT'
      WHEN UPPER(BTRIM(COALESCE(v_operation_auth_intent_json->>'execution_mode', ''))) IN ('EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'EXTERNAL_SETTLEMENT'
      ELSE UPPER(NULLIF(BTRIM(COALESCE(v_operation_auth_intent_json->>'execution_mode', '')), ''))
    END;
    v_batch_execution_mode := CASE
      WHEN UPPER(BTRIM(COALESCE(v_batch_intent_json->>'execution_mode', ''))) IN ('STANDARD_BANK', 'BANK') THEN 'STANDARD_BANK'
      WHEN UPPER(BTRIM(COALESCE(v_batch_intent_json->>'execution_mode', ''))) IN ('CSV', 'CSV_SETTLEMENT') THEN 'CSV_SETTLEMENT'
      WHEN UPPER(BTRIM(COALESCE(v_batch_intent_json->>'execution_mode', ''))) IN ('EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'EXTERNAL_SETTLEMENT'
      ELSE UPPER(NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'execution_mode', '')), ''))
    END;
    v_operation_projection_scope := UPPER(NULLIF(BTRIM(COALESCE(
      v_operation_auth_intent_json->>'pay_channel_scope',
      v_operation_auth_intent_json->>'scope',
      ''
    )), ''));
    v_batch_projection_scope := UPPER(NULLIF(BTRIM(COALESCE(
      v_batch_intent_json->>'pay_channel_scope',
      v_batch_intent_json->>'scope',
      ''
    )), ''));

    v_expected_paye_net_state_hash := NULLIF(BTRIM(COALESCE(
      v_operation_auth_intent_json->>'global_paye_net_state_hash',
      v_operation_auth_intent_json->>'paye_net_state_hash',
      ''
    )), '');
    v_batch_expected_paye_net_state_hash := NULLIF(BTRIM(COALESCE(
      v_batch_intent_json->>'global_paye_net_state_hash',
      v_batch_intent_json->>'paye_net_state_hash',
      ''
    )), '');
    v_expected_global_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(
      v_operation_auth_intent_json->>'global_bank_payment_projection_hash',
      ''
    )), '');
    v_batch_expected_global_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(
      v_batch_intent_json->>'global_bank_payment_projection_hash',
      ''
    )), '');
    v_expected_scoped_paye_net_state_hash := NULLIF(BTRIM(COALESCE(
      v_operation_auth_intent_json->>'scoped_paye_net_state_hash',
      ''
    )), '');
    v_batch_expected_scoped_paye_net_state_hash := NULLIF(BTRIM(COALESCE(
      v_batch_intent_json->>'scoped_paye_net_state_hash',
      ''
    )), '');
    v_expected_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(
      v_operation_auth_intent_json->>'scoped_bank_payment_projection_hash',
      v_operation_auth_intent_json->>'bank_payment_projection_hash',
      ''
    )), '');
    v_batch_expected_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(
      v_batch_intent_json->>'scoped_bank_payment_projection_hash',
      v_batch_intent_json->>'bank_payment_projection_hash',
      ''
    )), '');

    IF COALESCE(v_operation_auth_intent_json->>'global_missing_explicit_paye_input_count', v_operation_auth_intent_json->>'missing_explicit_paye_input_count', '') ~ '^[0-9]+$' THEN
      v_expected_missing_count := COALESCE(v_operation_auth_intent_json->>'global_missing_explicit_paye_input_count', v_operation_auth_intent_json->>'missing_explicit_paye_input_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'global_missing_explicit_paye_input_count', v_batch_intent_json->>'missing_explicit_paye_input_count', '') ~ '^[0-9]+$' THEN
      v_batch_expected_missing_count := COALESCE(v_batch_intent_json->>'global_missing_explicit_paye_input_count', v_batch_intent_json->>'missing_explicit_paye_input_count')::integer;
    END IF;
    IF COALESCE(v_operation_auth_intent_json->>'global_explicit_zero_count', v_operation_auth_intent_json->>'explicit_zero_count', '') ~ '^[0-9]+$' THEN
      v_expected_global_zero_count := COALESCE(v_operation_auth_intent_json->>'global_explicit_zero_count', v_operation_auth_intent_json->>'explicit_zero_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'global_explicit_zero_count', v_batch_intent_json->>'explicit_zero_count', '') ~ '^[0-9]+$' THEN
      v_batch_expected_global_zero_count := COALESCE(v_batch_intent_json->>'global_explicit_zero_count', v_batch_intent_json->>'explicit_zero_count')::integer;
    END IF;
    IF COALESCE(v_operation_auth_intent_json->>'global_positive_bank_payment_count', '') ~ '^[0-9]+$' THEN
      v_expected_global_positive_count := (v_operation_auth_intent_json->>'global_positive_bank_payment_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'global_positive_bank_payment_count', '') ~ '^[0-9]+$' THEN
      v_batch_expected_global_positive_count := (v_batch_intent_json->>'global_positive_bank_payment_count')::integer;
    END IF;
    IF COALESCE(v_operation_auth_intent_json->>'global_invalid_payment_row_count', '') ~ '^[0-9]+$' THEN
      v_expected_global_invalid_count := (v_operation_auth_intent_json->>'global_invalid_payment_row_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'global_invalid_payment_row_count', '') ~ '^[0-9]+$' THEN
      v_batch_expected_global_invalid_count := (v_batch_intent_json->>'global_invalid_payment_row_count')::integer;
    END IF;
    IF COALESCE(v_operation_auth_intent_json->>'scoped_missing_explicit_paye_input_count', '') ~ '^[0-9]+$' THEN
      v_expected_scoped_missing_count := (v_operation_auth_intent_json->>'scoped_missing_explicit_paye_input_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'scoped_missing_explicit_paye_input_count', '') ~ '^[0-9]+$' THEN
      v_batch_expected_scoped_missing_count := (v_batch_intent_json->>'scoped_missing_explicit_paye_input_count')::integer;
    END IF;
    IF COALESCE(v_operation_auth_intent_json->>'scoped_explicit_zero_count', '') ~ '^[0-9]+$' THEN
      v_expected_zero_count := (v_operation_auth_intent_json->>'scoped_explicit_zero_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'scoped_explicit_zero_count', '') ~ '^[0-9]+$' THEN
      v_batch_expected_zero_count := (v_batch_intent_json->>'scoped_explicit_zero_count')::integer;
    END IF;
    IF COALESCE(v_operation_auth_intent_json->>'scoped_positive_bank_payment_count', v_operation_auth_intent_json->>'positive_bank_payment_count', '') ~ '^[0-9]+$' THEN
      v_expected_positive_count := COALESCE(v_operation_auth_intent_json->>'scoped_positive_bank_payment_count', v_operation_auth_intent_json->>'positive_bank_payment_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'scoped_positive_bank_payment_count', v_batch_intent_json->>'positive_bank_payment_count', '') ~ '^[0-9]+$' THEN
      v_batch_expected_positive_count := COALESCE(v_batch_intent_json->>'scoped_positive_bank_payment_count', v_batch_intent_json->>'positive_bank_payment_count')::integer;
    END IF;
    IF COALESCE(v_operation_auth_intent_json->>'scoped_invalid_payment_row_count', '') ~ '^[0-9]+$' THEN
      v_expected_scoped_invalid_count := (v_operation_auth_intent_json->>'scoped_invalid_payment_row_count')::integer;
    END IF;
    IF COALESCE(v_batch_intent_json->>'scoped_invalid_payment_row_count', '') ~ '^[0-9]+$' THEN
      v_batch_expected_scoped_invalid_count := (v_batch_intent_json->>'scoped_invalid_payment_row_count')::integer;
    END IF;

    v_server_owned_projection_proof := LOWER(BTRIM(COALESCE(v_operation_auth_intent_json->>'server_owned_payment_projection_proof', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_batch_server_owned_projection_proof := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'server_owned_payment_projection_proof', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_scoped_no_transfer_marker := LOWER(BTRIM(COALESCE(v_operation_auth_intent_json->>'scoped_no_transfer_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_batch_scoped_no_transfer_marker := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'scoped_no_transfer_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_no_bank_payment_marker := LOWER(BTRIM(COALESCE(v_operation_auth_intent_json->>'no_bank_payment_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_batch_no_bank_payment_marker := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'no_bank_payment_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_allow_explicit_zero_no_bank_scopes_marker := LOWER(BTRIM(COALESCE(v_operation_auth_intent_json->>'allow_explicit_zero_no_bank_scopes', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_batch_allow_explicit_zero_no_bank_scopes_marker := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'allow_explicit_zero_no_bank_scopes', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_suppress_remittances := LOWER(BTRIM(COALESCE(v_operation_auth_intent_json->>'suppress_remittances', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_batch_suppress_remittances := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'suppress_remittances', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

    v_authorised_payment_date_raw := NULLIF(BTRIM(COALESCE(v_operation_auth_intent_json->>'payment_date', '')), '');
    v_batch_authorised_payment_date_raw := NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'payment_date', '')), '');
    IF v_authorised_payment_date_raw IS NOT NULL THEN
      BEGIN
        v_authorised_payment_date := v_authorised_payment_date_raw::date;
      EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'PAY_SETTLE_RAIL_AUTH_INTENT_PAYMENT_DATE_INVALID' USING ERRCODE = 'P0001';
      END;
    END IF;
    IF v_batch_authorised_payment_date_raw IS NOT NULL THEN
      BEGIN
        v_batch_authorised_payment_date := v_batch_authorised_payment_date_raw::date;
      EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'PAY_SETTLE_RAIL_BATCH_INTENT_PAYMENT_DATE_INVALID' USING ERRCODE = 'P0001';
      END;

    END IF;

    IF v_auth_intent_operation_id IS NULL
       OR v_batch_intent_operation_id IS NULL
       OR v_auth_intent_operation_id <> v_execution_operation_id
       OR v_batch_intent_operation_id <> v_execution_operation_id
       OR v_auth_intent_auth_request_id IS DISTINCT FROM v_operation_auth_request_id
       OR v_batch_intent_auth_request_id IS DISTINCT FROM v_operation_auth_request_id
       OR v_authorised_execution_mode NOT IN ('STANDARD_BANK', 'CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT')
       OR v_authorised_execution_mode IS DISTINCT FROM v_batch_execution_mode
       OR v_operation_projection_scope NOT IN ('ALL', 'PAYE', 'UMBRELLA', 'LOANS')
       OR v_operation_projection_scope IS DISTINCT FROM v_batch_projection_scope
       OR v_expected_paye_net_state_hash IS NULL
       OR v_expected_paye_net_state_hash IS DISTINCT FROM v_batch_expected_paye_net_state_hash
       OR v_expected_global_bank_payment_projection_hash IS NULL
       OR v_expected_global_bank_payment_projection_hash IS DISTINCT FROM v_batch_expected_global_bank_payment_projection_hash
       OR v_expected_scoped_paye_net_state_hash IS NULL
       OR v_expected_scoped_paye_net_state_hash IS DISTINCT FROM v_batch_expected_scoped_paye_net_state_hash
       OR v_expected_bank_payment_projection_hash IS NULL
       OR v_expected_bank_payment_projection_hash IS DISTINCT FROM v_batch_expected_bank_payment_projection_hash
       OR v_expected_missing_count IS NULL
       OR v_expected_missing_count IS DISTINCT FROM v_batch_expected_missing_count
       OR v_expected_global_zero_count IS NULL
       OR v_expected_global_zero_count IS DISTINCT FROM v_batch_expected_global_zero_count
       OR v_expected_global_positive_count IS NULL
       OR v_expected_global_positive_count IS DISTINCT FROM v_batch_expected_global_positive_count
       OR v_expected_global_invalid_count IS NULL
       OR v_expected_global_invalid_count IS DISTINCT FROM v_batch_expected_global_invalid_count
       OR v_expected_scoped_missing_count IS NULL
       OR v_expected_scoped_missing_count IS DISTINCT FROM v_batch_expected_scoped_missing_count
       OR v_expected_zero_count IS NULL
       OR v_expected_zero_count IS DISTINCT FROM v_batch_expected_zero_count
       OR v_expected_positive_count IS NULL
       OR v_expected_positive_count IS DISTINCT FROM v_batch_expected_positive_count
       OR v_expected_scoped_invalid_count IS NULL
       OR v_expected_scoped_invalid_count IS DISTINCT FROM v_batch_expected_scoped_invalid_count
       OR v_server_owned_projection_proof IS NOT TRUE
       OR v_batch_server_owned_projection_proof IS NOT TRUE
       OR v_scoped_no_transfer_marker IS DISTINCT FROM v_batch_scoped_no_transfer_marker
       OR v_no_bank_payment_marker IS DISTINCT FROM v_batch_no_bank_payment_marker
       OR v_allow_explicit_zero_no_bank_scopes_marker IS DISTINCT FROM v_batch_allow_explicit_zero_no_bank_scopes_marker
       OR v_suppress_remittances IS DISTINCT FROM v_batch_suppress_remittances
       OR v_authorised_payment_date IS DISTINCT FROM v_batch_authorised_payment_date THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_RAIL',
        'code', 'AUTH_BATCH_EXECUTION_INTENT_MISMATCH',
        'message', 'The authorised execution intent and batch execution intent are missing required server proof or are materially inconsistent.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'execution_operation_id', v_execution_operation_id::text,
        'auth_request_id', v_operation_auth_request_id::text,
        'authorised_execution_mode', v_authorised_execution_mode,
        'authorised_scope', v_operation_projection_scope
      )::text USING ERRCODE = 'P0001';
    END IF;

    v_settlement_mode := v_authorised_execution_mode;
    v_operation_effective_payment_date := COALESCE(
      v_authorised_payment_date,
      v_batch.authoritative_payment_date,
      v_batch.pay_date
    );

    DROP TABLE IF EXISTS pg_temp.tmp_pay_settle_rail_projection_rows;
    CREATE TEMPORARY TABLE pg_temp.tmp_pay_settle_rail_projection_rows
    ON COMMIT DROP
    AS
    SELECT projection_row.*
    FROM public._pay_batch_bank_payment_projection_rows(p_pay_batch_id, 'ALL') AS projection_row;

    DROP TABLE IF EXISTS pg_temp.tmp_pay_settle_rail_scoped_projection_rows;
    CREATE TEMPORARY TABLE pg_temp.tmp_pay_settle_rail_scoped_projection_rows
    ON COMMIT DROP
    AS
    SELECT projection_row.*
    FROM public._pay_batch_bank_payment_projection_rows(p_pay_batch_id, v_operation_projection_scope) AS projection_row;

    SELECT
      COUNT(*) FILTER (WHERE projection_row.is_paye_net_state_row AND projection_row.paye_net_classification = 'MISSING')::integer,
      COUNT(*) FILTER (WHERE projection_row.is_paye_net_state_row AND projection_row.paye_net_classification = 'ZERO')::integer,
      COUNT(*) FILTER (WHERE projection_row.is_positive_bank_payment)::integer,
      COUNT(*) FILTER (
        WHERE (
          projection_row.paye_net_required IS TRUE
          AND COALESCE(projection_row.paye_net_classification, '') NOT IN ('MISSING', 'ZERO', 'POSITIVE')
        )
        OR (
          COALESCE(projection_row.paye_net_required, false) IS FALSE
          AND (
            projection_row.final_frozen_bank_amount IS NULL
            OR ROUND(projection_row.final_frozen_bank_amount, 2) <= 0
          )
        )
      )::integer,
      MAX(projection_row.paye_net_state_hash),
      MAX(projection_row.bank_payment_projection_hash)
    INTO
      v_current_missing_count,
      v_global_zero_count,
      v_global_positive_count,
      v_global_invalid_count,
      v_current_paye_net_state_hash,
      v_all_bank_payment_projection_hash
    FROM pg_temp.tmp_pay_settle_rail_projection_rows AS projection_row;

    SELECT
      COUNT(*) FILTER (WHERE projection_row.is_paye_net_state_row AND projection_row.paye_net_classification = 'MISSING')::integer,
      COUNT(*) FILTER (WHERE projection_row.is_paye_net_state_row AND projection_row.paye_net_classification = 'ZERO')::integer,
      COUNT(*) FILTER (WHERE projection_row.is_positive_bank_payment)::integer,
      ROUND(COALESCE(SUM(projection_row.amount) FILTER (WHERE projection_row.is_positive_bank_payment), 0), 2)::numeric(14,2),
      COUNT(*) FILTER (
        WHERE (
          projection_row.paye_net_required IS TRUE
          AND COALESCE(projection_row.paye_net_classification, '') NOT IN ('MISSING', 'ZERO', 'POSITIVE')
        )
        OR (
          COALESCE(projection_row.paye_net_required, false) IS FALSE
          AND (
            projection_row.final_frozen_bank_amount IS NULL
            OR ROUND(projection_row.final_frozen_bank_amount, 2) <= 0
          )
        )
      )::integer,
      MAX(projection_row.paye_net_state_hash),
      MAX(projection_row.bank_payment_projection_hash)
    INTO
      v_current_scoped_missing_count,
      v_current_zero_count,
      v_current_positive_count,
      v_current_positive_total,
      v_current_scoped_invalid_count,
      v_current_scoped_paye_net_state_hash,
      v_current_bank_payment_projection_hash
    FROM pg_temp.tmp_pay_settle_rail_scoped_projection_rows AS projection_row;

    v_current_missing_count := COALESCE(v_current_missing_count, 0);
    v_global_zero_count := COALESCE(v_global_zero_count, 0);
    v_global_positive_count := COALESCE(v_global_positive_count, 0);
    v_global_invalid_count := COALESCE(v_global_invalid_count, 0);
    v_current_scoped_missing_count := COALESCE(v_current_scoped_missing_count, 0);
    v_current_zero_count := COALESCE(v_current_zero_count, 0);
    v_current_positive_count := COALESCE(v_current_positive_count, 0);
    v_current_positive_total := ROUND(COALESCE(v_current_positive_total, 0), 2);
    v_current_scoped_invalid_count := COALESCE(v_current_scoped_invalid_count, 0);
    v_current_paye_net_state_hash := COALESCE(v_current_paye_net_state_hash, MD5(JSONB_BUILD_OBJECT('pay_batch_id', p_pay_batch_id::text, 'scope', 'ALL', 'rows', '[]'::jsonb)::text));
    v_all_bank_payment_projection_hash := COALESCE(v_all_bank_payment_projection_hash, MD5(JSONB_BUILD_OBJECT('pay_batch_id', p_pay_batch_id::text, 'scope', 'ALL', 'rows', '[]'::jsonb)::text));
    v_current_scoped_paye_net_state_hash := COALESCE(v_current_scoped_paye_net_state_hash, MD5(JSONB_BUILD_OBJECT('pay_batch_id', p_pay_batch_id::text, 'scope', v_operation_projection_scope, 'rows', '[]'::jsonb)::text));
    v_current_bank_payment_projection_hash := COALESCE(v_current_bank_payment_projection_hash, MD5(JSONB_BUILD_OBJECT('pay_batch_id', p_pay_batch_id::text, 'scope', v_operation_projection_scope, 'rows', '[]'::jsonb)::text));

    v_current_projection_changed := (
      v_expected_paye_net_state_hash IS DISTINCT FROM v_current_paye_net_state_hash
      OR v_expected_global_bank_payment_projection_hash IS DISTINCT FROM v_all_bank_payment_projection_hash
      OR v_expected_scoped_paye_net_state_hash IS DISTINCT FROM v_current_scoped_paye_net_state_hash
      OR v_expected_bank_payment_projection_hash IS DISTINCT FROM v_current_bank_payment_projection_hash
      OR v_expected_missing_count IS DISTINCT FROM v_current_missing_count
      OR v_expected_global_zero_count IS DISTINCT FROM v_global_zero_count
      OR v_expected_global_positive_count IS DISTINCT FROM v_global_positive_count
      OR v_expected_global_invalid_count IS DISTINCT FROM v_global_invalid_count
      OR v_expected_scoped_missing_count IS DISTINCT FROM v_current_scoped_missing_count
      OR v_expected_zero_count IS DISTINCT FROM v_current_zero_count
      OR v_expected_positive_count IS DISTINCT FROM v_current_positive_count
      OR v_expected_scoped_invalid_count IS DISTINCT FROM v_current_scoped_invalid_count
    );

    v_projection_diagnostic_json := JSONB_BUILD_OBJECT(
      'projection_changed_after_authorisation', v_current_projection_changed,
      'settlement_blocked_by_projection_change', false,
      'authorised_global_paye_net_state_hash', v_expected_paye_net_state_hash,
      'current_global_paye_net_state_hash', v_current_paye_net_state_hash,
      'authorised_global_bank_payment_projection_hash', v_expected_global_bank_payment_projection_hash,
      'current_global_bank_payment_projection_hash', v_all_bank_payment_projection_hash,
      'authorised_scoped_paye_net_state_hash', v_expected_scoped_paye_net_state_hash,
      'current_scoped_paye_net_state_hash', v_current_scoped_paye_net_state_hash,
      'authorised_scoped_bank_payment_projection_hash', v_expected_bank_payment_projection_hash,
      'current_scoped_bank_payment_projection_hash', v_current_bank_payment_projection_hash,
      'authorised_scope', v_operation_projection_scope,
      'diagnostic_generated_at_utc', v_now::text
    );

    v_no_bank_scope_authorised := v_allow_explicit_zero_no_bank_scopes_marker

      AND COALESCE(v_expected_missing_count, -1) = 0
      AND COALESCE(v_expected_scoped_missing_count, -1) = 0
      AND COALESCE(v_expected_zero_count, 0) > 0
      AND COALESCE(v_expected_scoped_invalid_count, -1) = 0;
    v_no_bank_payment_execution_validated := v_no_bank_payment_marker
      AND v_scoped_no_transfer_marker
      AND v_no_bank_scope_authorised
      AND COALESCE(v_expected_positive_count, -1) = 0
      AND COALESCE(v_expected_global_positive_count, -1) = 0
      AND COALESCE(v_expected_global_invalid_count, -1) = 0;
    v_local_no_bank_commit_ref := 'NO_BANK_PAYMENT:' || v_operation_auth_request_id::text;
    v_proof_validation_outcome := CASE
      WHEN v_no_bank_payment_execution_validated THEN 'VALIDATED_NO_BANK_PAYMENT_FROM_AUTHORISED_INTENT'
      WHEN v_no_bank_scope_authorised AND COALESCE(v_expected_positive_count, 0) > 0 THEN 'VALIDATED_MIXED_ZERO_AND_TRANSFER_FROM_AUTHORISED_INTENT'
      WHEN v_no_bank_scope_authorised THEN 'VALIDATED_SCOPED_NO_TRANSFER_FROM_AUTHORISED_INTENT'
      ELSE 'VALIDATED_TRANSFER_BACKED_FROM_AUTHORISED_INTENT'
    END;

    IF v_no_bank_scope_authorised
       AND v_execution_operation_row.operation_type <> 'PAYMENT_EXECUTE' THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_RAIL',
        'code', 'NO_BANK_PAYMENT_EXECUTION_OPERATION_REQUIRED',
        'message', 'Explicit-zero no-bank settlement must remain bound to the original PAYMENT_EXECUTE operation and cannot be introduced by a blocked-funds retry.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'execution_operation_id', v_execution_operation_id::text,
        'execution_operation_type', v_execution_operation_row.operation_type
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF v_no_bank_payment_execution_validated THEN
      SELECT COUNT(*)::integer
      INTO v_no_bank_scope_artifact_count
      FROM public.banking_pay_operation_transfer_scope AS transfer_scope_row
      WHERE transfer_scope_row.operation_id = v_execution_operation_id
        AND transfer_scope_row.pay_batch_id = p_pay_batch_id;

      SELECT COUNT(*)::integer
      INTO v_no_bank_batch_transfer_count
      FROM public.pay_bank_transfers AS transfer_row
      WHERE transfer_row.pay_batch_id = p_pay_batch_id;

      SELECT COUNT(*)::integer
      INTO v_no_bank_transfer_event_count
      FROM public.pay_bank_transfer_events AS transfer_event_row
      WHERE transfer_event_row.pay_batch_id = p_pay_batch_id;

      SELECT COUNT(*)::integer
      INTO v_no_bank_provider_attempt_count
      FROM public.banking_pay_operation_provider_attempts AS provider_attempt_row
      WHERE provider_attempt_row.pay_batch_id = p_pay_batch_id
         OR provider_attempt_row.operation_id = v_execution_operation_id;

      IF COALESCE(v_no_bank_scope_artifact_count, 0) <> 0
         OR COALESCE(v_no_bank_batch_transfer_count, 0) <> 0
         OR COALESCE(v_no_bank_transfer_event_count, 0) <> 0
         OR COALESCE(v_no_bank_provider_attempt_count, 0) <> 0 THEN
        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
          'error', 'PAY_SETTLE_RAIL',
          'code', 'NO_BANK_PAYMENT_EXECUTION_EVIDENCE_CONFLICT',
          'message', 'No-bank payment settlement cannot continue because transfer or provider-submission evidence already exists.',
          'pay_batch_id', p_pay_batch_id::text,
          'operation_id', p_operation_id::text,
          'execution_operation_id', v_execution_operation_id::text,
          'transfer_scope_count', COALESCE(v_no_bank_scope_artifact_count, 0),
          'bank_transfer_count', COALESCE(v_no_bank_batch_transfer_count, 0),
          'bank_transfer_event_count', COALESCE(v_no_bank_transfer_event_count, 0),
          'provider_attempt_count', COALESCE(v_no_bank_provider_attempt_count, 0)
        )::text USING ERRCODE = 'P0001';
      END IF;

      IF UPPER(BTRIM(COALESCE(v_batch.execution_commit_state, 'NOT_SUBMITTED'))) NOT IN ('NOT_SUBMITTED', 'COMMITTED')
         OR (
           NULLIF(BTRIM(COALESCE(v_batch.execution_commit_ref, '')), '') IS NOT NULL
           AND NULLIF(BTRIM(COALESCE(v_batch.execution_commit_ref, '')), '') <> v_local_no_bank_commit_ref
         )
         OR (
           UPPER(BTRIM(COALESCE(v_batch.execution_commit_state, 'NOT_SUBMITTED'))) = 'COMMITTED'
           AND (
             NULLIF(BTRIM(COALESCE(v_batch.execution_commit_ref, '')), '') IS DISTINCT FROM v_local_no_bank_commit_ref
             OR v_batch.execution_committed_at_utc IS NULL
           )
         )
         OR (
           UPPER(BTRIM(COALESCE(v_batch.execution_commit_state, 'NOT_SUBMITTED'))) = 'NOT_SUBMITTED'
           AND v_batch.execution_committed_at_utc IS NOT NULL
         ) THEN
        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
          'error', 'PAY_SETTLE_RAIL',
          'code', 'NO_BANK_PAYMENT_EXECUTION_COMMIT_CONFLICT',
          'message', 'The batch contains execution commit evidence that is incompatible with the authorised no-bank-payment execution.',
          'pay_batch_id', p_pay_batch_id::text,
          'operation_id', p_operation_id::text,
          'execution_commit_state', v_batch.execution_commit_state,
          'execution_commit_ref', v_batch.execution_commit_ref,
          'expected_local_commit_reference', v_local_no_bank_commit_ref
        )::text USING ERRCODE = 'P0001';
      END IF;
    END IF;

    DROP TABLE IF EXISTS pg_temp.tmp_pay_settle_rail_requested_scope_ids;
    CREATE TEMPORARY TABLE pg_temp.tmp_pay_settle_rail_requested_scope_ids (
      settlement_scope_id uuid PRIMARY KEY
    ) ON COMMIT DROP;

    INSERT INTO pg_temp.tmp_pay_settle_rail_requested_scope_ids (settlement_scope_id)
    SELECT DISTINCT (scope_element.value #>> '{}')::uuid
    FROM JSONB_ARRAY_ELEMENTS(p_settlement_scope_ids) AS scope_element(value)
    WHERE (scope_element.value #>> '{}')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

    SELECT COUNT(*)::integer
    INTO v_requested_scope_count
    FROM pg_temp.tmp_pay_settle_rail_requested_scope_ids AS requested_scope_id;

    IF v_requested_scope_count <> JSONB_ARRAY_LENGTH(p_settlement_scope_ids) THEN
      RAISE EXCEPTION 'p_settlement_scope_ids contains invalid or duplicate uuid values';
    END IF;

    PERFORM 1
    FROM public.banking_pay_operation_settlement_scope AS scope_row
    JOIN pg_temp.tmp_pay_settle_rail_requested_scope_ids AS requested_scope_id
      ON requested_scope_id.settlement_scope_id = scope_row.id
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id
    FOR UPDATE OF scope_row;

    SELECT
      COUNT(*)::integer,
      COUNT(*) FILTER (WHERE scope_row.status = 'SETTLED')::integer,
      COUNT(*) FILTER (WHERE scope_row.status = 'FAILED')::integer
    INTO
      v_matched_scope_count,
      v_reused_this_chunk,
      v_existing_failed_scope_count
    FROM public.banking_pay_operation_settlement_scope AS scope_row
    JOIN pg_temp.tmp_pay_settle_rail_requested_scope_ids AS requested_scope_id
      ON requested_scope_id.settlement_scope_id = scope_row.id
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id;

    v_failed_this_chunk := COALESCE(v_existing_failed_scope_count, 0);

    IF v_matched_scope_count <> v_requested_scope_count THEN
      RAISE EXCEPTION 'one or more settlement scope ids do not belong to operation % and batch %', p_operation_id, p_pay_batch_id;
    END IF;

    DROP TABLE IF EXISTS pg_temp.tmp_pay_settle_rail_eligible_no_bank_scope;
    CREATE TEMPORARY TABLE pg_temp.tmp_pay_settle_rail_eligible_no_bank_scope
    ON COMMIT DROP
    AS
    WITH frozen_scope AS (
      SELECT
        scope_row.id AS settlement_scope_id,
        scope_row.status,
        scope_row.pay_batch_candidate_id,
        scope_row.candidate_id,
        scope_row.payload_json
      FROM public.banking_pay_operation_settlement_scope AS scope_row
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
        AND scope_row.status IN ('PENDING', 'SETTLED')
        AND scope_row.settlement_event_id IS NULL
        AND v_no_bank_scope_authorised
        AND UPPER(BTRIM(COALESCE(scope_row.pay_channel, ''))) = 'PAYE'
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'pay_batch_id', '')), '') = p_pay_batch_id::text
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'pay_batch_candidate_id', '')), '') = scope_row.pay_batch_candidate_id::text
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'candidate_id', '')), '') = scope_row.candidate_id::text
        AND UPPER(NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'pay_channel', '')), '')) = 'PAYE'
        AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'scope_kind', ''))) = 'NO_BANK_PAYMENT'
        AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_reason', ''))) = 'EXPLICIT_ZERO_PAYE'
        AND LOWER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_scope', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(scope_row.payload_json->>'server_owned_payment_projection_proof', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'pay_bank_transfer_id', '')), '') IS NULL
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')), '') IS NULL
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'execution_operation_id', '')), '') = v_execution_operation_id::text
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'settlement_operation_id', '')), '') = p_operation_id::text
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'auth_request_id', '')), '') = v_operation_auth_request_id::text
        AND UPPER(NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'authorised_execution_mode', '')), '')) IS NOT DISTINCT FROM v_authorised_execution_mode

        AND UPPER(NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'authorised_scope', scope_row.payload_json->>'projection_scope', '')), '')) IS NOT DISTINCT FROM v_operation_projection_scope
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'authorised_paye_net_state_hash', scope_row.payload_json->>'paye_net_state_hash', '')), '') = v_expected_paye_net_state_hash
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'global_bank_payment_projection_hash', '')), '') = v_expected_global_bank_payment_projection_hash
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'scoped_paye_net_state_hash', '')), '') = v_expected_scoped_paye_net_state_hash
        AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'authorised_bank_payment_projection_hash', scope_row.payload_json->>'bank_payment_projection_hash', '')), '') = v_expected_bank_payment_projection_hash
        AND (LOWER(BTRIM(COALESCE(scope_row.payload_json->>'scoped_no_transfer_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) = v_scoped_no_transfer_marker
        AND (LOWER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) = v_no_bank_payment_marker
        AND (LOWER(BTRIM(COALESCE(scope_row.payload_json->>'allow_explicit_zero_no_bank_scopes', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) = v_allow_explicit_zero_no_bank_scopes_marker
        AND (LOWER(BTRIM(COALESCE(scope_row.payload_json->>'suppress_remittances', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) = v_suppress_remittances
        AND COALESCE(scope_row.payload_json->>'authorised_missing_explicit_paye_input_count', '') ~ '^[0-9]+$'
        AND (scope_row.payload_json->>'authorised_missing_explicit_paye_input_count')::integer = v_expected_missing_count
        AND COALESCE(scope_row.payload_json->>'authorised_explicit_zero_count', '') ~ '^[0-9]+$'
        AND (scope_row.payload_json->>'authorised_explicit_zero_count')::integer = v_expected_global_zero_count
        AND COALESCE(scope_row.payload_json->>'authorised_global_positive_bank_payment_count', '') ~ '^[0-9]+$'
        AND (scope_row.payload_json->>'authorised_global_positive_bank_payment_count')::integer = v_expected_global_positive_count
        AND COALESCE(scope_row.payload_json->>'authorised_global_invalid_payment_row_count', '') ~ '^[0-9]+$'
        AND (scope_row.payload_json->>'authorised_global_invalid_payment_row_count')::integer = v_expected_global_invalid_count
        AND COALESCE(scope_row.payload_json->>'authorised_scoped_missing_explicit_paye_input_count', '') ~ '^[0-9]+$'
        AND (scope_row.payload_json->>'authorised_scoped_missing_explicit_paye_input_count')::integer = v_expected_scoped_missing_count
        AND COALESCE(scope_row.payload_json->>'authorised_scoped_explicit_zero_count', '') ~ '^[0-9]+$'
        AND (scope_row.payload_json->>'authorised_scoped_explicit_zero_count')::integer = v_expected_zero_count
        AND COALESCE(scope_row.payload_json->>'authorised_scoped_positive_bank_payment_count', '') ~ '^[0-9]+$'
        AND (scope_row.payload_json->>'authorised_scoped_positive_bank_payment_count')::integer = v_expected_positive_count
        AND COALESCE(scope_row.payload_json->>'authorised_scoped_invalid_payment_row_count', '') ~ '^[0-9]+$'
        AND (scope_row.payload_json->>'authorised_scoped_invalid_payment_row_count')::integer = v_expected_scoped_invalid_count
        AND JSONB_TYPEOF(scope_row.payload_json->'pay_batch_item_ids') = 'array'
        AND JSONB_ARRAY_LENGTH(scope_row.payload_json->'pay_batch_item_ids') > 0
        AND COALESCE(scope_row.payload_json->>'item_count', '') ~ '^[0-9]+$'
        AND (scope_row.payload_json->>'item_count')::integer = JSONB_ARRAY_LENGTH(scope_row.payload_json->'pay_batch_item_ids')
        AND NOT EXISTS (
          SELECT 1
          FROM JSONB_ARRAY_ELEMENTS_TEXT(scope_row.payload_json->'pay_batch_item_ids') AS item_element(item_id_text)
          WHERE item_element.item_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             OR NOT EXISTS (
               SELECT 1
               FROM public.pay_batch_items AS payload_item
               WHERE payload_item.id = CASE
                       WHEN item_element.item_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                         THEN item_element.item_id_text::uuid
                       ELSE NULL::uuid
                     END
                 AND payload_item.pay_batch_candidate_id = scope_row.pay_batch_candidate_id
                 AND UPPER(BTRIM(COALESCE(payload_item.pay_channel, ''))) = 'PAYE'
                 AND COALESCE(payload_item.is_voided, false) = false
                 AND COALESCE(payload_item.item_type, '') <> 'DEBT_CREATED'
                 AND payload_item.pay_bank_transfer_id IS NULL
             )
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_batch_items AS candidate_scope_item
          WHERE candidate_scope_item.pay_batch_candidate_id = scope_row.pay_batch_candidate_id
            AND UPPER(BTRIM(COALESCE(candidate_scope_item.pay_channel, ''))) = 'PAYE'
            AND COALESCE(candidate_scope_item.is_voided, false) = false
            AND COALESCE(candidate_scope_item.item_type, '') <> 'DEBT_CREATED'
            AND NOT (scope_row.payload_json->'pay_batch_item_ids' @> JSONB_BUILD_ARRAY(TO_JSONB(candidate_scope_item.id::text)))
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_batch_items AS linked_item
          WHERE linked_item.pay_batch_candidate_id = scope_row.pay_batch_candidate_id
            AND UPPER(BTRIM(COALESCE(linked_item.pay_channel, ''))) = 'PAYE'
            AND COALESCE(linked_item.is_voided, false) = false
            AND linked_item.pay_bank_transfer_id IS NOT NULL
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_transfer_scope AS transfer_scope_evidence
          WHERE transfer_scope_evidence.pay_batch_id = p_pay_batch_id
            AND (
              transfer_scope_evidence.candidate_id = scope_row.candidate_id
              OR transfer_scope_evidence.candidate_id IS NULL
            )
            AND UPPER(BTRIM(COALESCE(transfer_scope_evidence.pay_channel, ''))) = 'PAYE'
            AND (
              transfer_scope_evidence.pay_bank_transfer_id IS NOT NULL
              OR transfer_scope_evidence.provider_submit_attempt_count > 0
              OR transfer_scope_evidence.provider_request_sent_at_utc IS NOT NULL
              OR NULLIF(BTRIM(COALESCE(transfer_scope_evidence.provider_request_id, '')), '') IS NOT NULL
              OR NULLIF(BTRIM(COALESCE(transfer_scope_evidence.provider_transaction_id, '')), '') IS NOT NULL
            )
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_bank_transfers AS transfer_evidence
          WHERE transfer_evidence.pay_batch_id = p_pay_batch_id
            AND (
              transfer_evidence.candidate_id = scope_row.candidate_id
              OR transfer_evidence.candidate_id IS NULL
            )
            AND UPPER(BTRIM(COALESCE(transfer_evidence.pay_channel, ''))) = 'PAYE'
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_bank_transfer_events AS transfer_event_evidence
          LEFT JOIN public.pay_bank_transfers AS event_transfer_evidence
            ON event_transfer_evidence.id = transfer_event_evidence.pay_bank_transfer_id
          WHERE transfer_event_evidence.pay_batch_id = p_pay_batch_id
            AND (
              COALESCE(transfer_event_evidence.candidate_id, event_transfer_evidence.candidate_id) = scope_row.candidate_id
              OR (
                transfer_event_evidence.candidate_id IS NULL
                AND transfer_event_evidence.pay_bank_transfer_id IS NULL
              )
            )
            AND (
              transfer_event_evidence.pay_bank_transfer_id IS NULL
              OR UPPER(BTRIM(COALESCE(event_transfer_evidence.pay_channel, ''))) = 'PAYE'
            )
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_provider_attempts AS provider_attempt_evidence
          LEFT JOIN public.banking_pay_operation_transfer_scope AS provider_attempt_scope
            ON provider_attempt_scope.id = provider_attempt_evidence.transfer_scope_id
          WHERE (
              provider_attempt_evidence.pay_batch_id = p_pay_batch_id
              OR provider_attempt_scope.pay_batch_id = p_pay_batch_id
            )
            AND (
              (
                provider_attempt_scope.candidate_id = scope_row.candidate_id
                AND UPPER(BTRIM(COALESCE(provider_attempt_scope.pay_channel, ''))) = 'PAYE'
              )
              OR (
                provider_attempt_evidence.transfer_scope_id IS NULL
                AND (
                  provider_attempt_evidence.operation_id = v_execution_operation_id
                  OR provider_attempt_evidence.pay_batch_id = p_pay_batch_id
                )
              )
            )
        )
    ), current_zero AS (
      SELECT DISTINCT
        projection_row.pay_batch_candidate_id,
        projection_row.candidate_id,
        projection_row.effective_paye_net_input_id
      FROM pg_temp.tmp_pay_settle_rail_scoped_projection_rows AS projection_row
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.id = projection_row.pay_batch_candidate_id
       AND batch_candidate.pay_batch_id = p_pay_batch_id
      WHERE projection_row.is_paye_net_state_row
        AND projection_row.pay_channel = 'PAYE'
        AND projection_row.has_effective_paye_input IS TRUE
        AND projection_row.effective_paye_net_input_id IS NOT NULL
        AND projection_row.paye_net_classification = 'ZERO'
        AND projection_row.final_frozen_bank_amount IS NOT NULL
        AND ROUND(projection_row.final_frozen_bank_amount, 2) = 0
        AND batch_candidate.net_bank_amount IS NOT NULL
        AND ROUND(batch_candidate.net_bank_amount, 2) = 0
    )
    SELECT
      frozen_scope.settlement_scope_id,
      frozen_scope.pay_batch_candidate_id,
      frozen_scope.candidate_id
    FROM frozen_scope
    LEFT JOIN current_zero
      ON current_zero.pay_batch_candidate_id = frozen_scope.pay_batch_candidate_id
     AND current_zero.candidate_id = frozen_scope.candidate_id
    WHERE frozen_scope.status = 'SETTLED'
       OR (
         frozen_scope.status = 'PENDING'
         AND current_zero.pay_batch_candidate_id IS NOT NULL
         AND (
           v_no_bank_payment_marker IS NOT TRUE
           OR v_current_projection_changed IS NOT TRUE
         )
         AND NULLIF(BTRIM(COALESCE(frozen_scope.payload_json->>'effective_paye_net_input_id', '')), '') = current_zero.effective_paye_net_input_id::text
         AND COALESCE(frozen_scope.payload_json->>'net_bank_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
         AND ROUND((frozen_scope.payload_json->>'net_bank_amount')::numeric, 2) = 0
       );


    SELECT
      COUNT(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(scope_row.payload_json->>'scope_kind', ''))) = 'NO_BANK_PAYMENT'
          AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_reason', ''))) = 'EXPLICIT_ZERO_PAYE'
      )::integer,
      COUNT(eligible_scope.settlement_scope_id)::integer

    INTO
      v_selected_no_bank_scope_count,
      v_selected_eligible_no_bank_scope_count
    FROM public.banking_pay_operation_settlement_scope AS scope_row
    JOIN pg_temp.tmp_pay_settle_rail_requested_scope_ids AS requested_scope_id
      ON requested_scope_id.settlement_scope_id = scope_row.id
    LEFT JOIN pg_temp.tmp_pay_settle_rail_eligible_no_bank_scope AS eligible_scope
      ON eligible_scope.settlement_scope_id = scope_row.id
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id;

    IF COALESCE(v_selected_no_bank_scope_count, 0) <> COALESCE(v_selected_eligible_no_bank_scope_count, 0) THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_RAIL',
        'code', 'NO_BANK_SETTLEMENT_SCOPE_PROOF_INVALID',
        'message', 'One or more requested no-bank settlement scopes are not bound to the authorised execution proof or contain transfer/provider evidence.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'execution_operation_id', v_execution_operation_id::text,
        'auth_request_id', v_operation_auth_request_id::text,
        'requested_no_bank_scope_count', COALESCE(v_selected_no_bank_scope_count, 0),
        'eligible_no_bank_scope_count', COALESCE(v_selected_eligible_no_bank_scope_count, 0)
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM JSONB_ARRAY_ELEMENTS(p_settlement_json) AS settlement_element(value)
      WHERE JSONB_TYPEOF(settlement_element.value) <> 'object'
    ) THEN
      RAISE EXCEPTION 'pay_settle_rail: settlement_json must contain only JSON objects';
    END IF;

    IF JSONB_ARRAY_LENGTH(p_settlement_json) = 0
       AND EXISTS (
         SELECT 1
         FROM public.banking_pay_operation_settlement_scope AS pending_requested_scope
         JOIN pg_temp.tmp_pay_settle_rail_requested_scope_ids AS pending_requested_scope_id
           ON pending_requested_scope_id.settlement_scope_id = pending_requested_scope.id
         WHERE pending_requested_scope.operation_id = p_operation_id
           AND pending_requested_scope.pay_batch_id = p_pay_batch_id
           AND pending_requested_scope.status = 'PENDING'
           AND NOT EXISTS (
             SELECT 1
             FROM pg_temp.tmp_pay_settle_rail_eligible_no_bank_scope AS pending_eligible_no_bank_scope
             WHERE pending_eligible_no_bank_scope.settlement_scope_id = pending_requested_scope.id
           )
       ) THEN
      RAISE EXCEPTION 'PAY_SETTLE_RAIL_TRANSFER_PAYLOAD_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = JSONB_BUILD_OBJECT(
                'code', 'PAY_SETTLE_RAIL_TRANSFER_PAYLOAD_REQUIRED',
                'pay_batch_id', p_pay_batch_id::text,
                'operation_id', p_operation_id::text,
                'requested_scope_count', COALESCE(v_requested_scope_count, 0),
                'requested_no_bank_scope_count', COALESCE(v_selected_no_bank_scope_count, 0),
                'eligible_no_bank_scope_count', COALESCE(v_selected_eligible_no_bank_scope_count, 0),
                'message', 'An empty rail settlement payload is valid only when every requested scope that is still pending is an authorised explicit-zero no-bank-payment scope; already-terminal scopes remain idempotently reusable.'
              )::text;
    END IF;

    CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.tmp_operation_rail_settlement_updates (
      transfer_id uuid NULL,
      status text NOT NULL,
      rail_tx_id text NULL,
      rail_state text NULL,
      rail_meta_json jsonb NULL,
      provider_reference text NULL,
      provider_state text NULL,
      event_time_utc timestamptz NULL,
      input_json jsonb NOT NULL
    ) ON COMMIT DROP;
    TRUNCATE TABLE pg_temp.tmp_operation_rail_settlement_updates;

    INSERT INTO pg_temp.tmp_operation_rail_settlement_updates (
      transfer_id,
      status,
      rail_tx_id,
      rail_state,
      rail_meta_json,
      provider_reference,
      provider_state,
      event_time_utc,
      input_json
    )
    SELECT
      CASE
        WHEN NULLIF(BTRIM(COALESCE(update_element.value->>'transfer_id', update_element.value->>'pay_bank_transfer_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(update_element.value->>'transfer_id', update_element.value->>'pay_bank_transfer_id', '')), '')::uuid
        ELSE NULL::uuid
      END,
      CASE
        WHEN upper(BTRIM(COALESCE(update_element.value->>'status', update_element.value->>'normalised_state', update_element.value->>'normalized_state', 'UNKNOWN'))) IN ('SUCCESS', 'SUCCEEDED', 'SETTLED', 'PAID') THEN 'COMPLETED'
        WHEN upper(BTRIM(COALESCE(update_element.value->>'status', update_element.value->>'normalised_state', update_element.value->>'normalized_state', 'UNKNOWN'))) IN ('CANCELED', 'CANCELLED') THEN 'CANCELLED'
        WHEN upper(BTRIM(COALESCE(update_element.value->>'status', update_element.value->>'normalised_state', update_element.value->>'normalized_state', 'UNKNOWN'))) IN ('REVERSED', 'REVERTED') THEN 'RETURNED'
        WHEN upper(BTRIM(COALESCE(update_element.value->>'status', update_element.value->>'normalised_state', update_element.value->>'normalized_state', 'UNKNOWN'))) IN ('SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT', 'DECLINED', 'REJECTED') THEN 'FAILED'
        ELSE upper(BTRIM(COALESCE(update_element.value->>'status', update_element.value->>'normalised_state', update_element.value->>'normalized_state', 'UNKNOWN')))
      END,
      NULLIF(BTRIM(COALESCE(update_element.value->>'rail_tx_id', '')), ''),
      NULLIF(BTRIM(COALESCE(update_element.value->>'rail_state', update_element.value->>'provider_state', '')), ''),
      CASE WHEN update_element.value ? 'rail_meta_json' THEN update_element.value->'rail_meta_json' ELSE '{}'::jsonb END,
      NULLIF(BTRIM(COALESCE(
        update_element.value->>'provider_reference',
        update_element.value->>'provider_event_id',
        update_element.value->>'provider_submission_id',
        update_element.value->>'submission_id',
        update_element.value->>'rail_submission_id',
        update_element.value->>'provider_transfer_id',
        update_element.value->>'provider_payment_id',
        update_element.value->>'payment_id',
        update_element.value->>'external_payment_id',
        update_element.value->>'revolut_payment_id',
        update_element.value->>'external_transfer_id',
        update_element.value->>'provider_transaction_id',
        update_element.value->>'transaction_id',
        update_element.value #>> '{rail_meta_json,provider_reference}',
        update_element.value #>> '{rail_meta_json,provider_event_id}',
        update_element.value #>> '{rail_meta_json,provider_submission_id}',
        update_element.value #>> '{rail_meta_json,submission_id}',
        update_element.value #>> '{rail_meta_json,rail_submission_id}',
        update_element.value #>> '{rail_meta_json,provider_transfer_id}',
        update_element.value #>> '{rail_meta_json,provider_payment_id}',
        update_element.value #>> '{rail_meta_json,payment_id}',
        update_element.value #>> '{rail_meta_json,external_payment_id}',
        update_element.value #>> '{rail_meta_json,revolut_payment_id}',
        update_element.value #>> '{rail_meta_json,external_transfer_id}',
        update_element.value #>> '{rail_meta_json,provider_transaction_id}',
        update_element.value #>> '{rail_meta_json,transaction_id}',
        update_element.value->>'rail_tx_id',
        ''
      )), ''),
      NULLIF(BTRIM(COALESCE(update_element.value->>'provider_state', update_element.value->>'rail_state', update_element.value->>'status', '')), ''),
      CASE WHEN NULLIF(BTRIM(COALESCE(update_element.value->>'event_time_utc', '')), '') IS NOT NULL THEN NULLIF(BTRIM(COALESCE(update_element.value->>'event_time_utc', '')), '')::timestamptz ELSE v_now END,
      update_element.value
    FROM jsonb_array_elements(p_settlement_json) AS update_element(value)
    WHERE jsonb_typeof(update_element.value) = 'object';

    IF EXISTS (SELECT 1 FROM pg_temp.tmp_operation_rail_settlement_updates AS invalid_update WHERE invalid_update.transfer_id IS NULL LIMIT 1) THEN
      RAISE EXCEPTION 'pay_settle_rail: settlement_json contains an invalid or missing transfer_id';
    END IF;

    DROP TABLE IF EXISTS pg_temp.tmp_operation_rail_settlement_classification;
    CREATE TEMP TABLE tmp_operation_rail_settlement_classification ON COMMIT DROP AS
    SELECT
      update_rows.transfer_id,
      classification_rows.cash_state,
      classification_rows.normalised_transfer_status,
      classification_rows.is_final_money_moved,
      classification_rows.is_terminal_no_money,
      classification_rows.is_pending_non_final,
      classification_rows.completed_at_allowed,
      classification_rows.reason,
      classification_rows.support_details_json
    FROM pg_temp.tmp_operation_rail_settlement_updates AS update_rows
    CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
      update_rows.status,
      COALESCE(update_rows.rail_state, update_rows.provider_state),
      COALESCE(update_rows.rail_meta_json, '{}'::jsonb) || COALESCE(update_rows.input_json, '{}'::jsonb),
      COALESCE(update_rows.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
        'provider_state', update_rows.provider_state,
        'provider_reference', update_rows.provider_reference,
        'settlement_operation_id', p_operation_id::text
      )
    ) AS classification_rows;

    UPDATE pg_temp.tmp_operation_rail_settlement_updates AS update_rows
    SET
      status = CASE
        WHEN classification_rows.is_final_money_moved THEN 'COMPLETED'
        WHEN classification_rows.is_terminal_no_money AND upper(COALESCE(update_rows.status, '')) IN ('CANCELLED','CANCELED') THEN 'CANCELLED'
        WHEN classification_rows.is_terminal_no_money THEN 'FAILED'
        WHEN classification_rows.is_pending_non_final THEN CASE WHEN upper(COALESCE(update_rows.status, '')) IN ('PROCESSING','SUBMITTED','SENT','ACCEPTED') THEN 'PROCESSING' ELSE 'PENDING' END
        ELSE 'UNKNOWN'
      END,
      rail_meta_json = COALESCE(update_rows.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
        'money_movement_classification', jsonb_build_object(
          'cash_state', classification_rows.cash_state,
          'normalised_transfer_status', classification_rows.normalised_transfer_status,
          'is_final_money_moved', classification_rows.is_final_money_moved,
          'is_terminal_no_money', classification_rows.is_terminal_no_money,

          'is_pending_non_final', classification_rows.is_pending_non_final,
          'completed_at_allowed', classification_rows.completed_at_allowed,
          'reason', classification_rows.reason
        ),
        'settlement_final_paid_required', true
      )
    FROM pg_temp.tmp_operation_rail_settlement_classification AS classification_rows
    WHERE classification_rows.transfer_id = update_rows.transfer_id;

    SELECT COALESCE(jsonb_agg(to_jsonb(duplicate_update.transfer_id::text) ORDER BY duplicate_update.transfer_id::text), '[]'::jsonb)
    INTO v_duplicate_transfer_ids
    FROM (
      SELECT duplicate_source.transfer_id
      FROM pg_temp.tmp_operation_rail_settlement_updates AS duplicate_source
      GROUP BY duplicate_source.transfer_id
      HAVING COUNT(*) > 1
    ) AS duplicate_update;

    IF jsonb_array_length(v_duplicate_transfer_ids) > 0 THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_SETTLE_RAIL_DUPLICATE_TRANSFER_UPDATE',
        'message', 'A rail settlement update chunk cannot contain duplicate transfer IDs.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'duplicate_transfer_ids', v_duplicate_transfer_ids
      )::text;
    END IF;

    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS settlement_scope_id
      FROM jsonb_array_elements(p_settlement_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), selected_scope AS (
      SELECT scope_row.*
      FROM public.banking_pay_operation_settlement_scope AS scope_row
      JOIN requested_scope
        ON requested_scope.settlement_scope_id = scope_row.id
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
    ), payload_transfer AS (
      SELECT selected_scope.id AS settlement_scope_id,
             CASE
               WHEN COALESCE(selected_scope.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                 THEN (selected_scope.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}')::uuid
               ELSE NULL::uuid
             END AS pay_bank_transfer_id
      FROM selected_scope
    ), payload_item_ids AS (
      SELECT selected_scope.id AS settlement_scope_id,
             (item_element.value #>> '{}')::uuid AS pay_batch_item_id
      FROM selected_scope
      CROSS JOIN LATERAL jsonb_array_elements(COALESCE(selected_scope.payload_json->'pay_batch_item_ids', '[]'::jsonb)) AS item_element(value)
      WHERE (item_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), scope_transfers AS (
      SELECT DISTINCT selected_scope.id AS settlement_scope_id,
             COALESCE(payload_transfer.pay_bank_transfer_id, batch_item.pay_bank_transfer_id) AS pay_bank_transfer_id
      FROM selected_scope
      LEFT JOIN payload_transfer
        ON payload_transfer.settlement_scope_id = selected_scope.id
      LEFT JOIN payload_item_ids
        ON payload_item_ids.settlement_scope_id = selected_scope.id
      LEFT JOIN public.pay_batch_items AS batch_item
        ON batch_item.id = payload_item_ids.pay_batch_item_id
      WHERE COALESCE(payload_transfer.pay_bank_transfer_id, batch_item.pay_bank_transfer_id) IS NOT NULL
    ), out_of_scope_updates AS (
      SELECT DISTINCT update_row.transfer_id
      FROM pg_temp.tmp_operation_rail_settlement_updates AS update_row
      WHERE NOT EXISTS (
        SELECT 1
        FROM scope_transfers
        WHERE scope_transfers.pay_bank_transfer_id = update_row.transfer_id
      )
    )
    SELECT COALESCE(jsonb_agg(to_jsonb(out_of_scope_updates.transfer_id::text) ORDER BY out_of_scope_updates.transfer_id::text), '[]'::jsonb)
    INTO v_out_of_scope_transfer_ids
    FROM out_of_scope_updates;

    IF jsonb_array_length(v_out_of_scope_transfer_ids) > 0 THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_SETTLE_RAIL_OUT_OF_SCOPE_TRANSFER_UPDATE',
        'message', 'A rail settlement update chunk contained transfer IDs that are not part of the supplied settlement scope rows.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'out_of_scope_transfer_ids', v_out_of_scope_transfer_ids
      )::text;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM pg_temp.tmp_operation_rail_settlement_updates AS update_row
      JOIN public.pay_bank_transfers AS bank_transfer
        ON bank_transfer.id = update_row.transfer_id
       AND bank_transfer.pay_batch_id = p_pay_batch_id
      WHERE update_row.status = 'COMPLETED'
        AND NOT EXISTS (
          SELECT 1
          FROM (VALUES
            (update_row.provider_reference),
            (update_row.rail_tx_id),
            (update_row.rail_meta_json #>> '{provider_reference}'),
            (update_row.rail_meta_json #>> '{provider_event_id}'),
            (update_row.rail_meta_json #>> '{provider_submission_id}'),
            (update_row.rail_meta_json #>> '{submission_id}'),
            (update_row.rail_meta_json #>> '{rail_submission_id}'),
            (update_row.rail_meta_json #>> '{provider_payment_id}'),
            (update_row.rail_meta_json #>> '{payment_id}'),
            (update_row.rail_meta_json #>> '{external_payment_id}'),
            (update_row.rail_meta_json #>> '{revolut_payment_id}'),
            (update_row.rail_meta_json #>> '{provider_transfer_id}'),
            (update_row.rail_meta_json #>> '{transfer_id}'),
            (update_row.rail_meta_json #>> '{external_transfer_id}'),
            (update_row.rail_meta_json #>> '{provider_transaction_id}'),
            (update_row.rail_meta_json #>> '{transaction_id}')
          ) AS provider_identifier(identifier_value)
          WHERE NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') IS NOT NULL
            AND NOT (
              NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') = ANY(
                ARRAY_REMOVE(ARRAY[
                  bank_transfer.id::text,
                  NULLIF(BTRIM(COALESCE(bank_transfer.request_id, '')), ''),
                  NULLIF(BTRIM(COALESCE(bank_transfer.payment_reference, '')), ''),
                  NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''),
                  NULLIF(BTRIM(COALESCE(bank_transfer.rail_meta_json #>> '{request_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(bank_transfer.rail_meta_json #>> '{idempotency_key}', '')), ''),
                  NULLIF(BTRIM(COALESCE(bank_transfer.rail_meta_json #>> '{payment_reference}', '')), ''),
                  NULLIF(BTRIM(COALESCE(bank_transfer.rail_meta_json #>> '{bulk_reference}', '')), ''),
                  NULLIF(BTRIM(COALESCE(update_row.input_json #>> '{request_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(update_row.input_json #>> '{idempotency_key}', '')), ''),
                  NULLIF(BTRIM(COALESCE(update_row.input_json #>> '{payment_reference}', '')), ''),
                  NULLIF(BTRIM(COALESCE(update_row.input_json #>> '{bulk_reference}', '')), ''),
                  NULLIF(BTRIM(COALESCE(update_row.rail_meta_json #>> '{request_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(update_row.rail_meta_json #>> '{idempotency_key}', '')), ''),
                  NULLIF(BTRIM(COALESCE(update_row.rail_meta_json #>> '{payment_reference}', '')), ''),
                  NULLIF(BTRIM(COALESCE(update_row.rail_meta_json #>> '{bulk_reference}', '')), '')
                ]::text[], NULL::text)
              )
            )
        )
      LIMIT 1
    ) THEN
      RAISE EXCEPTION 'PAY_SETTLE_RAIL_PROVIDER_EVIDENCE_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SETTLE_RAIL_PROVIDER_EVIDENCE_REQUIRED',
                'pay_batch_id', p_pay_batch_id::text,
                'operation_id', p_operation_id::text,
                'message', 'STANDARD_BANK rail settlement marked as completed requires genuine provider or bank evidence, not local request/payment references.'
              )::text;
    END IF;

    WITH settled_scope_for_event_repair AS (
      SELECT
        scope_row.id AS settlement_scope_id,
        scope_row.pay_batch_candidate_id,
        scope_row.payload_json
      FROM public.banking_pay_operation_settlement_scope AS scope_row
      JOIN pg_temp.tmp_pay_settle_rail_requested_scope_ids AS requested_scope_id
        ON requested_scope_id.settlement_scope_id = scope_row.id
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
        AND UPPER(BTRIM(COALESCE(scope_row.status, ''))) = 'SETTLED'
        AND scope_row.settlement_event_id IS NULL
        AND NOT (
          UPPER(BTRIM(COALESCE(scope_row.payload_json->>'scope_kind', ''))) = 'NO_BANK_PAYMENT'
          AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_reason', ''))) = 'EXPLICIT_ZERO_PAYE'
        )
      FOR UPDATE OF scope_row
    ), direct_scope_transfer AS (
      SELECT
        settled_scope.settlement_scope_id,
        CASE
          WHEN COALESCE(
            NULLIF(BTRIM(COALESCE(settled_scope.payload_json->>'pay_bank_transfer_id', '')), ''),
            NULLIF(BTRIM(COALESCE(settled_scope.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')), '')
          ) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN COALESCE(
              NULLIF(BTRIM(COALESCE(settled_scope.payload_json->>'pay_bank_transfer_id', '')), ''),
              NULLIF(BTRIM(COALESCE(settled_scope.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')), '')
            )::uuid
          ELSE NULL::uuid

        END AS pay_bank_transfer_id
      FROM settled_scope_for_event_repair AS settled_scope
    ), item_scope_transfer AS (
      SELECT DISTINCT
        settled_scope.settlement_scope_id,
        batch_item.pay_bank_transfer_id
      FROM settled_scope_for_event_repair AS settled_scope
      CROSS JOIN LATERAL JSONB_ARRAY_ELEMENTS(
        CASE
          WHEN JSONB_TYPEOF(settled_scope.payload_json->'pay_batch_item_ids') = 'array'
            THEN settled_scope.payload_json->'pay_batch_item_ids'
          ELSE '[]'::jsonb
        END
      ) AS item_element(value)
      JOIN public.pay_batch_items AS batch_item
        ON batch_item.id = CASE
             WHEN (item_element.value #>> '{}')
                  ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
               THEN (item_element.value #>> '{}')::uuid
             ELSE NULL::uuid
           END
       AND batch_item.pay_batch_candidate_id = settled_scope.pay_batch_candidate_id
       AND COALESCE(batch_item.is_voided, false) = false
      WHERE batch_item.pay_bank_transfer_id IS NOT NULL
    ), scope_transfer_candidate AS (
      SELECT
        direct_scope_transfer.settlement_scope_id,
        direct_scope_transfer.pay_bank_transfer_id
      FROM direct_scope_transfer
      WHERE direct_scope_transfer.pay_bank_transfer_id IS NOT NULL

      UNION

      SELECT
        item_scope_transfer.settlement_scope_id,
        item_scope_transfer.pay_bank_transfer_id
      FROM item_scope_transfer
      WHERE item_scope_transfer.pay_bank_transfer_id IS NOT NULL
    ), resolved_scope_transfer AS (
      SELECT
        scope_transfer_candidate.settlement_scope_id,
        (ARRAY_AGG(scope_transfer_candidate.pay_bank_transfer_id ORDER BY scope_transfer_candidate.pay_bank_transfer_id))[1] AS pay_bank_transfer_id
      FROM scope_transfer_candidate
      GROUP BY scope_transfer_candidate.settlement_scope_id
      HAVING COUNT(*) = 1
    ), ranked_matching_event AS (
      SELECT
        resolved_scope_transfer.settlement_scope_id,
        matching_event.id AS event_id,
        ROW_NUMBER() OVER (
          PARTITION BY resolved_scope_transfer.settlement_scope_id
          ORDER BY
            matching_event.event_time_utc DESC NULLS LAST,
            matching_event.received_at_utc DESC NULLS LAST,
            matching_event.created_at_utc DESC NULLS LAST,
            matching_event.id DESC
        ) AS event_rank
      FROM resolved_scope_transfer
      JOIN public.pay_bank_transfer_events AS matching_event
        ON matching_event.pay_batch_id = p_pay_batch_id
       AND matching_event.pay_bank_transfer_id = resolved_scope_transfer.pay_bank_transfer_id
      WHERE (
          UPPER(BTRIM(COALESCE(matching_event.normalised_state, ''))) IN ('COMPLETED', 'SETTLED', 'PAID', 'SUCCESS', 'SUCCESSFUL', 'SUCCEEDED')
          OR UPPER(BTRIM(COALESCE(matching_event.provider_state, ''))) IN ('COMPLETED', 'SETTLED', 'PAID', 'SUCCESS', 'SUCCESSFUL', 'SUCCEEDED')
        )
        AND (
          matching_event.idempotency_key LIKE
            'rail-settle:' || p_operation_id::text || ':' || resolved_scope_transfer.settlement_scope_id::text || ':' || resolved_scope_transfer.pay_bank_transfer_id::text || ':%'
          OR (
            NULLIF(BTRIM(COALESCE(matching_event.raw_payload->>'source_rpc', '')), '') = 'pay_settle_rail'
            AND NULLIF(BTRIM(COALESCE(matching_event.raw_payload->>'operation_id', '')), '') = p_operation_id::text
            AND NULLIF(BTRIM(COALESCE(matching_event.raw_payload->>'settlement_scope_id', '')), '') = resolved_scope_transfer.settlement_scope_id::text
          )
        )
    )
    UPDATE public.banking_pay_operation_settlement_scope AS scope_repair
    SET settlement_event_id = ranked_matching_event.event_id,
        updated_at_utc = v_now
    FROM ranked_matching_event
    WHERE scope_repair.id = ranked_matching_event.settlement_scope_id
      AND ranked_matching_event.event_rank = 1
      AND scope_repair.operation_id = p_operation_id
      AND scope_repair.pay_batch_id = p_pay_batch_id
      AND scope_repair.status = 'SETTLED'
      AND scope_repair.settlement_event_id IS NULL;

    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS settlement_scope_id
      FROM jsonb_array_elements(p_settlement_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), pending_scope AS (
      SELECT scope_row.*
      FROM public.banking_pay_operation_settlement_scope AS scope_row
      JOIN requested_scope
        ON requested_scope.settlement_scope_id = scope_row.id
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
        AND scope_row.status = 'PENDING'
      FOR UPDATE OF scope_row
    ), payload_transfer AS (
      SELECT pending_scope.id AS settlement_scope_id,
             CASE
               WHEN COALESCE(pending_scope.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                 THEN (pending_scope.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}')::uuid
               ELSE NULL::uuid
             END AS pay_bank_transfer_id
      FROM pending_scope
    ), payload_item_ids AS (
      SELECT pending_scope.id AS settlement_scope_id,
             (item_element.value #>> '{}')::uuid AS pay_batch_item_id
      FROM pending_scope
      CROSS JOIN LATERAL jsonb_array_elements(COALESCE(pending_scope.payload_json->'pay_batch_item_ids', '[]'::jsonb)) AS item_element(value)
      WHERE (item_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), scope_transfers AS (
      SELECT DISTINCT pending_scope.id AS settlement_scope_id,
             COALESCE(payload_transfer.pay_bank_transfer_id, batch_item.pay_bank_transfer_id) AS pay_bank_transfer_id
      FROM pending_scope
      LEFT JOIN payload_transfer
        ON payload_transfer.settlement_scope_id = pending_scope.id
      LEFT JOIN payload_item_ids
        ON payload_item_ids.settlement_scope_id = pending_scope.id
      LEFT JOIN public.pay_batch_items AS batch_item
        ON batch_item.id = payload_item_ids.pay_batch_item_id
      WHERE COALESCE(payload_transfer.pay_bank_transfer_id, batch_item.pay_bank_transfer_id) IS NOT NULL
    ), eligible_no_bank_scope AS (
      SELECT
        eligible_scope.settlement_scope_id,
        eligible_scope.pay_batch_candidate_id,
        eligible_scope.candidate_id
      FROM pg_temp.tmp_pay_settle_rail_eligible_no_bank_scope AS eligible_scope
      JOIN pending_scope
        ON pending_scope.id = eligible_scope.settlement_scope_id
    ), failed_scope_no_transfer AS (
      UPDATE public.banking_pay_operation_settlement_scope AS scope_update
      SET status = 'FAILED',
          payload_json = jsonb_strip_nulls(COALESCE(scope_update.payload_json, '{}'::jsonb) || jsonb_build_object(
            'settlement_failure_code', 'NO_PAY_BANK_TRANSFER_FOR_SCOPE',
            'settlement_failure_message', 'Rail/provider settlement scope could not be processed because it does not resolve to a frozen pay_bank_transfer row.',
            'failed_at_utc', v_now::text
          )),
          updated_at_utc = v_now
      FROM pending_scope
      WHERE scope_update.id = pending_scope.id
        AND NOT EXISTS (
          SELECT 1
          FROM scope_transfers
          WHERE scope_transfers.settlement_scope_id = pending_scope.id
        )
        AND NOT EXISTS (
          SELECT 1
          FROM eligible_no_bank_scope
          WHERE eligible_no_bank_scope.settlement_scope_id = pending_scope.id
        )
      RETURNING scope_update.id,
                scope_update.pay_batch_candidate_id
    ), matched_updates AS (
      SELECT scope_transfers.settlement_scope_id,
             scope_transfers.pay_bank_transfer_id,
             update_row.status,
             update_row.rail_tx_id,
             update_row.rail_state,
             update_row.rail_meta_json,
             update_row.provider_reference,
             update_row.provider_state,
             update_row.event_time_utc,
             update_row.input_json
      FROM scope_transfers
      JOIN pg_temp.tmp_operation_rail_settlement_updates AS update_row
        ON update_row.transfer_id = scope_transfers.pay_bank_transfer_id
    ), inserted_events AS (
      INSERT INTO public.pay_bank_transfer_events (
        pay_batch_id,
        pay_bank_transfer_id,
        candidate_id,
        umbrella_id,
        provider_key,
        provider_event_id,
        provider_reference,
        provider_state,
        normalised_state,

        event_source,
        event_time_utc,
        received_at_utc,
        amount,
        currency,
        mapping_status,
        movement_classification,
        correction_disposition,
        raw_payload,
        idempotency_key,
        mapping_method
      )
      SELECT
        p_pay_batch_id,
        matched_updates.pay_bank_transfer_id,
        bank_transfer.candidate_id,
        bank_transfer.umbrella_id,
        COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.rail_provider, '')), ''), v_batch.rail_provider_snapshot),
        CASE
          WHEN NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') IS NOT NULL
           AND NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') NOT IN (
             COALESCE(bank_transfer.id::text, '__no_transfer_id__'),
             COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.request_id, '')), ''), '__no_request_id__'),
             COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
             COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
           )
            THEN NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '')
          WHEN NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') IS NOT NULL
           AND NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') NOT IN (
             COALESCE(bank_transfer.id::text, '__no_transfer_id__'),
             COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.request_id, '')), ''), '__no_request_id__'),
             COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
             COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
           )
            THEN NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '')
          ELSE NULL::text
        END,
        COALESCE(
          CASE
            WHEN NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') IS NOT NULL
             AND NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') NOT IN (
               COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.request_id, '')), ''), '__no_request_id__'),
               COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
               COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
             )
              THEN NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '')
            ELSE NULL::text
          END,
          CASE
            WHEN NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') IS NOT NULL
             AND NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') NOT IN (
               COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.request_id, '')), ''), '__no_request_id__'),
               COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
               COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
             )
              THEN NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '')
            ELSE NULL::text
          END,
          CASE
            WHEN NULLIF(BTRIM(COALESCE(bank_transfer.rail_tx_id, '')), '') IS NOT NULL
             AND NULLIF(BTRIM(COALESCE(bank_transfer.rail_tx_id, '')), '') NOT IN (
               COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.request_id, '')), ''), '__no_request_id__'),
               COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
               COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
             )
              THEN NULLIF(BTRIM(COALESCE(bank_transfer.rail_tx_id, '')), '')
            ELSE NULL::text
          END
        ),
        CASE
          WHEN matched_updates.status = 'COMPLETED' AND ((
              NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') IS NOT NULL
              AND NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') NOT IN (
                COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.request_id, '')), ''), '__no_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
                COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
              )
            )
            OR (
              NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') IS NOT NULL
              AND NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') NOT IN (
                COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.request_id, '')), ''), '__no_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
                COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
              )
            )
            OR lower(btrim(coalesce(matched_updates.rail_meta_json #>> '{last_update_provider_evidence}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) THEN COALESCE(matched_updates.provider_state, matched_updates.rail_state, matched_updates.status)
          WHEN matched_updates.status = 'COMPLETED' THEN 'UNKNOWN'
          ELSE COALESCE(matched_updates.provider_state, matched_updates.rail_state, matched_updates.status)
        END,
        CASE
          WHEN matched_updates.status = 'COMPLETED' AND ((
              NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') IS NOT NULL
              AND NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') NOT IN (
                COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.request_id, '')), ''), '__no_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
                COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
              )
            )
            OR (
              NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') IS NOT NULL
              AND NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') NOT IN (
                COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.request_id, '')), ''), '__no_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
                COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
              )
            )
            OR lower(btrim(coalesce(matched_updates.rail_meta_json #>> '{last_update_provider_evidence}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) THEN 'COMPLETED'
          WHEN matched_updates.status = 'COMPLETED' THEN 'UNKNOWN'
          WHEN matched_updates.status IN ('FAILED', 'RETURNED', 'CANCELLED', 'PENDING', 'PROCESSING', 'UNKNOWN') THEN matched_updates.status
          ELSE 'UNKNOWN'
        END,
        'PROVIDER_POLL',
        COALESCE(matched_updates.event_time_utc, v_now),
        v_now,
        bank_transfer.amount,
        COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.currency, '')), ''), 'GBP'),
        'MATCHED',
        NULL::text,
        NULL::text,
        jsonb_strip_nulls(COALESCE(matched_updates.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
          'source_rpc', 'pay_settle_rail',
          'settlement_event_source', 'PROVIDER_SETTLEMENT',
          'operation_id', p_operation_id::text,
          'settlement_scope_id', matched_updates.settlement_scope_id::text,
          'input_json', matched_updates.input_json
        )),
        'rail-settle:' || p_operation_id::text || ':' || matched_updates.settlement_scope_id::text || ':' || matched_updates.pay_bank_transfer_id::text || ':' || md5(jsonb_strip_nulls(jsonb_build_object(
          'status', matched_updates.status,
          'rail_tx_id', matched_updates.rail_tx_id,
          'rail_state', matched_updates.rail_state,
          'provider_reference', matched_updates.provider_reference,
          'provider_state', matched_updates.provider_state,
          'rail_meta_json', COALESCE(matched_updates.rail_meta_json, '{}'::jsonb)
        ))::text),
        'TRANSFER_ID'
      FROM matched_updates
      JOIN public.pay_bank_transfers AS bank_transfer
        ON bank_transfer.id = matched_updates.pay_bank_transfer_id
       AND bank_transfer.pay_batch_id = p_pay_batch_id
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.pay_bank_transfer_events AS existing_event
        WHERE existing_event.pay_batch_id = p_pay_batch_id
          AND existing_event.idempotency_key = 'rail-settle:' || p_operation_id::text || ':' || matched_updates.settlement_scope_id::text || ':' || matched_updates.pay_bank_transfer_id::text || ':' || md5(jsonb_strip_nulls(jsonb_build_object(
            'status', matched_updates.status,
            'rail_tx_id', matched_updates.rail_tx_id,
            'rail_state', matched_updates.rail_state,
            'provider_reference', matched_updates.provider_reference,
            'provider_state', matched_updates.provider_state,
            'rail_meta_json', COALESCE(matched_updates.rail_meta_json, '{}'::jsonb)
          ))::text)
      )
      RETURNING public.pay_bank_transfer_events.id,
                public.pay_bank_transfer_events.pay_bank_transfer_id,
                public.pay_bank_transfer_events.idempotency_key
    ), transfer_updates AS (
      UPDATE public.pay_bank_transfers AS transfer_update
      SET status = CASE
            WHEN matched_updates.status = 'COMPLETED' AND ((
              NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') IS NOT NULL
              AND NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') NOT IN (
                COALESCE(transfer_update.id::text, '__no_transfer_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.request_id, '')), ''), '__no_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.payment_reference, '')), ''), '__no_payment_reference__'),
                COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
              )
            )
            OR (
              NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') IS NOT NULL
              AND NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') NOT IN (
                COALESCE(transfer_update.id::text, '__no_transfer_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.request_id, '')), ''), '__no_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.payment_reference, '')), ''), '__no_payment_reference__'),
                COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
              )
            )
            OR lower(btrim(coalesce(matched_updates.rail_meta_json #>> '{last_update_provider_evidence}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) THEN 'COMPLETED'
            WHEN matched_updates.status = 'COMPLETED' THEN 'UNKNOWN'
            WHEN matched_updates.status IN ('FAILED', 'DECLINED', 'REJECTED', 'CANCELLED', 'RETURNED', 'REVERTED') THEN matched_updates.status

            WHEN matched_updates.status = 'PROCESSING' THEN 'PROCESSING'
            WHEN matched_updates.status = 'UNKNOWN' THEN 'UNKNOWN'
            ELSE 'PENDING'
          END,
          rail_tx_id = CASE
            WHEN matched_updates.status = 'COMPLETED' AND ((
              NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') IS NOT NULL
              AND NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') NOT IN (
                COALESCE(transfer_update.id::text, '__no_transfer_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.request_id, '')), ''), '__no_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.payment_reference, '')), ''), '__no_payment_reference__'),
                COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
              )
            )
            OR (
              NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') IS NOT NULL
              AND NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') NOT IN (
                COALESCE(transfer_update.id::text, '__no_transfer_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.request_id, '')), ''), '__no_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.payment_reference, '')), ''), '__no_payment_reference__'),
                COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
              )
            )
            OR lower(btrim(coalesce(matched_updates.rail_meta_json #>> '{last_update_provider_evidence}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) THEN COALESCE(matched_updates.rail_tx_id, transfer_update.rail_tx_id)
            WHEN matched_updates.status <> 'COMPLETED' THEN COALESCE(matched_updates.rail_tx_id, transfer_update.rail_tx_id)
            ELSE transfer_update.rail_tx_id
          END,
          rail_state = COALESCE(matched_updates.rail_state, matched_updates.provider_state, transfer_update.rail_state),
          rail_meta_json = jsonb_strip_nulls(COALESCE(transfer_update.rail_meta_json, '{}'::jsonb) || COALESCE(matched_updates.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
            'provider_reference', matched_updates.provider_reference,
            'provider_state', matched_updates.provider_state,
            'settlement_operation_id', p_operation_id::text
          )),
          completed_at_utc = CASE WHEN matched_updates.status = 'COMPLETED' AND ((
              NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') IS NOT NULL
              AND NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') NOT IN (
                COALESCE(transfer_update.id::text, '__no_transfer_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.request_id, '')), ''), '__no_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.payment_reference, '')), ''), '__no_payment_reference__'),
                COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
              )
            )
            OR (
              NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') IS NOT NULL
              AND NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') NOT IN (
                COALESCE(transfer_update.id::text, '__no_transfer_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.request_id, '')), ''), '__no_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.payment_reference, '')), ''), '__no_payment_reference__'),
                COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
              )
            )
            OR lower(btrim(coalesce(matched_updates.rail_meta_json #>> '{last_update_provider_evidence}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) THEN COALESCE(transfer_update.completed_at_utc, matched_updates.event_time_utc, v_now) ELSE transfer_update.completed_at_utc END,
          failed_reason = CASE WHEN matched_updates.status IN ('FAILED', 'DECLINED', 'REJECTED', 'CANCELLED', 'RETURNED', 'REVERTED') THEN COALESCE(transfer_update.failed_reason, matched_updates.provider_state, matched_updates.rail_state, matched_updates.status) ELSE transfer_update.failed_reason END
      FROM matched_updates
      WHERE transfer_update.id = matched_updates.pay_bank_transfer_id
        AND transfer_update.pay_batch_id = p_pay_batch_id
      RETURNING transfer_update.id,
                matched_updates.settlement_scope_id,
                transfer_update.status
    ), scope_current_transfer_status AS (
      SELECT
        pending_scope.id AS settlement_scope_id,
        scope_transfers.pay_bank_transfer_id,
        COALESCE(transfer_updates.status, bank_transfer.status) AS effective_transfer_status,
        COALESCE(bank_transfer.rail_state, transfer_updates.status) AS effective_rail_state,
        COALESCE(bank_transfer.completed_at_utc, NULL::timestamptz) AS completed_at_utc,
        COALESCE(transfer_classifier.is_final_money_moved, false) AS is_final_money_moved,
        COALESCE(transfer_classifier.is_terminal_no_money, false) AS is_terminal_no_money,
        COALESCE(transfer_classifier.is_pending_non_final, false) AS is_pending_non_final
      FROM pending_scope
      JOIN scope_transfers
        ON scope_transfers.settlement_scope_id = pending_scope.id
      LEFT JOIN transfer_updates
        ON transfer_updates.settlement_scope_id = pending_scope.id
       AND transfer_updates.id = scope_transfers.pay_bank_transfer_id
      LEFT JOIN public.pay_bank_transfers AS bank_transfer
        ON bank_transfer.id = scope_transfers.pay_bank_transfer_id
       AND bank_transfer.pay_batch_id = p_pay_batch_id
      LEFT JOIN LATERAL public._pay_rail_state_money_movement_classify(
        COALESCE(transfer_updates.status, bank_transfer.status),
        COALESCE(bank_transfer.rail_state, transfer_updates.status),
        COALESCE(bank_transfer.rail_meta_json, '{}'::jsonb),
        COALESCE(bank_transfer.rail_meta_json, '{}'::jsonb)
      ) AS transfer_classifier ON bank_transfer.id IS NOT NULL
    ), scope_status AS (
      SELECT
        scope_current_transfer_status.settlement_scope_id,
        CASE
          WHEN BOOL_OR(
            scope_current_transfer_status.is_terminal_no_money
            OR upper(btrim(COALESCE(scope_current_transfer_status.effective_transfer_status, ''))) IN ('FAILED', 'FAILURE', 'DECLINED', 'REJECTED', 'CANCELLED', 'CANCELED', 'RETURNED', 'REVERTED', 'REVERSED')
            OR upper(btrim(COALESCE(scope_current_transfer_status.effective_rail_state, ''))) IN ('FAILED', 'FAILURE', 'DECLINED', 'REJECTED', 'CANCELLED', 'CANCELED', 'RETURNED', 'REVERTED', 'REVERSED')
          ) THEN 'FAILED'
          WHEN COUNT(scope_current_transfer_status.pay_bank_transfer_id) > 0
           AND BOOL_AND(
             scope_current_transfer_status.is_final_money_moved
             OR upper(btrim(COALESCE(scope_current_transfer_status.effective_transfer_status, ''))) IN ('COMPLETED', 'COMPLETE', 'PAID', 'SETTLED', 'SUCCESS', 'SUCCESSFUL', 'SUCCEEDED')
             OR upper(btrim(COALESCE(scope_current_transfer_status.effective_rail_state, ''))) IN ('COMPLETED', 'COMPLETE', 'PAID', 'SETTLED', 'SUCCESS', 'SUCCESSFUL', 'SUCCEEDED')
             OR scope_current_transfer_status.completed_at_utc IS NOT NULL
           ) THEN 'SETTLED'
          ELSE 'PENDING'
        END AS new_scope_status
      FROM scope_current_transfer_status
      GROUP BY scope_current_transfer_status.settlement_scope_id
    ), event_candidate AS (
      SELECT
        matched_updates.settlement_scope_id,
        inserted_event.id AS event_id,
        0::integer AS source_priority
      FROM matched_updates
      JOIN inserted_events AS inserted_event
        ON inserted_event.pay_bank_transfer_id = matched_updates.pay_bank_transfer_id
       AND inserted_event.idempotency_key = 'rail-settle:' || p_operation_id::text || ':' || matched_updates.settlement_scope_id::text || ':' || matched_updates.pay_bank_transfer_id::text || ':' || md5(jsonb_strip_nulls(jsonb_build_object(
          'status', matched_updates.status,
          'rail_tx_id', matched_updates.rail_tx_id,
          'rail_state', matched_updates.rail_state,
          'provider_reference', matched_updates.provider_reference,
          'provider_state', matched_updates.provider_state,
          'rail_meta_json', COALESCE(matched_updates.rail_meta_json, '{}'::jsonb)
        ))::text)

      UNION ALL

      SELECT
        matched_updates.settlement_scope_id,
        existing_event.id AS event_id,
        1::integer AS source_priority
      FROM matched_updates
      JOIN public.pay_bank_transfer_events AS existing_event
        ON existing_event.pay_batch_id = p_pay_batch_id
       AND existing_event.idempotency_key = 'rail-settle:' || p_operation_id::text || ':' || matched_updates.settlement_scope_id::text || ':' || matched_updates.pay_bank_transfer_id::text || ':' || md5(jsonb_strip_nulls(jsonb_build_object(
          'status', matched_updates.status,
          'rail_tx_id', matched_updates.rail_tx_id,
          'rail_state', matched_updates.rail_state,
          'provider_reference', matched_updates.provider_reference,
          'provider_state', matched_updates.provider_state,
          'rail_meta_json', COALESCE(matched_updates.rail_meta_json, '{}'::jsonb)
        ))::text)
    ), event_by_scope AS (
      SELECT
        event_candidate.settlement_scope_id,
        (ARRAY_AGG(event_candidate.event_id ORDER BY event_candidate.source_priority, event_candidate.event_id))[1] AS event_id
      FROM event_candidate
      GROUP BY event_candidate.settlement_scope_id
    ), scope_updates AS (
      UPDATE public.banking_pay_operation_settlement_scope AS scope_update
      SET status = scope_status.new_scope_status,
          settlement_event_id = COALESCE(event_by_scope.event_id, scope_update.settlement_event_id),
          updated_at_utc = v_now
      FROM scope_status
      LEFT JOIN event_by_scope
        ON event_by_scope.settlement_scope_id = scope_status.settlement_scope_id
      WHERE scope_update.id = scope_status.settlement_scope_id
      RETURNING scope_update.id,
                scope_update.pay_batch_candidate_id,
                scope_update.status
    ), settled_no_bank_scope AS (
      UPDATE public.banking_pay_operation_settlement_scope AS scope_update
      SET status = 'SETTLED',
          settlement_event_id = NULL::uuid,
          payload_json = JSONB_STRIP_NULLS(
            COALESCE(scope_update.payload_json, '{}'::jsonb)
            || JSONB_BUILD_OBJECT(
              'scope_kind', 'NO_BANK_PAYMENT',
              'no_bank_payment_reason', 'EXPLICIT_ZERO_PAYE',
              'no_bank_payment_scope', true,
              'server_owned_payment_projection_proof', true,
              'no_bank_payment_execution', v_no_bank_payment_execution_validated,
              'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes_marker,
              'settlement_mode', v_settlement_mode,
              'confirmation_mode', CASE
                WHEN v_no_bank_payment_execution_validated AND v_settlement_mode = 'CSV_SETTLEMENT' THEN 'NO_BANK_PAYMENT_REVIEW'
                WHEN v_no_bank_payment_execution_validated AND v_settlement_mode = 'EXTERNAL_SETTLEMENT' THEN 'NO_BANK_PAYMENT_EXTERNAL_CONFIRMATION'
                WHEN v_no_bank_payment_execution_validated THEN 'NO_BANK_PAYMENT_EXECUTION'
                ELSE 'EXPLICIT_ZERO_NO_BANK_SCOPE'
              END,
              'local_commit_reference', v_local_no_bank_commit_ref,
              'paye_net_state_hash', v_expected_paye_net_state_hash,
              'authorised_paye_net_state_hash', v_expected_paye_net_state_hash,
              'global_bank_payment_projection_hash', v_expected_global_bank_payment_projection_hash,

              'scoped_paye_net_state_hash', v_expected_scoped_paye_net_state_hash,
              'bank_payment_projection_hash', v_expected_bank_payment_projection_hash,
              'authorised_bank_payment_projection_hash', v_expected_bank_payment_projection_hash,
              'projection_scope', v_operation_projection_scope,
              'authorised_scope', v_operation_projection_scope,
              'scoped_no_transfer_execution', v_scoped_no_transfer_marker,
              'accounting_payment_date', CASE WHEN v_operation_effective_payment_date IS NULL THEN NULL ELSE v_operation_effective_payment_date::text END
            )
            || JSONB_BUILD_OBJECT(
              'execution_operation_id', v_execution_operation_id::text,
              'settlement_operation_id', p_operation_id::text,
              'auth_request_id', v_operation_auth_request_id::text,
              'authorised_execution_mode', v_authorised_execution_mode,
              'authorised_missing_explicit_paye_input_count', v_expected_missing_count,
              'authorised_explicit_zero_count', v_expected_global_zero_count,
              'authorised_global_positive_bank_payment_count', v_expected_global_positive_count,
              'authorised_global_invalid_payment_row_count', v_expected_global_invalid_count,
              'authorised_scoped_missing_explicit_paye_input_count', v_expected_scoped_missing_count,
              'authorised_scoped_explicit_zero_count', v_expected_zero_count,
              'authorised_scoped_positive_bank_payment_count', v_expected_positive_count,
              'authorised_scoped_invalid_payment_row_count', v_expected_scoped_invalid_count,
              'current_missing_explicit_paye_input_count', v_current_missing_count,
              'current_explicit_zero_count', v_global_zero_count,
              'current_global_positive_bank_payment_count', v_global_positive_count,
              'current_global_invalid_payment_row_count', v_global_invalid_count,
              'current_scoped_missing_explicit_paye_input_count', v_current_scoped_missing_count,
              'current_scoped_explicit_zero_count', v_current_zero_count,
              'current_scoped_positive_bank_payment_count', v_current_positive_count,
              'current_scoped_invalid_payment_row_count', v_current_scoped_invalid_count,
              'projection_diagnostic', v_projection_diagnostic_json,
              'suppress_remittances', v_suppress_remittances,
              'settled_at_utc', v_now::text,
              'settled_by_user_id', p_actor_user_id::text,
              'no_bank_payment_note', CASE
                WHEN v_no_bank_payment_execution_validated AND v_settlement_mode = 'CSV_SETTLEMENT'
                  THEN 'The current zero-row CloudTMS Bank CSV was reviewed; no bank upload or payment occurred or was required.'
                WHEN v_no_bank_payment_execution_validated
                  THEN 'No bank transfer or provider submission occurred or was required for this explicit-zero PAYE execution.'
                ELSE 'This explicit-zero PAYE scope required no bank transfer; positive scopes, if any, remain transfer-backed.'
              END
            )
          ),
          updated_at_utc = v_now
      FROM eligible_no_bank_scope
      WHERE scope_update.id = eligible_no_bank_scope.settlement_scope_id
      RETURNING scope_update.id,
                scope_update.pay_batch_candidate_id,
                scope_update.status
    ), processed_scope_updates AS (
      SELECT
        scope_updates.id,
        scope_updates.pay_batch_candidate_id,
        scope_updates.status,
        false AS no_bank_payment_scope
      FROM scope_updates
      UNION ALL
      SELECT
        settled_no_bank_scope.id,
        settled_no_bank_scope.pay_batch_candidate_id,
        settled_no_bank_scope.status,
        true AS no_bank_payment_scope
      FROM settled_no_bank_scope
    ), candidate_complete AS (
      SELECT DISTINCT processed_scope_updates.pay_batch_candidate_id
      FROM processed_scope_updates
      WHERE processed_scope_updates.status = 'SETTLED'
        AND processed_scope_updates.pay_batch_candidate_id IS NOT NULL
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_settlement_scope AS remaining_for_candidate
          WHERE remaining_for_candidate.operation_id = p_operation_id
            AND remaining_for_candidate.pay_batch_id = p_pay_batch_id
            AND remaining_for_candidate.pay_batch_candidate_id = processed_scope_updates.pay_batch_candidate_id
            AND remaining_for_candidate.status NOT IN ('SETTLED', 'SKIPPED')
            AND NOT EXISTS (
              SELECT 1
              FROM processed_scope_updates AS current_scope_result
              WHERE current_scope_result.id = remaining_for_candidate.id
                AND current_scope_result.status IN ('SETTLED', 'SKIPPED')
            )
        )
    ), no_bank_candidate_complete AS (
      SELECT DISTINCT settled_no_bank_scope.pay_batch_candidate_id
      FROM settled_no_bank_scope
      WHERE settled_no_bank_scope.pay_batch_candidate_id IS NOT NULL
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_settlement_scope AS remaining_for_no_bank_candidate
          WHERE remaining_for_no_bank_candidate.operation_id = p_operation_id
            AND remaining_for_no_bank_candidate.pay_batch_id = p_pay_batch_id
            AND remaining_for_no_bank_candidate.pay_batch_candidate_id = settled_no_bank_scope.pay_batch_candidate_id
            AND remaining_for_no_bank_candidate.status NOT IN ('SETTLED', 'SKIPPED')
            AND NOT EXISTS (
              SELECT 1
              FROM processed_scope_updates AS current_scope_result
              WHERE current_scope_result.id = remaining_for_no_bank_candidate.id
                AND current_scope_result.status IN ('SETTLED', 'SKIPPED')
            )
        )
    ), transfer_backed_candidate_complete AS (
      SELECT candidate_complete.pay_batch_candidate_id
      FROM candidate_complete
      WHERE EXISTS (
        SELECT 1
        FROM public.pay_batch_items AS candidate_item
        WHERE candidate_item.pay_batch_candidate_id = candidate_complete.pay_batch_candidate_id
          AND COALESCE(candidate_item.is_voided, false) = false
          AND candidate_item.pay_bank_transfer_id IS NOT NULL
      )
      OR EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_settlement_scope AS candidate_scope
        WHERE candidate_scope.operation_id = p_operation_id
          AND candidate_scope.pay_batch_id = p_pay_batch_id
          AND candidate_scope.pay_batch_candidate_id = candidate_complete.pay_batch_candidate_id
          AND candidate_scope.settlement_event_id IS NOT NULL
      )
    ), candidate_updates AS (
      UPDATE public.pay_batch_candidates AS candidate_update
      SET settlement_status = 'SETTLED',
          settled_at_utc = COALESCE(candidate_update.settled_at_utc, v_now),
          settled_via = COALESCE(NULLIF(BTRIM(COALESCE(v_batch.rail_provider_snapshot, '')), ''), 'RAIL'),
          settled_note = COALESCE(candidate_update.settled_note, 'Rail/provider settlement confirmed')
      FROM transfer_backed_candidate_complete
      WHERE candidate_update.id = transfer_backed_candidate_complete.pay_batch_candidate_id
      RETURNING candidate_update.id
    ), no_bank_candidate_updates AS (
      UPDATE public.pay_batch_candidates AS candidate_update
      SET settlement_status = 'SETTLED',
          settled_at_utc = COALESCE(candidate_update.settled_at_utc, v_now),
          settled_via = 'NO_BANK_PAYMENT',
          settled_note = COALESCE(candidate_update.settled_note, v_local_no_bank_commit_ref)
      FROM no_bank_candidate_complete
      WHERE candidate_update.id = no_bank_candidate_complete.pay_batch_candidate_id
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_batch_items AS transfer_backed_candidate_item
          WHERE transfer_backed_candidate_item.pay_batch_candidate_id = no_bank_candidate_complete.pay_batch_candidate_id
            AND COALESCE(transfer_backed_candidate_item.is_voided, false) = false
            AND transfer_backed_candidate_item.pay_bank_transfer_id IS NOT NULL
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_settlement_scope AS transfer_backed_candidate_scope
          WHERE transfer_backed_candidate_scope.operation_id = p_operation_id
            AND transfer_backed_candidate_scope.pay_batch_id = p_pay_batch_id
            AND transfer_backed_candidate_scope.pay_batch_candidate_id = no_bank_candidate_complete.pay_batch_candidate_id
            AND transfer_backed_candidate_scope.settlement_event_id IS NOT NULL
        )
      RETURNING candidate_update.id
    )
    SELECT count(*) FILTER (WHERE processed_scope_updates.status = 'SETTLED')::integer,
           COALESCE(v_failed_this_chunk, 0)
             + COALESCE((SELECT COUNT(*)::integer FROM failed_scope_no_transfer), 0)
             + count(*) FILTER (WHERE processed_scope_updates.status = 'FAILED')::integer,
           count(*) FILTER (WHERE processed_scope_updates.status = 'PENDING')::integer,
           count(*) FILTER (WHERE processed_scope_updates.no_bank_payment_scope)::integer
    INTO v_settled_this_chunk,
         v_failed_this_chunk,
         v_pending_this_chunk,
         v_no_bank_settled_this_chunk
    FROM processed_scope_updates;

    SELECT
      COUNT(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(scope_row.payload_json->>'scope_kind', ''))) = 'NO_BANK_PAYMENT'
          AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_reason', ''))) = 'EXPLICIT_ZERO_PAYE'
          AND scope_row.status <> 'SKIPPED'
      )::integer,
      COUNT(eligible_scope.settlement_scope_id)::integer
    INTO
      v_no_bank_total_scope_count,
      v_no_bank_eligible_scope_count
    FROM public.banking_pay_operation_settlement_scope AS scope_row
    LEFT JOIN pg_temp.tmp_pay_settle_rail_eligible_no_bank_scope AS eligible_scope
      ON eligible_scope.settlement_scope_id = scope_row.id
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id;

    v_no_bank_invalid_scope_count := GREATEST(

      COALESCE(v_no_bank_total_scope_count, 0) - COALESCE(v_no_bank_eligible_scope_count, 0),
      0
    );

    IF COALESCE(v_no_bank_total_scope_count, 0) > 0
       AND (
         v_no_bank_scope_authorised IS NOT TRUE
         OR COALESCE(v_no_bank_invalid_scope_count, 0) <> 0
       ) THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_RAIL',
        'code', 'NO_BANK_PAYMENT_PROOF_REQUIRED',
        'message', 'A no-bank-payment settlement scope exists without a currently valid authorised proof or contains invalid scope evidence.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'no_bank_scope_count', COALESCE(v_no_bank_total_scope_count, 0),
        'eligible_no_bank_scope_count', COALESCE(v_no_bank_eligible_scope_count, 0),
        'invalid_no_bank_scope_count', COALESCE(v_no_bank_invalid_scope_count, 0)
      )::text USING ERRCODE = 'P0001';
    END IF;

    WITH scope_summary AS (
      SELECT
        COUNT(*)::integer AS total_scope_count,
        COUNT(*) FILTER (WHERE scope_row.status IN ('SETTLED', 'SKIPPED'))::integer AS successful_scope_count,
        COUNT(*) FILTER (WHERE scope_row.status = 'FAILED')::integer AS terminal_failed_scope_count,
        COUNT(*) FILTER (WHERE scope_row.status = 'PENDING')::integer AS pending_scope_count,
        COUNT(*) FILTER (WHERE scope_row.status NOT IN ('SETTLED', 'SKIPPED', 'FAILED', 'PENDING'))::integer AS unknown_scope_count,
        COALESCE(
          JSONB_AGG(
            JSONB_BUILD_OBJECT(
              'scope_id', scope_row.id::text,
              'status', scope_row.status,
              'settlement_event_id', CASE WHEN scope_row.settlement_event_id IS NULL THEN NULL::text ELSE scope_row.settlement_event_id::text END,
              'scope_kind', scope_row.payload_json->>'scope_kind'
            )
            ORDER BY scope_row.id::text
          ),
          '[]'::jsonb
        ) AS scope_state_json
      FROM public.banking_pay_operation_settlement_scope AS scope_row
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
    ), completed_scope_transfer_ids AS (
      SELECT DISTINCT
        CASE
          WHEN COALESCE(scope_row.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')
               ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN (scope_row.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}')::uuid
          ELSE NULL::uuid
        END AS pay_bank_transfer_id
      FROM public.banking_pay_operation_settlement_scope AS scope_row
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
        AND scope_row.status = 'SETTLED'

      UNION

      SELECT DISTINCT batch_item.pay_bank_transfer_id
      FROM public.banking_pay_operation_settlement_scope AS scope_row
      CROSS JOIN LATERAL JSONB_ARRAY_ELEMENTS(
        CASE
          WHEN JSONB_TYPEOF(scope_row.payload_json->'pay_batch_item_ids') = 'array'
            THEN scope_row.payload_json->'pay_batch_item_ids'
          ELSE '[]'::jsonb
        END
      ) AS item_element(value)
      JOIN public.pay_batch_items AS batch_item
        ON batch_item.id = CASE
             WHEN (item_element.value #>> '{}')
                  ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
               THEN (item_element.value #>> '{}')::uuid
             ELSE NULL::uuid
           END
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
        AND scope_row.status = 'SETTLED'
        AND batch_item.pay_bank_transfer_id IS NOT NULL
    ), completed_transfer_summary AS (
      SELECT COUNT(DISTINCT transfer_row.id)::integer AS completed_transfer_count
      FROM completed_scope_transfer_ids AS completed_scope_transfer_id
      JOIN public.pay_bank_transfers AS transfer_row
        ON transfer_row.id = completed_scope_transfer_id.pay_bank_transfer_id
       AND transfer_row.pay_batch_id = p_pay_batch_id
      LEFT JOIN LATERAL public._pay_rail_state_money_movement_classify(
        transfer_row.status,
        transfer_row.rail_state,
        COALESCE(transfer_row.rail_meta_json, '{}'::jsonb),
        COALESCE(transfer_row.rail_meta_json, '{}'::jsonb)
      ) AS transfer_classifier ON true
      WHERE COALESCE(transfer_classifier.is_final_money_moved, false)
         OR transfer_row.completed_at_utc IS NOT NULL
         OR UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('COMPLETED', 'COMPLETE', 'COMMITTED', 'SETTLED', 'PAID', 'EXECUTED', 'SUCCESS', 'SUCCESSFUL', 'SUCCEEDED')
         OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('COMPLETED', 'COMPLETE', 'COMMITTED', 'SETTLED', 'PAID', 'EXECUTED', 'SUCCESS', 'SUCCESSFUL', 'SUCCEEDED')
    )
    SELECT
      COALESCE(scope_summary.total_scope_count, 0),
      COALESCE(scope_summary.successful_scope_count, 0),
      COALESCE(scope_summary.terminal_failed_scope_count, 0),
      COALESCE(scope_summary.pending_scope_count, 0),
      COALESCE(scope_summary.unknown_scope_count, 0),
      COALESCE(completed_transfer_summary.completed_transfer_count, 0),
      scope_summary.scope_state_json
    INTO
      v_total_scope_count,
      v_successful_scope_count,
      v_terminal_failed_scope_count,
      v_pending_scope_count,
      v_unknown_scope_count,
      v_operation_completed_transfer_count,
      v_operation_scope_state_json
    FROM scope_summary
    CROSS JOIN completed_transfer_summary;

    v_processor_failed_scope_count := 0;
    v_total_failed_scope_count := COALESCE(v_terminal_failed_scope_count, 0);
    v_remaining_scope_count := COALESCE(v_pending_scope_count, 0);
    v_has_more := COALESCE(v_pending_scope_count, 0) > 0 OR COALESCE(v_unknown_scope_count, 0) > 0;
    v_all_scopes_terminal := COALESCE(v_total_scope_count, 0) > 0
      AND COALESCE(v_pending_scope_count, 0) = 0
      AND COALESCE(v_unknown_scope_count, 0) = 0;
    v_all_scopes_successful := v_all_scopes_terminal
      AND COALESCE(v_terminal_failed_scope_count, 0) = 0
      AND COALESCE(v_successful_scope_count, 0) = COALESCE(v_total_scope_count, 0);
    v_completed_with_failed_payments := v_all_scopes_terminal
      AND COALESCE(v_terminal_failed_scope_count, 0) > 0;
    v_scope_settlement_complete := v_all_scopes_successful;
    v_requires_full_batch_finalisation := v_all_scopes_terminal;
    v_full_batch_finalisation_safe := v_all_scopes_successful
      AND COALESCE(v_no_bank_invalid_scope_count, 0) = 0
      AND COALESCE(v_no_bank_total_scope_count, 0) = COALESCE(v_expected_zero_count, 0)
      AND COALESCE(v_operation_completed_transfer_count, 0) = COALESCE(v_expected_positive_count, 0)
      AND (
        COALESCE(v_expected_positive_count, 0) > 0
        OR (
          COALESCE(v_expected_positive_count, 0) = 0
          AND COALESCE(v_expected_zero_count, 0) > 0
          AND v_no_bank_payment_execution_validated
        )
      );

    v_batch_status_label := CASE
      WHEN v_completed_with_failed_payments THEN 'Completed with failed payments'
      WHEN v_all_scopes_successful THEN 'Completed'
      WHEN COALESCE(v_pending_scope_count, 0) + COALESCE(v_unknown_scope_count, 0) > 0 THEN 'Waiting for bank confirmation'
      ELSE NULL::text
    END;

    v_finalisation_payload_hash := CASE
      WHEN v_requires_full_batch_finalisation THEN MD5(
        JSONB_STRIP_NULLS(
          JSONB_BUILD_OBJECT(
            'pay_batch_id', p_pay_batch_id::text,
            'operation_id', p_operation_id::text,
            'execution_operation_id', v_execution_operation_id::text,
            'auth_request_id', v_operation_auth_request_id::text,
            'settlement_mode', v_settlement_mode,
            'projection_scope', v_operation_projection_scope,
            'scope_state', v_operation_scope_state_json,
            'successful_scope_count', COALESCE(v_successful_scope_count, 0),
            'terminal_failed_scope_count', COALESCE(v_terminal_failed_scope_count, 0),
            'pending_scope_count', COALESCE(v_pending_scope_count, 0),
            'unknown_scope_count', COALESCE(v_unknown_scope_count, 0),
            'completed_transfer_count', COALESCE(v_operation_completed_transfer_count, 0),
            'no_bank_scope_count', COALESCE(v_no_bank_total_scope_count, 0),
            'no_bank_payment_execution', v_no_bank_payment_execution_validated,
            'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes_marker,
            'global_paye_net_state_hash', v_expected_paye_net_state_hash,
            'global_bank_payment_projection_hash', v_expected_global_bank_payment_projection_hash,
            'scoped_paye_net_state_hash', v_expected_scoped_paye_net_state_hash,
            'scoped_bank_payment_projection_hash', v_expected_bank_payment_projection_hash,
            'projection_changed_after_authorisation', v_current_projection_changed,
            'local_commit_reference', CASE WHEN v_no_bank_scope_authorised THEN v_local_no_bank_commit_ref ELSE NULL::text END
          )
        )::text
      )
      ELSE NULL::text
    END;
    v_finalisation_idempotency_key := CASE
      WHEN v_requires_full_batch_finalisation

        THEN 'rail-finalise:batch:' || p_pay_batch_id::text || ':operation:' || p_operation_id::text || ':hash:' || v_finalisation_payload_hash
      ELSE NULL::text
    END;

    UPDATE public.banking_pay_operations AS operation_update
    SET pay_batch_id = COALESCE(operation_update.pay_batch_id, p_pay_batch_id),
        progress_json = JSONB_STRIP_NULLS(
          COALESCE(operation_update.progress_json, '{}'::jsonb)
          || JSONB_BUILD_OBJECT(
            'scope_settlement_complete', v_scope_settlement_complete,
            'all_scopes_terminal', v_all_scopes_terminal,
            'all_scopes_successful', v_all_scopes_successful,
            'completed_with_failed_payments', v_completed_with_failed_payments,
            'total_scope_count', COALESCE(v_total_scope_count, 0),
            'successful_scope_count', COALESCE(v_successful_scope_count, 0),
            'terminal_failed_scope_count', COALESCE(v_terminal_failed_scope_count, 0),
            'pending_scope_count', COALESCE(v_pending_scope_count, 0),
            'unknown_scope_count', COALESCE(v_unknown_scope_count, 0),
            'completed_transfer_count', COALESCE(v_operation_completed_transfer_count, 0),
            'no_bank_scope_count', COALESCE(v_no_bank_total_scope_count, 0),
            'requires_full_batch_finalisation', v_requires_full_batch_finalisation,
            'full_batch_finalisation_safe', v_full_batch_finalisation_safe,
            'finalisation_idempotency_key', v_finalisation_idempotency_key,
            'finalisation_payload_hash', v_finalisation_payload_hash,
            'projection_changed_after_authorisation', v_current_projection_changed,
            'projection_diagnostic', v_projection_diagnostic_json,
            'scope_settlement_updated_at_utc', v_now::text
          )
        ),
        updated_at_utc = v_now
    WHERE operation_update.id = p_operation_id;

    v_live_signal_result := public.banking_pay_batch_signal_touch(
      p_pay_batch_id := p_pay_batch_id,
      p_change_reason := 'PAY_SETTLE_RAIL_OPERATION_CHUNK',
      p_change_source := 'pay_settle_rail',
      p_change_scope_json := jsonb_strip_nulls(jsonb_build_object(
        'operation_id', p_operation_id::text,
        'settlement_scope_ids', COALESCE(p_settlement_scope_ids, '[]'::jsonb),
        'settled_this_chunk', COALESCE(v_settled_this_chunk, 0),
        'reused_this_chunk', COALESCE(v_reused_this_chunk, 0),
        'failed_this_chunk', COALESCE(v_failed_this_chunk, 0),
        'pending_this_chunk', COALESCE(v_pending_this_chunk, 0),
        'remaining', COALESCE(v_remaining_scope_count, 0),
        'scope_settlement_complete', v_scope_settlement_complete,
        'successful_scope_count', COALESCE(v_successful_scope_count, 0),
        'terminal_failed_scope_count', COALESCE(v_terminal_failed_scope_count, 0),
        'pending_scope_count', COALESCE(v_pending_scope_count, 0),
        'unknown_scope_count', COALESCE(v_unknown_scope_count, 0),
        'processor_failed_scope_count', COALESCE(v_processor_failed_scope_count, 0),
        'all_scopes_terminal', v_all_scopes_terminal,
        'all_scopes_successful', v_all_scopes_successful,
        'completed_with_failed_payments', v_completed_with_failed_payments,
        'batch_status_label', v_batch_status_label,
        'completed_transfer_count', COALESCE(v_operation_completed_transfer_count, 0),
        'no_bank_scopes_settled_this_chunk', COALESCE(v_no_bank_settled_this_chunk, 0),
        'no_bank_scope_count', COALESCE(v_no_bank_total_scope_count, 0),
        'no_bank_payment_execution', v_no_bank_payment_execution_validated,
        'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes_marker,
        'proposed_local_commit_reference', CASE WHEN v_no_bank_scope_authorised THEN v_local_no_bank_commit_ref ELSE NULL::text END,
        'requires_full_batch_finalisation', v_requires_full_batch_finalisation,
        'full_batch_finalisation_safe', v_full_batch_finalisation_safe,
        'finalisation_idempotency_key', v_finalisation_idempotency_key,
        'finalisation_payload_hash', v_finalisation_payload_hash,
        'consumed_carry_forward_count', COALESCE(v_consumed_carry_forward_count, 0)
      )),
      p_touch_payment_status := true,
      p_touch_correction_progress := true,
      p_touch_alerts := false,
      p_touch_overview := true
    );

    RETURN JSONB_BUILD_OBJECT(
      'ok', true,
      'operation_mode', true,
      'operation_id', p_operation_id::text,
      'settlement_operation_id', p_operation_id::text,
      'execution_operation_id', v_execution_operation_id::text,
      'auth_request_id', v_operation_auth_request_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'settlement_mode', v_settlement_mode,
      'projection_scope', v_operation_projection_scope,
      'settled_this_chunk', COALESCE(v_settled_this_chunk, 0),
      'reused_this_chunk', COALESCE(v_reused_this_chunk, 0),
      'failed_this_chunk', COALESCE(v_failed_this_chunk, 0),
      'pending_this_chunk', COALESCE(v_pending_this_chunk, 0),
      'no_bank_scopes_settled_this_chunk', COALESCE(v_no_bank_settled_this_chunk, 0),
      'remaining', COALESCE(v_remaining_scope_count, 0),
      'has_more', v_has_more,
      'scope_settlement_complete', v_scope_settlement_complete,
      'all_scopes_terminal', v_all_scopes_terminal,
      'all_scopes_successful', v_all_scopes_successful,
      'completed_with_failed_payments', v_completed_with_failed_payments,
      'batch_status_label', v_batch_status_label,
      'total_scope_count', COALESCE(v_total_scope_count, 0),
      'successful_scope_count', COALESCE(v_successful_scope_count, 0),
      'terminal_failed_scope_count', COALESCE(v_terminal_failed_scope_count, 0),
      'pending_scope_count', COALESCE(v_pending_scope_count, 0),
      'unknown_scope_count', COALESCE(v_unknown_scope_count, 0),
      'processor_failed_scope_count', COALESCE(v_processor_failed_scope_count, 0),
      'failed_scope_count', COALESCE(v_total_failed_scope_count, 0),
      'completed_transfer_count', COALESCE(v_operation_completed_transfer_count, 0),
      'no_bank_scope_count', COALESCE(v_no_bank_total_scope_count, 0),
      'eligible_no_bank_scope_count', COALESCE(v_no_bank_eligible_scope_count, 0),
      'invalid_no_bank_scope_count', COALESCE(v_no_bank_invalid_scope_count, 0)
    )
    || JSONB_BUILD_OBJECT(
      'server_owned_payment_projection_proof', true,
      'proof_validation_outcome', v_proof_validation_outcome,
      'no_bank_payment_execution', v_no_bank_payment_execution_validated,
      'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes_marker,
      'authorised_paye_net_state_hash', v_expected_paye_net_state_hash,
      'current_paye_net_state_hash', v_current_paye_net_state_hash,
      'authorised_bank_payment_projection_hash', v_expected_bank_payment_projection_hash,
      'current_bank_payment_projection_hash', v_current_bank_payment_projection_hash,
      'authorised_missing_explicit_paye_input_count', v_expected_missing_count,
      'current_missing_explicit_paye_input_count', v_current_missing_count,
      'authorised_explicit_zero_count', v_expected_global_zero_count,
      'current_explicit_zero_count', v_global_zero_count,
      'authorised_scoped_explicit_zero_count', v_expected_zero_count,
      'current_scoped_explicit_zero_count', v_current_zero_count,
      'authorised_scoped_positive_bank_payment_count', v_expected_positive_count,
      'current_scoped_positive_bank_payment_count', v_current_positive_count,
      'proposed_local_commit_reference', CASE WHEN v_no_bank_scope_authorised THEN v_local_no_bank_commit_ref ELSE NULL::text END,
      'projection_changed_after_authorisation', v_current_projection_changed,
      'projection_diagnostic', v_projection_diagnostic_json,
      'execution_commit_state', v_execution_commit_state,
      'execution_commit_ref', v_execution_commit_ref,
      'execution_committed_at_utc', CASE WHEN v_execution_committed_at_utc IS NULL THEN NULL::text ELSE v_execution_committed_at_utc::text END,
      'remittance_ready', v_full_batch_finalisation_safe,
      'requires_full_batch_finalisation', v_requires_full_batch_finalisation,
      'full_batch_finalisation_safe', v_full_batch_finalisation_safe,
      'finalisation_idempotency_key', v_finalisation_idempotency_key,
      'finalisation_payload_hash', v_finalisation_payload_hash,
      'remittance_queued', false,
      'consumed_carry_forward_count', COALESCE(v_consumed_carry_forward_count, 0),
      'carry_forward_mark_consumed_result', COALESCE(v_carry_forward_mark_result, '{}'::jsonb),
      'live_signal', COALESCE(v_live_signal_result, '{}'::jsonb),
      'freshness', JSONB_BUILD_OBJECT(
        'freshness_validation_status', NULLIF(v_stored_freshness_status, ''),
        'freshness_result_hash', v_stored_freshness_result_hash,
        'freshness_scope_hash', v_stored_freshness_scope_hash,
        'freshness_operation_id', CASE WHEN v_stored_freshness_operation_id IS NULL THEN NULL::text ELSE v_stored_freshness_operation_id::text END,
        'source', 'stored_freshness_metadata_non_blocking'
      ),
      'message', 'Rail settlement scope chunk processed; durable batch finalisation remains the responsibility of full-batch pay_settle_rail.'
    );
  END IF;

  SELECT CASE
    WHEN JSONB_TYPEOF(pb.execution_intent_json) = 'object'
      THEN COALESCE(pb.execution_intent_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END
  INTO v_batch_intent_json
  FROM public.pay_batches AS pb
  WHERE pb.id = p_pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_settle_rail: pay_batch not found';
  END IF;

  IF v_batch_intent_json = '{}'::jsonb THEN
    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
      'error', 'PAY_SETTLE_RAIL',
      'code', 'BATCH_EXECUTION_INTENT_REQUIRED',
      'message', 'Full-batch settlement requires the server-frozen batch execution intent.',
      'pay_batch_id', p_pay_batch_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'operation_id', '')), '')
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_execution_operation_id := (v_batch_intent_json->>'operation_id')::uuid;
    v_batch_intent_operation_id := v_execution_operation_id;
    v_execution_operation_resolved_from_batch_intent := true;
  END IF;

  IF v_execution_operation_id IS NULL THEN
    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(

      'error', 'PAY_SETTLE_RAIL',
      'code', 'EXECUTION_OPERATION_REQUIRED',
      'message', 'Full-batch settlement cannot determine the authorised payment execution operation.',
      'pay_batch_id', p_pay_batch_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  SELECT execution_operation.*
  INTO v_execution_operation_row
  FROM public.banking_pay_operations AS execution_operation
  WHERE execution_operation.id = v_execution_operation_id
  FOR UPDATE;

  IF NOT FOUND
     OR v_execution_operation_row.pay_batch_id IS DISTINCT FROM p_pay_batch_id
     OR v_execution_operation_row.operation_type NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
      'error', 'PAY_SETTLE_RAIL',
      'code', 'EXECUTION_OPERATION_INVALID',
      'message', 'The batch execution intent points to a missing or incompatible payment execution operation.',
      'pay_batch_id', p_pay_batch_id::text,
      'execution_operation_id', v_execution_operation_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  select
    pb.id,
    pb.status,
    pb.pay_date,
    pb.authoritative_payment_date,
    pb.authoritative_payment_date_source,
    pb.rail_provider_snapshot,
    pb.rail_env_snapshot,
    pb.bulk_reference,
    pb.batch_kind_fixed,
    pb.execution_intent_json,
    pb.settlement_confirmation_json,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc,
    pb.freshness_validation_status,
    pb.freshness_result_hash,
    pb.freshness_scope_hash,
    pb.freshness_result_json,
    pb.freshness_operation_id
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  for update;

  if v_batch.id is null then
    raise exception 'pay_settle_rail: pay_batch not found';
  end if;

  v_stored_freshness_status := upper(btrim(coalesce(v_batch.freshness_validation_status, '')));
  v_stored_freshness_result_hash := nullif(btrim(coalesce(v_batch.freshness_result_hash, '')), '');
  v_stored_freshness_scope_hash := nullif(btrim(coalesce(v_batch.freshness_scope_hash, '')), '');
  v_stored_freshness_result_json := coalesce(v_batch.freshness_result_json, '{}'::jsonb);
  v_stored_freshness_operation_id := v_batch.freshness_operation_id;

  v_batch_intent_json := CASE
    WHEN JSONB_TYPEOF(v_batch.execution_intent_json) = 'object'
      THEN COALESCE(v_batch.execution_intent_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_execution_intent_json := v_batch_intent_json;

  IF v_execution_operation_resolved_from_batch_intent
     AND (
       CASE
         WHEN NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'operation_id', '')), '')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           THEN (v_batch_intent_json->>'operation_id')::uuid
         ELSE NULL::uuid
       END
     ) IS DISTINCT FROM v_execution_operation_id THEN
    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
      'error', 'PAY_SETTLE_RAIL',
      'code', 'EXECUTION_OPERATION_BINDING_CHANGED',
      'message', 'The batch execution-operation binding changed while full-batch settlement was acquiring its canonical locks.',
      'pay_batch_id', p_pay_batch_id::text,
      'locked_execution_operation_id', v_execution_operation_id::text,
      'current_batch_execution_operation_id', NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'operation_id', '')), '')
    )::text USING ERRCODE = 'P0001';
  END IF;

  v_root_operation_input_json := COALESCE(v_execution_operation_row.input_json, '{}'::jsonb);

  IF NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'auth_request_id', '')), '')
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_operation_auth_request_id := (v_batch_intent_json->>'auth_request_id')::uuid;
  END IF;

  IF v_operation_auth_request_id IS NULL THEN
    SELECT COUNT(*)::integer
    INTO v_auth_request_candidate_count
    FROM public.pay_batch_auth_requests AS auth_request_candidate
    WHERE auth_request_candidate.pay_batch_id = p_pay_batch_id
      AND UPPER(BTRIM(COALESCE(auth_request_candidate.state, ''))) = 'AUTHORISED'
      AND JSONB_TYPEOF(auth_request_candidate.execution_intent_json) = 'object'
      AND NULLIF(BTRIM(COALESCE(auth_request_candidate.execution_intent_json->>'operation_id', '')), '') = v_execution_operation_id::text;

    IF COALESCE(v_auth_request_candidate_count, 0) = 1 THEN
      SELECT auth_request_candidate.id
      INTO v_operation_auth_request_id
      FROM public.pay_batch_auth_requests AS auth_request_candidate
      WHERE auth_request_candidate.pay_batch_id = p_pay_batch_id
        AND UPPER(BTRIM(COALESCE(auth_request_candidate.state, ''))) = 'AUTHORISED'
        AND JSONB_TYPEOF(auth_request_candidate.execution_intent_json) = 'object'
        AND NULLIF(BTRIM(COALESCE(auth_request_candidate.execution_intent_json->>'operation_id', '')), '') = v_execution_operation_id::text;
    ELSE
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_RAIL',
        'code', 'AUTHORISED_EXECUTION_INTENT_REQUIRED',
        'message', 'Full-batch settlement requires exactly one authorised auth request bound to the execution operation.',
        'pay_batch_id', p_pay_batch_id::text,
        'execution_operation_id', v_execution_operation_id::text,
        'authorised_auth_request_count', COALESCE(v_auth_request_candidate_count, 0)
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;

  SELECT
    auth_request.state,
    CASE
      WHEN JSONB_TYPEOF(auth_request.execution_intent_json) = 'object'
        THEN COALESCE(auth_request.execution_intent_json, '{}'::jsonb)
      ELSE '{}'::jsonb
    END
  INTO
    v_operation_auth_state,
    v_operation_auth_intent_json
  FROM public.pay_batch_auth_requests AS auth_request
  WHERE auth_request.id = v_operation_auth_request_id
    AND auth_request.pay_batch_id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND
     OR UPPER(BTRIM(COALESCE(v_operation_auth_state, ''))) <> 'AUTHORISED'
     OR JSONB_TYPEOF(v_operation_auth_intent_json) <> 'object'
     OR v_operation_auth_intent_json = '{}'::jsonb THEN
    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
      'error', 'PAY_SETTLE_RAIL',
      'code', 'AUTHORISED_EXECUTION_INTENT_REQUIRED',
      'message', 'The payment auth request is missing, belongs to another batch, is not authorised, or has no execution intent.',
      'pay_batch_id', p_pay_batch_id::text,
      'execution_operation_id', v_execution_operation_id::text,
      'auth_request_id', CASE WHEN v_operation_auth_request_id IS NULL THEN NULL::text ELSE v_operation_auth_request_id::text END,
      'auth_state', v_operation_auth_state
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_operation_auth_intent_json->>'operation_id', '')), '')
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_auth_intent_operation_id := (v_operation_auth_intent_json->>'operation_id')::uuid;
  END IF;
  IF NULLIF(BTRIM(COALESCE(v_operation_auth_intent_json->>'auth_request_id', '')), '')
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_auth_intent_auth_request_id := (v_operation_auth_intent_json->>'auth_request_id')::uuid;
  END IF;
  IF NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'auth_request_id', '')), '')
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_batch_intent_auth_request_id := (v_batch_intent_json->>'auth_request_id')::uuid;
  END IF;

  v_authorised_execution_mode := CASE
    WHEN UPPER(BTRIM(COALESCE(v_operation_auth_intent_json->>'execution_mode', ''))) IN ('STANDARD_BANK', 'BANK') THEN 'STANDARD_BANK'
    WHEN UPPER(BTRIM(COALESCE(v_operation_auth_intent_json->>'execution_mode', ''))) IN ('CSV', 'CSV_SETTLEMENT') THEN 'CSV_SETTLEMENT'
    WHEN UPPER(BTRIM(COALESCE(v_operation_auth_intent_json->>'execution_mode', ''))) IN ('EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'EXTERNAL_SETTLEMENT'
    ELSE UPPER(NULLIF(BTRIM(COALESCE(v_operation_auth_intent_json->>'execution_mode', '')), ''))
  END;
  v_batch_execution_mode := CASE
    WHEN UPPER(BTRIM(COALESCE(v_batch_intent_json->>'execution_mode', ''))) IN ('STANDARD_BANK', 'BANK') THEN 'STANDARD_BANK'
    WHEN UPPER(BTRIM(COALESCE(v_batch_intent_json->>'execution_mode', ''))) IN ('CSV', 'CSV_SETTLEMENT') THEN 'CSV_SETTLEMENT'
    WHEN UPPER(BTRIM(COALESCE(v_batch_intent_json->>'execution_mode', ''))) IN ('EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'EXTERNAL_SETTLEMENT'
    ELSE UPPER(NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'execution_mode', '')), ''))
  END;
  v_operation_projection_scope := UPPER(NULLIF(BTRIM(COALESCE(
    v_operation_auth_intent_json->>'pay_channel_scope',
    v_operation_auth_intent_json->>'scope',

    ''
  )), ''));
  v_batch_projection_scope := UPPER(NULLIF(BTRIM(COALESCE(
    v_batch_intent_json->>'pay_channel_scope',
    v_batch_intent_json->>'scope',
    ''
  )), ''));

  v_expected_paye_net_state_hash := NULLIF(BTRIM(COALESCE(
    v_operation_auth_intent_json->>'global_paye_net_state_hash',
    v_operation_auth_intent_json->>'paye_net_state_hash',
    ''
  )), '');
  v_batch_expected_paye_net_state_hash := NULLIF(BTRIM(COALESCE(
    v_batch_intent_json->>'global_paye_net_state_hash',
    v_batch_intent_json->>'paye_net_state_hash',
    ''
  )), '');
  v_expected_global_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(
    v_operation_auth_intent_json->>'global_bank_payment_projection_hash',
    ''
  )), '');
  v_batch_expected_global_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(
    v_batch_intent_json->>'global_bank_payment_projection_hash',
    ''
  )), '');
  v_expected_scoped_paye_net_state_hash := NULLIF(BTRIM(COALESCE(
    v_operation_auth_intent_json->>'scoped_paye_net_state_hash',
    ''
  )), '');
  v_batch_expected_scoped_paye_net_state_hash := NULLIF(BTRIM(COALESCE(
    v_batch_intent_json->>'scoped_paye_net_state_hash',
    ''
  )), '');
  v_expected_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(
    v_operation_auth_intent_json->>'scoped_bank_payment_projection_hash',
    v_operation_auth_intent_json->>'bank_payment_projection_hash',
    ''
  )), '');
  v_batch_expected_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(
    v_batch_intent_json->>'scoped_bank_payment_projection_hash',
    v_batch_intent_json->>'bank_payment_projection_hash',
    ''
  )), '');

  IF COALESCE(v_operation_auth_intent_json->>'global_missing_explicit_paye_input_count', v_operation_auth_intent_json->>'missing_explicit_paye_input_count', '') ~ '^[0-9]+$' THEN
    v_expected_missing_count := COALESCE(v_operation_auth_intent_json->>'global_missing_explicit_paye_input_count', v_operation_auth_intent_json->>'missing_explicit_paye_input_count')::integer;
  END IF;
  IF COALESCE(v_batch_intent_json->>'global_missing_explicit_paye_input_count', v_batch_intent_json->>'missing_explicit_paye_input_count', '') ~ '^[0-9]+$' THEN
    v_batch_expected_missing_count := COALESCE(v_batch_intent_json->>'global_missing_explicit_paye_input_count', v_batch_intent_json->>'missing_explicit_paye_input_count')::integer;
  END IF;
  IF COALESCE(v_operation_auth_intent_json->>'global_explicit_zero_count', v_operation_auth_intent_json->>'explicit_zero_count', '') ~ '^[0-9]+$' THEN
    v_expected_global_zero_count := COALESCE(v_operation_auth_intent_json->>'global_explicit_zero_count', v_operation_auth_intent_json->>'explicit_zero_count')::integer;
  END IF;
  IF COALESCE(v_batch_intent_json->>'global_explicit_zero_count', v_batch_intent_json->>'explicit_zero_count', '') ~ '^[0-9]+$' THEN
    v_batch_expected_global_zero_count := COALESCE(v_batch_intent_json->>'global_explicit_zero_count', v_batch_intent_json->>'explicit_zero_count')::integer;
  END IF;
  IF COALESCE(v_operation_auth_intent_json->>'global_positive_bank_payment_count', '') ~ '^[0-9]+$' THEN
    v_expected_global_positive_count := (v_operation_auth_intent_json->>'global_positive_bank_payment_count')::integer;
  END IF;
  IF COALESCE(v_batch_intent_json->>'global_positive_bank_payment_count', '') ~ '^[0-9]+$' THEN
    v_batch_expected_global_positive_count := (v_batch_intent_json->>'global_positive_bank_payment_count')::integer;
  END IF;
  IF COALESCE(v_operation_auth_intent_json->>'global_invalid_payment_row_count', '') ~ '^[0-9]+$' THEN
    v_expected_global_invalid_count := (v_operation_auth_intent_json->>'global_invalid_payment_row_count')::integer;
  END IF;
  IF COALESCE(v_batch_intent_json->>'global_invalid_payment_row_count', '') ~ '^[0-9]+$' THEN
    v_batch_expected_global_invalid_count := (v_batch_intent_json->>'global_invalid_payment_row_count')::integer;
  END IF;
  IF COALESCE(v_operation_auth_intent_json->>'scoped_missing_explicit_paye_input_count', '') ~ '^[0-9]+$' THEN
    v_expected_scoped_missing_count := (v_operation_auth_intent_json->>'scoped_missing_explicit_paye_input_count')::integer;
  END IF;
  IF COALESCE(v_batch_intent_json->>'scoped_missing_explicit_paye_input_count', '') ~ '^[0-9]+$' THEN
    v_batch_expected_scoped_missing_count := (v_batch_intent_json->>'scoped_missing_explicit_paye_input_count')::integer;
  END IF;
  IF COALESCE(v_operation_auth_intent_json->>'scoped_explicit_zero_count', '') ~ '^[0-9]+$' THEN
    v_expected_zero_count := (v_operation_auth_intent_json->>'scoped_explicit_zero_count')::integer;
  END IF;
  IF COALESCE(v_batch_intent_json->>'scoped_explicit_zero_count', '') ~ '^[0-9]+$' THEN
    v_batch_expected_zero_count := (v_batch_intent_json->>'scoped_explicit_zero_count')::integer;
  END IF;
  IF COALESCE(v_operation_auth_intent_json->>'scoped_positive_bank_payment_count', v_operation_auth_intent_json->>'positive_bank_payment_count', '') ~ '^[0-9]+$' THEN
    v_expected_positive_count := COALESCE(v_operation_auth_intent_json->>'scoped_positive_bank_payment_count', v_operation_auth_intent_json->>'positive_bank_payment_count')::integer;
  END IF;
  IF COALESCE(v_batch_intent_json->>'scoped_positive_bank_payment_count', v_batch_intent_json->>'positive_bank_payment_count', '') ~ '^[0-9]+$' THEN
    v_batch_expected_positive_count := COALESCE(v_batch_intent_json->>'scoped_positive_bank_payment_count', v_batch_intent_json->>'positive_bank_payment_count')::integer;
  END IF;
  IF COALESCE(v_operation_auth_intent_json->>'scoped_invalid_payment_row_count', '') ~ '^[0-9]+$' THEN
    v_expected_scoped_invalid_count := (v_operation_auth_intent_json->>'scoped_invalid_payment_row_count')::integer;
  END IF;
  IF COALESCE(v_batch_intent_json->>'scoped_invalid_payment_row_count', '') ~ '^[0-9]+$' THEN
    v_batch_expected_scoped_invalid_count := (v_batch_intent_json->>'scoped_invalid_payment_row_count')::integer;
  END IF;

  v_server_owned_projection_proof := LOWER(BTRIM(COALESCE(v_operation_auth_intent_json->>'server_owned_payment_projection_proof', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_batch_server_owned_projection_proof := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'server_owned_payment_projection_proof', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_scoped_no_transfer_marker := LOWER(BTRIM(COALESCE(v_operation_auth_intent_json->>'scoped_no_transfer_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_batch_scoped_no_transfer_marker := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'scoped_no_transfer_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_no_bank_payment_marker := LOWER(BTRIM(COALESCE(v_operation_auth_intent_json->>'no_bank_payment_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_batch_no_bank_payment_marker := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'no_bank_payment_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_allow_explicit_zero_no_bank_scopes_marker := LOWER(BTRIM(COALESCE(v_operation_auth_intent_json->>'allow_explicit_zero_no_bank_scopes', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_batch_allow_explicit_zero_no_bank_scopes_marker := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'allow_explicit_zero_no_bank_scopes', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_suppress_remittances := LOWER(BTRIM(COALESCE(v_operation_auth_intent_json->>'suppress_remittances', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_batch_suppress_remittances := LOWER(BTRIM(COALESCE(v_batch_intent_json->>'suppress_remittances', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_authorised_payment_date_raw := NULLIF(BTRIM(COALESCE(v_operation_auth_intent_json->>'payment_date', '')), '');
  v_batch_authorised_payment_date_raw := NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'payment_date', '')), '');
  IF v_authorised_payment_date_raw IS NOT NULL THEN
    BEGIN
      v_authorised_payment_date := v_authorised_payment_date_raw::date;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'PAY_SETTLE_RAIL_AUTH_INTENT_PAYMENT_DATE_INVALID' USING ERRCODE = 'P0001';
    END;
  END IF;
  IF v_batch_authorised_payment_date_raw IS NOT NULL THEN
    BEGIN
      v_batch_authorised_payment_date := v_batch_authorised_payment_date_raw::date;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'PAY_SETTLE_RAIL_BATCH_INTENT_PAYMENT_DATE_INVALID' USING ERRCODE = 'P0001';
    END;
  END IF;

  IF v_auth_intent_operation_id IS NULL
     OR v_batch_intent_operation_id IS NULL
     OR v_auth_intent_operation_id <> v_execution_operation_id
     OR v_batch_intent_operation_id <> v_execution_operation_id
     OR v_auth_intent_auth_request_id IS DISTINCT FROM v_operation_auth_request_id
     OR v_batch_intent_auth_request_id IS DISTINCT FROM v_operation_auth_request_id
     OR v_authorised_execution_mode NOT IN ('STANDARD_BANK', 'CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT')
     OR v_authorised_execution_mode IS DISTINCT FROM v_batch_execution_mode
     OR v_operation_projection_scope NOT IN ('ALL', 'PAYE', 'UMBRELLA', 'LOANS')
     OR v_operation_projection_scope IS DISTINCT FROM v_batch_projection_scope
     OR v_expected_paye_net_state_hash IS NULL
     OR v_expected_paye_net_state_hash IS DISTINCT FROM v_batch_expected_paye_net_state_hash
     OR v_expected_global_bank_payment_projection_hash IS NULL
     OR v_expected_global_bank_payment_projection_hash IS DISTINCT FROM v_batch_expected_global_bank_payment_projection_hash
     OR v_expected_scoped_paye_net_state_hash IS NULL
     OR v_expected_scoped_paye_net_state_hash IS DISTINCT FROM v_batch_expected_scoped_paye_net_state_hash
     OR v_expected_bank_payment_projection_hash IS NULL
     OR v_expected_bank_payment_projection_hash IS DISTINCT FROM v_batch_expected_bank_payment_projection_hash
     OR v_expected_missing_count IS NULL
     OR v_expected_missing_count IS DISTINCT FROM v_batch_expected_missing_count
     OR v_expected_global_zero_count IS NULL
     OR v_expected_global_zero_count IS DISTINCT FROM v_batch_expected_global_zero_count
     OR v_expected_global_positive_count IS NULL
     OR v_expected_global_positive_count IS DISTINCT FROM v_batch_expected_global_positive_count
     OR v_expected_global_invalid_count IS NULL
     OR v_expected_global_invalid_count IS DISTINCT FROM v_batch_expected_global_invalid_count
     OR v_expected_scoped_missing_count IS NULL
     OR v_expected_scoped_missing_count IS DISTINCT FROM v_batch_expected_scoped_missing_count
     OR v_expected_zero_count IS NULL
     OR v_expected_zero_count IS DISTINCT FROM v_batch_expected_zero_count
     OR v_expected_positive_count IS NULL
     OR v_expected_positive_count IS DISTINCT FROM v_batch_expected_positive_count
     OR v_expected_scoped_invalid_count IS NULL
     OR v_expected_scoped_invalid_count IS DISTINCT FROM v_batch_expected_scoped_invalid_count
     OR v_server_owned_projection_proof IS NOT TRUE
     OR v_batch_server_owned_projection_proof IS NOT TRUE
     OR v_scoped_no_transfer_marker IS DISTINCT FROM v_batch_scoped_no_transfer_marker
     OR v_no_bank_payment_marker IS DISTINCT FROM v_batch_no_bank_payment_marker
     OR v_allow_explicit_zero_no_bank_scopes_marker IS DISTINCT FROM v_batch_allow_explicit_zero_no_bank_scopes_marker
     OR v_suppress_remittances IS DISTINCT FROM v_batch_suppress_remittances
     OR v_authorised_payment_date IS DISTINCT FROM v_batch_authorised_payment_date THEN
    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
      'error', 'PAY_SETTLE_RAIL',
      'code', 'AUTH_BATCH_EXECUTION_INTENT_MISMATCH',
      'message', 'The authorised execution intent and batch execution intent are missing required server proof or are materially inconsistent.',
      'pay_batch_id', p_pay_batch_id::text,
      'execution_operation_id', v_execution_operation_id::text,
      'auth_request_id', v_operation_auth_request_id::text,
      'authorised_execution_mode', v_authorised_execution_mode,
      'authorised_scope', v_operation_projection_scope
    )::text USING ERRCODE = 'P0001';
  END IF;

  v_settlement_mode := v_authorised_execution_mode;
  v_effective_payment_date := COALESCE(
    v_authorised_payment_date,
    v_batch.authoritative_payment_date,
    v_batch.pay_date

  );
  v_execution_commit_state := UPPER(BTRIM(COALESCE(v_batch.execution_commit_state, 'NOT_SUBMITTED')));
  IF v_execution_commit_state NOT IN ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') THEN
    v_execution_commit_state := 'NOT_SUBMITTED';
  END IF;
  v_execution_commit_ref := v_batch.execution_commit_ref;
  v_execution_committed_at_utc := v_batch.execution_committed_at_utc;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_settle_rail_projection_rows;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_settle_rail_projection_rows
  ON COMMIT DROP
  AS
  SELECT projection_row.*
  FROM public._pay_batch_bank_payment_projection_rows(p_pay_batch_id, 'ALL') AS projection_row;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_settle_rail_scoped_projection_rows;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_settle_rail_scoped_projection_rows
  ON COMMIT DROP
  AS
  SELECT projection_row.*
  FROM public._pay_batch_bank_payment_projection_rows(p_pay_batch_id, v_operation_projection_scope) AS projection_row;

  SELECT
    COUNT(*) FILTER (WHERE projection_row.is_paye_net_state_row AND projection_row.paye_net_classification = 'MISSING')::integer,
    COUNT(*) FILTER (WHERE projection_row.is_paye_net_state_row AND projection_row.paye_net_classification = 'ZERO')::integer,
    COUNT(*) FILTER (WHERE projection_row.is_positive_bank_payment)::integer,
    COUNT(*) FILTER (
      WHERE (
        projection_row.paye_net_required IS TRUE
        AND COALESCE(projection_row.paye_net_classification, '') NOT IN ('MISSING', 'ZERO', 'POSITIVE')
      )
      OR (
        COALESCE(projection_row.paye_net_required, false) IS FALSE
        AND (
          projection_row.final_frozen_bank_amount IS NULL
          OR ROUND(projection_row.final_frozen_bank_amount, 2) <= 0
        )
      )
    )::integer,
    MAX(projection_row.paye_net_state_hash),
    MAX(projection_row.bank_payment_projection_hash)
  INTO
    v_current_missing_count,
    v_global_zero_count,
    v_global_positive_count,
    v_global_invalid_count,
    v_current_paye_net_state_hash,
    v_all_bank_payment_projection_hash
  FROM pg_temp.tmp_pay_settle_rail_projection_rows AS projection_row;

  SELECT
    COUNT(*) FILTER (WHERE projection_row.is_paye_net_state_row AND projection_row.paye_net_classification = 'MISSING')::integer,
    COUNT(*) FILTER (WHERE projection_row.is_paye_net_state_row AND projection_row.paye_net_classification = 'ZERO')::integer,
    COUNT(*) FILTER (WHERE projection_row.is_positive_bank_payment)::integer,
    ROUND(COALESCE(SUM(projection_row.amount) FILTER (WHERE projection_row.is_positive_bank_payment), 0), 2)::numeric(14,2),
    COUNT(*) FILTER (
      WHERE (
        projection_row.paye_net_required IS TRUE
        AND COALESCE(projection_row.paye_net_classification, '') NOT IN ('MISSING', 'ZERO', 'POSITIVE')
      )
      OR (
        COALESCE(projection_row.paye_net_required, false) IS FALSE
        AND (
          projection_row.final_frozen_bank_amount IS NULL
          OR ROUND(projection_row.final_frozen_bank_amount, 2) <= 0
        )
      )
    )::integer,
    MAX(projection_row.paye_net_state_hash),
    MAX(projection_row.bank_payment_projection_hash)
  INTO
    v_current_scoped_missing_count,
    v_current_zero_count,
    v_current_positive_count,
    v_current_positive_total,
    v_current_scoped_invalid_count,
    v_current_scoped_paye_net_state_hash,
    v_current_bank_payment_projection_hash
  FROM pg_temp.tmp_pay_settle_rail_scoped_projection_rows AS projection_row;

  v_current_missing_count := COALESCE(v_current_missing_count, 0);
  v_global_zero_count := COALESCE(v_global_zero_count, 0);
  v_global_positive_count := COALESCE(v_global_positive_count, 0);
  v_global_invalid_count := COALESCE(v_global_invalid_count, 0);
  v_current_scoped_missing_count := COALESCE(v_current_scoped_missing_count, 0);
  v_current_zero_count := COALESCE(v_current_zero_count, 0);
  v_current_positive_count := COALESCE(v_current_positive_count, 0);
  v_current_positive_total := ROUND(COALESCE(v_current_positive_total, 0), 2);
  v_current_scoped_invalid_count := COALESCE(v_current_scoped_invalid_count, 0);
  v_current_paye_net_state_hash := COALESCE(v_current_paye_net_state_hash, MD5(JSONB_BUILD_OBJECT('pay_batch_id', p_pay_batch_id::text, 'scope', 'ALL', 'rows', '[]'::jsonb)::text));
  v_all_bank_payment_projection_hash := COALESCE(v_all_bank_payment_projection_hash, MD5(JSONB_BUILD_OBJECT('pay_batch_id', p_pay_batch_id::text, 'scope', 'ALL', 'rows', '[]'::jsonb)::text));
  v_current_scoped_paye_net_state_hash := COALESCE(v_current_scoped_paye_net_state_hash, MD5(JSONB_BUILD_OBJECT('pay_batch_id', p_pay_batch_id::text, 'scope', v_operation_projection_scope, 'rows', '[]'::jsonb)::text));
  v_current_bank_payment_projection_hash := COALESCE(v_current_bank_payment_projection_hash, MD5(JSONB_BUILD_OBJECT('pay_batch_id', p_pay_batch_id::text, 'scope', v_operation_projection_scope, 'rows', '[]'::jsonb)::text));

  v_current_projection_changed := (
    v_expected_paye_net_state_hash IS DISTINCT FROM v_current_paye_net_state_hash
    OR v_expected_global_bank_payment_projection_hash IS DISTINCT FROM v_all_bank_payment_projection_hash
    OR v_expected_scoped_paye_net_state_hash IS DISTINCT FROM v_current_scoped_paye_net_state_hash
    OR v_expected_bank_payment_projection_hash IS DISTINCT FROM v_current_bank_payment_projection_hash
    OR v_expected_missing_count IS DISTINCT FROM v_current_missing_count
    OR v_expected_global_zero_count IS DISTINCT FROM v_global_zero_count
    OR v_expected_global_positive_count IS DISTINCT FROM v_global_positive_count
    OR v_expected_global_invalid_count IS DISTINCT FROM v_global_invalid_count
    OR v_expected_scoped_missing_count IS DISTINCT FROM v_current_scoped_missing_count
    OR v_expected_zero_count IS DISTINCT FROM v_current_zero_count
    OR v_expected_positive_count IS DISTINCT FROM v_current_positive_count
    OR v_expected_scoped_invalid_count IS DISTINCT FROM v_current_scoped_invalid_count
  );

  v_projection_diagnostic_json := JSONB_BUILD_OBJECT(
    'projection_changed_after_authorisation', v_current_projection_changed,
    'settlement_blocked_by_projection_change', false,
    'authorised_global_paye_net_state_hash', v_expected_paye_net_state_hash,
    'current_global_paye_net_state_hash', v_current_paye_net_state_hash,
    'authorised_global_bank_payment_projection_hash', v_expected_global_bank_payment_projection_hash,
    'current_global_bank_payment_projection_hash', v_all_bank_payment_projection_hash,
    'authorised_scoped_paye_net_state_hash', v_expected_scoped_paye_net_state_hash,
    'current_scoped_paye_net_state_hash', v_current_scoped_paye_net_state_hash,
    'authorised_scoped_bank_payment_projection_hash', v_expected_bank_payment_projection_hash,
    'current_scoped_bank_payment_projection_hash', v_current_bank_payment_projection_hash,
    'authorised_scope', v_operation_projection_scope,
    'diagnostic_generated_at_utc', v_now::text
  );

  v_no_bank_scope_authorised := v_allow_explicit_zero_no_bank_scopes_marker
    AND COALESCE(v_expected_missing_count, -1) = 0
    AND COALESCE(v_expected_scoped_missing_count, -1) = 0
    AND COALESCE(v_expected_zero_count, 0) > 0
    AND COALESCE(v_expected_scoped_invalid_count, -1) = 0;
  v_no_bank_payment_execution_validated := v_no_bank_payment_marker
    AND v_scoped_no_transfer_marker
    AND v_no_bank_scope_authorised
    AND COALESCE(v_expected_positive_count, -1) = 0
    AND COALESCE(v_expected_global_positive_count, -1) = 0
    AND COALESCE(v_expected_global_invalid_count, -1) = 0;
  v_local_no_bank_commit_ref := 'NO_BANK_PAYMENT:' || v_operation_auth_request_id::text;
  v_proof_validation_outcome := CASE
    WHEN v_no_bank_payment_execution_validated THEN 'VALIDATED_NO_BANK_PAYMENT_FROM_AUTHORISED_INTENT'
    WHEN v_no_bank_scope_authorised AND COALESCE(v_expected_positive_count, 0) > 0 THEN 'VALIDATED_MIXED_ZERO_AND_TRANSFER_FROM_AUTHORISED_INTENT'
    WHEN v_no_bank_scope_authorised THEN 'VALIDATED_SCOPED_NO_TRANSFER_FROM_AUTHORISED_INTENT'
    ELSE 'VALIDATED_TRANSFER_BACKED_FROM_AUTHORISED_INTENT'
  END;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_settle_rail_full_eligible_no_bank_scope;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_settle_rail_full_eligible_no_bank_scope (
    settlement_scope_id uuid PRIMARY KEY,
    pay_batch_candidate_id uuid NOT NULL,
    candidate_id uuid NOT NULL
  ) ON COMMIT DROP;

  IF v_no_bank_scope_authorised THEN
    IF v_execution_operation_row.operation_type <> 'PAYMENT_EXECUTE' THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_RAIL',
        'code', 'NO_BANK_PAYMENT_EXECUTION_OPERATION_REQUIRED',
        'message', 'Explicit-zero no-bank finalisation must remain bound to the original PAYMENT_EXECUTE operation and cannot be introduced by a blocked-funds retry.',
        'pay_batch_id', p_pay_batch_id::text,
        'execution_operation_id', v_execution_operation_id::text,
        'execution_operation_type', v_execution_operation_row.operation_type
      )::text USING ERRCODE = 'P0001';
    END IF;

    v_explicit_settlement_operation_id := NULL::uuid;
    IF NULLIF(BTRIM(COALESCE(
      v_batch_intent_json->>'settlement_operation_id',
      v_operation_auth_intent_json->>'settlement_operation_id',
      v_batch.settlement_confirmation_json->>'settlement_operation_id',
      v_batch.settlement_confirmation_json->>'operation_id',
      ''
    )), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_explicit_settlement_operation_id := COALESCE(
        v_batch_intent_json->>'settlement_operation_id',
        v_operation_auth_intent_json->>'settlement_operation_id',
        v_batch.settlement_confirmation_json->>'settlement_operation_id',
        v_batch.settlement_confirmation_json->>'operation_id'
      )::uuid;
    END IF;

    DROP TABLE IF EXISTS pg_temp.tmp_pay_settle_rail_no_bank_operation_ids;
    CREATE TEMPORARY TABLE pg_temp.tmp_pay_settle_rail_no_bank_operation_ids (

      operation_id uuid PRIMARY KEY
    ) ON COMMIT DROP;

    IF v_explicit_settlement_operation_id IS NOT NULL THEN
      INSERT INTO pg_temp.tmp_pay_settle_rail_no_bank_operation_ids (operation_id)
      SELECT settlement_operation.id
      FROM public.banking_pay_operations AS settlement_operation
      WHERE settlement_operation.id = v_explicit_settlement_operation_id
        AND settlement_operation.pay_batch_id = p_pay_batch_id
        AND (
          (
            settlement_operation.operation_type = 'PAYMENT_EXECUTE'
            AND settlement_operation.id = v_execution_operation_id
          )
          OR (
            settlement_operation.operation_type = 'PAYMENT_SETTLEMENT'
            AND (
              settlement_operation.root_operation_id = v_execution_operation_id
              OR (
                settlement_operation.root_operation_id IS NULL
                AND EXISTS (
                  SELECT 1
                  FROM public.banking_pay_operation_settlement_scope AS explicit_scope_binding
                  WHERE explicit_scope_binding.operation_id = settlement_operation.id
                    AND explicit_scope_binding.pay_batch_id = p_pay_batch_id
                    AND NULLIF(BTRIM(COALESCE(explicit_scope_binding.payload_json->>'execution_operation_id', '')), '') = v_execution_operation_id::text
                    AND NULLIF(BTRIM(COALESCE(explicit_scope_binding.payload_json->>'auth_request_id', '')), '') = v_operation_auth_request_id::text
                )
              )
            )
          )
        )
      ON CONFLICT (operation_id) DO NOTHING;

      IF NOT EXISTS (
        SELECT 1
        FROM pg_temp.tmp_pay_settle_rail_no_bank_operation_ids AS explicit_operation
        WHERE explicit_operation.operation_id = v_explicit_settlement_operation_id
      ) THEN
        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
          'error', 'PAY_SETTLE_RAIL',
          'code', 'NO_BANK_PAYMENT_SETTLEMENT_OPERATION_MISMATCH',
          'message', 'The stored settlement-operation locator is not compatible with the authorised execution intent.',
          'pay_batch_id', p_pay_batch_id::text,
          'execution_operation_id', v_execution_operation_id::text,
          'settlement_operation_id', v_explicit_settlement_operation_id::text
        )::text USING ERRCODE = 'P0001';
      END IF;
    END IF;

    INSERT INTO pg_temp.tmp_pay_settle_rail_no_bank_operation_ids (operation_id)
    SELECT DISTINCT no_bank_operation.id
    FROM public.banking_pay_operation_settlement_scope AS no_bank_scope
    JOIN public.banking_pay_operations AS no_bank_operation
      ON no_bank_operation.id = no_bank_scope.operation_id
     AND no_bank_operation.pay_batch_id = p_pay_batch_id
    WHERE no_bank_scope.pay_batch_id = p_pay_batch_id
      AND no_bank_scope.status = 'SETTLED'
      AND UPPER(BTRIM(COALESCE(no_bank_scope.payload_json->>'scope_kind', ''))) = 'NO_BANK_PAYMENT'
      AND UPPER(BTRIM(COALESCE(no_bank_scope.payload_json->>'no_bank_payment_reason', ''))) = 'EXPLICIT_ZERO_PAYE'
      AND NULLIF(BTRIM(COALESCE(no_bank_scope.payload_json->>'execution_operation_id', '')), '') = v_execution_operation_id::text
      AND NULLIF(BTRIM(COALESCE(no_bank_scope.payload_json->>'auth_request_id', '')), '') = v_operation_auth_request_id::text
      AND (
        (
          no_bank_operation.operation_type = 'PAYMENT_EXECUTE'
          AND no_bank_operation.id = v_execution_operation_id
        )
        OR (
          no_bank_operation.operation_type = 'PAYMENT_SETTLEMENT'
          AND (
            no_bank_operation.root_operation_id = v_execution_operation_id
            OR no_bank_operation.root_operation_id IS NULL
          )
        )
      )
    ON CONFLICT (operation_id) DO NOTHING;

    SELECT COUNT(*)::integer
    INTO v_no_bank_settlement_operation_count
    FROM pg_temp.tmp_pay_settle_rail_no_bank_operation_ids AS candidate_operation;

    IF COALESCE(v_no_bank_settlement_operation_count, 0) <> 1 THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_RAIL',
        'code', 'NO_BANK_PAYMENT_SETTLEMENT_OPERATION_REQUIRED',
        'message', 'Full no-bank finalisation requires exactly one settlement operation bound to the authorised execution proof.',
        'pay_batch_id', p_pay_batch_id::text,
        'execution_operation_id', v_execution_operation_id::text,
        'auth_request_id', v_operation_auth_request_id::text,
        'compatible_settlement_operation_count', COALESCE(v_no_bank_settlement_operation_count, 0)
      )::text USING ERRCODE = 'P0001';
    END IF;

    SELECT candidate_operation.operation_id
    INTO v_no_bank_settlement_operation_id
    FROM pg_temp.tmp_pay_settle_rail_no_bank_operation_ids AS candidate_operation;

    DROP TABLE IF EXISTS pg_temp.tmp_pay_settle_rail_full_eligible_no_bank_scope;
    CREATE TEMPORARY TABLE pg_temp.tmp_pay_settle_rail_full_eligible_no_bank_scope
    ON COMMIT DROP
    AS
    SELECT DISTINCT
      scope_row.id AS settlement_scope_id,
      scope_row.pay_batch_candidate_id,
      scope_row.candidate_id
    FROM public.banking_pay_operation_settlement_scope AS scope_row
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = scope_row.pay_batch_candidate_id
     AND batch_candidate.pay_batch_id = p_pay_batch_id
    WHERE scope_row.operation_id = v_no_bank_settlement_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id
      AND scope_row.status = 'SETTLED'
      AND scope_row.settlement_event_id IS NULL
      AND UPPER(BTRIM(COALESCE(scope_row.pay_channel, ''))) = 'PAYE'
      AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'pay_batch_id', '')), '') = p_pay_batch_id::text
      AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'pay_batch_candidate_id', '')), '') = scope_row.pay_batch_candidate_id::text
      AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'candidate_id', '')), '') = scope_row.candidate_id::text
      AND UPPER(NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'pay_channel', '')), '')) = 'PAYE'
      AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'pay_bank_transfer_id', '')), '') IS NULL
      AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'scope_kind', ''))) = 'NO_BANK_PAYMENT'
      AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_reason', ''))) = 'EXPLICIT_ZERO_PAYE'
      AND LOWER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_scope', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(scope_row.payload_json->>'server_owned_payment_projection_proof', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND UPPER(BTRIM(COALESCE(scope_row.payload_json #>> '{payment_scope_json,scope_kind}', ''))) = 'NO_BANK_PAYMENT'
      AND UPPER(BTRIM(COALESCE(scope_row.payload_json #>> '{payment_scope_json,no_bank_payment_reason}', ''))) = 'EXPLICIT_ZERO_PAYE'
      AND NULLIF(BTRIM(COALESCE(scope_row.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')), '') IS NULL
      AND LOWER(BTRIM(COALESCE(scope_row.payload_json->>'has_effective_paye_input', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND COALESCE(scope_row.payload_json->>'net_bank_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
      AND ROUND((scope_row.payload_json->>'net_bank_amount')::numeric, 2) = 0
      AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'effective_paye_net_input_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'authorised_paye_net_state_hash', scope_row.payload_json->>'paye_net_state_hash', '')), '') = v_expected_paye_net_state_hash
      AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'global_bank_payment_projection_hash', '')), '') = v_expected_global_bank_payment_projection_hash
      AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'scoped_paye_net_state_hash', '')), '') = v_expected_scoped_paye_net_state_hash
      AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'authorised_bank_payment_projection_hash', scope_row.payload_json->>'bank_payment_projection_hash', '')), '') = v_expected_bank_payment_projection_hash
      AND UPPER(NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'projection_scope', '')), '')) IS NOT DISTINCT FROM v_operation_projection_scope
      AND UPPER(NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'authorised_scope', scope_row.payload_json->>'projection_scope', '')), '')) IS NOT DISTINCT FROM v_operation_projection_scope
      AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'execution_operation_id', '')), '') = v_execution_operation_id::text
      AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'settlement_operation_id', '')), '') = v_no_bank_settlement_operation_id::text
      AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'auth_request_id', '')), '') = v_operation_auth_request_id::text
      AND UPPER(NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'authorised_execution_mode', '')), '')) IS NOT DISTINCT FROM v_authorised_execution_mode
      AND (
        NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'settlement_mode', '')), '') IS NULL
        OR UPPER(NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'settlement_mode', '')), '')) = v_settlement_mode
      )
      AND (LOWER(BTRIM(COALESCE(scope_row.payload_json->>'scoped_no_transfer_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) = v_scoped_no_transfer_marker
      AND (LOWER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) = v_no_bank_payment_marker
      AND (LOWER(BTRIM(COALESCE(scope_row.payload_json->>'allow_explicit_zero_no_bank_scopes', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) = v_allow_explicit_zero_no_bank_scopes_marker
      AND (LOWER(BTRIM(COALESCE(scope_row.payload_json->>'suppress_remittances', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) = v_suppress_remittances
      AND COALESCE(scope_row.payload_json->>'authorised_missing_explicit_paye_input_count', '') ~ '^[0-9]+$'
      AND (scope_row.payload_json->>'authorised_missing_explicit_paye_input_count')::integer = v_expected_missing_count
      AND COALESCE(scope_row.payload_json->>'authorised_explicit_zero_count', '') ~ '^[0-9]+$'
      AND (scope_row.payload_json->>'authorised_explicit_zero_count')::integer = v_expected_global_zero_count
      AND COALESCE(scope_row.payload_json->>'authorised_global_positive_bank_payment_count', '') ~ '^[0-9]+$'
      AND (scope_row.payload_json->>'authorised_global_positive_bank_payment_count')::integer = v_expected_global_positive_count
      AND COALESCE(scope_row.payload_json->>'authorised_global_invalid_payment_row_count', '') ~ '^[0-9]+$'
      AND (scope_row.payload_json->>'authorised_global_invalid_payment_row_count')::integer = v_expected_global_invalid_count
      AND COALESCE(scope_row.payload_json->>'authorised_scoped_missing_explicit_paye_input_count', '') ~ '^[0-9]+$'
      AND (scope_row.payload_json->>'authorised_scoped_missing_explicit_paye_input_count')::integer = v_expected_scoped_missing_count
      AND COALESCE(scope_row.payload_json->>'authorised_scoped_explicit_zero_count', '') ~ '^[0-9]+$'
      AND (scope_row.payload_json->>'authorised_scoped_explicit_zero_count')::integer = v_expected_zero_count
      AND COALESCE(scope_row.payload_json->>'authorised_scoped_positive_bank_payment_count', '') ~ '^[0-9]+$'
      AND (scope_row.payload_json->>'authorised_scoped_positive_bank_payment_count')::integer = v_expected_positive_count
      AND COALESCE(scope_row.payload_json->>'authorised_scoped_invalid_payment_row_count', '') ~ '^[0-9]+$'
      AND (scope_row.payload_json->>'authorised_scoped_invalid_payment_row_count')::integer = v_expected_scoped_invalid_count
      AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'local_commit_reference', '')), '') = v_local_no_bank_commit_ref
      AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'settled_at_utc', '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'settled_by_user_id', '')), '') IS NOT NULL
      AND (
        (
          v_no_bank_payment_execution_validated
          AND v_settlement_mode = 'CSV_SETTLEMENT'
          AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'confirmation_mode', ''))) = 'NO_BANK_PAYMENT_REVIEW'
        )
        OR (
          v_no_bank_payment_execution_validated
          AND v_settlement_mode = 'EXTERNAL_SETTLEMENT'
          AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'confirmation_mode', ''))) IN ('NO_BANK_PAYMENT_EXTERNAL_CONFIRMATION', 'NO_BANK_PAYMENT_EXECUTION')
        )
        OR (
          v_no_bank_payment_execution_validated

          AND v_settlement_mode = 'STANDARD_BANK'
          AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'confirmation_mode', ''))) = 'NO_BANK_PAYMENT_EXECUTION'
        )
        OR (
          v_no_bank_payment_execution_validated IS NOT TRUE
          AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'confirmation_mode', ''))) = 'EXPLICIT_ZERO_NO_BANK_SCOPE'
        )
      )
      AND JSONB_TYPEOF(scope_row.payload_json->'pay_batch_item_ids') = 'array'
      AND JSONB_ARRAY_LENGTH(scope_row.payload_json->'pay_batch_item_ids') > 0
      AND COALESCE(scope_row.payload_json->>'item_count', '') ~ '^[0-9]+$'
      AND (scope_row.payload_json->>'item_count')::integer = JSONB_ARRAY_LENGTH(scope_row.payload_json->'pay_batch_item_ids')
      AND NOT EXISTS (
        SELECT 1
        FROM JSONB_ARRAY_ELEMENTS_TEXT(scope_row.payload_json->'pay_batch_item_ids') AS item_element(item_id_text)
        WHERE item_element.item_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           OR NOT EXISTS (
             SELECT 1
             FROM public.pay_batch_items AS payload_item
             WHERE payload_item.id = CASE
                     WHEN item_element.item_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                       THEN item_element.item_id_text::uuid
                     ELSE NULL::uuid
                   END
               AND payload_item.pay_batch_candidate_id = scope_row.pay_batch_candidate_id
               AND UPPER(BTRIM(COALESCE(payload_item.pay_channel, ''))) = 'PAYE'
               AND COALESCE(payload_item.is_voided, false) = false
               AND COALESCE(payload_item.item_type, '') <> 'DEBT_CREATED'
               AND payload_item.pay_bank_transfer_id IS NULL
           )
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_batch_items AS candidate_scope_item
        WHERE candidate_scope_item.pay_batch_candidate_id = scope_row.pay_batch_candidate_id
          AND UPPER(BTRIM(COALESCE(candidate_scope_item.pay_channel, ''))) = 'PAYE'
          AND COALESCE(candidate_scope_item.is_voided, false) = false
          AND COALESCE(candidate_scope_item.item_type, '') <> 'DEBT_CREATED'
          AND NOT (scope_row.payload_json->'pay_batch_item_ids' @> JSONB_BUILD_ARRAY(TO_JSONB(candidate_scope_item.id::text)))
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_batch_items AS linked_item
        WHERE linked_item.pay_batch_candidate_id = scope_row.pay_batch_candidate_id
          AND UPPER(BTRIM(COALESCE(linked_item.pay_channel, ''))) = 'PAYE'
          AND COALESCE(linked_item.is_voided, false) = false
          AND linked_item.pay_bank_transfer_id IS NOT NULL
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_transfer_scope AS transfer_scope_evidence
        WHERE transfer_scope_evidence.pay_batch_id = p_pay_batch_id
          AND (
            transfer_scope_evidence.candidate_id = scope_row.candidate_id
            OR transfer_scope_evidence.candidate_id IS NULL
          )
          AND UPPER(BTRIM(COALESCE(transfer_scope_evidence.pay_channel, ''))) = 'PAYE'
          AND (
            transfer_scope_evidence.pay_bank_transfer_id IS NOT NULL
            OR transfer_scope_evidence.provider_submit_attempt_count > 0
            OR transfer_scope_evidence.provider_request_sent_at_utc IS NOT NULL
            OR NULLIF(BTRIM(COALESCE(transfer_scope_evidence.provider_request_id, '')), '') IS NOT NULL
            OR NULLIF(BTRIM(COALESCE(transfer_scope_evidence.provider_transaction_id, '')), '') IS NOT NULL
          )
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_bank_transfers AS transfer_evidence
        WHERE transfer_evidence.pay_batch_id = p_pay_batch_id
          AND (
            transfer_evidence.candidate_id = scope_row.candidate_id
            OR transfer_evidence.candidate_id IS NULL
          )
          AND UPPER(BTRIM(COALESCE(transfer_evidence.pay_channel, ''))) = 'PAYE'
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_bank_transfer_events AS transfer_event_evidence
        LEFT JOIN public.pay_bank_transfers AS event_transfer_evidence
          ON event_transfer_evidence.id = transfer_event_evidence.pay_bank_transfer_id
        WHERE transfer_event_evidence.pay_batch_id = p_pay_batch_id
          AND (
            COALESCE(transfer_event_evidence.candidate_id, event_transfer_evidence.candidate_id) = scope_row.candidate_id
            OR (
              transfer_event_evidence.candidate_id IS NULL
              AND transfer_event_evidence.pay_bank_transfer_id IS NULL
            )
          )
          AND (
            transfer_event_evidence.pay_bank_transfer_id IS NULL
            OR UPPER(BTRIM(COALESCE(event_transfer_evidence.pay_channel, ''))) = 'PAYE'
          )
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_provider_attempts AS provider_attempt_evidence
        LEFT JOIN public.banking_pay_operation_transfer_scope AS provider_attempt_scope
          ON provider_attempt_scope.id = provider_attempt_evidence.transfer_scope_id
        WHERE (
            provider_attempt_evidence.pay_batch_id = p_pay_batch_id
            OR provider_attempt_scope.pay_batch_id = p_pay_batch_id
          )
          AND (
            (
              provider_attempt_scope.candidate_id = scope_row.candidate_id
              AND UPPER(BTRIM(COALESCE(provider_attempt_scope.pay_channel, ''))) = 'PAYE'
            )
            OR (
              provider_attempt_evidence.transfer_scope_id IS NULL
              AND (
                provider_attempt_evidence.operation_id = v_execution_operation_id
                OR provider_attempt_evidence.pay_batch_id = p_pay_batch_id
              )
            )
          )
      );


    SELECT
      COUNT(*)::integer,
      COUNT(DISTINCT scope_row.pay_batch_candidate_id)::integer,
      COUNT(*) FILTER (WHERE scope_row.status NOT IN ('SETTLED', 'SKIPPED'))::integer,
      COUNT(*) FILTER (WHERE scope_row.status = 'FAILED')::integer
    INTO
      v_no_bank_total_scope_count,
      v_no_bank_distinct_candidate_count,
      v_no_bank_nonterminal_scope_count,
      v_no_bank_failed_scope_count
    FROM public.banking_pay_operation_settlement_scope AS scope_row
    WHERE scope_row.operation_id = v_no_bank_settlement_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id
      AND scope_row.status <> 'SKIPPED'
      AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'scope_kind', ''))) = 'NO_BANK_PAYMENT'
      AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_reason', ''))) = 'EXPLICIT_ZERO_PAYE';

    SELECT COUNT(*)::integer
    INTO v_no_bank_eligible_scope_count
    FROM pg_temp.tmp_pay_settle_rail_full_eligible_no_bank_scope AS eligible_scope;

    v_no_bank_invalid_scope_count := GREATEST(
      COALESCE(v_no_bank_total_scope_count, 0) - COALESCE(v_no_bank_eligible_scope_count, 0),
      0
    );

    v_no_bank_missing_scope_count := GREATEST(
      COALESCE(v_expected_zero_count, 0) - COALESCE(v_no_bank_distinct_candidate_count, 0),
      0
    );

    IF COALESCE(v_no_bank_invalid_scope_count, 0) <> 0
       OR COALESCE(v_no_bank_missing_scope_count, 0) <> 0
       OR COALESCE(v_no_bank_nonterminal_scope_count, 0) <> 0
       OR COALESCE(v_no_bank_failed_scope_count, 0) <> 0
       OR COALESCE(v_no_bank_total_scope_count, 0) <> COALESCE(v_expected_zero_count, 0)
       OR COALESCE(v_no_bank_distinct_candidate_count, 0) <> COALESCE(v_expected_zero_count, 0) THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_RAIL',
        'code', 'NO_BANK_PAYMENT_SCOPE_EVIDENCE_INVALID',
        'message', 'The locally settled explicit-zero scopes are invalid, incomplete, duplicated, non-terminal, or no longer match the frozen zero-payment proof.',
        'pay_batch_id', p_pay_batch_id::text,
        'execution_operation_id', v_execution_operation_id::text,
        'settlement_operation_id', v_no_bank_settlement_operation_id::text,
        'expected_zero_candidate_count', COALESCE(v_expected_zero_count, 0),
        'settled_no_bank_scope_count', COALESCE(v_no_bank_total_scope_count, 0),
        'eligible_no_bank_scope_count', COALESCE(v_no_bank_eligible_scope_count, 0),
        'distinct_no_bank_candidate_count', COALESCE(v_no_bank_distinct_candidate_count, 0),
        'missing_no_bank_scope_count', COALESCE(v_no_bank_missing_scope_count, 0),
        'nonterminal_no_bank_scope_count', COALESCE(v_no_bank_nonterminal_scope_count, 0),
        'failed_no_bank_scope_count', COALESCE(v_no_bank_failed_scope_count, 0),
        'invalid_no_bank_scope_count', COALESCE(v_no_bank_invalid_scope_count, 0)
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF COALESCE(v_expected_positive_count, 0) > 0 THEN
      SELECT
        COUNT(*)::integer,
        COUNT(*) FILTER (WHERE scope_row.status NOT IN ('SETTLED', 'SKIPPED'))::integer,
        COUNT(*) FILTER (WHERE scope_row.status = 'FAILED')::integer
      INTO
        v_positive_scope_count,

        v_positive_nonterminal_scope_count,
        v_positive_failed_scope_count
      FROM public.banking_pay_operation_settlement_scope AS scope_row
      WHERE scope_row.operation_id = v_no_bank_settlement_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
        AND NOT (
          UPPER(BTRIM(COALESCE(scope_row.payload_json->>'scope_kind', ''))) = 'NO_BANK_PAYMENT'
          AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_reason', ''))) = 'EXPLICIT_ZERO_PAYE'
        );

      IF COALESCE(v_positive_scope_count, 0) = 0
         OR COALESCE(v_positive_nonterminal_scope_count, 0) <> 0
         OR COALESCE(v_positive_failed_scope_count, 0) <> 0 THEN
        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
          'error', 'PAY_SETTLE_RAIL',
          'code', 'MIXED_SETTLEMENT_SCOPE_FINALISATION_INCOMPLETE',
          'message', 'Mixed positive/zero finalisation cannot continue until every transfer-backed scope is terminal and successful.',
          'pay_batch_id', p_pay_batch_id::text,
          'settlement_operation_id', v_no_bank_settlement_operation_id::text,
          'positive_scope_count', COALESCE(v_positive_scope_count, 0),
          'positive_nonterminal_scope_count', COALESCE(v_positive_nonterminal_scope_count, 0),
          'positive_failed_scope_count', COALESCE(v_positive_failed_scope_count, 0)
        )::text USING ERRCODE = 'P0001';
      END IF;
    END IF;

    IF v_no_bank_payment_execution_validated THEN
      IF JSONB_ARRAY_LENGTH(p_settlement_json) <> 0 THEN
        RAISE EXCEPTION 'PAY_SETTLE_RAIL_NO_BANK_PAYMENT_PAYLOAD_FORBIDDEN'
          USING ERRCODE = 'P0001',
                DETAIL = JSONB_BUILD_OBJECT(
                  'code', 'PAY_SETTLE_RAIL_NO_BANK_PAYMENT_PAYLOAD_FORBIDDEN',
                  'pay_batch_id', p_pay_batch_id::text,
                  'execution_operation_id', v_execution_operation_id::text,
                  'auth_request_id', v_operation_auth_request_id::text,
                  'message', 'Pure no-bank-payment full finalisation requires an empty settlement payload and cannot ingest transfer or provider evidence.'
                )::text;
      END IF;

      SELECT COUNT(*)::integer
      INTO v_no_bank_scope_artifact_count
      FROM public.banking_pay_operation_transfer_scope AS transfer_scope_row
      WHERE transfer_scope_row.operation_id = v_execution_operation_id
        AND transfer_scope_row.pay_batch_id = p_pay_batch_id;

      SELECT COUNT(*)::integer
      INTO v_no_bank_batch_transfer_count
      FROM public.pay_bank_transfers AS transfer_row
      WHERE transfer_row.pay_batch_id = p_pay_batch_id;

      SELECT COUNT(*)::integer
      INTO v_no_bank_transfer_event_count
      FROM public.pay_bank_transfer_events AS transfer_event_row
      WHERE transfer_event_row.pay_batch_id = p_pay_batch_id;

      SELECT COUNT(*)::integer
      INTO v_no_bank_provider_attempt_count
      FROM public.banking_pay_operation_provider_attempts AS provider_attempt_row
      WHERE provider_attempt_row.pay_batch_id = p_pay_batch_id
         OR provider_attempt_row.operation_id = v_execution_operation_id;

      IF COALESCE(v_no_bank_scope_artifact_count, 0) <> 0
         OR COALESCE(v_no_bank_batch_transfer_count, 0) <> 0
         OR COALESCE(v_no_bank_transfer_event_count, 0) <> 0
         OR COALESCE(v_no_bank_provider_attempt_count, 0) <> 0 THEN
        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
          'error', 'PAY_SETTLE_RAIL',
          'code', 'NO_BANK_PAYMENT_FINALISATION_EVIDENCE_CONFLICT',
          'message', 'No-bank-payment full finalisation cannot continue because transfer or provider-submission evidence exists.',
          'pay_batch_id', p_pay_batch_id::text,
          'execution_operation_id', v_execution_operation_id::text,
          'transfer_scope_count', COALESCE(v_no_bank_scope_artifact_count, 0),
          'bank_transfer_count', COALESCE(v_no_bank_batch_transfer_count, 0),
          'bank_transfer_event_count', COALESCE(v_no_bank_transfer_event_count, 0),
          'provider_attempt_count', COALESCE(v_no_bank_provider_attempt_count, 0)
        )::text USING ERRCODE = 'P0001';
      END IF;

      IF v_execution_commit_state NOT IN ('NOT_SUBMITTED', 'COMMITTED')
         OR (
           NULLIF(BTRIM(COALESCE(v_execution_commit_ref, '')), '') IS NOT NULL
           AND NULLIF(BTRIM(COALESCE(v_execution_commit_ref, '')), '') <> v_local_no_bank_commit_ref
         )
         OR (
           v_execution_commit_state = 'COMMITTED'
           AND (
             NULLIF(BTRIM(COALESCE(v_execution_commit_ref, '')), '') IS DISTINCT FROM v_local_no_bank_commit_ref
             OR v_execution_committed_at_utc IS NULL
           )
         )
         OR (
           v_execution_commit_state = 'NOT_SUBMITTED'
           AND v_execution_committed_at_utc IS NOT NULL
         ) THEN
        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
          'error', 'PAY_SETTLE_RAIL',
          'code', 'NO_BANK_PAYMENT_FINALISATION_COMMIT_CONFLICT',
          'message', 'The batch contains execution commit evidence incompatible with no-bank-payment finalisation.',
          'pay_batch_id', p_pay_batch_id::text,
          'execution_commit_state', v_execution_commit_state,
          'execution_commit_ref', v_execution_commit_ref,
          'expected_local_commit_reference', v_local_no_bank_commit_ref,
          'execution_committed_at_utc', CASE WHEN v_execution_committed_at_utc IS NULL THEN NULL::text ELSE v_execution_committed_at_utc::text END
        )::text USING ERRCODE = 'P0001';
      END IF;
    END IF;
  END IF;

  -- Settlement follows bank/provider truth after the execution boundary.
  -- Do not run current/live freshness as a blocking settlement check here.
  -- Stored freshness-at-execution metadata is carried as informational context only.
  v_fresh := jsonb_build_object(
    'is_stale', coalesce(v_stored_freshness_status in ('STALE', 'FAILED'), false),
    'stale_reasons', coalesce(v_stored_freshness_result_json->'stale_reasons', '[]'::jsonb),
    'diff', coalesce(v_stored_freshness_result_json->'diff_sample', '[]'::jsonb),
    'freshness_validation_status', nullif(v_stored_freshness_status, ''),
    'freshness_result_hash', v_stored_freshness_result_hash,
    'freshness_scope_hash', v_stored_freshness_scope_hash,
    'freshness_operation_id', case when v_stored_freshness_operation_id is null then null else v_stored_freshness_operation_id::text end,
    'source', 'stored_freshness_metadata_non_blocking'
  );
  v_is_stale := coalesce(v_stored_freshness_status in ('STALE', 'FAILED'), false);
  v_stale_reasons := coalesce(v_stored_freshness_result_json->'stale_reasons', '[]'::jsonb);
  v_diff_sample := coalesce(v_stored_freshness_result_json->'diff_sample', '[]'::jsonb);

  if v_is_stale = true then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_SETTLE_RAIL:STORED_STALE_METADATA_PROCEEDING',
        jsonb_build_object(
          'pay_batch_id', p_pay_batch_id::text,
          'freshness_validation_status', v_stored_freshness_status,
          'freshness_result_hash', v_stored_freshness_result_hash,
          'freshness_scope_hash', v_stored_freshness_scope_hash,
          'stale_reasons', v_stale_reasons,
          'diff_sample', v_diff_sample
        ),
        'pay_batches',
        p_pay_batch_id::text,
        null,
        null,
        null,
        null
      );
    exception when others then
      null;
    end;
  end if;

  create temp table if not exists _tmp_settle_in (
    transfer_id uuid null,
    status text not null,
    rail_tx_id text null,
    rail_state text null,
    rail_meta_json jsonb null
  ) on commit drop;

  truncate table _tmp_settle_in;

  insert into _tmp_settle_in(transfer_id, status, rail_tx_id, rail_state, rail_meta_json)
  select
    case
      when nullif(btrim(coalesce(e->>'transfer_id','')),'') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then nullif(btrim(coalesce(e->>'transfer_id','')),'')::uuid
      else null::uuid
    end as transfer_id,
    upper(btrim(coalesce(e->>'status',''))) as status,
    nullif(btrim(coalesce(e->>'rail_tx_id','')),'') as rail_tx_id,
    nullif(btrim(coalesce(e->>'rail_state','')),'') as rail_state,
    case
      when (e ? 'rail_meta_json') and jsonb_typeof(e->'rail_meta_json') in ('object','array','string','number','boolean','null')
        then e->'rail_meta_json'
      else null
    end as rail_meta_json
  from jsonb_array_elements(p_settlement_json) e
  where e is not null and jsonb_typeof(e) = 'object';

  update _tmp_settle_in AS settle_status_normalise
  set status = case

    when settle_status_normalise.status = 'CANCELED' then 'CANCELLED'
    when settle_status_normalise.status in ('SUCCESS','SUCCEEDED','SETTLED','PAID') then 'COMPLETED'
    when settle_status_normalise.status in ('EXECUTED','COMMITTED') then 'UNKNOWN'
    when settle_status_normalise.status = 'REVERSED' then 'REVERTED'
    when settle_status_normalise.status in ('SUBMISSION_FAILED','FAILED_BEFORE_COMMIT') then 'FAILED'
    else settle_status_normalise.status
  end
  where settle_status_normalise.status in (
    'CANCELED',
    'SUCCESS',
    'SUCCEEDED',
    'SETTLED',
    'PAID',
    'EXECUTED',
    'COMMITTED',
    'REVERSED',
    'SUBMISSION_FAILED',
    'FAILED_BEFORE_COMMIT'
  );

  DROP TABLE IF EXISTS pg_temp._tmp_settle_in_classification;
  CREATE TEMP TABLE _tmp_settle_in_classification ON COMMIT DROP AS
  SELECT
    settle_input_rows.transfer_id,
    classification_rows.cash_state,
    classification_rows.normalised_transfer_status,
    classification_rows.is_final_money_moved,
    classification_rows.is_terminal_no_money,
    classification_rows.is_pending_non_final,
    classification_rows.completed_at_allowed,
    classification_rows.reason,
    classification_rows.support_details_json
  FROM _tmp_settle_in AS settle_input_rows
  CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
    settle_input_rows.status,
    settle_input_rows.rail_state,
    COALESCE(settle_input_rows.rail_meta_json, '{}'::jsonb),
    COALESCE(settle_input_rows.rail_meta_json, '{}'::jsonb)
  ) AS classification_rows;

  UPDATE _tmp_settle_in AS settle_input_rows
  SET
    status = CASE
      WHEN classification_rows.is_final_money_moved THEN 'COMPLETED'
      WHEN classification_rows.is_terminal_no_money AND upper(COALESCE(settle_input_rows.status, '')) IN ('CANCELLED','CANCELED') THEN 'CANCELLED'
      WHEN classification_rows.is_terminal_no_money THEN 'FAILED'
      WHEN classification_rows.is_pending_non_final THEN CASE WHEN upper(COALESCE(settle_input_rows.status, '')) IN ('PROCESSING','SUBMITTED','SENT','ACCEPTED') THEN 'PROCESSING' ELSE 'PENDING' END
      ELSE 'UNKNOWN'
    END,
    rail_meta_json = COALESCE(settle_input_rows.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
      'money_movement_classification', jsonb_build_object(
        'cash_state', classification_rows.cash_state,
        'normalised_transfer_status', classification_rows.normalised_transfer_status,
        'is_final_money_moved', classification_rows.is_final_money_moved,
        'is_terminal_no_money', classification_rows.is_terminal_no_money,
        'is_pending_non_final', classification_rows.is_pending_non_final,
        'completed_at_allowed', classification_rows.completed_at_allowed,
        'reason', classification_rows.reason
      ),
      'settlement_final_paid_required', true
    )
  FROM pg_temp._tmp_settle_in_classification AS classification_rows
  WHERE classification_rows.transfer_id = settle_input_rows.transfer_id;

  if exists (select 1 from _tmp_settle_in t where t.transfer_id is null limit 1) then
    raise exception 'pay_settle_rail: settlement_json contains an invalid or missing transfer_id';
  end if;

  if exists (
    select 1
    from _tmp_settle_in t
    where t.status not in ('PENDING','PROCESSING','UNKNOWN','COMPLETED','FAILED','DECLINED','REJECTED','CANCELLED','RETURNED','REVERTED')
    limit 1
  ) then
    raise exception 'pay_settle_rail: invalid status in settlement_json (allowed: PENDING|PROCESSING|UNKNOWN|COMPLETED|FAILED|DECLINED|REJECTED|CANCELLED|RETURNED|REVERTED)';
  end if;

  if exists (
    select 1
    from _tmp_settle_in t
    left join public.pay_bank_transfers pbt
      on pbt.id = t.transfer_id
     and pbt.pay_batch_id = p_pay_batch_id
    where pbt.id is null
    limit 1
  ) then
    raise exception 'pay_settle_rail: one or more transfer_id values do not belong to the specified pay batch';
  end if;

  if v_settlement_mode = 'STANDARD_BANK' and exists (
    select 1
    from _tmp_settle_in as t
    join public.pay_bank_transfers as pbt
      on pbt.id = t.transfer_id
     and pbt.pay_batch_id = p_pay_batch_id
    where t.status = 'COMPLETED'
      and not exists (
        select 1
        from (values
          (t.rail_tx_id),
          (t.rail_meta_json #>> '{provider_reference}'),
          (t.rail_meta_json #>> '{provider_event_id}'),
          (t.rail_meta_json #>> '{provider_submission_id}'),
          (t.rail_meta_json #>> '{submission_id}'),
          (t.rail_meta_json #>> '{rail_submission_id}'),
          (t.rail_meta_json #>> '{provider_payment_id}'),
          (t.rail_meta_json #>> '{payment_id}'),
          (t.rail_meta_json #>> '{external_payment_id}'),
          (t.rail_meta_json #>> '{revolut_payment_id}'),
          (t.rail_meta_json #>> '{provider_transfer_id}'),
          (t.rail_meta_json #>> '{transfer_id}'),
          (t.rail_meta_json #>> '{external_transfer_id}'),
          (t.rail_meta_json #>> '{provider_transaction_id}'),
          (t.rail_meta_json #>> '{transaction_id}')
        ) as provider_identifier(identifier_value)
        where nullif(btrim(coalesce(provider_identifier.identifier_value, '')), '') is not null
          and not (
            nullif(btrim(coalesce(provider_identifier.identifier_value, '')), '') = any(
              array_remove(array[
                pbt.id::text,
                nullif(btrim(coalesce(pbt.request_id, '')), ''),
                nullif(btrim(coalesce(pbt.payment_reference, '')), ''),
                nullif(btrim(coalesce(v_batch.bulk_reference, '')), ''),
                nullif(btrim(coalesce(pbt.rail_meta_json #>> '{request_id}', '')), ''),
                nullif(btrim(coalesce(pbt.rail_meta_json #>> '{idempotency_key}', '')), ''),
                nullif(btrim(coalesce(pbt.rail_meta_json #>> '{payment_reference}', '')), ''),
                nullif(btrim(coalesce(pbt.rail_meta_json #>> '{bulk_reference}', '')), ''),
                nullif(btrim(coalesce(t.rail_meta_json #>> '{request_id}', '')), ''),
                nullif(btrim(coalesce(t.rail_meta_json #>> '{idempotency_key}', '')), ''),
                nullif(btrim(coalesce(t.rail_meta_json #>> '{payment_reference}', '')), ''),
                nullif(btrim(coalesce(t.rail_meta_json #>> '{bulk_reference}', '')), '')
              ]::text[], null::text)
            )
          )
      )
    limit 1
  ) then
    raise exception 'PAY_SETTLE_RAIL_PROVIDER_EVIDENCE_REQUIRED'
      using errcode = 'P0001',
            detail = jsonb_build_object(
              'code', 'PAY_SETTLE_RAIL_PROVIDER_EVIDENCE_REQUIRED',
              'pay_batch_id', p_pay_batch_id::text,
              'message', 'STANDARD_BANK settlement marked as completed requires genuine provider or bank evidence, not local request/payment references.'
            )::text;
  end if;


  update public.pay_bank_transfers pbt
  set
    status = CASE
      WHEN t.status = 'COMPLETED' THEN 'COMPLETED'
      WHEN t.status IN ('FAILED','DECLINED','REJECTED','CANCELLED','RETURNED','REVERTED') THEN t.status
      WHEN t.status = 'BLOCKED' THEN 'BLOCKED'
      WHEN t.status = 'PROCESSING' THEN 'PROCESSING'
      WHEN t.status = 'UNKNOWN' THEN 'UNKNOWN'
      WHEN t.status = 'PENDING' THEN 'PENDING'
      ELSE 'PENDING'
    END,
    rail_tx_id = coalesce(t.rail_tx_id, pbt.rail_tx_id),
    rail_state = coalesce(t.rail_state, pbt.rail_state),
    rail_meta_json = case
      when t.rail_meta_json is null then pbt.rail_meta_json
      when pbt.rail_meta_json is null then t.rail_meta_json
      else (pbt.rail_meta_json || t.rail_meta_json)
    end,
    completed_at_utc = case
      when t.status = 'COMPLETED' then coalesce(pbt.completed_at_utc, v_now)
      else pbt.completed_at_utc
    end,
    failed_reason = case
      when t.status IN ('FAILED','DECLINED','REJECTED','CANCELLED') then coalesce(pbt.failed_reason, nullif(btrim(coalesce(t.rail_state,'')),''), t.status)
      else pbt.failed_reason
    end
  from _tmp_settle_in t
  where pbt.id = t.transfer_id
    and pbt.pay_batch_id = p_pay_batch_id;

  DROP TABLE IF EXISTS pg_temp._tmp_settle_bank_event_ingest_results;
  CREATE TEMP TABLE _tmp_settle_bank_event_ingest_results ON COMMIT DROP AS
  SELECT

    settle_event_rows.transfer_id,
    settle_event_rows.status,
    CASE
      WHEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json->>'bank_event_id', '')), '') IS NOT NULL
       AND EXISTS (
         SELECT 1
         FROM public.pay_bank_transfer_events AS existing_authoritative_event
         WHERE existing_authoritative_event.id::text = settle_event_rows.rail_meta_json->>'bank_event_id'
           AND existing_authoritative_event.pay_batch_id = p_pay_batch_id
           AND existing_authoritative_event.pay_bank_transfer_id = settle_event_rows.transfer_id
           AND existing_authoritative_event.mapping_status = 'MATCHED'
       ) THEN jsonb_build_object(
         'ok', true,
         'event_id', settle_event_rows.rail_meta_json->>'bank_event_id',
         'idempotent', true,
         'mapped', true,
         'normalised_state', settle_event_rows.status,
         'settlement_reused_existing_event', true
       )
      ELSE public.pay_bank_event_ingest(
        jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'pay_bank_transfer_id', settle_event_rows.transfer_id::text,
        'provider_key', COALESCE(v_batch.rail_provider_snapshot, 'UNKNOWN'),
        'provider_reference', CASE
          WHEN v_settlement_mode IN ('CSV_SETTLEMENT','EXTERNAL_SETTLEMENT') THEN COALESCE(settle_event_rows.rail_tx_id, bank_transfer_for_event.rail_tx_id, bank_transfer_for_event.request_id, bank_transfer_for_event.payment_reference)
          ELSE COALESCE(
            CASE
              WHEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_tx_id, '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(settle_event_rows.rail_tx_id, '')), '') NOT IN (
                 COALESCE(bank_transfer_for_event.id::text, '__no_transfer_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.request_id, '')), ''), '__no_request_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.payment_reference, '')), ''), '__no_payment_reference__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
               )
                THEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_tx_id, '')), '')
              ELSE NULL::text
            END,
            CASE
              WHEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_reference}', '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_reference}', '')), '') NOT IN (
                 COALESCE(bank_transfer_for_event.id::text, '__no_transfer_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.request_id, '')), ''), '__no_request_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.payment_reference, '')), ''), '__no_payment_reference__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
               )
                THEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_reference}', '')), '')
              ELSE NULL::text
            END,
            CASE
              WHEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_event_id}', '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_event_id}', '')), '') NOT IN (
                 COALESCE(bank_transfer_for_event.id::text, '__no_transfer_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.request_id, '')), ''), '__no_request_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.payment_reference, '')), ''), '__no_payment_reference__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
               )
                THEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_event_id}', '')), '')
              ELSE NULL::text
            END,
            CASE
              WHEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_submission_id}', '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_submission_id}', '')), '') NOT IN (
                 COALESCE(bank_transfer_for_event.id::text, '__no_transfer_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.request_id, '')), ''), '__no_request_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.payment_reference, '')), ''), '__no_payment_reference__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
               )
                THEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_submission_id}', '')), '')
              ELSE NULL::text
            END,
            CASE
              WHEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_payment_id}', '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_payment_id}', '')), '') NOT IN (
                 COALESCE(bank_transfer_for_event.id::text, '__no_transfer_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.request_id, '')), ''), '__no_request_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.payment_reference, '')), ''), '__no_payment_reference__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
               )
                THEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_payment_id}', '')), '')
              ELSE NULL::text
            END,
            CASE
              WHEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_transfer_id}', '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_transfer_id}', '')), '') NOT IN (
                 COALESCE(bank_transfer_for_event.id::text, '__no_transfer_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.request_id, '')), ''), '__no_request_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.payment_reference, '')), ''), '__no_payment_reference__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
               )
                THEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_transfer_id}', '')), '')
              ELSE NULL::text
            END,
            CASE
              WHEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_transaction_id}', '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_transaction_id}', '')), '') NOT IN (
                 COALESCE(bank_transfer_for_event.id::text, '__no_transfer_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.request_id, '')), ''), '__no_request_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.payment_reference, '')), ''), '__no_payment_reference__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
               )
                THEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_transaction_id}', '')), '')
              ELSE NULL::text
            END,
            CASE
              WHEN NULLIF(BTRIM(COALESCE(bank_transfer_for_event.rail_tx_id, '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(bank_transfer_for_event.rail_tx_id, '')), '') NOT IN (
                 COALESCE(bank_transfer_for_event.id::text, '__no_transfer_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.request_id, '')), ''), '__no_request_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.payment_reference, '')), ''), '__no_payment_reference__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
               )
                THEN NULLIF(BTRIM(COALESCE(bank_transfer_for_event.rail_tx_id, '')), '')
              ELSE NULL::text
            END
          )
        END,
        'provider_state', COALESCE(settle_event_rows.rail_state, settle_event_rows.status),
        'normalised_state', settle_event_rows.status,
        'event_source', CASE WHEN v_settlement_mode IN ('CSV_SETTLEMENT','EXTERNAL_SETTLEMENT') THEN 'MANUAL_CONFIRM' ELSE 'PROVIDER_POLL' END,
        'event_time_utc', v_now::text,
        'amount', bank_transfer_for_event.amount,
        'currency', 'GBP',
        'raw_payload', COALESCE(settle_event_rows.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
          'settlement_mode', v_settlement_mode,
          'source_rpc', 'pay_settle_rail'
        )
        ),
        p_actor_user_id
      )
    END AS ingest_result
  FROM _tmp_settle_in AS settle_event_rows
  JOIN public.pay_bank_transfers AS bank_transfer_for_event
    ON bank_transfer_for_event.id = settle_event_rows.transfer_id;

  SELECT
    COALESCE(jsonb_agg(ingest_rows.ingest_result ORDER BY ingest_rows.transfer_id), '[]'::jsonb),
    count(*)::int
  INTO v_bank_event_ingest_results, v_bank_event_ingest_count
  FROM pg_temp._tmp_settle_bank_event_ingest_results AS ingest_rows;

  DROP TABLE IF EXISTS pg_temp._tmp_settle_external_completed_transfers;
  CREATE TEMP TABLE _tmp_settle_external_completed_transfers ON COMMIT DROP AS
  WITH completed_transfer_base AS (
    SELECT
      completed_transfer.id AS transfer_id,
      completed_transfer.rail_tx_id,
      completed_transfer.completed_at_utc,
      completed_transfer.status,
      completed_transfer.rail_state,
      COALESCE(completed_transfer.rail_meta_json, '{}'::jsonb) AS rail_meta_json,
      lower(btrim(coalesce(completed_transfer.rail_meta_json #>> '{last_update_provider_evidence}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') AS last_update_was_provider_evidence,
      ARRAY_REMOVE(ARRAY[
        completed_transfer.id::text,
        NULLIF(BTRIM(COALESCE(completed_transfer.request_id, '')), ''),
        NULLIF(BTRIM(COALESCE(completed_transfer.payment_reference, '')), ''),
        NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''),
        NULLIF(BTRIM(COALESCE(completed_transfer.rail_meta_json #>> '{request_id}', '')), ''),
        NULLIF(BTRIM(COALESCE(completed_transfer.rail_meta_json #>> '{idempotency_key}', '')), ''),
        NULLIF(BTRIM(COALESCE(completed_transfer.rail_meta_json #>> '{payment_reference}', '')), ''),
        NULLIF(BTRIM(COALESCE(completed_transfer.rail_meta_json #>> '{bulk_reference}', '')), '')
      ]::text[], NULL::text) AS local_identity_values
    FROM public.pay_bank_transfers AS completed_transfer
    WHERE completed_transfer.pay_batch_id = p_pay_batch_id
      AND EXISTS (
        SELECT 1
        FROM public._pay_rail_state_money_movement_classify(
          completed_transfer.status,
          completed_transfer.rail_state,
          COALESCE(completed_transfer.rail_meta_json, '{}'::jsonb),
          COALESCE(completed_transfer.rail_meta_json, '{}'::jsonb)
        ) AS completed_transfer_classifier
        WHERE completed_transfer_classifier.is_final_money_moved = true
      )
  ), externally_supported_completed AS (
    SELECT
      completed_transfer_base.transfer_id,
      completed_transfer_base.rail_tx_id,
      completed_transfer_base.completed_at_utc,
      (
        v_settlement_mode IN ('CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT')
        OR EXISTS (
          SELECT 1
          FROM public.pay_bank_transfer_events AS completed_event
          WHERE completed_event.pay_bank_transfer_id = completed_transfer_base.transfer_id
            AND upper(btrim(coalesce(completed_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK', 'WEBHOOK', 'POLL', 'RAIL_PROVIDER', 'PROVIDER', 'PROVIDER_SETTLEMENT')
            AND (
              upper(btrim(coalesce(completed_event.normalised_state, ''))) IN ('COMPLETED', 'SETTLED', 'PAID', 'SUCCESS', 'SUCCEEDED')
              OR upper(btrim(coalesce(completed_event.provider_state, ''))) IN ('COMPLETED', 'SETTLED', 'PAID', 'SUCCESS', 'SUCCEEDED')
            )
            AND EXISTS (
              SELECT 1
              FROM (VALUES
                (completed_event.provider_event_id),
                (completed_event.provider_reference),
                (completed_event.raw_payload #>> '{provider_event_id}'),
                (completed_event.raw_payload #>> '{provider_reference}'),
                (completed_event.raw_payload #>> '{provider_submission_id}'),

                (completed_event.raw_payload #>> '{submission_id}'),
                (completed_event.raw_payload #>> '{rail_submission_id}'),
                (completed_event.raw_payload #>> '{provider_payment_id}'),
                (completed_event.raw_payload #>> '{payment_id}'),
                (completed_event.raw_payload #>> '{external_payment_id}'),
                (completed_event.raw_payload #>> '{revolut_payment_id}'),
                (completed_event.raw_payload #>> '{provider_transfer_id}'),
                (completed_event.raw_payload #>> '{transfer_id}'),
                (completed_event.raw_payload #>> '{external_transfer_id}'),
                (completed_event.raw_payload #>> '{provider_transaction_id}'),
                (completed_event.raw_payload #>> '{transaction_id}')
              ) AS completed_event_identifier(identifier_value)
              WHERE NULLIF(BTRIM(COALESCE(completed_event_identifier.identifier_value, '')), '') IS NOT NULL
                AND NOT (NULLIF(BTRIM(COALESCE(completed_event_identifier.identifier_value, '')), '') = ANY(completed_transfer_base.local_identity_values))
            )
        )
        OR (
          completed_transfer_base.last_update_was_provider_evidence IS TRUE
          AND EXISTS (
            SELECT 1
            FROM (VALUES
              (completed_transfer_base.rail_tx_id),
              (completed_transfer_base.rail_meta_json #>> '{provider_event_id}'),
              (completed_transfer_base.rail_meta_json #>> '{provider_reference}'),
              (completed_transfer_base.rail_meta_json #>> '{provider_submission_id}'),
              (completed_transfer_base.rail_meta_json #>> '{submission_id}'),
              (completed_transfer_base.rail_meta_json #>> '{rail_submission_id}'),
              (completed_transfer_base.rail_meta_json #>> '{provider_payment_id}'),
              (completed_transfer_base.rail_meta_json #>> '{payment_id}'),
              (completed_transfer_base.rail_meta_json #>> '{external_payment_id}'),
              (completed_transfer_base.rail_meta_json #>> '{revolut_payment_id}'),
              (completed_transfer_base.rail_meta_json #>> '{provider_transfer_id}'),
              (completed_transfer_base.rail_meta_json #>> '{transfer_id}'),
              (completed_transfer_base.rail_meta_json #>> '{external_transfer_id}'),
              (completed_transfer_base.rail_meta_json #>> '{provider_transaction_id}'),
              (completed_transfer_base.rail_meta_json #>> '{transaction_id}')
            ) AS completed_transfer_identifier(identifier_value)
            WHERE NULLIF(BTRIM(COALESCE(completed_transfer_identifier.identifier_value, '')), '') IS NOT NULL
              AND NOT (NULLIF(BTRIM(COALESCE(completed_transfer_identifier.identifier_value, '')), '') = ANY(completed_transfer_base.local_identity_values))
          )
        )
      ) AS has_external_completion_evidence
    FROM completed_transfer_base
  )
  SELECT
    externally_supported_completed.transfer_id,
    externally_supported_completed.rail_tx_id,
    externally_supported_completed.completed_at_utc
  FROM externally_supported_completed
  WHERE externally_supported_completed.has_external_completion_evidence IS TRUE;

  SELECT
    COUNT(*)::int,
    ROUND(COALESCE(SUM(bank_transfer_total.amount), 0), 2)::numeric(14,2),
    COALESCE(
      JSONB_AGG(completed_transfer_count_row.transfer_id::text ORDER BY completed_transfer_count_row.transfer_id),
      '[]'::jsonb
    ),
    (
      SELECT NULLIF(BTRIM(COALESCE(completed_transfer_ref.rail_tx_id, bank_transfer_ref.rail_tx_id, '')), '')
      FROM pg_temp._tmp_settle_external_completed_transfers AS completed_transfer_ref
      JOIN public.pay_bank_transfers AS bank_transfer_ref
        ON bank_transfer_ref.id = completed_transfer_ref.transfer_id
       AND bank_transfer_ref.pay_batch_id = p_pay_batch_id
      WHERE NULLIF(BTRIM(COALESCE(completed_transfer_ref.rail_tx_id, bank_transfer_ref.rail_tx_id, '')), '') IS NOT NULL
      ORDER BY COALESCE(completed_transfer_ref.completed_at_utc, bank_transfer_ref.completed_at_utc) DESC NULLS LAST, bank_transfer_ref.id DESC
      LIMIT 1
    ),
    (
      SELECT COALESCE(completed_transfer_ts.completed_at_utc, bank_transfer_ts.completed_at_utc)
      FROM pg_temp._tmp_settle_external_completed_transfers AS completed_transfer_ts
      JOIN public.pay_bank_transfers AS bank_transfer_ts
        ON bank_transfer_ts.id = completed_transfer_ts.transfer_id
       AND bank_transfer_ts.pay_batch_id = p_pay_batch_id
      ORDER BY COALESCE(completed_transfer_ts.completed_at_utc, bank_transfer_ts.completed_at_utc) DESC NULLS LAST, bank_transfer_ts.id DESC
      LIMIT 1
    )
  INTO
    v_completed_transfer_count,
    v_completed_transfer_total,
    v_completed_transfer_ids,
    v_detected_execution_commit_ref,
    v_detected_execution_committed_at_utc
  FROM pg_temp._tmp_settle_external_completed_transfers AS completed_transfer_count_row
  JOIN public.pay_bank_transfers AS bank_transfer_total
    ON bank_transfer_total.id = completed_transfer_count_row.transfer_id
   AND bank_transfer_total.pay_batch_id = p_pay_batch_id;

  IF COALESCE(v_completed_transfer_count, 0) > 0 THEN
    v_execution_commit_state := 'COMMITTED';
    v_execution_commit_ref := COALESCE(v_execution_commit_ref, v_detected_execution_commit_ref);
    v_execution_committed_at_utc := COALESCE(v_execution_committed_at_utc, v_detected_execution_committed_at_utc, v_now);
  END IF;

  IF v_no_bank_settlement_operation_id IS NOT NULL THEN
    v_settlement_operation_id := v_no_bank_settlement_operation_id;
  ELSIF COALESCE(v_completed_transfer_count, 0) > 0 THEN
    DROP TABLE IF EXISTS pg_temp.tmp_pay_settle_rail_compatible_settlement_operations;
    CREATE TEMPORARY TABLE pg_temp.tmp_pay_settle_rail_compatible_settlement_operations
    ON COMMIT DROP
    AS
    SELECT settlement_operation.id AS operation_id
    FROM public.banking_pay_operations AS settlement_operation
    WHERE settlement_operation.pay_batch_id = p_pay_batch_id
      AND settlement_operation.operation_type = 'PAYMENT_SETTLEMENT'
      AND settlement_operation.root_operation_id = v_execution_operation_id
      AND JSONB_TYPEOF(settlement_operation.input_json) = 'object'
      AND NULLIF(BTRIM(COALESCE(
        settlement_operation.input_json->>'execution_operation_id',
        settlement_operation.input_json->>'root_operation_id',
        ''
      )), '') = v_execution_operation_id::text
      AND NULLIF(BTRIM(COALESCE(settlement_operation.input_json->>'auth_request_id', '')), '') = v_operation_auth_request_id::text
      AND CASE
        WHEN UPPER(BTRIM(COALESCE(
          settlement_operation.input_json->>'settlement_mode',
          settlement_operation.input_json->>'execution_mode',
          ''
        ))) IN ('STANDARD_BANK', 'BANK') THEN 'STANDARD_BANK'
        WHEN UPPER(BTRIM(COALESCE(
          settlement_operation.input_json->>'settlement_mode',
          settlement_operation.input_json->>'execution_mode',
          ''
        ))) IN ('CSV', 'CSV_SETTLEMENT') THEN 'CSV_SETTLEMENT'
        WHEN UPPER(BTRIM(COALESCE(
          settlement_operation.input_json->>'settlement_mode',
          settlement_operation.input_json->>'execution_mode',
          ''
        ))) IN ('EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'EXTERNAL_SETTLEMENT'
        ELSE UPPER(BTRIM(COALESCE(
          settlement_operation.input_json->>'settlement_mode',
          settlement_operation.input_json->>'execution_mode',
          ''
        )))
      END = v_settlement_mode
      AND UPPER(BTRIM(COALESCE(
        settlement_operation.input_json->>'pay_channel_scope',
        settlement_operation.input_json->>'scope',
        ''
      ))) = v_operation_projection_scope
      AND LOWER(BTRIM(COALESCE(settlement_operation.input_json->>'server_owned_payment_projection_proof', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND NULLIF(BTRIM(COALESCE(settlement_operation.input_json->>'paye_net_state_hash', '')), '') = v_expected_paye_net_state_hash
      AND NULLIF(BTRIM(COALESCE(settlement_operation.input_json->>'bank_payment_projection_hash', '')), '') = v_expected_bank_payment_projection_hash
      AND CASE
        WHEN COALESCE(settlement_operation.input_json->>'missing_explicit_paye_input_count', '') ~ '^[0-9]+$'
          THEN (settlement_operation.input_json->>'missing_explicit_paye_input_count')::integer
        ELSE -1
      END = COALESCE(v_expected_missing_count, -1)
      AND CASE
        WHEN COALESCE(settlement_operation.input_json->>'scoped_explicit_zero_count', '') ~ '^[0-9]+$'
          THEN (settlement_operation.input_json->>'scoped_explicit_zero_count')::integer
        ELSE -1
      END = COALESCE(v_expected_zero_count, -1)
      AND CASE
        WHEN COALESCE(settlement_operation.input_json->>'scoped_positive_bank_payment_count', '') ~ '^[0-9]+$'
          THEN (settlement_operation.input_json->>'scoped_positive_bank_payment_count')::integer
        ELSE -1
      END = COALESCE(v_expected_positive_count, -1)
      AND LOWER(BTRIM(COALESCE(settlement_operation.input_json->>'no_bank_payment_execution', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') = v_no_bank_payment_marker
      AND LOWER(BTRIM(COALESCE(settlement_operation.input_json->>'allow_explicit_zero_no_bank_scopes', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') = v_allow_explicit_zero_no_bank_scopes_marker
      AND LOWER(BTRIM(COALESCE(settlement_operation.input_json->>'suppress_remittances', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') = v_suppress_remittances
      AND EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_settlement_scope AS settlement_scope
        WHERE settlement_scope.operation_id = settlement_operation.id
          AND settlement_scope.pay_batch_id = p_pay_batch_id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_settlement_scope AS settlement_scope
        WHERE settlement_scope.operation_id = settlement_operation.id
          AND settlement_scope.pay_batch_id = p_pay_batch_id
          AND UPPER(BTRIM(COALESCE(settlement_scope.status, ''))) NOT IN ('SETTLED', 'SKIPPED')
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_settlement_scope AS settlement_scope
        WHERE settlement_scope.operation_id = settlement_operation.id
          AND settlement_scope.pay_batch_id = p_pay_batch_id
          AND UPPER(BTRIM(COALESCE(settlement_scope.status, ''))) = 'FAILED'

      );

    SELECT
      COUNT(*)::integer,
      (ARRAY_AGG(compatible_operation.operation_id ORDER BY compatible_operation.operation_id))[1]
    INTO
      v_settlement_operation_count,
      v_settlement_operation_id
    FROM pg_temp.tmp_pay_settle_rail_compatible_settlement_operations AS compatible_operation;

    SELECT COUNT(*)::integer
    INTO v_related_settlement_operation_count
    FROM public.banking_pay_operations AS related_operation
    WHERE related_operation.pay_batch_id = p_pay_batch_id
      AND related_operation.operation_type = 'PAYMENT_SETTLEMENT'
      AND (
        related_operation.root_operation_id = v_execution_operation_id
        OR NULLIF(BTRIM(COALESCE(related_operation.input_json->>'execution_operation_id', '')), '') = v_execution_operation_id::text
      );

    SELECT COUNT(*)::integer
    INTO v_bound_settlement_scope_count
    FROM public.banking_pay_operation_settlement_scope AS bound_scope
    JOIN public.banking_pay_operations AS bound_operation
      ON bound_operation.id = bound_scope.operation_id
     AND bound_operation.pay_batch_id = p_pay_batch_id
     AND bound_operation.operation_type = 'PAYMENT_SETTLEMENT'
    WHERE bound_scope.pay_batch_id = p_pay_batch_id
      AND (
        bound_operation.root_operation_id = v_execution_operation_id
        OR NULLIF(BTRIM(COALESCE(bound_operation.input_json->>'execution_operation_id', '')), '') = v_execution_operation_id::text
      );

    IF COALESCE(v_settlement_operation_count, 0) = 0 THEN
      IF COALESCE(v_related_settlement_operation_count, 0) = 0
         AND COALESCE(v_bound_settlement_scope_count, 0) = 0 THEN
        -- Compatibility for an older direct settlement route that genuinely has no
        -- child operation or durable settlement-scope rows. The execution operation
        -- remains the deterministic proof binding; no provider evidence is invented.
        v_settlement_operation_id := v_execution_operation_id;
        v_settlement_operation_count := 1;
        v_legacy_direct_settlement := true;
      ELSE
        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
          'error', 'PAY_SETTLE_RAIL',
          'code', 'SETTLEMENT_OPERATION_PROOF_INCOMPLETE',
          'message', 'Full settlement found a settlement child or settlement scopes, but none formed one complete successful operation bound to the authorised frozen proof.',
          'pay_batch_id', p_pay_batch_id::text,
          'execution_operation_id', v_execution_operation_id::text,
          'auth_request_id', v_operation_auth_request_id::text,
          'related_settlement_operation_count', COALESCE(v_related_settlement_operation_count, 0),
          'bound_settlement_scope_count', COALESCE(v_bound_settlement_scope_count, 0)
        )::text USING ERRCODE = 'P0001';
      END IF;
    ELSIF COALESCE(v_settlement_operation_count, 0) <> 1 THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_RAIL',
        'code', 'SETTLEMENT_OPERATION_PROOF_AMBIGUOUS',
        'message', 'Full settlement requires exactly one successful settlement operation bound to the authorised frozen proof.',
        'pay_batch_id', p_pay_batch_id::text,
        'execution_operation_id', v_execution_operation_id::text,
        'auth_request_id', v_operation_auth_request_id::text,
        'compatible_settlement_operation_count', COALESCE(v_settlement_operation_count, 0)
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF v_settlement_operation_id IS NOT NULL
     AND v_settlement_operation_id <> v_execution_operation_id THEN
    SELECT COUNT(*)::integer
    INTO v_settlement_operation_count
    FROM public.banking_pay_operations AS bound_settlement_operation
    WHERE bound_settlement_operation.id = v_settlement_operation_id
      AND bound_settlement_operation.pay_batch_id = p_pay_batch_id
      AND bound_settlement_operation.operation_type = 'PAYMENT_SETTLEMENT'
      AND bound_settlement_operation.root_operation_id = v_execution_operation_id
      AND JSONB_TYPEOF(bound_settlement_operation.input_json) = 'object'
      AND NULLIF(BTRIM(COALESCE(bound_settlement_operation.input_json->>'execution_operation_id', '')), '') = v_execution_operation_id::text
      AND NULLIF(BTRIM(COALESCE(bound_settlement_operation.input_json->>'auth_request_id', '')), '') = v_operation_auth_request_id::text
      AND CASE
        WHEN UPPER(BTRIM(COALESCE(bound_settlement_operation.input_json->>'settlement_mode', bound_settlement_operation.input_json->>'execution_mode', ''))) IN ('STANDARD_BANK', 'BANK') THEN 'STANDARD_BANK'
        WHEN UPPER(BTRIM(COALESCE(bound_settlement_operation.input_json->>'settlement_mode', bound_settlement_operation.input_json->>'execution_mode', ''))) IN ('CSV', 'CSV_SETTLEMENT') THEN 'CSV_SETTLEMENT'
        WHEN UPPER(BTRIM(COALESCE(bound_settlement_operation.input_json->>'settlement_mode', bound_settlement_operation.input_json->>'execution_mode', ''))) IN ('EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'EXTERNAL_SETTLEMENT'
        ELSE UPPER(BTRIM(COALESCE(bound_settlement_operation.input_json->>'settlement_mode', bound_settlement_operation.input_json->>'execution_mode', '')))
      END = v_settlement_mode
      AND UPPER(BTRIM(COALESCE(bound_settlement_operation.input_json->>'pay_channel_scope', bound_settlement_operation.input_json->>'scope', ''))) = v_operation_projection_scope
      AND LOWER(BTRIM(COALESCE(bound_settlement_operation.input_json->>'server_owned_payment_projection_proof', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND NULLIF(BTRIM(COALESCE(bound_settlement_operation.input_json->>'paye_net_state_hash', '')), '') = v_expected_paye_net_state_hash
      AND NULLIF(BTRIM(COALESCE(bound_settlement_operation.input_json->>'bank_payment_projection_hash', '')), '') = v_expected_bank_payment_projection_hash
      AND LOWER(BTRIM(COALESCE(bound_settlement_operation.input_json->>'suppress_remittances', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') = v_suppress_remittances;

    IF COALESCE(v_settlement_operation_count, 0) <> 1 THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_RAIL',
        'code', 'SETTLEMENT_OPERATION_BINDING_INVALID',
        'message', 'The selected settlement child is not bound to the authorised execution operation, auth request, mode, scope, hashes, and remittance policy.',
        'pay_batch_id', p_pay_batch_id::text,
        'execution_operation_id', v_execution_operation_id::text,
        'settlement_operation_id', v_settlement_operation_id::text,
        'auth_request_id', v_operation_auth_request_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF v_settlement_operation_id IS NOT NULL
     AND v_settlement_operation_id <> v_execution_operation_id THEN
    WITH settled_scope_for_event_repair AS (
      SELECT
        scope_row.id AS settlement_scope_id,
        scope_row.pay_batch_candidate_id,
        scope_row.payload_json
      FROM public.banking_pay_operation_settlement_scope AS scope_row
      WHERE scope_row.operation_id = v_settlement_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
        AND UPPER(BTRIM(COALESCE(scope_row.status, ''))) = 'SETTLED'
        AND scope_row.settlement_event_id IS NULL
        AND NOT (
          UPPER(BTRIM(COALESCE(scope_row.payload_json->>'scope_kind', ''))) = 'NO_BANK_PAYMENT'
          AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_reason', ''))) = 'EXPLICIT_ZERO_PAYE'
        )
      FOR UPDATE OF scope_row
    ), direct_scope_transfer AS (
      SELECT
        settled_scope.settlement_scope_id,
        CASE
          WHEN COALESCE(
            NULLIF(BTRIM(COALESCE(settled_scope.payload_json->>'pay_bank_transfer_id', '')), ''),
            NULLIF(BTRIM(COALESCE(settled_scope.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')), '')
          ) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN COALESCE(
              NULLIF(BTRIM(COALESCE(settled_scope.payload_json->>'pay_bank_transfer_id', '')), ''),
              NULLIF(BTRIM(COALESCE(settled_scope.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')), '')
            )::uuid
          ELSE NULL::uuid
        END AS pay_bank_transfer_id
      FROM settled_scope_for_event_repair AS settled_scope
    ), item_scope_transfer AS (
      SELECT DISTINCT
        settled_scope.settlement_scope_id,
        batch_item.pay_bank_transfer_id
      FROM settled_scope_for_event_repair AS settled_scope
      CROSS JOIN LATERAL JSONB_ARRAY_ELEMENTS(
        CASE
          WHEN JSONB_TYPEOF(settled_scope.payload_json->'pay_batch_item_ids') = 'array'
            THEN settled_scope.payload_json->'pay_batch_item_ids'
          ELSE '[]'::jsonb
        END
      ) AS item_element(value)
      JOIN public.pay_batch_items AS batch_item
        ON batch_item.id = CASE
             WHEN (item_element.value #>> '{}')
                  ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
               THEN (item_element.value #>> '{}')::uuid
             ELSE NULL::uuid
           END
       AND batch_item.pay_batch_candidate_id = settled_scope.pay_batch_candidate_id
       AND COALESCE(batch_item.is_voided, false) = false
      WHERE batch_item.pay_bank_transfer_id IS NOT NULL
    ), scope_transfer_candidate AS (
      SELECT
        direct_scope_transfer.settlement_scope_id,
        direct_scope_transfer.pay_bank_transfer_id
      FROM direct_scope_transfer
      WHERE direct_scope_transfer.pay_bank_transfer_id IS NOT NULL

      UNION

      SELECT
        item_scope_transfer.settlement_scope_id,
        item_scope_transfer.pay_bank_transfer_id
      FROM item_scope_transfer
      WHERE item_scope_transfer.pay_bank_transfer_id IS NOT NULL
    ), resolved_scope_transfer AS (
      SELECT
        scope_transfer_candidate.settlement_scope_id,
        (ARRAY_AGG(scope_transfer_candidate.pay_bank_transfer_id ORDER BY scope_transfer_candidate.pay_bank_transfer_id))[1] AS pay_bank_transfer_id
      FROM scope_transfer_candidate
      GROUP BY scope_transfer_candidate.settlement_scope_id
      HAVING COUNT(*) = 1
    ), ranked_matching_event AS (

      SELECT
        resolved_scope_transfer.settlement_scope_id,
        matching_event.id AS event_id,
        ROW_NUMBER() OVER (
          PARTITION BY resolved_scope_transfer.settlement_scope_id
          ORDER BY
            matching_event.event_time_utc DESC NULLS LAST,
            matching_event.received_at_utc DESC NULLS LAST,
            matching_event.created_at_utc DESC NULLS LAST,
            matching_event.id DESC
        ) AS event_rank
      FROM resolved_scope_transfer
      JOIN public.pay_bank_transfer_events AS matching_event
        ON matching_event.pay_batch_id = p_pay_batch_id
       AND matching_event.pay_bank_transfer_id = resolved_scope_transfer.pay_bank_transfer_id
      WHERE (
          UPPER(BTRIM(COALESCE(matching_event.normalised_state, ''))) IN ('COMPLETED', 'SETTLED', 'PAID', 'SUCCESS', 'SUCCESSFUL', 'SUCCEEDED')
          OR UPPER(BTRIM(COALESCE(matching_event.provider_state, ''))) IN ('COMPLETED', 'SETTLED', 'PAID', 'SUCCESS', 'SUCCESSFUL', 'SUCCEEDED')
        )
        AND (
          matching_event.idempotency_key LIKE
            'rail-settle:' || v_settlement_operation_id::text || ':' || resolved_scope_transfer.settlement_scope_id::text || ':' || resolved_scope_transfer.pay_bank_transfer_id::text || ':%'
          OR (
            NULLIF(BTRIM(COALESCE(matching_event.raw_payload->>'source_rpc', '')), '') = 'pay_settle_rail'
            AND NULLIF(BTRIM(COALESCE(matching_event.raw_payload->>'operation_id', '')), '') = v_settlement_operation_id::text
            AND NULLIF(BTRIM(COALESCE(matching_event.raw_payload->>'settlement_scope_id', '')), '') = resolved_scope_transfer.settlement_scope_id::text
          )
        )
    )
    UPDATE public.banking_pay_operation_settlement_scope AS scope_repair
    SET settlement_event_id = ranked_matching_event.event_id,
        updated_at_utc = v_now
    FROM ranked_matching_event
    WHERE scope_repair.id = ranked_matching_event.settlement_scope_id
      AND ranked_matching_event.event_rank = 1
      AND scope_repair.operation_id = v_settlement_operation_id
      AND scope_repair.pay_batch_id = p_pay_batch_id
      AND scope_repair.status = 'SETTLED'
      AND scope_repair.settlement_event_id IS NULL;
  END IF;

  IF v_settlement_operation_id IS NOT NULL THEN
    SELECT COALESCE(
      JSONB_AGG(settlement_scope_id_row.id::text ORDER BY settlement_scope_id_row.id),
      '[]'::jsonb
    )
    INTO v_settlement_scope_ids
    FROM public.banking_pay_operation_settlement_scope AS settlement_scope_id_row
    WHERE settlement_scope_id_row.operation_id = v_settlement_operation_id
      AND settlement_scope_id_row.pay_batch_id = p_pay_batch_id
      AND UPPER(BTRIM(COALESCE(settlement_scope_id_row.status, ''))) IN ('SETTLED', 'SKIPPED');
  END IF;

  IF COALESCE(v_completed_transfer_count, 0) > 0
     AND v_settlement_operation_id IS NOT NULL
     AND v_settlement_operation_id <> v_execution_operation_id THEN
    SELECT
      COUNT(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) = 'SETTLED'
          AND NOT (
            UPPER(BTRIM(COALESCE(scope_row.payload_json->>'scope_kind', ''))) = 'NO_BANK_PAYMENT'
            AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_reason', ''))) = 'EXPLICIT_ZERO_PAYE'
          )
      )::integer,
      COUNT(DISTINCT COALESCE(
        NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'pay_bank_transfer_id', '')), ''),
        NULLIF(BTRIM(COALESCE(scope_row.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')), '')
      )) FILTER (
        WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) = 'SETTLED'
          AND NOT (
            UPPER(BTRIM(COALESCE(scope_row.payload_json->>'scope_kind', ''))) = 'NO_BANK_PAYMENT'
            AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_reason', ''))) = 'EXPLICIT_ZERO_PAYE'
          )
      )::integer,
      COUNT(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) = 'SETTLED'
          AND NOT (
            UPPER(BTRIM(COALESCE(scope_row.payload_json->>'scope_kind', ''))) = 'NO_BANK_PAYMENT'
            AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_reason', ''))) = 'EXPLICIT_ZERO_PAYE'
          )
          AND scope_row.settlement_event_id IS NULL
      )::integer,
      COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) NOT IN ('SETTLED', 'SKIPPED'))::integer,
      COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) = 'FAILED')::integer,
      COUNT(*) FILTER (
        WHERE v_settlement_mode IN ('CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT')
          AND UPPER(BTRIM(COALESCE(scope_row.status, ''))) = 'SETTLED'
          AND NOT (
            UPPER(BTRIM(COALESCE(scope_row.payload_json->>'scope_kind', ''))) = 'NO_BANK_PAYMENT'
            AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_reason', ''))) = 'EXPLICIT_ZERO_PAYE'
          )
          AND (
            UPPER(BTRIM(COALESCE(scope_row.payload_json->>'scope_kind', ''))) <> 'LOCAL_MANUAL_TRANSFER'
            OR LOWER(BTRIM(COALESCE(scope_row.payload_json->>'local_manual_settlement_scope', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
            OR NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'execution_operation_id', '')), '') <> v_execution_operation_id::text
            OR NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'settlement_operation_id', '')), '') <> v_settlement_operation_id::text
            OR NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'auth_request_id', '')), '') <> v_operation_auth_request_id::text
            OR NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'global_paye_net_state_hash', scope_row.payload_json->>'paye_net_state_hash', '')), '') <> v_expected_paye_net_state_hash
            OR NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'scoped_paye_net_state_hash', '')), '') <> v_expected_scoped_paye_net_state_hash
            OR NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'global_bank_payment_projection_hash', '')), '') <> v_expected_global_bank_payment_projection_hash
            OR NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'scoped_bank_payment_projection_hash', scope_row.payload_json->>'bank_payment_projection_hash', '')), '') <> v_expected_bank_payment_projection_hash
            OR LOWER(BTRIM(COALESCE(scope_row.payload_json->>'submitted_to_bank', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
            OR LOWER(BTRIM(COALESCE(scope_row.payload_json->>'provider_submission_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
            OR LOWER(BTRIM(COALESCE(scope_row.payload_json->>'provider_submission_attempted', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          )
      )::integer
    INTO
      v_settlement_positive_scope_count,
      v_settlement_positive_transfer_count,
      v_settlement_missing_event_count,
      v_settlement_nonterminal_scope_count,
      v_settlement_failed_scope_count,
      v_settlement_local_proof_invalid_count
    FROM public.banking_pay_operation_settlement_scope AS scope_row
    WHERE scope_row.operation_id = v_settlement_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id;

    SELECT COUNT(*)::integer
    INTO v_settlement_unmatched_transfer_count
    FROM pg_temp._tmp_settle_external_completed_transfers AS completed_transfer
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_operation_settlement_scope AS scope_row
      WHERE scope_row.operation_id = v_settlement_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
        AND UPPER(BTRIM(COALESCE(scope_row.status, ''))) = 'SETTLED'
        AND COALESCE(
          NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'pay_bank_transfer_id', '')), ''),
          NULLIF(BTRIM(COALESCE(scope_row.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')), '')
        ) = completed_transfer.transfer_id::text
    );

    SELECT COUNT(*)::integer
    INTO v_settlement_unmatched_scope_transfer_count
    FROM public.banking_pay_operation_settlement_scope AS scope_row
    WHERE scope_row.operation_id = v_settlement_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id
      AND UPPER(BTRIM(COALESCE(scope_row.status, ''))) = 'SETTLED'
      AND NOT (
        UPPER(BTRIM(COALESCE(scope_row.payload_json->>'scope_kind', ''))) = 'NO_BANK_PAYMENT'
        AND UPPER(BTRIM(COALESCE(scope_row.payload_json->>'no_bank_payment_reason', ''))) = 'EXPLICIT_ZERO_PAYE'
      )
      AND NOT EXISTS (
        SELECT 1
        FROM pg_temp._tmp_settle_external_completed_transfers AS completed_transfer
        WHERE completed_transfer.transfer_id::text = COALESCE(
          NULLIF(BTRIM(COALESCE(scope_row.payload_json->>'pay_bank_transfer_id', '')), ''),
          NULLIF(BTRIM(COALESCE(scope_row.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '')), '')
        )
      );

    IF COALESCE(v_settlement_positive_scope_count, 0) = 0
       OR COALESCE(v_settlement_positive_transfer_count, 0) <> COALESCE(v_completed_transfer_count, 0)
       OR COALESCE(v_settlement_missing_event_count, 0) <> 0
       OR COALESCE(v_settlement_nonterminal_scope_count, 0) <> 0
       OR COALESCE(v_settlement_failed_scope_count, 0) <> 0
       OR COALESCE(v_settlement_local_proof_invalid_count, 0) <> 0
       OR COALESCE(v_settlement_unmatched_transfer_count, 0) <> 0
       OR COALESCE(v_settlement_unmatched_scope_transfer_count, 0) <> 0 THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_RAIL',
        'code', 'SETTLEMENT_SCOPE_TRANSFER_PROOF_INCOMPLETE',
        'message', 'Completed transfers and terminal settlement scopes do not form one exact, mode-valid, operation-bound proof set.',
        'pay_batch_id', p_pay_batch_id::text,
        'execution_operation_id', v_execution_operation_id::text,
        'settlement_operation_id', v_settlement_operation_id::text,
        'completed_transfer_count', COALESCE(v_completed_transfer_count, 0),
        'settlement_positive_scope_count', COALESCE(v_settlement_positive_scope_count, 0),
        'settlement_positive_transfer_count', COALESCE(v_settlement_positive_transfer_count, 0),
        'missing_settlement_event_count', COALESCE(v_settlement_missing_event_count, 0),
        'nonterminal_scope_count', COALESCE(v_settlement_nonterminal_scope_count, 0),
        'failed_scope_count', COALESCE(v_settlement_failed_scope_count, 0),
        'local_proof_invalid_count', COALESCE(v_settlement_local_proof_invalid_count, 0),
        'unmatched_completed_transfer_count', COALESCE(v_settlement_unmatched_transfer_count, 0),
        'unmatched_scope_transfer_count', COALESCE(v_settlement_unmatched_scope_transfer_count, 0)
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;

  v_submitted_to_bank := v_settlement_mode = 'STANDARD_BANK' AND COALESCE(v_completed_transfer_count, 0) > 0;

  v_provider_submission_required := v_submitted_to_bank;
  v_provider_submission_attempted := v_submitted_to_bank;
  v_local_settlement_evidence_only := v_settlement_mode IN ('CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT')
    OR v_no_bank_payment_execution_validated;

  IF v_settlement_mode = 'CSV_SETTLEMENT' THEN
    v_bank_confirm_ref := COALESCE(
      NULLIF(BTRIM(COALESCE(v_operation_auth_intent_json->>'csv_bank_confirm_ref', '')), ''),
      NULLIF(BTRIM(COALESCE(v_batch_intent_json->>'csv_bank_confirm_ref', '')), ''),
      NULLIF(BTRIM(COALESCE(v_batch.settlement_confirmation_json->>'bank_confirm_ref', '')), '')
    );
  END IF;

  IF COALESCE(v_completed_transfer_count, 0) > 0
     AND v_settlement_mode IN ('CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT') THEN
    IF v_settlement_operation_id IS NULL THEN
      RAISE EXCEPTION 'PAY_SETTLE_RAIL_LOCAL_SETTLEMENT_OPERATION_REQUIRED' USING ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM pg_temp._tmp_settle_external_completed_transfers AS local_completed_transfer
      JOIN public.pay_bank_transfers AS local_transfer
        ON local_transfer.id = local_completed_transfer.transfer_id
       AND local_transfer.pay_batch_id = p_pay_batch_id
      WHERE NULLIF(BTRIM(COALESCE(local_transfer.request_id, '')), '') IS NOT NULL
         OR NULLIF(BTRIM(COALESCE(local_transfer.rail_tx_id, '')), '') IS NOT NULL
         OR EXISTS (
           SELECT 1
           FROM public.pay_bank_transfer_events AS local_event_conflict
           WHERE local_event_conflict.pay_bank_transfer_id = local_transfer.id
             AND (
               NULLIF(BTRIM(COALESCE(local_event_conflict.provider_request_id, '')), '') IS NOT NULL
               OR NULLIF(BTRIM(COALESCE(local_event_conflict.provider_transaction_id, '')), '') IS NOT NULL
               OR local_event_conflict.provider_webhook_receipt_id IS NOT NULL
               OR NULLIF(BTRIM(COALESCE(local_event_conflict.provider_event_transport, '')), '') IS NOT NULL
               OR NULLIF(BTRIM(COALESCE(local_event_conflict.adapter_key, '')), '') IS NOT NULL
               OR NULLIF(BTRIM(COALESCE(local_event_conflict.adapter_version, '')), '') IS NOT NULL
               OR UPPER(BTRIM(COALESCE(local_event_conflict.event_source, ''))) IN (
                 'PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK', 'WEBHOOK', 'POLL',
                 'RAIL_PROVIDER', 'PROVIDER', 'PROVIDER_SETTLEMENT'
               )
             )
         )
      LIMIT 1
    ) THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_RAIL',
        'code', 'LOCAL_SETTLEMENT_PROVIDER_EVIDENCE_CONFLICT',
        'message', 'CSV/external settlement cannot be finalised from local proof while provider request, transaction, webhook, transport, or adapter evidence exists.',
        'pay_batch_id', p_pay_batch_id::text,
        'execution_operation_id', v_execution_operation_id::text,
        'settlement_operation_id', v_settlement_operation_id::text,
        'settlement_mode', v_settlement_mode
      )::text USING ERRCODE = 'P0001';
    END IF;

    v_local_positive_commit_ref := CASE
      WHEN v_legacy_direct_settlement
        THEN COALESCE(
          NULLIF(BTRIM(COALESCE(v_execution_commit_ref, '')), ''),
          CASE
            WHEN v_settlement_mode = 'CSV_SETTLEMENT' THEN 'CSV_SETTLEMENT:'
            ELSE 'EXTERNAL_SETTLEMENT:'
          END || v_settlement_operation_id::text
        )
      ELSE CASE
        WHEN v_settlement_mode = 'CSV_SETTLEMENT' THEN 'CSV_SETTLEMENT:'
        ELSE 'EXTERNAL_SETTLEMENT:'
      END || v_settlement_operation_id::text
    END;

    IF v_legacy_direct_settlement IS NOT TRUE
       AND NULLIF(BTRIM(COALESCE(v_execution_commit_ref, '')), '') IS NOT NULL
       AND NULLIF(BTRIM(COALESCE(v_execution_commit_ref, '')), '') <> v_local_positive_commit_ref THEN
      RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
        'error', 'PAY_SETTLE_RAIL',
        'code', 'LOCAL_SETTLEMENT_COMMIT_REFERENCE_CONFLICT',
        'message', 'The existing execution commit reference conflicts with the deterministic local settlement proof.',
        'pay_batch_id', p_pay_batch_id::text,
        'settlement_operation_id', v_settlement_operation_id::text,
        'existing_execution_commit_ref', v_execution_commit_ref,
        'expected_execution_commit_ref', v_local_positive_commit_ref
      )::text USING ERRCODE = 'P0001';
    END IF;

    v_execution_commit_ref := v_local_positive_commit_ref;

    UPDATE public.pay_bank_transfers AS local_completed_transfer_update
    SET rail_meta_json = JSONB_STRIP_NULLS(
      COALESCE(local_completed_transfer_update.rail_meta_json, '{}'::jsonb)
      || JSONB_BUILD_OBJECT(
        'execution_mode', v_settlement_mode,
        'settlement_mode', v_settlement_mode,
        'execution_operation_id', v_execution_operation_id::text,
        'manual_settlement_operation_id', v_settlement_operation_id::text,
        'auth_request_id', v_operation_auth_request_id::text,
        'bank_confirm_ref', CASE WHEN v_settlement_mode = 'CSV_SETTLEMENT' THEN v_bank_confirm_ref ELSE NULL::text END,
        'external_settlement_comment', CASE
          WHEN v_settlement_mode = 'EXTERNAL_SETTLEMENT'
            THEN NULLIF(BTRIM(COALESCE(v_operation_auth_intent_json->>'external_settlement_comment', '')), '')
          ELSE NULL::text
        END,
        'submitted_to_bank', false,
        'provider_submission_required', false,
        'provider_submission_attempted', false,
        'local_settlement_evidence_only', true
      )
    )
    WHERE local_completed_transfer_update.pay_batch_id = p_pay_batch_id
      AND EXISTS (
        SELECT 1
        FROM pg_temp._tmp_settle_external_completed_transfers AS completed_transfer_marker
        WHERE completed_transfer_marker.transfer_id = local_completed_transfer_update.id
      );
  END IF;


  select count(distinct pbi_chk.pay_bank_transfer_id)::int
  into v_linked_transfer_ct
  from public.pay_batch_items pbi_chk
  join public.pay_batch_candidates pbc_chk
    on pbc_chk.id = pbi_chk.pay_batch_candidate_id
  where pbc_chk.pay_batch_id = p_pay_batch_id
    and pbi_chk.item_type <> 'DEBT_CREATED'
    and pbi_chk.is_voided = false
    and pbi_chk.pay_bank_transfer_id is not null;

  select exists (
    select 1
    from public.pay_batch_candidates pbc_pos
    where pbc_pos.pay_batch_id = p_pay_batch_id
      and coalesce(pbc_pos.net_bank_amount,0) > 0
    limit 1
  )
  into v_has_pos_net;

  if v_linked_transfer_ct = 0 and v_has_pos_net and v_no_bank_scope_authorised is not true then
    raise exception 'STATE_INCONSISTENT: positive net_bank_amount but no transfers';
  end if;

  create temp table if not exists _tmp_newly_settled_candidates (
    candidate_id uuid primary key
  ) on commit drop;

  truncate table _tmp_newly_settled_candidates;

  with cand_transfers as (
    select
      pbc.candidate_id as candidate_id,
      count(distinct pbi.pay_bank_transfer_id) filter (
        where pbi.item_type <> 'DEBT_CREATED'
          and pbi.is_voided = false
          and pbi.pay_bank_transfer_id is not null
      ) as total_transfers,
      count(distinct pbi.pay_bank_transfer_id) filter (
        where pbi.item_type <> 'DEBT_CREATED'
          and pbi.is_voided = false
          and pbi.pay_bank_transfer_id is not null
          and external_completed_candidate_transfer.transfer_id is not null
      ) as completed_transfers
    from public.pay_batch_candidates pbc
    left join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
    left join public.pay_bank_transfers pbt
      on pbt.id = pbi.pay_bank_transfer_id
     and pbt.pay_batch_id = p_pay_batch_id
    left join pg_temp._tmp_settle_external_completed_transfers as external_completed_candidate_transfer
      on external_completed_candidate_transfer.transfer_id = pbi.pay_bank_transfer_id
    where pbc.pay_batch_id = p_pay_batch_id
    group by pbc.candidate_id
  ),
  eligible as (
    select
      ct.candidate_id
    from cand_transfers ct
    join public.pay_batch_candidates pbc2
      on pbc2.pay_batch_id = p_pay_batch_id
     and pbc2.candidate_id = ct.candidate_id
    where (

        pbc2.settled_at_utc is null
        or (
          upper(btrim(coalesce(v_batch.status, ''))) not in ('SETTLED', 'FAILED')
          and not exists (
            select 1
            from jsonb_array_elements(
              case
                when jsonb_typeof(v_batch.settlement_confirmation_json->'durably_finalised_candidate_ids') = 'array'
                  then v_batch.settlement_confirmation_json->'durably_finalised_candidate_ids'
                else '[]'::jsonb
              end
            ) as finalised_candidate_marker(value)
            where nullif(btrim(coalesce(finalised_candidate_marker.value #>> '{}', '')), '') = pbc2.candidate_id::text
          )
          and (
            (
              v_no_bank_scope_authorised
              and exists (
                select 1
                from pg_temp.tmp_pay_settle_rail_full_eligible_no_bank_scope as no_bank_candidate_scope
                where no_bank_candidate_scope.pay_batch_candidate_id = pbc2.id
              )
            )
            or (
              coalesce(ct.total_transfers, 0) > 0
              and coalesce(ct.total_transfers, 0) = coalesce(ct.completed_transfers, 0)
              and exists (
                select 1
                from public.banking_pay_operation_settlement_scope as operation_candidate_scope
                join public.banking_pay_operations as operation_candidate_settlement
                  on operation_candidate_settlement.id = operation_candidate_scope.operation_id
                 and operation_candidate_settlement.pay_batch_id = p_pay_batch_id
                where operation_candidate_scope.pay_batch_id = p_pay_batch_id
                  and operation_candidate_scope.pay_batch_candidate_id = pbc2.id
                  and operation_candidate_scope.status = 'SETTLED'
                  and operation_candidate_scope.settlement_event_id is not null
                  and (
                    (
                      operation_candidate_settlement.operation_type = 'PAYMENT_EXECUTE'
                      and operation_candidate_settlement.id = v_execution_operation_id
                    )
                    or (
                      operation_candidate_settlement.operation_type = 'PAYMENT_SETTLEMENT'
                      and operation_candidate_settlement.root_operation_id = v_execution_operation_id
                    )
                  )
                  and (
                    operation_candidate_settlement.id = v_execution_operation_id
                    or nullif(btrim(coalesce(
                      operation_candidate_settlement.input_json->>'auth_request_id',
                      operation_candidate_settlement.input_json->>'authRequestId',
                      operation_candidate_settlement.input_json #>> '{execution_intent_json,auth_request_id}',
                      operation_candidate_settlement.input_json #>> '{execution_intent_json,authRequestId}',
                      ''
                    )), '') = v_operation_auth_request_id::text
                  )
                  and lower(btrim(coalesce(operation_candidate_settlement.progress_json->>'requires_full_batch_finalisation', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
                  and lower(btrim(coalesce(operation_candidate_settlement.progress_json->>'full_batch_finalisation_safe', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
                  and lower(btrim(coalesce(operation_candidate_settlement.progress_json->>'all_scopes_terminal', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
                  and lower(btrim(coalesce(operation_candidate_settlement.progress_json->>'all_scopes_successful', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
              )
            )
          )
        )
      )
      and (
        (
          ct.total_transfers = 0
          and (
            (
              v_no_bank_scope_authorised
              and exists (
                select 1
                from pg_temp.tmp_pay_settle_rail_full_eligible_no_bank_scope as zero_candidate_scope
                where zero_candidate_scope.pay_batch_candidate_id = pbc2.id
              )
            )
          )
        )
        or (ct.total_transfers > 0 and ct.total_transfers = ct.completed_transfers)
      )
  )
  insert into _tmp_newly_settled_candidates(candidate_id)
  select e.candidate_id
  from eligible e;

  update public.pay_batch_candidates pbc
  set
    settlement_status = 'SETTLED',
    settled_at_utc = coalesce(pbc.settled_at_utc, v_now),
    settled_via = case
      when v_no_bank_scope_authorised
       and exists (
         select 1
         from pg_temp.tmp_pay_settle_rail_full_eligible_no_bank_scope as no_bank_candidate_scope
         where no_bank_candidate_scope.pay_batch_candidate_id = pbc.id
       )
       and not exists (
         select 1
         from public.pay_batch_items as transfer_backed_candidate_item
         where transfer_backed_candidate_item.pay_batch_candidate_id = pbc.id
           and coalesce(transfer_backed_candidate_item.is_voided, false) = false
           and transfer_backed_candidate_item.pay_bank_transfer_id is not null
       )
       and not exists (
         select 1
         from public.banking_pay_operation_settlement_scope as transfer_backed_candidate_scope
         where transfer_backed_candidate_scope.operation_id = v_no_bank_settlement_operation_id
           and transfer_backed_candidate_scope.pay_batch_id = p_pay_batch_id
           and transfer_backed_candidate_scope.pay_batch_candidate_id = pbc.id
           and transfer_backed_candidate_scope.settlement_event_id is not null
       )
        then 'NO_BANK_PAYMENT'
      else coalesce(
        nullif(btrim(coalesce(pbc.settled_via, '')), ''),
        case
          when v_settlement_mode in ('CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT') then v_settlement_mode
          else upper(coalesce(v_batch.rail_provider_snapshot, 'RAIL'))
        end
      )
    end,
    settled_note = case
      when v_no_bank_scope_authorised
       and exists (
         select 1
         from pg_temp.tmp_pay_settle_rail_full_eligible_no_bank_scope as no_bank_candidate_scope
         where no_bank_candidate_scope.pay_batch_candidate_id = pbc.id
       )
       and not exists (
         select 1
         from public.pay_batch_items as transfer_backed_candidate_item
         where transfer_backed_candidate_item.pay_batch_candidate_id = pbc.id
           and coalesce(transfer_backed_candidate_item.is_voided, false) = false
           and transfer_backed_candidate_item.pay_bank_transfer_id is not null
       )
       and not exists (
         select 1
         from public.banking_pay_operation_settlement_scope as transfer_backed_candidate_scope
         where transfer_backed_candidate_scope.operation_id = v_no_bank_settlement_operation_id
           and transfer_backed_candidate_scope.pay_batch_id = p_pay_batch_id
           and transfer_backed_candidate_scope.pay_batch_candidate_id = pbc.id
           and transfer_backed_candidate_scope.settlement_event_id is not null
       )
        then coalesce(pbc.settled_note, v_local_no_bank_commit_ref)
      else pbc.settled_note
    end
  where pbc.pay_batch_id = p_pay_batch_id
    and pbc.candidate_id in (select t.candidate_id from _tmp_newly_settled_candidates t);

  select coalesce(jsonb_agg(t.candidate_id::text order by t.candidate_id), '[]'::jsonb)
  into v_newly_settled_candidates
  from _tmp_newly_settled_candidates t;

  with existing_finalised_candidate_ids as (
    select distinct finalised_candidate_marker.value #>> '{}' as candidate_id_text
    from jsonb_array_elements(
      case
        when jsonb_typeof(v_batch.settlement_confirmation_json->'durably_finalised_candidate_ids') = 'array'
          then v_batch.settlement_confirmation_json->'durably_finalised_candidate_ids'
        else '[]'::jsonb
      end
    ) as finalised_candidate_marker(value)
    where (finalised_candidate_marker.value #>> '{}')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      and exists (
        select 1
        from public.pay_batch_candidates as existing_finalised_candidate
        where existing_finalised_candidate.pay_batch_id = p_pay_batch_id
          and existing_finalised_candidate.candidate_id::text = finalised_candidate_marker.value #>> '{}'
      )
  ), current_finalised_candidate_ids as (
    select newly_finalised_candidate.candidate_id::text as candidate_id_text
    from pg_temp._tmp_newly_settled_candidates as newly_finalised_candidate
  ), combined_finalised_candidate_ids as (
    select existing_finalised_candidate_ids.candidate_id_text
    from existing_finalised_candidate_ids
    union
    select current_finalised_candidate_ids.candidate_id_text
    from current_finalised_candidate_ids
  )

  select coalesce(
    jsonb_agg(combined_finalised_candidate_ids.candidate_id_text order by combined_finalised_candidate_ids.candidate_id_text),
    '[]'::jsonb
  )
  into v_durably_finalised_candidate_ids
  from combined_finalised_candidate_ids;


  create temp table if not exists _tmp_settle_cache_candidates (
    candidate_id uuid primary key
  ) on commit drop;

  truncate table _tmp_settle_cache_candidates;

  with candidate_transfer_state as (
    select
      pbc.candidate_id as candidate_id,
      bool_or(nsc.candidate_id is not null) as newly_settled_in_this_call,
      bool_or(coalesce(pbc.settled_at_utc, null) is not null or upper(coalesce(pbc.settlement_status, '')) = 'SETTLED') as already_settled_before_cache_rebuild,
      count(distinct pbi.pay_bank_transfer_id) filter (
        where pbi.item_type <> 'DEBT_CREATED'
          and coalesce(pbi.is_voided, false) = false
          and pbi.pay_bank_transfer_id is not null
      ) as total_transfers,
      count(distinct pbi.pay_bank_transfer_id) filter (
        where pbi.item_type <> 'DEBT_CREATED'
          and coalesce(pbi.is_voided, false) = false
          and pbi.pay_bank_transfer_id is not null
          and external_completed_cache_transfer.transfer_id is not null
      ) as completed_transfers
    from public.pay_batch_candidates pbc
    left join _tmp_newly_settled_candidates nsc
      on nsc.candidate_id = pbc.candidate_id
    left join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
    left join pg_temp._tmp_settle_external_completed_transfers as external_completed_cache_transfer
      on external_completed_cache_transfer.transfer_id = pbi.pay_bank_transfer_id
    where pbc.pay_batch_id = p_pay_batch_id
    group by pbc.candidate_id
  ), eligible_cache_candidates as (
    select
      cts.candidate_id
    from candidate_transfer_state cts
    where (cts.newly_settled_in_this_call is true or cts.already_settled_before_cache_rebuild is true)
      and (
        (
          coalesce(cts.total_transfers, 0) = 0
          and (
            (
              v_no_bank_scope_authorised
              and exists (
                select 1
                from pg_temp.tmp_pay_settle_rail_full_eligible_no_bank_scope as zero_cache_scope
                where zero_cache_scope.candidate_id = cts.candidate_id
              )
            )
          )
        )
        or (coalesce(cts.total_transfers, 0) > 0 and coalesce(cts.total_transfers, 0) = coalesce(cts.completed_transfers, 0))
      )
  )
  insert into _tmp_settle_cache_candidates(candidate_id)
  select distinct ecc.candidate_id
  from eligible_cache_candidates ecc
  where ecc.candidate_id is not null;

  SELECT public._pay_manual_adjustment_carry_forward_mark_consumed(
    p_pay_batch_id,
    NULL::uuid[],
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id::text,
      'pay_bank_transfer_ids', COALESCE((
        SELECT jsonb_agg(DISTINCT completed_transfer_rows.transfer_id::text ORDER BY completed_transfer_rows.transfer_id::text)
        FROM pg_temp._tmp_settle_external_completed_transfers AS completed_transfer_rows
      ), '[]'::jsonb),
      'pay_batch_item_ids', COALESCE((
        SELECT jsonb_agg(DISTINCT item_rows.id::text ORDER BY item_rows.id::text)
        FROM public.pay_batch_items AS item_rows
        JOIN public.pay_batch_candidates AS candidate_rows
          ON candidate_rows.id = item_rows.pay_batch_candidate_id
        JOIN pg_temp._tmp_settle_external_completed_transfers AS completed_transfer_rows
          ON completed_transfer_rows.transfer_id = item_rows.pay_bank_transfer_id
        WHERE candidate_rows.pay_batch_id = p_pay_batch_id
      ), '[]'::jsonb)
    ),
    jsonb_build_object('final_paid', true, 'cash_state', 'FINAL_PAID', 'source', 'pay_settle_rail'),
    p_actor_user_id
  )
  INTO v_carry_forward_mark_result;

  v_consumed_carry_forward_count := v_consumed_carry_forward_count + COALESCE(NULLIF(v_carry_forward_mark_result->>'consumed_count', '')::integer, 0);

  with needed_timesheets as (
    select distinct
      pbi.timesheet_id as timesheet_id
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = p_pay_batch_id
      and pbc.candidate_id in (select t.candidate_id from _tmp_settle_cache_candidates t)
      and pbi.item_type <> 'DEBT_CREATED'
      and pbi.is_voided = false
      and pbi.timesheet_id is not null
  ),
  have_snap as (
    select distinct
      pbs.timesheet_id as timesheet_id
    from public.pay_batch_timesheet_snapshots pbs
    where pbs.pay_batch_id = p_pay_batch_id
      and pbs.candidate_id in (select t.candidate_id from _tmp_settle_cache_candidates t)
  ),
  missing as (
    select n.timesheet_id
    from needed_timesheets n
    left join have_snap h
      on h.timesheet_id = n.timesheet_id
    where h.timesheet_id is null
  )
  select coalesce(jsonb_agg(m.timesheet_id::text order by m.timesheet_id), '[]'::jsonb)
  into v_missing_timesheets
  from missing m;

  if jsonb_array_length(v_missing_timesheets) > 0 then
    raise exception 'pay_settle_rail: MISSING_FROZEN_SNAPSHOTS for timesheets %', v_missing_timesheets::text;
  end if;

  with snap as (
    select
      pbs.timesheet_id,
      pbs.target_snapshot_json
    from public.pay_batch_timesheet_snapshots pbs
    where pbs.pay_batch_id = p_pay_batch_id
      and pbs.candidate_id in (select t.candidate_id from _tmp_settle_cache_candidates t)
  ),
  ambig as (
    select
      s.timesheet_id
    from snap s
    group by s.timesheet_id
    having count(distinct s.target_snapshot_json) > 1
  )
  select coalesce(jsonb_agg(a.timesheet_id::text order by a.timesheet_id), '[]'::jsonb)
  into v_ambig_timesheets
  from ambig a;

  if jsonb_array_length(v_ambig_timesheets) > 0 then
    raise exception 'pay_settle_rail: AMBIGUOUS_TARGET_SNAPSHOT for timesheets %', v_ambig_timesheets::text;
  end if;

  with chosen as (
    select distinct on (pbs.timesheet_id)
      pbs.timesheet_id,
      pbs.target_snapshot_json,
      pbs.signature
    from public.pay_batch_timesheet_snapshots pbs
    where pbs.pay_batch_id = p_pay_batch_id
      and pbs.candidate_id in (select t.candidate_id from _tmp_settle_cache_candidates t)
    order by pbs.timesheet_id, pbs.created_at_utc desc, pbs.id
  )
  insert into public.timesheet_pay_state_history(
    timesheet_id,
    pay_batch_id,
    settled_at_utc,
    snapshot_json,
    signature
  )
  select
    c.timesheet_id,
    p_pay_batch_id,
    v_now,
    c.target_snapshot_json,
    c.signature
  from chosen c
  where not exists (
    select 1
    from public.timesheet_pay_state_history existing_history
    where existing_history.timesheet_id = c.timesheet_id
      and existing_history.pay_batch_id = p_pay_batch_id
  );


  with chosen as (
    select distinct on (pbs.timesheet_id)
      pbs.timesheet_id,
      pbs.target_snapshot_json,
      pbs.signature
    from public.pay_batch_timesheet_snapshots pbs
    where pbs.pay_batch_id = p_pay_batch_id
      and pbs.candidate_id in (select t.candidate_id from _tmp_settle_cache_candidates t)
    order by pbs.timesheet_id, pbs.created_at_utc desc, pbs.id
  ),
  affected_ids as (
    select coalesce(array_agg(distinct chosen.timesheet_id order by chosen.timesheet_id), array[]::uuid[]) as timesheet_ids
    from chosen
  ),
  outstanding_components as (
    select
      oc.timesheet_id,
      oc.truth_ex_vat,
      oc.baseline_ex_vat,
      oc.reserved_ex_vat,
      oc.outstanding_ex_vat
    from affected_ids
    cross join lateral public._pay_outstanding_components(affected_ids.timesheet_ids, p_pay_batch_id) oc
  ),
  summary_calc as (
    select
      c.timesheet_id,
      round(coalesce(sum(coalesce(oc.truth_ex_vat, 0) - coalesce(oc.baseline_ex_vat, 0)), 0), 2)::numeric(12,2) as summary_net_delta_ex_vat,
      round(coalesce(sum(coalesce(oc.reserved_ex_vat, 0)), 0), 2)::numeric(12,2) as summary_reserved_ex_vat,
      round(coalesce(sum(coalesce(oc.outstanding_ex_vat, 0)), 0), 2)::numeric(12,2) as summary_outstanding_ex_vat
    from chosen c
    left join outstanding_components oc
      on oc.timesheet_id = c.timesheet_id
    group by c.timesheet_id
  ),
  summary_display as (
    select
      c.timesheet_id,
      c.target_snapshot_json,
      c.signature,
      coalesce(sc.summary_net_delta_ex_vat, 0)::numeric(12,2) as summary_net_delta_ex_vat,
      coalesce(sc.summary_reserved_ex_vat, 0)::numeric(12,2) as summary_reserved_ex_vat,
      coalesce(sc.summary_outstanding_ex_vat, 0)::numeric(12,2) as summary_outstanding_ex_vat,
      case
        when coalesce(sc.summary_outstanding_ex_vat, 0) > 0 then 'PARTIALLY_PAID'
        when coalesce(sc.summary_reserved_ex_vat, 0) > 0 then 'PROCESSING'
        else 'PAID'
      end as summary_pay_status_code,
      case
        when coalesce(sc.summary_net_delta_ex_vat, 0) < -0.01 then 'RED_COIN'
        when coalesce(sc.summary_outstanding_ex_vat, 0) > 0 then 'HALF_COIN'
        when coalesce(sc.summary_reserved_ex_vat, 0) > 0 then 'CLOCK'
        else 'COIN'
      end as summary_pay_icon_code
    from chosen c
    left join summary_calc sc
      on sc.timesheet_id = c.timesheet_id
  )
  insert into public.timesheet_pay_state(
    timesheet_id,
    last_settled_snapshot_json,
    last_settled_signature,
    last_settled_pay_batch_id,
    last_settled_at_utc,
    summary_pay_status_code,
    summary_pay_icon_code,
    summary_pay_paid_at_utc,
    summary_net_delta_ex_vat
  )
  select
    sd.timesheet_id,
    sd.target_snapshot_json,
    sd.signature,
    p_pay_batch_id,
    v_now,
    sd.summary_pay_status_code,
    sd.summary_pay_icon_code,
    v_now,
    sd.summary_net_delta_ex_vat
  from summary_display sd
  on conflict (timesheet_id) do update
  set
    last_settled_snapshot_json = excluded.last_settled_snapshot_json,
    last_settled_signature = excluded.last_settled_signature,
    last_settled_pay_batch_id = excluded.last_settled_pay_batch_id,
    last_settled_at_utc = excluded.last_settled_at_utc,
    summary_pay_status_code = excluded.summary_pay_status_code,
    summary_pay_icon_code = excluded.summary_pay_icon_code,
    summary_pay_paid_at_utc = excluded.summary_pay_paid_at_utc,
    summary_net_delta_ex_vat = excluded.summary_net_delta_ex_vat;

  -- Operation-mode settlement deliberately leaves finance reservations RESERVED
  -- until every frozen settlement scope for the candidate is terminal.  Commit any
  -- such reservations here, immediately before the existing atomic settlement
  -- transition, so component and case balances are finalised from the same frozen
  -- batch artifacts.  Legacy/manual paths that already committed reservations are
  -- unaffected.
  with newly_committed_reservations as (
    update public.pay_advance_reservations par
    set
      status = 'COMMITTED',
      committed_at_utc = coalesce(par.committed_at_utc, v_now),
      updated_by_user_id = p_actor_user_id
    from public.pay_batch_items pbi,
         public.pay_batch_candidates pbc
    where par.pay_batch_id = p_pay_batch_id
      and par.pay_batch_item_id = pbi.id
      and pbc.id = pbi.pay_batch_candidate_id
      and pbc.pay_batch_id = p_pay_batch_id
      and pbc.candidate_id in (select t.candidate_id from _tmp_newly_settled_candidates t)
      and upper(coalesce(par.status,'')) = 'RESERVED'
      and par.released_at_utc is null
      and par.settled_at_utc is null
    returning
      par.finance_case_id,
      par.finance_component_id,
      par.id as reservation_id,
      par.committed_at_utc
  )
  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    reservation_id,
    before_json,
    after_json,
    reason,
    note
  )
  select
    committed_reservation.finance_case_id,
    committed_reservation.finance_component_id,
    'RESERVATION_COMMITTED',
    v_now,
    p_actor_user_id,
    p_pay_batch_id,
    committed_reservation.reservation_id,
    jsonb_build_object('reservation_status', 'RESERVED'),
    jsonb_build_object(
      'reservation_status', 'COMMITTED',
      'committed_at_utc', committed_reservation.committed_at_utc::text,
      'commit_stage', 'FULL_BATCH_SETTLEMENT_FINALISATION'
    ),
    'rail_settlement_commit',
    null
  from newly_committed_reservations committed_reservation;

  update public.pay_advance_reservations par
  set
    status = 'SETTLED',
    settled_at_utc = coalesce(par.settled_at_utc, v_now),
    updated_by_user_id = p_actor_user_id
  from public.pay_batch_items pbi,
       public.pay_batch_candidates pbc
  where par.pay_batch_id = p_pay_batch_id
    and par.pay_batch_item_id = pbi.id
    and pbc.id = pbi.pay_batch_candidate_id
    and pbc.pay_batch_id = p_pay_batch_id
    and pbc.candidate_id in (select t.candidate_id from _tmp_newly_settled_candidates t)
    and upper(coalesce(par.status,'')) = 'COMMITTED';

  create temp table if not exists _tmp_component_settle (
    finance_component_id uuid not null primary key,
    finance_case_id uuid null,
    settled_source_amount numeric not null
  ) on commit drop;

  truncate table _tmp_component_settle;

  create temp table if not exists _tmp_component_settle_source (
    finance_component_id uuid null,
    finance_case_id uuid null,
    pay_batch_item_id uuid not null,
    reservation_id uuid null,
    frozen_component_key_type text null,
    frozen_component_key_value text null,
    settled_source_amount numeric not null

  ) on commit drop;

  truncate table _tmp_component_settle_source;

  create temp table if not exists _tmp_component_settle_unresolved (
    pay_batch_id uuid not null,
    pay_batch_item_id uuid not null,
    reservation_id uuid null,
    finance_case_id uuid null,
    frozen_component_key_type text null,
    frozen_component_key_value text null,
    affected_source_amount numeric not null,
    reason_code text not null
  ) on commit drop;

  truncate table _tmp_component_settle_unresolved;

  insert into _tmp_component_settle_source(
    finance_component_id,
    finance_case_id,
    pay_batch_item_id,
    reservation_id,
    frozen_component_key_type,
    frozen_component_key_value,
    settled_source_amount
  )
  select
    coalesce(
      par.finance_component_id,
      pbi.finance_component_id
    ) as finance_component_id,
    coalesce(
      par.finance_case_id,
      pbi.finance_case_id
    ) as finance_case_id,
    pbi.id as pay_batch_item_id,
    par.id as reservation_id,
    nullif(
      btrim(
        coalesce(
          par.frozen_component_key_type,
          pbi.frozen_component_key_type,
          par.frozen_component_snapshot_json->>'component_key_type',
          pbi.frozen_component_snapshot_json->>'component_key_type',
          ''
        )
      ),
      ''
    ) as frozen_component_key_type,
    nullif(
      btrim(
        coalesce(
          par.frozen_component_key_value,
          pbi.frozen_component_key_value,
          par.frozen_component_snapshot_json->>'component_key_value',
          pbi.frozen_component_snapshot_json->>'component_key_value',
          ''
        )
      ),
      ''
    ) as frozen_component_key_value,
    round(
      sum(
        coalesce(
          par.reserved_source_amount,
          pbi.frozen_source_amount,
          abs(coalesce(pbi.amount_ex_vat, pbi.amount_inc_vat, par.reserved_amount, 0))
        )
      ),
      2
    ) as settled_source_amount
  from public.pay_advance_reservations par
  join public.pay_batch_items pbi
    on pbi.id = par.pay_batch_item_id
  join public.pay_batch_candidates pbc
    on pbc.id = pbi.pay_batch_candidate_id
   and pbc.pay_batch_id = p_pay_batch_id
  where par.pay_batch_id = p_pay_batch_id
    and upper(coalesce(par.status,'')) = 'SETTLED'
    and par.settled_at_utc = v_now
    and pbc.candidate_id in (select t.candidate_id from _tmp_newly_settled_candidates t)
  group by
    coalesce(
      par.finance_component_id,
      pbi.finance_component_id
    ),
    coalesce(
      par.finance_case_id,
      pbi.finance_case_id
    ),
    pbi.id,
    par.id,
    nullif(
      btrim(
        coalesce(
          par.frozen_component_key_type,
          pbi.frozen_component_key_type,
          par.frozen_component_snapshot_json->>'component_key_type',
          pbi.frozen_component_snapshot_json->>'component_key_type',
          ''
        )
      ),
      ''
    ),
    nullif(
      btrim(
        coalesce(
          par.frozen_component_key_value,
          pbi.frozen_component_key_value,
          par.frozen_component_snapshot_json->>'component_key_value',
          pbi.frozen_component_snapshot_json->>'component_key_value',
          ''
        )
      ),
      ''
    )
  having round(
    sum(
      coalesce(
        par.reserved_source_amount,
        pbi.frozen_source_amount,
        abs(coalesce(pbi.amount_ex_vat, pbi.amount_inc_vat, par.reserved_amount, 0))
      )
    ),
    2
  ) > 0;

  insert into _tmp_component_settle(finance_component_id, finance_case_id, settled_source_amount)
  select
    component_source.finance_component_id,
    component_source.finance_case_id,
    round(sum(component_source.settled_source_amount), 2) as settled_source_amount
  from _tmp_component_settle_source as component_source
  where component_source.finance_component_id is not null
    and component_source.settled_source_amount > 0
  group by component_source.finance_component_id,
           component_source.finance_case_id
  having round(sum(component_source.settled_source_amount), 2) > 0;

  insert into _tmp_component_settle_unresolved(
    pay_batch_id,
    pay_batch_item_id,
    reservation_id,
    finance_case_id,
    frozen_component_key_type,
    frozen_component_key_value,
    affected_source_amount,
    reason_code
  )
  select
    p_pay_batch_id,
    component_source.pay_batch_item_id,
    component_source.reservation_id,
    component_source.finance_case_id,
    component_source.frozen_component_key_type,
    component_source.frozen_component_key_value,
    component_source.settled_source_amount,
    'SETTLEMENT_COMPONENT_ID_MISSING_FROM_FROZEN_ARTIFACT'
  from _tmp_component_settle_source as component_source
  where component_source.finance_component_id is null
    and component_source.settled_source_amount > 0;

  select
    count(*)::int,
    round(coalesce(sum(component_unresolved.affected_source_amount), 0), 2),
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'reason_code', component_unresolved.reason_code,
          'pay_batch_id', component_unresolved.pay_batch_id::text,
          'pay_batch_item_id', component_unresolved.pay_batch_item_id::text,
          'reservation_id', case when component_unresolved.reservation_id is null then null else component_unresolved.reservation_id::text end,
          'finance_case_id', case when component_unresolved.finance_case_id is null then null else component_unresolved.finance_case_id::text end,
          'frozen_component_key_type', component_unresolved.frozen_component_key_type,
          'frozen_component_key_value', component_unresolved.frozen_component_key_value,
          'affected_source_amount', component_unresolved.affected_source_amount
        )
        order by component_unresolved.pay_batch_item_id::text,
                 component_unresolved.reservation_id::text
      ),

      '[]'::jsonb
    )
  into
    v_component_unresolved_count,
    v_component_unresolved_amount,
    v_component_unresolved_json
  from _tmp_component_settle_unresolved as component_unresolved;

  create temp table if not exists _tmp_component_settle_apply (
    finance_component_id uuid not null primary key,
    finance_case_id uuid null,
    classification public.pay_finance_component_classification_enum not null,
    settled_source_amount numeric not null,
    remaining_before numeric not null,
    remaining_after numeric not null
  ) on commit drop;

  truncate table _tmp_component_settle_apply;

  insert into _tmp_component_settle_apply(
    finance_component_id,
    finance_case_id,
    classification,
    settled_source_amount,
    remaining_before,
    remaining_after
  )
  select
    pfc.id,
    pfc.finance_case_id,
    pfc.classification,
    tcs.settled_source_amount,
    round(coalesce(pfc.remaining_source_amount, 0), 2) as remaining_before,
    round(greatest(coalesce(pfc.remaining_source_amount, 0) - coalesce(tcs.settled_source_amount, 0), 0), 2) as remaining_after
  from _tmp_component_settle tcs
  join public.pay_finance_case_components pfc
    on pfc.id = tcs.finance_component_id;

  update public.pay_finance_case_components pfc
  set
    remaining_source_amount = csa.remaining_after,
    resolved_at_utc = case
      when csa.remaining_after <= 0 then coalesce(pfc.resolved_at_utc, v_now)
      else pfc.resolved_at_utc
    end,
    updated_at_utc = v_now
  from _tmp_component_settle_apply csa
  where pfc.id = csa.finance_component_id;

  select
    count(*)::int,
    round(coalesce(sum(csa.settled_source_amount), 0), 2)
  into
    v_component_settled_count,
    v_component_settled_amount
  from _tmp_component_settle_apply csa;

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    reservation_id,
    before_json,
    after_json,
    reason,
    note
  )
  select
    csa.finance_case_id,
    csa.finance_component_id,
    'COMPONENT_SETTLED',
    v_now,
    p_actor_user_id,
    p_pay_batch_id,
    null::uuid,
    jsonb_build_object(
      'remaining_source_amount', csa.remaining_before
    ),
    jsonb_build_object(
      'remaining_source_amount', csa.remaining_after,
      'settled_source_amount', csa.settled_source_amount,
      'classification', csa.classification::text
    ),
    'rail_settlement',
    null
  from _tmp_component_settle_apply csa;

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    reservation_id,
    before_json,
    after_json,
    reason,
    note
  )
  select
    par.finance_case_id,
    par.finance_component_id,
    'RESERVATION_SETTLED',
    v_now,
    p_actor_user_id,
    p_pay_batch_id,
    par.id,
    jsonb_build_object('reservation_status', 'COMMITTED'),
    jsonb_build_object('reservation_status', 'SETTLED', 'settled_at_utc', v_now::text),
    'rail_settlement',
    null
  from public.pay_advance_reservations par
  where par.pay_batch_id = p_pay_batch_id
    and upper(coalesce(par.status,'')) = 'SETTLED'
    and par.settled_at_utc = v_now;

  create temp table if not exists _tmp_repay_taken (
    finance_case_id uuid not null,
    repayment_week_start date null,
    item_type text not null,
    taken_amount numeric not null
  ) on commit drop;

  truncate table _tmp_repay_taken;

  insert into _tmp_repay_taken(finance_case_id, repayment_week_start, item_type, taken_amount)
  select
    coalesce(
      pbi.finance_case_id,
      nullif(btrim(split_part(coalesce(pbi.source_ref,''), ':', 2)),'')::uuid
    ) as finance_case_id,
    pbi.repayment_week_start,
    pbi.item_type,
    round(
      sum(
        abs(
          coalesce(
            pbi.frozen_source_amount,
            pbi.amount_ex_vat,
            pbi.amount_inc_vat,
            0
          )
        )
      ),
      2
    ) as taken_amount
  from public.pay_batch_items pbi
  join public.pay_batch_candidates pbc
    on pbc.id = pbi.pay_batch_candidate_id
  where pbc.pay_batch_id = p_pay_batch_id
    and pbc.candidate_id in (select t.candidate_id from _tmp_newly_settled_candidates t)
    and pbi.is_voided = false
    and pbi.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY','UNDERPAYMENT_PAYMENT')
    and coalesce(
      pbi.finance_case_id,
      nullif(btrim(split_part(coalesce(pbi.source_ref,''), ':', 2)),'')::uuid
    ) is not null
  group by
    coalesce(
      pbi.finance_case_id,
      nullif(btrim(split_part(coalesce(pbi.source_ref,''), ':', 2)),'')::uuid
    ),
    pbi.repayment_week_start,
    pbi.item_type
  having round(
    sum(
      abs(
        coalesce(
          pbi.frozen_source_amount,
          pbi.amount_ex_vat,
          pbi.amount_inc_vat,
          0
        )
      )
    ),
    2

  ) > 0;

  for v_adv_id in
    select distinct trt.finance_case_id
    from _tmp_repay_taken trt
    where trt.finance_case_id is not null
  loop
    select
      pa.schedule_json,
      pa.outstanding_amount,
      pa.next_due_week_start,
      pa.case_type,
      pa.minimum_earnings_threshold,
      pa.take_home_floor_override,
      (pa.cleared_at_utc is not null) as was_cleared
    into
      v_old_sched,
      v_old_out,
      v_old_next,
      v_case_type,
      v_min_earnings_threshold,
      v_take_home_floor_override,
      v_was_cleared
    from public.pay_advances pa
    where pa.id = v_adv_id
    for update;

    if v_old_sched is null then
      v_old_sched := '[]'::jsonb;
    end if;

    select round(coalesce(sum(trt.taken_amount),0),2)
    into v_total_taken
    from _tmp_repay_taken trt
    where trt.finance_case_id = v_adv_id;

    v_new_out := round(greatest(coalesce(v_old_out,0) - coalesce(v_total_taken,0), 0), 2);

    /*
      Componentised cases use their open component ledger as the settlement
      authority.  The case-level outstanding value can be a current-run due
      rather than the whole residual, especially after a cross-pay-method
      resolution.  Rebuild the post-settlement case balance from the already
      updated source-side components so a partial recovery leaves the true
      residual instead of clearing the case.
    */
    if exists (
      select 1
      from public.pay_finance_case_components pfc_any
      where pfc_any.finance_case_id = v_adv_id
      limit 1
    ) then
      select round(
        coalesce(
          sum(coalesce(pfc_open.remaining_source_amount, 0))
            filter (where pfc_open.closed_at_utc is null),
          0
        ),
        2
      )
      into v_new_out
      from public.pay_finance_case_components pfc_open
      where pfc_open.finance_case_id = v_adv_id;
    end if;

    if v_case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum
       or v_case_type = 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum then
      with taken_map as (
        select
          trt.repayment_week_start as week_start,
          round(sum(trt.taken_amount),2) as taken_amount
        from _tmp_repay_taken trt
        where trt.finance_case_id = v_adv_id
        group by trt.repayment_week_start
      ),
      expanded as (
        select
          e.elem as elem,
          nullif(e.elem->>'week_start','')::date as wk,
          coalesce(nullif(e.elem->>'amount','')::numeric,0) as amt
        from jsonb_array_elements(coalesce(v_old_sched,'[]'::jsonb)) e(elem)
      ),
      rewritten as (
        select
          case
            when em.wk is not null
             and tm.week_start is not null
             and em.wk = tm.week_start
             and em.amt < 0
            then jsonb_set(
              em.elem,
              '{amount}',
              to_jsonb(round(em.amt + tm.taken_amount, 2)),
              true
            )
            else em.elem
          end as elem
        from expanded em
        left join taken_map tm
          on tm.week_start = em.wk
      )
      select coalesce(jsonb_agg(r.elem), '[]'::jsonb)
      into v_new_sched
      from rewritten r;

      with expanded2 as (
        select
          nullif(e2.elem->>'week_start','')::date as wk,
          coalesce(nullif(e2.elem->>'amount','')::numeric,0) as amt
        from jsonb_array_elements(coalesce(v_new_sched,'[]'::jsonb)) e2(elem)
      )
      select min(ex2.wk)
      into v_new_next
      from expanded2 ex2
      where ex2.wk is not null
        and ex2.amt < 0;
    else
      v_new_sched := v_old_sched;
      v_new_next := v_old_next;
    end if;

    select exists (
      select 1
      from public.pay_item_snoozes pis
      where v_today_uk is not null
        and pis.cleared_at_utc is null
        and pis.cancelled_at_utc is null
        and pis.source_ref = ('advance:' || v_adv_id::text)
        and (
          pis.snooze_until_date is null
          or pis.snooze_until_date >= v_today_uk
        )
      limit 1
    )
    into v_snooze_active;

    IF COALESCE(v_snooze_active, false) THEN
      v_active_snooze_report_count := COALESCE(v_active_snooze_report_count, 0) + 1;
      IF jsonb_array_length(COALESCE(v_active_snooze_report_sample, '[]'::jsonb)) < 25 THEN
        v_active_snooze_report_sample := COALESCE(v_active_snooze_report_sample, '[]'::jsonb) || jsonb_build_array(
          jsonb_strip_nulls(jsonb_build_object(
            'finance_case_id', v_adv_id::text,
            'source_ref', 'advance:' || v_adv_id::text,
            'finance_case_type', v_case_type::text,
            'active_as_of_london_date', v_today_uk::text,
            'reporting_effect_only', true,
            'frozen_settlement_authority_unchanged', true
          ))
        );
      END IF;
    END IF;

    if v_case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum
       or v_case_type = 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum then
      insert into public.pay_finance_case_events(
        finance_case_id,
        event_type,
        event_at_utc,
        actor_user_id,
        pay_batch_id,
        reservation_id,
        before_json,
        after_json,
        reason,
        note
      )
      select
        v_adv_id,
        'RECOVERY_SHORTFALL',
        v_now,
        p_actor_user_id,
        p_pay_batch_id,
        null::uuid,
        jsonb_build_object(
          'week_start', exp.week_start::text,
          'scheduled_due_amount', exp.expected_due,
          'taken_amount', coalesce(tkn.taken_amount,0)
        ),
        jsonb_build_object(
          'week_start', exp.week_start::text,

          'scheduled_due_amount', exp.expected_due,
          'taken_amount', coalesce(tkn.taken_amount,0),
          'remaining_due_amount', round(greatest(exp.expected_due - coalesce(tkn.taken_amount,0),0),2)
        ),
        case
          when v_snooze_active then 'SNOOZED'
          when coalesce(v_take_home_floor_override,0) > 0 then 'MIN_TAKE_HOME_FLOOR'
          when coalesce(v_min_earnings_threshold,0) > 0 then 'INSUFFICIENT_EARNINGS'
          else 'INSUFFICIENT_EARNINGS'
        end,
        null
      from (
        select
          nullif(elem->>'week_start','')::date as week_start,
          abs(coalesce(nullif(elem->>'amount','')::numeric,0)) as expected_due
        from jsonb_array_elements(coalesce(v_old_sched,'[]'::jsonb)) elem
        where nullif(elem->>'week_start','') is not null
          and coalesce(nullif(elem->>'amount','')::numeric,0) < 0
      ) exp
      left join (
        select trt.repayment_week_start as week_start, round(sum(trt.taken_amount),2) as taken_amount
        from _tmp_repay_taken trt
        where trt.finance_case_id = v_adv_id
        group by trt.repayment_week_start
      ) tkn
        on tkn.week_start = exp.week_start
      where round(greatest(exp.expected_due - coalesce(tkn.taken_amount,0),0),2) > 0;
    end if;

    update public.pay_advances pa2
    set
      schedule_json = coalesce(v_new_sched,'[]'::jsonb),
      outstanding_amount = v_new_out,
      next_due_week_start = v_new_next,
      status = case
        when v_case_type in ('PAYMENT_ADVANCE'::public.pay_finance_case_type_enum, 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum, 'OVERPAYMENT'::public.pay_finance_case_type_enum, 'UNDERPAYMENT'::public.pay_finance_case_type_enum)
             and v_new_out <= 0 then 'PAID_OFF'::public.pay_advance_status_enum
        else pa2.status
      end,
      cleared_at_utc = case
        when v_case_type in ('PAYMENT_ADVANCE'::public.pay_finance_case_type_enum, 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum, 'OVERPAYMENT'::public.pay_finance_case_type_enum, 'UNDERPAYMENT'::public.pay_finance_case_type_enum)
             and v_new_out <= 0 then coalesce(pa2.cleared_at_utc, v_now)
        else pa2.cleared_at_utc
      end,
      cleared_by_user_id = case
        when v_case_type in ('PAYMENT_ADVANCE'::public.pay_finance_case_type_enum, 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum, 'OVERPAYMENT'::public.pay_finance_case_type_enum, 'UNDERPAYMENT'::public.pay_finance_case_type_enum)
             and v_new_out <= 0 then coalesce(pa2.cleared_by_user_id, p_actor_user_id)
        else pa2.cleared_by_user_id
      end,
      updated_at = v_now
    where pa2.id = v_adv_id;

    insert into public.pay_advance_patches(
      advance_id,
      pay_batch_id,
      old_outstanding_amount,
      new_outstanding_amount,
      old_schedule_json,
      new_schedule_json,
      old_next_due_week_start,
      new_next_due_week_start
    )
    values (
      v_adv_id,
      p_pay_batch_id,
      v_old_out,
      v_new_out,
      v_old_sched,
      v_new_sched,
      v_old_next,
      v_new_next
    );

    insert into public.pay_finance_case_events(
      finance_case_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    values (
      v_adv_id,
      'RECOVERY_SETTLED',
      v_now,
      p_actor_user_id,
      p_pay_batch_id,
      null::uuid,
      jsonb_build_object(
        'outstanding_amount', v_old_out,
        'next_due_week_start', case when v_old_next is null then null else v_old_next::text end,
        'schedule_json', v_old_sched
      ),
      jsonb_build_object(
        'outstanding_amount', v_new_out,
        'next_due_week_start', case when v_new_next is null then null else v_new_next::text end,
        'schedule_json', v_new_sched,
        'taken_amount', v_total_taken,
        'case_type', v_case_type::text
      ),
      'rail_settlement',
      null
    );

    if v_new_out <= 0 then
      insert into public.pay_finance_case_events(
        finance_case_id,
        event_type,
        event_at_utc,
        actor_user_id,
        pay_batch_id,
        reservation_id,
        before_json,
        after_json,
        reason,
        note
      )
      values (
        v_adv_id,
        'CASE_CLEARED',
        v_now,
        p_actor_user_id,
        p_pay_batch_id,
        null::uuid,
        jsonb_build_object(
          'outstanding_amount', v_old_out,
          'was_cleared', v_was_cleared
        ),
        jsonb_build_object(
          'outstanding_amount', v_new_out,
          'cleared_at_utc', v_now::text,
          'cleared_by_user_id', p_actor_user_id::text
        ),
        'rail_settlement',
        null
      );
    end if;

    if v_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then
      v_overpay_patched_ct := v_overpay_patched_ct + 1;
    elsif v_case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum then
      v_payment_advance_recovery_patched_ct := v_payment_advance_recovery_patched_ct + 1;
    elsif v_case_type = 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum then
      v_manual_debt_patched_ct := v_manual_debt_patched_ct + 1;
    end if;
  end loop;

  with affected_component_cases as (
    select distinct csa.finance_case_id
    from _tmp_component_settle_apply csa
    where csa.finance_case_id is not null
    union
    select distinct trt.finance_case_id
    from _tmp_repay_taken trt
    where trt.finance_case_id is not null
      and exists (
        select 1
        from public.pay_finance_case_components pfc_exists
        where pfc_exists.finance_case_id = trt.finance_case_id
        limit 1
      )
  ),
  reconciled_component_cases as (
    select
      afc.finance_case_id,
      round(coalesce(pa.outstanding_amount, 0), 2) as case_outstanding_amount,
      round(coalesce(sum(coalesce(pfc.remaining_source_amount, 0)), 0), 2) as open_component_remaining_source_amount,
      count(pfc.id)::int as open_component_count
    from affected_component_cases afc
    join public.pay_advances pa
      on pa.id = afc.finance_case_id
    left join public.pay_finance_case_components pfc
      on pfc.finance_case_id = afc.finance_case_id
     and pfc.closed_at_utc is null
    where exists (
      select 1

      from public.pay_finance_case_components pfc_any
      where pfc_any.finance_case_id = afc.finance_case_id
      limit 1
    )
    group by
      afc.finance_case_id,
      pa.outstanding_amount
  ),
  reconciliation_bad as (
    select
      rcc.finance_case_id,
      rcc.case_outstanding_amount,
      rcc.open_component_remaining_source_amount,
      rcc.open_component_count,
      round(rcc.case_outstanding_amount - rcc.open_component_remaining_source_amount, 2) as mismatch_amount
    from reconciled_component_cases rcc
    where abs(round(rcc.case_outstanding_amount - rcc.open_component_remaining_source_amount, 2)) > 0.01
      and not exists (
        select 1
        from _tmp_component_settle_unresolved component_unresolved
        where component_unresolved.finance_case_id = rcc.finance_case_id
      )
  )
  select
    (select count(*)::int from reconciled_component_cases),
    count(*)::int,
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'finance_case_id', reconciliation_bad.finance_case_id::text,
          'case_outstanding_amount', reconciliation_bad.case_outstanding_amount,
          'open_component_remaining_source_amount', reconciliation_bad.open_component_remaining_source_amount,
          'open_component_count', reconciliation_bad.open_component_count,
          'mismatch_amount', reconciliation_bad.mismatch_amount
        )
        order by reconciliation_bad.finance_case_id::text
      ),
      '[]'::jsonb
    )
  into
    v_component_reconciliation_checked_ct,
    v_component_reconciliation_bad_ct,
    v_component_reconciliation_bad
  from reconciliation_bad;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_SETTLE_RAIL:COMPONENT_RECONCILIATION_RESULT',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'checked_count', coalesce(v_component_reconciliation_checked_ct, 0),
        'mismatch_count', coalesce(v_component_reconciliation_bad_ct, 0),
        'mismatches', v_component_reconciliation_bad,
        'component_id_missing_from_frozen_artifact_count', coalesce(v_component_unresolved_count, 0),
        'component_id_missing_from_frozen_artifact_amount', coalesce(v_component_unresolved_amount, 0),
        'component_id_missing_from_frozen_artifact', coalesce(v_component_unresolved_json, '[]'::jsonb)
      ),
      'pay_batches',
      p_pay_batch_id::text,
      null,
      null,
      null,
      null
    );
  exception when others then
    null;
  end;

  if coalesce(v_component_reconciliation_bad_ct, 0) > 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_RAIL_COMPONENT_RECONCILIATION_MISMATCH',
      'pay_batch_id', p_pay_batch_id::text,
      'message', 'Finance case outstanding amount does not reconcile to open component remaining_source_amount after settlement.',
      'mismatches', v_component_reconciliation_bad
    )::text;
  end if;


  with payouts as (
    select distinct
      coalesce(
        pbi.finance_case_id,
        nullif(btrim(replace(coalesce(pbi.source_ref,''), 'advance:', '')),'')::uuid
      ) as finance_case_id,
      pbi.pay_bank_transfer_id as transfer_id,
      pbi.item_type
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join public.pay_bank_transfers pbt
      on pbt.id = pbi.pay_bank_transfer_id
     and pbt.pay_batch_id = p_pay_batch_id
    join pg_temp._tmp_settle_external_completed_transfers as external_completed_payout_transfer
      on external_completed_payout_transfer.transfer_id = pbt.id
    where pbc.pay_batch_id = p_pay_batch_id
      and pbc.candidate_id in (select t.candidate_id from _tmp_newly_settled_candidates t)
      and pbi.is_voided = false
      and pbi.item_type in ('LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','UNDERPAYMENT_PAYMENT')
      and pbi.pay_bank_transfer_id is not null
      and coalesce(
        pbi.finance_case_id,
        nullif(btrim(replace(coalesce(pbi.source_ref,''), 'advance:', '')),'')::uuid
      ) is not null
  ),
  upd as (
    update public.pay_advances pa
    set
      payout_status = 'PAID'::public.pay_advance_payout_status_enum,
      payout_pay_batch_id = p_pay_batch_id,
      payout_transfer_id = p.transfer_id,
      updated_at = v_now
    from payouts p
    where pa.id = p.finance_case_id
      and pa.case_type in ('PAYMENT_ADVANCE'::public.pay_finance_case_type_enum, 'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum, 'UNDERPAYMENT'::public.pay_finance_case_type_enum)
      and coalesce(pa.payout_status::text,'') <> 'PAID'
    returning pa.id, pa.case_type, p.transfer_id, p.item_type
  )
  select count(*)::int
  into v_payout_cases_marked_paid_ct
  from upd;

  insert into public.pay_finance_case_events(
    finance_case_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    reservation_id,
    before_json,
    after_json,
    reason,
    note
  )
  select
    upd.id,
    'PAYOUT_SETTLED',
    v_now,
    p_actor_user_id,
    p_pay_batch_id,
    null::uuid,
    jsonb_build_object('payout_status', 'PENDING_OR_COMMITTED'),
    jsonb_build_object(
      'payout_status', 'PAID',
      'payout_transfer_id', upd.transfer_id::text,
      'item_type', upd.item_type,
      'case_type', upd.case_type::text
    ),
    'rail_settlement',
    null
  from (
    select distinct
      pa.id,
      pa.case_type,
      pbi.pay_bank_transfer_id as transfer_id,
      pbi.item_type
    from public.pay_advances pa
    join public.pay_batch_items pbi
      on pbi.finance_case_id = pa.id
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join public.pay_bank_transfers pbt
      on pbt.id = pbi.pay_bank_transfer_id
     and pbt.pay_batch_id = p_pay_batch_id
    join pg_temp._tmp_settle_external_completed_transfers as external_completed_payout_event_transfer
      on external_completed_payout_event_transfer.transfer_id = pbt.id
    where pbc.pay_batch_id = p_pay_batch_id
      and pbc.candidate_id in (select t.candidate_id from _tmp_newly_settled_candidates t)
      and pbi.is_voided = false
      and pbi.item_type in ('LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','UNDERPAYMENT_PAYMENT')
      and pa.case_type in ('PAYMENT_ADVANCE'::public.pay_finance_case_type_enum, 'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum, 'UNDERPAYMENT'::public.pay_finance_case_type_enum)
  ) upd;

  with payable_transfer_ids as (
    select distinct
      pbi.pay_bank_transfer_id as transfer_id
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = p_pay_batch_id

      and pbi.item_type <> 'DEBT_CREATED'
      and pbi.is_voided = false
      and pbi.pay_bank_transfer_id is not null
  ),
  stats as (
    select
      count(*)::int as total_ct,
      sum(case when upper(coalesce(pbt.status,'')) in ('PENDING','PROCESSING','UNKNOWN') then 1 else 0 end)::int as pending_ct,
      sum(case when external_completed_status_transfer.transfer_id is not null then 1 else 0 end)::int as completed_ct,
      sum(case when external_completed_status_transfer.transfer_id is not null then 1 else 0 end)::int as settled_evidence_ct,
      sum(case when upper(coalesce(pbt.status,'')) in ('FAILED','DECLINED','REJECTED','CANCELLED') then 1 else 0 end)::int as failed_ct,
      sum(case when upper(coalesce(pbt.status,'')) in ('RETURNED','REVERTED') then 1 else 0 end)::int as returned_ct,
      sum(case when upper(coalesce(pbt.status,'')) = 'BLOCKED' then 1 else 0 end)::int as blocked_ct
    from payable_transfer_ids pti
    join public.pay_bank_transfers pbt
      on pbt.id = pti.transfer_id
     and pbt.pay_batch_id = p_pay_batch_id
    left join pg_temp._tmp_settle_external_completed_transfers as external_completed_status_transfer
      on external_completed_status_transfer.transfer_id = pbt.id
  )
  select
    case
      when coalesce(s.total_ct, 0) = 0 and v_no_bank_payment_execution_validated then 'SETTLED'
      when coalesce(s.total_ct, 0) = 0 then 'PARTIAL'
      when coalesce(s.pending_ct,0) = 0
       and coalesce(s.failed_ct,0) = 0
       and coalesce(s.blocked_ct,0) = 0
       and coalesce(s.returned_ct,0) = 0
       and coalesce(s.settled_evidence_ct,0) >= coalesce(s.total_ct,0)
        then 'SETTLED'
      when coalesce(s.pending_ct,0) = 0
       and coalesce(s.failed_ct,0) = 0
       and coalesce(s.blocked_ct,0) = 0
       and coalesce(s.returned_ct,0) > 0
       and coalesce(s.settled_evidence_ct,0) > 0
        then 'SETTLED'
      when coalesce(s.pending_ct,0) = 0
       and coalesce(s.failed_ct,0) > 0
       and coalesce(s.returned_ct,0) = 0
        then 'FAILED'
      else 'PARTIAL'
    end
  into v_batch_status
  from stats s;

  v_completed_with_failed_payments := (v_batch_status = 'FAILED');
  v_batch_status_label := CASE
    WHEN v_batch_status = 'FAILED' THEN 'Completed with failed payments'
    WHEN v_batch_status = 'SETTLED' THEN 'Completed'
    WHEN v_batch_status = 'PARTIAL' THEN 'Partially completed'
    ELSE v_batch_status
  END;

  v_settlement_confirmation_json := COALESCE(v_batch.settlement_confirmation_json, '{}'::jsonb);

  IF COALESCE(v_completed_transfer_count, 0) > 0 THEN
    IF v_settlement_mode IN ('CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT') THEN
      v_settlement_confirmation_json := v_settlement_confirmation_json
        - 'provider_reference'
        - 'provider_request_id'
        - 'provider_submission_id'
        - 'provider_transaction_id'
        - 'rail_tx_id';
    ELSIF v_no_bank_scope_authorised THEN
      v_settlement_confirmation_json := v_settlement_confirmation_json - 'local_commit_reference';
    END IF;

    v_settlement_confirmation_json := v_settlement_confirmation_json
      || JSONB_STRIP_NULLS(
        JSONB_BUILD_OBJECT(
          'settlement_mode', v_settlement_mode,
          'provisional_scope_settlement', CASE WHEN v_batch_status IN ('SETTLED', 'FAILED') THEN false ELSE NULL::boolean END,
          'full_batch_finalised', (v_batch_status IN ('SETTLED', 'FAILED')),
          'full_batch_finalised_at_utc', CASE
            WHEN v_batch_status IN ('SETTLED', 'FAILED') THEN COALESCE(
              NULLIF(BTRIM(COALESCE(v_settlement_confirmation_json->>'full_batch_finalised_at_utc', '')), ''),
              v_now::text
            )
            ELSE NULL::text
          END,
          'confirmation_mode', CASE
            WHEN v_no_bank_scope_authorised THEN 'MIXED_TRANSFER_AND_NO_BANK_PAYMENT'
            WHEN v_settlement_mode = 'CSV_SETTLEMENT' THEN 'CSV_MANUAL_CONFIRM'
            WHEN v_settlement_mode = 'EXTERNAL_SETTLEMENT' THEN 'EXTERNAL_MANUAL_CONFIRM'
            ELSE 'PROVIDER_TERMINAL_SETTLEMENT'
          END,
          'settled_at_utc', COALESCE(
            NULLIF(BTRIM(COALESCE(v_settlement_confirmation_json->>'settled_at_utc', '')), ''),
            v_now::text
          ),
          'settled_by_user_id', COALESCE(
            NULLIF(BTRIM(COALESCE(v_settlement_confirmation_json->>'settled_by_user_id', '')), ''),
            p_actor_user_id::text
          ),
          'payment_date', CASE WHEN v_effective_payment_date IS NULL THEN NULL::text ELSE v_effective_payment_date::text END,
          'execution_operation_id', v_execution_operation_id::text,
          'settlement_operation_id', CASE WHEN v_settlement_operation_id IS NULL THEN NULL::text ELSE v_settlement_operation_id::text END,
          'auth_request_id', v_operation_auth_request_id::text,
          'projection_scope', v_operation_projection_scope
        )
        || JSONB_BUILD_OBJECT(
          'global_paye_net_state_hash', v_expected_paye_net_state_hash,
          'paye_net_state_hash', v_expected_paye_net_state_hash,
          'scoped_paye_net_state_hash', v_expected_scoped_paye_net_state_hash,
          'global_bank_payment_projection_hash', v_expected_global_bank_payment_projection_hash,
          'scoped_bank_payment_projection_hash', v_expected_bank_payment_projection_hash,
          'bank_payment_projection_hash', v_expected_bank_payment_projection_hash,
          'projection_changed_after_authorisation', v_current_projection_changed,
          'positive_transfer_count', COALESCE(v_completed_transfer_count, 0),
          'total_bank_out', ROUND(COALESCE(v_completed_transfer_total, 0), 2),
          'pay_bank_transfer_ids', COALESCE(v_completed_transfer_ids, '[]'::jsonb),
          'pay_bank_transfer_id', CASE
            WHEN JSONB_ARRAY_LENGTH(COALESCE(v_completed_transfer_ids, '[]'::jsonb)) = 1 THEN v_completed_transfer_ids->>0
            ELSE NULL::text
          END,
          'settlement_scope_ids', COALESCE(v_settlement_scope_ids, '[]'::jsonb),
          'settlement_scope_id', CASE
            WHEN JSONB_ARRAY_LENGTH(COALESCE(v_settlement_scope_ids, '[]'::jsonb)) = 1 THEN v_settlement_scope_ids->>0
            ELSE NULL::text
          END
        )
        || JSONB_BUILD_OBJECT(
          'execution_commit_ref', COALESCE(
            NULLIF(BTRIM(COALESCE(v_execution_commit_ref, '')), ''),
            NULLIF(BTRIM(COALESCE(v_detected_execution_commit_ref, '')), ''),
            NULLIF(BTRIM(COALESCE(v_local_positive_commit_ref, '')), '')
          ),
          'local_commit_reference', CASE
            WHEN v_settlement_mode IN ('CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT')
              THEN COALESCE(NULLIF(BTRIM(COALESCE(v_execution_commit_ref, '')), ''), v_local_positive_commit_ref)
            ELSE NULL::text
          END,
          'bank_confirm_ref', CASE WHEN v_settlement_mode = 'CSV_SETTLEMENT' THEN v_bank_confirm_ref ELSE NULL::text END,
          'external_comment', CASE
            WHEN v_settlement_mode = 'EXTERNAL_SETTLEMENT'
              THEN NULLIF(BTRIM(COALESCE(v_operation_auth_intent_json->>'external_settlement_comment', '')), '')
            ELSE NULL::text
          END,
          'csv_export_hash', CASE
            WHEN v_settlement_mode = 'CSV_SETTLEMENT'
              THEN NULLIF(BTRIM(COALESCE(v_operation_auth_intent_json->>'bank_csv_export_hash', v_batch_intent_json->>'bank_csv_export_hash', '')), '')
            ELSE NULL::text
          END,
          'csv_uploaded_confirmed', CASE
            WHEN v_settlement_mode = 'CSV_SETTLEMENT'
              THEN LOWER(BTRIM(COALESCE(v_operation_auth_intent_json->>'csv_uploaded_confirmed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
            ELSE NULL::boolean
          END,
          'external_settlement_confirmed', CASE WHEN v_settlement_mode = 'EXTERNAL_SETTLEMENT' THEN true ELSE NULL::boolean END,
          'submitted_to_bank', v_submitted_to_bank,
          'provider_submission_required', v_provider_submission_required,
          'provider_submission_attempted', v_provider_submission_attempted,
          'local_settlement_evidence_only', v_local_settlement_evidence_only
        )
        || JSONB_BUILD_OBJECT(
          'contains_no_bank_payment_scopes', CASE WHEN v_no_bank_scope_authorised THEN true ELSE NULL::boolean END,
          'no_bank_payment_reason', CASE WHEN v_no_bank_scope_authorised THEN 'EXPLICIT_ZERO_PAYE' ELSE NULL::text END,
          'zero_scope_count', CASE WHEN v_no_bank_scope_authorised THEN COALESCE(v_no_bank_total_scope_count, 0) ELSE 0 END,
          'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes_marker,
          'no_bank_scope_reference', CASE WHEN v_no_bank_scope_authorised THEN v_local_no_bank_commit_ref ELSE NULL::text END,
          'suppress_remittances', v_suppress_remittances,
          'remittances_suppressed_at_utc', CASE
            WHEN v_suppress_remittances THEN COALESCE(
              NULLIF(BTRIM(COALESCE(v_settlement_confirmation_json->>'remittances_suppressed_at_utc', '')), ''),
              v_now::text
            )
            ELSE NULL::text
          END,
          'no_bank_payment_note', CASE
            WHEN v_no_bank_scope_authorised
              THEN 'Explicit-zero PAYE scopes were settled locally without transfer or provider evidence; the positive-payment commit proof remains authoritative.'
            ELSE NULL::text
          END
        )
      );
  ELSIF v_no_bank_payment_execution_validated AND v_batch_status = 'SETTLED' THEN
    v_settlement_confirmation_json := v_settlement_confirmation_json
      - 'bank_confirm_ref'
      - 'provider_reference'
      - 'provider_request_id'

      - 'provider_submission_id'
      - 'provider_transaction_id'
      - 'rail_tx_id';

    v_settlement_confirmation_json := v_settlement_confirmation_json
      || JSONB_STRIP_NULLS(
        JSONB_BUILD_OBJECT(
          'settlement_mode', v_settlement_mode,
          'provisional_scope_settlement', false,
          'full_batch_finalised', true,
          'full_batch_finalised_at_utc', COALESCE(
            NULLIF(BTRIM(COALESCE(v_settlement_confirmation_json->>'full_batch_finalised_at_utc', '')), ''),
            v_now::text
          ),
          'confirmation_mode', CASE
            WHEN v_settlement_mode = 'CSV_SETTLEMENT' THEN 'NO_BANK_PAYMENT_REVIEW'
            WHEN v_settlement_mode = 'EXTERNAL_SETTLEMENT' THEN 'NO_BANK_PAYMENT_EXTERNAL_CONFIRMATION'
            ELSE 'NO_BANK_PAYMENT_EXECUTION'
          END,
          'scope_kind', 'NO_BANK_PAYMENT',
          'no_bank_payment_reason', 'EXPLICIT_ZERO_PAYE',
          'no_bank_payment_execution', true,
          'contains_no_bank_payment_scopes', true,
          'allow_explicit_zero_no_bank_scopes', true,
          'local_commit_reference', v_local_no_bank_commit_ref,
          'execution_commit_ref', v_local_no_bank_commit_ref,
          'execution_operation_id', v_execution_operation_id::text,
          'settlement_operation_id', CASE WHEN v_settlement_operation_id IS NULL THEN NULL::text ELSE v_settlement_operation_id::text END,
          'auth_request_id', v_operation_auth_request_id::text
        )
        || JSONB_BUILD_OBJECT(
          'global_paye_net_state_hash', v_expected_paye_net_state_hash,
          'paye_net_state_hash', v_expected_paye_net_state_hash,
          'scoped_paye_net_state_hash', v_expected_scoped_paye_net_state_hash,
          'global_bank_payment_projection_hash', v_expected_global_bank_payment_projection_hash,
          'scoped_bank_payment_projection_hash', v_expected_bank_payment_projection_hash,
          'bank_payment_projection_hash', v_expected_bank_payment_projection_hash,
          'projection_changed_after_authorisation', v_current_projection_changed,
          'projection_scope', v_operation_projection_scope,
          'zero_scope_count', COALESCE(v_no_bank_total_scope_count, 0),
          'positive_transfer_count', 0,
          'total_bank_out', 0,
          'pay_bank_transfer_ids', '[]'::jsonb,
          'settlement_scope_ids', COALESCE(v_settlement_scope_ids, '[]'::jsonb),
          'settlement_scope_id', CASE
            WHEN JSONB_ARRAY_LENGTH(COALESCE(v_settlement_scope_ids, '[]'::jsonb)) = 1 THEN v_settlement_scope_ids->>0
            ELSE NULL::text
          END
        )
        || JSONB_BUILD_OBJECT(
          'payment_date', CASE WHEN v_effective_payment_date IS NULL THEN NULL::text ELSE v_effective_payment_date::text END,
          'settled_at_utc', COALESCE(
            NULLIF(BTRIM(COALESCE(v_settlement_confirmation_json->>'settled_at_utc', '')), ''),
            v_now::text
          ),
          'settled_by_user_id', COALESCE(
            NULLIF(BTRIM(COALESCE(v_settlement_confirmation_json->>'settled_by_user_id', '')), ''),
            p_actor_user_id::text
          ),
          'csv_uploaded_confirmed', CASE
            WHEN v_settlement_mode = 'CSV_SETTLEMENT'
              THEN LOWER(BTRIM(COALESCE(v_operation_auth_intent_json->>'csv_uploaded_confirmed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
            ELSE NULL::boolean
          END,
          'external_comment', CASE
            WHEN v_settlement_mode = 'EXTERNAL_SETTLEMENT'
              THEN NULLIF(BTRIM(COALESCE(v_operation_auth_intent_json->>'external_settlement_comment', '')), '')
            ELSE NULL::text
          END,
          'submitted_to_bank', false,
          'provider_submission_required', false,
          'provider_submission_attempted', false,
          'local_settlement_evidence_only', true,
          'bank_upload_occurred', false,
          'bank_payment_occurred', false,
          'provider_submission_occurred', false
        )
        || JSONB_BUILD_OBJECT(
          'suppress_remittances', v_suppress_remittances,
          'remittances_suppressed_at_utc', CASE
            WHEN v_suppress_remittances THEN COALESCE(
              NULLIF(BTRIM(COALESCE(v_settlement_confirmation_json->>'remittances_suppressed_at_utc', '')), ''),
              v_now::text
            )
            ELSE NULL::text
          END,
          'no_bank_payment_note', CASE
            WHEN v_settlement_mode = 'CSV_SETTLEMENT'
              THEN 'The current zero-row CloudTMS Bank CSV was reviewed; no bank upload or payment occurred or was required.'
            WHEN v_settlement_mode = 'EXTERNAL_SETTLEMENT'
              THEN 'The authorised external no-bank settlement was completed locally; no bank payment or provider submission occurred or was required.'
            ELSE 'All authorised PAYE bank amounts were explicitly zero; no bank transfer or provider submission occurred or was required.'
          END
        )
      );
  END IF;

  UPDATE public.pay_batches AS pb2
  SET
    status = v_batch_status,
    completed_at_utc = CASE
      WHEN v_batch_status IN ('SETTLED', 'FAILED') THEN COALESCE(pb2.completed_at_utc, v_now)
      ELSE pb2.completed_at_utc
    END,
    last_status_checked_at_utc = v_now,
    total_bank_out = CASE
      WHEN v_batch_status = 'SETTLED' AND COALESCE(v_completed_transfer_count, 0) > 0
        THEN ROUND(COALESCE(v_completed_transfer_total, 0), 2)
      WHEN v_batch_status = 'SETTLED' AND v_no_bank_payment_execution_validated
        THEN 0
      ELSE pb2.total_bank_out
    END,
    execution_commit_state = CASE
      WHEN COALESCE(v_completed_transfer_count, 0) > 0 THEN 'COMMITTED'
      WHEN v_no_bank_payment_execution_validated AND v_batch_status = 'SETTLED' THEN 'COMMITTED'
      ELSE COALESCE(NULLIF(BTRIM(COALESCE(pb2.execution_commit_state, '')), ''), 'NOT_SUBMITTED')
    END,
    execution_commit_ref = CASE
      WHEN COALESCE(v_completed_transfer_count, 0) > 0
           AND v_settlement_mode IN ('CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT')
        THEN v_local_positive_commit_ref
      WHEN COALESCE(v_completed_transfer_count, 0) > 0 THEN COALESCE(
        NULLIF(BTRIM(COALESCE(pb2.execution_commit_ref, '')), ''),
        NULLIF(BTRIM(COALESCE(v_execution_commit_ref, '')), ''),
        NULLIF(BTRIM(COALESCE(v_detected_execution_commit_ref, '')), '')
      )
      WHEN v_no_bank_payment_execution_validated AND v_batch_status = 'SETTLED' THEN COALESCE(
        NULLIF(BTRIM(COALESCE(pb2.execution_commit_ref, '')), ''),
        v_local_no_bank_commit_ref
      )
      ELSE pb2.execution_commit_ref
    END,
    execution_committed_at_utc = CASE
      WHEN COALESCE(v_completed_transfer_count, 0) > 0 THEN COALESCE(
        pb2.execution_committed_at_utc,
        v_execution_committed_at_utc,
        v_detected_execution_committed_at_utc,
        v_now
      )
      WHEN v_no_bank_payment_execution_validated AND v_batch_status = 'SETTLED' THEN COALESCE(
        pb2.execution_committed_at_utc,
        v_execution_committed_at_utc,
        v_now
      )
      ELSE pb2.execution_committed_at_utc
    END,
    settlement_confirmation_json = v_settlement_confirmation_json
  WHERE pb2.id = p_pay_batch_id;


  if jsonb_array_length(coalesce(v_durably_finalised_candidate_ids, '[]'::jsonb)) > 0 then
    update public.pay_batches as finalised_candidate_batch_update
    set settlement_confirmation_json = coalesce(finalised_candidate_batch_update.settlement_confirmation_json, '{}'::jsonb)
      || jsonb_build_object(
        'durably_finalised_candidate_ids', v_durably_finalised_candidate_ids
      )
    where finalised_candidate_batch_update.id = p_pay_batch_id;
  end if;

  IF v_no_bank_payment_execution_validated AND v_batch_status = 'SETTLED' THEN
    v_execution_commit_state := 'COMMITTED';
    v_execution_commit_ref := v_local_no_bank_commit_ref;
    v_execution_committed_at_utc := COALESCE(v_execution_committed_at_utc, v_now);
  ELSIF COALESCE(v_completed_transfer_count, 0) > 0 THEN
    v_execution_commit_state := 'COMMITTED';
    v_execution_commit_ref := COALESCE(v_local_positive_commit_ref, v_execution_commit_ref, v_detected_execution_commit_ref);
    v_execution_committed_at_utc := COALESCE(v_execution_committed_at_utc, v_detected_execution_committed_at_utc, v_now);
  END IF;

  select exists (
    select 1
    from public.pay_batch_candidates pbc_unsent
    where pbc_unsent.pay_batch_id = p_pay_batch_id
      and pbc_unsent.remittance_sent_at_utc is null
    limit 1
  )
  into v_catchup_needed;

  if v_suppress_remittances = true then
    v_comm_trigger_status := 'SUPPRESSED_BY_EXECUTION_INTENT';

    v_comm_error := null;
    v_comm_result := jsonb_build_object(
      'ok', true,
      'trigger_status', v_comm_trigger_status,
      'message_kind', case when upper(btrim(coalesce(v_batch.batch_kind_fixed,''))) = 'LOANS' then 'PAYOUT_NOTICE' else 'REMITTANCE' end,
      'catchup_send', false,
      'dispatch_required', false,
      'suppressed_by_execution_intent', true,
      'execution_mode', v_settlement_mode
    );
    v_suppression_audit_json := jsonb_build_object(
      'pay_batch_id', p_pay_batch_id::text,
      'batch_kind_fixed', upper(coalesce(v_batch.batch_kind_fixed,'')),
      'settlement_mode', v_settlement_mode,
      'suppress_remittances', true,
      'suppressed_at_utc', v_now::text,
      'auth_request_id', nullif(btrim(coalesce(v_execution_intent_json->>'auth_request_id', '')), '')
    );
    begin
      insert into public.audit_events(
        actor_user_id,
        object_type,
        object_id_text,
        action,
        before_json,
        after_json,
        reason
      )
      select
        p_actor_user_id,
        'pay_batch',
        p_pay_batch_id::text,
        'PAY_BATCH_SETTLEMENT_COMMUNICATION_SUPPRESSED',
        null::jsonb,
        v_suppression_audit_json,
        'suppressed_by_execution_intent'
      where not exists (
        select 1
        from public.audit_events as existing_suppression_audit
        where existing_suppression_audit.object_type = 'pay_batch'
          and existing_suppression_audit.object_id_text = p_pay_batch_id::text
          and existing_suppression_audit.action = 'PAY_BATCH_SETTLEMENT_COMMUNICATION_SUPPRESSED'
          and existing_suppression_audit.reason = 'suppressed_by_execution_intent'
      );
    exception when others then
      null;
    end;
  elsif v_catchup_needed then
    v_comm_trigger_status := 'REMITTANCE_READY_DEFERRED_TO_OPERATION';
    v_comm_error := null;
    v_comm_result := jsonb_build_object(
      'ok', true,
      'trigger_status', v_comm_trigger_status,
      'message_kind', case when upper(btrim(coalesce(v_batch.batch_kind_fixed,''))) = 'LOANS' then 'PAYOUT_NOTICE' else 'REMITTANCE' end,
      'catchup_send', false,
      'dispatch_required', true,
      'remittance_ready', true,
      'remittance_queued', false,
      'deferred_to_operation', true,
      'requires_remittance_operation', true,
      'operation_type', 'REMITTANCE_QUEUE',
      'source_rpc', 'pay_settle_rail',
      'message', 'Settlement is remittance-ready. Queueing is handled by the separate scalable remittance operation.'
    );

    begin
      insert into public.audit_events(
        actor_user_id,
        object_type,
        object_id_text,
        action,
        before_json,
        after_json,
        reason
      )
      select
        p_actor_user_id,
        'pay_batch',
        p_pay_batch_id::text,
        'PAY_BATCH_SETTLEMENT_REMITTANCE_DEFERRED_TO_OPERATION',
        null::jsonb,
        jsonb_build_object(
          'pay_batch_id', p_pay_batch_id::text,
          'batch_kind_fixed', upper(coalesce(v_batch.batch_kind_fixed,'')),
          'trigger_status', v_comm_trigger_status,
          'result', coalesce(v_comm_result, '{}'::jsonb)
        ),
        'settlement_remittance_deferred_to_operation'
      where not exists (
        select 1
        from public.audit_events as existing_deferred_audit
        where existing_deferred_audit.object_type = 'pay_batch'
          and existing_deferred_audit.object_id_text = p_pay_batch_id::text
          and existing_deferred_audit.action = 'PAY_BATCH_SETTLEMENT_REMITTANCE_DEFERRED_TO_OPERATION'
          and existing_deferred_audit.reason = 'settlement_remittance_deferred_to_operation'
      );
    exception when others then
      null;
    end;
  else
    v_comm_trigger_status := 'NO_CATCHUP_NEEDED';
    v_comm_error := null;
    v_comm_result := jsonb_build_object(
      'ok', true,
      'trigger_status', v_comm_trigger_status,
      'message_kind', case when upper(btrim(coalesce(v_batch.batch_kind_fixed,''))) = 'LOANS' then 'PAYOUT_NOTICE' else 'REMITTANCE' end,
      'catchup_send', false
    );
  end if;

  v_worker_communications := jsonb_build_object(
    'primary_trigger_stage', 'COMMIT',
    'catchup_attempted_at_settlement', (v_catchup_needed and v_suppress_remittances = false),
    'message_kind', coalesce(nullif(btrim(coalesce(v_comm_result->>'message_kind','')), ''), case when upper(btrim(coalesce(v_batch.batch_kind_fixed,''))) = 'LOANS' then 'PAYOUT_NOTICE' else 'REMITTANCE' end),
    'trigger_status', v_comm_trigger_status,
    'error', v_comm_error,
    'result', coalesce(v_comm_result, '{}'::jsonb),
    'remittance_queue_stage_result', coalesce(v_comm_result, '{}'::jsonb),
    'remittance_ready', (v_catchup_needed and v_suppress_remittances = false),
    'remittance_queued', false,
    'requires_remittance_operation', (v_catchup_needed and v_suppress_remittances = false),
    'execution_mode', v_settlement_mode,
    'suppress_remittances', v_suppress_remittances
  );

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', pbt.id::text,
        'pay_channel', pbt.pay_channel,
        'status', pbt.status,
        'amount', pbt.amount,
        'rail_tx_id', pbt.rail_tx_id,
        'rail_state', pbt.rail_state,
        'rail_meta_json', pbt.rail_meta_json
      )
      order by pbt.pay_channel, pbt.amount desc, pbt.id
    ),
    '[]'::jsonb
  )
  into v_pending_transfers
  from public.pay_bank_transfers pbt
  where pbt.pay_batch_id = p_pay_batch_id
    and upper(coalesce(pbt.status,'')) in ('PENDING','PROCESSING','UNKNOWN');

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', pbt.id::text,
        'pay_channel', pbt.pay_channel,
        'status', pbt.status,
        'amount', pbt.amount,
        'rail_tx_id', pbt.rail_tx_id,
        'rail_state', pbt.rail_state,
        'rail_meta_json', pbt.rail_meta_json,
        'failed_reason', pbt.failed_reason
      )
      order by pbt.pay_channel, pbt.amount desc, pbt.id
    ),
    '[]'::jsonb
  )
  into v_failed_transfers
  from public.pay_bank_transfers pbt
  where pbt.pay_batch_id = p_pay_batch_id
    and upper(coalesce(pbt.status,'')) in ('FAILED','DECLINED','REJECTED','CANCELLED');

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', pbt.id::text,
        'pay_channel', pbt.pay_channel,
        'status', pbt.status,
        'amount', pbt.amount,
        'rail_tx_id', pbt.rail_tx_id,
        'rail_state', pbt.rail_state,
        'rail_meta_json', pbt.rail_meta_json,
        'completed_at_utc', case when pbt.completed_at_utc is null then null else pbt.completed_at_utc::text end
      )
      order by pbt.pay_channel, pbt.amount desc, pbt.id
    ),

    '[]'::jsonb
  )
  into v_returned_transfers
  from public.pay_bank_transfers pbt
  where pbt.pay_batch_id = p_pay_batch_id
    and upper(coalesce(pbt.status,'')) in ('RETURNED','REVERTED');

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', pbt.id::text,
        'pay_channel', pbt.pay_channel,
        'status', pbt.status,
        'amount', pbt.amount,
        'rail_state', pbt.rail_state,
        'rail_meta_json', pbt.rail_meta_json
      )
      order by pbt.pay_channel, pbt.amount desc, pbt.id
    ),
    '[]'::jsonb
  )
  into v_blocked_transfers
  from public.pay_bank_transfers pbt
  where pbt.pay_batch_id = p_pay_batch_id
    and upper(coalesce(pbt.status,'')) = 'BLOCKED';


  for v_changed_channel_audit in
    with batch_item_portions as (
      select
        pbi.id as pay_batch_item_id,
        pbc.id as pay_batch_candidate_id,
        pbc.candidate_id as candidate_id,
        pbi.timesheet_id as timesheet_id,
        ts.booking_id as booking_id,
        pbi.pay_bank_transfer_id as pay_bank_transfer_id,
        pbi.item_type as item_type,
        pbi.segment_key as segment_key,
        pbi.source_ref as source_ref,
        pbi.description as description,
        upper(coalesce(nullif(btrim(coalesce(pbi.frozen_source_pay_method,'')), ''), '')) as source_pay_channel,
        upper(coalesce(nullif(btrim(coalesce(pbi.pay_channel,'')), ''), nullif(btrim(coalesce(pbi.frozen_target_pay_method,'')), ''), '')) as settled_pay_channel,
        case when pbi.frozen_component_key_type is null then null else pbi.frozen_component_key_type end as component_key_type,
        pbi.frozen_component_key_value as component_key_value,
        case when pbi.frozen_component_classification is null then null else pbi.frozen_component_classification::text end as component_classification,
        case when pbi.frozen_resolution_mode is null then null else pbi.frozen_resolution_mode::text end as resolution_mode,
        pbi.frozen_resolution_payload_json as resolution_payload_json,
        pbi.frozen_resolution_result_json as resolution_result_json,
        pbi.frozen_source_basis_json as frozen_source_basis_json,
        round(coalesce(pbi.frozen_source_amount, pbi.amount_ex_vat, 0), 2) as item_source_amount_ex_vat,
        round(coalesce(pbi.frozen_target_amount_ex_vat, pbi.amount_ex_vat, 0), 2) as item_settled_amount_ex_vat,
        pbi.amount_ex_vat as item_amount_ex_vat
      from public.pay_batch_items pbi
      join public.pay_batch_candidates pbc
        on pbc.id = pbi.pay_batch_candidate_id
      left join public.timesheets ts
        on ts.timesheet_id = pbi.timesheet_id
      where pbc.pay_batch_id = p_pay_batch_id
        and pbc.candidate_id in (select t.candidate_id from _tmp_newly_settled_candidates t)
        and pbi.timesheet_id is not null
        and pbi.item_type <> 'DEBT_CREATED'
        and coalesce(pbi.is_voided, false) = false
    ),
    portion_rows as (
      select
        bip.pay_batch_item_id,
        bip.pay_batch_candidate_id,
        bip.candidate_id,
        bip.timesheet_id,
        bip.booking_id,
        bip.pay_bank_transfer_id,
        bip.source_pay_channel,
        bip.settled_pay_channel,
        bip.component_key_type,
        bip.component_key_value,
        bip.component_classification,
        bip.resolution_mode,
        bip.resolution_payload_json,
        bip.resolution_result_json,
        bip.segment_key,
        bip.source_ref,
        bip.description,
        pbib.id as pay_batch_item_breakdown_id,
        coalesce(
          nullif(btrim(coalesce(pbib.line_kind,'')), ''),
          case
            when bip.item_type = 'SEGMENT_DELTA' then 'SEGMENT_BUCKET'
            when bip.item_type = 'EXPENSE_DELTA' then 'EXPENSE'
            when bip.item_type = 'MILEAGE_DELTA' then 'MILEAGE'
            when bip.item_type = 'ADJUSTMENT_DELTA' then 'ADJUSTMENT'
            when bip.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
            when bip.item_type = 'LOAN_REPAYMENT' then 'LOAN_REPAYMENT'
            when bip.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
            when bip.item_type = 'LOAN_PAYOUT' then 'LOAN_PAYOUT'
            when bip.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_PAYOUT'
            when bip.item_type = 'UNDERPAYMENT_PAYMENT' then 'UNDERPAYMENT_PAYMENT'
            else bip.item_type
          end
        ) as line_kind,
        nullif(btrim(coalesce(pbib.bucket_code, bip.frozen_source_basis_json ->> 'bucket_code', '')), '') as bucket_code,
        coalesce(
          nullif(btrim(coalesce(pbib.unit_name, '')), ''),
          nullif(btrim(coalesce(bip.description, '')), ''),
          case
            when bip.item_type = 'SEGMENT_DELTA' then 'Timesheet portion'
            when bip.item_type = 'EXPENSE_DELTA' then 'Expense'
            when bip.item_type = 'MILEAGE_DELTA' then 'Mileage'
            when bip.item_type = 'ADJUSTMENT_DELTA' then 'Adjustment'
            when bip.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            when bip.item_type = 'LOAN_REPAYMENT' then 'Loan repayment'
            when bip.item_type = 'MANUAL_DEBT_RECOVERY' then 'Manual debt recovery'
            when bip.item_type = 'LOAN_PAYOUT' then 'Loan payout'
            when bip.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual credit payout'
            when bip.item_type = 'UNDERPAYMENT_PAYMENT' then 'Underpayment payment'
            else 'Batch item'
          end
        ) as unit_name,
        case
          when pbib.units is not null then round(pbib.units, 4)
          when bip.frozen_source_basis_json ? 'source_units'
           and nullif(btrim(coalesce(bip.frozen_source_basis_json ->> 'source_units', '')), '') is not null
            then round((bip.frozen_source_basis_json ->> 'source_units')::numeric, 4)
          else null::numeric
        end as units,
        case
          when bip.frozen_source_basis_json ? 'source_rate'
           and nullif(btrim(coalesce(bip.frozen_source_basis_json ->> 'source_rate', '')), '') is not null
            then round((bip.frozen_source_basis_json ->> 'source_rate')::numeric, 6)
          else null::numeric
        end as source_rate,
        case
          when pbib.rate is not null then round(pbib.rate, 6)
          else null::numeric
        end as settled_rate,
        case
          when pbib.units is not null
           and bip.frozen_source_basis_json ? 'source_rate'
           and nullif(btrim(coalesce(bip.frozen_source_basis_json ->> 'source_rate', '')), '') is not null
            then round(pbib.units * round((bip.frozen_source_basis_json ->> 'source_rate')::numeric, 6), 2)
          else bip.item_source_amount_ex_vat
        end as source_amount_ex_vat,
        round(coalesce(pbib.amount_ex_vat, bip.item_settled_amount_ex_vat), 2) as settled_amount_ex_vat,
        md5(concat_ws('|',
          bip.pay_batch_item_id::text,
          coalesce(
            nullif(btrim(coalesce(pbib.line_kind,'')), ''),
            case
              when bip.item_type = 'SEGMENT_DELTA' then 'SEGMENT_BUCKET'
              when bip.item_type = 'EXPENSE_DELTA' then 'EXPENSE'
              when bip.item_type = 'MILEAGE_DELTA' then 'MILEAGE'
              when bip.item_type = 'ADJUSTMENT_DELTA' then 'ADJUSTMENT'
              when bip.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
              when bip.item_type = 'LOAN_REPAYMENT' then 'LOAN_REPAYMENT'
              when bip.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
              when bip.item_type = 'LOAN_PAYOUT' then 'LOAN_PAYOUT'
              when bip.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_PAYOUT'
              else bip.item_type
            end
          ),
          coalesce(nullif(btrim(coalesce(pbib.bucket_code, bip.frozen_source_basis_json ->> 'bucket_code', '')), ''), ''),
          coalesce(
            case
              when pbib.units is not null then round(pbib.units, 4)::text
              when bip.frozen_source_basis_json ? 'source_units'
               and nullif(btrim(coalesce(bip.frozen_source_basis_json ->> 'source_units', '')), '') is not null
                then round((bip.frozen_source_basis_json ->> 'source_units')::numeric, 4)::text
              else null::text
            end,
            ''
          ),
          coalesce(case when pbib.rate is not null then round(pbib.rate, 6)::text else null::text end, ''),
          round(coalesce(pbib.amount_ex_vat, bip.item_settled_amount_ex_vat), 2)::text
        )) as portion_identity_key
      from batch_item_portions bip
      left join public.pay_batch_item_breakdowns pbib
        on pbib.pay_batch_item_id = bip.pay_batch_item_id
    )
    select
      pr.pay_batch_item_id,
      pr.pay_batch_item_breakdown_id,

      pr.pay_batch_candidate_id,
      pr.candidate_id,
      pr.timesheet_id,
      pr.booking_id,
      pr.pay_bank_transfer_id,
      pr.source_pay_channel,
      pr.settled_pay_channel,
      pr.component_key_type,
      pr.component_key_value,
      pr.component_classification,
      pr.resolution_mode,
      pr.resolution_payload_json,
      pr.resolution_result_json,
      pr.segment_key,
      pr.source_ref,
      pr.description,
      pr.line_kind,
      pr.bucket_code,
      pr.unit_name,
      pr.units,
      pr.source_rate,
      pr.settled_rate,
      pr.source_amount_ex_vat,
      pr.settled_amount_ex_vat,
      pr.portion_identity_key
    from portion_rows pr
    where pr.source_pay_channel <> ''
      and pr.settled_pay_channel <> ''
      and pr.source_pay_channel <> pr.settled_pay_channel
    order by
      pr.timesheet_id,
      pr.pay_batch_item_id,
      pr.line_kind,
      pr.bucket_code nulls first,
      pr.unit_name,
      pr.settled_amount_ex_vat desc
  loop
    v_changed_channel_audit_after_json := jsonb_build_object(
      'event_kind', 'TIMESHEET_CHANNEL_CHANGE_PORTION',
      'audit_effective_state', 'SETTLED_ACTIVE',
      'channel_changed', true,
      'timesheet_id', v_changed_channel_audit.timesheet_id::text,
      'booking_id', case when v_changed_channel_audit.booking_id is null then null else v_changed_channel_audit.booking_id::text end,
      'candidate_id', case when v_changed_channel_audit.candidate_id is null then null else v_changed_channel_audit.candidate_id::text end,
      'pay_batch_id', p_pay_batch_id::text,
      'pay_batch_candidate_id', case when v_changed_channel_audit.pay_batch_candidate_id is null then null else v_changed_channel_audit.pay_batch_candidate_id::text end,
      'pay_batch_item_id', case when v_changed_channel_audit.pay_batch_item_id is null then null else v_changed_channel_audit.pay_batch_item_id::text end,
      'pay_batch_item_breakdown_id', case when v_changed_channel_audit.pay_batch_item_breakdown_id is null then null else v_changed_channel_audit.pay_batch_item_breakdown_id::text end,
      'portion_identity_key', v_changed_channel_audit.portion_identity_key,
      'source_pay_channel', v_changed_channel_audit.source_pay_channel,
      'settled_pay_channel', v_changed_channel_audit.settled_pay_channel,
      'component_key_type', v_changed_channel_audit.component_key_type,
      'component_key_value', v_changed_channel_audit.component_key_value,
      'component_classification', v_changed_channel_audit.component_classification,
      'line_kind', v_changed_channel_audit.line_kind,
      'bucket_code', v_changed_channel_audit.bucket_code,
      'unit_name', v_changed_channel_audit.unit_name,
      'units', case when v_changed_channel_audit.units is null then null else round(v_changed_channel_audit.units, 4) end,
      'source_rate', case when v_changed_channel_audit.source_rate is null then null else round(v_changed_channel_audit.source_rate, 6) end,
      'settled_rate', case when v_changed_channel_audit.settled_rate is null then null else round(v_changed_channel_audit.settled_rate, 6) end,
      'source_amount_ex_vat', round(coalesce(v_changed_channel_audit.source_amount_ex_vat, 0), 2),
      'settled_amount_ex_vat', round(coalesce(v_changed_channel_audit.settled_amount_ex_vat, 0), 2),
      'resolution_mode', v_changed_channel_audit.resolution_mode,
      'resolution_selection_kind', case
        when v_changed_channel_audit.resolution_mode = 'SUGGESTED_EQUIVALENT_BASIS' then 'SUGGESTED'
        when v_changed_channel_audit.resolution_mode in ('MANUAL_REPLACEMENT_RATE','MANUAL_AMOUNT') then 'MANUAL'
        else null
      end,
      'pay_bank_transfer_id', case when v_changed_channel_audit.pay_bank_transfer_id is null then null else v_changed_channel_audit.pay_bank_transfer_id::text end,
      'segment_key', v_changed_channel_audit.segment_key,
      'source_ref', v_changed_channel_audit.source_ref,
      'description', v_changed_channel_audit.description,
      'settled_at_utc', v_now
    );

    begin
      perform public._audit_insert(
        'timesheets',
        v_changed_channel_audit.timesheet_id::text,
        'TIMESHEET_CHANNEL_CHANGE_PORTION_SETTLED',
        null,
        v_changed_channel_audit_after_json,
        'rail_settlement',
        p_actor_user_id
      );
      v_changed_channel_settled_ct := v_changed_channel_settled_ct + 1;
    exception when others then
      null;
    end;
  end loop;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_SETTLE_RAIL:COUNTS',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'is_stale', v_is_stale,
        'stale_reasons', v_stale_reasons,
        'newly_settled_candidates_count', jsonb_array_length(coalesce(v_newly_settled_candidates,'[]'::jsonb)),
        'overpayment_patches_applied', v_overpay_patched_ct,
        'payment_advance_recovery_patches_applied', v_payment_advance_recovery_patched_ct,
        'manual_debt_recovery_patches_applied', v_manual_debt_patched_ct,
        'payout_cases_marked_paid', v_payout_cases_marked_paid_ct,
        'component_settlements_applied', v_component_settled_count,
        'component_settlement_amount', v_component_settled_amount,
        'component_id_missing_from_frozen_artifact_count', coalesce(v_component_unresolved_count, 0),
        'component_id_missing_from_frozen_artifact_amount', coalesce(v_component_unresolved_amount, 0),
        'component_id_missing_from_frozen_artifact', coalesce(v_component_unresolved_json, '[]'::jsonb),
        'component_reconciliation_checked_count', coalesce(v_component_reconciliation_checked_ct, 0),
        'component_reconciliation_mismatch_count', coalesce(v_component_reconciliation_bad_ct, 0),
        'component_reconciliation_mismatches', v_component_reconciliation_bad,
        'batch_status', v_batch_status,
        'execution_commit_state', case when coalesce(v_completed_transfer_count, 0) > 0 then 'COMMITTED' else v_execution_commit_state end,
        'execution_commit_ref', coalesce(v_execution_commit_ref, v_detected_execution_commit_ref),
        'execution_committed_at_utc', case when coalesce(v_execution_committed_at_utc, v_detected_execution_committed_at_utc) is null then null else coalesce(v_execution_committed_at_utc, v_detected_execution_committed_at_utc)::text end,
        'worker_communications', v_worker_communications,
        'bank_event_ingest_count', v_bank_event_ingest_count,
        'bank_event_ingest_results', v_bank_event_ingest_results,
        'active_snooze_report_count', COALESCE(v_active_snooze_report_count, 0),
        'active_snooze_report_sample', COALESCE(v_active_snooze_report_sample, '[]'::jsonb),
        'london_current_date', v_today_uk::text
      ),
      'pay_batches',
      p_pay_batch_id::text,
      null,
      null,
      null,
      null
    );
  exception when others then
    null;
  end;

  v_live_signal_result := public.banking_pay_batch_signal_touch(
    p_pay_batch_id := p_pay_batch_id,
    p_change_reason := 'PAY_SETTLE_RAIL',
    p_change_source := 'pay_settle_rail',
    p_change_scope_json := jsonb_strip_nulls(jsonb_build_object(
      'execution_mode', v_settlement_mode,
      'batch_status', v_batch_status,
      'batch_status_label', v_batch_status_label,
      'completed_with_failed_payments', v_completed_with_failed_payments,
      'newly_settled_candidates', COALESCE(v_newly_settled_candidates, '[]'::jsonb),
      'completed_transfer_count', COALESCE(v_completed_transfer_count, 0),
      'no_bank_scope_authorised', v_no_bank_scope_authorised,
      'no_bank_payment_execution', v_no_bank_payment_execution_validated,
      'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes_marker,
      'no_bank_scope_count', COALESCE(v_no_bank_total_scope_count, 0),
      'local_commit_reference', COALESCE(
        CASE WHEN v_no_bank_scope_authorised THEN v_local_no_bank_commit_ref ELSE NULL::text END,
        v_local_positive_commit_ref
      ),
      'consumed_carry_forward_count', COALESCE(v_consumed_carry_forward_count, 0),
      'component_id_missing_from_frozen_artifact_count', COALESCE(v_component_unresolved_count, 0),
      'bank_event_ingest_count', COALESCE(v_bank_event_ingest_count, 0)
    )),
    p_touch_payment_status := true,
    p_touch_correction_progress := false,
    p_touch_alerts := false,
    p_touch_overview := true
  );

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'settled_count', jsonb_array_length(coalesce(v_newly_settled_candidates, '[]'::jsonb)),
    'settled_amount', round(coalesce(v_completed_transfer_total, 0), 2)::numeric(14,2),
    'status', (select pb3.status from public.pay_batches pb3 where pb3.id = p_pay_batch_id),
    'display_message', case
      when v_mutation_mode = 'AUTHORITATIVE_EVENT' then 'Authoritative bank evidence recorded and reconciled.'
      else 'Payment settlement recorded.'
    end,
    'batch_status', (select pb3.status from public.pay_batches pb3 where pb3.id = p_pay_batch_id),
    'batch_status_label', v_batch_status_label,
    'completed_with_failed_payments', v_completed_with_failed_payments,
    'execution_commit_state', (select pb3.execution_commit_state from public.pay_batches pb3 where pb3.id = p_pay_batch_id),
    'execution_commit_ref', (select pb3.execution_commit_ref from public.pay_batches pb3 where pb3.id = p_pay_batch_id),
    'execution_committed_at_utc', (select case when pb3.execution_committed_at_utc is null then null else pb3.execution_committed_at_utc::text end from public.pay_batches pb3 where pb3.id = p_pay_batch_id),
    'total_bank_out', (select pb3.total_bank_out from public.pay_batches pb3 where pb3.id = p_pay_batch_id),
    'settlement_operation_id', CASE WHEN v_settlement_operation_id IS NULL THEN NULL::text ELSE v_settlement_operation_id::text END,
    'settlement_confirmation_json', (select pb3.settlement_confirmation_json from public.pay_batches pb3 where pb3.id = p_pay_batch_id),
    'execution_mode', v_settlement_mode,
    'suppress_remittances', v_suppress_remittances,
    'newly_settled_candidates', v_newly_settled_candidates,
    'still_pending_transfers', v_pending_transfers,
    'failed_transfers', v_failed_transfers,

    'returned_transfers', v_returned_transfers,
    'blocked_transfers', v_blocked_transfers,
    'live_snooze_diagnostics', jsonb_build_object(
      'date_authority_available', v_today_uk IS NOT NULL,
      'date_authority_code', CASE WHEN v_today_uk IS NULL THEN COALESCE(v_date_context->>'code', 'PAY_SETTLE_RAIL_LONDON_DATE_UNAVAILABLE') ELSE 'OK' END,
      'active_as_of_london_date', CASE WHEN v_today_uk IS NULL THEN NULL ELSE v_today_uk::text END,
      'active_snooze_report_count', COALESCE(v_active_snooze_report_count, 0),
      'active_snooze_report_sample', COALESCE(v_active_snooze_report_sample, '[]'::jsonb),
      'reporting_only', true,
      'frozen_settlement_authority_unchanged', true
    ),
    'freshness', jsonb_build_object(
      'is_stale', v_is_stale,
      'stale_reasons', v_stale_reasons,
      'diff_sample', v_diff_sample,
      'freshness_validation_status', nullif(v_stored_freshness_status, ''),
      'freshness_result_hash', v_stored_freshness_result_hash,
      'freshness_scope_hash', v_stored_freshness_scope_hash,
      'freshness_operation_id', case when v_stored_freshness_operation_id is null then null else v_stored_freshness_operation_id::text end,
      'source', coalesce(v_fresh->>'source', 'stored_freshness_metadata_non_blocking')
    ),
    'patch_summary', jsonb_build_object(
      'overpayment_patches_applied', v_overpay_patched_ct,
      'payment_advance_recovery_patches_applied', v_payment_advance_recovery_patched_ct,
      'manual_debt_recovery_patches_applied', v_manual_debt_patched_ct,
      'payout_cases_marked_paid', v_payout_cases_marked_paid_ct,
      'component_settlements_applied', v_component_settled_count,
      'component_settlement_amount', v_component_settled_amount,
      'component_id_missing_from_frozen_artifact_count', coalesce(v_component_unresolved_count, 0),
      'component_id_missing_from_frozen_artifact_amount', coalesce(v_component_unresolved_amount, 0),
      'component_id_missing_from_frozen_artifact', coalesce(v_component_unresolved_json, '[]'::jsonb),
      'component_reconciliation_checked_count', coalesce(v_component_reconciliation_checked_ct, 0),
      'component_reconciliation_mismatch_count', coalesce(v_component_reconciliation_bad_ct, 0)
    ),
    'timesheet_channel_change_audit', jsonb_build_object(
      'settled_event_count', v_changed_channel_settled_ct
    ),
    'worker_communications', v_worker_communications,
    'consumed_carry_forward_count', COALESCE(v_consumed_carry_forward_count, 0),
    'carry_forward_mark_consumed_result', COALESCE(v_carry_forward_mark_result, '{}'::jsonb),
    'remittance_ready', (v_catchup_needed and v_suppress_remittances = false),
    'remittance_queued', false,
    'remittance_queue_stage_result', coalesce(v_comm_result, '{}'::jsonb),
    'bank_event_ingest', jsonb_build_object(
      'count', v_bank_event_ingest_count,
      'results', v_bank_event_ingest_results
    ),
    'live_signal', COALESCE(v_live_signal_result, '{}'::jsonb),
    'policy_x_checked', true
  ) || jsonb_strip_nulls(
    jsonb_build_object(
      'proof_validation_outcome', v_proof_validation_outcome,
      'auth_request_id', case when v_operation_auth_request_id is null then null else v_operation_auth_request_id::text end,
      'execution_operation_id', case when v_execution_operation_id is null then null else v_execution_operation_id::text end,
      'settlement_operation_id', CASE
        WHEN v_settlement_operation_id IS NULL THEN NULL::text
        ELSE v_settlement_operation_id::text
      END,
      'authorised_execution_mode', v_authorised_execution_mode,
      'authorised_projection_scope', v_operation_projection_scope,
      'authorised_paye_net_state_hash', v_expected_paye_net_state_hash,
      'current_paye_net_state_hash', v_current_paye_net_state_hash,
      'authorised_global_bank_payment_projection_hash', v_expected_global_bank_payment_projection_hash,
      'current_global_bank_payment_projection_hash', v_all_bank_payment_projection_hash,
      'authorised_scoped_paye_net_state_hash', v_expected_scoped_paye_net_state_hash,
      'current_scoped_paye_net_state_hash', v_current_scoped_paye_net_state_hash,
      'authorised_bank_payment_projection_hash', v_expected_bank_payment_projection_hash,
      'current_bank_payment_projection_hash', v_current_bank_payment_projection_hash,
      'projection_changed_after_authorisation', v_current_projection_changed,
      'projection_diagnostic', v_projection_diagnostic_json,
      'authorised_missing_explicit_paye_input_count', v_expected_missing_count,
      'current_missing_explicit_paye_input_count', v_current_missing_count,
      'authorised_scoped_explicit_zero_count', v_expected_zero_count,
      'current_scoped_explicit_zero_count', v_current_zero_count,
      'authorised_scoped_positive_bank_payment_count', v_expected_positive_count,
      'current_scoped_positive_bank_payment_count', v_current_positive_count,
      'completed_transfer_count', coalesce(v_completed_transfer_count, 0),
      'no_bank_scope_authorised', v_no_bank_scope_authorised,
      'no_bank_payment_execution', v_no_bank_payment_execution_validated,
      'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes_marker,
      'no_bank_scope_count', case when v_no_bank_scope_authorised then coalesce(v_no_bank_total_scope_count, 0) else null::integer end,
      'no_bank_scope_reference', case when v_no_bank_scope_authorised then v_local_no_bank_commit_ref else null::text end,
      'local_commit_reference', case when v_no_bank_payment_execution_validated then v_local_no_bank_commit_ref else null::text end,
      'no_bank_invalid_scope_count', case when v_no_bank_scope_authorised then coalesce(v_no_bank_invalid_scope_count, 0) else null::integer end,
      'no_bank_missing_scope_count', case when v_no_bank_scope_authorised then coalesce(v_no_bank_missing_scope_count, 0) else null::integer end,
      'no_bank_nonterminal_scope_count', case when v_no_bank_scope_authorised then coalesce(v_no_bank_nonterminal_scope_count, 0) else null::integer end,
      'no_bank_failed_scope_count', case when v_no_bank_scope_authorised then coalesce(v_no_bank_failed_scope_count, 0) else null::integer end,
      'no_bank_transfer_scope_count', case when v_no_bank_payment_execution_validated then coalesce(v_no_bank_scope_artifact_count, 0) else null::integer end,
      'no_bank_transfer_count', case when v_no_bank_payment_execution_validated then coalesce(v_no_bank_batch_transfer_count, 0) else null::integer end,
      'no_bank_transfer_event_count', case when v_no_bank_payment_execution_validated then coalesce(v_no_bank_transfer_event_count, 0) else null::integer end,
      'no_bank_provider_attempt_count', case when v_no_bank_payment_execution_validated then coalesce(v_no_bank_provider_attempt_count, 0) else null::integer end
    )
  ) || jsonb_build_object(
    'continuation', jsonb_build_object(
      'required', v_execution_operation_id IS NOT NULL,
      'operation_id', v_execution_operation_id,
      'operation_type', 'PAYMENT_EXECUTE',
      'pay_batch_id', p_pay_batch_id,
      'root_operation_id', v_execution_operation_id,
      'phase', 'WAITING_CHILD',
      'run_after_utc', clock_timestamp(),
      'reason', 'SETTLEMENT_STATE_APPLIED',
      'successor_relation', CASE WHEN v_execution_operation_id IS NULL THEN 'NONE' ELSE 'ROOT' END,
      'requires_user_action', false,
      'terminal', false
    )
  );
end;
$function$;

-- pay_settled_payment_reversal_apply_work_item(uuid,uuid)
CREATE OR REPLACE FUNCTION public.pay_settled_payment_reversal_apply_work_item(p_work_item_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_work_item public.pay_payment_correction_work_items%rowtype;
  v_request public.pay_payment_correction_requests%rowtype;
  v_batch public.pay_batches%rowtype;
  v_now timestamptz := now();
  v_effective_correction_kind text := NULL::text;
  v_blocker jsonb := '{}'::jsonb;
  v_result jsonb := '{}'::jsonb;
BEGIN
  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAYMENT_CORRECTION_SETTLED_REVERSAL_BLOCK_START',
    jsonb_build_object(
      'work_item_id', p_work_item_id,
      'actor_user_id', p_actor_user_id
    ),
    'pay_payment_correction',
    COALESCE(p_work_item_id::text, 'NO_WORK_ITEM_ID'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  IF p_work_item_id IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_WORK_ITEM_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAYMENT_CORRECTION_WORK_ITEM_ID_REQUIRED')::text;
  END IF;

  SELECT public.pay_payment_correction_work_items.*
  INTO v_work_item
  FROM public.pay_payment_correction_work_items
  WHERE public.pay_payment_correction_work_items.id = p_work_item_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_WORK_ITEM_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_WORK_ITEM_NOT_FOUND',
              'work_item_id', p_work_item_id
            )::text;
  END IF;

  SELECT public.pay_payment_correction_requests.*
  INTO v_request
  FROM public.pay_payment_correction_requests
  WHERE public.pay_payment_correction_requests.id = v_work_item.correction_request_id
  FOR UPDATE;

  IF FOUND THEN
    SELECT public.pay_batches.*
    INTO v_batch
    FROM public.pay_batches
    WHERE public.pay_batches.id = v_request.pay_batch_id
    FOR UPDATE;
  END IF;

  v_effective_correction_kind := upper(btrim(COALESCE(v_work_item.work_kind, v_request.correction_kind, 'SETTLED_REVERSAL')));

  IF upper(btrim(COALESCE(v_work_item.status, ''))) = 'APPLIED' THEN
    v_result := jsonb_build_object(
      'ok', true,
      'status', 'APPLIED',
      'legacy_audit_only', true,
      'work_item_id', p_work_item_id,
      'correction_request_id', v_work_item.correction_request_id,
      'pay_batch_id', COALESCE(v_work_item.pay_batch_id, v_request.pay_batch_id),
      'work_kind', v_work_item.work_kind,
      'correction_kind', v_request.correction_kind,
      'message', 'Legacy settled-reversal work item is already applied and remains audit history only. No new paid/settled reversal action was performed.'
    );

    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAYMENT_CORRECTION_SETTLED_REVERSAL_LEGACY_APPLIED_AUDIT_ONLY',
      v_result,
      'pay_payment_correction',
      p_work_item_id::text,
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RETURN v_result;
  END IF;

  v_blocker := jsonb_build_object(
    'code', 'PAID_SETTLED_RECOVERY_REQUIRED',
    'message', 'Paid/settled Banking Pay corrections must be handled through amendment and recovery, not settled payment reversal.',
    'recommended_action', 'AMEND_AND_RECOVER_OVERPAYMENT',
    'work_item_id', p_work_item_id,
    'correction_request_id', v_work_item.correction_request_id,
    'pay_batch_id', COALESCE(v_work_item.pay_batch_id, v_request.pay_batch_id),
    'work_kind', v_work_item.work_kind,
    'correction_kind', v_request.correction_kind,
    'effective_correction_kind', v_effective_correction_kind
  );

  v_result := jsonb_build_object(
    'ok', false,
    'status', 'BLOCKED',
    'blocker', v_blocker,
    'blockers', jsonb_build_array(v_blocker),
    'recommended_action', 'AMEND_AND_RECOVER_OVERPAYMENT',
    'payment_lifecycle_state', 'PAID_OR_SETTLED',
    'paid_settled_reversal_forbidden', true,
    'applied_at_utc', NULL::timestamptz,
    'processed_at_utc', v_now
  );

  UPDATE public.pay_payment_correction_work_items AS blocked_work_item
  SET
    status = 'BLOCKED',
    locked_at_utc = NULL,
    locked_by = NULL,
    processed_at_utc = COALESCE(blocked_work_item.processed_at_utc, v_now),
    processed_by_user_id = COALESCE(p_actor_user_id, blocked_work_item.processed_by_user_id),
    last_error = 'PAID_SETTLED_RECOVERY_REQUIRED',
    result_json = COALESCE(blocked_work_item.result_json, '{}'::jsonb) || v_result
  WHERE blocked_work_item.id = p_work_item_id
    AND upper(btrim(COALESCE(blocked_work_item.status, ''))) <> 'APPLIED';

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAYMENT_CORRECTION_SETTLED_REVERSAL_BLOCKED',
    v_result,
    'pay_payment_correction',
    p_work_item_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  RETURN v_result;
END;
$function$;

-- pay_snooze_clear_cross_pay_week_rate_resolutions_v1(uuid,uuid)
CREATE OR REPLACE FUNCTION public.pay_snooze_clear_cross_pay_week_rate_resolutions_v1(p_snooze_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  v_result := public.pay_snooze_resolution_transition_v1(
    p_snooze_id => p_snooze_id,
    p_actor_user_id => p_actor_user_id,
    p_transition_reason => 'MANUAL_UNSNOOZE'
  );

  RETURN jsonb_strip_nulls(
    COALESCE(v_result, '{}'::jsonb)
    || jsonb_build_object(
      'code', CASE
        WHEN COALESCE((v_result->>'review_required')::boolean, false)
          THEN 'RATE_RESOLUTION_REQUIRES_REVIEW_AFTER_UNSNOOZE'
        ELSE NULL
      END,
      'reason', CASE
        WHEN COALESCE((v_result->>'review_required')::boolean, false)
          THEN 'CROSS_PAY_WEEK_OR_STALE_SAME_WEEK_UNSNOOZE'
        ELSE COALESCE(v_result->>'reason', 'MANUAL_UNSNOOZE')
      END,
      'manual_unsnooze', true
    )
  );
END;
$function$;

-- pay_snooze_clear(uuid,uuid)
CREATE OR REPLACE FUNCTION public.pay_snooze_clear(p_snooze_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row record;
  v_candidate_id_hint uuid := NULL::uuid;
  v_before jsonb := NULL;
  v_after jsonb := NULL;
  v_finance_case_id uuid := NULL;

  v_finance_case_record public.pay_advances%rowtype;
  v_effective_from_date date := NULL;
  v_requested_week_start_date date := NULL;
  v_current_operating_week_start_date date := NULL;
  v_target_week_start date := NULL;
  v_next_due_week_start_before_restore_date date := NULL;
  v_next_due_week_start_after_restore_date date := NULL;

  v_schedule_restore_result jsonb := NULL;
  v_schedule_before_restore_json jsonb := NULL;
  v_next_due_week_start_before_restore text := NULL;
  v_requested_week_start text := NULL;
  v_current_operating_week_start text := NULL;
  v_schedule_after_restore_json jsonb := NULL;
  v_next_due_week_start_after_restore text := NULL;
  v_installment_count integer := NULL;
  v_rate_resolution_clear_result jsonb := '{}'::jsonb;
BEGIN
  IF p_snooze_id IS NULL THEN
    RAISE EXCEPTION 'snooze_id is required';
  END IF;

  SELECT s.candidate_id
  INTO v_candidate_id_hint
  FROM public.pay_item_snoozes AS s
  WHERE s.id = p_snooze_id;

  IF v_candidate_id_hint IS NULL THEN
    RAISE EXCEPTION 'SNOOZE_NOT_FOUND';
  END IF;

  -- Use the same candidate-then-row lock order as Snooze upsert, natural
  -- expiry and the final Create Draft guard.  Reading the immutable candidate
  -- identity first avoids a row-lock/advisory-lock inversion with a concurrent
  -- exact expense upsert or clear.
  PERFORM pg_advisory_xact_lock(
    pg_catalog.hashtext('public.banking_pay_candidate_snooze_guard'),
    pg_catalog.hashtext(v_candidate_id_hint::text)
  );

  SELECT
    s.id,
    s.candidate_id,
    s.timesheet_id,
    s.segment_id,
    s.source_ref,
    s.snooze_kind,
    s.snooze_until_date,
    s.note,
    s.created_at_utc,
    s.cleared_at_utc
  INTO v_row
  FROM public.pay_item_snoozes AS s
  WHERE s.id = p_snooze_id
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND OR v_row.candidate_id IS DISTINCT FROM v_candidate_id_hint THEN
    RAISE EXCEPTION 'SNOOZE_AUTHORITY_CHANGED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'SNOOZE_AUTHORITY_CHANGED',
              'snooze_id', p_snooze_id::text
            )::text;
  END IF;

  v_before := jsonb_build_object(
    'id', v_row.id::text,
    'candidate_id', v_row.candidate_id::text,
    'timesheet_id', CASE WHEN v_row.timesheet_id IS NULL THEN NULL ELSE v_row.timesheet_id::text END,
    'segment_id', v_row.segment_id,
    'source_ref', v_row.source_ref,
    'snooze_kind', v_row.snooze_kind,
    'snooze_until_date', CASE WHEN v_row.snooze_until_date IS NULL THEN NULL ELSE v_row.snooze_until_date::text END,
    'note', v_row.note,
    'cleared_at_utc', v_row.cleared_at_utc
  );

  perform public._ctms_clear_correction_chain_snoozes_v1(p_snooze_id,p_actor_user_id);

  IF v_row.cleared_at_utc IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'london_current_date', (clock_timestamp() AT TIME ZONE 'Europe/London')::date::text,
      'action', 'NOOP_ALREADY_CLEARED',
      'id', v_row.id::text
    );
  END IF;

  IF v_row.source_ref IS NOT NULL
     AND v_row.source_ref LIKE 'advance:%'
     AND split_part(v_row.source_ref, ':', 2) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  THEN
    v_finance_case_id := split_part(v_row.source_ref, ':', 2)::uuid;
  END IF;

  UPDATE public.pay_item_snoozes s
  SET
    cleared_at_utc = now(),
    cleared_by_user_id = p_actor_user_id,
    updated_at_utc = now(),
    updated_by_user_id = p_actor_user_id
  WHERE s.id = p_snooze_id;

  IF to_regprocedure('public.pay_snooze_clear_cross_pay_week_rate_resolutions_v1(uuid,uuid)') IS NOT NULL THEN
    v_rate_resolution_clear_result := public.pay_snooze_clear_cross_pay_week_rate_resolutions_v1(
      p_snooze_id,
      p_actor_user_id
    );
  ELSE
    RAISE EXCEPTION 'CROSS_PAY_WEEK_UNSNOOZE_HELPER_UNAVAILABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'CROSS_PAY_WEEK_UNSNOOZE_HELPER_UNAVAILABLE',
              'message', 'The snooze was not cleared because rate-resolution safety could not be verified.'
            )::text;
  END IF;

  IF v_finance_case_id IS NOT NULL
     AND upper(coalesce(v_row.snooze_kind, '')) IN ('OVERPAYMENT_RECOVERY', 'PAYMENT_ADVANCE_REPAYMENT', 'MANUAL_DEBT_RECOVERY')
     AND v_row.snooze_until_date IS NOT NULL
  THEN
    v_effective_from_date := (now() AT TIME ZONE 'Europe/London')::date;

    SELECT pa.*
    INTO v_finance_case_record
    FROM public.pay_advances AS pa
    WHERE pa.id = v_finance_case_id
    LIMIT 1
    FOR UPDATE;

    IF v_finance_case_record.id IS NULL THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_REPAYMENT_SCHEDULE_RESTORE_AFTER_SNOOZE_CLEAR',
        'code', 'FINANCE_CASE_NOT_FOUND',
        'message', '_pay_repayment_schedule_restore_after_snooze_clear: finance case not found',
        'finance_case_id', v_finance_case_id::text
      )::text;
    END IF;

    IF v_finance_case_record.case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum THEN
      v_schedule_before_restore_json := coalesce(v_finance_case_record.schedule_json, '[]'::jsonb);
      v_next_due_week_start_before_restore_date := v_finance_case_record.next_due_week_start;
      v_requested_week_start_date := public._pay_week_start_monday(v_effective_from_date);
      v_current_operating_week_start_date := public._pay_week_start_monday((now() AT TIME ZONE 'Europe/London')::date);

      IF v_requested_week_start_date < v_current_operating_week_start_date THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_REPAYMENT_SCHEDULE_RESTORE_AFTER_SNOOZE_CLEAR',
          'code', 'EFFECTIVE_FROM_DATE_BEFORE_NOW',
          'message', '_pay_repayment_schedule_restore_after_snooze_clear: effective_from_date cannot restore the repayment schedule earlier than the current operating week',
          'finance_case_id', v_finance_case_id::text,
          'requested_week_start', v_requested_week_start_date::text,
          'current_operating_week_start', v_current_operating_week_start_date::text
        )::text;
      END IF;

      v_target_week_start := v_requested_week_start_date;

      WITH schedule_rows AS (
        SELECT
          row_number() OVER (ORDER BY (elem.value ->> 'week_start')::date ASC, elem.ordinality ASC) AS seq_no,
          round(coalesce((elem.value ->> 'amount')::numeric, 0), 2) AS amount_value
        FROM jsonb_array_elements(v_schedule_before_restore_json) WITH ORDINALITY AS elem(value, ordinality)
        WHERE coalesce((elem.value ->> 'amount')::numeric, 0) < 0
      )
      SELECT
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'week_start', (v_target_week_start + (((sr.seq_no - 1)::integer) * 7))::date,
              'amount', sr.amount_value
            )
            ORDER BY (v_target_week_start + (((sr.seq_no - 1)::integer) * 7))::date ASC
          ),
          '[]'::jsonb
        ),
        count(*)::integer
      INTO v_schedule_after_restore_json, v_installment_count
      FROM schedule_rows AS sr;

      v_next_due_week_start_after_restore_date := CASE
        WHEN v_installment_count > 0 THEN v_target_week_start
        ELSE NULL
      END;

      UPDATE public.pay_advances AS pa
      SET schedule_json = v_schedule_after_restore_json,
          next_due_week_start = v_next_due_week_start_after_restore_date,
          updated_at = now()
      WHERE pa.id = v_finance_case_id;

      v_schedule_restore_result := jsonb_build_object(
        'ok', true,
        'finance_case_id', v_finance_case_id::text,
        'schedule_before_restore_json', v_schedule_before_restore_json,
        'next_due_week_start_before_restore', CASE WHEN v_next_due_week_start_before_restore_date IS NULL THEN NULL ELSE v_next_due_week_start_before_restore_date::text END,
        'requested_week_start', CASE WHEN v_requested_week_start_date IS NULL THEN NULL ELSE v_requested_week_start_date::text END,
        'current_operating_week_start', CASE WHEN v_current_operating_week_start_date IS NULL THEN NULL ELSE v_current_operating_week_start_date::text END,
        'schedule_after_restore_json', v_schedule_after_restore_json,
        'next_due_week_start_after_restore', CASE WHEN v_next_due_week_start_after_restore_date IS NULL THEN NULL ELSE v_next_due_week_start_after_restore_date::text END,
        'installment_count', v_installment_count
      );
    ELSE
      v_schedule_restore_result := public._pay_repayment_schedule_restore_after_snooze_clear(
        v_finance_case_id,
        v_effective_from_date
      );
    END IF;

    v_schedule_before_restore_json := v_schedule_restore_result -> 'schedule_before_restore_json';
    v_next_due_week_start_before_restore_date := CASE
      WHEN nullif(btrim(coalesce(v_schedule_restore_result ->> 'next_due_week_start_before_restore', '')), '') IS NULL THEN NULL
      ELSE (v_schedule_restore_result ->> 'next_due_week_start_before_restore')::date
    END;
    v_next_due_week_start_before_restore := CASE
      WHEN v_next_due_week_start_before_restore_date IS NULL THEN NULL
      ELSE v_next_due_week_start_before_restore_date::text
    END;
    v_requested_week_start_date := CASE
      WHEN nullif(btrim(coalesce(v_schedule_restore_result ->> 'requested_week_start', '')), '') IS NULL THEN NULL
      ELSE (v_schedule_restore_result ->> 'requested_week_start')::date
    END;
    v_requested_week_start := CASE
      WHEN v_requested_week_start_date IS NULL THEN NULL
      ELSE v_requested_week_start_date::text
    END;
    v_current_operating_week_start_date := CASE
      WHEN nullif(btrim(coalesce(v_schedule_restore_result ->> 'current_operating_week_start', '')), '') IS NULL THEN NULL
      ELSE (v_schedule_restore_result ->> 'current_operating_week_start')::date
    END;
    v_current_operating_week_start := CASE
      WHEN v_current_operating_week_start_date IS NULL THEN NULL
      ELSE v_current_operating_week_start_date::text
    END;
    v_schedule_after_restore_json := v_schedule_restore_result -> 'schedule_after_restore_json';
    v_next_due_week_start_after_restore_date := CASE
      WHEN nullif(btrim(coalesce(v_schedule_restore_result ->> 'next_due_week_start_after_restore', '')), '') IS NULL THEN NULL
      ELSE (v_schedule_restore_result ->> 'next_due_week_start_after_restore')::date
    END;
    v_next_due_week_start_after_restore := CASE
      WHEN v_next_due_week_start_after_restore_date IS NULL THEN NULL
      ELSE v_next_due_week_start_after_restore_date::text
    END;
    v_installment_count := CASE
      WHEN nullif(btrim(coalesce(v_schedule_restore_result ->> 'installment_count', '')), '') ~ '^-?[0-9]+$'
      THEN (v_schedule_restore_result ->> 'installment_count')::integer
      ELSE NULL
    END;
  END IF;

  SELECT
    jsonb_build_object(
      'id', s.id::text,
      'candidate_id', s.candidate_id::text,
      'timesheet_id', CASE WHEN s.timesheet_id IS NULL THEN NULL ELSE s.timesheet_id::text END,
      'segment_id', s.segment_id,
      'source_ref', s.source_ref,
      'snooze_kind', s.snooze_kind,
      'snooze_until_date', CASE WHEN s.snooze_until_date IS NULL THEN NULL ELSE s.snooze_until_date::text END,
      'note', s.note,
      'cleared_at_utc', s.cleared_at_utc
    )
    ||
    CASE
      WHEN v_schedule_restore_result IS NULL THEN '{}'::jsonb
      ELSE jsonb_build_object('schedule_restore_result', v_schedule_restore_result)
    END
  INTO v_after
  FROM public.pay_item_snoozes s
  WHERE s.id = p_snooze_id;

  IF v_finance_case_id IS NOT NULL THEN
    INSERT INTO public.pay_finance_case_events (
      finance_case_id,
      event_type,
      event_at_utc,
      actor_user_id,
      before_json,
      after_json,
      reason,
      note
    )
    VALUES (
      v_finance_case_id,
      'SNOOZE_CLEARED',
      now(),
      p_actor_user_id,
      v_before,
      v_after,
      COALESCE(v_row.snooze_kind, 'SNOOZE_CLEARED'),
      v_row.note
    );

    PERFORM public._audit_insert(
      'finance_case',
      v_finance_case_id::text,
      'SNOOZE_CLEARED',
      v_before,
      v_after,
      COALESCE(v_row.snooze_kind, 'SNOOZE_CLEARED'),
      p_actor_user_id
    );
  ELSIF v_row.timesheet_id IS NOT NULL THEN
    PERFORM public._audit_insert(
      'timesheets',
      v_row.timesheet_id::text,
      'SNOOZE_CLEARED',
      v_before,
      v_after,
      COALESCE(v_row.snooze_kind, 'SNOOZE_CLEARED'),
      p_actor_user_id
    );
  ELSE
    PERFORM public._audit_insert(
      'pay_item_snoozes',
      v_row.id::text,
      'SNOOZE_CLEARED',
      v_before,
      v_after,
      COALESCE(v_row.snooze_kind, 'SNOOZE_CLEARED'),
      p_actor_user_id
    );
  END IF;

  RETURN
    jsonb_build_object(
      'ok', true,
      'london_current_date', (clock_timestamp() AT TIME ZONE 'Europe/London')::date::text,
      'rate_resolution_review_required_after_cross_pay_week_unsnooze',
        COALESCE((v_rate_resolution_clear_result->>'review_required')::boolean, false),
      'rate_resolution_clear_result', COALESCE(v_rate_resolution_clear_result, '{}'::jsonb),
      'action', 'CLEARED',
      'id', v_row.id::text,
      'candidate_id', v_row.candidate_id::text,
      'timesheet_id', CASE WHEN v_row.timesheet_id IS NULL THEN NULL ELSE v_row.timesheet_id::text END,
      'segment_id', v_row.segment_id,
      'source_ref', v_row.source_ref,
      'finance_case_id', CASE WHEN v_finance_case_id IS NULL THEN NULL ELSE v_finance_case_id::text END,
      'snooze_kind', v_row.snooze_kind,
      'preview_visibility_hint', 'RELOAD_PREVIEW'
    )
    ||
    jsonb_build_object(
      'schedule_before_restore_json', v_schedule_before_restore_json,
      'next_due_week_start_before_restore', v_next_due_week_start_before_restore,
      'requested_week_start', v_requested_week_start,
      'current_operating_week_start', v_current_operating_week_start,
      'schedule_after_restore_json', v_schedule_after_restore_json,
      'next_due_week_start_after_restore', v_next_due_week_start_after_restore,
      'installment_count', v_installment_count
    );
END;
$function$;

-- pay_snooze_resolution_transition_v1(uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.pay_snooze_resolution_transition_v1(p_snooze_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_transition_reason text DEFAULT 'MANUAL_UNSNOOZE'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_transition_reason text := UPPER(BTRIM(COALESCE(p_transition_reason, 'MANUAL_UNSNOOZE')));
  v_date_context jsonb;
  v_today_uk date;
  v_current_official_pay_date date;
  v_context_fingerprint text;
  v_snooze public.pay_item_snoozes%ROWTYPE;
  v_candidate_id_hint uuid;
  v_scope_kind text;
  v_is_timesheet_expense_scope boolean := false;
  v_actor_user_id uuid := p_actor_user_id;
  v_refresh_actor_user_id uuid;
  v_scope record;
  v_matched_count integer := 0;
  v_cross_week_count integer := 0;
  v_stale_same_week_count integer := 0;
  v_retained_same_week_count integer := 0;
  v_deleted_count integer := 0;
  v_session_count integer := 0;
  v_job_result jsonb := '{}'::jsonb;
  v_job_id_text text;
  v_job_id uuid;
  v_job_ids jsonb := '[]'::jsonb;
  v_affected_sessions jsonb := '[]'::jsonb;
BEGIN
  IF p_snooze_id IS NULL THEN
    RAISE EXCEPTION 'SNOOZE_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'SNOOZE_ID_REQUIRED')::text;
  END IF;

  IF v_transition_reason NOT IN ('MANUAL_UNSNOOZE', 'NATURAL_EXPIRY') THEN
    RAISE EXCEPTION 'SNOOZE_RESOLUTION_TRANSITION_REASON_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'SNOOZE_RESOLUTION_TRANSITION_REASON_INVALID',
              'transition_reason', v_transition_reason
            )::text;
  END IF;

  SELECT snooze_row.candidate_id
  INTO v_candidate_id_hint
  FROM public.pay_item_snoozes AS snooze_row
  WHERE snooze_row.id = p_snooze_id;

  IF v_candidate_id_hint IS NULL THEN
    RAISE EXCEPTION 'SNOOZE_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'SNOOZE_NOT_FOUND')::text;
  END IF;

  PERFORM pg_advisory_xact_lock(
    pg_catalog.hashtext('public.banking_pay_candidate_snooze_guard'),
    pg_catalog.hashtext(v_candidate_id_hint::text)
  );

  SELECT snooze_row.*
  INTO v_snooze
  FROM public.pay_item_snoozes AS snooze_row
  WHERE snooze_row.id = p_snooze_id
  FOR UPDATE;

  IF v_snooze.id IS NULL OR v_snooze.candidate_id IS DISTINCT FROM v_candidate_id_hint THEN
    RAISE EXCEPTION 'SNOOZE_AUTHORITY_CHANGED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'SNOOZE_AUTHORITY_CHANGED',
              'snooze_id', p_snooze_id::text
            )::text;
  END IF;

  v_date_context := public.pay_banking_official_date_context_v1(NULL::timestamptz);
  v_today_uk := (v_date_context->>'business_date')::date;
  v_current_official_pay_date := (v_date_context->>'current_official_pay_date')::date;
  v_context_fingerprint := v_date_context->>'configuration_fingerprint';

  IF v_transition_reason = 'NATURAL_EXPIRY' THEN
    IF v_snooze.snooze_until_date IS NULL
       OR v_snooze.cleared_at_utc IS NOT NULL
       OR v_snooze.cancelled_at_utc IS NOT NULL
       OR v_snooze.snooze_until_date >= v_today_uk THEN
      RAISE EXCEPTION 'SNOOZE_NATURAL_EXPIRY_NOT_DUE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'SNOOZE_NATURAL_EXPIRY_NOT_DUE',
                'snooze_id', v_snooze.id::text,
                'snooze_until_date', CASE WHEN v_snooze.snooze_until_date IS NULL THEN NULL ELSE v_snooze.snooze_until_date::text END,
                'london_current_date', v_today_uk::text,
                'cleared', v_snooze.cleared_at_utc IS NOT NULL,
                'cancelled', v_snooze.cancelled_at_utc IS NOT NULL
              )::text;
    END IF;
  ELSE
    IF v_snooze.cleared_at_utc IS NULL OR v_snooze.cancelled_at_utc IS NOT NULL THEN
      RAISE EXCEPTION 'SNOOZE_MANUAL_UNSNOOZE_NOT_CLEARED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'SNOOZE_MANUAL_UNSNOOZE_NOT_CLEARED',
                'snooze_id', v_snooze.id::text,
                'message', 'The snooze must be cleared by the owning transaction before rate authority is transitioned.'
              )::text;
    END IF;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_snooze.snooze_kind, ''))) NOT IN ('DO_NOT_PAY', 'BLOCKED_TIMESHEET', 'TIMESHEET_PAYMENT') THEN
    RETURN jsonb_build_object(
      'ok', true,
      'state_changed', false,
      'review_required', false,
      'reason', 'SNOOZE_KIND_NOT_PAYMENT_SCOPE',
      'transition_reason', v_transition_reason,
      'snooze_id', v_snooze.id::text,
      'snooze_kind', v_snooze.snooze_kind,
      'london_current_date', v_today_uk::text,
      'current_official_pay_date', v_current_official_pay_date::text,
      'configuration_fingerprint', v_context_fingerprint,
      'deleted_resolution_count', 0,
      'job_ids', '[]'::jsonb
    );
  END IF;

  IF v_snooze.timesheet_id IS NULL THEN
    RAISE EXCEPTION 'SNOOZE_PAYMENT_SCOPE_UNVERIFIABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'SNOOZE_PAYMENT_SCOPE_UNVERIFIABLE',
              'snooze_id', v_snooze.id::text
            )::text;
  END IF;

  v_is_timesheet_expense_scope := (
    v_snooze.timesheet_id IS NOT NULL
    AND NULLIF(BTRIM(COALESCE(v_snooze.segment_stable_key, '')), '') IS NULL
    AND NULLIF(BTRIM(COALESCE(v_snooze.segment_id, '')), '') IS NULL
    AND UPPER(BTRIM(COALESCE(v_snooze.snooze_kind, ''))) = 'DO_NOT_PAY'
    AND LOWER(BTRIM(COALESCE(v_snooze.source_ref, ''))) ~
      '^timesheet-expense:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}:(expenses|travel|accommodation|other|mileage):[0-9a-f]{32}$'
    AND split_part(LOWER(BTRIM(v_snooze.source_ref)), ':', 2)::uuid IS NOT DISTINCT FROM v_snooze.timesheet_id
  );

  v_scope_kind := CASE
    WHEN COALESCE(v_is_timesheet_expense_scope, false) THEN 'TIMESHEET_EXPENSE'
    WHEN NULLIF(BTRIM(COALESCE(v_snooze.segment_stable_key, '')), '') IS NOT NULL
      OR NULLIF(BTRIM(COALESCE(v_snooze.segment_id, '')), '') IS NOT NULL
      THEN 'SEGMENT'
    ELSE 'TIMESHEET'
  END;

  IF NOT (
    (v_scope_kind = 'SEGMENT' AND UPPER(BTRIM(v_snooze.snooze_kind)) IN ('DO_NOT_PAY', 'BLOCKED_TIMESHEET'))
    OR
    (v_scope_kind = 'TIMESHEET' AND UPPER(BTRIM(v_snooze.snooze_kind)) = 'TIMESHEET_PAYMENT')
    OR
    (v_scope_kind = 'TIMESHEET_EXPENSE' AND UPPER(BTRIM(v_snooze.snooze_kind)) = 'DO_NOT_PAY')
  ) THEN
    RAISE EXCEPTION 'SNOOZE_PAYMENT_SCOPE_IDENTITY_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'SNOOZE_PAYMENT_SCOPE_IDENTITY_MISMATCH',
              'snooze_id', v_snooze.id::text,
              'snooze_kind', v_snooze.snooze_kind,
              'scope_kind', v_scope_kind
            )::text;
  END IF;

  IF v_actor_user_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.tms_users AS actor_row
      WHERE actor_row.id = v_actor_user_id
        AND actor_row.is_active = true
    ) THEN
      RAISE EXCEPTION 'SNOOZE_RESOLUTION_TRANSITION_ACTOR_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'SNOOZE_RESOLUTION_TRANSITION_ACTOR_INVALID',
                'actor_user_id', v_actor_user_id::text
              )::text;
    END IF;
  END IF;

  IF v_scope_kind = 'TIMESHEET_EXPENSE' THEN
    RETURN jsonb_build_object(
      'ok', true,
      'state_changed', false,
      'review_required', false,
      'reason', 'TIMESHEET_EXPENSE_SCOPE_NO_RATE_TRANSITION',
      'transition_reason', v_transition_reason,
      'snooze_id', v_snooze.id::text,
      'snooze_kind', v_snooze.snooze_kind,
      'scope_kind', v_scope_kind,
      'candidate_id', v_snooze.candidate_id::text,
      'timesheet_id', v_snooze.timesheet_id::text,
      'source_ref', v_snooze.source_ref,
      'london_current_date', v_today_uk::text,
      'current_official_pay_date', v_current_official_pay_date::text,
      'configuration_fingerprint', v_context_fingerprint,
      'matched_resolution_count', 0,
      'cross_week_resolution_count', 0,
      'stale_same_week_resolution_count', 0,
      'retained_same_week_resolution_count', 0,
      'deleted_resolution_count', 0,
      'job_ids', '[]'::jsonb,
      'affected_sessions', '[]'::jsonb
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp._bpay_snooze_resolution_transition;
  CREATE TEMP TABLE _bpay_snooze_resolution_transition ON COMMIT DROP AS
  WITH exact_resolutions AS (
    SELECT resolution_row.*,
           session_row.source_snapshot_run_id,
           session_row.pay_date AS resolution_session_pay_date,
           EXISTS (
             SELECT 1
             FROM public.banking_pay_snapshot_case_component_state AS current_basis
             WHERE current_basis.snapshot_run_id = session_row.source_snapshot_run_id
               AND current_basis.candidate_id = resolution_row.candidate_id
               AND current_basis.case_key IS NOT DISTINCT FROM resolution_row.case_key
               AND (
                 resolution_row.timesheet_id IS NULL
                 OR current_basis.timesheet_id IS NOT DISTINCT FROM resolution_row.timesheet_id
               )
               AND current_basis.source_basis_fingerprint IS NOT DISTINCT FROM resolution_row.source_basis_fingerprint
           ) AS source_basis_still_current
    FROM public.banking_pay_workbench_session_case_resolutions AS resolution_row
    JOIN public.banking_pay_workbench_sessions AS session_row
      ON session_row.id = resolution_row.session_id
    WHERE resolution_row.candidate_id = v_snooze.candidate_id
      AND resolution_row.timesheet_id = v_snooze.timesheet_id
      AND UPPER(BTRIM(COALESCE(resolution_row.resolution_family, ''))) IN ('BUCKETED', 'NON_BUCKET')
      AND session_row.status = 'OPEN'
      AND session_row.discarded_at_utc IS NULL
      AND session_row.replacement_session_id IS NULL
      AND (
        v_scope_kind = 'TIMESHEET'
        OR (
          v_scope_kind = 'SEGMENT'
          AND (
            (
              NULLIF(BTRIM(COALESCE(v_snooze.segment_stable_key, '')), '') IS NOT NULL
              AND (
                NULLIF(BTRIM(COALESCE(resolution_row.payload_json->>'segment_stable_key', '')), '') = NULLIF(BTRIM(v_snooze.segment_stable_key), '')
                OR NULLIF(BTRIM(COALESCE(resolution_row.payload_json#>>'{source_basis_json,segment_stable_key}', '')), '') = NULLIF(BTRIM(v_snooze.segment_stable_key), '')
                OR NULLIF(BTRIM(COALESCE(resolution_row.payload_json#>>'{linked_resolution_scope_json,segment_stable_key}', '')), '') = NULLIF(BTRIM(v_snooze.segment_stable_key), '')
                OR EXISTS (
                  SELECT 1
                  FROM jsonb_array_elements(
                    CASE
                      WHEN jsonb_typeof(resolution_row.payload_json->'bucket_resolutions') = 'array'
                        THEN resolution_row.payload_json->'bucket_resolutions'
                      ELSE '[]'::jsonb
                    END
                  ) AS bucket_resolution(value)
                  WHERE NULLIF(BTRIM(COALESCE(bucket_resolution.value->>'segment_stable_key', '')), '') = NULLIF(BTRIM(v_snooze.segment_stable_key), '')
                     OR NULLIF(BTRIM(COALESCE(bucket_resolution.value#>>'{source_basis_json,segment_stable_key}', '')), '') = NULLIF(BTRIM(v_snooze.segment_stable_key), '')
                )
              )
            )
            OR
            (
              NULLIF(BTRIM(COALESCE(v_snooze.segment_stable_key, '')), '') IS NULL
              AND NULLIF(BTRIM(COALESCE(v_snooze.segment_id, '')), '') IS NOT NULL
              AND (
                NULLIF(BTRIM(COALESCE(resolution_row.payload_json->>'segment_id', '')), '') = NULLIF(BTRIM(v_snooze.segment_id), '')
                OR NULLIF(BTRIM(COALESCE(resolution_row.payload_json#>>'{source_basis_json,segment_id}', '')), '') = NULLIF(BTRIM(v_snooze.segment_id), '')
                OR NULLIF(BTRIM(COALESCE(resolution_row.payload_json#>>'{linked_resolution_scope_json,segment_id}', '')), '') = NULLIF(BTRIM(v_snooze.segment_id), '')
                OR EXISTS (
                  SELECT 1
                  FROM jsonb_array_elements(
                    CASE
                      WHEN jsonb_typeof(resolution_row.payload_json->'bucket_resolutions') = 'array'
                        THEN resolution_row.payload_json->'bucket_resolutions'
                      ELSE '[]'::jsonb
                    END
                  ) AS bucket_resolution(value)
                  WHERE NULLIF(BTRIM(COALESCE(bucket_resolution.value->>'segment_id', '')), '') = NULLIF(BTRIM(v_snooze.segment_id), '')
                     OR NULLIF(BTRIM(COALESCE(bucket_resolution.value#>>'{source_basis_json,segment_id}', '')), '') = NULLIF(BTRIM(v_snooze.segment_id), '')
                )
              )
            )
          )
        )
      )
  )
  SELECT exact_resolution.*,
         exact_resolution.resolution_origin_pay_date IS DISTINCT FROM v_current_official_pay_date AS cross_week,
         CASE
           WHEN exact_resolution.resolution_origin_pay_date IS DISTINCT FROM v_current_official_pay_date THEN 'CROSS_PAY_WEEK'
           WHEN exact_resolution.source_basis_still_current IS NOT TRUE THEN 'SAME_WEEK_SOURCE_BASIS_STALE'
           ELSE 'SAME_WEEK_SOURCE_BASIS_CURRENT'
         END AS transition_class,
         (
           exact_resolution.resolution_origin_pay_date IS DISTINCT FROM v_current_official_pay_date
           OR exact_resolution.source_basis_still_current IS NOT TRUE
         ) AS should_clear
  FROM exact_resolutions AS exact_resolution;

  SELECT COUNT(*)::integer,
         COUNT(*) FILTER (WHERE transition_row.cross_week IS TRUE)::integer,
         COUNT(*) FILTER (WHERE transition_row.cross_week IS NOT TRUE AND transition_row.source_basis_still_current IS NOT TRUE)::integer,
         COUNT(*) FILTER (WHERE transition_row.cross_week IS NOT TRUE AND transition_row.source_basis_still_current IS TRUE)::integer
  INTO v_matched_count,
       v_cross_week_count,
       v_stale_same_week_count,
       v_retained_same_week_count
  FROM pg_temp._bpay_snooze_resolution_transition AS transition_row;

  WITH deleted_rows AS (
    DELETE FROM public.banking_pay_workbench_session_case_resolutions AS resolution_delete
    USING pg_temp._bpay_snooze_resolution_transition AS transition_row
    WHERE resolution_delete.id = transition_row.id
      AND transition_row.should_clear IS TRUE
    RETURNING resolution_delete.id
  )
  SELECT COUNT(*)::integer
  INTO v_deleted_count
  FROM deleted_rows;

  FOR v_scope IN
    SELECT transition_row.session_id,
           transition_row.candidate_id,
           MIN(transition_row.resolution_origin_pay_date) FILTER (WHERE transition_row.should_clear IS TRUE) AS origin_pay_date_min,
           MAX(transition_row.resolution_origin_pay_date) FILTER (WHERE transition_row.should_clear IS TRUE) AS origin_pay_date_max,
           COUNT(*) FILTER (WHERE transition_row.should_clear IS TRUE)::integer AS cleared_count
    FROM pg_temp._bpay_snooze_resolution_transition AS transition_row
    GROUP BY transition_row.session_id, transition_row.candidate_id
    HAVING COUNT(*) FILTER (WHERE transition_row.should_clear IS TRUE) > 0
    ORDER BY transition_row.session_id, transition_row.candidate_id
  LOOP
    v_session_count := v_session_count + 1;
    SELECT COALESCE(p_actor_user_id, session_actor.actor_user_id)
    INTO v_refresh_actor_user_id
    FROM public.banking_pay_workbench_sessions AS session_actor
    WHERE session_actor.id = v_scope.session_id;

    IF v_refresh_actor_user_id IS NULL OR NOT EXISTS (
      SELECT 1
      FROM public.tms_users AS refresh_actor
      WHERE refresh_actor.id = v_refresh_actor_user_id
        AND refresh_actor.is_active IS TRUE
    ) THEN
      RAISE EXCEPTION 'SNOOZE_TRANSITION_REFRESH_ACTOR_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'SNOOZE_TRANSITION_REFRESH_ACTOR_INVALID',
                'session_id', v_scope.session_id::text,
                'actor_user_id', CASE WHEN v_refresh_actor_user_id IS NULL THEN NULL ELSE v_refresh_actor_user_id::text END
              )::text;
    END IF;

    UPDATE public.banking_pay_workbench_sessions AS session_update
    SET version = session_update.version + 1,
        progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
        progress_updated_at_utc = v_now,
        updated_at_utc = v_now,
        progress_json = jsonb_strip_nulls(
          COALESCE(session_update.progress_json, '{}'::jsonb)
          || jsonb_build_object(
            'rate_resolution_review_required_after_snooze_transition', true,
            'rate_resolution_review_reason', v_transition_reason,
            'rate_resolution_review_scope_kind', v_scope_kind,
            'rate_resolution_review_timesheet_id', v_snooze.timesheet_id::text,
            'rate_resolution_review_segment_id', NULLIF(BTRIM(COALESCE(v_snooze.segment_id, '')), ''),
            'rate_resolution_review_segment_stable_key', NULLIF(BTRIM(COALESCE(v_snooze.segment_stable_key, '')), ''),
            'rate_resolution_origin_pay_date_min', v_scope.origin_pay_date_min::text,
            'rate_resolution_origin_pay_date_max', v_scope.origin_pay_date_max::text,
            'rate_resolution_current_pay_date', v_current_official_pay_date::text,
            'rate_resolution_cleared_count', v_scope.cleared_count
          )
        )
    WHERE session_update.id = v_scope.session_id;

    v_job_result := public.pay_workbench_enqueue_session_candidate_refresh(
      p_session_id => v_scope.session_id,
      p_candidate_id => v_scope.candidate_id,
      p_reason => CASE
        WHEN v_transition_reason = 'NATURAL_EXPIRY' THEN 'NATURAL_EXPIRY_RATE_RESOLUTION_CLEARED'
        ELSE 'CROSS_PAY_WEEK_UNSNOOZE_RATE_RESOLUTION_CLEARED'
      END,
      p_actor_user_id => v_refresh_actor_user_id,
      p_payload_json => jsonb_build_object(
        'refresh_scope_kind', 'TARGETED_TIMESHEETS',
        'targeted_timesheet_ids', jsonb_build_array(v_snooze.timesheet_id::text),
        'force_legacy', true,
        'projection_mode', 'LEGACY',
        'projection_class', 'CASE_RESOLUTION',
        'fallback_reason', 'CASE_RESOLUTION_CHANGED',
        'source_build_required', true,
        'line_work_required', true,
        'delta_refresh_required', false,
        'complex_refresh_required', true,
        'resolved_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'rate_resolution_review_required', true,
        'rate_resolution_review_reason', v_transition_reason,
        'rate_resolution_review_scope_kind', v_scope_kind,
        'segment_id', NULLIF(BTRIM(COALESCE(v_snooze.segment_id, '')), ''),
        'segment_stable_key', NULLIF(BTRIM(COALESCE(v_snooze.segment_stable_key, '')), ''),
        'origin_pay_date_min', v_scope.origin_pay_date_min::text,
        'origin_pay_date_max', v_scope.origin_pay_date_max::text,
        'current_official_pay_date', v_current_official_pay_date::text,
        'configuration_fingerprint', v_context_fingerprint
      )
    );

    v_job_id_text := BTRIM(COALESCE(
      v_job_result->>'job_id',
      v_job_result#>>'{enqueue_result,job_id}',
      v_job_result#>>'{enqueue_result,job_ids,0}',
      v_job_result#>>'{job_ids,0}',
      v_job_result#>>'{enqueue_result,session_recompute_job_ids,0}',
      v_job_result#>>'{session_recompute_job_ids,0}',
      ''
    ));
    v_job_id := NULL::uuid;
    IF v_job_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_job_id := v_job_id_text::uuid;
    END IF;

    IF v_job_id IS NULL OR NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_jobs AS job_row
      WHERE job_row.id = v_job_id
        AND job_row.session_id = v_scope.session_id
        AND job_row.candidate_id = v_scope.candidate_id
        AND job_row.status IN ('QUEUED', 'RUNNING', 'SUCCEEDED')
    ) THEN
      RAISE EXCEPTION 'WORKBENCH_REFRESH_JOB_NOT_PROVEN'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'WORKBENCH_REFRESH_JOB_NOT_PROVEN',
                'session_id', v_scope.session_id::text,
                'candidate_id', v_scope.candidate_id::text,
                'transition_reason', v_transition_reason
              )::text;
    END IF;

    v_job_ids := v_job_ids || jsonb_build_array(v_job_id::text);
    v_affected_sessions := v_affected_sessions || jsonb_build_array(
      jsonb_build_object(
        'session_id', v_scope.session_id::text,
        'candidate_id', v_scope.candidate_id::text,
        'job_id', v_job_id::text,
        'cleared_resolution_count', v_scope.cleared_count,
        'origin_pay_date_min', v_scope.origin_pay_date_min::text,
        'origin_pay_date_max', v_scope.origin_pay_date_max::text
      )
    );
  END LOOP;

  INSERT INTO public.audit_events(
    object_type,
    object_id_text,
    action,
    before_json,
    after_json,
    reason,
    actor_user_id
  )
  SELECT 'banking_pay_workbench_session_case_resolution',
         transition_row.id::text,
         'SESSION_CASE_RESOLUTION_CLEARED',
         jsonb_build_object(
           'session_id', transition_row.session_id::text,
           'candidate_id', transition_row.candidate_id::text,
           'timesheet_id', CASE WHEN transition_row.timesheet_id IS NULL THEN NULL ELSE transition_row.timesheet_id::text END,
           'case_key', transition_row.case_key,
           'resolution_identity_key', transition_row.resolution_identity_key,
           'resolution_origin_session_id', transition_row.resolution_origin_session_id::text,
           'resolution_origin_pay_date', transition_row.resolution_origin_pay_date::text,
           'payload_json', transition_row.payload_json
         ),
         jsonb_build_object(
           'cleared_at_utc', v_now,
           'transition_reason', v_transition_reason,
           'transition_class', transition_row.transition_class,
           'scope_kind', v_scope_kind,
           'current_official_pay_date', v_current_official_pay_date::text
         ),
         v_transition_reason || '_RATE_RESOLUTION_CLEARED',
         COALESCE(
           p_actor_user_id,
           (
             SELECT audit_session.actor_user_id
             FROM public.banking_pay_workbench_sessions AS audit_session
             WHERE audit_session.id = transition_row.session_id
           )
         )
  FROM pg_temp._bpay_snooze_resolution_transition AS transition_row
  WHERE transition_row.should_clear IS TRUE;

  RETURN jsonb_build_object(
    'ok', true,
    'state_changed', v_deleted_count > 0,
    'review_required', v_deleted_count > 0,
    'code', CASE WHEN v_deleted_count > 0 THEN 'RATE_RESOLUTION_REQUIRES_REVIEW_AFTER_SNOOZE_TRANSITION' ELSE NULL END,
    'reason', v_transition_reason,
    'snooze_id', v_snooze.id::text,
    'snooze_kind', v_snooze.snooze_kind,
    'scope_kind', v_scope_kind,
    'timesheet_id', v_snooze.timesheet_id::text,
    'segment_id', NULLIF(BTRIM(COALESCE(v_snooze.segment_id, '')), ''),
    'segment_stable_key', NULLIF(BTRIM(COALESCE(v_snooze.segment_stable_key, '')), ''),
    'london_current_date', v_today_uk::text,
    'current_official_pay_date', v_current_official_pay_date::text,
    'configuration_fingerprint', v_context_fingerprint,
    'matched_resolution_count', v_matched_count,
    'cross_week_resolution_count', v_cross_week_count,
    'stale_same_week_resolution_count', v_stale_same_week_count,
    'retained_same_week_resolution_count', v_retained_same_week_count,
    'deleted_resolution_count', v_deleted_count,
    'affected_session_count', v_session_count,
    'affected_sessions', v_affected_sessions,
    'job_ids', v_job_ids
  );
END;
$function$;

-- pay_snooze_upsert_v2(uuid,uuid,text,text,text,date,uuid,text,text,text,text)
CREATE OR REPLACE FUNCTION public.pay_snooze_upsert_v2(p_candidate_id uuid, p_timesheet_id uuid, p_segment_id text, p_source_ref text, p_snooze_kind text DEFAULT 'DO_NOT_PAY'::text, p_snooze_until_date date DEFAULT NULL::date, p_actor_user_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text, p_segment_stable_key text DEFAULT NULL::text, p_resolved_rate_acknowledgement_token text DEFAULT NULL::text, p_pay_run_acknowledgement_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_date_context jsonb := '{}'::jsonb;
  v_today_uk date;
  v_next_official_pay_date date;
  v_validation_pre_open jsonb := '{}'::jsonb;
  v_validation_pre_save jsonb := '{}'::jsonb;
  v_post_lock_validation jsonb := '{}'::jsonb;
  v_required_scope_fingerprint text := NULL::text;
  v_scope_kind text := NULL::text;
  v_expense_code text := NULL::text;
  v_expense_source_basis_fingerprint text := NULL::text;
  v_expense_source_prefix text := NULL::text;
  v_stale_expense_snoozes_before jsonb := '[]'::jsonb;
  v_stale_expense_snoozes_cancelled integer := 0;
  v_acknowledgement_row public.pay_snooze_warning_acknowledgements%ROWTYPE;
  v_segment_stable_key_hint text := NULLIF(BTRIM(COALESCE(p_segment_stable_key, '')), '');
  v_kind_input text := upper(btrim(coalesce(p_snooze_kind, 'DO_NOT_PAY')));
  v_kind text;
  v_segment_id_input text := nullif(btrim(coalesce(p_segment_id, '')), '');
  v_source_ref text := lower(nullif(btrim(coalesce(p_source_ref, '')), ''));
  v_note text := nullif(btrim(coalesce(p_note, '')), '');

  v_input_booking_id text := NULL;
  v_booking_id text := NULL;
  v_current_timesheet_id uuid := NULL;
  v_effective_timesheet_id uuid := NULL;

  v_input_invoice_breakdown_json jsonb := NULL;
  v_current_invoice_breakdown_json jsonb := NULL;

  v_input_segment_stable_key text := NULL;
  v_segment_stable_key text := NULL;
  v_current_segment_id text := NULL;
  v_effective_segment_id text := NULL;

  v_keeper_id uuid := NULL;
  v_action text := NULL;

  v_before jsonb := NULL;
  v_after jsonb := NULL;

  v_finance_case_id uuid := NULL;
  v_event_type text := NULL;
  v_conflict_snooze_id uuid := NULL;

  v_finance_case_record public.pay_advances%rowtype;
  v_expected_finance_case_type public.pay_finance_case_type_enum;
  v_requested_week_start_date date := NULL;
  v_target_week_start date := NULL;
  v_next_due_week_start_before_snooze_date date := NULL;
  v_next_due_week_start_after_snooze_date date := NULL;

  v_schedule_rebase_result jsonb := NULL;
  v_schedule_before_snooze_json jsonb := NULL;
  v_next_due_week_start_before_snooze text := NULL;
  v_requested_week_start text := NULL;
  v_schedule_after_snooze_json jsonb := NULL;
  v_next_due_week_start_after_snooze text := NULL;
  v_installment_count integer := NULL;
BEGIN
  declare v_correction_chain jsonb;
  begin
    if p_timesheet_id is not null and coalesce((public._ctms_import_correction_classify_v1(p_timesheet_id)->>'is_import_authoritative_correction')::boolean,false) then
      v_correction_chain:=public.timesheet_correction_chain_scope_v1(p_timesheet_id,false,32,100);
      if coalesce((v_correction_chain->>'valid')::boolean,false) is not true then raise exception 'CORRECTION_CHAIN_INVALID_FOR_SNOOZE' using errcode='P0001',detail=v_correction_chain::text; end if;
      v_segment_stable_key_hint:='correction-chain:'||(v_correction_chain->>'root_timesheet_id');
      v_source_ref:=v_segment_stable_key_hint;
    end if;
  end;
  v_date_context := public.pay_banking_official_date_context_v1(NULL::timestamptz);
  v_today_uk := (v_date_context->>'business_date')::date;
  v_next_official_pay_date := (v_date_context->>'next_official_pay_date')::date;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'candidate_id is required';
  END IF;

  v_kind := CASE v_kind_input
    WHEN 'BLOCKED' THEN 'BLOCKED_TIMESHEET'
    WHEN 'BLOCKED_TIMESHEET' THEN 'BLOCKED_TIMESHEET'
    WHEN 'DO_NOT_PAY' THEN 'DO_NOT_PAY'
    WHEN 'TIMESHEET_PAYMENT' THEN 'TIMESHEET_PAYMENT'
    WHEN 'OVERPAYMENT_RECOVERY' THEN 'OVERPAYMENT_RECOVERY'
    WHEN 'PAYMENT_ADVANCE_REPAYMENT' THEN 'PAYMENT_ADVANCE_REPAYMENT'
    WHEN 'LOAN_REPAYMENT' THEN 'PAYMENT_ADVANCE_REPAYMENT'
    WHEN 'MANUAL_DEBT_RECOVERY' THEN 'MANUAL_DEBT_RECOVERY'
    ELSE NULL
  END;

  IF v_kind IS NULL THEN
    RAISE EXCEPTION 'invalid snooze_kind';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'SNOOZE_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'SNOOZE_ACTOR_REQUIRED')::text;
  END IF;

  v_validation_pre_open := public.pay_snooze_validate_request_v1(
    p_actor_user_id => p_actor_user_id,
    p_candidate_id => p_candidate_id,
    p_timesheet_id => p_timesheet_id,
    p_segment_id => p_segment_id,
    p_segment_stable_key => v_segment_stable_key_hint,
    p_source_ref => v_source_ref,
    p_snooze_kind => v_kind,
    p_snooze_until_date => p_snooze_until_date,
    p_validation_phase => 'INTERNAL_PRE_OPEN'
  );

  IF COALESCE((v_validation_pre_open->>'warning_required')::boolean, false) THEN
    v_required_scope_fingerprint := NULLIF(BTRIM(COALESCE(v_validation_pre_open->>'scope_fingerprint', '')), '');
    IF NULLIF(BTRIM(COALESCE(p_resolved_rate_acknowledgement_token, '')), '') IS NULL
       OR NULLIF(BTRIM(COALESCE(p_resolved_rate_acknowledgement_token, '')), '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'SNOOZE_CONFIRMATION_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = (v_validation_pre_open || jsonb_build_object(
                'code', 'SNOOZE_CONFIRMATION_REQUIRED',
                'confirmation_type', 'RESOLVED_RATE',
                'refresh_required', false
              ))::text;
    END IF;

    SELECT ack_row.*
    INTO v_acknowledgement_row
    FROM public.pay_snooze_warning_acknowledgements AS ack_row
    WHERE ack_row.token_hash = md5(BTRIM(p_resolved_rate_acknowledgement_token))
      AND ack_row.actor_user_id = p_actor_user_id
      AND ack_row.validation_phase = 'PRE_OPEN'
      AND ack_row.candidate_id = p_candidate_id
      AND ack_row.source_ref IS NOT DISTINCT FROM v_source_ref
      AND ack_row.warning_code = 'RATE_RESOLUTION_REQUIRES_REVIEW_AFTER_UNSNOOZE'
      AND ack_row.scope_fingerprint = v_required_scope_fingerprint
      AND ack_row.expires_at_utc > clock_timestamp()
      AND ack_row.last_used_at_utc IS NULL
    FOR UPDATE;

    IF v_acknowledgement_row.id IS NULL THEN
      RAISE EXCEPTION 'SNOOZE_CONFIRMATION_STALE'
        USING ERRCODE = 'P0001',
              DETAIL = (v_validation_pre_open || jsonb_build_object(
                'code', 'SNOOZE_CONFIRMATION_STALE',
                'confirmation_type', 'RESOLVED_RATE',
                'refresh_required', true
              ))::text;
    END IF;

    UPDATE public.pay_snooze_warning_acknowledgements AS ack_update
    SET last_used_at_utc = clock_timestamp()
    WHERE ack_update.id = v_acknowledgement_row.id
      AND ack_update.last_used_at_utc IS NULL;
  END IF;

  v_acknowledgement_row := NULL;
  v_validation_pre_save := public.pay_snooze_validate_request_v1(
    p_actor_user_id => p_actor_user_id,
    p_candidate_id => p_candidate_id,
    p_timesheet_id => p_timesheet_id,
    p_segment_id => p_segment_id,
    p_segment_stable_key => v_segment_stable_key_hint,
    p_source_ref => v_source_ref,
    p_snooze_kind => v_kind,
    p_snooze_until_date => p_snooze_until_date,
    p_validation_phase => 'INTERNAL_PRE_SAVE'
  );

  v_scope_kind := UPPER(NULLIF(BTRIM(COALESCE(v_validation_pre_save->>'scope_kind', '')), ''));
  v_expense_code := UPPER(NULLIF(BTRIM(COALESCE(v_validation_pre_save->>'expense_code', '')), ''));
  v_expense_source_basis_fingerprint := LOWER(NULLIF(BTRIM(COALESCE(v_validation_pre_save->>'expense_source_basis_fingerprint', '')), ''));

  IF COALESCE((v_validation_pre_save->>'warning_required')::boolean, false) THEN
    v_required_scope_fingerprint := NULLIF(BTRIM(COALESCE(v_validation_pre_save->>'scope_fingerprint', '')), '');
    IF NULLIF(BTRIM(COALESCE(p_pay_run_acknowledgement_token, '')), '') IS NULL
       OR NULLIF(BTRIM(COALESCE(p_pay_run_acknowledgement_token, '')), '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'SNOOZE_CONFIRMATION_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = (v_validation_pre_save || jsonb_build_object(
                'code', 'SNOOZE_CONFIRMATION_REQUIRED',
                'confirmation_type', 'PAY_RUN_DATE',
                'refresh_required', false
              ))::text;
    END IF;

    SELECT ack_row.*
    INTO v_acknowledgement_row
    FROM public.pay_snooze_warning_acknowledgements AS ack_row
    WHERE ack_row.token_hash = md5(BTRIM(p_pay_run_acknowledgement_token))
      AND ack_row.actor_user_id = p_actor_user_id
      AND ack_row.validation_phase = 'PRE_SAVE'
      AND ack_row.candidate_id = p_candidate_id
      AND ack_row.source_ref IS NOT DISTINCT FROM v_source_ref
      AND ack_row.warning_code = NULLIF(BTRIM(COALESCE(v_validation_pre_save->>'warning_code', '')), '')
      AND ack_row.scope_fingerprint = v_required_scope_fingerprint
      AND ack_row.expires_at_utc > clock_timestamp()
      AND ack_row.last_used_at_utc IS NULL
    FOR UPDATE;

    IF v_acknowledgement_row.id IS NULL THEN
      RAISE EXCEPTION 'SNOOZE_CONFIRMATION_STALE'
        USING ERRCODE = 'P0001',
              DETAIL = (v_validation_pre_save || jsonb_build_object(
                'code', 'SNOOZE_CONFIRMATION_STALE',
                'confirmation_type', 'PAY_RUN_DATE',
                'refresh_required', true
              ))::text;
    END IF;

    UPDATE public.pay_snooze_warning_acknowledgements AS ack_update
    SET last_used_at_utc = clock_timestamp()
    WHERE ack_update.id = v_acknowledgement_row.id
      AND ack_update.last_used_at_utc IS NULL;
  END IF;

  IF p_snooze_until_date IS NOT NULL AND p_snooze_until_date < v_today_uk THEN
    RAISE EXCEPTION 'snooze_until_date must be today or later in Europe/London (or NULL for indefinite)'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'SNOOZE_DATE_IN_PAST',
              'london_current_date', v_today_uk::text,
              'snooze_until_date', p_snooze_until_date::text
            )::text;
  END IF;

  -- Candidate-scoped mutation lock.  The draft guard uses the same lock so a
  -- snooze and a stale Create Draft request cannot pass one another.
  PERFORM pg_advisory_xact_lock(
    pg_catalog.hashtext('public.banking_pay_candidate_snooze_guard'),
    pg_catalog.hashtext(p_candidate_id::text)
  );

  v_post_lock_validation := public.pay_snooze_validate_request_v1(
    p_actor_user_id => p_actor_user_id,
    p_candidate_id => p_candidate_id,
    p_timesheet_id => p_timesheet_id,
    p_segment_id => p_segment_id,
    p_segment_stable_key => v_segment_stable_key_hint,
    p_source_ref => v_source_ref,
    p_snooze_kind => v_kind,
    p_snooze_until_date => p_snooze_until_date,
    p_validation_phase => 'INTERNAL_PRE_SAVE'
  );

  IF NULLIF(BTRIM(COALESCE(v_post_lock_validation->>'scope_fingerprint', '')), '')
       IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_validation_pre_save->>'scope_fingerprint', '')), '')
     OR UPPER(NULLIF(BTRIM(COALESCE(v_post_lock_validation->>'scope_kind', '')), ''))
       IS DISTINCT FROM v_scope_kind
     OR LOWER(NULLIF(BTRIM(COALESCE(v_post_lock_validation->>'source_ref', '')), ''))
       IS DISTINCT FROM v_source_ref THEN
    RAISE EXCEPTION 'SNOOZE_AUTHORITY_CHANGED_DURING_SAVE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'SNOOZE_AUTHORITY_CHANGED_DURING_SAVE',
              'candidate_id', p_candidate_id::text,
              'timesheet_id', CASE WHEN p_timesheet_id IS NULL THEN NULL ELSE p_timesheet_id::text END,
              'source_ref', v_source_ref,
              'refresh_required', true
            )::text;
  END IF;

  v_scope_kind := UPPER(NULLIF(BTRIM(COALESCE(v_post_lock_validation->>'scope_kind', '')), ''));
  v_expense_code := UPPER(NULLIF(BTRIM(COALESCE(v_post_lock_validation->>'expense_code', '')), ''));
  v_expense_source_basis_fingerprint := LOWER(NULLIF(BTRIM(COALESCE(v_post_lock_validation->>'expense_source_basis_fingerprint', '')), ''));

  IF v_scope_kind = 'TIMESHEET_EXPENSE' THEN
    IF v_kind <> 'DO_NOT_PAY'
       OR v_source_ref IS NULL
       OR p_timesheet_id IS NULL
       OR v_segment_id_input IS NOT NULL
       OR v_segment_stable_key_hint IS NOT NULL THEN
      RAISE EXCEPTION 'SNOOZE_EXPENSE_SCOPE_IDENTITY_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'SNOOZE_EXPENSE_SCOPE_IDENTITY_INVALID',
                'source_ref', v_source_ref,
                'snooze_kind', v_kind
              )::text;
    END IF;
  ELSIF v_kind IN ('OVERPAYMENT_RECOVERY','PAYMENT_ADVANCE_REPAYMENT','MANUAL_DEBT_RECOVERY') THEN
    IF v_source_ref IS NULL THEN
      RAISE EXCEPTION 'source_ref is required for finance-case snoozes';
    END IF;
    IF p_timesheet_id IS NOT NULL OR v_segment_id_input IS NOT NULL THEN
      RAISE EXCEPTION 'timesheet_id/segment_id must not be supplied for finance-case snoozes';
    END IF;
  ELSIF v_kind = 'TIMESHEET_PAYMENT' THEN
    IF p_timesheet_id IS NULL THEN
      RAISE EXCEPTION 'timesheet_id is required for TIMESHEET_PAYMENT snoozes';
    END IF;
    IF v_segment_id_input IS NOT NULL THEN
      RAISE EXCEPTION 'segment_id must be null for TIMESHEET_PAYMENT snoozes';
    END IF;
    IF v_source_ref IS NOT NULL THEN
      RAISE EXCEPTION 'source_ref must be null for TIMESHEET_PAYMENT snoozes';
    END IF;
  ELSE
    IF p_timesheet_id IS NULL THEN
      RAISE EXCEPTION 'timesheet_id is required for timesheet-line snoozes';
    END IF;
    IF v_source_ref IS NOT NULL THEN
      RAISE EXCEPTION 'source_ref must be null for timesheet-line snoozes';
    END IF;
  END IF;

  IF v_source_ref IS NOT NULL
     AND v_source_ref LIKE 'advance:%'
     AND split_part(v_source_ref, ':', 2) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  THEN
    v_finance_case_id := split_part(v_source_ref, ':', 2)::uuid;
  END IF;

  IF v_kind IN ('OVERPAYMENT_RECOVERY', 'PAYMENT_ADVANCE_REPAYMENT', 'MANUAL_DEBT_RECOVERY') THEN
    v_expected_finance_case_type := CASE v_kind
      WHEN 'OVERPAYMENT_RECOVERY' THEN 'OVERPAYMENT'::public.pay_finance_case_type_enum
      WHEN 'PAYMENT_ADVANCE_REPAYMENT' THEN 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum
      WHEN 'MANUAL_DEBT_RECOVERY' THEN 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum
      ELSE NULL::public.pay_finance_case_type_enum
    END;

    IF v_finance_case_id IS NULL THEN
      RAISE EXCEPTION 'SNOOZE_FINANCE_SOURCE_REF_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'SNOOZE_FINANCE_SOURCE_REF_INVALID',
                'source_ref', v_source_ref
              )::text;
    END IF;

    SELECT finance_case.*
    INTO v_finance_case_record
    FROM public.pay_advances AS finance_case
    WHERE finance_case.id = v_finance_case_id
    FOR UPDATE;

    IF v_finance_case_record.id IS NULL THEN
      RAISE EXCEPTION 'SNOOZE_FINANCE_CASE_AUTHORITY_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'SNOOZE_FINANCE_CASE_AUTHORITY_MISMATCH',
                'candidate_id', p_candidate_id::text,
                'source_ref', v_source_ref,
                'snooze_kind', v_kind,
                'reason', 'FINANCE_CASE_NOT_FOUND'
              )::text;
    END IF;

    IF v_finance_case_record.candidate_id IS DISTINCT FROM p_candidate_id
       OR v_finance_case_record.case_type IS DISTINCT FROM v_expected_finance_case_type THEN
      RAISE EXCEPTION 'SNOOZE_FINANCE_CASE_AUTHORITY_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'SNOOZE_FINANCE_CASE_AUTHORITY_MISMATCH',
                'candidate_id', p_candidate_id::text,
                'source_ref', v_source_ref,
                'snooze_kind', v_kind,
                'resolved_candidate_id', CASE WHEN v_finance_case_record.candidate_id IS NULL THEN NULL ELSE v_finance_case_record.candidate_id::text END,
                'resolved_case_type', v_finance_case_record.case_type::text,
                'expected_case_type', v_expected_finance_case_type::text
              )::text;
    END IF;
  END IF;

  IF v_scope_kind = 'TIMESHEET_EXPENSE' THEN
    IF COALESCE(v_post_lock_validation->>'timesheet_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'SNOOZE_EXPENSE_CURRENT_TIMESHEET_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'SNOOZE_EXPENSE_CURRENT_TIMESHEET_INVALID',
                'source_ref', v_source_ref,
                'refresh_required', true
              )::text;
    END IF;

    v_effective_timesheet_id := (v_post_lock_validation->>'timesheet_id')::uuid;
    v_current_timesheet_id := v_effective_timesheet_id;
    v_booking_id := NULLIF(BTRIM(COALESCE(v_post_lock_validation->>'booking_id', '')), '');
    v_input_booking_id := v_booking_id;
    v_effective_segment_id := NULL::text;
    v_segment_stable_key := NULL::text;
    v_expense_source_prefix := left(v_source_ref, length(v_source_ref) - 32);

    IF v_expense_code IS NULL
       OR v_expense_source_basis_fingerprint IS NULL
       OR v_expense_source_prefix IS NULL THEN
      RAISE EXCEPTION 'SNOOZE_EXPENSE_CANONICAL_IDENTITY_INCOMPLETE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'SNOOZE_EXPENSE_CANONICAL_IDENTITY_INCOMPLETE',
                'source_ref', v_source_ref,
                'refresh_required', true
              )::text;
    END IF;
  ELSIF v_source_ref IS NULL THEN
    SELECT
      nullif(btrim(coalesce(t.booking_id, '')), '')
    INTO v_input_booking_id
    FROM public.timesheets t
    WHERE t.timesheet_id = p_timesheet_id
    LIMIT 1;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'timesheet_id is invalid or no longer exists';
    END IF;

    v_booking_id := v_input_booking_id;

    IF v_booking_id IS NOT NULL THEN
      SELECT t.timesheet_id
      INTO v_current_timesheet_id
      FROM public.timesheets t
      WHERE t.booking_id = v_booking_id
        AND t.is_current = true
      ORDER BY coalesce(t.version, 0) DESC, t.updated_at DESC NULLS LAST, t.created_at DESC NULLS LAST, t.timesheet_id DESC
      LIMIT 1;
    END IF;

    v_effective_timesheet_id := coalesce(v_current_timesheet_id, p_timesheet_id);

    SELECT tf.invoice_breakdown_json
    INTO v_input_invoice_breakdown_json
    FROM public.timesheets_financials tf
    WHERE tf.timesheet_id = p_timesheet_id
    ORDER BY CASE WHEN tf.is_current THEN 0 ELSE 1 END, tf.updated_at DESC NULLS LAST, tf.created_at DESC NULLS LAST, tf.id DESC
    LIMIT 1;

    IF v_effective_timesheet_id IS NOT NULL THEN
      SELECT tf.invoice_breakdown_json
      INTO v_current_invoice_breakdown_json
      FROM public.timesheets_financials tf
      WHERE tf.timesheet_id = v_effective_timesheet_id
      ORDER BY CASE WHEN tf.is_current THEN 0 ELSE 1 END, tf.updated_at DESC NULLS LAST, tf.created_at DESC NULLS LAST, tf.id DESC
      LIMIT 1;
    END IF;

    IF v_segment_id_input IS NOT NULL THEN
      SELECT
        nullif(
          btrim(
            coalesce(
              nullif(btrim(coalesce(seg.value->>'segment_stable_key', '')), ''),
              nullif(btrim(coalesce(seg.value->>'work_date', '')), ''),
              nullif(btrim(coalesce(seg.value->>'ref_num', '')), ''),
              nullif(btrim(coalesce(seg.value->>'segment_key', '')), ''),
              nullif(btrim(coalesce(seg.value->>'segment_id', '')), '')
            )
          ),
          ''
        )
      INTO v_input_segment_stable_key
      FROM jsonb_array_elements(
        CASE
          WHEN v_input_invoice_breakdown_json IS NOT NULL
           AND jsonb_typeof(v_input_invoice_breakdown_json) = 'object'
           AND jsonb_typeof(v_input_invoice_breakdown_json->'segments') = 'array'
          THEN v_input_invoice_breakdown_json->'segments'
          ELSE '[]'::jsonb
        END
      ) AS seg(value)
      WHERE jsonb_typeof(seg.value) = 'object'
        AND (
          nullif(btrim(coalesce(seg.value->>'segment_id', '')), '') = v_segment_id_input
          OR nullif(btrim(coalesce(seg.value->>'segment_stable_key', '')), '') = v_segment_id_input
          OR nullif(btrim(coalesce(seg.value->>'segment_key', '')), '') = v_segment_id_input
          OR nullif(btrim(coalesce(seg.value->>'ref_num', '')), '') = v_segment_id_input
          OR nullif(btrim(coalesce(seg.value->>'work_date', '')), '') = v_segment_id_input
        )
      ORDER BY
        CASE
          WHEN nullif(btrim(coalesce(seg.value->>'segment_id', '')), '') = v_segment_id_input THEN 1
          WHEN nullif(btrim(coalesce(seg.value->>'segment_stable_key', '')), '') = v_segment_id_input THEN 2
          WHEN nullif(btrim(coalesce(seg.value->>'segment_key', '')), '') = v_segment_id_input THEN 3
          WHEN nullif(btrim(coalesce(seg.value->>'ref_num', '')), '') = v_segment_id_input THEN 4
          WHEN nullif(btrim(coalesce(seg.value->>'work_date', '')), '') = v_segment_id_input THEN 5
          ELSE 99
        END
      LIMIT 1;

      SELECT
        nullif(btrim(coalesce(seg.value->>'segment_id', '')), ''),
        nullif(
          btrim(
            coalesce(
              nullif(btrim(coalesce(seg.value->>'segment_stable_key', '')), ''),
              nullif(btrim(coalesce(seg.value->>'work_date', '')), ''),
              nullif(btrim(coalesce(seg.value->>'ref_num', '')), ''),
              nullif(btrim(coalesce(seg.value->>'segment_key', '')), ''),
              nullif(btrim(coalesce(seg.value->>'segment_id', '')), '')
            )
          ),
          ''
        )
      INTO v_current_segment_id, v_segment_stable_key
      FROM jsonb_array_elements(
        CASE
          WHEN v_current_invoice_breakdown_json IS NOT NULL
           AND jsonb_typeof(v_current_invoice_breakdown_json) = 'object'
           AND jsonb_typeof(v_current_invoice_breakdown_json->'segments') = 'array'
          THEN v_current_invoice_breakdown_json->'segments'
          ELSE '[]'::jsonb
        END
      ) AS seg(value)
      WHERE jsonb_typeof(seg.value) = 'object'
        AND (
          (
            v_input_segment_stable_key IS NOT NULL
            AND nullif(
                  btrim(
                    coalesce(
                      nullif(btrim(coalesce(seg.value->>'segment_stable_key', '')), ''),
                      nullif(btrim(coalesce(seg.value->>'work_date', '')), ''),
                      nullif(btrim(coalesce(seg.value->>'ref_num', '')), ''),
                      nullif(btrim(coalesce(seg.value->>'segment_key', '')), ''),
                      nullif(btrim(coalesce(seg.value->>'segment_id', '')), '')
                    )
                  ),
                  ''
                ) = v_input_segment_stable_key
          )
          OR nullif(btrim(coalesce(seg.value->>'segment_id', '')), '') = v_segment_id_input
          OR nullif(btrim(coalesce(seg.value->>'segment_stable_key', '')), '') = v_segment_id_input
          OR nullif(btrim(coalesce(seg.value->>'segment_key', '')), '') = v_segment_id_input
          OR nullif(btrim(coalesce(seg.value->>'ref_num', '')), '') = v_segment_id_input
          OR nullif(btrim(coalesce(seg.value->>'work_date', '')), '') = v_segment_id_input
        )
      ORDER BY
        CASE
          WHEN v_input_segment_stable_key IS NOT NULL
           AND nullif(
                 btrim(
                   coalesce(
                     nullif(btrim(coalesce(seg.value->>'segment_stable_key', '')), ''),
                     nullif(btrim(coalesce(seg.value->>'work_date', '')), ''),
                     nullif(btrim(coalesce(seg.value->>'ref_num', '')), ''),
                     nullif(btrim(coalesce(seg.value->>'segment_key', '')), ''),
                     nullif(btrim(coalesce(seg.value->>'segment_id', '')), '')
                   )
                 ),
                 ''
               ) = v_input_segment_stable_key THEN 1
          WHEN nullif(btrim(coalesce(seg.value->>'segment_id', '')), '') = v_segment_id_input THEN 2
          WHEN nullif(btrim(coalesce(seg.value->>'segment_stable_key', '')), '') = v_segment_id_input THEN 3
          WHEN nullif(btrim(coalesce(seg.value->>'segment_key', '')), '') = v_segment_id_input THEN 4
          WHEN nullif(btrim(coalesce(seg.value->>'ref_num', '')), '') = v_segment_id_input THEN 5
          WHEN nullif(btrim(coalesce(seg.value->>'work_date', '')), '') = v_segment_id_input THEN 6
          ELSE 99
        END
      LIMIT 1;

      v_segment_stable_key := coalesce(v_segment_stable_key, v_input_segment_stable_key);
      v_effective_segment_id := v_current_segment_id;

      IF v_segment_stable_key IS NULL THEN
        RAISE EXCEPTION 'segment_id could not be resolved on the timesheet';
      END IF;
    ELSE
      v_segment_stable_key := NULL;
      v_effective_segment_id := NULL;
    END IF;
  END IF;

  IF v_scope_kind = 'TIMESHEET_EXPENSE' THEN
    SELECT COALESCE(
             jsonb_agg(
               jsonb_build_object(
                 'id', stale_snooze.id::text,
                 'source_ref', stale_snooze.source_ref,
                 'snooze_until_date', CASE WHEN stale_snooze.snooze_until_date IS NULL THEN NULL ELSE stale_snooze.snooze_until_date::text END,
                 'note', stale_snooze.note
               )
               ORDER BY stale_snooze.created_at_utc, stale_snooze.id
             ),
             '[]'::jsonb
           )
    INTO v_stale_expense_snoozes_before
    FROM public.pay_item_snoozes AS stale_snooze
    WHERE stale_snooze.candidate_id = p_candidate_id
      AND stale_snooze.timesheet_id = v_effective_timesheet_id
      AND stale_snooze.source_ref LIKE v_expense_source_prefix || '%'
      AND stale_snooze.source_ref IS DISTINCT FROM v_source_ref
      AND stale_snooze.cleared_at_utc IS NULL
      AND stale_snooze.cancelled_at_utc IS NULL
      AND UPPER(BTRIM(COALESCE(stale_snooze.snooze_kind, ''))) = 'DO_NOT_PAY';

    UPDATE public.pay_item_snoozes AS stale_snooze
    SET cancelled_at_utc = now(),
        cancelled_by_user_id = p_actor_user_id,
        cancel_reason = 'SUPERSEDED_BY_CURRENT_EXPENSE_SOURCE',
        updated_at_utc = now(),
        updated_by_user_id = p_actor_user_id
    WHERE stale_snooze.candidate_id = p_candidate_id
      AND stale_snooze.timesheet_id = v_effective_timesheet_id
      AND stale_snooze.source_ref LIKE v_expense_source_prefix || '%'
      AND stale_snooze.source_ref IS DISTINCT FROM v_source_ref
      AND stale_snooze.cleared_at_utc IS NULL
      AND stale_snooze.cancelled_at_utc IS NULL
      AND UPPER(BTRIM(COALESCE(stale_snooze.snooze_kind, ''))) = 'DO_NOT_PAY';

    GET DIAGNOSTICS v_stale_expense_snoozes_cancelled = ROW_COUNT;

    IF COALESCE(v_stale_expense_snoozes_cancelled, 0) > 0 THEN
      PERFORM public._audit_insert(
        'timesheets',
        v_effective_timesheet_id::text,
        'SNOOZE_STALE_EXPENSE_IDENTITIES_CANCELLED',
        v_stale_expense_snoozes_before,
        jsonb_build_object(
          'current_source_ref', v_source_ref,
          'expense_code', v_expense_code,
          'cancelled_count', v_stale_expense_snoozes_cancelled,
          'cancel_reason', 'SUPERSEDED_BY_CURRENT_EXPENSE_SOURCE'
        ),
        'SUPERSEDED_BY_CURRENT_EXPENSE_SOURCE',
        p_actor_user_id
      );
    END IF;
  END IF;

  IF v_source_ref IS NULL THEN
    IF v_kind = 'TIMESHEET_PAYMENT' THEN
      SELECT s.id
      INTO v_conflict_snooze_id
      FROM public.pay_item_snoozes s
      WHERE s.candidate_id = p_candidate_id
        AND s.source_ref IS NULL
        AND s.cleared_at_utc IS NULL
    AND s.cancelled_at_utc IS NULL
        AND upper(coalesce(s.snooze_kind, '')) IN ('DO_NOT_PAY', 'BLOCKED_TIMESHEET')
        AND coalesce(
              nullif(btrim(coalesce(s.segment_stable_key, '')), ''),
              nullif(btrim(coalesce(s.segment_id, '')), '')
            ) IS NOT NULL
        AND (
          (
            v_booking_id IS NOT NULL
            AND (
              s.booking_id IS NOT DISTINCT FROM v_booking_id
              OR (
                s.booking_id IS NULL
                AND (
                  s.timesheet_id IS NOT DISTINCT FROM p_timesheet_id
                  OR s.timesheet_id IS NOT DISTINCT FROM v_effective_timesheet_id
                )
              )
            )
          )
          OR
          (
            v_booking_id IS NULL
            AND (
              s.timesheet_id IS NOT DISTINCT FROM p_timesheet_id
              OR s.timesheet_id IS NOT DISTINCT FROM v_effective_timesheet_id
            )
          )
        )
      ORDER BY s.updated_at_utc DESC NULLS LAST, s.created_at_utc DESC, s.id DESC
      LIMIT 1;

      IF v_conflict_snooze_id IS NOT NULL THEN
        RAISE EXCEPTION '%', 'SEGMENT_SNOOZES_ALREADY_EXIST'
          USING DETAIL = jsonb_build_object(
            'error_code', 'SEGMENT_SNOOZES_ALREADY_EXIST',
            'candidate_id', p_candidate_id::text,
            'timesheet_id', coalesce(v_effective_timesheet_id, p_timesheet_id)::text,
            'booking_id', v_booking_id,
            'conflict_snooze_id', v_conflict_snooze_id::text
          )::text;
      END IF;
    ELSIF coalesce(v_effective_segment_id, v_segment_stable_key, v_segment_id_input) IS NOT NULL THEN
      SELECT s.id
      INTO v_conflict_snooze_id
      FROM public.pay_item_snoozes s
      WHERE s.candidate_id = p_candidate_id
        AND s.source_ref IS NULL
        AND s.cleared_at_utc IS NULL
    AND s.cancelled_at_utc IS NULL
        AND upper(coalesce(s.snooze_kind, '')) = 'TIMESHEET_PAYMENT'
        AND s.segment_id IS NULL
        AND s.segment_stable_key IS NULL
        AND (
          (
            v_booking_id IS NOT NULL
            AND (
              s.booking_id IS NOT DISTINCT FROM v_booking_id
              OR (
                s.booking_id IS NULL
                AND (
                  s.timesheet_id IS NOT DISTINCT FROM p_timesheet_id
                  OR s.timesheet_id IS NOT DISTINCT FROM v_effective_timesheet_id
                )
              )
            )
          )
          OR
          (
            v_booking_id IS NULL
            AND (
              s.timesheet_id IS NOT DISTINCT FROM p_timesheet_id
              OR s.timesheet_id IS NOT DISTINCT FROM v_effective_timesheet_id
            )
          )
        )
      ORDER BY s.updated_at_utc DESC NULLS LAST, s.created_at_utc DESC, s.id DESC
      LIMIT 1;

      IF v_conflict_snooze_id IS NOT NULL THEN
        RAISE EXCEPTION '%', 'WHOLE_TIMESHEET_ALREADY_SNOOZED'
          USING DETAIL = jsonb_build_object(
            'error_code', 'WHOLE_TIMESHEET_ALREADY_SNOOZED',
            'candidate_id', p_candidate_id::text,
            'timesheet_id', coalesce(v_effective_timesheet_id, p_timesheet_id)::text,
            'booking_id', v_booking_id,
            'segment_id', coalesce(v_effective_segment_id, v_segment_id_input),
            'segment_stable_key', v_segment_stable_key,
            'conflict_snooze_id', v_conflict_snooze_id::text
          )::text;
      END IF;
    END IF;
  END IF;

  SELECT jsonb_build_object(
           'id', s.id::text,
           'candidate_id', s.candidate_id::text,
           'timesheet_id', CASE WHEN s.timesheet_id IS NULL THEN NULL ELSE s.timesheet_id::text END,
           'booking_id', s.booking_id,
           'segment_id', s.segment_id,
           'segment_stable_key', s.segment_stable_key,
           'source_ref', s.source_ref,
           'snooze_kind', s.snooze_kind,
           'snooze_until_date', CASE WHEN s.snooze_until_date IS NULL THEN NULL ELSE s.snooze_until_date::text END,
           'note', s.note
         )
  INTO v_before
  FROM public.pay_item_snoozes s
  WHERE s.candidate_id = p_candidate_id
    AND s.cleared_at_utc IS NULL
    AND s.cancelled_at_utc IS NULL
    AND (
      (v_source_ref IS NOT NULL AND s.source_ref IS NOT DISTINCT FROM v_source_ref)
      OR
      (
        v_source_ref IS NULL
        AND s.source_ref IS NULL
        AND (
          (
            v_booking_id IS NOT NULL
            AND s.booking_id IS NOT DISTINCT FROM v_booking_id
            AND coalesce(s.segment_stable_key, '') IS NOT DISTINCT FROM coalesce(v_segment_stable_key, '')
          )
          OR
          (
            s.booking_id IS NULL
            AND (
              s.timesheet_id IS NOT DISTINCT FROM p_timesheet_id
              OR s.timesheet_id IS NOT DISTINCT FROM v_effective_timesheet_id
            )
            AND s.segment_id IS NOT DISTINCT FROM coalesce(v_effective_segment_id, v_segment_id_input)
          )
        )
      )
    )
  ORDER BY s.updated_at_utc DESC NULLS LAST, s.created_at_utc DESC, s.id DESC
  LIMIT 1;

  SELECT s.id
  INTO v_keeper_id
  FROM public.pay_item_snoozes s
  WHERE s.candidate_id = p_candidate_id
    AND s.cleared_at_utc IS NULL
    AND s.cancelled_at_utc IS NULL
    AND (
      (v_source_ref IS NOT NULL AND s.source_ref IS NOT DISTINCT FROM v_source_ref)
      OR
      (
        v_source_ref IS NULL
        AND s.source_ref IS NULL
        AND (
          (
            v_booking_id IS NOT NULL
            AND s.booking_id IS NOT DISTINCT FROM v_booking_id
            AND coalesce(s.segment_stable_key, '') IS NOT DISTINCT FROM coalesce(v_segment_stable_key, '')
          )
          OR
          (
            s.booking_id IS NULL
            AND (
              s.timesheet_id IS NOT DISTINCT FROM p_timesheet_id
              OR s.timesheet_id IS NOT DISTINCT FROM v_effective_timesheet_id
            )
            AND s.segment_id IS NOT DISTINCT FROM coalesce(v_effective_segment_id, v_segment_id_input)
          )
        )
      )
    )
  ORDER BY s.updated_at_utc DESC NULLS LAST, s.created_at_utc DESC, s.id DESC
  LIMIT 1;

  IF v_scope_kind = 'TIMESHEET_EXPENSE' AND v_keeper_id IS NULL THEN
    SELECT s.id,
           jsonb_build_object(
             'id', s.id::text,
             'candidate_id', s.candidate_id::text,
             'timesheet_id', CASE WHEN s.timesheet_id IS NULL THEN NULL ELSE s.timesheet_id::text END,
             'booking_id', s.booking_id,
             'segment_id', s.segment_id,
             'segment_stable_key', s.segment_stable_key,
             'source_ref', s.source_ref,
             'snooze_kind', s.snooze_kind,
             'snooze_until_date', CASE WHEN s.snooze_until_date IS NULL THEN NULL ELSE s.snooze_until_date::text END,
             'note', s.note,
             'cancelled_at_utc', CASE WHEN s.cancelled_at_utc IS NULL THEN NULL ELSE s.cancelled_at_utc::text END,
             'cancel_reason', s.cancel_reason
           )
    INTO v_keeper_id,
         v_before
    FROM public.pay_item_snoozes AS s
    WHERE s.candidate_id = p_candidate_id
      AND s.timesheet_id = v_effective_timesheet_id
      AND s.source_ref IS NOT DISTINCT FROM v_source_ref
      AND UPPER(BTRIM(COALESCE(s.snooze_kind, ''))) = 'DO_NOT_PAY'
      AND s.cleared_at_utc IS NULL
      AND s.cancelled_at_utc IS NOT NULL
    ORDER BY s.cancelled_at_utc DESC NULLS LAST,
             s.updated_at_utc DESC NULLS LAST,
             s.id DESC
    LIMIT 1
    FOR UPDATE;
  END IF;

  IF v_source_ref IS NULL AND v_segment_id_input IS NOT NULL AND v_effective_segment_id IS NULL THEN
    IF v_keeper_id IS NOT NULL THEN
      UPDATE public.pay_item_snoozes s
      SET
        cleared_at_utc = now(),
        cleared_by_user_id = p_actor_user_id,
        updated_at_utc = now(),
        updated_by_user_id = p_actor_user_id
      WHERE s.id = v_keeper_id;

      SELECT jsonb_build_object(
               'id', s.id::text,
               'candidate_id', s.candidate_id::text,
               'timesheet_id', CASE WHEN s.timesheet_id IS NULL THEN NULL ELSE s.timesheet_id::text END,
               'booking_id', s.booking_id,
               'segment_id', s.segment_id,
               'segment_stable_key', s.segment_stable_key,
               'source_ref', s.source_ref,
               'snooze_kind', s.snooze_kind,
               'snooze_until_date', CASE WHEN s.snooze_until_date IS NULL THEN NULL ELSE s.snooze_until_date::text END,
               'note', s.note,
               'cleared_at_utc', CASE WHEN s.cleared_at_utc IS NULL THEN NULL ELSE s.cleared_at_utc::text END
             )
      INTO v_after
      FROM public.pay_item_snoozes s
      WHERE s.id = v_keeper_id;

      PERFORM public._audit_insert(
        'timesheets',
        coalesce(v_effective_timesheet_id, p_timesheet_id)::text,
        'SNOOZE_CLEARED',
        v_before,
        v_after,
        'SEGMENT_NO_LONGER_MATCHED',
        p_actor_user_id
      );

      RETURN jsonb_build_object(
        'ok', true,
        'london_current_date', v_today_uk::text,
        'active_through_end_date', true,
        'action', 'CLEARED_ORPHANED',
        'id', v_keeper_id::text,
        'candidate_id', p_candidate_id::text,
        'timesheet_id', CASE WHEN v_effective_timesheet_id IS NULL THEN NULL ELSE v_effective_timesheet_id::text END,
        'booking_id', v_booking_id,
        'segment_id', NULL,
        'segment_stable_key', v_segment_stable_key,
        'source_ref', NULL,
        'snooze_kind', v_kind,
        'snooze_until_date', NULL,
        'snooze_is_indefinite', NULL,
        'note', v_note,
        'preview_visibility_hint', 'RELOAD_PREVIEW'
      );
    END IF;

    RAISE EXCEPTION 'segment_id could not be matched on the current timesheet';
  END IF;

  UPDATE public.pay_item_snoozes s
  SET
    cleared_at_utc = now(),
    cleared_by_user_id = p_actor_user_id,
    updated_at_utc = now(),
    updated_by_user_id = p_actor_user_id
  WHERE s.candidate_id = p_candidate_id
    AND s.cleared_at_utc IS NULL
    AND s.cancelled_at_utc IS NULL
    AND s.id <> v_keeper_id
    AND (
      (v_source_ref IS NOT NULL AND s.source_ref IS NOT DISTINCT FROM v_source_ref)
      OR
      (
        v_source_ref IS NULL
        AND s.source_ref IS NULL
        AND (
          (
            v_booking_id IS NOT NULL
            AND s.booking_id IS NOT DISTINCT FROM v_booking_id
            AND coalesce(s.segment_stable_key, '') IS NOT DISTINCT FROM coalesce(v_segment_stable_key, '')
          )
          OR
          (
            s.booking_id IS NULL
            AND (
              s.timesheet_id IS NOT DISTINCT FROM p_timesheet_id
              OR s.timesheet_id IS NOT DISTINCT FROM v_effective_timesheet_id
            )
            AND s.segment_id IS NOT DISTINCT FROM coalesce(v_effective_segment_id, v_segment_id_input)
          )
        )
      )
    );

  IF v_keeper_id IS NOT NULL THEN
    UPDATE public.pay_item_snoozes s
    SET
      timesheet_id = CASE WHEN v_source_ref IS NULL OR v_scope_kind = 'TIMESHEET_EXPENSE' THEN v_effective_timesheet_id ELSE NULL END,
      booking_id = CASE WHEN v_source_ref IS NULL OR v_scope_kind = 'TIMESHEET_EXPENSE' THEN v_booking_id ELSE NULL END,
      segment_id = CASE WHEN v_source_ref IS NULL THEN v_effective_segment_id ELSE NULL END,
      segment_stable_key = CASE WHEN v_source_ref IS NULL THEN v_segment_stable_key ELSE NULL END,
      snooze_kind = v_kind,
      snooze_until_date = p_snooze_until_date,
      note = v_note,
      cancelled_at_utc = CASE WHEN v_scope_kind = 'TIMESHEET_EXPENSE' THEN NULL ELSE s.cancelled_at_utc END,
      cancelled_by_user_id = CASE WHEN v_scope_kind = 'TIMESHEET_EXPENSE' THEN NULL ELSE s.cancelled_by_user_id END,
      cancel_reason = CASE WHEN v_scope_kind = 'TIMESHEET_EXPENSE' THEN NULL ELSE s.cancel_reason END,
      updated_at_utc = now(),
      updated_by_user_id = p_actor_user_id
    WHERE s.id = v_keeper_id;

    v_action := 'UPDATED';
  ELSE
    INSERT INTO public.pay_item_snoozes (
      candidate_id,
      timesheet_id,
      booking_id,
      segment_id,
      segment_stable_key,
      source_ref,
      snooze_kind,
      snooze_until_date,
      created_at_utc,
      created_by_user_id,
      note,
      cleared_at_utc,
      cleared_by_user_id,
      updated_at_utc,
      updated_by_user_id
    )
    VALUES (
      p_candidate_id,
      CASE WHEN v_source_ref IS NULL OR v_scope_kind = 'TIMESHEET_EXPENSE' THEN v_effective_timesheet_id ELSE NULL END,
      CASE WHEN v_source_ref IS NULL OR v_scope_kind = 'TIMESHEET_EXPENSE' THEN v_booking_id ELSE NULL END,
      CASE WHEN v_source_ref IS NULL THEN v_effective_segment_id ELSE NULL END,
      CASE WHEN v_source_ref IS NULL THEN v_segment_stable_key ELSE NULL END,
      v_source_ref,
      v_kind,
      p_snooze_until_date,
      now(),
      p_actor_user_id,
      v_note,
      NULL,
      NULL,
      now(),
      p_actor_user_id
    )
    RETURNING id INTO v_keeper_id;

    v_action := 'CREATED';
  END IF;

  IF v_finance_case_id IS NOT NULL
     AND v_kind IN ('OVERPAYMENT_RECOVERY', 'PAYMENT_ADVANCE_REPAYMENT', 'MANUAL_DEBT_RECOVERY')
     AND p_snooze_until_date IS NOT NULL
  THEN
    IF v_finance_case_record.case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum THEN
      v_schedule_before_snooze_json := coalesce(v_finance_case_record.schedule_json, '[]'::jsonb);
      v_next_due_week_start_before_snooze_date := v_finance_case_record.next_due_week_start;
      v_requested_week_start_date := public._pay_week_start_monday(p_snooze_until_date);

      IF v_next_due_week_start_before_snooze_date IS NULL THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_REPAYMENT_SCHEDULE_REBASE_FOR_SNOOZE',
          'code', 'NEXT_DUE_MISSING',
          'message', '_pay_repayment_schedule_rebase_for_snooze: next_due_week_start is required on the finance case'
        )::text;
      END IF;

      IF v_requested_week_start_date < v_next_due_week_start_before_snooze_date THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_REPAYMENT_SCHEDULE_REBASE_FOR_SNOOZE',
          'code', 'SNOOZE_DATE_BEFORE_NEXT_DUE',
          'message', '_pay_repayment_schedule_rebase_for_snooze: snooze_until_date cannot move the repayment schedule earlier than the current next due week',
          'finance_case_id', v_finance_case_id::text,
          'current_next_due_week_start', v_next_due_week_start_before_snooze_date::text,
          'requested_week_start', v_requested_week_start_date::text
        )::text;
      END IF;

      v_target_week_start := CASE
        WHEN v_requested_week_start_date = v_next_due_week_start_before_snooze_date THEN (v_next_due_week_start_before_snooze_date + 7)
        ELSE v_requested_week_start_date
      END;

      WITH schedule_rows AS (
        SELECT
          row_number() OVER (ORDER BY (elem.value ->> 'week_start')::date ASC, elem.ordinality ASC) AS seq_no,
          round(coalesce((elem.value ->> 'amount')::numeric, 0), 2) AS amount_value
        FROM jsonb_array_elements(v_schedule_before_snooze_json) WITH ORDINALITY AS elem(value, ordinality)
        WHERE coalesce((elem.value ->> 'amount')::numeric, 0) < 0
      )
      SELECT
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'week_start', (v_target_week_start + (((sr.seq_no - 1)::integer) * 7))::date,
              'amount', sr.amount_value
            )
            ORDER BY (v_target_week_start + (((sr.seq_no - 1)::integer) * 7))::date ASC
          ),
          '[]'::jsonb
        ),
        count(*)::integer
      INTO v_schedule_after_snooze_json, v_installment_count
      FROM schedule_rows AS sr;

      v_next_due_week_start_after_snooze_date := CASE
        WHEN v_installment_count > 0 THEN v_target_week_start
        ELSE NULL
      END;

      UPDATE public.pay_advances AS pa
      SET schedule_json = v_schedule_after_snooze_json,
          next_due_week_start = v_next_due_week_start_after_snooze_date,
          updated_at = now()
      WHERE pa.id = v_finance_case_id;

      v_schedule_rebase_result := jsonb_build_object(
        'ok', true,
        'finance_case_id', v_finance_case_id::text,
        'schedule_before_snooze_json', v_schedule_before_snooze_json,
        'next_due_week_start_before_snooze', CASE WHEN v_next_due_week_start_before_snooze_date IS NULL THEN NULL ELSE v_next_due_week_start_before_snooze_date::text END,
        'requested_week_start', CASE WHEN v_requested_week_start_date IS NULL THEN NULL ELSE v_requested_week_start_date::text END,
        'schedule_after_snooze_json', v_schedule_after_snooze_json,
        'next_due_week_start_after_snooze', CASE WHEN v_next_due_week_start_after_snooze_date IS NULL THEN NULL ELSE v_next_due_week_start_after_snooze_date::text END,
        'installment_count', v_installment_count
      );
    ELSE
      v_schedule_rebase_result := public._pay_repayment_schedule_rebase_for_snooze(
        v_finance_case_id,
        p_snooze_until_date
      );
    END IF;

    v_schedule_before_snooze_json := v_schedule_rebase_result -> 'schedule_before_snooze_json';
    v_next_due_week_start_before_snooze_date := CASE
      WHEN nullif(btrim(coalesce(v_schedule_rebase_result ->> 'next_due_week_start_before_snooze', '')), '') IS NULL THEN NULL
      ELSE (v_schedule_rebase_result ->> 'next_due_week_start_before_snooze')::date
    END;
    v_next_due_week_start_before_snooze := CASE
      WHEN v_next_due_week_start_before_snooze_date IS NULL THEN NULL
      ELSE v_next_due_week_start_before_snooze_date::text
    END;
    v_requested_week_start_date := CASE
      WHEN nullif(btrim(coalesce(v_schedule_rebase_result ->> 'requested_week_start', '')), '') IS NULL THEN NULL
      ELSE (v_schedule_rebase_result ->> 'requested_week_start')::date
    END;
    v_requested_week_start := CASE
      WHEN v_requested_week_start_date IS NULL THEN NULL
      ELSE v_requested_week_start_date::text
    END;
    v_schedule_after_snooze_json := v_schedule_rebase_result -> 'schedule_after_snooze_json';
    v_next_due_week_start_after_snooze_date := CASE
      WHEN nullif(btrim(coalesce(v_schedule_rebase_result ->> 'next_due_week_start_after_snooze', '')), '') IS NULL THEN NULL
      ELSE (v_schedule_rebase_result ->> 'next_due_week_start_after_snooze')::date
    END;
    v_next_due_week_start_after_snooze := CASE
      WHEN v_next_due_week_start_after_snooze_date IS NULL THEN NULL
      ELSE v_next_due_week_start_after_snooze_date::text
    END;
    v_installment_count := CASE
      WHEN nullif(btrim(coalesce(v_schedule_rebase_result ->> 'installment_count', '')), '') ~ '^-?[0-9]+$'
      THEN (v_schedule_rebase_result ->> 'installment_count')::integer
      ELSE NULL
    END;

    UPDATE public.pay_item_snoozes AS s
    SET schedule_before_snooze_json = v_schedule_before_snooze_json,
        next_due_week_start_before_snooze = v_next_due_week_start_before_snooze_date,
        schedule_after_snooze_json = v_schedule_after_snooze_json,
        next_due_week_start_after_snooze = v_next_due_week_start_after_snooze_date,
        updated_at_utc = now(),
        updated_by_user_id = p_actor_user_id
    WHERE s.id = v_keeper_id;
  END IF;

  SELECT
    jsonb_build_object(
      'id', s.id::text,
      'candidate_id', s.candidate_id::text,
      'timesheet_id', CASE WHEN s.timesheet_id IS NULL THEN NULL ELSE s.timesheet_id::text END,
      'booking_id', s.booking_id,
      'segment_id', s.segment_id,
      'segment_stable_key', s.segment_stable_key,
      'source_ref', s.source_ref,
      'snooze_kind', s.snooze_kind,
      'snooze_until_date', CASE WHEN s.snooze_until_date IS NULL THEN NULL ELSE s.snooze_until_date::text END,
      'note', s.note
    )
    ||
    CASE
      WHEN v_schedule_rebase_result IS NULL THEN '{}'::jsonb
      ELSE jsonb_build_object('schedule_rebase_result', v_schedule_rebase_result)
    END
  INTO v_after
  FROM public.pay_item_snoozes s
  WHERE s.id = v_keeper_id;

  v_event_type := CASE v_action
    WHEN 'CREATED' THEN 'SNOOZE_APPLIED'
    ELSE 'SNOOZE_UPDATED'
  END;

  IF v_finance_case_id IS NOT NULL THEN
    INSERT INTO public.pay_finance_case_events (
      finance_case_id,
      event_type,
      event_at_utc,
      actor_user_id,
      before_json,
      after_json,
      reason,
      note
    )
    VALUES (
      v_finance_case_id,
      v_event_type,
      now(),
      p_actor_user_id,
      v_before,
      v_after,
      v_kind,
      v_note
    );

    PERFORM public._audit_insert(
      'finance_case',
      v_finance_case_id::text,
      v_event_type,
      v_before,
      v_after,
      v_kind,
      p_actor_user_id
    );
  ELSIF coalesce(v_effective_timesheet_id, p_timesheet_id) IS NOT NULL THEN
    PERFORM public._audit_insert(
      'timesheets',
      coalesce(v_effective_timesheet_id, p_timesheet_id)::text,
      v_event_type,
      v_before,
      v_after,
      v_kind,
      p_actor_user_id
    );
  ELSE
    PERFORM public._audit_insert(
      'pay_item_snoozes',
      v_keeper_id::text,
      v_event_type,
      v_before,
      v_after,
      v_kind,
      p_actor_user_id
    );
  END IF;

  RETURN
    jsonb_build_object(
      'ok', true,
      'london_current_date', v_today_uk::text,
      'active_through_end_date', true,
      'action', v_action,
      'id', v_keeper_id::text,
      'candidate_id', p_candidate_id::text,
      'timesheet_id', CASE WHEN v_effective_timesheet_id IS NULL THEN NULL ELSE v_effective_timesheet_id::text END,
      'booking_id', v_booking_id,
      'segment_id', v_effective_segment_id,
      'segment_stable_key', v_segment_stable_key,
      'source_ref', v_source_ref,
      'scope_kind', v_scope_kind,
      'expense_code', v_expense_code,
      'expense_source_basis_fingerprint', v_expense_source_basis_fingerprint,
      'stale_expense_snoozes_cancelled', COALESCE(v_stale_expense_snoozes_cancelled, 0),
      'finance_case_id', CASE WHEN v_finance_case_id IS NULL THEN NULL ELSE v_finance_case_id::text END,
      'snooze_kind', v_kind,
      'snooze_until_date', CASE WHEN p_snooze_until_date IS NULL THEN NULL ELSE p_snooze_until_date::text END,
      'snooze_is_indefinite', (p_snooze_until_date IS NULL),
      'note', v_note,
      'current_official_pay_date', v_date_context->>'current_official_pay_date',
      'next_official_pay_date', v_next_official_pay_date::text,
      'date_context_configuration_fingerprint', v_date_context->>'configuration_fingerprint',
      'resolved_rate_confirmation_applied', COALESCE((v_validation_pre_open->>'warning_required')::boolean, false),
      'pay_run_confirmation_applied', COALESCE((v_validation_pre_save->>'warning_required')::boolean, false)
    )
    ||
    jsonb_build_object(
      'schedule_before_snooze_json', v_schedule_before_snooze_json,
      'next_due_week_start_before_snooze', v_next_due_week_start_before_snooze,
      'requested_week_start', v_requested_week_start,
      'schedule_after_snooze_json', v_schedule_after_snooze_json,
      'next_due_week_start_after_snooze', v_next_due_week_start_after_snooze,
      'installment_count', v_installment_count
    );
END;
$function$;

-- pay_snooze_upsert(uuid,uuid,text,text,text,date,uuid,text)
CREATE OR REPLACE FUNCTION public.pay_snooze_upsert(p_candidate_id uuid, p_timesheet_id uuid, p_segment_id text, p_source_ref text, p_snooze_kind text DEFAULT 'DO_NOT_PAY'::text, p_snooze_until_date date DEFAULT NULL::date, p_actor_user_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_kind text := UPPER(BTRIM(COALESCE(p_snooze_kind, 'DO_NOT_PAY')));
BEGIN
  IF v_kind = 'BLOCKED' THEN
    v_kind := 'BLOCKED_TIMESHEET';
  ELSIF v_kind = 'LOAN_REPAYMENT' THEN
    v_kind := 'PAYMENT_ADVANCE_REPAYMENT';
  END IF;

  IF v_kind IN ('DO_NOT_PAY', 'BLOCKED_TIMESHEET', 'TIMESHEET_PAYMENT') THEN
    RAISE EXCEPTION 'SNOOZE_CONFIRMATION_CONTRACT_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'SNOOZE_CONFIRMATION_CONTRACT_REQUIRED',
              'message', 'This Banking Pay snooze must be validated and confirmed through the current Snooze workflow before it can be saved.',
              'required_rpc', 'pay_snooze_upsert_v2',
              'refresh_required', false
            )::text;
  END IF;

  IF v_kind IN ('OVERPAYMENT_RECOVERY', 'PAYMENT_ADVANCE_REPAYMENT', 'MANUAL_DEBT_RECOVERY')
     AND p_snooze_until_date IS NOT NULL THEN
    RAISE EXCEPTION 'SNOOZE_CONFIRMATION_CONTRACT_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'SNOOZE_CONFIRMATION_CONTRACT_REQUIRED',
              'message', 'This dated finance snooze must be validated and confirmed through the current Snooze workflow before it can be saved.',
              'required_rpc', 'pay_snooze_upsert_v2',
              'refresh_required', false
            )::text;
  END IF;

  IF v_kind NOT IN ('OVERPAYMENT_RECOVERY', 'PAYMENT_ADVANCE_REPAYMENT', 'MANUAL_DEBT_RECOVERY') THEN
    RAISE EXCEPTION 'SNOOZE_KIND_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'SNOOZE_KIND_INVALID',
              'snooze_kind', p_snooze_kind
            )::text;
  END IF;

  RETURN public.pay_snooze_upsert_v2(
    p_candidate_id,
    p_timesheet_id,
    p_segment_id,
    p_source_ref,
    v_kind,
    p_snooze_until_date,
    p_actor_user_id,
    p_note,
    NULL::text,
    NULL::text,
    NULL::text
  );
END;
$function$;

-- pay_snooze_validate_request_v1(uuid,uuid,uuid,text,text,text,text,date,text)
CREATE OR REPLACE FUNCTION public.pay_snooze_validate_request_v1(p_actor_user_id uuid, p_candidate_id uuid, p_timesheet_id uuid, p_segment_id text DEFAULT NULL::text, p_segment_stable_key text DEFAULT NULL::text, p_source_ref text DEFAULT NULL::text, p_snooze_kind text DEFAULT 'DO_NOT_PAY'::text, p_snooze_until_date date DEFAULT NULL::date, p_validation_phase text DEFAULT 'PRE_SAVE'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_phase text := UPPER(BTRIM(COALESCE(p_validation_phase, 'PRE_SAVE')));
  v_issue_acknowledgement boolean := true;
  v_kind_input text := UPPER(BTRIM(COALESCE(p_snooze_kind, 'DO_NOT_PAY')));
  v_kind text;
  v_is_payment_scope boolean := false;
  v_scope_kind text;
  v_noun text;
  v_input_segment_id text := NULLIF(BTRIM(COALESCE(p_segment_id, '')), '');
  v_input_segment_stable_key text := NULLIF(BTRIM(COALESCE(p_segment_stable_key, '')), '');
  v_source_ref text := LOWER(NULLIF(BTRIM(COALESCE(p_source_ref, '')), ''));
  v_is_timesheet_expense_scope boolean := false;
  v_expense_source_timesheet_id uuid := NULL::uuid;
  v_expense_code text := NULL::text;
  v_expense_label text := NULL::text;
  v_expense_item_type text := NULL::text;
  v_expense_source_basis_fingerprint text := NULL::text;
  v_expense_source_basis_json jsonb := NULL::jsonb;
  v_expense_amount_ex_vat numeric := NULL::numeric;
  v_expense_amount_display numeric := NULL::numeric;
  v_expense_source_charge_ex_vat numeric := NULL::numeric;
  v_expense_source_row_json jsonb := NULL::jsonb;
  v_finance_case_id uuid := NULL::uuid;
  v_expected_finance_case_type public.pay_finance_case_type_enum;
  v_effective_timesheet_id uuid := NULL::uuid;
  v_booking_id text := NULL::text;
  v_effective_candidate_id uuid := NULL::uuid;
  v_effective_segment_id text := NULL::text;
  v_effective_segment_stable_key text := NULL::text;
  v_invoice_breakdown_json jsonb := '{}'::jsonb;
  v_date_context jsonb;
  v_london_current_date date;
  v_next_official_pay_date date;
  v_date_context_fingerprint text;
  v_has_resolved_rate boolean := false;
  v_resolved_component_count integer := 0;
  v_resolution_fingerprint text := NULL::text;
  v_warning_required boolean := false;
  v_warning_code text := NULL::text;
  v_warning_message text := NULL::text;
  v_date_relation text := 'NOT_APPLICABLE';
  v_scope_fingerprint text;
  v_acknowledgement_token uuid := NULL::uuid;
  v_acknowledgement_expires_at_utc timestamptz := NULL::timestamptz;
BEGIN
  declare v_correction_chain jsonb;
  begin
    if p_timesheet_id is not null and coalesce((public._ctms_import_correction_classify_v1(p_timesheet_id)->>'is_import_authoritative_correction')::boolean,false) then
      v_correction_chain:=public.timesheet_correction_chain_scope_v1(p_timesheet_id,false,32,100);
      if coalesce((v_correction_chain->>'valid')::boolean,false) is not true then raise exception 'CORRECTION_CHAIN_INVALID_FOR_SNOOZE' using errcode='P0001',detail=v_correction_chain::text; end if;
      v_input_segment_stable_key:='correction-chain:'||(v_correction_chain->>'root_timesheet_id');
      v_source_ref:=v_input_segment_stable_key;
    end if;
  end;
  IF v_phase IN ('INTERNAL_PRE_OPEN', 'PRE_OPEN_CHECK') THEN
    v_phase := 'PRE_OPEN';
    v_issue_acknowledgement := false;
  ELSIF v_phase IN ('INTERNAL_PRE_SAVE', 'PRE_SAVE_CHECK') THEN
    v_phase := 'PRE_SAVE';
    v_issue_acknowledgement := false;
  ELSIF v_phase NOT IN ('PRE_OPEN', 'PRE_SAVE') THEN
    RAISE EXCEPTION 'SNOOZE_VALIDATION_PHASE_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'SNOOZE_VALIDATION_PHASE_INVALID',
              'validation_phase', p_validation_phase
            )::text;
  END IF;

  IF p_actor_user_id IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.tms_users AS actor_row
    WHERE actor_row.id = p_actor_user_id
      AND actor_row.is_active IS TRUE
  ) THEN
    RAISE EXCEPTION 'SNOOZE_ACTOR_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'SNOOZE_ACTOR_INVALID')::text;
  END IF;

  IF p_candidate_id IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.candidates AS candidate_row
    WHERE candidate_row.id = p_candidate_id
  ) THEN
    RAISE EXCEPTION 'SNOOZE_CANDIDATE_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'SNOOZE_CANDIDATE_INVALID')::text;
  END IF;

  v_kind := CASE v_kind_input
    WHEN 'BLOCKED' THEN 'BLOCKED_TIMESHEET'
    WHEN 'BLOCKED_TIMESHEET' THEN 'BLOCKED_TIMESHEET'
    WHEN 'DO_NOT_PAY' THEN 'DO_NOT_PAY'
    WHEN 'TIMESHEET_PAYMENT' THEN 'TIMESHEET_PAYMENT'
    WHEN 'OVERPAYMENT_RECOVERY' THEN 'OVERPAYMENT_RECOVERY'
    WHEN 'PAYMENT_ADVANCE_REPAYMENT' THEN 'PAYMENT_ADVANCE_REPAYMENT'
    WHEN 'LOAN_REPAYMENT' THEN 'PAYMENT_ADVANCE_REPAYMENT'
    WHEN 'MANUAL_DEBT_RECOVERY' THEN 'MANUAL_DEBT_RECOVERY'
    ELSE NULL::text
  END;

  IF v_kind IS NULL THEN
    RAISE EXCEPTION 'SNOOZE_KIND_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'SNOOZE_KIND_INVALID', 'snooze_kind', p_snooze_kind)::text;
  END IF;

  v_is_payment_scope := v_kind IN ('DO_NOT_PAY', 'BLOCKED_TIMESHEET', 'TIMESHEET_PAYMENT');
  v_is_timesheet_expense_scope := (
    v_kind = 'DO_NOT_PAY'
    AND v_source_ref IS NOT NULL
    AND v_source_ref ~ '^timesheet-expense:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}:(expenses|travel|accommodation|other|mileage):[0-9a-f]{32}$'
  );

  IF v_source_ref IS NOT NULL
     AND v_is_payment_scope
     AND COALESCE(v_is_timesheet_expense_scope, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'SNOOZE_TIMESHEET_SOURCE_REF_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'SNOOZE_TIMESHEET_SOURCE_REF_INVALID',
              'source_ref', v_source_ref,
              'snooze_kind', v_kind,
              'refresh_required', true
            )::text;
  END IF;

  IF v_is_payment_scope THEN
    IF p_timesheet_id IS NULL THEN
      RAISE EXCEPTION 'SNOOZE_TIMESHEET_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'SNOOZE_TIMESHEET_REQUIRED')::text;
    END IF;

    SELECT input_timesheet.booking_id
    INTO v_booking_id
    FROM public.timesheets AS input_timesheet
    WHERE input_timesheet.timesheet_id = p_timesheet_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'SNOOZE_TIMESHEET_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'SNOOZE_TIMESHEET_INVALID', 'timesheet_id', p_timesheet_id::text)::text;
    END IF;

    SELECT current_timesheet.timesheet_id
    INTO v_effective_timesheet_id
    FROM public.timesheets AS current_timesheet
    WHERE current_timesheet.booking_id = v_booking_id
      AND current_timesheet.is_current IS TRUE
    ORDER BY COALESCE(current_timesheet.version, 0) DESC,
             current_timesheet.updated_at DESC NULLS LAST,
             current_timesheet.created_at DESC NULLS LAST,
             current_timesheet.timesheet_id DESC
    LIMIT 1;

    v_effective_timesheet_id := COALESCE(v_effective_timesheet_id, p_timesheet_id);

    SELECT financial_row.candidate_id,
           COALESCE(financial_row.invoice_breakdown_json, '{}'::jsonb)
    INTO v_effective_candidate_id,
         v_invoice_breakdown_json
    FROM public.timesheets_financials AS financial_row
    WHERE financial_row.timesheet_id = v_effective_timesheet_id
    ORDER BY CASE WHEN financial_row.is_current IS TRUE THEN 0 ELSE 1 END,
             financial_row.updated_at DESC NULLS LAST,
             financial_row.created_at DESC NULLS LAST,
             financial_row.id DESC
    LIMIT 1;

    IF v_effective_candidate_id IS DISTINCT FROM p_candidate_id THEN
      RAISE EXCEPTION 'SNOOZE_TIMESHEET_CANDIDATE_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'SNOOZE_TIMESHEET_CANDIDATE_MISMATCH',
                'candidate_id', p_candidate_id::text,
                'timesheet_id', v_effective_timesheet_id::text,
                'resolved_candidate_id', CASE WHEN v_effective_candidate_id IS NULL THEN NULL ELSE v_effective_candidate_id::text END
              )::text;
    END IF;

    IF COALESCE(v_is_timesheet_expense_scope, false) THEN
      IF v_input_segment_id IS NOT NULL OR v_input_segment_stable_key IS NOT NULL THEN
        RAISE EXCEPTION 'SNOOZE_EXPENSE_SCOPE_MUST_NOT_HAVE_SEGMENT'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'SNOOZE_EXPENSE_SCOPE_MUST_NOT_HAVE_SEGMENT',
                  'source_ref', v_source_ref
                )::text;
      END IF;

      v_expense_source_timesheet_id := split_part(v_source_ref, ':', 2)::uuid;
      v_expense_code := UPPER(split_part(v_source_ref, ':', 3));
      v_expense_source_basis_fingerprint := LOWER(split_part(v_source_ref, ':', 4));
      v_expense_label := CASE v_expense_code
        WHEN 'EXPENSES' THEN 'Expenses'
        WHEN 'TRAVEL' THEN 'Travel'
        WHEN 'ACCOMMODATION' THEN 'Accommodation'
        WHEN 'OTHER' THEN 'Other'
        WHEN 'MILEAGE' THEN 'Mileage'
        ELSE NULL::text
      END;
      v_expense_item_type := CASE WHEN v_expense_code = 'MILEAGE' THEN 'MILEAGE_DELTA' ELSE 'EXPENSE_DELTA' END;

      IF v_expense_source_timesheet_id IS DISTINCT FROM v_effective_timesheet_id THEN
        RAISE EXCEPTION 'SNOOZE_EXPENSE_TIMESHEET_IDENTITY_STALE'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'SNOOZE_EXPENSE_TIMESHEET_IDENTITY_STALE',
                  'source_ref', v_source_ref,
                  'source_timesheet_id', v_expense_source_timesheet_id::text,
                  'current_timesheet_id', v_effective_timesheet_id::text,
                  'refresh_required', true
                )::text;
      END IF;

      SELECT
        source_line.source_row_json,
        COALESCE(
          source_line.source_row_json->'expense_source_basis_json',
          source_line.source_row_json->'source_basis_json',
          '{}'::jsonb
        ),
        NULLIF(BTRIM(COALESCE(
          source_line.source_row_json->>'source_basis_fingerprint',
          source_line.source_row_json->>'expense_source_basis_fingerprint',
          ''
        )), ''),
        CASE
          WHEN COALESCE(source_line.source_row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
            THEN (source_line.source_row_json->>'amount_ex_vat')::numeric
          WHEN COALESCE(source_line.source_row_json->>'preview_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
            THEN (source_line.source_row_json->>'preview_amount_ex_vat')::numeric
          ELSE NULL::numeric
        END,
        CASE
          WHEN COALESCE(source_line.source_row_json->>'amount_display', '') ~ '^-?[0-9]+([.][0-9]+)?$'
            THEN (source_line.source_row_json->>'amount_display')::numeric
          WHEN COALESCE(source_line.source_row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
            THEN (source_line.source_row_json->>'amount_ex_vat')::numeric
          ELSE NULL::numeric
        END,
        CASE
          WHEN COALESCE(source_line.source_row_json#>>'{expense_source_basis_json,source_charge_ex_vat}', '') ~ '^-?[0-9]+([.][0-9]+)?$'
            THEN (source_line.source_row_json#>>'{expense_source_basis_json,source_charge_ex_vat}')::numeric
          WHEN COALESCE(source_line.source_row_json#>>'{source_basis_json,source_charge_ex_vat}', '') ~ '^-?[0-9]+([.][0-9]+)?$'
            THEN (source_line.source_row_json#>>'{source_basis_json,source_charge_ex_vat}')::numeric
          ELSE NULL::numeric
        END
      INTO
        v_expense_source_row_json,
        v_expense_source_basis_json,
        v_expense_source_basis_fingerprint,
        v_expense_amount_ex_vat,
        v_expense_amount_display,
        v_expense_source_charge_ex_vat
      FROM public.banking_pay_workbench_candidate_source_lines AS source_line
      JOIN public.banking_pay_workbench_sessions AS source_session
        ON source_session.id = source_line.session_id
      LEFT JOIN public.app_change_counters AS candidate_counter
        ON candidate_counter.entity_key = 'pay_candidate:' || p_candidate_id::text
      WHERE source_line.candidate_id = p_candidate_id
        AND source_line.timesheet_id = v_effective_timesheet_id
        AND source_line.status = 'CURRENT'
        AND source_line.session_version = COALESCE(source_session.version, 1)
        AND source_line.source_change_seq = COALESCE(candidate_counter.seq, 0)
        AND UPPER(BTRIM(COALESCE(source_session.status, ''))) = 'OPEN'
        AND source_session.discarded_at_utc IS NULL
        AND source_session.replacement_session_id IS NULL
        AND LOWER(BTRIM(COALESCE(source_line.source_row_json->>'source_ref', ''))) = v_source_ref
        AND UPPER(BTRIM(COALESCE(source_line.source_row_json#>>'{snooze_identity,identity_type}', ''))) = 'TIMESHEET_EXPENSE'
        AND UPPER(BTRIM(COALESCE(
              source_line.economic_key_json->>'key_type',
              source_line.source_row_json#>>'{economic_key,key_type}',
              source_line.source_row_json->>'component_key_type',
              ''
            ))) = 'EXPENSE_CODE'
        AND UPPER(BTRIM(COALESCE(
              source_line.economic_key_json->>'key_value',
              source_line.source_row_json#>>'{economic_key,key_value}',
              source_line.source_row_json->>'component_key_value',
              ''
            ))) = v_expense_code
      ORDER BY source_session.updated_at_utc DESC NULLS LAST,
               source_line.updated_at_utc DESC NULLS LAST,
               source_line.id DESC
      LIMIT 1;

      IF v_expense_source_row_json IS NULL
         OR v_expense_source_basis_fingerprint IS DISTINCT FROM LOWER(split_part(v_source_ref, ':', 4))
         OR md5(COALESCE(v_expense_source_basis_json, '{}'::jsonb)::text) IS DISTINCT FROM LOWER(split_part(v_source_ref, ':', 4))
         OR UPPER(BTRIM(COALESCE(v_expense_source_row_json->>'expense_code', v_expense_source_row_json->>'component_key_value', ''))) IS DISTINCT FROM v_expense_code THEN
        RAISE EXCEPTION 'SNOOZE_EXPENSE_SOURCE_IDENTITY_STALE'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'SNOOZE_EXPENSE_SOURCE_IDENTITY_STALE',
                  'candidate_id', p_candidate_id::text,
                  'timesheet_id', v_effective_timesheet_id::text,
                  'expense_code', v_expense_code,
                  'source_ref', v_source_ref,
                  'refresh_required', true
                )::text;
      END IF;

      v_scope_kind := 'TIMESHEET_EXPENSE';
      v_noun := LOWER(v_expense_label || ' expense');
    ELSIF v_kind = 'TIMESHEET_PAYMENT' THEN
      IF v_source_ref IS NOT NULL THEN
        RAISE EXCEPTION 'SNOOZE_TIMESHEET_SCOPE_MUST_NOT_HAVE_SOURCE_REF'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object('code', 'SNOOZE_TIMESHEET_SCOPE_MUST_NOT_HAVE_SOURCE_REF')::text;
      END IF;
      IF v_input_segment_id IS NOT NULL OR v_input_segment_stable_key IS NOT NULL THEN
        RAISE EXCEPTION 'SNOOZE_TIMESHEET_SCOPE_MUST_NOT_HAVE_SEGMENT'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object('code', 'SNOOZE_TIMESHEET_SCOPE_MUST_NOT_HAVE_SEGMENT')::text;
      END IF;
      v_scope_kind := 'TIMESHEET';
      v_noun := 'timesheet';
    ELSE
      IF v_source_ref IS NOT NULL THEN
        RAISE EXCEPTION 'SNOOZE_SEGMENT_SCOPE_MUST_NOT_HAVE_SOURCE_REF'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object('code', 'SNOOZE_SEGMENT_SCOPE_MUST_NOT_HAVE_SOURCE_REF')::text;
      END IF;
      IF v_input_segment_id IS NULL AND v_input_segment_stable_key IS NULL THEN
        RAISE EXCEPTION 'SNOOZE_SEGMENT_IDENTITY_REQUIRED'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object('code', 'SNOOZE_SEGMENT_IDENTITY_REQUIRED')::text;
      END IF;

      SELECT NULLIF(BTRIM(COALESCE(
               segment_row.value->>'segment_id',
               segment_row.value->>'id',
               segment_row.value->>'segment_key',
               ''
             )), ''),
             NULLIF(BTRIM(COALESCE(
               segment_row.value->>'segment_stable_key',
               segment_row.value->>'work_date',
               segment_row.value->>'ref_num',
               segment_row.value->>'segment_key',
               segment_row.value->>'segment_id',
               ''
             )), '')
      INTO v_effective_segment_id,
           v_effective_segment_stable_key
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(v_invoice_breakdown_json->'segments') = 'array'
            THEN v_invoice_breakdown_json->'segments'
          ELSE '[]'::jsonb
        END
      ) WITH ORDINALITY AS segment_row(value, ordinal)
      WHERE (
        v_input_segment_stable_key IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(
          segment_row.value->>'segment_stable_key',
          segment_row.value->>'work_date',
          segment_row.value->>'ref_num',
          segment_row.value->>'segment_key',
          segment_row.value->>'segment_id',
          ''
        )), '') = v_input_segment_stable_key
      ) OR (
        v_input_segment_id IS NOT NULL
        AND (
          NULLIF(BTRIM(COALESCE(segment_row.value->>'segment_id', '')), '') = v_input_segment_id
          OR NULLIF(BTRIM(COALESCE(segment_row.value->>'id', '')), '') = v_input_segment_id
          OR NULLIF(BTRIM(COALESCE(segment_row.value->>'segment_key', '')), '') = v_input_segment_id
          OR NULLIF(BTRIM(COALESCE(segment_row.value->>'segment_stable_key', '')), '') = v_input_segment_id
        )
      )
      ORDER BY CASE
        WHEN v_input_segment_stable_key IS NOT NULL
             AND NULLIF(BTRIM(COALESCE(segment_row.value->>'segment_stable_key', '')), '') = v_input_segment_stable_key THEN 0
        WHEN v_input_segment_id IS NOT NULL
             AND NULLIF(BTRIM(COALESCE(segment_row.value->>'segment_id', '')), '') = v_input_segment_id THEN 1
        ELSE 2
      END,
      segment_row.ordinal
      LIMIT 1;

      v_effective_segment_id := COALESCE(v_effective_segment_id, v_input_segment_id);
      v_effective_segment_stable_key := COALESCE(v_effective_segment_stable_key, v_input_segment_stable_key);

      IF v_effective_segment_stable_key IS NULL THEN
        RAISE EXCEPTION 'SNOOZE_SEGMENT_IDENTITY_UNVERIFIABLE'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'SNOOZE_SEGMENT_IDENTITY_UNVERIFIABLE',
                  'timesheet_id', v_effective_timesheet_id::text,
                  'segment_id', v_input_segment_id,
                  'segment_stable_key', v_input_segment_stable_key
                )::text;
      END IF;

      v_scope_kind := 'SEGMENT';
      v_noun := 'shift';
    END IF;
  ELSE
    IF p_timesheet_id IS NOT NULL OR v_input_segment_id IS NOT NULL OR v_input_segment_stable_key IS NOT NULL THEN
      RAISE EXCEPTION 'SNOOZE_FINANCE_SCOPE_IDENTITY_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'SNOOZE_FINANCE_SCOPE_IDENTITY_INVALID')::text;
    END IF;

    IF v_source_ref IS NULL THEN
      RAISE EXCEPTION 'SNOOZE_FINANCE_SOURCE_REF_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'SNOOZE_FINANCE_SOURCE_REF_REQUIRED')::text;
    END IF;

    IF v_source_ref !~* '^advance:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'SNOOZE_FINANCE_SOURCE_REF_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'SNOOZE_FINANCE_SOURCE_REF_INVALID',
                'source_ref', v_source_ref
              )::text;
    END IF;

    v_finance_case_id := split_part(v_source_ref, ':', 2)::uuid;
    v_expected_finance_case_type := CASE v_kind
      WHEN 'OVERPAYMENT_RECOVERY' THEN 'OVERPAYMENT'::public.pay_finance_case_type_enum
      WHEN 'PAYMENT_ADVANCE_REPAYMENT' THEN 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum
      WHEN 'MANUAL_DEBT_RECOVERY' THEN 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum
      ELSE NULL::public.pay_finance_case_type_enum
    END;

    IF NOT EXISTS (
      SELECT 1
      FROM public.pay_advances AS finance_case
      WHERE finance_case.id = v_finance_case_id
        AND finance_case.candidate_id = p_candidate_id
        AND finance_case.case_type = v_expected_finance_case_type
    ) THEN
      RAISE EXCEPTION 'SNOOZE_FINANCE_CASE_AUTHORITY_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'SNOOZE_FINANCE_CASE_AUTHORITY_MISMATCH',
                'candidate_id', p_candidate_id::text,
                'source_ref', v_source_ref,
                'snooze_kind', v_kind
              )::text;
    END IF;

    v_scope_kind := 'FINANCE_CASE';
    v_noun := 'payment';
  END IF;

  v_date_context := public.pay_banking_official_date_context_v1(NULL::timestamptz);
  v_london_current_date := (v_date_context->>'business_date')::date;
  v_next_official_pay_date := (v_date_context->>'next_official_pay_date')::date;
  v_date_context_fingerprint := v_date_context->>'configuration_fingerprint';

  IF p_snooze_until_date IS NOT NULL AND p_snooze_until_date < v_london_current_date THEN
    RAISE EXCEPTION 'SNOOZE_DATE_IN_PAST'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'SNOOZE_DATE_IN_PAST',
              'london_current_date', v_london_current_date::text,
              'snooze_until_date', p_snooze_until_date::text
            )::text;
  END IF;

  IF v_is_payment_scope THEN
    SELECT COUNT(*)::integer,
           CASE WHEN COUNT(*) > 0 THEN true ELSE false END,
           CASE
             WHEN COUNT(*) = 0 THEN NULL::text
             ELSE md5(string_agg(
               resolution_row.id::text
               || ':' || resolution_row.resolution_identity_key
               || ':' || COALESCE(resolution_row.updated_at_utc::text, ''),
               '|' ORDER BY resolution_row.id::text
             ))
           END
    INTO v_resolved_component_count,
         v_has_resolved_rate,
         v_resolution_fingerprint
    FROM public.banking_pay_workbench_session_case_resolutions AS resolution_row
    JOIN public.banking_pay_workbench_sessions AS resolution_session
      ON resolution_session.id = resolution_row.session_id
    WHERE resolution_row.candidate_id = p_candidate_id
      AND resolution_row.timesheet_id = v_effective_timesheet_id
      AND UPPER(BTRIM(COALESCE(resolution_row.resolution_family, ''))) IN ('BUCKETED', 'NON_BUCKET')
      AND resolution_session.status = 'OPEN'
      AND resolution_session.discarded_at_utc IS NULL
      AND resolution_session.replacement_session_id IS NULL
      AND (
        v_scope_kind = 'TIMESHEET'
        OR (
          v_scope_kind = 'SEGMENT'
          AND (
            NULLIF(BTRIM(COALESCE(resolution_row.payload_json->>'segment_stable_key', '')), '') = v_effective_segment_stable_key
            OR NULLIF(BTRIM(COALESCE(resolution_row.payload_json#>>'{source_basis_json,segment_stable_key}', '')), '') = v_effective_segment_stable_key
            OR NULLIF(BTRIM(COALESCE(resolution_row.payload_json->>'segment_id', '')), '') = v_effective_segment_id
            OR NULLIF(BTRIM(COALESCE(resolution_row.payload_json#>>'{source_basis_json,segment_id}', '')), '') = v_effective_segment_id
          )
        )
      );
  END IF;

  IF v_phase = 'PRE_OPEN' AND v_has_resolved_rate THEN
    v_warning_required := true;
    v_warning_code := 'RATE_RESOLUTION_REQUIRES_REVIEW_AFTER_UNSNOOZE';
    v_warning_message := CASE
      WHEN v_scope_kind = 'SEGMENT' THEN
        'This shift has a rate resolved to it. When you unsnooze it, you will need to resolve this rate again if it is unsnoozed in a different pay week to this one.'
      ELSE
        'This timesheet has a rate resolved to it. When you unsnooze it, you will need to resolve this rate again if it is unsnoozed in a different pay week to this one.'
    END;
  ELSIF v_phase = 'PRE_SAVE' AND p_snooze_until_date IS NOT NULL THEN
    IF p_snooze_until_date < v_next_official_pay_date THEN
      v_warning_required := true;
      v_warning_code := 'SNOOZE_DATE_BEFORE_NEXT_PAY_RUN';
      v_date_relation := 'BEFORE_NEXT_OFFICIAL_PAY_DATE';
      v_warning_message := 'This snooze date is before the next official pay run. Your payment will be snoozed but it will be eligible to pay in the next pay run once that date has passed.';
    ELSE
      v_warning_required := true;
      v_warning_code := 'SNOOZE_INCLUDES_NEXT_PAY_RUN';
      v_date_relation := CASE
        WHEN p_snooze_until_date = v_next_official_pay_date THEN 'EQUAL_TO_NEXT_OFFICIAL_PAY_DATE'
        ELSE 'AFTER_NEXT_OFFICIAL_PAY_DATE'
      END;
      v_warning_message := 'This snooze includes the next official pay run date, so this payment will not be eligible for that pay run. It may become eligible after the snooze date has passed, subject to the usual payment checks.';
    END IF;
  END IF;

  IF v_phase = 'PRE_SAVE' AND p_snooze_until_date IS NULL THEN
    v_date_relation := CASE WHEN p_snooze_until_date IS NULL THEN 'INDEFINITE' ELSE 'NOT_APPLICABLE' END;
  END IF;

  v_scope_fingerprint := md5(concat_ws('|',
    p_actor_user_id::text,
    p_candidate_id::text,
    COALESCE(v_effective_timesheet_id::text, ''),
    COALESCE(v_effective_segment_id, ''),
    COALESCE(v_effective_segment_stable_key, ''),
    COALESCE(v_source_ref, ''),
    v_kind,
    CASE WHEN v_phase = 'PRE_SAVE' THEN COALESCE(p_snooze_until_date::text, '') ELSE '' END,
    v_phase,
    COALESCE(v_warning_code, ''),
    COALESCE(v_resolution_fingerprint, ''),
    COALESCE(v_date_context_fingerprint, '')
  ));

  IF v_warning_required AND v_issue_acknowledgement THEN
    v_acknowledgement_token := gen_random_uuid();
    v_acknowledgement_expires_at_utc := v_now + interval '30 minutes';

    WITH expired_ack_ids AS (
      SELECT expired_ack.id
      FROM public.pay_snooze_warning_acknowledgements AS expired_ack
      WHERE expired_ack.expires_at_utc < v_now - interval '1 day'
      ORDER BY expired_ack.expires_at_utc, expired_ack.id
      LIMIT 100
    )
    DELETE FROM public.pay_snooze_warning_acknowledgements AS expired_ack
    USING expired_ack_ids
    WHERE expired_ack.id = expired_ack_ids.id;

    INSERT INTO public.pay_snooze_warning_acknowledgements (
      token_hash,
      actor_user_id,
      validation_phase,
      candidate_id,
      timesheet_id,
      segment_id,
      segment_stable_key,
      source_ref,
      snooze_kind,
      snooze_until_date,
      warning_code,
      scope_fingerprint,
      resolution_fingerprint,
      date_context_fingerprint,
      created_at_utc,
      expires_at_utc
    )
    VALUES (
      md5(v_acknowledgement_token::text),
      p_actor_user_id,
      v_phase,
      p_candidate_id,
      v_effective_timesheet_id,
      v_effective_segment_id,
      v_effective_segment_stable_key,
      v_source_ref,
      v_kind,
      p_snooze_until_date,
      v_warning_code,
      v_scope_fingerprint,
      v_resolution_fingerprint,
      v_date_context_fingerprint,
      v_now,
      v_acknowledgement_expires_at_utc
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'validation_phase', v_phase,
    'warning_required', v_warning_required,
    'warning_code', v_warning_code,
    'warning_message', v_warning_message,
    'buttons', CASE WHEN v_warning_required THEN jsonb_build_array('Cancel', 'OK') ELSE '[]'::jsonb END,
    'acknowledgement_token', CASE WHEN v_acknowledgement_token IS NULL THEN NULL ELSE v_acknowledgement_token::text END,
    'acknowledgement_expires_at_utc', v_acknowledgement_expires_at_utc,
    'scope_fingerprint', v_scope_fingerprint,
    'candidate_id', p_candidate_id::text,
    'timesheet_id', CASE WHEN v_effective_timesheet_id IS NULL THEN NULL ELSE v_effective_timesheet_id::text END,
    'booking_id', v_booking_id,
    'segment_id', v_effective_segment_id,
    'segment_stable_key', v_effective_segment_stable_key,
    'source_ref', v_source_ref,
    'scope_kind', v_scope_kind,
    'noun', v_noun,
    'expense_code', v_expense_code,
    'expense_label', v_expense_label,
    'expense_item_type', v_expense_item_type,
    'expense_source_basis_fingerprint', v_expense_source_basis_fingerprint,
    'expense_source_basis_json', v_expense_source_basis_json,
    'expense_amount_ex_vat', v_expense_amount_ex_vat,
    'expense_amount_display', v_expense_amount_display,
    'expense_source_charge_ex_vat', v_expense_source_charge_ex_vat,
    'snooze_kind', v_kind,
    'snooze_until_date', CASE WHEN p_snooze_until_date IS NULL THEN NULL ELSE p_snooze_until_date::text END,
    'london_current_date', v_london_current_date::text,
    'current_official_pay_date', v_date_context->>'current_official_pay_date',
    'next_official_pay_date', v_next_official_pay_date::text,
    'date_relation_to_next_pay_run', v_date_relation,
    'requires_before_next_run_warning', v_warning_code = 'SNOOZE_DATE_BEFORE_NEXT_PAY_RUN',
    'requires_includes_next_run_warning', v_warning_code = 'SNOOZE_INCLUDES_NEXT_PAY_RUN',
    'has_resolved_rate', v_has_resolved_rate,
    'resolved_rate_component_count', v_resolved_component_count,
    'resolution_fingerprint', v_resolution_fingerprint,
    'date_context_configuration_fingerprint', v_date_context_fingerprint
  );
END;
$function$;

-- pay_snoozes_export_rows(uuid,date,date,text,uuid,uuid,text,text,text)
CREATE OR REPLACE FUNCTION public.pay_snoozes_export_rows(p_actor_user_id uuid DEFAULT NULL::uuid, p_created_from date DEFAULT NULL::date, p_created_to date DEFAULT NULL::date, p_status text DEFAULT 'ALL'::text, p_candidate_id uuid DEFAULT NULL::uuid, p_client_id uuid DEFAULT NULL::uuid, p_case_type text DEFAULT NULL::text, p_sort_key text DEFAULT 'created_at'::text, p_sort_dir text DEFAULT 'desc'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status text := upper(btrim(coalesce(p_status, 'ALL')));
  v_case_type text := upper(nullif(btrim(coalesce(p_case_type, '')), ''));
  v_sort_key text := lower(coalesce(nullif(btrim(p_sort_key), ''), 'created_at'));
  v_sort_dir text := lower(coalesce(nullif(btrim(p_sort_dir), ''), 'desc'));
  v_rows jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
  v_meta jsonb := '{}'::jsonb;
  v_date_context jsonb := '{}'::jsonb;
  v_today_uk date := NULL::date;
BEGIN
  IF v_status NOT IN ('ALL', 'OUTSTANDING', 'FULLY_PAID') THEN
    v_status := 'ALL';
  END IF;

  IF v_sort_key NOT IN (
    'created_at',
    'updated_at',
    'candidate',
    'client',
    'snooze_until_date'
  ) THEN
    v_sort_key := 'created_at';
  END IF;

  IF v_sort_dir NOT IN ('asc', 'desc') THEN
    v_sort_dir := 'desc';
  END IF;

  v_date_context := public.pay_banking_official_date_context_v1(NULL::timestamptz);
  v_today_uk := CASE
    WHEN coalesce(v_date_context->>'london_current_date', '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      THEN (v_date_context->>'london_current_date')::date
    ELSE NULL::date
  END;

  IF v_today_uk IS NULL THEN
    RAISE EXCEPTION 'PAY_SNOOZES_EXPORT_LONDON_DATE_UNAVAILABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SNOOZES_EXPORT_LONDON_DATE_UNAVAILABLE',
              'message', 'The current Europe/London business date could not be resolved for the Snoozes report.'
            )::text;
  END IF;

  WITH parsed_snoozes AS (
    SELECT
      s.id AS snooze_id,
      s.candidate_id AS snooze_candidate_id,
      s.timesheet_id,
      s.booking_id,
      s.segment_id,
      s.segment_stable_key,
      s.source_ref,
      s.snooze_kind,
      s.snooze_until_date,
      s.note,
      s.created_at_utc,
      s.created_by_user_id,
      s.updated_at_utc,
      s.updated_by_user_id,
      s.cleared_at_utc,
      s.cleared_by_user_id,
      s.cancelled_at_utc,
      s.cancelled_by_user_id,
      s.cancel_reason,
      CASE
        WHEN s.source_ref IS NOT NULL
         AND s.source_ref LIKE 'advance:%'
         AND split_part(s.source_ref, ':', 2) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        THEN split_part(s.source_ref, ':', 2)::uuid
        ELSE NULL::uuid
      END AS finance_case_id,
      CASE
        WHEN LOWER(NULLIF(BTRIM(COALESCE(s.source_ref, '')), '')) ~
             '^timesheet-expense:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}:(expenses|travel|accommodation|other|mileage):[0-9a-f]{32}$'
          THEN true
        ELSE false
      END AS is_timesheet_expense,
      CASE
        WHEN LOWER(NULLIF(BTRIM(COALESCE(s.source_ref, '')), '')) ~
             '^timesheet-expense:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}:(expenses|travel|accommodation|other|mileage):[0-9a-f]{32}$'
          THEN UPPER(split_part(LOWER(s.source_ref), ':', 3))
        ELSE NULL::text
      END AS expense_code,
      CASE
        WHEN LOWER(NULLIF(BTRIM(COALESCE(s.source_ref, '')), '')) ~
             '^timesheet-expense:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}:(expenses|travel|accommodation|other|mileage):[0-9a-f]{32}$'
          THEN LOWER(split_part(LOWER(s.source_ref), ':', 4))
        ELSE NULL::text
      END AS expense_source_basis_fingerprint
    FROM public.pay_item_snoozes AS s
    WHERE
      (p_created_from IS NULL OR s.created_at_utc::date >= p_created_from)
      AND (p_created_to IS NULL OR s.created_at_utc::date <= p_created_to)
      AND (
        (s.source_ref IS NOT NULL AND LOWER(s.source_ref) LIKE 'advance:%')
        OR (s.source_ref IS NOT NULL AND LOWER(s.source_ref) LIKE 'timesheet-expense:%')
        OR s.timesheet_id IS NOT NULL
      )
  ),
  base_rows AS (
    SELECT
      ps.snooze_id,
      CASE
        WHEN ps.finance_case_id IS NOT NULL THEN 'FINANCE_CASE'
        WHEN ps.is_timesheet_expense THEN 'TIMESHEET_EXPENSE'
        ELSE 'TIMESHEET_PAYMENT'
      END AS snooze_scope,
      CASE
        WHEN ps.finance_case_id IS NOT NULL THEN
          CASE vfcr.case_type
            WHEN 'PAYMENT_ADVANCE' THEN 'Payment Advance'
            WHEN 'OVERPAYMENT' THEN 'Overpayment'
            WHEN 'UNDERPAYMENT' THEN 'Underpayment'
            WHEN 'MANUAL_DEBT_ADJUSTMENT' THEN 'Manual Debt Adjustment'
            WHEN 'MANUAL_CREDIT_ADJUSTMENT' THEN 'Manual Credit Adjustment'
            ELSE coalesce(vfcr.case_type::text, 'Finance Case')
          END
        WHEN ps.is_timesheet_expense THEN
          CASE ps.expense_code
            WHEN 'EXPENSES' THEN 'Expenses'
            WHEN 'TRAVEL' THEN 'Travel'
            WHEN 'ACCOMMODATION' THEN 'Accommodation'
            WHEN 'OTHER' THEN 'Other'
            WHEN 'MILEAGE' THEN 'Mileage'
            ELSE 'Timesheet Expense'
          END
        ELSE 'Timesheet Payment'
      END AS row_label,
      vfcr.case_type,
      cs.tms_ref AS candidate_tms_ref,
      cs.tms_ref_num AS candidate_tms_ref_num,
      cs.first_name AS candidate_first_name,
      cs.last_name AS candidate_last_name,
      coalesce(cs.display_name, vfcr.candidate_display_name, vts.candidate_name) AS candidate_display_name,
      coalesce(vfcr.client_name, vts.client_name) AS client_name,
      coalesce(ts_current.booking_id, ts_stored.booking_id, ps.booking_id) AS linked_timesheet_booking_id,
      ts_current.week_ending_date AS linked_timesheet_week_ending_date,
      ts_current.shift_label_norm AS linked_timesheet_shift_label_norm,
      ts_current.reference_number AS linked_timesheet_reference_number,
      ps.source_ref,
      ps.segment_id,
      ps.segment_stable_key,
      ps.expense_code,
      ps.expense_source_basis_fingerprint,
      ps.timesheet_id AS original_timesheet_id,
      ts_current.timesheet_id AS current_timesheet_id,
      ps.snooze_kind,
      CASE
        WHEN ps.snooze_until_date IS NULL THEN 'INDEFINITE'
        ELSE 'DATED'
      END AS snooze_mode,
      ps.snooze_until_date,
      ps.note,
      ps.created_at_utc,
      coalesce(nullif(btrim(coalesce(u_created.display_name, u_created.email, '')), ''), 'CloudTMS server') AS created_by_display,
      ps.updated_at_utc,
      coalesce(nullif(btrim(coalesce(u_updated.display_name, u_updated.email, '')), ''), NULL) AS updated_by_display,
      ps.cleared_at_utc,
      coalesce(nullif(btrim(coalesce(u_cleared.display_name, u_cleared.email, '')), ''), NULL) AS cleared_by_display,
      coalesce(nullif(btrim(coalesce(u_cancelled.display_name, u_cancelled.email, '')), ''), NULL) AS cancelled_by_display,
      CASE
        WHEN ps.cancelled_at_utc IS NOT NULL THEN 'HISTORY'
        WHEN ps.cleared_at_utc IS NOT NULL THEN 'HISTORY'
        WHEN ps.snooze_until_date IS NOT NULL AND ps.snooze_until_date < v_today_uk THEN 'HISTORY'
        WHEN ps.snooze_until_date IS NULL THEN 'INDEFINITE_DEFERRED'
        ELSE 'ACTIVE'
      END AS current_visibility_status,
      CASE
        WHEN ps.cancelled_at_utc IS NOT NULL THEN 'CANCELLED'
        WHEN ps.cleared_at_utc IS NOT NULL THEN 'CLEARED'
        WHEN ps.snooze_until_date IS NOT NULL AND ps.snooze_until_date < v_today_uk THEN 'EXPIRED'
        ELSE 'ACTIVE'
      END AS snooze_lifecycle_status,
      ps.cancelled_at_utc,
      ps.cancel_reason,
      CASE
        WHEN ps.finance_case_id IS NOT NULL THEN
          CASE
            WHEN vfcr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' THEN
              CASE
                WHEN upper(coalesce(vfcr.payout_status::text, '')) = 'PAID' THEN 'FULLY_PAID'
                WHEN upper(coalesce(vfcr.payout_status::text, '')) = 'CANCELLED' THEN 'CANCELLED'
                ELSE 'OUTSTANDING'
              END
            ELSE
              CASE
                WHEN vfcr.written_off_at_utc IS NOT NULL THEN 'WRITTEN_OFF'
                WHEN round(coalesce(vfcr.outstanding_amount, 0), 2) > 0 THEN 'OUTSTANDING'
                ELSE 'FULLY_PAID'
              END
          END
        ELSE
          CASE
            WHEN ps.cancelled_at_utc IS NOT NULL
              OR ps.cleared_at_utc IS NOT NULL
              OR (ps.snooze_until_date IS NOT NULL AND ps.snooze_until_date < v_today_uk)
            THEN 'FULLY_PAID'
            ELSE 'OUTSTANDING'
          END
      END AS linked_case_status,
      round(coalesce(vfcr.original_amount, 0), 2) AS original_amount,
      round(coalesce(vfcr.outstanding_amount, 0), 2) AS outstanding_amount,
      round(coalesce(vfcr.weekly_due, 0), 2) AS weekly_due,
      vfcr.weeks_total,
      vfcr.start_week_start,
      vfcr.next_due_week_start,
      vfcr.schedule_json,
      vfcr.adjustment_comment,
      CASE
        WHEN ps.finance_case_id IS NULL THEN NULL::text
        WHEN coalesce(vfcr.is_mixed_case, false) THEN 'MIXED_CASE'
        WHEN coalesce(vfcr.open_taxable_count, 0) > 0 AND coalesce(vfcr.open_reimbursement_count, 0) = 0 THEN 'TAXABLE_RECOVERY'
        WHEN coalesce(vfcr.open_reimbursement_count, 0) > 0 AND coalesce(vfcr.open_taxable_count, 0) = 0 THEN 'REIMBURSEMENT_CARRY_FORWARD'
        ELSE 'UNCLASSIFIED'
      END AS snooze_component_scope,
      CASE
        WHEN ps.finance_case_id IS NULL THEN NULL::text
        WHEN coalesce(vfcr.is_mixed_case, false) THEN 'Mixed Case'
        WHEN coalesce(vfcr.open_taxable_count, 0) > 0 AND coalesce(vfcr.open_reimbursement_count, 0) = 0 THEN 'Taxable Recovery'
        WHEN coalesce(vfcr.open_reimbursement_count, 0) > 0 AND coalesce(vfcr.open_taxable_count, 0) = 0 THEN 'Reimbursement Carry-forward'
        ELSE 'Unclassified'
      END AS snooze_component_scope_label,
      coalesce(vfcr.is_mixed_case, false) AS is_mixed_case,
      coalesce(vfcr.open_taxable_count, 0) AS open_taxable_count,
      coalesce(vfcr.open_reimbursement_count, 0) AS open_reimbursement_count,
      coalesce(vfcr.unresolved_taxable_count, 0) AS unresolved_taxable_count,
      coalesce(vfcr.stale_count, 0) AS stale_count,
      (coalesce(vfcr.unresolved_taxable_count, 0) > 0) AS has_unresolved_taxable_components,
      (coalesce(vfcr.stale_count, 0) > 0) AS has_stale_components,
      coalesce(vfcr.component_resolution_summary_json, '{}'::jsonb) AS component_resolution_summary_json
    FROM parsed_snoozes AS ps
    LEFT JOIN public.v_finance_cases_register AS vfcr
      ON vfcr.finance_case_id = ps.finance_case_id
    LEFT JOIN public.timesheets AS ts_stored
      ON ts_stored.timesheet_id = ps.timesheet_id
    LEFT JOIN public.timesheets AS ts_current
      ON ts_current.booking_id = coalesce(ps.booking_id, ts_stored.booking_id)
     AND ts_current.is_current IS TRUE
    LEFT JOIN public.v_timesheets_summary AS vts
      ON vts.timesheet_id = coalesce(ts_current.timesheet_id, ps.timesheet_id)
    LEFT JOIN public.candidates_summary AS cs
      ON cs.id = coalesce(vfcr.candidate_id, vts.candidate_id, ps.snooze_candidate_id)
    LEFT JOIN public.tms_users AS u_created
      ON u_created.id = ps.created_by_user_id
    LEFT JOIN public.tms_users AS u_updated
      ON u_updated.id = ps.updated_by_user_id
    LEFT JOIN public.tms_users AS u_cleared
      ON u_cleared.id = ps.cleared_by_user_id
    LEFT JOIN public.tms_users AS u_cancelled
      ON u_cancelled.id = ps.cancelled_by_user_id
    WHERE
      (p_candidate_id IS NULL OR coalesce(vfcr.candidate_id, vts.candidate_id, ps.snooze_candidate_id) = p_candidate_id)
      AND (p_client_id IS NULL OR coalesce(vfcr.client_id, vts.client_id) = p_client_id)
      AND (v_case_type IS NULL OR upper(coalesce(vfcr.case_type::text, '')) = v_case_type)
  ),
  filtered_rows AS (
    SELECT
      br.*
    FROM base_rows AS br
    WHERE
      v_status = 'ALL'
      OR (
        v_status = 'OUTSTANDING'
        AND (
          (
            br.snooze_scope = 'FINANCE_CASE'
            AND br.linked_case_status = 'OUTSTANDING'
          )
          OR (
            br.snooze_scope <> 'FINANCE_CASE'
            AND br.snooze_lifecycle_status = 'ACTIVE'
          )
        )
      )
      OR (
        v_status = 'FULLY_PAID'
        AND (
          (
            br.snooze_scope = 'FINANCE_CASE'
            AND br.linked_case_status = 'FULLY_PAID'
          )
          OR (
            br.snooze_scope <> 'FINANCE_CASE'
            AND br.snooze_lifecycle_status IN ('CLEARED', 'EXPIRED', 'CANCELLED')
          )
        )
      )
  ),
  ordered_rows AS (
    SELECT
      fr.*
    FROM filtered_rows AS fr
    ORDER BY
      CASE WHEN v_sort_key = 'created_at' AND v_sort_dir = 'asc' THEN fr.created_at_utc END ASC NULLS LAST,
      CASE WHEN v_sort_key = 'created_at' AND v_sort_dir = 'desc' THEN fr.created_at_utc END DESC NULLS LAST,

      CASE WHEN v_sort_key = 'updated_at' AND v_sort_dir = 'asc' THEN fr.updated_at_utc END ASC NULLS LAST,
      CASE WHEN v_sort_key = 'updated_at' AND v_sort_dir = 'desc' THEN fr.updated_at_utc END DESC NULLS LAST,

      CASE WHEN v_sort_key = 'candidate' AND v_sort_dir = 'asc' THEN lower(coalesce(fr.candidate_display_name, '')) END ASC NULLS LAST,
      CASE WHEN v_sort_key = 'candidate' AND v_sort_dir = 'desc' THEN lower(coalesce(fr.candidate_display_name, '')) END DESC NULLS LAST,

      CASE WHEN v_sort_key = 'client' AND v_sort_dir = 'asc' THEN lower(coalesce(fr.client_name, '')) END ASC NULLS LAST,
      CASE WHEN v_sort_key = 'client' AND v_sort_dir = 'desc' THEN lower(coalesce(fr.client_name, '')) END DESC NULLS LAST,

      CASE WHEN v_sort_key = 'snooze_until_date' AND v_sort_dir = 'asc' THEN fr.snooze_until_date END ASC NULLS LAST,
      CASE WHEN v_sort_key = 'snooze_until_date' AND v_sort_dir = 'desc' THEN fr.snooze_until_date END DESC NULLS LAST,

      fr.created_at_utc DESC,
      lower(coalesce(fr.candidate_display_name, '')) ASC
  )
  SELECT
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'snooze_id', orw.snooze_id::text,
          'snooze_scope', orw.snooze_scope,
          'row_label', orw.row_label,
          'source_ref', orw.source_ref,
          'expense_code', orw.expense_code,
          'expense_source_basis_fingerprint', orw.expense_source_basis_fingerprint,
          'original_timesheet_id', CASE WHEN orw.original_timesheet_id IS NULL THEN NULL ELSE orw.original_timesheet_id::text END,
          'current_timesheet_id', CASE WHEN orw.current_timesheet_id IS NULL THEN NULL ELSE orw.current_timesheet_id::text END,
          'segment_id', orw.segment_id,
          'segment_stable_key', orw.segment_stable_key,
          'case_type', orw.case_type,
          'candidate_tms_ref', orw.candidate_tms_ref,
          'candidate_tms_ref_num', orw.candidate_tms_ref_num,
          'candidate_first_name', orw.candidate_first_name,
          'candidate_last_name', orw.candidate_last_name,
          'candidate_display_name', orw.candidate_display_name,
          'client_name', orw.client_name,
          'linked_timesheet_booking_id', orw.linked_timesheet_booking_id,
          'linked_timesheet_week_ending_date', CASE WHEN orw.linked_timesheet_week_ending_date IS NULL THEN NULL ELSE orw.linked_timesheet_week_ending_date::text END,
          'linked_timesheet_shift_label_norm', orw.linked_timesheet_shift_label_norm,
          'linked_timesheet_reference_number', orw.linked_timesheet_reference_number,
          'snooze_kind', orw.snooze_kind,
          'snooze_mode', orw.snooze_mode,
          'snooze_until_date', CASE WHEN orw.snooze_until_date IS NULL THEN NULL ELSE orw.snooze_until_date::text END,
          'note', orw.note,
          'created_at_utc', CASE WHEN orw.created_at_utc IS NULL THEN NULL ELSE orw.created_at_utc::text END,
          'created_by_display', orw.created_by_display,
          'updated_at_utc', CASE WHEN orw.updated_at_utc IS NULL THEN NULL ELSE orw.updated_at_utc::text END,
          'updated_by_display', orw.updated_by_display,
          'cleared_at_utc', CASE WHEN orw.cleared_at_utc IS NULL THEN NULL ELSE orw.cleared_at_utc::text END,
          'cleared_by_display', orw.cleared_by_display,
          'cancelled_at_utc', CASE WHEN orw.cancelled_at_utc IS NULL THEN NULL ELSE orw.cancelled_at_utc::text END,
          'cancelled_by_display', orw.cancelled_by_display,
          'cancel_reason', orw.cancel_reason,
          'current_visibility_status', orw.current_visibility_status,
          'snooze_lifecycle_status', orw.snooze_lifecycle_status,
          'linked_case_status', orw.linked_case_status
        )
        || jsonb_build_object(
          'original_amount', orw.original_amount,
          'outstanding_amount', orw.outstanding_amount,
          'weekly_due', orw.weekly_due,
          'weeks_total', orw.weeks_total,
          'start_week_start', CASE WHEN orw.start_week_start IS NULL THEN NULL ELSE orw.start_week_start::text END,
          'next_due_week_start', CASE WHEN orw.next_due_week_start IS NULL THEN NULL ELSE orw.next_due_week_start::text END,
          'schedule_json', coalesce(orw.schedule_json, '[]'::jsonb),
          'adjustment_comment', orw.adjustment_comment,
          'snooze_component_scope', orw.snooze_component_scope,
          'snooze_component_scope_label', orw.snooze_component_scope_label,
          'is_mixed_case', orw.is_mixed_case,
          'open_taxable_count', orw.open_taxable_count,
          'open_reimbursement_count', orw.open_reimbursement_count,
          'unresolved_taxable_count', orw.unresolved_taxable_count,
          'stale_count', orw.stale_count,
          'has_unresolved_taxable_components', orw.has_unresolved_taxable_components,
          'has_stale_components', orw.has_stale_components,
          'component_resolution_summary_json', orw.component_resolution_summary_json
        )
      ),
      '[]'::jsonb
    ),
    jsonb_build_object(
      'total_count', count(*)::int,
      'finance_case_snooze_count', count(*) FILTER (WHERE orw.snooze_scope = 'FINANCE_CASE')::int,
      'timesheet_expense_snooze_count', count(*) FILTER (WHERE orw.snooze_scope = 'TIMESHEET_EXPENSE')::int,
      'timesheet_payment_snooze_count', count(*) FILTER (WHERE orw.snooze_scope = 'TIMESHEET_PAYMENT')::int,
      'active_count', count(*) FILTER (WHERE orw.snooze_lifecycle_status = 'ACTIVE')::int,
      'cleared_count', count(*) FILTER (WHERE orw.snooze_lifecycle_status = 'CLEARED')::int,
      'expired_count', count(*) FILTER (WHERE orw.snooze_lifecycle_status = 'EXPIRED')::int,
      'cancelled_count', count(*) FILTER (WHERE orw.snooze_lifecycle_status = 'CANCELLED')::int,
      'history_count', count(*) FILTER (WHERE orw.snooze_lifecycle_status IN ('CLEARED', 'EXPIRED', 'CANCELLED'))::int,
      'indefinite_count', count(*) FILTER (WHERE orw.snooze_mode = 'INDEFINITE')::int,
      'dated_count', count(*) FILTER (WHERE orw.snooze_mode = 'DATED')::int,
      'taxable_recovery_count', count(*) FILTER (WHERE orw.snooze_component_scope = 'TAXABLE_RECOVERY')::int,
      'reimbursement_carry_forward_count', count(*) FILTER (WHERE orw.snooze_component_scope = 'REIMBURSEMENT_CARRY_FORWARD')::int,
      'mixed_case_count', count(*) FILTER (WHERE orw.snooze_component_scope = 'MIXED_CASE')::int,
      'unresolved_case_count', count(*) FILTER (WHERE coalesce(orw.unresolved_taxable_count, 0) > 0)::int,
      'stale_case_count', count(*) FILTER (WHERE coalesce(orw.stale_count, 0) > 0)::int
    )
  INTO v_rows, v_summary
  FROM ordered_rows AS orw;

  v_meta := jsonb_build_object(
    'title', 'Snoozes Report',
    'orientation', 'LANDSCAPE',
    'generated_at_utc', now()::text,
    'london_current_date', v_today_uk::text,
    'applied_filters', jsonb_build_object(
      'created_from', CASE WHEN p_created_from IS NULL THEN NULL ELSE p_created_from::text END,
      'created_to', CASE WHEN p_created_to IS NULL THEN NULL ELSE p_created_to::text END,
      'status', v_status,
      'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'client_id', CASE WHEN p_client_id IS NULL THEN NULL ELSE p_client_id::text END,
      'case_type', v_case_type,
      'sort_key', v_sort_key,
      'sort_dir', v_sort_dir
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'title', 'Snoozes Report',
    'generated_at_utc', now()::text,
    'summary', coalesce(v_summary, '{}'::jsonb),
    'meta', v_meta,
    'rows', coalesce(v_rows, '[]'::jsonb)
  );
END;
$function$;

-- pay_snoozes_list(uuid,boolean,integer,integer,uuid)
CREATE OR REPLACE FUNCTION public.pay_snoozes_list(p_candidate_id uuid DEFAULT NULL::uuid, p_active_only boolean DEFAULT true, p_limit integer DEFAULT 200, p_offset integer DEFAULT 0, p_client_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_limit int := greatest(1, least(coalesce(p_limit,200), 500));
  v_offset int := greatest(coalesce(p_offset,0), 0);
  v_total int := 0;
  v_rows jsonb := '[]'::jsonb;
BEGIN
  WITH base AS (
    SELECT
      s.id,
      s.candidate_id,
      s.timesheet_id,
      s.segment_id,
      s.source_ref,
      upper(COALESCE(s.snooze_kind,'')) AS snooze_kind,
      s.snooze_until_date,
      s.note,
      s.created_at_utc,
      s.created_by_user_id,
      s.updated_at_utc,
      s.updated_by_user_id,
      s.cleared_at_utc,
      s.cleared_by_user_id,
      CASE
        WHEN s.source_ref IS NOT NULL
         AND s.source_ref LIKE 'advance:%'
         AND split_part(s.source_ref, ':', 2) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        THEN split_part(s.source_ref, ':', 2)::uuid
        ELSE NULL
      END AS finance_case_id
    FROM public.pay_item_snoozes s
    WHERE (p_candidate_id IS NULL OR s.candidate_id = p_candidate_id)
      AND (coalesce(p_active_only,true) = false OR s.cleared_at_utc IS NULL)
  ),
  enriched AS (
    SELECT
      b.id,
      b.candidate_id,
      c.tms_ref AS candidate_tms_ref,
      c.display_name AS candidate_display_name,
      b.timesheet_id,
      ts.week_ending_date,
      tf.client_id AS timesheet_client_id,
      cli_tf.name AS timesheet_client_name,
      b.segment_id,
      b.source_ref,
      b.finance_case_id,
      vfc.case_type,
      vfc.client_id AS finance_client_id,
      vfc.client_name AS finance_client_name,
      vfc.linked_shift_date,
      vfc.adjustment_comment,
      vfc.status AS finance_case_status,
      vfc.payout_status AS finance_case_payout_status,
      vfc.outstanding_amount,
      vfc.active_snooze_until_date,
      b.snooze_kind,
      b.snooze_until_date,
      b.note,
      b.created_at_utc,
      b.created_by_user_id,
      b.updated_at_utc,
      b.updated_by_user_id,
      b.cleared_at_utc,
      b.cleared_by_user_id,
      CASE
        WHEN b.finance_case_id IS NOT NULL THEN
          CASE vfc.case_type
            WHEN 'PAYMENT_ADVANCE' THEN 'PAYMENT_ADVANCE_REPAYMENT'
            WHEN 'OVERPAYMENT' THEN 'OVERPAYMENT_RECOVERY'
            WHEN 'MANUAL_DEBT_ADJUSTMENT' THEN 'MANUAL_DEBT_RECOVERY'
            WHEN 'MANUAL_CREDIT_ADJUSTMENT' THEN 'MANUAL_CREDIT_ADJUSTMENT'
            ELSE 'FINANCE_CASE'
          END
        WHEN b.snooze_kind = 'TIMESHEET_PAYMENT' THEN 'TIMESHEET_PAYMENT'
        WHEN b.snooze_kind = 'BLOCKED_TIMESHEET' THEN 'BLOCKED_TIMESHEET'
        WHEN b.snooze_kind = 'DO_NOT_PAY' THEN 'DO_NOT_PAY'
        ELSE 'SNOOZE'
      END AS line_type,
      CASE
        WHEN b.finance_case_id IS NOT NULL THEN
          CASE vfc.case_type
            WHEN 'PAYMENT_ADVANCE' THEN 'Payment Advance Repayment'
            WHEN 'OVERPAYMENT' THEN 'Overpayment Recovery'
            WHEN 'MANUAL_DEBT_ADJUSTMENT' THEN 'Manual Debt Adjustment Recovery'
            WHEN 'MANUAL_CREDIT_ADJUSTMENT' THEN 'Manual Credit Adjustment'
            ELSE 'Finance item'
          END
        WHEN b.snooze_kind = 'TIMESHEET_PAYMENT' THEN 'Timesheet payment'
        WHEN b.snooze_kind = 'BLOCKED_TIMESHEET' THEN 'Blocked timesheet line'
        WHEN b.snooze_kind = 'DO_NOT_PAY' THEN 'Do not pay line'
        ELSE 'Snoozed item'
      END AS line_label,
      CASE
        WHEN b.finance_case_id IS NOT NULL THEN
          trim(
            both ' '
            from concat(
              CASE vfc.case_type
                WHEN 'PAYMENT_ADVANCE' THEN 'Payment Advance Repayment'
                WHEN 'OVERPAYMENT' THEN 'Overpayment Recovery'
                WHEN 'MANUAL_DEBT_ADJUSTMENT' THEN 'Manual Debt Adjustment Recovery'
                WHEN 'MANUAL_CREDIT_ADJUSTMENT' THEN 'Manual Credit Adjustment'
                ELSE 'Finance item'
              END,
              CASE
                WHEN nullif(btrim(coalesce(vfc.adjustment_comment,'')), '') IS NOT NULL
                  THEN ' - ' || nullif(btrim(coalesce(vfc.adjustment_comment,'')), '')
                ELSE ''
              END
            )
          )
        WHEN b.snooze_kind = 'TIMESHEET_PAYMENT' THEN 'Timesheet payment'
        WHEN b.snooze_kind = 'BLOCKED_TIMESHEET' THEN
          CASE
            WHEN nullif(btrim(coalesce(b.segment_id,'')), '') IS NOT NULL THEN 'Blocked timesheet line - ' || b.segment_id
            ELSE 'Blocked timesheet line'
          END
        WHEN b.snooze_kind = 'DO_NOT_PAY' THEN
          CASE
            WHEN nullif(btrim(coalesce(b.segment_id,'')), '') IS NOT NULL THEN 'Do not pay line - ' || b.segment_id
            ELSE 'Do not pay line'
          END
        ELSE 'Snoozed item'
      END AS line_description,
      (b.snooze_until_date IS NULL) AS snooze_is_indefinite,
      (
        b.cleared_at_utc IS NULL
        AND (b.snooze_until_date IS NULL OR b.snooze_until_date >= current_date)
      ) AS is_currently_effective,
      CASE
        WHEN b.cleared_at_utc IS NOT NULL THEN 'CLEARED_HISTORY'
        WHEN b.snooze_until_date IS NULL THEN 'LOANS_SNOOZES_ONLY'
        WHEN b.snooze_until_date >= current_date THEN 'PREVIEW_VISIBLE_EXCLUDED'
        ELSE 'PREVIEW_ELIGIBLE'
      END AS visibility_hint
    FROM base b
    JOIN public.candidates c
      ON c.id = b.candidate_id
    LEFT JOIN public.timesheets ts
      ON ts.timesheet_id = b.timesheet_id
    LEFT JOIN public.timesheets_financials tf
      ON tf.timesheet_id = b.timesheet_id
     AND tf.is_current = true
    LEFT JOIN public.clients cli_tf
      ON cli_tf.id = tf.client_id
    LEFT JOIN public.v_finance_cases_register vfc
      ON vfc.finance_case_id = b.finance_case_id
  )
  SELECT count(*)::int
  INTO v_total
  FROM enriched e
  WHERE (p_client_id IS NULL OR COALESCE(e.finance_client_id, e.timesheet_client_id) = p_client_id);

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', e.id::text,
        'candidate_id', e.candidate_id::text,
        'candidate_tms_ref', e.candidate_tms_ref,
        'candidate_display_name', e.candidate_display_name,
        'client_id', CASE WHEN COALESCE(e.finance_client_id, e.timesheet_client_id) IS NULL THEN NULL ELSE COALESCE(e.finance_client_id, e.timesheet_client_id)::text END,
        'client_name', COALESCE(e.finance_client_name, e.timesheet_client_name),
        'timesheet_id', CASE WHEN e.timesheet_id IS NULL THEN NULL ELSE e.timesheet_id::text END,
        'week_ending_date', CASE WHEN e.week_ending_date IS NULL THEN NULL ELSE e.week_ending_date::text END,
        'linked_shift_date', CASE WHEN e.linked_shift_date IS NULL THEN NULL ELSE e.linked_shift_date::text END,
        'segment_id', e.segment_id,
        'source_ref', e.source_ref,
        'finance_case_id', CASE WHEN e.finance_case_id IS NULL THEN NULL ELSE e.finance_case_id::text END,
        'case_type', e.case_type,
        'finance_case_status', e.finance_case_status,
        'finance_case_payout_status', e.finance_case_payout_status,
        'finance_case_outstanding_amount', e.outstanding_amount,
        'adjustment_comment', e.adjustment_comment,
        'line_type', e.line_type,
        'line_label', e.line_label,
        'line_description', e.line_description,
        'snooze_kind', e.snooze_kind,
        'snooze_until_date', CASE WHEN e.snooze_until_date IS NULL THEN NULL ELSE e.snooze_until_date::text END,
        'snooze_is_indefinite', e.snooze_is_indefinite,
        'is_currently_effective', e.is_currently_effective,
        'visibility_hint', e.visibility_hint,
        'note', e.note,
        'created_at_utc', e.created_at_utc,
        'created_by_user_id', CASE WHEN e.created_by_user_id IS NULL THEN NULL ELSE e.created_by_user_id::text END,
        'updated_at_utc', e.updated_at_utc,
        'updated_by_user_id', CASE WHEN e.updated_by_user_id IS NULL THEN NULL ELSE e.updated_by_user_id::text END,
        'cleared_at_utc', e.cleared_at_utc,
        'cleared_by_user_id', CASE WHEN e.cleared_by_user_id IS NULL THEN NULL ELSE e.cleared_by_user_id::text END,
        'action_flags', jsonb_build_object(
          'can_clear', e.cleared_at_utc IS NULL,
          'can_amend_date', e.cleared_at_utc IS NULL,
          'can_set_indefinite', e.cleared_at_utc IS NULL AND e.snooze_until_date IS NOT NULL,
          'can_set_dated', e.cleared_at_utc IS NULL AND e.snooze_until_date IS NULL
        )
      )
      ORDER BY e.created_at_utc DESC, e.id DESC
    ),
    '[]'::jsonb
  )
  INTO v_rows
  FROM (
    SELECT e.*
    FROM enriched e
    WHERE (p_client_id IS NULL OR COALESCE(e.finance_client_id, e.timesheet_client_id) = p_client_id)
    ORDER BY e.created_at_utc DESC, e.id DESC
    LIMIT v_limit OFFSET v_offset
  ) e;

  RETURN jsonb_build_object(
    'ok', true,
    'total_count', v_total,
    'limit', v_limit,
    'offset', v_offset,
    'rows', v_rows
  );
END;
$function$;

-- pay_snoozes_list(uuid,boolean,integer,integer)
CREATE OR REPLACE FUNCTION public.pay_snoozes_list(p_candidate_id uuid DEFAULT NULL::uuid, p_active_only boolean DEFAULT true, p_limit integer DEFAULT 200, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_limit int := greatest(1, least(coalesce(p_limit,200), 500));
  v_offset int := greatest(coalesce(p_offset,0), 0);
  v_total int := 0;
  v_rows jsonb := '[]'::jsonb;
begin
  select count(*)::int
  into v_total
  from public.pay_item_snoozes s
  where (p_candidate_id is null or s.candidate_id = p_candidate_id)
    and (coalesce(p_active_only,true) = false or s.cleared_at_utc is null);

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', s.id::text,
        'candidate_id', s.candidate_id::text,
        'timesheet_id', case when s.timesheet_id is null then null else s.timesheet_id::text end,
        'segment_id', s.segment_id,
        'source_ref', s.source_ref,
        'snooze_kind', s.snooze_kind,
        'snooze_until_date', case when s.snooze_until_date is null then null else s.snooze_until_date::text end,
        'note', s.note,
        'created_at_utc', s.created_at_utc,
        'created_by_user_id', case when s.created_by_user_id is null then null else s.created_by_user_id::text end,
        'cleared_at_utc', s.cleared_at_utc,
        'cleared_by_user_id', case when s.cleared_by_user_id is null then null else s.cleared_by_user_id::text end
      )
      order by s.created_at_utc desc, s.id desc
    ),
    '[]'::jsonb
  )
  into v_rows
  from (
    select s.*
    from public.pay_item_snoozes s
    where (p_candidate_id is null or s.candidate_id = p_candidate_id)
      and (coalesce(p_active_only,true) = false or s.cleared_at_utc is null)
    order by s.created_at_utc desc, s.id desc
    limit v_limit offset v_offset
  ) s;

  return jsonb_build_object(
    'ok', true,
    'total_count', v_total,
    'limit', v_limit,
    'offset', v_offset,
    'rows', v_rows
  );
end;
$function$;

-- pay_snoozes_pdf_payload(uuid,date,date,text,uuid,uuid,text,text,text)
CREATE OR REPLACE FUNCTION public.pay_snoozes_pdf_payload(p_actor_user_id uuid DEFAULT NULL::uuid, p_created_from date DEFAULT NULL::date, p_created_to date DEFAULT NULL::date, p_status text DEFAULT 'ALL'::text, p_candidate_id uuid DEFAULT NULL::uuid, p_client_id uuid DEFAULT NULL::uuid, p_case_type text DEFAULT NULL::text, p_sort_key text DEFAULT 'created_at'::text, p_sort_dir text DEFAULT 'desc'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_base jsonb := '{}'::jsonb;
  v_rows jsonb := '[]'::jsonb;
  v_groups jsonb := '[]'::jsonb;
BEGIN
  v_base := public.pay_snoozes_export_rows(
    p_actor_user_id => p_actor_user_id,
    p_created_from => p_created_from,
    p_created_to => p_created_to,
    p_status => p_status,
    p_candidate_id => p_candidate_id,
    p_client_id => p_client_id,
    p_case_type => p_case_type,
    p_sort_key => p_sort_key,
    p_sort_dir => p_sort_dir
  );

  v_rows := coalesce(v_base->'rows', '[]'::jsonb);

  SELECT jsonb_build_array(
    jsonb_build_object(
      'row_group', 'FINANCE_CASE',
      'title', 'Finance-case Snoozes',
      'rows', coalesce(
        (
          SELECT jsonb_agg(e.elem)
          FROM jsonb_array_elements(v_rows) AS e(elem)
          WHERE e.elem->>'snooze_scope' = 'FINANCE_CASE'
        ),
        '[]'::jsonb
      )
    ),
    jsonb_build_object(
      'row_group', 'TIMESHEET_EXPENSE',
      'title', 'Timesheet-expense Snoozes',
      'rows', coalesce(
        (
          SELECT jsonb_agg(e.elem)
          FROM jsonb_array_elements(v_rows) AS e(elem)
          WHERE e.elem->>'snooze_scope' = 'TIMESHEET_EXPENSE'
        ),
        '[]'::jsonb
      )
    ),
    jsonb_build_object(
      'row_group', 'TIMESHEET_PAYMENT',
      'title', 'Timesheet-payment Snoozes',
      'rows', coalesce(
        (
          SELECT jsonb_agg(e.elem)
          FROM jsonb_array_elements(v_rows) AS e(elem)
          WHERE e.elem->>'snooze_scope' = 'TIMESHEET_PAYMENT'
        ),
        '[]'::jsonb
      )
    )
  )
  INTO v_groups;

  RETURN jsonb_build_object(
    'ok', true,
    'title', 'Snoozes Report',
    'orientation', 'LANDSCAPE',
    'generated_at_utc', now()::text,
    'summary', coalesce(v_base->'summary', '{}'::jsonb),
    'meta', coalesce(v_base->'meta', '{}'::jsonb),
    'groups', coalesce(v_groups, '[]'::jsonb),
    'rows', coalesce(v_rows, '[]'::jsonb)
  );
END;
$function$;

-- pay_sync_overpayments_from_preview(date,date,uuid,text,uuid[],jsonb,uuid,uuid[],uuid[])
CREATE OR REPLACE FUNCTION public.pay_sync_overpayments_from_preview(p_pay_date date, p_week_ending_cutoff date, p_actor_user_id uuid, p_pay_channel_scope text, p_candidate_ids uuid[], p_mismatch_choices jsonb DEFAULT '{}'::jsonb, p_client_filter_single uuid DEFAULT NULL::uuid, p_force_include_timesheet_ids uuid[] DEFAULT NULL::uuid[], p_exclude_timesheet_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "plpgsql_check.mode" TO 'disabled'
AS $function$
DECLARE
  v_context regclass:=pg_catalog.to_regclass('pg_temp._bpay_wb_sync_context_v1');
  v_owner oid;
  v_context_count integer;
  v_job_id uuid;
  v_build_id uuid;
  v_attempt_id uuid;
  v_attempt_nonce uuid;
  v_result jsonb;
BEGIN
  IF v_context IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_BUILD_REQUIRED' USING ERRCODE='42501';
  END IF;
  SELECT relowner INTO v_owner FROM pg_catalog.pg_class WHERE oid=v_context;
  IF v_owner IS DISTINCT FROM current_user::regrole::oid THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_BUILD_REQUIRED' USING ERRCODE='42501';
  END IF;
  SELECT count(*) INTO v_context_count FROM pg_catalog.pg_attribute
  WHERE attrelid=v_context AND attnum>0 AND NOT attisdropped;
  IF v_context_count<>10 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_BUILD_REQUIRED' USING ERRCODE='42501';
  END IF;

  SELECT context.job_id,context.build_id,context.attempt_id,context.attempt_nonce
  INTO v_job_id,v_build_id,v_attempt_id,v_attempt_nonce
  FROM pg_temp._bpay_wb_sync_context_v1 AS context;
  IF NOT FOUND OR EXISTS(SELECT 1 FROM pg_temp._bpay_wb_sync_context_v1 OFFSET 1) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_BUILD_REQUIRED' USING ERRCODE='42501';
  END IF;

  v_result:=private.pay_sync_overpayments_from_workbench_workspace_v1(
    v_build_id,v_job_id,v_attempt_id,v_attempt_nonce,
    p_pay_date,p_week_ending_cutoff,p_actor_user_id,p_pay_channel_scope,
    p_candidate_ids,p_mismatch_choices,p_client_filter_single,
    p_force_include_timesheet_ids,p_exclude_timesheet_ids
  );
  IF jsonb_typeof(v_result)<>'object' OR jsonb_typeof(v_result->'public_result_json')<>'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_RESULT_INVALID' USING ERRCODE='22023';
  END IF;
  RETURN v_result->'public_result_json';
END;
$function$;

-- pay_timesheet_impact_preview(uuid)
CREATE OR REPLACE FUNCTION public.pay_timesheet_impact_preview(p_timesheet_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tf record;
  v_ts record;

  v_require_ref boolean;

  v_base jsonb;
  v_base_segments jsonb;
  v_cur_segments jsonb;

  v_segment_ids text[];
  v_seg_id text;

  v_cur_pay numeric;
  v_cur_excl boolean;
  v_cur_ref text;

  v_base_pay numeric;
  v_base_excl boolean;

  v_cur_payable numeric;
  v_base_payable numeric;

  v_seg_delta_raw numeric;
  v_seg_delta_payable numeric;

  v_seg_sum_raw numeric := 0;
  v_seg_sum_payable numeric := 0;

  v_base_add numeric := 0;
  v_cur_add numeric := 0;

  v_base_exp numeric := 0;
  v_cur_exp numeric := 0;

  v_base_adj numeric := 0;
  v_cur_adj numeric := 0;

  v_delta_raw numeric := 0;
  v_delta_payable numeric := 0;
begin
  if p_timesheet_id is null then
    raise exception 'timesheet_id is required';
  end if;

  select
    tf.timesheet_id,
    tf.client_id,
    tf.invoice_breakdown_json,
    tf.total_pay_ex_vat,
    tf.additional_pay_ex_vat,
    tf.expenses_pay_ex_vat,
    tf.travel_pay_ex_vat,
    tf.accommodation_pay_ex_vat,
    tf.other_pay_ex_vat,
    tf.mileage_pay_ex_vat
  into v_tf
  from public.timesheets_financials tf
  where tf.timesheet_id = p_timesheet_id
    and tf.is_current = true
  limit 1;

  if v_tf.timesheet_id is null then
    raise exception 'timesheet_financials not found for timesheet';
  end if;

  select
    ts.timesheet_id,
    ts.contract_id,
    ts.reference_number
  into v_ts
  from public.timesheets ts
  where ts.timesheet_id = p_timesheet_id
    and ts.is_current = true
  limit 1;

  select
    coalesce(
      case when ct.overrideclientsettings then ct.require_reference_to_pay end,
      cs.pay_reference_required,
      false
    )
  into v_require_ref
  from public.contracts ct
  left join public.client_settings cs on cs.client_id = v_tf.client_id
  where ct.id = v_ts.contract_id
  limit 1;

  select coalesce(tps.last_settled_snapshot_json, '{}'::jsonb)
  into v_base
  from public.timesheet_pay_state tps
  where tps.timesheet_id = p_timesheet_id
  limit 1;

  v_base_segments := coalesce(v_base->'segments','[]'::jsonb);

  -- current segments
  if v_tf.invoice_breakdown_json is not null
     and jsonb_typeof(v_tf.invoice_breakdown_json) = 'object'
     and upper(coalesce(v_tf.invoice_breakdown_json->>'mode','')) = 'SEGMENTS'
     and jsonb_typeof(v_tf.invoice_breakdown_json->'segments') = 'array' then
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'segment_id', nullif(btrim(coalesce(seg->>'segment_id','')), ''),
          'pay_amount', round(coalesce(nullif(seg->>'pay_amount','')::numeric,0),2),
          'exclude_from_pay', coalesce(nullif(seg->>'exclude_from_pay','')::boolean,false),
          'ref_num', nullif(btrim(coalesce(seg->>'ref_num','')), '')
        )
      ),
      '[]'::jsonb
    )
    into v_cur_segments
    from jsonb_array_elements(v_tf.invoice_breakdown_json->'segments') seg
    where seg is not null and jsonb_typeof(seg)='object';
  else
    v_cur_segments := jsonb_build_array(
      jsonb_build_object(
        'segment_id', ('ts:' || p_timesheet_id::text),
        'pay_amount', round(coalesce(v_tf.total_pay_ex_vat,0),2),
        'exclude_from_pay', false,
        'ref_num', nullif(btrim(coalesce(v_ts.reference_number,'')), '')
      )
    );
  end if;

  select coalesce(array_agg(distinct sid), array[]::text[])
  into v_segment_ids
  from (
    select nullif(btrim(coalesce(s->>'segment_id','')),'') as sid
    from jsonb_array_elements(v_cur_segments) s
    where s is not null and jsonb_typeof(s)='object'
    union
    select nullif(btrim(coalesce(s->>'segment_id','')),'') as sid
    from jsonb_array_elements(v_base_segments) s
    where s is not null and jsonb_typeof(s)='object'
  ) u
  where u.sid is not null;

  foreach v_seg_id in array v_segment_ids
  loop
    select
      round(coalesce(nullif(s->>'pay_amount','')::numeric,0),2) as pay_amount,
      coalesce(nullif(s->>'exclude_from_pay','')::boolean,false) as exclude_from_pay,
      nullif(btrim(coalesce(s->>'ref_num','')), '') as ref_num
    into v_cur_pay, v_cur_excl, v_cur_ref
    from jsonb_array_elements(v_cur_segments) s
    where nullif(btrim(coalesce(s->>'segment_id','')),'') = v_seg_id
    limit 1;

    if v_cur_pay is null then v_cur_pay := 0; end if;
    if v_cur_excl is null then v_cur_excl := false; end if;

    select
      round(coalesce(nullif(s->>'pay_amount','')::numeric,0),2) as pay_amount,
      coalesce(nullif(s->>'exclude_from_pay','')::boolean,false) as exclude_from_pay
    into v_base_pay, v_base_excl
    from jsonb_array_elements(v_base_segments) s
    where nullif(btrim(coalesce(s->>'segment_id','')),'') = v_seg_id
    limit 1;

    if v_base_pay is null then v_base_pay := 0; end if;
    if v_base_excl is null then v_base_excl := false; end if;

    v_cur_payable := case when v_cur_excl then 0 else v_cur_pay end;
    v_base_payable := case when v_base_excl then 0 else v_base_pay end;

    v_seg_delta_raw := round(v_cur_payable - v_base_payable, 2);

    v_seg_delta_payable := v_seg_delta_raw;
    if v_require_ref = true
       and v_cur_excl = false
       and nullif(btrim(coalesce(v_cur_ref,'')),'') is null
       and v_seg_delta_raw > 0 then
      v_seg_delta_payable := 0;
    end if;

    v_seg_sum_raw := round(v_seg_sum_raw + v_seg_delta_raw, 2);
    v_seg_sum_payable := round(v_seg_sum_payable + v_seg_delta_payable, 2);
  end loop;

  v_base_add := round(coalesce(nullif(v_base->>'additional_pay_ex_vat','')::numeric,0),2);
  v_cur_add := round(coalesce(v_tf.additional_pay_ex_vat,0),2);

  v_base_exp :=
    round(coalesce(nullif(v_base #>> '{expenses,expenses_pay_ex_vat}','')::numeric,0),2)
    + round(coalesce(nullif(v_base #>> '{expenses,travel_pay_ex_vat}','')::numeric,0),2)
    + round(coalesce(nullif(v_base #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0),2)
    + round(coalesce(nullif(v_base #>> '{expenses,other_pay_ex_vat}','')::numeric,0),2)
    + round(coalesce(nullif(v_base #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0),2);

  v_cur_exp :=
    round(coalesce(v_tf.expenses_pay_ex_vat,0),2)
    + round(coalesce(v_tf.travel_pay_ex_vat,0),2)
    + round(coalesce(v_tf.accommodation_pay_ex_vat,0),2)
    + round(coalesce(v_tf.other_pay_ex_vat,0),2)
    + round(coalesce(v_tf.mileage_pay_ex_vat,0),2);

  -- baseline adjustments sum
  select round(coalesce(sum(coalesce(nullif(a->>'delta_pay_ex_vat','')::numeric,0)),0),2)
  into v_base_adj
  from jsonb_array_elements(coalesce(v_base->'adjustments','[]'::jsonb)) a;

  -- current adjustments sum
  select round(coalesce(sum(coalesce(a.delta_pay_ex_vat,0)),0),2)
  into v_cur_adj
  from public.ts_pay_adjustments a
  where a.timesheet_id = p_timesheet_id
    and a.as_advance = false;

  v_delta_raw := round((v_seg_sum_raw + (v_cur_add - v_base_add) + (v_cur_exp - v_base_exp) + (v_cur_adj - v_base_adj)), 2);
  v_delta_payable := round((v_seg_sum_payable + (v_cur_add - v_base_add) + (v_cur_exp - v_base_exp) + (v_cur_adj - v_base_adj)), 2);

  return jsonb_build_object(
    'ok', true,
    'timesheet_id', p_timesheet_id::text,
    'require_reference_to_pay', v_require_ref,
    'baseline', jsonb_build_object(
      'segments_payable_ex_vat', round(coalesce(v_seg_sum_raw,0) - coalesce(v_seg_sum_raw - v_seg_sum_raw,0),2),
      'additional_pay_ex_vat', v_base_add,
      'expenses_total_pay_ex_vat', v_base_exp,
      'adjustments_total_ex_vat', v_base_adj
    ),
    'current', jsonb_build_object(
      'additional_pay_ex_vat', v_cur_add,
      'expenses_total_pay_ex_vat', v_cur_exp,
      'adjustments_total_ex_vat', v_cur_adj
    ),
    'delta', jsonb_build_object(
      'raw_delta_ex_vat', v_delta_raw,
      'payable_delta_ex_vat', v_delta_payable
    )
  );
end;
$function$;

-- pay_timesheet_summary_advance_state_refresh(uuid,uuid)
CREATE OR REPLACE FUNCTION public.pay_timesheet_summary_advance_state_refresh(p_timesheet_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_canonical_timesheet_id uuid := NULL;
  v_latest_override_created_at_utc timestamptz := NULL;
  v_existing_consumed_at_utc timestamptz := NULL;
  v_authorisation_event_at_utc timestamptz := NULL;
  v_new_consumed_at_utc timestamptz := NULL;
  v_active_advance boolean := false;
  v_cache public.timesheet_summary_pay_state_cache%ROWTYPE;
  v_new_badges text[] := ARRAY[]::text[];
  v_summary_state_applies boolean := false;
  v_cache_updated boolean := false;
BEGIN
  IF p_timesheet_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error_code', 'INVALID_PAYLOAD',
      'message', 'p_timesheet_id is required'
    );
  END IF;

  SELECT rs.canonical_timesheet_id
    INTO v_canonical_timesheet_id
  FROM public._pay_timesheet_rotation_scope(ARRAY[p_timesheet_id]) AS rs
  WHERE rs.canonical_timesheet_id IS NOT NULL
  ORDER BY COALESCE(rs.requested_is_canonical, false) DESC, rs.family_version DESC NULLS LAST, rs.canonical_timesheet_id
  LIMIT 1;

  IF v_canonical_timesheet_id IS NULL THEN
    v_canonical_timesheet_id := p_timesheet_id;
  END IF;

  SELECT payment_override.created_at_utc
    INTO v_latest_override_created_at_utc
  FROM public._pay_timesheet_rotation_scope(ARRAY[p_timesheet_id]) AS rs
  JOIN public.timesheet_payment_overrides AS payment_override
    ON payment_override.timesheet_id = rs.family_timesheet_id
  WHERE payment_override.cleared_at_utc IS NULL
    AND UPPER(BTRIM(COALESCE(payment_override.override_type, ''))) = 'ADVANCE_THIS_PAYMENT'
  ORDER BY payment_override.created_at_utc DESC, payment_override.id DESC
  LIMIT 1;

  IF v_latest_override_created_at_utc IS NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'NO_ACTIVE_ADVANCE_THIS_PAYMENT_OVERRIDE',
      'timesheet_id', v_canonical_timesheet_id,
      'cache_updated', false
    );
  END IF;

  SELECT MAX(existing_cache.advance_authorisation_consumed_at_utc)
    INTO v_existing_consumed_at_utc
  FROM public._pay_timesheet_rotation_scope(ARRAY[p_timesheet_id]) AS rs
  LEFT JOIN public.timesheet_summary_pay_state_cache AS existing_cache
    ON existing_cache.timesheet_id = rs.family_timesheet_id;

  SELECT GREATEST(
           MAX(family_timesheet.authorised_at_server),
           MAX(family_timesheet.revoked_at),
           MAX(family_financial.authorised_at_utc)
         )
    INTO v_authorisation_event_at_utc
  FROM public._pay_timesheet_rotation_scope(ARRAY[p_timesheet_id]) AS rs
  LEFT JOIN public.timesheets AS family_timesheet
    ON family_timesheet.timesheet_id = rs.family_timesheet_id
  LEFT JOIN public.timesheets_financials AS family_financial
    ON family_financial.timesheet_id = rs.family_timesheet_id;

  IF v_existing_consumed_at_utc IS NOT NULL
     AND v_existing_consumed_at_utc >= v_latest_override_created_at_utc THEN
    v_new_consumed_at_utc := v_existing_consumed_at_utc;
  ELSIF v_authorisation_event_at_utc IS NOT NULL
        AND v_authorisation_event_at_utc >= v_latest_override_created_at_utc THEN
    v_new_consumed_at_utc := v_authorisation_event_at_utc;
  ELSE
    v_new_consumed_at_utc := NULL::timestamptz;
  END IF;

  v_active_advance := (
    v_latest_override_created_at_utc IS NOT NULL
    AND (
      v_new_consumed_at_utc IS NULL
      OR v_new_consumed_at_utc < v_latest_override_created_at_utc
    )
  );

  SELECT c.*
    INTO v_cache
  FROM public.timesheet_summary_pay_state_cache AS c
  WHERE c.timesheet_id = v_canonical_timesheet_id
  LIMIT 1
  FOR UPDATE;

  IF v_cache.timesheet_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'SUMMARY_PAY_STATE_CACHE_ROW_NOT_FOUND',
      'timesheet_id', v_canonical_timesheet_id,
      'active_advance', v_active_advance,
      'advance_override_created_at_utc', v_latest_override_created_at_utc,
      'advance_authorisation_consumed_at_utc', v_new_consumed_at_utc,
      'cache_updated', false
    );
  END IF;

  v_new_badges := COALESCE(v_cache.summary_badge_codes, ARRAY[]::text[]);
  v_new_badges := ARRAY_REMOVE(v_new_badges, NULL);
  v_new_badges := ARRAY_REMOVE(v_new_badges, '__PAY_BADGE_ADV__');
  IF COALESCE(v_active_advance, false) THEN
    v_new_badges := ARRAY_PREPEND('__PAY_BADGE_ADV__', v_new_badges);
  END IF;

  v_summary_state_applies := (
    COALESCE(v_active_advance, false)
    OR COALESCE(v_cache.active_processing, false)
    OR ABS(COALESCE(v_cache.paid_to_date_ex_vat, 0)) > 0.005
    OR ABS(COALESCE(v_cache.reserved_ex_vat, 0)) > 0.005
    OR ABS(COALESCE(v_cache.outstanding_ex_vat, 0)) > 0.005
    OR ABS(COALESCE(v_cache.net_delta_ex_vat, 0)) > 0.005
    OR v_cache.last_paid_at_utc IS NOT NULL
    OR UPPER(COALESCE(v_cache.summary_pay_status_code, '')) IN ('PAID', 'PARTIALLY_PAID', 'PROCESSING', 'OVERPAID')
    OR COALESCE(ARRAY_LENGTH(v_new_badges, 1), 0) > 0
  );

  UPDATE public.timesheet_summary_pay_state_cache AS c
     SET active_advance = COALESCE(v_active_advance, false),
         advance_override_created_at_utc = v_latest_override_created_at_utc,
         advance_authorisation_consumed_at_utc = v_new_consumed_at_utc,
         summary_state_applies = COALESCE(v_summary_state_applies, false),
         summary_badge_codes = COALESCE(v_new_badges, ARRAY[]::text[]),
         refreshed_at_utc = now(),
         refreshed_by_user_id = COALESCE(p_actor_user_id, c.refreshed_by_user_id)
   WHERE c.timesheet_id = v_canonical_timesheet_id
   RETURNING c.* INTO v_cache;

  v_cache_updated := FOUND;

  RETURN jsonb_build_object(
    'ok', true,
    'timesheet_id', v_canonical_timesheet_id,
    'requested_timesheet_id', p_timesheet_id,
    'active_advance', COALESCE(v_active_advance, false),
    'advance_override_created_at_utc', v_latest_override_created_at_utc,
    'advance_authorisation_consumed_at_utc', v_new_consumed_at_utc,
    'summary_badge_codes', TO_JSONB(COALESCE(v_new_badges, ARRAY[]::text[])),
    'summary_state_applies', COALESCE(v_summary_state_applies, false),
    'cache_updated', COALESCE(v_cache_updated, false)
  );
END;
$function$;

-- pay_timesheet_summary_pay_state_patch_lightweight(uuid[],uuid,text)
CREATE OR REPLACE FUNCTION public.pay_timesheet_summary_pay_state_patch_lightweight(p_timesheet_ids uuid[], p_actor_user_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_requested_ids uuid[] := ARRAY[]::uuid[];
  v_target_ids uuid[] := ARRAY[]::uuid[];
  v_patched_count integer := 0;
  v_legacy_state_rows_updated integer := 0;
  v_fallback_reason_codes text[] := ARRAY[]::text[];
  v_fallback_required boolean := false;
  v_diag_started_at timestamptz := clock_timestamp();
BEGIN
  PERFORM public._temp_diag_log(
    'TEMP_SUMMARY_REFRESH_STAGE',
    'TEMP_SUMMARY_REFRESH',
    CASE WHEN COALESCE(CARDINALITY(p_timesheet_ids), 0) > 0 THEN p_timesheet_ids[1]::text ELSE NULL::text END,
    jsonb_build_object(
      'function_name', 'pay_timesheet_summary_pay_state_patch_lightweight',
      'stage', 'entry',
      'reason', NULLIF(BTRIM(COALESCE(p_reason, '')), ''),
      'requested_count_raw', COALESCE(CARDINALITY(p_timesheet_ids), 0),
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  SELECT COALESCE(
    ARRAY_AGG(DISTINCT input_rows.timesheet_id ORDER BY input_rows.timesheet_id),
    ARRAY[]::uuid[]
  )
  INTO v_requested_ids
  FROM UNNEST(COALESCE(p_timesheet_ids, ARRAY[]::uuid[])) AS input_rows(timesheet_id)
  WHERE input_rows.timesheet_id IS NOT NULL;

  IF COALESCE(CARDINALITY(v_requested_ids), 0) = 0 THEN
    PERFORM public._temp_diag_log(
      'TEMP_SUMMARY_REFRESH_STAGE',
      'TEMP_SUMMARY_REFRESH',
      NULL::text,
      jsonb_build_object(
        'function_name', 'pay_timesheet_summary_pay_state_patch_lightweight',
        'stage', 'return_zero_requested',
        'requested_count', 0,
        'target_count', 0,
        'patched_count', 0,
        'legacy_state_rows_updated', 0,
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
      )
    );

    RETURN jsonb_build_object(
      'ok', true,
      'mode', 'ordinary_manual_save_lightweight',
      'requested_count', 0,
      'target_count', 0,
      'patched_count', 0,
      'legacy_state_rows_updated', 0
    );
  END IF;

  IF CARDINALITY(v_requested_ids) > 100 THEN
    RAISE EXCEPTION 'pay_timesheet_summary_pay_state_patch_lightweight accepts at most 100 distinct timesheet ids per call';
  END IF;

  SELECT COALESCE(
    ARRAY_AGG(DISTINCT resolved_rows.target_timesheet_id ORDER BY resolved_rows.target_timesheet_id),
    ARRAY[]::uuid[]
  )
  INTO v_target_ids
  FROM (
    SELECT
      COALESCE(
        rotation_rows.canonical_timesheet_id,
        rotation_rows.requested_timesheet_id
      ) AS target_timesheet_id
    FROM public._pay_timesheet_rotation_scope(v_requested_ids) AS rotation_rows
  ) AS resolved_rows
  JOIN public.timesheets AS target_timesheet
    ON target_timesheet.timesheet_id = resolved_rows.target_timesheet_id
  WHERE resolved_rows.target_timesheet_id IS NOT NULL;

  PERFORM public._temp_diag_log(
    'TEMP_SUMMARY_REFRESH_STAGE',
    'TEMP_SUMMARY_REFRESH',
    CASE WHEN COALESCE(CARDINALITY(v_requested_ids), 0) > 0 THEN v_requested_ids[1]::text ELSE NULL::text END,
    jsonb_build_object(
      'function_name', 'pay_timesheet_summary_pay_state_patch_lightweight',
      'stage', 'rotation_scope_done',
      'reason', NULLIF(BTRIM(COALESCE(p_reason, '')), ''),
      'requested_count', COALESCE(CARDINALITY(v_requested_ids), 0),
      'target_count', COALESCE(CARDINALITY(v_target_ids), 0),
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  IF COALESCE(CARDINALITY(v_target_ids), 0) = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'mode', 'ordinary_manual_save_lightweight',
      'requested_count', CARDINALITY(v_requested_ids),
      'target_count', 0,
      'patched_count', 0,
      'legacy_state_rows_updated', 0
    );
  END IF;

  WITH
  target_ids AS MATERIALIZED (
    SELECT target_values.timesheet_id
    FROM UNNEST(v_target_ids) AS target_values(timesheet_id)
  ),
  target_id_array AS MATERIALIZED (
    SELECT ARRAY_AGG(target_ids.timesheet_id ORDER BY target_ids.timesheet_id) AS timesheet_ids
    FROM target_ids
  ),
  family_scope AS MATERIALIZED (
    SELECT DISTINCT
      rotation_rows.family_timesheet_id,
      COALESCE(rotation_rows.canonical_timesheet_id, rotation_rows.requested_timesheet_id) AS projected_timesheet_id
    FROM target_id_array
    CROSS JOIN LATERAL public._pay_timesheet_rotation_scope(target_id_array.timesheet_ids) AS rotation_rows
    WHERE rotation_rows.family_timesheet_id IS NOT NULL
      AND COALESCE(rotation_rows.canonical_timesheet_id, rotation_rows.requested_timesheet_id) IS NOT NULL
  ),
  fallback_reasons AS MATERIALIZED (
    SELECT 'PAY_BATCH_ITEM_PRESENT'::text AS reason_code
    WHERE EXISTS (
      SELECT 1
      FROM family_scope
      JOIN public.pay_batch_items AS batch_item
        ON batch_item.timesheet_id = family_scope.family_timesheet_id
      WHERE COALESCE(batch_item.is_voided, false) = false
    )

    UNION ALL

    SELECT 'MATERIAL_LEGACY_PAY_STATE_PRESENT'::text AS reason_code
    WHERE EXISTS (
      SELECT 1
      FROM family_scope
      JOIN public.timesheet_pay_state AS legacy_state
        ON legacy_state.timesheet_id = family_scope.family_timesheet_id
      WHERE legacy_state.last_settled_snapshot_json IS NOT NULL
         OR NULLIF(BTRIM(COALESCE(legacy_state.last_settled_signature, '')), '') IS NOT NULL
         OR legacy_state.last_settled_pay_batch_id IS NOT NULL
         OR legacy_state.last_settled_at_utc IS NOT NULL
         OR legacy_state.summary_pay_paid_at_utc IS NOT NULL
         OR ABS(COALESCE(legacy_state.summary_net_delta_ex_vat, 0)) > 0.01
         OR UPPER(BTRIM(COALESCE(legacy_state.summary_pay_status_code, ''))) NOT IN ('', 'UNPAID')
         OR UPPER(BTRIM(COALESCE(legacy_state.summary_pay_icon_code, ''))) NOT IN ('', 'NONE')
    )

    UNION ALL

    SELECT 'MATERIAL_SUMMARY_CACHE_PRESENT'::text AS reason_code
    WHERE EXISTS (
      SELECT 1
      FROM family_scope
      JOIN public.timesheet_summary_pay_state_cache AS summary_cache
        ON summary_cache.timesheet_id = family_scope.family_timesheet_id
      WHERE COALESCE(summary_cache.summary_state_applies, false) = true
         OR summary_cache.last_paid_at_utc IS NOT NULL
         OR ABS(COALESCE(summary_cache.paid_to_date_ex_vat, 0)) > 0.01
         OR ABS(COALESCE(summary_cache.reserved_ex_vat, 0)) > 0.01
         OR COALESCE(summary_cache.active_advance, false) = true
         OR summary_cache.advance_override_created_at_utc IS NOT NULL
         OR summary_cache.advance_authorisation_consumed_at_utc IS NOT NULL
         OR COALESCE(summary_cache.active_processing, false) = true
         OR UPPER(BTRIM(COALESCE(summary_cache.summary_pay_status_code, ''))) NOT IN ('', 'UNPAID')
         OR UPPER(BTRIM(COALESCE(summary_cache.summary_pay_icon_code, ''))) NOT IN ('', 'NONE')
         OR CARDINALITY(COALESCE(summary_cache.summary_badge_codes, ARRAY[]::text[])) > 0
    )

    UNION ALL

    SELECT 'ACTIVE_PAYMENT_CORRECTION_PRESENT'::text AS reason_code
    WHERE EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_items AS correction_item
      LEFT JOIN public.pay_batch_items AS correction_batch_item
        ON correction_batch_item.id = correction_item.pay_batch_item_id
      JOIN family_scope
        ON family_scope.family_timesheet_id = COALESCE(
          correction_item.timesheet_id,
          correction_batch_item.timesheet_id
        )
      JOIN public.pay_payment_correction_requests AS correction_request
        ON correction_request.id = correction_item.correction_request_id
      WHERE correction_request.status IN (
        'REQUESTED',
        'AWAITING_AUTHORISATION',
        'AUTHORISED',
        'EXPANDED',
        'PROCESSING',
        'BLOCKED'
      )
        AND correction_item.status NOT IN ('APPLIED', 'SKIPPED')
    )

    UNION ALL

    SELECT 'OPEN_FINANCE_COMPONENT_PRESENT'::text AS reason_code
    WHERE EXISTS (
      SELECT 1
      FROM family_scope
      JOIN public.pay_finance_case_components AS finance_component
        ON finance_component.linked_timesheet_id = family_scope.family_timesheet_id
      WHERE finance_component.closed_at_utc IS NULL
         OR ABS(COALESCE(finance_component.remaining_source_amount, 0)) > 0.01
    )

    UNION ALL

    SELECT 'ACTIVE_ADVANCE_CASE_PRESENT'::text AS reason_code
    WHERE EXISTS (
      SELECT 1
      FROM family_scope
      JOIN public.pay_advances AS pay_advance
        ON pay_advance.linked_timesheet_id = family_scope.family_timesheet_id
      WHERE UPPER(BTRIM(COALESCE(pay_advance.status::text, ''))) NOT IN ('', 'PAID_OFF')
         OR ABS(COALESCE(pay_advance.outstanding_amount, 0)) > 0.01
    )

    UNION ALL

    SELECT 'PAID_LOCKED_OR_PAY_ON_HOLD_TSFIN_PRESENT'::text AS reason_code
    WHERE EXISTS (
      SELECT 1
      FROM family_scope
      JOIN public.timesheets_financials AS family_financial
        ON family_financial.timesheet_id = family_scope.family_timesheet_id
      WHERE family_financial.paid_at_utc IS NOT NULL
         OR family_financial.locked_by_invoice_id IS NOT NULL
         OR family_financial.locked_at_utc IS NOT NULL
         OR family_financial.unlocked_by_credit_note_id IS NOT NULL
         OR COALESCE(family_financial.pay_on_hold, false) = true
         OR family_financial.pay_on_hold_since_utc IS NOT NULL
         OR family_financial.remittance_last_sent_at_utc IS NOT NULL
         OR COALESCE(family_financial.remittance_send_count, 0) > 0
    )
  )
  SELECT COALESCE(
    ARRAY_AGG(fallback_reasons.reason_code ORDER BY fallback_reasons.reason_code),
    ARRAY[]::text[]
  )
  INTO v_fallback_reason_codes
  FROM fallback_reasons;

  v_fallback_required := COALESCE(CARDINALITY(v_fallback_reason_codes), 0) > 0;

  IF v_fallback_required IS TRUE THEN
    PERFORM public._temp_diag_log(
      'TEMP_SUMMARY_REFRESH_STAGE',
      'TEMP_SUMMARY_REFRESH',
      CASE WHEN COALESCE(CARDINALITY(v_target_ids), 0) > 0 THEN v_target_ids[1]::text ELSE NULL::text END,
      jsonb_build_object(
        'function_name', 'pay_timesheet_summary_pay_state_patch_lightweight',
        'stage', 'fallback_required_deferred_full_summary_refresh',
        'reason', NULLIF(BTRIM(COALESCE(p_reason, '')), ''),
        'requested_count', COALESCE(CARDINALITY(v_requested_ids), 0),
        'target_count', COALESCE(CARDINALITY(v_target_ids), 0),
        'fallback_required', true,
        'fallback_reason_codes', to_jsonb(v_fallback_reason_codes),
        'patched_count', 0,
        'legacy_state_rows_updated', 0,
        'policy_x_authority_scope', 'MATERIAL_PAY_STATE_REQUIRES_NON_MODAL_FULL_REFRESH',
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
      )
    );

    RETURN jsonb_build_object(
      'ok', true,
      'mode', 'ordinary_manual_save_lightweight',
      'fallback_required', true,
      'fallback_deferred', true,
      'deferred_full_refresh_required', true,
      'fallback_reason_codes', to_jsonb(v_fallback_reason_codes),
      'requested_count', CARDINALITY(v_requested_ids),
      'target_count', CARDINALITY(v_target_ids),
      'patched_count', 0,
      'legacy_state_rows_updated', 0
    );
  END IF;

  WITH
  target_ids AS MATERIALIZED (
    SELECT target_values.timesheet_id
    FROM UNNEST(v_target_ids) AS target_values(timesheet_id)
  ),
  target_id_array AS MATERIALIZED (
    SELECT ARRAY_AGG(target_ids.timesheet_id ORDER BY target_ids.timesheet_id) AS timesheet_ids
    FROM target_ids
  ),
  family_scope AS MATERIALIZED (
    SELECT DISTINCT
      rotation_rows.family_timesheet_id,
      COALESCE(rotation_rows.canonical_timesheet_id, rotation_rows.requested_timesheet_id) AS projected_timesheet_id
    FROM target_id_array
    CROSS JOIN LATERAL public._pay_timesheet_rotation_scope(target_id_array.timesheet_ids) AS rotation_rows
    WHERE rotation_rows.family_timesheet_id IS NOT NULL
      AND COALESCE(rotation_rows.canonical_timesheet_id, rotation_rows.requested_timesheet_id) IS NOT NULL
  ),
  existing_cache AS MATERIALIZED (
    SELECT
      target_ids.timesheet_id,
      summary_cache.paid_to_date_ex_vat,
      summary_cache.last_paid_at_utc,
      summary_cache.reserved_ex_vat,
      summary_cache.outstanding_ex_vat,
      summary_cache.net_delta_ex_vat,
      summary_cache.active_advance,
      summary_cache.active_processing,
      summary_cache.summary_state_applies,
      summary_cache.advance_override_created_at_utc,
      summary_cache.advance_authorisation_consumed_at_utc,
      summary_cache.summary_pay_status_code,
      summary_cache.summary_pay_icon_code,
      summary_cache.summary_badge_codes
    FROM target_ids
    LEFT JOIN public.timesheet_summary_pay_state_cache AS summary_cache
      ON summary_cache.timesheet_id = target_ids.timesheet_id
  ),
  current_tsfin_totals AS MATERIALIZED (
    SELECT DISTINCT ON (target_ids.timesheet_id)
      target_ids.timesheet_id,
      ROUND(COALESCE(current_financial.total_pay_ex_vat, 0), 2)::numeric AS current_total_pay_ex_vat
    FROM target_ids
    LEFT JOIN public.timesheets_financials AS current_financial
      ON current_financial.timesheet_id = target_ids.timesheet_id
     AND COALESCE(current_financial.is_current, false) = true
    ORDER BY
      target_ids.timesheet_id,
      current_financial.computed_at_utc DESC NULLS LAST,
      current_financial.updated_at DESC NULLS LAST,
      current_financial.created_at DESC NULLS LAST,
      current_financial.id DESC
  ),
  legacy_ranked AS MATERIALIZED (
    SELECT
      family_scope.projected_timesheet_id AS timesheet_id,
      legacy_state.summary_pay_status_code,
      legacy_state.summary_pay_icon_code,
      legacy_state.summary_pay_paid_at_utc,
      legacy_state.summary_net_delta_ex_vat,
      COALESCE(legacy_state.last_settled_at_utc, legacy_state.summary_pay_paid_at_utc) AS last_paid_at_utc,
      ROW_NUMBER() OVER (
        PARTITION BY family_scope.projected_timesheet_id
        ORDER BY
          CASE WHEN NULLIF(BTRIM(COALESCE(legacy_state.summary_pay_status_code, '')), '') IS NOT NULL THEN 0 ELSE 1 END,
          COALESCE(legacy_state.last_settled_at_utc, legacy_state.summary_pay_paid_at_utc) DESC NULLS LAST,
          family_scope.family_timesheet_id
      ) AS row_rank
    FROM family_scope
    JOIN public.timesheet_pay_state AS legacy_state
      ON legacy_state.timesheet_id = family_scope.family_timesheet_id
  ),
  legacy_state AS MATERIALIZED (
    SELECT
      legacy_ranked.timesheet_id,
      legacy_ranked.summary_pay_status_code,
      legacy_ranked.summary_pay_icon_code,
      legacy_ranked.summary_pay_paid_at_utc,
      legacy_ranked.summary_net_delta_ex_vat,
      legacy_ranked.last_paid_at_utc
    FROM legacy_ranked
    WHERE legacy_ranked.row_rank = 1
  ),
  latest_advance_override AS MATERIALIZED (
    SELECT DISTINCT ON (family_scope.projected_timesheet_id)
      family_scope.projected_timesheet_id AS timesheet_id,
      payment_override.id AS override_id,
      payment_override.created_at_utc AS override_created_at_utc
    FROM family_scope
    JOIN public.timesheet_payment_overrides AS payment_override
      ON payment_override.timesheet_id = family_scope.family_timesheet_id
    WHERE payment_override.cleared_at_utc IS NULL
      AND UPPER(BTRIM(COALESCE(payment_override.override_type, ''))) = 'ADVANCE_THIS_PAYMENT'
    ORDER BY
      family_scope.projected_timesheet_id,
      payment_override.created_at_utc DESC,
      payment_override.id DESC
  ),
  current_authorisation_state AS MATERIALIZED (
    SELECT
      target_ids.timesheet_id,
      GREATEST(
        MAX(family_timesheet.authorised_at_server),
        MAX(family_timesheet.revoked_at),
        MAX(family_financial.authorised_at_utc)
      ) AS authorised_at_utc
    FROM target_ids
    LEFT JOIN family_scope
      ON family_scope.projected_timesheet_id = target_ids.timesheet_id
    LEFT JOIN public.timesheets AS family_timesheet
      ON family_timesheet.timesheet_id = family_scope.family_timesheet_id
    LEFT JOIN public.timesheets_financials AS family_financial
      ON family_financial.timesheet_id = family_scope.family_timesheet_id
    GROUP BY target_ids.timesheet_id
  ),
  existing_display_cache AS MATERIALIZED (
    SELECT
      target_ids.timesheet_id,
      MAX(existing_family_cache.advance_authorisation_consumed_at_utc) AS advance_authorisation_consumed_at_utc
    FROM target_ids
    LEFT JOIN family_scope
      ON family_scope.projected_timesheet_id = target_ids.timesheet_id
    LEFT JOIN public.timesheet_summary_pay_state_cache AS existing_family_cache
      ON existing_family_cache.timesheet_id = family_scope.family_timesheet_id
    GROUP BY target_ids.timesheet_id
  ),
  advance_state_prepared AS MATERIALIZED (
    SELECT
      target_ids.timesheet_id,
      latest_advance_override.override_created_at_utc,
      current_authorisation_state.authorised_at_utc,
      CASE
        WHEN latest_advance_override.override_created_at_utc IS NULL
          THEN existing_display_cache.advance_authorisation_consumed_at_utc
        WHEN existing_display_cache.advance_authorisation_consumed_at_utc
             >= latest_advance_override.override_created_at_utc
          THEN existing_display_cache.advance_authorisation_consumed_at_utc
        WHEN current_authorisation_state.authorised_at_utc
             >= latest_advance_override.override_created_at_utc
          THEN current_authorisation_state.authorised_at_utc
        ELSE NULL::timestamptz
      END AS advance_authorisation_consumed_at_utc
    FROM target_ids
    LEFT JOIN latest_advance_override
      ON latest_advance_override.timesheet_id = target_ids.timesheet_id
    LEFT JOIN current_authorisation_state
      ON current_authorisation_state.timesheet_id = target_ids.timesheet_id
    LEFT JOIN existing_display_cache
      ON existing_display_cache.timesheet_id = target_ids.timesheet_id
  ),
  advance_state AS MATERIALIZED (
    SELECT
      advance_state_prepared.timesheet_id,
      advance_state_prepared.override_created_at_utc,
      advance_state_prepared.advance_authorisation_consumed_at_utc,
      (
        advance_state_prepared.override_created_at_utc IS NOT NULL
        AND (
          advance_state_prepared.advance_authorisation_consumed_at_utc IS NULL
          OR advance_state_prepared.advance_authorisation_consumed_at_utc
               < advance_state_prepared.override_created_at_utc
        )
      ) AS active_advance
    FROM advance_state_prepared
  ),
  active_batch_processing AS MATERIALIZED (
    SELECT DISTINCT
      family_scope.projected_timesheet_id AS timesheet_id
    FROM family_scope
    JOIN public.pay_batch_items AS batch_item
      ON batch_item.timesheet_id = family_scope.family_timesheet_id
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = batch_item.pay_batch_candidate_id
    JOIN public.pay_batches AS pay_batch
      ON pay_batch.id = batch_candidate.pay_batch_id
    LEFT JOIN public.pay_bank_transfers AS bank_transfer
      ON bank_transfer.id = batch_item.pay_bank_transfer_id
     AND bank_transfer.pay_batch_id = pay_batch.id
    LEFT JOIN LATERAL public._pay_rail_state_money_movement_classify(
      bank_transfer.status,
      bank_transfer.rail_state,
      COALESCE(bank_transfer.rail_meta_json, '{}'::jsonb),
      COALESCE(bank_transfer.rail_meta_json, '{}'::jsonb)
    ) AS transfer_classifier
      ON bank_transfer.id IS NOT NULL
    WHERE COALESCE(batch_item.is_voided, false) = false
      AND UPPER(BTRIM(COALESCE(batch_item.item_type, ''))) IN (
        'SEGMENT_DELTA',
        'EXPENSE_DELTA',
        'ADJUSTMENT_DELTA',
        'MILEAGE_DELTA'
      )
      AND public._pay_batch_status_is_active_reservation(pay_batch.status)
      AND UPPER(BTRIM(COALESCE(batch_candidate.settlement_status, ''))) NOT IN (
        'SETTLED',
        'PAID',
        'CONFIRMED'
      )
      AND batch_candidate.settled_at_utc IS NULL
      AND COALESCE(transfer_classifier.is_final_money_moved, false) = false
      AND COALESCE(transfer_classifier.is_terminal_no_money, false) = false
      AND bank_transfer.completed_at_utc IS NULL
  ),
  active_correction_processing AS MATERIALIZED (
    SELECT DISTINCT
      family_scope.projected_timesheet_id AS timesheet_id
    FROM public.pay_payment_correction_items AS correction_item
    LEFT JOIN public.pay_batch_items AS correction_batch_item
      ON correction_batch_item.id = correction_item.pay_batch_item_id
    JOIN family_scope
      ON family_scope.family_timesheet_id = COALESCE(
        correction_item.timesheet_id,
        correction_batch_item.timesheet_id
      )
    JOIN public.pay_payment_correction_requests AS correction_request
      ON correction_request.id = correction_item.correction_request_id
    WHERE correction_request.status IN (
      'REQUESTED',
      'AWAITING_AUTHORISATION',
      'AUTHORISED',
      'EXPANDED',
      'PROCESSING',
      'BLOCKED'
    )
      AND correction_item.status NOT IN ('APPLIED', 'SKIPPED')
  ),
  prepared AS MATERIALIZED (
    SELECT
      target_ids.timesheet_id,
      ROUND(COALESCE(existing_cache.paid_to_date_ex_vat, 0), 2)::numeric AS paid_to_date_ex_vat,
      COALESCE(existing_cache.last_paid_at_utc, legacy_state.last_paid_at_utc) AS last_paid_at_utc,
      ROUND(COALESCE(existing_cache.reserved_ex_vat, 0), 2)::numeric AS reserved_ex_vat,
      ROUND(
        COALESCE(current_tsfin_totals.current_total_pay_ex_vat, 0)
        - COALESCE(existing_cache.paid_to_date_ex_vat, 0)
        - COALESCE(existing_cache.reserved_ex_vat, 0),
        2
      )::numeric AS outstanding_ex_vat,
      ROUND(
        COALESCE(current_tsfin_totals.current_total_pay_ex_vat, 0)
        - COALESCE(existing_cache.paid_to_date_ex_vat, 0),
        2
      )::numeric AS net_delta_ex_vat,
      COALESCE(advance_state.active_advance, false) AS active_advance,
      (
        COALESCE(existing_cache.active_processing, false)
        OR active_batch_processing.timesheet_id IS NOT NULL
        OR active_correction_processing.timesheet_id IS NOT NULL
      ) AS active_processing,
      advance_state.override_created_at_utc AS advance_override_created_at_utc,
      advance_state.advance_authorisation_consumed_at_utc,
      COALESCE(
        NULLIF(BTRIM(COALESCE(existing_cache.summary_pay_status_code, '')), ''),
        NULLIF(BTRIM(COALESCE(legacy_state.summary_pay_status_code, '')), ''),
        CASE
          WHEN (
            COALESCE(existing_cache.active_processing, false)
            OR active_batch_processing.timesheet_id IS NOT NULL
            OR active_correction_processing.timesheet_id IS NOT NULL
          ) THEN 'PROCESSING'
          ELSE 'UNPAID'
        END
      ) AS summary_pay_status_code,
      COALESCE(
        NULLIF(BTRIM(COALESCE(existing_cache.summary_pay_icon_code, '')), ''),
        NULLIF(BTRIM(COALESCE(legacy_state.summary_pay_icon_code, '')), ''),
        CASE
          WHEN (
            COALESCE(existing_cache.active_processing, false)
            OR active_batch_processing.timesheet_id IS NOT NULL
            OR active_correction_processing.timesheet_id IS NOT NULL
          ) THEN 'CLOCK'
          ELSE 'NONE'
        END
      ) AS summary_pay_icon_code,
      ARRAY_REMOVE(
        ARRAY_REMOVE(
          ARRAY_REMOVE(COALESCE(existing_cache.summary_badge_codes, ARRAY[]::text[]), NULL::text),
          '__PAY_BADGE_ADV__'
        ),
        '__PAY_BADGE_PROCESSING__'
      ) AS badge_codes_without_dynamic_state,
      COALESCE(existing_cache.summary_state_applies, false) AS existing_summary_state_applies
    FROM target_ids
    LEFT JOIN existing_cache
      ON existing_cache.timesheet_id = target_ids.timesheet_id
    LEFT JOIN legacy_state
      ON legacy_state.timesheet_id = target_ids.timesheet_id
    LEFT JOIN current_tsfin_totals
      ON current_tsfin_totals.timesheet_id = target_ids.timesheet_id
    LEFT JOIN advance_state
      ON advance_state.timesheet_id = target_ids.timesheet_id
    LEFT JOIN active_batch_processing
      ON active_batch_processing.timesheet_id = target_ids.timesheet_id
    LEFT JOIN active_correction_processing
      ON active_correction_processing.timesheet_id = target_ids.timesheet_id
  ),
  final_values AS MATERIALIZED (
    SELECT
      prepared.timesheet_id,
      prepared.paid_to_date_ex_vat,
      prepared.last_paid_at_utc,
      prepared.reserved_ex_vat,
      prepared.outstanding_ex_vat,
      prepared.net_delta_ex_vat,
      prepared.active_advance,
      prepared.active_processing,
      prepared.advance_override_created_at_utc,
      prepared.advance_authorisation_consumed_at_utc,
      prepared.summary_pay_status_code,
      prepared.summary_pay_icon_code,
      ARRAY_REMOVE(
        ARRAY[
          CASE WHEN prepared.active_advance THEN '__PAY_BADGE_ADV__' ELSE NULL::text END,
          CASE WHEN prepared.active_processing AND prepared.summary_pay_status_code <> 'PROCESSING' THEN '__PAY_BADGE_PROCESSING__' ELSE NULL::text END
        ]::text[] || prepared.badge_codes_without_dynamic_state,
        NULL::text
      ) AS summary_badge_codes,
      (
        prepared.existing_summary_state_applies
        OR prepared.active_advance
        OR prepared.active_processing
        OR prepared.last_paid_at_utc IS NOT NULL
        OR ABS(COALESCE(prepared.paid_to_date_ex_vat, 0)) > 0.01
        OR ABS(COALESCE(prepared.reserved_ex_vat, 0)) > 0.01
      ) AS summary_state_applies
    FROM prepared
  )
  INSERT INTO public.timesheet_summary_pay_state_cache AS summary_cache (
    timesheet_id,
    paid_to_date_ex_vat,
    last_paid_at_utc,
    reserved_ex_vat,
    outstanding_ex_vat,
    net_delta_ex_vat,
    active_advance,
    active_processing,
    summary_state_applies,
    advance_override_created_at_utc,
    advance_authorisation_consumed_at_utc,
    summary_pay_status_code,
    summary_pay_icon_code,
    summary_badge_codes,
    refreshed_at_utc,
    refreshed_by_user_id
  )
  SELECT
    final_values.timesheet_id,
    final_values.paid_to_date_ex_vat,
    final_values.last_paid_at_utc,
    final_values.reserved_ex_vat,
    final_values.outstanding_ex_vat,
    final_values.net_delta_ex_vat,
    final_values.active_advance,
    final_values.active_processing,
    final_values.summary_state_applies,
    final_values.advance_override_created_at_utc,
    final_values.advance_authorisation_consumed_at_utc,
    final_values.summary_pay_status_code,
    final_values.summary_pay_icon_code,
    final_values.summary_badge_codes,
    clock_timestamp(),
    p_actor_user_id
  FROM final_values
  ON CONFLICT (timesheet_id) DO UPDATE
  SET
    paid_to_date_ex_vat = EXCLUDED.paid_to_date_ex_vat,
    last_paid_at_utc = EXCLUDED.last_paid_at_utc,
    reserved_ex_vat = EXCLUDED.reserved_ex_vat,
    outstanding_ex_vat = EXCLUDED.outstanding_ex_vat,
    net_delta_ex_vat = EXCLUDED.net_delta_ex_vat,
    active_advance = EXCLUDED.active_advance,
    active_processing = EXCLUDED.active_processing,
    summary_state_applies = EXCLUDED.summary_state_applies,
    advance_override_created_at_utc = EXCLUDED.advance_override_created_at_utc,
    advance_authorisation_consumed_at_utc = EXCLUDED.advance_authorisation_consumed_at_utc,
    summary_pay_status_code = EXCLUDED.summary_pay_status_code,
    summary_pay_icon_code = EXCLUDED.summary_pay_icon_code,
    summary_badge_codes = EXCLUDED.summary_badge_codes,
    refreshed_at_utc = EXCLUDED.refreshed_at_utc,
    refreshed_by_user_id = EXCLUDED.refreshed_by_user_id
  WHERE summary_cache.paid_to_date_ex_vat IS DISTINCT FROM EXCLUDED.paid_to_date_ex_vat
     OR summary_cache.last_paid_at_utc IS DISTINCT FROM EXCLUDED.last_paid_at_utc
     OR summary_cache.reserved_ex_vat IS DISTINCT FROM EXCLUDED.reserved_ex_vat
     OR summary_cache.outstanding_ex_vat IS DISTINCT FROM EXCLUDED.outstanding_ex_vat
     OR summary_cache.net_delta_ex_vat IS DISTINCT FROM EXCLUDED.net_delta_ex_vat
     OR summary_cache.active_advance IS DISTINCT FROM EXCLUDED.active_advance
     OR summary_cache.active_processing IS DISTINCT FROM EXCLUDED.active_processing
     OR summary_cache.summary_state_applies IS DISTINCT FROM EXCLUDED.summary_state_applies
     OR summary_cache.advance_override_created_at_utc IS DISTINCT FROM EXCLUDED.advance_override_created_at_utc
     OR summary_cache.advance_authorisation_consumed_at_utc IS DISTINCT FROM EXCLUDED.advance_authorisation_consumed_at_utc
     OR summary_cache.summary_pay_status_code IS DISTINCT FROM EXCLUDED.summary_pay_status_code
     OR summary_cache.summary_pay_icon_code IS DISTINCT FROM EXCLUDED.summary_pay_icon_code
     OR summary_cache.summary_badge_codes IS DISTINCT FROM EXCLUDED.summary_badge_codes
     OR summary_cache.refreshed_by_user_id IS DISTINCT FROM EXCLUDED.refreshed_by_user_id;

  GET DIAGNOSTICS v_patched_count = ROW_COUNT;

  WITH legacy_projection AS MATERIALIZED (
    SELECT DISTINCT
      rotation_rows.family_timesheet_id,
      COALESCE(rotation_rows.canonical_timesheet_id, rotation_rows.requested_timesheet_id) AS projected_timesheet_id
    FROM public._pay_timesheet_rotation_scope(v_target_ids) AS rotation_rows
    WHERE rotation_rows.family_timesheet_id IS NOT NULL
      AND COALESCE(rotation_rows.canonical_timesheet_id, rotation_rows.requested_timesheet_id) IS NOT NULL
  )
  UPDATE public.timesheet_pay_state AS legacy_state
  SET
    summary_pay_status_code = CASE
      WHEN summary_cache.summary_pay_status_code = 'OVERPAID' THEN 'PAID'
      ELSE summary_cache.summary_pay_status_code
    END,
    summary_pay_icon_code = CASE
      WHEN summary_cache.summary_pay_status_code = 'OVERPAID' THEN 'RED_COIN'
      ELSE summary_cache.summary_pay_icon_code
    END,
    summary_pay_paid_at_utc = summary_cache.last_paid_at_utc,
    summary_net_delta_ex_vat = summary_cache.net_delta_ex_vat
  FROM legacy_projection
  JOIN public.timesheet_summary_pay_state_cache AS summary_cache
    ON summary_cache.timesheet_id = legacy_projection.projected_timesheet_id
  WHERE legacy_state.timesheet_id = legacy_projection.family_timesheet_id
    AND summary_cache.timesheet_id = ANY (v_target_ids)
    AND COALESCE(summary_cache.summary_state_applies, false) = true
    AND (
      legacy_state.summary_pay_status_code IS DISTINCT FROM CASE
        WHEN summary_cache.summary_pay_status_code = 'OVERPAID' THEN 'PAID'
        ELSE summary_cache.summary_pay_status_code
      END
      OR legacy_state.summary_pay_icon_code IS DISTINCT FROM CASE
        WHEN summary_cache.summary_pay_status_code = 'OVERPAID' THEN 'RED_COIN'
        ELSE summary_cache.summary_pay_icon_code
      END
      OR legacy_state.summary_pay_paid_at_utc IS DISTINCT FROM summary_cache.last_paid_at_utc
      OR legacy_state.summary_net_delta_ex_vat IS DISTINCT FROM summary_cache.net_delta_ex_vat
    );

  GET DIAGNOSTICS v_legacy_state_rows_updated = ROW_COUNT;

  PERFORM public._temp_diag_log(
    'TEMP_SUMMARY_REFRESH_STAGE',
    'TEMP_SUMMARY_REFRESH',
    CASE WHEN COALESCE(CARDINALITY(v_target_ids), 0) > 0 THEN v_target_ids[1]::text ELSE NULL::text END,
    jsonb_build_object(
      'function_name', 'pay_timesheet_summary_pay_state_patch_lightweight',
      'stage', 'return',
      'reason', NULLIF(BTRIM(COALESCE(p_reason, '')), ''),
      'requested_count', COALESCE(CARDINALITY(v_requested_ids), 0),
      'target_count', COALESCE(CARDINALITY(v_target_ids), 0),
      'patched_count', v_patched_count,
      'legacy_state_rows_updated', v_legacy_state_rows_updated,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH_DISPLAY_PATCH_NO_BANKING_PAY_RECALC',
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'mode', 'ordinary_manual_save_lightweight',
    'fallback_required', false,
    'requested_count', CARDINALITY(v_requested_ids),
    'target_count', CARDINALITY(v_target_ids),
    'patched_count', v_patched_count,
    'legacy_state_rows_updated', v_legacy_state_rows_updated
  );
END;
$function$;

-- pay_timesheet_summary_pay_state_refresh_trigger()
CREATE OR REPLACE FUNCTION public.pay_timesheet_summary_pay_state_refresh_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_chunk_ids uuid[] := ARRAY[]::uuid[];
  v_offset integer := 1;
  v_total integer := 0;
  v_diag_started_at timestamptz := clock_timestamp();
  v_chunk_started_at timestamptz;
  v_refresh_result jsonb := '{}'::jsonb;
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_invalidation_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_scope_invalidation_result jsonb := '{}'::jsonb;
  v_correction_dirty_contexts jsonb := '{}'::jsonb;
  v_scope_change_tx_token uuid := NULL::uuid;
  v_correction_request_id uuid := NULL::uuid;
  v_correction_pay_batch_id uuid := NULL::uuid;
  v_correction_operation_id uuid := NULL::uuid;
  v_correction_request_status text := NULL::text;
  v_correction_selection_json jsonb := '{}'::jsonb;
  v_correction_plan_json jsonb := '{}'::jsonb;
  v_correction_lifecycle_phase text := NULL::text;
BEGIN

  PERFORM public._temp_diag_log(
    'TEMP_SUMMARY_REFRESH_STAGE',
    'TEMP_SUMMARY_REFRESH',
    NULL::text,
    jsonb_build_object(
      'function_name', 'pay_timesheet_summary_pay_state_refresh_trigger',
      'stage', 'entry',
      'trigger_table', TG_TABLE_NAME,
      'trigger_op', TG_OP,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  IF COALESCE(current_setting('cloudtms.lifecycle_defer_summary_refresh', true), '') = 'on'
     AND TG_TABLE_NAME IN ('timesheets', 'timesheets_financials') THEN
    PERFORM public._temp_diag_log(
      'TEMP_SUMMARY_REFRESH_STAGE',
      'TEMP_SUMMARY_REFRESH',
      NULL::text,
      jsonb_build_object(
        'function_name', 'pay_timesheet_summary_pay_state_refresh_trigger',
        'stage', CASE
          WHEN LOWER(BTRIM(COALESCE(current_setting('cloudtms.lifecycle_mutation_context', true), ''))) = 'manual_timesheet_save'
            THEN 'deferred_by_manual_save_context'
          ELSE 'deferred_by_lifecycle_context'
        END,
        'trigger_table', TG_TABLE_NAME,
        'trigger_op', TG_OP,
        'mutation_context', NULLIF(current_setting('cloudtms.lifecycle_mutation_context', true), ''),
        'summary_refresh_mode', NULLIF(current_setting('cloudtms.summary_refresh_mode', true), ''),
        'target_timesheet_id', NULLIF(current_setting('cloudtms.lifecycle_target_timesheet_id', true), ''),
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
      )
    );
    RETURN NULL;
  END IF;

  IF TG_TABLE_SCHEMA <> 'public' THEN
    RETURN NULL;
  END IF;

  IF TG_TABLE_NAME = 'timesheets_financials' THEN
    IF TG_OP = 'INSERT' THEN
      SELECT COALESCE(ARRAY_AGG(DISTINCT new_rows.timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM new_rows
      WHERE new_rows.timesheet_id IS NOT NULL
        AND COALESCE(new_rows.is_current, false) = true;
    ELSIF TG_OP = 'UPDATE' THEN
      WITH changed_rows AS MATERIALIZED (
        SELECT
          new_rows.timesheet_id AS new_timesheet_id,
          old_rows.timesheet_id AS old_timesheet_id,
          COALESCE(new_rows.is_current, false) AS new_is_current,
          COALESCE(old_rows.is_current, false) AS old_is_current
        FROM new_rows
        JOIN old_rows
          ON old_rows.id = new_rows.id
        WHERE (
             new_rows.timesheet_id IS DISTINCT FROM old_rows.timesheet_id
             OR new_rows.is_current IS DISTINCT FROM old_rows.is_current
             OR new_rows.basis IS DISTINCT FROM old_rows.basis
             OR new_rows.candidate_id IS DISTINCT FROM old_rows.candidate_id
             OR new_rows.client_id IS DISTINCT FROM old_rows.client_id
             OR new_rows.pay_method IS DISTINCT FROM old_rows.pay_method
             OR new_rows.policy_snapshot_json IS DISTINCT FROM old_rows.policy_snapshot_json
             OR new_rows.rate_source_refs_json IS DISTINCT FROM old_rows.rate_source_refs_json
             OR new_rows.hours_day IS DISTINCT FROM old_rows.hours_day
             OR new_rows.hours_night IS DISTINCT FROM old_rows.hours_night
             OR new_rows.hours_sat IS DISTINCT FROM old_rows.hours_sat
             OR new_rows.hours_sun IS DISTINCT FROM old_rows.hours_sun
             OR new_rows.hours_bh IS DISTINCT FROM old_rows.hours_bh
             OR new_rows.pay_day IS DISTINCT FROM old_rows.pay_day
             OR new_rows.pay_night IS DISTINCT FROM old_rows.pay_night
             OR new_rows.pay_sat IS DISTINCT FROM old_rows.pay_sat
             OR new_rows.pay_sun IS DISTINCT FROM old_rows.pay_sun
             OR new_rows.pay_bh IS DISTINCT FROM old_rows.pay_bh
             OR new_rows.total_pay_ex_vat IS DISTINCT FROM old_rows.total_pay_ex_vat
             OR new_rows.invoice_breakdown_json IS DISTINCT FROM old_rows.invoice_breakdown_json
             OR new_rows.additional_units_json IS DISTINCT FROM old_rows.additional_units_json
             OR new_rows.additional_pay_ex_vat IS DISTINCT FROM old_rows.additional_pay_ex_vat
             OR new_rows.expenses_pay_ex_vat IS DISTINCT FROM old_rows.expenses_pay_ex_vat
             OR new_rows.travel_pay_ex_vat IS DISTINCT FROM old_rows.travel_pay_ex_vat
             OR new_rows.accommodation_pay_ex_vat IS DISTINCT FROM old_rows.accommodation_pay_ex_vat
             OR new_rows.other_pay_ex_vat IS DISTINCT FROM old_rows.other_pay_ex_vat
             OR new_rows.mileage_pay_ex_vat IS DISTINCT FROM old_rows.mileage_pay_ex_vat
             OR new_rows.worked_start_iso IS DISTINCT FROM old_rows.worked_start_iso
             OR new_rows.worked_end_iso IS DISTINCT FROM old_rows.worked_end_iso
             OR new_rows.break_start_iso IS DISTINCT FROM old_rows.break_start_iso
             OR new_rows.break_end_iso IS DISTINCT FROM old_rows.break_end_iso
             OR new_rows.break_minutes IS DISTINCT FROM old_rows.break_minutes
             OR new_rows.actual_schedule_json IS DISTINCT FROM old_rows.actual_schedule_json
             OR new_rows.pay_on_hold IS DISTINCT FROM old_rows.pay_on_hold
             OR new_rows.paid_at_utc IS DISTINCT FROM old_rows.paid_at_utc
             OR new_rows.authorised_at_utc IS DISTINCT FROM old_rows.authorised_at_utc
           )
          AND (
             new_rows.timesheet_id IS DISTINCT FROM old_rows.timesheet_id
             OR new_rows.is_current IS DISTINCT FROM old_rows.is_current
             OR new_rows.authorised_at_utc IS NOT NULL
             OR old_rows.authorised_at_utc IS NOT NULL
             OR new_rows.pay_on_hold IS DISTINCT FROM old_rows.pay_on_hold
             OR new_rows.paid_at_utc IS DISTINCT FROM old_rows.paid_at_utc
           )
      ),
      affected_rows AS (
        SELECT changed_rows.new_timesheet_id AS timesheet_id
        FROM changed_rows
        WHERE changed_rows.new_timesheet_id IS NOT NULL
          AND changed_rows.new_is_current = true

        UNION

        SELECT changed_rows.old_timesheet_id AS timesheet_id
        FROM changed_rows
        WHERE changed_rows.old_timesheet_id IS NOT NULL
          AND changed_rows.old_is_current = true
      )
      SELECT COALESCE(ARRAY_AGG(DISTINCT affected_rows.timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM affected_rows;
    ELSE
      SELECT COALESCE(ARRAY_AGG(DISTINCT old_rows.timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM old_rows
      WHERE old_rows.timesheet_id IS NOT NULL
        AND COALESCE(old_rows.is_current, false) = true;
    END IF;

  ELSIF TG_TABLE_NAME = 'timesheets' THEN
    SELECT COALESCE(ARRAY_AGG(DISTINCT new_rows.timesheet_id), ARRAY[]::uuid[])
    INTO v_timesheet_ids
    FROM new_rows
    JOIN old_rows
      ON old_rows.timesheet_id = new_rows.timesheet_id
    WHERE new_rows.timesheet_id IS NOT NULL
      AND (
        new_rows.is_current IS DISTINCT FROM old_rows.is_current
        OR new_rows.version IS DISTINCT FROM old_rows.version
        OR new_rows.authorised_at_server IS DISTINCT FROM old_rows.authorised_at_server
        OR new_rows.revoked_at IS DISTINCT FROM old_rows.revoked_at
        OR new_rows.status IS DISTINCT FROM old_rows.status
        OR new_rows.booking_id IS DISTINCT FROM old_rows.booking_id
        OR new_rows.contract_id IS DISTINCT FROM old_rows.contract_id
        OR new_rows.sheet_scope IS DISTINCT FROM old_rows.sheet_scope
        OR new_rows.submission_mode IS DISTINCT FROM old_rows.submission_mode
        OR new_rows.line_type IS DISTINCT FROM old_rows.line_type
        OR new_rows.week_ending_date IS DISTINCT FROM old_rows.week_ending_date
        OR new_rows.reference_number IS DISTINCT FROM old_rows.reference_number
        OR new_rows.scheduled_start_iso IS DISTINCT FROM old_rows.scheduled_start_iso
        OR new_rows.scheduled_end_iso IS DISTINCT FROM old_rows.scheduled_end_iso
        OR new_rows.worked_start_iso IS DISTINCT FROM old_rows.worked_start_iso
        OR new_rows.worked_end_iso IS DISTINCT FROM old_rows.worked_end_iso
        OR new_rows.break_start_iso IS DISTINCT FROM old_rows.break_start_iso
        OR new_rows.break_end_iso IS DISTINCT FROM old_rows.break_end_iso
        OR new_rows.break_minutes IS DISTINCT FROM old_rows.break_minutes
        OR new_rows.actual_schedule_json IS DISTINCT FROM old_rows.actual_schedule_json
        OR new_rows.additional_units_week IS DISTINCT FROM old_rows.additional_units_week
        OR new_rows.additional_units_per_day IS DISTINCT FROM old_rows.additional_units_per_day
        OR new_rows.is_adjustment IS DISTINCT FROM old_rows.is_adjustment
        OR new_rows.parent_timesheet_id IS DISTINCT FROM old_rows.parent_timesheet_id
        OR new_rows.correction_id IS DISTINCT FROM old_rows.correction_id
        OR new_rows.correction_kind IS DISTINCT FROM old_rows.correction_kind
        OR new_rows.adjustment_origin IS DISTINCT FROM old_rows.adjustment_origin
      );

  ELSIF TG_TABLE_NAME = 'timesheet_payment_overrides' THEN
    IF TG_OP = 'INSERT' THEN
      SELECT COALESCE(ARRAY_AGG(DISTINCT new_rows.timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM new_rows
      WHERE new_rows.timesheet_id IS NOT NULL;
    ELSIF TG_OP = 'UPDATE' THEN
      WITH changed_overrides AS (
        SELECT
          new_rows.timesheet_id AS new_timesheet_id,
          old_rows.timesheet_id AS old_timesheet_id
        FROM new_rows
        JOIN old_rows ON old_rows.id = new_rows.id
        WHERE new_rows.timesheet_id IS DISTINCT FROM old_rows.timesheet_id
           OR new_rows.override_type IS DISTINCT FROM old_rows.override_type
           OR new_rows.created_at_utc IS DISTINCT FROM old_rows.created_at_utc
           OR new_rows.consumed_by_pay_batch_id IS DISTINCT FROM old_rows.consumed_by_pay_batch_id
           OR new_rows.consumed_at_utc IS DISTINCT FROM old_rows.consumed_at_utc
           OR new_rows.cleared_at_utc IS DISTINCT FROM old_rows.cleared_at_utc
      )
      SELECT COALESCE(ARRAY_AGG(DISTINCT affected_rows.timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM (
        SELECT changed_overrides.new_timesheet_id AS timesheet_id
        FROM changed_overrides
        WHERE changed_overrides.new_timesheet_id IS NOT NULL

        UNION

        SELECT changed_overrides.old_timesheet_id AS timesheet_id
        FROM changed_overrides
        WHERE changed_overrides.old_timesheet_id IS NOT NULL
      ) AS affected_rows;
    ELSE
      SELECT COALESCE(ARRAY_AGG(DISTINCT old_rows.timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM old_rows
      WHERE old_rows.timesheet_id IS NOT NULL;
    END IF;

  ELSIF TG_TABLE_NAME = 'timesheet_pay_state' THEN
    IF TG_OP = 'INSERT' THEN
      SELECT COALESCE(ARRAY_AGG(DISTINCT new_rows.timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM new_rows
      WHERE new_rows.timesheet_id IS NOT NULL;
    ELSIF TG_OP = 'UPDATE' THEN
      SELECT COALESCE(ARRAY_AGG(DISTINCT new_rows.timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM new_rows
      JOIN old_rows
        ON old_rows.timesheet_id = new_rows.timesheet_id
      WHERE new_rows.timesheet_id IS NOT NULL
        AND (
          new_rows.last_settled_snapshot_json IS DISTINCT FROM old_rows.last_settled_snapshot_json
          OR new_rows.last_settled_signature IS DISTINCT FROM old_rows.last_settled_signature
          OR new_rows.last_settled_pay_batch_id IS DISTINCT FROM old_rows.last_settled_pay_batch_id
          OR new_rows.last_settled_at_utc IS DISTINCT FROM old_rows.last_settled_at_utc
        );
    ELSE
      SELECT COALESCE(ARRAY_AGG(DISTINCT old_rows.timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM old_rows
      WHERE old_rows.timesheet_id IS NOT NULL;
    END IF;

  ELSIF TG_TABLE_NAME = 'timesheet_pay_state_history' THEN
    IF TG_OP = 'INSERT' THEN
      SELECT COALESCE(ARRAY_AGG(DISTINCT new_rows.timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM new_rows
      WHERE new_rows.timesheet_id IS NOT NULL;
    ELSIF TG_OP = 'UPDATE' THEN
      WITH changed_history AS (
        SELECT
          new_rows.timesheet_id AS new_timesheet_id,
          old_rows.timesheet_id AS old_timesheet_id
        FROM new_rows
        JOIN old_rows ON old_rows.id = new_rows.id
        WHERE new_rows.timesheet_id IS DISTINCT FROM old_rows.timesheet_id
           OR new_rows.pay_batch_id IS DISTINCT FROM old_rows.pay_batch_id
           OR new_rows.settled_at_utc IS DISTINCT FROM old_rows.settled_at_utc
           OR new_rows.snapshot_json IS DISTINCT FROM old_rows.snapshot_json
           OR new_rows.signature IS DISTINCT FROM old_rows.signature
      )
      SELECT COALESCE(ARRAY_AGG(DISTINCT affected_rows.timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM (
        SELECT changed_history.new_timesheet_id AS timesheet_id
        FROM changed_history
        WHERE changed_history.new_timesheet_id IS NOT NULL

        UNION

        SELECT changed_history.old_timesheet_id AS timesheet_id
        FROM changed_history
        WHERE changed_history.old_timesheet_id IS NOT NULL
      ) AS affected_rows;
    ELSE
      SELECT COALESCE(ARRAY_AGG(DISTINCT old_rows.timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM old_rows
      WHERE old_rows.timesheet_id IS NOT NULL;
    END IF;

  ELSIF TG_TABLE_NAME = 'pay_batch_items' THEN
    IF TG_OP = 'UPDATE' THEN
      SELECT COALESCE(ARRAY_AGG(DISTINCT affected_rows.timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM (
        SELECT new_rows.timesheet_id
        FROM new_rows
        JOIN old_rows ON old_rows.id = new_rows.id
        WHERE new_rows.timesheet_id IS NOT NULL
          AND (
            new_rows.timesheet_id IS DISTINCT FROM old_rows.timesheet_id
            OR new_rows.is_voided IS DISTINCT FROM old_rows.is_voided
          )

        UNION

        SELECT old_rows.timesheet_id
        FROM old_rows
        JOIN new_rows ON new_rows.id = old_rows.id
        WHERE old_rows.timesheet_id IS NOT NULL
          AND old_rows.timesheet_id IS DISTINCT FROM new_rows.timesheet_id
      ) AS affected_rows;
    ELSE
      SELECT COALESCE(ARRAY_AGG(DISTINCT old_rows.timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM old_rows
      WHERE old_rows.timesheet_id IS NOT NULL;
    END IF;

  ELSIF TG_TABLE_NAME = 'pay_batch_candidates' THEN
    WITH changed_candidates AS (
      SELECT new_rows.id
      FROM new_rows
      JOIN old_rows ON old_rows.id = new_rows.id
      WHERE new_rows.settlement_status IS DISTINCT FROM old_rows.settlement_status
         OR new_rows.settled_at_utc IS DISTINCT FROM old_rows.settled_at_utc
         OR new_rows.pay_batch_id IS DISTINCT FROM old_rows.pay_batch_id
    )
    SELECT COALESCE(ARRAY_AGG(DISTINCT batch_item.timesheet_id), ARRAY[]::uuid[])
    INTO v_timesheet_ids
    FROM changed_candidates
    JOIN public.pay_batch_items AS batch_item
      ON batch_item.pay_batch_candidate_id = changed_candidates.id
    WHERE batch_item.timesheet_id IS NOT NULL;

  ELSIF TG_TABLE_NAME = 'pay_batches' THEN
    WITH changed_batches AS (
      SELECT new_rows.id
      FROM new_rows
      JOIN old_rows ON old_rows.id = new_rows.id
      WHERE public._pay_batch_status_is_active_reservation(old_rows.status)
            IS DISTINCT FROM
            public._pay_batch_status_is_active_reservation(new_rows.status)
         OR new_rows.cancelled_at_utc IS DISTINCT FROM old_rows.cancelled_at_utc
         OR new_rows.completed_at_utc IS DISTINCT FROM old_rows.completed_at_utc
    )
    SELECT COALESCE(ARRAY_AGG(DISTINCT batch_item.timesheet_id), ARRAY[]::uuid[])
    INTO v_timesheet_ids
    FROM changed_batches
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.pay_batch_id = changed_batches.id
    JOIN public.pay_batch_items AS batch_item
      ON batch_item.pay_batch_candidate_id = batch_candidate.id
    WHERE batch_item.timesheet_id IS NOT NULL;

  ELSIF TG_TABLE_NAME = 'pay_bank_transfers' THEN
    WITH changed_transfers AS (
      SELECT new_rows.id
      FROM new_rows
      JOIN old_rows ON old_rows.id = new_rows.id
      WHERE new_rows.status IS DISTINCT FROM old_rows.status
         OR new_rows.rail_state IS DISTINCT FROM old_rows.rail_state
         OR new_rows.rail_meta_json IS DISTINCT FROM old_rows.rail_meta_json
         OR new_rows.completed_at_utc IS DISTINCT FROM old_rows.completed_at_utc
    )
    SELECT COALESCE(ARRAY_AGG(DISTINCT batch_item.timesheet_id), ARRAY[]::uuid[])
    INTO v_timesheet_ids
    FROM changed_transfers
    JOIN public.pay_batch_items AS batch_item
      ON batch_item.pay_bank_transfer_id = changed_transfers.id
    WHERE batch_item.timesheet_id IS NOT NULL;

  ELSIF TG_TABLE_NAME = 'pay_payment_correction_items' THEN
    IF TG_OP = 'INSERT' THEN
      SELECT COALESCE(ARRAY_AGG(DISTINCT COALESCE(new_rows.timesheet_id, batch_item.timesheet_id)), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM new_rows
      LEFT JOIN public.pay_batch_items AS batch_item
        ON batch_item.id = new_rows.pay_batch_item_id
      WHERE COALESCE(new_rows.timesheet_id, batch_item.timesheet_id) IS NOT NULL;
    ELSIF TG_OP = 'UPDATE' THEN
      WITH changed_correction_rows AS (
        SELECT
          new_rows.timesheet_id AS new_timesheet_id,
          new_rows.pay_batch_item_id AS new_pay_batch_item_id,
          old_rows.timesheet_id AS old_timesheet_id,
          old_rows.pay_batch_item_id AS old_pay_batch_item_id
        FROM new_rows
        JOIN old_rows ON old_rows.id = new_rows.id
        WHERE new_rows.timesheet_id IS DISTINCT FROM old_rows.timesheet_id
           OR new_rows.pay_batch_item_id IS DISTINCT FROM old_rows.pay_batch_item_id
           OR new_rows.correction_request_id IS DISTINCT FROM old_rows.correction_request_id
           OR new_rows.status IS DISTINCT FROM old_rows.status
           OR new_rows.correction_item_kind IS DISTINCT FROM old_rows.correction_item_kind
      ),
      correction_rows AS (
        SELECT
          changed_correction_rows.new_timesheet_id AS timesheet_id,
          changed_correction_rows.new_pay_batch_item_id AS pay_batch_item_id
        FROM changed_correction_rows

        UNION ALL

        SELECT
          changed_correction_rows.old_timesheet_id AS timesheet_id,
          changed_correction_rows.old_pay_batch_item_id AS pay_batch_item_id
        FROM changed_correction_rows
      )
      SELECT COALESCE(ARRAY_AGG(DISTINCT COALESCE(correction_rows.timesheet_id, batch_item.timesheet_id)), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM correction_rows
      LEFT JOIN public.pay_batch_items AS batch_item
        ON batch_item.id = correction_rows.pay_batch_item_id
      WHERE COALESCE(correction_rows.timesheet_id, batch_item.timesheet_id) IS NOT NULL;
    ELSE
      SELECT COALESCE(ARRAY_AGG(DISTINCT COALESCE(old_rows.timesheet_id, batch_item.timesheet_id)), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM old_rows
      LEFT JOIN public.pay_batch_items AS batch_item
        ON batch_item.id = old_rows.pay_batch_item_id
      WHERE COALESCE(old_rows.timesheet_id, batch_item.timesheet_id) IS NOT NULL;
    END IF;

  ELSIF TG_TABLE_NAME = 'pay_payment_correction_requests' THEN
    IF TG_OP = 'INSERT' THEN
      WITH changed_batches AS (
        SELECT new_rows.pay_batch_id
        FROM new_rows
        WHERE new_rows.pay_batch_id IS NOT NULL
      )
      SELECT COALESCE(ARRAY_AGG(DISTINCT batch_item.timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM changed_batches
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.pay_batch_id = changed_batches.pay_batch_id
      JOIN public.pay_batch_items AS batch_item
        ON batch_item.pay_batch_candidate_id = batch_candidate.id
      WHERE batch_item.timesheet_id IS NOT NULL;
    ELSIF TG_OP = 'UPDATE' THEN
      WITH changed_batches AS (
        SELECT new_rows.pay_batch_id
        FROM new_rows
        JOIN old_rows ON old_rows.id = new_rows.id
        WHERE new_rows.pay_batch_id IS DISTINCT FROM old_rows.pay_batch_id
           OR new_rows.status IS DISTINCT FROM old_rows.status
        UNION
        SELECT old_rows.pay_batch_id
        FROM old_rows
        JOIN new_rows ON new_rows.id = old_rows.id
        WHERE new_rows.pay_batch_id IS DISTINCT FROM old_rows.pay_batch_id
           OR new_rows.status IS DISTINCT FROM old_rows.status
      )
      SELECT COALESCE(ARRAY_AGG(DISTINCT batch_item.timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM changed_batches
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.pay_batch_id = changed_batches.pay_batch_id
      JOIN public.pay_batch_items AS batch_item
        ON batch_item.pay_batch_candidate_id = batch_candidate.id
      WHERE batch_item.timesheet_id IS NOT NULL;
    ELSE
      WITH changed_batches AS (
        SELECT old_rows.pay_batch_id
        FROM old_rows
        WHERE old_rows.pay_batch_id IS NOT NULL
      )
      SELECT COALESCE(ARRAY_AGG(DISTINCT batch_item.timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM changed_batches
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.pay_batch_id = changed_batches.pay_batch_id
      JOIN public.pay_batch_items AS batch_item
        ON batch_item.pay_batch_candidate_id = batch_candidate.id
      WHERE batch_item.timesheet_id IS NOT NULL;
    END IF;

  ELSIF TG_TABLE_NAME = 'pay_finance_case_components' THEN
    IF TG_OP = 'INSERT' THEN
      SELECT COALESCE(ARRAY_AGG(DISTINCT new_rows.linked_timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM new_rows
      WHERE new_rows.linked_timesheet_id IS NOT NULL;
    ELSIF TG_OP = 'UPDATE' THEN
      WITH changed_components AS (
        SELECT
          new_rows.linked_timesheet_id AS new_timesheet_id,
          old_rows.linked_timesheet_id AS old_timesheet_id
        FROM new_rows
        JOIN old_rows ON old_rows.id = new_rows.id
        WHERE new_rows.linked_timesheet_id IS DISTINCT FROM old_rows.linked_timesheet_id
           OR new_rows.finance_case_id IS DISTINCT FROM old_rows.finance_case_id
           OR new_rows.component_key_type IS DISTINCT FROM old_rows.component_key_type
           OR new_rows.component_key_value IS DISTINCT FROM old_rows.component_key_value
           OR new_rows.source_basis_json IS DISTINCT FROM old_rows.source_basis_json
           OR new_rows.remaining_source_amount IS DISTINCT FROM old_rows.remaining_source_amount
           OR new_rows.closed_at_utc IS DISTINCT FROM old_rows.closed_at_utc
      )
      SELECT COALESCE(ARRAY_AGG(DISTINCT affected_rows.timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM (
        SELECT changed_components.new_timesheet_id AS timesheet_id
        FROM changed_components
        WHERE changed_components.new_timesheet_id IS NOT NULL

        UNION

        SELECT changed_components.old_timesheet_id AS timesheet_id
        FROM changed_components
        WHERE changed_components.old_timesheet_id IS NOT NULL
      ) AS affected_rows;
    ELSE
      SELECT COALESCE(ARRAY_AGG(DISTINCT old_rows.linked_timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM old_rows
      WHERE old_rows.linked_timesheet_id IS NOT NULL;
    END IF;

  ELSIF TG_TABLE_NAME = 'pay_advances' THEN
    WITH changed_advances AS (
      SELECT
        new_rows.id AS new_id,
        new_rows.linked_timesheet_id AS new_linked_timesheet_id,
        old_rows.id AS old_id,
        old_rows.linked_timesheet_id AS old_linked_timesheet_id
      FROM new_rows
      JOIN old_rows ON old_rows.id = new_rows.id
      WHERE new_rows.linked_timesheet_id IS DISTINCT FROM old_rows.linked_timesheet_id
         OR new_rows.case_type IS DISTINCT FROM old_rows.case_type
    ),
    advance_ids AS (
      SELECT
        changed_advances.new_id AS id,
        changed_advances.new_linked_timesheet_id AS linked_timesheet_id
      FROM changed_advances

      UNION

      SELECT
        changed_advances.old_id AS id,
        changed_advances.old_linked_timesheet_id AS linked_timesheet_id
      FROM changed_advances
    )
    SELECT COALESCE(ARRAY_AGG(DISTINCT affected_rows.timesheet_id), ARRAY[]::uuid[])
    INTO v_timesheet_ids
    FROM (
      SELECT advance_ids.linked_timesheet_id AS timesheet_id
      FROM advance_ids
      WHERE advance_ids.linked_timesheet_id IS NOT NULL

      UNION

      SELECT finance_component.linked_timesheet_id AS timesheet_id
      FROM advance_ids
      JOIN public.pay_finance_case_components AS finance_component
        ON finance_component.finance_case_id = advance_ids.id
      WHERE finance_component.linked_timesheet_id IS NOT NULL
    ) AS affected_rows;

  ELSIF TG_TABLE_NAME = 'ts_pay_adjustments' THEN
    IF TG_OP = 'INSERT' THEN
      SELECT COALESCE(ARRAY_AGG(DISTINCT new_rows.timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM new_rows
      WHERE new_rows.timesheet_id IS NOT NULL;
    ELSIF TG_OP = 'UPDATE' THEN
      WITH changed_adjustments AS (
        SELECT
          new_rows.timesheet_id AS new_timesheet_id,
          old_rows.timesheet_id AS old_timesheet_id
        FROM new_rows
        JOIN old_rows ON old_rows.id = new_rows.id
        WHERE new_rows.timesheet_id IS DISTINCT FROM old_rows.timesheet_id
           OR new_rows.delta_pay_ex_vat IS DISTINCT FROM old_rows.delta_pay_ex_vat
           OR new_rows.as_advance IS DISTINCT FROM old_rows.as_advance
      )
      SELECT COALESCE(ARRAY_AGG(DISTINCT affected_rows.timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM (
        SELECT changed_adjustments.new_timesheet_id AS timesheet_id
        FROM changed_adjustments
        WHERE changed_adjustments.new_timesheet_id IS NOT NULL

        UNION

        SELECT changed_adjustments.old_timesheet_id AS timesheet_id
        FROM changed_adjustments
        WHERE changed_adjustments.old_timesheet_id IS NOT NULL
      ) AS affected_rows;
    ELSE
      SELECT COALESCE(ARRAY_AGG(DISTINCT old_rows.timesheet_id), ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM old_rows
      WHERE old_rows.timesheet_id IS NOT NULL;
    END IF;
  END IF;

  SELECT COALESCE(
    ARRAY_AGG(DISTINCT input_ids.timesheet_id ORDER BY input_ids.timesheet_id),
    ARRAY[]::uuid[]
  )
  INTO v_timesheet_ids
  FROM UNNEST(COALESCE(v_timesheet_ids, ARRAY[]::uuid[])) AS input_ids(timesheet_id)
  WHERE input_ids.timesheet_id IS NOT NULL;

  v_total := COALESCE(CARDINALITY(v_timesheet_ids), 0);

  IF v_total>0 AND NOT (
       to_regclass('pg_temp._bpay_wb_sync_context_v1') IS NOT NULL
       AND COALESCE(current_setting('cloudtms.pay_workbench_overpayment_sync_token',true),'')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     ) THEN
    WITH resolved AS (
      SELECT DISTINCT COALESCE(scope_state.candidate_id,current_financial.candidate_id) candidate_id,
             input_id.timesheet_id
      FROM unnest(v_timesheet_ids) input_id(timesheet_id)
      LEFT JOIN private.banking_pay_workbench_timesheet_scope_state scope_state
        ON scope_state.timesheet_id=input_id.timesheet_id
      LEFT JOIN LATERAL (
        SELECT financial.candidate_id FROM public.timesheets_financials financial
        WHERE financial.timesheet_id=input_id.timesheet_id AND financial.is_current
        ORDER BY financial.id DESC LIMIT 1
      ) current_financial ON true
      WHERE COALESCE(scope_state.candidate_id,current_financial.candidate_id) IS NOT NULL
    )
    SELECT array_agg(candidate_id ORDER BY candidate_id,timesheet_id),
           array_agg(timesheet_id ORDER BY candidate_id,timesheet_id)
    INTO v_candidate_ids,v_invalidation_timesheet_ids FROM resolved;

    -- The correction-request transition relation is the strongest causal
    -- authority available: it proves that this exact statement, rather than a
    -- caller hint, caused the summary refresh.  Establish the candidate-keyed
    -- transaction-local envelope here.  The operation is intentionally
    -- optional on INSERT because request_start creates it immediately after the
    -- request row; the asynchronous dirty job cannot run before that commit.
    IF TG_TABLE_NAME='pay_payment_correction_requests'
       AND TG_OP IN ('INSERT','UPDATE')
       AND pg_catalog.cardinality(COALESCE(v_candidate_ids,ARRAY[]::uuid[]))>0 THEN
      IF TG_OP='INSERT' THEN
        SELECT request_transition.id,request_transition.pay_batch_id,
               request_transition.status,
               COALESCE(request_transition.selection_json,'{}'::jsonb),
               COALESCE(request_transition.plan_json,'{}'::jsonb)
        INTO v_correction_request_id,v_correction_pay_batch_id,
             v_correction_request_status,v_correction_selection_json,
             v_correction_plan_json
        FROM new_rows AS request_transition
        WHERE request_transition.id IS NOT NULL
        ORDER BY request_transition.id
        LIMIT 1;
      ELSE
        SELECT new_request.id,new_request.pay_batch_id,new_request.status,
               COALESCE(new_request.selection_json,'{}'::jsonb),
               COALESCE(new_request.plan_json,'{}'::jsonb)
        INTO v_correction_request_id,v_correction_pay_batch_id,
             v_correction_request_status,v_correction_selection_json,
             v_correction_plan_json
        FROM new_rows AS new_request
        JOIN old_rows AS old_request ON old_request.id=new_request.id
        WHERE new_request.pay_batch_id IS DISTINCT FROM old_request.pay_batch_id
           OR new_request.status IS DISTINCT FROM old_request.status
        ORDER BY new_request.id
        LIMIT 1;
      END IF;

      IF v_correction_request_id IS NOT NULL
         AND v_correction_pay_batch_id IS NOT NULL THEN
        SELECT operation_row.id
        INTO v_correction_operation_id
        FROM public.banking_pay_operations AS operation_row
        WHERE operation_row.operation_type='PAYMENT_CORRECTION'
          AND operation_row.input_json->>'correction_request_id'
                =v_correction_request_id::text
        ORDER BY operation_row.created_at_utc DESC,operation_row.id DESC
        LIMIT 1;

        v_correction_lifecycle_phase:=CASE
          WHEN pg_catalog.upper(pg_catalog.btrim(COALESCE(
                 v_correction_request_status,''
               ))) IN ('AUTHORISED','EXPANDED','PROCESSING','APPLIED','APPLIED_WITH_BLOCKERS')
            THEN 'REQUEST_START'
          ELSE 'REQUEST_PREPARE'
        END;

        PERFORM private.pay_workbench_correction_dirty_context_set_v1(
          p_correction_request_id:=v_correction_request_id,
          p_pay_batch_id:=v_correction_pay_batch_id,
          p_candidate_ids:=v_candidate_ids,
          p_lifecycle_phase:=v_correction_lifecycle_phase,
          p_policy_x_boundary:='POST_DRAFT_FROZEN_EVIDENCE',
          p_pre_request_authorities_json:=COALESCE(
            v_correction_selection_json->'draft_overlay_fast_pre_request_authorities',
            '{}'::jsonb
          ),
          p_operation_id:=v_correction_operation_id,
          p_work_item_id:=NULL::uuid,
          p_options_json:=pg_catalog.jsonb_build_object(
            'trigger_table',TG_TABLE_NAME,
            'trigger_operation',TG_OP,
            'request_status',v_correction_request_status,
            'requested_action',v_correction_plan_json->>'requested_action'
          )
        );
      END IF;
    END IF;

    -- A correction request may affect a subset of a statement.  Copy its exact
    -- candidate-keyed causal envelope into the durable invalidation payload,
    -- while retaining every other candidate in the normal invalidation.  A
    -- mixed statement must never suppress an unrelated economic change.
    IF pg_catalog.to_regclass('pg_temp._bpay_wb_correction_dirty_context_v1') IS NOT NULL
       AND pg_catalog.cardinality(COALESCE(v_candidate_ids,ARRAY[]::uuid[]))>0 THEN
      EXECUTE $context$
        SELECT COALESCE(
          pg_catalog.jsonb_object_agg(
            context_row.candidate_id::text,
            pg_catalog.to_jsonb(context_row)-'created_at_utc'
            ORDER BY context_row.candidate_id
          ),
          '{}'::jsonb
        )
        FROM pg_temp._bpay_wb_correction_dirty_context_v1 AS context_row
        WHERE context_row.candidate_id=ANY($1)
      $context$
      INTO v_correction_dirty_contexts
      USING v_candidate_ids;

      IF v_correction_dirty_contexts<>'{}'::jsonb THEN
        v_scope_change_tx_token:=public.pay_workbench_scope_change_tx_token_v1();
      END IF;
    END IF;

    IF cardinality(COALESCE(v_candidate_ids,ARRAY[]::uuid[]))>0 THEN
      v_scope_invalidation_result:=private.pay_workbench_scope_invalidate_v1(
        v_candidate_ids,v_invalidation_timesheet_ids,
        'DIRTY_TRIGGER:'||upper(TG_TABLE_NAME)||':'||TG_OP,v_scope_change_tx_token,
        jsonb_strip_nulls(jsonb_build_object(
          'trigger_table',TG_TABLE_NAME,
          'trigger_operation',TG_OP,
          'correction_dirty_contexts',CASE
            WHEN v_correction_dirty_contexts<>'{}'::jsonb
              THEN v_correction_dirty_contexts ELSE NULL::jsonb END,
          'request_owned_scope_change_tx_token',CASE
            WHEN v_correction_dirty_contexts<>'{}'::jsonb
              THEN v_scope_change_tx_token ELSE NULL::uuid END,
          'correction_dirty_causal_contract_version',CASE
            WHEN v_correction_dirty_contexts<>'{}'::jsonb
              THEN 'CORRECTION_OWNED_DIRTY_CAUSAL_V1' ELSE NULL::text END
        ))
      );
    END IF;
  END IF;

  PERFORM public._temp_diag_log(
    'TEMP_SUMMARY_REFRESH_STAGE',
    'TEMP_SUMMARY_REFRESH',
    CASE WHEN v_total > 0 THEN v_timesheet_ids[1]::text ELSE NULL::text END,
    jsonb_build_object(
      'function_name', 'pay_timesheet_summary_pay_state_refresh_trigger',
      'stage', 'timesheet_ids_collected',
      'trigger_table', TG_TABLE_NAME,
      'trigger_op', TG_OP,
      'targeted_timesheet_count', v_total,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  v_offset := 1;

  WHILE v_offset <= v_total LOOP
    SELECT COALESCE(
      ARRAY_AGG(chunk_rows.timesheet_id ORDER BY chunk_rows.ordinality),
      ARRAY[]::uuid[]
    )
    INTO v_chunk_ids
    FROM UNNEST(v_timesheet_ids) WITH ORDINALITY AS chunk_rows(timesheet_id, ordinality)
    WHERE chunk_rows.ordinality BETWEEN v_offset AND v_offset + 99;

    v_chunk_started_at := clock_timestamp();

    PERFORM public._temp_diag_log(
      'TEMP_SUMMARY_REFRESH_STAGE',
      'TEMP_SUMMARY_REFRESH',
      CASE WHEN COALESCE(CARDINALITY(v_chunk_ids), 0) > 0 THEN v_chunk_ids[1]::text ELSE NULL::text END,
      jsonb_build_object(
        'function_name', 'pay_timesheet_summary_pay_state_refresh_trigger',
        'stage', 'chunk_refresh_start',
        'trigger_table', TG_TABLE_NAME,
        'trigger_op', TG_OP,
        'targeted_timesheet_count', COALESCE(CARDINALITY(v_chunk_ids), 0),
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
      )
    );

    v_refresh_result := public.pay_timesheet_summary_pay_state_refresh(
      p_timesheet_ids => v_chunk_ids,
      p_actor_user_id => NULL::uuid
    );

    PERFORM public._temp_diag_log(
      'TEMP_SUMMARY_REFRESH_STAGE',
      'TEMP_SUMMARY_REFRESH',
      CASE WHEN COALESCE(CARDINALITY(v_chunk_ids), 0) > 0 THEN v_chunk_ids[1]::text ELSE NULL::text END,
      jsonb_build_object(
        'function_name', 'pay_timesheet_summary_pay_state_refresh_trigger',
        'stage', 'chunk_refresh_done',
        'trigger_table', TG_TABLE_NAME,
        'trigger_op', TG_OP,
        'targeted_timesheet_count', COALESCE(CARDINALITY(v_chunk_ids), 0),
        'refresh_result', COALESCE(v_refresh_result, '{}'::jsonb),
        'chunk_elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_chunk_started_at)) * 1000)::numeric, 2),
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
      )
    );

    v_offset := v_offset + 100;
  END LOOP;

  PERFORM public._temp_diag_log(
    'TEMP_SUMMARY_REFRESH_STAGE',
    'TEMP_SUMMARY_REFRESH',
    CASE WHEN v_total > 0 THEN v_timesheet_ids[1]::text ELSE NULL::text END,
    jsonb_build_object(
      'function_name', 'pay_timesheet_summary_pay_state_refresh_trigger',
      'stage', 'return',
      'trigger_table', TG_TABLE_NAME,
      'trigger_op', TG_OP,
      'targeted_timesheet_count', v_total,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  RETURN NULL;
END;
$function$;

-- pay_timesheet_summary_pay_state_refresh(uuid[],uuid)
CREATE OR REPLACE FUNCTION public.pay_timesheet_summary_pay_state_refresh(p_timesheet_ids uuid[], p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_requested_ids uuid[] := ARRAY[]::uuid[];
  v_target_ids uuid[] := ARRAY[]::uuid[];
  v_refreshed_count integer := 0;
  v_legacy_state_rows_updated integer := 0;
  v_diag_started_at timestamptz := clock_timestamp();
  v_summary_refresh_mode text := LOWER(BTRIM(COALESCE(current_setting('cloudtms.summary_refresh_mode', true), '')));
  v_lifecycle_context text := LOWER(BTRIM(COALESCE(current_setting('cloudtms.lifecycle_mutation_context', true), '')));
  v_lifecycle_defer_summary_refresh boolean := COALESCE(current_setting('cloudtms.lifecycle_defer_summary_refresh', true), '') = 'on';
  v_lightweight_result jsonb := '{}'::jsonb;
  v_lightweight_fallback_used boolean := false;
BEGIN
  PERFORM public._temp_diag_log(
    'TEMP_SUMMARY_REFRESH_STAGE',
    'TEMP_SUMMARY_REFRESH',
    CASE WHEN COALESCE(CARDINALITY(p_timesheet_ids), 0) > 0 THEN p_timesheet_ids[1]::text ELSE NULL::text END,
    jsonb_build_object(
      'function_name', 'pay_timesheet_summary_pay_state_refresh',
      'stage', 'entry',
      'requested_count_raw', COALESCE(CARDINALITY(p_timesheet_ids), 0),
      'summary_refresh_mode', NULLIF(v_summary_refresh_mode, ''),
      'mutation_context', NULLIF(v_lifecycle_context, ''),
      'lifecycle_defer_summary_refresh', v_lifecycle_defer_summary_refresh,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  SELECT COALESCE(
    ARRAY_AGG(DISTINCT input_rows.timesheet_id ORDER BY input_rows.timesheet_id),
    ARRAY[]::uuid[]
  )
  INTO v_requested_ids
  FROM UNNEST(COALESCE(p_timesheet_ids, ARRAY[]::uuid[])) AS input_rows(timesheet_id)
  WHERE input_rows.timesheet_id IS NOT NULL;

  PERFORM public._temp_diag_log(
    'TEMP_SUMMARY_REFRESH_STAGE',
    'TEMP_SUMMARY_REFRESH',
    CASE WHEN COALESCE(CARDINALITY(v_requested_ids), 0) > 0 THEN v_requested_ids[1]::text ELSE NULL::text END,
    jsonb_build_object(
      'function_name', 'pay_timesheet_summary_pay_state_refresh',
      'stage', 'requested_ids_normalised',
      'requested_count', COALESCE(CARDINALITY(v_requested_ids), 0),
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  IF COALESCE(CARDINALITY(v_requested_ids), 0) = 0 THEN
    PERFORM public._temp_diag_log(
      'TEMP_SUMMARY_REFRESH_STAGE',
      'TEMP_SUMMARY_REFRESH',
      NULL::text,
      jsonb_build_object(
        'function_name', 'pay_timesheet_summary_pay_state_refresh',
        'stage', 'return_zero_requested',
        'requested_count', 0,
        'target_count', 0,
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
      )
    );

    RETURN jsonb_build_object(
      'ok', true,
      'requested_count', 0,
      'target_count', 0,
      'refreshed_count', 0,
      'legacy_state_rows_updated', 0
    );
  END IF;

  IF CARDINALITY(v_requested_ids) > 100 THEN
    RAISE EXCEPTION 'pay_timesheet_summary_pay_state_refresh accepts at most 100 distinct timesheet ids per call';
  END IF;

  SELECT COALESCE(
    ARRAY_AGG(DISTINCT resolved_rows.target_timesheet_id ORDER BY resolved_rows.target_timesheet_id),
    ARRAY[]::uuid[]
  )
  INTO v_target_ids
  FROM (
    SELECT
      COALESCE(
        rotation_rows.canonical_timesheet_id,
        rotation_rows.requested_timesheet_id
      ) AS target_timesheet_id
    FROM public._pay_timesheet_rotation_scope(v_requested_ids) AS rotation_rows
  ) AS resolved_rows
  JOIN public.timesheets AS target_timesheet
    ON target_timesheet.timesheet_id = resolved_rows.target_timesheet_id
  WHERE resolved_rows.target_timesheet_id IS NOT NULL;

  PERFORM public._temp_diag_log(
    'TEMP_SUMMARY_REFRESH_STAGE',
    'TEMP_SUMMARY_REFRESH',
    CASE WHEN COALESCE(CARDINALITY(v_requested_ids), 0) > 0 THEN v_requested_ids[1]::text ELSE NULL::text END,
    jsonb_build_object(
      'function_name', 'pay_timesheet_summary_pay_state_refresh',
      'stage', 'rotation_scope_done',
      'requested_count', COALESCE(CARDINALITY(v_requested_ids), 0),
      'target_count', COALESCE(CARDINALITY(v_target_ids), 0),
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  IF COALESCE(CARDINALITY(v_target_ids), 0) = 0 THEN
    PERFORM public._temp_diag_log(
      'TEMP_SUMMARY_REFRESH_STAGE',
      'TEMP_SUMMARY_REFRESH',
      CASE WHEN COALESCE(CARDINALITY(v_requested_ids), 0) > 0 THEN v_requested_ids[1]::text ELSE NULL::text END,
      jsonb_build_object(
        'function_name', 'pay_timesheet_summary_pay_state_refresh',
        'stage', 'return_zero_target',
        'requested_count', COALESCE(CARDINALITY(v_requested_ids), 0),
        'target_count', 0,
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
      )
    );

    RETURN jsonb_build_object(
      'ok', true,
      'requested_count', CARDINALITY(v_requested_ids),
      'target_count', 0,
      'refreshed_count', 0,
      'legacy_state_rows_updated', 0
    );
  END IF;

  IF v_summary_refresh_mode IN ('ordinary_manual_save_lightweight', 'manual_save_lightweight', 'lightweight_manual_save')
     OR (v_lifecycle_context = 'manual_timesheet_save' AND v_lifecycle_defer_summary_refresh IS TRUE) THEN
    v_lightweight_result := public.pay_timesheet_summary_pay_state_patch_lightweight(
      p_timesheet_ids => v_target_ids,
      p_actor_user_id => p_actor_user_id,
      p_reason => 'ordinary_manual_save'
    );

    IF COALESCE((v_lightweight_result ->> 'fallback_required')::boolean, false) IS NOT TRUE THEN
      PERFORM public._temp_diag_log(
        'TEMP_SUMMARY_REFRESH_STAGE',
        'TEMP_SUMMARY_REFRESH',
        CASE WHEN COALESCE(CARDINALITY(v_target_ids), 0) > 0 THEN v_target_ids[1]::text ELSE NULL::text END,
        jsonb_build_object(
          'function_name', 'pay_timesheet_summary_pay_state_refresh',
          'stage', 'lightweight_patch_done',
          'requested_count', COALESCE(CARDINALITY(v_requested_ids), 0),
          'target_count', COALESCE(CARDINALITY(v_target_ids), 0),
          'summary_refresh_mode', NULLIF(v_summary_refresh_mode, ''),
          'mutation_context', NULLIF(v_lifecycle_context, ''),
          'lightweight_result', v_lightweight_result,
          'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
        )
      );

      RETURN jsonb_build_object(
        'ok', true,
        'mode', 'ordinary_manual_save_lightweight',
        'requested_count', CARDINALITY(v_requested_ids),
        'target_count', CARDINALITY(v_target_ids),
        'refreshed_count', COALESCE((v_lightweight_result ->> 'patched_count')::integer, 0),
        'legacy_state_rows_updated', COALESCE((v_lightweight_result ->> 'legacy_state_rows_updated')::integer, 0),
        'lightweight_result', COALESCE(v_lightweight_result, '{}'::jsonb)
      );
    END IF;

    PERFORM public._temp_diag_log(
      'TEMP_SUMMARY_REFRESH_STAGE',
      'TEMP_SUMMARY_REFRESH',
      CASE WHEN COALESCE(CARDINALITY(v_target_ids), 0) > 0 THEN v_target_ids[1]::text ELSE NULL::text END,
      jsonb_build_object(
        'function_name', 'pay_timesheet_summary_pay_state_refresh',
        'stage', 'lightweight_patch_fallback_deferred',
        'requested_count', COALESCE(CARDINALITY(v_requested_ids), 0),
        'target_count', COALESCE(CARDINALITY(v_target_ids), 0),
        'summary_refresh_mode', NULLIF(v_summary_refresh_mode, ''),
        'mutation_context', NULLIF(v_lifecycle_context, ''),
        'fallback_required', true,
        'fallback_deferred', true,
        'fallback_reason_codes', COALESCE(v_lightweight_result -> 'fallback_reason_codes', '[]'::jsonb),
        'lightweight_result', v_lightweight_result,
        'policy_x_authority_scope', 'MANUAL_SAVE_MODAL_FULL_SUMMARY_REFRESH_DEFERRED',
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
      )
    );

    RETURN jsonb_build_object(
      'ok', true,
      'mode', 'ordinary_manual_save_lightweight',
      'requested_count', CARDINALITY(v_requested_ids),
      'target_count', CARDINALITY(v_target_ids),
      'refreshed_count', 0,
      'legacy_state_rows_updated', 0,
      'fallback_required', true,
      'fallback_deferred', true,
      'deferred_full_refresh_required', true,
      'fallback_reason_codes', COALESCE(v_lightweight_result -> 'fallback_reason_codes', '[]'::jsonb),
      'lightweight_result', COALESCE(v_lightweight_result, '{}'::jsonb)
    );
  END IF;

  WITH
  target_ids AS MATERIALIZED (
    SELECT target_values.timesheet_id
    FROM UNNEST(v_target_ids) AS target_values(timesheet_id)
  ),
  target_id_array AS MATERIALIZED (
    SELECT ARRAY_AGG(target_ids.timesheet_id ORDER BY target_ids.timesheet_id) AS timesheet_ids
    FROM target_ids
  ),
  family_scope AS MATERIALIZED (
    SELECT DISTINCT
      rotation_rows.family_timesheet_id,
      COALESCE(
        rotation_rows.canonical_timesheet_id,
        rotation_rows.requested_timesheet_id
      ) AS projected_timesheet_id
    FROM target_id_array
    CROSS JOIN LATERAL public._pay_timesheet_rotation_scope(
      target_id_array.timesheet_ids
    ) AS rotation_rows
    WHERE rotation_rows.family_timesheet_id IS NOT NULL
      AND COALESCE(
        rotation_rows.canonical_timesheet_id,
        rotation_rows.requested_timesheet_id
      ) IS NOT NULL
  ),
  outstanding_components AS MATERIALIZED (
    SELECT
      outstanding_rows.timesheet_id,
      outstanding_rows.truth_ex_vat,
      outstanding_rows.baseline_ex_vat,
      outstanding_rows.reserved_ex_vat,
      outstanding_rows.outstanding_ex_vat
    FROM target_id_array
    CROSS JOIN LATERAL public._pay_outstanding_components(
      target_id_array.timesheet_ids
    ) AS outstanding_rows
  ),
  component_totals AS MATERIALIZED (
    SELECT
      target_ids.timesheet_id,
      ROUND(
        COALESCE(SUM(COALESCE(outstanding_components.baseline_ex_vat, 0)), 0),
        2
      )::numeric AS paid_to_date_ex_vat,
      ROUND(
        COALESCE(
          SUM(
            COALESCE(outstanding_components.truth_ex_vat, 0)
            - COALESCE(outstanding_components.baseline_ex_vat, 0)
          ),
          0
        ),
        2
      )::numeric AS net_delta_ex_vat,
      ROUND(
        COALESCE(SUM(COALESCE(outstanding_components.reserved_ex_vat, 0)), 0),
        2
      )::numeric AS reserved_ex_vat,
      ROUND(
        COALESCE(SUM(COALESCE(outstanding_components.outstanding_ex_vat, 0)), 0),
        2
      )::numeric AS outstanding_ex_vat
    FROM target_ids
    LEFT JOIN outstanding_components
      ON outstanding_components.timesheet_id = target_ids.timesheet_id
    GROUP BY target_ids.timesheet_id
  ),
  legacy_state_presence AS MATERIALIZED (
    SELECT
      target_ids.timesheet_id,
      COALESCE(BOOL_OR(legacy_state.timesheet_id IS NOT NULL), false) AS has_legacy_pay_state
    FROM target_ids
    LEFT JOIN family_scope
      ON family_scope.projected_timesheet_id = target_ids.timesheet_id
    LEFT JOIN public.timesheet_pay_state AS legacy_state
      ON legacy_state.timesheet_id = family_scope.family_timesheet_id
    GROUP BY target_ids.timesheet_id
  ),
  actual_last_paid_totals AS MATERIALIZED (
    SELECT
      family_scope.projected_timesheet_id AS timesheet_id,
      MAX(
        GREATEST(
          paid_candidate.settled_at_utc,
          paid_transfer.completed_at_utc,
          paid_history.settled_at_utc,
          paid_batch.completed_at_utc
        )
      ) AS last_paid_at_utc
    FROM family_scope
    JOIN public.pay_batch_items AS paid_item
      ON paid_item.timesheet_id = family_scope.family_timesheet_id
    JOIN public.pay_batch_candidates AS paid_candidate
      ON paid_candidate.id = paid_item.pay_batch_candidate_id
    JOIN public.pay_batches AS paid_batch
      ON paid_batch.id = paid_candidate.pay_batch_id
    LEFT JOIN public.pay_bank_transfers AS paid_transfer
      ON paid_transfer.id = paid_item.pay_bank_transfer_id
     AND paid_transfer.pay_batch_id = paid_batch.id
    LEFT JOIN public.timesheet_pay_state_history AS paid_history
      ON paid_history.pay_batch_id = paid_candidate.pay_batch_id
     AND paid_history.timesheet_id = paid_item.timesheet_id
    WHERE COALESCE(paid_item.is_voided, false) = false
      AND UPPER(BTRIM(COALESCE(paid_item.item_type, ''))) IN (
        'SEGMENT_DELTA',
        'EXPENSE_DELTA',
        'ADJUSTMENT_DELTA',
        'MILEAGE_DELTA'
      )
      AND (
        UPPER(BTRIM(COALESCE(paid_candidate.settlement_status, ''))) = 'SETTLED'
        OR paid_candidate.settled_at_utc IS NOT NULL
        OR UPPER(BTRIM(COALESCE(paid_transfer.status, ''))) = 'COMPLETED'
        OR paid_transfer.completed_at_utc IS NOT NULL
        OR paid_history.id IS NOT NULL
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS applied_correction
        WHERE applied_correction.pay_batch_item_id = paid_item.id
          AND applied_correction.status = 'APPLIED'
          AND applied_correction.correction_item_kind IN (
            'PRE_BANK_CANCEL',
            'NO_MONEY_UNWIND',
            'SETTLED_REVERSAL'
          )
      )
    GROUP BY family_scope.projected_timesheet_id
  ),
  legacy_last_paid_totals AS MATERIALIZED (
    SELECT
      target_ids.timesheet_id,
      MAX(
        COALESCE(
          legacy_state.last_settled_at_utc,
          legacy_state.summary_pay_paid_at_utc
        )
      ) AS last_paid_at_utc
    FROM target_ids
    LEFT JOIN family_scope
      ON family_scope.projected_timesheet_id = target_ids.timesheet_id
    LEFT JOIN public.timesheet_pay_state AS legacy_state
      ON legacy_state.timesheet_id = family_scope.family_timesheet_id
    GROUP BY target_ids.timesheet_id
  ),
  last_paid_totals AS MATERIALIZED (
    SELECT
      target_ids.timesheet_id,
      COALESCE(
        actual_last_paid_totals.last_paid_at_utc,
        legacy_last_paid_totals.last_paid_at_utc
      ) AS last_paid_at_utc
    FROM target_ids
    LEFT JOIN actual_last_paid_totals
      ON actual_last_paid_totals.timesheet_id = target_ids.timesheet_id
    LEFT JOIN legacy_last_paid_totals
      ON legacy_last_paid_totals.timesheet_id = target_ids.timesheet_id
  ),
  latest_advance_override AS MATERIALIZED (
    SELECT DISTINCT ON (family_scope.projected_timesheet_id)
      family_scope.projected_timesheet_id AS timesheet_id,
      payment_override.id AS override_id,
      payment_override.created_at_utc AS override_created_at_utc
    FROM family_scope
    JOIN public.timesheet_payment_overrides AS payment_override
      ON payment_override.timesheet_id = family_scope.family_timesheet_id
    WHERE payment_override.cleared_at_utc IS NULL
      AND UPPER(BTRIM(COALESCE(payment_override.override_type, ''))) = 'ADVANCE_THIS_PAYMENT'
    ORDER BY
      family_scope.projected_timesheet_id,
      payment_override.created_at_utc DESC,
      payment_override.id DESC
  ),
  current_authorisation_state AS MATERIALIZED (
    SELECT
      target_ids.timesheet_id,
      GREATEST(
        MAX(family_timesheet.authorised_at_server),
        MAX(family_timesheet.revoked_at),
        MAX(family_financial.authorised_at_utc)
      ) AS authorised_at_utc
    FROM target_ids
    LEFT JOIN family_scope
      ON family_scope.projected_timesheet_id = target_ids.timesheet_id
    LEFT JOIN public.timesheets AS family_timesheet
      ON family_timesheet.timesheet_id = family_scope.family_timesheet_id
    LEFT JOIN public.timesheets_financials AS family_financial
      ON family_financial.timesheet_id = family_scope.family_timesheet_id
    GROUP BY target_ids.timesheet_id
  ),
  existing_display_cache AS MATERIALIZED (
    SELECT
      target_ids.timesheet_id,
      MAX(existing_cache.advance_authorisation_consumed_at_utc) AS advance_authorisation_consumed_at_utc
    FROM target_ids
    LEFT JOIN family_scope
      ON family_scope.projected_timesheet_id = target_ids.timesheet_id
    LEFT JOIN public.timesheet_summary_pay_state_cache AS existing_cache
      ON existing_cache.timesheet_id = family_scope.family_timesheet_id
    GROUP BY target_ids.timesheet_id
  ),
  advance_state_prepared AS MATERIALIZED (
    SELECT
      target_ids.timesheet_id,
      latest_advance_override.override_created_at_utc,
      current_authorisation_state.authorised_at_utc,
      CASE
        WHEN latest_advance_override.override_created_at_utc IS NULL
          THEN existing_display_cache.advance_authorisation_consumed_at_utc
        WHEN existing_display_cache.advance_authorisation_consumed_at_utc
               >= latest_advance_override.override_created_at_utc
          THEN existing_display_cache.advance_authorisation_consumed_at_utc
        WHEN current_authorisation_state.authorised_at_utc
               >= latest_advance_override.override_created_at_utc
          THEN current_authorisation_state.authorised_at_utc
        ELSE NULL::timestamptz
      END AS advance_authorisation_consumed_at_utc
    FROM target_ids
    LEFT JOIN latest_advance_override
      ON latest_advance_override.timesheet_id = target_ids.timesheet_id
    LEFT JOIN current_authorisation_state
      ON current_authorisation_state.timesheet_id = target_ids.timesheet_id
    LEFT JOIN existing_display_cache
      ON existing_display_cache.timesheet_id = target_ids.timesheet_id
  ),
  advance_state AS MATERIALIZED (
    SELECT
      advance_state_prepared.timesheet_id,
      advance_state_prepared.override_created_at_utc,
      advance_state_prepared.advance_authorisation_consumed_at_utc,
      (
        advance_state_prepared.override_created_at_utc IS NOT NULL
        AND (
          advance_state_prepared.advance_authorisation_consumed_at_utc IS NULL
          OR advance_state_prepared.advance_authorisation_consumed_at_utc
               < advance_state_prepared.override_created_at_utc
        )
      ) AS active_advance
    FROM advance_state_prepared
  ),
  active_batch_processing AS MATERIALIZED (
    SELECT DISTINCT
      family_scope.projected_timesheet_id AS timesheet_id
    FROM family_scope
    JOIN public.pay_batch_items AS batch_item
      ON batch_item.timesheet_id = family_scope.family_timesheet_id
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = batch_item.pay_batch_candidate_id
    JOIN public.pay_batches AS pay_batch
      ON pay_batch.id = batch_candidate.pay_batch_id
    LEFT JOIN public.pay_bank_transfers AS bank_transfer
      ON bank_transfer.id = batch_item.pay_bank_transfer_id
     AND bank_transfer.pay_batch_id = pay_batch.id
    LEFT JOIN LATERAL public._pay_rail_state_money_movement_classify(
      bank_transfer.status,
      bank_transfer.rail_state,
      COALESCE(bank_transfer.rail_meta_json, '{}'::jsonb),
      COALESCE(bank_transfer.rail_meta_json, '{}'::jsonb)
    ) AS transfer_classifier
      ON bank_transfer.id IS NOT NULL
    WHERE COALESCE(batch_item.is_voided, false) = false
      AND UPPER(BTRIM(COALESCE(batch_item.item_type, ''))) IN (
        'SEGMENT_DELTA',
        'EXPENSE_DELTA',
        'ADJUSTMENT_DELTA',
        'MILEAGE_DELTA'
      )
      AND public._pay_batch_status_is_active_reservation(pay_batch.status)
      AND UPPER(BTRIM(COALESCE(batch_candidate.settlement_status, ''))) NOT IN (
        'SETTLED',
        'PAID',
        'CONFIRMED'
      )
      AND batch_candidate.settled_at_utc IS NULL
      AND COALESCE(transfer_classifier.is_final_money_moved, false) = false
      AND COALESCE(transfer_classifier.is_terminal_no_money, false) = false
      AND bank_transfer.completed_at_utc IS NULL
  ),
  active_correction_processing AS MATERIALIZED (
    SELECT DISTINCT
      family_scope.projected_timesheet_id AS timesheet_id
    FROM public.pay_payment_correction_items AS correction_item
    LEFT JOIN public.pay_batch_items AS correction_batch_item
      ON correction_batch_item.id = correction_item.pay_batch_item_id
    JOIN family_scope
      ON family_scope.family_timesheet_id = COALESCE(
        correction_item.timesheet_id,
        correction_batch_item.timesheet_id
      )
    JOIN public.pay_payment_correction_requests AS correction_request
      ON correction_request.id = correction_item.correction_request_id
    WHERE correction_request.status IN (
      'REQUESTED',
      'AWAITING_AUTHORISATION',
      'AUTHORISED',
      'EXPANDED',
      'PROCESSING',
      'BLOCKED'
    )
      AND correction_item.status NOT IN ('APPLIED', 'SKIPPED')
  ),
  calculated_state AS MATERIALIZED (
    SELECT
      target_ids.timesheet_id,
      COALESCE(component_totals.paid_to_date_ex_vat, 0)::numeric AS paid_to_date_ex_vat,
      last_paid_totals.last_paid_at_utc,
      COALESCE(component_totals.reserved_ex_vat, 0)::numeric AS reserved_ex_vat,
      COALESCE(component_totals.outstanding_ex_vat, 0)::numeric AS outstanding_ex_vat,
      COALESCE(component_totals.net_delta_ex_vat, 0)::numeric AS net_delta_ex_vat,
      COALESCE(advance_state.active_advance, false) AS active_advance,
      advance_state.override_created_at_utc AS advance_override_created_at_utc,
      advance_state.advance_authorisation_consumed_at_utc,
      (
        ABS(COALESCE(component_totals.reserved_ex_vat, 0)) > 0.01
        OR active_batch_processing.timesheet_id IS NOT NULL
        OR active_correction_processing.timesheet_id IS NOT NULL
      ) AS active_processing,
      (
        COALESCE(component_totals.net_delta_ex_vat, 0) < -0.01
        OR COALESCE(component_totals.outstanding_ex_vat, 0) < -0.01
      ) AS is_overpaid,
      COALESCE(legacy_state_presence.has_legacy_pay_state, false) AS has_legacy_pay_state
    FROM target_ids
    LEFT JOIN component_totals
      ON component_totals.timesheet_id = target_ids.timesheet_id
    LEFT JOIN last_paid_totals
      ON last_paid_totals.timesheet_id = target_ids.timesheet_id
    LEFT JOIN advance_state
      ON advance_state.timesheet_id = target_ids.timesheet_id
    LEFT JOIN active_batch_processing
      ON active_batch_processing.timesheet_id = target_ids.timesheet_id
    LEFT JOIN active_correction_processing
      ON active_correction_processing.timesheet_id = target_ids.timesheet_id
    LEFT JOIN legacy_state_presence
      ON legacy_state_presence.timesheet_id = target_ids.timesheet_id
  ),
  display_state_base AS MATERIALIZED (
    SELECT
      calculated_state.*,
      CASE
        WHEN calculated_state.is_overpaid THEN 'OVERPAID'
        WHEN calculated_state.paid_to_date_ex_vat > 0.01
         AND calculated_state.net_delta_ex_vat > 0.01 THEN 'PARTIALLY_PAID'
        WHEN calculated_state.paid_to_date_ex_vat > 0.01 THEN 'PAID'
        WHEN calculated_state.active_processing THEN 'PROCESSING'
        ELSE 'UNPAID'
      END::text AS summary_pay_status_code,
      (
        calculated_state.has_legacy_pay_state
        OR ABS(calculated_state.paid_to_date_ex_vat) > 0.01
        OR calculated_state.last_paid_at_utc IS NOT NULL
        OR ABS(calculated_state.reserved_ex_vat) > 0.01
        OR calculated_state.active_advance
        OR calculated_state.active_processing
        OR calculated_state.is_overpaid
      ) AS summary_state_applies
    FROM calculated_state
  ),
  display_state AS MATERIALIZED (
    SELECT
      display_state_base.timesheet_id,
      display_state_base.paid_to_date_ex_vat,
      display_state_base.last_paid_at_utc,
      display_state_base.reserved_ex_vat,
      display_state_base.outstanding_ex_vat,
      display_state_base.net_delta_ex_vat,
      display_state_base.active_advance,
      display_state_base.active_processing,
      display_state_base.summary_state_applies,
      display_state_base.advance_override_created_at_utc,
      display_state_base.advance_authorisation_consumed_at_utc,
      display_state_base.summary_pay_status_code,
      CASE display_state_base.summary_pay_status_code
        WHEN 'PARTIALLY_PAID' THEN 'HALF_COIN'
        WHEN 'PAID' THEN 'COIN'
        WHEN 'PROCESSING' THEN 'CLOCK'
        ELSE 'NONE'
      END::text AS summary_pay_icon_code,
      ARRAY_REMOVE(
        ARRAY[
          CASE
            WHEN display_state_base.active_advance THEN '__PAY_BADGE_ADV__'
            ELSE NULL::text
          END,
          CASE
            WHEN display_state_base.summary_pay_status_code = 'OVERPAID'
              THEN '__PAY_BADGE_OVERPAID__'
            ELSE NULL::text
          END,
          CASE
            WHEN display_state_base.active_processing
             AND display_state_base.summary_pay_status_code <> 'PROCESSING'
              THEN '__PAY_BADGE_PROCESSING__'
            ELSE NULL::text
          END
        ]::text[],
        NULL::text
      ) AS summary_badge_codes
    FROM display_state_base
  )
  INSERT INTO public.timesheet_summary_pay_state_cache (
    timesheet_id,
    paid_to_date_ex_vat,
    last_paid_at_utc,
    reserved_ex_vat,
    outstanding_ex_vat,
    net_delta_ex_vat,
    active_advance,
    active_processing,
    summary_state_applies,
    advance_override_created_at_utc,
    advance_authorisation_consumed_at_utc,
    summary_pay_status_code,
    summary_pay_icon_code,
    summary_badge_codes,
    refreshed_at_utc,
    refreshed_by_user_id
  )
  SELECT
    display_state.timesheet_id,
    display_state.paid_to_date_ex_vat,
    display_state.last_paid_at_utc,
    display_state.reserved_ex_vat,
    display_state.outstanding_ex_vat,
    display_state.net_delta_ex_vat,
    display_state.active_advance,
    display_state.active_processing,
    display_state.summary_state_applies,
    display_state.advance_override_created_at_utc,
    display_state.advance_authorisation_consumed_at_utc,
    display_state.summary_pay_status_code,
    display_state.summary_pay_icon_code,
    display_state.summary_badge_codes,
    now(),
    p_actor_user_id
  FROM display_state
  ORDER BY display_state.timesheet_id
  ON CONFLICT (timesheet_id) DO UPDATE
  SET
    paid_to_date_ex_vat = EXCLUDED.paid_to_date_ex_vat,
    last_paid_at_utc = EXCLUDED.last_paid_at_utc,
    reserved_ex_vat = EXCLUDED.reserved_ex_vat,
    outstanding_ex_vat = EXCLUDED.outstanding_ex_vat,
    net_delta_ex_vat = EXCLUDED.net_delta_ex_vat,
    active_advance = EXCLUDED.active_advance,
    active_processing = EXCLUDED.active_processing,
    summary_state_applies = EXCLUDED.summary_state_applies,
    advance_override_created_at_utc = EXCLUDED.advance_override_created_at_utc,
    advance_authorisation_consumed_at_utc = EXCLUDED.advance_authorisation_consumed_at_utc,
    summary_pay_status_code = EXCLUDED.summary_pay_status_code,
    summary_pay_icon_code = EXCLUDED.summary_pay_icon_code,
    summary_badge_codes = EXCLUDED.summary_badge_codes,
    refreshed_at_utc = EXCLUDED.refreshed_at_utc,
    refreshed_by_user_id = EXCLUDED.refreshed_by_user_id;

  GET DIAGNOSTICS v_refreshed_count = ROW_COUNT;

  PERFORM public._temp_diag_log(
    'TEMP_SUMMARY_REFRESH_STAGE',
    'TEMP_SUMMARY_REFRESH',
    CASE WHEN COALESCE(CARDINALITY(v_target_ids), 0) > 0 THEN v_target_ids[1]::text ELSE NULL::text END,
    jsonb_build_object(
      'function_name', 'pay_timesheet_summary_pay_state_refresh',
      'stage', 'pay_state_refresh_done',
      'requested_count', COALESCE(CARDINALITY(v_requested_ids), 0),
      'target_count', COALESCE(CARDINALITY(v_target_ids), 0),
      'refreshed_count', v_refreshed_count,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  WITH legacy_projection AS MATERIALIZED (
    SELECT DISTINCT
      rotation_rows.family_timesheet_id,
      COALESCE(
        rotation_rows.canonical_timesheet_id,
        rotation_rows.requested_timesheet_id
      ) AS projected_timesheet_id
    FROM public._pay_timesheet_rotation_scope(v_target_ids) AS rotation_rows
    WHERE rotation_rows.family_timesheet_id IS NOT NULL
      AND COALESCE(
        rotation_rows.canonical_timesheet_id,
        rotation_rows.requested_timesheet_id
      ) IS NOT NULL
  )
  UPDATE public.timesheet_pay_state AS legacy_state
  SET
    summary_pay_status_code = CASE
      WHEN summary_cache.summary_pay_status_code = 'OVERPAID' THEN 'PAID'
      ELSE summary_cache.summary_pay_status_code
    END,
    summary_pay_icon_code = CASE
      WHEN summary_cache.summary_pay_status_code = 'OVERPAID' THEN 'RED_COIN'
      ELSE summary_cache.summary_pay_icon_code
    END,
    summary_pay_paid_at_utc = summary_cache.last_paid_at_utc,
    summary_net_delta_ex_vat = summary_cache.net_delta_ex_vat
  FROM legacy_projection
  JOIN public.timesheet_summary_pay_state_cache AS summary_cache
    ON summary_cache.timesheet_id = legacy_projection.projected_timesheet_id
  WHERE legacy_state.timesheet_id = legacy_projection.family_timesheet_id
    AND summary_cache.timesheet_id = ANY (v_target_ids)
    AND (
      legacy_state.summary_pay_status_code IS DISTINCT FROM CASE
        WHEN summary_cache.summary_pay_status_code = 'OVERPAID' THEN 'PAID'
        ELSE summary_cache.summary_pay_status_code
      END
      OR legacy_state.summary_pay_icon_code IS DISTINCT FROM CASE
        WHEN summary_cache.summary_pay_status_code = 'OVERPAID' THEN 'RED_COIN'
        ELSE summary_cache.summary_pay_icon_code
      END
      OR legacy_state.summary_pay_paid_at_utc IS DISTINCT FROM summary_cache.last_paid_at_utc
      OR legacy_state.summary_net_delta_ex_vat IS DISTINCT FROM summary_cache.net_delta_ex_vat
    );

  GET DIAGNOSTICS v_legacy_state_rows_updated = ROW_COUNT;

  PERFORM public._temp_diag_log(
    'TEMP_SUMMARY_REFRESH_STAGE',
    'TEMP_SUMMARY_REFRESH',
    CASE WHEN COALESCE(CARDINALITY(v_target_ids), 0) > 0 THEN v_target_ids[1]::text ELSE NULL::text END,
    jsonb_build_object(
      'function_name', 'pay_timesheet_summary_pay_state_refresh',
      'stage', 'legacy_state_updated',
      'requested_count', COALESCE(CARDINALITY(v_requested_ids), 0),
      'target_count', COALESCE(CARDINALITY(v_target_ids), 0),
      'refreshed_count', v_refreshed_count,
      'legacy_state_rows_updated', v_legacy_state_rows_updated,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  PERFORM public._temp_diag_log(
    'TEMP_SUMMARY_REFRESH_STAGE',
    'TEMP_SUMMARY_REFRESH',
    CASE WHEN COALESCE(CARDINALITY(v_target_ids), 0) > 0 THEN v_target_ids[1]::text ELSE NULL::text END,
    jsonb_build_object(
      'function_name', 'pay_timesheet_summary_pay_state_refresh',
      'stage', 'return',
      'requested_count', COALESCE(CARDINALITY(v_requested_ids), 0),
      'target_count', COALESCE(CARDINALITY(v_target_ids), 0),
      'refreshed_count', v_refreshed_count,
      'legacy_state_rows_updated', v_legacy_state_rows_updated,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'mode', CASE
      WHEN v_lightweight_fallback_used IS TRUE THEN 'ordinary_manual_save_full_fallback'
      ELSE 'full_summary_refresh'
    END,
    'requested_count', CARDINALITY(v_requested_ids),
    'target_count', CARDINALITY(v_target_ids),
    'refreshed_count', v_refreshed_count,
    'legacy_state_rows_updated', v_legacy_state_rows_updated,
    'lightweight_fallback_used', v_lightweight_fallback_used,
    'lightweight_result', CASE
      WHEN v_lightweight_fallback_used IS TRUE THEN COALESCE(v_lightweight_result, '{}'::jsonb)
      ELSE NULL::jsonb
    END
  );
END;
$function$;

-- pay_unpay_batch(uuid,uuid,text,boolean)
CREATE OR REPLACE FUNCTION public.pay_unpay_batch(p_pay_batch_id uuid, p_actor_user_id uuid, p_reason text, p_force boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := now();
  v_batch record;
  v_timesheet_id uuid;

  v_aff_timesheets uuid[] := array[]::uuid[];

  v_latest record;

  v_patch record;
  v_old_outstanding numeric;
  v_old_schedule jsonb;
  v_old_next_due date;

  v_component_restore record;
  v_component_before_json jsonb;
  v_component_after_json jsonb;

  v_reverted_adv int := 0;
  v_removed_hist int := 0;
  v_rebuilt_states int := 0;
  v_restored_components int := 0;
  v_released_reservations int := 0;
  v_changed_channel_audit record;
  v_changed_channel_audit_before_json jsonb := null;
  v_changed_channel_audit_after_json jsonb := null;
  v_changed_channel_unwound_ct int := 0;
  v_correction_flow_guard jsonb := '{}'::jsonb;
begin
  if p_pay_batch_id is null then
    raise exception 'pay_batch_id is required';
  end if;

  select
    pb.id,
    pb.status,
    pb.batch_kind_fixed,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  for update;

  if v_batch.id is null then
    raise exception 'pay_batch not found';
  end if;

  if (
    upper(btrim(coalesce(v_batch.execution_commit_state, 'NOT_SUBMITTED'))) <> 'NOT_SUBMITTED'
    or nullif(btrim(coalesce(v_batch.execution_commit_ref, '')), '') is not null
    or v_batch.execution_committed_at_utc is not null
    or exists (
      select 1
      from public.pay_bank_transfers as pbt_guard
      where pbt_guard.pay_batch_id = p_pay_batch_id
        and (
          nullif(btrim(coalesce(pbt_guard.rail_tx_id, '')), '') is not null
          or nullif(btrim(coalesce(pbt_guard.request_id, '')), '') is not null
          or nullif(btrim(coalesce(pbt_guard.payment_reference, '')), '') is not null
          or nullif(btrim(coalesce(pbt_guard.rail_state, '')), '') is not null
          or coalesce(pbt_guard.rail_meta_json, '{}'::jsonb) <> '{}'::jsonb
          or pbt_guard.completed_at_utc is not null
          or upper(btrim(coalesce(pbt_guard.status, ''))) in ('COMPLETED','FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','RETURNED','REVERTED')
          or nullif(btrim(coalesce(pbt_guard.failed_reason, '')), '') is not null
          or upper(btrim(coalesce(pbt_guard.rail_state, ''))) in ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','RETURNED','REVERTED','COMPLETED','SETTLED','PAID','EXECUTED')
          or lower(btrim(coalesce(pbt_guard.rail_meta_json->>'completed', 'false'))) in ('true','1','yes','y','on')
          or lower(btrim(coalesce(pbt_guard.rail_meta_json->>'failed', 'false'))) in ('true','1','yes','y','on')
          or lower(btrim(coalesce(pbt_guard.rail_meta_json->>'declined', 'false'))) in ('true','1','yes','y','on')
          or lower(btrim(coalesce(pbt_guard.rail_meta_json->>'rejected', 'false'))) in ('true','1','yes','y','on')
          or lower(btrim(coalesce(pbt_guard.rail_meta_json->>'returned', 'false'))) in ('true','1','yes','y','on')
        )
    )
    or exists (select 1 from public.pay_bank_transfer_events as pbte_guard where pbte_guard.pay_batch_id = p_pay_batch_id)
    or exists (select 1 from public.timesheet_pay_state_history as tpsh_guard where tpsh_guard.pay_batch_id = p_pay_batch_id)
    or exists (select 1 from public.pay_payment_correction_requests as ppcr_guard where ppcr_guard.pay_batch_id = p_pay_batch_id and ppcr_guard.status not in ('REJECTED','CANCELLED'))
    or exists (select 1 from public.pay_payment_correction_items as ppci_guard where ppci_guard.pay_batch_id = p_pay_batch_id)
  ) then
    v_correction_flow_guard := jsonb_build_object(
      'error', 'USE_PAYMENT_CORRECTION_FLOW',
      'code', 'USE_PAYMENT_CORRECTION_FLOW',
      'message', 'pay_unpay_batch is restricted to legacy/admin no-bank-evidence batches. Use the payment correction flow for submitted, failed, settled, returned, or corrected batches.',
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end
    );

    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_UNPAY_BATCH_BLOCKED_USE_CORRECTION_FLOW',
        v_correction_flow_guard,
        'pay_batch',
        p_pay_batch_id::text,
        null::jsonb,
        null::text,
        null::text,
        null::text
      );
    exception when others then
      null;
    end;

    raise exception '%', v_correction_flow_guard::text;
  end if;

  if v_batch.status in
 ('SETTLED','PARTIAL') and p_force is distinct from true then
    raise exception 'UNPAY_REQUIRES_FORCE_FOR_SETTLED_BATCH';
  end if;

  -- Revert finance-case header patches first so header totals are restored
  for v_patch in
    select
      pap.advance_id,
      pap.old_outstanding_amount,
      pap.old_schedule_json,
      pap.old_next_due_week_start
    from public.pay_advance_patches pap
    where pap.pay_batch_id = p_pay_batch_id
  loop
    v_old_outstanding := v_patch.old_outstanding_amount;
    v_old_schedule := v_patch.old_schedule_json;
    v_old_next_due := v_patch.old_next_due_week_start;

    update public.pay_advances pa
    set
      outstanding_amount = v_old_outstanding,
      schedule_json = v_old_schedule,
      next_due_week_start = v_old_next_due,
      status = case
        when coalesce(v_old_outstanding, 0) <= 0 then 'PAID_OFF'::public.pay_advance_status_enum
        else 'ACTIVE'::public.pay_advance_status_enum
      end,
      updated_at = v_now
    where pa.id = v_patch.advance_id;

    v_reverted_adv := v_reverted_adv + 1;
  end loop;

  -- Restore component-level remainders from frozen snapshots on batch items first,
  -- then fall back to reservation snapshots only for components that had no batch item snapshot.
  for v_component_restore in
    with item_component_restore as (
      select
        pbi.finance_case_id,
        pbi.finance_component_id,
        round(
          sum(
            coalesce(
              pbi.frozen_source_amount,
              case
                when pbi.frozen_component_snapshot_json ? 'frozen_source_amount'
                  and nullif(btrim(pbi.frozen_component_snapshot_json ->> 'frozen_source_amount'), '') is not null
                then (pbi.frozen_component_snapshot_json ->> 'frozen_source_amount')::numeric
                else null::numeric
              end,
              case
                when pbi.frozen_component_snapshot_json ? 'reserved_source_amount'
                  and nullif(btrim(pbi.frozen_component_snapshot_json ->> 'reserved_source_amount'), '') is not null
                then (pbi.frozen_component_snapshot_json ->> 'reserved_source_amount')::numeric
                else null::numeric
              end,
              0::numeric
            )
          ),
          2
        )::numeric(12,2) as restore_source_amount
      from public.pay_batch_items pbi
      join public.pay_batch_candidates pbc
        on pbc.id = pbi.pay_batch_candidate_id
      where pbc.pay_batch_id = p_pay_batch_id
        and coalesce(pbi.is_voided, false) = false
        and pbi.finance_component_id is not null
      group by
        pbi.finance_case_id,
        pbi.finance_component_id
    ),
    reservation_component_restore as (
      select
        par.finance_case_id,
        par.finance_component_id,
        round(
          sum(
            coalesce(
              par.reserved_source_amount,
              par.reserved_amount,
              0::numeric
            )
          ),
          2
        )::numeric(12,2) as restore_source_amount
      from public.pay_advance_reservations par
      where par.pay_batch_id = p_pay_batch_id
        and par.finance_component_id is not null
        and par.status in ('RESERVED','COMMITTED','SETTLED')
      group by
        par.finance_case_id,
        par.finance_component_id
    ),
    combined_restore as (
      select
        icr.finance_case_id,
        icr.finance_component_id,
        icr.restore_source_amount
      from item_component_restore icr

      union all

      select
        rcr.finance_case_id,
        rcr.finance_component_id,
        rcr.restore_source_amount
      from reservation_component_restore rcr
      where not exists (
        select 1
        from item_component_restore icr2
        where icr2.finance_case_id is not distinct from rcr.finance_case_id
          and icr2.finance_component_id = rcr.finance_component_id
      )
    )
    select
      cr.finance_case_id,
      cr.finance_component_id,
      cr.restore_source_amount,
      pfc.source_amount,
      pfc.remaining_source_amount,
      pfc.closed_at_utc,
      pfc.classification,
      pfc.source_pay_method,
      pfc.saved_target_pay_method,
      pfc.saved_resolution_mode,
      pfc.saved_resolution_payload_json,
      pfc.saved_resolution_result_json,
      pfc.stale_reason
    from combined_restore cr
    join public.pay_finance_case_components pfc
      on pfc.id = cr.finance_component_id
    where cr.restore_source_amount > 0
    order by
      pfc.allocation_priority_group,
      pfc.allocation_priority_order,
      pfc.created_at_utc,
      pfc.id
  loop
    select jsonb_build_object(
      'finance_component_id', v_component_restore.finance_component_id::text,
      'classification', v_component_restore.classification::text,
      'source_pay_method', v_component_restore.source_pay_method,
      'saved_target_pay_method', v_component_restore.saved_target_pay_method,
      'saved_resolution_mode', case when v_component_restore.saved_resolution_mode is null then null else v_component_restore.saved_resolution_mode::text end,
      'saved_resolution_payload_json', v_component_restore.saved_resolution_payload_json,
      'saved_resolution_result_json', v_component_restore.saved_resolution_result_json,
      'stale_reason', v_component_restore.stale_reason,
      'source_amount', round(coalesce(v_component_restore.source_amount, 0), 2),
      'remaining_source_amount', round(coalesce(v_component_restore.remaining_source_amount, 0), 2),
      'closed_at_utc', v_component_restore.closed_at_utc
    )
    into v_component_before_json;

    update public.pay_finance_case_components pfc
    set
      remaining_source_amount = least(
        round(coalesce(pfc.source_amount, 0), 2),
        round(coalesce(pfc.remaining_source_amount, 0), 2) + round(coalesce(v_component_restore.restore_source_amount, 0), 2)
      )::numeric(12,2),
      closed_at_utc = null,
      updated_at_utc = v_now
    where pfc.id = v_component_restore.finance_component_id
    returning jsonb_build_object(
      'finance_component_id', pfc.id::text,
      'classification', pfc.classification::text,
      'source_pay_method', pfc.source_pay_method,
      'saved_target_pay_method', pfc.saved_target_pay_method,
      'saved_resolution_mode', case when pfc.saved_resolution_mode is null then null else pfc.saved_resolution_mode::text end,
      'saved_resolution_payload_json', pfc.saved_resolution_payload_json,
      'saved_resolution_result_json', pfc.saved_resolution_result_json,
      'stale_reason', pfc.stale_reason,
      'source_amount', round(coalesce(pfc.source_amount, 0), 2),
      'remaining_source_amount', round(coalesce(pfc.remaining_source_amount, 0), 2),
      'closed_at_utc', pfc.closed_at_utc
    )
    into v_component_after_json;

    insert into public.pay_finance_case_events (
      finance_case_id,
      finance_component_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    values (
      v_component_restore.finance_case_id,
      v_component_restore.finance_component_id,
      'COMPONENT_RESTORED_ON_UNPAY',
      v_now,
      p_actor_user_id,
      p_pay_batch_id,
      null,
      v_component_before_json,
      v_component_after_json,
      coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'UNPAID'),
      'Restored finance component remainder from frozen batch-item/reservation snapshot during unpay.'
    );

    v_restored_components := v_restored_components + 1;
  end loop;

  -- Release any reservations tied to the batch so finance cases remain open correctly.
  update public.pay_advance_reservations par
  set
    status = 'RELEASED',
    settled_at_utc = null,
    released_at_utc = coalesce(par.released_at_utc, v_now),
    released_reason = coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'UNPAID')
  where par.pay_batch_id = p_pay_batch_id
    and par.status in ('RESERVED','COMMITTED','SETTLED');

  get diagnostics v_released_reservations = row_count;

  -- Revert LOANS payout status (if this batch paid out loans)
  if upper(btrim(coalesce(v_batch.batch_kind_fixed,''))) = 'LOANS' then
    with loan_ids as (
      select distinct
        replace(pbi.source_ref, 'advance:', '')::uuid as loan_id
      from public.pay_batch_items pbi
      join public.pay_batch_candidates pbc
        on pbc.id = pbi.pay_batch_candidate_id
      where pbc.pay_batch_id = p_pay_batch_id
        and pbi.item_type = 'LOAN_PAYOUT'
        and pbi.is_voided = false
        and pbi.source_ref ~ '^advance:[0-9a-fA-F-]{36}$'
    )
    update public.pay_advances pa
    set
      payout_status = 'PENDING'::public.pay_advance_payout_status_enum,
      payout_pay_batch_id = null,
      payout_transfer_id = null,
      updated_at = v_now
    from loan_ids li
    where pa.id = li.loan_id
      and pa.advance_kind = 'LOAN'::public.pay_advance_kind_enum
      and pa.payout_pay_batch_id = p_pay_batch_id;
  end if;

  -- Gather affected timesheets from history rows for this batch
  select coalesce(array_agg(distinct h.timesheet_id), array[]::uuid[])
  into v_aff_timesheets
  from public.timesheet_pay_state_history h
  where h.pay_batch_id = p_pay_batch_id;

  -- Remove history rows for this batch
  delete from public.timesheet_pay_state_history h
  where h.pay_batch_id = p_pay_batch_id;

  get diagnostics v_removed_hist = row_count;

  create temp table if not exists _tmp_unpay_timesheet_pay_display (
    timesheet_id uuid not null primary key,
    pay_batch_id uuid not null,
    settled_at_utc timestamptz not null,
    snapshot_json jsonb not null,
    signature text null,
    summary_pay_status_code text not null,
    summary_pay_icon_code text not null,
    summary_pay_paid_at_utc timestamptz not null,
    summary_net_delta_ex_vat numeric(12,2) not null
  ) on commit drop;

  truncate table _tmp_unpay_timesheet_pay_display;

  insert into _tmp_unpay_timesheet_pay_display(
    timesheet_id,
    pay_batch_id,
    settled_at_utc,
    snapshot_json,
    signature,
    summary_pay_status_code,
    summary_pay_icon_code,
    summary_pay_paid_at_utc,
    summary_net_delta_ex_vat
  )
  with affected_timesheets as (
    select distinct unnest(coalesce(v_aff_timesheets, array[]::uuid[])) as timesheet_id
  ),
  latest_history as (
    select distinct on (h.timesheet_id)
      h.timesheet_id,
      h.pay_batch_id,
      h.settled_at_utc,
      h.snapshot_json,
      h.signature
    from public.timesheet_pay_state_history h
    join affected_timesheets affected_history
      on affected_history.timesheet_id = h.timesheet_id
    order by h.timesheet_id, h.settled_at_utc desc, h.id desc
  ),
  affected_ids as (
    select coalesce(array_agg(distinct affected_timesheets.timesheet_id order by affected_timesheets.timesheet_id), array[]::uuid[]) as timesheet_ids
    from affected_timesheets
  ),
  outstanding_components as (
    select
      oc.timesheet_id,
      oc.truth_ex_vat,
      oc.baseline_ex_vat,
      oc.reserved_ex_vat,
      oc.outstanding_ex_vat
    from affected_ids
    cross join lateral public._pay_outstanding_components(affected_ids.timesheet_ids, p_pay_batch_id) oc
  ),
  summary_calc as (
    select
      lh.timesheet_id,
      round(coalesce(sum(coalesce(oc.truth_ex_vat, 0) - coalesce(oc.baseline_ex_vat, 0)), 0), 2)::numeric(12,2) as summary_net_delta_ex_vat,
      round(coalesce(sum(coalesce(oc.reserved_ex_vat, 0)), 0), 2)::numeric(12,2) as summary_reserved_ex_vat,
      round(coalesce(sum(coalesce(oc.outstanding_ex_vat, 0)), 0), 2)::numeric(12,2) as summary_outstanding_ex_vat
    from latest_history lh
    left join outstanding_components oc
      on oc.timesheet_id = lh.timesheet_id
    group by lh.timesheet_id
  )
  select
    lh.timesheet_id,
    lh.pay_batch_id,
    lh.settled_at_utc,
    lh.snapshot_json,
    lh.signature,
    case
      when coalesce(sc.summary_outstanding_ex_vat, 0) > 0 then 'PARTIALLY_PAID'
      when coalesce(sc.summary_reserved_ex_vat, 0) > 0 then 'PROCESSING'
      else 'PAID'
    end as summary_pay_status_code,
    case
      when coalesce(sc.summary_net_delta_ex_vat, 0) < -0.01 then 'RED_COIN'
      when coalesce(sc.summary_outstanding_ex_vat, 0) > 0 then 'HALF_COIN'
      when coalesce(sc.summary_reserved_ex_vat, 0) > 0 then 'CLOCK'
      else 'COIN'
    end as summary_pay_icon_code,
    lh.settled_at_utc as summary_pay_paid_at_utc,
    coalesce(sc.summary_net_delta_ex_vat, 0)::numeric(12,2) as summary_net_delta_ex_vat
  from latest_history lh
  left join summary_calc sc
    on sc.timesheet_id = lh.timesheet_id;

  -- Rebuild timesheet_pay_state for affected timesheets
  foreach v_timesheet_id in array v_aff_timesheets
  loop
    select
      tpd.timesheet_id,
      tpd.pay_batch_id,
      tpd.settled_at_utc,
      tpd.snapshot_json,
      tpd.signature,
      tpd.summary_pay_status_code,
      tpd.summary_pay_icon_code,
      tpd.summary_pay_paid_at_utc,
      tpd.summary_net_delta_ex_vat
    into v_latest
    from _tmp_unpay_timesheet_pay_display tpd
    where tpd.timesheet_id = v_timesheet_id
    limit 1;

    if v_latest.timesheet_id is null then
      delete from public.timesheet_pay_state tps
      where tps.timesheet_id = v_timesheet_id;
    else
      insert into public.timesheet_pay_state(
        timesheet_id,
        last_settled_snapshot_json,
        last_settled_signature,
        last_settled_pay_batch_id,
        last_settled_at_utc,
        summary_pay_status_code,
        summary_pay_icon_code,
        summary_pay_paid_at_utc,
        summary_net_delta_ex_vat
      )
      values (
        v_timesheet_id,
        v_latest.snapshot_json,
        v_latest.signature,
        v_latest.pay_batch_id,
        v_latest.settled_at_utc,
        v_latest.summary_pay_status_code,
        v_latest.summary_pay_icon_code,
        v_latest.summary_pay_paid_at_utc,
        v_latest.summary_net_delta_ex_vat
      )
      on conflict (timesheet_id) do update
      set
        last_settled_snapshot_json = excluded.last_settled_snapshot_json,
        last_settled_signature = excluded.last_settled_signature,
        last_settled_pay_batch_id = excluded.last_settled_pay_batch_id,
        last_settled_at_utc = excluded.last_settled_at_utc,
        summary_pay_status_code = excluded.summary_pay_status_code,
        summary_pay_icon_code = excluded.summary_pay_icon_code,
        summary_pay_paid_at_utc = excluded.summary_pay_paid_at_utc,
        summary_net_delta_ex_vat = excluded.summary_net_delta_ex_vat;
    end if;

    v_rebuilt_states := v_rebuilt_states + 1;
  end loop;


  for v_changed_channel_audit in
    with settled_batch_item_portions as (
      select
        pbi.id as pay_batch_item_id,
        pbc.id as pay_batch_candidate_id,
        pbc.candidate_id as candidate_id,
        pbc.settled_at_utc as settled_at_utc,
        pbi.timesheet_id as timesheet_id,
        ts.booking_id as booking_id,
        pbi.pay_bank_transfer_id as pay_bank_transfer_id,
        pbi.item_type as item_type,
        pbi.segment_key as segment_key,
        pbi.source_ref as source_ref,
        pbi.description as description,
        upper(coalesce(nullif(btrim(coalesce(pbi.frozen_source_pay_method,'')), ''), '')) as source_pay_channel,
        upper(coalesce(nullif(btrim(coalesce(pbi.pay_channel,'')), ''), nullif(btrim(coalesce(pbi.frozen_target_pay_method,'')), ''), '')) as settled_pay_channel,
        case when pbi.frozen_component_key_type is null then null else pbi.frozen_component_key_type end as component_key_type,
        pbi.frozen_component_key_value as component_key_value,
        case when pbi.frozen_component_classification is null then null else pbi.frozen_component_classification::text end as component_classification,
        case when pbi.frozen_resolution_mode is null then null else pbi.frozen_resolution_mode::text end as resolution_mode,
        pbi.frozen_resolution_payload_json as resolution_payload_json,
        pbi.frozen_resolution_result_json as resolution_result_json,
        pbi.frozen_source_basis_json as frozen_source_basis_json,
        round(coalesce(pbi.frozen_source_amount, pbi.amount_ex_vat, 0), 2) as item_source_amount_ex_vat,
        round(coalesce(pbi.frozen_target_amount_ex_vat, pbi.amount_ex_vat, 0), 2) as item_settled_amount_ex_vat
      from public.pay_batch_items pbi
      join public.pay_batch_candidates pbc
        on pbc.id = pbi.pay_batch_candidate_id
      left join public.timesheets ts
        on ts.timesheet_id = pbi.timesheet_id
      where pbc.pay_batch_id = p_pay_batch_id
        and coalesce(pbi.is_voided, false) = false
        and pbi.item_type <> 'DEBT_CREATED'
        and pbi.timesheet_id is not null
        and pbc.settled_at_utc is not null
    ),
    portion_rows as (
      select
        sbip.pay_batch_item_id,
        sbip.pay_batch_candidate_id,
        sbip.candidate_id,
        sbip.settled_at_utc,
        sbip.timesheet_id,
        sbip.booking_id,
        sbip.pay_bank_transfer_id,
        sbip.source_pay_channel,
        sbip.settled_pay_channel,
        sbip.component_key_type,
        sbip.component_key_value,
        sbip.component_classification,
        sbip.resolution_mode,
        sbip.resolution_payload_json,
        sbip.resolution_result_json,
        sbip.segment_key,
        sbip.source_ref,
        sbip.description,
        pbib.id as pay_batch_item_breakdown_id,
        coalesce(
          nullif(btrim(coalesce(pbib.line_kind,'')), ''),
          case
            when sbip.item_type = 'SEGMENT_DELTA' then 'SEGMENT_BUCKET'
            when sbip.item_type = 'EXPENSE_DELTA' then 'EXPENSE'
            when sbip.item_type = 'MILEAGE_DELTA' then 'MILEAGE'
            when sbip.item_type = 'ADJUSTMENT_DELTA' then 'ADJUSTMENT'
            when sbip.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
            when sbip.item_type = 'LOAN_REPAYMENT' then 'LOAN_REPAYMENT'
            when sbip.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
            when sbip.item_type = 'LOAN_PAYOUT' then 'LOAN_PAYOUT'
            when sbip.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_PAYOUT'
            else sbip.item_type
          end
        ) as line_kind,
        nullif(btrim(coalesce(pbib.bucket_code, sbip.frozen_source_basis_json ->> 'bucket_code', '')), '') as bucket_code,
        coalesce(
          nullif(btrim(coalesce(pbib.unit_name, '')), ''),
          nullif(btrim(coalesce(sbip.description, '')), ''),
          case
            when sbip.item_type = 'SEGMENT_DELTA' then 'Timesheet portion'
            when sbip.item_type = 'EXPENSE_DELTA' then 'Expense'
            when sbip.item_type = 'MILEAGE_DELTA' then 'Mileage'
            when sbip.item_type = 'ADJUSTMENT_DELTA' then 'Adjustment'
            when sbip.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            when sbip.item_type = 'LOAN_REPAYMENT' then 'Loan repayment'
            when sbip.item_type = 'MANUAL_DEBT_RECOVERY' then 'Manual debt recovery'
            when sbip.item_type = 'LOAN_PAYOUT' then 'Loan payout'
            when sbip.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual credit payout'
            else 'Batch item'
          end
        ) as unit_name,
        case
          when pbib.units is not null then round(pbib.units, 4)
          when sbip.frozen_source_basis_json ? 'source_units'
           and nullif(btrim(coalesce(sbip.frozen_source_basis_json ->> 'source_units', '')), '') is not null
            then round((sbip.frozen_source_basis_json ->> 'source_units')::numeric, 4)
          else null::numeric
        end as units,
        case
          when sbip.frozen_source_basis_json ? 'source_rate'
           and nullif(btrim(coalesce(sbip.frozen_source_basis_json ->> 'source_rate', '')), '') is not null
            then round((sbip.frozen_source_basis_json ->> 'source_rate')::numeric, 6)
          else null::numeric
        end as source_rate,
        case
          when pbib.rate is not null then round(pbib.rate, 6)
          else null::numeric
        end as settled_rate,
        case
          when pbib.units is not null
           and sbip.frozen_source_basis_json ? 'source_rate'
           and nullif(btrim(coalesce(sbip.frozen_source_basis_json ->> 'source_rate', '')), '') is not null
            then round(pbib.units * round((sbip.frozen_source_basis_json ->> 'source_rate')::numeric, 6), 2)
          else sbip.item_source_amount_ex_vat
        end as source_amount_ex_vat,
        round(coalesce(pbib.amount_ex_vat, sbip.item_settled_amount_ex_vat), 2) as settled_amount_ex_vat,
        md5(concat_ws('|',
          sbip.pay_batch_item_id::text,
          coalesce(
            nullif(btrim(coalesce(pbib.line_kind,'')), ''),
            case
              when sbip.item_type = 'SEGMENT_DELTA' then 'SEGMENT_BUCKET'
              when sbip.item_type = 'EXPENSE_DELTA' then 'EXPENSE'
              when sbip.item_type = 'MILEAGE_DELTA' then 'MILEAGE'
              when sbip.item_type = 'ADJUSTMENT_DELTA' then 'ADJUSTMENT'
              when sbip.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
              when sbip.item_type = 'LOAN_REPAYMENT' then 'LOAN_REPAYMENT'
              when sbip.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
              when sbip.item_type = 'LOAN_PAYOUT' then 'LOAN_PAYOUT'
              when sbip.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_PAYOUT'
              else sbip.item_type
            end
          ),
          coalesce(nullif(btrim(coalesce(pbib.bucket_code, sbip.frozen_source_basis_json ->> 'bucket_code', '')), ''), ''),
          coalesce(
            case
              when pbib.units is not null then round(pbib.units, 4)::text
              when sbip.frozen_source_basis_json ? 'source_units'
               and nullif(btrim(coalesce(sbip.frozen_source_basis_json ->> 'source_units', '')), '') is not null
                then round((sbip.frozen_source_basis_json ->> 'source_units')::numeric, 4)::text
              else null::text
            end,
            ''
          ),
          coalesce(case when pbib.rate is not null then round(pbib.rate, 6)::text else null::text end, ''),
          round(coalesce(pbib.amount_ex_vat, sbip.item_settled_amount_ex_vat), 2)::text
        )) as portion_identity_key
      from settled_batch_item_portions sbip
      left join public.pay_batch_item_breakdowns pbib
        on pbib.pay_batch_item_id = sbip.pay_batch_item_id
    )
    select
      pr.pay_batch_item_id,
      pr.pay_batch_item_breakdown_id,
      pr.pay_batch_candidate_id,
      pr.candidate_id,
      pr.settled_at_utc,
      pr.timesheet_id,
      pr.booking_id,
      pr.pay_bank_transfer_id,
      pr.source_pay_channel,
      pr.settled_pay_channel,
      pr.component_key_type,
      pr.component_key_value,
      pr.component_classification,
      pr.resolution_mode,
      pr.resolution_payload_json,
      pr.resolution_result_json,
      pr.segment_key,
      pr.source_ref,
      pr.description,
      pr.line_kind,
      pr.bucket_code,
      pr.unit_name,
      pr.units,
      pr.source_rate,
      pr.settled_rate,
      pr.source_amount_ex_vat,
      pr.settled_amount_ex_vat,
      pr.portion_identity_key
    from portion_rows pr
    where pr.source_pay_channel <> ''
      and pr.settled_pay_channel <> ''
      and pr.source_pay_channel <> pr.settled_pay_channel
    order by
      pr.timesheet_id,
      pr.pay_batch_item_id,
      pr.line_kind,
      pr.bucket_code nulls first,
      pr.unit_name,
      pr.settled_amount_ex_vat desc
  loop
    v_changed_channel_audit_before_json := jsonb_build_object(
      'event_kind', 'TIMESHEET_CHANNEL_CHANGE_PORTION',
      'audit_effective_state', 'SETTLED_ACTIVE',
      'channel_changed', true,
      'timesheet_id', v_changed_channel_audit.timesheet_id::text,
      'booking_id', case when v_changed_channel_audit.booking_id is null then null else v_changed_channel_audit.booking_id::text end,
      'candidate_id', case when v_changed_channel_audit.candidate_id is null then null else v_changed_channel_audit.candidate_id::text end,
      'pay_batch_id', p_pay_batch_id::text,
      'pay_batch_candidate_id', case when v_changed_channel_audit.pay_batch_candidate_id is null then null else v_changed_channel_audit.pay_batch_candidate_id::text end,
      'pay_batch_item_id', case when v_changed_channel_audit.pay_batch_item_id is null then null else v_changed_channel_audit.pay_batch_item_id::text end,
      'pay_batch_item_breakdown_id', case when v_changed_channel_audit.pay_batch_item_breakdown_id is null then null else v_changed_channel_audit.pay_batch_item_breakdown_id::text end,
      'portion_identity_key', v_changed_channel_audit.portion_identity_key,
      'source_pay_channel', v_changed_channel_audit.source_pay_channel,
      'settled_pay_channel', v_changed_channel_audit.settled_pay_channel,
      'component_key_type', v_changed_channel_audit.component_key_type,
      'component_key_value', v_changed_channel_audit.component_key_value,
      'component_classification', v_changed_channel_audit.component_classification,
      'line_kind', v_changed_channel_audit.line_kind,
      'bucket_code', v_changed_channel_audit.bucket_code,
      'unit_name', v_changed_channel_audit.unit_name,
      'units', case when v_changed_channel_audit.units is null then null else round(v_changed_channel_audit.units, 4) end,
      'source_rate', case when v_changed_channel_audit.source_rate is null then null else round(v_changed_channel_audit.source_rate, 6) end,
      'settled_rate', case when v_changed_channel_audit.settled_rate is null then null else round(v_changed_channel_audit.settled_rate, 6) end,
      'source_amount_ex_vat', round(coalesce(v_changed_channel_audit.source_amount_ex_vat, 0), 2),
      'settled_amount_ex_vat', round(coalesce(v_changed_channel_audit.settled_amount_ex_vat, 0), 2),
      'resolution_mode', v_changed_channel_audit.resolution_mode,
      'resolution_selection_kind', case
        when v_changed_channel_audit.resolution_mode = 'SUGGESTED_EQUIVALENT_BASIS' then 'SUGGESTED'
        when v_changed_channel_audit.resolution_mode in ('MANUAL_REPLACEMENT_RATE','MANUAL_AMOUNT') then 'MANUAL'
        else null
      end,
      'pay_bank_transfer_id', case when v_changed_channel_audit.pay_bank_transfer_id is null then null else v_changed_channel_audit.pay_bank_transfer_id::text end,
      'segment_key', v_changed_channel_audit.segment_key,
      'source_ref', v_changed_channel_audit.source_ref,
      'description', v_changed_channel_audit.description,
      'settled_at_utc', v_changed_channel_audit.settled_at_utc
    );

    v_changed_channel_audit_after_json := v_changed_channel_audit_before_json || jsonb_build_object(
      'audit_effective_state', 'UNWOUND',
      'unwound_at_utc', v_now,
      'unwind_reason', coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'UNPAID'),
      'reverses_action', 'TIMESHEET_CHANNEL_CHANGE_PORTION_SETTLED'
    );

    begin
      perform public._audit_insert(
        'timesheets',
        v_changed_channel_audit.timesheet_id::text,
        'TIMESHEET_CHANNEL_CHANGE_PORTION_UNWOUND',
        v_changed_channel_audit_before_json,
        v_changed_channel_audit_after_json,
        coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'UNPAID'),
        p_actor_user_id
      );
      v_changed_channel_unwound_ct := v_changed_channel_unwound_ct + 1;
    exception when others then
      null;
    end;
  end loop;

  -- Mark candidate rows as UNPAID
  update public.pay_batch_candidates pbc
  set
    settlement_status = 'UNPAID',
    settled_at_utc = null,
    settled_via = null,
    settled_note = coalesce(nullif(btrim(coalesce(p_reason,'')),''), 'UNPAID'),
    paye_state = case when pbc.paye_state is null then null else 'READY' end
  where pbc.pay_batch_id = p_pay_batch_id;

  -- Mark batch as UNPAID (preserve audit; do not delete)
  update public.pay_batches pb
  set status = 'UNPAID'
  where pb.id = p_pay_batch_id;

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'action', 'UNPAID',
    'reverted_advances', v_reverted_adv,
    'restored_components', v_restored_components,
    'released_reservations', v_released_reservations,
    'deleted_history_rows', v_removed_hist,
    'rebuilt_timesheet_states', v_rebuilt_states,
    'timesheet_channel_change_audit', jsonb_build_object(
      'unwound_event_count', v_changed_channel_unwound_ct
    )
  );
end;
$function$;

-- pay_workbench_authorise_delta_hotkey_preflight(uuid,uuid,uuid[],uuid[],jsonb,text,uuid,bigint)
CREATE OR REPLACE FUNCTION public.pay_workbench_authorise_delta_hotkey_preflight(p_session_id uuid, p_candidate_id uuid, p_targeted_timesheet_ids uuid[] DEFAULT ARRAY[]::uuid[], p_linked_timesheet_ids uuid[] DEFAULT ARRAY[]::uuid[], p_payload_json jsonb DEFAULT '{}'::jsonb, p_reason text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid, p_source_change_seq bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_payload jsonb := CASE WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_family_scope jsonb := '{}'::jsonb;
  v_targeted_json jsonb := '[]'::jsonb;
  v_linked_json jsonb := '[]'::jsonb;
  v_queue_targeted_json jsonb := '[]'::jsonb;
  v_queue_linked_json jsonb := '[]'::jsonb;
  v_requested_json jsonb := '[]'::jsonb;
  v_family_key text := NULL::text;
  v_delta_hash text := NULL::text;
  v_latest_seq bigint := 0;
  v_payload_seq bigint := 0;
  v_live_seq bigint := 0;
  v_existing_queued public.banking_pay_workbench_jobs%ROWTYPE;
  v_running public.banking_pay_workbench_jobs%ROWTYPE;
  v_existing_seq bigint := 0;
  v_existing_event_count integer := 0;
  v_new_event_count integer := 1;
  v_new_projection_run_id uuid := gen_random_uuid();
  v_dedupe_key text := NULL::text;
  v_payload_new jsonb := '{}'::jsonb;
  v_job_id uuid := NULL::uuid;
  v_job_status text := NULL::text;
  v_inserted boolean := false;
  v_insert_count integer := 0;
  v_reason text := COALESCE(NULLIF(BTRIM(COALESCE(p_reason, '')), ''), NULLIF(BTRIM(COALESCE(v_payload->>'reason_latest', v_payload->>'reason', '')), ''), 'AUTHORISE_UNAUTHORISE_DELTA_PREFLIGHT');
  v_lifecycle_context text := LOWER(BTRIM(COALESCE(v_payload->>'lifecycle_mutation_context', v_payload->>'mutation_context', v_payload->>'lifecycle_context', '')));
  v_is_authorise_boundary boolean := false;
  v_is_archive_boundary boolean := false;
  v_is_lifecycle_boundary boolean := false;
  v_is_ordinary_save_no_dirty boolean := false;
  v_event_class text := NULL::text;
  v_admission jsonb := '{}'::jsonb;
  v_settings_json jsonb := '{}'::jsonb;
  v_lifecycle_fast_enabled boolean := false;
  v_projection_class text := 'NORMAL_TIMESHEET';
BEGIN
  IF p_session_id IS NULL OR p_candidate_id IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'action', 'PROCEED', 'match_found', false, 'reason', 'SESSION_OR_CANDIDATE_REQUIRED');
  END IF;

  v_is_authorise_boundary :=
    lower(BTRIM(COALESCE(v_payload->>'authorise_boundary_changed', v_payload->>'timesheet_authorise_boundary_changed', 'false'))) IN ('true','t','1','yes','y','on')
    OR lower(BTRIM(COALESCE(v_payload->>'unauthorise_boundary_changed', v_payload->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true','t','1','yes','y','on')
    OR v_lifecycle_context IN ('timesheet_authorise', 'authorise_timesheet', 'timesheet_unauthorise', 'unauthorise_timesheet')
    OR LOWER(COALESCE(v_reason, '')) LIKE '%authorise%'
    OR LOWER(COALESCE(v_reason, '')) LIKE '%unauthorise%';

  v_is_archive_boundary :=
    lower(BTRIM(COALESCE(v_payload->>'archive_boundary_changed', v_payload->>'timesheet_archive_boundary_changed', 'false'))) IN ('true','t','1','yes','y','on')
    OR lower(BTRIM(COALESCE(v_payload->>'unarchive_boundary_changed', v_payload->>'timesheet_unarchive_boundary_changed', 'false'))) IN ('true','t','1','yes','y','on')
    OR v_lifecycle_context IN ('timesheet_archive', 'archive_timesheet', 'timesheet_unarchive', 'unarchive_timesheet')
    OR LOWER(COALESCE(v_reason, '')) LIKE '%archive%'
    OR LOWER(COALESCE(v_reason, '')) LIKE '%unarchive%';

  v_is_lifecycle_boundary := COALESCE(v_is_authorise_boundary, false) OR COALESCE(v_is_archive_boundary, false);
  v_is_ordinary_save_no_dirty := lower(BTRIM(COALESCE(v_payload->>'ordinary_timesheet_edit_save_no_dirty', 'false'))) IN ('true','t','1','yes','y','on');

  IF v_is_archive_boundary IS TRUE THEN
    RETURN jsonb_build_object(
      'ok', true,
      'action', 'PROCEED',
      'match_found', false,
      'reason', 'TIMESHEET_ARCHIVE_LIFECYCLE_REQUIRES_SOURCE_BUILD',
      'authorise_boundary_changed', COALESCE(v_is_authorise_boundary, false),
      'archive_boundary_changed', COALESCE(v_is_archive_boundary, false),
      'source_build_required', true,
      'classifier_work_skipped', false,
      'dirty_marking_skipped', false,
      'session_progress_dirtying_skipped', false,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    );
  END IF;

  IF v_is_ordinary_save_no_dirty IS TRUE
     OR COALESCE(array_length(COALESCE(p_targeted_timesheet_ids, ARRAY[]::uuid[]), 1), 0) = 0 THEN
    RETURN jsonb_build_object('ok', true, 'action', 'PROCEED', 'match_found', false, 'reason', 'NOT_TARGETED_AUTHORISE_UNAUTHORISE_DELTA');
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
    AND session_row.status = 'OPEN'
    AND session_row.discarded_at_utc IS NULL;

  IF v_session_row.id IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'action', 'PROCEED', 'match_found', false, 'reason', 'NO_OPEN_WORKBENCH_SESSION');
  END IF;

  SELECT COALESCE(change_counter.seq, 0)
  INTO v_live_seq
  FROM public.app_change_counters AS change_counter
  WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;

  v_payload_seq := GREATEST(
    COALESCE(p_source_change_seq, 0),
    COALESCE(CASE WHEN COALESCE(v_payload->>'latest_source_change_seq', '') ~ '^\d{1,18}$' THEN (v_payload->>'latest_source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(v_payload->>'source_change_seq', '') ~ '^\d{1,18}$' THEN (v_payload->>'source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(v_payload->>'source_change_sequence', '') ~ '^\d{1,18}$' THEN (v_payload->>'source_change_sequence')::bigint END, 0)
  );
  v_latest_seq := GREATEST(COALESCE(v_payload_seq, 0), COALESCE(v_live_seq, 0));

  IF v_is_authorise_boundary THEN
    v_event_class := CASE
      WHEN lower(BTRIM(COALESCE(v_payload->>'unauthorise_boundary_changed',v_payload->>'timesheet_unauthorise_boundary_changed','false'))) IN ('true','t','1','yes','y','on')
        OR v_lifecycle_context IN ('timesheet_unauthorise','unauthorise_timesheet')
        OR lower(COALESCE(v_reason,'')) LIKE '%unauthorise%'
      THEN 'UNAUTHORISE'
      ELSE 'AUTHORISE'
    END;
    v_admission := private.pay_workbench_targeted_delta_admission_v1(
      p_session_id,p_candidate_id,NULL,v_event_class,
      COALESCE(p_targeted_timesheet_ids,ARRAY[]::uuid[]),
      COALESCE(p_linked_timesheet_ids,ARRAY[]::uuid[]),v_latest_seq
    );
    SELECT to_jsonb(settings_row) INTO v_settings_json
    FROM public.settings_defaults AS settings_row WHERE settings_row.id=1;
    v_lifecycle_fast_enabled := CASE v_event_class
      WHEN 'AUTHORISE' THEN lower(COALESCE(v_settings_json->>'banking_pay_workbench_delta_enable_simple_authorise','false')) IN ('true','t','1','yes','on')
      WHEN 'UNAUTHORISE' THEN lower(COALESCE(v_settings_json->>'banking_pay_workbench_delta_enable_simple_unauthorise','false')) IN ('true','t','1','yes','on')
      ELSE false
    END;
    IF COALESCE((v_admission->>'admitted')::boolean,false) IS NOT TRUE
       OR v_lifecycle_fast_enabled IS NOT TRUE THEN
      RETURN jsonb_build_object(
        'ok',true,'action','PROCEED','match_found',false,
        'reason',CASE WHEN COALESCE((v_admission->>'admitted')::boolean,false)
          THEN 'TARGETED_LIFECYCLE_FAST_ROUTE_DISABLED'
          ELSE COALESCE(v_admission->>'reason','TARGETED_LIFECYCLE_REQUIRES_SOURCE_BUILD') END,
        'source_build_required',true,
        'would_fast_path_allowed',COALESCE((v_admission->>'admitted')::boolean,false),
        'fast_path_allowed',false,
        'lifecycle_event_class',v_event_class,
        'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH'
      );
    END IF;
    v_projection_class := 'TIMESHEET_LIFECYCLE';
  END IF;

  v_family_scope := public._pay_workbench_normalise_timesheet_rotation_scope_payload(
    COALESCE(p_targeted_timesheet_ids, ARRAY[]::uuid[]),
    COALESCE(p_linked_timesheet_ids, ARRAY[]::uuid[])
  );
  v_targeted_json := COALESCE(v_family_scope->'targeted_timesheet_ids', '[]'::jsonb);
  v_linked_json := COALESCE(v_family_scope->'linked_timesheet_ids', '[]'::jsonb);
  v_queue_targeted_json := COALESCE(v_family_scope->'queue_identity_targeted_timesheet_ids', v_family_scope->'family_timesheet_ids', v_targeted_json, '[]'::jsonb);
  v_queue_linked_json := COALESCE(v_family_scope->'queue_identity_linked_timesheet_ids', '[]'::jsonb);
  v_requested_json := COALESCE(v_family_scope->'requested_timesheet_ids', v_targeted_json);

  v_delta_hash := md5(COALESCE(v_queue_targeted_json, '[]'::jsonb)::text || ':' || COALESCE(v_queue_linked_json, '[]'::jsonb)::text);
  v_family_key := 'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
    || ':session:' || p_session_id::text
    || ':version:' || COALESCE(COALESCE(v_session_row.version, 0), 0)::text
    || ':projection_mode:DELTA'
    || ':projection_class:' || v_projection_class
    || ':refresh_scope:TARGETED_TIMESHEETS'
    || ':candidate:' || p_candidate_id::text
    || ':timesheets:' || v_delta_hash;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_family_key, 24062026));

  SELECT queued_job.*
  INTO v_existing_queued
  FROM public.banking_pay_workbench_jobs AS queued_job
  WHERE queued_job.session_id = p_session_id
    AND queued_job.candidate_id = p_candidate_id
    AND UPPER(BTRIM(COALESCE(queued_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
    AND UPPER(BTRIM(COALESCE(queued_job.status, ''))) = 'QUEUED'
    AND (
      queued_job.dedupe_key = v_family_key
      OR queued_job.dedupe_key LIKE v_family_key || ':waiting_after_running:%'
      OR COALESCE(queued_job.payload_json->>'normalised_delta_family_key', queued_job.payload_json->>'delta_family_key', queued_job.payload_json->>'delta_coalescing_key', '') = v_family_key
    )
  ORDER BY CASE WHEN queued_job.dedupe_key = v_family_key THEN 0 ELSE 1 END,
           queued_job.run_at_utc ASC,
           queued_job.created_at_utc ASC,
           queued_job.id ASC
  LIMIT 1
  FOR UPDATE;

  IF v_existing_queued.id IS NOT NULL THEN
    v_existing_seq := GREATEST(
      COALESCE(CASE WHEN COALESCE(v_existing_queued.payload_json->>'latest_source_change_seq', '') ~ '^\d{1,18}$' THEN (v_existing_queued.payload_json->>'latest_source_change_seq')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(v_existing_queued.payload_json->>'source_change_seq', '') ~ '^\d{1,18}$' THEN (v_existing_queued.payload_json->>'source_change_seq')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(v_existing_queued.payload_json->>'source_change_sequence', '') ~ '^\d{1,18}$' THEN (v_existing_queued.payload_json->>'source_change_sequence')::bigint END, 0)
    );
    v_existing_event_count := CASE WHEN COALESCE(v_existing_queued.payload_json->>'coalesced_event_count', '') ~ '^\d{1,9}$' THEN GREATEST((v_existing_queued.payload_json->>'coalesced_event_count')::integer, 1) ELSE 1 END;
    v_new_event_count := v_existing_event_count + 1;
    v_latest_seq := GREATEST(v_latest_seq, v_existing_seq);
    v_dedupe_key := CASE WHEN v_existing_queued.dedupe_key LIKE v_family_key || ':waiting_after_running:%' THEN v_existing_queued.dedupe_key ELSE v_family_key END;

    v_payload_new := jsonb_strip_nulls(
      (
        public._pay_workbench_merge_targeted_scope_payload(COALESCE(v_existing_queued.payload_json, '{}'::jsonb), COALESCE(v_payload, '{}'::jsonb))
        - 'cursor' - 'cursor_json' - 'next_cursor' - 'next_cursor_json' - 'source_cursor' - 'write_cursor_json'
        - 'candidate_cursor' - 'cursor_token' - 'has_cursor' - 'continuation_reason' - 'source_job_id'
        - 'continuation_source_job_id' - 'bounded_continuation_source_job_id' - 'parent_job_id'
        - 'next_phase' - 'write_phase' - 'source_result_summary' - 'source_result_has_more' - 'source_result_next_cursor_present'
        - 'old_row_json' - 'new_row_json' - 'source_row_json' - 'work_payload_json' - 'result_row_json'
        - 'preview_row_json' - 'projection_rows' - 'projected_rows'
      )
      || jsonb_build_object(
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'canonical_job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'resolved_mode', 'DELTA',
        'projection_mode', 'DELTA',
        'projection_class', v_projection_class,
        'lifecycle_event_class', v_event_class,
        'refresh_scope_kind', 'TARGETED_TIMESHEETS',
        'phase', 'INIT_PREFLIGHT',
        'run_mode', 'LATEST_STATE_HEAD',
        'continuation', false,
        'cursor_json', '{}'::jsonb,
        'projection_run_id', v_new_projection_run_id::text,
        'session_id', p_session_id::text,
        'source_session_id', p_session_id::text,
        'workbench_session_id', p_session_id::text,
        'session_version', COALESCE(v_session_row.version, 0),
        'session_signature', v_session_row.session_signature,
        'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
        'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
        'candidate_id', p_candidate_id::text,
        'targeted_timesheet_ids', v_targeted_json,
        'linked_timesheet_ids', v_linked_json,
        'queue_identity_targeted_timesheet_ids', v_queue_targeted_json,
        'queue_identity_linked_timesheet_ids', v_queue_linked_json,
        'family_timesheet_ids', COALESCE(v_family_scope->'family_timesheet_ids', v_targeted_json),
        'requested_timesheet_ids', v_requested_json,
        'targeted_timesheet_ids_requested', COALESCE(v_family_scope->'requested_targeted_timesheet_ids', v_requested_json),
        'linked_timesheet_ids_requested', COALESCE(v_family_scope->'requested_linked_timesheet_ids', '[]'::jsonb),
        'source_change_seq', v_latest_seq,
        'source_change_sequence', v_latest_seq,
        'latest_source_change_seq', v_latest_seq,
        'delta_coalescing_key', v_family_key,
        'delta_family_key', v_family_key,
        'normalised_delta_family_key', v_family_key,
        'delta_coalescing_hash', md5(v_family_key),
        'coalesced_event_count', v_new_event_count,
        'coalesced_source_change_seqs', jsonb_build_array(v_existing_seq, v_latest_seq),
        'latest_event_at_utc', v_now::text,
        'reason', v_reason,
        'early_preflight_action', 'REUSED_QUEUED_SAME_FAMILY_JOB',
        'dirty_marking_skipped', true,
        'session_progress_dirtying_skipped', true,
        'classifier_work_skipped_by_dirty_apply_preflight', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      )
    );

    UPDATE public.banking_pay_workbench_jobs AS job_update
    SET dedupe_key = v_dedupe_key,
        priority = LEAST(job_update.priority, 43),
        run_at_utc = LEAST(job_update.run_at_utc, v_now),
        payload_json = v_payload_new,
        updated_at_utc = v_now,
        started_at_utc = NULL,
        completed_at_utc = NULL,
        failed_at_utc = NULL,
        last_error_json = NULL::jsonb
    WHERE job_update.id = v_existing_queued.id
    RETURNING job_update.id, job_update.status
    INTO v_job_id, v_job_status;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_job_id::text,
      'EARLY_PREFLIGHT_REUSED_QUEUED_SAME_FAMILY_JOB',
      NULL::jsonb,
      jsonb_build_object(
        'id', v_job_id::text,
        'session_id', p_session_id::text,
        'session_version', COALESCE(v_session_row.version, 0),
        'candidate_id', p_candidate_id::text,
        'targeted_timesheet_ids', v_targeted_json,
        'linked_timesheet_ids', v_linked_json,
        'queue_identity_targeted_timesheet_ids', v_queue_targeted_json,
        'queue_identity_linked_timesheet_ids', v_queue_linked_json,
        'resolved_family_timesheet_ids', COALESCE(v_family_scope->'family_timesheet_ids', v_targeted_json),
        'requested_timesheet_ids', v_requested_json,
        'normalised_delta_family_key', v_family_key,
        'existing_job_id', v_existing_queued.id::text,
        'latest_source_change_seq', v_latest_seq,
        'previous_job_source_change_seq', v_existing_seq,
        'coalesced_event_count', v_new_event_count,
        'dirty_marking_skipped', true,
        'session_progress_dirtying_skipped', true,
        'classifier_work_skipped', true,
        'trigger_reason', v_reason,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      ),
      'EARLY_PREFLIGHT_REUSED_QUEUED_SAME_FAMILY_JOB',
      COALESCE(p_actor_user_id, v_session_row.actor_user_id)
    );

    RETURN jsonb_build_object(
      'ok', true,
      'action', 'REUSED_QUEUED_SAME_FAMILY_JOB',
      'match_found', true,
      'job_id', v_job_id::text,
      'status', v_job_status,
      'candidate_id', p_candidate_id::text,
      'session_id', p_session_id::text,
      'session_version', COALESCE(v_session_row.version, 0),
      'targeted_timesheet_ids', v_targeted_json,
      'linked_timesheet_ids', v_linked_json,
      'queue_identity_targeted_timesheet_ids', v_queue_targeted_json,
      'queue_identity_linked_timesheet_ids', v_queue_linked_json,
      'resolved_family_timesheet_ids', COALESCE(v_family_scope->'family_timesheet_ids', v_targeted_json),
      'normalised_delta_family_key', v_family_key,
      'latest_source_change_seq', v_latest_seq,
      'coalesced_event_count', v_new_event_count,
      'dirty_marking_skipped', true,
      'session_progress_dirtying_skipped', true,
      'classifier_work_skipped', true,
      'more_due', false,
      'has_more', false,
      'made_progress', true,
      'dirty_apply_can_complete_cleanly', true
    );
  END IF;

  SELECT running_job.*
  INTO v_running
  FROM public.banking_pay_workbench_jobs AS running_job
  WHERE running_job.session_id = p_session_id
    AND running_job.candidate_id = p_candidate_id
    AND UPPER(BTRIM(COALESCE(running_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
    AND UPPER(BTRIM(COALESCE(running_job.status, ''))) = 'RUNNING'
    AND (
      running_job.dedupe_key = v_family_key
      OR COALESCE(running_job.payload_json->>'normalised_delta_family_key', running_job.payload_json->>'delta_family_key', running_job.payload_json->>'delta_coalescing_key', '') = v_family_key
    )
  ORDER BY running_job.started_at_utc ASC NULLS LAST, running_job.created_at_utc ASC, running_job.id ASC
  LIMIT 1;

  IF v_running.id IS NOT NULL THEN
    v_dedupe_key := v_family_key || ':waiting_after_running:' || v_running.id::text;
    v_payload_new := jsonb_strip_nulls(
      (COALESCE(v_payload, '{}'::jsonb)
        - 'cursor' - 'cursor_json' - 'next_cursor' - 'next_cursor_json' - 'source_cursor' - 'write_cursor_json'
        - 'candidate_cursor' - 'cursor_token' - 'has_cursor' - 'continuation_reason' - 'source_job_id'
        - 'continuation_source_job_id' - 'bounded_continuation_source_job_id' - 'parent_job_id'
        - 'next_phase' - 'write_phase' - 'source_result_summary' - 'source_result_has_more' - 'source_result_next_cursor_present'
        - 'old_row_json' - 'new_row_json' - 'source_row_json' - 'work_payload_json' - 'result_row_json'
        - 'preview_row_json' - 'projection_rows' - 'projected_rows')
      || jsonb_build_object(
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'canonical_job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'resolved_mode', 'DELTA',
        'projection_mode', 'DELTA',
        'projection_class', v_projection_class,
        'lifecycle_event_class', v_event_class,
        'refresh_scope_kind', 'TARGETED_TIMESHEETS',
        'phase', 'INIT_PREFLIGHT',
        'run_mode', 'LATEST_RERUN_AFTER_RUNNING',
        'continuation', false,
        'cursor_json', '{}'::jsonb,
        'projection_run_id', v_new_projection_run_id::text,
        'session_id', p_session_id::text,
        'source_session_id', p_session_id::text,
        'workbench_session_id', p_session_id::text,
        'session_version', COALESCE(v_session_row.version, 0),
        'session_signature', v_session_row.session_signature,
        'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
        'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
        'candidate_id', p_candidate_id::text,
        'targeted_timesheet_ids', v_targeted_json,
        'linked_timesheet_ids', v_linked_json,
        'queue_identity_targeted_timesheet_ids', v_queue_targeted_json,
        'queue_identity_linked_timesheet_ids', v_queue_linked_json,
        'family_timesheet_ids', COALESCE(v_family_scope->'family_timesheet_ids', v_targeted_json),
        'requested_timesheet_ids', v_requested_json,
        'targeted_timesheet_ids_requested', COALESCE(v_family_scope->'requested_targeted_timesheet_ids', v_requested_json),
        'linked_timesheet_ids_requested', COALESCE(v_family_scope->'requested_linked_timesheet_ids', '[]'::jsonb),
        'source_change_seq', v_latest_seq,
        'source_change_sequence', v_latest_seq,
        'latest_source_change_seq', v_latest_seq,
        'delta_coalescing_key', v_family_key,
        'delta_family_key', v_family_key,
        'normalised_delta_family_key', v_family_key,
        'delta_coalescing_hash', md5(v_family_key),
        'dedupe_key', v_dedupe_key,
        'delta_active_running_job_id', v_running.id::text,
        'waiting_after_running_delta_job', true,
        'coalesced_event_count', 1,
        'coalesced_source_change_seqs', jsonb_build_array(v_latest_seq),
        'latest_event_at_utc', v_now::text,
        'reason', v_reason,
        'early_preflight_action', 'UPDATED_WAITING_AFTER_RUNNING_JOB',
        'dirty_marking_skipped', true,
        'session_progress_dirtying_skipped', true,
        'classifier_work_skipped_by_dirty_apply_preflight', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      )
    );

    INSERT INTO public.banking_pay_workbench_jobs AS waiting_job (
      job_type, status, priority, run_at_utc, attempt_count, max_attempts, dedupe_key,
      snapshot_run_id, session_id, candidate_id, payload_json,
      created_at_utc, updated_at_utc, started_at_utc, completed_at_utc, failed_at_utc, last_error_json
    )
    VALUES (
      'WORKBENCH_CANDIDATE_DELTA_REFRESH', 'QUEUED', 43, v_now, 0, 8, v_dedupe_key,
      v_session_row.source_snapshot_run_id, p_session_id, p_candidate_id, v_payload_new,
      v_now, v_now, NULL::timestamptz, NULL::timestamptz, NULL::timestamptz, NULL::jsonb
    )
    ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
    DO UPDATE
    SET priority = LEAST(waiting_job.priority, EXCLUDED.priority),
        run_at_utc = LEAST(waiting_job.run_at_utc, EXCLUDED.run_at_utc),
        payload_json = jsonb_strip_nulls(
          (public._pay_workbench_merge_targeted_scope_payload(COALESCE(waiting_job.payload_json, '{}'::jsonb), EXCLUDED.payload_json)
            - 'cursor' - 'cursor_json' - 'next_cursor' - 'next_cursor_json' - 'source_cursor' - 'write_cursor_json'
            - 'candidate_cursor' - 'cursor_token' - 'has_cursor' - 'continuation_reason' - 'source_job_id'
            - 'continuation_source_job_id' - 'bounded_continuation_source_job_id' - 'parent_job_id'
            - 'next_phase' - 'write_phase' - 'source_result_summary' - 'source_result_has_more' - 'source_result_next_cursor_present')
          || jsonb_build_object(
            'cursor_json', '{}'::jsonb,
            'continuation', false,
            'projection_run_id', v_new_projection_run_id::text,
            'phase', 'INIT_PREFLIGHT',
            'run_mode', 'LATEST_RERUN_AFTER_RUNNING',
            'latest_source_change_seq', v_latest_seq,
            'source_change_seq', v_latest_seq,
            'source_change_sequence', v_latest_seq,
            'normalised_delta_family_key', v_family_key,
            'delta_family_key', v_family_key,
            'delta_coalescing_key', v_family_key,
            'coalesced_event_count', CASE WHEN COALESCE(waiting_job.payload_json->>'coalesced_event_count', '') ~ '^\d{1,9}$' THEN (waiting_job.payload_json->>'coalesced_event_count')::integer + 1 ELSE 2 END,
            'latest_event_at_utc', v_now::text,
            'dirty_marking_skipped', true,
            'session_progress_dirtying_skipped', true
          )
        ),
        updated_at_utc = v_now,
        started_at_utc = NULL,
        completed_at_utc = NULL,
        failed_at_utc = NULL,
        last_error_json = NULL::jsonb
    WHERE UPPER(BTRIM(COALESCE(waiting_job.status, ''))) = 'QUEUED'
    RETURNING waiting_job.id, waiting_job.status, (xmax = 0)
    INTO v_job_id, v_job_status, v_inserted;

    GET DIAGNOSTICS v_insert_count = ROW_COUNT;

    IF COALESCE(v_insert_count, 0) = 0 THEN
      SELECT queued_job.id, queued_job.status
      INTO v_job_id, v_job_status
      FROM public.banking_pay_workbench_jobs AS queued_job
      WHERE queued_job.dedupe_key = v_dedupe_key
        AND UPPER(BTRIM(COALESCE(queued_job.status, ''))) = 'QUEUED'
      LIMIT 1;
    END IF;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      COALESCE(v_job_id::text, v_running.id::text),
      'EARLY_PREFLIGHT_UPDATED_WAITING_AFTER_RUNNING_JOB',
      NULL::jsonb,
      jsonb_build_object(
        'id', CASE WHEN v_job_id IS NULL THEN NULL ELSE v_job_id::text END,
        'running_job_id', v_running.id::text,
        'session_id', p_session_id::text,
        'session_version', COALESCE(v_session_row.version, 0),
        'candidate_id', p_candidate_id::text,
        'targeted_timesheet_ids', v_targeted_json,
        'linked_timesheet_ids', v_linked_json,
        'queue_identity_targeted_timesheet_ids', v_queue_targeted_json,
        'queue_identity_linked_timesheet_ids', v_queue_linked_json,
        'resolved_family_timesheet_ids', COALESCE(v_family_scope->'family_timesheet_ids', v_targeted_json),
        'normalised_delta_family_key', v_family_key,
        'latest_source_change_seq', v_latest_seq,
        'dirty_marking_skipped', true,
        'session_progress_dirtying_skipped', true,
        'classifier_work_skipped', true,
        'trigger_reason', v_reason,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      ),
      'EARLY_PREFLIGHT_UPDATED_WAITING_AFTER_RUNNING_JOB',
      COALESCE(p_actor_user_id, v_session_row.actor_user_id)
    );

    RETURN jsonb_build_object(
      'ok', true,
      'action', 'UPDATED_WAITING_AFTER_RUNNING_JOB',
      'match_found', true,
      'job_id', CASE WHEN v_job_id IS NULL THEN NULL ELSE v_job_id::text END,
      'running_job_id', v_running.id::text,
      'status', COALESCE(v_job_status, 'QUEUED'),
      'candidate_id', p_candidate_id::text,
      'session_id', p_session_id::text,
      'session_version', COALESCE(v_session_row.version, 0),
      'targeted_timesheet_ids', v_targeted_json,
      'linked_timesheet_ids', v_linked_json,
      'queue_identity_targeted_timesheet_ids', v_queue_targeted_json,
      'queue_identity_linked_timesheet_ids', v_queue_linked_json,
      'resolved_family_timesheet_ids', COALESCE(v_family_scope->'family_timesheet_ids', v_targeted_json),
      'normalised_delta_family_key', v_family_key,
      'latest_source_change_seq', v_latest_seq,
      'dirty_marking_skipped', true,
      'session_progress_dirtying_skipped', true,
      'classifier_work_skipped', true,
      'more_due', false,
      'has_more', false,
      'made_progress', true,
      'dirty_apply_can_complete_cleanly', true
    );
  END IF;

  PERFORM public._audit_insert(
    'banking_pay_workbench_job',
    p_session_id::text || ':' || p_candidate_id::text,
    'EARLY_PREFLIGHT_NO_MATCH_PROCEED',
    NULL::jsonb,
    jsonb_build_object(
      'session_id', p_session_id::text,
      'session_version', COALESCE(v_session_row.version, 0),
      'candidate_id', p_candidate_id::text,
      'targeted_timesheet_ids', v_targeted_json,
      'linked_timesheet_ids', v_linked_json,
      'queue_identity_targeted_timesheet_ids', v_queue_targeted_json,
      'queue_identity_linked_timesheet_ids', v_queue_linked_json,
      'resolved_family_timesheet_ids', COALESCE(v_family_scope->'family_timesheet_ids', v_targeted_json),
      'normalised_delta_family_key', v_family_key,
      'latest_source_change_seq', v_latest_seq,
      'dirty_marking_skipped', false,
      'session_progress_dirtying_skipped', false,
      'trigger_reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    ),
    'EARLY_PREFLIGHT_NO_MATCH_PROCEED',
    COALESCE(p_actor_user_id, v_session_row.actor_user_id)
  );

  RETURN jsonb_build_object(
    'ok', true,
    'action', 'PROCEED',
    'match_found', false,
    'candidate_id', p_candidate_id::text,
    'session_id', p_session_id::text,
    'session_version', COALESCE(v_session_row.version, 0),
    'targeted_timesheet_ids', v_targeted_json,
    'linked_timesheet_ids', v_linked_json,
    'resolved_family_timesheet_ids', COALESCE(v_family_scope->'family_timesheet_ids', v_targeted_json),
    'normalised_delta_family_key', v_family_key,
    'latest_source_change_seq', v_latest_seq
  );
END;
$function$;

-- pay_workbench_candidate_delta_refresh_chunk(uuid,uuid,jsonb,jsonb,integer)
CREATE OR REPLACE FUNCTION public.pay_workbench_candidate_delta_refresh_chunk(p_session_id uuid, p_candidate_id uuid, p_payload_json jsonb DEFAULT '{}'::jsonb, p_cursor_json jsonb DEFAULT '{}'::jsonb, p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_started_at timestamptz := clock_timestamp();
  v_elapsed_ms integer := 0;
  v_budget_ms integer := 3000;
  v_budget_cutoff_ms integer := 2400;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 25), 1), 100);
  v_payload_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_cursor_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_cursor_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_cursor_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_settings_json jsonb := '{}'::jsonb;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope_row public.banking_pay_workbench_session_scope%ROWTYPE;
  v_projection_run_id uuid := NULL::uuid;
  v_projection_run_id_text text := NULL::text;
  v_projection_run_status text := NULL::text;
  v_requested_phase text := 'INIT_PREFLIGHT';
  v_persisted_phase text := NULL::text;
  v_requested_phase_order integer := 0;
  v_persisted_phase_order integer := 0;
  v_effective_phase_order integer := 0;
  v_write_resume_recreate_limit integer := 0;
  v_source_change_seq bigint := 0;
  v_source_snapshot_run_id uuid := NULL::uuid;
  v_source_snapshot_run_id_text text := NULL::text;
  v_session_version bigint := NULL::bigint;
  v_projection_mode text := 'DELTA';
  v_projection_class text := 'UNKNOWN';
  v_phase text := 'INIT_PREFLIGHT';
  v_cursor_phase text := NULL::text;
  v_phase_cursor_json jsonb := '{}'::jsonb;
  v_write_phase text := 'NOT_STARTED';
  v_write_cursor_json jsonb := '{}'::jsonb;
  v_classifier_result jsonb := '{}'::jsonb;
  v_stored_classifier_result jsonb := '{}'::jsonb;
  v_effective_classifier_payload_json jsonb := '{}'::jsonb;
  v_stored_classifier_safe_delta boolean := false;
  v_project_result jsonb := '{}'::jsonb;
  v_write_result jsonb := '{}'::jsonb;
  v_candidate_state_result jsonb := '{}'::jsonb;
  v_shadow_result jsonb := '{}'::jsonb;
  v_payload_shadow_mode boolean := false;
  v_payload_shadow_compare_required boolean := false;
  v_payload_shadow_compare_enforced boolean := false;
  v_settings_delta_shadow_mode boolean := false;
  v_classifier_delta_shadow_mode boolean := false;
  v_classifier_payload_shadow_mode boolean := false;
  v_classifier_shadow_compare_required boolean := false;
  v_classifier_shadow_compare_enforced boolean := false;
  v_shadow_flags_reconciled_to_not_required boolean := false;
  v_shadow_compare_required boolean := false;
  v_shadow_compare_enforced boolean := false;
  v_shadow_compare_status text := 'NOT_REQUIRED';
  v_shadow_reference_unavailable boolean := false;
  v_fallback_allowed boolean := true;
  v_fallback_reason text := NULL::text;
  v_dependency_missing_reason text := NULL::text;
  v_targeted_json jsonb := '[]'::jsonb;
  v_linked_json jsonb := '[]'::jsonb;
  v_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_linked_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_resolved_family_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_invalid_targeted_uuid_count integer := 0;
  v_invalid_linked_uuid_count integer := 0;
  v_projected_row_count integer := 0;
  v_written_source_count integer := 0;
  v_written_line_work_count integer := 0;
  v_written_preview_count integer := 0;
  v_source_rows_written integer := 0;
  v_line_rows_written integer := 0;
  v_preview_rows_written integer := 0;
  v_rows_superseded integer := 0;
  v_selected_preserved_count integer := 0;
  v_selected_cleared_count integer := 0;
  v_projection_more_due boolean := false;
  v_projection_cursor_json jsonb := '{}'::jsonb;
  v_current_projection_cursor_json jsonb := '{}'::jsonb;
  v_candidate_state_updated boolean := false;
  v_policy_x_invalid_count integer := 0;
  v_economic_key_invalid_count integer := 0;
  v_projection_cert_invalid_count integer := 0;
  v_key_parity_invalid_count integer := 0;
  v_scope_total_count integer := 0;
  v_scope_ready_count integer := 0;
  v_scope_pending_count integer := 0;
  v_scope_failed_count integer := 0;
  v_line_units_total integer := 0;
  v_line_units_ready integer := 0;
  v_line_units_pending integer := 0;
  v_line_units_failed integer := 0;
  v_preview_row_count integer := 0;
  v_selected_row_count integer := 0;
  v_section_counts_json jsonb := '{}'::jsonb;
  v_candidate_sample_rows_json jsonb := '[]'::jsonb;
  v_pre_candidate_counts_json jsonb := '{}'::jsonb;
  v_post_candidate_counts_json jsonb := '{}'::jsonb;
  v_section_delta_json jsonb := '{}'::jsonb;
  v_preview_row_count_delta integer := 0;
  v_selected_row_count_delta integer := 0;
  v_line_units_total_delta integer := 0;
  v_line_units_ready_delta integer := 0;
  v_line_units_pending_delta integer := 0;
  v_line_units_failed_delta integer := 0;
  v_scope_ready_delta integer := 0;
  v_scope_seeded_delta integer := 0;
  v_scope_pending_delta integer := 0;
  v_scope_failed_delta integer := 0;
  v_return_json jsonb := '{}'::jsonb;
  v_live_source_change_seq bigint := 0;
  v_superseded_projection_runs integer := 0;
  v_prelock_payload_source_change_seq bigint := 0;
  v_prelock_cursor_source_change_seq bigint := 0;
  v_prelock_projection_source_change_seq bigint := 0;
  v_prelock_effective_latest_source_seq bigint := 0;
  v_prelock_projection_run_id uuid := NULL::uuid;
  v_prelock_projection_run_id_text text := NULL::text;
  v_prelock_family_key text := NULL::text;
  v_admission_result jsonb := '{}'::jsonb;
  v_admission_seal_json jsonb := '{}'::jsonb;
  v_admission_seal_digest text := NULL::text;
  v_admission_seal_version integer := 0;
  v_sealed_lifecycle_delta boolean := false;
  v_lifecycle_event_class text := NULL::text;
  v_finalize_result jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_session_id IS NULL OR p_candidate_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'fallback_required', true,
      'fallback_reason', 'SESSION_ID_AND_CANDIDATE_ID_REQUIRED',
      'more_due', false,
      'has_more', false,
      'made_progress', false,
      'delta_refresh_complete', false,
      'stop_reason', 'DELTA_INPUT_INVALID'
    );
  END IF;

  SELECT COALESCE(to_jsonb(settings_row), '{}'::jsonb)
  INTO v_settings_json
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id = 1
  LIMIT 1;

  v_settings_delta_shadow_mode := lower(BTRIM(COALESCE(
    v_settings_json->>'banking_pay_workbench_delta_shadow_mode',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF COALESCE(v_settings_json->>'banking_pay_workbench_delta_budget_ms', '') ~ '^[0-9]{1,9}$' THEN
    v_budget_ms := LEAST(GREATEST((v_settings_json->>'banking_pay_workbench_delta_budget_ms')::integer, 500), 30000);
  ELSE
    v_budget_ms := 3000;
  END IF;
  v_budget_cutoff_ms := GREATEST(250, FLOOR(v_budget_ms * 0.80)::integer);

  v_prelock_projection_run_id_text := NULLIF(BTRIM(COALESCE(
    v_cursor_json->>'projection_run_id',
    v_cursor_json#>>'{cursor,projection_run_id}',
    v_payload_json->>'projection_run_id',
    v_payload_json#>>'{cursor,projection_run_id}',
    v_payload_json#>>'{cursor_json,projection_run_id}',
    v_payload_json#>>'{cursor_json,cursor,projection_run_id}',
    ''
  )), '');
  IF v_prelock_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_prelock_projection_run_id := v_prelock_projection_run_id_text::uuid;
  END IF;

  v_prelock_payload_source_change_seq := GREATEST(
    COALESCE(CASE WHEN COALESCE(v_payload_json->>'latest_source_change_seq', '') ~ '^\d{1,18}$' THEN (v_payload_json->>'latest_source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(v_payload_json->>'source_change_seq', '') ~ '^\d{1,18}$' THEN (v_payload_json->>'source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(v_payload_json->>'source_change_sequence', '') ~ '^\d{1,18}$' THEN (v_payload_json->>'source_change_sequence')::bigint END, 0)
  );
  v_prelock_cursor_source_change_seq := GREATEST(
    COALESCE(CASE WHEN COALESCE(v_cursor_json->>'source_change_seq', '') ~ '^\d{1,18}$' THEN (v_cursor_json->>'source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(v_cursor_json->>'source_change_sequence', '') ~ '^\d{1,18}$' THEN (v_cursor_json->>'source_change_sequence')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(v_cursor_json#>>'{cursor,source_change_seq}', '') ~ '^\d{1,18}$' THEN (v_cursor_json#>>'{cursor,source_change_seq}')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(v_payload_json#>>'{cursor,source_change_seq}', '') ~ '^\d{1,18}$' THEN (v_payload_json#>>'{cursor,source_change_seq}')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(v_payload_json#>>'{cursor,cursor,source_change_seq}', '') ~ '^\d{1,18}$' THEN (v_payload_json#>>'{cursor,cursor,source_change_seq}')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(v_payload_json#>>'{cursor_json,source_change_seq}', '') ~ '^\d{1,18}$' THEN (v_payload_json#>>'{cursor_json,source_change_seq}')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(v_payload_json#>>'{cursor_json,cursor,source_change_seq}', '') ~ '^\d{1,18}$' THEN (v_payload_json#>>'{cursor_json,cursor,source_change_seq}')::bigint END, 0)
  );
  v_prelock_family_key := COALESCE(
    NULLIF(BTRIM(COALESCE(v_payload_json->>'normalised_delta_family_key', '')), ''),
    NULLIF(BTRIM(COALESCE(v_payload_json->>'delta_family_key', '')), ''),
    NULLIF(BTRIM(COALESCE(v_payload_json->>'delta_coalescing_key', '')), ''),
    NULL::text
  );

  SELECT COALESCE(change_counter.seq, 0)
  INTO v_live_source_change_seq
  FROM public.app_change_counters AS change_counter
  WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;

  IF v_prelock_projection_run_id IS NOT NULL THEN
    SELECT COALESCE(projection_run.source_change_seq, 0)
    INTO v_prelock_projection_source_change_seq
    FROM public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run
    WHERE projection_run.id = v_prelock_projection_run_id;
  END IF;

  v_prelock_effective_latest_source_seq := GREATEST(
    COALESCE(v_live_source_change_seq, 0),
    COALESCE(v_prelock_payload_source_change_seq, 0)
  );

  IF (
    (COALESCE(v_prelock_cursor_source_change_seq, 0) > 0 AND v_prelock_effective_latest_source_seq > COALESCE(v_prelock_cursor_source_change_seq, 0))
    OR (COALESCE(v_prelock_projection_source_change_seq, 0) > 0 AND v_prelock_effective_latest_source_seq > COALESCE(v_prelock_projection_source_change_seq, 0))
  ) THEN
    IF v_prelock_projection_run_id IS NOT NULL THEN
      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run
      SET status = CASE WHEN UPPER(BTRIM(COALESCE(projection_run.status, ''))) = 'COMPLETED' THEN projection_run.status ELSE 'FAILED' END,
          fallback_required = false,
          fallback_reason = CASE WHEN UPPER(BTRIM(COALESCE(projection_run.status, ''))) = 'COMPLETED' THEN projection_run.fallback_reason ELSE 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ' END,
          diagnostics_json = jsonb_strip_nulls(
            COALESCE(projection_run.diagnostics_json, '{}'::jsonb)
            || jsonb_build_object(
              'stale_continuation_superseded_before_session_lock', true,
              'stale_continuation_superseded_at_utc', v_now::text,
              'payload_source_change_seq', v_prelock_payload_source_change_seq,
              'cursor_source_change_seq', v_prelock_cursor_source_change_seq,
              'projection_run_source_change_seq', v_prelock_projection_source_change_seq,
              'live_candidate_source_change_seq', v_live_source_change_seq,
              'normalised_delta_family_key', v_prelock_family_key
            )
          ),
          updated_at_utc = v_now,
          completed_at_utc = COALESCE(projection_run.completed_at_utc, v_now)
      WHERE projection_run.id = v_prelock_projection_run_id;
    END IF;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      COALESCE(v_payload_json->>'job_id', v_payload_json->>'source_job_id', p_session_id::text || ':' || p_candidate_id::text),
      'STALE_CONTINUATION_SUPERSEDED_BEFORE_SESSION_LOCK',
      NULL::jsonb,
      jsonb_build_object(
        'session_id', p_session_id::text,
        'candidate_id', p_candidate_id::text,
        'projection_run_id', CASE WHEN v_prelock_projection_run_id IS NULL THEN NULL ELSE v_prelock_projection_run_id::text END,
        'normalised_delta_family_key', v_prelock_family_key,
        'payload_source_change_seq', v_prelock_payload_source_change_seq,
        'cursor_source_change_seq', v_prelock_cursor_source_change_seq,
        'projection_run_source_change_seq', v_prelock_projection_source_change_seq,
        'live_candidate_source_change_seq', v_live_source_change_seq,
        'session_progress_lock_skipped', true,
        'session_lock_skipped', true,
        'write_compatible_outputs_blocked', true,
        'more_due', false,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      ),
      'STALE_CONTINUATION_SUPERSEDED_BEFORE_SESSION_LOCK',
      CASE WHEN COALESCE(v_payload_json->>'actor_user_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN (v_payload_json->>'actor_user_id')::uuid ELSE NULL::uuid END
    );

    RETURN jsonb_build_object(
      'ok', true,
      'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'projection_run_id', CASE WHEN v_prelock_projection_run_id IS NULL THEN NULL ELSE v_prelock_projection_run_id::text END,
      'normalised_delta_family_key', v_prelock_family_key,
      'source_change_seq', v_prelock_effective_latest_source_seq,
      'cursor_source_change_seq', v_prelock_cursor_source_change_seq,
      'projection_run_source_change_seq', v_prelock_projection_source_change_seq,
      'live_candidate_source_change_seq', v_live_source_change_seq,
      'fallback_required', false,
      'more_due', false,
      'has_more', false,
      'made_progress', true,
      'delta_refresh_complete', true,
      'superseded_by_newer_source_change_seq', true,
      'stop_reason', 'STALE_CONTINUATION_SUPERSEDED_BEFORE_SESSION_LOCK',
      'session_lock_skipped', true,
      'write_compatible_outputs_blocked', true,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    );
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
    AND session_row.status = 'OPEN'
    AND session_row.discarded_at_utc IS NULL
  FOR UPDATE;

  SELECT scope_row.*
  INTO v_scope_row
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = p_candidate_id
  FOR UPDATE;

  IF v_session_row.id IS NULL OR v_scope_row.id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'fallback_required', true,
      'fallback_reason', 'SESSION_OR_SCOPE_NOT_OPEN',
      'more_due', false,
      'has_more', false,
      'made_progress', true,
      'delta_refresh_complete', false,
      'stop_reason', 'DELTA_FALLBACK_REQUIRED'
    );
  END IF;

  IF to_regclass('public.banking_pay_workbench_candidate_delta_projection_runs') IS NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'fallback_required', true,
      'fallback_reason', 'DELTA_PROJECTION_RUN_TABLE_MISSING',
      'more_due', false,
      'has_more', false,
      'made_progress', true,
      'delta_refresh_complete', false,
      'stop_reason', 'DELTA_FALLBACK_REQUIRED'
    );
  END IF;

  v_projection_run_id_text := NULLIF(BTRIM(COALESCE(
    v_cursor_json->>'projection_run_id',
    v_payload_json->>'projection_run_id',
    ''
  )), '');

  IF v_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_projection_run_id := v_projection_run_id_text::uuid;
  ELSE
    v_projection_run_id := gen_random_uuid();
  END IF;

  v_cursor_phase := upper(BTRIM(COALESCE(v_cursor_json->>'phase', '')));
  v_phase := upper(BTRIM(COALESCE(v_cursor_json->>'phase', v_payload_json->>'phase', 'INIT_PREFLIGHT')));
  IF v_phase = 'SHADOW_COMPARE' THEN
    v_phase := 'VERIFY_PARITY_OR_SHADOW';
  END IF;
  IF v_cursor_phase = 'SHADOW_COMPARE' THEN
    v_cursor_phase := 'VERIFY_PARITY_OR_SHADOW';
  END IF;

  IF v_phase NOT IN (
    'INIT_PREFLIGHT',
    'RESOLVE_SCOPE',
    'PROJECT_ROWS',
    'WRITE_COMPATIBLE_OUTPUTS',
    'VERIFY_PARITY_OR_SHADOW',
    'UPDATE_CANDIDATE_STATE',
    'FINALISE'
  ) THEN
    v_phase := 'INIT_PREFLIGHT';
  END IF;
  v_requested_phase := v_phase;

  v_phase_cursor_json := CASE
    WHEN jsonb_typeof(v_cursor_json->'cursor') = 'object' THEN COALESCE(v_cursor_json->'cursor', '{}'::jsonb)
    WHEN jsonb_typeof(v_payload_json->'cursor_json') = 'object' THEN COALESCE(v_payload_json->'cursor_json', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  IF COALESCE(v_payload_json->>'session_version', '') ~ '^[0-9]{1,18}$' THEN
    v_session_version := (v_payload_json->>'session_version')::bigint;
  ELSE
    v_session_version := COALESCE(v_session_row.version, 1);
  END IF;

  IF COALESCE(v_payload_json->>'source_change_seq', v_payload_json->>'source_change_sequence', '') ~ '^-?[0-9]{1,18}$' THEN
    v_source_change_seq := COALESCE(v_payload_json->>'source_change_seq', v_payload_json->>'source_change_sequence')::bigint;
  ELSE
    v_source_change_seq := 0;
  END IF;

  SELECT COALESCE(change_counter.seq, 0)
  INTO v_live_source_change_seq
  FROM public.app_change_counters AS change_counter
  WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;

  v_live_source_change_seq := COALESCE(v_live_source_change_seq, 0);

  IF COALESCE(v_source_change_seq, 0) > 0
     AND COALESCE(v_live_source_change_seq, 0) > COALESCE(v_source_change_seq, 0) THEN
    UPDATE public.banking_pay_workbench_preview_rows AS preview_row_update
    SET selected = false,
        selection_state = 'DIRTY',
        status = 'DIRTY',
        row_json = jsonb_strip_nulls(
          COALESCE(preview_row_update.row_json, '{}'::jsonb)
          || jsonb_build_object(
            'superseded_by_newer_source_change_seq', true,
            'source_change_seq', v_source_change_seq,
            'newer_source_change_seq', v_live_source_change_seq,
            'superseded_at_utc', v_now::text
          )
        ),
        updated_at_utc = v_now
    WHERE preview_row_update.session_id = p_session_id
      AND preview_row_update.candidate_id = p_candidate_id
      AND COALESCE(preview_row_update.row_json->>'projection_run_id', '') = v_projection_run_id::text;

    UPDATE public.banking_pay_workbench_candidate_source_lines AS source_row_update
    SET status = 'SUPERSEDED',
        source_row_json = jsonb_strip_nulls(
          COALESCE(source_row_update.source_row_json, '{}'::jsonb)
          || jsonb_build_object(
            'superseded_by_newer_source_change_seq', true,
            'source_change_seq', v_source_change_seq,
            'newer_source_change_seq', v_live_source_change_seq,
            'superseded_at_utc', v_now::text
          )
        ),
        updated_at_utc = v_now
    WHERE source_row_update.session_id = p_session_id
      AND source_row_update.candidate_id = p_candidate_id
      AND source_row_update.source_build_run_id = v_projection_run_id
      AND source_row_update.status IN ('CURRENT', 'DIRTY');

    UPDATE public.banking_pay_workbench_candidate_line_work AS line_work_update
    SET status = 'SKIPPED',
        result_row_json = jsonb_strip_nulls(
          COALESCE(line_work_update.result_row_json, '{}'::jsonb)
          || jsonb_build_object(
            'superseded_by_newer_source_change_seq', true,
            'source_change_seq', v_source_change_seq,
            'newer_source_change_seq', v_live_source_change_seq,
            'superseded_at_utc', v_now::text
          )
        ),
        updated_at_utc = v_now
    WHERE line_work_update.session_id = p_session_id
      AND line_work_update.candidate_id = p_candidate_id
      AND (
        COALESCE(line_work_update.work_payload_json->>'projection_run_id', '') = v_projection_run_id::text
        OR COALESCE(line_work_update.result_row_json->>'projection_run_id', '') = v_projection_run_id::text
      )
      AND UPPER(BTRIM(COALESCE(line_work_update.status, ''))) NOT IN ('ERROR', 'FAILED', 'SKIPPED');

    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
    SET status = 'FAILED',
        fallback_required = false,
        fallback_reason = 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ',
        diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
          || jsonb_build_object(
            'superseded_by_newer_source_change_seq', true,
            'source_change_seq', v_source_change_seq,
            'newer_source_change_seq', v_live_source_change_seq,
            'terminalised_by', 'pay_workbench_candidate_delta_refresh_chunk',
            'terminalised_at_utc', v_now::text
          ),
        updated_at_utc = v_now,
        completed_at_utc = v_now
    WHERE projection_run_update.id = v_projection_run_id
      AND projection_run_update.session_id = p_session_id
      AND projection_run_update.candidate_id = p_candidate_id
      AND UPPER(BTRIM(COALESCE(projection_run_update.status, ''))) = 'RUNNING';

    GET DIAGNOSTICS v_superseded_projection_runs = ROW_COUNT;

    RETURN jsonb_build_object(
      'ok', true,
      'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'projection_run_id', v_projection_run_id::text,
      'source_change_seq', v_source_change_seq,
      'newer_source_change_seq', v_live_source_change_seq,
      'fallback_required', false,
      'more_due', false,
      'has_more', false,
      'made_progress', true,
      'delta_refresh_complete', true,
      'superseded_by_newer_source_change_seq', true,
      'superseded_projection_runs', COALESCE(v_superseded_projection_runs, 0),
      'stop_reason', 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ'
    );
  END IF;

  v_source_snapshot_run_id_text := NULLIF(BTRIM(COALESCE(v_payload_json->>'source_snapshot_run_id', v_payload_json->>'snapshot_run_id', '')), '');
  IF v_source_snapshot_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_source_snapshot_run_id := v_source_snapshot_run_id_text::uuid;
  ELSE
    v_source_snapshot_run_id := v_session_row.source_snapshot_run_id;
  END IF;

  v_payload_shadow_mode := lower(BTRIM(COALESCE(
    v_payload_json->>'shadow_mode',
    v_payload_json->>'payload_shadow_mode',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_payload_shadow_compare_required := lower(BTRIM(COALESCE(
    v_payload_json->>'shadow_compare_required',
    v_payload_json->>'shadow_compare',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_payload_shadow_compare_enforced := lower(BTRIM(COALESCE(
    v_payload_json->>'shadow_compare_enforced',
    v_payload_json->>'enforce_shadow_compare',
    v_payload_json->>'shadow_enforced',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_shadow_compare_required := COALESCE(v_payload_shadow_compare_required, false);
  v_shadow_compare_enforced := COALESCE(v_payload_shadow_compare_enforced, false);
  v_fallback_allowed := lower(BTRIM(COALESCE(v_payload_json->>'fallback_allowed', 'true'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_stored_classifier_result := CASE
    WHEN jsonb_typeof(COALESCE(v_payload_json->'classifier_result', '{}'::jsonb)) = 'object'
      THEN COALESCE(v_payload_json->'classifier_result', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_stored_classifier_safe_delta :=
    UPPER(BTRIM(COALESCE(v_stored_classifier_result->>'resolved_mode', ''))) = 'DELTA'
    AND UPPER(BTRIM(COALESCE(v_stored_classifier_result->>'projection_mode', v_stored_classifier_result->>'resolved_mode', ''))) = 'DELTA'
    AND UPPER(BTRIM(COALESCE(v_stored_classifier_result->>'resolved_job_type', v_stored_classifier_result->>'job_type', ''))) = 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
    AND UPPER(BTRIM(COALESCE(v_stored_classifier_result->>'projection_class', ''))) = 'NORMAL_TIMESHEET'
    AND lower(BTRIM(COALESCE(v_stored_classifier_result->>'fast_path_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    AND lower(BTRIM(COALESCE(v_stored_classifier_result->>'fallback_required', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
    AND lower(BTRIM(COALESCE(v_stored_classifier_result->>'no_op', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
    AND lower(BTRIM(COALESCE(v_stored_classifier_result->'complexity_flags'->>'ordinary_timesheet_edit_save_no_dirty', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
    AND lower(BTRIM(COALESCE(v_stored_classifier_result->>'banking_pay_dirty_required', v_stored_classifier_result->'complexity_flags'->>'banking_pay_dirty_required', 'true'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    AND lower(BTRIM(COALESCE(v_stored_classifier_result->'complexity_flags'->>'force_legacy', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
    AND lower(BTRIM(COALESCE(v_stored_classifier_result->'complexity_flags'->>'force_source_build', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
    AND jsonb_typeof(COALESCE(v_stored_classifier_result->'targeted_timesheet_ids', '[]'::jsonb)) = 'array'
    AND jsonb_array_length(COALESCE(v_stored_classifier_result->'targeted_timesheet_ids', '[]'::jsonb)) > 0;

  IF v_phase = 'INIT_PREFLIGHT' THEN
    v_effective_classifier_payload_json := v_payload_json;

    IF v_stored_classifier_safe_delta IS TRUE
       AND lower(BTRIM(COALESCE(v_effective_classifier_payload_json->>'banking_pay_dirty_required', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
       AND lower(BTRIM(COALESCE(v_effective_classifier_payload_json->>'explicit_banking_pay_action', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
       AND NULLIF(BTRIM(COALESCE(v_effective_classifier_payload_json->>'mutation_context', v_effective_classifier_payload_json->>'lifecycle_mutation_context', '')), '') IS NULL THEN
      v_effective_classifier_payload_json := jsonb_strip_nulls(
        v_effective_classifier_payload_json
        || jsonb_build_object(
          'mutation_context', COALESCE(
            NULLIF(BTRIM(v_stored_classifier_result->'complexity_flags'->>'mutation_context'), ''),
            NULLIF(BTRIM(v_stored_classifier_result->'complexity_flags'->>'lifecycle_mutation_context'), ''),
            'timesheet_unauthorise'
          ),
          'lifecycle_mutation_context', COALESCE(
            NULLIF(BTRIM(v_stored_classifier_result->'complexity_flags'->>'lifecycle_mutation_context'), ''),
            NULLIF(BTRIM(v_stored_classifier_result->'complexity_flags'->>'mutation_context'), ''),
            'timesheet_unauthorise'
          ),
          'trigger_table', COALESCE(NULLIF(BTRIM(v_stored_classifier_result->'complexity_flags'->>'trigger_table'), ''), 'timesheets'),
          'trigger_op', COALESCE(NULLIF(BTRIM(v_stored_classifier_result->'complexity_flags'->>'trigger_operation'), ''), 'UPDATE'),
          'trigger_operation', COALESCE(NULLIF(BTRIM(v_stored_classifier_result->'complexity_flags'->>'trigger_operation'), ''), 'UPDATE'),
          'authorise_boundary_changed', lower(BTRIM(COALESCE(v_stored_classifier_result->'complexity_flags'->>'authorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
          'unauthorise_boundary_changed', CASE
            WHEN lower(BTRIM(COALESCE(v_stored_classifier_result->'complexity_flags'->>'unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN true
            WHEN lower(BTRIM(COALESCE(v_stored_classifier_result->'complexity_flags'->>'authorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN false
            ELSE true
          END,
          'explicit_banking_pay_action', true,
          'banking_pay_dirty_required', true,
          'ordinary_timesheet_edit_save_no_dirty', false,
          'projection_class', 'NORMAL_TIMESHEET',
          'refresh_scope_kind', COALESCE(NULLIF(BTRIM(v_stored_classifier_result->>'refresh_scope_kind'), ''), 'TARGETED_TIMESHEETS'),
          'targeted_timesheet_ids', CASE
            WHEN jsonb_typeof(COALESCE(v_effective_classifier_payload_json->'targeted_timesheet_ids', '[]'::jsonb)) = 'array'
             AND jsonb_array_length(COALESCE(v_effective_classifier_payload_json->'targeted_timesheet_ids', '[]'::jsonb)) > 0
              THEN v_effective_classifier_payload_json->'targeted_timesheet_ids'
            ELSE COALESCE(v_stored_classifier_result->'targeted_timesheet_ids', '[]'::jsonb)
          END,
          'linked_timesheet_ids', CASE
            WHEN jsonb_typeof(COALESCE(v_effective_classifier_payload_json->'linked_timesheet_ids', '[]'::jsonb)) = 'array'
             AND jsonb_array_length(COALESCE(v_effective_classifier_payload_json->'linked_timesheet_ids', '[]'::jsonb)) > 0
              THEN v_effective_classifier_payload_json->'linked_timesheet_ids'
            ELSE COALESCE(v_stored_classifier_result->'linked_timesheet_ids', '[]'::jsonb)
          END,
          'stored_classifier_context_rehydrated', true
        )
      );
    END IF;

    v_classifier_result := public.pay_workbench_delta_refresh_classify_v1(
      p_session_id,
      p_candidate_id,
      v_effective_classifier_payload_json || jsonb_build_object(
        'session_id', p_session_id::text,
        'candidate_id', p_candidate_id::text,
        'projection_run_id', v_projection_run_id::text,
        'session_version', COALESCE(v_session_version, v_session_row.version),
        'source_snapshot_run_id', CASE WHEN v_source_snapshot_run_id IS NULL THEN NULL ELSE v_source_snapshot_run_id::text END
      )
    );

    IF v_stored_classifier_safe_delta IS TRUE
       AND (
         UPPER(BTRIM(COALESCE(v_classifier_result->>'resolved_mode', 'LEGACY'))) <> 'DELTA'
         OR COALESCE((v_classifier_result->>'fast_path_allowed')::boolean, false) IS NOT TRUE
         OR UPPER(BTRIM(COALESCE(v_classifier_result->>'projection_class', 'UNKNOWN'))) NOT IN ('NORMAL_TIMESHEET','TIMESHEET_LIFECYCLE')
       ) THEN
      v_classifier_result := jsonb_strip_nulls(
        v_stored_classifier_result
        || jsonb_build_object(
          'resolved_mode', 'DELTA',
          'projection_mode', 'DELTA',
          'resolved_job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
          'projection_class', COALESCE(NULLIF(UPPER(BTRIM(v_stored_classifier_result->>'projection_class')),''),'NORMAL_TIMESHEET'),
          'fast_path_allowed', true,
          'delta_refresh_required', true,
          'source_build_required', false,
          'fallback_required', false,
          'fallback_reason', NULL::text,
          'no_op', false,
          'blocked', false,
          'banking_pay_dirty_required', true,
          'ordinary_timesheet_edit_save_no_dirty', false,
          'classifier_recovered_from_stored_result', true,
          'classifier_recovery_reason', 'PRESERVED_TARGETED_DELTA_CLASSIFIER_RESULT'
        )
      );
    END IF;

    v_projection_mode := upper(BTRIM(COALESCE(v_classifier_result->>'projection_mode', v_payload_json->>'projection_mode', 'DELTA')));
    v_projection_class := upper(BTRIM(COALESCE(v_classifier_result->>'projection_class', v_payload_json->>'projection_class', 'UNKNOWN')));
    v_classifier_delta_shadow_mode := lower(BTRIM(COALESCE(v_classifier_result#>>'{complexity_flags,delta_shadow_mode}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_classifier_payload_shadow_mode := lower(BTRIM(COALESCE(v_classifier_result#>>'{complexity_flags,payload_shadow_mode}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_classifier_shadow_compare_required := lower(BTRIM(COALESCE(v_classifier_result->>'shadow_compare_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_classifier_shadow_compare_enforced := lower(BTRIM(COALESCE(v_classifier_result->>'shadow_compare_enforced', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_shadow_compare_required := COALESCE(v_shadow_compare_required, false)
      OR COALESCE(v_classifier_delta_shadow_mode, false)
      OR COALESCE(v_classifier_payload_shadow_mode, false)
      OR COALESCE(v_classifier_shadow_compare_required, false);
    v_shadow_compare_enforced := COALESCE(v_shadow_compare_required, false)
      AND (COALESCE(v_shadow_compare_enforced, false) OR COALESCE(v_classifier_shadow_compare_enforced, false));

    v_targeted_json := COALESCE(v_classifier_result->'targeted_timesheet_ids', v_payload_json->'targeted_timesheet_ids', '[]'::jsonb);
    v_linked_json := COALESCE(v_classifier_result->'linked_timesheet_ids', v_payload_json->'linked_timesheet_ids', '[]'::jsonb);

    IF v_projection_class='TIMESHEET_LIFECYCLE' THEN
      v_lifecycle_event_class:=CASE
        WHEN lower(BTRIM(COALESCE(v_payload_json->>'unauthorise_boundary_changed',v_payload_json->>'timesheet_unauthorise_boundary_changed','false'))) IN ('true','t','1','yes','y','on')
          OR lower(BTRIM(COALESCE(v_payload_json->>'lifecycle_mutation_context',v_payload_json->>'mutation_context',''))) IN ('timesheet_unauthorise','unauthorise_timesheet')
        THEN 'UNAUTHORISE' ELSE 'AUTHORISE' END;
      v_source_change_seq:=GREATEST(COALESCE(v_source_change_seq,0),COALESCE(v_live_source_change_seq,0));
      v_admission_result:=private.pay_workbench_targeted_delta_admission_v1(
        p_session_id,p_candidate_id,v_projection_run_id,v_lifecycle_event_class,
        v_targeted_timesheet_ids,v_linked_timesheet_ids,v_source_change_seq
      );
      IF COALESCE((v_admission_result->>'admitted')::boolean,false) IS NOT TRUE THEN
        RETURN jsonb_build_object(
          'ok',true,'job_type','WORKBENCH_CANDIDATE_DELTA_REFRESH',
          'projection_run_id',v_projection_run_id,'fallback_required',true,
          'fallback_reason',COALESCE(v_admission_result->>'reason','TARGETED_DELTA_ADMISSION_FAILED'),
          'more_due',false,'has_more',false,'made_progress',true,
          'delta_refresh_complete',false,'stop_reason','DELTA_FALLBACK_REQUIRED'
        );
      END IF;
      v_admission_seal_json:=v_admission_result->'admission_seal_json';
      v_admission_seal_digest:=v_admission_result->>'admission_seal_digest';
      v_sealed_lifecycle_delta:=true;
    END IF;

    INSERT INTO public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run (
      id,
      session_id,
      candidate_id,
      session_version,
      source_change_seq,
      source_snapshot_run_id,
      projection_mode,
      projection_class,
      phase,
      cursor_json,
      targeted_timesheet_ids,
      linked_timesheet_ids,
      status,
      fallback_required,
      fallback_reason,
      diagnostics_json,
      write_phase,
      write_cursor_json,
      projected_row_count,
      written_source_count,
      written_line_work_count,
      written_preview_count,
      candidate_state_updated,
      projection_fingerprint,
      shadow_compare_required,
      shadow_compare_status,
      shadow_compare_enforced,
      admission_seal_version,
      admission_seal_json,
      admission_seal_digest,
      admission_sealed_at_utc,
      started_at_utc,
      updated_at_utc
    )
    VALUES (
      v_projection_run_id,
      p_session_id,
      p_candidate_id,
      COALESCE(v_session_version, v_session_row.version, 1),
      COALESCE(v_source_change_seq, 0),
      v_source_snapshot_run_id,
      CASE WHEN v_projection_mode IN ('DELTA', 'READINESS_PATCH', 'RESERVATION_PATCH', 'POST_DRAFT_OVERLAY', 'CLONE_REBASE', 'SHADOW_COMPARE') THEN v_projection_mode ELSE 'DELTA' END,
      v_projection_class,
      'INIT_PREFLIGHT',
      jsonb_build_object('phase', 'INIT_PREFLIGHT', 'cursor', '{}'::jsonb),
      CASE WHEN jsonb_typeof(v_targeted_json) = 'array' THEN v_targeted_json ELSE '[]'::jsonb END,
      CASE WHEN jsonb_typeof(v_linked_json) = 'array' THEN v_linked_json ELSE '[]'::jsonb END,
      'RUNNING',
      false,
      NULL::text,
      jsonb_build_object('classifier_result', v_classifier_result, 'created_by', 'pay_workbench_candidate_delta_refresh_chunk'),
      'NOT_STARTED',
      '{}'::jsonb,
      0,
      0,
      0,
      0,
      false,
      NULL::text,
      v_shadow_compare_required,
      CASE WHEN v_shadow_compare_required OR v_shadow_compare_enforced THEN 'PENDING' ELSE 'NOT_REQUIRED' END,
      v_shadow_compare_enforced,
      CASE WHEN v_sealed_lifecycle_delta THEN 1 ELSE NULL END,
      CASE WHEN v_sealed_lifecycle_delta THEN v_admission_seal_json ELSE '{}'::jsonb END,
      CASE WHEN v_sealed_lifecycle_delta THEN v_admission_seal_digest ELSE NULL END,
      CASE WHEN v_sealed_lifecycle_delta THEN v_now ELSE NULL END,
      v_now,
      v_now
    )
    ON CONFLICT (id) DO UPDATE SET
      session_version = EXCLUDED.session_version,
      source_change_seq = EXCLUDED.source_change_seq,
      source_snapshot_run_id = EXCLUDED.source_snapshot_run_id,
      projection_mode = EXCLUDED.projection_mode,
      projection_class = EXCLUDED.projection_class,
      phase = EXCLUDED.phase,
      cursor_json = EXCLUDED.cursor_json,
      targeted_timesheet_ids = EXCLUDED.targeted_timesheet_ids,
      linked_timesheet_ids = EXCLUDED.linked_timesheet_ids,
      status = 'RUNNING',
      fallback_required = false,
      fallback_reason = NULL::text,
      diagnostics_json = COALESCE(projection_run.diagnostics_json, '{}'::jsonb) || EXCLUDED.diagnostics_json,
      write_phase = 'NOT_STARTED',
      write_cursor_json = '{}'::jsonb,
      projected_row_count = 0,
      written_source_count = 0,
      written_line_work_count = 0,
      written_preview_count = 0,
      candidate_state_updated = false,
      shadow_compare_required = EXCLUDED.shadow_compare_required,
      shadow_compare_status = EXCLUDED.shadow_compare_status,
      shadow_compare_enforced = EXCLUDED.shadow_compare_enforced,
      admission_seal_version = CASE
        WHEN projection_run.admission_seal_version IS NULL THEN EXCLUDED.admission_seal_version
        ELSE projection_run.admission_seal_version END,
      admission_seal_json = CASE
        WHEN projection_run.admission_seal_version IS NULL THEN EXCLUDED.admission_seal_json
        ELSE projection_run.admission_seal_json END,
      admission_seal_digest = CASE
        WHEN projection_run.admission_seal_version IS NULL THEN EXCLUDED.admission_seal_digest
        ELSE projection_run.admission_seal_digest END,
      admission_sealed_at_utc = CASE
        WHEN projection_run.admission_seal_version IS NULL THEN EXCLUDED.admission_sealed_at_utc
        ELSE projection_run.admission_sealed_at_utc END,
      completed_at_utc = NULL::timestamptz,
      updated_at_utc = v_now;

    IF v_sealed_lifecycle_delta AND EXISTS (
      SELECT 1 FROM public.banking_pay_workbench_candidate_delta_projection_runs AS sealed_run
      WHERE sealed_run.id=v_projection_run_id
        AND (sealed_run.admission_seal_version<>1
          OR sealed_run.admission_seal_digest IS DISTINCT FROM v_admission_seal_digest
          OR sealed_run.admission_seal_json IS DISTINCT FROM v_admission_seal_json)
    ) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_TARGETED_DELTA_SEAL_REPLAY_CONFLICT' USING ERRCODE='P0001';
    END IF;

    WITH supersedable_older_projection_runs AS MATERIALIZED (
      SELECT older_projection_run.id
      FROM public.banking_pay_workbench_candidate_delta_projection_runs AS older_projection_run
      WHERE older_projection_run.session_id = p_session_id
        AND older_projection_run.candidate_id = p_candidate_id
        AND older_projection_run.id <> v_projection_run_id
        AND UPPER(BTRIM(COALESCE(older_projection_run.status, ''))) = 'RUNNING'
        AND COALESCE(older_projection_run.source_change_seq, 0) < COALESCE(v_source_change_seq, 0)
        AND UPPER(BTRIM(COALESCE(older_projection_run.projection_class, ''))) = v_projection_class
      FOR UPDATE SKIP LOCKED
    )
    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS older_projection_run
    SET status = 'FAILED',
        fallback_required = false,
        fallback_reason = 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ',
        diagnostics_json = COALESCE(older_projection_run.diagnostics_json, '{}'::jsonb)
          || jsonb_build_object(
            'superseded_by_newer_source_change_seq', true,
            'source_change_seq', COALESCE(older_projection_run.source_change_seq, 0),
            'newer_source_change_seq', COALESCE(v_source_change_seq, 0),
            'newer_projection_run_id', v_projection_run_id::text,
            'terminalised_by', 'pay_workbench_candidate_delta_refresh_chunk_init_preflight',
            'terminalised_at_utc', v_now::text
          ),
        completed_at_utc = v_now,
        updated_at_utc = v_now
    FROM supersedable_older_projection_runs
    WHERE older_projection_run.id = supersedable_older_projection_runs.id;

    GET DIAGNOSTICS v_superseded_projection_runs = ROW_COUNT;

    IF COALESCE(v_superseded_projection_runs, 0) > 0 THEN
      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
            || jsonb_build_object(
              'older_running_projection_runs_superseded', v_superseded_projection_runs,
              'older_runs_superseded_at_utc', v_now::text
            ),
          updated_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id;
    END IF;

    IF COALESCE((v_classifier_result->>'fast_path_allowed')::boolean, false) IS NOT TRUE
       OR upper(BTRIM(COALESCE(v_classifier_result->>'resolved_mode', 'LEGACY'))) <> 'DELTA' THEN
      v_fallback_reason := COALESCE(v_classifier_result->>'fallback_reason', 'DELTA_CLASSIFIER_REQUIRES_NON_DELTA_MODE');

      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET status = CASE WHEN upper(BTRIM(COALESCE(v_classifier_result->>'resolved_mode', 'LEGACY'))) = 'BLOCKED' THEN 'BLOCKED' ELSE 'FALLBACK_REQUIRED' END,
          phase = 'INIT_PREFLIGHT',
          cursor_json = jsonb_build_object('phase', 'INIT_PREFLIGHT', 'cursor', '{}'::jsonb),
          fallback_required = upper(BTRIM(COALESCE(v_classifier_result->>'resolved_mode', 'LEGACY'))) NOT IN ('BLOCKED', 'PATCH_ONLY', 'CLONE_REBASE'),
          fallback_reason = v_fallback_reason,
          diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb) || jsonb_build_object('classifier_result', v_classifier_result),
          updated_at_utc = v_now,
          completed_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id;

      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'fallback_required', upper(BTRIM(COALESCE(v_classifier_result->>'resolved_mode', 'LEGACY'))) NOT IN ('BLOCKED', 'PATCH_ONLY', 'CLONE_REBASE'),
        'fallback_reason', v_fallback_reason,
        'more_due', false,
        'has_more', false,
        'made_progress', true,
        'delta_refresh_complete', false,
        'stop_reason', CASE WHEN upper(BTRIM(COALESCE(v_classifier_result->>'resolved_mode', 'LEGACY'))) = 'BLOCKED' THEN 'DELTA_BLOCKED' ELSE 'DELTA_FALLBACK_REQUIRED' END,
        'classifier_result', v_classifier_result
      );
    END IF;

    IF v_projection_mode <> 'DELTA' THEN
      v_fallback_reason := 'DELTA_CHUNK_UNSUPPORTED_PROJECTION_MODE';

      UPDATE public.banking_pay_workbench_preview_rows AS preview_row_update
      SET selected = false,
          selection_state = 'DIRTY',
          status = 'DIRTY',
          row_json = jsonb_strip_nulls(
            COALESCE(preview_row_update.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE preview_row_update.session_id = p_session_id
        AND preview_row_update.candidate_id = p_candidate_id
        AND COALESCE(preview_row_update.row_json->>'projection_run_id', '') = v_projection_run_id::text;

      UPDATE public.banking_pay_workbench_candidate_source_lines AS source_row_update
      SET status = 'SUPERSEDED',
          source_row_json = jsonb_strip_nulls(
            COALESCE(source_row_update.source_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE source_row_update.session_id = p_session_id
        AND source_row_update.candidate_id = p_candidate_id
      AND source_row_update.source_build_run_id = v_projection_run_id
      AND source_row_update.status IN ('CURRENT', 'DIRTY');

      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work_update
      SET status = 'SKIPPED',
          result_row_json = jsonb_strip_nulls(
            COALESCE(line_work_update.result_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE line_work_update.session_id = p_session_id
        AND line_work_update.candidate_id = p_candidate_id
        AND (
          COALESCE(line_work_update.work_payload_json->>'projection_run_id', '') = v_projection_run_id::text
          OR COALESCE(line_work_update.result_row_json->>'projection_run_id', '') = v_projection_run_id::text
        )
        AND UPPER(BTRIM(COALESCE(line_work_update.status, ''))) NOT IN ('ERROR', 'FAILED', 'SKIPPED');

      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET status = 'FALLBACK_REQUIRED',
          fallback_required = true,
          fallback_reason = v_fallback_reason,
          updated_at_utc = v_now,
          completed_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id;
      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'fallback_required', true,
        'fallback_reason', v_fallback_reason,
        'more_due', false,
        'has_more', false,
        'made_progress', true,
        'delta_refresh_complete', false,
        'stop_reason', 'DELTA_FALLBACK_REQUIRED'
      );
    END IF;

    v_phase := 'RESOLVE_SCOPE';
    v_projection_run_status := 'RUNNING';
    v_persisted_phase := v_phase;
    v_requested_phase := v_phase;
    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
    SET phase = v_phase,
        cursor_json = jsonb_build_object('phase', v_phase, 'cursor', '{}'::jsonb),
        updated_at_utc = v_now
    WHERE projection_run_update.id = v_projection_run_id;
  ELSE
    SELECT projection_run.projection_mode,
           projection_run.projection_class,
           UPPER(BTRIM(COALESCE(projection_run.status, 'RUNNING'))),
           UPPER(BTRIM(COALESCE(projection_run.phase, 'INIT_PREFLIGHT'))),
           projection_run.cursor_json,
           projection_run.write_phase,
           projection_run.write_cursor_json,
           projection_run.targeted_timesheet_ids,
           projection_run.linked_timesheet_ids,
           projection_run.session_version,
           projection_run.source_change_seq,
           projection_run.source_snapshot_run_id,
           COALESCE(projection_run.projected_row_count, 0),
           COALESCE(projection_run.written_source_count, 0),
           COALESCE(projection_run.written_line_work_count, 0),
           COALESCE(projection_run.written_preview_count, 0),
           COALESCE(projection_run.candidate_state_updated, false),
           COALESCE(projection_run.shadow_compare_required, false),
           COALESCE(projection_run.shadow_compare_status, 'NOT_REQUIRED'),
           COALESCE(projection_run.shadow_compare_enforced, false),
           COALESCE(projection_run.admission_seal_version,0),
           COALESCE(projection_run.admission_seal_json,'{}'::jsonb),
           projection_run.admission_seal_digest
    INTO v_projection_mode,
         v_projection_class,
         v_projection_run_status,
         v_persisted_phase,
         v_phase_cursor_json,
         v_write_phase,
         v_write_cursor_json,
         v_targeted_json,
         v_linked_json,
         v_session_version,
         v_source_change_seq,
         v_source_snapshot_run_id,
         v_projected_row_count,
         v_written_source_count,
         v_written_line_work_count,
         v_written_preview_count,
         v_candidate_state_updated,
         v_shadow_compare_required,
         v_shadow_compare_status,
         v_shadow_compare_enforced,
         v_admission_seal_version,
         v_admission_seal_json,
         v_admission_seal_digest
    FROM public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run
    WHERE projection_run.id = v_projection_run_id
      AND projection_run.session_id = p_session_id
      AND projection_run.candidate_id = p_candidate_id
      AND projection_run.status IN ('RUNNING', 'COMPLETED')
    FOR UPDATE;

    v_sealed_lifecycle_delta:=v_admission_seal_version=1
      AND v_projection_class='TIMESHEET_LIFECYCLE';

    IF NOT FOUND THEN
      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'fallback_required', true,
        'fallback_reason', 'DELTA_PROJECTION_RUN_NOT_RUNNING',
        'more_due', false,
        'has_more', false,
        'made_progress', true,
        'delta_refresh_complete', false,
        'stop_reason', 'DELTA_FALLBACK_REQUIRED'
      );
    END IF;

    IF v_projection_run_status = 'COMPLETED' THEN
      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'phase', COALESCE(NULLIF(v_persisted_phase, ''), 'FINALISE'),
        'write_phase', COALESCE(NULLIF(v_write_phase, ''), 'WRITE_COMPLETE'),
        'fallback_required', false,
        'more_due', false,
        'has_more', false,
        'made_progress', false,
        'delta_refresh_complete', true,
        'stop_reason', 'DELTA_PROJECTION_RUN_ALREADY_COMPLETED'
      );
    END IF;

    IF COALESCE(v_source_change_seq, 0) > 0
       AND COALESCE(v_live_source_change_seq, 0) > COALESCE(v_source_change_seq, 0) THEN
      UPDATE public.banking_pay_workbench_preview_rows AS preview_row_update
      SET selected = false,
          selection_state = 'DIRTY',
          status = 'DIRTY',
          row_json = jsonb_strip_nulls(
            COALESCE(preview_row_update.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'superseded_by_newer_source_change_seq', true,
              'source_change_seq', v_source_change_seq,
              'newer_source_change_seq', v_live_source_change_seq,
              'superseded_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE preview_row_update.session_id = p_session_id
        AND preview_row_update.candidate_id = p_candidate_id
        AND COALESCE(preview_row_update.row_json->>'projection_run_id', '') = v_projection_run_id::text;

      UPDATE public.banking_pay_workbench_candidate_source_lines AS source_row_update
      SET status = 'SUPERSEDED',
          source_row_json = jsonb_strip_nulls(
            COALESCE(source_row_update.source_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'superseded_by_newer_source_change_seq', true,
              'source_change_seq', v_source_change_seq,
              'newer_source_change_seq', v_live_source_change_seq,
              'superseded_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE source_row_update.session_id = p_session_id
        AND source_row_update.candidate_id = p_candidate_id
      AND source_row_update.source_build_run_id = v_projection_run_id
      AND source_row_update.status IN ('CURRENT', 'DIRTY');

      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work_update
      SET status = 'SKIPPED',
          result_row_json = jsonb_strip_nulls(
            COALESCE(line_work_update.result_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'superseded_by_newer_source_change_seq', true,
              'source_change_seq', v_source_change_seq,
              'newer_source_change_seq', v_live_source_change_seq,
              'superseded_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE line_work_update.session_id = p_session_id
        AND line_work_update.candidate_id = p_candidate_id
        AND (
          COALESCE(line_work_update.work_payload_json->>'projection_run_id', '') = v_projection_run_id::text
          OR COALESCE(line_work_update.result_row_json->>'projection_run_id', '') = v_projection_run_id::text
        )
        AND UPPER(BTRIM(COALESCE(line_work_update.status, ''))) NOT IN ('ERROR', 'FAILED', 'SKIPPED');

      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET status = 'FAILED',
          fallback_required = false,
          fallback_reason = 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ',
          diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
            || jsonb_build_object(
              'superseded_by_newer_source_change_seq', true,
              'source_change_seq', v_source_change_seq,
              'newer_source_change_seq', v_live_source_change_seq,
              'terminalised_by', 'pay_workbench_candidate_delta_refresh_chunk',
              'terminalised_at_utc', v_now::text
            ),
          updated_at_utc = v_now,
          completed_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id
        AND projection_run_update.session_id = p_session_id
        AND projection_run_update.candidate_id = p_candidate_id
        AND UPPER(BTRIM(COALESCE(projection_run_update.status, ''))) = 'RUNNING';

      GET DIAGNOSTICS v_superseded_projection_runs = ROW_COUNT;

      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'source_change_seq', v_source_change_seq,
        'newer_source_change_seq', v_live_source_change_seq,
        'phase', COALESCE(NULLIF(v_persisted_phase, ''), 'INIT_PREFLIGHT'),
        'write_phase', COALESCE(NULLIF(v_write_phase, ''), 'NOT_STARTED'),
        'fallback_required', false,
        'more_due', false,
        'has_more', false,
        'made_progress', true,
        'delta_refresh_complete', true,
        'superseded_by_newer_source_change_seq', true,
        'superseded_projection_runs', COALESCE(v_superseded_projection_runs, 0),
        'stop_reason', 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ'
      );
    END IF;

    IF v_cursor_phase IN ('WRITE_COMPATIBLE_OUTPUTS', 'VERIFY_PARITY_OR_SHADOW', 'UPDATE_CANDIDATE_STATE', 'FINALISE') THEN
      v_requested_phase := v_cursor_phase;
    END IF;

    v_requested_phase_order := CASE v_requested_phase
      WHEN 'INIT_PREFLIGHT' THEN 0
      WHEN 'RESOLVE_SCOPE' THEN 1
      WHEN 'PROJECT_ROWS' THEN 2
      WHEN 'WRITE_COMPATIBLE_OUTPUTS' THEN 3
      WHEN 'VERIFY_PARITY_OR_SHADOW' THEN 4
      WHEN 'UPDATE_CANDIDATE_STATE' THEN 5
      WHEN 'FINALISE' THEN 6
      ELSE 0
    END;
    v_persisted_phase_order := CASE v_persisted_phase
      WHEN 'INIT_PREFLIGHT' THEN 0
      WHEN 'RESOLVE_SCOPE' THEN 1
      WHEN 'PROJECT_ROWS' THEN 2
      WHEN 'WRITE_COMPATIBLE_OUTPUTS' THEN 3
      WHEN 'VERIFY_PARITY_OR_SHADOW' THEN 4
      WHEN 'UPDATE_CANDIDATE_STATE' THEN 5
      WHEN 'FINALISE' THEN 6
      ELSE 0
    END;
    IF NULLIF(UPPER(BTRIM(COALESCE(v_write_phase, ''))), '') IS NOT NULL
       AND UPPER(BTRIM(COALESCE(v_write_phase, ''))) <> 'NOT_STARTED' THEN
      v_persisted_phase_order := GREATEST(v_persisted_phase_order, 3);
      IF UPPER(BTRIM(COALESCE(v_write_phase, ''))) = 'WRITE_COMPLETE' THEN
        v_persisted_phase_order := GREATEST(v_persisted_phase_order, 4);
      END IF;
    END IF;

    v_effective_phase_order := GREATEST(v_requested_phase_order, v_persisted_phase_order);
    v_phase := CASE v_effective_phase_order
      WHEN 0 THEN 'INIT_PREFLIGHT'
      WHEN 1 THEN 'RESOLVE_SCOPE'
      WHEN 2 THEN 'PROJECT_ROWS'
      WHEN 3 THEN 'WRITE_COMPATIBLE_OUTPUTS'
      WHEN 4 THEN 'VERIFY_PARITY_OR_SHADOW'
      WHEN 5 THEN 'UPDATE_CANDIDATE_STATE'
      ELSE 'FINALISE'
    END;

    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
    SET diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
          || jsonb_build_object(
            'phase_resolver_requested_phase', v_requested_phase,
            'phase_resolver_persisted_phase', v_persisted_phase,
            'phase_resolver_effective_phase', v_phase,
            'phase_resolver_write_phase', COALESCE(v_write_phase, 'NOT_STARTED')
          ),
        updated_at_utc = v_now
    WHERE projection_run_update.id = v_projection_run_id;
  END IF;

  v_classifier_delta_shadow_mode := lower(BTRIM(COALESCE(
    NULLIF(v_classifier_result#>>'{complexity_flags,delta_shadow_mode}', ''),
    NULLIF(v_stored_classifier_result#>>'{complexity_flags,delta_shadow_mode}', ''),
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_classifier_payload_shadow_mode := lower(BTRIM(COALESCE(
    NULLIF(v_classifier_result#>>'{complexity_flags,payload_shadow_mode}', ''),
    NULLIF(v_stored_classifier_result#>>'{complexity_flags,payload_shadow_mode}', ''),
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_classifier_shadow_compare_required := lower(BTRIM(COALESCE(
    NULLIF(v_classifier_result->>'shadow_compare_required', ''),
    NULLIF(v_stored_classifier_result->>'shadow_compare_required', ''),
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_classifier_shadow_compare_enforced := lower(BTRIM(COALESCE(
    NULLIF(v_classifier_result->>'shadow_compare_enforced', ''),
    NULLIF(v_stored_classifier_result->>'shadow_compare_enforced', ''),
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_shadow_compare_required := COALESCE(v_shadow_compare_required, false)
    OR COALESCE(v_classifier_delta_shadow_mode, false)
    OR COALESCE(v_classifier_payload_shadow_mode, false)
    OR COALESCE(v_classifier_shadow_compare_required, false);
  v_shadow_compare_enforced := COALESCE(v_shadow_compare_required, false)
    AND (COALESCE(v_shadow_compare_enforced, false) OR COALESCE(v_classifier_shadow_compare_enforced, false));

  IF v_projection_mode = 'DELTA'
     AND v_projection_class = 'NORMAL_TIMESHEET'
     AND COALESCE(v_settings_delta_shadow_mode, false) IS NOT TRUE
     AND COALESCE(v_classifier_delta_shadow_mode, false) IS NOT TRUE
     AND COALESCE(v_classifier_payload_shadow_mode, false) IS NOT TRUE
     AND COALESCE(v_classifier_shadow_compare_required, false) IS NOT TRUE
     AND COALESCE(v_payload_shadow_mode, false) IS NOT TRUE
     AND COALESCE(v_payload_shadow_compare_required, false) IS NOT TRUE THEN
    v_shadow_compare_required := false;
    v_shadow_compare_enforced := false;
    v_shadow_compare_status := 'NOT_REQUIRED';
    v_shadow_flags_reconciled_to_not_required := true;

    IF v_projection_run_id IS NOT NULL THEN
      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET shadow_compare_required = false,
          shadow_compare_enforced = false,
          shadow_compare_status = 'NOT_REQUIRED',
          legacy_compare_status = 'NOT_REQUIRED',
          legacy_compare_json = jsonb_build_object(
            'compare_status', 'NOT_REQUIRED',
            'shadow_compare_not_required', true,
            'shadow_flags_reconciled_to_current_settings', true
          ),
          diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
            || jsonb_build_object(
              'shadow_flags_reconciled_to_not_required', true,
              'settings_delta_shadow_mode', COALESCE(v_settings_delta_shadow_mode, false),
              'classifier_delta_shadow_mode', COALESCE(v_classifier_delta_shadow_mode, false),
              'classifier_payload_shadow_mode', COALESCE(v_classifier_payload_shadow_mode, false),
              'payload_shadow_mode', COALESCE(v_payload_shadow_mode, false)
            ),
          updated_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id;
    END IF;
  ELSIF v_shadow_compare_enforced IS TRUE AND v_shadow_compare_required IS NOT TRUE THEN
    v_shadow_compare_required := true;
  END IF;

  IF jsonb_typeof(v_targeted_json) = 'array' THEN
    SELECT COALESCE(array_agg(DISTINCT parsed_targeted.timesheet_id_value ORDER BY parsed_targeted.timesheet_id_value), ARRAY[]::uuid[]),
           COALESCE(count(*) FILTER (WHERE parsed_targeted.raw_value IS NOT NULL AND parsed_targeted.timesheet_id_value IS NULL), 0)::integer
    INTO v_targeted_timesheet_ids,
         v_invalid_targeted_uuid_count
    FROM (
      SELECT targeted_element.value #>> '{}' AS raw_value,
             CASE
               WHEN BTRIM(targeted_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                 THEN BTRIM(targeted_element.value #>> '{}')::uuid
               ELSE NULL::uuid
             END AS timesheet_id_value
      FROM jsonb_array_elements(v_targeted_json) AS targeted_element(value)
    ) AS parsed_targeted
    WHERE parsed_targeted.raw_value IS NOT NULL;
  END IF;

  IF jsonb_typeof(v_linked_json) = 'array' THEN
    SELECT COALESCE(array_agg(DISTINCT parsed_linked.timesheet_id_value ORDER BY parsed_linked.timesheet_id_value), ARRAY[]::uuid[]),
           COALESCE(count(*) FILTER (WHERE parsed_linked.raw_value IS NOT NULL AND parsed_linked.timesheet_id_value IS NULL), 0)::integer
    INTO v_linked_timesheet_ids,
         v_invalid_linked_uuid_count
    FROM (
      SELECT linked_element.value #>> '{}' AS raw_value,
             CASE
               WHEN BTRIM(linked_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                 THEN BTRIM(linked_element.value #>> '{}')::uuid
               ELSE NULL::uuid
             END AS timesheet_id_value
      FROM jsonb_array_elements(v_linked_json) AS linked_element(value)
    ) AS parsed_linked
    WHERE parsed_linked.raw_value IS NOT NULL;
  END IF;

  IF v_invalid_targeted_uuid_count > 0 OR v_invalid_linked_uuid_count > 0 THEN
    v_fallback_reason := 'INVALID_UUID_IN_DELTA_CURSOR_OR_PAYLOAD';
    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
    SET status = 'FALLBACK_REQUIRED',
        fallback_required = true,
        fallback_reason = v_fallback_reason,
        diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
          || jsonb_build_object('invalid_targeted_uuid_count', v_invalid_targeted_uuid_count, 'invalid_linked_uuid_count', v_invalid_linked_uuid_count),
        updated_at_utc = v_now,
        completed_at_utc = v_now
    WHERE projection_run_update.id = v_projection_run_id;
    RETURN jsonb_build_object(
      'ok', true,
      'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'projection_run_id', v_projection_run_id::text,
      'fallback_required', true,
      'fallback_reason', v_fallback_reason,
      'more_due', false,
      'has_more', false,
      'made_progress', true,
      'delta_refresh_complete', false,
      'stop_reason', 'DELTA_FALLBACK_REQUIRED'
    );
  END IF;

  IF v_phase = 'RESOLVE_SCOPE' THEN
    IF COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0 THEN
      SELECT COALESCE(array_agg(DISTINCT rotation_scope.family_timesheet_id ORDER BY rotation_scope.family_timesheet_id), ARRAY[]::uuid[])
      INTO v_resolved_family_timesheet_ids
      FROM public._pay_timesheet_rotation_scope(v_targeted_timesheet_ids) AS rotation_scope
      WHERE rotation_scope.family_timesheet_id IS NOT NULL;

      SELECT COALESCE(array_agg(DISTINCT linked_scope.timesheet_id_value ORDER BY linked_scope.timesheet_id_value), ARRAY[]::uuid[])
      INTO v_linked_timesheet_ids
      FROM (
        SELECT unnest(COALESCE(v_linked_timesheet_ids, ARRAY[]::uuid[])) AS timesheet_id_value
        UNION ALL
        SELECT unnest(COALESCE(v_resolved_family_timesheet_ids, ARRAY[]::uuid[])) AS timesheet_id_value
      ) AS linked_scope
      WHERE linked_scope.timesheet_id_value IS NOT NULL
        AND NOT (linked_scope.timesheet_id_value = ANY(COALESCE(v_targeted_timesheet_ids, ARRAY[]::uuid[])));
    END IF;

    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
    SET phase = 'PROJECT_ROWS',
        cursor_json = jsonb_build_object('phase', 'PROJECT_ROWS', 'cursor', '{}'::jsonb),
        targeted_timesheet_ids = COALESCE(to_jsonb(v_targeted_timesheet_ids), '[]'::jsonb),
        linked_timesheet_ids = COALESCE(to_jsonb(v_linked_timesheet_ids), '[]'::jsonb),
        diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
          || jsonb_build_object(
            'resolved_targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
            'resolved_linked_timesheet_count', COALESCE(array_length(v_linked_timesheet_ids, 1), 0),
            'resolve_scope_completed_at_utc', v_now::text
          ),
        updated_at_utc = v_now
    WHERE projection_run_update.id = v_projection_run_id;

    v_phase := 'PROJECT_ROWS';
    v_elapsed_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::integer;
    IF v_elapsed_ms >= v_budget_cutoff_ms THEN
      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'phase', 'RESOLVE_SCOPE',
        'next_phase', 'PROJECT_ROWS',
        'more_due', true,
        'has_more', true,
        'made_progress', true,
        'fallback_required', false,
        'delta_refresh_complete', false,
        'stop_reason', 'DELTA_PHASE_BUDGET_EXHAUSTED',
        'elapsed_ms', v_elapsed_ms,
        'next_cursor_json', jsonb_build_object('projection_run_id', v_projection_run_id::text, 'phase', 'PROJECT_ROWS', 'cursor', '{}'::jsonb)
      );
    END IF;
  END IF;

  IF to_regprocedure('public.pay_workbench_project_changed_timesheets_v1(uuid,uuid,uuid,uuid[],uuid[],jsonb)') IS NULL THEN
    v_dependency_missing_reason := 'PAY_WORKBENCH_PROJECT_CHANGED_TIMESHEETS_V1_MISSING';
  ELSIF to_regprocedure('public.pay_workbench_delta_write_compatible_rows_v1(uuid,uuid,uuid,jsonb)') IS NULL THEN
    v_dependency_missing_reason := 'PAY_WORKBENCH_DELTA_WRITE_COMPATIBLE_ROWS_V1_MISSING';
  ELSIF to_regprocedure('public.pay_workbench_delta_update_candidate_state_v1(uuid,uuid,uuid,jsonb)') IS NULL THEN
    v_dependency_missing_reason := 'PAY_WORKBENCH_DELTA_UPDATE_CANDIDATE_STATE_V1_MISSING';
  END IF;

  IF v_dependency_missing_reason IS NOT NULL THEN
    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
    SET status = 'FALLBACK_REQUIRED',
        fallback_required = true,
        fallback_reason = v_dependency_missing_reason,
        diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
          || jsonb_build_object('dependency_missing_reason', v_dependency_missing_reason),
        updated_at_utc = v_now,
        completed_at_utc = v_now
    WHERE projection_run_update.id = v_projection_run_id;
    RETURN jsonb_build_object(
      'ok', true,
      'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'projection_run_id', v_projection_run_id::text,
      'fallback_required', true,
      'fallback_reason', v_dependency_missing_reason,
      'more_due', false,
      'has_more', false,
      'made_progress', true,
      'delta_refresh_complete', false,
      'stop_reason', 'DELTA_FALLBACK_REQUIRED'
    );
  END IF;

  IF v_phase IN ('PROJECT_ROWS', 'WRITE_COMPATIBLE_OUTPUTS') THEN
    CREATE TEMP TABLE IF NOT EXISTS _bpay_delta_projection_rows (
      projection_run_id uuid NOT NULL,
      session_id uuid NOT NULL,
      candidate_id uuid NOT NULL,
      session_version bigint NOT NULL,
      source_change_seq bigint,
      timesheet_id uuid,
      canonical_timesheet_id uuid,
      section text NOT NULL,
      line_key text NOT NULL,
      row_key text NOT NULL,
      parent_line_key text,
      split_suffix text,
      source_ordinal bigint NOT NULL,
      row_ordinal bigint NOT NULL,
      pay_channel_scope text,
      refresh_scope_kind text NOT NULL,
      key_type text,
      key_value text,
      amount_ex_vat numeric,
      amount_inc_vat numeric,
      vat_amount numeric,
      draftable boolean NOT NULL DEFAULT false,
      is_ready_for_draft boolean NOT NULL DEFAULT false,
      selection_allowed boolean NOT NULL DEFAULT false,
      readiness_state text,
      blocked_reason_codes jsonb NOT NULL DEFAULT '[]'::jsonb,
      outstanding_state_json jsonb NOT NULL DEFAULT '{}'::jsonb,
      source_row_json jsonb NOT NULL,
      economic_key_json jsonb NOT NULL,
      contract_json jsonb NOT NULL,
      work_payload_json jsonb NOT NULL,
      result_row_json jsonb NOT NULL,
      preview_row_json jsonb NOT NULL,
      contract_ok boolean NOT NULL DEFAULT false,
      materialisable boolean NOT NULL DEFAULT false
    ) ON COMMIT DROP;

    TRUNCATE TABLE _bpay_delta_projection_rows;

    v_current_projection_cursor_json := CASE
      WHEN v_phase = 'WRITE_COMPATIBLE_OUTPUTS' THEN '{}'::jsonb
      WHEN jsonb_typeof(v_phase_cursor_json->'cursor') = 'object' THEN COALESCE(v_phase_cursor_json->'cursor', '{}'::jsonb)
      ELSE COALESCE(v_phase_cursor_json, '{}'::jsonb)
    END;
    v_write_resume_recreate_limit := CASE
      WHEN v_phase = 'WRITE_COMPATIBLE_OUTPUTS'
        THEN LEAST(GREATEST(COALESCE(v_projected_row_count, 0), COALESCE(v_limit, 25), 25), 1000)
      ELSE v_limit
    END;

    v_project_result := public.pay_workbench_project_changed_timesheets_v1(
      p_session_id,
      p_candidate_id,
      v_projection_run_id,
      v_targeted_timesheet_ids,
      v_linked_timesheet_ids,
      v_payload_json
        || jsonb_build_object(
          'projection_run_id', v_projection_run_id::text,
          'projection_mode', v_projection_mode,
          'projection_class', v_projection_class,
          'session_version', COALESCE(v_session_version, v_session_row.version),
          'source_change_seq', COALESCE(v_source_change_seq, 0),
          'source_snapshot_run_id', CASE WHEN v_source_snapshot_run_id IS NULL THEN NULL ELSE v_source_snapshot_run_id::text END,
          'limit', v_write_resume_recreate_limit,
          'cursor', v_current_projection_cursor_json,
          'shadow_compare_required', v_shadow_compare_required,
          'shadow_compare_enforced', v_shadow_compare_enforced
        )
    );

    IF COALESCE((v_project_result->>'fallback_required')::boolean, false) IS TRUE THEN
      v_fallback_reason := COALESCE(v_project_result->>'fallback_reason', 'DELTA_PROJECT_ROWS_FALLBACK_REQUIRED');

      UPDATE public.banking_pay_workbench_preview_rows AS preview_row_update
      SET selected = false,
          selection_state = 'DIRTY',
          status = 'DIRTY',
          row_json = jsonb_strip_nulls(
            COALESCE(preview_row_update.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE preview_row_update.session_id = p_session_id
        AND preview_row_update.candidate_id = p_candidate_id
        AND COALESCE(preview_row_update.row_json->>'projection_run_id', '') = v_projection_run_id::text;

      UPDATE public.banking_pay_workbench_candidate_source_lines AS source_row_update
      SET status = 'SUPERSEDED',
          source_row_json = jsonb_strip_nulls(
            COALESCE(source_row_update.source_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE source_row_update.session_id = p_session_id
        AND source_row_update.candidate_id = p_candidate_id
      AND source_row_update.source_build_run_id = v_projection_run_id
      AND source_row_update.status IN ('CURRENT', 'DIRTY');

      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work_update
      SET status = 'SKIPPED',
          result_row_json = jsonb_strip_nulls(
            COALESCE(line_work_update.result_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE line_work_update.session_id = p_session_id
        AND line_work_update.candidate_id = p_candidate_id
        AND (
          COALESCE(line_work_update.work_payload_json->>'projection_run_id', '') = v_projection_run_id::text
          OR COALESCE(line_work_update.result_row_json->>'projection_run_id', '') = v_projection_run_id::text
        )
        AND UPPER(BTRIM(COALESCE(line_work_update.status, ''))) NOT IN ('ERROR', 'FAILED', 'SKIPPED');

      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET status = 'FALLBACK_REQUIRED',
          phase = 'PROJECT_ROWS',
          fallback_required = true,
          fallback_reason = v_fallback_reason,
          diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
            || jsonb_build_object('project_result', v_project_result),
          updated_at_utc = v_now,
          completed_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id;
      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'fallback_required', true,
        'fallback_reason', v_fallback_reason,
        'more_due', false,
        'has_more', false,
        'made_progress', true,
        'delta_refresh_complete', false,
        'stop_reason', 'DELTA_FALLBACK_REQUIRED',
        'project_result', jsonb_build_object('fallback_reason', v_fallback_reason)
      );
    END IF;

    IF v_phase = 'PROJECT_ROWS' THEN
      v_projected_row_count := COALESCE(v_projected_row_count, 0) + COALESCE((v_project_result->>'projected_row_count')::integer, 0);
    ELSE
      v_projected_row_count := GREATEST(
        COALESCE(v_projected_row_count, 0),
        COALESCE((v_project_result->>'projected_row_count')::integer, 0)
      );
    END IF;
    v_projection_more_due := COALESCE((v_project_result->>'more_due')::boolean, false);
    v_projection_cursor_json := CASE
      WHEN jsonb_typeof(v_project_result->'next_cursor_json') = 'object' THEN v_project_result->'next_cursor_json'
      ELSE '{}'::jsonb
    END;

    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
    SET phase = CASE
          WHEN v_phase = 'WRITE_COMPATIBLE_OUTPUTS' THEN 'WRITE_COMPATIBLE_OUTPUTS'
          WHEN v_projection_more_due THEN 'PROJECT_ROWS'
          ELSE 'WRITE_COMPATIBLE_OUTPUTS'
        END,
        cursor_json = jsonb_build_object(
          'phase', CASE
            WHEN v_phase = 'WRITE_COMPATIBLE_OUTPUTS' THEN 'WRITE_COMPATIBLE_OUTPUTS'
            WHEN v_projection_more_due THEN 'PROJECT_ROWS'
            ELSE 'WRITE_COMPATIBLE_OUTPUTS'
          END,
          'cursor', CASE
            WHEN v_phase = 'WRITE_COMPATIBLE_OUTPUTS' THEN '{}'::jsonb
            ELSE COALESCE(CASE WHEN v_projection_more_due THEN v_projection_cursor_json ELSE v_current_projection_cursor_json END, '{}'::jsonb)
          END
        ),
        projected_row_count = v_projected_row_count,
        projection_fingerprint = md5(jsonb_build_object(
          'projection_run_id', v_projection_run_id::text,
          'candidate_id', p_candidate_id::text,
          'targeted_timesheet_ids', COALESCE(to_jsonb(v_targeted_timesheet_ids), '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(to_jsonb(v_linked_timesheet_ids), '[]'::jsonb),
          'session_version', COALESCE(v_session_version, v_session_row.version),
          'source_change_seq', COALESCE(v_source_change_seq, 0),
          'projected_row_count', v_projected_row_count
        )::text),
        diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
          || jsonb_build_object(
            'last_projection_row_count', COALESCE((v_project_result->>'projected_row_count')::integer, 0),
            'projection_more_due', v_projection_more_due,
            'write_resume_recreate', v_phase = 'WRITE_COMPATIBLE_OUTPUTS',
            'write_resume_recreate_limit', v_write_resume_recreate_limit,
            'row_key_line_key_parity_proven', LOWER(BTRIM(COALESCE(v_project_result->>'row_key_line_key_parity_proven', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
            'economic_key_parity_proven', LOWER(BTRIM(COALESCE(v_project_result->>'economic_key_parity_proven', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          ),
        updated_at_utc = v_now
    WHERE projection_run_update.id = v_projection_run_id;

    IF v_phase = 'WRITE_COMPATIBLE_OUTPUTS' AND v_projection_more_due THEN
      v_fallback_reason := 'DELTA_WRITE_RECREATE_EXCEEDED_SINGLE_CHUNK';
      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET status = 'FALLBACK_REQUIRED',
          fallback_required = true,
          fallback_reason = v_fallback_reason,
          diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
            || jsonb_build_object(
              'write_resume_recreate_more_due', true,
              'write_resume_recreate_limit', v_write_resume_recreate_limit,
              'project_result', v_project_result
            ),
          updated_at_utc = v_now,
          completed_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id;
      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'fallback_required', true,
        'fallback_reason', v_fallback_reason,
        'more_due', false,
        'has_more', false,
        'made_progress', true,
        'delta_refresh_complete', false,
        'stop_reason', 'DELTA_FALLBACK_REQUIRED'
      );
    END IF;

    v_elapsed_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::integer;
    IF v_elapsed_ms >= v_budget_cutoff_ms AND v_phase = 'PROJECT_ROWS' THEN
      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'phase', 'PROJECT_ROWS',
        'next_phase', CASE WHEN v_projection_more_due THEN 'PROJECT_ROWS' ELSE 'WRITE_COMPATIBLE_OUTPUTS' END,
        'more_due', true,
        'has_more', true,
        'made_progress', true,
        'fallback_required', false,
        'delta_refresh_complete', false,
        'stop_reason', 'DELTA_PHASE_BUDGET_EXHAUSTED',
        'elapsed_ms', v_elapsed_ms,
        'next_cursor_json', jsonb_build_object(
          'projection_run_id', v_projection_run_id::text,
          'phase', CASE WHEN v_projection_more_due THEN 'PROJECT_ROWS' ELSE 'WRITE_COMPATIBLE_OUTPUTS' END,
          'cursor', COALESCE(CASE WHEN v_projection_more_due THEN v_projection_cursor_json ELSE v_current_projection_cursor_json END, '{}'::jsonb),
          'write_phase', COALESCE(v_write_result->>'write_phase', v_write_phase, 'SUPERSEDE_PREVIEW_ROWS'),
          'write_cursor_json', CASE
            WHEN jsonb_typeof(v_write_result->'write_cursor_json') = 'object' THEN v_write_result->'write_cursor_json'
            ELSE COALESCE(v_write_cursor_json, '{}'::jsonb)
          END
        )
      );
    ELSIF v_elapsed_ms >= v_budget_cutoff_ms AND v_phase = 'WRITE_COMPATIBLE_OUTPUTS' THEN
      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
            || jsonb_build_object(
              'write_resume_project_budget_cutoff_reached', true,
              'write_resume_project_elapsed_ms', v_elapsed_ms,
              'write_resume_project_budget_cutoff_ms', v_budget_cutoff_ms,
              'write_resume_project_continued_to_write', true
            ),
          updated_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id;
    END IF;

    SELECT COALESCE(projection_run.diagnostics_json->'pre_delta_candidate_counts', '{}'::jsonb)
    INTO v_pre_candidate_counts_json
    FROM public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run
    WHERE projection_run.id = v_projection_run_id
      AND projection_run.session_id = p_session_id
      AND projection_run.candidate_id = p_candidate_id
    FOR UPDATE;

    IF COALESCE(v_pre_candidate_counts_json, '{}'::jsonb) = '{}'::jsonb THEN
      WITH pre_line_counts AS (
        SELECT COUNT(*)::integer AS line_units_total,
               COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(line_work.status, ''))) IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SKIPPED'))::integer AS line_units_ready,
               COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(line_work.status, ''))) IN ('PENDING', 'PROCESSING', 'DIRTY'))::integer AS line_units_pending,
               COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(line_work.status, ''))) IN ('ERROR', 'FAILED'))::integer AS line_units_failed
        FROM public.banking_pay_workbench_candidate_line_work AS line_work
        WHERE line_work.session_id = p_session_id
          AND line_work.candidate_id = p_candidate_id
      ), pre_preview_counts AS (
        SELECT COUNT(*) FILTER (WHERE preview_row.status = 'READY')::integer AS preview_row_count,
               COUNT(*) FILTER (WHERE preview_row.status = 'READY' AND preview_row.selected IS TRUE AND preview_row.selection_state = 'SELECTED')::integer AS selected_row_count
        FROM public.banking_pay_workbench_preview_rows AS preview_row
        WHERE preview_row.session_id = p_session_id
          AND preview_row.candidate_id = p_candidate_id
          AND preview_row.session_version = COALESCE(v_session_version, v_session_row.version)
      ), pre_section_counts AS (
        SELECT COALESCE(jsonb_object_agg(section_group.section, section_group.row_count ORDER BY section_group.section), '{}'::jsonb) AS section_counts_json
        FROM (
          SELECT preview_section.section, COUNT(*)::integer AS row_count
          FROM public.banking_pay_workbench_preview_rows AS preview_section
          WHERE preview_section.session_id = p_session_id
            AND preview_section.candidate_id = p_candidate_id
            AND preview_section.session_version = COALESCE(v_session_version, v_session_row.version)
            AND preview_section.status = 'READY'
          GROUP BY preview_section.section
        ) AS section_group
      )
      SELECT jsonb_build_object(
               'line_units_total', pre_line_counts.line_units_total,
               'line_units_ready', pre_line_counts.line_units_ready,
               'line_units_pending', pre_line_counts.line_units_pending,
               'line_units_failed', pre_line_counts.line_units_failed,
               'preview_row_count', pre_preview_counts.preview_row_count,
               'selected_row_count', pre_preview_counts.selected_row_count,
               'section_counts_json', pre_section_counts.section_counts_json
             )
      INTO v_pre_candidate_counts_json
      FROM pre_line_counts, pre_preview_counts, pre_section_counts;

      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
            || jsonb_build_object('pre_delta_candidate_counts', COALESCE(v_pre_candidate_counts_json, '{}'::jsonb)),
          updated_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id
        AND projection_run_update.session_id = p_session_id
        AND projection_run_update.candidate_id = p_candidate_id;
    END IF;

    v_write_result := public.pay_workbench_delta_write_compatible_rows_v1(
      p_session_id,
      p_candidate_id,
      v_projection_run_id,
      v_payload_json
        || jsonb_build_object(
          'projection_run_id', v_projection_run_id::text,
          'projection_class', v_projection_class,
          'reset_write_phase', (
            v_phase = 'PROJECT_ROWS'
            OR (
              v_phase = 'WRITE_COMPATIBLE_OUTPUTS'
              AND COALESCE(v_write_phase, 'SUPERSEDE_PREVIEW_ROWS') = 'SUPERSEDE_PREVIEW_ROWS'
              AND COALESCE(v_written_source_count, 0) = 0
              AND COALESCE(v_written_line_work_count, 0) = 0
              AND COALESCE(v_written_preview_count, 0) = 0
            )
          ),
          'shadow_compare_required', v_shadow_compare_required,
          'shadow_compare_enforced', v_shadow_compare_enforced
        )
    );

    IF COALESCE((v_write_result->>'fallback_required')::boolean, false) IS TRUE THEN
      v_fallback_reason := COALESCE(v_write_result->>'fallback_reason', 'DELTA_WRITE_COMPATIBLE_ROWS_FALLBACK_REQUIRED');

      UPDATE public.banking_pay_workbench_preview_rows AS preview_row_update
      SET selected = false,
          selection_state = 'DIRTY',
          status = 'DIRTY',
          row_json = jsonb_strip_nulls(
            COALESCE(preview_row_update.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE preview_row_update.session_id = p_session_id
        AND preview_row_update.candidate_id = p_candidate_id
        AND COALESCE(preview_row_update.row_json->>'projection_run_id', '') = v_projection_run_id::text;

      UPDATE public.banking_pay_workbench_candidate_source_lines AS source_row_update
      SET status = 'SUPERSEDED',
          source_row_json = jsonb_strip_nulls(
            COALESCE(source_row_update.source_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE source_row_update.session_id = p_session_id
        AND source_row_update.candidate_id = p_candidate_id
      AND source_row_update.source_build_run_id = v_projection_run_id
      AND source_row_update.status IN ('CURRENT', 'DIRTY');

      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work_update
      SET status = 'SKIPPED',
          result_row_json = jsonb_strip_nulls(
            COALESCE(line_work_update.result_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE line_work_update.session_id = p_session_id
        AND line_work_update.candidate_id = p_candidate_id
        AND (
          COALESCE(line_work_update.work_payload_json->>'projection_run_id', '') = v_projection_run_id::text
          OR COALESCE(line_work_update.result_row_json->>'projection_run_id', '') = v_projection_run_id::text
        )
        AND UPPER(BTRIM(COALESCE(line_work_update.status, ''))) NOT IN ('ERROR', 'FAILED', 'SKIPPED');

      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET status = 'FALLBACK_REQUIRED',
          phase = 'WRITE_COMPATIBLE_OUTPUTS',
          fallback_required = true,
          fallback_reason = v_fallback_reason,
          diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
            || jsonb_build_object('write_result', v_write_result),
          updated_at_utc = v_now,
          completed_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id;
      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'fallback_required', true,
        'fallback_reason', v_fallback_reason,
        'more_due', false,
        'has_more', false,
        'made_progress', true,
        'delta_refresh_complete', false,
        'stop_reason', 'DELTA_FALLBACK_REQUIRED'
      );
    END IF;

    IF COALESCE((v_write_result->>'more_due')::boolean, false) IS TRUE THEN
      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET phase = 'WRITE_COMPATIBLE_OUTPUTS',
          cursor_json = jsonb_build_object('phase', 'WRITE_COMPATIBLE_OUTPUTS', 'cursor', COALESCE(v_current_projection_cursor_json, '{}'::jsonb)),
          write_phase = COALESCE(v_write_result->>'write_phase', projection_run_update.write_phase, 'SUPERSEDE_PREVIEW_ROWS'),
          write_cursor_json = CASE WHEN jsonb_typeof(v_write_result->'write_cursor_json') = 'object' THEN v_write_result->'write_cursor_json' ELSE COALESCE(projection_run_update.write_cursor_json, '{}'::jsonb) END,
          updated_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id;

      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'phase', 'WRITE_COMPATIBLE_OUTPUTS',
        'next_phase', 'WRITE_COMPATIBLE_OUTPUTS',
        'more_due', true,
        'has_more', true,
        'made_progress', true,
        'fallback_required', false,
        'delta_refresh_complete', false,
        'stop_reason', COALESCE(v_write_result->>'stop_reason', 'DELTA_WRITE_PHASE_BUDGET_EXHAUSTED'),
        'elapsed_ms', FLOOR(EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::integer,
        'source_rows_written', COALESCE((v_write_result->>'source_rows_written')::integer, 0),
        'line_rows_written', COALESCE((v_write_result->>'line_rows_written')::integer, 0),
        'preview_rows_written', COALESCE((v_write_result->>'preview_rows_written')::integer, 0),
        'next_cursor_json', jsonb_build_object(
          'projection_run_id', v_projection_run_id::text,
          'phase', 'WRITE_COMPATIBLE_OUTPUTS',
          'cursor', COALESCE(v_current_projection_cursor_json, '{}'::jsonb),
          'write_phase', COALESCE(v_write_result->>'write_phase', v_write_phase, 'SUPERSEDE_PREVIEW_ROWS'),
          'write_cursor_json', CASE
            WHEN jsonb_typeof(v_write_result->'write_cursor_json') = 'object' THEN v_write_result->'write_cursor_json'
            ELSE COALESCE(v_write_cursor_json, '{}'::jsonb)
          END
        )
      );
    END IF;

    v_source_rows_written := COALESCE((v_write_result->>'source_rows_written')::integer, 0);
    v_line_rows_written := COALESCE((v_write_result->>'line_rows_written')::integer, 0);
    v_preview_rows_written := COALESCE((v_write_result->>'preview_rows_written')::integer, 0);
    v_rows_superseded := COALESCE((v_write_result->>'rows_superseded')::integer, 0);
    v_selected_preserved_count := COALESCE((v_write_result->>'selected_preserved_count')::integer, 0);
    v_selected_cleared_count := COALESCE((v_write_result->>'selected_cleared_count')::integer, 0);
    v_written_source_count := COALESCE(v_written_source_count, 0) + v_source_rows_written;
    v_written_line_work_count := COALESCE(v_written_line_work_count, 0) + v_line_rows_written;
    v_written_preview_count := COALESCE(v_written_preview_count, 0) + v_preview_rows_written;

    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
    SET phase = CASE WHEN v_projection_more_due THEN 'PROJECT_ROWS' ELSE 'VERIFY_PARITY_OR_SHADOW' END,
        cursor_json = jsonb_build_object(
          'phase', CASE WHEN v_projection_more_due THEN 'PROJECT_ROWS' ELSE 'VERIFY_PARITY_OR_SHADOW' END,
          'cursor', COALESCE(v_projection_cursor_json, '{}'::jsonb)
        ),
        write_phase = 'WRITE_COMPLETE',
        write_cursor_json = jsonb_build_object('phase', 'WRITE_COMPLETE'),
        written_source_count = GREATEST(COALESCE(projection_run_update.written_source_count, 0), v_written_source_count),
        written_line_work_count = GREATEST(COALESCE(projection_run_update.written_line_work_count, 0), v_written_line_work_count),
        written_preview_count = GREATEST(COALESCE(projection_run_update.written_preview_count, 0), v_written_preview_count),
        diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
          || jsonb_build_object(
            'last_write_source_rows', v_source_rows_written,
            'last_write_line_rows', v_line_rows_written,
            'last_write_preview_rows', v_preview_rows_written,
            'last_rows_superseded', v_rows_superseded
          ),
        updated_at_utc = v_now
    WHERE projection_run_update.id = v_projection_run_id;

    v_elapsed_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::integer;
    IF v_projection_more_due THEN
      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'phase', 'WRITE_COMPATIBLE_OUTPUTS',
        'next_phase', 'PROJECT_ROWS',
        'more_due', true,
        'has_more', true,
        'made_progress', true,
        'fallback_required', false,
        'delta_refresh_complete', false,
        'stop_reason', 'DELTA_ROWS_REMAINING',
        'elapsed_ms', v_elapsed_ms,
        'source_rows_written', v_source_rows_written,
        'line_rows_written', v_line_rows_written,
        'preview_rows_written', v_preview_rows_written,
        'next_cursor_json', jsonb_build_object('projection_run_id', v_projection_run_id::text, 'phase', 'PROJECT_ROWS', 'cursor', COALESCE(v_projection_cursor_json, '{}'::jsonb))
      );
    END IF;

    IF v_elapsed_ms >= v_budget_cutoff_ms THEN
      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
            || jsonb_build_object(
              'budget_checkpoint_phase', 'WRITE_COMPATIBLE_OUTPUTS',
              'budget_checkpoint_elapsed_ms', v_elapsed_ms,
              'budget_checkpoint_at_utc', v_now::text
            ),
          phase = 'VERIFY_PARITY_OR_SHADOW',
          cursor_json = jsonb_build_object('phase', 'VERIFY_PARITY_OR_SHADOW', 'cursor', '{}'::jsonb),
          updated_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id;

      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'phase', 'WRITE_COMPATIBLE_OUTPUTS',
        'next_phase', 'VERIFY_PARITY_OR_SHADOW',
        'more_due', true,
        'has_more', true,
        'made_progress', true,
        'fallback_required', false,
        'delta_refresh_complete', false,
        'stop_reason', 'DELTA_PHASE_BUDGET_EXHAUSTED',
        'elapsed_ms', v_elapsed_ms,
        'source_rows_written', v_source_rows_written,
        'line_rows_written', v_line_rows_written,
        'preview_rows_written', v_preview_rows_written,
        'next_cursor_json', jsonb_build_object('projection_run_id', v_projection_run_id::text, 'phase', 'VERIFY_PARITY_OR_SHADOW', 'cursor', '{}'::jsonb)
      );
    END IF;

    v_phase := 'VERIFY_PARITY_OR_SHADOW';
  END IF;


  IF v_phase IN ('VERIFY_PARITY_OR_SHADOW', 'UPDATE_CANDIDATE_STATE', 'FINALISE') THEN
    CREATE TEMP TABLE IF NOT EXISTS _bpay_delta_projection_rows (
      projection_run_id uuid NOT NULL,
      session_id uuid NOT NULL,
      candidate_id uuid NOT NULL,
      session_version bigint NOT NULL,
      source_change_seq bigint,
      timesheet_id uuid,
      canonical_timesheet_id uuid,
      section text NOT NULL,
      line_key text NOT NULL,
      row_key text NOT NULL,
      parent_line_key text,
      split_suffix text,
      source_ordinal bigint NOT NULL,
      row_ordinal bigint NOT NULL,
      pay_channel_scope text,
      refresh_scope_kind text NOT NULL,
      key_type text,
      key_value text,
      amount_ex_vat numeric,
      amount_inc_vat numeric,
      vat_amount numeric,
      draftable boolean NOT NULL DEFAULT false,
      is_ready_for_draft boolean NOT NULL DEFAULT false,
      selection_allowed boolean NOT NULL DEFAULT false,
      readiness_state text,
      blocked_reason_codes jsonb NOT NULL DEFAULT '[]'::jsonb,
      outstanding_state_json jsonb NOT NULL DEFAULT '{}'::jsonb,
      source_row_json jsonb NOT NULL,
      economic_key_json jsonb NOT NULL,
      contract_json jsonb NOT NULL,
      work_payload_json jsonb NOT NULL,
      result_row_json jsonb NOT NULL,
      preview_row_json jsonb NOT NULL,
      contract_ok boolean NOT NULL DEFAULT false,
      materialisable boolean NOT NULL DEFAULT false
    ) ON COMMIT DROP;


    TRUNCATE TABLE _bpay_delta_projection_rows;

    v_current_projection_cursor_json := '{}'::jsonb;
    v_project_result := public.pay_workbench_project_changed_timesheets_v1(
      p_session_id,
      p_candidate_id,
      v_projection_run_id,
      v_targeted_timesheet_ids,
      v_linked_timesheet_ids,
      v_payload_json
        || jsonb_build_object(
          'projection_run_id', v_projection_run_id::text,
          'projection_mode', v_projection_mode,
          'projection_class', v_projection_class,
          'session_version', COALESCE(v_session_version, v_session_row.version),
          'source_change_seq', COALESCE(v_source_change_seq, 0),
          'source_snapshot_run_id', CASE WHEN v_source_snapshot_run_id IS NULL THEN NULL ELSE v_source_snapshot_run_id::text END,
          'limit', LEAST(GREATEST(COALESCE(v_projected_row_count, 0), COALESCE(v_limit, 25), 25), 1000),
          'cursor', v_current_projection_cursor_json,
          'shadow_compare_required', v_shadow_compare_required,
          'shadow_compare_enforced', v_shadow_compare_enforced,
          'deterministic_recreate', true
        )
    );

    IF COALESCE((v_project_result->>'fallback_required')::boolean, false) IS TRUE THEN
      v_fallback_reason := COALESCE(v_project_result->>'fallback_reason', 'DELTA_RECREATE_PROJECTION_FALLBACK_REQUIRED');

      UPDATE public.banking_pay_workbench_preview_rows AS preview_row_update
      SET selected = false,
          selection_state = 'DIRTY',
          status = 'DIRTY',
          row_json = jsonb_strip_nulls(
            COALESCE(preview_row_update.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'deterministic_recreate_failed', true,
              'delta_fallback_reason', v_fallback_reason,
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE preview_row_update.session_id = p_session_id
        AND preview_row_update.candidate_id = p_candidate_id
        AND preview_row_update.status IN ('DELTA_PENDING', 'READY')
        AND COALESCE(preview_row_update.row_json->>'projection_run_id', '') = v_projection_run_id::text;


      UPDATE public.banking_pay_workbench_preview_rows AS preview_row_update
      SET selected = false,
          selection_state = 'DIRTY',
          status = 'DIRTY',
          row_json = jsonb_strip_nulls(
            COALESCE(preview_row_update.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE preview_row_update.session_id = p_session_id
        AND preview_row_update.candidate_id = p_candidate_id
        AND COALESCE(preview_row_update.row_json->>'projection_run_id', '') = v_projection_run_id::text;

      UPDATE public.banking_pay_workbench_candidate_source_lines AS source_row_update
      SET status = 'SUPERSEDED',
          source_row_json = jsonb_strip_nulls(
            COALESCE(source_row_update.source_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE source_row_update.session_id = p_session_id
        AND source_row_update.candidate_id = p_candidate_id
      AND source_row_update.source_build_run_id = v_projection_run_id
      AND source_row_update.status IN ('CURRENT', 'DIRTY');

      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work_update
      SET status = 'SKIPPED',
          result_row_json = jsonb_strip_nulls(
            COALESCE(line_work_update.result_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE line_work_update.session_id = p_session_id
        AND line_work_update.candidate_id = p_candidate_id
        AND (
          COALESCE(line_work_update.work_payload_json->>'projection_run_id', '') = v_projection_run_id::text
          OR COALESCE(line_work_update.result_row_json->>'projection_run_id', '') = v_projection_run_id::text
        )
        AND UPPER(BTRIM(COALESCE(line_work_update.status, ''))) NOT IN ('ERROR', 'FAILED', 'SKIPPED');

      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET status = 'FALLBACK_REQUIRED',
          fallback_required = true,
          fallback_reason = v_fallback_reason,
          diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
            || jsonb_build_object('deterministic_recreate_result', v_project_result),
          updated_at_utc = v_now,
          completed_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id;

      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'fallback_required', true,
        'fallback_reason', v_fallback_reason,
        'more_due', false,
        'has_more', false,
        'made_progress', true,
        'delta_refresh_complete', false,
        'stop_reason', 'DELTA_FALLBACK_REQUIRED'
      );
    END IF;

    IF COALESCE((v_project_result->>'more_due')::boolean, false) IS TRUE THEN
      v_fallback_reason := 'DELTA_DETERMINISTIC_RECREATE_EXCEEDED_SINGLE_CHUNK';

      UPDATE public.banking_pay_workbench_preview_rows AS preview_row_update
      SET selected = false,
          selection_state = 'DIRTY',
          status = 'DIRTY',
          row_json = jsonb_strip_nulls(
            COALESCE(preview_row_update.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'deterministic_recreate_incomplete', true,
              'delta_fallback_reason', v_fallback_reason,
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE preview_row_update.session_id = p_session_id
        AND preview_row_update.candidate_id = p_candidate_id
        AND preview_row_update.status IN ('DELTA_PENDING', 'READY')
        AND COALESCE(preview_row_update.row_json->>'projection_run_id', '') = v_projection_run_id::text;


      UPDATE public.banking_pay_workbench_preview_rows AS preview_row_update
      SET selected = false,
          selection_state = 'DIRTY',
          status = 'DIRTY',
          row_json = jsonb_strip_nulls(
            COALESCE(preview_row_update.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE preview_row_update.session_id = p_session_id
        AND preview_row_update.candidate_id = p_candidate_id
        AND COALESCE(preview_row_update.row_json->>'projection_run_id', '') = v_projection_run_id::text;

      UPDATE public.banking_pay_workbench_candidate_source_lines AS source_row_update
      SET status = 'SUPERSEDED',
          source_row_json = jsonb_strip_nulls(
            COALESCE(source_row_update.source_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE source_row_update.session_id = p_session_id
        AND source_row_update.candidate_id = p_candidate_id
      AND source_row_update.source_build_run_id = v_projection_run_id
      AND source_row_update.status IN ('CURRENT', 'DIRTY');

      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work_update
      SET status = 'SKIPPED',
          result_row_json = jsonb_strip_nulls(
            COALESCE(line_work_update.result_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE line_work_update.session_id = p_session_id
        AND line_work_update.candidate_id = p_candidate_id
        AND (
          COALESCE(line_work_update.work_payload_json->>'projection_run_id', '') = v_projection_run_id::text
          OR COALESCE(line_work_update.result_row_json->>'projection_run_id', '') = v_projection_run_id::text
        )
        AND UPPER(BTRIM(COALESCE(line_work_update.status, ''))) NOT IN ('ERROR', 'FAILED', 'SKIPPED');

      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET status = 'FALLBACK_REQUIRED',
          fallback_required = true,
          fallback_reason = v_fallback_reason,
          diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
            || jsonb_build_object('deterministic_recreate_result', v_project_result),
          updated_at_utc = v_now,
          completed_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id;

      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'fallback_required', true,
        'fallback_reason', v_fallback_reason,
        'more_due', false,
        'has_more', false,
        'made_progress', true,
        'delta_refresh_complete', false,
        'stop_reason', 'DELTA_FALLBACK_REQUIRED'
      );
    END IF;

    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
    SET diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
          || jsonb_build_object(
            'deterministic_recreate_completed_at_utc', v_now::text,
            'deterministic_recreate_phase', v_phase,
            'deterministic_recreate_row_count', COALESCE((v_project_result->>'projected_row_count')::integer, 0),
            'deterministic_recreate_row_key_line_key_parity_proven', LOWER(BTRIM(COALESCE(v_project_result->>'row_key_line_key_parity_proven', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
            'deterministic_recreate_economic_key_parity_proven', LOWER(BTRIM(COALESCE(v_project_result->>'economic_key_parity_proven', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          ),
        updated_at_utc = v_now
    WHERE projection_run_update.id = v_projection_run_id;

    v_elapsed_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::integer;
    IF v_elapsed_ms >= v_budget_cutoff_ms THEN
      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
            || jsonb_build_object(
              'budget_checkpoint_phase', 'DETERMINISTIC_RECREATE',
              'budget_checkpoint_elapsed_ms', v_elapsed_ms,
              'budget_checkpoint_at_utc', v_now::text
            ),
          cursor_json = jsonb_build_object('phase', v_phase, 'cursor', '{}'::jsonb),
          updated_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id;

      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'phase', 'DETERMINISTIC_RECREATE',
        'next_phase', v_phase,
        'more_due', true,
        'has_more', true,
        'made_progress', true,
        'fallback_required', false,
        'delta_refresh_complete', false,
        'stop_reason', 'DELTA_PHASE_BUDGET_EXHAUSTED',
        'elapsed_ms', v_elapsed_ms,
        'next_cursor_json', jsonb_build_object('projection_run_id', v_projection_run_id::text, 'phase', v_phase, 'cursor', '{}'::jsonb)
      );
    END IF;
  END IF;

  IF v_phase = 'VERIFY_PARITY_OR_SHADOW' THEN
    IF v_shadow_compare_required OR v_shadow_compare_enforced THEN
      IF to_regprocedure('public.pay_workbench_delta_shadow_compare_v1(uuid,uuid,uuid,jsonb)') IS NULL THEN
        v_shadow_result := jsonb_build_object(
          'ok', true,
          'compare_status', 'REFERENCE_UNAVAILABLE',
          'fallback_required', v_shadow_compare_enforced,
          'fallback_reason', 'DELTA_SHADOW_COMPARE_FUNCTION_MISSING'
        );
      ELSE
        v_shadow_result := public.pay_workbench_delta_shadow_compare_v1(
          p_session_id,
          p_candidate_id,
          v_projection_run_id,
          v_payload_json || jsonb_build_object(
            'shadow_compare_required', v_shadow_compare_required,
            'shadow_compare_enforced', v_shadow_compare_enforced
          )
        );
      END IF;

      v_shadow_compare_status := upper(BTRIM(COALESCE(v_shadow_result->>'compare_status', 'UNKNOWN')));
      v_shadow_reference_unavailable := v_shadow_compare_status IN ('REFERENCE_UNAVAILABLE', 'REFERENCE_MISSING', 'UNAVAILABLE');

      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET shadow_compare_required = v_shadow_compare_required,
          shadow_compare_enforced = v_shadow_compare_enforced,
          shadow_compare_status = v_shadow_compare_status,
          legacy_compare_status = v_shadow_compare_status,
          legacy_compare_json = jsonb_build_object(
            'compare_status', v_shadow_compare_status,
            'source_mismatches', COALESCE((v_shadow_result->>'source_mismatches')::integer, 0),
            'line_work_mismatches', COALESCE((v_shadow_result->>'line_work_mismatches')::integer, 0),
            'preview_mismatches', COALESCE((v_shadow_result->>'preview_mismatches')::integer, 0),
            'reference_unavailable', v_shadow_reference_unavailable
          ),
          diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
            || jsonb_build_object('shadow_compare_status', v_shadow_compare_status),
          updated_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id;

      IF v_shadow_compare_status = 'MISMATCH'
         OR (v_shadow_reference_unavailable AND v_shadow_compare_enforced)
         OR COALESCE((v_shadow_result->>'fallback_required')::boolean, false) IS TRUE THEN
        v_fallback_reason := COALESCE(v_shadow_result->>'fallback_reason', CASE WHEN v_shadow_reference_unavailable THEN 'SHADOW_COMPARE_REFERENCE_UNAVAILABLE' ELSE 'SHADOW_COMPARE_MISMATCH' END);

        UPDATE public.banking_pay_workbench_preview_rows AS preview_row_update
        SET selected = false,
            selection_state = 'DIRTY',
            status = 'DIRTY',
            row_json = jsonb_strip_nulls(COALESCE(preview_row_update.row_json, '{}'::jsonb)
              || jsonb_build_object('delta_fallback_reason', v_fallback_reason, 'shadow_compare_failed', true)),
            updated_at_utc = v_now
        WHERE preview_row_update.session_id = p_session_id
          AND preview_row_update.candidate_id = p_candidate_id
          AND COALESCE(preview_row_update.row_json->>'projection_run_id', '') = v_projection_run_id::text
          AND preview_row_update.status = 'DELTA_PENDING';

        UPDATE public.banking_pay_workbench_candidate_source_lines AS source_row_update
        SET status = 'SUPERSEDED',
            source_row_json = jsonb_strip_nulls(
              COALESCE(source_row_update.source_row_json, '{}'::jsonb)
              || jsonb_build_object(
                'delta_fallback_cleanup_applied', true,
                'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
                'shadow_compare_failed', true,
                'delta_fallback_at_utc', v_now::text
              )
            ),
            updated_at_utc = v_now
        WHERE source_row_update.session_id = p_session_id
          AND source_row_update.candidate_id = p_candidate_id
      AND source_row_update.source_build_run_id = v_projection_run_id
      AND source_row_update.status IN ('CURRENT', 'DIRTY');

        UPDATE public.banking_pay_workbench_candidate_line_work AS line_work_update
        SET status = 'SKIPPED',
            result_row_json = jsonb_strip_nulls(
              COALESCE(line_work_update.result_row_json, '{}'::jsonb)
              || jsonb_build_object(
                'delta_fallback_cleanup_applied', true,
                'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
                'shadow_compare_failed', true,
                'delta_fallback_at_utc', v_now::text
              )
            ),
            updated_at_utc = v_now
        WHERE line_work_update.session_id = p_session_id
          AND line_work_update.candidate_id = p_candidate_id
          AND (
            COALESCE(line_work_update.work_payload_json->>'projection_run_id', '') = v_projection_run_id::text
            OR COALESCE(line_work_update.result_row_json->>'projection_run_id', '') = v_projection_run_id::text
          )
          AND UPPER(BTRIM(COALESCE(line_work_update.status, ''))) NOT IN ('ERROR', 'FAILED', 'SKIPPED');

        UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
        SET status = 'FALLBACK_REQUIRED',
            fallback_required = true,
            fallback_reason = v_fallback_reason,
            updated_at_utc = v_now,
            completed_at_utc = v_now
        WHERE projection_run_update.id = v_projection_run_id;

        RETURN jsonb_build_object(
          'ok', true,
          'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
          'projection_run_id', v_projection_run_id::text,
          'fallback_required', true,
          'fallback_reason', v_fallback_reason,
          'shadow_compare_status', v_shadow_compare_status,
          'shadow_compare_failed', true,
          'more_due', false,
          'has_more', false,
          'made_progress', true,
          'delta_refresh_complete', false,
          'stop_reason', 'DELTA_FALLBACK_REQUIRED'
        );
      END IF;
    ELSE
      v_shadow_compare_status := 'NOT_REQUIRED';
      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET shadow_compare_required = false,
          shadow_compare_enforced = false,
          shadow_compare_status = 'NOT_REQUIRED',
          legacy_compare_status = 'NOT_REQUIRED',
          legacy_compare_json = jsonb_build_object(
            'compare_status', 'NOT_REQUIRED',
            'shadow_compare_not_required', true
          ),
          phase = 'UPDATE_CANDIDATE_STATE',
          cursor_json = jsonb_build_object('phase', 'UPDATE_CANDIDATE_STATE', 'cursor', '{}'::jsonb),
          updated_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id;
    END IF;

    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
    SET phase = 'UPDATE_CANDIDATE_STATE',
        cursor_json = jsonb_build_object('phase', 'UPDATE_CANDIDATE_STATE', 'cursor', '{}'::jsonb),
        updated_at_utc = v_now
    WHERE projection_run_update.id = v_projection_run_id;

    v_elapsed_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::integer;
    IF v_elapsed_ms >= v_budget_cutoff_ms THEN
      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
            || jsonb_build_object(
              'budget_checkpoint_phase', 'VERIFY_PARITY_OR_SHADOW',
              'budget_checkpoint_elapsed_ms', v_elapsed_ms,
              'budget_checkpoint_at_utc', v_now::text
            ),
          phase = 'UPDATE_CANDIDATE_STATE',
          cursor_json = jsonb_build_object('phase', 'UPDATE_CANDIDATE_STATE', 'cursor', '{}'::jsonb),
          updated_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id;

      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'phase', 'VERIFY_PARITY_OR_SHADOW',
        'next_phase', 'UPDATE_CANDIDATE_STATE',
        'more_due', true,
        'has_more', true,
        'made_progress', true,
        'fallback_required', false,
        'delta_refresh_complete', false,
        'stop_reason', 'DELTA_PHASE_BUDGET_EXHAUSTED',
        'elapsed_ms', v_elapsed_ms,
        'shadow_compare_status', COALESCE(NULLIF(v_shadow_compare_status, ''), 'NOT_REQUIRED'),
        'next_cursor_json', jsonb_build_object('projection_run_id', v_projection_run_id::text, 'phase', 'UPDATE_CANDIDATE_STATE', 'cursor', '{}'::jsonb)
      );
    END IF;

    v_phase := 'UPDATE_CANDIDATE_STATE';
  END IF;

  IF v_phase='UPDATE_CANDIDATE_STATE' AND v_sealed_lifecycle_delta THEN
    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS sealed_run
    SET phase='FINALISE',cursor_json=jsonb_build_object('phase','FINALISE','cursor','{}'::jsonb),
        candidate_state_updated=false,updated_at_utc=v_now
    WHERE sealed_run.id=v_projection_run_id;
    v_phase:='FINALISE';
  END IF;

  IF v_phase = 'UPDATE_CANDIDATE_STATE' THEN
    SELECT COUNT(*) FILTER (
             WHERE COALESCE(preview_row.row_json->>'policy_x_authority_scope', '') <> 'PRE_DRAFT_LIVE_TRUTH'
           )::integer,
           COUNT(*) FILTER (
             WHERE (preview_row.selected IS TRUE OR COALESCE(preview_row.row_json->>'target_selected', 'false') IN ('true', 't', '1', 'yes', 'y', 'on'))
               AND (preview_row.timesheet_id IS NULL OR NULLIF(BTRIM(COALESCE(preview_row.key_type, '')), '') IS NULL OR NULLIF(BTRIM(COALESCE(preview_row.key_value, '')), '') IS NULL)
           )::integer,
           COUNT(*) FILTER (
             WHERE COALESCE(preview_row.row_json->>'projection_certified', 'false') NOT IN ('true', 't', '1', 'yes', 'y', 'on')
           )::integer,
           COUNT(*) FILTER (
             WHERE (preview_row.selected IS TRUE OR COALESCE(preview_row.row_json->>'target_selected', 'false') IN ('true', 't', '1', 'yes', 'y', 'on'))
               AND COALESCE(preview_row.row_json->>'row_key_line_key_parity_proven', 'false') NOT IN ('true', 't', '1', 'yes', 'y', 'on')
               AND NOT (
                 (v_shadow_compare_required OR v_shadow_compare_enforced)
                 AND COALESCE(v_shadow_compare_status, '') = 'MATCH'
               )
           )::integer
    INTO v_policy_x_invalid_count,
         v_economic_key_invalid_count,
         v_projection_cert_invalid_count,
         v_key_parity_invalid_count
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id = p_session_id
      AND preview_row.candidate_id = p_candidate_id
      AND preview_row.status IN ('DELTA_PENDING', 'READY')
      AND COALESCE(preview_row.row_json->>'projection_run_id', '') = v_projection_run_id::text;

    IF COALESCE(v_policy_x_invalid_count, 0) > 0
       OR COALESCE(v_economic_key_invalid_count, 0) > 0
       OR COALESCE(v_projection_cert_invalid_count, 0) > 0
       OR COALESCE(v_key_parity_invalid_count, 0) > 0 THEN
      v_fallback_reason := 'DELTA_FINAL_SAFETY_GUARD_FAILED';
      UPDATE public.banking_pay_workbench_preview_rows AS preview_row_update
      SET selected = false,
          selection_state = 'DIRTY',
          status = 'DIRTY',
          row_json = jsonb_strip_nulls(COALESCE(preview_row_update.row_json, '{}'::jsonb)
            || jsonb_build_object('delta_final_safety_guard_failed', true, 'delta_fallback_reason', v_fallback_reason)),
          updated_at_utc = v_now
      WHERE preview_row_update.session_id = p_session_id
        AND preview_row_update.candidate_id = p_candidate_id
        AND preview_row_update.status = 'DELTA_PENDING'
        AND COALESCE(preview_row_update.row_json->>'projection_run_id', '') = v_projection_run_id::text;


      UPDATE public.banking_pay_workbench_preview_rows AS preview_row_update
      SET selected = false,
          selection_state = 'DIRTY',
          status = 'DIRTY',
          row_json = jsonb_strip_nulls(
            COALESCE(preview_row_update.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE preview_row_update.session_id = p_session_id
        AND preview_row_update.candidate_id = p_candidate_id
        AND COALESCE(preview_row_update.row_json->>'projection_run_id', '') = v_projection_run_id::text;

      UPDATE public.banking_pay_workbench_candidate_source_lines AS source_row_update
      SET status = 'SUPERSEDED',
          source_row_json = jsonb_strip_nulls(
            COALESCE(source_row_update.source_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE source_row_update.session_id = p_session_id
        AND source_row_update.candidate_id = p_candidate_id
      AND source_row_update.source_build_run_id = v_projection_run_id
      AND source_row_update.status IN ('CURRENT', 'DIRTY');

      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work_update
      SET status = 'SKIPPED',
          result_row_json = jsonb_strip_nulls(
            COALESCE(line_work_update.result_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE line_work_update.session_id = p_session_id
        AND line_work_update.candidate_id = p_candidate_id
        AND (
          COALESCE(line_work_update.work_payload_json->>'projection_run_id', '') = v_projection_run_id::text
          OR COALESCE(line_work_update.result_row_json->>'projection_run_id', '') = v_projection_run_id::text
        )
        AND UPPER(BTRIM(COALESCE(line_work_update.status, ''))) NOT IN ('ERROR', 'FAILED', 'SKIPPED');

      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET status = 'FALLBACK_REQUIRED',
          fallback_required = true,
          fallback_reason = v_fallback_reason,
          diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
            || jsonb_build_object(
              'policy_x_invalid_count', COALESCE(v_policy_x_invalid_count, 0),
              'economic_key_invalid_count', COALESCE(v_economic_key_invalid_count, 0),
              'projection_cert_invalid_count', COALESCE(v_projection_cert_invalid_count, 0),
              'key_parity_invalid_count', COALESCE(v_key_parity_invalid_count, 0)
            ),
          updated_at_utc = v_now,
          completed_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id;

      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'fallback_required', true,
        'fallback_reason', v_fallback_reason,
        'more_due', false,
        'has_more', false,
        'made_progress', true,
        'delta_refresh_complete', false,
        'stop_reason', 'DELTA_FALLBACK_REQUIRED'
      );
    END IF;

    UPDATE public.banking_pay_workbench_preview_rows AS preview_row_update
    SET status = 'READY',
        selected = CASE
          WHEN (v_shadow_compare_required OR v_shadow_compare_enforced)
           AND COALESCE(v_shadow_compare_status, '') = 'MATCH'
           AND COALESCE(preview_row_update.row_json->>'target_selected', 'false') IN ('true', 't', '1', 'yes', 'y', 'on')
           AND COALESCE(preview_row_update.row_json->>'target_selection_state', '') = 'SELECTED'
          THEN true
          ELSE false
        END,
        selection_state = CASE
          WHEN (v_shadow_compare_required OR v_shadow_compare_enforced)
           AND COALESCE(v_shadow_compare_status, '') = 'MATCH'
           AND COALESCE(preview_row_update.row_json->>'target_selected', 'false') IN ('true', 't', '1', 'yes', 'y', 'on')
           AND COALESCE(preview_row_update.row_json->>'target_selection_state', '') = 'SELECTED'
          THEN 'SELECTED'
          ELSE 'NOT_SELECTABLE'
        END,
        row_json = jsonb_strip_nulls(
          COALESCE(preview_row_update.row_json, '{}'::jsonb)
          || jsonb_build_object(
            'shadow_compare_status', COALESCE(NULLIF(v_shadow_compare_status, ''), 'NOT_REQUIRED')
          )
          || CASE
            WHEN COALESCE(v_shadow_compare_status, '') = 'MATCH' THEN jsonb_build_object(
              'shadow_compare_passed', true,
              'projection_certified', true,
              'shadow_promoted_at_utc', v_now::text
            )
            ELSE jsonb_build_object(
              'shadow_compare_passed', false
            )
          END
        ),
        updated_at_utc = v_now
    WHERE preview_row_update.session_id = p_session_id
      AND preview_row_update.candidate_id = p_candidate_id
      AND preview_row_update.status = 'DELTA_PENDING'
      AND COALESCE(preview_row_update.row_json->>'projection_run_id', '') = v_projection_run_id::text;

    v_candidate_state_result := public.pay_workbench_delta_update_candidate_state_v1(
      p_session_id,
      p_candidate_id,
      v_projection_run_id,
      v_payload_json || jsonb_build_object('context', 'DELTA_REFRESH')
    );

    IF LOWER(BTRIM(COALESCE(v_candidate_state_result->>'stale_candidate_state_update_skipped', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      UPDATE public.banking_pay_workbench_preview_rows AS preview_row_update
      SET selected = false,
          selection_state = 'DIRTY',
          status = 'DIRTY',
          row_json = jsonb_strip_nulls(
            COALESCE(preview_row_update.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'superseded_by_newer_source_change_seq', true,
              'candidate_state_update_skipped', true,
              'source_change_seq', COALESCE(v_source_change_seq, 0),
              'existing_source_change_seq', CASE WHEN COALESCE(v_candidate_state_result->>'existing_source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (v_candidate_state_result->>'existing_source_change_seq')::bigint ELSE 0::bigint END,
              'superseded_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE preview_row_update.session_id = p_session_id
        AND preview_row_update.candidate_id = p_candidate_id
        AND COALESCE(preview_row_update.row_json->>'projection_run_id', '') = v_projection_run_id::text;

      UPDATE public.banking_pay_workbench_candidate_source_lines AS source_row_update
      SET status = 'SUPERSEDED',
          source_row_json = jsonb_strip_nulls(
            COALESCE(source_row_update.source_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'superseded_by_newer_source_change_seq', true,
              'candidate_state_update_skipped', true,
              'source_change_seq', COALESCE(v_source_change_seq, 0),
              'existing_source_change_seq', CASE WHEN COALESCE(v_candidate_state_result->>'existing_source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (v_candidate_state_result->>'existing_source_change_seq')::bigint ELSE 0::bigint END,
              'superseded_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE source_row_update.session_id = p_session_id
        AND source_row_update.candidate_id = p_candidate_id
      AND source_row_update.source_build_run_id = v_projection_run_id
      AND source_row_update.status IN ('CURRENT', 'DIRTY');

      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work_update
      SET status = 'SKIPPED',
          result_row_json = jsonb_strip_nulls(
            COALESCE(line_work_update.result_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'superseded_by_newer_source_change_seq', true,
              'candidate_state_update_skipped', true,
              'source_change_seq', COALESCE(v_source_change_seq, 0),
              'existing_source_change_seq', CASE WHEN COALESCE(v_candidate_state_result->>'existing_source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (v_candidate_state_result->>'existing_source_change_seq')::bigint ELSE 0::bigint END,
              'superseded_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE line_work_update.session_id = p_session_id
        AND line_work_update.candidate_id = p_candidate_id
        AND (
          COALESCE(line_work_update.work_payload_json->>'projection_run_id', '') = v_projection_run_id::text
          OR COALESCE(line_work_update.result_row_json->>'projection_run_id', '') = v_projection_run_id::text
        )
        AND UPPER(BTRIM(COALESCE(line_work_update.status, ''))) NOT IN ('ERROR', 'FAILED', 'SKIPPED');

      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET status = 'FAILED',
          fallback_required = false,
          fallback_reason = 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ',
          candidate_state_updated = false,
          diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
            || jsonb_build_object(
              'candidate_state_result', v_candidate_state_result,
              'superseded_by_newer_source_change_seq', true,
              'terminalised_by', 'pay_workbench_candidate_delta_refresh_chunk_candidate_state_guard',
              'terminalised_at_utc', v_now::text
            ),
          updated_at_utc = v_now,
          completed_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id
        AND projection_run_update.session_id = p_session_id
        AND projection_run_update.candidate_id = p_candidate_id;

      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'fallback_required', false,
        'more_due', false,
        'has_more', false,
        'made_progress', true,
        'delta_refresh_complete', true,
        'candidate_state_updated', false,
        'superseded_by_newer_source_change_seq', true,
        'source_change_seq', COALESCE(v_source_change_seq, 0),
        'newer_source_change_seq', CASE WHEN COALESCE(v_candidate_state_result->>'existing_source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (v_candidate_state_result->>'existing_source_change_seq')::bigint ELSE COALESCE(v_live_source_change_seq, 0) END,
        'candidate_state_result', v_candidate_state_result,
        'stop_reason', 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ'
      );
    END IF;

    IF COALESCE((v_candidate_state_result->>'ok')::boolean, false) IS NOT TRUE THEN
      v_fallback_reason := COALESCE(v_candidate_state_result->>'fallback_reason', 'DELTA_CANDIDATE_STATE_UPDATE_FAILED');

      UPDATE public.banking_pay_workbench_preview_rows AS preview_row_update
      SET selected = false,
          selection_state = 'DIRTY',
          status = 'DIRTY',
          row_json = jsonb_strip_nulls(
            COALESCE(preview_row_update.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'candidate_state_update_failed', true,
              'delta_fallback_reason', v_fallback_reason,
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE preview_row_update.session_id = p_session_id
        AND preview_row_update.candidate_id = p_candidate_id
        AND preview_row_update.status IN ('DELTA_PENDING', 'READY')
        AND COALESCE(preview_row_update.row_json->>'projection_run_id', '') = v_projection_run_id::text;


      UPDATE public.banking_pay_workbench_preview_rows AS preview_row_update
      SET selected = false,
          selection_state = 'DIRTY',
          status = 'DIRTY',
          row_json = jsonb_strip_nulls(
            COALESCE(preview_row_update.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE preview_row_update.session_id = p_session_id
        AND preview_row_update.candidate_id = p_candidate_id
        AND COALESCE(preview_row_update.row_json->>'projection_run_id', '') = v_projection_run_id::text;

      UPDATE public.banking_pay_workbench_candidate_source_lines AS source_row_update
      SET status = 'SUPERSEDED',
          source_row_json = jsonb_strip_nulls(
            COALESCE(source_row_update.source_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE source_row_update.session_id = p_session_id
        AND source_row_update.candidate_id = p_candidate_id
      AND source_row_update.source_build_run_id = v_projection_run_id
      AND source_row_update.status IN ('CURRENT', 'DIRTY');

      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work_update
      SET status = 'SKIPPED',
          result_row_json = jsonb_strip_nulls(
            COALESCE(line_work_update.result_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE line_work_update.session_id = p_session_id
        AND line_work_update.candidate_id = p_candidate_id
        AND (
          COALESCE(line_work_update.work_payload_json->>'projection_run_id', '') = v_projection_run_id::text
          OR COALESCE(line_work_update.result_row_json->>'projection_run_id', '') = v_projection_run_id::text
        )
        AND UPPER(BTRIM(COALESCE(line_work_update.status, ''))) NOT IN ('ERROR', 'FAILED', 'SKIPPED');

      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET status = 'FALLBACK_REQUIRED',
          fallback_required = true,
          fallback_reason = v_fallback_reason,
          diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
            || jsonb_build_object('candidate_state_result', v_candidate_state_result),
          updated_at_utc = v_now,
          completed_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id;
      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'fallback_required', true,
        'fallback_reason', v_fallback_reason,
        'more_due', false,
        'has_more', false,
        'made_progress', true,
        'delta_refresh_complete', false,
        'stop_reason', 'DELTA_FALLBACK_REQUIRED'
      );
    END IF;

    v_candidate_state_updated := true;
    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
    SET phase = 'FINALISE',
        cursor_json = jsonb_build_object('phase', 'FINALISE', 'cursor', '{}'::jsonb),
        candidate_state_updated = true,
        diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
          || jsonb_build_object('candidate_state_result', v_candidate_state_result),
        updated_at_utc = v_now
    WHERE projection_run_update.id = v_projection_run_id;

    v_elapsed_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::integer;
    IF v_elapsed_ms >= v_budget_cutoff_ms THEN
      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
            || jsonb_build_object(
              'budget_checkpoint_phase', 'UPDATE_CANDIDATE_STATE',
              'budget_checkpoint_elapsed_ms', v_elapsed_ms,
              'budget_checkpoint_at_utc', v_now::text
            ),
          phase = 'FINALISE',
          cursor_json = jsonb_build_object('phase', 'FINALISE', 'cursor', '{}'::jsonb),
          updated_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id;

      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'phase', 'UPDATE_CANDIDATE_STATE',
        'next_phase', 'FINALISE',
        'more_due', true,
        'has_more', true,
        'made_progress', true,
        'fallback_required', false,
        'delta_refresh_complete', false,
        'candidate_state_updated', true,
        'stop_reason', 'DELTA_PHASE_BUDGET_EXHAUSTED',
        'elapsed_ms', v_elapsed_ms,
        'next_cursor_json', jsonb_build_object('projection_run_id', v_projection_run_id::text, 'phase', 'FINALISE', 'cursor', '{}'::jsonb)
      );
    END IF;

    v_phase := 'FINALISE';
  END IF;

  IF v_phase = 'FINALISE' THEN
    IF v_sealed_lifecycle_delta THEN
      BEGIN
        v_finalize_result:=private.pay_workbench_targeted_delta_scope_finalize_v1(
          p_session_id,p_candidate_id,v_projection_run_id
        );
      EXCEPTION WHEN OTHERS THEN
        v_fallback_reason:='TARGETED_DELTA_ATOMIC_FINALISE_FAILED';
        UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS failed_run
        SET status='FALLBACK_REQUIRED',fallback_required=true,
            fallback_reason=v_fallback_reason,completed_at_utc=v_now,updated_at_utc=v_now,
            diagnostics_json=COALESCE(failed_run.diagnostics_json,'{}'::jsonb)
              ||jsonb_build_object('finalise_sqlstate',SQLSTATE,'finalise_failed',true)
        WHERE failed_run.id=v_projection_run_id;
        RETURN jsonb_build_object(
          'ok',true,'job_type','WORKBENCH_CANDIDATE_DELTA_REFRESH',
          'projection_run_id',v_projection_run_id,'fallback_required',true,
          'fallback_reason',v_fallback_reason,'more_due',false,'has_more',false,
          'made_progress',true,'delta_refresh_complete',false,
          'stop_reason','DELTA_FALLBACK_REQUIRED'
        );
      END;
      RETURN COALESCE(v_finalize_result,'{}'::jsonb)||jsonb_build_object(
        'job_type','WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id',v_projection_run_id,'fallback_required',false,
        'more_due',false,'has_more',false,'made_progress',true,
        'delta_refresh_complete',true,'stop_reason','DELTA_COMPLETE'
      );
    END IF;

    SELECT COALESCE(projection_run.candidate_state_updated, false),
           COALESCE(projection_run.fallback_required, false),
           projection_run.fallback_reason,
           COALESCE(projection_run.shadow_compare_status, 'NOT_REQUIRED'),
           COALESCE(projection_run.shadow_compare_required, false),
           COALESCE(projection_run.shadow_compare_enforced, false),
           COALESCE(projection_run.projected_row_count, 0),
           COALESCE(projection_run.written_source_count, 0),
           COALESCE(projection_run.written_line_work_count, 0),
           COALESCE(projection_run.written_preview_count, 0)
    INTO v_candidate_state_updated,
         v_fallback_allowed,
         v_fallback_reason,
         v_shadow_compare_status,
         v_shadow_compare_required,
         v_shadow_compare_enforced,
         v_projected_row_count,
         v_written_source_count,
         v_written_line_work_count,
         v_written_preview_count
    FROM public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run
    WHERE projection_run.id = v_projection_run_id
      AND projection_run.session_id = p_session_id
      AND projection_run.candidate_id = p_candidate_id
    FOR UPDATE;

    IF v_fallback_allowed IS TRUE OR v_candidate_state_updated IS NOT TRUE THEN
      v_fallback_reason := COALESCE(v_fallback_reason, 'DELTA_FINALISE_GUARD_NOT_SATISFIED');

      UPDATE public.banking_pay_workbench_preview_rows AS preview_row_update
      SET selected = false,
          selection_state = 'DIRTY',
          status = 'DIRTY',
          row_json = jsonb_strip_nulls(
            COALESCE(preview_row_update.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'finalise_guard_failed', true,
              'delta_fallback_reason', v_fallback_reason,
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE preview_row_update.session_id = p_session_id
        AND preview_row_update.candidate_id = p_candidate_id
        AND preview_row_update.status IN ('DELTA_PENDING', 'READY')
        AND COALESCE(preview_row_update.row_json->>'projection_run_id', '') = v_projection_run_id::text;


      UPDATE public.banking_pay_workbench_preview_rows AS preview_row_update
      SET selected = false,
          selection_state = 'DIRTY',
          status = 'DIRTY',
          row_json = jsonb_strip_nulls(
            COALESCE(preview_row_update.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE preview_row_update.session_id = p_session_id
        AND preview_row_update.candidate_id = p_candidate_id
        AND COALESCE(preview_row_update.row_json->>'projection_run_id', '') = v_projection_run_id::text;

      UPDATE public.banking_pay_workbench_candidate_source_lines AS source_row_update
      SET status = 'SUPERSEDED',
          source_row_json = jsonb_strip_nulls(
            COALESCE(source_row_update.source_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE source_row_update.session_id = p_session_id
        AND source_row_update.candidate_id = p_candidate_id
      AND source_row_update.source_build_run_id = v_projection_run_id
      AND source_row_update.status IN ('CURRENT', 'DIRTY');

      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work_update
      SET status = 'SKIPPED',
          result_row_json = jsonb_strip_nulls(
            COALESCE(line_work_update.result_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE line_work_update.session_id = p_session_id
        AND line_work_update.candidate_id = p_candidate_id
        AND (
          COALESCE(line_work_update.work_payload_json->>'projection_run_id', '') = v_projection_run_id::text
          OR COALESCE(line_work_update.result_row_json->>'projection_run_id', '') = v_projection_run_id::text
        )
        AND UPPER(BTRIM(COALESCE(line_work_update.status, ''))) NOT IN ('ERROR', 'FAILED', 'SKIPPED');

      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET status = 'FALLBACK_REQUIRED',
          fallback_required = true,
          fallback_reason = v_fallback_reason,
          updated_at_utc = v_now,
          completed_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id;
      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'fallback_required', true,
        'fallback_reason', v_fallback_reason,
        'more_due', false,
        'has_more', false,
        'made_progress', true,
        'delta_refresh_complete', false,
        'stop_reason', 'DELTA_FALLBACK_REQUIRED'
      );
    END IF;

    IF COALESCE(v_shadow_compare_enforced, false) IS TRUE
       AND COALESCE(v_shadow_compare_status, '') NOT IN ('MATCH', 'NOT_REQUIRED') THEN
      v_fallback_reason := 'DELTA_SHADOW_COMPARE_NOT_PASSED_AT_FINALISE';

      UPDATE public.banking_pay_workbench_preview_rows AS preview_row_update
      SET selected = false,
          selection_state = 'DIRTY',
          status = 'DIRTY',
          row_json = jsonb_strip_nulls(
            COALESCE(preview_row_update.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'shadow_compare_not_passed_at_finalise', true,
              'shadow_compare_status', COALESCE(v_shadow_compare_status, 'UNKNOWN'),
              'delta_fallback_reason', v_fallback_reason,
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE preview_row_update.session_id = p_session_id
        AND preview_row_update.candidate_id = p_candidate_id
        AND preview_row_update.status IN ('DELTA_PENDING', 'READY')
        AND COALESCE(preview_row_update.row_json->>'projection_run_id', '') = v_projection_run_id::text;


      UPDATE public.banking_pay_workbench_preview_rows AS preview_row_update
      SET selected = false,
          selection_state = 'DIRTY',
          status = 'DIRTY',
          row_json = jsonb_strip_nulls(
            COALESCE(preview_row_update.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE preview_row_update.session_id = p_session_id
        AND preview_row_update.candidate_id = p_candidate_id
        AND COALESCE(preview_row_update.row_json->>'projection_run_id', '') = v_projection_run_id::text;

      UPDATE public.banking_pay_workbench_candidate_source_lines AS source_row_update
      SET status = 'SUPERSEDED',
          source_row_json = jsonb_strip_nulls(
            COALESCE(source_row_update.source_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE source_row_update.session_id = p_session_id
        AND source_row_update.candidate_id = p_candidate_id
      AND source_row_update.source_build_run_id = v_projection_run_id
      AND source_row_update.status IN ('CURRENT', 'DIRTY');

      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work_update
      SET status = 'SKIPPED',
          result_row_json = jsonb_strip_nulls(
            COALESCE(line_work_update.result_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_fallback_cleanup_applied', true,
              'delta_fallback_reason', COALESCE(v_fallback_reason, 'DELTA_FALLBACK_REQUIRED'),
              'delta_fallback_at_utc', v_now::text
            )
          ),
          updated_at_utc = v_now
      WHERE line_work_update.session_id = p_session_id
        AND line_work_update.candidate_id = p_candidate_id
        AND (
          COALESCE(line_work_update.work_payload_json->>'projection_run_id', '') = v_projection_run_id::text
          OR COALESCE(line_work_update.result_row_json->>'projection_run_id', '') = v_projection_run_id::text
        )
        AND UPPER(BTRIM(COALESCE(line_work_update.status, ''))) NOT IN ('ERROR', 'FAILED', 'SKIPPED');

      UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
      SET status = 'FALLBACK_REQUIRED',
          fallback_required = true,
          fallback_reason = v_fallback_reason,
          updated_at_utc = v_now,
          completed_at_utc = v_now
      WHERE projection_run_update.id = v_projection_run_id;
      RETURN jsonb_build_object(
        'ok', true,
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'fallback_required', true,
        'fallback_reason', v_fallback_reason,
        'more_due', false,
        'has_more', false,
        'made_progress', true,
        'delta_refresh_complete', false,
        'stop_reason', 'DELTA_FALLBACK_REQUIRED'
      );
    END IF;

    SELECT COALESCE(projection_run.diagnostics_json->'pre_delta_candidate_counts', '{}'::jsonb)
    INTO v_pre_candidate_counts_json
    FROM public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run
    WHERE projection_run.id = v_projection_run_id
      AND projection_run.session_id = p_session_id
      AND projection_run.candidate_id = p_candidate_id;

    WITH post_line_counts AS (
      SELECT COUNT(*)::integer AS line_units_total,
             COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(line_work.status, ''))) IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SKIPPED'))::integer AS line_units_ready,
             COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(line_work.status, ''))) IN ('PENDING', 'PROCESSING', 'DIRTY'))::integer AS line_units_pending,
             COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(line_work.status, ''))) IN ('ERROR', 'FAILED'))::integer AS line_units_failed
      FROM public.banking_pay_workbench_candidate_line_work AS line_work
      WHERE line_work.session_id = p_session_id
        AND line_work.candidate_id = p_candidate_id
    ), post_preview_counts AS (
      SELECT COUNT(*) FILTER (WHERE preview_row.status = 'READY')::integer AS preview_row_count,
             COUNT(*) FILTER (WHERE preview_row.status = 'READY' AND preview_row.selected IS TRUE AND preview_row.selection_state = 'SELECTED')::integer AS selected_row_count
      FROM public.banking_pay_workbench_preview_rows AS preview_row
      WHERE preview_row.session_id = p_session_id
        AND preview_row.candidate_id = p_candidate_id
        AND preview_row.session_version = COALESCE(v_session_version, v_session_row.version)
    ), post_section_counts AS (
      SELECT COALESCE(jsonb_object_agg(section_group.section, section_group.row_count ORDER BY section_group.section), '{}'::jsonb) AS section_counts_json
      FROM (
        SELECT preview_section.section, COUNT(*)::integer AS row_count
        FROM public.banking_pay_workbench_preview_rows AS preview_section
        WHERE preview_section.session_id = p_session_id
          AND preview_section.candidate_id = p_candidate_id
          AND preview_section.session_version = COALESCE(v_session_version, v_session_row.version)
          AND preview_section.status = 'READY'
        GROUP BY preview_section.section
      ) AS section_group
    ), post_sample_rows AS (
      SELECT COALESCE(jsonb_agg(sample_row.sample_json ORDER BY sample_row.row_ordinal, sample_row.id), '[]'::jsonb) AS candidate_sample_rows_json
      FROM (
        SELECT preview_sample.id,
               preview_sample.row_ordinal,
               jsonb_build_object(
                 'id', preview_sample.id::text,
                 'candidate_id', preview_sample.candidate_id::text,
                 'section', preview_sample.section,
                 'row_key', preview_sample.row_key,
                 'selected', preview_sample.selected,
                 'selection_state', preview_sample.selection_state
               ) AS sample_json
        FROM public.banking_pay_workbench_preview_rows AS preview_sample
        WHERE preview_sample.session_id = p_session_id
          AND preview_sample.candidate_id = p_candidate_id
          AND preview_sample.session_version = COALESCE(v_session_version, v_session_row.version)
          AND preview_sample.status = 'READY'
        ORDER BY preview_sample.row_ordinal, preview_sample.id
        LIMIT 50
      ) AS sample_row
    )
    SELECT jsonb_build_object(
             'line_units_total', post_line_counts.line_units_total,
             'line_units_ready', post_line_counts.line_units_ready,
             'line_units_pending', post_line_counts.line_units_pending,
             'line_units_failed', post_line_counts.line_units_failed,
             'preview_row_count', post_preview_counts.preview_row_count,
             'selected_row_count', post_preview_counts.selected_row_count,
             'section_counts_json', post_section_counts.section_counts_json
           ),
           post_line_counts.line_units_total - COALESCE((v_pre_candidate_counts_json->>'line_units_total')::integer, 0),
           post_line_counts.line_units_ready - COALESCE((v_pre_candidate_counts_json->>'line_units_ready')::integer, 0),
           post_line_counts.line_units_pending - COALESCE((v_pre_candidate_counts_json->>'line_units_pending')::integer, 0),
           post_line_counts.line_units_failed - COALESCE((v_pre_candidate_counts_json->>'line_units_failed')::integer, 0),
           post_preview_counts.preview_row_count - COALESCE((v_pre_candidate_counts_json->>'preview_row_count')::integer, 0),
           post_preview_counts.selected_row_count - COALESCE((v_pre_candidate_counts_json->>'selected_row_count')::integer, 0),
           post_section_counts.section_counts_json,
           post_sample_rows.candidate_sample_rows_json
    INTO v_post_candidate_counts_json,
         v_line_units_total_delta,
         v_line_units_ready_delta,
         v_line_units_pending_delta,
         v_line_units_failed_delta,
         v_preview_row_count_delta,
         v_selected_row_count_delta,
         v_section_counts_json,
         v_candidate_sample_rows_json
    FROM post_line_counts, post_preview_counts, post_section_counts, post_sample_rows;

    SELECT COALESCE(jsonb_object_agg(section_keys.section_key, to_jsonb(section_keys.section_delta) ORDER BY section_keys.section_key), '{}'::jsonb)
    INTO v_section_delta_json
    FROM (
      SELECT all_sections.section_key,
             COALESCE((v_section_counts_json->>all_sections.section_key)::integer, 0)
             - COALESCE((COALESCE(v_pre_candidate_counts_json->'section_counts_json', '{}'::jsonb)->>all_sections.section_key)::integer, 0) AS section_delta
      FROM (
        SELECT current_sections.key AS section_key
        FROM jsonb_each(COALESCE(v_section_counts_json, '{}'::jsonb)) AS current_sections(key, value)
        UNION
        SELECT previous_sections.key AS section_key
        FROM jsonb_each(COALESCE(v_pre_candidate_counts_json->'section_counts_json', '{}'::jsonb)) AS previous_sections(key, value)
      ) AS all_sections
    ) AS section_keys;

    v_scope_ready_delta := CASE WHEN UPPER(BTRIM(COALESCE(v_scope_row.status, ''))) IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY') THEN 0 ELSE 1 END;
    v_scope_seeded_delta := CASE WHEN COALESCE(v_scope_row.seeded, false) IS TRUE THEN 0 ELSE 1 END;
    v_scope_pending_delta := CASE WHEN UPPER(BTRIM(COALESCE(v_scope_row.status, ''))) NOT IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY', 'FAILED', 'ERROR', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR') THEN -1 ELSE 0 END;
    v_scope_failed_delta := CASE WHEN UPPER(BTRIM(COALESCE(v_scope_row.status, ''))) IN ('FAILED', 'ERROR', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR') THEN -1 ELSE 0 END;


    UPDATE public.banking_pay_workbench_session_scope AS scope_row_update
    SET status = 'READY',
        seeded = true,
        dirty = false,
        pending_job_id = NULL::uuid,
        error_json = NULL::jsonb,
        updated_at_utc = v_now
    WHERE scope_row_update.session_id = p_session_id
      AND scope_row_update.candidate_id = p_candidate_id;

    PERFORM public.pay_workbench_session_recompute_progress_counters(
      p_session_id => p_session_id,
      p_apply => true,
      p_reason => 'DELTA_REFRESH_COMPLETE_AUTHORITATIVE_RECOMPUTE',
      p_write_progress_json => true
    );

    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
    SET status = 'COMPLETED',
        phase = 'FINALISE',
        cursor_json = jsonb_build_object('phase', 'FINALISE', 'cursor', '{}'::jsonb),
        fallback_required = false,
        fallback_reason = NULL::text,
        candidate_state_updated = true,
        shadow_compare_required = COALESCE(v_shadow_compare_required, false),
        shadow_compare_enforced = COALESCE(v_shadow_compare_enforced, false),
        shadow_compare_status = COALESCE(NULLIF(v_shadow_compare_status, ''), 'NOT_REQUIRED'),
        legacy_compare_status = CASE
          WHEN COALESCE(v_shadow_compare_required, false) OR COALESCE(v_shadow_compare_enforced, false)
            THEN projection_run_update.legacy_compare_status
          ELSE 'NOT_REQUIRED'
        END,
        diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
          || jsonb_build_object(
            'finalise_candidate_state_updated', true,
            'finalise_shadow_compare_status', COALESCE(NULLIF(v_shadow_compare_status, ''), 'NOT_REQUIRED'),
            'finalise_policy_x_invalid_count', COALESCE(v_policy_x_invalid_count, 0),
            'finalise_economic_key_invalid_count', COALESCE(v_economic_key_invalid_count, 0),
            'finalise_projection_cert_invalid_count', COALESCE(v_projection_cert_invalid_count, 0),
            'finalise_key_parity_invalid_count', COALESCE(v_key_parity_invalid_count, 0),
            'finalise_completed_at_utc', v_now::text
          ),
        updated_at_utc = v_now,
        completed_at_utc = v_now
    WHERE projection_run_update.id = v_projection_run_id;

    v_elapsed_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::integer;
    v_return_json := jsonb_build_object(
      'ok', true,
      'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'projection_run_id', v_projection_run_id::text,
      'candidate_id', p_candidate_id::text,
      'session_id', p_session_id::text,
      'fallback_required', false,
      'fallback_reason', NULL,
      'more_due', false,
      'has_more', false,
      'made_progress', true,
      'delta_refresh_complete', true,
      'candidate_state_updated', true,
      'shadow_compare_required', COALESCE(v_shadow_compare_required, false),
      'shadow_compare_enforced', COALESCE(v_shadow_compare_enforced, false),
      'shadow_compare_status', COALESCE(NULLIF(v_shadow_compare_status, ''), 'NOT_REQUIRED'),
      'source_rows_written', COALESCE(v_written_source_count, 0),
      'line_rows_written', COALESCE(v_written_line_work_count, 0),
      'preview_rows_written', COALESCE(v_written_preview_count, 0),
      'rows_superseded', COALESCE(v_rows_superseded, 0),
      'selected_preserved_count', COALESCE(v_selected_preserved_count, 0),
      'selected_cleared_count', COALESCE(v_selected_cleared_count, 0),
      'elapsed_ms', v_elapsed_ms,
      'stop_reason', 'DELTA_REFRESH_COMPLETE'
    );

    RETURN v_return_json;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
    'projection_run_id', v_projection_run_id::text,
    'fallback_required', true,
    'fallback_reason', 'DELTA_UNKNOWN_PHASE_STATE',
    'more_due', false,
    'has_more', false,
    'made_progress', true,
    'delta_refresh_complete', false,
    'stop_reason', 'DELTA_FALLBACK_REQUIRED'
  );
END;
$function$;

-- pay_workbench_candidate_dirty_apply_job_process(uuid,integer)
CREATE OR REPLACE FUNCTION public.pay_workbench_candidate_dirty_apply_job_process(p_job_id uuid, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_started_at timestamptz := clock_timestamp();
  v_now timestamptz := clock_timestamp();
  v_job public.banking_pay_workbench_jobs%ROWTYPE;
  v_payload jsonb := '{}'::jsonb;
  v_candidate_id uuid;
  v_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_linked_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_finance_case_ids uuid[] := ARRAY[]::uuid[];
  v_dependency_closure_json jsonb := '{}'::jsonb;
  v_dependency_closure_requires_full boolean := false;
  v_dependency_closure_reason text := NULL::text;
  v_family_scope_json jsonb := '{}'::jsonb;
  v_family_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_canonical_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_canonical_linked_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_all_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_reason text := 'DIRTY_TRIGGER:CANDIDATE';
  v_payload_seq bigint := 0;
  v_live_seq bigint := 0;
  v_processed_source_change_seq bigint := 0;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope_updated integer := 0;
  v_scope_count integer := 0;
  v_source_dirty_count integer := 0;
  v_source_dirty_total integer := 0;
  v_line_work_count integer := 0;
  v_line_work_total integer := 0;
  v_preview_count integer := 0;
  v_preview_total integer := 0;
  v_session_count integer := 0;
  v_jobs_queued integer := 0;
  v_refresh_result jsonb := '{}'::jsonb;
  v_refresh_payload_json jsonb := '{}'::jsonb;
  v_jobs_coalesced_active integer := 0;
  v_jobs_coalesced_complete integer := 0;
  v_jobs_requeued_for_conflict integer := 0;
  v_preflight_result jsonb := '{}'::jsonb;
  v_preflight_action text := 'PROCEED';
  v_preflight_match_count integer := 0;
  v_dirty_marking_skipped boolean := false;
  v_is_authorise_delta_targeted boolean := false;
  v_lifecycle_context text := NULL::text;
  v_candidate_serial_state jsonb := '{}'::jsonb;
  v_candidate_serial_blocked boolean := false;
  v_scope_ensure_result jsonb := '{}'::jsonb;
  v_new_scope_baseline_required boolean := false;
  v_session_scan_cutoff_created_at timestamptz;
  v_session_scan_cutoff_id uuid;
  v_session_scan_last_created_at timestamptz;
  v_session_scan_last_id uuid;
  v_session_scan_has_more boolean := false;
  v_session_scan_started_at timestamptz;
  v_session_scan_sessions_examined bigint := 0;
  v_session_page_ids uuid[] := ARRAY[]::uuid[];
  v_candidate_lock_acquired boolean := false;
  v_private_cursor jsonb := '{}'::jsonb;
  v_cursor_sequence bigint := NULL::bigint;
  v_reuse_selection jsonb := '{}'::jsonb;
  v_reuse_job_id uuid := NULL::uuid;
  v_reuse_source_session_id uuid := NULL::uuid;
  v_reuse_dedupe_key text := NULL::text;
  v_request_owned_dirty_request_id uuid := NULL::uuid;
  v_request_owned_dirty_operation_id uuid := NULL::uuid;
  v_request_owned_dirty_operation_phase text := NULL::text;
  v_request_owned_dirty_context jsonb := '{}'::jsonb;
  v_request_owned_dirty_context_digest text := NULL::text;
  v_request_owned_dirty_deferral_enabled boolean := false;
  v_request_owned_dirty_delay interval := interval '5 seconds';
BEGIN
  SELECT job_row.*
  INTO v_job
  FROM public.banking_pay_workbench_jobs AS job_row
  WHERE job_row.id = p_job_id
  FOR UPDATE;

  IF v_job.id IS NULL THEN
    RAISE EXCEPTION 'Banking Pay candidate dirty apply job not found: %', p_job_id
      USING ERRCODE = 'P0002';
  END IF;
  IF UPPER(BTRIM(COALESCE(v_job.job_type, ''))) <> 'WORKBENCH_CANDIDATE_DIRTY_APPLY' THEN
    RAISE EXCEPTION 'Job % is %, not WORKBENCH_CANDIDATE_DIRTY_APPLY', p_job_id, v_job.job_type
      USING ERRCODE = '22023';
  END IF;
  IF UPPER(BTRIM(COALESCE(v_job.status, ''))) <> 'RUNNING' THEN
    RAISE EXCEPTION 'Job % must be RUNNING before processing; status=%', p_job_id, v_job.status
      USING ERRCODE = '55000';
  END IF;

  v_payload := COALESCE(v_job.payload_json, '{}'::jsonb);
  v_candidate_id := COALESCE(
    v_job.candidate_id,
    CASE WHEN COALESCE(v_payload->>'candidate_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN (v_payload->>'candidate_id')::uuid END
  );
  IF v_candidate_id IS NULL THEN
    RAISE EXCEPTION 'Candidate dirty apply job % has no candidate_id', p_job_id
      USING ERRCODE = '22023';
  END IF;

  v_candidate_lock_acquired := pg_catalog.pg_try_advisory_xact_lock(
    pg_catalog.hashtextextended(
      public._pay_workbench_candidate_serial_key(v_candidate_id),
      24062027
    )
  );

  IF v_candidate_lock_acquired THEN
    v_candidate_serial_state := public._pay_workbench_candidate_serial_active_state(
      p_job_id,
      v_candidate_id,
      v_job.job_type,
      v_payload,
      v_now
    );
  END IF;
  v_candidate_serial_blocked := NOT v_candidate_lock_acquired;

  IF v_candidate_serial_blocked IS TRUE THEN
    UPDATE public.banking_pay_workbench_jobs AS delayed_job
    SET status = 'QUEUED',
        attempt_count = GREATEST(COALESCE(delayed_job.attempt_count, 0) - 1, 0),
        run_at_utc = GREATEST(COALESCE(delayed_job.run_at_utc, v_now), v_now + interval '5 seconds'),
        started_at_utc = NULL,
        updated_at_utc = v_now,
        payload_json = public._pay_workbench_dirty_payload_merge(
          COALESCE(delayed_job.payload_json, '{}'::jsonb),
          jsonb_strip_nulls(jsonb_build_object(
            'candidate_serial_key', public._pay_workbench_candidate_serial_key(v_candidate_id),
            'candidate_serial_candidate_id', v_candidate_id::text,
            'candidate_serial_blocked_by_job_id', v_candidate_serial_state->>'blocked_job_id',
            'candidate_serial_blocked_by_chain_job_id', v_candidate_serial_state->>'blocked_chain_job_id',
            'candidate_serial_blocked_by_projection_run_id', v_candidate_serial_state->>'projection_run_id',
            'candidate_serial_wait_reason', COALESCE(v_candidate_serial_state->>'reason', CASE WHEN NOT v_candidate_lock_acquired THEN 'CANDIDATE_SERIAL_LOCK_BUSY' ELSE 'CANDIDATE_SERIAL_DIRTY_APPLY_DELAYED' END),
            'candidate_serial_delayed_at_utc', v_now::text,
            'dirty_apply_row_marking_applied', false,
            'dirty_marking_skipped', true,
            'session_progress_dirtying_skipped', true,
            'classifier_work_skipped_by_candidate_serial', true,
            'source_build_enqueue_skipped_by_candidate_serial', true,
            'line_work_enqueue_skipped_by_candidate_serial', true,
            'preview_materialise_enqueue_skipped_by_candidate_serial', true,
            'rerun_required', true,
            'has_more', true,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
          ))
        )
    WHERE delayed_job.id = p_job_id;

    PERFORM public._pay_workbench_candidate_serial_audit(
      'CANDIDATE_SERIAL_DIRTY_APPLY_DELAYED',
      p_job_id,
      v_candidate_id,
      COALESCE(v_candidate_serial_state, '{}'::jsonb) || jsonb_build_object(
        'job_type', v_job.job_type,
        'dirty_apply_row_marking_applied', false,
        'dirty_marking_skipped', true,
        'delayed_until_utc', (v_now + interval '5 seconds')::text
      ),
      'CANDIDATE_SERIAL_DIRTY_APPLY_DELAYED',
      NULL::uuid
    );

    RETURN jsonb_build_object(
      'ok', true,
      'job_id', p_job_id::text,
      'candidate_id', v_candidate_id::text,
      'candidate_serial_delayed', true,
      'has_more', true,
      'rerun_required', true,
      'next_cursor_json', COALESCE(v_job.private_cursor_json, '{}'::jsonb),
      'reason', COALESCE(v_candidate_serial_state->>'reason', CASE WHEN NOT v_candidate_lock_acquired THEN 'CANDIDATE_SERIAL_LOCK_BUSY' ELSE 'CANDIDATE_SERIAL_DIRTY_APPLY_DELAYED' END),
      'dirty_apply_row_marking_applied', false,
      'dirty_marking_skipped', true,
      'session_progress_dirtying_skipped', true,
      'classifier_work_skipped_by_candidate_serial', true,
      'source_build_enqueue_skipped_by_candidate_serial', true,
      'line_work_enqueue_skipped_by_candidate_serial', true,
      'preview_materialise_enqueue_skipped_by_candidate_serial', true,
      'elapsed_ms', EXTRACT(MILLISECONDS FROM clock_timestamp() - v_started_at)
    );
  END IF;

  SELECT COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid), ARRAY[]::uuid[])
  INTO v_targeted_timesheet_ids
  FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_payload->'targeted_timesheet_ids') = 'array' THEN v_payload->'targeted_timesheet_ids' ELSE '[]'::jsonb END) AS raw_value(value_text)
  WHERE raw_value.value_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

  SELECT COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid), ARRAY[]::uuid[])
  INTO v_linked_timesheet_ids
  FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_payload->'linked_timesheet_ids') = 'array' THEN v_payload->'linked_timesheet_ids' ELSE '[]'::jsonb END) AS raw_value(value_text)
  WHERE raw_value.value_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

  SELECT COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid), ARRAY[]::uuid[])
  INTO v_finance_case_ids
  FROM jsonb_array_elements_text(
    CASE
      WHEN jsonb_typeof(v_payload->'finance_case_ids') = 'array'
        THEN v_payload->'finance_case_ids'
      ELSE '[]'::jsonb
    END
  ) AS raw_value(value_text)
  WHERE raw_value.value_text
    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

  IF COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0
     OR COALESCE(array_length(v_linked_timesheet_ids, 1), 0) > 0
     OR COALESCE(array_length(v_finance_case_ids, 1), 0) > 0 THEN
    IF to_regprocedure(
         'public._pay_workbench_refresh_dependency_closure_v1(uuid,uuid[],uuid[],uuid[],integer,integer)'
       ) IS NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_REFRESH_DEPENDENCY_CLOSURE_UNAVAILABLE'
        USING ERRCODE = 'P0001';
    END IF;

    EXECUTE
      'SELECT public._pay_workbench_refresh_dependency_closure_v1($1,$2,$3,$4,$5,$6)'
    INTO v_dependency_closure_json
    USING
      v_candidate_id,
      v_targeted_timesheet_ids,
      v_linked_timesheet_ids,
      v_finance_case_ids,
      250,
      100;

    v_dependency_closure_requires_full :=
      LOWER(BTRIM(COALESCE(
        v_dependency_closure_json->>'requires_full_candidate',
        'true'
      ))) IN ('true', 't', '1', 'yes', 'y', 'on')
      OR LOWER(BTRIM(COALESCE(
        v_dependency_closure_json->>'coverage_complete',
        'false'
      ))) NOT IN ('true', 't', '1', 'yes', 'y', 'on');
    v_dependency_closure_reason := NULLIF(BTRIM(COALESCE(
      v_dependency_closure_json->>'fallback_reason',
      ''
    )), '');

    IF v_dependency_closure_requires_full THEN
      v_targeted_timesheet_ids := ARRAY[]::uuid[];
      v_linked_timesheet_ids := ARRAY[]::uuid[];
      v_finance_case_ids := ARRAY[]::uuid[];
      v_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
    ELSE
      SELECT COALESCE(array_agg(DISTINCT value::uuid ORDER BY value::uuid), ARRAY[]::uuid[])
      INTO v_targeted_timesheet_ids
      FROM jsonb_array_elements_text(
        COALESCE(v_dependency_closure_json->'effective_targeted_timesheet_ids', '[]'::jsonb)
      ) AS effective_timesheet(value)
      WHERE value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

      v_linked_timesheet_ids := ARRAY[]::uuid[];

      SELECT COALESCE(array_agg(DISTINCT value::uuid ORDER BY value::uuid), ARRAY[]::uuid[])
      INTO v_finance_case_ids
      FROM jsonb_array_elements_text(
        COALESCE(v_dependency_closure_json->'effective_finance_case_ids', '[]'::jsonb)
      ) AS effective_finance_case(value)
      WHERE value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
    END IF;
  END IF;

  IF COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0
     OR COALESCE(array_length(v_finance_case_ids, 1), 0) > 0 THEN
    v_family_scope_json := public._pay_workbench_normalise_timesheet_rotation_scope_payload(v_targeted_timesheet_ids, v_linked_timesheet_ids);

    SELECT COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid), ARRAY[]::uuid[])
    INTO v_family_timesheet_ids
    FROM jsonb_array_elements_text(COALESCE(v_family_scope_json->'family_timesheet_ids', '[]'::jsonb)) AS raw_value(value_text)
    WHERE raw_value.value_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

    SELECT COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid), ARRAY[]::uuid[])
    INTO v_canonical_targeted_timesheet_ids
    FROM jsonb_array_elements_text(COALESCE(v_family_scope_json->'targeted_timesheet_ids', '[]'::jsonb)) AS raw_value(value_text)
    WHERE raw_value.value_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

    SELECT COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid), ARRAY[]::uuid[])
    INTO v_canonical_linked_timesheet_ids
    FROM jsonb_array_elements_text(COALESCE(v_family_scope_json->'linked_timesheet_ids', '[]'::jsonb)) AS raw_value(value_text)
    WHERE raw_value.value_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

    SELECT COALESCE(array_agg(DISTINCT all_ids.timesheet_id ORDER BY all_ids.timesheet_id), ARRAY[]::uuid[])
    INTO v_all_timesheet_ids
    FROM (
      SELECT unnest(v_targeted_timesheet_ids) AS timesheet_id
      UNION ALL
      SELECT unnest(v_linked_timesheet_ids) AS timesheet_id
      UNION ALL
      SELECT unnest(v_family_timesheet_ids) AS timesheet_id
    ) AS all_ids
    WHERE all_ids.timesheet_id IS NOT NULL;
    v_refresh_scope_kind := 'TARGETED_TIMESHEETS';
  ELSE
    v_linked_timesheet_ids := ARRAY[]::uuid[];
    v_family_timesheet_ids := ARRAY[]::uuid[];
    v_canonical_targeted_timesheet_ids := ARRAY[]::uuid[];
    v_canonical_linked_timesheet_ids := ARRAY[]::uuid[];
    v_all_timesheet_ids := ARRAY[]::uuid[];
    v_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
  END IF;

  v_reason := COALESCE(NULLIF(BTRIM(COALESCE(v_payload->>'reason_latest', v_payload->>'reason', '')), ''), 'DIRTY_TRIGGER:CANDIDATE');
  v_payload_seq := GREATEST(
    COALESCE(CASE WHEN COALESCE(v_payload->>'latest_source_change_seq', '') ~ '^\d+$' THEN (v_payload->>'latest_source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(v_payload->>'source_change_seq', '') ~ '^\d+$' THEN (v_payload->>'source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(v_payload->>'source_change_sequence', '') ~ '^\d+$' THEN (v_payload->>'source_change_sequence')::bigint END, 0)
  );

  SELECT COALESCE(change_counter.seq, 0)
  INTO v_live_seq
  FROM public.app_change_counters AS change_counter
  WHERE change_counter.entity_key = 'pay_candidate:' || v_candidate_id::text;

  v_processed_source_change_seq := GREATEST(COALESCE(v_payload_seq, 0), COALESCE(v_live_seq, 0));

  -- A correction request transition is orchestration evidence, not economic
  -- truth.  Validate the transaction-stamped causal envelope before consulting
  -- the durable correction lifecycle.  The latest scope token must be the
  -- request-owned token; any later unrelated invalidation changes that token
  -- and immediately falls through to the ordinary classifier.
  SELECT COALESCE(
    (pg_catalog.to_jsonb(settings_row)
      ->>'banking_pay_correction_request_dirty_deferral_v1_enabled')::boolean,
    false
  )
  INTO v_request_owned_dirty_deferral_enabled
  FROM public.settings_defaults AS settings_row
  ORDER BY settings_row.id
  LIMIT 1;

  v_request_owned_dirty_context:=CASE
    WHEN pg_catalog.jsonb_typeof(v_payload->'correction_dirty_contexts')='object'
      AND pg_catalog.jsonb_typeof(
        v_payload->'correction_dirty_contexts'->v_candidate_id::text
      )='object'
      THEN v_payload->'correction_dirty_contexts'->v_candidate_id::text
    ELSE '{}'::jsonb
  END;

  IF COALESCE(v_request_owned_dirty_deferral_enabled,false)
     AND COALESCE(v_request_owned_dirty_context->>'contract_version','')
           ='CORRECTION_OWNED_DIRTY_CAUSAL_V1'
     AND COALESCE(v_request_owned_dirty_context->>'candidate_id','')=v_candidate_id::text
     AND COALESCE(v_request_owned_dirty_context->>'correction_request_id','')
           ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     AND COALESCE(v_request_owned_dirty_context->>'pay_batch_id','')
           ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     AND COALESCE(v_request_owned_dirty_context->>'lifecycle_phase','') IN (
       'REQUEST_PREPARE','REQUEST_START','FINANCIAL_PAGE_START',
       'FINANCIAL_PAGE_APPLIED','FINANCIAL_TERMINAL'
     )
     AND COALESCE(v_request_owned_dirty_context->>'policy_x_boundary','') IN (
       'POST_DRAFT_FROZEN_EVIDENCE','PRE_DRAFT_LIVE_TRUTH'
     )
     AND COALESCE(v_request_owned_dirty_context->>'pre_request_source_change_seq','')
           ~ '^[0-9]{1,18}$'
     AND COALESCE(v_request_owned_dirty_context->>'pre_request_dirty_generation','')
           ~ '^[0-9]{1,18}$'
     AND COALESCE(v_payload->>'request_owned_scope_change_tx_token','')
           ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     AND COALESCE(v_payload->>'scope_change_tx_token','')
           =COALESCE(v_payload->>'request_owned_scope_change_tx_token','')
     AND (
       v_job.scope_change_tx_token IS NULL
       OR v_job.scope_change_tx_token::text
            =COALESCE(v_payload->>'request_owned_scope_change_tx_token','')
     )
     AND LOWER(BTRIM(COALESCE(v_payload->>'policy_x_dirtying_only','false')))
           IN ('true','t','1','yes','y','on')
     AND LOWER(BTRIM(COALESCE(v_payload->>'economic_truth_mutation_allowed','false')))
           NOT IN ('true','t','1','yes','y','on') THEN
    v_request_owned_dirty_context_digest:=pg_catalog.encode(extensions.digest(
      pg_catalog.convert_to(
        'CORRECTION_OWNED_DIRTY_CAUSAL_V1'||'|'||
        COALESCE(v_request_owned_dirty_context->>'correction_request_id','')||'|'||
        COALESCE(v_request_owned_dirty_context->>'correction_operation_id','')||'|'||
        COALESCE(v_request_owned_dirty_context->>'correction_work_item_id','')||'|'||
        COALESCE(v_request_owned_dirty_context->>'pay_batch_id','')||'|'||
        v_candidate_id::text||'|'||
        COALESCE(v_request_owned_dirty_context->>'lifecycle_phase','')||'|'||
        COALESCE(v_request_owned_dirty_context->>'policy_x_boundary','')||'|'||
        COALESCE(v_request_owned_dirty_context->>'pre_request_source_change_seq','')||'|'||
        COALESCE(v_request_owned_dirty_context->>'pre_request_dirty_generation','')||'|'||
        COALESCE(v_request_owned_dirty_context->>'pre_request_fence_digest',''),
        'UTF8'
      ),
      'sha256'
    ),'hex');

    IF v_request_owned_dirty_context_digest
         =COALESCE(v_request_owned_dirty_context->>'context_digest','') THEN
      SELECT request_row.id,correction_operation.id,correction_operation.phase,
             CASE
               WHEN correction_operation.status='WAITING_AUTHORISATION'
                 OR correction_operation.phase='AWAITING_REAUTHENTICATION'
                 OR request_row.status IN ('PLANNING','PLANNED','REQUESTED','AWAITING_AUTHORISATION')
                 THEN interval '30 seconds'
               ELSE interval '5 seconds'
             END
      INTO v_request_owned_dirty_request_id,
           v_request_owned_dirty_operation_id,
           v_request_owned_dirty_operation_phase,
           v_request_owned_dirty_delay
      FROM public.pay_payment_correction_requests AS request_row
      JOIN public.banking_pay_operations AS correction_operation
        ON correction_operation.operation_type='PAYMENT_CORRECTION'
       AND correction_operation.input_json->>'correction_request_id'=request_row.id::text
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.pay_batch_id=request_row.pay_batch_id
       AND batch_candidate.candidate_id=v_candidate_id
      WHERE request_row.id=(v_request_owned_dirty_context->>'correction_request_id')::uuid
        AND request_row.pay_batch_id=(v_request_owned_dirty_context->>'pay_batch_id')::uuid
        AND correction_operation.status IN ('QUEUED','RUNNING','WAITING_AUTHORISATION')
        AND correction_operation.phase<>'COMPLETE'
        AND request_row.status NOT IN ('CANCELLED','FAILED','REJECTED')
        -- Candidate dirty jobs are deliberately deduplicated and may be reused.
        -- Their immutable created_at can therefore predate the correction even
        -- when the exact request-owned event was merged later.  The causal
        -- digest and transaction token above prove ownership; updated_at proves
        -- that this durable job received the request event after it existed.
        AND request_row.created_at_utc<=GREATEST(
          v_job.created_at_utc,
          COALESCE(v_job.updated_at_utc,v_job.created_at_utc)
        )
        AND (
          COALESCE(v_request_owned_dirty_context->>'correction_operation_id','')=''
          OR correction_operation.id::text
               =v_request_owned_dirty_context->>'correction_operation_id'
        )
      ORDER BY correction_operation.created_at_utc DESC
      LIMIT 1;
    END IF;
  ELSE
    -- Compatibility fallback while the new setting is disabled.  This is the
    -- prior retrospective proof and is deliberately retained for rollback.
    IF LOWER(BTRIM(COALESCE(v_payload->>'trigger_table','')))
          ='pay_payment_correction_requests'
       AND LOWER(BTRIM(COALESCE(v_payload->>'policy_x_dirtying_only','false')))
             IN ('true','t','1','yes','y','on')
       AND LOWER(BTRIM(COALESCE(v_payload->>'economic_truth_mutation_allowed','false')))
             NOT IN ('true','t','1','yes','y','on')
       AND (
         (
           jsonb_typeof(v_payload->'reasons')='array'
           AND jsonb_array_length(v_payload->'reasons')>0
           AND NOT EXISTS (
             SELECT 1
             FROM jsonb_array_elements_text(v_payload->'reasons') AS dirty_reason(reason_text)
             WHERE UPPER(BTRIM(dirty_reason.reason_text)) NOT IN (
               'DIRTY_TRIGGER:PAY_PAYMENT_CORRECTION_REQUESTS:INSERT',
               'DIRTY_TRIGGER:PAY_PAYMENT_CORRECTION_REQUESTS:UPDATE'
             )
           )
         )
         OR (
           jsonb_typeof(v_payload->'reasons') IS DISTINCT FROM 'array'
           AND UPPER(BTRIM(COALESCE(v_payload->>'reason_latest',v_payload->>'reason',''))) IN (
             'DIRTY_TRIGGER:PAY_PAYMENT_CORRECTION_REQUESTS:INSERT',
             'DIRTY_TRIGGER:PAY_PAYMENT_CORRECTION_REQUESTS:UPDATE'
           )
         )
       ) THEN
      SELECT request_row.id,correction_operation.id,correction_operation.phase
      INTO v_request_owned_dirty_request_id,
           v_request_owned_dirty_operation_id,
           v_request_owned_dirty_operation_phase
      FROM public.banking_pay_operations AS correction_operation
      JOIN public.pay_payment_correction_requests AS request_row
        ON request_row.id=CASE
          WHEN COALESCE(correction_operation.input_json->>'correction_request_id','')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (correction_operation.input_json->>'correction_request_id')::uuid
          ELSE NULL::uuid END
      JOIN public.pay_payment_correction_request_candidates AS request_candidate
        ON request_candidate.correction_request_id=request_row.id
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.id=request_candidate.pay_batch_candidate_id
       AND batch_candidate.candidate_id=v_candidate_id
      WHERE correction_operation.operation_type='PAYMENT_CORRECTION'
        AND correction_operation.status IN ('QUEUED','RUNNING')
        AND correction_operation.phase NOT IN ('REFRESH_WORKBENCH','COMPLETE')
        AND correction_operation.input_json->'draft_overlay_fast_start_authorities'
              ->v_candidate_id::text->>'request_owned_dirty_job_id'=p_job_id::text
        AND request_row.status IN (
          'REQUESTED','AWAITING_AUTHORISATION','AUTHORISED','EXPANDED','PROCESSING'
        )
        AND request_row.created_at_utc<=GREATEST(
          v_job.created_at_utc,
          COALESCE(v_job.updated_at_utc,v_job.created_at_utc)
        )
      ORDER BY request_row.created_at_utc DESC,correction_operation.created_at_utc DESC
      LIMIT 1;
    END IF;
  END IF;

  IF v_request_owned_dirty_request_id IS NOT NULL THEN
    UPDATE public.banking_pay_workbench_jobs AS delayed_job
    SET status = 'QUEUED',
        attempt_count = GREATEST(COALESCE(delayed_job.attempt_count, 0) - 1, 0),
        run_at_utc = GREATEST(COALESCE(delayed_job.run_at_utc, v_now), v_now + v_request_owned_dirty_delay),
        started_at_utc = NULL,
        updated_at_utc = v_now,
        payload_json = public._pay_workbench_dirty_payload_merge(
          COALESCE(delayed_job.payload_json, '{}'::jsonb),
          jsonb_build_object(
            'request_owned_dirty_classification', 'REQUEST_OWNED_POLICY_X_DIRTY',
            'waiting_for_correction_financial_boundary',
              COALESCE(v_request_owned_dirty_operation_phase,'')<>'REFRESH_WORKBENCH',
            'waiting_for_correction_route_election',
              COALESCE(v_request_owned_dirty_operation_phase,'')='REFRESH_WORKBENCH'
              OR COALESCE(v_request_owned_dirty_context->>'lifecycle_phase','') IN (
                'FINANCIAL_PAGE_APPLIED','FINANCIAL_TERMINAL'
              ),
            'correction_request_id', v_request_owned_dirty_request_id::text,
            'correction_operation_id', v_request_owned_dirty_operation_id::text,
            'correction_operation_phase', v_request_owned_dirty_operation_phase,
            'correction_dirty_context_digest', v_request_owned_dirty_context->>'context_digest',
            'request_owned_scope_change_tx_token', v_payload->>'request_owned_scope_change_tx_token',
            'request_boundary_delayed_at_utc', v_now::text,
            'dirty_apply_row_marking_applied', false,
            'dirty_marking_skipped', true,
            'session_progress_dirtying_skipped', true,
            'classifier_work_skipped_by_request_boundary', true,
            'source_build_enqueue_skipped_by_request_boundary', true,
            'rerun_required', true,
            'has_more', true,
            'policy_x_authority_scope', 'POST_DRAFT_FROZEN_BATCH_EVIDENCE'
          )
        )
    WHERE delayed_job.id = p_job_id;

    RETURN jsonb_build_object(
      'ok', true,
      'job_id', p_job_id::text,
      'candidate_id', v_candidate_id::text,
      'candidate_serial_delayed', true,
      'request_boundary_delayed', true,
      'has_more', true,
      'rerun_required', true,
      'reason', CASE
        WHEN COALESCE(v_request_owned_dirty_operation_phase,'')='REFRESH_WORKBENCH'
          OR COALESCE(v_request_owned_dirty_context->>'lifecycle_phase','') IN (
            'FINANCIAL_PAGE_APPLIED','FINANCIAL_TERMINAL'
          )
          THEN 'WAITING_FOR_CORRECTION_ROUTE_ELECTION'
        ELSE 'REQUEST_OWNED_POLICY_X_DIRTY_WAITING_FOR_FINANCIAL_BOUNDARY'
      END,
      'correction_request_id', v_request_owned_dirty_request_id::text,
      'correction_operation_id', v_request_owned_dirty_operation_id::text,
      'correction_operation_phase', v_request_owned_dirty_operation_phase,
      'correction_dirty_context_digest', v_request_owned_dirty_context->>'context_digest',
      'request_owned_scope_change_tx_token', v_payload->>'request_owned_scope_change_tx_token',
      'dirty_apply_row_marking_applied', false,
      'dirty_marking_skipped', true,
      'session_progress_dirtying_skipped', true,
      'classifier_work_skipped_by_request_boundary', true,
      'source_build_enqueue_skipped_by_request_boundary', true,
      'elapsed_ms', EXTRACT(MILLISECONDS FROM clock_timestamp() - v_started_at)
    );
  END IF;

  IF v_job.private_cursor_kind IS NOT NULL
     AND v_job.private_cursor_kind <> 'DIRTY_SESSION_SCAN_V1' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_SESSION_CURSOR_KIND_INVALID'
      USING ERRCODE='P0001';
  END IF;

  v_private_cursor := COALESCE(v_job.private_cursor_json, '{}'::jsonb);
  BEGIN
    v_cursor_sequence := CASE
      WHEN COALESCE(v_private_cursor->>'scan_source_change_seq','') ~ '^\d+$'
        THEN (v_private_cursor->>'scan_source_change_seq')::bigint
      ELSE NULL::bigint
    END;
    v_session_scan_cutoff_created_at := NULLIF(BTRIM(COALESCE(v_private_cursor->>'upper_created_at_utc','')),'')::timestamptz;
    v_session_scan_cutoff_id := NULLIF(BTRIM(COALESCE(v_private_cursor->>'upper_session_id','')),'')::uuid;
    v_session_scan_last_created_at := NULLIF(BTRIM(COALESCE(v_private_cursor->>'last_created_at_utc','')),'')::timestamptz;
    v_session_scan_last_id := NULLIF(BTRIM(COALESCE(v_private_cursor->>'last_session_id','')),'')::uuid;
    v_session_scan_started_at := COALESCE(
      NULLIF(BTRIM(COALESCE(v_private_cursor->>'scan_started_at_utc','')),'')::timestamptz,
      v_now
    );
    v_session_scan_sessions_examined := COALESCE(
      CASE WHEN COALESCE(v_private_cursor->>'sessions_examined','') ~ '^\d+$'
        THEN (v_private_cursor->>'sessions_examined')::bigint END,
      0
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_SESSION_CURSOR_INVALID' USING ERRCODE='P0001';
  END;

  IF v_job.private_cursor_kind IS NULL
     OR v_job.private_stage_version IS DISTINCT FROM 1
     OR v_cursor_sequence IS DISTINCT FROM v_processed_source_change_seq THEN
    SELECT session_candidate.created_at_utc, session_candidate.id
    INTO v_session_scan_cutoff_created_at, v_session_scan_cutoff_id
    FROM public.banking_pay_workbench_sessions AS session_candidate
    WHERE session_candidate.status='OPEN'
      AND session_candidate.discarded_at_utc IS NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_sessions AS newer_session
        WHERE newer_session.actor_user_id=session_candidate.actor_user_id
          AND newer_session.status='OPEN' AND newer_session.discarded_at_utc IS NULL
          AND (newer_session.pay_date,newer_session.created_at_utc,newer_session.id)>
              (session_candidate.pay_date,session_candidate.created_at_utc,session_candidate.id)
      )
    ORDER BY session_candidate.created_at_utc DESC,session_candidate.id DESC
    LIMIT 1;

    v_session_scan_last_created_at := NULL::timestamptz;
    v_session_scan_last_id := NULL::uuid;
    v_session_scan_started_at := v_now;
    v_session_scan_sessions_examined := 0;

    UPDATE public.banking_pay_workbench_jobs AS cursor_job
    SET private_cursor_kind='DIRTY_SESSION_SCAN_V1',
        private_stage_version=1,
        private_cursor_json=jsonb_strip_nulls(jsonb_build_object(
          'scan_source_change_seq',v_processed_source_change_seq,
          'upper_created_at_utc',v_session_scan_cutoff_created_at,
          'upper_session_id',v_session_scan_cutoff_id,
          'last_created_at_utc',NULL,
          'last_session_id',NULL,
          'scan_started_at_utc',v_session_scan_started_at,
          'sessions_examined',0
        )),
        updated_at_utc=v_now
    WHERE cursor_job.id=p_job_id;
  END IF;
  v_lifecycle_context := LOWER(BTRIM(COALESCE(v_payload->>'lifecycle_mutation_context', v_payload->>'mutation_context', v_payload->>'lifecycle_context', '')));
  v_is_authorise_delta_targeted := v_refresh_scope_kind = 'TARGETED_TIMESHEETS'
    AND COALESCE(array_length(v_canonical_targeted_timesheet_ids, 1), 0) > 0
    AND COALESCE(array_length(v_finance_case_ids, 1), 0) = 0
    AND lower(BTRIM(COALESCE(v_payload->>'ordinary_timesheet_edit_save_no_dirty', 'false'))) NOT IN ('true','t','1','yes','y','on')
    AND (
      lower(BTRIM(COALESCE(v_payload->>'authorise_boundary_changed', v_payload->>'timesheet_authorise_boundary_changed', 'false'))) IN ('true','t','1','yes','y','on')
      OR lower(BTRIM(COALESCE(v_payload->>'unauthorise_boundary_changed', v_payload->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true','t','1','yes','y','on')
      OR v_lifecycle_context IN ('timesheet_authorise', 'authorise_timesheet', 'timesheet_unauthorise', 'unauthorise_timesheet')
      OR LOWER(COALESCE(v_reason, '')) LIKE '%authorise%'
      OR LOWER(COALESCE(v_reason, '')) LIKE '%unauthorise%'
    );

  PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', p_job_id::text, jsonb_build_object('function_name', 'pay_workbench_candidate_dirty_apply_job_process', 'stage', 'dirty_worker_apply_start', 'job_id', p_job_id::text, 'candidate_id', v_candidate_id::text, 'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0), 'family_timesheet_count', COALESCE(array_length(v_family_timesheet_ids, 1), 0), 'latest_source_change_seq', v_payload_seq, 'processed_source_change_seq', v_processed_source_change_seq));

  SELECT COALESCE(array_agg(page_row.id ORDER BY page_row.created_at_utc,page_row.id),ARRAY[]::uuid[])
  INTO v_session_page_ids
  FROM (
    SELECT session_candidate.id,session_candidate.created_at_utc
    FROM public.banking_pay_workbench_sessions AS session_candidate
    WHERE session_candidate.status='OPEN'
      AND session_candidate.discarded_at_utc IS NULL
      AND v_session_scan_cutoff_created_at IS NOT NULL
      AND (session_candidate.created_at_utc,session_candidate.id)<=
          (v_session_scan_cutoff_created_at,v_session_scan_cutoff_id)
      AND (
        v_session_scan_last_created_at IS NULL
        OR (session_candidate.created_at_utc,session_candidate.id)>
           (v_session_scan_last_created_at,v_session_scan_last_id)
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_sessions AS newer_session
        WHERE newer_session.actor_user_id=session_candidate.actor_user_id
          AND newer_session.status='OPEN' AND newer_session.discarded_at_utc IS NULL
          AND (newer_session.pay_date,newer_session.created_at_utc,newer_session.id)>
              (session_candidate.pay_date,session_candidate.created_at_utc,session_candidate.id)
      )
    ORDER BY session_candidate.created_at_utc,session_candidate.id
    LIMIT GREATEST(1, COALESCE(p_limit, 100))
  ) AS page_row;

  PERFORM session_lock.id
  FROM public.banking_pay_workbench_sessions AS session_lock
  WHERE session_lock.id=ANY(v_session_page_ids)
  ORDER BY session_lock.id
  FOR UPDATE;

  FOR v_session_row IN
    SELECT session_candidate.*
    FROM public.banking_pay_workbench_sessions AS session_candidate
    WHERE session_candidate.id=ANY(v_session_page_ids)
    ORDER BY session_candidate.created_at_utc,session_candidate.id
  LOOP
    v_session_scan_last_created_at:=v_session_row.created_at_utc;
    v_session_scan_last_id:=v_session_row.id;
    v_session_scan_sessions_examined:=v_session_scan_sessions_examined+1;
    IF NOT EXISTS (
      SELECT 1 FROM public.banking_pay_workbench_session_scope AS existing_scope
      WHERE existing_scope.session_id=v_session_row.id
        AND existing_scope.candidate_id=v_candidate_id
    ) THEN
      v_scope_ensure_result:=private.pay_workbench_session_candidate_scope_ensure_v1(
        v_session_row.id,v_candidate_id,p_job_id,v_processed_source_change_seq,v_reason
      );
      IF COALESCE((v_scope_ensure_result->>'eligible')::boolean,false) IS NOT TRUE THEN
        CONTINUE;
      END IF;
      v_new_scope_baseline_required:=COALESCE((v_scope_ensure_result->>'inserted')::boolean,false);
    ELSE
      v_new_scope_baseline_required:=false;
    END IF;
    IF v_new_scope_baseline_required IS TRUE THEN
      v_reuse_selection := private.pay_workbench_candidate_reuse_source_select_v1(
        v_session_row.id,
        v_candidate_id,
        v_processed_source_change_seq,
        jsonb_build_object(
          'source_job_id',p_job_id::text,
          'direct_candidate_id',v_candidate_id::text,
          'target_session_id',v_session_row.id::text
        )
      );

      IF coalesce((v_reuse_selection->>'reuse_available')::boolean,false) IS TRUE
         AND coalesce(v_reuse_selection->>'selected_source_session_id','')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        v_reuse_source_session_id := (v_reuse_selection->>'selected_source_session_id')::uuid;
        v_reuse_dedupe_key := 'workbench:certified-reuse-v2:'
          ||v_session_row.id::text||':'||v_candidate_id::text||':'||v_processed_source_change_seq::text;

        INSERT INTO public.banking_pay_workbench_jobs AS reuse_job(
          id,job_type,status,priority,run_at_utc,attempt_count,max_attempts,
          dedupe_key,snapshot_run_id,session_id,candidate_id,payload_json,
          created_at_utc,updated_at_utc,started_at_utc,completed_at_utc,
          failed_at_utc,last_error_json
        ) VALUES (
          gen_random_uuid(),'WORKBENCH_SESSION_CLONE_REBASE','QUEUED',42,v_now,0,8,
          v_reuse_dedupe_key,v_session_row.source_snapshot_run_id,v_session_row.id,v_candidate_id,
          jsonb_strip_nulls(jsonb_build_object(
            'job_type','WORKBENCH_SESSION_CLONE_REBASE',
            'source_session_id',v_reuse_source_session_id::text,
            'target_session_id',v_session_row.id::text,
            'direct_candidate_id',v_candidate_id::text,
            'source_change_seq',v_processed_source_change_seq,
            'source_job_id',p_job_id::text,
            'source_selection_authorised',true,
            'allow_session_rebase',true,
            'rebase_simple_rows_only',true,
            'clone_mode','CERTIFIED_ONLY',
            'cursor_json','{}'::jsonb,
            'limit',1,
            'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH'
          )),
          v_now,v_now,NULL,NULL,NULL,NULL
        )
        ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED','RUNNING')
        DO UPDATE SET
          run_at_utc=LEAST(reuse_job.run_at_utc,EXCLUDED.run_at_utc),
          payload_json=coalesce(reuse_job.payload_json,'{}'::jsonb)||EXCLUDED.payload_json,
          updated_at_utc=v_now
        RETURNING reuse_job.id INTO v_reuse_job_id;

        UPDATE public.banking_pay_workbench_session_scope AS reuse_scope
        SET status='PENDING',dirty=true,pending_job_id=v_reuse_job_id,
            error_json=NULL::jsonb,
            certified_preview_publication_required=true,
            certified_preview_publication_parity_ok=false,
            certified_preview_publication_session_version=NULL,
            certified_preview_publication_source_change_seq=NULL,
            certified_preview_publication_source_build_run_id=NULL,
            certified_preview_publication_source_publication_id=NULL,
            certified_preview_publication_attestation_json='{}'::jsonb,
            certified_preview_publication_attested_at_utc=NULL,
            updated_at_utc=v_now
        WHERE reuse_scope.session_id=v_session_row.id
          AND reuse_scope.candidate_id=v_candidate_id;

        v_jobs_queued:=v_jobs_queued+1;
        v_session_count:=v_session_count+1;
        v_refresh_result:=jsonb_build_object(
          'ok',true,
          'job_id',v_reuse_job_id::text,
          'job_type','WORKBENCH_SESSION_CLONE_REBASE',
          'scope_status','PENDING',
          'source_build_required',false,
          'certified_reuse_pending',true
        );
        CONTINUE;
      END IF;
    END IF;


    IF v_is_authorise_delta_targeted AND NOT v_new_scope_baseline_required THEN
      SELECT public.pay_workbench_authorise_delta_hotkey_preflight(
        p_session_id => v_session_row.id,
        p_candidate_id => v_candidate_id,
        p_targeted_timesheet_ids => v_canonical_targeted_timesheet_ids,
        p_linked_timesheet_ids => v_canonical_linked_timesheet_ids,
        p_payload_json => public._pay_workbench_merge_targeted_scope_payload(
          v_payload,
          jsonb_build_object(
            'session_id', v_session_row.id::text,
            'source_session_id', v_session_row.id::text,
            'source_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
            'snapshot_run_id', v_session_row.source_snapshot_run_id::text,
            'session_version', COALESCE(v_session_row.version, 0),
            'session_signature', v_session_row.session_signature,
            'refresh_scope_kind', 'TARGETED_TIMESHEETS',
            'projection_mode', 'DELTA',
            'projection_class', 'TIMESHEET_LIFECYCLE',
            'targeted_timesheet_ids', COALESCE(v_family_scope_json->'targeted_timesheet_ids', to_jsonb(v_canonical_targeted_timesheet_ids)),
            'linked_timesheet_ids', COALESCE(v_family_scope_json->'linked_timesheet_ids', to_jsonb(v_canonical_linked_timesheet_ids)),
            'queue_identity_targeted_timesheet_ids', COALESCE(v_family_scope_json->'queue_identity_targeted_timesheet_ids', v_family_scope_json->'family_timesheet_ids', to_jsonb(v_canonical_targeted_timesheet_ids)),
            'queue_identity_linked_timesheet_ids', COALESCE(v_family_scope_json->'queue_identity_linked_timesheet_ids', '[]'::jsonb),
            'requested_timesheet_ids', COALESCE(v_family_scope_json->'requested_timesheet_ids', to_jsonb(v_targeted_timesheet_ids)),
            'targeted_timesheet_ids_requested', COALESCE(v_family_scope_json->'requested_targeted_timesheet_ids', to_jsonb(v_targeted_timesheet_ids)),
            'linked_timesheet_ids_requested', COALESCE(v_family_scope_json->'requested_linked_timesheet_ids', to_jsonb(v_linked_timesheet_ids)),
            'source_change_seq', v_processed_source_change_seq,
            'latest_source_change_seq', v_processed_source_change_seq,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
          )
        ),
        p_reason => v_reason,
        p_actor_user_id => v_session_row.actor_user_id,
        p_source_change_seq => v_processed_source_change_seq
      ) INTO v_preflight_result;

      v_preflight_action := COALESCE(v_preflight_result->>'action', 'PROCEED');

      IF v_preflight_action IN ('REUSED_QUEUED_SAME_FAMILY_JOB', 'UPDATED_WAITING_AFTER_RUNNING_JOB') THEN
        v_preflight_match_count := v_preflight_match_count + 1;
        v_dirty_marking_skipped := true;
        v_jobs_queued := v_jobs_queued + CASE WHEN NULLIF(BTRIM(COALESCE(v_preflight_result->>'job_id', '')), '') IS NOT NULL THEN 1 ELSE 0 END;
        v_session_count := v_session_count + 1;

        UPDATE public.banking_pay_workbench_jobs AS job_update
        SET payload_json = public._pay_workbench_dirty_payload_merge(
              COALESCE(job_update.payload_json, '{}'::jsonb),
              jsonb_build_object(
                'processed_source_change_seq', v_processed_source_change_seq,
                'processed_at_utc', v_now::text,
                'processed_candidate_id', v_candidate_id::text,
                'source_change_seq', v_processed_source_change_seq,
                'source_change_sequence', v_processed_source_change_seq,
                'latest_source_change_seq', v_processed_source_change_seq,
                'rerun_required', false,
                'has_more', false,
                'cursor_json', '{}'::jsonb,
                'next_cursor_json', '{}'::jsonb,
                'dirty_apply_row_marking_applied', false,
                'dirty_marking_skipped', true,
                'session_progress_dirtying_skipped', true,
                'classifier_work_skipped', true,
                'source_rows_marking_skipped', true,
                'line_work_marking_skipped', true,
                'preview_marking_skipped', true,
                'early_preflight_action', v_preflight_action,
                'early_preflight_result', COALESCE(v_preflight_result, '{}'::jsonb),
                'actual_refresh_job_id', NULLIF(BTRIM(COALESCE(v_preflight_result->>'job_id', '')), ''),
                'actual_refresh_job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
                'actual_refresh_scope_status', 'DELTA_REFRESH_PENDING',
                'source_build_required', false,
                'delta_refresh_required', true,
                'line_work_action', 'EARLY_PREFLIGHT_SKIPPED_DIRTY_MARKING',
                'early_preflight_completed_cleanly', true,
                'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
              )
            ),
            updated_at_utc = v_now
        WHERE job_update.id = p_job_id;

        PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', p_job_id::text, jsonb_build_object('function_name', 'pay_workbench_candidate_dirty_apply_job_process', 'stage', 'early_preflight_return_before_dirty_marking', 'job_id', p_job_id::text, 'candidate_id', v_candidate_id::text, 'session_id', v_session_row.id::text, 'action', v_preflight_action, 'normalised_delta_family_key', v_preflight_result->>'normalised_delta_family_key', 'dirty_marking_skipped', true));

        CONTINUE;
      END IF;
    END IF;

    -- Resolve the current economic owner before making public source/preview
    -- rows dirty.  This allows delayed finance/batch/candidate dirty events to
    -- be absorbed by an already-active or already-published full authority.
    v_refresh_payload_json := public._pay_workbench_merge_targeted_scope_payload(
      v_payload,
      jsonb_build_object(
        'session_id', v_session_row.id::text,
        'source_session_id', v_session_row.id::text,
        'source_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
        'snapshot_run_id', v_session_row.source_snapshot_run_id::text,
        'session_version', COALESCE(v_session_row.version, 0),
        'session_signature', v_session_row.session_signature,
        'pay_channel_scope', COALESCE(NULLIF(UPPER(BTRIM(COALESCE(v_session_row.filters_json->>'pay_channel_scope', v_session_row.filters_json#>>'{filters,pay_channel_scope}', ''))), ''), 'ALL'),
        'refresh_scope_kind', v_refresh_scope_kind,
        'targeted_timesheet_ids', COALESCE(to_jsonb(v_canonical_targeted_timesheet_ids), '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(to_jsonb(v_canonical_linked_timesheet_ids), '[]'::jsonb),
        'finance_case_ids', COALESCE(to_jsonb(v_finance_case_ids), '[]'::jsonb),
        'dependency_closure', COALESCE(v_dependency_closure_json, '{}'::jsonb),
        'dependency_closure_fallback_reason', v_dependency_closure_reason,
        'requested_timesheet_ids', COALESCE(v_family_scope_json->'requested_timesheet_ids', COALESCE(to_jsonb(v_targeted_timesheet_ids), '[]'::jsonb)),
        'targeted_timesheet_ids_requested', COALESCE(v_family_scope_json->'requested_targeted_timesheet_ids', COALESCE(to_jsonb(v_targeted_timesheet_ids), '[]'::jsonb)),
        'linked_timesheet_ids_requested', COALESCE(v_family_scope_json->'requested_linked_timesheet_ids', COALESCE(to_jsonb(v_linked_timesheet_ids), '[]'::jsonb)),
        'family_timesheet_ids', COALESCE(v_family_scope_json->'family_timesheet_ids', COALESCE(to_jsonb(v_family_timesheet_ids), '[]'::jsonb)),
        'source_rows_marked_dirty_count', 0,
        'line_work_marked_pending_count', 0,
        'preview_rows_marked_dirty_count', 0,
        'source_change_seq', v_processed_source_change_seq,
        'latest_source_change_seq', v_processed_source_change_seq,
        'force_legacy', false,
        'force_broad_legacy', false,
        'new_scope_baseline_required',v_new_scope_baseline_required,
        'source_dirty_job_id', p_job_id::text,
        'enqueue_origin', 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      )
    );

    SELECT public.pay_workbench_enqueue_candidate_refresh(
      p_snapshot_run_id => v_session_row.source_snapshot_run_id,
      p_candidate_id => v_candidate_id,
      p_reason => v_reason,
      p_actor_user_id => v_session_row.actor_user_id,
      p_payload_json => v_refresh_payload_json
    )
    INTO v_refresh_result;

    IF lower(BTRIM(COALESCE(v_refresh_result->>'coalesced', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      v_dirty_marking_skipped := true;
      v_session_count := v_session_count + 1;
      IF UPPER(BTRIM(COALESCE(v_refresh_result->>'owner_resolution', ''))) = 'COMPLETE_CURRENT_AUTHORITY' THEN
        v_jobs_coalesced_complete := v_jobs_coalesced_complete + 1;
      ELSE
        v_jobs_coalesced_active := v_jobs_coalesced_active + 1;
      END IF;

      UPDATE public.banking_pay_workbench_jobs AS coalesced_dirty_job
      SET payload_json = public._pay_workbench_dirty_payload_merge(
            COALESCE(coalesced_dirty_job.payload_json, '{}'::jsonb),
            jsonb_build_object(
              'processed_source_change_seq', v_processed_source_change_seq,
              'processed_at_utc', v_now::text,
              'processed_candidate_id', v_candidate_id::text,
              'dirty_apply_row_marking_applied', false,
              'dirty_marking_skipped', true,
              'coalesced_to_current_refresh_authority', true,
              'coalesced_owner_resolution', v_refresh_result->>'owner_resolution',
              'coalesced_owner_build_id', v_refresh_result->>'owner_build_id',
              'coalesced_owner_root_job_id', v_refresh_result->>'owner_root_job_id',
              'refresh_enqueue_result', v_refresh_result,
              'rerun_required', false,
              'has_more', false,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            )
          ),
          updated_at_utc = v_now
      WHERE coalesced_dirty_job.id = p_job_id;

      CONTINUE;
    END IF;

    UPDATE public.banking_pay_workbench_session_scope AS scope_row
    SET status = COALESCE(NULLIF(BTRIM(v_refresh_result->>'scope_status'), ''), 'SOURCE_BUILD_PENDING'),
        dirty = true,
        error_json = NULL::jsonb,
        certified_preview_publication_required = true,
        certified_preview_publication_parity_ok = false,
        certified_preview_publication_session_version = NULL,
        certified_preview_publication_source_change_seq = NULL,
        certified_preview_publication_source_build_run_id = NULL,
        certified_preview_publication_source_publication_id = NULL,
        certified_preview_publication_attestation_json = '{}'::jsonb,
        certified_preview_publication_attested_at_utc = NULL,
        updated_at_utc = v_now
    WHERE scope_row.session_id = v_session_row.id
      AND scope_row.candidate_id = v_candidate_id;
    GET DIAGNOSTICS v_scope_updated = ROW_COUNT;
    v_scope_count := v_scope_count + COALESCE(v_scope_updated, 0);

    UPDATE public.banking_pay_workbench_candidate_source_lines AS source_line
    SET status = 'DIRTY',
        source_row_json = jsonb_strip_nulls(
          COALESCE(source_line.source_row_json, '{}'::jsonb)
          || jsonb_build_object(
            'dirty_reason', v_reason,
            'source_change_seq', v_processed_source_change_seq,
            'dirty_trigger_table', COALESCE(v_payload->>'trigger_table', 'dirty_apply_worker'),
            'dirty_trigger_operation', COALESCE(v_payload->>'trigger_op', 'APPLY'),
            'dirty_at_utc', v_now::text,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
          )
        ),
        updated_at_utc = v_now
    WHERE source_line.session_id = v_session_row.id
      AND source_line.candidate_id = v_candidate_id
      AND source_line.status = 'CURRENT'
      AND (
        v_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
        OR source_line.timesheet_id = ANY(v_all_timesheet_ids)
        OR (
          NULLIF(BTRIM(COALESCE(source_line.source_row_json->>'finance_case_id', '')), '')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          AND (source_line.source_row_json->>'finance_case_id')::uuid
                = ANY(COALESCE(v_finance_case_ids, ARRAY[]::uuid[]))
        )
      );
    GET DIAGNOSTICS v_source_dirty_count = ROW_COUNT;
    v_source_dirty_total := v_source_dirty_total + COALESCE(v_source_dirty_count, 0);

    UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
    SET status = 'PENDING',
        result_row_json = NULL::jsonb,
        error_json = NULL::jsonb,
        work_payload_json = jsonb_strip_nulls(
          COALESCE(line_work.work_payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'dirty_reason', v_reason,
            'source_change_seq', v_processed_source_change_seq,
            'dirty_at_utc', v_now::text,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
          )
        ),
        updated_at_utc = v_now
    WHERE line_work.session_id = v_session_row.id
      AND line_work.candidate_id = v_candidate_id
      AND (
        v_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
        OR line_work.timesheet_id = ANY(v_all_timesheet_ids)
        OR (
          NULLIF(BTRIM(COALESCE(line_work.result_row_json->>'finance_case_id', '')), '')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          AND (line_work.result_row_json->>'finance_case_id')::uuid
                = ANY(COALESCE(v_finance_case_ids, ARRAY[]::uuid[]))
        )
      );
    GET DIAGNOSTICS v_line_work_count = ROW_COUNT;
    v_line_work_total := v_line_work_total + COALESCE(v_line_work_count, 0);

    UPDATE public.banking_pay_workbench_preview_rows AS preview_row
    SET status = 'DIRTY',
        selected = false,
        selection_state = 'DIRTY',
        row_json = jsonb_strip_nulls(
          COALESCE(preview_row.row_json, '{}'::jsonb)
          || jsonb_build_object(
            'dirty_reason', v_reason,
            'source_change_seq', v_processed_source_change_seq,
            'dirty_at_utc', v_now::text,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
          )
        ),
        updated_at_utc = v_now
    WHERE preview_row.session_id = v_session_row.id
      AND preview_row.candidate_id = v_candidate_id
      AND (
        v_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
        OR preview_row.timesheet_id = ANY(v_all_timesheet_ids)
        OR (
          NULLIF(BTRIM(COALESCE(preview_row.row_json->>'finance_case_id', '')), '')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          AND (preview_row.row_json->>'finance_case_id')::uuid
                = ANY(COALESCE(v_finance_case_ids, ARRAY[]::uuid[]))
        )
      );
    GET DIAGNOSTICS v_preview_count = ROW_COUNT;
    v_preview_total := v_preview_total + COALESCE(v_preview_count, 0);

    UPDATE public.banking_pay_workbench_sessions AS session_update
    SET progress_state = 'DIRTY',
        scope_pending_count = GREATEST(COALESCE(session_update.scope_pending_count, 0), 1),
        selected_row_count = GREATEST(COALESCE(session_update.selected_row_count, 0) - COALESCE(v_preview_count, 0), 0),
        candidate_sample_rows_json = jsonb_build_array(jsonb_build_object('candidate_id', v_candidate_id::text, 'status', 'SOURCE_BUILD_PENDING', 'reason', v_reason)),
        progress_json = jsonb_strip_nulls(
          COALESCE(session_update.progress_json, '{}'::jsonb)
          || jsonb_build_object(
            'last_dirty_candidate_id', v_candidate_id::text,
            'last_dirty_reason', v_reason,
            'last_dirty_at_utc', v_now::text,
            'last_dirty_job_id', p_job_id::text,
            'last_dirty_source_change_seq', v_processed_source_change_seq,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
          )
        ),
        progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
        progress_updated_at_utc = v_now,
        updated_at_utc = v_now
    WHERE session_update.id = v_session_row.id;
    v_session_count := v_session_count + 1;

    UPDATE public.banking_pay_workbench_jobs AS refresh_job
    SET payload_json = jsonb_strip_nulls(
          COALESCE(refresh_job.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'source_rows_marked_dirty_count', COALESCE(v_source_dirty_count, 0),
            'line_work_marked_pending_count', COALESCE(v_line_work_count, 0),
            'preview_rows_marked_dirty_count', COALESCE(v_preview_count, 0),
            'dirty_apply_marking_completed_at_utc', v_now::text
          )
        ),
        updated_at_utc = v_now
    WHERE COALESCE(v_refresh_result->>'job_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      AND refresh_job.id = (v_refresh_result->>'job_id')::uuid;

    v_jobs_queued := v_jobs_queued
      + CASE
          WHEN lower(BTRIM(COALESCE(v_refresh_result->>'new_owner_created', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 1
          WHEN NULLIF(BTRIM(COALESCE(v_refresh_result->>'job_id', '')), '') IS NOT NULL
               AND lower(BTRIM(COALESCE(v_refresh_result->>'reused', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN 1
          WHEN COALESCE(v_refresh_result->>'jobs_queued', '') ~ '^-?[0-9]+$' THEN (v_refresh_result->>'jobs_queued')::integer
          ELSE 0
        END;
  END LOOP;

  SELECT EXISTS (
    SELECT 1
    FROM public.banking_pay_workbench_sessions AS remaining_session
    WHERE remaining_session.status='OPEN' AND remaining_session.discarded_at_utc IS NULL
      AND v_session_scan_cutoff_created_at IS NOT NULL
      AND (remaining_session.created_at_utc,remaining_session.id)<=
          (v_session_scan_cutoff_created_at,v_session_scan_cutoff_id)
      AND (v_session_scan_last_created_at IS NULL OR
        (remaining_session.created_at_utc,remaining_session.id)>
          (v_session_scan_last_created_at,v_session_scan_last_id))
      AND NOT EXISTS (
        SELECT 1 FROM public.banking_pay_workbench_sessions AS newer_session
        WHERE newer_session.actor_user_id=remaining_session.actor_user_id
          AND newer_session.status='OPEN' AND newer_session.discarded_at_utc IS NULL
          AND (newer_session.pay_date,newer_session.created_at_utc,newer_session.id)>
              (remaining_session.pay_date,remaining_session.created_at_utc,remaining_session.id)
      )
  ) INTO v_session_scan_has_more;

  UPDATE public.banking_pay_workbench_jobs AS job_update
  SET payload_json = public._pay_workbench_dirty_payload_merge(
        COALESCE(job_update.payload_json, '{}'::jsonb),
        jsonb_build_object(
          'processed_source_change_seq', v_processed_source_change_seq,
          'processed_at_utc', v_now::text,
          'processed_candidate_id', v_candidate_id::text,
          'dirty_scope_count', v_scope_count,
          'dirty_line_count', v_line_work_total,
          'dirty_preview_count', v_preview_total,
          'dirty_apply_row_marking_applied', (v_scope_count + v_source_dirty_total + v_line_work_total + v_preview_total) > 0,
          'dirty_marking_skipped', v_dirty_marking_skipped,
          'jobs_coalesced_active', v_jobs_coalesced_active,
          'jobs_coalesced_complete', v_jobs_coalesced_complete,
          'jobs_requeued_for_conflict', v_jobs_requeued_for_conflict,
          'early_preflight_checked', v_is_authorise_delta_targeted,
          'early_preflight_action', COALESCE(v_preflight_action, 'PROCEED'),
          'actual_refresh_job_id', NULLIF(BTRIM(COALESCE(v_refresh_result->>'job_id', '')), ''),
          'actual_refresh_job_type', NULLIF(BTRIM(COALESCE(v_refresh_result->>'job_type', v_refresh_result->>'canonical_job_type', '')), ''),
          'actual_refresh_scope_status', NULLIF(BTRIM(COALESCE(v_refresh_result->>'scope_status', '')), ''),
          'source_build_required', lower(BTRIM(COALESCE(v_refresh_result->>'source_build_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
          'delta_refresh_required', lower(BTRIM(COALESCE(v_refresh_result->>'delta_refresh_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
          'line_work_action', CASE
            WHEN lower(BTRIM(COALESCE(v_refresh_result->>'delta_refresh_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              THEN 'DIRTY_ROW_MARKING_ONLY_DELTA_REFRESH'
            ELSE 'SOURCE_BUILD_OR_LEGACY_REFRESH'
          END,
          'refresh_enqueue_result', COALESCE(v_refresh_result, '{}'::jsonb)
          ,'session_scan_cutoff_created_at_utc',v_session_scan_cutoff_created_at::text
          ,'session_scan_cutoff_id',v_session_scan_cutoff_id::text
          ,'session_scan_last_created_at_utc',CASE WHEN v_session_scan_has_more THEN v_session_scan_last_created_at::text ELSE NULL END
          ,'session_scan_last_id',CASE WHEN v_session_scan_has_more THEN v_session_scan_last_id::text ELSE NULL END
          ,'rerun_required',v_session_scan_has_more
          ,'has_more',v_session_scan_has_more
        )
      ),
      private_cursor_kind=CASE WHEN v_session_scan_has_more THEN 'DIRTY_SESSION_SCAN_V1' ELSE NULL::text END,
      private_stage_version=CASE WHEN v_session_scan_has_more THEN 1 ELSE NULL::integer END,
      private_cursor_json=CASE
        WHEN v_session_scan_has_more THEN jsonb_strip_nulls(jsonb_build_object(
          'scan_source_change_seq',v_processed_source_change_seq,
          'upper_created_at_utc',v_session_scan_cutoff_created_at,
          'upper_session_id',v_session_scan_cutoff_id,
          'last_created_at_utc',v_session_scan_last_created_at,
          'last_session_id',v_session_scan_last_id,
          'scan_started_at_utc',v_session_scan_started_at,
          'sessions_examined',v_session_scan_sessions_examined
        ))
        ELSE '{}'::jsonb
      END,
      updated_at_utc = v_now
  WHERE job_update.id = p_job_id;

  PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', p_job_id::text, jsonb_build_object('function_name', 'pay_workbench_candidate_dirty_apply_job_process', 'stage', 'dirty_worker_apply_done', 'job_id', p_job_id::text, 'candidate_id', v_candidate_id::text, 'dirty_scope_count', v_scope_count, 'dirty_source_line_count', v_source_dirty_total, 'dirty_line_count', v_line_work_total, 'dirty_preview_count', v_preview_total, 'jobs_queued', v_jobs_queued, 'processed_source_change_seq', v_processed_source_change_seq, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', p_job_id::text,
    'job_type', 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
    'candidate_id', v_candidate_id::text,
    'refresh_scope_kind', v_refresh_scope_kind,
    'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
    'family_timesheet_count', COALESCE(array_length(v_family_timesheet_ids, 1), 0),
    'finance_case_count', COALESCE(array_length(v_finance_case_ids, 1), 0),
    'dependency_closure', COALESCE(v_dependency_closure_json, '{}'::jsonb),
    'dirty_scope_count', v_scope_count,
    'dirty_source_line_count', v_source_dirty_total,
    'dirty_line_count', v_line_work_total,
    'dirty_preview_count', v_preview_total,
    'sessions_touched', v_session_count,
    'jobs_queued', v_jobs_queued,
    'jobs_coalesced_active', v_jobs_coalesced_active,
    'jobs_coalesced_complete', v_jobs_coalesced_complete,
    'jobs_requeued_for_conflict', v_jobs_requeued_for_conflict,
    'processed_source_change_seq', v_processed_source_change_seq,
    'dirty_apply_row_marking_applied', (v_scope_count + v_source_dirty_total + v_line_work_total + v_preview_total) > 0,
    'dirty_marking_skipped', v_dirty_marking_skipped,
    'early_preflight_checked', v_is_authorise_delta_targeted,
    'early_preflight_action', COALESCE(v_preflight_action, 'PROCEED'),
    'actual_refresh_job_id', NULLIF(BTRIM(COALESCE(v_refresh_result->>'job_id', '')), ''),
    'actual_refresh_job_type', NULLIF(BTRIM(COALESCE(v_refresh_result->>'job_type', v_refresh_result->>'canonical_job_type', '')), ''),
    'actual_refresh_scope_status', NULLIF(BTRIM(COALESCE(v_refresh_result->>'scope_status', '')), ''),
    'source_build_required', lower(BTRIM(COALESCE(v_refresh_result->>'source_build_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    'delta_refresh_required', lower(BTRIM(COALESCE(v_refresh_result->>'delta_refresh_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    'line_work_action', CASE
      WHEN lower(BTRIM(COALESCE(v_refresh_result->>'delta_refresh_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        THEN 'DIRTY_ROW_MARKING_ONLY_DELTA_REFRESH'
      ELSE 'SOURCE_BUILD_OR_LEGACY_REFRESH'
    END,
    'refresh_enqueue_result', COALESCE(v_refresh_result, '{}'::jsonb),
    'more_due', v_session_scan_has_more,
    'has_more', v_session_scan_has_more,
    'made_progress', true,
    'dirty_apply_complete', NOT v_session_scan_has_more,
    'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
  );
END;
$function$;

-- pay_workbench_candidate_line_work_process_chunk(uuid,uuid,jsonb,integer)
CREATE OR REPLACE FUNCTION public.pay_workbench_candidate_line_work_process_chunk(p_session_id uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_cursor_json jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_cursor_scope_ordinal bigint := -1;
  v_cursor_line_ordinal bigint := -1;
  v_cursor_line_work_id uuid := NULL::uuid;
  v_cursor_has_scope boolean := false;
  v_raw_count integer := 0;
  v_processed_count integer := 0;
  v_error_count integer := 0;
  v_ready_delta integer := 0;
  v_skipped_count integer := 0;
  v_next_cursor jsonb := NULL::jsonb;
  v_last_returned_scope_ordinal bigint := NULL::bigint;
  v_last_returned_line_ordinal bigint := NULL::bigint;
  v_last_returned_line_work_id uuid := NULL::uuid;
  v_affected_candidate_sample jsonb := '[]'::jsonb;
  v_scope_pending_delta integer := 0;
  v_scope_ready_delta integer := 0;
  v_scope_failed_delta integer := 0;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_SESSION_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_SESSION_ID_REQUIRED')::text;
  END IF;

  IF p_cursor_json IS NOT NULL AND jsonb_typeof(p_cursor_json) = 'object' THEN
    BEGIN
      IF NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_scope_ordinal', p_cursor_json->>'cursor_scope_ordinal', '')), '') IS NOT NULL THEN
        v_cursor_scope_ordinal := NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_scope_ordinal', p_cursor_json->>'cursor_scope_ordinal', '')), '')::bigint;
        v_cursor_has_scope := true;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_cursor_scope_ordinal := -1;
      v_cursor_has_scope := false;
    END;

    BEGIN
      v_cursor_line_ordinal := COALESCE(
        NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_line_ordinal', '')), '')::bigint,
        NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_ordinal', '')), '')::bigint,
        NULLIF(BTRIM(COALESCE(p_cursor_json->>'cursor_ordinal', '')), '')::bigint,
        -1
      );
    EXCEPTION WHEN OTHERS THEN
      v_cursor_line_ordinal := -1;
    END;

    IF NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_line_work_id', p_cursor_json->>'last_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_cursor_line_work_id := NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_line_work_id', p_cursor_json->>'last_id', '')), '')::uuid;
    END IF;
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_SESSION_NOT_FOUND',
              'session_id', p_session_id::text
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_SESSION_NOT_OPEN',
              'session_id', p_session_id::text,
              'status', v_session_row.status
            )::text;
  END IF;

  IF p_candidate_id IS NOT NULL THEN
    SELECT COALESCE(scope_check.scope_ordinal, 0)::bigint
    INTO v_cursor_scope_ordinal
    FROM public.banking_pay_workbench_session_scope AS scope_check
    WHERE scope_check.session_id = p_session_id
      AND scope_check.candidate_id = p_candidate_id
    LIMIT 1;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CANDIDATE_NOT_IN_SCOPE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CANDIDATE_NOT_IN_SCOPE',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text
              )::text;
    END IF;
  ELSIF v_cursor_has_scope IS NOT TRUE THEN
    v_cursor_scope_ordinal := -1;
    v_cursor_line_ordinal := -1;
    v_cursor_line_work_id := NULL::uuid;
  END IF;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_line_process;
  CREATE TEMP TABLE _tmp_pay_wb_line_process ON COMMIT DROP AS
  WITH pending_rows AS (
    SELECT
      line_work.id,
      line_work.session_id,
      line_work.candidate_id,
      line_work.timesheet_id,
      line_work.line_key,
      line_work.line_ordinal,
      line_work.work_payload_json,
      COALESCE(scope_row.scope_ordinal, 0)::bigint AS scope_ordinal,
      ROW_NUMBER() OVER (
        ORDER BY COALESCE(scope_row.scope_ordinal, 0), line_work.line_ordinal, line_work.id
      ) AS page_ordinal
    FROM public.banking_pay_workbench_candidate_line_work AS line_work
    JOIN public.banking_pay_workbench_session_scope AS scope_row
      ON scope_row.session_id = line_work.session_id
     AND scope_row.candidate_id = line_work.candidate_id
    WHERE line_work.session_id = p_session_id
      AND (p_candidate_id IS NULL OR line_work.candidate_id = p_candidate_id)
      AND UPPER(BTRIM(COALESCE(line_work.status, ''))) = 'PENDING'
      AND (
        COALESCE(scope_row.scope_ordinal, 0)::bigint > COALESCE(v_cursor_scope_ordinal, -1)
        OR (
          COALESCE(scope_row.scope_ordinal, 0)::bigint = COALESCE(v_cursor_scope_ordinal, -1)
          AND line_work.line_ordinal > COALESCE(v_cursor_line_ordinal, -1)
        )
        OR (
          COALESCE(scope_row.scope_ordinal, 0)::bigint = COALESCE(v_cursor_scope_ordinal, -1)
          AND line_work.line_ordinal = COALESCE(v_cursor_line_ordinal, -1)
          AND v_cursor_line_work_id IS NOT NULL
          AND line_work.id > v_cursor_line_work_id
        )
      )
    ORDER BY COALESCE(scope_row.scope_ordinal, 0), line_work.line_ordinal, line_work.id
    LIMIT (v_limit + 1)
  )
  SELECT pending_rows.*
  FROM pending_rows;

  SELECT COUNT(*)::integer
  INTO v_raw_count
  FROM pg_temp._tmp_pay_wb_line_process AS process_rows;

  WITH selected_rows AS (
    SELECT process_rows.*
    FROM pg_temp._tmp_pay_wb_line_process AS process_rows
    WHERE process_rows.page_ordinal <= v_limit
  ), prepared_source_rows AS (
    SELECT
      selected_rows.id,
      selected_rows.candidate_id,
      selected_rows.timesheet_id AS line_work_timesheet_id,
      CASE
        WHEN NULLIF(BTRIM(COALESCE(selected_rows.work_payload_json#>>'{economic_key,timesheet_id}', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(selected_rows.work_payload_json#>>'{economic_key,timesheet_id}', '')), '')::uuid
        ELSE NULL::uuid
      END AS economic_key_timesheet_id,
      CASE
        WHEN NULLIF(BTRIM(COALESCE(
          selected_rows.work_payload_json#>>'{line_json,economic_key,timesheet_id}',
          selected_rows.work_payload_json#>>'{line_json,real_business_timesheet_id}',
          selected_rows.work_payload_json#>>'{line_json,timesheet_id}',
          ''
        )), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(
            selected_rows.work_payload_json#>>'{line_json,economic_key,timesheet_id}',
            selected_rows.work_payload_json#>>'{line_json,real_business_timesheet_id}',
            selected_rows.work_payload_json#>>'{line_json,timesheet_id}',
            ''
          )), '')::uuid
        ELSE NULL::uuid
      END AS line_json_timesheet_id,
      selected_rows.line_key,
      selected_rows.line_ordinal,
      selected_rows.scope_ordinal,
      selected_rows.work_payload_json,
      COALESCE(selected_rows.work_payload_json->'line_json', '{}'::jsonb) AS safe_line_json,
      CASE
        WHEN jsonb_typeof(selected_rows.work_payload_json->'economic_key') = 'object'
          THEN selected_rows.work_payload_json->'economic_key'
        ELSE '{}'::jsonb
      END AS economic_key_json,
      COALESCE(
        NULLIF(BTRIM(selected_rows.work_payload_json->>'target_section'), ''),
        NULLIF(BTRIM(selected_rows.work_payload_json->>'section'), ''),
        NULLIF(BTRIM(selected_rows.work_payload_json#>>'{preview_contract,target_section}'), '')
      ) AS target_section_hint,
      UPPER(NULLIF(BTRIM(COALESCE(selected_rows.work_payload_json->>'source_kind', selected_rows.work_payload_json#>>'{line_json,source_kind}', '')), '')) AS source_kind,
      UPPER(NULLIF(BTRIM(COALESCE(selected_rows.work_payload_json->>'source_function', '')), '')) AS source_function,
      CASE
        WHEN selected_rows.line_key LIKE 'timesheet_snapshot:%' THEN true
        WHEN UPPER(NULLIF(BTRIM(COALESCE(selected_rows.work_payload_json->>'source_kind', selected_rows.work_payload_json#>>'{line_json,source_kind}', '')), '')) IN (
          'TIMESHEET_SNAPSHOT',
          'TIMESHEET_SNAPSHOT_EVIDENCE',
          'RAW_TIMESHEET_SNAPSHOT',
          'INTERNAL_ONLY',
          'NO_DELTA',
          'EXCLUDED'
        ) THEN true
        WHEN UPPER(NULLIF(BTRIM(COALESCE(selected_rows.work_payload_json->>'source_function', '')), '')) = 'PAY_PREVIEW_CANDIDATE_BUILD_TIMESHEET_SNAPSHOTS' THEN true
        ELSE false
      END AS is_internal_snapshot_row
    FROM selected_rows
  ), source_timesheet_refs AS (
    SELECT prepared_source_rows.id, 'LINE_WORK'::text AS source_label, prepared_source_rows.line_work_timesheet_id AS source_timesheet_id
    FROM prepared_source_rows
    WHERE prepared_source_rows.line_work_timesheet_id IS NOT NULL
    UNION ALL
    SELECT prepared_source_rows.id, 'ECONOMIC_KEY'::text AS source_label, prepared_source_rows.economic_key_timesheet_id AS source_timesheet_id
    FROM prepared_source_rows
    WHERE prepared_source_rows.economic_key_timesheet_id IS NOT NULL
    UNION ALL
    SELECT prepared_source_rows.id, 'LINE_JSON'::text AS source_label, prepared_source_rows.line_json_timesheet_id AS source_timesheet_id
    FROM prepared_source_rows
    WHERE prepared_source_rows.line_json_timesheet_id IS NOT NULL
  ), source_timesheet_id_array AS (
    SELECT COALESCE(
      array_agg(DISTINCT source_timesheet_refs.source_timesheet_id ORDER BY source_timesheet_refs.source_timesheet_id),
      array[]::uuid[]
    ) AS timesheet_ids
    FROM source_timesheet_refs
  ), rotation_scope_rows AS (
    SELECT
      rotation_scope.requested_timesheet_id,
      rotation_scope.canonical_timesheet_id,
      rotation_scope.family_timesheet_id,
      rotation_scope.family_is_current,
      rotation_scope.family_version,
      rotation_scope.requested_is_canonical
    FROM source_timesheet_id_array
    JOIN public._pay_timesheet_rotation_scope(source_timesheet_id_array.timesheet_ids) AS rotation_scope
      ON true
  ), rotation_scope_by_requested AS (
    SELECT DISTINCT ON (rotation_scope_rows.requested_timesheet_id)
      rotation_scope_rows.requested_timesheet_id,
      COALESCE(rotation_scope_rows.canonical_timesheet_id, rotation_scope_rows.requested_timesheet_id) AS canonical_timesheet_id,
      (rotation_scope_rows.family_timesheet_id IS NOT NULL AND rotation_scope_rows.family_is_current IS NOT NULL) AS rotation_scope_resolved,
      COALESCE(rotation_scope_rows.requested_is_canonical, false) AS requested_is_canonical
    FROM rotation_scope_rows
    WHERE rotation_scope_rows.requested_timesheet_id IS NOT NULL
    ORDER BY
      rotation_scope_rows.requested_timesheet_id,
      rotation_scope_rows.family_is_current DESC NULLS LAST,
      rotation_scope_rows.family_version DESC NULLS LAST,
      rotation_scope_rows.family_timesheet_id
  ), prepared_rows AS (
    SELECT
      prepared_source_rows.id,
      prepared_source_rows.candidate_id,
      COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id) AS timesheet_id,
      prepared_source_rows.line_work_timesheet_id,
      prepared_source_rows.economic_key_timesheet_id,
      prepared_source_rows.line_json_timesheet_id,
      line_work_rotation.canonical_timesheet_id AS line_work_canonical_timesheet_id,
      economic_key_rotation.canonical_timesheet_id AS economic_key_canonical_timesheet_id,
      line_json_rotation.canonical_timesheet_id AS line_json_canonical_timesheet_id,
      prepared_source_rows.line_key,
      prepared_source_rows.line_ordinal,
      prepared_source_rows.scope_ordinal,
      jsonb_strip_nulls(
        COALESCE(prepared_source_rows.economic_key_json, '{}'::jsonb)
        || jsonb_build_object(
          'timesheet_id', CASE
            WHEN COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id) IS NULL THEN NULL
            ELSE COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id)::text
          END
        )
      ) AS economic_key_json,
      jsonb_strip_nulls(
        CASE
          WHEN COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id) IS NULL THEN prepared_source_rows.safe_line_json
          ELSE prepared_source_rows.safe_line_json
            || jsonb_build_object(
              'timesheet_id', COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id)::text,
              'real_business_timesheet_id', COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id)::text
            )
            || jsonb_build_object(
              'economic_key', COALESCE(prepared_source_rows.safe_line_json->'economic_key', '{}'::jsonb)
                || jsonb_build_object('timesheet_id', COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id)::text)
            )
            || CASE
              WHEN prepared_source_rows.line_work_timesheet_id IS DISTINCT FROM COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id)
                OR prepared_source_rows.economic_key_timesheet_id IS DISTINCT FROM COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id)
                OR prepared_source_rows.line_json_timesheet_id IS DISTINCT FROM COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id)
              THEN jsonb_build_object(
                'rotation_requested_timesheet_ids', jsonb_strip_nulls(jsonb_build_object(
                  'line_work_timesheet_id', CASE WHEN prepared_source_rows.line_work_timesheet_id IS NULL THEN NULL ELSE prepared_source_rows.line_work_timesheet_id::text END,
                  'economic_key_timesheet_id', CASE WHEN prepared_source_rows.economic_key_timesheet_id IS NULL THEN NULL ELSE prepared_source_rows.economic_key_timesheet_id::text END,
                  'line_json_timesheet_id', CASE WHEN prepared_source_rows.line_json_timesheet_id IS NULL THEN NULL ELSE prepared_source_rows.line_json_timesheet_id::text END
                ))
              )
              ELSE '{}'::jsonb
            END
        END
      ) AS safe_line_json,
      prepared_source_rows.target_section_hint,
      prepared_source_rows.source_kind,
      prepared_source_rows.source_function,
      prepared_source_rows.is_internal_snapshot_row,
      CASE
        WHEN prepared_source_rows.is_internal_snapshot_row THEN false
        WHEN prepared_source_rows.line_work_timesheet_id IS NULL
         AND prepared_source_rows.economic_key_timesheet_id IS NULL
         AND prepared_source_rows.line_json_timesheet_id IS NULL THEN false
        WHEN COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id) IS NULL THEN true
        WHEN prepared_source_rows.line_work_timesheet_id IS NOT NULL AND COALESCE(line_work_rotation.rotation_scope_resolved, false) = false THEN true
        WHEN prepared_source_rows.economic_key_timesheet_id IS NOT NULL AND COALESCE(economic_key_rotation.rotation_scope_resolved, false) = false THEN true
        WHEN prepared_source_rows.line_json_timesheet_id IS NOT NULL AND COALESCE(line_json_rotation.rotation_scope_resolved, false) = false THEN true
        WHEN line_work_rotation.canonical_timesheet_id IS NOT NULL
         AND economic_key_rotation.canonical_timesheet_id IS NOT NULL
         AND line_work_rotation.canonical_timesheet_id IS DISTINCT FROM economic_key_rotation.canonical_timesheet_id THEN true
        WHEN line_work_rotation.canonical_timesheet_id IS NOT NULL
         AND line_json_rotation.canonical_timesheet_id IS NOT NULL
         AND line_work_rotation.canonical_timesheet_id IS DISTINCT FROM line_json_rotation.canonical_timesheet_id THEN true
        WHEN economic_key_rotation.canonical_timesheet_id IS NOT NULL
         AND line_json_rotation.canonical_timesheet_id IS NOT NULL
         AND economic_key_rotation.canonical_timesheet_id IS DISTINCT FROM line_json_rotation.canonical_timesheet_id THEN true
        ELSE false
      END AS rotation_validation_failed,
      CASE
        WHEN prepared_source_rows.is_internal_snapshot_row THEN NULL::text
        WHEN prepared_source_rows.line_work_timesheet_id IS NULL
         AND prepared_source_rows.economic_key_timesheet_id IS NULL
         AND prepared_source_rows.line_json_timesheet_id IS NULL THEN NULL::text
        WHEN COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id) IS NULL THEN 'ROTATION_CANONICAL_TIMESHEET_NOT_RESOLVED'
        WHEN prepared_source_rows.line_work_timesheet_id IS NOT NULL AND COALESCE(line_work_rotation.rotation_scope_resolved, false) = false THEN 'LINE_WORK_TIMESHEET_ROTATION_SCOPE_UNRESOLVED'
        WHEN prepared_source_rows.economic_key_timesheet_id IS NOT NULL AND COALESCE(economic_key_rotation.rotation_scope_resolved, false) = false THEN 'ECONOMIC_KEY_TIMESHEET_ROTATION_SCOPE_UNRESOLVED'
        WHEN prepared_source_rows.line_json_timesheet_id IS NOT NULL AND COALESCE(line_json_rotation.rotation_scope_resolved, false) = false THEN 'LINE_JSON_TIMESHEET_ROTATION_SCOPE_UNRESOLVED'
        WHEN line_work_rotation.canonical_timesheet_id IS NOT NULL
         AND economic_key_rotation.canonical_timesheet_id IS NOT NULL
         AND line_work_rotation.canonical_timesheet_id IS DISTINCT FROM economic_key_rotation.canonical_timesheet_id THEN 'LINE_WORK_AND_ECONOMIC_KEY_CANONICAL_TIMESHEET_MISMATCH'
        WHEN line_work_rotation.canonical_timesheet_id IS NOT NULL
         AND line_json_rotation.canonical_timesheet_id IS NOT NULL
         AND line_work_rotation.canonical_timesheet_id IS DISTINCT FROM line_json_rotation.canonical_timesheet_id THEN 'LINE_WORK_AND_RESULT_ROW_CANONICAL_TIMESHEET_MISMATCH'
        WHEN economic_key_rotation.canonical_timesheet_id IS NOT NULL
         AND line_json_rotation.canonical_timesheet_id IS NOT NULL
         AND economic_key_rotation.canonical_timesheet_id IS DISTINCT FROM line_json_rotation.canonical_timesheet_id THEN 'ECONOMIC_KEY_AND_RESULT_ROW_CANONICAL_TIMESHEET_MISMATCH'
        ELSE NULL::text
      END AS rotation_failure_reason
    FROM prepared_source_rows
    LEFT JOIN rotation_scope_by_requested AS line_work_rotation
      ON line_work_rotation.requested_timesheet_id = prepared_source_rows.line_work_timesheet_id
    LEFT JOIN rotation_scope_by_requested AS economic_key_rotation
      ON economic_key_rotation.requested_timesheet_id = prepared_source_rows.economic_key_timesheet_id
    LEFT JOIN rotation_scope_by_requested AS line_json_rotation
      ON line_json_rotation.requested_timesheet_id = prepared_source_rows.line_json_timesheet_id
  ), contracted_rows AS (
    SELECT
      prepared_rows.*,
      CASE
        WHEN prepared_rows.is_internal_snapshot_row THEN jsonb_build_object(
          'ok', false,
          'materialisable', false,
          'target_section', 'internal_only',
          'selection_allowed', false,
          'reasons', jsonb_build_array('INTERNAL_TIMESHEET_SNAPSHOT_ROW_SKIPPED'),
          'status', 'SKIPPED'
        )
        WHEN prepared_rows.rotation_validation_failed THEN jsonb_build_object(
          'ok', false,
          'materialisable', true,
          'target_section', COALESCE(prepared_rows.target_section_hint, 'canonical_preview_lines'),
          'selection_allowed', false,
          'reasons', jsonb_build_array(prepared_rows.rotation_failure_reason),
          'status', 'ERROR'
        )
        WHEN jsonb_typeof(prepared_rows.safe_line_json) = 'object' THEN public.pay_workbench_preview_line_contract_ok(
          p_line_json => prepared_rows.safe_line_json,
          p_economic_key_json => prepared_rows.economic_key_json,
          p_target_section => prepared_rows.target_section_hint
        )
        ELSE jsonb_build_object(
          'ok', false,
          'materialisable', false,
          'target_section', 'internal_only',
          'selection_allowed', false,
          'reasons', jsonb_build_array('LINE_JSON_NOT_OBJECT'),
          'status', 'NOT_OK'
        )
      END AS contract_json
    FROM prepared_rows
  ), update_source AS (
    SELECT
      contracted_rows.*,
      COALESCE(NULLIF(BTRIM(contracted_rows.contract_json->>'target_section'), ''), 'internal_only') AS target_section,
      CASE
        WHEN contracted_rows.rotation_validation_failed THEN 'ERROR'
        WHEN LOWER(BTRIM(COALESCE(contracted_rows.contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 'READY'
        WHEN LOWER(BTRIM(COALESCE(contracted_rows.contract_json->>'materialisable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 'ERROR'
        ELSE 'SKIPPED'
      END AS next_status
    FROM contracted_rows
  ), updated_rows AS (
    UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
    SET status = update_source.next_status,
        timesheet_id = CASE
          WHEN update_source.rotation_validation_failed THEN line_work.timesheet_id
          ELSE COALESCE(update_source.timesheet_id, line_work.timesheet_id)
        END,
        result_row_json = CASE
          WHEN update_source.next_status = 'READY' THEN jsonb_strip_nulls(
            update_source.safe_line_json
            || jsonb_build_object(
              'session_id', p_session_id::text,
              'candidate_id', update_source.candidate_id::text,
              'line_work_id', update_source.id::text,
              'row_key', update_source.line_key,
              'line_key', update_source.line_key,
              'line_ordinal', update_source.line_ordinal,
              'scope_ordinal', update_source.scope_ordinal,
              'timesheet_id', CASE WHEN update_source.timesheet_id IS NULL THEN NULL ELSE update_source.timesheet_id::text END,
              'section', update_source.target_section
            )
            || jsonb_build_object(
              'economic_key', update_source.economic_key_json,
              'preview_contract', update_source.contract_json,
              'selection_allowed', COALESCE(NULLIF(BTRIM(update_source.contract_json->>'selection_allowed'), '')::boolean, false),
              'policy_x_pre_draft_key_resolved', LOWER(BTRIM(COALESCE(update_source.economic_key_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
              'row_processing_status', CASE WHEN update_source.target_section = 'canonical_preview_lines' THEN 'READY' ELSE 'DISPLAY_ONLY' END
            )
          )
          WHEN update_source.next_status = 'SKIPPED' THEN jsonb_strip_nulls(
            update_source.safe_line_json
            || jsonb_build_object(
              'session_id', p_session_id::text,
              'candidate_id', update_source.candidate_id::text,
              'line_work_id', update_source.id::text,
              'row_key', update_source.line_key,
              'line_key', update_source.line_key,
              'line_ordinal', update_source.line_ordinal,
              'scope_ordinal', update_source.scope_ordinal,
              'section', 'internal_only',
              'preview_contract', update_source.contract_json,
              'row_processing_status', 'SKIPPED'
            )
          )
          ELSE NULL::jsonb
        END,
        error_json = CASE
          WHEN update_source.next_status = 'ERROR' THEN jsonb_build_object(
            'code', CASE WHEN update_source.rotation_validation_failed THEN 'WORKBENCH_ROTATED_TIMESHEET_MISMATCH' ELSE 'PREVIEW_LINE_CONTRACT_FAILED' END,
            'message', CASE
              WHEN update_source.rotation_validation_failed THEN 'Candidate line work timesheet identities did not resolve to the same current canonical timesheet.'
              ELSE 'Candidate line work did not satisfy the Banking Pay preview-row contract.'
            END,
            'line_key', update_source.line_key,
            'line_ordinal', update_source.line_ordinal,
            'scope_ordinal', update_source.scope_ordinal,
            'target_section', update_source.target_section,
            'reasons', COALESCE(update_source.contract_json->'reasons', '[]'::jsonb)
          )
          ELSE NULL::jsonb
        END,
        updated_at_utc = v_now
    FROM update_source
    WHERE line_work.id = update_source.id
    RETURNING line_work.candidate_id, line_work.status
  )
  SELECT
    COUNT(*)::integer,
    COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(updated_rows.status, ''))) = 'ERROR')::integer,
    COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(updated_rows.status, ''))) = 'READY')::integer,
    COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(updated_rows.status, ''))) = 'SKIPPED')::integer
  INTO v_processed_count, v_error_count, v_ready_delta, v_skipped_count
  FROM updated_rows;

  IF v_raw_count > v_limit THEN
    SELECT
      process_rows.scope_ordinal,
      process_rows.line_ordinal,
      process_rows.id
    INTO
      v_last_returned_scope_ordinal,
      v_last_returned_line_ordinal,
      v_last_returned_line_work_id
    FROM pg_temp._tmp_pay_wb_line_process AS process_rows
    WHERE process_rows.page_ordinal = v_limit;

    v_next_cursor := jsonb_build_object(
      'last_scope_ordinal', v_last_returned_scope_ordinal,
      'last_line_ordinal', v_last_returned_line_ordinal,
      'last_line_work_id', v_last_returned_line_work_id::text
    );
  ELSE
    v_next_cursor := NULL::jsonb;
  END IF;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_line_process_scope_delta;
  CREATE TEMP TABLE _tmp_pay_wb_line_process_scope_delta ON COMMIT DROP AS
  WITH affected_candidates AS (
    SELECT DISTINCT process_rows.candidate_id
    FROM pg_temp._tmp_pay_wb_line_process AS process_rows
    WHERE process_rows.page_ordinal <= v_limit
    UNION
    SELECT p_candidate_id
    WHERE p_candidate_id IS NOT NULL
  ), candidate_new_status AS (
    SELECT
      affected_candidates.candidate_id,
      CASE
        WHEN EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_line_work AS line_error
          WHERE line_error.session_id = p_session_id
            AND line_error.candidate_id = affected_candidates.candidate_id
            AND UPPER(BTRIM(COALESCE(line_error.status, ''))) = 'ERROR'
        ) THEN 'ERROR'
        WHEN EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_line_work AS line_pending
          WHERE line_pending.session_id = p_session_id
            AND line_pending.candidate_id = affected_candidates.candidate_id
            AND UPPER(BTRIM(COALESCE(line_pending.status, ''))) = 'PENDING'
        ) THEN 'LINE_WORK_PENDING'
        WHEN EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_line_work AS line_ready
          WHERE line_ready.session_id = p_session_id
            AND line_ready.candidate_id = affected_candidates.candidate_id
            AND UPPER(BTRIM(COALESCE(line_ready.status, ''))) = 'READY'
        ) THEN 'LINE_WORK_READY'
        ELSE 'MATERIALISED'
      END AS new_status
    FROM affected_candidates
  )
  SELECT
    scope_row.candidate_id,
    UPPER(BTRIM(COALESCE(scope_row.status, 'PENDING'))) AS old_status,
    candidate_new_status.new_status
  FROM candidate_new_status
  JOIN public.banking_pay_workbench_session_scope AS scope_row
    ON scope_row.session_id = p_session_id
   AND scope_row.candidate_id = candidate_new_status.candidate_id;

  SELECT
    COALESCE(SUM(
      CASE
        WHEN scope_delta.new_status IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR') THEN 0
        ELSE 1
      END
      - CASE
        WHEN scope_delta.old_status IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR') THEN 0
        ELSE 1
      END
    ), 0)::integer,
    COALESCE(SUM(
      CASE WHEN scope_delta.new_status IN ('READY', 'MATERIALISED', 'MATERIALIZED') THEN 1 ELSE 0 END
      - CASE WHEN scope_delta.old_status IN ('READY', 'MATERIALISED', 'MATERIALIZED') THEN 1 ELSE 0 END
    ), 0)::integer,
    COALESCE(SUM(
      CASE WHEN scope_delta.new_status IN ('ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR') THEN 1 ELSE 0 END
      - CASE WHEN scope_delta.old_status IN ('ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR') THEN 1 ELSE 0 END
    ), 0)::integer
  INTO v_scope_pending_delta,
       v_scope_ready_delta,
       v_scope_failed_delta
  FROM pg_temp._tmp_pay_wb_line_process_scope_delta AS scope_delta;

  UPDATE public.banking_pay_workbench_session_scope AS scope_row
  SET status = scope_delta.new_status,
      dirty = scope_delta.new_status NOT IN ('LINE_WORK_READY', 'MATERIALISED', 'MATERIALIZED'),
      updated_at_utc = v_now,
      error_json = CASE
        WHEN scope_delta.new_status = 'ERROR' THEN jsonb_build_object('code', 'LINE_WORK_PROCESS_ERROR')
        ELSE NULL::jsonb
      END
  FROM pg_temp._tmp_pay_wb_line_process_scope_delta AS scope_delta
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = scope_delta.candidate_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'candidate_id', scope_delta.candidate_id::text,
           'old_status', scope_delta.old_status,
           'new_status', scope_delta.new_status
         ) ORDER BY scope_delta.candidate_id), '[]'::jsonb)
  INTO v_affected_candidate_sample
  FROM (
    SELECT scope_delta.*
    FROM pg_temp._tmp_pay_wb_line_process_scope_delta AS scope_delta
    ORDER BY scope_delta.candidate_id
    LIMIT 25
  ) AS scope_delta;

  UPDATE public.banking_pay_workbench_sessions AS session_row
  SET line_units_pending = GREATEST(COALESCE(session_row.line_units_pending, 0) - COALESCE(v_processed_count, 0), 0),
      line_units_ready = GREATEST(COALESCE(session_row.line_units_ready, 0) + COALESCE(v_ready_delta, 0), 0),
      line_units_failed = GREATEST(COALESCE(session_row.line_units_failed, 0) + COALESCE(v_error_count, 0), 0),
      scope_pending_count = GREATEST(COALESCE(session_row.scope_pending_count, 0) + COALESCE(v_scope_pending_delta, 0), 0),
      scope_ready_count = GREATEST(COALESCE(session_row.scope_ready_count, 0) + COALESCE(v_scope_ready_delta, 0), 0),
      scope_failed_count = GREATEST(COALESCE(session_row.scope_failed_count, 0) + COALESCE(v_scope_failed_delta, 0), 0),
      candidate_sample_rows_json = COALESCE(v_affected_candidate_sample, '[]'::jsonb),
      progress_state = CASE
        WHEN COALESCE(v_error_count, 0) > 0 THEN 'ERROR'
        ELSE 'PROCESSING_LINE_WORK'
      END,
      progress_json = COALESCE(session_row.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'last_line_process_at_utc', v_now::text,
          'last_line_process_count', COALESCE(v_processed_count, 0),
          'last_line_process_ready_count', COALESCE(v_ready_delta, 0),
          'last_line_process_skipped_count', COALESCE(v_skipped_count, 0),
          'last_line_process_error_count', COALESCE(v_error_count, 0),
          'last_line_process_has_more', v_next_cursor IS NOT NULL,
          'last_scope_pending_delta', COALESCE(v_scope_pending_delta, 0),
          'last_scope_ready_delta', COALESCE(v_scope_ready_delta, 0),
          'last_scope_failed_delta', COALESCE(v_scope_failed_delta, 0),
          'phase', CASE WHEN COALESCE(v_error_count, 0) > 0 THEN 'ERROR' ELSE 'PROCESSING_LINE_WORK' END,
          'status_text', CASE
            WHEN COALESCE(v_error_count, 0) > 0 THEN 'Payment preview could not be prepared for every candidate.'
            ELSE 'Processing payment preview line work.'
          END,
          'next_recommended_action', CASE
            WHEN COALESCE(v_error_count, 0) > 0 THEN 'REVIEW_ERRORS'
            WHEN v_next_cursor IS NOT NULL THEN 'PROCESS_LINE_WORK_CHUNK'
            WHEN COALESCE(v_ready_delta, 0) > 0 THEN 'MATERIALISE_PREVIEW_ROWS_CHUNK'
            ELSE 'WAIT_FOR_WORKER'
          END,
          'terminal_readiness_deferred', true,
          'terminal_readiness_deferred_to', 'pay_workbench_complete_job'
        ),
      progress_counter_version = COALESCE(session_row.progress_counter_version, 0) + 1,
      progress_updated_at_utc = v_now,
      updated_at_utc = v_now
  WHERE session_row.id = p_session_id;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    'limit', v_limit,
    'cursor_scope_ordinal', COALESCE(v_cursor_scope_ordinal, -1),
    'cursor_line_ordinal', COALESCE(v_cursor_line_ordinal, -1),
    'cursor_line_work_id', CASE WHEN v_cursor_line_work_id IS NULL THEN NULL ELSE v_cursor_line_work_id::text END,
    'processed_count', COALESCE(v_processed_count, 0),
    'ready_count_delta', COALESCE(v_ready_delta, 0),
    'skipped_count', COALESCE(v_skipped_count, 0),
    'error_count', COALESCE(v_error_count, 0),
    'terminal_reconciliation_only', COALESCE(v_processed_count, 0) = 0
      AND p_candidate_id IS NOT NULL
      AND jsonb_array_length(COALESCE(v_affected_candidate_sample, '[]'::jsonb)) > 0
  )
  || jsonb_build_object(
    'next_cursor', v_next_cursor,
    'has_more', v_next_cursor IS NOT NULL,
    'affected_candidates', COALESCE(v_affected_candidate_sample, '[]'::jsonb),
    'scope_counter_deltas', jsonb_build_object(
      'pending_delta', COALESCE(v_scope_pending_delta, 0),
      'ready_delta', COALESCE(v_scope_ready_delta, 0),
      'failed_delta', COALESCE(v_scope_failed_delta, 0)
    ),
    'cursor_scheme', 'last_scope_ordinal_last_line_ordinal_last_line_work_id'
  );
END;
$function$;

-- pay_workbench_candidate_line_work_seed(uuid,uuid,jsonb,integer)
CREATE OR REPLACE FUNCTION public.pay_workbench_candidate_line_work_seed(p_session_id uuid, p_candidate_id uuid, p_cursor_json jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_scope_status text := NULL::text;
  v_seeded_count integer := 0;
  v_error_count integer := 0;
  v_new_pending_count integer := 0;
  v_new_error_count integer := 0;
  v_new_line_count integer := 0;
  v_pending_transition_count integer := 0;
  v_requeued_pending_count integer := 0;
  v_ready_to_pending_count integer := 0;
  v_materialised_to_pending_count integer := 0;
  v_failed_to_pending_count integer := 0;
  v_retired_line_count integer := 0;
  v_retired_pending_count integer := 0;
  v_retired_ready_count integer := 0;
  v_retired_materialised_count integer := 0;
  v_retired_failed_count integer := 0;
  v_retired_other_count integer := 0;
  v_retired_preview_row_count integer := 0;
  v_superseded_preview_row_count integer := 0;
  v_has_more boolean := false;
  v_next_cursor jsonb := NULL::jsonb;
  v_next_scope_status text := 'MATERIALISED';
  v_old_scope_bucket text := 'PENDING';
  v_new_scope_bucket text := 'PENDING';
  v_scope_pending_delta integer := 0;
  v_scope_ready_delta integer := 0;
  v_scope_failed_delta integer := 0;
  v_line_has_pending boolean := false;
  v_line_has_ready boolean := false;
  v_line_has_error boolean := false;
  v_source_build_run_id_text text := NULL::text;
  v_source_build_run_id uuid := NULL::uuid;
  v_source_change_seq bigint := NULL::bigint;
  v_session_version bigint := NULL::bigint;
  v_cursor_session_id_text text := NULL::text;
  v_cursor_candidate_id_text text := NULL::text;
  v_cursor_source_change_seq bigint := NULL::bigint;
  v_cursor_session_version bigint := NULL::bigint;
  v_cursor_source_ordinal bigint := 0;
  v_cursor_source_row_id uuid := NULL::uuid;
  v_source_rows_available integer := 0;
  v_source_rows_read integer := 0;
  v_source_rows_remaining_after_cursor integer := 0;
  v_source_page_count integer := 0;
  v_last_source_ordinal bigint := NULL::bigint;
  v_last_source_row_id uuid := NULL::uuid;
  v_full_source_rebuild boolean := false;
  v_source_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_pay_channel_scope text := 'ALL';
  v_distinct_source_change_seq_count integer := 0;
  v_distinct_session_version_count integer := 0;
  v_source_identity_json jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SESSION_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SESSION_ID_REQUIRED')::text;
  END IF;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_CANDIDATE_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_CANDIDATE_ID_REQUIRED')::text;
  END IF;

  IF to_regclass('public.banking_pay_workbench_candidate_source_lines') IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SOURCE_TABLE_MISSING'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SOURCE_TABLE_MISSING',
              'required_table', 'public.banking_pay_workbench_candidate_source_lines'
            )::text;
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SESSION_NOT_FOUND',
              'session_id', p_session_id::text
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SESSION_NOT_OPEN',
              'session_id', p_session_id::text,
              'status', v_session_row.status
            )::text;
  END IF;

  SELECT scope_row.status
  INTO v_scope_status
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = p_candidate_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_CANDIDATE_NOT_IN_SCOPE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_CANDIDATE_NOT_IN_SCOPE',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text
            )::text;
  END IF;

  IF p_cursor_json IS NOT NULL AND jsonb_typeof(p_cursor_json) = 'object' THEN
    v_source_build_run_id_text := NULLIF(BTRIM(COALESCE(
      p_cursor_json->>'source_build_run_id',
      p_cursor_json#>>'{source_build,source_build_run_id}',
      p_cursor_json#>>'{source_build,run_id}',
      ''
    )), '');

    v_cursor_session_id_text := NULLIF(BTRIM(COALESCE(
      p_cursor_json->>'session_id',
      p_cursor_json->>'workbench_session_id',
      p_cursor_json#>>'{workbench,session_id}',
      ''
    )), '');

    IF v_cursor_session_id_text IS NOT NULL THEN
      IF v_cursor_session_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_CURSOR_SESSION_ID_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_CURSOR_SESSION_ID_INVALID',
                  'session_id', p_session_id::text,
                  'candidate_id', p_candidate_id::text,
                  'cursor_session_id', v_cursor_session_id_text
                )::text;
      ELSIF v_cursor_session_id_text::uuid IS DISTINCT FROM p_session_id THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_CURSOR_SESSION_MISMATCH'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_CURSOR_SESSION_MISMATCH',
                  'session_id', p_session_id::text,
                  'candidate_id', p_candidate_id::text,
                  'cursor_session_id', v_cursor_session_id_text
                )::text;
      END IF;
    END IF;

    v_cursor_candidate_id_text := NULLIF(BTRIM(COALESCE(
      p_cursor_json->>'candidate_id',
      p_cursor_json#>>'{candidate,id}',
      ''
    )), '');

    IF v_cursor_candidate_id_text IS NOT NULL THEN
      IF v_cursor_candidate_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_CURSOR_CANDIDATE_ID_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_CURSOR_CANDIDATE_ID_INVALID',
                  'session_id', p_session_id::text,
                  'candidate_id', p_candidate_id::text,
                  'cursor_candidate_id', v_cursor_candidate_id_text
                )::text;
      ELSIF v_cursor_candidate_id_text::uuid IS DISTINCT FROM p_candidate_id THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_CURSOR_CANDIDATE_MISMATCH'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_CURSOR_CANDIDATE_MISMATCH',
                  'session_id', p_session_id::text,
                  'candidate_id', p_candidate_id::text,
                  'cursor_candidate_id', v_cursor_candidate_id_text
                )::text;
      END IF;
    END IF;

    IF COALESCE(p_cursor_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN
      v_cursor_source_change_seq := (p_cursor_json->>'source_change_seq')::bigint;
      v_source_change_seq := v_cursor_source_change_seq;
    ELSIF COALESCE(p_cursor_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$' THEN
      v_cursor_source_change_seq := (p_cursor_json->>'source_change_sequence')::bigint;
      v_source_change_seq := v_cursor_source_change_seq;
    ELSIF NULLIF(BTRIM(COALESCE(p_cursor_json->>'source_change_seq', p_cursor_json->>'source_change_sequence', '')), '') IS NOT NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_CURSOR_SOURCE_CHANGE_SEQ_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_CURSOR_SOURCE_CHANGE_SEQ_INVALID',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text,
                'cursor_source_change_seq', COALESCE(p_cursor_json->>'source_change_seq', p_cursor_json->>'source_change_sequence')
              )::text;
    END IF;

    IF COALESCE(p_cursor_json->>'session_version', '') ~ '^[0-9]{1,18}$' THEN
      v_cursor_session_version := (p_cursor_json->>'session_version')::bigint;
      v_session_version := v_cursor_session_version;
    ELSIF NULLIF(BTRIM(COALESCE(p_cursor_json->>'session_version', '')), '') IS NOT NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_CURSOR_SESSION_VERSION_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_CURSOR_SESSION_VERSION_INVALID',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text,
                'cursor_session_version', p_cursor_json->>'session_version'
              )::text;
    END IF;

    IF COALESCE(p_cursor_json->>'last_source_ordinal', '') ~ '^[0-9]{1,18}$' THEN
      v_cursor_source_ordinal := (p_cursor_json->>'last_source_ordinal')::bigint;
    ELSIF COALESCE(p_cursor_json->>'last_line_ordinal', '') ~ '^[0-9]{1,18}$' THEN
      v_cursor_source_ordinal := (p_cursor_json->>'last_line_ordinal')::bigint;
    ELSIF COALESCE(p_cursor_json->>'last_ordinal', '') ~ '^[0-9]{1,18}$' THEN
      v_cursor_source_ordinal := (p_cursor_json->>'last_ordinal')::bigint;
    ELSE
      v_cursor_source_ordinal := 0;
    END IF;

    IF COALESCE(p_cursor_json->>'last_source_row_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_cursor_source_row_id := (p_cursor_json->>'last_source_row_id')::uuid;
    ELSIF COALESCE(p_cursor_json->>'source_row_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_cursor_source_row_id := (p_cursor_json->>'source_row_id')::uuid;
    END IF;

    IF NULLIF(BTRIM(COALESCE(p_cursor_json->>'source_snapshot_run_id', '')), '') IS NOT NULL
       AND p_cursor_json->>'source_snapshot_run_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SNAPSHOT_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SNAPSHOT_INVALID',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text,
                'cursor_snapshot_run_id', p_cursor_json->>'source_snapshot_run_id'
              )::text;
    ELSIF NULLIF(BTRIM(COALESCE(p_cursor_json->>'source_snapshot_run_id', '')), '') IS NOT NULL
       AND (p_cursor_json->>'source_snapshot_run_id')::uuid IS DISTINCT FROM v_session_row.source_snapshot_run_id THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SNAPSHOT_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SNAPSHOT_MISMATCH',
                'session_id', p_session_id::text,
                'cursor_snapshot_run_id', p_cursor_json->>'source_snapshot_run_id',
                'session_snapshot_run_id', v_session_row.source_snapshot_run_id::text
              )::text;
    END IF;

    IF NULLIF(BTRIM(COALESCE(p_cursor_json->>'session_signature', '')), '') IS NOT NULL
       AND p_cursor_json->>'session_signature' IS DISTINCT FROM v_session_row.session_signature THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SESSION_SIGNATURE_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SESSION_SIGNATURE_MISMATCH',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text,
                'cursor_session_signature', p_cursor_json->>'session_signature',
                'session_signature', v_session_row.session_signature
              )::text;
    END IF;
  END IF;

  IF v_source_build_run_id_text IS NULL
     OR v_source_build_run_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SOURCE_BUILD_RUN_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SOURCE_BUILD_RUN_ID_REQUIRED',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text,
              'message', 'Line-work seed now reads persisted source rows and requires source_build_run_id in the cursor.'
            )::text;
  END IF;

  v_source_build_run_id := v_source_build_run_id_text::uuid;

  SELECT
    COUNT(*)::integer,
    COUNT(DISTINCT source_line.source_change_seq)::integer,
    COUNT(DISTINCT source_line.session_version)::integer,
    COALESCE(MIN(source_line.source_change_seq), v_source_change_seq),
    COALESCE(MIN(source_line.session_version), COALESCE(v_session_version, v_session_row.version)),
    COALESCE(BOOL_OR(
      source_line.refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
      OR UPPER(BTRIM(COALESCE(source_line.source_row_json->>'requested_refresh_scope_kind', ''))) = 'CANDIDATE_FULL_LIVE'
    ), false),
    COALESCE(MAX(source_line.refresh_scope_kind), 'CANDIDATE_FULL_LIVE'),
    COALESCE(MAX(source_line.pay_channel_scope), 'ALL')
  INTO v_source_rows_available,
       v_distinct_source_change_seq_count,
       v_distinct_session_version_count,
       v_source_change_seq,
       v_session_version,
       v_full_source_rebuild,
       v_source_refresh_scope_kind,
       v_pay_channel_scope
  FROM public.banking_pay_workbench_candidate_source_lines AS source_line
  WHERE source_line.session_id = p_session_id
    AND source_line.candidate_id = p_candidate_id
    AND source_line.source_build_run_id = v_source_build_run_id
    AND source_line.status = 'CURRENT';

  IF COALESCE(v_full_source_rebuild, false) THEN
    v_source_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
  END IF;

  IF COALESCE(v_source_rows_available, 0) = 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SOURCE_ROWS_MISSING'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SOURCE_ROWS_MISSING',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text,
              'source_build_run_id', v_source_build_run_id::text
            )::text;
  END IF;

  IF COALESCE(v_distinct_source_change_seq_count, 0) <> 1
     OR COALESCE(v_distinct_session_version_count, 0) <> 1 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SOURCE_IDENTITY_AMBIGUOUS'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SOURCE_IDENTITY_AMBIGUOUS',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text,
              'source_build_run_id', v_source_build_run_id::text,
              'distinct_source_change_seq_count', COALESCE(v_distinct_source_change_seq_count, 0),
              'distinct_session_version_count', COALESCE(v_distinct_session_version_count, 0)
            )::text;
  END IF;

  IF v_cursor_source_change_seq IS NOT NULL
     AND v_cursor_source_change_seq IS DISTINCT FROM v_source_change_seq THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SOURCE_CHANGE_SEQ_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SOURCE_CHANGE_SEQ_MISMATCH',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text,
              'source_build_run_id', v_source_build_run_id::text,
              'cursor_source_change_seq', v_cursor_source_change_seq,
              'source_row_source_change_seq', v_source_change_seq
            )::text;
  END IF;

  IF v_cursor_session_version IS NOT NULL
     AND v_cursor_session_version IS DISTINCT FROM v_session_version THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SESSION_VERSION_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SESSION_VERSION_MISMATCH',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text,
              'source_build_run_id', v_source_build_run_id::text,
              'cursor_session_version', v_cursor_session_version,
              'source_row_session_version', v_session_version
            )::text;
  END IF;

  IF v_session_version IS DISTINCT FROM COALESCE(v_session_row.version, 1) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SESSION_VERSION_STALE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SESSION_VERSION_STALE',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text,
              'source_build_run_id', v_source_build_run_id::text,
              'source_session_version', v_session_version,
              'current_session_version', COALESCE(v_session_row.version, 1)
            )::text;
  END IF;

  v_source_identity_json := jsonb_build_object(
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'session_version', v_session_version,
    'source_change_seq', v_source_change_seq,
    'source_build_run_id', v_source_build_run_id::text,
    'source_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
    'session_signature', v_session_row.session_signature
  );

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_line_seed_current_source_scope;
  CREATE TEMPORARY TABLE pg_temp._tmp_pay_wb_line_seed_current_source_scope ON COMMIT DROP AS
  SELECT
    source_line.id AS source_row_id,
    source_line.timesheet_id,
    source_line.line_key
  FROM public.banking_pay_workbench_candidate_source_lines AS source_line
  WHERE source_line.session_id = p_session_id
    AND source_line.candidate_id = p_candidate_id
    AND source_line.session_version = v_session_version
    AND source_line.source_change_seq = v_source_change_seq
    AND source_line.source_build_run_id = v_source_build_run_id
    AND source_line.status = 'CURRENT';

  IF COALESCE(v_cursor_source_ordinal, 0) <= 0 THEN
    WITH retirement_candidates AS (
      SELECT
        existing_line_work.id,
        existing_line_work.timesheet_id,
        existing_line_work.line_key,
        existing_line_work.line_ordinal,
        UPPER(BTRIM(COALESCE(existing_line_work.status, ''))) AS existing_status
      FROM public.banking_pay_workbench_candidate_line_work AS existing_line_work
      WHERE existing_line_work.session_id = p_session_id
        AND existing_line_work.candidate_id = p_candidate_id
        AND UPPER(BTRIM(COALESCE(existing_line_work.status, ''))) <> 'SKIPPED'
        AND (
          COALESCE(v_full_source_rebuild, false)
          OR (
            existing_line_work.timesheet_id IS NOT NULL
            AND EXISTS (
              SELECT 1
              FROM pg_temp._tmp_pay_wb_line_seed_current_source_scope AS source_scope
              WHERE source_scope.timesheet_id IS NOT DISTINCT FROM existing_line_work.timesheet_id
            )
          )
          OR (
            existing_line_work.timesheet_id IS NULL
            AND EXISTS (
              SELECT 1
              FROM pg_temp._tmp_pay_wb_line_seed_current_source_scope AS source_scope
              WHERE source_scope.timesheet_id IS NULL
            )
          )
        )
        AND NOT EXISTS (
          SELECT 1
          FROM pg_temp._tmp_pay_wb_line_seed_current_source_scope AS current_source
          WHERE current_source.timesheet_id IS NOT DISTINCT FROM existing_line_work.timesheet_id
            AND current_source.line_key = existing_line_work.line_key
        )
      FOR UPDATE
    ), retired_line_work AS (
      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
      SET status = 'SKIPPED',
          result_row_json = jsonb_strip_nulls(
            jsonb_build_object(
              'source_function', 'pay_workbench_candidate_line_work_seed',
              'source_kind', 'RETIRED_PREVIEW_LINE',
              'session_id', p_session_id::text,
              'session_version', v_session_version,
              'candidate_id', p_candidate_id::text,
              'line_work_id', line_work.id::text,
              'timesheet_id', CASE WHEN line_work.timesheet_id IS NULL THEN NULL ELSE line_work.timesheet_id::text END,
              'row_key', line_work.line_key,
              'line_key', line_work.line_key,
              'line_ordinal', line_work.line_ordinal,
              'section', 'internal_only',
              'target_section', 'internal_only',
              'presentation_section', 'INTERNAL_ONLY'
            )
            || jsonb_build_object(
              'readiness_state', 'SKIPPED',
              'row_processing_status', 'SKIPPED',
              'draftable', false,
              'selection_allowed', false,
              'is_ready_for_draft', false,
              'materialisation_suppressed', true,
              'materialised_no_visible_preview_row', true,
              'retired_reason', 'SOURCE_LINE_NO_LONGER_CURRENT',
              'retired_at_utc', v_now::text,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            )
          ),
          error_json = NULL::jsonb,
          updated_at_utc = v_now
      FROM retirement_candidates
      WHERE line_work.id = retirement_candidates.id
      RETURNING retirement_candidates.existing_status,
                retirement_candidates.timesheet_id,
                retirement_candidates.line_key
    ), retired_preview_rows AS (
      UPDATE public.banking_pay_workbench_preview_rows AS preview_row
      SET status = 'SUPERSEDED',
          selected = false,
          selection_state = 'SUPERSEDED',
          row_json = COALESCE(preview_row.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'materialisation_suppressed', true,
              'materialisation_suppressed_reason', 'SOURCE_LINE_NO_LONGER_CURRENT',
              'materialisation_suppressed_at_utc', v_now::text,
              'materialised_no_visible_preview_row', true,
              'retired_source_line_key', retired_line_work.line_key,
              'retired_at_utc', v_now::text,
              'retired_reason', 'SOURCE_LINE_NO_LONGER_CURRENT'
            ),
          updated_at_utc = v_now
      FROM retired_line_work
      WHERE preview_row.session_id = p_session_id
        AND preview_row.candidate_id = p_candidate_id
        AND preview_row.row_key = retired_line_work.line_key
        AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) <> 'SUPERSEDED'
      RETURNING preview_row.id
    ), retired_counts AS (
      SELECT
        COUNT(*)::integer AS retired_line_count,
        COUNT(*) FILTER (WHERE retired_line_work.existing_status IN ('PENDING', 'QUEUED', 'RUNNING', 'PROCESSING', 'IN_PROGRESS', 'CLAIMED', 'RETRY', 'WAITING_RETRY', 'SCHEDULED', 'RUNNABLE', 'DIRTY'))::integer AS retired_pending_count,
        COUNT(*) FILTER (WHERE retired_line_work.existing_status = 'READY')::integer AS retired_ready_count,
        COUNT(*) FILTER (WHERE retired_line_work.existing_status IN ('MATERIALISED', 'MATERIALIZED'))::integer AS retired_materialised_count,
        COUNT(*) FILTER (WHERE retired_line_work.existing_status IN ('ERROR', 'FAILED'))::integer AS retired_failed_count,
        COUNT(*) FILTER (WHERE retired_line_work.existing_status NOT IN ('PENDING', 'QUEUED', 'RUNNING', 'PROCESSING', 'IN_PROGRESS', 'CLAIMED', 'RETRY', 'WAITING_RETRY', 'SCHEDULED', 'RUNNABLE', 'DIRTY', 'READY', 'MATERIALISED', 'MATERIALIZED', 'ERROR', 'FAILED'))::integer AS retired_other_count
      FROM retired_line_work
    ), retired_preview_counts AS (
      SELECT COUNT(*)::integer AS retired_preview_row_count
      FROM retired_preview_rows
    )
    SELECT retired_counts.retired_line_count,
           retired_counts.retired_pending_count,
           retired_counts.retired_ready_count,
           retired_counts.retired_materialised_count,
           retired_counts.retired_failed_count,
           retired_counts.retired_other_count,
           retired_preview_counts.retired_preview_row_count
    INTO v_retired_line_count,
         v_retired_pending_count,
         v_retired_ready_count,
         v_retired_materialised_count,
         v_retired_failed_count,
         v_retired_other_count,
         v_retired_preview_row_count
    FROM retired_counts
    CROSS JOIN retired_preview_counts;

    v_superseded_preview_row_count := COALESCE(v_superseded_preview_row_count, 0) + COALESCE(v_retired_preview_row_count, 0);
  END IF;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_line_seed_source_page;
  CREATE TEMPORARY TABLE pg_temp._tmp_pay_wb_line_seed_source_page ON COMMIT DROP AS
  SELECT
    source_line.id AS source_row_id,
    source_line.session_id,
    source_line.candidate_id,
    source_line.session_version,
    source_line.source_change_seq,
    source_line.source_build_run_id,
    source_line.source_ordinal,
    source_line.line_key,
    source_line.parent_line_key,
    source_line.split_suffix,
    source_line.timesheet_id,
    source_line.section,
    source_line.source_row_json,
    source_line.economic_key_json,
    source_line.contract_json,
    source_line.pay_channel_scope,
    source_line.refresh_scope_kind
  FROM public.banking_pay_workbench_candidate_source_lines AS source_line
  WHERE source_line.session_id = p_session_id
    AND source_line.candidate_id = p_candidate_id
    AND source_line.session_version = v_session_version
    AND source_line.source_change_seq = v_source_change_seq
    AND source_line.source_build_run_id = v_source_build_run_id
    AND source_line.status = 'CURRENT'
    AND (
      source_line.source_ordinal > COALESCE(v_cursor_source_ordinal, 0)
      OR (
        source_line.source_ordinal = COALESCE(v_cursor_source_ordinal, 0)
        AND v_cursor_source_row_id IS NOT NULL
        AND source_line.id > v_cursor_source_row_id
      )
    )
  ORDER BY source_line.source_ordinal, source_line.id
  LIMIT (v_limit + 1);

  SELECT COUNT(*)::integer
  INTO v_source_page_count
  FROM pg_temp._tmp_pay_wb_line_seed_source_page AS page_count_rows;

  v_has_more := COALESCE(v_source_page_count, 0) > v_limit;

  SELECT COUNT(*)::integer
  INTO v_source_rows_remaining_after_cursor
  FROM public.banking_pay_workbench_candidate_source_lines AS remaining_source_line
  WHERE remaining_source_line.session_id = p_session_id
    AND remaining_source_line.candidate_id = p_candidate_id
    AND remaining_source_line.session_version = v_session_version
    AND remaining_source_line.source_change_seq = v_source_change_seq
    AND remaining_source_line.source_build_run_id = v_source_build_run_id
    AND remaining_source_line.status = 'CURRENT'
    AND (
      remaining_source_line.source_ordinal > COALESCE(v_cursor_source_ordinal, 0)
      OR (
        remaining_source_line.source_ordinal = COALESCE(v_cursor_source_ordinal, 0)
        AND v_cursor_source_row_id IS NOT NULL
        AND remaining_source_line.id > v_cursor_source_row_id
      )
    );

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_line_seed_selected_source_page;
  CREATE TEMPORARY TABLE pg_temp._tmp_pay_wb_line_seed_selected_source_page ON COMMIT DROP AS
  SELECT page_rows.*
  FROM pg_temp._tmp_pay_wb_line_seed_source_page AS page_rows
  ORDER BY page_rows.source_ordinal, page_rows.source_row_id
  LIMIT v_limit;

  SELECT COUNT(*)::integer,
         MAX(selected_rows.source_ordinal),
         (array_agg(selected_rows.source_row_id ORDER BY selected_rows.source_ordinal DESC, selected_rows.source_row_id DESC))[1]
  INTO v_source_rows_read,
       v_last_source_ordinal,
       v_last_source_row_id
  FROM pg_temp._tmp_pay_wb_line_seed_selected_source_page AS selected_rows;

  IF COALESCE(v_has_more, false) THEN
    v_next_cursor := jsonb_build_object(
      'source_build_run_id', v_source_build_run_id::text,
      'source_change_seq', v_source_change_seq,
      'source_change_sequence', v_source_change_seq,
      'session_version', v_session_version,
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'source_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
      'session_signature', v_session_row.session_signature,
      'last_source_ordinal', COALESCE(v_last_source_ordinal, v_cursor_source_ordinal, 0),
      'last_line_ordinal', COALESCE(v_last_source_ordinal, v_cursor_source_ordinal, 0),
      'last_source_row_id', CASE WHEN v_last_source_row_id IS NULL THEN NULL ELSE v_last_source_row_id::text END
    );
  ELSE
    v_next_cursor := NULL::jsonb;
  END IF;

  WITH selected_rows AS (
    SELECT selected_source.*
    FROM pg_temp._tmp_pay_wb_line_seed_selected_source_page AS selected_source
    ORDER BY selected_source.source_ordinal, selected_source.source_row_id
  ), existing_rows AS (
    SELECT
      selected_rows.timesheet_id,
      selected_rows.line_key,
      existing_line.status AS existing_status
    FROM selected_rows
    LEFT JOIN public.banking_pay_workbench_candidate_line_work AS existing_line
      ON existing_line.session_id = p_session_id
     AND existing_line.candidate_id = p_candidate_id
     AND existing_line.timesheet_id IS NOT DISTINCT FROM selected_rows.timesheet_id
     AND existing_line.line_key = selected_rows.line_key
  ), upserted_line_work AS (
    INSERT INTO public.banking_pay_workbench_candidate_line_work (
      session_id,
      candidate_id,
      timesheet_id,
      line_key,
      line_ordinal,
      status,
      work_payload_json,
      result_row_json,
      error_json,
      created_at_utc,
      updated_at_utc
    )
    SELECT
      p_session_id,
      selected_rows.candidate_id,
      selected_rows.timesheet_id,
      selected_rows.line_key,
      selected_rows.source_ordinal,
      'PENDING',
      jsonb_strip_nulls(
        jsonb_build_object(
          'source_function', 'pay_workbench_candidate_line_work_seed',
          'source_kind', 'VALID_PREVIEW_LINE',
          'session_id', p_session_id::text,
          'session_version', v_session_version,
          'candidate_id', selected_rows.candidate_id::text,
          'source_row_id', selected_rows.source_row_id::text,
          'source_build_run_id', selected_rows.source_build_run_id::text,
          'source_change_seq', selected_rows.source_change_seq,
          'source_ordinal', selected_rows.source_ordinal,
          'line_key', selected_rows.line_key,
          'line_ordinal', selected_rows.source_ordinal
        )
        || jsonb_build_object(
          'target_section', selected_rows.section,
          'section', selected_rows.section,
          'line_json', COALESCE(selected_rows.source_row_json, '{}'::jsonb),
          'economic_key', COALESCE(selected_rows.economic_key_json, '{}'::jsonb),
          'preview_contract', COALESCE(selected_rows.contract_json, '{}'::jsonb),
          'pay_channel_scope', selected_rows.pay_channel_scope,
          'refresh_scope_kind', selected_rows.refresh_scope_kind,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
        )
      ),
      NULL::jsonb,
      NULL::jsonb,
      v_now,
      v_now
    FROM selected_rows
    ON CONFLICT (session_id, candidate_id, (COALESCE(timesheet_id, '00000000-0000-0000-0000-000000000000'::uuid)), line_key)
    DO UPDATE
    SET line_ordinal = EXCLUDED.line_ordinal,
        work_payload_json = EXCLUDED.work_payload_json,
        status = CASE
          WHEN UPPER(BTRIM(COALESCE(public.banking_pay_workbench_candidate_line_work.status, ''))) = 'SKIPPED' THEN
            CASE
              WHEN UPPER(BTRIM(COALESCE(public.banking_pay_workbench_candidate_line_work.result_row_json->>'source_kind', ''))) = 'RETIRED_PREVIEW_LINE'
                OR public.banking_pay_workbench_candidate_line_work.work_payload_json IS DISTINCT FROM EXCLUDED.work_payload_json
                OR public.banking_pay_workbench_candidate_line_work.result_row_json IS NULL
                THEN EXCLUDED.status
              ELSE public.banking_pay_workbench_candidate_line_work.status
            END
          WHEN public.banking_pay_workbench_candidate_line_work.work_payload_json IS DISTINCT FROM EXCLUDED.work_payload_json
            OR UPPER(BTRIM(COALESCE(public.banking_pay_workbench_candidate_line_work.status, ''))) IN ('ERROR', 'FAILED')
            THEN EXCLUDED.status
          ELSE public.banking_pay_workbench_candidate_line_work.status
        END,
        result_row_json = CASE
          WHEN UPPER(BTRIM(COALESCE(public.banking_pay_workbench_candidate_line_work.status, ''))) = 'SKIPPED' THEN
            CASE
              WHEN UPPER(BTRIM(COALESCE(public.banking_pay_workbench_candidate_line_work.result_row_json->>'source_kind', ''))) = 'RETIRED_PREVIEW_LINE'
                OR public.banking_pay_workbench_candidate_line_work.work_payload_json IS DISTINCT FROM EXCLUDED.work_payload_json
                OR public.banking_pay_workbench_candidate_line_work.result_row_json IS NULL
                THEN NULL::jsonb
              ELSE public.banking_pay_workbench_candidate_line_work.result_row_json
            END
          WHEN public.banking_pay_workbench_candidate_line_work.work_payload_json IS DISTINCT FROM EXCLUDED.work_payload_json
            OR UPPER(BTRIM(COALESCE(public.banking_pay_workbench_candidate_line_work.status, ''))) IN ('ERROR', 'FAILED')
            THEN NULL::jsonb
          ELSE public.banking_pay_workbench_candidate_line_work.result_row_json
        END,
        error_json = EXCLUDED.error_json,
        updated_at_utc = v_now
    RETURNING public.banking_pay_workbench_candidate_line_work.timesheet_id,
              public.banking_pay_workbench_candidate_line_work.line_key,
              public.banking_pay_workbench_candidate_line_work.status
  ), counted_changes AS (
    SELECT
      upserted_line_work.status,
      existing_rows.existing_status
    FROM upserted_line_work
    LEFT JOIN existing_rows
      ON existing_rows.timesheet_id IS NOT DISTINCT FROM upserted_line_work.timesheet_id
     AND existing_rows.line_key = upserted_line_work.line_key
  )
  SELECT COUNT(*)::integer,
         COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(counted_changes.status, ''))) = 'ERROR')::integer,
         COUNT(*) FILTER (WHERE counted_changes.existing_status IS NULL AND UPPER(BTRIM(COALESCE(counted_changes.status, ''))) = 'PENDING')::integer,
         COUNT(*) FILTER (WHERE counted_changes.existing_status IS NULL AND UPPER(BTRIM(COALESCE(counted_changes.status, ''))) = 'ERROR')::integer,
         COUNT(*) FILTER (WHERE counted_changes.existing_status IS NULL)::integer,
         COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(counted_changes.status, ''))) = 'PENDING' AND (counted_changes.existing_status IS NULL OR UPPER(BTRIM(COALESCE(counted_changes.existing_status, ''))) <> 'PENDING'))::integer,
         COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(counted_changes.status, ''))) = 'PENDING' AND UPPER(BTRIM(COALESCE(counted_changes.existing_status, ''))) = 'PENDING')::integer,
         COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(counted_changes.status, ''))) = 'PENDING' AND UPPER(BTRIM(COALESCE(counted_changes.existing_status, ''))) = 'READY')::integer,
         COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(counted_changes.status, ''))) = 'PENDING' AND UPPER(BTRIM(COALESCE(counted_changes.existing_status, ''))) IN ('MATERIALISED', 'MATERIALIZED'))::integer,
         COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(counted_changes.status, ''))) = 'PENDING' AND UPPER(BTRIM(COALESCE(counted_changes.existing_status, ''))) IN ('ERROR', 'FAILED'))::integer
  INTO v_seeded_count,
       v_error_count,
       v_new_pending_count,
       v_new_error_count,
       v_new_line_count,
       v_pending_transition_count,
       v_requeued_pending_count,
       v_ready_to_pending_count,
       v_materialised_to_pending_count,
       v_failed_to_pending_count
  FROM counted_changes;

  SELECT
    EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_candidate_line_work AS post_seed_error_line
      WHERE post_seed_error_line.session_id = p_session_id
        AND post_seed_error_line.candidate_id = p_candidate_id
        AND UPPER(BTRIM(COALESCE(post_seed_error_line.status, ''))) IN ('ERROR', 'FAILED')
    ),
    EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_candidate_line_work AS post_seed_pending_line
      WHERE post_seed_pending_line.session_id = p_session_id
        AND post_seed_pending_line.candidate_id = p_candidate_id
        AND UPPER(BTRIM(COALESCE(post_seed_pending_line.status, ''))) = 'PENDING'
    ),
    EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_candidate_line_work AS post_seed_ready_line
      WHERE post_seed_ready_line.session_id = p_session_id
        AND post_seed_ready_line.candidate_id = p_candidate_id
        AND UPPER(BTRIM(COALESCE(post_seed_ready_line.status, ''))) = 'READY'
    )
  INTO v_line_has_error,
       v_line_has_pending,
       v_line_has_ready;

  v_next_scope_status := CASE
    WHEN COALESCE(v_error_count, 0) > 0 OR COALESCE(v_line_has_error, false) THEN 'ERROR'
    WHEN COALESCE(v_has_more, false) OR COALESCE(v_line_has_pending, false) THEN 'LINE_WORK_PENDING'
    WHEN COALESCE(v_line_has_ready, false) THEN 'LINE_WORK_READY'
    ELSE 'MATERIALISED'
  END;

  v_old_scope_bucket := CASE
    WHEN UPPER(BTRIM(COALESCE(v_scope_status, ''))) IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY') THEN 'READY'
    WHEN UPPER(BTRIM(COALESCE(v_scope_status, ''))) IN ('ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR') THEN 'FAILED'
    ELSE 'PENDING'
  END;

  v_new_scope_bucket := CASE
    WHEN UPPER(BTRIM(COALESCE(v_next_scope_status, ''))) IN ('READY', 'MATERIALISED', 'MATERIALIZED') THEN 'READY'
    WHEN UPPER(BTRIM(COALESCE(v_next_scope_status, ''))) IN ('ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR') THEN 'FAILED'
    ELSE 'PENDING'
  END;

  v_scope_pending_delta := CASE WHEN v_new_scope_bucket = 'PENDING' THEN 1 ELSE 0 END
    - CASE WHEN v_old_scope_bucket = 'PENDING' THEN 1 ELSE 0 END;
  v_scope_ready_delta := CASE WHEN v_new_scope_bucket = 'READY' THEN 1 ELSE 0 END
    - CASE WHEN v_old_scope_bucket = 'READY' THEN 1 ELSE 0 END;
  v_scope_failed_delta := CASE WHEN v_new_scope_bucket = 'FAILED' THEN 1 ELSE 0 END
    - CASE WHEN v_old_scope_bucket = 'FAILED' THEN 1 ELSE 0 END;

  UPDATE public.banking_pay_workbench_session_scope AS scope_update
  SET status = v_next_scope_status,
      dirty = v_next_scope_status NOT IN ('MATERIALISED', 'MATERIALIZED', 'READY'),
      error_json = CASE
        WHEN COALESCE(v_error_count, 0) > 0 THEN jsonb_build_object(
          'code', 'LINE_WORK_SEED_ERRORS',
          'error_count', v_error_count,
          'source_identity', v_source_identity_json
        )
        ELSE NULL::jsonb
      END,
      updated_at_utc = v_now
  WHERE scope_update.session_id = p_session_id
    AND scope_update.candidate_id = p_candidate_id;

  UPDATE public.banking_pay_workbench_sessions AS session_update
  SET line_units_total = GREATEST(COALESCE(session_update.line_units_total, 0) + COALESCE(v_new_line_count, 0), 0),
      line_units_pending = GREATEST(COALESCE(session_update.line_units_pending, 0) + COALESCE(v_pending_transition_count, 0) - COALESCE(v_retired_pending_count, 0), 0),
      line_units_ready = GREATEST(COALESCE(session_update.line_units_ready, 0) - COALESCE(v_ready_to_pending_count, 0) - COALESCE(v_retired_ready_count, 0), 0),
      line_units_failed = GREATEST(COALESCE(session_update.line_units_failed, 0) + COALESCE(v_new_error_count, 0) - COALESCE(v_failed_to_pending_count, 0) - COALESCE(v_retired_failed_count, 0), 0),
      scope_pending_count = GREATEST(COALESCE(session_update.scope_pending_count, 0) + COALESCE(v_scope_pending_delta, 0), 0),
      scope_ready_count = GREATEST(COALESCE(session_update.scope_ready_count, 0) + COALESCE(v_scope_ready_delta, 0), 0),
      scope_failed_count = GREATEST(COALESCE(session_update.scope_failed_count, 0) + COALESCE(v_scope_failed_delta, 0), 0),
      progress_state = CASE
        WHEN COALESCE(v_error_count, 0) > 0 OR COALESCE(v_line_has_error, false) THEN 'ERROR'
        WHEN COALESCE(v_has_more, false) OR COALESCE(v_line_has_pending, false) THEN 'LINE_WORK_SEEDED'
        WHEN COALESCE(v_line_has_ready, false) THEN 'MATERIALISING_PREVIEW_ROWS'
        ELSE 'REFRESHING_CANDIDATES'
      END,
      progress_json = COALESCE(session_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'phase', 'LINE_WORK_SEEDED_FROM_SOURCE_ROWS',
          'last_line_seeded_count', COALESCE(v_seeded_count, 0),
          'last_line_seed_error_count', COALESCE(v_error_count, 0),
          'last_line_seed_has_more', COALESCE(v_has_more, false),
          'last_line_seeded_at_utc', v_now::text,
          'last_line_seed_source_build_run_id', v_source_build_run_id::text,
          'last_line_seed_source_change_seq', v_source_change_seq,
          'last_line_seed_source_rows_read', COALESCE(v_source_rows_read, 0),
          'last_line_seed_source_rows_available', COALESCE(v_source_rows_available, 0),
          'last_scope_old_status', UPPER(BTRIM(COALESCE(v_scope_status, 'PENDING'))),
          'last_scope_new_status', v_next_scope_status
        )
        || jsonb_build_object(
          'last_scope_pending_delta', COALESCE(v_scope_pending_delta, 0),
          'last_scope_ready_delta', COALESCE(v_scope_ready_delta, 0),
          'last_scope_failed_delta', COALESCE(v_scope_failed_delta, 0),
          'status_text', CASE
            WHEN COALESCE(v_error_count, 0) > 0 THEN 'Payment preview could not be prepared for this candidate.'
            ELSE 'Preparing payment preview.'
          END,
          'next_recommended_action', CASE
            WHEN COALESCE(v_error_count, 0) > 0 OR COALESCE(v_line_has_error, false) THEN 'REVIEW_ERRORS'
            WHEN COALESCE(v_has_more, false) THEN 'SEED_LINE_WORK_CHUNK'
            WHEN COALESCE(v_line_has_pending, false) THEN 'PROCESS_LINE_WORK_CHUNK'
            WHEN COALESCE(v_line_has_ready, false) THEN 'MATERIALISE_PREVIEW_ROWS_CHUNK'
            ELSE 'WAIT_FOR_WORKER'
          END,
          'terminal_readiness_deferred', true,
          'terminal_readiness_deferred_to', 'pay_workbench_complete_job'
        ),
      progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
      progress_updated_at_utc = v_now,
      updated_at_utc = v_now
  WHERE session_update.id = p_session_id;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'candidate_state', COALESCE(v_scope_status, 'PENDING'),
    'limit', v_limit,
    'seeded_count', COALESCE(v_seeded_count, 0),
    'page_count', COALESCE(v_seeded_count, 0),
    'line_work_seeded_count', COALESCE(v_seeded_count, 0),
    'error_count', COALESCE(v_error_count, 0),
    'line_work_error_count', COALESCE(v_error_count, 0),
    'source_rows_available', COALESCE(v_source_rows_available, 0),
    'source_rows_read', COALESCE(v_source_rows_read, 0),
    'source_rows_remaining_after_cursor_count', COALESCE(v_source_rows_remaining_after_cursor, 0),
    'next_cursor', v_next_cursor,
    'next_cursor_json', v_next_cursor
  )
  || jsonb_build_object(
    'has_more', COALESCE(v_has_more, false),
    'pending', COALESCE(v_has_more, false) OR COALESCE(v_line_has_pending, false) OR COALESCE(v_line_has_ready, false),
    'ready', COALESCE(v_has_more, false) IS NOT TRUE
      AND COALESCE(v_error_count, 0) = 0
      AND COALESCE(v_line_has_error, false) IS NOT TRUE
      AND COALESCE(v_line_has_pending, false) IS NOT TRUE
      AND COALESCE(v_line_has_ready, false) IS NOT TRUE,
    'scope_status', v_next_scope_status,
    'source_build_run_id', v_source_build_run_id::text,
    'source_change_seq', v_source_change_seq,
    'session_version', v_session_version,
    'refresh_scope_kind', v_source_refresh_scope_kind,
    'pay_channel_scope', v_pay_channel_scope,
    'source_table', 'public.banking_pay_workbench_candidate_source_lines',
    'source', 'PERSISTED_SOURCE_LINES',
    'count_unknown', false
  )
  || jsonb_build_object(
    'scope_transition', jsonb_build_object(
      'old_status', UPPER(BTRIM(COALESCE(v_scope_status, 'PENDING'))),
      'new_status', v_next_scope_status,
      'old_bucket', v_old_scope_bucket,
      'new_bucket', v_new_scope_bucket,
      'pending_delta', COALESCE(v_scope_pending_delta, 0),
      'ready_delta', COALESCE(v_scope_ready_delta, 0),
      'failed_delta', COALESCE(v_scope_failed_delta, 0)
    ),
    'line_work_state', jsonb_build_object(
      'seeded_count', COALESCE(v_seeded_count, 0),
      'error_count', COALESCE(v_error_count, 0),
      'new_pending_count', COALESCE(v_new_pending_count, 0),
      'new_error_count', COALESCE(v_new_error_count, 0),
      'new_line_count', COALESCE(v_new_line_count, 0),
      'pending_transition_count', COALESCE(v_pending_transition_count, 0),
      'requeued_pending_count', COALESCE(v_requeued_pending_count, 0),
      'ready_to_pending_count', COALESCE(v_ready_to_pending_count, 0),
      'failed_to_pending_count', COALESCE(v_failed_to_pending_count, 0),
      'retired_line_count', COALESCE(v_retired_line_count, 0),
      'retired_pending_count', COALESCE(v_retired_pending_count, 0),
      'retired_ready_count', COALESCE(v_retired_ready_count, 0),
      'retired_materialised_count', COALESCE(v_retired_materialised_count, 0),
      'retired_failed_count', COALESCE(v_retired_failed_count, 0),
      'retired_other_count', COALESCE(v_retired_other_count, 0),
      'superseded_preview_row_count', COALESCE(v_superseded_preview_row_count, 0),
      'post_seed_has_error', COALESCE(v_line_has_error, false),
      'post_seed_has_pending', COALESCE(v_line_has_pending, false),
      'post_seed_has_ready', COALESCE(v_line_has_ready, false),
      'post_seed_scope_status', v_next_scope_status,
      'source', 'PERSISTED_SOURCE_LINES',
      'count_unknown', false
    ),
    'source_identity', v_source_identity_json
  );
END;
$function$;

-- pay_workbench_candidate_source_build_chunk(uuid,uuid,jsonb,jsonb,integer)
CREATE OR REPLACE FUNCTION public.pay_workbench_candidate_source_build_chunk(p_session_id uuid, p_candidate_id uuid, p_cursor_json jsonb DEFAULT NULL::jsonb, p_payload_json jsonb DEFAULT '{}'::jsonb, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "plpgsql_check.mode" TO 'disabled'
AS $function$
DECLARE
  v_profile integer := 1;
  v_stage text := pg_catalog.upper(pg_catalog.btrim(COALESCE(
    p_payload_json->>'private_stage',
    p_cursor_json->>'private_stage',
    p_cursor_json->>'cursor_kind',''
  )));
  v_cursor jsonb := COALESCE(p_cursor_json,'{}'::jsonb);
  v_result jsonb := '{}'::jsonb;
  v_previous_token text;
  v_next_token text;
  v_step integer := 0;
  v_started timestamptz := clock_timestamp();
BEGIN
  BEGIN
    v_profile := COALESCE(
      NULLIF(pg_catalog.current_setting('cloudtms.pay_workbench_execution_profile_version',true),'')::integer,
      1
    );
  EXCEPTION WHEN OTHERS THEN
    v_profile := 1;
  END;
  IF v_profile NOT IN (1,2) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_EXECUTION_PROFILE_INVALID' USING ERRCODE='P0001';
  END IF;

  v_result := private.pay_workbench_candidate_source_build_chunk_legacy_v1(
    p_session_id,p_candidate_id,v_cursor,p_payload_json,p_limit
  );

  IF v_profile=1
     OR v_stage <> 'WORKSPACE_FACT'
     OR pg_catalog.upper(COALESCE(v_result->>'private_stage','')) <> 'WORKSPACE_FACT'
     OR COALESCE((v_result->>'has_more')::boolean,false) IS NOT TRUE THEN
    RETURN v_result || jsonb_build_object(
      'execution_profile_version',v_profile,
      'packed_internal_steps',1
    );
  END IF;

  v_step := 1;
  WHILE v_step < 4
    AND clock_timestamp() < v_started + interval '2.5 seconds'
    AND pg_catalog.upper(COALESCE(v_result->>'private_stage',''))='WORKSPACE_FACT'
    AND COALESCE((v_result->>'has_more')::boolean,false)
  LOOP
    v_cursor := COALESCE(v_result->'next_cursor_json','{}'::jsonb);
    v_previous_token := pg_catalog.encode(
      extensions.digest(pg_catalog.convert_to(
        pg_catalog.concat_ws('|',v_result->>'private_stage',v_cursor::text),'UTF8'
      ),'sha256'),'hex'
    );
    v_result := private.pay_workbench_candidate_source_build_chunk_legacy_v1(
      p_session_id,p_candidate_id,v_cursor,p_payload_json,p_limit
    );
    v_step := v_step + 1;
    v_next_token := pg_catalog.encode(
      extensions.digest(pg_catalog.convert_to(
        pg_catalog.concat_ws('|',v_result->>'private_stage',COALESCE(v_result->'next_cursor_json','{}'::jsonb)::text),'UTF8'
      ),'sha256'),'hex'
    );
    IF v_next_token=v_previous_token
       AND COALESCE((v_result->>'has_more')::boolean,false) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_MATERIAL_ATTEMPT_NO_PROGRESS'
        USING ERRCODE='P0001',DETAIL=jsonb_build_object(
          'code','PAY_WORKBENCH_MATERIAL_ATTEMPT_NO_PROGRESS',
          'private_stage',v_result->>'private_stage'
        )::text;
    END IF;
  END LOOP;

  RETURN v_result || jsonb_build_object(
    'execution_profile_version',v_profile,
    'packed_internal_steps',v_step
  );
END;
$function$;

-- pay_workbench_case_resolution_carry_status_get_v1(uuid,uuid)
CREATE OR REPLACE FUNCTION public.pay_workbench_case_resolution_carry_status_get_v1(p_target_session_id uuid, p_candidate_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  IF p_target_session_id IS NULL THEN
    RAISE EXCEPTION 'WORKBENCH_CASE_RESOLUTION_CARRY_TARGET_REQUIRED'
      USING ERRCODE = '22023';
  END IF;

  SELECT jsonb_build_object(
    'ok', true,
    'target_session_id', p_target_session_id,
    'candidate_id', p_candidate_id,
    'total_count', count(*),
    'pending_count', count(*) FILTER (WHERE status = 'PENDING'),
    'carried_count', count(*) FILTER (WHERE status = 'CARRIED'),
    'stale_count', count(*) FILTER (WHERE status = 'STALE'),
    'incompatible_count', count(*) FILTER (WHERE status = 'INCOMPATIBLE'),
    'superseded_count', count(*) FILTER (WHERE status = 'SUPERSEDED'),
    'carry_state', CASE
      WHEN count(*) FILTER (WHERE status = 'PENDING') > 0 THEN 'DEFERRED'
      WHEN count(*) FILTER (WHERE status IN ('STALE', 'INCOMPATIBLE')) > 0
        THEN 'REVIEW_REQUIRED'
      WHEN count(*) FILTER (WHERE status = 'CARRIED') > 0 THEN 'CARRIED'
      ELSE 'NOT_REQUIRED'
    END
  )
  INTO v_result
  FROM public.banking_pay_workbench_case_resolution_carry_registrations
  WHERE target_session_id = p_target_session_id
    AND (p_candidate_id IS NULL OR candidate_id = p_candidate_id);

  RETURN v_result;
END;
$function$;

-- pay_workbench_case_resolution_origin_backfill_v1(uuid,integer,boolean)
CREATE OR REPLACE FUNCTION public.pay_workbench_case_resolution_origin_backfill_v1(p_after_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 500, p_apply boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 500), 1), 1000);
  v_scanned_count integer := 0;
  v_valid_count integer := 0;
  v_updated_count integer := 0;
  v_invalid_count integer := 0;
  v_unresolved_total_count integer := 0;
  v_next_cursor uuid := NULL::uuid;
  v_has_more boolean := false;
  v_complete boolean := false;
  v_invalid_samples jsonb := '[]'::jsonb;
BEGIN
  DROP TABLE IF EXISTS pg_temp._bpay_resolution_origin_backfill_page;
  CREATE TEMP TABLE _bpay_resolution_origin_backfill_page ON COMMIT DROP AS
  WITH page_rows AS (
    SELECT resolution_row.*,
           current_session.actor_user_id AS current_actor_user_id,
           current_session.pay_date AS current_session_pay_date,
           NULLIF(BTRIM(COALESCE(resolution_row.payload_json->>'resolution_origin_session_id', '')), '') AS payload_origin_session_id_text,
           NULLIF(BTRIM(COALESCE(resolution_row.payload_json->>'source_session_id', '')), '') AS payload_source_session_id_text,
           NULLIF(BTRIM(COALESCE(resolution_row.payload_json->>'resolution_origin_pay_date', '')), '') AS payload_origin_pay_date_text,
           NULLIF(BTRIM(COALESCE(
             resolution_row.payload_json->>'resolution_origin_source_basis_fingerprint',
             resolution_row.source_basis_fingerprint,
             ''
           )), '') AS derived_origin_fingerprint
    FROM public.banking_pay_workbench_session_case_resolutions AS resolution_row
    JOIN public.banking_pay_workbench_sessions AS current_session
      ON current_session.id = resolution_row.session_id
    WHERE (
      resolution_row.resolution_origin_session_id IS NULL
      OR resolution_row.resolution_origin_pay_date IS NULL
    )
      AND (p_after_id IS NULL OR resolution_row.id > p_after_id)
    ORDER BY resolution_row.id
    LIMIT v_limit
  ),
  derived_rows AS (
    SELECT page_row.*,
           CASE
             WHEN page_row.payload_origin_pay_date_text IS NOT NULL
                  AND page_row.payload_origin_pay_date_text ~ '^\d{4}-\d{2}-\d{2}$'
                  AND to_char(to_date(page_row.payload_origin_pay_date_text, 'YYYY-MM-DD'), 'YYYY-MM-DD') = page_row.payload_origin_pay_date_text
               THEN to_date(page_row.payload_origin_pay_date_text, 'YYYY-MM-DD')
             ELSE NULL::date
           END AS derived_payload_origin_pay_date,
           CASE
             WHEN page_row.payload_origin_session_id_text IS NOT NULL
                  AND page_row.payload_origin_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
               THEN page_row.payload_origin_session_id_text::uuid
             WHEN page_row.payload_origin_session_id_text IS NOT NULL
               THEN NULL::uuid
             WHEN page_row.payload_source_session_id_text IS NOT NULL
                  AND page_row.payload_source_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
               THEN page_row.payload_source_session_id_text::uuid
             WHEN page_row.payload_source_session_id_text IS NOT NULL
               THEN NULL::uuid
             ELSE page_row.session_id
           END AS derived_origin_session_id
    FROM page_rows AS page_row
  )
  SELECT derived_row.id,
         derived_row.session_id,
         derived_row.resolution_identity_key,
         derived_row.current_actor_user_id,
         derived_row.current_session_pay_date,
         derived_row.payload_origin_session_id_text,
         derived_row.payload_source_session_id_text,
         derived_row.derived_origin_session_id,
         origin_session.actor_user_id AS origin_actor_user_id,
         origin_session.pay_date AS origin_pay_date,
         derived_row.payload_origin_pay_date_text,
         derived_row.derived_payload_origin_pay_date,
         derived_row.derived_origin_fingerprint,
         CASE
           WHEN derived_row.payload_origin_session_id_text IS NOT NULL
                AND derived_row.payload_origin_session_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             THEN 'ORIGIN_SESSION_ID_INVALID'
           WHEN derived_row.payload_origin_session_id_text IS NULL
                AND derived_row.payload_source_session_id_text IS NOT NULL
                AND derived_row.payload_source_session_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             THEN 'SOURCE_SESSION_ID_INVALID'
           WHEN derived_row.derived_origin_session_id IS NULL THEN 'ORIGIN_SESSION_UNRESOLVED'
           WHEN origin_session.id IS NULL THEN 'ORIGIN_SESSION_NOT_FOUND'
           WHEN origin_session.actor_user_id IS DISTINCT FROM derived_row.current_actor_user_id THEN 'ORIGIN_ACTOR_MISMATCH'
           WHEN origin_session.pay_date > derived_row.current_session_pay_date THEN 'ORIGIN_AFTER_CURRENT_SESSION'
           WHEN derived_row.payload_origin_pay_date_text IS NOT NULL
                AND derived_row.derived_payload_origin_pay_date IS NULL THEN 'ORIGIN_PAY_DATE_INVALID'
           WHEN derived_row.derived_payload_origin_pay_date IS NOT NULL
                AND derived_row.derived_payload_origin_pay_date IS DISTINCT FROM origin_session.pay_date THEN 'ORIGIN_PAY_DATE_MISMATCH'
           ELSE NULL::text
         END AS invalid_reason
  FROM derived_rows AS derived_row
  LEFT JOIN public.banking_pay_workbench_sessions AS origin_session
    ON origin_session.id = derived_row.derived_origin_session_id;

  SELECT COUNT(*)::integer,
         COUNT(*) FILTER (WHERE page_row.invalid_reason IS NULL)::integer,
         COUNT(*) FILTER (WHERE page_row.invalid_reason IS NOT NULL)::integer,
         (array_agg(page_row.id ORDER BY page_row.id DESC))[1]
  INTO v_scanned_count,
       v_valid_count,
       v_invalid_count,
       v_next_cursor
  FROM pg_temp._bpay_resolution_origin_backfill_page AS page_row;

  SELECT COALESCE(
           jsonb_agg(
             jsonb_build_object(
               'resolution_id', invalid_row.id::text,
               'session_id', invalid_row.session_id::text,
               'resolution_identity_key', invalid_row.resolution_identity_key,
               'payload_origin_session_id', invalid_row.payload_origin_session_id_text,
               'payload_source_session_id', invalid_row.payload_source_session_id_text,
               'derived_origin_session_id', CASE WHEN invalid_row.derived_origin_session_id IS NULL THEN NULL ELSE invalid_row.derived_origin_session_id::text END,
               'reason', invalid_row.invalid_reason
             )
             ORDER BY invalid_row.id
           ),
           '[]'::jsonb
         )
  INTO v_invalid_samples
  FROM (
    SELECT page_row.*
    FROM pg_temp._bpay_resolution_origin_backfill_page AS page_row
    WHERE page_row.invalid_reason IS NOT NULL
    ORDER BY page_row.id
    LIMIT 25
  ) AS invalid_row;

  IF p_apply IS TRUE THEN
    WITH updated_rows AS (
      UPDATE public.banking_pay_workbench_session_case_resolutions AS resolution_update
      SET resolution_origin_session_id = page_row.derived_origin_session_id,
          resolution_origin_pay_date = page_row.origin_pay_date,
          resolution_origin_source_basis_fingerprint = page_row.derived_origin_fingerprint,
          payload_json = jsonb_strip_nulls(
            (
              COALESCE(resolution_update.payload_json, '{}'::jsonb)
              - 'resolution_origin_session_id'
              - 'resolution_origin_pay_date'
              - 'resolution_origin_source_basis_fingerprint'
            )
            || jsonb_build_object(
              'resolution_origin_session_id', page_row.derived_origin_session_id::text,
              'resolution_origin_pay_date', page_row.origin_pay_date::text,
              'resolution_origin_source_basis_fingerprint', page_row.derived_origin_fingerprint
            )
          ),
          updated_at_utc = clock_timestamp()
      FROM pg_temp._bpay_resolution_origin_backfill_page AS page_row
      WHERE resolution_update.id = page_row.id
        AND page_row.invalid_reason IS NULL
        AND (
          resolution_update.resolution_origin_session_id IS NULL
          OR resolution_update.resolution_origin_pay_date IS NULL
        )
      RETURNING resolution_update.id
    )
    SELECT COUNT(*)::integer
    INTO v_updated_count
    FROM updated_rows;
  END IF;

  IF v_next_cursor IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_session_case_resolutions AS remaining_row
      WHERE (
        remaining_row.resolution_origin_session_id IS NULL
        OR remaining_row.resolution_origin_pay_date IS NULL
      )
        AND remaining_row.id > v_next_cursor
    )
    INTO v_has_more;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_unresolved_total_count
  FROM public.banking_pay_workbench_session_case_resolutions AS unresolved_row
  WHERE unresolved_row.resolution_origin_session_id IS NULL
     OR unresolved_row.resolution_origin_pay_date IS NULL;

  v_complete := p_apply IS TRUE
    AND v_has_more IS NOT TRUE
    AND v_unresolved_total_count = 0;

  RETURN jsonb_build_object(
    'ok', v_invalid_count = 0,
    'apply', p_apply,
    'limit', v_limit,
    'after_id', CASE WHEN p_after_id IS NULL THEN NULL ELSE p_after_id::text END,
    'scanned_count', v_scanned_count,
    'valid_count', v_valid_count,
    'updated_count', v_updated_count,
    'invalid_count', v_invalid_count,
    'invalid_samples', v_invalid_samples,
    'unresolved_total_count', v_unresolved_total_count,
    'next_cursor', CASE WHEN v_next_cursor IS NULL THEN NULL ELSE v_next_cursor::text END,
    'has_more', v_has_more,
    'complete', v_complete
  );
END;
$function$;

-- pay_workbench_case_resolution_origin_guard_v1()
CREATE OR REPLACE FUNCTION public.pay_workbench_case_resolution_origin_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_current_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_origin_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_origin_session_id uuid;
  v_origin_pay_date date;
  v_origin_fingerprint text;
BEGIN
  SELECT session_row.*
  INTO v_current_session
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = NEW.session_id;

  IF v_current_session.id IS NULL THEN
    RAISE EXCEPTION 'WORKBENCH_RESOLUTION_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_RESOLUTION_SESSION_NOT_FOUND',
              'session_id', NEW.session_id::text
            )::text;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.session_id IS DISTINCT FROM OLD.session_id THEN
    RAISE EXCEPTION 'WORKBENCH_RESOLUTION_SESSION_IMMUTABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_RESOLUTION_SESSION_IMMUTABLE',
              'resolution_id', OLD.id::text,
              'session_id', OLD.session_id::text,
              'requested_session_id', NEW.session_id::text
            )::text;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.resolution_origin_session_id IS NOT NULL THEN
    IF NEW.resolution_origin_session_id IS DISTINCT FROM OLD.resolution_origin_session_id
       OR NEW.resolution_origin_pay_date IS DISTINCT FROM OLD.resolution_origin_pay_date
       OR NEW.resolution_origin_source_basis_fingerprint IS DISTINCT FROM OLD.resolution_origin_source_basis_fingerprint THEN
      RAISE EXCEPTION 'WORKBENCH_RESOLUTION_ORIGIN_IMMUTABLE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'WORKBENCH_RESOLUTION_ORIGIN_IMMUTABLE',
                'resolution_id', OLD.id::text,
                'origin_session_id', OLD.resolution_origin_session_id::text,
                'origin_pay_date', OLD.resolution_origin_pay_date::text,
                'message', 'The original Banking Pay resolution authority cannot be replaced.'
              )::text;
    END IF;

    v_origin_session_id := OLD.resolution_origin_session_id;
    v_origin_pay_date := OLD.resolution_origin_pay_date;
    v_origin_fingerprint := OLD.resolution_origin_source_basis_fingerprint;
  ELSE
    v_origin_session_id := COALESCE(NEW.resolution_origin_session_id, NEW.session_id);
    v_origin_pay_date := NEW.resolution_origin_pay_date;
    v_origin_fingerprint := NULLIF(BTRIM(COALESCE(
      NEW.resolution_origin_source_basis_fingerprint,
      NEW.source_basis_fingerprint,
      ''
    )), '');
  END IF;

  SELECT session_row.*
  INTO v_origin_session
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = v_origin_session_id;

  IF v_origin_session.id IS NULL THEN
    RAISE EXCEPTION 'WORKBENCH_RESOLUTION_ORIGIN_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_RESOLUTION_ORIGIN_SESSION_NOT_FOUND',
              'resolution_id', NEW.id::text,
              'origin_session_id', v_origin_session_id::text
            )::text;
  END IF;

  IF v_origin_session.actor_user_id IS DISTINCT FROM v_current_session.actor_user_id THEN
    RAISE EXCEPTION 'WORKBENCH_RESOLUTION_ORIGIN_ACTOR_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_RESOLUTION_ORIGIN_ACTOR_MISMATCH',
              'resolution_id', NEW.id::text,
              'session_id', NEW.session_id::text,
              'origin_session_id', v_origin_session_id::text
            )::text;
  END IF;

  IF v_origin_session.pay_date > v_current_session.pay_date THEN
    RAISE EXCEPTION 'WORKBENCH_RESOLUTION_ORIGIN_AFTER_TARGET'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_RESOLUTION_ORIGIN_AFTER_TARGET',
              'resolution_id', NEW.id::text,
              'session_pay_date', v_current_session.pay_date::text,
              'origin_pay_date', v_origin_session.pay_date::text
            )::text;
  END IF;

  v_origin_pay_date := COALESCE(v_origin_pay_date, v_origin_session.pay_date);

  IF v_origin_pay_date IS DISTINCT FROM v_origin_session.pay_date THEN
    RAISE EXCEPTION 'WORKBENCH_RESOLUTION_ORIGIN_PAY_DATE_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_RESOLUTION_ORIGIN_PAY_DATE_MISMATCH',
              'resolution_id', NEW.id::text,
              'origin_session_id', v_origin_session_id::text,
              'provided_origin_pay_date', v_origin_pay_date::text,
              'authoritative_origin_pay_date', v_origin_session.pay_date::text
            )::text;
  END IF;

  NEW.resolution_origin_session_id := v_origin_session_id;
  NEW.resolution_origin_pay_date := v_origin_pay_date;
  NEW.resolution_origin_source_basis_fingerprint := v_origin_fingerprint;
  NEW.payload_json := jsonb_strip_nulls(
    (
      COALESCE(NEW.payload_json, '{}'::jsonb)
      - 'resolution_origin_session_id'
      - 'resolution_origin_pay_date'
      - 'resolution_origin_source_basis_fingerprint'
    )
    || jsonb_build_object(
      'resolution_origin_session_id', v_origin_session_id::text,
      'resolution_origin_pay_date', v_origin_pay_date::text,
      'resolution_origin_source_basis_fingerprint', v_origin_fingerprint
    )
  );

  RETURN NEW;
END;
$function$;

-- pay_workbench_claim_due_jobs(integer,timestamp with time zone,uuid,uuid,text[])
CREATE OR REPLACE FUNCTION public.pay_workbench_claim_due_jobs(p_limit integer DEFAULT 25, p_now_utc timestamp with time zone DEFAULT NULL::timestamp with time zone, p_session_id uuid DEFAULT NULL::uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_allowed_job_types text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 25), 500));
  v_now timestamptz := now();
  v_cutoff timestamptz := COALESCE(p_now_utc, v_now);
  v_stale_running_seconds integer := 180;
  v_configured_lease_seconds integer := NULL::integer;
  v_stale_cutoff timestamptz := NULL::timestamptz;
  v_recovered_stale jsonb := '[]'::jsonb;
  v_dead_stale jsonb := '[]'::jsonb;
  v_claimed jsonb := '[]'::jsonb;
  v_recovered_stale_count integer := 0;
  v_dead_stale_count integer := 0;
  v_claimed_count integer := 0;
  v_claimed_delta_refresh_count integer := 0;
  v_claimed_clone_rebase_count integer := 0;
  v_stale_row record;
  v_stale_before_json jsonb := NULL;
  v_stale_after_json jsonb := '{}'::jsonb;
  v_stale_error_json jsonb := NULL;
  v_claimed_row record;
  v_stale_job_source_change_seq bigint := 0;
  v_stale_job_session_version bigint := 0;
  v_stale_live_candidate_change_seq bigint := 0;
  v_stale_snapshot_state_status text := NULL;
  v_stale_snapshot_state_source_change_seq bigint := 0;
  v_stale_session_status text := NULL;
  v_stale_session_version bigint := 0;
  v_stale_session_candidate_status text := NULL;
  v_stale_session_candidate_source_change_seq bigint := 0;
  v_stale_session_candidate_session_version bigint := 0;
  v_stale_other_active_job_id uuid := NULL::uuid;
  v_stale_completed_equivalent_id uuid := NULL::uuid;
  v_stale_obsolete boolean := false;
  v_stale_obsolete_reason text := NULL;
  v_stale_canonical_job_type text := NULL::text;
  v_stale_failed_line_work_count integer := 0;
  v_stale_failed_source_row_count integer := 0;
  v_allowed_job_types text[] := NULL::text[];
  v_stale_recovery_limit integer := 0;
  v_preclaim_due_queued_count integer := 0;
  v_preclaim_due_queued_sample jsonb := '[]'::jsonb;
  v_claim_lock_contention_detected boolean := false;
  v_claim_lock_contention_count integer := 0;
  v_delta_queued_coalesced_count integer := 0;
  v_delta_queued_coalesced_hot_key_count integer := 0;
  v_projection_lifecycle_repair_json jsonb := '{}'::jsonb;
  v_invalid_source_build_poison_repair_json jsonb := '{}'::jsonb;
  v_orphaned_pending_source_build_repair_json jsonb := '{}'::jsonb;
  v_stale_source_build_run_id_text text := NULL::text;
  v_stale_invalid_source_build_without_run_id boolean := false;
  v_delta_stale_continuation_superseded_count integer := 0;
  v_delta_stale_continuation_sample jsonb := '[]'::jsonb;
  v_delta_stale_projection_terminalised_count integer := 0;
  v_delta_stale_projection_terminalisation_sample jsonb := '[]'::jsonb;
  v_claim_mismatch_detected boolean := false;
  v_claim_mismatch_reason text := NULL::text;
  v_claim_mismatch_json jsonb := '{}'::jsonb;
  v_claimable_sample jsonb := '[]'::jsonb;
  v_claim_reject_summary jsonb := '{}'::jsonb;
  v_advisory_lock_reject_count integer := 0;
  v_candidate_serial_reject_count integer := 0;
  v_skip_locked_or_concurrent_lock_count integer := 0;
  v_allowed_job_types_reject_count integer := 0;
  v_status_changed_before_claim_count integer := 0;
  v_obsolete_or_superseded_reject_count integer := 0;
  v_active_projection_reject_count integer := 0;
  v_unknown_claim_query_mismatch_count integer := 0;
BEGIN
  IF p_allowed_job_types IS NOT NULL THEN
    SELECT ARRAY(
      SELECT DISTINCT normalised_allowed.job_type
      FROM (
        SELECT
          CASE
            WHEN normalised_raw.raw_value_text IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED_PAGE', 'SCOPE_SEED_PAGE')
              THEN 'WORKBENCH_SESSION_SCOPE_SEED'
            WHEN normalised_raw.raw_value_text IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE')
              THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
            WHEN normalised_raw.raw_value_text IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
              THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
            WHEN normalised_raw.raw_value_text IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE')
              THEN 'WORKBENCH_SESSION_CLONE_REBASE'
            WHEN normalised_raw.raw_value_text IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE', 'CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED_PAGE', 'LINE_WORK_SEED_PAGE', 'SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH')
              THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
            WHEN normalised_raw.raw_value_text IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'LINE_WORK_PROCESS', 'LINE_WORK_PROCESS_CHUNK')
              THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
            WHEN normalised_raw.raw_value_text IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE_CHUNK', 'PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROW_MATERIALISE_CHUNK', 'PREVIEW_ROW_MATERIALIZE_CHUNK')
              THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
            ELSE normalised_raw.raw_value_text
          END AS job_type
        FROM unnest(p_allowed_job_types) AS allowed_job_type(raw_value)
        CROSS JOIN LATERAL (
          SELECT UPPER(BTRIM(COALESCE(allowed_job_type.raw_value, ''))) AS raw_value_text
        ) AS normalised_raw
        WHERE normalised_raw.raw_value_text <> ''
      ) AS normalised_allowed
      WHERE normalised_allowed.job_type <> ''
      ORDER BY normalised_allowed.job_type
    )
    INTO v_allowed_job_types;

    IF COALESCE(array_length(v_allowed_job_types, 1), 0) = 0 THEN
      v_allowed_job_types := ARRAY[]::text[];
    END IF;
  ELSE
    v_allowed_job_types := NULL::text[];
  END IF;

  IF p_session_id IS NOT NULL
     AND (
       v_allowed_job_types IS NULL
       OR 'WORKBENCH_SESSION_SCOPE_SEED' = ANY(v_allowed_job_types)
       OR 'WORKBENCH_CANDIDATE_SOURCE_BUILD' = ANY(v_allowed_job_types)
       OR 'WORKBENCH_CANDIDATE_DELTA_REFRESH' = ANY(v_allowed_job_types)
       OR 'WORKBENCH_SESSION_CLONE_REBASE' = ANY(v_allowed_job_types)
       OR 'WORKBENCH_CANDIDATE_LINE_WORK_SEED' = ANY(v_allowed_job_types)
       OR 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS' = ANY(v_allowed_job_types)
       OR 'WORKBENCH_PREVIEW_ROWS_MATERIALISE' = ANY(v_allowed_job_types)
     ) THEN
    v_stale_running_seconds := 25;
  ELSE
    v_stale_running_seconds := 180;
  END IF;

  SELECT sd.banking_pay_workbench_db_worker_lease_seconds
  INTO v_configured_lease_seconds
  FROM public.settings_defaults AS sd
  WHERE sd.id = 1
  LIMIT 1;

  IF v_configured_lease_seconds IS NOT NULL THEN
    v_stale_running_seconds := LEAST(GREATEST(v_configured_lease_seconds, 25), 3600);
  END IF;

  v_stale_cutoff := v_cutoff - make_interval(secs => v_stale_running_seconds);
  v_stale_recovery_limit := LEAST(v_limit, 3);

  IF v_allowed_job_types IS NULL
     OR 'WORKBENCH_CANDIDATE_DELTA_REFRESH' = ANY(v_allowed_job_types) THEN
    v_projection_lifecycle_repair_json := public.pay_workbench_projection_lifecycle_repair(
      p_session_id => p_session_id,
      p_candidate_id => p_candidate_id,
      p_safe_age_seconds => GREATEST(v_stale_running_seconds, 300),
      p_limit => LEAST(GREATEST(v_limit, 1), 100),
      p_reason => 'CLAIM_DUE_JOBS_PROJECTION_LIFECYCLE_REPAIR'
    );
  END IF;

  IF v_allowed_job_types IS NULL
     OR 'WORKBENCH_CANDIDATE_SOURCE_BUILD' = ANY(v_allowed_job_types)
     OR 'WORKBENCH_CANDIDATE_LINE_WORK_SEED' = ANY(v_allowed_job_types) THEN
    IF to_regprocedure('public.pay_workbench_repair_invalid_source_build_poison(uuid,uuid,integer,timestamp with time zone,text)') IS NOT NULL THEN
      BEGIN
        EXECUTE 'SELECT public.pay_workbench_repair_invalid_source_build_poison($1, $2, $3, $4, $5)'
        INTO v_invalid_source_build_poison_repair_json
        USING
          p_session_id,
          p_candidate_id,
          LEAST(GREATEST(v_limit, 1), 10),
          v_now,
          'CLAIM_DUE_JOBS_INVALID_SOURCE_BUILD_POISON_REPAIR';
      EXCEPTION WHEN OTHERS THEN
        v_invalid_source_build_poison_repair_json := jsonb_build_object(
          'ok', false,
          'deferred', true,
          'reason', 'CLAIM_DUE_JOBS_INVALID_SOURCE_BUILD_POISON_REPAIR_FAILED',
          'code', SQLSTATE,
          'message', SQLERRM,
          'session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
          'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
          'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
        );
      END;
    END IF;
  END IF;

  IF v_allowed_job_types IS NULL
     OR 'WORKBENCH_CANDIDATE_SOURCE_BUILD' = ANY(v_allowed_job_types) THEN
    IF to_regprocedure('public.pay_workbench_repair_orphaned_pending_source_build(uuid,uuid,integer,timestamp with time zone,text)') IS NOT NULL THEN
      BEGIN
        EXECUTE 'SELECT public.pay_workbench_repair_orphaned_pending_source_build($1, $2, $3, $4, $5)'
        INTO v_orphaned_pending_source_build_repair_json
        USING
          p_session_id,
          p_candidate_id,
          LEAST(GREATEST(v_limit, 1), 10),
          v_now,
          'CLAIM_DUE_JOBS_PENDING_SOURCE_BUILD_OWNER_REPAIR';
      EXCEPTION WHEN OTHERS THEN
        v_orphaned_pending_source_build_repair_json := jsonb_build_object(
          'ok', false,
          'deferred', true,
          'reason', 'CLAIM_DUE_JOBS_PENDING_SOURCE_BUILD_OWNER_REPAIR_FAILED',
          'code', SQLSTATE,
          'message', SQLERRM,
          'session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
          'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
          'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
        );
      END;
    END IF;
  END IF;

  FOR v_stale_row IN
    WITH stale_candidates AS (
      SELECT
        stale_job.id,
        stale_job.job_type,
        stale_job.status,
        stale_job.priority,
        stale_job.run_at_utc,
        stale_job.attempt_count,
        stale_job.max_attempts,
        stale_job.dedupe_key,
        stale_job.snapshot_run_id,
        stale_job.session_id,
        stale_job.candidate_id,
        stale_job.payload_json,
        stale_job.created_at_utc,
        stale_job.updated_at_utc,
        stale_job.started_at_utc,
        stale_job.completed_at_utc,
        stale_job.failed_at_utc,
        stale_job.last_error_json,
        COALESCE(
          stale_job.updated_at_utc,
          stale_job.started_at_utc,
          stale_job.run_at_utc,
          stale_job.created_at_utc
        ) AS last_activity_utc
      FROM public.banking_pay_workbench_jobs AS stale_job
      WHERE stale_job.status = 'RUNNING'
        AND (
          CASE
            WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED_PAGE', 'SCOPE_SEED_PAGE')
              THEN 'WORKBENCH_SESSION_SCOPE_SEED'
            WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE')
              THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
            WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
              THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
              WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE')
                THEN 'WORKBENCH_SESSION_CLONE_REBASE'
            WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE', 'CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED_PAGE', 'LINE_WORK_SEED_PAGE', 'SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH')
              THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
            WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'LINE_WORK_PROCESS', 'LINE_WORK_PROCESS_CHUNK')
              THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
            WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE_CHUNK', 'PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROW_MATERIALISE_CHUNK', 'PREVIEW_ROW_MATERIALIZE_CHUNK')
              THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
            ELSE UPPER(BTRIM(COALESCE(stale_job.job_type, '')))
          END
        ) IN (
          'WORKBENCH_SESSION_SCOPE_SEED',
          'WORKBENCH_CANDIDATE_SOURCE_BUILD',
          'WORKBENCH_CANDIDATE_DELTA_REFRESH',
          'WORKBENCH_SESSION_CLONE_REBASE',
          'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
          'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
          'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
        )
        AND (p_session_id IS NULL OR stale_job.session_id = p_session_id)
        AND (p_candidate_id IS NULL OR stale_job.candidate_id = p_candidate_id)
        AND (
          v_allowed_job_types IS NULL
          OR UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) = ANY(v_allowed_job_types)
          OR (
            CASE
              WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED_PAGE', 'SCOPE_SEED_PAGE')
                THEN 'WORKBENCH_SESSION_SCOPE_SEED'
              WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE')
                THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
              WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
                THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
                WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE')
                  THEN 'WORKBENCH_SESSION_CLONE_REBASE'
              WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE', 'CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED_PAGE', 'LINE_WORK_SEED_PAGE', 'SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH')
                THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
              WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'LINE_WORK_PROCESS', 'LINE_WORK_PROCESS_CHUNK')
                THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
              WHEN UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE_CHUNK', 'PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROW_MATERIALISE_CHUNK', 'PREVIEW_ROW_MATERIALIZE_CHUNK')
                THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
              ELSE UPPER(BTRIM(COALESCE(stale_job.job_type, '')))
            END
          ) = ANY(v_allowed_job_types)
        )
        AND stale_job.completed_at_utc IS NULL
        AND stale_job.failed_at_utc IS NULL
        AND COALESCE(
              stale_job.updated_at_utc,
              stale_job.started_at_utc,
              stale_job.run_at_utc,
              stale_job.created_at_utc
            ) <= v_stale_cutoff
      ORDER BY
        COALESCE(
          stale_job.updated_at_utc,
          stale_job.started_at_utc,
          stale_job.run_at_utc,
          stale_job.created_at_utc
        ) ASC,
        stale_job.priority ASC,
        stale_job.run_at_utc ASC,
        stale_job.created_at_utc ASC,
        stale_job.id ASC
      LIMIT v_stale_recovery_limit
      FOR UPDATE SKIP LOCKED
    )
    SELECT
      stale_candidates.id,
      stale_candidates.job_type,
      stale_candidates.status,
      stale_candidates.priority,
      stale_candidates.run_at_utc,
      stale_candidates.attempt_count,
      stale_candidates.max_attempts,
      stale_candidates.dedupe_key,
      stale_candidates.snapshot_run_id,
      stale_candidates.session_id,
      stale_candidates.candidate_id,
      stale_candidates.payload_json,
      stale_candidates.created_at_utc,
      stale_candidates.updated_at_utc,
      stale_candidates.started_at_utc,
      stale_candidates.completed_at_utc,
      stale_candidates.failed_at_utc,
      stale_candidates.last_error_json,
      stale_candidates.last_activity_utc
    FROM stale_candidates
  LOOP
    v_stale_job_source_change_seq := COALESCE(
      CASE
        WHEN COALESCE(v_stale_row.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
          THEN (v_stale_row.payload_json->>'source_change_seq')::bigint
        ELSE 0::bigint
      END,
      0::bigint
    );
    v_stale_job_session_version := COALESCE(
      CASE
        WHEN COALESCE(v_stale_row.payload_json->>'session_version', '') ~ '^[0-9]+$'
          THEN (v_stale_row.payload_json->>'session_version')::bigint
        ELSE 0::bigint
      END,
      0::bigint
    );
    v_stale_live_candidate_change_seq := 0;
    v_stale_snapshot_state_status := NULL;
    v_stale_snapshot_state_source_change_seq := 0;
    v_stale_session_status := NULL;
    v_stale_session_version := 0;
    v_stale_session_candidate_status := NULL;
    v_stale_session_candidate_source_change_seq := 0;
    v_stale_session_candidate_session_version := 0;
    v_stale_other_active_job_id := NULL::uuid;
    v_stale_completed_equivalent_id := NULL::uuid;
    v_stale_obsolete := false;
    v_stale_obsolete_reason := NULL;
    v_stale_failed_line_work_count := 0;
    v_stale_failed_source_row_count := 0;
    v_stale_source_build_run_id_text := NULL::text;
    v_stale_invalid_source_build_without_run_id := false;
    v_stale_canonical_job_type := CASE
      WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED_PAGE', 'SCOPE_SEED_PAGE')
        THEN 'WORKBENCH_SESSION_SCOPE_SEED'
      WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE')
        THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
      WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
        THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
        WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE')
          THEN 'WORKBENCH_SESSION_CLONE_REBASE'
      WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE', 'CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED_PAGE', 'LINE_WORK_SEED_PAGE', 'SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH')
        THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
      WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'LINE_WORK_PROCESS', 'LINE_WORK_PROCESS_CHUNK')
        THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
      WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE_CHUNK', 'PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROW_MATERIALISE_CHUNK', 'PREVIEW_ROW_MATERIALIZE_CHUNK')
        THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
      ELSE UPPER(BTRIM(COALESCE(v_stale_row.job_type, '')))
    END;

    IF v_stale_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN
      v_stale_source_build_run_id_text := NULLIF(BTRIM(COALESCE(
        v_stale_row.payload_json->>'source_build_run_id',
        v_stale_row.payload_json#>>'{source_build,source_build_run_id}',
        v_stale_row.payload_json#>>'{source_build,run_id}',
        v_stale_row.payload_json#>>'{cursor,source_build_run_id}',
        v_stale_row.payload_json#>>'{cursor_json,source_build_run_id}',
        v_stale_row.payload_json#>>'{result_json,source_build_run_id}',
        ''
      )), '');

      IF v_stale_source_build_run_id_text IS NULL
         OR v_stale_source_build_run_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        v_stale_source_build_run_id_text := NULL::text;
        v_stale_invalid_source_build_without_run_id := true;
      END IF;
    END IF;

    IF UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) = 'SNAPSHOT_CANDIDATE_REFRESH' THEN
      IF v_stale_row.snapshot_run_id IS NULL OR v_stale_row.candidate_id IS NULL THEN
        v_stale_obsolete := true;
        v_stale_obsolete_reason := 'INVALID_SNAPSHOT_CONTEXT';
      ELSE
        SELECT COALESCE(acc.seq, 0)
        INTO v_stale_live_candidate_change_seq
        FROM public.app_change_counters AS acc
        WHERE acc.entity_key = 'pay_candidate:' || v_stale_row.candidate_id::text;

        SELECT COALESCE(snap.status, NULL), COALESCE(snap.source_change_seq, 0)
        INTO v_stale_snapshot_state_status, v_stale_snapshot_state_source_change_seq
        FROM public.banking_pay_snapshot_candidate_state AS snap
        WHERE snap.snapshot_run_id = v_stale_row.snapshot_run_id
          AND snap.candidate_id = v_stale_row.candidate_id
        LIMIT 1;

        SELECT j.id
        INTO v_stale_other_active_job_id
        FROM public.banking_pay_workbench_jobs AS j
        WHERE j.id <> v_stale_row.id
          AND j.job_type = 'SNAPSHOT_CANDIDATE_REFRESH'
          AND j.snapshot_run_id = v_stale_row.snapshot_run_id
          AND j.candidate_id = v_stale_row.candidate_id
          AND j.status IN ('QUEUED', 'RUNNING')
          AND COALESCE(
                CASE
                  WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                    THEN (j.payload_json->>'source_change_seq')::bigint
                  ELSE 0::bigint
                END,
                0::bigint
              ) >= GREATEST(v_stale_job_source_change_seq, v_stale_live_candidate_change_seq)
        ORDER BY COALESCE(
                   CASE
                     WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                       THEN (j.payload_json->>'source_change_seq')::bigint
                     ELSE 0::bigint
                   END,
                   0::bigint
                 ) DESC,
                 j.updated_at_utc DESC NULLS LAST,
                 j.created_at_utc DESC NULLS LAST,
                 j.id DESC
        LIMIT 1;

        IF v_stale_live_candidate_change_seq > v_stale_job_source_change_seq THEN
          v_stale_obsolete := true;
          v_stale_obsolete_reason := 'SUPERSEDED_BY_LIVE_CHANGE_SEQ';
        ELSIF v_stale_other_active_job_id IS NOT NULL THEN
          v_stale_obsolete := true;
          v_stale_obsolete_reason := 'MATCHING_ACTIVE_SNAPSHOT_JOB_EXISTS';
        ELSIF UPPER(COALESCE(v_stale_snapshot_state_status, '')) = 'READY'
              AND v_stale_snapshot_state_source_change_seq >= GREATEST(v_stale_job_source_change_seq, v_stale_live_candidate_change_seq) THEN
          v_stale_obsolete := true;
          v_stale_obsolete_reason := 'SNAPSHOT_ALREADY_CURRENT';
        END IF;
      END IF;
    ELSIF UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) = 'SESSION_CANDIDATE_RECOMPUTE' THEN
      IF v_stale_row.session_id IS NULL OR v_stale_row.candidate_id IS NULL THEN
        v_stale_obsolete := true;
        v_stale_obsolete_reason := 'INVALID_SESSION_CONTEXT';
      ELSE
        SELECT COALESCE(acc.seq, 0)
        INTO v_stale_live_candidate_change_seq
        FROM public.app_change_counters AS acc
        WHERE acc.entity_key = 'pay_candidate:' || v_stale_row.candidate_id::text;

        SELECT COALESCE(ws.status, NULL), COALESCE(ws.version, 0)
        INTO v_stale_session_status, v_stale_session_version
        FROM public.banking_pay_workbench_sessions AS ws
        WHERE ws.id = v_stale_row.session_id
        LIMIT 1;

        IF v_stale_session_status IS NULL OR UPPER(COALESCE(v_stale_session_status, '')) <> 'OPEN' THEN
          v_stale_obsolete := true;
          v_stale_obsolete_reason := 'SESSION_NOT_OPEN';
        ELSE
          SELECT COALESCE(scs.status, NULL),
                 COALESCE(scs.source_change_seq, 0),
                 COALESCE(scs.session_version, 0)
          INTO v_stale_session_candidate_status,
               v_stale_session_candidate_source_change_seq,
               v_stale_session_candidate_session_version
          FROM public.banking_pay_workbench_session_candidate_state AS scs
          WHERE scs.session_id = v_stale_row.session_id
            AND scs.candidate_id = v_stale_row.candidate_id
          LIMIT 1;

          SELECT j.id
          INTO v_stale_other_active_job_id
          FROM public.banking_pay_workbench_jobs AS j
          WHERE j.id <> v_stale_row.id
            AND j.job_type = 'SESSION_CANDIDATE_RECOMPUTE'
            AND j.session_id = v_stale_row.session_id
            AND j.candidate_id = v_stale_row.candidate_id
            AND j.status IN ('QUEUED', 'RUNNING')
            AND COALESCE(
                  CASE
                    WHEN COALESCE(j.payload_json->>'session_version', '') ~ '^[0-9]+$'
                      THEN (j.payload_json->>'session_version')::bigint
                    ELSE 0::bigint
                  END,
                  0::bigint
                ) >= v_stale_session_version
            AND COALESCE(
                  CASE
                    WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                      THEN (j.payload_json->>'source_change_seq')::bigint
                    ELSE 0::bigint
                  END,
                  0::bigint
                ) >= GREATEST(v_stale_job_source_change_seq, v_stale_live_candidate_change_seq)
          ORDER BY COALESCE(
                     CASE
                       WHEN COALESCE(j.payload_json->>'session_version', '') ~ '^[0-9]+$'
                         THEN (j.payload_json->>'session_version')::bigint
                       ELSE 0::bigint
                     END,
                     0::bigint
                   ) DESC,
                   COALESCE(
                     CASE
                       WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                         THEN (j.payload_json->>'source_change_seq')::bigint
                       ELSE 0::bigint
                     END,
                     0::bigint
                   ) DESC,
                   j.updated_at_utc DESC NULLS LAST,
                   j.created_at_utc DESC NULLS LAST,
                   j.id DESC
          LIMIT 1;

          IF v_stale_session_version > v_stale_job_session_version THEN
            v_stale_obsolete := true;
            v_stale_obsolete_reason := 'SUPERSEDED_BY_NEWER_SESSION_VERSION';
          ELSIF v_stale_other_active_job_id IS NOT NULL THEN
            v_stale_obsolete := true;
            v_stale_obsolete_reason := 'MATCHING_ACTIVE_SESSION_JOB_EXISTS';
          ELSIF UPPER(COALESCE(v_stale_session_candidate_status, '')) = 'READY'
                AND v_stale_session_candidate_session_version >= v_stale_session_version
                AND v_stale_session_candidate_source_change_seq >= GREATEST(v_stale_job_source_change_seq, v_stale_live_candidate_change_seq) THEN
            v_stale_obsolete := true;
            v_stale_obsolete_reason := 'SESSION_ALREADY_CURRENT';
          END IF;
        END IF;
      END IF;
    ELSIF UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) = 'PAYEE_READINESS_ENSURE' THEN
      IF v_stale_row.candidate_id IS NULL THEN
        v_stale_obsolete := true;
        v_stale_obsolete_reason := 'INVALID_READINESS_CONTEXT';
      ELSE
        SELECT COALESCE(acc.seq, 0)
        INTO v_stale_live_candidate_change_seq
        FROM public.app_change_counters AS acc
        WHERE acc.entity_key = 'pay_candidate:' || v_stale_row.candidate_id::text;

        IF v_stale_row.session_id IS NOT NULL THEN
          SELECT COALESCE(ws.status, NULL), COALESCE(ws.version, 0)
          INTO v_stale_session_status, v_stale_session_version
          FROM public.banking_pay_workbench_sessions AS ws
          WHERE ws.id = v_stale_row.session_id
          LIMIT 1;

          IF v_stale_session_status IS NULL OR UPPER(COALESCE(v_stale_session_status, '')) <> 'OPEN' THEN
            v_stale_obsolete := true;
            v_stale_obsolete_reason := 'SESSION_NOT_OPEN';
          ELSIF v_stale_session_version > v_stale_job_session_version THEN
            v_stale_obsolete := true;
            v_stale_obsolete_reason := 'SUPERSEDED_BY_NEWER_SESSION_VERSION';
          END IF;
        END IF;

        IF NOT v_stale_obsolete AND v_stale_live_candidate_change_seq > v_stale_job_source_change_seq THEN
          v_stale_obsolete := true;
          v_stale_obsolete_reason := 'SUPERSEDED_BY_LIVE_CHANGE_SEQ';
        END IF;

        IF NOT v_stale_obsolete THEN
          SELECT j.id
          INTO v_stale_completed_equivalent_id
          FROM public.banking_pay_workbench_jobs AS j
          WHERE j.id <> v_stale_row.id
            AND j.job_type = 'PAYEE_READINESS_ENSURE'
            AND j.dedupe_key = v_stale_row.dedupe_key
            AND j.completed_at_utc IS NOT NULL
            AND j.failed_at_utc IS NULL
          ORDER BY j.completed_at_utc DESC, j.id DESC
          LIMIT 1;

          IF v_stale_completed_equivalent_id IS NOT NULL THEN
            v_stale_obsolete := true;
            v_stale_obsolete_reason := 'COMPLETED_EQUIVALENT_EXISTS';
          ELSE
            SELECT j.id
            INTO v_stale_other_active_job_id
            FROM public.banking_pay_workbench_jobs AS j
            WHERE j.id <> v_stale_row.id
              AND j.job_type = 'PAYEE_READINESS_ENSURE'
              AND j.dedupe_key = v_stale_row.dedupe_key
              AND j.status IN ('QUEUED', 'RUNNING')
            ORDER BY j.updated_at_utc DESC NULLS LAST, j.created_at_utc DESC NULLS LAST, j.id DESC
            LIMIT 1;

            IF v_stale_other_active_job_id IS NOT NULL THEN
              v_stale_obsolete := true;
              v_stale_obsolete_reason := 'MATCHING_ACTIVE_READINESS_JOB_EXISTS';
            END IF;
          END IF;
        END IF;
      END IF;
    ELSIF (
      CASE
        WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED_PAGE', 'SCOPE_SEED_PAGE')
          THEN 'WORKBENCH_SESSION_SCOPE_SEED'
        WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE')
        THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
      WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
        THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
        WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE')
          THEN 'WORKBENCH_SESSION_CLONE_REBASE'
      WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE', 'CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED_PAGE', 'LINE_WORK_SEED_PAGE', 'SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH')
          THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
        WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'LINE_WORK_PROCESS', 'LINE_WORK_PROCESS_CHUNK')
          THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
        WHEN UPPER(BTRIM(COALESCE(v_stale_row.job_type, ''))) IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE_CHUNK', 'PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROW_MATERIALISE_CHUNK', 'PREVIEW_ROW_MATERIALIZE_CHUNK')
          THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
        ELSE UPPER(BTRIM(COALESCE(v_stale_row.job_type, '')))
      END
    ) IN ('WORKBENCH_SESSION_SCOPE_SEED', 'WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_DELTA_REFRESH', 'WORKBENCH_SESSION_CLONE_REBASE', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE') THEN
      IF v_stale_row.session_id IS NULL THEN
        v_stale_obsolete := true;
        v_stale_obsolete_reason := 'INVALID_WORKBENCH_SESSION_CONTEXT';
      ELSE
        SELECT COALESCE(workbench_session.status, NULL), COALESCE(workbench_session.version, 0)
        INTO v_stale_session_status, v_stale_session_version
        FROM public.banking_pay_workbench_sessions AS workbench_session
        WHERE workbench_session.id = v_stale_row.session_id
        LIMIT 1;

        IF v_stale_session_status IS NULL OR UPPER(COALESCE(v_stale_session_status, '')) <> 'OPEN' THEN
          v_stale_obsolete := true;
          v_stale_obsolete_reason := 'SESSION_NOT_OPEN';
        ELSIF v_stale_job_session_version > 0 AND v_stale_session_version > v_stale_job_session_version THEN
          v_stale_obsolete := true;
          v_stale_obsolete_reason := 'SUPERSEDED_BY_NEWER_SESSION_VERSION';
        END IF;
      END IF;

    END IF;

    v_stale_before_json := jsonb_build_object(
      'id', v_stale_row.id::text,
      'job_type', v_stale_row.job_type,
      'status', v_stale_row.status,
      'priority', v_stale_row.priority,
      'run_at_utc', v_stale_row.run_at_utc,
      'attempt_count', v_stale_row.attempt_count,
      'max_attempts', v_stale_row.max_attempts,
      'dedupe_key', v_stale_row.dedupe_key,
      'snapshot_run_id', CASE WHEN v_stale_row.snapshot_run_id IS NULL THEN NULL ELSE v_stale_row.snapshot_run_id::text END,
      'session_id', CASE WHEN v_stale_row.session_id IS NULL THEN NULL ELSE v_stale_row.session_id::text END,
      'candidate_id', CASE WHEN v_stale_row.candidate_id IS NULL THEN NULL ELSE v_stale_row.candidate_id::text END,
      'payload_json', v_stale_row.payload_json,
      'created_at_utc', v_stale_row.created_at_utc,
      'updated_at_utc', v_stale_row.updated_at_utc,
      'started_at_utc', v_stale_row.started_at_utc,
      'completed_at_utc', v_stale_row.completed_at_utc,
      'failed_at_utc', v_stale_row.failed_at_utc,
      'last_error_json', v_stale_row.last_error_json,
      'last_activity_utc', v_stale_row.last_activity_utc
    );

    v_stale_error_json := jsonb_build_object(
      'code', CASE
        WHEN v_stale_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
             AND v_stale_invalid_source_build_without_run_id IS TRUE THEN 'STALE_RUNNING_WORKBENCH_SOURCE_BUILD_RUN_ID_MISSING_FAILED_CLOSED'
        WHEN v_stale_obsolete THEN 'STALE_RUNNING_WORKBENCH_JOB_MAX_ATTEMPTS'
        WHEN COALESCE(v_stale_row.attempt_count, 0) >= COALESCE(v_stale_row.max_attempts, 8) THEN 'STALE_RUNNING_WORKBENCH_JOB_MAX_ATTEMPTS'
        ELSE 'STALE_RUNNING_WORKBENCH_JOB_RECOVERED'
      END,
      'message', CASE
        WHEN v_stale_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
             AND v_stale_invalid_source_build_without_run_id IS TRUE THEN 'Failed stale running-like Banking Pay source-build job because its payload is missing source_build_run_id and cannot safely authorise source-row mutation.'
        WHEN v_stale_obsolete THEN 'Failed stale running-like Banking Pay workbench preview job because its context is obsolete or superseded.'
        WHEN COALESCE(v_stale_row.attempt_count, 0) >= COALESCE(v_stale_row.max_attempts, 8) THEN 'Failed stale running-like Banking Pay workbench preview job because max attempts are exhausted.'
        ELSE 'Recovered stale running-like Banking Pay workbench preview job during due-job claim cycle.'
      END,
      'job_id', v_stale_row.id::text,
      'job_type', v_stale_row.job_type,
      'previous_status', v_stale_row.status,
      'attempt_count', COALESCE(v_stale_row.attempt_count, 0),
      'max_attempts', COALESCE(v_stale_row.max_attempts, 8),
      'last_activity_utc', v_stale_row.last_activity_utc,
      'stale_cutoff_utc', v_stale_cutoff,
      'stale_running_seconds', v_stale_running_seconds,
      'recovered_at_utc', v_now,
      'obsolete', v_stale_obsolete,
      'obsolete_reason', v_stale_obsolete_reason,
      'source_change_seq', v_stale_job_source_change_seq,
      'session_version', v_stale_job_session_version,
      'live_candidate_change_seq', CASE WHEN v_stale_live_candidate_change_seq = 0 THEN NULL ELSE v_stale_live_candidate_change_seq END,
      'snapshot_state_status', v_stale_snapshot_state_status,
      'snapshot_state_source_change_seq', CASE WHEN v_stale_snapshot_state_source_change_seq = 0 THEN NULL ELSE v_stale_snapshot_state_source_change_seq END,
      'session_status', v_stale_session_status,
      'current_session_version', CASE WHEN v_stale_session_version = 0 THEN NULL ELSE v_stale_session_version END,
      'session_candidate_status', v_stale_session_candidate_status,
      'session_candidate_source_change_seq', CASE WHEN v_stale_session_candidate_source_change_seq = 0 THEN NULL ELSE v_stale_session_candidate_source_change_seq END,
      'session_candidate_session_version', CASE WHEN v_stale_session_candidate_session_version = 0 THEN NULL ELSE v_stale_session_candidate_session_version END,
      'other_active_job_id', CASE WHEN v_stale_other_active_job_id IS NULL THEN NULL ELSE v_stale_other_active_job_id::text END,
      'completed_equivalent_job_id', CASE WHEN v_stale_completed_equivalent_id IS NULL THEN NULL ELSE v_stale_completed_equivalent_id::text END
    );

    IF v_stale_obsolete
       OR (
         v_stale_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
         AND v_stale_invalid_source_build_without_run_id IS TRUE
       )
       OR COALESCE(v_stale_row.attempt_count, 0) >= COALESCE(v_stale_row.max_attempts, 8) THEN
      UPDATE public.banking_pay_workbench_jobs AS dead_job
      SET status = 'FAILED',
          updated_at_utc = v_now,
          completed_at_utc = NULL,
          failed_at_utc = v_now,
          last_error_json = v_stale_error_json,
          payload_json = jsonb_strip_nulls(
            COALESCE(dead_job.payload_json, '{}'::jsonb)
            || jsonb_build_object('last_failure_json', v_stale_error_json)
            || CASE
              WHEN v_stale_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
                   AND v_stale_invalid_source_build_without_run_id IS TRUE THEN
                jsonb_build_object(
                  'invalid_source_build_without_run_id_failed_closed', true,
                  'invalid_source_build_without_run_id_non_blocking', true,
                  'non_blocking_terminal_failure', true,
                  'non_blocking_terminal_failure_reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
                  'non_blocking_terminal_failure_at_utc', v_now::text,
                  'source_build_run_id_required', true,
                  'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
                )
              ELSE '{}'::jsonb
            END
          )
      WHERE dead_job.id = v_stale_row.id
      RETURNING
        dead_job.id,
        dead_job.job_type,
        dead_job.status,
        dead_job.priority,
        dead_job.run_at_utc,
        dead_job.attempt_count,
        dead_job.max_attempts,
        dead_job.dedupe_key,
        dead_job.snapshot_run_id,
        dead_job.session_id,
        dead_job.candidate_id,
        dead_job.payload_json,
        dead_job.created_at_utc,
        dead_job.updated_at_utc,
        dead_job.started_at_utc,
        dead_job.completed_at_utc,
        dead_job.failed_at_utc,
        dead_job.last_error_json
      INTO
        v_stale_row.id,
        v_stale_row.job_type,
        v_stale_row.status,
        v_stale_row.priority,
        v_stale_row.run_at_utc,
        v_stale_row.attempt_count,
        v_stale_row.max_attempts,
        v_stale_row.dedupe_key,
        v_stale_row.snapshot_run_id,
        v_stale_row.session_id,
        v_stale_row.candidate_id,
        v_stale_row.payload_json,
        v_stale_row.created_at_utc,
        v_stale_row.updated_at_utc,
        v_stale_row.started_at_utc,
        v_stale_row.completed_at_utc,
        v_stale_row.failed_at_utc,
        v_stale_row.last_error_json;

      IF v_stale_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
         AND v_stale_obsolete IS NOT TRUE
         AND (
           v_stale_invalid_source_build_without_run_id IS TRUE
           OR COALESCE(v_stale_row.attempt_count, 0) >= GREATEST(COALESCE(v_stale_row.max_attempts, 8), 1)
         )
         AND v_stale_row.session_id IS NOT NULL
         AND v_stale_row.candidate_id IS NOT NULL THEN
        IF v_stale_source_build_run_id_text IS NULL THEN
          v_stale_failed_source_row_count := 0;

          PERFORM public._audit_insert(
            'banking_pay_workbench_candidate_source_lines',
            v_stale_row.candidate_id::text,
            'INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_DID_NOT_MARK_ROWS_ERROR',
            jsonb_build_object(
              'session_id', v_stale_row.session_id::text,
              'candidate_id', v_stale_row.candidate_id::text,
              'bad_job_id', v_stale_row.id::text,
              'source_build_run_id', NULL::text,
              'source_change_seq', CASE WHEN v_stale_job_source_change_seq = 0 THEN NULL ELSE v_stale_job_source_change_seq END,
              'old_status', 'CURRENT_OR_DIRTY',
              'reason', 'STALE_SOURCE_BUILD_JOB_MISSING_SOURCE_BUILD_RUN_ID',
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            ),
            jsonb_build_object(
              'session_id', v_stale_row.session_id::text,
              'candidate_id', v_stale_row.candidate_id::text,
              'bad_job_id', v_stale_row.id::text,
              'source_build_run_id', NULL::text,
              'source_change_seq', CASE WHEN v_stale_job_source_change_seq = 0 THEN NULL ELSE v_stale_job_source_change_seq END,
              'affected_row_count', 0,
              'source_rows_marked_error_count', 0,
              'new_status', 'UNCHANGED',
              'reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            ),
            'INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_DID_NOT_MARK_ROWS_ERROR',
            NULL
          );

          PERFORM public._audit_insert(
            'banking_pay_workbench_session_scope',
            v_stale_row.candidate_id::text,
            'INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_IGNORED',
            jsonb_build_object(
              'session_id', v_stale_row.session_id::text,
              'candidate_id', v_stale_row.candidate_id::text,
              'bad_job_id', v_stale_row.id::text,
              'source_build_run_id', NULL::text,
              'source_change_seq', CASE WHEN v_stale_job_source_change_seq = 0 THEN NULL ELSE v_stale_job_source_change_seq END,
              'reason', 'STALE_SOURCE_BUILD_JOB_MISSING_SOURCE_BUILD_RUN_ID',
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            ),
            jsonb_build_object(
              'session_id', v_stale_row.session_id::text,
              'candidate_id', v_stale_row.candidate_id::text,
              'bad_job_id', v_stale_row.id::text,
              'source_build_run_id', NULL::text,
              'source_change_seq', CASE WHEN v_stale_job_source_change_seq = 0 THEN NULL ELSE v_stale_job_source_change_seq END,
              'scope_status_changed', false,
              'session_progress_changed', false,
              'reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            ),
            'INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_IGNORED',
            NULL
          );
        ELSE
          IF to_regclass('public.banking_pay_workbench_candidate_source_lines') IS NOT NULL THEN
            WITH failed_source_rows AS (
              UPDATE public.banking_pay_workbench_candidate_source_lines AS source_line
              SET status = 'ERROR',
                  source_row_json = COALESCE(source_line.source_row_json, '{}'::jsonb)
                    || jsonb_build_object(
                      'stale_source_build_error', jsonb_build_object(
                        'code', 'STALE_RUNNING_WORKBENCH_SOURCE_BUILD_FAILED',
                        'job_id', v_stale_row.id::text,
                        'job_type', v_stale_row.job_type,
                        'source_build_run_id', v_stale_source_build_run_id_text,
                        'failed_at_utc', v_now::text,
                        'job_error_json', COALESCE(v_stale_error_json, '{}'::jsonb),
                        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
                      )
                    ),
                  updated_at_utc = v_now
              WHERE source_line.session_id = v_stale_row.session_id
                AND source_line.candidate_id = v_stale_row.candidate_id
                AND source_line.status IN ('CURRENT', 'DIRTY')
                AND source_line.source_build_run_id::text = v_stale_source_build_run_id_text
              RETURNING source_line.id
            )
            SELECT COUNT(*)::integer
            INTO v_stale_failed_source_row_count
            FROM failed_source_rows;
          END IF;

          UPDATE public.banking_pay_workbench_session_scope AS source_scope_row
          SET status = 'SOURCE_BUILD_ERROR',
              dirty = true,
              error_json = jsonb_build_object(
                'code', 'STALE_RUNNING_WORKBENCH_SOURCE_BUILD_FAILED',
                'message', 'Candidate source build job exhausted attempts.',
                'job_id', v_stale_row.id::text,
                'job_type', v_stale_row.job_type,
                'source_build_run_id', v_stale_source_build_run_id_text,
                'source_rows_marked_error_count', COALESCE(v_stale_failed_source_row_count, 0),
                'job_error_json', COALESCE(v_stale_error_json, '{}'::jsonb)
              ),
              updated_at_utc = v_now
          WHERE source_scope_row.session_id = v_stale_row.session_id
            AND source_scope_row.candidate_id = v_stale_row.candidate_id;

          UPDATE public.banking_pay_workbench_sessions AS source_session_row
          SET progress_state = 'ERROR',
              progress_json = public.pay_workbench_session_compact_progress_json(COALESCE(source_session_row.progress_json, '{}'::jsonb), true) || jsonb_build_object(
                'last_source_build_failure_at_utc', v_now::text,
                'last_source_build_failure_job_id', v_stale_row.id::text,
                'last_source_build_failure_code', 'STALE_RUNNING_WORKBENCH_SOURCE_BUILD_FAILED',
                'last_source_build_failure_source_build_run_id', v_stale_source_build_run_id_text,
                'last_source_build_source_rows_marked_error_count', COALESCE(v_stale_failed_source_row_count, 0)
              ),
              progress_counter_version = COALESCE(source_session_row.progress_counter_version, 0) + 1,
              progress_updated_at_utc = v_now,
              updated_at_utc = v_now
          WHERE source_session_row.id = v_stale_row.session_id;
        END IF;
      END IF;

      IF v_stale_canonical_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
         AND v_stale_obsolete IS NOT TRUE
         AND COALESCE(v_stale_row.attempt_count, 0) >= GREATEST(COALESCE(v_stale_row.max_attempts, 8), 1)
         AND v_stale_row.session_id IS NOT NULL
         AND v_stale_row.candidate_id IS NOT NULL THEN
        WITH failed_lines AS (
          UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
          SET status = 'ERROR',
              error_json = jsonb_build_object(
                'code', 'STALE_RUNNING_WORKBENCH_LINE_WORK_PROCESS_FAILED',
                'message', 'Candidate line work was marked failed because its stale process job exhausted attempts.',
                'job_id', v_stale_row.id::text,
                'job_type', v_stale_row.job_type,
                'session_id', v_stale_row.session_id::text,
                'candidate_id', v_stale_row.candidate_id::text,
                'job_error_json', COALESCE(v_stale_error_json, '{}'::jsonb)
              ),
              updated_at_utc = v_now
          WHERE line_work.session_id = v_stale_row.session_id
            AND line_work.candidate_id = v_stale_row.candidate_id
            AND UPPER(BTRIM(COALESCE(line_work.status, ''))) = 'PENDING'
          RETURNING line_work.id
        )
        SELECT COUNT(*)::integer
        INTO v_stale_failed_line_work_count
        FROM failed_lines;

        IF COALESCE(v_stale_failed_line_work_count, 0) > 0 THEN
          UPDATE public.banking_pay_workbench_session_scope AS scope_row
          SET status = 'ERROR',
              dirty = true,
              error_json = jsonb_build_object(
                'code', 'STALE_RUNNING_WORKBENCH_LINE_WORK_PROCESS_FAILED',
                'message', 'Candidate line work process job exhausted attempts.',
                'job_id', v_stale_row.id::text,
                'line_work_failed_count', v_stale_failed_line_work_count,
                'job_error_json', COALESCE(v_stale_error_json, '{}'::jsonb)
              ),
              updated_at_utc = v_now
          WHERE scope_row.session_id = v_stale_row.session_id
            AND scope_row.candidate_id = v_stale_row.candidate_id;

          UPDATE public.banking_pay_workbench_sessions AS session_row
          SET line_units_pending = GREATEST(COALESCE(session_row.line_units_pending, 0) - COALESCE(v_stale_failed_line_work_count, 0), 0),
              line_units_failed = GREATEST(COALESCE(session_row.line_units_failed, 0) + COALESCE(v_stale_failed_line_work_count, 0), 0),
              progress_state = 'ERROR',
              progress_json = public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true) || jsonb_build_object(
                'last_line_process_failure_at_utc', v_now::text,
                'last_line_process_failure_job_id', v_stale_row.id::text,
                'last_line_process_failure_code', 'STALE_RUNNING_WORKBENCH_LINE_WORK_PROCESS_FAILED',
                'last_line_process_failure_count', v_stale_failed_line_work_count
              ),
              progress_counter_version = COALESCE(session_row.progress_counter_version, 0) + 1,
              progress_updated_at_utc = v_now,
              updated_at_utc = v_now
          WHERE session_row.id = v_stale_row.session_id;
        END IF;
      END IF;

      v_stale_after_json := jsonb_build_object(
        'id', v_stale_row.id::text,
        'job_type', v_stale_row.job_type,
        'status', v_stale_row.status,
        'priority', v_stale_row.priority,
        'run_at_utc', v_stale_row.run_at_utc,
        'attempt_count', v_stale_row.attempt_count,
        'max_attempts', v_stale_row.max_attempts,
        'dedupe_key', v_stale_row.dedupe_key,
        'snapshot_run_id', CASE WHEN v_stale_row.snapshot_run_id IS NULL THEN NULL ELSE v_stale_row.snapshot_run_id::text END,
        'session_id', CASE WHEN v_stale_row.session_id IS NULL THEN NULL ELSE v_stale_row.session_id::text END,
        'candidate_id', CASE WHEN v_stale_row.candidate_id IS NULL THEN NULL ELSE v_stale_row.candidate_id::text END,
        'payload_json', v_stale_row.payload_json,
        'created_at_utc', v_stale_row.created_at_utc,
        'updated_at_utc', v_stale_row.updated_at_utc,
        'started_at_utc', v_stale_row.started_at_utc,
        'completed_at_utc', v_stale_row.completed_at_utc,
        'failed_at_utc', v_stale_row.failed_at_utc,
        'last_error_json', v_stale_row.last_error_json,
        'last_activity_utc', COALESCE(
          v_stale_row.updated_at_utc,
          v_stale_row.started_at_utc,
          v_stale_row.run_at_utc,
          v_stale_row.created_at_utc
        ),
        'stale_recovery', true,
        'failed_terminal', true,
        'stale_cutoff_utc', v_stale_cutoff,
        'stale_running_seconds', v_stale_running_seconds,
        'obsolete', v_stale_obsolete,
        'obsolete_reason', v_stale_obsolete_reason,
        'line_work_failed_count', COALESCE(v_stale_failed_line_work_count, 0),
        'source_rows_marked_error_count', COALESCE(v_stale_failed_source_row_count, 0),
        'invalid_source_build_without_run_id_non_blocking', COALESCE(v_stale_invalid_source_build_without_run_id, false),
        'non_blocking_terminal_failure', COALESCE(v_stale_invalid_source_build_without_run_id, false)
      );

      v_dead_stale := v_dead_stale || jsonb_build_array(
        jsonb_build_object(
          'job_id', v_stale_row.id::text,
          'job_type', v_stale_row.job_type,
          'priority', v_stale_row.priority,
          'run_at_utc', v_stale_row.run_at_utc,
          'attempt_count', v_stale_row.attempt_count,
          'max_attempts', v_stale_row.max_attempts,
          'snapshot_run_id', CASE WHEN v_stale_row.snapshot_run_id IS NULL THEN NULL ELSE v_stale_row.snapshot_run_id::text END,
          'session_id', CASE WHEN v_stale_row.session_id IS NULL THEN NULL ELSE v_stale_row.session_id::text END,
          'candidate_id', CASE WHEN v_stale_row.candidate_id IS NULL THEN NULL ELSE v_stale_row.candidate_id::text END,
          'payload_json', v_stale_row.payload_json,
          'failed_at_utc', v_stale_row.failed_at_utc,
          'last_error_json', v_stale_row.last_error_json,
          'obsolete', v_stale_obsolete,
          'obsolete_reason', v_stale_obsolete_reason,
          'source_build_run_id', v_stale_source_build_run_id_text,
          'invalid_source_build_without_run_id_failed_closed', COALESCE(v_stale_invalid_source_build_without_run_id, false),
          'invalid_source_build_without_run_id_non_blocking', COALESCE(v_stale_invalid_source_build_without_run_id, false),
          'non_blocking_terminal_failure', COALESCE(v_stale_invalid_source_build_without_run_id, false),
          'source_rows_marked_error_count', COALESCE(v_stale_failed_source_row_count, 0)
        )
      );

      v_dead_stale_count := v_dead_stale_count + 1;

      PERFORM public._audit_insert(
        'banking_pay_workbench_job',
        v_stale_row.id::text,
        'FAILED',
        v_stale_before_json,
        v_stale_after_json,
        CASE
          WHEN v_stale_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
               AND v_stale_invalid_source_build_without_run_id IS TRUE
            THEN 'WORKBENCH_INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_FAILED_CLOSED'
          ELSE 'WORKBENCH_JOB_STALE_RUNNER_FAILED'
        END,
        NULL
      );
    ELSE
      UPDATE public.banking_pay_workbench_jobs AS requeue_job
      SET status = 'QUEUED',
          run_at_utc = v_cutoff,
          updated_at_utc = v_now,
          started_at_utc = NULL,
          completed_at_utc = NULL,
          failed_at_utc = NULL,
          last_error_json = v_stale_error_json
      WHERE requeue_job.id = v_stale_row.id
      RETURNING
        requeue_job.id,
        requeue_job.job_type,
        requeue_job.status,
        requeue_job.priority,
        requeue_job.run_at_utc,
        requeue_job.attempt_count,
        requeue_job.max_attempts,
        requeue_job.dedupe_key,
        requeue_job.snapshot_run_id,
        requeue_job.session_id,
        requeue_job.candidate_id,
        requeue_job.payload_json,
        requeue_job.created_at_utc,
        requeue_job.updated_at_utc,
        requeue_job.started_at_utc,
        requeue_job.completed_at_utc,
        requeue_job.failed_at_utc,
        requeue_job.last_error_json
      INTO
        v_stale_row.id,
        v_stale_row.job_type,
        v_stale_row.status,
        v_stale_row.priority,
        v_stale_row.run_at_utc,
        v_stale_row.attempt_count,
        v_stale_row.max_attempts,
        v_stale_row.dedupe_key,
        v_stale_row.snapshot_run_id,
        v_stale_row.session_id,
        v_stale_row.candidate_id,
        v_stale_row.payload_json,
        v_stale_row.created_at_utc,
        v_stale_row.updated_at_utc,
        v_stale_row.started_at_utc,
        v_stale_row.completed_at_utc,
        v_stale_row.failed_at_utc,
        v_stale_row.last_error_json;

      v_stale_after_json := jsonb_build_object(
        'id', v_stale_row.id::text,
        'job_type', v_stale_row.job_type,
        'status', v_stale_row.status,
        'priority', v_stale_row.priority,
        'run_at_utc', v_stale_row.run_at_utc,
        'attempt_count', v_stale_row.attempt_count,
        'max_attempts', v_stale_row.max_attempts,
        'dedupe_key', v_stale_row.dedupe_key,
        'snapshot_run_id', CASE WHEN v_stale_row.snapshot_run_id IS NULL THEN NULL ELSE v_stale_row.snapshot_run_id::text END,
        'session_id', CASE WHEN v_stale_row.session_id IS NULL THEN NULL ELSE v_stale_row.session_id::text END,
        'candidate_id', CASE WHEN v_stale_row.candidate_id IS NULL THEN NULL ELSE v_stale_row.candidate_id::text END,
        'payload_json', v_stale_row.payload_json,
        'created_at_utc', v_stale_row.created_at_utc,
        'updated_at_utc', v_stale_row.updated_at_utc,
        'started_at_utc', v_stale_row.started_at_utc,
        'completed_at_utc', v_stale_row.completed_at_utc,
        'failed_at_utc', v_stale_row.failed_at_utc,
        'last_error_json', v_stale_row.last_error_json,
        'last_activity_utc', COALESCE(
          v_stale_row.updated_at_utc,
          v_stale_row.started_at_utc,
          v_stale_row.run_at_utc,
          v_stale_row.created_at_utc
        ),
        'stale_recovery', true,
        'requeued', true,
        'stale_cutoff_utc', v_stale_cutoff,
        'stale_running_seconds', v_stale_running_seconds,
        'obsolete', false,
        'obsolete_reason', NULL
      );

      v_recovered_stale := v_recovered_stale || jsonb_build_array(
        jsonb_build_object(
          'job_id', v_stale_row.id::text,
          'job_type', v_stale_row.job_type,
          'priority', v_stale_row.priority,
          'run_at_utc', v_stale_row.run_at_utc,
          'attempt_count', v_stale_row.attempt_count,
          'max_attempts', v_stale_row.max_attempts,
          'snapshot_run_id', CASE WHEN v_stale_row.snapshot_run_id IS NULL THEN NULL ELSE v_stale_row.snapshot_run_id::text END,
          'session_id', CASE WHEN v_stale_row.session_id IS NULL THEN NULL ELSE v_stale_row.session_id::text END,
          'candidate_id', CASE WHEN v_stale_row.candidate_id IS NULL THEN NULL ELSE v_stale_row.candidate_id::text END,
          'payload_json', v_stale_row.payload_json,
          'updated_at_utc', v_stale_row.updated_at_utc,
          'last_error_json', v_stale_row.last_error_json
        )
      );

      v_recovered_stale_count := v_recovered_stale_count + 1;

      PERFORM public._audit_insert(
        'banking_pay_workbench_job',
        v_stale_row.id::text,
        'REQUEUED',
        v_stale_before_json,
        v_stale_after_json,
        'WORKBENCH_JOB_STALE_RUNNER_REQUEUED',
        NULL
      );
    END IF;
  END LOOP;

  BEGIN
    WITH visible_due AS (
      SELECT
        claim_job.id,
        claim_job.job_type,
        claim_job.priority,
        claim_job.run_at_utc,
        claim_job.session_id,
        claim_job.candidate_id,
        claim_job.created_at_utc
      FROM public.banking_pay_workbench_jobs AS claim_job
      WHERE claim_job.status = 'QUEUED'
        AND claim_job.run_at_utc <= v_cutoff
        AND (p_session_id IS NULL OR claim_job.session_id = p_session_id)
        AND (p_candidate_id IS NULL OR claim_job.candidate_id = p_candidate_id)
        AND (
          v_allowed_job_types IS NULL
          OR claim_job.job_type = ANY(v_allowed_job_types)
          OR UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) = ANY(v_allowed_job_types)
          OR (
            CASE
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED_PAGE', 'SCOPE_SEED_PAGE')
                THEN 'WORKBENCH_SESSION_SCOPE_SEED'
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE')
                THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
                THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
                WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE')
                  THEN 'WORKBENCH_SESSION_CLONE_REBASE'
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE', 'CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED_PAGE', 'LINE_WORK_SEED_PAGE', 'SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH')
                THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'LINE_WORK_PROCESS', 'LINE_WORK_PROCESS_CHUNK')
                THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE_CHUNK', 'PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROW_MATERIALISE_CHUNK', 'PREVIEW_ROW_MATERIALIZE_CHUNK')
                THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
              ELSE UPPER(BTRIM(COALESCE(claim_job.job_type, '')))
            END
          ) = ANY(v_allowed_job_types)
        )
      ORDER BY claim_job.priority ASC, claim_job.run_at_utc ASC, claim_job.created_at_utc ASC, claim_job.id ASC
      LIMIT v_limit
    )
    SELECT
      COALESCE(COUNT(*), 0)::integer,
      COALESCE(
        jsonb_agg(
          jsonb_build_object(
            'job_id', visible_due.id::text,
            'job_type', visible_due.job_type,
            'priority', visible_due.priority,
            'run_at_utc', visible_due.run_at_utc,
            'session_id', CASE WHEN visible_due.session_id IS NULL THEN NULL ELSE visible_due.session_id::text END,
            'candidate_id', CASE WHEN visible_due.candidate_id IS NULL THEN NULL ELSE visible_due.candidate_id::text END,
            'created_at_utc', visible_due.created_at_utc
          )
          ORDER BY visible_due.priority ASC, visible_due.run_at_utc ASC, visible_due.created_at_utc ASC, visible_due.id ASC
        ),
        '[]'::jsonb
      )
    INTO v_preclaim_due_queued_count, v_preclaim_due_queued_sample
    FROM visible_due;
  EXCEPTION WHEN OTHERS THEN
    v_preclaim_due_queued_count := 0;
    v_preclaim_due_queued_sample := '[]'::jsonb;
  END;

  -- Latest-wins queue compaction for queued DELTA jobs.
  -- This collapses repeated lifecycle flips for the same session/candidate/timesheet hot key
  -- before expensive projection work is claimed.  It does not touch payment economics.
  BEGIN
    WITH queued_delta AS (
      SELECT
        delta_job.id,
        delta_job.priority,
        delta_job.run_at_utc,
        delta_job.created_at_utc,
        delta_job.updated_at_utc,
        delta_job.payload_json,
        delta_job.dedupe_key,
        COALESCE(
          NULLIF(BTRIM(COALESCE(
            delta_job.payload_json->>'normalised_delta_family_key',
            delta_job.payload_json->>'delta_family_key',
            delta_job.payload_json->>'delta_coalescing_key',
            ''
          )), ''),
          (
          SELECT
            'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
            || ':session:' || COALESCE(NULLIF(BTRIM(COALESCE(
              delta_job.session_id::text,
              (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'session_id',
              (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'workbench_session_id',
              (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'source_session_id',
              (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'target_session_id',
              ''
            )), ''), 'none')
            || ':version:' || COALESCE(
              CASE
                WHEN delta_family_values.session_version_text ~ '^-?[0-9]{1,18}$'
                  THEN delta_family_values.session_version_text::bigint
                ELSE COALESCE(NULL::bigint, 0)::bigint
              END,
              0
            )::text
            || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
              NULLIF(delta_family_values.projection_mode_text, ''),
              NULLIF(NULL::text, ''),
              'DELTA'
            ))), ''), 'DELTA')
            || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
              NULLIF(delta_family_values.projection_class_text, ''),
              NULLIF(NULL::text, ''),
              'UNKNOWN'
            ))), ''), 'UNKNOWN')
            || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
              NULLIF(delta_family_values.refresh_scope_kind_text, ''),
              NULLIF(NULL::text, ''),
              CASE
                WHEN jsonb_array_length(COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)) > 0
                  OR jsonb_array_length(COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)) > 0
                  THEN 'TARGETED_TIMESHEETS'
                ELSE 'CANDIDATE_FULL_LIVE'
              END
            ))), ''), 'CANDIDATE_FULL_LIVE')
            || ':candidate:' || COALESCE(NULLIF(BTRIM(COALESCE(
              delta_job.candidate_id::text,
              (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'candidate_id',
              ((COALESCE(delta_job.payload_json, '{}'::jsonb))#>>'{candidate,id}'),
              ''
            )), ''), 'none')
            || ':timesheets:' || md5(
              COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)::text
              || ':'
              || COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)::text
            )
          FROM (
            SELECT
              NULLIF(BTRIM(COALESCE(
                (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'session_version',
                (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'workbench_session_version',
                (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'version',
                CASE WHEN NULL::bigint IS NULL THEN NULL ELSE (NULL::bigint)::text END,
                '0'
              )), '') AS session_version_text,
              UPPER(BTRIM(COALESCE(
                NULLIF((COALESCE(delta_job.payload_json, '{}'::jsonb))->>'projection_mode', ''),
                NULLIF((COALESCE(delta_job.payload_json, '{}'::jsonb))->>'resolved_mode', ''),
                NULLIF((COALESCE(delta_job.payload_json, '{}'::jsonb))->>'mode', ''),
                NULLIF(NULL::text, ''),
                'DELTA'
              ))) AS projection_mode_text,
              UPPER(BTRIM(COALESCE(
                NULLIF((COALESCE(delta_job.payload_json, '{}'::jsonb))->>'projection_class', ''),
                NULLIF((COALESCE(delta_job.payload_json, '{}'::jsonb))->>'classifier_projection_class', ''),
                NULLIF(((COALESCE(delta_job.payload_json, '{}'::jsonb))#>>'{classifier_result,projection_class}'), ''),
                NULLIF(NULL::text, ''),
                'UNKNOWN'
              ))) AS projection_class_text,
              UPPER(BTRIM(COALESCE(
                NULLIF((COALESCE(delta_job.payload_json, '{}'::jsonb))->>'refresh_scope_kind', ''),
                NULLIF((COALESCE(delta_job.payload_json, '{}'::jsonb))->>'scope_kind', ''),
                NULLIF(((COALESCE(delta_job.payload_json, '{}'::jsonb))#>>'{source_build,refresh_scope_kind}'), ''),
                NULLIF(((COALESCE(delta_job.payload_json, '{}'::jsonb))#>>'{preview_decisions_json,refresh_scope_kind}'), ''),
                NULLIF(NULL::text, '')
              ))) AS refresh_scope_kind_text
          ) AS delta_family_values
          CROSS JOIN (
            SELECT COALESCE(jsonb_agg(delta_family_targeted_sorted.timesheet_id_text ORDER BY delta_family_targeted_sorted.timesheet_id_text), '[]'::jsonb) AS targeted_timesheet_ids_json
            FROM (
              SELECT DISTINCT NULLIF(BTRIM(delta_family_targeted_raw.value), '') AS timesheet_id_text
              FROM jsonb_array_elements_text(
                CASE
                  WHEN jsonb_typeof((COALESCE(delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'array'
                    THEN (COALESCE(delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids'
                  WHEN jsonb_typeof((COALESCE(delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'string'
                    THEN jsonb_build_array((COALESCE(delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_ids')
                  WHEN jsonb_typeof(((COALESCE(delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')) = 'array'
                    THEN ((COALESCE(delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')
                  WHEN jsonb_typeof(((COALESCE(delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')) = 'array'
                    THEN ((COALESCE(delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')
                  WHEN NULLIF(BTRIM(COALESCE(
                         (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                         (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'timesheet_id',
                         ''
                       )), '') IS NOT NULL
                    THEN jsonb_build_array(COALESCE(
                      (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                      (COALESCE(delta_job.payload_json, '{}'::jsonb))->>'timesheet_id'
                    ))
                  ELSE '[]'::jsonb
                END
              ) AS delta_family_targeted_raw(value)
              WHERE NULLIF(BTRIM(delta_family_targeted_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            ) AS delta_family_targeted_sorted
          ) AS delta_family_targeted
          CROSS JOIN (
            SELECT COALESCE(jsonb_agg(delta_family_linked_sorted.timesheet_id_text ORDER BY delta_family_linked_sorted.timesheet_id_text), '[]'::jsonb) AS linked_timesheet_ids_json
            FROM (
              SELECT DISTINCT NULLIF(BTRIM(delta_family_linked_raw.value), '') AS timesheet_id_text
              FROM jsonb_array_elements_text(
                CASE
                  WHEN jsonb_typeof((COALESCE(delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'array'
                    THEN (COALESCE(delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids'
                  WHEN jsonb_typeof((COALESCE(delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'string'
                    THEN jsonb_build_array((COALESCE(delta_job.payload_json, '{}'::jsonb))->>'linked_timesheet_ids')
                  WHEN jsonb_typeof(((COALESCE(delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')) = 'array'
                    THEN ((COALESCE(delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')
                  WHEN jsonb_typeof(((COALESCE(delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')) = 'array'
                    THEN ((COALESCE(delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')
                  ELSE '[]'::jsonb
                END
              ) AS delta_family_linked_raw(value)
              WHERE NULLIF(BTRIM(delta_family_linked_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            ) AS delta_family_linked_sorted
          ) AS delta_family_linked
          )
        ) AS hot_key,
        GREATEST(
          CASE WHEN COALESCE(delta_job.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$'
            THEN (delta_job.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
          CASE WHEN COALESCE(delta_job.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$'
            THEN (delta_job.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END,
          CASE WHEN COALESCE(delta_job.payload_json->>'source_change_sequence', '') ~ '^-?[0-9]{1,18}$'
            THEN (delta_job.payload_json->>'source_change_sequence')::bigint ELSE 0::bigint END
        ) AS source_change_seq
      FROM public.banking_pay_workbench_jobs AS delta_job
      WHERE delta_job.status = 'QUEUED'
        AND delta_job.run_at_utc <= v_cutoff
        AND (p_session_id IS NULL OR delta_job.session_id = p_session_id)
        AND (p_candidate_id IS NULL OR delta_job.candidate_id = p_candidate_id)
        AND UPPER(BTRIM(COALESCE(delta_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
        AND (
          v_allowed_job_types IS NULL
          OR delta_job.job_type = ANY(v_allowed_job_types)
          OR UPPER(BTRIM(COALESCE(delta_job.job_type, ''))) = ANY(v_allowed_job_types)
          OR 'WORKBENCH_CANDIDATE_DELTA_REFRESH' = ANY(v_allowed_job_types)
        )
      ORDER BY delta_job.priority ASC, delta_job.run_at_utc ASC, delta_job.created_at_utc ASC, delta_job.id ASC
      LIMIT GREATEST(v_limit * 10, 50)
      FOR UPDATE SKIP LOCKED
    ),
    ranked_delta AS (
      SELECT
        queued_delta.*,
        ROW_NUMBER() OVER (
          PARTITION BY queued_delta.hot_key
          ORDER BY queued_delta.source_change_seq DESC, queued_delta.priority ASC, queued_delta.run_at_utc ASC, queued_delta.updated_at_utc DESC NULLS LAST, queued_delta.created_at_utc DESC, queued_delta.id DESC
        ) AS hot_key_rank,
        COUNT(*) OVER (PARTITION BY queued_delta.hot_key) AS hot_key_count,
        MAX(queued_delta.source_change_seq) OVER (PARTITION BY queued_delta.hot_key) AS latest_hot_key_seq
      FROM queued_delta
      WHERE NULLIF(BTRIM(COALESCE(queued_delta.hot_key, '')), '') IS NOT NULL
    ),
    kept_heads AS (
      UPDATE public.banking_pay_workbench_jobs AS head_job
      SET payload_json = jsonb_strip_nulls(
            COALESCE(head_job.payload_json, '{}'::jsonb)
            || jsonb_build_object(
              'delta_coalesced_queue_head', true,
              'delta_coalesced_queue_duplicate_count', GREATEST(ranked_delta.hot_key_count - 1, 0),
              'latest_source_change_seq', ranked_delta.latest_hot_key_seq,
              'source_change_seq', ranked_delta.latest_hot_key_seq,
              'source_change_sequence', ranked_delta.latest_hot_key_seq,
              'claim_coalesced_at_utc', v_now::text,
              'delta_family_key', ranked_delta.hot_key,
              'normalised_delta_family_key', ranked_delta.hot_key,
              'delta_coalescing_key', ranked_delta.hot_key
            )
          ),
          updated_at_utc = v_now
      FROM ranked_delta
      WHERE head_job.id = ranked_delta.id
        AND ranked_delta.hot_key_rank = 1
        AND ranked_delta.hot_key_count > 1
      RETURNING head_job.id, ranked_delta.hot_key
    ),
    superseded_delta AS (
      UPDATE public.banking_pay_workbench_jobs AS obsolete_job
      SET status = 'SUCCEEDED',
          completed_at_utc = v_now,
          updated_at_utc = v_now,
          last_error_json = NULL::jsonb,
          payload_json = jsonb_strip_nulls(
            COALESCE(obsolete_job.payload_json, '{}'::jsonb)
            || jsonb_build_object(
              'superseded_by_delta_queue_coalescing', true,
              'superseded_by_delta_queue_coalescing_at_utc', v_now::text,
              'superseded_reason', 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ_BEFORE_CLAIM',
              'latest_source_change_seq', ranked_delta.latest_hot_key_seq,
              'coalesced_hot_key', ranked_delta.hot_key,
              'delta_family_key', ranked_delta.hot_key,
              'normalised_delta_family_key', ranked_delta.hot_key
            )
          )
      FROM ranked_delta
      WHERE obsolete_job.id = ranked_delta.id
        AND ranked_delta.hot_key_rank > 1
      RETURNING obsolete_job.id, ranked_delta.hot_key
    )
    SELECT
      COALESCE((SELECT COUNT(*) FROM superseded_delta), 0)::integer,
      GREATEST(
        COALESCE((SELECT COUNT(DISTINCT superseded_delta.hot_key) FROM superseded_delta), 0),
        COALESCE((SELECT COUNT(DISTINCT kept_heads.hot_key) FROM kept_heads), 0)
      )::integer
    INTO v_delta_queued_coalesced_count, v_delta_queued_coalesced_hot_key_count;
  EXCEPTION WHEN OTHERS THEN
    -- Queue compaction is an optimisation.  Claiming must continue if diagnostic payloads are malformed.
    v_delta_queued_coalesced_count := 0;
    v_delta_queued_coalesced_hot_key_count := 0;
  END;

  IF v_allowed_job_types IS NULL
     OR 'WORKBENCH_CANDIDATE_DELTA_REFRESH' = ANY(v_allowed_job_types) THEN
    WITH queued_delta_continuation AS (
      SELECT
        stale_job.id,
        stale_job.session_id,
        stale_job.candidate_id,
        stale_job.payload_json,
        stale_job.created_at_utc,
        COALESCE(live_change.seq, 0) AS live_source_change_seq,
        GREATEST(
          COALESCE(CASE WHEN COALESCE(stale_job.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (stale_job.payload_json->>'latest_source_change_seq')::bigint END, 0),
          COALESCE(CASE WHEN COALESCE(stale_job.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (stale_job.payload_json->>'source_change_seq')::bigint END, 0),
          COALESCE(CASE WHEN COALESCE(stale_job.payload_json->>'source_change_sequence', '') ~ '^-?[0-9]{1,18}$' THEN (stale_job.payload_json->>'source_change_sequence')::bigint END, 0)
        ) AS payload_source_change_seq,
        GREATEST(
          COALESCE(CASE WHEN COALESCE(stale_job.payload_json#>>'{cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (stale_job.payload_json#>>'{cursor,source_change_seq}')::bigint END, 0),
          COALESCE(CASE WHEN COALESCE(stale_job.payload_json#>>'{cursor,cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (stale_job.payload_json#>>'{cursor,cursor,source_change_seq}')::bigint END, 0),
          COALESCE(CASE WHEN COALESCE(stale_job.payload_json#>>'{cursor_json,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (stale_job.payload_json#>>'{cursor_json,source_change_seq}')::bigint END, 0),
          COALESCE(CASE WHEN COALESCE(stale_job.payload_json#>>'{cursor_json,cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (stale_job.payload_json#>>'{cursor_json,cursor,source_change_seq}')::bigint END, 0),
          COALESCE(CASE WHEN COALESCE(stale_job.payload_json#>>'{result_json,next_cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (stale_job.payload_json#>>'{result_json,next_cursor,source_change_seq}')::bigint END, 0),
          COALESCE(CASE WHEN COALESCE(stale_job.payload_json#>>'{result_json,next_cursor,cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (stale_job.payload_json#>>'{result_json,next_cursor,cursor,source_change_seq}')::bigint END, 0),
          COALESCE(CASE WHEN COALESCE(stale_job.payload_json#>>'{result_json,next_cursor_json,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (stale_job.payload_json#>>'{result_json,next_cursor_json,source_change_seq}')::bigint END, 0),
          COALESCE(CASE WHEN COALESCE(stale_job.payload_json#>>'{result_json,next_cursor_json,cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (stale_job.payload_json#>>'{result_json,next_cursor_json,cursor,source_change_seq}')::bigint END, 0)
        ) AS cursor_source_change_seq,
        COALESCE(projection_run.source_change_seq, 0) AS projection_run_source_change_seq,
        COALESCE(stale_job.payload_json->>'normalised_delta_family_key', stale_job.payload_json->>'delta_family_key', stale_job.payload_json->>'delta_coalescing_key', '') AS normalised_delta_family_key,
        projection_id.projection_run_id_text,
        projection_id.projection_run_id
      FROM public.banking_pay_workbench_jobs AS stale_job
      CROSS JOIN LATERAL (
        SELECT
          COALESCE(
            stale_job.payload_json->>'projection_run_id',
            stale_job.payload_json#>>'{cursor,projection_run_id}',
            stale_job.payload_json#>>'{cursor,cursor,projection_run_id}',
            stale_job.payload_json#>>'{cursor_json,projection_run_id}',
            stale_job.payload_json#>>'{cursor_json,cursor,projection_run_id}',
            stale_job.payload_json#>>'{result_json,next_cursor,projection_run_id}',
            stale_job.payload_json#>>'{result_json,next_cursor,cursor,projection_run_id}',
            stale_job.payload_json#>>'{result_json,next_cursor_json,projection_run_id}',
            stale_job.payload_json#>>'{result_json,next_cursor_json,cursor,projection_run_id}',
            ''
          ) AS projection_run_id_text
      ) AS projection_id_text
      CROSS JOIN LATERAL (
        SELECT
          projection_id_text.projection_run_id_text,
          CASE
            WHEN projection_id_text.projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              THEN projection_id_text.projection_run_id_text::uuid
            ELSE NULL::uuid
          END AS projection_run_id
      ) AS projection_id
      LEFT JOIN public.app_change_counters AS live_change
        ON live_change.entity_key = 'pay_candidate:' || stale_job.candidate_id::text
      LEFT JOIN public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run
        ON projection_run.id = projection_id.projection_run_id
      WHERE stale_job.status = 'QUEUED'
        AND stale_job.run_at_utc <= v_cutoff
        AND (p_session_id IS NULL OR stale_job.session_id = p_session_id)
        AND (p_candidate_id IS NULL OR stale_job.candidate_id = p_candidate_id)
        AND UPPER(BTRIM(COALESCE(stale_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
        AND (
          lower(BTRIM(COALESCE(stale_job.payload_json->>'continuation', 'false'))) IN ('true','t','1','yes','y','on')
          OR UPPER(BTRIM(COALESCE(stale_job.payload_json->>'run_mode', ''))) = 'BOUNDED_CONTINUATION'
          OR jsonb_typeof(stale_job.payload_json->'cursor') = 'object'
          OR jsonb_typeof(stale_job.payload_json->'cursor_json') = 'object'
          OR jsonb_typeof(stale_job.payload_json#>'{result_json,next_cursor}') = 'object'
          OR jsonb_typeof(stale_job.payload_json#>'{result_json,next_cursor_json}') = 'object'
        )
      ORDER BY stale_job.priority ASC, stale_job.run_at_utc ASC, stale_job.created_at_utc ASC, stale_job.id ASC
      LIMIT GREATEST(v_limit * 10, 50)
      FOR UPDATE OF stale_job SKIP LOCKED
    ), stale_delta_continuation AS (
      SELECT qdc.*
      FROM queued_delta_continuation AS qdc
      WHERE (
        (COALESCE(qdc.cursor_source_change_seq, 0) > 0 AND GREATEST(COALESCE(qdc.live_source_change_seq, 0), COALESCE(qdc.payload_source_change_seq, 0)) > COALESCE(qdc.cursor_source_change_seq, 0))
        OR (COALESCE(qdc.projection_run_source_change_seq, 0) > 0 AND GREATEST(COALESCE(qdc.live_source_change_seq, 0), COALESCE(qdc.payload_source_change_seq, 0)) > COALESCE(qdc.projection_run_source_change_seq, 0))
      )
    ), terminalised_delta_projection AS MATERIALIZED (
      SELECT
        stale_delta_continuation.*,
        public._pay_workbench_delta_projection_terminalise_if_orphaned(
          p_projection_run_id => stale_delta_continuation.projection_run_id,
          p_session_id => stale_delta_continuation.session_id,
          p_candidate_id => stale_delta_continuation.candidate_id,
          p_superseded_job_id => stale_delta_continuation.id,
          p_payload_source_change_seq => stale_delta_continuation.payload_source_change_seq,
          p_cursor_source_change_seq => stale_delta_continuation.cursor_source_change_seq,
          p_projection_run_source_change_seq => stale_delta_continuation.projection_run_source_change_seq,
          p_live_candidate_source_change_seq => stale_delta_continuation.live_source_change_seq,
          p_reason => 'STALE_CONTINUATION_SUPERSEDED_BEFORE_CLAIM',
          p_now_utc => v_now,
          p_actor_user_id => NULL::uuid
        ) AS terminalise_json
      FROM stale_delta_continuation
    ), superseded_delta_continuation AS (
      UPDATE public.banking_pay_workbench_jobs AS upd_stale
      SET status = 'SUCCEEDED',
          completed_at_utc = v_now,
          updated_at_utc = v_now,
          last_error_json = NULL::jsonb,
          payload_json = jsonb_strip_nulls(
            COALESCE(upd_stale.payload_json, '{}'::jsonb)
            || jsonb_build_object(
              'superseded_stale_continuation_before_claim', true,
              'superseded_reason', 'STALE_CONTINUATION_SUPERSEDED_BEFORE_CLAIM',
              'superseded_at_utc', v_now::text,
              'payload_source_change_seq', terminalised_delta_projection.payload_source_change_seq,
              'cursor_source_change_seq', terminalised_delta_projection.cursor_source_change_seq,
              'projection_run_source_change_seq', terminalised_delta_projection.projection_run_source_change_seq,
              'live_candidate_source_change_seq', terminalised_delta_projection.live_source_change_seq,
              'normalised_delta_family_key', terminalised_delta_projection.normalised_delta_family_key,
              'projection_run_id', NULLIF(terminalised_delta_projection.projection_run_id_text, ''),
              'projection_run_terminalised', lower(BTRIM(COALESCE(terminalised_delta_projection.terminalise_json->>'projection_run_terminalised', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
              'projection_run_status_after', terminalised_delta_projection.terminalise_json->>'projection_run_status_after',
              'projection_run_terminalised_reason', terminalised_delta_projection.terminalise_json->>'projection_run_terminalised_reason',
              'projection_run_terminalisation_json', terminalised_delta_projection.terminalise_json,
              'no_active_continuation_job', lower(BTRIM(COALESCE(terminalised_delta_projection.terminalise_json->>'no_active_continuation_job', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
              'candidate_serial_unblocked', lower(BTRIM(COALESCE(terminalised_delta_projection.terminalise_json->>'candidate_serial_unblocked', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            )
          )
      FROM terminalised_delta_projection
      WHERE upd_stale.id = terminalised_delta_projection.id
      RETURNING upd_stale.id,
                terminalised_delta_projection.session_id,
                terminalised_delta_projection.candidate_id,
                terminalised_delta_projection.normalised_delta_family_key,
                terminalised_delta_projection.payload_source_change_seq,
                terminalised_delta_projection.cursor_source_change_seq,
                terminalised_delta_projection.projection_run_source_change_seq,
                terminalised_delta_projection.live_source_change_seq,
                terminalised_delta_projection.projection_run_id_text,
                terminalised_delta_projection.projection_run_id,
                terminalised_delta_projection.terminalise_json
    )
    SELECT COALESCE(COUNT(*), 0)::integer,
           COALESCE(jsonb_agg(jsonb_build_object(
             'job_id', superseded_delta_continuation.id::text,
             'session_id', superseded_delta_continuation.session_id::text,
             'candidate_id', superseded_delta_continuation.candidate_id::text,
             'normalised_delta_family_key', superseded_delta_continuation.normalised_delta_family_key,
             'payload_source_change_seq', superseded_delta_continuation.payload_source_change_seq,
             'cursor_source_change_seq', superseded_delta_continuation.cursor_source_change_seq,
             'projection_run_source_change_seq', superseded_delta_continuation.projection_run_source_change_seq,
             'live_candidate_source_change_seq', superseded_delta_continuation.live_source_change_seq,
             'projection_run_id', NULLIF(superseded_delta_continuation.projection_run_id_text, ''),
             'projection_run_terminalised', lower(BTRIM(COALESCE(superseded_delta_continuation.terminalise_json->>'projection_run_terminalised', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
             'projection_run_status_after', superseded_delta_continuation.terminalise_json->>'projection_run_status_after',
             'projection_run_terminalised_reason', superseded_delta_continuation.terminalise_json->>'projection_run_terminalised_reason',
             'no_active_continuation_job', lower(BTRIM(COALESCE(superseded_delta_continuation.terminalise_json->>'no_active_continuation_job', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
             'candidate_serial_unblocked', lower(BTRIM(COALESCE(superseded_delta_continuation.terminalise_json->>'candidate_serial_unblocked', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
             'projection_terminalisation_json', superseded_delta_continuation.terminalise_json
           ) ORDER BY superseded_delta_continuation.id), '[]'::jsonb),
           COALESCE(COUNT(*) FILTER (WHERE lower(BTRIM(COALESCE(superseded_delta_continuation.terminalise_json->>'projection_run_terminalised', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')), 0)::integer,
           COALESCE(jsonb_agg(jsonb_build_object(
             'job_id', superseded_delta_continuation.id::text,
             'projection_run_id', NULLIF(superseded_delta_continuation.projection_run_id_text, ''),
             'projection_run_terminalised', lower(BTRIM(COALESCE(superseded_delta_continuation.terminalise_json->>'projection_run_terminalised', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
             'projection_run_status_after', superseded_delta_continuation.terminalise_json->>'projection_run_status_after',
             'projection_run_terminalised_reason', superseded_delta_continuation.terminalise_json->>'projection_run_terminalised_reason',
             'no_active_continuation_job', lower(BTRIM(COALESCE(superseded_delta_continuation.terminalise_json->>'no_active_continuation_job', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
             'candidate_serial_unblocked', lower(BTRIM(COALESCE(superseded_delta_continuation.terminalise_json->>'candidate_serial_unblocked', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           ) ORDER BY superseded_delta_continuation.id) FILTER (WHERE lower(BTRIM(COALESCE(superseded_delta_continuation.terminalise_json->>'projection_run_terminalised', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')), '[]'::jsonb)
    INTO v_delta_stale_continuation_superseded_count,
         v_delta_stale_continuation_sample,
         v_delta_stale_projection_terminalised_count,
         v_delta_stale_projection_terminalisation_sample
    FROM superseded_delta_continuation;

    IF COALESCE(v_delta_stale_continuation_superseded_count, 0) > 0 THEN
      PERFORM public._audit_insert(
        'banking_pay_workbench_job',
        'delta_stale_continuation_preclaim',
        'STALE_CONTINUATION_SUPERSEDED_BEFORE_CLAIM',
        NULL::jsonb,
        jsonb_build_object(
          'superseded_stale_continuation_count', v_delta_stale_continuation_superseded_count,
          'projection_run_terminalised_count', COALESCE(v_delta_stale_projection_terminalised_count, 0),
          'projection_run_terminalised', COALESCE(v_delta_stale_projection_terminalised_count, 0) > 0,
          'projection_terminalisation_sample', COALESCE(v_delta_stale_projection_terminalisation_sample, '[]'::jsonb),
          'sample', v_delta_stale_continuation_sample,
          'claim_session_filter', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
          'claim_candidate_filter', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
          'session_progress_lock_skipped', true,
          'claimed_running_skipped', true,
          'candidate_serial_unblocked', COALESCE(v_delta_stale_projection_terminalised_count, 0) > 0,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
        ),
        'STALE_CONTINUATION_SUPERSEDED_BEFORE_CLAIM',
        NULL::uuid
      );
    END IF;
  END IF;

  FOR v_claimed_row IN
    WITH claim_source AS MATERIALIZED (
      SELECT
        claim_job.id,
        claim_job.job_type,
        claim_job.priority,
        claim_job.run_at_utc,
        claim_job.attempt_count,
        claim_job.max_attempts,
        claim_job.snapshot_run_id,
        claim_job.session_id,
        claim_job.candidate_id,
        claim_job.payload_json,
        claim_job.created_at_utc,
        public._pay_workbench_candidate_serial_candidate_id(claim_job.candidate_id, claim_job.payload_json) AS candidate_serial_candidate_id,
        public._pay_workbench_candidate_serial_key(public._pay_workbench_candidate_serial_candidate_id(claim_job.candidate_id, claim_job.payload_json)) AS candidate_serial_key,
        public._pay_workbench_candidate_serial_is_candidate_job(claim_job.job_type, claim_job.candidate_id, claim_job.payload_json) AS candidate_serial_required,
        (
          lower(BTRIM(COALESCE(claim_job.payload_json->>'continuation', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          OR UPPER(BTRIM(COALESCE(claim_job.payload_json->>'run_mode', ''))) IN ('BOUNDED_CONTINUATION', 'CONTINUATION', 'STAGE_CONTINUATION')
          OR lower(BTRIM(COALESCE(claim_job.payload_json->>'fallback_from_delta', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          OR (
            lower(BTRIM(COALESCE(claim_job.payload_json->>'source_build_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
            AND NULLIF(BTRIM(COALESCE(claim_job.payload_json->>'fallback_reason', '')), '') IS NOT NULL
          )
          OR (
            NULLIF(BTRIM(COALESCE(claim_job.payload_json->>'source_job_id', claim_job.payload_json->>'continuation_source_job_id', claim_job.payload_json->>'bounded_continuation_source_job_id', '')), '') IS NOT NULL
            AND UPPER(BTRIM(COALESCE(claim_job.payload_json->>'run_mode', ''))) NOT IN ('LATEST_STATE_HEAD', 'LATEST_RERUN_AFTER_RUNNING')
          )
        ) AS candidate_serial_is_chain_continuation,
        CASE
          WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
            THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
          ELSE UPPER(BTRIM(COALESCE(claim_job.job_type, '')))
        END AS canonical_job_type,
        CASE
          WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH') THEN
            COALESCE(
              NULLIF(BTRIM(COALESCE(
                claim_job.payload_json->>'normalised_delta_family_key',
                claim_job.payload_json->>'delta_family_key',
                claim_job.payload_json->>'delta_coalescing_key',
                ''
              )), ''),
              (
              SELECT
                'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
                || ':session:' || COALESCE(NULLIF(BTRIM(COALESCE(
                  claim_job.session_id::text,
                  (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'session_id',
                  (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'workbench_session_id',
                  (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'source_session_id',
                  (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'target_session_id',
                  ''
                )), ''), 'none')
                || ':version:' || COALESCE(
                  CASE
                    WHEN delta_family_values.session_version_text ~ '^-?[0-9]{1,18}$'
                      THEN delta_family_values.session_version_text::bigint
                    ELSE COALESCE(NULL::bigint, 0)::bigint
                  END,
                  0
                )::text
                || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                  NULLIF(delta_family_values.projection_mode_text, ''),
                  NULLIF(NULL::text, ''),
                  'DELTA'
                ))), ''), 'DELTA')
                || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                  NULLIF(delta_family_values.projection_class_text, ''),
                  NULLIF(NULL::text, ''),
                  'UNKNOWN'
                ))), ''), 'UNKNOWN')
                || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                  NULLIF(delta_family_values.refresh_scope_kind_text, ''),
                  NULLIF(NULL::text, ''),
                  CASE
                    WHEN jsonb_array_length(COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)) > 0
                      OR jsonb_array_length(COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)) > 0
                      THEN 'TARGETED_TIMESHEETS'
                    ELSE 'CANDIDATE_FULL_LIVE'
                  END
                ))), ''), 'CANDIDATE_FULL_LIVE')
                || ':candidate:' || COALESCE(NULLIF(BTRIM(COALESCE(
                  claim_job.candidate_id::text,
                  (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'candidate_id',
                  ((COALESCE(claim_job.payload_json, '{}'::jsonb))#>>'{candidate,id}'),
                  ''
                )), ''), 'none')
                || ':timesheets:' || md5(
                  COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)::text
                  || ':'
                  || COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)::text
                )
              FROM (
                SELECT
                  NULLIF(BTRIM(COALESCE(
                    (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'session_version',
                    (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'workbench_session_version',
                    (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'version',
                    CASE WHEN NULL::bigint IS NULL THEN NULL ELSE (NULL::bigint)::text END,
                    '0'
                  )), '') AS session_version_text,
                  UPPER(BTRIM(COALESCE(
                    NULLIF((COALESCE(claim_job.payload_json, '{}'::jsonb))->>'projection_mode', ''),
                    NULLIF((COALESCE(claim_job.payload_json, '{}'::jsonb))->>'resolved_mode', ''),
                    NULLIF((COALESCE(claim_job.payload_json, '{}'::jsonb))->>'mode', ''),
                    NULLIF(NULL::text, ''),
                    'DELTA'
                  ))) AS projection_mode_text,
                  UPPER(BTRIM(COALESCE(
                    NULLIF((COALESCE(claim_job.payload_json, '{}'::jsonb))->>'projection_class', ''),
                    NULLIF((COALESCE(claim_job.payload_json, '{}'::jsonb))->>'classifier_projection_class', ''),
                    NULLIF(((COALESCE(claim_job.payload_json, '{}'::jsonb))#>>'{classifier_result,projection_class}'), ''),
                    NULLIF(NULL::text, ''),
                    'UNKNOWN'
                  ))) AS projection_class_text,
                  UPPER(BTRIM(COALESCE(
                    NULLIF((COALESCE(claim_job.payload_json, '{}'::jsonb))->>'refresh_scope_kind', ''),
                    NULLIF((COALESCE(claim_job.payload_json, '{}'::jsonb))->>'scope_kind', ''),
                    NULLIF(((COALESCE(claim_job.payload_json, '{}'::jsonb))#>>'{source_build,refresh_scope_kind}'), ''),
                    NULLIF(((COALESCE(claim_job.payload_json, '{}'::jsonb))#>>'{preview_decisions_json,refresh_scope_kind}'), ''),
                    NULLIF(NULL::text, '')
                  ))) AS refresh_scope_kind_text
              ) AS delta_family_values
              CROSS JOIN (
                SELECT COALESCE(jsonb_agg(delta_family_targeted_sorted.timesheet_id_text ORDER BY delta_family_targeted_sorted.timesheet_id_text), '[]'::jsonb) AS targeted_timesheet_ids_json
                FROM (
                  SELECT DISTINCT NULLIF(BTRIM(delta_family_targeted_raw.value), '') AS timesheet_id_text
                  FROM jsonb_array_elements_text(
                    CASE
                      WHEN jsonb_typeof((COALESCE(claim_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'array'
                        THEN (COALESCE(claim_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids'
                      WHEN jsonb_typeof((COALESCE(claim_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'string'
                        THEN jsonb_build_array((COALESCE(claim_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_ids')
                      WHEN jsonb_typeof(((COALESCE(claim_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')) = 'array'
                        THEN ((COALESCE(claim_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')
                      WHEN jsonb_typeof(((COALESCE(claim_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')) = 'array'
                        THEN ((COALESCE(claim_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')
                      WHEN NULLIF(BTRIM(COALESCE(
                             (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                             (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'timesheet_id',
                             ''
                           )), '') IS NOT NULL
                        THEN jsonb_build_array(COALESCE(
                          (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                          (COALESCE(claim_job.payload_json, '{}'::jsonb))->>'timesheet_id'
                        ))
                      ELSE '[]'::jsonb
                    END
                  ) AS delta_family_targeted_raw(value)
                  WHERE NULLIF(BTRIM(delta_family_targeted_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                ) AS delta_family_targeted_sorted
              ) AS delta_family_targeted
              CROSS JOIN (
                SELECT COALESCE(jsonb_agg(delta_family_linked_sorted.timesheet_id_text ORDER BY delta_family_linked_sorted.timesheet_id_text), '[]'::jsonb) AS linked_timesheet_ids_json
                FROM (
                  SELECT DISTINCT NULLIF(BTRIM(delta_family_linked_raw.value), '') AS timesheet_id_text
                  FROM jsonb_array_elements_text(
                    CASE
                      WHEN jsonb_typeof((COALESCE(claim_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'array'
                        THEN (COALESCE(claim_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids'
                      WHEN jsonb_typeof((COALESCE(claim_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'string'
                        THEN jsonb_build_array((COALESCE(claim_job.payload_json, '{}'::jsonb))->>'linked_timesheet_ids')
                      WHEN jsonb_typeof(((COALESCE(claim_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')) = 'array'
                        THEN ((COALESCE(claim_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')
                      WHEN jsonb_typeof(((COALESCE(claim_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')) = 'array'
                        THEN ((COALESCE(claim_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')
                      ELSE '[]'::jsonb
                    END
                  ) AS delta_family_linked_raw(value)
                  WHERE NULLIF(BTRIM(delta_family_linked_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                ) AS delta_family_linked_sorted
              ) AS delta_family_linked
              )
            )
          ELSE COALESCE(
            NULLIF(BTRIM(COALESCE(claim_job.payload_json->>'coalescing_key', '')), ''),
            claim_job.dedupe_key,
            claim_job.id::text
          )
        END AS hot_key
      FROM public.banking_pay_workbench_jobs AS claim_job
      WHERE claim_job.status = 'QUEUED'
        AND claim_job.run_at_utc <= v_cutoff
        AND (p_session_id IS NULL OR claim_job.session_id = p_session_id)
        AND (p_candidate_id IS NULL OR claim_job.candidate_id = p_candidate_id)
        AND (
          v_allowed_job_types IS NULL
          OR claim_job.job_type = ANY(v_allowed_job_types)
          OR UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) = ANY(v_allowed_job_types)
          OR (
            CASE
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED_PAGE', 'SCOPE_SEED_PAGE')
                THEN 'WORKBENCH_SESSION_SCOPE_SEED'
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE')
                THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
                THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE')
                THEN 'WORKBENCH_SESSION_CLONE_REBASE'
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE', 'CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED_PAGE', 'LINE_WORK_SEED_PAGE', 'SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH')
                THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'LINE_WORK_PROCESS', 'LINE_WORK_PROCESS_CHUNK')
                THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
              WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE_CHUNK', 'PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROW_MATERIALISE_CHUNK', 'PREVIEW_ROW_MATERIALIZE_CHUNK')
                THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
              ELSE UPPER(BTRIM(COALESCE(claim_job.job_type, '')))
            END
          ) = ANY(v_allowed_job_types)
        )
      ORDER BY
        candidate_serial_is_chain_continuation DESC,
        claim_job.priority ASC,
        claim_job.run_at_utc ASC,
        claim_job.created_at_utc ASC,
        claim_job.id ASC
      LIMIT GREATEST(v_limit * 5, v_limit)
    ),
    claim_pool AS MATERIALIZED (
      SELECT
        claim_source.*,
        ROW_NUMBER() OVER (
          PARTITION BY CASE
            WHEN claim_source.canonical_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN claim_source.hot_key
            ELSE claim_source.id::text
          END
          ORDER BY claim_source.priority ASC, claim_source.run_at_utc ASC, claim_source.created_at_utc ASC, claim_source.id ASC
        ) AS hot_key_rank,
        ROW_NUMBER() OVER (
          PARTITION BY COALESCE(claim_source.candidate_serial_key, claim_source.id::text)
          ORDER BY
            CASE WHEN claim_source.candidate_serial_required IS TRUE AND claim_source.candidate_serial_is_chain_continuation IS TRUE THEN 0 ELSE 1 END ASC,
            claim_source.priority ASC,
            claim_source.run_at_utc ASC,
            claim_source.created_at_utc ASC,
            claim_source.id ASC
        ) AS candidate_serial_rank
      FROM claim_source
    ),
    eligible_claim AS MATERIALIZED (
      SELECT claim_pool.*
      FROM claim_pool
      CROSS JOIN LATERAL (
        SELECT public._pay_workbench_candidate_serial_active_state(
          claim_pool.id,
          claim_pool.candidate_serial_candidate_id,
          claim_pool.job_type,
          claim_pool.payload_json,
          v_now
        ) AS state_json
      ) AS candidate_serial_state
      WHERE claim_pool.hot_key_rank = 1
        AND (
          claim_pool.candidate_serial_required IS NOT TRUE
          OR claim_pool.candidate_serial_rank = 1
        )
        AND (
          claim_pool.candidate_serial_required IS NOT TRUE
          OR lower(BTRIM(COALESCE(candidate_serial_state.state_json->>'blocked', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        )
        AND NOT (
          claim_pool.canonical_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
          AND (
            lower(BTRIM(COALESCE(claim_pool.payload_json->>'continuation', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
            OR UPPER(BTRIM(COALESCE(claim_pool.payload_json->>'run_mode', ''))) = 'BOUNDED_CONTINUATION'
            OR jsonb_typeof(claim_pool.payload_json->'cursor') = 'object'
            OR jsonb_typeof(claim_pool.payload_json->'cursor_json') = 'object'
          )
          AND COALESCE((
            SELECT
              (
                COALESCE(delta_claim_staleness.cursor_source_change_seq, 0) > 0
                AND GREATEST(
                  COALESCE(delta_claim_live_change.seq, 0),
                  COALESCE(delta_claim_staleness.payload_source_change_seq, 0)
                ) > COALESCE(delta_claim_staleness.cursor_source_change_seq, 0)
              )
              OR (
                COALESCE(delta_claim_projection_run.source_change_seq, 0) > 0
                AND GREATEST(
                  COALESCE(delta_claim_live_change.seq, 0),
                  COALESCE(delta_claim_staleness.payload_source_change_seq, 0)
                ) > COALESCE(delta_claim_projection_run.source_change_seq, 0)
              )
            FROM (
              SELECT
                GREATEST(
                  COALESCE(CASE WHEN COALESCE(claim_pool.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json->>'latest_source_change_seq')::bigint END, 0),
                  COALESCE(CASE WHEN COALESCE(claim_pool.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json->>'source_change_seq')::bigint END, 0),
                  COALESCE(CASE WHEN COALESCE(claim_pool.payload_json->>'source_change_sequence', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json->>'source_change_sequence')::bigint END, 0)
                ) AS payload_source_change_seq,
                GREATEST(
                  COALESCE(CASE WHEN COALESCE(claim_pool.payload_json#>>'{cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json#>>'{cursor,source_change_seq}')::bigint END, 0),
                  COALESCE(CASE WHEN COALESCE(claim_pool.payload_json#>>'{cursor,cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json#>>'{cursor,cursor,source_change_seq}')::bigint END, 0),
                  COALESCE(CASE WHEN COALESCE(claim_pool.payload_json#>>'{cursor_json,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json#>>'{cursor_json,source_change_seq}')::bigint END, 0),
                  COALESCE(CASE WHEN COALESCE(claim_pool.payload_json#>>'{cursor_json,cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json#>>'{cursor_json,cursor,source_change_seq}')::bigint END, 0),
                  COALESCE(CASE WHEN COALESCE(claim_pool.payload_json#>>'{result_json,next_cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json#>>'{result_json,next_cursor,source_change_seq}')::bigint END, 0),
                  COALESCE(CASE WHEN COALESCE(claim_pool.payload_json#>>'{result_json,next_cursor,cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json#>>'{result_json,next_cursor,cursor,source_change_seq}')::bigint END, 0),
                  COALESCE(CASE WHEN COALESCE(claim_pool.payload_json#>>'{result_json,next_cursor_json,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json#>>'{result_json,next_cursor_json,source_change_seq}')::bigint END, 0),
                  COALESCE(CASE WHEN COALESCE(claim_pool.payload_json#>>'{result_json,next_cursor_json,cursor,source_change_seq}', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json#>>'{result_json,next_cursor_json,cursor,source_change_seq}')::bigint END, 0)
                ) AS cursor_source_change_seq,
                COALESCE(
                  claim_pool.payload_json->>'projection_run_id',
                  claim_pool.payload_json#>>'{cursor,projection_run_id}',
                  claim_pool.payload_json#>>'{cursor,cursor,projection_run_id}',
                  claim_pool.payload_json#>>'{cursor_json,projection_run_id}',
                  claim_pool.payload_json#>>'{cursor_json,cursor,projection_run_id}',
                  claim_pool.payload_json#>>'{result_json,next_cursor,projection_run_id}',
                  claim_pool.payload_json#>>'{result_json,next_cursor,cursor,projection_run_id}',
                  claim_pool.payload_json#>>'{result_json,next_cursor_json,projection_run_id}',
                  claim_pool.payload_json#>>'{result_json,next_cursor_json,cursor,projection_run_id}',
                  ''
                ) AS projection_run_id_text
            ) AS delta_claim_staleness
            LEFT JOIN public.app_change_counters AS delta_claim_live_change
              ON delta_claim_live_change.entity_key = 'pay_candidate:' || claim_pool.candidate_id::text
            LEFT JOIN public.banking_pay_workbench_candidate_delta_projection_runs AS delta_claim_projection_run
              ON delta_claim_projection_run.id = CASE
                   WHEN delta_claim_staleness.projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                     THEN delta_claim_staleness.projection_run_id_text::uuid
                   ELSE NULL::uuid
                 END
          ), false)
        )
        AND NOT (
          claim_pool.canonical_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
          AND EXISTS (
            SELECT 1
            FROM public.banking_pay_workbench_jobs AS running_delta_job
            WHERE running_delta_job.status = 'RUNNING'
              AND running_delta_job.id IS DISTINCT FROM claim_pool.id
              AND running_delta_job.session_id IS NOT DISTINCT FROM claim_pool.session_id
              AND running_delta_job.candidate_id IS NOT DISTINCT FROM claim_pool.candidate_id
              AND UPPER(BTRIM(COALESCE(running_delta_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
              AND COALESCE(
                    NULLIF(BTRIM(COALESCE(
                      running_delta_job.payload_json->>'normalised_delta_family_key',
                      running_delta_job.payload_json->>'delta_family_key',
                      running_delta_job.payload_json->>'delta_coalescing_key',
                      ''
                    )), ''),
                    (
                    SELECT
                      'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
                      || ':session:' || COALESCE(NULLIF(BTRIM(COALESCE(
                        running_delta_job.session_id::text,
                        (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'session_id',
                        (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_id',
                        (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'source_session_id',
                        (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'target_session_id',
                        ''
                      )), ''), 'none')
                      || ':version:' || COALESCE(
                        CASE
                          WHEN delta_family_values.session_version_text ~ '^-?[0-9]{1,18}$'
                            THEN delta_family_values.session_version_text::bigint
                          ELSE COALESCE(CASE WHEN COALESCE(claim_pool.payload_json->>'session_version', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json->>'session_version')::bigint ELSE NULL::bigint END, 0)::bigint
                        END,
                        0
                      )::text
                      || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                        NULLIF(delta_family_values.projection_mode_text, ''),
                        NULLIF(NULLIF(UPPER(BTRIM(COALESCE(claim_pool.payload_json->>'projection_mode', claim_pool.payload_json->>'resolved_mode', ''))), ''), ''),
                        'DELTA'
                      ))), ''), 'DELTA')
                      || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                        NULLIF(delta_family_values.projection_class_text, ''),
                        NULLIF(NULLIF(UPPER(BTRIM(COALESCE(claim_pool.payload_json->>'projection_class', ''))), ''), ''),
                        'UNKNOWN'
                      ))), ''), 'UNKNOWN')
                      || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                        NULLIF(delta_family_values.refresh_scope_kind_text, ''),
                        NULLIF(NULLIF(UPPER(BTRIM(COALESCE(claim_pool.payload_json->>'refresh_scope_kind', ''))), ''), ''),
                        CASE
                          WHEN jsonb_array_length(COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)) > 0
                            OR jsonb_array_length(COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)) > 0
                            THEN 'TARGETED_TIMESHEETS'
                          ELSE 'CANDIDATE_FULL_LIVE'
                        END
                      ))), ''), 'CANDIDATE_FULL_LIVE')
                      || ':candidate:' || COALESCE(NULLIF(BTRIM(COALESCE(
                        running_delta_job.candidate_id::text,
                        (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'candidate_id',
                        ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{candidate,id}'),
                        ''
                      )), ''), 'none')
                      || ':timesheets:' || md5(
                        COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)::text
                        || ':'
                        || COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)::text
                      )
                    FROM (
                      SELECT
                        NULLIF(BTRIM(COALESCE(
                          (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'session_version',
                          (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_version',
                          (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'version',
                          CASE WHEN CASE WHEN COALESCE(claim_pool.payload_json->>'session_version', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json->>'session_version')::bigint ELSE NULL::bigint END IS NULL THEN NULL ELSE (CASE WHEN COALESCE(claim_pool.payload_json->>'session_version', '') ~ '^-?[0-9]{1,18}$' THEN (claim_pool.payload_json->>'session_version')::bigint ELSE NULL::bigint END)::text END,
                          '0'
                        )), '') AS session_version_text,
                        UPPER(BTRIM(COALESCE(
                          NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'projection_mode', ''),
                          NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'resolved_mode', ''),
                          NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'mode', ''),
                          NULLIF(NULLIF(UPPER(BTRIM(COALESCE(claim_pool.payload_json->>'projection_mode', claim_pool.payload_json->>'resolved_mode', ''))), ''), ''),
                          'DELTA'
                        ))) AS projection_mode_text,
                        UPPER(BTRIM(COALESCE(
                          NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'projection_class', ''),
                          NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'classifier_projection_class', ''),
                          NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{classifier_result,projection_class}'), ''),
                          NULLIF(NULLIF(UPPER(BTRIM(COALESCE(claim_pool.payload_json->>'projection_class', ''))), ''), ''),
                          'UNKNOWN'
                        ))) AS projection_class_text,
                        UPPER(BTRIM(COALESCE(
                          NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'refresh_scope_kind', ''),
                          NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'scope_kind', ''),
                          NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{source_build,refresh_scope_kind}'), ''),
                          NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{preview_decisions_json,refresh_scope_kind}'), ''),
                          NULLIF(NULLIF(UPPER(BTRIM(COALESCE(claim_pool.payload_json->>'refresh_scope_kind', ''))), ''), '')
                        ))) AS refresh_scope_kind_text
                    ) AS delta_family_values
                    CROSS JOIN (
                      SELECT COALESCE(jsonb_agg(delta_family_targeted_sorted.timesheet_id_text ORDER BY delta_family_targeted_sorted.timesheet_id_text), '[]'::jsonb) AS targeted_timesheet_ids_json
                      FROM (
                        SELECT DISTINCT NULLIF(BTRIM(delta_family_targeted_raw.value), '') AS timesheet_id_text
                        FROM jsonb_array_elements_text(
                          CASE
                            WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'array'
                              THEN (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids'
                            WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'string'
                              THEN jsonb_build_array((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_ids')
                            WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')) = 'array'
                              THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')
                            WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')) = 'array'
                              THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')
                            WHEN NULLIF(BTRIM(COALESCE(
                                   (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                                   (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id',
                                   ''
                                 )), '') IS NOT NULL
                              THEN jsonb_build_array(COALESCE(
                                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id'
                              ))
                            ELSE '[]'::jsonb
                          END
                        ) AS delta_family_targeted_raw(value)
                        WHERE NULLIF(BTRIM(delta_family_targeted_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                      ) AS delta_family_targeted_sorted
                    ) AS delta_family_targeted
                    CROSS JOIN (
                      SELECT COALESCE(jsonb_agg(delta_family_linked_sorted.timesheet_id_text ORDER BY delta_family_linked_sorted.timesheet_id_text), '[]'::jsonb) AS linked_timesheet_ids_json
                      FROM (
                        SELECT DISTINCT NULLIF(BTRIM(delta_family_linked_raw.value), '') AS timesheet_id_text
                        FROM jsonb_array_elements_text(
                          CASE
                            WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'array'
                              THEN (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids'
                            WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'string'
                              THEN jsonb_build_array((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'linked_timesheet_ids')
                            WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')) = 'array'
                              THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')
                            WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')) = 'array'
                              THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')
                            ELSE '[]'::jsonb
                          END
                        ) AS delta_family_linked_raw(value)
                        WHERE NULLIF(BTRIM(delta_family_linked_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                      ) AS delta_family_linked_sorted
                    ) AS delta_family_linked
                    )
                  ) = claim_pool.hot_key
          )
        )
      ORDER BY claim_pool.priority ASC, claim_pool.run_at_utc ASC, claim_pool.created_at_utc ASC, claim_pool.id ASC
      LIMIT v_limit
    ),
    candidate_locked_claim AS MATERIALIZED (
      SELECT
        eligible_claim.*,
        CASE
          WHEN eligible_claim.candidate_serial_required IS NOT TRUE THEN true
          ELSE pg_try_advisory_xact_lock(hashtextextended(eligible_claim.candidate_serial_key, 24062027))
        END AS candidate_advisory_lock_granted
      FROM eligible_claim
    ),
    hot_key_locked_claim AS MATERIALIZED (
      SELECT
        candidate_locked_claim.*,
        CASE
          WHEN candidate_locked_claim.canonical_job_type <> 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN true
          ELSE pg_try_advisory_xact_lock(
            hashtextextended(
              COALESCE(NULLIF(BTRIM(candidate_locked_claim.hot_key), ''), candidate_locked_claim.id::text),
              24062026
            )
          )
        END AS hot_key_advisory_lock_granted
      FROM candidate_locked_claim
      WHERE candidate_locked_claim.candidate_advisory_lock_granted IS TRUE
    ),
    claim AS MATERIALIZED (
      SELECT hot_key_locked_claim.*
      FROM hot_key_locked_claim
      WHERE hot_key_locked_claim.hot_key_advisory_lock_granted IS TRUE
    ),
    upd AS (
      UPDATE public.banking_pay_workbench_jobs AS upd_job
      SET status = 'RUNNING',
          attempt_count = COALESCE(upd_job.attempt_count, 0) + 1,
          started_at_utc = COALESCE(upd_job.started_at_utc, v_now),
          updated_at_utc = v_now,
          completed_at_utc = NULL,
          failed_at_utc = NULL,
          last_error_json = NULL,
          payload_json = CASE
            WHEN claim_row.canonical_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
              jsonb_strip_nulls(
                COALESCE(upd_job.payload_json, '{}'::jsonb)
                || jsonb_build_object(
                  'latest_source_change_seq', GREATEST(
                    COALESCE(live_change.seq, 0),
                    CASE WHEN COALESCE(upd_job.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$'
                      THEN (upd_job.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
                    CASE WHEN COALESCE(upd_job.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$'
                      THEN (upd_job.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END,
                    CASE WHEN COALESCE(upd_job.payload_json->>'source_change_sequence', '') ~ '^-?[0-9]{1,18}$'
                      THEN (upd_job.payload_json->>'source_change_sequence')::bigint ELSE 0::bigint END
                  ),
                  'source_change_seq', GREATEST(
                    COALESCE(live_change.seq, 0),
                    CASE WHEN COALESCE(upd_job.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$'
                      THEN (upd_job.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
                    CASE WHEN COALESCE(upd_job.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$'
                      THEN (upd_job.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END,
                    CASE WHEN COALESCE(upd_job.payload_json->>'source_change_sequence', '') ~ '^-?[0-9]{1,18}$'
                      THEN (upd_job.payload_json->>'source_change_sequence')::bigint ELSE 0::bigint END
                  ),
                  'source_change_sequence', GREATEST(
                    COALESCE(live_change.seq, 0),
                    CASE WHEN COALESCE(upd_job.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$'
                      THEN (upd_job.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
                    CASE WHEN COALESCE(upd_job.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$'
                      THEN (upd_job.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END,
                    CASE WHEN COALESCE(upd_job.payload_json->>'source_change_sequence', '') ~ '^-?[0-9]{1,18}$'
                      THEN (upd_job.payload_json->>'source_change_sequence')::bigint ELSE 0::bigint END
                  ),
                  'claim_live_source_guard_applied', true,
                  'claim_live_source_seq', COALESCE(live_change.seq, 0),
                  'claimed_delta_hot_key', claim_row.hot_key,
                  'delta_family_key', claim_row.hot_key,
                  'normalised_delta_family_key', claim_row.hot_key,
                  'delta_coalescing_key', claim_row.hot_key,
                  'claimed_at_utc', v_now::text,
                  'candidate_serial_key', CASE WHEN claim_row.candidate_serial_required IS TRUE THEN claim_row.candidate_serial_key ELSE NULL END,
                  'candidate_serial_candidate_id', CASE WHEN claim_row.candidate_serial_candidate_id IS NULL THEN NULL ELSE claim_row.candidate_serial_candidate_id::text END,
                  'candidate_serial_active_chain_id', CASE WHEN claim_row.candidate_serial_required IS TRUE THEN COALESCE(NULLIF(BTRIM(COALESCE(upd_job.payload_json->>'candidate_serial_active_chain_id', '')), ''), NULLIF(BTRIM(COALESCE(upd_job.payload_json->>'source_job_id', '')), ''), upd_job.id::text) ELSE NULL END,
                  'candidate_serial_source_job_id', NULLIF(BTRIM(COALESCE(upd_job.payload_json->>'source_job_id', '')), ''),
                  'candidate_serial_started_at_utc', CASE WHEN claim_row.candidate_serial_required IS TRUE THEN v_now::text ELSE NULL END,
                  'candidate_serial_reason', CASE WHEN claim_row.candidate_serial_required IS TRUE THEN 'CANDIDATE_SERIAL_CLAIM_GRANTED' ELSE NULL END
                )
              )
            ELSE
              CASE WHEN claim_row.candidate_serial_required IS TRUE THEN
                jsonb_strip_nulls(
                  COALESCE(upd_job.payload_json, '{}'::jsonb)
                  || jsonb_build_object(
                    'claimed_at_utc', v_now::text,
                    'candidate_serial_key', claim_row.candidate_serial_key,
                    'candidate_serial_candidate_id', CASE WHEN claim_row.candidate_serial_candidate_id IS NULL THEN NULL ELSE claim_row.candidate_serial_candidate_id::text END,
                    'candidate_serial_active_chain_id', COALESCE(NULLIF(BTRIM(COALESCE(upd_job.payload_json->>'candidate_serial_active_chain_id', '')), ''), NULLIF(BTRIM(COALESCE(upd_job.payload_json->>'source_job_id', '')), ''), upd_job.id::text),
                    'candidate_serial_source_job_id', NULLIF(BTRIM(COALESCE(upd_job.payload_json->>'source_job_id', '')), ''),
                    'candidate_serial_started_at_utc', v_now::text,
                    'candidate_serial_reason', 'CANDIDATE_SERIAL_CLAIM_GRANTED'
                  )
                )
              ELSE upd_job.payload_json END
          END
      FROM claim AS claim_row
      LEFT JOIN public.app_change_counters AS live_change
        ON live_change.entity_key = 'pay_candidate:' || COALESCE(claim_row.candidate_serial_candidate_id, claim_row.candidate_id)::text
      WHERE upd_job.id = claim_row.id
        AND upd_job.status = 'QUEUED'
        AND upd_job.run_at_utc <= v_cutoff
      RETURNING
        upd_job.id,
        upd_job.job_type,
        upd_job.priority,
        upd_job.run_at_utc,
        upd_job.attempt_count,
        upd_job.max_attempts,
        upd_job.snapshot_run_id,
        upd_job.session_id,
        upd_job.candidate_id,
        upd_job.payload_json,
        upd_job.started_at_utc,
        upd_job.created_at_utc
    )
    SELECT
      upd.id,
      upd.job_type,
      upd.priority,
      upd.run_at_utc,
      upd.attempt_count,
      upd.max_attempts,
      upd.snapshot_run_id,
      upd.session_id,
      upd.candidate_id,
      upd.payload_json,
      upd.started_at_utc,
      upd.created_at_utc
    FROM upd
    ORDER BY upd.priority ASC, upd.run_at_utc ASC, upd.created_at_utc ASC, upd.id ASC
  LOOP
    v_claimed := v_claimed || jsonb_build_array(
      jsonb_build_object(
        'job_id', v_claimed_row.id::text,
        'job_type', v_claimed_row.job_type,
        'priority', v_claimed_row.priority,
        'run_at_utc', v_claimed_row.run_at_utc,
        'attempt_count', v_claimed_row.attempt_count,
        'max_attempts', v_claimed_row.max_attempts,
        'snapshot_run_id', CASE WHEN v_claimed_row.snapshot_run_id IS NULL THEN NULL ELSE v_claimed_row.snapshot_run_id::text END,
        'session_id', CASE WHEN v_claimed_row.session_id IS NULL THEN NULL ELSE v_claimed_row.session_id::text END,
        'candidate_id', CASE WHEN v_claimed_row.candidate_id IS NULL THEN NULL ELSE v_claimed_row.candidate_id::text END,
        'payload_json', v_claimed_row.payload_json,
        'started_at_utc', v_claimed_row.started_at_utc,
        'created_at_utc', v_claimed_row.created_at_utc
      )
    );

    v_claimed_count := v_claimed_count + 1;
    IF UPPER(BTRIM(COALESCE(v_claimed_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH') THEN
      v_claimed_delta_refresh_count := v_claimed_delta_refresh_count + 1;
    ELSIF UPPER(BTRIM(COALESCE(v_claimed_row.job_type, ''))) IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE') THEN
      v_claimed_clone_rebase_count := v_claimed_clone_rebase_count + 1;
    END IF;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_claimed_row.id::text,
      'RUNNING',
      NULL,
      jsonb_build_object(
        'id', v_claimed_row.id::text,
        'job_type', v_claimed_row.job_type,
        'status', 'RUNNING',
        'attempt_count', v_claimed_row.attempt_count,
        'max_attempts', v_claimed_row.max_attempts,
        'run_at_utc', v_claimed_row.run_at_utc,
        'started_at_utc', v_claimed_row.started_at_utc,
        'snapshot_run_id', CASE WHEN v_claimed_row.snapshot_run_id IS NULL THEN NULL ELSE v_claimed_row.snapshot_run_id::text END,
        'session_id', CASE WHEN v_claimed_row.session_id IS NULL THEN NULL ELSE v_claimed_row.session_id::text END,
        'candidate_id', CASE WHEN v_claimed_row.candidate_id IS NULL THEN NULL ELSE v_claimed_row.candidate_id::text END,
        'candidate_serial_key', v_claimed_row.payload_json->>'candidate_serial_key',
        'candidate_serial_active_chain_id', v_claimed_row.payload_json->>'candidate_serial_active_chain_id'
      ),
      'WORKBENCH_JOB_CLAIMED',
      NULL
    );

    IF NULLIF(BTRIM(COALESCE(v_claimed_row.payload_json->>'candidate_serial_key', '')), '') IS NOT NULL THEN
      PERFORM public._pay_workbench_candidate_serial_audit(
        'CANDIDATE_SERIAL_CLAIM_GRANTED',
        v_claimed_row.id,
        public._pay_workbench_candidate_serial_candidate_id(v_claimed_row.candidate_id, v_claimed_row.payload_json),
        jsonb_build_object(
          'job_type', v_claimed_row.job_type,
          'candidate_serial_key', v_claimed_row.payload_json->>'candidate_serial_key',
          'candidate_serial_active_chain_id', v_claimed_row.payload_json->>'candidate_serial_active_chain_id',
          'claimed_at_utc', v_now::text
        ),
        'CANDIDATE_SERIAL_CLAIM_GRANTED',
        NULL::uuid
      );
    END IF;
  END LOOP;

  v_claim_mismatch_detected := (
    v_claimed_count = 0
    AND v_preclaim_due_queued_count > 0
    AND v_recovered_stale_count = 0
    AND v_dead_stale_count = 0
  );
  v_claim_lock_contention_detected := false;
  v_claim_lock_contention_count := 0;
  IF v_claim_mismatch_detected IS TRUE THEN
    BEGIN
      WITH visible_due AS (
        SELECT
          claim_job.id,
          claim_job.job_type,
          claim_job.status,
          claim_job.priority,
          claim_job.run_at_utc,
          claim_job.created_at_utc,
          claim_job.started_at_utc,
          claim_job.attempt_count,
          claim_job.max_attempts,
          claim_job.session_id,
          claim_job.candidate_id,
          claim_job.dedupe_key,
          COALESCE(claim_job.payload_json, '{}'::jsonb) AS payload_json,
          CASE
            WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED_PAGE', 'SCOPE_SEED_PAGE')
              THEN 'WORKBENCH_SESSION_SCOPE_SEED'
            WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE')
              THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
            WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
              THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
            WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE')
              THEN 'WORKBENCH_SESSION_CLONE_REBASE'
            WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE', 'CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED_PAGE', 'LINE_WORK_SEED_PAGE', 'SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH')
              THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
            WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'LINE_WORK_PROCESS', 'LINE_WORK_PROCESS_CHUNK')
              THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
            WHEN UPPER(BTRIM(COALESCE(claim_job.job_type, ''))) IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE_CHUNK', 'PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROW_MATERIALISE_CHUNK', 'PREVIEW_ROW_MATERIALIZE_CHUNK')
              THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
            ELSE UPPER(BTRIM(COALESCE(claim_job.job_type, '')))
          END AS canonical_job_type
        FROM public.banking_pay_workbench_jobs AS claim_job
        WHERE UPPER(BTRIM(COALESCE(claim_job.status, ''))) = 'QUEUED'
          AND claim_job.run_at_utc <= v_cutoff
          AND (p_session_id IS NULL OR claim_job.session_id = p_session_id)
          AND (p_candidate_id IS NULL OR claim_job.candidate_id = p_candidate_id)
        ORDER BY claim_job.priority ASC, claim_job.run_at_utc ASC, claim_job.created_at_utc ASC, claim_job.id ASC
        LIMIT 5
      ),
      enriched AS (
        SELECT
          vd.*,
          public._pay_workbench_candidate_serial_candidate_id(vd.candidate_id, vd.payload_json) AS derived_candidate_id,
          public._pay_workbench_candidate_serial_is_candidate_job(vd.job_type, vd.candidate_id, vd.payload_json) AS is_candidate_job,
          public._pay_workbench_candidate_serial_key(public._pay_workbench_candidate_serial_candidate_id(vd.candidate_id, vd.payload_json)) AS derived_candidate_serial_key,
          public._pay_workbench_candidate_serial_active_state(
            vd.id,
            public._pay_workbench_candidate_serial_candidate_id(vd.candidate_id, vd.payload_json),
            vd.job_type,
            vd.payload_json,
            v_now
          ) AS serial_state_json
        FROM visible_due AS vd
      ),
      rejected AS (
        SELECT
          e.*,
          (
            SELECT same_job.id
            FROM public.banking_pay_workbench_jobs AS same_job
            WHERE same_job.id IS DISTINCT FROM e.id
              AND UPPER(BTRIM(COALESCE(same_job.status, ''))) = 'RUNNING'
              AND public._pay_workbench_candidate_serial_candidate_id(same_job.candidate_id, same_job.payload_json) = e.derived_candidate_id
              AND public._pay_workbench_candidate_serial_is_candidate_job(same_job.job_type, same_job.candidate_id, same_job.payload_json)
            ORDER BY same_job.started_at_utc ASC NULLS FIRST, same_job.created_at_utc ASC, same_job.id ASC
            LIMIT 1
          ) AS same_candidate_active_job_id,
          (
            SELECT same_projection.id
            FROM public.banking_pay_workbench_candidate_delta_projection_runs AS same_projection
            WHERE same_projection.candidate_id = e.derived_candidate_id
              AND UPPER(BTRIM(COALESCE(same_projection.status, ''))) IN ('RUNNING', 'PROCESSING', 'IN_PROGRESS')
            ORDER BY same_projection.started_at_utc ASC NULLS FIRST, same_projection.updated_at_utc ASC NULLS FIRST, same_projection.id ASC
            LIMIT 1
          ) AS same_candidate_active_projection_run_id,
          CASE
            WHEN UPPER(BTRIM(COALESCE(e.status, ''))) <> 'QUEUED' THEN 'JOB_STATUS_CHANGED_BEFORE_UPDATE'
            WHEN e.run_at_utc > v_cutoff THEN 'RUN_AT_CHANGED_OR_NOT_DUE'
            WHEN v_allowed_job_types IS NOT NULL AND NOT (e.canonical_job_type = ANY(v_allowed_job_types) OR e.job_type = ANY(v_allowed_job_types) OR UPPER(BTRIM(COALESCE(e.job_type, ''))) = ANY(v_allowed_job_types)) THEN 'ALLOWED_JOB_TYPES_FILTER_MISMATCH'
            WHEN lower(BTRIM(COALESCE(e.serial_state_json->>'candidate_serial_blocked', e.serial_state_json->>'blocked', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 'CANDIDATE_SERIAL_BLOCKED'
            WHEN e.serial_state_json->>'blocking_projection_run_id' IS NOT NULL OR e.serial_state_json->>'projection_run_id' IS NOT NULL THEN 'ACTIVE_PROJECTION_RUN'
            WHEN lower(BTRIM(COALESCE(e.payload_json->>'continuation', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') AND e.serial_state_json->>'blocked_chain_job_id' IS NOT NULL THEN 'ACTIVE_CONTINUATION'
            ELSE 'UNKNOWN_CLAIM_QUERY_MISMATCH'
          END AS claim_reject_reason
        FROM enriched AS e
      )
      SELECT
        COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
          'job_id', r.id::text,
          'job_type', r.job_type,
          'status', r.status,
          'candidate_id', CASE WHEN r.candidate_id IS NULL THEN NULL ELSE r.candidate_id::text END,
          'session_id', CASE WHEN r.session_id IS NULL THEN NULL ELSE r.session_id::text END,
          'dedupe_key', r.dedupe_key,
          'priority', r.priority,
          'run_at_utc', r.run_at_utc,
          'created_at_utc', r.created_at_utc,
          'started_at_utc', r.started_at_utc,
          'attempt_count', r.attempt_count,
          'max_attempts', r.max_attempts,
          'payload_candidate_serial_key', r.payload_json->>'candidate_serial_key',
          'payload_candidate_serial_wait_reason', r.payload_json->>'candidate_serial_wait_reason',
          'payload_projection_run_id', COALESCE(r.payload_json->>'projection_run_id', r.payload_json#>>'{cursor,projection_run_id}', r.payload_json#>>'{cursor_json,projection_run_id}'),
          'payload_source_change_seq', r.payload_json->>'source_change_seq',
          'payload_latest_source_change_seq', r.payload_json->>'latest_source_change_seq',
          'payload_continuation', r.payload_json->>'continuation',
          'payload_source_job_id', r.payload_json->>'source_job_id',
          'payload_run_mode', r.payload_json->>'run_mode',
          'payload_targeted_timesheet_ids', r.payload_json->'targeted_timesheet_ids',
          'is_candidate_job', r.is_candidate_job,
          'derived_candidate_id', CASE WHEN r.derived_candidate_id IS NULL THEN NULL ELSE r.derived_candidate_id::text END,
          'derived_candidate_serial_key', r.derived_candidate_serial_key,
          'candidate_serial_active_state', r.serial_state_json,
          'same_candidate_active_job_id', CASE WHEN r.same_candidate_active_job_id IS NULL THEN NULL ELSE r.same_candidate_active_job_id::text END,
          'same_candidate_active_projection_run_id', CASE WHEN r.same_candidate_active_projection_run_id IS NULL THEN NULL ELSE r.same_candidate_active_projection_run_id::text END,
          'advisory_lock_attempted', false,
          'advisory_lock_granted', NULL,
          'claim_filter_passed', false,
          'allowed_job_types_filter_passed', NOT (v_allowed_job_types IS NOT NULL AND NOT (r.canonical_job_type = ANY(v_allowed_job_types) OR r.job_type = ANY(v_allowed_job_types) OR UPPER(BTRIM(COALESCE(r.job_type, ''))) = ANY(v_allowed_job_types))),
          'claim_reject_reason', r.claim_reject_reason,
          'worker_id', NULL,
          'origin', 'pay_workbench_claim_due_jobs'
        )) ORDER BY r.priority ASC, r.run_at_utc ASC, r.created_at_utc ASC, r.id ASC), '[]'::jsonb),
        COALESCE(COUNT(*) FILTER (WHERE r.claim_reject_reason = 'CANDIDATE_SERIAL_BLOCKED'), 0)::integer,
        COALESCE(COUNT(*) FILTER (WHERE r.claim_reject_reason = 'ACTIVE_PROJECTION_RUN'), 0)::integer,
        COALESCE(COUNT(*) FILTER (WHERE r.claim_reject_reason = 'ALLOWED_JOB_TYPES_FILTER_MISMATCH'), 0)::integer,
        COALESCE(COUNT(*) FILTER (WHERE r.claim_reject_reason = 'JOB_STATUS_CHANGED_BEFORE_UPDATE'), 0)::integer,
        COALESCE(COUNT(*) FILTER (WHERE r.claim_reject_reason = 'OBSOLETE_OR_SUPERSEDED'), 0)::integer,
        COALESCE(COUNT(*) FILTER (WHERE r.claim_reject_reason = 'UNKNOWN_CLAIM_QUERY_MISMATCH'), 0)::integer,
        COALESCE((array_agg(r.claim_reject_reason ORDER BY r.priority ASC, r.run_at_utc ASC, r.created_at_utc ASC, r.id ASC))[1], 'UNKNOWN_CLAIM_QUERY_MISMATCH')
      INTO
        v_claimable_sample,
        v_candidate_serial_reject_count,
        v_active_projection_reject_count,
        v_allowed_job_types_reject_count,
        v_status_changed_before_claim_count,
        v_obsolete_or_superseded_reject_count,
        v_unknown_claim_query_mismatch_count,
        v_claim_mismatch_reason
      FROM rejected AS r;
    EXCEPTION WHEN OTHERS THEN
      v_claimable_sample := COALESCE(v_preclaim_due_queued_sample, '[]'::jsonb);
      v_claim_mismatch_reason := 'UNKNOWN_CLAIM_QUERY_MISMATCH';
      v_unknown_claim_query_mismatch_count := GREATEST(COALESCE(v_preclaim_due_queued_count, 0), 1);
    END;

    v_claim_reject_summary := jsonb_strip_nulls(jsonb_build_object(
      'candidate_serial_reject_count', COALESCE(v_candidate_serial_reject_count, 0),
      'advisory_lock_reject_count', COALESCE(v_advisory_lock_reject_count, 0),
      'skip_locked_or_concurrent_lock_count', COALESCE(v_skip_locked_or_concurrent_lock_count, 0),
      'allowed_job_types_reject_count', COALESCE(v_allowed_job_types_reject_count, 0),
      'status_changed_before_claim_count', COALESCE(v_status_changed_before_claim_count, 0),
      'obsolete_or_superseded_reject_count', COALESCE(v_obsolete_or_superseded_reject_count, 0),
      'active_projection_reject_count', COALESCE(v_active_projection_reject_count, 0),
      'unknown_claim_query_mismatch_count', COALESCE(v_unknown_claim_query_mismatch_count, 0)
    ));
    v_claim_mismatch_json := jsonb_strip_nulls(jsonb_build_object(
      'claim_mismatch_detected', true,
      'claim_mismatch_reason', COALESCE(v_claim_mismatch_reason, 'UNKNOWN_CLAIM_QUERY_MISMATCH'),
      'claimable_count', COALESCE(v_preclaim_due_queued_count, 0),
      'claimed_count', COALESCE(v_claimed_count, 0),
      'claimable_sample', COALESCE(v_claimable_sample, '[]'::jsonb),
      'claim_reject_summary', COALESCE(v_claim_reject_summary, '{}'::jsonb),
      'advisory_lock_reject_count', COALESCE(v_advisory_lock_reject_count, 0),
      'candidate_serial_reject_count', COALESCE(v_candidate_serial_reject_count, 0),
      'skip_locked_or_concurrent_lock_count', COALESCE(v_skip_locked_or_concurrent_lock_count, 0),
      'allowed_job_types_reject_count', COALESCE(v_allowed_job_types_reject_count, 0),
      'status_changed_before_claim_count', COALESCE(v_status_changed_before_claim_count, 0),
      'obsolete_or_superseded_reject_count', COALESCE(v_obsolete_or_superseded_reject_count, 0),
      'active_projection_reject_count', COALESCE(v_active_projection_reject_count, 0),
      'unknown_claim_query_mismatch_count', COALESCE(v_unknown_claim_query_mismatch_count, 0),
      'function_name', 'pay_workbench_claim_due_jobs',
      'stage', 'CLAIMABLE_BUT_UNCLAIMED_EXPLAIN',
      'filtered_session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
      'filtered_candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'allowed_job_types', CASE WHEN v_allowed_job_types IS NULL THEN NULL ELSE to_jsonb(v_allowed_job_types) END
    ));
    BEGIN
      PERFORM public._temp_diag_log(
        'TEMP_WORKBENCH_CLAIM_DIAG',
        'CLAIMABLE_BUT_UNCLAIMED_EXPLAIN',
        COALESCE(p_session_id::text, p_candidate_id::text, 'pay_workbench_claim_due_jobs'),
        v_claim_mismatch_json
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'server_utc', v_now,
    'cutoff_utc', v_cutoff,
    'stale_cutoff_utc', v_stale_cutoff,
    'stale_running_seconds', v_stale_running_seconds,
    'limit', v_limit,
    'stale_recovery_limit', v_stale_recovery_limit,
    'due_queued_count', v_preclaim_due_queued_count,
    'visible_due_queued_count', v_preclaim_due_queued_count,
    'claimable_count', v_preclaim_due_queued_count,
    'claimable_due_count', v_preclaim_due_queued_count,
    'claim_mismatch_detected', COALESCE(v_claim_mismatch_detected, false),
    'claim_mismatch_reason', CASE WHEN v_claim_mismatch_detected THEN COALESCE(v_claim_mismatch_reason, 'UNKNOWN_CLAIM_QUERY_MISMATCH') ELSE NULL END,
    'claim_mismatch_json', COALESCE(v_claim_mismatch_json, '{}'::jsonb),
    'claimable_sample', CASE WHEN v_claim_mismatch_detected THEN COALESCE(v_claimable_sample, '[]'::jsonb) ELSE COALESCE(v_preclaim_due_queued_sample, '[]'::jsonb) END,
    'claim_reject_summary', COALESCE(v_claim_reject_summary, '{}'::jsonb),
    'advisory_lock_reject_count', COALESCE(v_advisory_lock_reject_count, 0),
    'candidate_serial_reject_count', COALESCE(v_candidate_serial_reject_count, 0),
    'skip_locked_or_concurrent_lock_count', COALESCE(v_skip_locked_or_concurrent_lock_count, 0),
    'allowed_job_types_reject_count', COALESCE(v_allowed_job_types_reject_count, 0),
    'status_changed_before_claim_count', COALESCE(v_status_changed_before_claim_count, 0),
    'obsolete_or_superseded_reject_count', COALESCE(v_obsolete_or_superseded_reject_count, 0),
    'active_projection_reject_count', COALESCE(v_active_projection_reject_count, 0),
    'unknown_claim_query_mismatch_count', COALESCE(v_unknown_claim_query_mismatch_count, 0),
    'claim_lock_contention_detected', v_claim_lock_contention_detected,
    'lock_contention_detected', v_claim_lock_contention_detected,
    'claim_lock_contention_count', v_claim_lock_contention_count,
    'lock_contention_count', v_claim_lock_contention_count,
    'delta_queued_coalesced_count', COALESCE(v_delta_queued_coalesced_count, 0),
    'delta_queued_coalesced_hot_key_count', COALESCE(v_delta_queued_coalesced_hot_key_count, 0),
    'delta_stale_continuation_superseded_before_claim_count', COALESCE(v_delta_stale_continuation_superseded_count, 0),
    'delta_stale_continuation_superseded_before_claim_sample', COALESCE(v_delta_stale_continuation_sample, '[]'::jsonb),
    'delta_stale_projection_terminalised_before_claim_count', COALESCE(v_delta_stale_projection_terminalised_count, 0),
    'delta_stale_projection_terminalised_before_claim_sample', COALESCE(v_delta_stale_projection_terminalisation_sample, '[]'::jsonb),
    'claim_lock_contention_sample', CASE
      WHEN v_claim_lock_contention_detected THEN COALESCE(v_claimable_sample, '[]'::jsonb)
      ELSE '[]'::jsonb
    END
  )
  || jsonb_build_object(
    'filtered_session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
    'filtered_candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    'allowed_job_types', CASE WHEN v_allowed_job_types IS NULL THEN NULL ELSE to_jsonb(v_allowed_job_types) END,
    'recovered_stale_count', v_recovered_stale_count,
    'dead_stale_count', v_dead_stale_count,
    'failed_stale_count', v_dead_stale_count,
    'projection_lifecycle_repair', COALESCE(v_projection_lifecycle_repair_json, '{}'::jsonb),
    'projection_lifecycle_repaired_count', CASE WHEN COALESCE(v_projection_lifecycle_repair_json->>'repaired_count', '') ~ '^[0-9]+$' THEN (v_projection_lifecycle_repair_json->>'repaired_count')::integer ELSE 0 END,
    'invalid_source_build_poison_repair', COALESCE(v_invalid_source_build_poison_repair_json, '{}'::jsonb),
    'invalid_source_build_poison_repaired_count', CASE WHEN COALESCE(v_invalid_source_build_poison_repair_json->>'repaired_count', '') ~ '^[0-9]+$' THEN (v_invalid_source_build_poison_repair_json->>'repaired_count')::integer ELSE 0 END,
    'orphaned_pending_source_build_repair', COALESCE(v_orphaned_pending_source_build_repair_json, '{}'::jsonb),
    'orphaned_pending_source_build_repaired_count', CASE WHEN COALESCE(v_orphaned_pending_source_build_repair_json->>'repaired_count', '') ~ '^[0-9]+$' THEN (v_orphaned_pending_source_build_repair_json->>'repaired_count')::integer ELSE 0 END,
    'orphaned_pending_source_build_recovery_scheduled', LOWER(BTRIM(COALESCE(v_orphaned_pending_source_build_repair_json->>'automatic_recovery_scheduled', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    'claimed_count', v_claimed_count,
    'claimed_delta_refresh_count', COALESCE(v_claimed_delta_refresh_count, 0),
    'claimed_clone_rebase_count', COALESCE(v_claimed_clone_rebase_count, 0),
    'recovered_stale', v_recovered_stale,
    'dead_stale', v_dead_stale,
    'failed_stale', v_dead_stale,
    'claimed', v_claimed
  );
END;
$function$;

-- pay_workbench_claim_job_now(uuid,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.pay_workbench_claim_job_now(p_job_id uuid, p_now_utc timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_cutoff timestamptz := COALESCE(p_now_utc, v_now);
  v_stale_running_seconds integer := 600;
  v_stale_cutoff timestamptz := NULL;
  v_requested_job_id_text text := CASE WHEN p_job_id IS NULL THEN NULL ELSE p_job_id::text END;
  v_job_row public.banking_pay_workbench_jobs%ROWTYPE;
  v_before_json jsonb := NULL;
  v_after_json jsonb := '{}'::jsonb;
  v_claimed boolean := false;
  v_reclaimed_stale boolean := false;
  v_no_op boolean := false;
  v_terminalized boolean := false;
  v_reason text := NULL;
  v_audit_action text := NULL;
  v_audit_reason text := NULL;
  v_last_activity_utc timestamptz := NULL;
  v_supported_job_type boolean := false;
  v_due_now boolean := false;
  v_stale_now boolean := false;
  v_attempt_count_after integer := 0;
  v_max_attempts integer := 0;
  v_attempts_exhausted boolean := false;
  v_terminal_error_json jsonb := NULL;
BEGIN
  v_stale_cutoff := v_cutoff - make_interval(secs => v_stale_running_seconds);

  IF p_job_id IS NULL THEN
    v_no_op := true;
    v_reason := 'INVALID_JOB_ID';
    v_audit_action := 'CLAIM_DENIED';
    v_audit_reason := 'WORKBENCH_JOB_TARGET_CLAIM_DENIED_INVALID_JOB_ID';

    v_after_json := jsonb_build_object(
      'id', NULL,
      'job_type', NULL,
      'status', NULL,
      'priority', NULL,
      'run_at_utc', NULL,
      'attempt_count', NULL,
      'max_attempts', NULL,
      'dedupe_key', NULL,
      'snapshot_run_id', NULL,
      'session_id', NULL,
      'candidate_id', NULL,
      'payload_json', NULL,
      'created_at_utc', NULL,
      'updated_at_utc', NULL,
      'started_at_utc', NULL,
      'completed_at_utc', NULL,
      'failed_at_utc', NULL,
      'last_error_json', NULL,
      'claimed', v_claimed,
      'reclaimed_stale', v_reclaimed_stale,
      'no_op', v_no_op,
      'terminalized', v_terminalized,
      'reason', v_reason,
      'cutoff_utc', v_cutoff,
      'stale_cutoff_utc', v_stale_cutoff,
      'stale_running_seconds', v_stale_running_seconds,
      'last_activity_utc', NULL,
      'supported_job_type', v_supported_job_type
    );

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_requested_job_id_text,
      v_audit_action,
      v_before_json,
      v_after_json,
      v_audit_reason,
      NULL
    );

    RETURN jsonb_build_object(
      'ok', true,
      'job_id', NULL,
      'job_type', NULL,
      'status', NULL,
      'priority', NULL,
      'run_at_utc', NULL,
      'attempt_count', NULL,
      'max_attempts', NULL,
      'snapshot_run_id', NULL,
      'session_id', NULL,
      'candidate_id', NULL,
      'payload_json', NULL,
      'started_at_utc', NULL,
      'updated_at_utc', NULL,
      'created_at_utc', NULL,
      'completed_at_utc', NULL,
      'failed_at_utc', NULL,
      'last_error_json', NULL,
      'claimed', v_claimed,
      'reclaimed_stale', v_reclaimed_stale,
      'no_op', v_no_op,
      'terminalized', v_terminalized,
      'reason', v_reason,
      'cutoff_utc', v_cutoff,
      'stale_cutoff_utc', v_stale_cutoff,
      'stale_running_seconds', v_stale_running_seconds,
      'last_activity_utc', NULL,
      'supported_job_type', v_supported_job_type
    );
  END IF;

  SELECT public.banking_pay_workbench_jobs.*
  INTO v_job_row
  FROM public.banking_pay_workbench_jobs
  WHERE public.banking_pay_workbench_jobs.id = p_job_id
  FOR UPDATE;

  IF NOT FOUND THEN
    v_no_op := true;
    v_reason := 'JOB_NOT_FOUND';
    v_audit_action := 'CLAIM_DENIED';
    v_audit_reason := 'WORKBENCH_JOB_TARGET_CLAIM_DENIED_NOT_FOUND';

    v_after_json := jsonb_build_object(
      'id', v_requested_job_id_text,
      'job_type', NULL,
      'status', NULL,
      'priority', NULL,
      'run_at_utc', NULL,
      'attempt_count', NULL,
      'max_attempts', NULL,
      'dedupe_key', NULL,
      'snapshot_run_id', NULL,
      'session_id', NULL,
      'candidate_id', NULL,
      'payload_json', NULL,
      'created_at_utc', NULL,
      'updated_at_utc', NULL,
      'started_at_utc', NULL,
      'completed_at_utc', NULL,
      'failed_at_utc', NULL,
      'last_error_json', NULL,
      'claimed', v_claimed,
      'reclaimed_stale', v_reclaimed_stale,
      'no_op', v_no_op,
      'terminalized', v_terminalized,
      'reason', v_reason,
      'cutoff_utc', v_cutoff,
      'stale_cutoff_utc', v_stale_cutoff,
      'stale_running_seconds', v_stale_running_seconds,
      'last_activity_utc', NULL,
      'supported_job_type', v_supported_job_type
    );

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_requested_job_id_text,
      v_audit_action,
      v_before_json,
      v_after_json,
      v_audit_reason,
      NULL
    );

    RETURN jsonb_build_object(
      'ok', true,
      'job_id', v_requested_job_id_text,
      'job_type', NULL,
      'status', NULL,
      'priority', NULL,
      'run_at_utc', NULL,
      'attempt_count', NULL,
      'max_attempts', NULL,
      'snapshot_run_id', NULL,
      'session_id', NULL,
      'candidate_id', NULL,
      'payload_json', NULL,
      'started_at_utc', NULL,
      'updated_at_utc', NULL,
      'created_at_utc', NULL,
      'completed_at_utc', NULL,
      'failed_at_utc', NULL,
      'last_error_json', NULL,
      'claimed', v_claimed,
      'reclaimed_stale', v_reclaimed_stale,
      'no_op', v_no_op,
      'terminalized', v_terminalized,
      'reason', v_reason,
      'cutoff_utc', v_cutoff,
      'stale_cutoff_utc', v_stale_cutoff,
      'stale_running_seconds', v_stale_running_seconds,
      'last_activity_utc', NULL,
      'supported_job_type', v_supported_job_type
    );
  END IF;

  v_last_activity_utc := COALESCE(
    v_job_row.updated_at_utc,
    v_job_row.started_at_utc,
    v_job_row.created_at_utc,
    v_job_row.run_at_utc
  );

  v_supported_job_type := COALESCE(v_job_row.job_type, '') IN ('SESSION_CANDIDATE_RECOMPUTE', 'SNAPSHOT_CANDIDATE_REFRESH');
  v_due_now := COALESCE(v_job_row.status, '') = 'QUEUED'
               AND v_job_row.run_at_utc IS NOT NULL
               AND v_job_row.run_at_utc <= v_cutoff;
  v_stale_now := COALESCE(v_job_row.status, '') = 'RUNNING'
                 AND v_last_activity_utc IS NOT NULL
                 AND v_last_activity_utc <= v_stale_cutoff;
  v_max_attempts := COALESCE(v_job_row.max_attempts, 8);
  v_attempts_exhausted := COALESCE(v_job_row.attempt_count, 0) >= v_max_attempts;

  v_before_json := jsonb_build_object(
    'id', v_job_row.id::text,
    'job_type', v_job_row.job_type,
    'status', v_job_row.status,
    'priority', v_job_row.priority,
    'run_at_utc', v_job_row.run_at_utc,
    'attempt_count', v_job_row.attempt_count,
    'max_attempts', v_job_row.max_attempts,
    'dedupe_key', v_job_row.dedupe_key,
    'snapshot_run_id', CASE WHEN v_job_row.snapshot_run_id IS NULL THEN NULL ELSE v_job_row.snapshot_run_id::text END,
    'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
    'candidate_id', CASE WHEN v_job_row.candidate_id IS NULL THEN NULL ELSE v_job_row.candidate_id::text END,
    'payload_json', v_job_row.payload_json,
    'created_at_utc', v_job_row.created_at_utc,
    'updated_at_utc', v_job_row.updated_at_utc,
    'started_at_utc', v_job_row.started_at_utc,
    'completed_at_utc', v_job_row.completed_at_utc,
    'failed_at_utc', v_job_row.failed_at_utc,
    'last_error_json', v_job_row.last_error_json
  );

  IF NOT v_supported_job_type THEN
    v_no_op := true;
    v_reason := 'UNSUPPORTED_JOB_TYPE';
    v_audit_action := 'CLAIM_DENIED';
    v_audit_reason := 'WORKBENCH_JOB_TARGET_CLAIM_DENIED_UNSUPPORTED';
  ELSIF COALESCE(v_job_row.status, '') IN ('SUCCEEDED', 'DEAD') THEN
    v_no_op := true;
    v_reason := 'TERMINAL_STATUS';
    v_audit_action := 'CLAIM_DENIED';
    v_audit_reason := 'WORKBENCH_JOB_TARGET_CLAIM_DENIED_TERMINAL';
  ELSIF COALESCE(v_job_row.status, '') = 'RUNNING' AND NOT v_stale_now THEN
    v_no_op := true;
    v_reason := 'FRESH_RUNNING';
    v_audit_action := 'CLAIM_DENIED';
    v_audit_reason := 'WORKBENCH_JOB_TARGET_CLAIM_DENIED_FRESH_RUNNING';
  ELSIF v_due_now THEN
    IF v_attempts_exhausted THEN
      v_terminalized := true;
      v_reason := 'MAX_ATTEMPTS_EXHAUSTED';
      v_audit_action := 'DEAD';
      v_audit_reason := 'WORKBENCH_JOB_TARGET_MAX_ATTEMPTS_DEAD';
      v_terminal_error_json := jsonb_build_object(
        'code', 'MAX_ATTEMPTS_EXHAUSTED',
        'message', 'Targeted workbench job claim refused because max_attempts has been reached.',
        'job_id', v_job_row.id::text,
        'job_type', v_job_row.job_type,
        'status', v_job_row.status,
        'attempt_count', COALESCE(v_job_row.attempt_count, 0),
        'max_attempts', v_max_attempts,
        'targeted_claim_at_utc', v_now
      );

      UPDATE public.banking_pay_workbench_jobs AS update_job
      SET status = 'DEAD',
          updated_at_utc = v_now,
          completed_at_utc = NULL,
          failed_at_utc = v_now,
          last_error_json = v_terminal_error_json,
          payload_json = COALESCE(update_job.payload_json, '{}'::jsonb) || jsonb_build_object('last_failure_json', v_terminal_error_json)
      WHERE update_job.id = p_job_id
      RETURNING update_job.*
      INTO v_job_row;
    ELSE
      v_claimed := true;
      v_reason := 'CLAIMED_QUEUED_JOB';
      v_audit_action := 'RUNNING';
      v_audit_reason := 'WORKBENCH_JOB_TARGET_CLAIMED';

      UPDATE public.banking_pay_workbench_jobs AS update_job
      SET status = 'RUNNING',
          attempt_count = COALESCE(update_job.attempt_count, 0) + 1,
          started_at_utc = COALESCE(update_job.started_at_utc, v_now),
          updated_at_utc = v_now,
          last_error_json = NULL
      WHERE update_job.id = p_job_id
      RETURNING update_job.*
      INTO v_job_row;
    END IF;
  ELSIF v_stale_now THEN
    IF v_attempts_exhausted THEN
      v_terminalized := true;
      v_reason := 'MAX_ATTEMPTS_EXHAUSTED';
      v_audit_action := 'DEAD';
      v_audit_reason := 'WORKBENCH_JOB_TARGET_MAX_ATTEMPTS_DEAD';
      v_terminal_error_json := jsonb_build_object(
        'code', 'MAX_ATTEMPTS_EXHAUSTED',
        'message', 'Targeted workbench job claim refused because max_attempts has been reached.',
        'job_id', v_job_row.id::text,
        'job_type', v_job_row.job_type,
        'status', v_job_row.status,
        'attempt_count', COALESCE(v_job_row.attempt_count, 0),
        'max_attempts', v_max_attempts,
        'targeted_claim_at_utc', v_now
      );

      UPDATE public.banking_pay_workbench_jobs AS update_job
      SET status = 'DEAD',
          updated_at_utc = v_now,
          completed_at_utc = NULL,
          failed_at_utc = v_now,
          last_error_json = v_terminal_error_json,
          payload_json = COALESCE(update_job.payload_json, '{}'::jsonb) || jsonb_build_object('last_failure_json', v_terminal_error_json)
      WHERE update_job.id = p_job_id
      RETURNING update_job.*
      INTO v_job_row;
    ELSE
      v_claimed := true;
      v_reclaimed_stale := true;
      v_reason := 'RECLAIMED_STALE_RUNNING_JOB';
      v_audit_action := 'RUNNING';
      v_audit_reason := 'WORKBENCH_JOB_TARGET_STALE_RECLAIMED';

      UPDATE public.banking_pay_workbench_jobs AS update_job
      SET status = 'RUNNING',
          attempt_count = COALESCE(update_job.attempt_count, 0) + 1,
          started_at_utc = v_now,
          updated_at_utc = v_now,
          last_error_json = NULL
      WHERE update_job.id = p_job_id
      RETURNING update_job.*
      INTO v_job_row;
    END IF;
  ELSIF COALESCE(v_job_row.status, '') = 'QUEUED' THEN
    IF v_attempts_exhausted THEN
      v_terminalized := true;
      v_reason := 'MAX_ATTEMPTS_EXHAUSTED';
      v_audit_action := 'DEAD';
      v_audit_reason := 'WORKBENCH_JOB_TARGET_MAX_ATTEMPTS_DEAD';
      v_terminal_error_json := jsonb_build_object(
        'code', 'MAX_ATTEMPTS_EXHAUSTED',
        'message', 'Targeted workbench job claim refused because max_attempts has been reached.',
        'job_id', v_job_row.id::text,
        'job_type', v_job_row.job_type,
        'status', v_job_row.status,
        'attempt_count', COALESCE(v_job_row.attempt_count, 0),
        'max_attempts', v_max_attempts,
        'targeted_claim_at_utc', v_now
      );

      UPDATE public.banking_pay_workbench_jobs AS update_job
      SET status = 'DEAD',
          updated_at_utc = v_now,
          completed_at_utc = NULL,
          failed_at_utc = v_now,
          last_error_json = v_terminal_error_json,
          payload_json = COALESCE(update_job.payload_json, '{}'::jsonb) || jsonb_build_object('last_failure_json', v_terminal_error_json)
      WHERE update_job.id = p_job_id
      RETURNING update_job.*
      INTO v_job_row;
    ELSE
      v_no_op := true;
      v_reason := 'JOB_NOT_DUE_YET';
      v_audit_action := 'CLAIM_DENIED';
      v_audit_reason := 'WORKBENCH_JOB_TARGET_CLAIM_DENIED_NOT_DUE';
    END IF;
  ELSE
    v_no_op := true;
    v_reason := 'STATUS_NOT_CLAIMABLE';
    v_audit_action := 'CLAIM_DENIED';
    v_audit_reason := 'WORKBENCH_JOB_TARGET_CLAIM_DENIED_STATUS';
  END IF;

  v_last_activity_utc := COALESCE(
    v_job_row.updated_at_utc,
    v_job_row.started_at_utc,
    v_job_row.created_at_utc,
    v_job_row.run_at_utc
  );
  v_attempt_count_after := COALESCE(v_job_row.attempt_count, 0);

  v_after_json := jsonb_build_object(
    'id', v_job_row.id::text,
    'job_type', v_job_row.job_type,
    'status', v_job_row.status,
    'priority', v_job_row.priority,
    'run_at_utc', v_job_row.run_at_utc,
    'attempt_count', v_job_row.attempt_count,
    'max_attempts', v_job_row.max_attempts,
    'dedupe_key', v_job_row.dedupe_key,
    'snapshot_run_id', CASE WHEN v_job_row.snapshot_run_id IS NULL THEN NULL ELSE v_job_row.snapshot_run_id::text END,
    'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
    'candidate_id', CASE WHEN v_job_row.candidate_id IS NULL THEN NULL ELSE v_job_row.candidate_id::text END,
    'payload_json', v_job_row.payload_json,
    'created_at_utc', v_job_row.created_at_utc,
    'updated_at_utc', v_job_row.updated_at_utc,
    'started_at_utc', v_job_row.started_at_utc,
    'completed_at_utc', v_job_row.completed_at_utc,
    'failed_at_utc', v_job_row.failed_at_utc,
    'last_error_json', v_job_row.last_error_json,
    'claimed', v_claimed,
    'reclaimed_stale', v_reclaimed_stale,
    'no_op', v_no_op,
    'terminalized', v_terminalized,
    'reason', v_reason,
    'cutoff_utc', v_cutoff,
    'stale_cutoff_utc', v_stale_cutoff,
    'stale_running_seconds', v_stale_running_seconds,
    'last_activity_utc', v_last_activity_utc,
    'supported_job_type', v_supported_job_type
  );

  PERFORM public._audit_insert(
    'banking_pay_workbench_job',
    p_job_id::text,
    COALESCE(v_audit_action, 'CLAIM_DENIED'),
    v_before_json,
    v_after_json,
    COALESCE(v_audit_reason, 'WORKBENCH_JOB_TARGET_CLAIM_DENIED_STATUS'),
    NULL
  );

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', v_job_row.id::text,
    'job_type', v_job_row.job_type,
    'status', v_job_row.status,
    'priority', v_job_row.priority,
    'run_at_utc', v_job_row.run_at_utc,
    'attempt_count', v_attempt_count_after,
    'max_attempts', v_max_attempts,
    'snapshot_run_id', CASE WHEN v_job_row.snapshot_run_id IS NULL THEN NULL ELSE v_job_row.snapshot_run_id::text END,
    'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
    'candidate_id', CASE WHEN v_job_row.candidate_id IS NULL THEN NULL ELSE v_job_row.candidate_id::text END,
    'payload_json', v_job_row.payload_json,
    'started_at_utc', v_job_row.started_at_utc,
    'updated_at_utc', v_job_row.updated_at_utc,
    'created_at_utc', v_job_row.created_at_utc,
    'completed_at_utc', v_job_row.completed_at_utc,
    'failed_at_utc', v_job_row.failed_at_utc,
    'last_error_json', v_job_row.last_error_json,
    'claimed', v_claimed,
    'reclaimed_stale', v_reclaimed_stale,
    'no_op', v_no_op,
    'terminalized', v_terminalized,
    'reason', v_reason,
    'cutoff_utc', v_cutoff,
    'stale_cutoff_utc', v_stale_cutoff,
    'stale_running_seconds', v_stale_running_seconds,
    'last_activity_utc', v_last_activity_utc,
    'supported_job_type', v_supported_job_type
  );
END;
$function$;

-- pay_workbench_compact_job_result_json(jsonb)
CREATE OR REPLACE FUNCTION public.pay_workbench_compact_job_result_json(p_result_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_result_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_result_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_next_cursor_json jsonb := CASE
    WHEN jsonb_typeof(v_result_json->'next_cursor_json') = 'object' THEN v_result_json->'next_cursor_json'
    WHEN jsonb_typeof(v_result_json->'next_cursor') = 'object' THEN v_result_json->'next_cursor'
    WHEN jsonb_typeof(v_result_json->'nextCursorJson') = 'object' THEN v_result_json->'nextCursorJson'
    WHEN jsonb_typeof(v_result_json->'nextCursor') = 'object' THEN v_result_json->'nextCursor'
    ELSE NULL::jsonb
  END;
  v_targeted_timesheet_ids jsonb := CASE
    WHEN jsonb_typeof(v_result_json->'targeted_timesheet_ids') = 'array' THEN v_result_json->'targeted_timesheet_ids'
    ELSE NULL::jsonb
  END;
  v_linked_timesheet_ids jsonb := CASE
    WHEN jsonb_typeof(v_result_json->'linked_timesheet_ids') = 'array' THEN v_result_json->'linked_timesheet_ids'
    ELSE NULL::jsonb
  END;
BEGIN
  RETURN jsonb_strip_nulls(jsonb_build_object(
    'ok', CASE WHEN v_result_json ? 'ok' THEN v_result_json->'ok' ELSE NULL END,
    'has_more', CASE WHEN v_result_json ? 'has_more' THEN v_result_json->'has_more' WHEN v_result_json ? 'more_due' THEN v_result_json->'more_due' ELSE NULL END,
    'more_due', CASE WHEN v_result_json ? 'more_due' THEN v_result_json->'more_due' WHEN v_result_json ? 'has_more' THEN v_result_json->'has_more' ELSE NULL END,
    'next_cursor_json', v_next_cursor_json,
    'next_cursor', v_next_cursor_json,
    'processed_count', CASE WHEN v_result_json ? 'processed_count' THEN v_result_json->'processed_count' ELSE NULL END,
    'seeded_count', CASE WHEN v_result_json ? 'seeded_count' THEN v_result_json->'seeded_count' ELSE NULL END,
    'new_scope_count', CASE WHEN v_result_json ? 'new_scope_count' THEN v_result_json->'new_scope_count' ELSE NULL END,
    'ready_count_delta', CASE WHEN v_result_json ? 'ready_count_delta' THEN v_result_json->'ready_count_delta' ELSE NULL END,
    'materialised_count', CASE WHEN v_result_json ? 'materialised_count' THEN v_result_json->'materialised_count' WHEN v_result_json ? 'materialized_count' THEN v_result_json->'materialized_count' ELSE NULL END,
    'error_count', CASE WHEN v_result_json ? 'error_count' THEN v_result_json->'error_count' WHEN v_result_json ? 'materialisation_error_count' THEN v_result_json->'materialisation_error_count' ELSE NULL END,
    'source_rows_written', CASE WHEN v_result_json ? 'source_rows_written' THEN v_result_json->'source_rows_written' ELSE NULL END,
    'current_source_row_count', CASE WHEN v_result_json ? 'current_source_row_count' THEN v_result_json->'current_source_row_count' ELSE NULL END,
    'line_rows_written', CASE WHEN v_result_json ? 'line_rows_written' THEN v_result_json->'line_rows_written' ELSE NULL END,
    'preview_rows_written', CASE WHEN v_result_json ? 'preview_rows_written' THEN v_result_json->'preview_rows_written' ELSE NULL END,
    'source_build_run_id', NULLIF(BTRIM(COALESCE(v_result_json->>'source_build_run_id', '')), ''),
    'session_id', NULLIF(BTRIM(COALESCE(v_result_json->>'session_id', v_result_json->>'workbench_session_id', '')), ''),
    'candidate_id', NULLIF(BTRIM(COALESCE(v_result_json->>'candidate_id', '')), ''),
    'snapshot_run_id', NULLIF(BTRIM(COALESCE(v_result_json->>'snapshot_run_id', v_result_json->>'source_snapshot_run_id', '')), ''),
    'projection_run_id', NULLIF(BTRIM(COALESCE(v_result_json->>'projection_run_id', v_result_json->>'delta_projection_run_id', '')), ''),
    'timesheet_id', NULLIF(BTRIM(COALESCE(v_result_json->>'timesheet_id', v_result_json->>'targeted_timesheet_id', v_result_json->>'real_business_timesheet_id', '')), ''),
    'real_business_timesheet_id', NULLIF(BTRIM(COALESCE(v_result_json->>'real_business_timesheet_id', v_result_json->>'timesheet_id', '')), ''),
    'source_change_seq', CASE WHEN v_result_json ? 'source_change_seq' THEN v_result_json->'source_change_seq' ELSE NULL END,
    'source_change_sequence', CASE WHEN v_result_json ? 'source_change_sequence' THEN v_result_json->'source_change_sequence' WHEN v_result_json ? 'source_change_seq' THEN v_result_json->'source_change_seq' ELSE NULL END,
    'session_version', CASE WHEN v_result_json ? 'session_version' THEN v_result_json->'session_version' ELSE NULL END,
    'projection_mode', NULLIF(BTRIM(COALESCE(v_result_json->>'projection_mode', '')), ''),
    'projection_class', NULLIF(BTRIM(COALESCE(v_result_json->>'projection_class', '')), ''),
    'refresh_scope_kind', NULLIF(BTRIM(COALESCE(v_result_json->>'refresh_scope_kind', '')), ''),
    'targeted_timesheet_ids', v_targeted_timesheet_ids,
    'linked_timesheet_ids', v_linked_timesheet_ids,
    'fallback_required', CASE WHEN v_result_json ? 'fallback_required' THEN v_result_json->'fallback_required' ELSE NULL END,
    'fallback_reason', NULLIF(BTRIM(COALESCE(v_result_json->>'fallback_reason', '')), ''),
    'delta_refresh_complete', CASE WHEN v_result_json ? 'delta_refresh_complete' THEN v_result_json->'delta_refresh_complete' ELSE NULL END,
    'made_progress', CASE WHEN v_result_json ? 'made_progress' THEN v_result_json->'made_progress' ELSE NULL END,
    'shadow_compare_required', CASE WHEN v_result_json ? 'shadow_compare_required' THEN v_result_json->'shadow_compare_required' ELSE NULL END,
    'shadow_compare_enforced', CASE WHEN v_result_json ? 'shadow_compare_enforced' THEN v_result_json->'shadow_compare_enforced' ELSE NULL END,
    'shadow_compare_failed', CASE WHEN v_result_json ? 'shadow_compare_failed' THEN v_result_json->'shadow_compare_failed' ELSE NULL END,
    'shadow_compare_status', NULLIF(BTRIM(COALESCE(v_result_json->>'shadow_compare_status', '')), ''),
    'phase', NULLIF(BTRIM(COALESCE(v_result_json->>'phase', v_result_json->>'next_phase', '')), ''),
    'write_phase', NULLIF(BTRIM(COALESCE(v_result_json->>'write_phase', '')), '')
  ));
END;
$function$;

-- pay_workbench_complete_job(uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_workbench_complete_job(p_job_id uuid, p_result_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_job_row public.banking_pay_workbench_jobs%ROWTYPE;
  v_result_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_result_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_result_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_job_type text := NULL::text;
  v_stage_job_type text := NULL::text;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_has_open_session boolean := false;
  v_has_more boolean := false;
  v_next_cursor jsonb := NULL::jsonb;
  v_seeded_count integer := 0;
  v_new_scope_count integer := 0;
  v_processed_count integer := 0;
  v_ready_count_delta integer := 0;
  v_materialised_count integer := 0;
  v_error_count integer := 0;
  v_source_rows_written integer := 0;
  v_current_source_row_count integer := 0;
  v_current_source_row_count_authoritative boolean := false;
  v_source_build_run_id_text text := NULL::text;
  v_source_change_seq bigint := NULL::bigint;
  v_result_session_version bigint := NULL::bigint;
  v_source_seed_cursor_json jsonb := '{}'::jsonb;
  v_pending_line_work_exists boolean := false;
  v_ready_line_work_exists boolean := false;
  v_continuation_result jsonb := '{}'::jsonb;
  v_continuation_job_id_text text := NULL::text;
  v_continuation_jobs jsonb := '[]'::jsonb;
  v_continuation_count integer := 0;
  v_continuation_enqueued boolean := false;
  v_continuation_reused_count integer := 0;
  v_next_recommended_action text := NULL::text;
  v_existing_completion_json jsonb := '{}'::jsonb;
  v_payload_limit integer := 100;
  v_duplicate_completion boolean := false;
  v_completed_at_utc timestamptz := NULL::timestamptz;
  v_scope_pending_job_cleared_count integer := 0;
  v_scope_status_before_continuation text := NULL::text;
  v_scope_status_after_continuation text := NULL::text;
  v_scope_bucket_before_continuation text := NULL::text;
  v_scope_bucket_after_continuation text := NULL::text;
  v_scope_continuation_pending_delta integer := 0;
  v_scope_continuation_ready_delta integer := 0;
  v_scope_continuation_failed_delta integer := 0;
  v_scope_continuation_counter_adjusted boolean := false;
  v_finalisation_should_evaluate boolean := false;
  v_finalisation_actual_precheck_required boolean := false;
  v_finalisation_actual_precheck_passed boolean := false;
  v_current_candidate_terminal_success boolean := false;
  v_finalisation_evaluated boolean := false;
  v_finalisation_progress_json jsonb := '{}'::jsonb;
  v_finalisation_session_ready boolean := false;
  v_finalisation_ready_for_draft boolean := false;
  v_finalisation_ready_empty boolean := false;
  v_finalisation_stored_ready_mismatch boolean := false;
  v_finalisation_counter_reconciliation_required boolean := false;
  v_finalisation_counter_reconciliation_applied boolean := false;
  v_finalisation_counter_reconciled boolean := false;
  v_finalisation_counter_reconciliation_json jsonb := '{}'::jsonb;
  v_finalisation_blocker_codes jsonb := '[]'::jsonb;
  v_finalisation_draft_blocker_codes jsonb := '[]'::jsonb;
  v_finalisation_blocker_counts jsonb := '{}'::jsonb;
  v_final_progress_state text := NULL::text;
  v_final_phase text := NULL::text;
  v_final_status_text text := NULL::text;
  v_final_next_recommended_action text := NULL::text;
  v_authoritative_scope_total integer := 0;
  v_authoritative_scope_seeded integer := 0;
  v_authoritative_scope_ready integer := 0;
  v_authoritative_scope_pending integer := 0;
  v_authoritative_scope_failed integer := 0;
  v_authoritative_line_total integer := 0;
  v_authoritative_line_pending integer := 0;
  v_authoritative_line_ready integer := 0;
  v_authoritative_line_failed integer := 0;
  v_authoritative_preview_row_count integer := 0;
  v_authoritative_selected_row_count integer := 0;
  v_authoritative_section_counts_json jsonb := '{}'::jsonb;
  v_authoritative_candidate_sample_rows_json jsonb := '[]'::jsonb;
  v_completion_finalisation_json jsonb := '{}'::jsonb;
  v_source_reconciliation_json jsonb := '{}'::jsonb;
  v_source_reconciliation_applied boolean := false;
  v_source_reconciliation_deferred boolean := false;
  v_source_reconciliation_deferred_reason text := NULL::text;
  v_certified_publication_json jsonb := '{}'::jsonb;
  v_certified_publication_applied boolean := false;
  v_certified_targeted_timesheet_ids jsonb := '[]'::jsonb;
  v_certified_linked_timesheet_ids jsonb := '[]'::jsonb;
  v_source_empty_session_progress_deferred boolean := false;
  v_source_empty_session_progress_deferred_reason text := NULL::text;
  v_source_empty_cleanup_source_row_count integer := 0;
  v_source_empty_cleanup_line_work_count integer := 0;
  v_source_empty_cleanup_preview_row_count integer := 0;
  v_source_empty_targeted_timesheet_count integer := 0;
  v_bounded_terminal_refresh_scope_kind text := NULL::text;
  v_bounded_terminal_targeted_timesheet_count integer := 0;
  v_bounded_terminal_source_rows_retired_count integer := 0;
  v_bounded_terminal_line_work_retired_count integer := 0;
  v_bounded_terminal_scope_finalised_count integer := 0;
  v_continuation_scope_counter_deferred boolean := false;
  v_continuation_scope_counter_deferred_reason text := NULL::text;
  v_finalisation_deferred boolean := false;
  v_finalisation_deferred_reason text := NULL::text;
  v_delta_fallback_required boolean := false;
  v_delta_fallback_reason text := NULL::text;
  v_delta_refresh_complete boolean := false;
  v_delta_more_due boolean := false;
  v_delta_made_progress boolean := false;
  v_delta_projection_run_id_text text := NULL::text;
  v_delta_next_cursor_json jsonb := NULL::jsonb;
  v_delta_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_delta_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_delta_source_rows_written integer := 0;
  v_delta_line_rows_written integer := 0;
  v_delta_preview_rows_written integer := 0;
  v_delta_rows_superseded integer := 0;
  v_delta_shadow_compare_status text := NULL::text;
  v_delta_shadow_compare_required boolean := false;
  v_delta_shadow_compare_enforced boolean := false;
  v_delta_shadow_compare_failed boolean := false;
  v_clone_more_due boolean := false;
  v_clone_complete boolean := false;
  v_clone_copied_candidate_count integer := 0;
  v_clone_copied_preview_row_count integer := 0;
  v_clone_legacy_refresh_enqueued_count integer := 0;
  v_clone_continuation_job_id uuid := NULL::uuid;
  v_clone_source_session_id_text text := NULL::text;
  v_clone_source_session_id uuid := NULL::uuid;
  v_clone_source_session_retired_count integer := 0;
  v_delta_fallback_enqueue_result jsonb := '{}'::jsonb;
  v_delta_fallback_job_id_text text := NULL::text;
  v_delta_scope_total_count integer := 0;
  v_delta_scope_ready_count integer := 0;
  v_delta_scope_pending_count integer := 0;
  v_delta_scope_failed_count integer := 0;
  v_delta_line_units_total integer := 0;
  v_delta_line_units_ready integer := 0;
  v_delta_line_units_pending integer := 0;
  v_delta_line_units_failed integer := 0;
  v_delta_preview_row_count integer := 0;
  v_delta_selected_row_count integer := 0;
  v_delta_section_counts_json jsonb := '{}'::jsonb;
  v_delta_candidate_sample_rows_json jsonb := '[]'::jsonb;
  v_live_source_change_seq bigint := 0;
  v_delta_superseded_by_live_source_guard boolean := false;
  v_delta_superseded_projection_runs integer := 0;
  v_delta_projection_mode text := 'DELTA';
  v_delta_projection_class text := 'UNKNOWN';
  v_delta_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_delta_lifecycle_context text := NULL::text;
  v_delta_is_normal_targeted_lifecycle boolean := false;
  v_delta_recovery_enqueue_result jsonb := '{}'::jsonb;
  v_delta_recovery_job_id_text text := NULL::text;
  v_delta_recovery_job_id uuid := NULL::uuid;
  v_delta_recovery_source_change_seq bigint := 0;
  v_delta_recovery_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_delta_recovery_linked_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_material_attempt_id uuid := NULL::uuid;
  v_semantic_publication_v3_enabled boolean := false;
  v_correction_request_id uuid := NULL::uuid;
  v_correction_pay_batch_id uuid := NULL::uuid;
  v_correction_signal_claimed boolean := false;
BEGIN
  IF p_job_id IS NULL THEN
    RAISE EXCEPTION 'job_id is required';
  END IF;

  SELECT workbench_job.*
  INTO v_job_row
  FROM public.banking_pay_workbench_jobs AS workbench_job
  WHERE workbench_job.id = p_job_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_workbench_jobs row % not found', p_job_id;
  END IF;

  SELECT COALESCE(settings_row.banking_pay_workbench_semantic_ready_publication_v3_enabled, false)
  INTO v_semantic_publication_v3_enabled
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id = 1;

  IF v_job_row.candidate_id IS NOT NULL
     AND UPPER(BTRIM(COALESCE(v_job_row.job_type,''))) IN (
       'WORKBENCH_CANDIDATE_SOURCE_BUILD',
       'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
       'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
       'CANDIDATE_SOURCE_BUILD',
       'CANDIDATE_SOURCE_BUILD_CHUNK',
       'SOURCE_BUILD',
       'SOURCE_BUILD_PAGE',
       'WORKBENCH_SESSION_CLONE_REBASE',
       'SESSION_CLONE_REBASE',
       'CLONE_REBASE'
     ) THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        public._pay_workbench_candidate_serial_key(v_job_row.candidate_id),
        24062027
      )
    );
  END IF;

  v_duplicate_completion := UPPER(BTRIM(COALESCE(v_job_row.status, ''))) = 'SUCCEEDED'
    AND v_job_row.completed_at_utc IS NOT NULL;

  IF v_duplicate_completion THEN
    v_existing_completion_json := CASE
      WHEN jsonb_typeof(COALESCE(v_job_row.payload_json->'completion_json', '{}'::jsonb)) = 'object'
        THEN COALESCE(v_job_row.payload_json->'completion_json', '{}'::jsonb)
      ELSE '{}'::jsonb
    END;

    v_result_json := CASE
      WHEN jsonb_typeof(COALESCE(v_job_row.payload_json->'result_json', '{}'::jsonb)) = 'object'
        THEN COALESCE(v_job_row.payload_json->'result_json', '{}'::jsonb)
      ELSE v_result_json
    END;

    v_continuation_jobs := CASE
      WHEN jsonb_typeof(COALESCE(v_existing_completion_json->'continuation_jobs', '[]'::jsonb)) = 'array'
        THEN COALESCE(v_existing_completion_json->'continuation_jobs', '[]'::jsonb)
      ELSE '[]'::jsonb
    END;

    v_continuation_count := CASE
      WHEN COALESCE(v_existing_completion_json->>'continuation_count', '') ~ '^[0-9]+$'
        THEN (v_existing_completion_json->>'continuation_count')::integer
      ELSE jsonb_array_length(v_continuation_jobs)
    END;

    v_continuation_reused_count := CASE
      WHEN COALESCE(v_existing_completion_json->>'continuation_reused_count', '') ~ '^[0-9]+$'
        THEN (v_existing_completion_json->>'continuation_reused_count')::integer
      ELSE 0
    END;

    v_continuation_enqueued := COALESCE(v_continuation_count, 0) > 0
      OR LOWER(BTRIM(COALESCE(v_existing_completion_json->>'continuation_enqueued', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_next_recommended_action := NULLIF(BTRIM(COALESCE(v_existing_completion_json->>'next_recommended_action', '')), '');
    v_completed_at_utc := v_job_row.completed_at_utc;
  END IF;

  v_job_type := UPPER(BTRIM(COALESCE(v_job_row.job_type, '')));
  v_stage_job_type := CASE
    WHEN v_job_type IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED') THEN 'WORKBENCH_SESSION_SCOPE_SEED'
    WHEN v_job_type IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE') THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    WHEN v_job_type IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH') THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
    WHEN v_job_type IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE') THEN 'WORKBENCH_SESSION_CLONE_REBASE'
    WHEN v_job_type IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED') THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
    WHEN v_job_type IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS', 'LINE_WORK_PROCESS') THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
    WHEN v_job_type IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE') THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
    WHEN v_job_type IN ('SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH')
      AND v_job_row.session_id IS NOT NULL
      AND COALESCE((v_job_row.payload_json->>'line_work_only')::boolean, false) IS TRUE THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
    ELSE v_job_type
  END;

  IF COALESCE(v_result_json->>'has_more', '') ~* '^(true|t|1|yes)$' THEN
    v_has_more := true;
  ELSE
    v_has_more := false;
  END IF;

  v_next_cursor := CASE
    WHEN jsonb_typeof(v_result_json->'next_cursor') = 'object' THEN v_result_json->'next_cursor'
    WHEN jsonb_typeof(v_result_json->'next_cursor_json') = 'object' THEN v_result_json->'next_cursor_json'
    WHEN jsonb_typeof(v_result_json->'nextCursor') = 'object' THEN v_result_json->'nextCursor'
    WHEN jsonb_typeof(v_result_json->'nextCursorJson') = 'object' THEN v_result_json->'nextCursorJson'
    ELSE NULL::jsonb
  END;

  -- Material bounded-source stages have their own exact completion path.  The
  -- immutable attempt must already be COMPLETED by RPC 2, and at most one
  -- typed continuation is committed with this job completion.
  IF v_stage_job_type='WORKBENCH_CANDIDATE_SOURCE_BUILD'
     AND v_job_row.economic_build_id IS NOT NULL THEN
    IF v_duplicate_completion THEN
      -- A lost terminal response may leave certified CURRENT source without
      -- the public preview.  Duplicate completion is therefore the normal,
      -- idempotent self-heal owner; it never reruns source economics.
      SELECT build_row.source_build_run_id::text,
             build_row.source_change_seq,
             build_row.session_version
      INTO v_source_build_run_id_text,
           v_source_change_seq,
           v_result_session_version
      FROM private.banking_pay_workbench_economic_builds AS build_row
      WHERE build_row.id = v_job_row.economic_build_id
        AND build_row.session_id = v_job_row.session_id
        AND build_row.candidate_id = v_job_row.candidate_id
        AND UPPER(BTRIM(COALESCE(build_row.status, ''))) = 'COMPLETE'
        AND UPPER(BTRIM(COALESCE(build_row.private_stage, ''))) = 'COMPLETE';

      IF FOUND THEN
        v_certified_targeted_timesheet_ids := CASE
          WHEN jsonb_typeof(v_job_row.payload_json->'targeted_timesheet_ids') = 'array'
            THEN v_job_row.payload_json->'targeted_timesheet_ids'
          WHEN jsonb_typeof(v_job_row.payload_json#>'{source_build,targeted_timesheet_ids}') = 'array'
            THEN v_job_row.payload_json#>'{source_build,targeted_timesheet_ids}'
          ELSE COALESCE((
            SELECT jsonb_agg(DISTINCT build_scope.timesheet_id::text ORDER BY build_scope.timesheet_id::text)
            FROM private.banking_pay_workbench_economic_build_scope AS build_scope
            WHERE build_scope.build_id = v_job_row.economic_build_id
              AND build_scope.timesheet_id IS NOT NULL
          ), '[]'::jsonb)
        END;
        v_certified_linked_timesheet_ids := CASE
          WHEN jsonb_typeof(v_job_row.payload_json->'linked_timesheet_ids') = 'array'
            THEN v_job_row.payload_json->'linked_timesheet_ids'
          WHEN jsonb_typeof(v_job_row.payload_json#>'{source_build,linked_timesheet_ids}') = 'array'
            THEN v_job_row.payload_json#>'{source_build,linked_timesheet_ids}'
          ELSE '[]'::jsonb
        END;

        v_certified_publication_json := private.pay_workbench_publish_certified_source_preview_v1(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_economic_build_id => v_job_row.economic_build_id,
          p_source_build_run_id => v_source_build_run_id_text::uuid,
          p_source_change_seq => v_source_change_seq,
          p_session_version => v_result_session_version,
          p_completion_job_id => p_job_id,
          p_refresh_scope_kind => COALESCE(
            NULLIF(BTRIM(v_job_row.payload_json->>'refresh_scope_kind'), ''),
            NULLIF(BTRIM(v_job_row.payload_json#>>'{source_build,refresh_scope_kind}'), ''),
            'CANDIDATE_FULL_LIVE'
          ),
          p_targeted_timesheet_ids => v_certified_targeted_timesheet_ids,
          p_linked_timesheet_ids => v_certified_linked_timesheet_ids,
          p_publication_options_json => CASE
            WHEN v_semantic_publication_v3_enabled THEN jsonb_build_object(
              'authority_kind', 'BOUNDED_FULL_SOURCE_BUILD',
              'invocation_kind', 'DUPLICATE_REPLAY_REPAIR',
              'contract_version', 3,
              'final_state', CASE WHEN EXISTS (
                SELECT 1
                FROM public.banking_pay_workbench_candidate_source_lines AS duplicate_source
                WHERE duplicate_source.session_id=v_job_row.session_id
                  AND duplicate_source.candidate_id=v_job_row.candidate_id
                  AND duplicate_source.source_build_run_id=v_source_build_run_id_text::uuid
                  AND duplicate_source.source_change_seq=v_source_change_seq
                  AND duplicate_source.status='CURRENT'
              ) THEN 'READY' ELSE 'SOURCE_EMPTY' END,
              'semantic_contract_version', 'READY_TO_PAY_SEMANTIC_V2'
            )
            ELSE jsonb_build_object(
              'authority_kind', 'BOUNDED_FULL_SOURCE_BUILD',
              'invocation_kind', 'DUPLICATE_REPLAY_REPAIR',
              'contract_version', 1
            )
          END
        );
        v_certified_publication_applied := COALESCE((v_certified_publication_json->>'parity_complete')::boolean, false);

        IF v_certified_publication_applied IS NOT TRUE THEN
          RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_PARITY_FAILED' USING ERRCODE = 'P0001';
        END IF;

        IF COALESCE((v_certified_publication_json->>'already_current')::boolean, false) IS NOT TRUE THEN
          UPDATE public.banking_pay_workbench_session_scope AS duplicate_scope
          SET status = CASE
                WHEN COALESCE((v_certified_publication_json->>'source_row_count')::integer, 0) = 0 THEN 'SOURCE_EMPTY'
                ELSE 'MATERIALISED'
              END,
              seeded = true,
              dirty = false,
              pending_job_id = NULL::uuid,
              error_json = NULL::jsonb,
              updated_at_utc = v_now
          WHERE duplicate_scope.session_id = v_job_row.session_id
            AND duplicate_scope.candidate_id = v_job_row.candidate_id;

          PERFORM public.pay_workbench_session_recompute_progress_counters(
            v_job_row.session_id,
            true,
            'CERTIFIED_SOURCE_PREVIEW_DUPLICATE_SELF_HEAL',
            true
          );
        END IF;
      END IF;

      RETURN jsonb_build_object('ok',true,'job_id',p_job_id,'status','SUCCEEDED',
        'duplicate_completion',true,'continuation_enqueued',
        COALESCE((v_existing_completion_json->>'continuation_enqueued')::boolean,false),
        'continuation_jobs',COALESCE(v_existing_completion_json->'continuation_jobs','[]'::jsonb),
        'certified_source_preview',v_certified_publication_json,
        'completed_at_utc',v_job_row.completed_at_utc);
    END IF;
    SELECT attempt.id INTO v_material_attempt_id
    FROM private.banking_pay_workbench_stage_attempts attempt
    WHERE attempt.job_id=p_job_id AND attempt.build_id=v_job_row.economic_build_id
      AND attempt.private_stage=v_job_row.private_stage
      AND attempt.attempt_status='COMPLETED'
      AND attempt.attempt_number=v_job_row.attempt_count
    ORDER BY attempt.id DESC LIMIT 1;
    IF v_material_attempt_id IS NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_ATTEMPT_COMPLETION_REQUIRED' USING ERRCODE='40001';
    END IF;
    IF v_has_more AND v_next_cursor IS NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_SOURCE_CONTINUATION_CURSOR_REQUIRED' USING ERRCODE='22023';
    END IF;
    IF v_has_more THEN
      v_continuation_result:=public.pay_workbench_enqueue_stage_continuation(
        p_session_id=>v_job_row.session_id,p_candidate_id=>v_job_row.candidate_id,
        p_job_type=>'WORKBENCH_CANDIDATE_SOURCE_BUILD',p_cursor_json=>v_next_cursor,
        p_source_job_id=>p_job_id,p_result_json=>v_result_json,
        p_actor_user_id=>NULLIF(v_job_row.payload_json->>'actor_user_id','')::uuid,
        p_reason=>COALESCE(v_result_json->>'next_action','BOUNDED_STAGE_CONTINUATION'),
        p_priority=>v_job_row.priority,p_limit=>COALESCE(
          NULLIF(v_job_row.payload_json->>'source_build_limit','')::integer,
          NULLIF(v_job_row.payload_json->>'limit','')::integer,25)
      );
      v_continuation_job_id_text:=NULLIF(v_continuation_result->>'job_id','');
      v_continuation_enqueued:=v_continuation_job_id_text IS NOT NULL;
      v_continuation_jobs:=CASE WHEN v_continuation_job_id_text IS NULL THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('job_id',v_continuation_job_id_text,
          'job_type','WORKBENCH_CANDIDATE_SOURCE_BUILD','private_stage',v_result_json->>'next_action')) END;
      v_continuation_count:=CASE WHEN v_continuation_enqueued THEN 1 ELSE 0 END;
    END IF;
    -- A nonterminal material page owns only its exact continuation. Terminal
    -- material completion must continue through the common successful-source
    -- reconciliation below so the public session scope cannot remain bound to
    -- a job that has already succeeded.
    IF v_has_more THEN
      UPDATE public.banking_pay_workbench_jobs target_job SET status='SUCCEEDED',
        completed_at_utc=clock_timestamp(),failed_at_utc=NULL,last_error_json=NULL,
        payload_json=COALESCE(target_job.payload_json,'{}'::jsonb)
          ||jsonb_build_object('result_json',public.pay_workbench_compact_job_result_json(v_result_json))
          ||jsonb_build_object('completion_json',jsonb_build_object(
            'attempt_id',v_material_attempt_id,'continuation_enqueued',v_continuation_enqueued,
            'continuation_jobs',v_continuation_jobs,'continuation_count',v_continuation_count,
            'next_recommended_action',v_result_json->>'next_action',
            'completed_at_utc',clock_timestamp())),updated_at_utc=clock_timestamp()
      WHERE target_job.id=p_job_id AND target_job.status='RUNNING';
      IF NOT FOUND THEN RAISE EXCEPTION 'PAY_WORKBENCH_JOB_COMPLETION_STALE' USING ERRCODE='40001'; END IF;
      RETURN jsonb_build_object('ok',true,'job_id',p_job_id,'status','SUCCEEDED',
        'duplicate_completion',false,'continuation_enqueued',v_continuation_enqueued,
        'continuation_jobs',v_continuation_jobs,'continuation_count',v_continuation_count,
        'next_recommended_action',v_result_json->>'next_action','completed_at_utc',clock_timestamp());
    END IF;
  END IF;

  v_seeded_count := CASE WHEN COALESCE(v_result_json->>'seeded_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'seeded_count')::integer ELSE 0 END;
  v_new_scope_count := CASE WHEN COALESCE(v_result_json->>'new_scope_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'new_scope_count')::integer ELSE 0 END;
  v_processed_count := CASE WHEN COALESCE(v_result_json->>'processed_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'processed_count')::integer ELSE 0 END;
  v_ready_count_delta := CASE WHEN COALESCE(v_result_json->>'ready_count_delta', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'ready_count_delta')::integer ELSE 0 END;
  v_materialised_count := CASE
    WHEN COALESCE(v_result_json->>'materialised_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'materialised_count')::integer
    WHEN COALESCE(v_result_json->>'materialized_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'materialized_count')::integer
    ELSE 0
  END;
  v_error_count := CASE
    WHEN COALESCE(v_result_json->>'error_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'error_count')::integer
    WHEN COALESCE(v_result_json->>'materialisation_error_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'materialisation_error_count')::integer
    ELSE 0
  END;
  v_source_rows_written := CASE
    WHEN COALESCE(v_result_json->>'source_rows_written', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'source_rows_written')::integer
    WHEN COALESCE(v_result_json->>'published_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'published_count')::integer
    ELSE 0
  END;
  v_current_source_row_count := CASE
    WHEN COALESCE(v_result_json->>'current_source_row_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'current_source_row_count')::integer
    WHEN COALESCE(v_result_json->>'source_rows_written', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'source_rows_written')::integer
    WHEN COALESCE(v_result_json->>'published_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'published_count')::integer
    ELSE 0
  END;
  v_current_source_row_count_authoritative := LOWER(BTRIM(COALESCE(
    v_result_json->>'current_source_row_count_authoritative',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR (
      v_stage_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
      AND v_job_row.economic_build_id IS NOT NULL
      AND COALESCE(v_has_more, false) IS NOT TRUE
      AND UPPER(BTRIM(COALESCE(v_result_json->>'private_stage', ''))) = 'COMPLETE'
      AND UPPER(BTRIM(COALESCE(v_result_json->>'stage_status', ''))) = 'COMPLETE'
      AND COALESCE(v_result_json->>'published_count', '') ~ '^-?[0-9]+$'
    );
  v_source_build_run_id_text := COALESCE(
    NULLIF(BTRIM(COALESCE(v_result_json->>'source_build_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'source_build_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_job_row.payload_json#>>'{source_build,source_build_run_id}', '')), '')
  );
  v_source_change_seq := CASE
    WHEN COALESCE(v_result_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (v_result_json->>'source_change_seq')::bigint
    WHEN COALESCE(v_job_row.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (v_job_row.payload_json->>'source_change_seq')::bigint
    WHEN COALESCE(v_job_row.payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$' THEN (v_job_row.payload_json->>'source_change_sequence')::bigint
    ELSE NULL::bigint
  END;
  v_result_session_version := CASE
    WHEN COALESCE(v_result_json->>'session_version', '') ~ '^[0-9]{1,18}$' THEN (v_result_json->>'session_version')::bigint
    WHEN COALESCE(v_job_row.payload_json->>'session_version', '') ~ '^[0-9]{1,18}$' THEN (v_job_row.payload_json->>'session_version')::bigint
    ELSE NULL::bigint
  END;
  v_source_seed_cursor_json := jsonb_strip_nulls(jsonb_build_object(
    'source_build_run_id', v_source_build_run_id_text,
    'source_change_seq', v_source_change_seq,
    'session_version', v_result_session_version,
    'source_snapshot_run_id', CASE WHEN v_job_row.snapshot_run_id IS NULL THEN NULL ELSE v_job_row.snapshot_run_id::text END,
    'source_row_cursor', 'START'
  ));
  v_payload_limit := LEAST(
    GREATEST(
      CASE
        WHEN COALESCE(NULLIF(BTRIM(v_job_row.payload_json->>'line_limit'), ''), NULLIF(BTRIM(v_job_row.payload_json->>'limit'), ''), '') ~ '^[0-9]+$'
          THEN COALESCE(NULLIF(BTRIM(v_job_row.payload_json->>'line_limit'), ''), NULLIF(BTRIM(v_job_row.payload_json->>'limit'), ''))::integer
        ELSE 100
      END,
      1
    ),
    100
  );

  IF v_job_row.session_id IS NOT NULL THEN
    SELECT session_row.*
    INTO v_session_row
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_job_row.session_id;

    v_has_open_session := FOUND
      AND UPPER(BTRIM(COALESCE(v_session_row.status, ''))) = 'OPEN'
      AND v_session_row.discarded_at_utc IS NULL;
  END IF;

  IF v_duplicate_completion IS NOT TRUE
     AND v_stage_job_type IN (
       'WORKBENCH_SESSION_SCOPE_SEED',
       'WORKBENCH_CANDIDATE_SOURCE_BUILD',
       'WORKBENCH_CANDIDATE_DELTA_REFRESH',
       'WORKBENCH_SESSION_CLONE_REBASE',
       'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
       'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
       'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
     )
     AND v_job_row.session_id IS NOT NULL
     AND v_has_open_session IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_COMPLETE_JOB_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_COMPLETE_JOB_SESSION_NOT_OPEN',
              'job_id', p_job_id::text,
              'session_id', v_job_row.session_id::text,
              'job_type', v_stage_job_type,
              'status', CASE WHEN v_session_row.id IS NULL THEN NULL ELSE v_session_row.status END,
              'discarded_at_utc', CASE WHEN v_session_row.id IS NULL THEN NULL ELSE v_session_row.discarded_at_utc END
            )::text;
  END IF;

  IF v_duplicate_completion IS NOT TRUE
     AND v_stage_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
    v_delta_fallback_required := LOWER(BTRIM(COALESCE(v_result_json->>'fallback_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_delta_fallback_reason := COALESCE(NULLIF(BTRIM(COALESCE(v_result_json->>'fallback_reason', '')), ''), 'DELTA_REFRESH_FALLBACK_REQUIRED');
    v_delta_refresh_complete := LOWER(BTRIM(COALESCE(v_result_json->>'delta_refresh_complete', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_delta_more_due := LOWER(BTRIM(COALESCE(v_result_json->>'more_due', v_result_json->>'has_more', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_delta_made_progress := LOWER(BTRIM(COALESCE(v_result_json->>'made_progress', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_delta_projection_run_id_text := COALESCE(
      NULLIF(BTRIM(COALESCE(v_result_json->>'projection_run_id', '')), ''),
      NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'projection_run_id', '')), '')
    );
    v_delta_next_cursor_json := CASE
      WHEN jsonb_typeof(v_result_json->'next_cursor_json') = 'object' THEN v_result_json->'next_cursor_json'
      WHEN jsonb_typeof(v_result_json->'next_cursor') = 'object' THEN v_result_json->'next_cursor'
      WHEN jsonb_typeof(v_job_row.payload_json->'cursor_json') = 'object' THEN v_job_row.payload_json->'cursor_json'
      ELSE '{}'::jsonb
    END;
    v_delta_targeted_timesheet_ids_json := CASE
      WHEN jsonb_typeof(v_result_json->'targeted_timesheet_ids') = 'array' THEN v_result_json->'targeted_timesheet_ids'
      WHEN jsonb_typeof(v_job_row.payload_json->'targeted_timesheet_ids') = 'array' THEN v_job_row.payload_json->'targeted_timesheet_ids'
      ELSE '[]'::jsonb
    END;
    v_delta_linked_timesheet_ids_json := CASE
      WHEN jsonb_typeof(v_result_json->'linked_timesheet_ids') = 'array' THEN v_result_json->'linked_timesheet_ids'
      WHEN jsonb_typeof(v_job_row.payload_json->'linked_timesheet_ids') = 'array' THEN v_job_row.payload_json->'linked_timesheet_ids'
      ELSE '[]'::jsonb
    END;
    v_delta_source_rows_written := CASE WHEN COALESCE(v_result_json->>'source_rows_written', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'source_rows_written')::integer ELSE 0 END;
    v_delta_line_rows_written := CASE WHEN COALESCE(v_result_json->>'line_rows_written', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'line_rows_written')::integer ELSE 0 END;
    v_delta_preview_rows_written := CASE WHEN COALESCE(v_result_json->>'preview_rows_written', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'preview_rows_written')::integer ELSE 0 END;
    v_delta_rows_superseded := CASE WHEN COALESCE(v_result_json->>'rows_superseded', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'rows_superseded')::integer ELSE 0 END;
    v_delta_shadow_compare_status := UPPER(BTRIM(COALESCE(v_result_json->>'shadow_compare_status', '')));
    v_delta_shadow_compare_required := LOWER(BTRIM(COALESCE(
      v_result_json->>'shadow_compare_required',
      v_job_row.payload_json->>'shadow_compare_required',
      'false'
    ))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_delta_shadow_compare_enforced := LOWER(BTRIM(COALESCE(
      v_result_json->>'shadow_compare_enforced',
      v_job_row.payload_json->>'shadow_compare_enforced',
      'false'
    ))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_delta_shadow_compare_enforced := COALESCE(v_delta_shadow_compare_required, false)
      AND COALESCE(v_delta_shadow_compare_enforced, false);
    v_delta_shadow_compare_failed := LOWER(BTRIM(COALESCE(v_result_json->>'shadow_compare_failed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      OR v_delta_shadow_compare_status = 'MISMATCH'
      OR (
        COALESCE(v_delta_shadow_compare_enforced, false) IS TRUE
        AND v_delta_shadow_compare_status IN ('REFERENCE_UNAVAILABLE', 'REFERENCE_MISSING', 'UNAVAILABLE')
      );
    IF v_delta_shadow_compare_failed IS TRUE THEN
      v_delta_fallback_required := true;
      v_delta_fallback_reason := CASE
        WHEN COALESCE(v_delta_shadow_compare_enforced, false) IS TRUE
         AND v_delta_shadow_compare_status IN ('REFERENCE_UNAVAILABLE', 'REFERENCE_MISSING', 'UNAVAILABLE')
          THEN 'SHADOW_REFERENCE_UNAVAILABLE'
        ELSE 'SHADOW_COMPARE_MISMATCH'
      END;
    END IF;

    SELECT COALESCE(array_agg(DISTINCT parsed_target.timesheet_id ORDER BY parsed_target.timesheet_id), ARRAY[]::uuid[])
    INTO v_delta_recovery_targeted_timesheet_ids
    FROM (
      SELECT NULLIF(BTRIM(target_value.value), '')::uuid AS timesheet_id
      FROM jsonb_array_elements_text(COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb)) AS target_value(value)
      WHERE NULLIF(BTRIM(target_value.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) AS parsed_target;

    SELECT COALESCE(array_agg(DISTINCT parsed_linked.timesheet_id ORDER BY parsed_linked.timesheet_id), ARRAY[]::uuid[])
    INTO v_delta_recovery_linked_timesheet_ids
    FROM (
      SELECT NULLIF(BTRIM(linked_value.value), '')::uuid AS timesheet_id
      FROM jsonb_array_elements_text(COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb)) AS linked_value(value)
      WHERE NULLIF(BTRIM(linked_value.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) AS parsed_linked;

    v_delta_projection_mode := COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
      v_result_json->>'projection_mode',
      v_job_row.payload_json->>'projection_mode',
      v_result_json->>'resolved_mode',
      v_job_row.payload_json->>'resolved_mode',
      'DELTA'
    ))), ''), 'DELTA');

    v_delta_projection_class := COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
      v_result_json->>'projection_class',
      v_job_row.payload_json->>'projection_class',
      'UNKNOWN'
    ))), ''), 'UNKNOWN');

    v_delta_refresh_scope_kind := COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
      v_result_json->>'refresh_scope_kind',
      v_job_row.payload_json->>'refresh_scope_kind',
      ''
    ))), ''), CASE
      WHEN COALESCE(array_length(v_delta_recovery_targeted_timesheet_ids, 1), 0) > 0
        OR COALESCE(array_length(v_delta_recovery_linked_timesheet_ids, 1), 0) > 0
      THEN 'TARGETED_TIMESHEETS'
      ELSE 'CANDIDATE_FULL_LIVE'
    END);

    v_delta_lifecycle_context := LOWER(BTRIM(COALESCE(
      v_result_json->>'lifecycle_mutation_context',
      v_job_row.payload_json->>'lifecycle_mutation_context',
      v_result_json->>'mutation_context',
      v_job_row.payload_json->>'mutation_context',
      v_result_json->>'lifecycle_context',
      v_job_row.payload_json->>'lifecycle_context',
      v_result_json->>'trigger_source',
      v_job_row.payload_json->>'trigger_source',
      v_result_json->>'reason',
      v_job_row.payload_json->>'reason_latest',
      v_job_row.payload_json->>'reason',
      ''
    )));

    v_delta_is_normal_targeted_lifecycle := v_delta_projection_mode = 'DELTA'
      AND v_delta_projection_class = 'NORMAL_TIMESHEET'
      AND v_delta_refresh_scope_kind = 'TARGETED_TIMESHEETS'
      AND COALESCE(array_length(v_delta_recovery_targeted_timesheet_ids, 1), 0) > 0
      AND COALESCE(v_delta_shadow_compare_failed, false) IS NOT TRUE
      AND (
        COALESCE(v_delta_fallback_required, false) IS NOT TRUE
        OR UPPER(BTRIM(COALESCE(v_delta_fallback_reason, ''))) = 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED'
        OR LOWER(BTRIM(COALESCE(v_result_json->>'identical_cursor_self_reuse_suppressed', v_result_json->>'continuation_not_enqueued', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      )
      AND LOWER(BTRIM(COALESCE(v_result_json->>'force_legacy', v_job_row.payload_json->>'force_legacy', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(v_result_json->>'force_broad_legacy', v_job_row.payload_json->>'force_broad_legacy', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(v_result_json->>'source_build_required', v_job_row.payload_json->>'source_build_required', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(v_result_json->>'ordinary_timesheet_edit_save_no_dirty', v_job_row.payload_json->>'ordinary_timesheet_edit_save_no_dirty', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
      AND (
        LOWER(BTRIM(COALESCE(v_result_json->>'authorise_boundary_changed', v_job_row.payload_json->>'authorise_boundary_changed', v_result_json->>'timesheet_authorise_boundary_changed', v_job_row.payload_json->>'timesheet_authorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR v_delta_lifecycle_context IN ('timesheet_authorise', 'authorise_timesheet', 'timesheet_unauthorise', 'unauthorise_timesheet')
        OR LOWER(COALESCE(v_result_json->>'reason', v_job_row.payload_json->>'reason_latest', v_job_row.payload_json->>'reason', '')) LIKE '%authorise%'
        OR LOWER(COALESCE(v_result_json->>'reason', v_job_row.payload_json->>'reason_latest', v_job_row.payload_json->>'reason', '')) LIKE '%unauthorise%'
      );

    v_delta_next_cursor_json := COALESCE(v_delta_next_cursor_json, '{}'::jsonb)
      || jsonb_strip_nulls(jsonb_build_object(
        'projection_run_id', v_delta_projection_run_id_text,
        'phase', COALESCE(NULLIF(BTRIM(COALESCE(v_result_json->>'next_phase', '')), ''), NULLIF(BTRIM(COALESCE(v_result_json->>'phase', '')), ''), NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'phase', '')), '')),
        'cursor', CASE
          WHEN jsonb_typeof(v_delta_next_cursor_json->'cursor') = 'object' THEN v_delta_next_cursor_json->'cursor'
          WHEN jsonb_typeof(v_job_row.payload_json->'cursor_json') = 'object' THEN v_job_row.payload_json->'cursor_json'
          ELSE '{}'::jsonb
        END,
        'write_phase', COALESCE(NULLIF(BTRIM(COALESCE(v_result_json->>'write_phase', '')), ''), NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'write_phase', '')), '')),
        'write_cursor_json', CASE
          WHEN jsonb_typeof(v_result_json->'write_cursor_json') = 'object' THEN v_result_json->'write_cursor_json'
          WHEN jsonb_typeof(v_delta_next_cursor_json->'write_cursor_json') = 'object' THEN v_delta_next_cursor_json->'write_cursor_json'
          WHEN jsonb_typeof(v_job_row.payload_json->'write_cursor_json') = 'object' THEN v_job_row.payload_json->'write_cursor_json'
          ELSE NULL::jsonb
        END,
        'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb),
        'source_change_seq', CASE WHEN COALESCE(v_result_json->>'source_change_seq', v_job_row.payload_json->>'source_change_seq', '') ~ '^-?[0-9]+$' THEN COALESCE(v_result_json->>'source_change_seq', v_job_row.payload_json->>'source_change_seq')::bigint ELSE NULL::bigint END
      ));

    IF v_job_row.candidate_id IS NOT NULL
       AND v_source_change_seq IS NOT NULL THEN
      SELECT COALESCE(change_counter.seq, 0)
      INTO v_live_source_change_seq
      FROM public.app_change_counters AS change_counter
      WHERE change_counter.entity_key = 'pay_candidate:' || v_job_row.candidate_id::text;

      v_live_source_change_seq := COALESCE(v_live_source_change_seq, 0);

      IF COALESCE(v_live_source_change_seq, 0) > COALESCE(v_source_change_seq, 0) THEN
        v_delta_superseded_by_live_source_guard := true;
        v_delta_more_due := false;
        v_delta_fallback_required := false;
        v_delta_refresh_complete := true;
        v_delta_fallback_reason := 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ';

        v_result_json := jsonb_strip_nulls(
          COALESCE(v_result_json, '{}'::jsonb)
          || jsonb_build_object(
            'superseded_by_newer_source_change_seq', true,
            'complete_job_live_source_guard_applied', true,
            'source_change_seq', v_source_change_seq,
            'newer_source_change_seq', v_live_source_change_seq,
            'live_source_change_seq', v_live_source_change_seq,
            'fallback_required', false,
            'delta_refresh_complete', true,
            'more_due', false,
            'has_more', false,
            'stop_reason', 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ'
          )
        );

        IF v_delta_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
          UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
          SET status = 'FAILED',
              fallback_required = false,
              fallback_reason = 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ',
              diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
                || jsonb_build_object(
                  'superseded_by_newer_source_change_seq', true,
                  'complete_job_live_source_guard_applied', true,
                  'source_change_seq', v_source_change_seq,
                  'newer_source_change_seq', v_live_source_change_seq,
                  'terminalised_by', 'pay_workbench_complete_job',
                  'terminalised_at_utc', v_now::text
                ),
              updated_at_utc = v_now,
              completed_at_utc = v_now
          WHERE projection_run_update.id = v_delta_projection_run_id_text::uuid
            AND projection_run_update.session_id = v_job_row.session_id
            AND projection_run_update.candidate_id = v_job_row.candidate_id
            AND UPPER(BTRIM(COALESCE(projection_run_update.status, ''))) = 'RUNNING';

          GET DIAGNOSTICS v_delta_superseded_projection_runs = ROW_COUNT;
        END IF;
      END IF;
    ELSE
      v_live_source_change_seq := 0;
    END IF;

    IF v_delta_superseded_by_live_source_guard IS TRUE THEN
      UPDATE public.banking_pay_workbench_session_scope AS delta_superseded_scope
      SET dirty = true,
          pending_job_id = CASE WHEN delta_superseded_scope.pending_job_id = p_job_id THEN NULL::uuid ELSE delta_superseded_scope.pending_job_id END,
          error_json = NULL::jsonb,
          updated_at_utc = v_now
      WHERE delta_superseded_scope.session_id = v_job_row.session_id
        AND delta_superseded_scope.candidate_id = v_job_row.candidate_id;

      v_continuation_jobs := '[]'::jsonb;
      v_continuation_count := 0;
      v_continuation_reused_count := 0;
      v_continuation_enqueued := false;
      v_next_recommended_action := 'DELTA_REFRESH_CHUNK';
    ELSIF v_delta_more_due IS TRUE THEN
      v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
        p_session_id => v_job_row.session_id,
        p_candidate_id => v_job_row.candidate_id,
        p_job_type => 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        p_cursor_json => COALESCE(v_delta_next_cursor_json, '{}'::jsonb),
        p_source_job_id => p_job_id,
        p_result_json => v_result_json,
        p_actor_user_id => v_session_row.actor_user_id,
        p_reason => 'DELTA_REFRESH_MORE_DUE',
        p_priority => COALESCE(v_job_row.priority, 43),
        p_limit => v_payload_limit
      );

      v_continuation_job_id_text := NULLIF(BTRIM(COALESCE(v_continuation_result->>'job_id', '')), '');

      IF LOWER(BTRIM(COALESCE(
           v_continuation_result->>'identical_cursor_self_reuse_suppressed',
           v_continuation_result->>'continuation_not_enqueued',
           'false'
         ))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
        IF v_job_row.candidate_id IS NOT NULL
           AND v_source_change_seq IS NOT NULL THEN
          SELECT COALESCE(change_counter.seq, 0)
          INTO v_live_source_change_seq
          FROM public.app_change_counters AS change_counter
          WHERE change_counter.entity_key = 'pay_candidate:' || v_job_row.candidate_id::text;

          v_live_source_change_seq := COALESCE(v_live_source_change_seq, 0);
        END IF;

        IF v_delta_is_normal_targeted_lifecycle IS TRUE THEN
          v_delta_recovery_source_change_seq := GREATEST(COALESCE(v_live_source_change_seq, 0), COALESCE(v_source_change_seq, 0));
          v_delta_more_due := false;
          v_delta_fallback_required := false;
          v_delta_refresh_complete := true;
          v_delta_fallback_reason := 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED';
          v_delta_superseded_by_live_source_guard := COALESCE(v_live_source_change_seq, 0) > COALESCE(v_source_change_seq, 0);

          v_result_json := jsonb_strip_nulls(
            COALESCE(v_result_json, '{}'::jsonb)
            || jsonb_build_object(
              'identical_cursor_self_reuse_suppressed', true,
              'delta_identical_cursor_self_reuse_no_source_build', true,
              'fallback_required', false,
              'fallback_reason', v_delta_fallback_reason,
              'delta_refresh_complete', true,
              'more_due', false,
              'has_more', false,
              'source_change_seq', COALESCE(v_source_change_seq, 0),
              'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
              'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
              'stop_reason', 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_NO_SOURCE_BUILD_SUCCESSOR_REQUIRED',
              'next_recommended_action', 'DELTA_REFRESH_CHUNK'
            )
          );

          IF v_delta_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
            UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
            SET status = 'FAILED',
                fallback_required = false,
                fallback_reason = v_delta_fallback_reason,
                diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
                  || jsonb_build_object(
                    'identical_cursor_self_reuse_suppressed', true,
                    'delta_identical_cursor_self_reuse_no_source_build', true,
                    'successor_required', true,
                    'continuation_result', COALESCE(v_continuation_result, '{}'::jsonb),
                    'source_change_seq', COALESCE(v_source_change_seq, 0),
                    'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
                    'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
                    'terminalised_by', 'pay_workbench_complete_job',
                    'terminalised_at_utc', v_now::text
                  ),
                updated_at_utc = v_now,
                completed_at_utc = v_now
            WHERE projection_run_update.id = v_delta_projection_run_id_text::uuid
              AND projection_run_update.session_id = v_job_row.session_id
              AND projection_run_update.candidate_id = v_job_row.candidate_id
              AND UPPER(BTRIM(COALESCE(projection_run_update.status, ''))) = 'RUNNING';
          END IF;

          v_delta_recovery_enqueue_result := public.pay_workbench_enqueue_candidate_refresh(
            p_snapshot_run_id => v_session_row.source_snapshot_run_id,
            p_candidate_id => v_job_row.candidate_id,
            p_reason => 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_DELTA_SUCCESSOR',
            p_actor_user_id => v_session_row.actor_user_id,
            p_payload_json => jsonb_strip_nulls(
              (COALESCE(v_job_row.payload_json, '{}'::jsonb) - ARRAY[
                'cursor',
                'cursor_json',
                'next_cursor',
                'next_cursor_json',
                'source_cursor',
                'write_cursor_json',
                'candidate_cursor',
                'cursor_token',
                'has_cursor',
                'continuation_reason',
                'source_job_id',
                'continuation_source_job_id',
                'bounded_continuation_source_job_id',
                'parent_job_id',
                'next_phase',
                'write_phase',
                'source_result_summary',
                'source_result_has_more',
                'source_result_next_cursor_present',
                'projection_run_id'
              ]::text[])
              || jsonb_build_object(
                'session_id', v_job_row.session_id::text,
                'source_session_id', v_job_row.session_id::text,
                'workbench_session_id', v_job_row.session_id::text,
                'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
                'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
                'session_version', COALESCE(v_session_row.version, 0),
                'session_signature', v_session_row.session_signature,
                'force_legacy', false,
                'force_broad_legacy', false,
                'fallback_from_delta', false,
                'fallback_reason', v_delta_fallback_reason,
                'projection_mode', 'DELTA',
                'projection_class', 'NORMAL_TIMESHEET',
                'refresh_scope_kind', 'TARGETED_TIMESHEETS',
                'phase', 'INIT_PREFLIGHT',
                'cursor_json', '{}'::jsonb,
                'source_build_required', false,
                'line_work_required', false,
                'delta_refresh_required', true,
                'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
                'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb),
                'source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
                'source_change_sequence', COALESCE(v_delta_recovery_source_change_seq, 0),
                'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
                'identical_cursor_self_reuse_suppressed', true,
                'delta_identical_cursor_self_reuse_no_source_build', true,
                'successor_for_job_id', p_job_id::text,
                'previous_projection_run_id', v_delta_projection_run_id_text,
                'authorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on'),
                'unauthorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
                'lifecycle_mutation_context', CASE
                  WHEN LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                    OR v_delta_lifecycle_context IN ('timesheet_unauthorise', 'unauthorise_timesheet')
                    OR LOWER(COALESCE(v_result_json->>'reason', v_job_row.payload_json->>'reason_latest', v_job_row.payload_json->>'reason', '')) LIKE '%unauthorise%'
                  THEN 'timesheet_unauthorise'
                  ELSE 'timesheet_authorise'
                END,
                'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
                'policy_x_dirtying_only', true,
                'economic_truth_mutation_allowed', false
              )
            )
          );

          v_delta_recovery_job_id_text := NULLIF(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'job_id', '')), '');

          IF v_delta_recovery_job_id_text = p_job_id::text THEN
            v_delta_recovery_job_id_text := NULL;
          END IF;

          IF v_delta_recovery_job_id_text IS NULL THEN
            v_delta_recovery_enqueue_result := public.pay_workbench_dirty_event_enqueue(
              p_job_type => 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
              p_scope_kind => 'CANDIDATE',
              p_scope_id => v_job_row.candidate_id::text,
              p_candidate_id => v_job_row.candidate_id,
              p_targeted_timesheet_ids => v_delta_recovery_targeted_timesheet_ids,
              p_linked_timesheet_ids => v_delta_recovery_linked_timesheet_ids,
              p_payload_json => jsonb_strip_nulls(
                COALESCE(v_job_row.payload_json, '{}'::jsonb)
                || jsonb_build_object(
                  'session_id', v_job_row.session_id::text,
                  'source_session_id', v_job_row.session_id::text,
                  'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
                  'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
                  'session_version', COALESCE(v_session_row.version, 0),
                  'session_signature', v_session_row.session_signature,
                  'refresh_scope_kind', 'TARGETED_TIMESHEETS',
                  'projection_mode', 'DELTA',
                  'projection_class', 'NORMAL_TIMESHEET',
                  'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
                  'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb),
                  'source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
                  'source_change_sequence', COALESCE(v_delta_recovery_source_change_seq, 0),
                  'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
                  'reason', 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_DIRTY_RECOVERY',
                  'fallback_reason', v_delta_fallback_reason,
                  'source_build_required', false,
                  'line_work_required', false,
                  'delta_refresh_required', true,
                  'identical_cursor_self_reuse_suppressed', true,
                  'delta_identical_cursor_self_reuse_no_source_build', true,
                  'authorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on'),
                  'unauthorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
                  'lifecycle_mutation_context', CASE
                    WHEN LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                      OR v_delta_lifecycle_context IN ('timesheet_unauthorise', 'unauthorise_timesheet')
                      OR LOWER(COALESCE(v_result_json->>'reason', v_job_row.payload_json->>'reason_latest', v_job_row.payload_json->>'reason', '')) LIKE '%unauthorise%'
                    THEN 'timesheet_unauthorise'
                    ELSE 'timesheet_authorise'
                  END,
                  'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
                  'policy_x_dirtying_only', true,
                  'economic_truth_mutation_allowed', false
                )
              ),
              p_reason => 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_DIRTY_RECOVERY',
              p_priority => -1000,
              p_run_at_utc => v_now
            );

            v_delta_recovery_job_id_text := NULLIF(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'job_id', '')), '');

            IF v_delta_recovery_job_id_text IS NULL
               AND jsonb_typeof(COALESCE(v_delta_recovery_enqueue_result->'coalesced_scope_results', '[]'::jsonb)) = 'array' THEN
              SELECT NULLIF(BTRIM(COALESCE(coalesced_scope_result.value->>'job_id', '')), '')
              INTO v_delta_recovery_job_id_text
              FROM jsonb_array_elements(COALESCE(v_delta_recovery_enqueue_result->'coalesced_scope_results', '[]'::jsonb)) AS coalesced_scope_result(value)
              WHERE COALESCE(coalesced_scope_result.value->>'session_id', '') = v_job_row.session_id::text
                AND COALESCE(coalesced_scope_result.value->>'job_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              LIMIT 1;
            END IF;

            IF v_delta_recovery_job_id_text = p_job_id::text THEN
              v_delta_recovery_job_id_text := NULL;
            END IF;
          END IF;

          IF v_delta_recovery_job_id_text IS NULL
             OR v_delta_recovery_job_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
            RAISE EXCEPTION 'PAY_WORKBENCH_DELTA_SELF_REUSE_RECOVERY_JOB_ID_MISSING'
              USING ERRCODE = 'P0001',
                    DETAIL = jsonb_build_object(
                      'code', 'PAY_WORKBENCH_DELTA_SELF_REUSE_RECOVERY_JOB_ID_MISSING',
                      'job_id', p_job_id::text,
                      'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
                      'candidate_id', CASE WHEN v_job_row.candidate_id IS NULL THEN NULL ELSE v_job_row.candidate_id::text END,
                      'projection_run_id', v_delta_projection_run_id_text,
                      'source_change_seq', v_source_change_seq,
                      'recovery_enqueue_result', COALESCE(v_delta_recovery_enqueue_result, '{}'::jsonb),
                      'message', 'Normal targeted lifecycle DELTA self-reuse suppression could not create or reuse a cron-claimable recovery job.'
                    )::text;
          END IF;

          v_delta_recovery_job_id := v_delta_recovery_job_id_text::uuid;

          UPDATE public.banking_pay_workbench_session_scope AS delta_recovery_scope
          SET status = CASE
                WHEN UPPER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'job_type', ''))) = 'WORKBENCH_CANDIDATE_DIRTY_APPLY'
                 AND LOWER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'dirty_enqueue_coalesced_all_relevant_scopes', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
                  THEN 'PENDING'
                ELSE 'DELTA_REFRESH_PENDING'
              END,
              dirty = true,
              pending_job_id = v_delta_recovery_job_id,
              error_json = NULL::jsonb,
              updated_at_utc = v_now
          WHERE delta_recovery_scope.session_id = v_job_row.session_id
            AND delta_recovery_scope.candidate_id = v_job_row.candidate_id;

          v_continuation_jobs := jsonb_build_array(v_continuation_result, v_delta_recovery_enqueue_result);
          v_continuation_count := 1;
          v_continuation_reused_count := CASE
            WHEN LOWER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              OR LOWER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'dirty_enqueue_coalesced_all_relevant_scopes', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
            THEN 1
            ELSE 0
          END;
          v_continuation_enqueued := true;
          v_next_recommended_action := 'DELTA_REFRESH_CHUNK';
        ELSIF v_job_row.candidate_id IS NOT NULL
           AND v_source_change_seq IS NOT NULL
           AND COALESCE(v_live_source_change_seq, 0) > COALESCE(v_source_change_seq, 0) THEN
          v_delta_more_due := false;
          v_delta_fallback_required := false;
          v_delta_refresh_complete := true;
          v_delta_fallback_reason := 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ';
          v_delta_superseded_by_live_source_guard := true;

          v_result_json := jsonb_strip_nulls(
            COALESCE(v_result_json, '{}'::jsonb)
            || jsonb_build_object(
              'superseded_by_newer_source_change_seq', true,
              'complete_job_live_source_guard_applied', true,
              'identical_cursor_self_reuse_suppressed', true,
              'source_change_seq', v_source_change_seq,
              'newer_source_change_seq', v_live_source_change_seq,
              'live_source_change_seq', v_live_source_change_seq,
              'fallback_required', false,
              'delta_refresh_complete', true,
              'more_due', false,
              'has_more', false,
              'stop_reason', 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ'
            )
          );

          IF v_delta_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
            UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
            SET status = 'FAILED',
                fallback_required = false,
                fallback_reason = 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ',
                diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
                  || jsonb_build_object(
                    'superseded_by_newer_source_change_seq', true,
                    'complete_job_live_source_guard_applied', true,
                    'identical_cursor_self_reuse_suppressed', true,
                    'source_change_seq', v_source_change_seq,
                    'newer_source_change_seq', v_live_source_change_seq,
                    'terminalised_by', 'pay_workbench_complete_job',
                    'terminalised_at_utc', v_now::text
                  ),
                updated_at_utc = v_now,
                completed_at_utc = v_now
            WHERE projection_run_update.id = v_delta_projection_run_id_text::uuid
              AND projection_run_update.session_id = v_job_row.session_id
              AND projection_run_update.candidate_id = v_job_row.candidate_id
              AND UPPER(BTRIM(COALESCE(projection_run_update.status, ''))) = 'RUNNING';

            GET DIAGNOSTICS v_delta_superseded_projection_runs = ROW_COUNT;
          END IF;

          UPDATE public.banking_pay_workbench_session_scope AS delta_superseded_scope
          SET dirty = true,
              pending_job_id = CASE WHEN delta_superseded_scope.pending_job_id = p_job_id THEN NULL::uuid ELSE delta_superseded_scope.pending_job_id END,
              error_json = NULL::jsonb,
              updated_at_utc = v_now
          WHERE delta_superseded_scope.session_id = v_job_row.session_id
            AND delta_superseded_scope.candidate_id = v_job_row.candidate_id;

          v_continuation_jobs := jsonb_build_array(v_continuation_result);
          v_continuation_count := 0;
          v_continuation_reused_count := 0;
          v_continuation_enqueued := false;
          v_next_recommended_action := 'DELTA_REFRESH_CHUNK';
        ELSE
          v_delta_more_due := false;
          v_delta_fallback_required := true;
          v_delta_fallback_reason := 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED';

          IF v_delta_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
            UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
            SET status = 'FALLBACK_REQUIRED',
                fallback_required = true,
                fallback_reason = v_delta_fallback_reason,
                diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
                  || jsonb_build_object(
                    'identical_cursor_self_reuse_suppressed', true,
                    'continuation_result', COALESCE(v_continuation_result, '{}'::jsonb),
                    'terminalised_by', 'pay_workbench_complete_job',
                    'terminalised_at_utc', v_now::text
                  ),
                updated_at_utc = v_now,
                completed_at_utc = v_now
            WHERE projection_run_update.id = v_delta_projection_run_id_text::uuid
              AND projection_run_update.session_id = v_job_row.session_id
              AND projection_run_update.candidate_id = v_job_row.candidate_id
              AND UPPER(BTRIM(COALESCE(projection_run_update.status, ''))) = 'RUNNING';
          END IF;

          v_delta_fallback_enqueue_result := public.pay_workbench_enqueue_candidate_refresh(
            p_snapshot_run_id => v_session_row.source_snapshot_run_id,
            p_candidate_id => v_job_row.candidate_id,
            p_reason => v_delta_fallback_reason,
            p_actor_user_id => v_session_row.actor_user_id,
            p_payload_json => jsonb_strip_nulls(
              jsonb_build_object(
                'session_id', v_job_row.session_id::text,
                'source_session_id', v_job_row.session_id::text,
                'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
                'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
                'session_version', COALESCE(v_session_row.version, 0),
                'session_signature', v_session_row.session_signature,
                'force_legacy', true,
                'fallback_from_delta', true,
                'fallback_reason', v_delta_fallback_reason,
                'projection_run_id', v_delta_projection_run_id_text,
                'projection_class', COALESCE(NULLIF(BTRIM(COALESCE(v_result_json->>'projection_class', '')), ''), NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'projection_class', '')), '')),
                'source_build_required', true,
                'line_work_required', true,
                'delta_refresh_required', false,
                'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
                'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb),
                'refresh_scope_kind', CASE WHEN jsonb_array_length(COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb)) > 0 OR jsonb_array_length(COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb)) > 0 THEN 'TARGETED_TIMESHEETS' ELSE 'CANDIDATE_FULL_LIVE' END
              )
            )
          );

          v_delta_fallback_job_id_text := NULLIF(BTRIM(COALESCE(v_delta_fallback_enqueue_result->>'job_id', '')), '');

          UPDATE public.banking_pay_workbench_session_scope AS delta_fallback_scope
          SET status = 'SOURCE_BUILD_PENDING',
              dirty = true,
              pending_job_id = CASE WHEN v_delta_fallback_job_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_delta_fallback_job_id_text::uuid ELSE delta_fallback_scope.pending_job_id END,
              error_json = NULL::jsonb,
              updated_at_utc = v_now
          WHERE delta_fallback_scope.session_id = v_job_row.session_id
            AND delta_fallback_scope.candidate_id = v_job_row.candidate_id;

          v_continuation_jobs := jsonb_build_array(v_continuation_result, v_delta_fallback_enqueue_result);
          v_continuation_count := CASE WHEN v_delta_fallback_job_id_text IS NULL THEN 0 ELSE 1 END;
          v_continuation_reused_count := CASE WHEN LOWER(BTRIM(COALESCE(v_delta_fallback_enqueue_result->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 1 ELSE 0 END;
          v_continuation_enqueued := v_delta_fallback_job_id_text IS NOT NULL;
          v_next_recommended_action := 'BUILD_SOURCE_CHUNK';
        END IF;
      ELSE
        IF v_continuation_job_id_text IS NULL THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_DELTA_CONTINUATION_JOB_ID_MISSING'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_WORKBENCH_DELTA_CONTINUATION_JOB_ID_MISSING',
                    'job_id', p_job_id::text,
                    'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
                    'candidate_id', CASE WHEN v_job_row.candidate_id IS NULL THEN NULL ELSE v_job_row.candidate_id::text END,
                    'projection_run_id', v_delta_projection_run_id_text,
                    'source_change_seq', v_source_change_seq,
                    'continuation_result', v_continuation_result,
                    'message', 'Delta more_due completion did not receive a concrete continuation job id.'
                  )::text;
        END IF;

        IF v_continuation_job_id_text = p_job_id::text THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_DELTA_CONTINUATION_SELF_REUSE_GUARD_FAILED'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_WORKBENCH_DELTA_CONTINUATION_SELF_REUSE_GUARD_FAILED',
                    'job_id', p_job_id::text,
                    'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
                    'candidate_id', CASE WHEN v_job_row.candidate_id IS NULL THEN NULL ELSE v_job_row.candidate_id::text END,
                    'projection_run_id', v_delta_projection_run_id_text,
                    'source_change_seq', v_source_change_seq,
                    'continuation_result', v_continuation_result,
                    'message', 'Delta continuation helper returned the currently completing job as its own continuation.'
                  )::text;
        END IF;

        v_continuation_jobs := jsonb_build_array(v_continuation_result);
        v_continuation_count := 1;
        v_continuation_reused_count := CASE WHEN LOWER(BTRIM(COALESCE(v_continuation_result->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 1 ELSE 0 END;
        v_continuation_enqueued := true;
        v_next_recommended_action := 'DELTA_REFRESH_CHUNK';
      END IF;
    ELSIF v_delta_fallback_required IS TRUE
          AND v_delta_is_normal_targeted_lifecycle IS TRUE
          AND UPPER(BTRIM(COALESCE(v_delta_fallback_reason, ''))) = 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED' THEN
      IF v_job_row.candidate_id IS NOT NULL
         AND v_source_change_seq IS NOT NULL THEN
        SELECT COALESCE(change_counter.seq, 0)
        INTO v_live_source_change_seq
        FROM public.app_change_counters AS change_counter
        WHERE change_counter.entity_key = 'pay_candidate:' || v_job_row.candidate_id::text;

        v_live_source_change_seq := COALESCE(v_live_source_change_seq, 0);
      END IF;

      v_delta_recovery_source_change_seq := GREATEST(COALESCE(v_live_source_change_seq, 0), COALESCE(v_source_change_seq, 0));
      v_delta_more_due := false;
      v_delta_fallback_required := false;
      v_delta_refresh_complete := true;
      v_delta_fallback_reason := 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED';
      v_delta_superseded_by_live_source_guard := COALESCE(v_live_source_change_seq, 0) > COALESCE(v_source_change_seq, 0);

      v_continuation_result := jsonb_build_object(
        'ok', true,
        'action', 'DIRECT_FALLBACK_SELF_REUSE_SUPPRESSED_NO_SOURCE_BUILD',
        'continuation_not_enqueued', true,
        'identical_cursor_self_reuse_suppressed', true,
        'delta_identical_cursor_self_reuse_no_source_build', true,
        'normal_targeted_lifecycle_delta', true,
        'successor_required', true,
        'source_change_seq', COALESCE(v_source_change_seq, 0),
        'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
        'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
        'projection_run_id', v_delta_projection_run_id_text
      );

      v_result_json := jsonb_strip_nulls(
        COALESCE(v_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'identical_cursor_self_reuse_suppressed', true,
          'delta_identical_cursor_self_reuse_no_source_build', true,
          'direct_fallback_intercepted', true,
          'fallback_required', false,
          'fallback_reason', v_delta_fallback_reason,
          'delta_refresh_complete', true,
          'more_due', false,
          'has_more', false,
          'source_change_seq', COALESCE(v_source_change_seq, 0),
          'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
          'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
          'stop_reason', 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_DIRECT_FALLBACK_NO_SOURCE_BUILD_SUCCESSOR_REQUIRED',
          'next_recommended_action', 'DELTA_REFRESH_CHUNK'
        )
      );

      IF v_delta_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
        SET status = 'FAILED',
            fallback_required = false,
            fallback_reason = v_delta_fallback_reason,
            diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
              || jsonb_build_object(
                'identical_cursor_self_reuse_suppressed', true,
                'delta_identical_cursor_self_reuse_no_source_build', true,
                'direct_fallback_intercepted', true,
                'successor_required', true,
                'continuation_result', COALESCE(v_continuation_result, '{}'::jsonb),
                'source_change_seq', COALESCE(v_source_change_seq, 0),
                'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
                'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
                'terminalised_by', 'pay_workbench_complete_job',
                'terminalised_at_utc', v_now::text
              ),
            updated_at_utc = v_now,
            completed_at_utc = v_now
        WHERE projection_run_update.id = v_delta_projection_run_id_text::uuid
          AND projection_run_update.session_id = v_job_row.session_id
          AND projection_run_update.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(projection_run_update.status, ''))) IN ('RUNNING', 'FALLBACK_REQUIRED');
      END IF;

      v_delta_recovery_enqueue_result := public.pay_workbench_enqueue_candidate_refresh(
        p_snapshot_run_id => v_session_row.source_snapshot_run_id,
        p_candidate_id => v_job_row.candidate_id,
        p_reason => 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_DELTA_SUCCESSOR',
        p_actor_user_id => v_session_row.actor_user_id,
        p_payload_json => jsonb_strip_nulls(jsonb_build_object(
          'session_id', v_job_row.session_id::text,
          'source_session_id', v_job_row.session_id::text,
          'workbench_session_id', v_job_row.session_id::text,
          'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
          'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
          'session_version', COALESCE(v_session_row.version, 0),
          'session_signature', v_session_row.session_signature,
          'force_legacy', false,
          'force_broad_legacy', false,
          'fallback_from_delta', false,
          'fallback_reason', v_delta_fallback_reason,
          'projection_mode', 'DELTA',
          'projection_class', 'NORMAL_TIMESHEET',
          'refresh_scope_kind', 'TARGETED_TIMESHEETS',
          'phase', 'INIT_PREFLIGHT',
          'cursor_json', '{}'::jsonb,
          'source_build_required', false,
          'line_work_required', false,
          'delta_refresh_required', true,
          'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb),
          'source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
          'source_change_sequence', COALESCE(v_delta_recovery_source_change_seq, 0),
          'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
          'identical_cursor_self_reuse_suppressed', true,
          'delta_identical_cursor_self_reuse_no_source_build', true,
          'direct_fallback_intercepted', true,
          'successor_for_job_id', p_job_id::text,
          'previous_projection_run_id', v_delta_projection_run_id_text,
          'authorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on'),
          'unauthorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
          'lifecycle_mutation_context', CASE
            WHEN LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              OR v_delta_lifecycle_context IN ('timesheet_unauthorise', 'unauthorise_timesheet')
              OR LOWER(COALESCE(v_result_json->>'reason', v_job_row.payload_json->>'reason_latest', v_job_row.payload_json->>'reason', '')) LIKE '%unauthorise%'
            THEN 'timesheet_unauthorise'
            ELSE 'timesheet_authorise'
          END,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'policy_x_dirtying_only', true,
          'economic_truth_mutation_allowed', false
        ))
      );

      v_delta_recovery_job_id_text := NULLIF(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'job_id', '')), '');

      IF v_delta_recovery_job_id_text = p_job_id::text THEN
        v_delta_recovery_job_id_text := NULL;
      END IF;

      IF v_delta_recovery_job_id_text IS NULL THEN
        v_delta_recovery_enqueue_result := public.pay_workbench_dirty_event_enqueue(
          p_job_type => 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
          p_scope_kind => 'CANDIDATE',
          p_scope_id => v_job_row.candidate_id::text,
          p_candidate_id => v_job_row.candidate_id,
          p_targeted_timesheet_ids => v_delta_recovery_targeted_timesheet_ids,
          p_linked_timesheet_ids => v_delta_recovery_linked_timesheet_ids,
          p_payload_json => jsonb_strip_nulls(jsonb_build_object(
            'session_id', v_job_row.session_id::text,
            'source_session_id', v_job_row.session_id::text,
            'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
            'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
            'session_version', COALESCE(v_session_row.version, 0),
            'session_signature', v_session_row.session_signature,
            'refresh_scope_kind', 'TARGETED_TIMESHEETS',
            'projection_mode', 'DELTA',
            'projection_class', 'NORMAL_TIMESHEET',
            'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
            'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb),
            'source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
            'source_change_sequence', COALESCE(v_delta_recovery_source_change_seq, 0),
            'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
            'reason', 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_DIRTY_RECOVERY',
            'fallback_reason', v_delta_fallback_reason,
            'source_build_required', false,
            'line_work_required', false,
            'delta_refresh_required', true,
            'identical_cursor_self_reuse_suppressed', true,
            'delta_identical_cursor_self_reuse_no_source_build', true,
            'direct_fallback_intercepted', true,
            'authorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on'),
            'unauthorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
            'lifecycle_mutation_context', CASE
              WHEN LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                OR v_delta_lifecycle_context IN ('timesheet_unauthorise', 'unauthorise_timesheet')
                OR LOWER(COALESCE(v_result_json->>'reason', v_job_row.payload_json->>'reason_latest', v_job_row.payload_json->>'reason', '')) LIKE '%unauthorise%'
              THEN 'timesheet_unauthorise'
              ELSE 'timesheet_authorise'
            END,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
            'policy_x_dirtying_only', true,
            'economic_truth_mutation_allowed', false
          )),
          p_reason => 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_DIRTY_RECOVERY',
          p_priority => -1000,
          p_run_at_utc => v_now
        );

        v_delta_recovery_job_id_text := NULLIF(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'job_id', '')), '');

        IF v_delta_recovery_job_id_text IS NULL
           AND jsonb_typeof(COALESCE(v_delta_recovery_enqueue_result->'coalesced_scope_results', '[]'::jsonb)) = 'array' THEN
          SELECT NULLIF(BTRIM(COALESCE(coalesced_scope_result.value->>'job_id', '')), '')
          INTO v_delta_recovery_job_id_text
          FROM jsonb_array_elements(COALESCE(v_delta_recovery_enqueue_result->'coalesced_scope_results', '[]'::jsonb)) AS coalesced_scope_result(value)
          WHERE COALESCE(coalesced_scope_result.value->>'session_id', '') = v_job_row.session_id::text
            AND COALESCE(coalesced_scope_result.value->>'job_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          LIMIT 1;
        END IF;

        IF v_delta_recovery_job_id_text = p_job_id::text THEN
          v_delta_recovery_job_id_text := NULL;
        END IF;
      END IF;

      IF v_delta_recovery_job_id_text IS NULL
         OR v_delta_recovery_job_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_DELTA_SELF_REUSE_RECOVERY_JOB_ID_MISSING'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_DELTA_SELF_REUSE_RECOVERY_JOB_ID_MISSING',
                  'job_id', p_job_id::text,
                  'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
                  'candidate_id', CASE WHEN v_job_row.candidate_id IS NULL THEN NULL ELSE v_job_row.candidate_id::text END,
                  'projection_run_id', v_delta_projection_run_id_text,
                  'source_change_seq', v_source_change_seq,
                  'recovery_enqueue_result', COALESCE(v_delta_recovery_enqueue_result, '{}'::jsonb),
                  'message', 'Normal targeted lifecycle DELTA self-reuse fallback could not create or reuse a cron-claimable recovery job.'
                )::text;
      END IF;

      v_delta_recovery_job_id := v_delta_recovery_job_id_text::uuid;

      UPDATE public.banking_pay_workbench_session_scope AS delta_recovery_scope
      SET status = CASE
            WHEN UPPER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'job_type', ''))) = 'WORKBENCH_CANDIDATE_DIRTY_APPLY'
             AND LOWER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'dirty_enqueue_coalesced_all_relevant_scopes', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
              THEN 'PENDING'
            ELSE 'DELTA_REFRESH_PENDING'
          END,
          dirty = true,
          pending_job_id = v_delta_recovery_job_id,
          error_json = NULL::jsonb,
          updated_at_utc = v_now
      WHERE delta_recovery_scope.session_id = v_job_row.session_id
        AND delta_recovery_scope.candidate_id = v_job_row.candidate_id;

      v_continuation_jobs := jsonb_build_array(v_continuation_result, v_delta_recovery_enqueue_result);
      v_continuation_count := 1;
      v_continuation_reused_count := CASE
        WHEN LOWER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          OR LOWER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'dirty_enqueue_coalesced_all_relevant_scopes', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        THEN 1
        ELSE 0
      END;
      v_continuation_enqueued := true;
      v_next_recommended_action := 'DELTA_REFRESH_CHUNK';
    ELSIF v_delta_fallback_required IS TRUE THEN
      v_delta_fallback_enqueue_result := public.pay_workbench_enqueue_candidate_refresh(
        p_snapshot_run_id => v_session_row.source_snapshot_run_id,
        p_candidate_id => v_job_row.candidate_id,
        p_reason => COALESCE(v_delta_fallback_reason, 'DELTA_REFRESH_FALLBACK_REQUIRED'),
        p_actor_user_id => v_session_row.actor_user_id,
        p_payload_json => jsonb_strip_nulls(
          jsonb_build_object(
            'session_id', v_job_row.session_id::text,
            'source_session_id', v_job_row.session_id::text,
            'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
            'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
            'session_version', COALESCE(v_session_row.version, 0),
            'session_signature', v_session_row.session_signature,
            'force_legacy', true,
            'fallback_from_delta', true,
            'fallback_reason', v_delta_fallback_reason,
            'shadow_compare_failed', COALESCE(v_delta_shadow_compare_failed, false),
            'shadow_compare_status', NULLIF(v_delta_shadow_compare_status, ''),
            'shadow_compare_required', COALESCE(v_delta_shadow_compare_required, false),
            'shadow_compare_enforced', COALESCE(v_delta_shadow_compare_enforced, false),
            'projection_run_id', v_delta_projection_run_id_text,
            'projection_class', COALESCE(NULLIF(BTRIM(COALESCE(v_result_json->>'projection_class', '')), ''), NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'projection_class', '')), '')),
            'source_build_required', true,
            'line_work_required', true,
            'delta_refresh_required', false,
            'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
            'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb),
            'refresh_scope_kind', CASE WHEN jsonb_array_length(COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb)) > 0 OR jsonb_array_length(COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb)) > 0 THEN 'TARGETED_TIMESHEETS' ELSE 'CANDIDATE_FULL_LIVE' END
          )
        )
      );
      v_delta_fallback_job_id_text := NULLIF(BTRIM(COALESCE(v_delta_fallback_enqueue_result->>'job_id', '')), '');
      UPDATE public.banking_pay_workbench_session_scope AS delta_fallback_scope
      SET status = 'SOURCE_BUILD_PENDING',
          dirty = true,
          pending_job_id = CASE WHEN v_delta_fallback_job_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_delta_fallback_job_id_text::uuid ELSE delta_fallback_scope.pending_job_id END,
          error_json = NULL::jsonb,
          updated_at_utc = v_now
      WHERE delta_fallback_scope.session_id = v_job_row.session_id
        AND delta_fallback_scope.candidate_id = v_job_row.candidate_id;
      v_continuation_jobs := jsonb_build_array(v_delta_fallback_enqueue_result);
      v_continuation_count := CASE WHEN v_delta_fallback_job_id_text IS NULL THEN 0 ELSE 1 END;
      v_continuation_reused_count := CASE WHEN LOWER(BTRIM(COALESCE(v_delta_fallback_enqueue_result->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 1 ELSE 0 END;
      v_continuation_enqueued := v_delta_fallback_job_id_text IS NOT NULL;
      v_next_recommended_action := 'BUILD_SOURCE_CHUNK';
    ELSIF v_delta_refresh_complete IS TRUE
          AND LOWER(BTRIM(COALESCE(v_result_json->>'superseded_by_newer_source_change_seq', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      UPDATE public.banking_pay_workbench_session_scope AS delta_superseded_scope
      SET dirty = true,
          pending_job_id = CASE WHEN delta_superseded_scope.pending_job_id = p_job_id THEN NULL::uuid ELSE delta_superseded_scope.pending_job_id END,
          error_json = NULL::jsonb,
          updated_at_utc = v_now
      WHERE delta_superseded_scope.session_id = v_job_row.session_id
        AND delta_superseded_scope.candidate_id = v_job_row.candidate_id;

      v_next_recommended_action := 'DELTA_REFRESH_CHUNK';
    ELSIF v_delta_refresh_complete IS TRUE THEN
      UPDATE public.banking_pay_workbench_session_scope AS delta_ready_scope
      SET status = 'READY',
          seeded = true,
          dirty = false,
          pending_job_id = NULL::uuid,
          error_json = NULL::jsonb,
          updated_at_utc = v_now
      WHERE delta_ready_scope.session_id = v_job_row.session_id
        AND delta_ready_scope.candidate_id = v_job_row.candidate_id;

      -- Session counters/progress are recomputed authoritatively after the completing
      -- delta job is marked SUCCEEDED, so stored active_jobs never captures this job as stale.


      v_next_recommended_action := 'READ_PREVIEW_PAGE';
    ELSE
      v_delta_fallback_required := true;
      v_delta_fallback_reason := COALESCE(v_delta_fallback_reason, 'DELTA_RESULT_NOT_TERMINAL');
      v_delta_fallback_enqueue_result := public.pay_workbench_enqueue_candidate_refresh(
        p_snapshot_run_id => v_session_row.source_snapshot_run_id,
        p_candidate_id => v_job_row.candidate_id,
        p_reason => v_delta_fallback_reason,
        p_actor_user_id => v_session_row.actor_user_id,
        p_payload_json => jsonb_build_object(
          'session_id', v_job_row.session_id::text,
          'source_session_id', v_job_row.session_id::text,
          'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
          'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
          'session_version', COALESCE(v_session_row.version, 0),
          'session_signature', v_session_row.session_signature,
          'force_legacy', true,
          'fallback_from_delta', true,
          'fallback_reason', v_delta_fallback_reason,
          'shadow_compare_failed', COALESCE(v_delta_shadow_compare_failed, false),
          'shadow_compare_status', NULLIF(v_delta_shadow_compare_status, ''),
          'shadow_compare_required', COALESCE(v_delta_shadow_compare_required, false),
          'shadow_compare_enforced', COALESCE(v_delta_shadow_compare_enforced, false),
          'projection_run_id', v_delta_projection_run_id_text,
          'source_build_required', true,
          'line_work_required', true,
          'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb)
        )
      );
      v_continuation_jobs := jsonb_build_array(v_delta_fallback_enqueue_result);
      v_continuation_count := 1;
      v_next_recommended_action := 'BUILD_SOURCE_CHUNK';
    END IF;

    UPDATE public.banking_pay_workbench_jobs AS update_delta_job
    SET status = 'SUCCEEDED',
        updated_at_utc = v_now,
        completed_at_utc = v_now,
        failed_at_utc = NULL,
        last_error_json = NULL,
        payload_json = COALESCE(update_delta_job.payload_json, '{}'::jsonb)
          || jsonb_build_object('result_json', public.pay_workbench_compact_job_result_json(v_result_json))
          || jsonb_build_object(
            'completion_json', jsonb_build_object(
              'delta_completion_handled', true,
              'delta_refresh_complete', COALESCE(v_delta_refresh_complete, false),
              'fallback_required', COALESCE(v_delta_fallback_required, false),
              'fallback_reason', v_delta_fallback_reason,
              'superseded_by_newer_source_change_seq', COALESCE(v_delta_superseded_by_live_source_guard, false),
              'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
              'superseded_projection_runs', COALESCE(v_delta_superseded_projection_runs, 0),
              'shadow_compare_status', NULLIF(v_delta_shadow_compare_status, ''),
              'shadow_compare_required', COALESCE(v_delta_shadow_compare_required, false),
              'shadow_compare_enforced', COALESCE(v_delta_shadow_compare_enforced, false),
              'shadow_compare_failed', COALESCE(v_delta_shadow_compare_failed, false),
              'projection_run_id', v_delta_projection_run_id_text,
              'continuation_enqueued', COALESCE(v_continuation_enqueued, false),
              'continuation_jobs', COALESCE(v_continuation_jobs, '[]'::jsonb),
              'continuation_count', COALESCE(v_continuation_count, 0),
              'continuation_reused_count', COALESCE(v_continuation_reused_count, 0),
              'certified_source_preview', COALESCE(v_certified_publication_json, '{}'::jsonb),
              'next_recommended_action', v_next_recommended_action,
              'completed_at_utc', v_now::text
            )
          )
    WHERE update_delta_job.id = p_job_id
    RETURNING update_delta_job.*
    INTO v_job_row;

    PERFORM public.pay_workbench_session_recompute_progress_counters(
      p_session_id => v_job_row.session_id,
      p_apply => true,
      p_reason => CASE
        WHEN COALESCE(v_delta_fallback_required, false) IS TRUE THEN 'DELTA_COMPLETE_JOB_FALLBACK_AUTHORITATIVE_RECOMPUTE'
        ELSE 'DELTA_COMPLETE_JOB_AUTHORITATIVE_RECOMPUTE'
      END,
      p_write_progress_json => true
    );

    PERFORM public.pay_workbench_projection_lifecycle_repair(
      p_session_id => v_job_row.session_id,
      p_candidate_id => v_job_row.candidate_id,
      p_safe_age_seconds => 300,
      p_limit => 50,
      p_reason => 'DELTA_COMPLETE_JOB_PROJECTION_LIFECYCLE_REPAIR'
    );

    RETURN jsonb_build_object(
      'ok', true,
      'job_id', p_job_id::text,
      'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'stage_job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'delta_completion_handled', true,
      'delta_refresh_complete', COALESCE(v_delta_refresh_complete, false),
      'fallback_required', COALESCE(v_delta_fallback_required, false),
      'fallback_reason', v_delta_fallback_reason,
      'superseded_by_newer_source_change_seq', COALESCE(v_delta_superseded_by_live_source_guard, false),
      'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
      'superseded_projection_runs', COALESCE(v_delta_superseded_projection_runs, 0),
      'shadow_compare_status', NULLIF(v_delta_shadow_compare_status, ''),
      'shadow_compare_required', COALESCE(v_delta_shadow_compare_required, false),
      'shadow_compare_enforced', COALESCE(v_delta_shadow_compare_enforced, false),
      'shadow_compare_failed', COALESCE(v_delta_shadow_compare_failed, false),
      'projection_run_id', v_delta_projection_run_id_text,
      'continuation_enqueued', COALESCE(v_continuation_enqueued, false),
      'continuation_count', COALESCE(v_continuation_count, 0),
      'continuation_jobs', COALESCE(v_continuation_jobs, '[]'::jsonb),
      'next_recommended_action', v_next_recommended_action,
      'old_line_work_seed_enqueued', false,
      'old_line_work_process_enqueued', false,
      'old_preview_materialise_enqueued', false,
      'source_rows_written', COALESCE(v_delta_source_rows_written, 0),
      'line_rows_written', COALESCE(v_delta_line_rows_written, 0),
      'preview_rows_written', COALESCE(v_delta_preview_rows_written, 0),
      'rows_superseded', COALESCE(v_delta_rows_superseded, 0),
      'completed_at_utc', v_now::text
    );
  END IF;


  IF v_duplicate_completion IS NOT TRUE
     AND v_stage_job_type = 'WORKBENCH_SESSION_CLONE_REBASE' THEN
    v_clone_more_due := LOWER(BTRIM(COALESCE(v_result_json->>'more_due', v_result_json->>'has_more', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_clone_complete := LOWER(BTRIM(COALESCE(v_result_json->>'clone_rebase_complete', v_result_json->>'complete', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') OR v_clone_more_due IS NOT TRUE;
    v_clone_copied_candidate_count := CASE WHEN COALESCE(v_result_json->>'copied_candidate_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'copied_candidate_count')::integer ELSE 0 END;
    v_clone_copied_preview_row_count := CASE WHEN COALESCE(v_result_json->>'copied_preview_row_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'copied_preview_row_count')::integer ELSE 0 END;
    v_clone_legacy_refresh_enqueued_count := CASE WHEN COALESCE(v_result_json->>'legacy_refresh_enqueued_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'legacy_refresh_enqueued_count')::integer ELSE 0 END;
    v_clone_source_session_id_text := COALESCE(
      NULLIF(BTRIM(COALESCE(v_result_json->>'source_session_id', '')), ''),
      NULLIF(BTRIM(COALESCE(v_result_json->>'clone_from_session_id', '')), ''),
      NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'source_session_id', '')), ''),
      NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'source_session_id_text', '')), ''),
      NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'clone_from_session_id', '')), '')
    );
    IF v_clone_source_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_clone_source_session_id := v_clone_source_session_id_text::uuid;
    ELSE
      v_clone_source_session_id := NULL::uuid;
    END IF;

    PERFORM session_lock.id
    FROM public.banking_pay_workbench_sessions AS session_lock
    WHERE session_lock.id=ANY(array_remove(ARRAY[
      v_job_row.session_id,
      v_clone_source_session_id
    ]::uuid[],NULL::uuid))
    ORDER BY session_lock.id
    FOR UPDATE;

    SELECT target_session.*
    INTO v_session_row
    FROM public.banking_pay_workbench_sessions AS target_session
    WHERE target_session.id=v_job_row.session_id;

    IF v_clone_more_due IS TRUE THEN
      INSERT INTO public.banking_pay_workbench_jobs AS clone_continuation (
        job_type,
        status,
        priority,
        run_at_utc,
        dedupe_key,
        snapshot_run_id,
        session_id,
        candidate_id,
        payload_json,
        created_at_utc,
        updated_at_utc
      )
      VALUES (
        'WORKBENCH_SESSION_CLONE_REBASE',
        'QUEUED',
        COALESCE(v_job_row.priority, 45),
        v_now,
        'WORKBENCH_SESSION_CLONE_REBASE:session:' || v_job_row.session_id::text || ':cursor:' || md5(COALESCE(v_next_cursor, '{}'::jsonb)::text),
        v_job_row.snapshot_run_id,
        v_job_row.session_id,
        v_job_row.candidate_id,
        jsonb_strip_nulls(
          COALESCE(v_job_row.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'job_type', 'WORKBENCH_SESSION_CLONE_REBASE',
            'cursor_json', COALESCE(v_next_cursor, '{}'::jsonb),
            'source_job_id', p_job_id::text,
            'continuation', true,
            'more_due_from_previous', true,
            'previous_result_summary', jsonb_build_object(
              'copied_candidate_count', COALESCE(v_clone_copied_candidate_count, 0),
              'copied_preview_row_count', COALESCE(v_clone_copied_preview_row_count, 0),
              'legacy_refresh_enqueued_count', COALESCE(v_clone_legacy_refresh_enqueued_count, 0)
            )
          )
        ),
        v_now,
        v_now
      )
      ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
      DO UPDATE SET
        run_at_utc = LEAST(clone_continuation.run_at_utc, EXCLUDED.run_at_utc),
        priority = LEAST(clone_continuation.priority, EXCLUDED.priority),
        payload_json = COALESCE(clone_continuation.payload_json, '{}'::jsonb) || EXCLUDED.payload_json,
        updated_at_utc = v_now
      RETURNING clone_continuation.id
      INTO v_clone_continuation_job_id;

      v_continuation_result := jsonb_build_object(
        'ok', true,
        'job_id', v_clone_continuation_job_id::text,
        'job_type', 'WORKBENCH_SESSION_CLONE_REBASE',
        'continuation_enqueued', true
      );
      v_continuation_jobs := jsonb_build_array(v_continuation_result);
      v_continuation_count := 1;
      v_continuation_enqueued := true;
      v_next_recommended_action := 'CLONE_REBASE_CHUNK';
    ELSE
      v_next_recommended_action := CASE WHEN COALESCE(v_clone_legacy_refresh_enqueued_count, 0) > 0 THEN 'WAIT_FOR_WORKER' ELSE 'READ_PREVIEW_PAGE' END;
    END IF;

    IF COALESCE(v_clone_more_due, false) IS NOT TRUE
       AND v_clone_source_session_id IS NOT NULL
       AND v_job_row.session_id IS NOT NULL
       AND v_clone_source_session_id IS DISTINCT FROM v_job_row.session_id THEN
      UPDATE public.banking_pay_workbench_sessions AS clone_source_session
      SET status = 'DISCARDED',
          discarded_at_utc = COALESCE(clone_source_session.discarded_at_utc, v_now),
          replacement_session_id = v_job_row.session_id,
          replacement_idempotency_key = COALESCE(
            clone_source_session.replacement_idempotency_key,
            'clone-rebase-complete:' || clone_source_session.id::text || ':replacement:' || v_job_row.session_id::text
          ),
          progress_state = 'DISCARDED',
          progress_json = jsonb_strip_nulls(
            COALESCE(clone_source_session.progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'discard_reason', 'SUPERSEDED_BY_COMPLETED_CLONE_REBASE',
              'discarded_by_function', 'pay_workbench_complete_job',
              'replacement_session_id', v_job_row.session_id::text,
              'replacement_linked_at_utc', v_now::text,
              'clone_rebase_completed_by_job_id', p_job_id::text,
              'superseded_by_pay_date', CASE WHEN v_session_row.id IS NULL THEN NULL ELSE v_session_row.pay_date::text END,
              'superseded_by_week_ending_cutoff', CASE WHEN v_session_row.id IS NULL THEN NULL ELSE v_session_row.week_ending_cutoff::text END
            )
          ),
          progress_counter_version = COALESCE(clone_source_session.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
      WHERE clone_source_session.id = v_clone_source_session_id
        AND clone_source_session.status = 'OPEN'
        AND clone_source_session.discarded_at_utc IS NULL
        AND (
          v_session_row.id IS NULL
          OR clone_source_session.actor_user_id = v_session_row.actor_user_id
        )
        AND (
          v_session_row.id IS NULL
          OR clone_source_session.pay_date IS DISTINCT FROM v_session_row.pay_date
          OR clone_source_session.week_ending_cutoff IS DISTINCT FROM v_session_row.week_ending_cutoff
        );

      GET DIAGNOSTICS v_clone_source_session_retired_count = ROW_COUNT;
    END IF;

    UPDATE public.banking_pay_workbench_sessions AS clone_session_update
    SET progress_state = CASE
          WHEN v_clone_more_due IS TRUE THEN 'CLONE_REBASING'
          WHEN COALESCE(v_clone_legacy_refresh_enqueued_count, 0) > 0 THEN 'REFRESHING_CANDIDATES'
          WHEN COALESCE(clone_session_update.scope_pending_count, 0) = 0
           AND COALESCE(clone_session_update.line_units_pending, 0) = 0
           AND COALESCE(clone_session_update.scope_failed_count, 0) = 0
           AND COALESCE(clone_session_update.line_units_failed, 0) = 0
          THEN 'READY'
          ELSE COALESCE(NULLIF(BTRIM(clone_session_update.progress_state), ''), 'REFRESHING_CANDIDATES')
        END,
        progress_json = jsonb_strip_nulls(
          public.pay_workbench_session_compact_progress_json(COALESCE(clone_session_update.progress_json, '{}'::jsonb), true)
          || jsonb_build_object(
            'last_clone_rebase_job_id', p_job_id::text,
            'last_clone_rebase_completed_at_utc', v_now::text,
            'last_clone_rebase_more_due', COALESCE(v_clone_more_due, false),
            'last_clone_rebase_copied_candidate_count', COALESCE(v_clone_copied_candidate_count, 0),
            'last_clone_rebase_copied_preview_row_count', COALESCE(v_clone_copied_preview_row_count, 0),
            'last_clone_rebase_legacy_refresh_enqueued_count', COALESCE(v_clone_legacy_refresh_enqueued_count, 0),
            'last_clone_rebase_source_session_id', CASE WHEN v_clone_source_session_id IS NULL THEN NULL ELSE v_clone_source_session_id::text END,
            'last_clone_rebase_source_session_retired_count', COALESCE(v_clone_source_session_retired_count, 0),
            'next_recommended_action', v_next_recommended_action
          )
        ),
        progress_counter_version = COALESCE(clone_session_update.progress_counter_version, 0) + 1,
        progress_updated_at_utc = v_now,
        updated_at_utc = v_now
    WHERE clone_session_update.id = v_job_row.session_id;

    UPDATE public.banking_pay_workbench_jobs AS update_clone_job
    SET status = 'SUCCEEDED',
        updated_at_utc = v_now,
        completed_at_utc = v_now,
        failed_at_utc = NULL,
        last_error_json = NULL,
        payload_json = COALESCE(update_clone_job.payload_json, '{}'::jsonb)
          || jsonb_build_object('result_json', public.pay_workbench_compact_job_result_json(v_result_json))
          || jsonb_build_object(
            'completion_json', jsonb_build_object(
              'clone_rebase_completion_handled', true,
              'clone_rebase_complete', COALESCE(v_clone_complete, false),
              'more_due', COALESCE(v_clone_more_due, false),
              'continuation_enqueued', COALESCE(v_continuation_enqueued, false),
              'continuation_jobs', COALESCE(v_continuation_jobs, '[]'::jsonb),
              'source_session_id', CASE WHEN v_clone_source_session_id IS NULL THEN NULL ELSE v_clone_source_session_id::text END,
              'source_session_retired_count', COALESCE(v_clone_source_session_retired_count, 0),
              'source_session_retired', COALESCE(v_clone_source_session_retired_count, 0) > 0,
              'next_recommended_action', v_next_recommended_action,
              'completed_at_utc', v_now::text
            )
          )
    WHERE update_clone_job.id = p_job_id
    RETURNING update_clone_job.*
    INTO v_job_row;

    RETURN jsonb_build_object(
      'ok', true,
      'job_id', p_job_id::text,
      'job_type', 'WORKBENCH_SESSION_CLONE_REBASE',
      'stage_job_type', 'WORKBENCH_SESSION_CLONE_REBASE',
      'clone_rebase_completion_handled', true,
      'clone_rebase_complete', COALESCE(v_clone_complete, false),
      'more_due', COALESCE(v_clone_more_due, false),
      'continuation_enqueued', COALESCE(v_continuation_enqueued, false),
      'continuation_count', COALESCE(v_continuation_count, 0),
      'continuation_jobs', COALESCE(v_continuation_jobs, '[]'::jsonb),
      'copied_candidate_count', COALESCE(v_clone_copied_candidate_count, 0),
      'copied_preview_row_count', COALESCE(v_clone_copied_preview_row_count, 0),
      'legacy_refresh_enqueued_count', COALESCE(v_clone_legacy_refresh_enqueued_count, 0),
      'source_session_id', CASE WHEN v_clone_source_session_id IS NULL THEN NULL ELSE v_clone_source_session_id::text END,
      'source_session_retired_count', COALESCE(v_clone_source_session_retired_count, 0),
      'source_session_retired', COALESCE(v_clone_source_session_retired_count, 0) > 0,
      'next_recommended_action', v_next_recommended_action,
      'completed_at_utc', v_now::text
    );
  END IF;

  IF v_duplicate_completion IS NOT TRUE THEN
    IF v_stage_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
       AND v_job_row.session_id IS NOT NULL
       AND v_job_row.candidate_id IS NOT NULL
       AND v_has_more IS NOT TRUE THEN
      SELECT EXISTS(
        SELECT 1
        FROM public.banking_pay_workbench_candidate_line_work AS line_work_pending
        WHERE line_work_pending.session_id = v_job_row.session_id
          AND line_work_pending.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(line_work_pending.status, ''))) = 'PENDING'
      )
      INTO v_pending_line_work_exists;
    END IF;

    IF v_stage_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
       AND v_job_row.session_id IS NOT NULL
       AND v_job_row.candidate_id IS NOT NULL THEN
      SELECT EXISTS(
        SELECT 1
        FROM public.banking_pay_workbench_candidate_line_work AS line_work_pending
        WHERE line_work_pending.session_id = v_job_row.session_id
          AND line_work_pending.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(line_work_pending.status, ''))) = 'PENDING'
      )
      INTO v_pending_line_work_exists;

      SELECT EXISTS(
        SELECT 1
        FROM public.banking_pay_workbench_candidate_line_work AS line_work_ready
        WHERE line_work_ready.session_id = v_job_row.session_id
          AND line_work_ready.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(line_work_ready.status, ''))) = 'READY'
      )
      INTO v_ready_line_work_exists;
    END IF;

    IF v_stage_job_type IN (
         'WORKBENCH_CANDIDATE_SOURCE_BUILD',
         'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
         'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
         'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
       )
       AND v_job_row.session_id IS NOT NULL
       AND v_job_row.candidate_id IS NOT NULL THEN
      SELECT UPPER(BTRIM(COALESCE(scope_before_continuation.status, 'PENDING')))
      INTO v_scope_status_before_continuation
      FROM public.banking_pay_workbench_session_scope AS scope_before_continuation
      WHERE scope_before_continuation.session_id = v_job_row.session_id
        AND scope_before_continuation.candidate_id = v_job_row.candidate_id
      FOR UPDATE;
    END IF;

    IF v_stage_job_type = 'WORKBENCH_SESSION_SCOPE_SEED'
       AND v_has_more IS TRUE
       AND v_next_cursor IS NOT NULL THEN
      v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
        p_session_id => v_job_row.session_id,
        p_candidate_id => NULL::uuid,
        p_job_type => 'WORKBENCH_SESSION_SCOPE_SEED',
        p_cursor_json => v_next_cursor,
        p_source_job_id => p_job_id,
        p_result_json => v_result_json,
        p_actor_user_id => v_session_row.actor_user_id,
        p_reason => 'SCOPE_SEED_CURSOR_CONTINUATION',
        p_priority => 40,
        p_limit => v_payload_limit
      );
      v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
      v_next_recommended_action := 'SEED_SCOPE_CHUNK';
    ELSIF v_stage_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
          AND v_job_row.candidate_id IS NOT NULL THEN
      IF v_has_more IS TRUE AND v_next_cursor IS NULL THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_COMPLETE_JOB_SOURCE_BUILD_CURSOR_MISSING'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_COMPLETE_JOB_SOURCE_BUILD_CURSOR_MISSING',
                  'job_id', p_job_id::text,
                  'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
                  'candidate_id', v_job_row.candidate_id::text,
                  'job_type', v_stage_job_type,
                  'source_build_run_id', v_source_build_run_id_text,
                  'source_change_seq', v_source_change_seq,
                  'message', 'WORKBENCH_CANDIDATE_SOURCE_BUILD returned has_more=true without a next cursor; refusing to start line seed early.'
                )::text;
      ELSIF v_has_more IS TRUE THEN
        v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_job_type => 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
          p_cursor_json => v_next_cursor,
          p_source_job_id => p_job_id,
          p_result_json => v_result_json,
          p_actor_user_id => v_session_row.actor_user_id,
          p_reason => 'SOURCE_BUILD_CURSOR_CONTINUATION',
          p_priority => 44,
          p_limit => v_payload_limit
        );
        v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
        v_next_recommended_action := 'BUILD_SOURCE_CHUNK';
      ELSIF v_job_row.economic_build_id IS NOT NULL
            AND UPPER(BTRIM(COALESCE(v_result_json->>'private_stage', ''))) = 'COMPLETE'
            AND UPPER(BTRIM(COALESCE(v_result_json->>'stage_status', ''))) = 'COMPLETE'
            AND v_current_source_row_count_authoritative
            AND COALESCE(v_current_source_row_count, 0) > 0 THEN
        -- Bounded SOURCE_PUBLISH has already produced the complete canonical
        -- CURRENT set. The common terminal path below owns public scope and
        -- progress reconciliation; it must not enter the legacy line-work
        -- pipeline or carry private build identity into a legacy job.
        v_bounded_terminal_refresh_scope_kind := UPPER(BTRIM(COALESCE(
          NULLIF(v_result_json->>'refresh_scope_kind', ''),
          NULLIF(v_job_row.payload_json->>'refresh_scope_kind', ''),
          NULLIF(v_job_row.payload_json#>>'{source_build,refresh_scope_kind}', ''),
          'CANDIDATE_FULL_LIVE'
        )));

        DROP TABLE IF EXISTS pg_temp._bpay_complete_job_bounded_terminal_timesheets;
        CREATE TEMP TABLE _bpay_complete_job_bounded_terminal_timesheets ON COMMIT DROP AS
        WITH raw_timesheet_ids(timesheet_id_text) AS (
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result_json->'targeted_timesheet_ids') = 'array' THEN v_result_json->'targeted_timesheet_ids' ELSE '[]'::jsonb END)
          UNION
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result_json->'linked_timesheet_ids') = 'array' THEN v_result_json->'linked_timesheet_ids' ELSE '[]'::jsonb END)
          UNION
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_job_row.payload_json->'targeted_timesheet_ids') = 'array' THEN v_job_row.payload_json->'targeted_timesheet_ids' ELSE '[]'::jsonb END)
          UNION
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_job_row.payload_json->'linked_timesheet_ids') = 'array' THEN v_job_row.payload_json->'linked_timesheet_ids' ELSE '[]'::jsonb END)
          UNION
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_job_row.payload_json#>'{source_build,targeted_timesheet_ids}') = 'array' THEN v_job_row.payload_json#>'{source_build,targeted_timesheet_ids}' ELSE '[]'::jsonb END)
          UNION
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_job_row.payload_json#>'{source_build,linked_timesheet_ids}') = 'array' THEN v_job_row.payload_json#>'{source_build,linked_timesheet_ids}' ELSE '[]'::jsonb END)
          UNION
          SELECT current_source.timesheet_id::text
          FROM public.banking_pay_workbench_candidate_source_lines AS current_source
          WHERE current_source.session_id = v_job_row.session_id
            AND current_source.candidate_id = v_job_row.candidate_id
            AND current_source.session_version = COALESCE(v_result_session_version, v_session_row.version)
            AND current_source.source_build_run_id = v_source_build_run_id_text::uuid
            AND current_source.source_change_seq = v_source_change_seq
            AND current_source.status = 'CURRENT'
            AND current_source.timesheet_id IS NOT NULL
          UNION
          SELECT bounded_scope.timesheet_id::text
          FROM private.banking_pay_workbench_economic_build_scope AS bounded_scope
          WHERE bounded_scope.build_id = v_job_row.economic_build_id
        )
        SELECT DISTINCT LOWER(BTRIM(timesheet_id_text))::uuid AS timesheet_id
        FROM raw_timesheet_ids
        WHERE NULLIF(BTRIM(timesheet_id_text), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

        SELECT COUNT(*)::integer
        INTO v_bounded_terminal_targeted_timesheet_count
        FROM pg_temp._bpay_complete_job_bounded_terminal_timesheets;

        IF v_bounded_terminal_refresh_scope_kind = 'TARGETED_TIMESHEETS'
           AND COALESCE(v_bounded_terminal_targeted_timesheet_count, 0) = 0 THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_BOUNDED_TERMINAL_TARGET_SCOPE_REQUIRED'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_WORKBENCH_BOUNDED_TERMINAL_TARGET_SCOPE_REQUIRED',
                    'session_id', v_job_row.session_id::text,
                    'candidate_id', v_job_row.candidate_id::text,
                    'job_id', p_job_id::text,
                    'source_build_run_id', v_source_build_run_id_text,
                    'source_change_seq', v_source_change_seq
                  )::text;
        END IF;

        UPDATE public.banking_pay_workbench_candidate_source_lines AS bounded_previous_source
        SET status = 'SUPERSEDED',
            source_row_json = jsonb_strip_nulls(
              COALESCE(bounded_previous_source.source_row_json, '{}'::jsonb)
              || jsonb_build_object(
                'bounded_source_publish_superseded', true,
                'bounded_source_publish_job_id', p_job_id::text,
                'bounded_source_publish_build_id', v_job_row.economic_build_id::text,
                'bounded_source_publish_run_id', v_source_build_run_id_text,
                'bounded_source_publish_change_seq', v_source_change_seq,
                'bounded_source_publish_at_utc', v_now::text,
                'bounded_source_publish_reason', 'NEWER_CANONICAL_SOURCE_ALREADY_PUBLISHED'
              )
            ),
            updated_at_utc = v_now
        WHERE bounded_previous_source.session_id = v_job_row.session_id
          AND bounded_previous_source.candidate_id = v_job_row.candidate_id
          AND bounded_previous_source.session_version = COALESCE(v_result_session_version, v_session_row.version)
          AND UPPER(BTRIM(COALESCE(bounded_previous_source.status, ''))) IN (
            'CURRENT', 'DIRTY', 'ERROR', 'PENDING', 'READY'
          )
          AND bounded_previous_source.source_change_seq <= v_source_change_seq
          AND NOT (
            bounded_previous_source.status = 'CURRENT'
            AND bounded_previous_source.source_build_run_id = v_source_build_run_id_text::uuid
            AND bounded_previous_source.source_change_seq = v_source_change_seq
          )
          AND (
            v_bounded_terminal_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            OR bounded_previous_source.timesheet_id IN (
              SELECT bounded_timesheets.timesheet_id
              FROM pg_temp._bpay_complete_job_bounded_terminal_timesheets AS bounded_timesheets
            )
          );
        GET DIAGNOSTICS v_bounded_terminal_source_rows_retired_count = ROW_COUNT;

        UPDATE public.banking_pay_workbench_candidate_line_work AS bounded_legacy_line_work
        SET status = 'SKIPPED',
            work_payload_json = jsonb_strip_nulls(
              COALESCE(bounded_legacy_line_work.work_payload_json, '{}'::jsonb)
              || jsonb_build_object(
                'bounded_source_publish_superseded', true,
                'bounded_source_publish_job_id', p_job_id::text,
                'bounded_source_publish_build_id', v_job_row.economic_build_id::text,
                'bounded_source_publish_at_utc', v_now::text,
                'bounded_source_publish_reason', 'CANONICAL_SOURCE_ALREADY_PUBLISHED'
              )
            ),
            error_json = NULL::jsonb,
            updated_at_utc = v_now
        WHERE bounded_legacy_line_work.session_id = v_job_row.session_id
          AND bounded_legacy_line_work.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(bounded_legacy_line_work.status, ''))) IN (
            'PENDING', 'PROCESSING', 'RUNNING', 'QUEUED', 'DIRTY', 'READY'
          )
          AND (
            v_bounded_terminal_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            OR bounded_legacy_line_work.timesheet_id IN (
              SELECT bounded_timesheets.timesheet_id
              FROM pg_temp._bpay_complete_job_bounded_terminal_timesheets AS bounded_timesheets
            )
          );
        GET DIAGNOSTICS v_bounded_terminal_line_work_retired_count = ROW_COUNT;

        v_next_recommended_action := 'READ_PREVIEW_PAGE';
      ELSIF (
        (
          v_current_source_row_count_authoritative
          AND COALESCE(v_current_source_row_count, 0) > 0
        )
        OR (
          v_current_source_row_count_authoritative IS NOT TRUE
          AND (
            COALESCE(v_current_source_row_count, 0) > 0
            OR COALESCE(v_source_rows_written, 0) > 0
          )
        )
      ) THEN
        v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_job_type => 'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
          p_cursor_json => v_source_seed_cursor_json,
          p_source_job_id => p_job_id,
          p_result_json => v_result_json,
          p_actor_user_id => v_session_row.actor_user_id,
          p_reason => 'SOURCE_BUILD_COMPLETE_SEED_LINE_WORK',
          p_priority => 45,
          p_limit => v_payload_limit
        );
        v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
        v_next_recommended_action := 'SEED_LINE_WORK_CHUNK';
      ELSE
        DROP TABLE IF EXISTS pg_temp._bpay_complete_job_source_empty_timesheets;
        CREATE TEMP TABLE _bpay_complete_job_source_empty_timesheets ON COMMIT DROP AS
        WITH raw_timesheet_ids(timesheet_id_text) AS (
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result_json->'targeted_timesheet_ids') = 'array' THEN v_result_json->'targeted_timesheet_ids' ELSE '[]'::jsonb END)
          UNION ALL
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result_json->'linked_timesheet_ids') = 'array' THEN v_result_json->'linked_timesheet_ids' ELSE '[]'::jsonb END)
          UNION ALL
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result_json #> '{source_build,targeted_timesheet_ids}') = 'array' THEN v_result_json #> '{source_build,targeted_timesheet_ids}' ELSE '[]'::jsonb END)
          UNION ALL
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result_json #> '{source_build,linked_timesheet_ids}') = 'array' THEN v_result_json #> '{source_build,linked_timesheet_ids}' ELSE '[]'::jsonb END)
          UNION ALL
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_job_row.payload_json->'targeted_timesheet_ids') = 'array' THEN v_job_row.payload_json->'targeted_timesheet_ids' ELSE '[]'::jsonb END)
          UNION ALL
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_job_row.payload_json->'linked_timesheet_ids') = 'array' THEN v_job_row.payload_json->'linked_timesheet_ids' ELSE '[]'::jsonb END)
          UNION ALL
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_job_row.payload_json #> '{source_build,targeted_timesheet_ids}') = 'array' THEN v_job_row.payload_json #> '{source_build,targeted_timesheet_ids}' ELSE '[]'::jsonb END)
          UNION ALL
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_job_row.payload_json #> '{source_build,linked_timesheet_ids}') = 'array' THEN v_job_row.payload_json #> '{source_build,linked_timesheet_ids}' ELSE '[]'::jsonb END)
        )
        SELECT DISTINCT LOWER(BTRIM(timesheet_id_text))::uuid AS timesheet_id
        FROM raw_timesheet_ids
        WHERE NULLIF(BTRIM(timesheet_id_text), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

        SELECT COUNT(*)::integer
        INTO v_source_empty_targeted_timesheet_count
        FROM pg_temp._bpay_complete_job_source_empty_timesheets;

        v_delta_refresh_scope_kind := UPPER(BTRIM(COALESCE(
          NULLIF(v_result_json->>'refresh_scope_kind', ''),
          NULLIF(v_job_row.payload_json->>'refresh_scope_kind', ''),
          NULLIF(v_job_row.payload_json#>>'{source_build,refresh_scope_kind}', ''),
          'CANDIDATE_FULL_LIVE'
        )));

        IF v_delta_refresh_scope_kind = 'TARGETED_TIMESHEETS'
           AND COALESCE(v_source_empty_targeted_timesheet_count, 0) = 0 THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_SOURCE_EMPTY_TARGET_SCOPE_REQUIRED'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_WORKBENCH_SOURCE_EMPTY_TARGET_SCOPE_REQUIRED',
                    'session_id', v_job_row.session_id::text,
                    'candidate_id', v_job_row.candidate_id::text,
                    'job_id', p_job_id::text,
                    'refresh_scope_kind', v_delta_refresh_scope_kind
                  )::text;
        END IF;

        UPDATE public.banking_pay_workbench_session_scope AS source_empty_scope
        SET status = CASE
              WHEN v_delta_refresh_scope_kind = 'TARGETED_TIMESHEETS' THEN 'READY'
              ELSE 'SOURCE_EMPTY'
            END,
            seeded = true,
            dirty = false,
            pending_job_id = NULL::uuid,
            error_json = NULL::jsonb,
            updated_at_utc = v_now
        WHERE source_empty_scope.session_id = v_job_row.session_id
          AND source_empty_scope.candidate_id = v_job_row.candidate_id;

        UPDATE public.banking_pay_workbench_candidate_source_lines AS source_empty_source_line
        SET status = 'SUPERSEDED',
            source_row_json = jsonb_strip_nulls(
              COALESCE(source_empty_source_line.source_row_json, '{}'::jsonb)
              || jsonb_build_object(
                'source_empty_cleanup', true,
                'source_empty_cleanup_job_id', p_job_id::text,
                'source_empty_cleanup_at_utc', v_now::text,
                'source_empty_cleanup_reason', 'TARGETED_SOURCE_BUILD_RETURNED_ZERO_CURRENT_SOURCE_ROWS'
              )
            ),
            updated_at_utc = v_now
        WHERE source_empty_source_line.session_id = v_job_row.session_id
          AND source_empty_source_line.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(source_empty_source_line.status, ''))) IN ('CURRENT', 'READY', 'PENDING', 'DIRTY')
          AND (
            v_delta_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            OR source_empty_source_line.timesheet_id IN (
              SELECT empty_timesheets.timesheet_id
              FROM pg_temp._bpay_complete_job_source_empty_timesheets AS empty_timesheets
            )
          );
        GET DIAGNOSTICS v_source_empty_cleanup_source_row_count = ROW_COUNT;

        UPDATE public.banking_pay_workbench_candidate_line_work AS source_empty_line_work
        SET status = 'SKIPPED',
            work_payload_json = jsonb_strip_nulls(
              COALESCE(source_empty_line_work.work_payload_json, '{}'::jsonb)
              || jsonb_build_object(
                'source_empty_cleanup', true,
                'source_empty_cleanup_job_id', p_job_id::text,
                'source_empty_cleanup_at_utc', v_now::text,
                'source_empty_cleanup_reason', 'TARGETED_SOURCE_BUILD_RETURNED_ZERO_CURRENT_SOURCE_ROWS',
                'source_empty_cleanup_targeted_timesheet_count', COALESCE(v_source_empty_targeted_timesheet_count, 0)
              )
            ),
            error_json = NULL::jsonb,
            updated_at_utc = v_now
        WHERE source_empty_line_work.session_id = v_job_row.session_id
          AND source_empty_line_work.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(source_empty_line_work.status, ''))) IN (
            'PENDING',
            'PROCESSING',
            'RUNNING',
            'QUEUED',
            'DIRTY',
            'READY',
            'MATERIALISED',
            'MATERIALIZED'
          )
          AND (
            v_delta_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            OR source_empty_line_work.timesheet_id IN (
              SELECT empty_timesheets.timesheet_id
              FROM pg_temp._bpay_complete_job_source_empty_timesheets AS empty_timesheets
            )
          );
        GET DIAGNOSTICS v_source_empty_cleanup_line_work_count = ROW_COUNT;

        UPDATE public.banking_pay_workbench_preview_rows AS source_empty_preview_row
        SET status = 'SUPERSEDED',
            selected = false,
            selection_state = 'SUPERSEDED',
            row_json = jsonb_strip_nulls(
              COALESCE(source_empty_preview_row.row_json, '{}'::jsonb)
              || jsonb_build_object(
                'source_empty_cleanup', true,
                'source_empty_cleanup_job_id', p_job_id::text,
                'source_empty_cleanup_at_utc', v_now::text,
                'source_empty_cleanup_reason', 'TARGETED_SOURCE_BUILD_RETURNED_ZERO_CURRENT_SOURCE_ROWS',
                'not_payable_reason', 'SOURCE_EMPTY_AFTER_UNAUTHORISE_OR_SOURCE_CHANGE'
              )
            ),
            updated_at_utc = v_now
        WHERE source_empty_preview_row.session_id = v_job_row.session_id
          AND source_empty_preview_row.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(source_empty_preview_row.status, ''))) IN ('READY', 'DIRTY', 'PENDING')
          AND (
            v_delta_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            OR source_empty_preview_row.timesheet_id IN (
              SELECT empty_timesheets.timesheet_id
              FROM pg_temp._bpay_complete_job_source_empty_timesheets AS empty_timesheets
            )
          );
        GET DIAGNOSTICS v_source_empty_cleanup_preview_row_count = ROW_COUNT;

        BEGIN
          PERFORM 1
          FROM public.banking_pay_workbench_sessions AS source_empty_session_lock
          WHERE source_empty_session_lock.id = v_job_row.session_id
            AND UPPER(BTRIM(COALESCE(source_empty_session_lock.status, ''))) = 'OPEN'
            AND source_empty_session_lock.discarded_at_utc IS NULL
            AND COALESCE(source_empty_session_lock.version, 1) = COALESCE(v_session_row.version, 1)
            AND source_empty_session_lock.source_snapshot_run_id IS NOT DISTINCT FROM v_session_row.source_snapshot_run_id
            AND source_empty_session_lock.session_signature IS NOT DISTINCT FROM v_session_row.session_signature
          FOR UPDATE NOWAIT;

          IF FOUND THEN
            UPDATE public.banking_pay_workbench_sessions AS source_empty_session
            SET scope_ready_count = COALESCE(source_scope_counts.ready_count, 0),
                scope_pending_count = COALESCE(source_scope_counts.pending_count, 0),
                scope_failed_count = COALESCE(source_scope_counts.failed_count, 0),
                progress_state = CASE
                  WHEN COALESCE(source_scope_counts.pending_count, 0) > 0 THEN 'REFRESHING_CANDIDATES'
                  WHEN COALESCE(source_scope_counts.failed_count, 0) > 0 THEN 'ERROR'
                  ELSE source_empty_session.progress_state
                END,
                progress_json = public.pay_workbench_session_compact_progress_json(COALESCE(source_empty_session.progress_json, '{}'::jsonb), true)
                  || jsonb_build_object(
                    'last_source_build_empty_candidate_id', v_job_row.candidate_id::text,
                    'last_source_build_empty_at_utc', v_now::text,
                    'last_source_build_empty_job_id', p_job_id::text,
                    'next_recommended_action', 'READ_PREVIEW_PAGE',
                    'terminal_readiness_deferred', true,
                    'terminal_readiness_deferred_to', 'pay_workbench_complete_job',
                    'source_empty_session_progress_locking', 'NOWAIT',
                    'source_empty_session_progress_update_applied', true,
                    'source_empty_cleanup_source_row_count', COALESCE(v_source_empty_cleanup_source_row_count, 0),
                    'source_empty_cleanup_line_work_count', COALESCE(v_source_empty_cleanup_line_work_count, 0),
                    'source_empty_cleanup_preview_row_count', COALESCE(v_source_empty_cleanup_preview_row_count, 0),
                    'source_empty_cleanup_targeted_timesheet_count', COALESCE(v_source_empty_targeted_timesheet_count, 0)
                  ),
                progress_counter_version = COALESCE(source_empty_session.progress_counter_version, 0) + 1,
                progress_updated_at_utc = v_now,
                updated_at_utc = v_now
            FROM (
              SELECT
                COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_recount.status, ''))) IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY'))::integer AS ready_count,
                COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_recount.status, ''))) IN ('ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR'))::integer AS failed_count,
                COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_recount.status, ''))) NOT IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY', 'ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR'))::integer AS pending_count
              FROM public.banking_pay_workbench_session_scope AS scope_recount
              WHERE scope_recount.session_id = v_job_row.session_id
            ) AS source_scope_counts
            WHERE source_empty_session.id = v_job_row.session_id
            RETURNING source_empty_session.*
            INTO v_session_row;
          ELSE
            v_source_empty_session_progress_deferred := true;
            v_source_empty_session_progress_deferred_reason := 'SESSION_NOT_OPEN_OR_CONTEXT_STALE';
          END IF;
        EXCEPTION
          WHEN lock_not_available THEN
            v_source_empty_session_progress_deferred := true;
            v_source_empty_session_progress_deferred_reason := 'SESSION_LOCK_NOT_AVAILABLE';
        END;

        v_next_recommended_action := 'READ_PREVIEW_PAGE';
      END IF;
    ELSIF v_stage_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
          AND v_job_row.candidate_id IS NOT NULL THEN
      IF v_has_more IS TRUE AND v_next_cursor IS NOT NULL THEN
        v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_job_type => 'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
          p_cursor_json => v_next_cursor,
          p_source_job_id => p_job_id,
          p_result_json => v_result_json,
          p_actor_user_id => v_session_row.actor_user_id,
          p_reason => 'LINE_WORK_SEED_CURSOR_CONTINUATION',
          p_priority => 45,
          p_limit => v_payload_limit
        );
        v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
        v_next_recommended_action := 'SEED_LINE_WORK_CHUNK';
      ELSIF COALESCE(v_seeded_count, 0) > 0 OR v_pending_line_work_exists IS TRUE THEN
        v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_job_type => 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
          p_cursor_json => NULL::jsonb,
          p_source_job_id => p_job_id,
          p_result_json => v_result_json,
          p_actor_user_id => v_session_row.actor_user_id,
          p_reason => 'LINE_WORK_SEED_COMPLETE_PROCESS_PENDING',
          p_priority => 42,
          p_limit => v_payload_limit
        );
        v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
        v_next_recommended_action := 'PROCESS_LINE_WORK_CHUNK';
      END IF;
    ELSIF v_stage_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
          AND v_job_row.candidate_id IS NOT NULL THEN
      IF v_has_more IS TRUE AND v_next_cursor IS NOT NULL THEN
        v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_job_type => 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
          p_cursor_json => v_next_cursor,
          p_source_job_id => p_job_id,
          p_result_json => v_result_json,
          p_actor_user_id => v_session_row.actor_user_id,
          p_reason => 'LINE_WORK_PROCESS_CURSOR_CONTINUATION',
          p_priority => 42,
          p_limit => v_payload_limit
        );
        v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
        v_next_recommended_action := 'PROCESS_LINE_WORK_CHUNK';
      END IF;

      IF v_has_more IS NOT TRUE
         AND v_pending_line_work_exists IS NOT TRUE
         AND (COALESCE(v_ready_count_delta, 0) > 0 OR v_ready_line_work_exists IS TRUE) THEN
        v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_job_type => 'WORKBENCH_PREVIEW_ROWS_MATERIALISE',
          p_cursor_json => NULL::jsonb,
          p_source_job_id => p_job_id,
          p_result_json => v_result_json,
          p_actor_user_id => v_session_row.actor_user_id,
          p_reason => 'LINE_WORK_READY_MATERIALISE_PREVIEW_ROWS',
          p_priority => 41,
          p_limit => v_payload_limit
        );
        v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
        v_next_recommended_action := COALESCE(v_next_recommended_action, 'MATERIALISE_PREVIEW_ROWS_CHUNK');
      END IF;
    ELSIF v_stage_job_type = 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
          AND v_job_row.candidate_id IS NOT NULL THEN
      IF v_has_more IS TRUE AND v_next_cursor IS NOT NULL THEN
        v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_job_type => 'WORKBENCH_PREVIEW_ROWS_MATERIALISE',
          p_cursor_json => v_next_cursor,
          p_source_job_id => p_job_id,
          p_result_json => v_result_json,
          p_actor_user_id => v_session_row.actor_user_id,
          p_reason => 'PREVIEW_ROWS_MATERIALISE_CURSOR_CONTINUATION',
          p_priority => 41,
          p_limit => v_payload_limit
        );
        v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
        v_next_recommended_action := 'MATERIALISE_PREVIEW_ROWS_CHUNK';
      ELSIF COALESCE(v_materialised_count, 0) > 0 THEN
        v_next_recommended_action := 'READ_PREVIEW_PAGE';
      END IF;
    END IF;

    v_continuation_count := jsonb_array_length(COALESCE(v_continuation_jobs, '[]'::jsonb));
    v_continuation_enqueued := v_continuation_count > 0;

    SELECT COUNT(*)::integer
    INTO v_continuation_reused_count
    FROM jsonb_array_elements(COALESCE(v_continuation_jobs, '[]'::jsonb)) AS continuation_items(continuation_item)
    WHERE LOWER(BTRIM(COALESCE(continuation_items.continuation_item->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

    IF COALESCE(v_continuation_count, 0) > 0
       AND v_scope_status_before_continuation IS NOT NULL
       AND v_job_row.session_id IS NOT NULL
       AND v_job_row.candidate_id IS NOT NULL THEN
      SELECT UPPER(BTRIM(COALESCE(scope_after_continuation.status, 'PENDING')))
      INTO v_scope_status_after_continuation
      FROM public.banking_pay_workbench_session_scope AS scope_after_continuation
      WHERE scope_after_continuation.session_id = v_job_row.session_id
        AND scope_after_continuation.candidate_id = v_job_row.candidate_id
      FOR UPDATE;

      v_scope_bucket_before_continuation := CASE
        WHEN v_scope_status_before_continuation IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY') THEN 'READY'
        WHEN v_scope_status_before_continuation IN ('ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR') THEN 'FAILED'
        ELSE 'PENDING'
      END;

      v_scope_bucket_after_continuation := CASE
        WHEN v_scope_status_after_continuation IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY') THEN 'READY'
        WHEN v_scope_status_after_continuation IN ('ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR') THEN 'FAILED'
        ELSE 'PENDING'
      END;

      v_scope_continuation_pending_delta := CASE WHEN v_scope_bucket_after_continuation = 'PENDING' THEN 1 ELSE 0 END
        - CASE WHEN v_scope_bucket_before_continuation = 'PENDING' THEN 1 ELSE 0 END;
      v_scope_continuation_ready_delta := CASE WHEN v_scope_bucket_after_continuation = 'READY' THEN 1 ELSE 0 END
        - CASE WHEN v_scope_bucket_before_continuation = 'READY' THEN 1 ELSE 0 END;
      v_scope_continuation_failed_delta := CASE WHEN v_scope_bucket_after_continuation = 'FAILED' THEN 1 ELSE 0 END
        - CASE WHEN v_scope_bucket_before_continuation = 'FAILED' THEN 1 ELSE 0 END;

      IF COALESCE(v_scope_continuation_pending_delta, 0) <> 0
         OR COALESCE(v_scope_continuation_ready_delta, 0) <> 0
         OR COALESCE(v_scope_continuation_failed_delta, 0) <> 0 THEN
        BEGIN
          PERFORM 1
          FROM public.banking_pay_workbench_sessions AS continuation_session_lock
          WHERE continuation_session_lock.id = v_job_row.session_id
            AND UPPER(BTRIM(COALESCE(continuation_session_lock.status, ''))) = 'OPEN'
            AND continuation_session_lock.discarded_at_utc IS NULL
            AND COALESCE(continuation_session_lock.version, 1) = COALESCE(v_session_row.version, 1)
            AND continuation_session_lock.source_snapshot_run_id IS NOT DISTINCT FROM v_session_row.source_snapshot_run_id
            AND continuation_session_lock.session_signature IS NOT DISTINCT FROM v_session_row.session_signature
          FOR UPDATE NOWAIT;

          IF FOUND THEN
            UPDATE public.banking_pay_workbench_sessions AS continuation_session_update
            SET scope_pending_count = GREATEST(
                  COALESCE(continuation_session_update.scope_pending_count, 0)
                    + COALESCE(v_scope_continuation_pending_delta, 0),
                  0
                ),
                scope_ready_count = GREATEST(
                  COALESCE(continuation_session_update.scope_ready_count, 0)
                    + COALESCE(v_scope_continuation_ready_delta, 0),
                  0
                ),
                scope_failed_count = GREATEST(
                  COALESCE(continuation_session_update.scope_failed_count, 0)
                    + COALESCE(v_scope_continuation_failed_delta, 0),
                  0
                ),
                progress_json = public.pay_workbench_session_compact_progress_json(COALESCE(continuation_session_update.progress_json, '{}'::jsonb), true)
                  || jsonb_build_object(
                    'last_continuation_scope_old_status', v_scope_status_before_continuation,
                    'last_continuation_scope_new_status', v_scope_status_after_continuation,
                    'last_continuation_scope_pending_delta', COALESCE(v_scope_continuation_pending_delta, 0),
                    'last_continuation_scope_ready_delta', COALESCE(v_scope_continuation_ready_delta, 0),
                    'last_continuation_scope_failed_delta', COALESCE(v_scope_continuation_failed_delta, 0),
                    'last_continuation_scope_counter_adjusted_at_utc', v_now::text,
                    'last_continuation_scope_counter_locking', 'NOWAIT',
                    'last_continuation_scope_counter_lock_skipped', false
                  ),
                progress_counter_version = COALESCE(continuation_session_update.progress_counter_version, 0) + 1,
                progress_updated_at_utc = v_now,
                updated_at_utc = v_now
            WHERE continuation_session_update.id = v_job_row.session_id;

            v_scope_continuation_counter_adjusted := true;
          ELSE
            v_continuation_scope_counter_deferred := true;
            v_continuation_scope_counter_deferred_reason := 'SESSION_NOT_OPEN_OR_CONTEXT_STALE';
          END IF;
        EXCEPTION
          WHEN lock_not_available THEN
            v_continuation_scope_counter_deferred := true;
            v_continuation_scope_counter_deferred_reason := 'SESSION_LOCK_NOT_AVAILABLE';
        END;
      END IF;
    END IF;

    -- Bounded terminal ownership is not complete until the certified CURRENT
    -- source has been reconciled and published into the one public preview
    -- read model.  All work remains in this completion transaction.
    IF v_stage_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
       AND v_job_row.economic_build_id IS NOT NULL
       AND COALESCE(v_has_more, false) IS NOT TRUE
       AND UPPER(BTRIM(COALESCE(v_result_json->>'private_stage', ''))) = 'COMPLETE'
       AND UPPER(BTRIM(COALESCE(v_result_json->>'stage_status', ''))) = 'COMPLETE'
       AND v_current_source_row_count_authoritative IS TRUE
       AND v_source_build_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND v_source_change_seq IS NOT NULL THEN
      IF COALESCE(v_current_source_row_count, 0) > 0 THEN
        v_source_reconciliation_json := public.pay_workbench_reconcile_successful_source_build(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_source_build_run_id => v_source_build_run_id_text::uuid,
          p_source_change_seq => v_source_change_seq,
          p_session_version => COALESCE(v_result_session_version, v_session_row.version),
          p_success_job_id => p_job_id,
          p_refresh_scope_kind => COALESCE(
            NULLIF(BTRIM(COALESCE(v_result_json->>'refresh_scope_kind', '')), ''),
            NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'refresh_scope_kind', '')), ''),
            NULLIF(BTRIM(COALESCE(v_job_row.payload_json#>>'{source_build,refresh_scope_kind}', '')), ''),
            'CANDIDATE_FULL_LIVE'
          ),
          p_targeted_timesheet_ids => CASE
            WHEN jsonb_typeof(v_result_json->'targeted_timesheet_ids') = 'array' THEN v_result_json->'targeted_timesheet_ids'
            WHEN jsonb_typeof(v_job_row.payload_json->'targeted_timesheet_ids') = 'array' THEN v_job_row.payload_json->'targeted_timesheet_ids'
            WHEN jsonb_typeof(v_job_row.payload_json#>'{source_build,targeted_timesheet_ids}') = 'array' THEN v_job_row.payload_json#>'{source_build,targeted_timesheet_ids}'
            ELSE '[]'::jsonb
          END,
          p_linked_timesheet_ids => CASE
            WHEN jsonb_typeof(v_result_json->'linked_timesheet_ids') = 'array' THEN v_result_json->'linked_timesheet_ids'
            WHEN jsonb_typeof(v_job_row.payload_json->'linked_timesheet_ids') = 'array' THEN v_job_row.payload_json->'linked_timesheet_ids'
            WHEN jsonb_typeof(v_job_row.payload_json#>'{source_build,linked_timesheet_ids}') = 'array' THEN v_job_row.payload_json#>'{source_build,linked_timesheet_ids}'
            ELSE '[]'::jsonb
          END,
          p_recompute_session_progress => false
        );

        v_source_reconciliation_deferred := LOWER(BTRIM(COALESCE(v_source_reconciliation_json->>'deferred', 'false')))
          IN ('true', 't', '1', 'yes', 'y', 'on');
        v_source_reconciliation_applied := v_source_reconciliation_deferred IS NOT TRUE
          AND LOWER(BTRIM(COALESCE(v_source_reconciliation_json->>'ok', 'true')))
            NOT IN ('false', 'f', '0', 'no', 'n', 'off');

        IF v_source_reconciliation_applied IS NOT TRUE THEN
          RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH',
                    'reason', 'SOURCE_RECONCILIATION_NOT_COMPLETE'
                  )::text;
        END IF;
      ELSE
        v_source_reconciliation_applied := true;
        v_source_reconciliation_json := jsonb_build_object(
          'ok', true,
          'skipped', true,
          'reason', 'POSITIVELY_CERTIFIED_EMPTY_SOURCE',
          'progress_recomputed', false
        );
      END IF;

      v_certified_targeted_timesheet_ids := CASE
        WHEN jsonb_typeof(v_result_json->'targeted_timesheet_ids') = 'array'
          THEN v_result_json->'targeted_timesheet_ids'
        WHEN jsonb_typeof(v_job_row.payload_json->'targeted_timesheet_ids') = 'array'
          THEN v_job_row.payload_json->'targeted_timesheet_ids'
        WHEN jsonb_typeof(v_job_row.payload_json#>'{source_build,targeted_timesheet_ids}') = 'array'
          THEN v_job_row.payload_json#>'{source_build,targeted_timesheet_ids}'
        ELSE COALESCE((
          SELECT jsonb_agg(DISTINCT build_scope.timesheet_id::text ORDER BY build_scope.timesheet_id::text)
          FROM private.banking_pay_workbench_economic_build_scope AS build_scope
          WHERE build_scope.build_id = v_job_row.economic_build_id
            AND build_scope.timesheet_id IS NOT NULL
        ), '[]'::jsonb)
      END;
      v_certified_linked_timesheet_ids := CASE
        WHEN jsonb_typeof(v_result_json->'linked_timesheet_ids') = 'array'
          THEN v_result_json->'linked_timesheet_ids'
        WHEN jsonb_typeof(v_job_row.payload_json->'linked_timesheet_ids') = 'array'
          THEN v_job_row.payload_json->'linked_timesheet_ids'
        WHEN jsonb_typeof(v_job_row.payload_json#>'{source_build,linked_timesheet_ids}') = 'array'
          THEN v_job_row.payload_json#>'{source_build,linked_timesheet_ids}'
        ELSE '[]'::jsonb
      END;

      v_certified_publication_json := private.pay_workbench_publish_certified_source_preview_v1(
        p_session_id => v_job_row.session_id,
        p_candidate_id => v_job_row.candidate_id,
        p_economic_build_id => v_job_row.economic_build_id,
        p_source_build_run_id => v_source_build_run_id_text::uuid,
        p_source_change_seq => v_source_change_seq,
        p_session_version => COALESCE(v_result_session_version, v_session_row.version),
        p_completion_job_id => p_job_id,
        p_refresh_scope_kind => COALESCE(
          NULLIF(BTRIM(COALESCE(v_result_json->>'refresh_scope_kind', '')), ''),
          NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'refresh_scope_kind', '')), ''),
          NULLIF(BTRIM(COALESCE(v_job_row.payload_json#>>'{source_build,refresh_scope_kind}', '')), ''),
          'CANDIDATE_FULL_LIVE'
        ),
        p_targeted_timesheet_ids => v_certified_targeted_timesheet_ids,
        p_linked_timesheet_ids => v_certified_linked_timesheet_ids,
        p_publication_options_json => CASE
          WHEN v_semantic_publication_v3_enabled THEN jsonb_build_object(
            'authority_kind', 'BOUNDED_FULL_SOURCE_BUILD',
            'invocation_kind', 'INITIAL_COMPLETION',
            'contract_version', 3,
            'final_state', CASE WHEN COALESCE(v_current_source_row_count,0)=0 THEN 'SOURCE_EMPTY' ELSE 'READY' END,
            'semantic_contract_version', 'READY_TO_PAY_SEMANTIC_V2'
          )
          ELSE jsonb_build_object(
            'authority_kind', 'BOUNDED_FULL_SOURCE_BUILD',
            'invocation_kind', 'INITIAL_COMPLETION',
            'contract_version', 1
          )
        END
      );
      v_certified_publication_applied := COALESCE((v_certified_publication_json->>'parity_complete')::boolean, false);

      IF v_certified_publication_applied IS NOT TRUE THEN
        RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_PARITY_FAILED' USING ERRCODE = 'P0001';
      END IF;

      UPDATE public.banking_pay_workbench_session_scope AS certified_scope
      SET status = CASE
            WHEN COALESCE((v_certified_publication_json->>'source_row_count')::integer, 0) = 0 THEN 'SOURCE_EMPTY'
            ELSE 'MATERIALISED'
          END,
          seeded = true,
          dirty = false,
          pending_job_id = NULL::uuid,
          error_json = NULL::jsonb,
          updated_at_utc = v_now
      WHERE certified_scope.session_id = v_job_row.session_id
        AND certified_scope.candidate_id = v_job_row.candidate_id;
      GET DIAGNOSTICS v_bounded_terminal_scope_finalised_count = ROW_COUNT;

      v_finalisation_progress_json := public.pay_workbench_session_recompute_progress_counters(
        v_job_row.session_id,
        true,
        'CERTIFIED_SOURCE_PREVIEW_TERMINAL_COMPLETION',
        true
      );
      v_next_recommended_action := 'READ_PREVIEW_PAGE';
    END IF;

    UPDATE public.banking_pay_workbench_jobs AS update_job
    SET status = 'SUCCEEDED',
        updated_at_utc = v_now,
        completed_at_utc = v_now,
        failed_at_utc = NULL,
        last_error_json = NULL,
        payload_json = COALESCE(update_job.payload_json, '{}'::jsonb)
          || jsonb_build_object('result_json', public.pay_workbench_compact_job_result_json(v_result_json))
          || jsonb_build_object(
            'completion_json', jsonb_build_object(
              'continuation_enqueued', v_continuation_enqueued,
              'continuation_jobs', COALESCE(v_continuation_jobs, '[]'::jsonb),
              'continuation_count', COALESCE(v_continuation_count, 0),
              'continuation_reused_count', COALESCE(v_continuation_reused_count, 0),
              'next_recommended_action', v_next_recommended_action,
              'completed_at_utc', v_now::text
            )
          )
    WHERE update_job.id = p_job_id
    RETURNING update_job.*
    INTO v_job_row;

    v_completed_at_utc := v_now;

    IF v_stage_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
       AND v_source_reconciliation_applied IS NOT TRUE
       AND v_job_row.session_id IS NOT NULL
       AND v_job_row.candidate_id IS NOT NULL
       AND v_source_build_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND v_source_change_seq IS NOT NULL
       AND COALESCE(v_has_more, false) IS NOT TRUE
       AND (COALESCE(v_source_rows_written, 0) > 0 OR COALESCE(v_current_source_row_count, 0) > 0) THEN
      BEGIN
        v_source_reconciliation_json := public.pay_workbench_reconcile_successful_source_build(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_source_build_run_id => v_source_build_run_id_text::uuid,
          p_source_change_seq => v_source_change_seq,
          p_session_version => COALESCE(v_result_session_version, v_session_row.version),
          p_success_job_id => p_job_id,
          p_refresh_scope_kind => COALESCE(
            NULLIF(BTRIM(COALESCE(v_result_json->>'refresh_scope_kind', '')), ''),
            NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'refresh_scope_kind', '')), ''),
            NULLIF(BTRIM(COALESCE(v_job_row.payload_json#>>'{source_build,refresh_scope_kind}', '')), '')
          ),
          p_targeted_timesheet_ids => CASE
            WHEN jsonb_typeof(v_result_json->'targeted_timesheet_ids') = 'array' THEN v_result_json->'targeted_timesheet_ids'
            WHEN jsonb_typeof(v_job_row.payload_json->'targeted_timesheet_ids') = 'array' THEN v_job_row.payload_json->'targeted_timesheet_ids'
            WHEN jsonb_typeof(v_job_row.payload_json#>'{source_build,targeted_timesheet_ids}') = 'array' THEN v_job_row.payload_json#>'{source_build,targeted_timesheet_ids}'
            ELSE '[]'::jsonb
          END,
          p_linked_timesheet_ids => CASE
            WHEN jsonb_typeof(v_result_json->'linked_timesheet_ids') = 'array' THEN v_result_json->'linked_timesheet_ids'
            WHEN jsonb_typeof(v_job_row.payload_json->'linked_timesheet_ids') = 'array' THEN v_job_row.payload_json->'linked_timesheet_ids'
            WHEN jsonb_typeof(v_job_row.payload_json#>'{source_build,linked_timesheet_ids}') = 'array' THEN v_job_row.payload_json#>'{source_build,linked_timesheet_ids}'
            ELSE '[]'::jsonb
          END,
          p_recompute_session_progress => true
        );

        v_source_reconciliation_deferred := LOWER(BTRIM(COALESCE(v_source_reconciliation_json->>'deferred', 'false')))
          IN ('true', 't', '1', 'yes', 'y', 'on');
        v_source_reconciliation_deferred_reason := CASE
          WHEN v_source_reconciliation_deferred THEN NULLIF(BTRIM(COALESCE(v_source_reconciliation_json->>'reason', '')), '')
          ELSE NULL::text
        END;
        v_source_reconciliation_applied := v_source_reconciliation_deferred IS NOT TRUE
          AND LOWER(BTRIM(COALESCE(v_source_reconciliation_json->>'ok', 'true')))
            NOT IN ('false', 'f', '0', 'no', 'n', 'off');

        IF v_source_reconciliation_applied
           AND v_job_row.economic_build_id IS NOT NULL
           AND UPPER(BTRIM(COALESCE(v_result_json->>'private_stage', ''))) = 'COMPLETE'
           AND UPPER(BTRIM(COALESCE(v_result_json->>'stage_status', ''))) = 'COMPLETE'
           AND v_current_source_row_count_authoritative
           AND COALESCE(v_current_source_row_count, 0) > 0
           AND COALESCE(NULLIF(v_source_reconciliation_json->>'scope_rows_repaired', '')::integer, 0) > 0 THEN
          -- The bounded path publishes its canonical CURRENT set itself. Once
          -- that source is reconciled, no legacy line-work stage remains to
          -- move SOURCE_READY to a public terminal scope state.
          UPDATE public.banking_pay_workbench_session_scope AS bounded_terminal_scope
          SET status = 'MATERIALISED',
              seeded = true,
              dirty = false,
              pending_job_id = NULL::uuid,
              error_json = NULL::jsonb,
              updated_at_utc = v_now
          WHERE bounded_terminal_scope.session_id = v_job_row.session_id
            AND bounded_terminal_scope.candidate_id = v_job_row.candidate_id
            AND NOT EXISTS (
              SELECT 1
              FROM public.banking_pay_workbench_jobs AS newer_active_source_job
              WHERE newer_active_source_job.session_id = v_job_row.session_id
                AND newer_active_source_job.candidate_id = v_job_row.candidate_id
                AND newer_active_source_job.id <> p_job_id
                AND UPPER(BTRIM(COALESCE(newer_active_source_job.status, ''))) IN ('QUEUED', 'RUNNING')
                AND UPPER(BTRIM(COALESCE(newer_active_source_job.job_type, ''))) IN (
                  'WORKBENCH_CANDIDATE_SOURCE_BUILD',
                  'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
                  'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
                  'CANDIDATE_SOURCE_BUILD',
                  'CANDIDATE_SOURCE_BUILD_CHUNK',
                  'SOURCE_BUILD',
                  'SOURCE_BUILD_PAGE'
                )
            )
            AND EXISTS (
              SELECT 1
              FROM public.banking_pay_workbench_candidate_source_lines AS bounded_current_source
              WHERE bounded_current_source.session_id = v_job_row.session_id
                AND bounded_current_source.candidate_id = v_job_row.candidate_id
                AND bounded_current_source.session_version = COALESCE(v_result_session_version, v_session_row.version)
                AND bounded_current_source.source_build_run_id = v_source_build_run_id_text::uuid
                AND bounded_current_source.source_change_seq = v_source_change_seq
                AND bounded_current_source.status = 'CURRENT'
            );
          GET DIAGNOSTICS v_bounded_terminal_scope_finalised_count = ROW_COUNT;
        END IF;
      EXCEPTION
        WHEN lock_not_available THEN
          v_source_reconciliation_applied := false;
          v_source_reconciliation_deferred := true;
          v_source_reconciliation_deferred_reason := 'SESSION_LOCK_NOT_AVAILABLE';
          v_source_reconciliation_json := jsonb_build_object(
            'ok', true,
            'deferred', true,
            'reason', 'SESSION_LOCK_NOT_AVAILABLE',
            'session_id', v_job_row.session_id::text,
            'candidate_id', v_job_row.candidate_id::text,
            'source_build_run_id', v_source_build_run_id_text,
            'source_change_seq', v_source_change_seq,
            'progress_recomputed', false,
            'counter_reconciled', false,
            'retry_safe', true
          );
      END;
    END IF;
  END IF;

  IF v_stage_job_type IN (
       'WORKBENCH_CANDIDATE_SOURCE_BUILD',
       'WORKBENCH_CANDIDATE_DELTA_REFRESH',
       'WORKBENCH_SESSION_CLONE_REBASE',
       'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
       'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
       'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
     )
     AND v_job_row.session_id IS NOT NULL
     AND v_job_row.candidate_id IS NOT NULL
     AND COALESCE(v_continuation_count, 0) = 0 THEN
    UPDATE public.banking_pay_workbench_session_scope AS scope_update
    SET pending_job_id = NULL::uuid,
        updated_at_utc = v_now
    WHERE scope_update.session_id = v_job_row.session_id
      AND scope_update.candidate_id = v_job_row.candidate_id
      AND scope_update.pending_job_id = p_job_id;

    GET DIAGNOSTICS v_scope_pending_job_cleared_count = ROW_COUNT;
  END IF;

  IF v_stage_job_type IN (
       'WORKBENCH_SESSION_SCOPE_SEED',
       'WORKBENCH_CANDIDATE_SOURCE_BUILD',
       'WORKBENCH_CANDIDATE_DELTA_REFRESH',
       'WORKBENCH_SESSION_CLONE_REBASE',
       'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
       'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
       'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
     )
     AND v_job_row.session_id IS NOT NULL
     AND v_has_open_session THEN
    BEGIN
      SELECT session_row.*
      INTO v_session_row
      FROM public.banking_pay_workbench_sessions AS session_row
      WHERE session_row.id = v_job_row.session_id
        AND UPPER(BTRIM(COALESCE(session_row.status, ''))) = 'OPEN'
        AND session_row.discarded_at_utc IS NULL
        AND COALESCE(session_row.version, 1) = COALESCE(v_session_row.version, 1)
        AND session_row.source_snapshot_run_id IS NOT DISTINCT FROM v_session_row.source_snapshot_run_id
        AND session_row.session_signature IS NOT DISTINCT FROM v_session_row.session_signature
      FOR UPDATE NOWAIT;

      IF NOT FOUND THEN
        v_finalisation_deferred := true;
        v_finalisation_deferred_reason := 'SESSION_NOT_OPEN_OR_CONTEXT_STALE';
      END IF;
    EXCEPTION
      WHEN lock_not_available THEN
        v_finalisation_deferred := true;
        v_finalisation_deferred_reason := 'SESSION_LOCK_NOT_AVAILABLE';
    END;

    IF v_finalisation_deferred IS NOT TRUE THEN
      IF v_job_row.candidate_id IS NOT NULL THEN
      SELECT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_session_scope AS terminal_scope
        WHERE terminal_scope.session_id = v_job_row.session_id
          AND terminal_scope.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(terminal_scope.status, ''))) IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY')
          AND COALESCE(terminal_scope.dirty, false) IS NOT TRUE
          AND (
            terminal_scope.error_json IS NULL
            OR terminal_scope.error_json = '{}'::jsonb
            OR terminal_scope.error_json = 'null'::jsonb
          )
      )
      INTO v_current_candidate_terminal_success;
    END IF;

    v_finalisation_should_evaluate := (
      COALESCE(v_continuation_count, 0) = 0
      AND COALESCE(v_session_row.scope_seed_complete, false)
      AND COALESCE(v_session_row.scope_pending_count, 0) = 0
      AND COALESCE(v_session_row.scope_failed_count, 0) = 0
      AND COALESCE(v_session_row.line_units_pending, 0) = 0
      AND COALESCE(v_session_row.line_units_failed, 0) = 0
    )
    OR UPPER(BTRIM(COALESCE(v_session_row.progress_state, ''))) IN ('READY', 'READY_EMPTY');

    v_finalisation_actual_precheck_required := v_finalisation_should_evaluate IS NOT TRUE
      AND COALESCE(v_continuation_count, 0) = 0
      AND COALESCE(v_session_row.scope_seed_complete, false)
      AND COALESCE(v_session_row.scope_next_cursor_json, '{}'::jsonb) = '{}'::jsonb
      AND (
        v_stage_job_type = 'WORKBENCH_SESSION_SCOPE_SEED'
        OR v_current_candidate_terminal_success
      );

    IF v_finalisation_actual_precheck_required THEN
      SELECT
        NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_session_scope AS unresolved_scope
          WHERE unresolved_scope.session_id = v_job_row.session_id
            AND (
              UPPER(BTRIM(COALESCE(unresolved_scope.status, ''))) NOT IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY')
              OR COALESCE(unresolved_scope.seeded, false) IS NOT TRUE
              OR COALESCE(unresolved_scope.dirty, false)
              OR NOT (
                unresolved_scope.error_json IS NULL
                OR unresolved_scope.error_json = '{}'::jsonb
                OR unresolved_scope.error_json = 'null'::jsonb
              )
            )
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_line_work AS unresolved_line_work
          WHERE unresolved_line_work.session_id = v_job_row.session_id
            AND (
              UPPER(BTRIM(COALESCE(unresolved_line_work.status, ''))) NOT IN ('MATERIALISED', 'MATERIALIZED', 'SKIPPED')
              OR NOT (
                unresolved_line_work.error_json IS NULL
                OR unresolved_line_work.error_json = '{}'::jsonb
                OR unresolved_line_work.error_json = 'null'::jsonb
              )
            )
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_jobs AS active_job
          CROSS JOIN LATERAL (
            SELECT CASE
              WHEN COALESCE(active_job.payload_json->>'session_version', '') ~ '^[0-9]+$'
                THEN (active_job.payload_json->>'session_version')::bigint
              ELSE NULL::bigint
            END AS job_session_version
          ) AS active_job_version
          WHERE active_job.session_id = v_job_row.session_id
            AND UPPER(BTRIM(COALESCE(active_job.status, ''))) IN ('QUEUED', 'RUNNING')
            AND (
              active_job_version.job_session_version IS NULL
              OR active_job_version.job_session_version >= COALESCE(v_session_row.version, 0)
            )
        )
      INTO v_finalisation_actual_precheck_passed;

      v_finalisation_should_evaluate := COALESCE(v_finalisation_actual_precheck_passed, false);
    END IF;

    IF v_finalisation_should_evaluate THEN
      v_finalisation_progress_json := public.pay_workbench_session_recompute_progress_counters(
        p_session_id => v_job_row.session_id,
        p_apply => false,
        p_reason => 'COMPLETE_JOB_FINALISATION_AUTHORITATIVE_COUNTER_SNAPSHOT',
        p_write_progress_json => false
      );

      IF jsonb_typeof(COALESCE(v_finalisation_progress_json, '{}'::jsonb)) <> 'object'
         OR LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
         OR NOT (v_finalisation_progress_json ? 'session_ready') THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_COMPLETE_JOB_FINALISATION_PROGRESS_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_COMPLETE_JOB_FINALISATION_PROGRESS_INVALID',
                  'job_id', p_job_id::text,
                  'session_id', v_job_row.session_id::text,
                  'progress_result', COALESCE(v_finalisation_progress_json, '{}'::jsonb)
                )::text;
      END IF;

      v_finalisation_evaluated := true;
      v_finalisation_session_ready := LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'session_ready', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
      v_finalisation_ready_for_draft := LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
      v_finalisation_ready_empty := LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'ready_empty', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
      v_finalisation_stored_ready_mismatch := LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'stored_ready_mismatch', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
      v_finalisation_blocker_codes := CASE
        WHEN jsonb_typeof(COALESCE(v_finalisation_progress_json->'session_blocker_codes', '[]'::jsonb)) = 'array'
          THEN COALESCE(v_finalisation_progress_json->'session_blocker_codes', '[]'::jsonb)
        ELSE '[]'::jsonb
      END;
      v_finalisation_draft_blocker_codes := CASE
        WHEN jsonb_typeof(COALESCE(v_finalisation_progress_json->'draft_blocker_codes', '[]'::jsonb)) = 'array'
          THEN COALESCE(v_finalisation_progress_json->'draft_blocker_codes', '[]'::jsonb)
        ELSE '[]'::jsonb
      END;
      v_finalisation_blocker_counts := CASE
        WHEN jsonb_typeof(COALESCE(v_finalisation_progress_json->'blocker_counts', '{}'::jsonb)) = 'object'
          THEN COALESCE(v_finalisation_progress_json->'blocker_counts', '{}'::jsonb)
        ELSE '{}'::jsonb
      END;

      v_authoritative_scope_total := CASE WHEN COALESCE(v_finalisation_progress_json->>'scope_total_count', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'scope_total_count')::integer ELSE 0 END;
      v_authoritative_scope_seeded := CASE WHEN COALESCE(v_finalisation_progress_json->>'scope_seeded_count', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'scope_seeded_count')::integer ELSE 0 END;
      v_authoritative_scope_ready := CASE WHEN COALESCE(v_finalisation_progress_json->>'scope_ready_count', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'scope_ready_count')::integer ELSE 0 END;
      v_authoritative_scope_pending := CASE WHEN COALESCE(v_finalisation_progress_json->>'scope_pending_count', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'scope_pending_count')::integer ELSE 0 END;
      v_authoritative_scope_failed := CASE WHEN COALESCE(v_finalisation_progress_json->>'scope_failed_count', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'scope_failed_count')::integer ELSE 0 END;
      v_authoritative_line_total := CASE WHEN COALESCE(v_finalisation_progress_json->>'line_units_total', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'line_units_total')::integer ELSE 0 END;
      v_authoritative_line_pending := CASE WHEN COALESCE(v_finalisation_progress_json->>'line_units_pending', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'line_units_pending')::integer ELSE 0 END;
      v_authoritative_line_ready := CASE WHEN COALESCE(v_finalisation_progress_json->>'line_units_ready', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'line_units_ready')::integer ELSE 0 END;
      v_authoritative_line_failed := CASE WHEN COALESCE(v_finalisation_progress_json->>'line_units_failed', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'line_units_failed')::integer ELSE 0 END;
      v_authoritative_preview_row_count := CASE WHEN COALESCE(v_finalisation_progress_json->>'preview_row_count', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'preview_row_count')::integer ELSE 0 END;
      v_authoritative_selected_row_count := CASE WHEN COALESCE(v_finalisation_progress_json->>'selected_row_count', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'selected_row_count')::integer ELSE 0 END;
      v_authoritative_section_counts_json := CASE
        WHEN jsonb_typeof(COALESCE(v_finalisation_progress_json->'section_counts_json', '{}'::jsonb)) = 'object'
          THEN COALESCE(v_finalisation_progress_json->'section_counts_json', '{}'::jsonb)
        ELSE '{}'::jsonb
      END;
      v_authoritative_candidate_sample_rows_json := CASE
        WHEN jsonb_typeof(COALESCE(v_finalisation_progress_json->'candidate_sample_rows_json', '[]'::jsonb)) = 'array'
          THEN COALESCE(v_finalisation_progress_json->'candidate_sample_rows_json', '[]'::jsonb)
        ELSE '[]'::jsonb
      END;

      v_finalisation_counter_reconciliation_required := COALESCE(v_session_row.scope_total_count, 0) IS DISTINCT FROM COALESCE(v_authoritative_scope_total, 0)
        OR COALESCE(v_session_row.scope_seeded_count, 0) IS DISTINCT FROM COALESCE(v_authoritative_scope_seeded, 0)
        OR COALESCE(v_session_row.scope_ready_count, 0) IS DISTINCT FROM COALESCE(v_authoritative_scope_ready, 0)
        OR COALESCE(v_session_row.scope_pending_count, 0) IS DISTINCT FROM COALESCE(v_authoritative_scope_pending, 0)
        OR COALESCE(v_session_row.scope_failed_count, 0) IS DISTINCT FROM COALESCE(v_authoritative_scope_failed, 0)
        OR COALESCE(v_session_row.line_units_total, 0) IS DISTINCT FROM COALESCE(v_authoritative_line_total, 0)
        OR COALESCE(v_session_row.line_units_pending, 0) IS DISTINCT FROM COALESCE(v_authoritative_line_pending, 0)
        OR COALESCE(v_session_row.line_units_ready, 0) IS DISTINCT FROM COALESCE(v_authoritative_line_ready, 0)
        OR COALESCE(v_session_row.line_units_failed, 0) IS DISTINCT FROM COALESCE(v_authoritative_line_failed, 0)
        OR COALESCE(v_session_row.preview_row_count, 0) IS DISTINCT FROM COALESCE(v_authoritative_preview_row_count, 0)
        OR COALESCE(v_session_row.selected_row_count, 0) IS DISTINCT FROM COALESCE(v_authoritative_selected_row_count, 0)
        OR COALESCE(v_session_row.section_counts_json, '{}'::jsonb) IS DISTINCT FROM COALESCE(v_authoritative_section_counts_json, '{}'::jsonb);
      v_finalisation_counter_reconciliation_applied := v_duplicate_completion IS NOT TRUE;
      v_finalisation_counter_reconciled := v_finalisation_counter_reconciliation_applied;

      v_finalisation_counter_reconciliation_json := jsonb_build_object(
        'required', v_finalisation_counter_reconciliation_required,
        'applied', v_finalisation_counter_reconciliation_applied,
        'changed', v_finalisation_counter_reconciliation_required AND v_finalisation_counter_reconciliation_applied,
        'reconciled', v_finalisation_counter_reconciled,
        'scope_total_count', COALESCE(v_authoritative_scope_total, 0),
        'scope_seeded_count', COALESCE(v_authoritative_scope_seeded, 0),
        'scope_ready_count', COALESCE(v_authoritative_scope_ready, 0),
        'scope_pending_count', COALESCE(v_authoritative_scope_pending, 0),
        'scope_failed_count', COALESCE(v_authoritative_scope_failed, 0),
        'line_units_total', COALESCE(v_authoritative_line_total, 0),
        'line_units_pending', COALESCE(v_authoritative_line_pending, 0),
        'line_units_ready', COALESCE(v_authoritative_line_ready, 0),
        'line_units_failed', COALESCE(v_authoritative_line_failed, 0),
        'preview_row_count', COALESCE(v_authoritative_preview_row_count, 0),
        'selected_row_count', COALESCE(v_authoritative_selected_row_count, 0),
        'section_counts_json', COALESCE(v_authoritative_section_counts_json, '{}'::jsonb)
      );

      IF v_finalisation_session_ready THEN
        v_final_progress_state := CASE WHEN v_finalisation_ready_empty THEN 'READY_EMPTY' ELSE 'READY' END;
        v_final_phase := 'READY';
        v_final_status_text := 'Payment preview is ready.';
        v_final_next_recommended_action := 'READ_PREVIEW_PAGE';
      ELSE
        v_final_progress_state := UPPER(BTRIM(COALESCE(v_finalisation_progress_json->>'progress_state', '')));
        IF v_final_progress_state IN ('', 'READY', 'READY_EMPTY') THEN
          v_final_progress_state := CASE
            WHEN COALESCE(v_authoritative_scope_failed, 0) > 0
              OR COALESCE(v_authoritative_line_failed, 0) > 0
              OR (COALESCE(v_finalisation_blocker_codes, '[]'::jsonb) ? 'WORKBENCH_JOBS_FAILED') THEN 'ERROR'
            WHEN COALESCE(v_authoritative_line_ready, 0) > 0 THEN 'MATERIALISING_PREVIEW_ROWS'
            WHEN COALESCE(v_authoritative_line_pending, 0) > 0 THEN 'PROCESSING_LINE_WORK'
            ELSE 'REFRESHING_CANDIDATES'
          END;
        END IF;
        v_final_phase := COALESCE(NULLIF(BTRIM(v_finalisation_progress_json->>'phase'), ''), 'REFRESHING_CANDIDATES');
        v_final_status_text := COALESCE(NULLIF(BTRIM(v_finalisation_progress_json->>'status_text'), ''), 'Preparing payment preview.');
        v_final_next_recommended_action := COALESCE(NULLIF(BTRIM(v_finalisation_progress_json->>'next_recommended_action'), ''), 'WAIT_FOR_WORKER');
      END IF;

      IF v_duplicate_completion IS NOT TRUE THEN
        UPDATE public.banking_pay_workbench_sessions AS session_update
        SET scope_total_count = GREATEST(COALESCE(v_authoritative_scope_total, 0), 0),
          scope_seeded_count = GREATEST(COALESCE(v_authoritative_scope_seeded, 0), 0),
          scope_ready_count = GREATEST(COALESCE(v_authoritative_scope_ready, 0), 0),
          scope_pending_count = GREATEST(COALESCE(v_authoritative_scope_pending, 0), 0),
          scope_failed_count = GREATEST(COALESCE(v_authoritative_scope_failed, 0), 0),
          line_units_total = GREATEST(COALESCE(v_authoritative_line_total, 0), 0),
          line_units_pending = GREATEST(COALESCE(v_authoritative_line_pending, 0), 0),
          line_units_ready = GREATEST(COALESCE(v_authoritative_line_ready, 0), 0),
          line_units_failed = GREATEST(COALESCE(v_authoritative_line_failed, 0), 0),
          preview_row_count = GREATEST(COALESCE(v_authoritative_preview_row_count, 0), 0),
          selected_row_count = GREATEST(COALESCE(v_authoritative_selected_row_count, 0), 0),
          section_counts_json = COALESCE(v_authoritative_section_counts_json, '{}'::jsonb),
          candidate_sample_rows_json = COALESCE(v_authoritative_candidate_sample_rows_json, '[]'::jsonb),
          progress_state = v_final_progress_state,
          progress_json = public.pay_workbench_session_compact_progress_json(
            jsonb_strip_nulls(
              jsonb_build_object(
              'ok', true,
              'server_utc', v_now,
              'updated_at_utc', v_now,
              'phase', v_final_phase,
              'status_text', v_final_status_text,
              'next_recommended_action', v_final_next_recommended_action,
              'progress_state', v_final_progress_state,
              'ready', v_finalisation_session_ready,
              'ready_flag', v_finalisation_session_ready,
              'session_ready', v_finalisation_session_ready,
              'ready_for_draft', v_finalisation_ready_for_draft,
              'can_create_draft', v_finalisation_ready_for_draft,
              'ready_empty', v_finalisation_ready_empty,
              'preview_ready', v_finalisation_session_ready,
              'work_queued', CASE
                WHEN v_finalisation_session_ready THEN false
                ELSE LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'work_queued', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              END,
              'still_running', CASE
                WHEN v_finalisation_session_ready THEN false
                ELSE LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'still_running', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              END,
              'pending_refresh', CASE
                WHEN v_finalisation_session_ready THEN false
                ELSE LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'pending_refresh', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              END,
              'refresh_pending', CASE
                WHEN v_finalisation_session_ready THEN false
                ELSE LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'refresh_pending', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              END,
              'preview_refresh_pending', CASE
                WHEN v_finalisation_session_ready THEN false
                ELSE LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'preview_refresh_pending', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              END,
              'preview_deferred', CASE
                WHEN v_finalisation_session_ready THEN false
                ELSE LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'preview_deferred', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              END,
              'authoritative_session_ready', v_finalisation_session_ready,
              'authoritative_ready_for_draft', v_finalisation_ready_for_draft,
              'authoritative_ready_empty', v_finalisation_ready_empty,
              'authoritative_progress_state', v_final_progress_state,
              'session_blocker_codes', COALESCE(v_finalisation_blocker_codes, '[]'::jsonb),
              'draft_blocker_codes', COALESCE(v_finalisation_draft_blocker_codes, '[]'::jsonb),
              'blocker_codes', COALESCE(v_finalisation_draft_blocker_codes, '[]'::jsonb),
              'blocker_counts', COALESCE(v_finalisation_blocker_counts, '{}'::jsonb),
              'stored_ready_mismatch', v_finalisation_stored_ready_mismatch
            )
            || jsonb_build_object(
              'scope_total_count', COALESCE(v_authoritative_scope_total, 0),
              'scope_seeded_count', COALESCE(v_authoritative_scope_seeded, 0),
              'scope_ready_count', COALESCE(v_authoritative_scope_ready, 0),
              'scope_pending_count', COALESCE(v_authoritative_scope_pending, 0),
              'scope_failed_count', COALESCE(v_authoritative_scope_failed, 0),
              'line_units_total', COALESCE(v_authoritative_line_total, 0),
              'line_units_pending', COALESCE(v_authoritative_line_pending, 0),
              'line_units_ready', COALESCE(v_authoritative_line_ready, 0),
              'line_units_failed', COALESCE(v_authoritative_line_failed, 0),
              'preview_row_count', COALESCE(v_authoritative_preview_row_count, 0),
              'selected_row_count', COALESCE(v_authoritative_selected_row_count, 0),
              'selected_eligible_ready_row_count', CASE
                WHEN COALESCE(v_finalisation_progress_json->>'selected_eligible_ready_row_count', '') ~ '^[0-9]+$'
                  THEN (v_finalisation_progress_json->>'selected_eligible_ready_row_count')::integer
                ELSE COALESCE(v_authoritative_selected_row_count, 0)
              END,
              'section_counts_json', COALESCE(v_authoritative_section_counts_json, '{}'::jsonb),
              'candidate_sample_rows_json', COALESCE(v_authoritative_candidate_sample_rows_json, '[]'::jsonb),
              'candidate_counts', CASE
                WHEN jsonb_typeof(v_finalisation_progress_json->'candidate_counts') = 'object'
                  THEN v_finalisation_progress_json->'candidate_counts'
                ELSE '{}'::jsonb
              END,
              'line_counts', CASE
                WHEN jsonb_typeof(v_finalisation_progress_json->'line_counts') = 'object'
                  THEN v_finalisation_progress_json->'line_counts'
                ELSE '{}'::jsonb
              END,
              'job_counts', CASE
                WHEN jsonb_typeof(v_finalisation_progress_json->'job_counts') = 'object'
                  THEN v_finalisation_progress_json->'job_counts'
                ELSE '{}'::jsonb
              END,
              'source_build_counts', CASE
                WHEN jsonb_typeof(v_finalisation_progress_json->'source_build_counts') = 'object'
                  THEN v_finalisation_progress_json->'source_build_counts'
                ELSE '{}'::jsonb
              END,
              'pending_job_ids_json', CASE
                WHEN v_finalisation_session_ready THEN '[]'::jsonb
                WHEN jsonb_typeof(v_finalisation_progress_json->'pending_job_ids_json') = 'array'
                  THEN v_finalisation_progress_json->'pending_job_ids_json'
                ELSE '[]'::jsonb
              END,
              'session_blockers', CASE
                WHEN jsonb_typeof(v_finalisation_progress_json->'session_blockers') = 'array'
                  THEN v_finalisation_progress_json->'session_blockers'
                ELSE '[]'::jsonb
              END,
              'draft_blockers', CASE
                WHEN jsonb_typeof(v_finalisation_progress_json->'draft_blockers') = 'array'
                  THEN v_finalisation_progress_json->'draft_blockers'
                ELSE '[]'::jsonb
              END
            )
            || jsonb_build_object(
              'finalisation_evaluated', true,
              'finalisation_evaluated_at_utc', v_now::text,
              'finalisation_source_job_id', p_job_id::text,
              'finalisation_source_job_type', v_stage_job_type,
              'terminal_readiness_deferred', v_finalisation_session_ready IS NOT TRUE,
              'finalisation_pending', v_finalisation_session_ready IS NOT TRUE,
              'finalised_at_utc', CASE WHEN v_finalisation_session_ready THEN v_now::text ELSE NULL::text END,
              'counter_reconciled', v_finalisation_counter_reconciled,
              'counter_reconciliation', COALESCE(v_finalisation_counter_reconciliation_json, '{}'::jsonb)
            )
            ),
            true
          ),
          progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
        WHERE session_update.id = v_job_row.session_id
        RETURNING session_update.*
        INTO v_session_row;
      END IF;
    END IF;
    END IF;
  END IF;

  v_completion_finalisation_json := jsonb_build_object(
    'finalisation_evaluated', v_finalisation_evaluated,
    'session_ready', CASE WHEN v_finalisation_evaluated THEN v_finalisation_session_ready ELSE NULL::boolean END,
    'ready_for_draft', CASE WHEN v_finalisation_evaluated THEN v_finalisation_ready_for_draft ELSE NULL::boolean END,
    'ready_empty', CASE WHEN v_finalisation_evaluated THEN v_finalisation_ready_empty ELSE NULL::boolean END,
    'final_progress_state', CASE WHEN v_finalisation_evaluated THEN v_final_progress_state ELSE v_session_row.progress_state END,
    'blocker_codes', COALESCE(v_finalisation_blocker_codes, '[]'::jsonb),
    'draft_blocker_codes', COALESCE(v_finalisation_draft_blocker_codes, '[]'::jsonb),
    'counter_reconciliation_required', v_finalisation_counter_reconciliation_required,
    'counter_reconciliation_applied', v_finalisation_counter_reconciliation_applied,
    'counter_reconciled', v_finalisation_counter_reconciled,
    'counter_reconciliation', COALESCE(v_finalisation_counter_reconciliation_json, '{}'::jsonb),
    'source_build_reconciliation_applied', v_source_reconciliation_applied,
    'source_build_reconciliation', COALESCE(v_source_reconciliation_json, '{}'::jsonb),
    'certified_source_preview_applied', v_certified_publication_applied,
    'certified_source_preview', COALESCE(v_certified_publication_json, '{}'::jsonb),
    'actual_precheck_required', v_finalisation_actual_precheck_required,
    'actual_precheck_passed', v_finalisation_actual_precheck_passed,
    'scope_pending_job_cleared_count', COALESCE(v_scope_pending_job_cleared_count, 0),
    'continuation_scope_counter_adjusted', v_scope_continuation_counter_adjusted,
    'continuation_scope_old_status', v_scope_status_before_continuation,
    'continuation_scope_new_status', v_scope_status_after_continuation,
    'continuation_scope_pending_delta', COALESCE(v_scope_continuation_pending_delta, 0),
    'continuation_scope_ready_delta', COALESCE(v_scope_continuation_ready_delta, 0),
    'continuation_scope_failed_delta', COALESCE(v_scope_continuation_failed_delta, 0),
    'source_build_reconciliation_deferred', COALESCE(v_source_reconciliation_deferred, false),
    'source_build_reconciliation_deferred_reason', v_source_reconciliation_deferred_reason,
    'source_empty_session_progress_deferred', COALESCE(v_source_empty_session_progress_deferred, false),
    'source_empty_session_progress_deferred_reason', v_source_empty_session_progress_deferred_reason,
    'source_empty_cleanup_source_row_count', COALESCE(v_source_empty_cleanup_source_row_count, 0),
    'source_empty_cleanup_line_work_count', COALESCE(v_source_empty_cleanup_line_work_count, 0),
    'source_empty_cleanup_preview_row_count', COALESCE(v_source_empty_cleanup_preview_row_count, 0),
    'source_empty_cleanup_targeted_timesheet_count', COALESCE(v_source_empty_targeted_timesheet_count, 0),
    'bounded_terminal_targeted_timesheet_count', COALESCE(v_bounded_terminal_targeted_timesheet_count, 0),
    'bounded_terminal_source_rows_retired_count', COALESCE(v_bounded_terminal_source_rows_retired_count, 0),
    'bounded_terminal_line_work_retired_count', COALESCE(v_bounded_terminal_line_work_retired_count, 0),
    'bounded_terminal_scope_finalised_count', COALESCE(v_bounded_terminal_scope_finalised_count, 0),
    'continuation_scope_counter_deferred', COALESCE(v_continuation_scope_counter_deferred, false),
    'continuation_scope_counter_deferred_reason', v_continuation_scope_counter_deferred_reason,
    'finalisation_deferred', COALESCE(v_finalisation_deferred, false),
    'finalisation_deferred_reason', v_finalisation_deferred_reason,
    'evaluated_at_utc', CASE WHEN v_finalisation_evaluated THEN v_now::text ELSE NULL::text END
  );

  IF v_duplicate_completion IS NOT TRUE THEN
    UPDATE public.banking_pay_workbench_jobs AS update_job
    SET payload_json = COALESCE(update_job.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'completion_json', COALESCE(update_job.payload_json->'completion_json', '{}'::jsonb)
              || v_completion_finalisation_json
          ),
        updated_at_utc = v_now
    WHERE update_job.id = p_job_id
    RETURNING update_job.*
    INTO v_job_row;

    -- A correction fallback build can finish after the correction operation.
    -- Emit one lightweight batch signal only when this exact source-build job
    -- has made its candidate physically current.  The payload claim makes the
    -- hook idempotent and does not create a second financial or queue owner.
    IF v_stage_job_type='WORKBENCH_CANDIDATE_SOURCE_BUILD'
       AND v_has_more IS NOT TRUE AND COALESCE(v_continuation_count,0)=0
       AND COALESCE(v_current_candidate_terminal_success,false)
       AND COALESCE(v_job_row.payload_json->>'correction_request_id','')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_correction_request_id:=(v_job_row.payload_json->>'correction_request_id')::uuid;
      SELECT request_row.pay_batch_id
      INTO v_correction_pay_batch_id
      FROM public.pay_payment_correction_requests AS request_row
      WHERE request_row.id=v_correction_request_id
        AND request_row.status IN ('APPLIED','APPLIED_WITH_BLOCKERS','BLOCKED');

      IF v_correction_pay_batch_id IS NOT NULL THEN
        UPDATE public.banking_pay_workbench_jobs AS signal_job
        SET payload_json=COALESCE(signal_job.payload_json,'{}'::jsonb)||pg_catalog.jsonb_build_object(
              'correction_terminal_current_signal_emitted',true,
              'correction_terminal_current_signal_emitted_at_utc',v_now
            ),updated_at_utc=v_now
        WHERE signal_job.id=p_job_id
          AND COALESCE((signal_job.payload_json->>'correction_terminal_current_signal_emitted')::boolean,false)
            IS NOT TRUE
        RETURNING true INTO v_correction_signal_claimed;

        IF COALESCE(v_correction_signal_claimed,false) THEN
          PERFORM public.banking_pay_batch_signal_touch(
            p_pay_batch_id:=v_correction_pay_batch_id,
            p_change_reason:='PAYMENT_CORRECTION_WORKBENCH_CURRENT',
            p_change_source:='pay_workbench_complete_job',
            p_change_scope_json:=pg_catalog.jsonb_build_object(
              'correction_request_id',v_correction_request_id,
              'job_id',p_job_id,'candidate_id',v_job_row.candidate_id,
              'workbench_status','CURRENT'
            ),
            p_touch_payment_status:=true,p_touch_correction_progress:=true,
            p_touch_alerts:=false,p_touch_overview:=true
          );
        END IF;
      END IF;
    END IF;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      p_job_id::text,
      'SUCCEEDED',
      NULL,
      jsonb_build_object(
        'id', p_job_id::text,
        'job_type', v_job_row.job_type,
        'status', v_job_row.status,
        'snapshot_run_id', CASE WHEN v_job_row.snapshot_run_id IS NULL THEN NULL ELSE v_job_row.snapshot_run_id::text END,
        'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
        'candidate_id', CASE WHEN v_job_row.candidate_id IS NULL THEN NULL ELSE v_job_row.candidate_id::text END,
        'attempt_count', v_job_row.attempt_count,
        'completed_at_utc', v_job_row.completed_at_utc,
        'continuation_count', COALESCE(v_continuation_count, 0),
        'continuation_reused_count', COALESCE(v_continuation_reused_count, 0),
        'next_recommended_action', v_next_recommended_action
      )
      || jsonb_build_object(
        'has_more', v_has_more,
        'next_cursor_present', v_next_cursor IS NOT NULL,
        'seeded_count', COALESCE(v_seeded_count, 0),
        'source_rows_written', COALESCE(v_source_rows_written, 0),
        'current_source_row_count', COALESCE(v_current_source_row_count, 0),
        'source_build_run_id', v_source_build_run_id_text,
        'source_change_seq', v_source_change_seq,
        'new_scope_count', COALESCE(v_new_scope_count, 0),
        'processed_count', COALESCE(v_processed_count, 0),
        'ready_count_delta', COALESCE(v_ready_count_delta, 0),
        'materialised_count', COALESCE(v_materialised_count, 0),
        'error_count', COALESCE(v_error_count, 0),
        'finalisation', v_completion_finalisation_json,
        'source_build_reconciliation', COALESCE(v_source_reconciliation_json, '{}'::jsonb),
        'certified_source_preview', COALESCE(v_certified_publication_json, '{}'::jsonb),
        'source_build_reconciliation_deferred', COALESCE(v_source_reconciliation_deferred, false),
        'source_build_reconciliation_deferred_reason', v_source_reconciliation_deferred_reason
      ),
      'WORKBENCH_JOB_COMPLETED',
      NULL
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', p_job_id::text,
    'status', 'SUCCEEDED',
    'completed_at_utc', COALESCE(v_completed_at_utc, v_job_row.completed_at_utc, v_now),
    'result_json', v_result_json,
    'continuation_enqueued', v_continuation_enqueued,
    'continuation_jobs', COALESCE(v_continuation_jobs, '[]'::jsonb),
    'continuation_count', COALESCE(v_continuation_count, 0),
    'continuation_reused_count', COALESCE(v_continuation_reused_count, 0),
    'next_recommended_action', v_next_recommended_action,
    'has_more', v_has_more,
    'next_cursor_present', v_next_cursor IS NOT NULL,
    'line_work_pending_after_completion', CASE WHEN v_stage_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS' THEN v_pending_line_work_exists ELSE NULL END,
    'source_rows_written', COALESCE(v_source_rows_written, 0),
    'current_source_row_count', COALESCE(v_current_source_row_count, 0),
    'source_build_run_id', v_source_build_run_id_text,
    'source_change_seq', v_source_change_seq,
    'stage_job_type', v_stage_job_type,
    'duplicate_completion', v_duplicate_completion,
    'source_build_reconciliation_applied', v_source_reconciliation_applied,
    'source_build_reconciliation_deferred', COALESCE(v_source_reconciliation_deferred, false),
    'source_build_reconciliation_deferred_reason', v_source_reconciliation_deferred_reason,
    'source_build_reconciliation', COALESCE(v_source_reconciliation_json, '{}'::jsonb),
    'certified_source_preview_applied', v_certified_publication_applied,
    'certified_source_preview', COALESCE(v_certified_publication_json, '{}'::jsonb)
  )
  || jsonb_build_object(
    'finalisation_evaluated', v_finalisation_evaluated,
    'session_ready', CASE WHEN v_finalisation_evaluated THEN v_finalisation_session_ready ELSE NULL::boolean END,
    'ready_for_draft', CASE WHEN v_finalisation_evaluated THEN v_finalisation_ready_for_draft ELSE NULL::boolean END,
    'ready_empty', CASE WHEN v_finalisation_evaluated THEN v_finalisation_ready_empty ELSE NULL::boolean END,
    'final_progress_state', CASE WHEN v_finalisation_evaluated THEN v_final_progress_state ELSE v_session_row.progress_state END,
    'blocker_codes', COALESCE(v_finalisation_blocker_codes, '[]'::jsonb),
    'draft_blocker_codes', COALESCE(v_finalisation_draft_blocker_codes, '[]'::jsonb),
    'counter_reconciliation_required', v_finalisation_counter_reconciliation_required,
    'counter_reconciliation_applied', v_finalisation_counter_reconciliation_applied,
    'counter_reconciled', v_finalisation_counter_reconciled,
    'counter_reconciliation', COALESCE(v_finalisation_counter_reconciliation_json, '{}'::jsonb),
    'actual_precheck_required', v_finalisation_actual_precheck_required,
    'actual_precheck_passed', v_finalisation_actual_precheck_passed,
    'scope_pending_job_cleared_count', COALESCE(v_scope_pending_job_cleared_count, 0),
    'continuation_scope_counter_adjusted', v_scope_continuation_counter_adjusted,
    'continuation_scope_old_status', v_scope_status_before_continuation,
    'continuation_scope_new_status', v_scope_status_after_continuation,
    'continuation_scope_pending_delta', COALESCE(v_scope_continuation_pending_delta, 0),
    'continuation_scope_ready_delta', COALESCE(v_scope_continuation_ready_delta, 0),
    'continuation_scope_failed_delta', COALESCE(v_scope_continuation_failed_delta, 0),
    'source_empty_session_progress_deferred', COALESCE(v_source_empty_session_progress_deferred, false),
    'source_empty_session_progress_deferred_reason', v_source_empty_session_progress_deferred_reason,
    'source_empty_cleanup_source_row_count', COALESCE(v_source_empty_cleanup_source_row_count, 0),
    'source_empty_cleanup_line_work_count', COALESCE(v_source_empty_cleanup_line_work_count, 0),
    'source_empty_cleanup_preview_row_count', COALESCE(v_source_empty_cleanup_preview_row_count, 0),
    'source_empty_cleanup_targeted_timesheet_count', COALESCE(v_source_empty_targeted_timesheet_count, 0),
    'bounded_terminal_targeted_timesheet_count', COALESCE(v_bounded_terminal_targeted_timesheet_count, 0),
    'bounded_terminal_source_rows_retired_count', COALESCE(v_bounded_terminal_source_rows_retired_count, 0),
    'bounded_terminal_line_work_retired_count', COALESCE(v_bounded_terminal_line_work_retired_count, 0),
    'bounded_terminal_scope_finalised_count', COALESCE(v_bounded_terminal_scope_finalised_count, 0),
    'continuation_scope_counter_deferred', COALESCE(v_continuation_scope_counter_deferred, false),
    'continuation_scope_counter_deferred_reason', v_continuation_scope_counter_deferred_reason,
    'finalisation_deferred', COALESCE(v_finalisation_deferred, false),
    'finalisation_deferred_reason', v_finalisation_deferred_reason
  );
END;
$function$;

-- pay_workbench_contract_client_dirty_fanout_chunk(uuid,jsonb,integer)
CREATE OR REPLACE FUNCTION public.pay_workbench_contract_client_dirty_fanout_chunk(p_job_id uuid, p_cursor_json jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_job_row public.banking_pay_workbench_jobs%ROWTYPE;
  v_payload_json jsonb := '{}'::jsonb;
  v_cursor_json jsonb := '{}'::jsonb;
  v_scope_kind text := '';
  v_scope_id_text text := NULL::text;
  v_scope_id uuid := NULL::uuid;
  v_specific_scope_id_text text := NULL::text;
  v_specific_scope_id uuid := NULL::uuid;
  v_payload_candidate_id_text text := NULL::text;
  v_payload_candidate_id uuid := NULL::uuid;
  v_payload_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_payload_candidate_value jsonb := NULL::jsonb;
  v_payload_candidate_value_text text := NULL::text;
  v_payload_candidate_index integer := 0;
  v_cursor_candidate_id_text text := NULL::text;
  v_cursor_candidate_id uuid := NULL::uuid;
  v_reason text := NULL::text;
  v_trigger_table text := NULL::text;
  v_trigger_op text := NULL::text;
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_candidate_ids_json jsonb := '[]'::jsonb;
  v_candidate_count integer := 0;
  v_has_more boolean := false;
  v_last_candidate_id uuid := NULL::uuid;
  v_next_cursor_json jsonb := NULL::jsonb;
  v_affected_scope_count integer := 0;
  v_affected_session_count integer := 0;
  v_jobs_queued_or_reused integer := 0;
  v_source_rows_marked_dirty_count integer := 0;
  v_gate_candidate_id uuid := NULL::uuid;
  v_gate_result jsonb := '{}'::jsonb;
  v_gate_allowed_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_gate_blocked boolean := false;
  v_gate_blocked_candidate_id uuid := NULL::uuid;
  v_gate_last_allowed_candidate_id uuid := NULL::uuid;
  v_gate_allowed_count integer := 0;
  v_invalidation_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_invalidation_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_scope_change_tx_token uuid := NULL::uuid;
  v_scope_invalidation_result jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_job_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_ID_REQUIRED'
            )::text;
  END IF;

  SELECT fanout_job.*
  INTO v_job_row
  FROM public.banking_pay_workbench_jobs AS fanout_job
  WHERE fanout_job.id = p_job_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_NOT_FOUND',
              'job_id', p_job_id::text
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_job_row.job_type, ''))) <> 'CONTRACT_CLIENT_DIRTY_FANOUT' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_TYPE_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_TYPE_INVALID',
              'job_id', v_job_row.id::text,
              'job_type', v_job_row.job_type
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_job_row.status, ''))) <> 'RUNNING' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_NOT_RUNNING'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_NOT_RUNNING',
              'job_id', v_job_row.id::text,
              'status', v_job_row.status
            )::text;
  END IF;

  IF v_job_row.scope_change_generation IS NOT NULL THEN
    PERFORM set_config(
      'cloudtms.banking_pay_inherited_scope_generation',
      v_job_row.scope_change_generation::text,
      true
    );
  END IF;

  v_payload_json := CASE
    WHEN jsonb_typeof(COALESCE(v_job_row.payload_json, '{}'::jsonb)) = 'object'
      THEN COALESCE(v_job_row.payload_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  v_cursor_json := CASE
    WHEN p_cursor_json IS NOT NULL
         AND jsonb_typeof(p_cursor_json) = 'object'
      THEN p_cursor_json
    WHEN jsonb_typeof(v_payload_json->'cursor_json') = 'object'
      THEN v_payload_json->'cursor_json'
    WHEN jsonb_typeof(v_payload_json->'cursor') = 'object'
      THEN v_payload_json->'cursor'
    ELSE '{}'::jsonb
  END;

  v_scope_kind := UPPER(BTRIM(COALESCE(v_payload_json->>'scope_kind', '')));

  IF v_scope_kind NOT IN ('CONTRACT', 'CLIENT', 'UMBRELLA') THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_KIND_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_KIND_INVALID',
              'job_id', v_job_row.id::text,
              'scope_kind', v_scope_kind
            )::text;
  END IF;

  v_scope_id_text := COALESCE(
    NULLIF(BTRIM(COALESCE(v_payload_json->>'scope_id', '')), ''),
    CASE
      WHEN v_scope_kind = 'CONTRACT'
        THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'contract_id', '')), '')
      WHEN v_scope_kind = 'CLIENT'
        THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'client_id', '')), '')
      WHEN v_scope_kind = 'UMBRELLA'
        THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'umbrella_id', '')), '')
      ELSE NULL::text
    END
  );

  IF COALESCE(v_scope_id_text, '')
     !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_ID_INVALID',
              'job_id', v_job_row.id::text,
              'scope_kind', v_scope_kind,
              'scope_id', v_scope_id_text
            )::text;
  END IF;

  v_scope_id := v_scope_id_text::uuid;

  v_specific_scope_id_text := CASE
    WHEN v_scope_kind = 'CONTRACT'
      THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'contract_id', '')), '')
    WHEN v_scope_kind = 'CLIENT'
      THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'client_id', '')), '')
    WHEN v_scope_kind = 'UMBRELLA'
      THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'umbrella_id', '')), '')
    ELSE NULL::text
  END;

  IF v_specific_scope_id_text IS NOT NULL THEN
    IF v_specific_scope_id_text
       !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_SPECIFIC_SCOPE_ID_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_DIRTY_FANOUT_SPECIFIC_SCOPE_ID_INVALID',
                'job_id', v_job_row.id::text,
                'scope_kind', v_scope_kind,
                'scope_id', v_scope_id::text,
                'specific_scope_id', v_specific_scope_id_text
              )::text;
    END IF;

    v_specific_scope_id := v_specific_scope_id_text::uuid;

    IF v_specific_scope_id IS DISTINCT FROM v_scope_id THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_PAYLOAD_CONFLICT'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_PAYLOAD_CONFLICT',
                'job_id', v_job_row.id::text,
                'scope_kind', v_scope_kind,
                'scope_id', v_scope_id::text,
                'specific_scope_id', v_specific_scope_id::text
              )::text;
    END IF;
  END IF;

  IF v_payload_json ? 'candidate_ids' THEN
    IF jsonb_typeof(v_payload_json->'candidate_ids') IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_IDS_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_IDS_INVALID',
                'job_id', v_job_row.id::text,
                'candidate_ids', v_payload_json->'candidate_ids'
              )::text;
    END IF;

    v_payload_candidate_index := 0;

    FOR v_payload_candidate_value IN
      SELECT payload_candidate.value
      FROM jsonb_array_elements(v_payload_json->'candidate_ids') AS payload_candidate(value)
    LOOP
      v_payload_candidate_index := v_payload_candidate_index + 1;
      v_payload_candidate_value_text := CASE
        WHEN jsonb_typeof(v_payload_candidate_value) = 'string'
          THEN NULLIF(BTRIM(v_payload_candidate_value #>> '{}'), '')
        ELSE NULL::text
      END;

      IF COALESCE(v_payload_candidate_value_text, '')
         !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_IDS_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_IDS_INVALID',
                  'job_id', v_job_row.id::text,
                  'candidate_index', v_payload_candidate_index,
                  'candidate_value', v_payload_candidate_value
                )::text;
      END IF;

      v_payload_candidate_ids := array_append(
        v_payload_candidate_ids,
        v_payload_candidate_value_text::uuid
      );
    END LOOP;

    SELECT COALESCE(
      array_agg(DISTINCT payload_candidate.candidate_id ORDER BY payload_candidate.candidate_id),
      ARRAY[]::uuid[]
    )
    INTO v_payload_candidate_ids
    FROM unnest(v_payload_candidate_ids) AS payload_candidate(candidate_id);
  END IF;

  v_payload_candidate_id_text := NULLIF(
    BTRIM(COALESCE(v_payload_json->>'candidate_id', '')),
    ''
  );

  IF v_payload_candidate_id_text IS NOT NULL THEN
    IF v_payload_candidate_id_text
       !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_ID_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_ID_INVALID',
                'job_id', v_job_row.id::text,
                'candidate_id', v_payload_candidate_id_text
              )::text;
    END IF;

    v_payload_candidate_id := v_payload_candidate_id_text::uuid;
  END IF;

  v_cursor_candidate_id_text := COALESCE(
    NULLIF(BTRIM(COALESCE(v_cursor_json->>'last_candidate_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_cursor_json->>'after_candidate_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_cursor_json->>'candidate_id', '')), '')
  );

  IF v_cursor_candidate_id_text IS NOT NULL THEN
    IF v_cursor_candidate_id_text
       !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_CURSOR_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_DIRTY_FANOUT_CURSOR_INVALID',
                'job_id', v_job_row.id::text,
                'cursor_json', v_cursor_json
              )::text;
    END IF;

    v_cursor_candidate_id := v_cursor_candidate_id_text::uuid;
  END IF;

  v_reason := COALESCE(
    NULLIF(BTRIM(COALESCE(v_payload_json->>'reason', '')), ''),
    'DIRTY_FANOUT:' || v_scope_kind
  );
  v_trigger_table := NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_table', '')), '');
  v_trigger_op := NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_op', '')), '');

  WITH candidate_pool AS (
    SELECT historical_candidate.candidate_id
    FROM unnest(v_payload_candidate_ids) AS historical_candidate(candidate_id)
    WHERE historical_candidate.candidate_id IS NOT NULL

    UNION

    SELECT v_payload_candidate_id AS candidate_id
    WHERE v_payload_candidate_id IS NOT NULL

    UNION

    SELECT derived_payload_candidate.candidate_id
    FROM public._pay_workbench_candidate_serial_candidate_ids(v_job_row.candidate_id, v_payload_json) AS derived_payload_candidate(candidate_id)
    WHERE derived_payload_candidate.candidate_id IS NOT NULL

    UNION

    SELECT contract_scope.candidate_id
    FROM public.contracts AS contract_scope
    WHERE v_scope_kind = 'CONTRACT'
      AND contract_scope.id = v_scope_id
      AND contract_scope.candidate_id IS NOT NULL

    UNION

    SELECT client_contract.candidate_id
    FROM public.contracts AS client_contract
    WHERE v_scope_kind = 'CLIENT'
      AND client_contract.client_id = v_scope_id
      AND client_contract.candidate_id IS NOT NULL

    UNION

    SELECT umbrella_candidate.id
    FROM public.candidates AS umbrella_candidate
    WHERE v_scope_kind = 'UMBRELLA'
      AND umbrella_candidate.umbrella_id = v_scope_id
  ),
  ordered_candidates AS (
    SELECT candidate_pool.candidate_id,
           ROW_NUMBER() OVER (ORDER BY candidate_pool.candidate_id) AS candidate_ordinal
    FROM candidate_pool
    WHERE candidate_pool.candidate_id IS NOT NULL
      AND (
        v_cursor_candidate_id IS NULL
        OR candidate_pool.candidate_id > v_cursor_candidate_id
      )
    ORDER BY candidate_pool.candidate_id
    LIMIT (v_limit + 1)
  ),
  selected_candidates AS (
    SELECT ordered_candidates.candidate_id,
           ordered_candidates.candidate_ordinal
    FROM ordered_candidates
    WHERE ordered_candidates.candidate_ordinal <= v_limit
  )
  SELECT
    COALESCE(
      array_agg(
        selected_candidates.candidate_id
        ORDER BY selected_candidates.candidate_id
      ),
      ARRAY[]::uuid[]
    ),
    COALESCE(COUNT(*)::integer, 0),
    EXISTS (
      SELECT 1
      FROM ordered_candidates AS extra_candidate
      WHERE extra_candidate.candidate_ordinal > v_limit
    ),
    (
      SELECT last_selected.candidate_id
      FROM selected_candidates AS last_selected
      ORDER BY last_selected.candidate_id DESC
      LIMIT 1
    )
  INTO
    v_candidate_ids,
    v_candidate_count,
    v_has_more,
    v_last_candidate_id
  FROM selected_candidates;

  v_candidate_ids_json := COALESCE(to_jsonb(v_candidate_ids), '[]'::jsonb);

  IF v_has_more AND v_last_candidate_id IS NOT NULL THEN
    v_next_cursor_json := jsonb_build_object(
      'last_candidate_id', v_last_candidate_id::text,
      'scope_kind', v_scope_kind,
      'scope_id', v_scope_id::text
    );
  ELSE
    v_next_cursor_json := NULL::jsonb;
  END IF;

  IF COALESCE(v_candidate_count, 0) = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'job_id', v_job_row.id::text,
      'job_type', v_job_row.job_type,
      'scope_kind', v_scope_kind,
      'scope_id', v_scope_id::text,
      'reason', v_reason,
      'limit', v_limit,
      'cursor_json', v_cursor_json,
      'candidate_ids', '[]'::jsonb,
      'candidate_count', 0,
      'processed_count', 0,
      'affected_scope_count', 0,
      'affected_session_count', 0,
      'enqueued_count', 0,
      'has_more', false,
      'next_cursor', NULL::jsonb,
      'next_cursor_json', NULL::jsonb,
      'candidate_line_calculation_performed', false
    );
  END IF;

  v_gate_allowed_candidate_ids := ARRAY[]::uuid[];
  v_gate_blocked := false;
  v_gate_blocked_candidate_id := NULL::uuid;
  v_gate_last_allowed_candidate_id := NULL::uuid;

  FOREACH v_gate_candidate_id IN ARRAY v_candidate_ids
  LOOP
    v_gate_result := public._pay_workbench_candidate_serial_try_gate(
      p_job_id => v_job_row.id,
      p_candidate_id => v_gate_candidate_id,
      p_job_type => v_job_row.job_type,
      p_payload_json => v_payload_json || jsonb_build_object(
        'candidate_id', v_gate_candidate_id::text,
        'candidate_serial_candidate_id', v_gate_candidate_id::text,
        'candidate_serial_key', public._pay_workbench_candidate_serial_key(v_gate_candidate_id),
        'fanout_scope_kind', v_scope_kind,
        'fanout_scope_id', v_scope_id::text,
        'cursor_json', v_cursor_json
      ),
      p_reason => 'CANDIDATE_SERIAL_CONTRACT_CLIENT_FANOUT_GATE'
    );

    IF lower(BTRIM(COALESCE(v_gate_result->>'blocked', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       OR lower(BTRIM(COALESCE(v_gate_result->>'allowed', 'true'))) IN ('false', 'f', '0', 'no', 'n', 'off') THEN
      v_gate_blocked := true;
      v_gate_blocked_candidate_id := v_gate_candidate_id;
      EXIT;
    END IF;

    v_gate_allowed_candidate_ids := array_append(v_gate_allowed_candidate_ids, v_gate_candidate_id);
    v_gate_last_allowed_candidate_id := v_gate_candidate_id;
  END LOOP;

  IF v_gate_blocked IS TRUE THEN
    SELECT COALESCE(array_agg(DISTINCT allowed_candidate.candidate_id ORDER BY allowed_candidate.candidate_id), ARRAY[]::uuid[])
    INTO v_candidate_ids
    FROM unnest(COALESCE(v_gate_allowed_candidate_ids, ARRAY[]::uuid[])) AS allowed_candidate(candidate_id)
    WHERE allowed_candidate.candidate_id IS NOT NULL;

    v_candidate_count := COALESCE(array_length(v_candidate_ids, 1), 0);
    v_candidate_ids_json := COALESCE(to_jsonb(v_candidate_ids), '[]'::jsonb);
    v_has_more := true;
    v_last_candidate_id := v_gate_last_allowed_candidate_id;

    v_next_cursor_json := jsonb_strip_nulls(
      CASE
        WHEN v_gate_last_allowed_candidate_id IS NOT NULL THEN
          jsonb_build_object(
            'last_candidate_id', v_gate_last_allowed_candidate_id::text,
            'scope_kind', v_scope_kind,
            'scope_id', v_scope_id::text
          )
        ELSE
          COALESCE(v_cursor_json, '{}'::jsonb)
          || jsonb_build_object(
            'scope_kind', v_scope_kind,
            'scope_id', v_scope_id::text
          )
      END
      || jsonb_build_object(
        'candidate_serial_blocked_candidate_id', v_gate_blocked_candidate_id::text,
        'candidate_serial_blocked_at_utc', v_now::text,
        'candidate_serial_wait_reason', COALESCE(v_gate_result->>'reason', 'CANDIDATE_SERIAL_CONTRACT_CLIENT_FANOUT_DELAYED'),
        'candidate_serial_delayed', true
      )
    );

    PERFORM public._pay_workbench_candidate_serial_audit(
      'CANDIDATE_SERIAL_CONTRACT_CLIENT_FANOUT_DELAYED',
      v_job_row.id,
      v_gate_blocked_candidate_id,
      COALESCE(v_gate_result, '{}'::jsonb) || jsonb_build_object(
        'job_type', v_job_row.job_type,
        'scope_kind', v_scope_kind,
        'scope_id', v_scope_id::text,
        'cursor_json', v_cursor_json,
        'next_cursor_json', v_next_cursor_json,
        'allowed_before_block_count', COALESCE(v_candidate_count, 0),
        'blocked_candidate_preserved', true,
        'candidate_mutation_skipped_for_blocked_candidate', true
      ),
      'CANDIDATE_SERIAL_CONTRACT_CLIENT_FANOUT_DELAYED',
      NULL::uuid
    );

    IF COALESCE(v_candidate_count, 0) = 0 THEN
      UPDATE public.banking_pay_workbench_jobs AS delayed_job
      SET payload_json = public._pay_workbench_dirty_payload_merge(
            COALESCE(delayed_job.payload_json, '{}'::jsonb),
            jsonb_build_object(
              'candidate_serial_delayed', true,
              'candidate_serial_blocked_candidate_id', v_gate_blocked_candidate_id::text,
              'candidate_serial_wait_reason', COALESCE(v_gate_result->>'reason', 'CANDIDATE_SERIAL_CONTRACT_CLIENT_FANOUT_DELAYED'),
              'next_cursor_json', v_next_cursor_json,
              'cursor_json', v_next_cursor_json,
              'has_more', true,
              'rerun_required', true,
              'candidate_mutation_skipped_for_blocked_candidate', true,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            )
          ),
          updated_at_utc = v_now
      WHERE delayed_job.id = v_job_row.id;

      RETURN jsonb_build_object(
        'ok', true,
        'job_id', v_job_row.id::text,
        'job_type', v_job_row.job_type,
        'scope_kind', v_scope_kind,
        'scope_id', v_scope_id::text,
        'reason', v_reason,
        'limit', v_limit,
        'cursor_json', v_cursor_json,
        'candidate_ids', '[]'::jsonb,
        'candidate_count', 0,
        'processed_count', 0,
        'affected_scope_count', 0,
        'affected_session_count', 0,
        'enqueued_count', 0,
        'has_more', true,
        'next_cursor', v_next_cursor_json,
        'next_cursor_json', v_next_cursor_json,
        'candidate_serial_delayed', true,
        'candidate_serial_blocked_candidate_id', v_gate_blocked_candidate_id::text,
        'candidate_mutation_skipped_for_blocked_candidate', true,
        'candidate_line_calculation_performed', false
      );
    END IF;
  END IF;

  CREATE TEMPORARY TABLE IF NOT EXISTS pay_workbench_dirty_fanout_candidates (
    candidate_id uuid PRIMARY KEY,
    source_change_seq bigint NOT NULL DEFAULT 0
  ) ON COMMIT DROP;

  CREATE TEMPORARY TABLE IF NOT EXISTS pay_workbench_dirty_fanout_affected_scope (
    session_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    PRIMARY KEY (session_id, candidate_id)
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.pay_workbench_dirty_fanout_candidates;
  TRUNCATE TABLE pg_temp.pay_workbench_dirty_fanout_affected_scope;

  INSERT INTO pg_temp.pay_workbench_dirty_fanout_candidates (
    candidate_id,
    source_change_seq
  )
  SELECT page_candidate.candidate_id,
         0::bigint
  FROM unnest(v_candidate_ids) AS page_candidate(candidate_id)
  ON CONFLICT (candidate_id) DO NOTHING;

  WITH exact_pairs AS (
    SELECT active_state.candidate_id,active_state.timesheet_id
    FROM private.banking_pay_workbench_timesheet_scope_state active_state
    JOIN pg_temp.pay_workbench_dirty_fanout_candidates fanout_candidate
      ON fanout_candidate.candidate_id=active_state.candidate_id
    WHERE active_state.economic_state IN ('DIRTY','LIVE')
    UNION
    SELECT source_owner.candidate_id,source_owner.timesheet_id
    FROM public.banking_pay_workbench_candidate_source_lines source_owner
    JOIN pg_temp.pay_workbench_dirty_fanout_candidates fanout_candidate
      ON fanout_candidate.candidate_id=source_owner.candidate_id
    WHERE source_owner.status IN ('CURRENT','DIRTY') AND source_owner.timesheet_id IS NOT NULL
  ), complete_pairs AS (
    SELECT candidate_id,timesheet_id FROM exact_pairs
    UNION ALL
    SELECT fanout_candidate.candidate_id,NULL::uuid
    FROM pg_temp.pay_workbench_dirty_fanout_candidates fanout_candidate
    WHERE NOT EXISTS(SELECT 1 FROM exact_pairs WHERE exact_pairs.candidate_id=fanout_candidate.candidate_id)
  )
  SELECT array_agg(candidate_id ORDER BY candidate_id,timesheet_id NULLS FIRST),
         array_agg(timesheet_id ORDER BY candidate_id,timesheet_id NULLS FIRST)
  INTO v_invalidation_candidate_ids,v_invalidation_timesheet_ids
  FROM complete_pairs;

  IF COALESCE(v_job_row.payload_json->>'scope_change_tx_token','')
     ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_scope_change_tx_token:=(v_job_row.payload_json->>'scope_change_tx_token')::uuid;
  END IF;
  v_scope_invalidation_result:=private.pay_workbench_scope_invalidate_v1(
    COALESCE(v_invalidation_candidate_ids,ARRAY[]::uuid[]),
    COALESCE(v_invalidation_timesheet_ids,ARRAY[]::uuid[]),
    v_reason,v_scope_change_tx_token,
    COALESCE(v_job_row.payload_json,'{}'::jsonb)||jsonb_build_object(
      'skip_candidate_job_enqueue',true,'inherited_scope_generation',v_job_row.scope_change_generation)
  );

  WITH bumped_counters AS (
    INSERT INTO public.app_change_counters AS candidate_counter (
      entity_key,
      seq,
      updated_at
    )
    SELECT
      'pay_candidate:' || fanout_candidate.candidate_id::text,
      1::bigint,
      v_now
    FROM pg_temp.pay_workbench_dirty_fanout_candidates AS fanout_candidate
    ON CONFLICT (entity_key)
    DO UPDATE
    SET seq = candidate_counter.seq + 1,
        updated_at = v_now
    RETURNING candidate_counter.entity_key,
              candidate_counter.seq
  )
  UPDATE pg_temp.pay_workbench_dirty_fanout_candidates AS fanout_candidate
  SET source_change_seq = bumped_counter.seq
  FROM bumped_counters AS bumped_counter
  WHERE bumped_counter.entity_key = 'pay_candidate:' || fanout_candidate.candidate_id::text;

  WITH candidate_open_scope AS (
    SELECT
      scope_row.session_id,
      scope_row.candidate_id,
      open_session.actor_user_id,
      open_session.pay_date,
      MAX(open_session.pay_date) OVER (
        PARTITION BY open_session.actor_user_id
      ) AS latest_actor_open_pay_date
    FROM public.banking_pay_workbench_session_scope AS scope_row
    JOIN public.banking_pay_workbench_sessions AS open_session
      ON open_session.id = scope_row.session_id
    JOIN pg_temp.pay_workbench_dirty_fanout_candidates AS fanout_candidate
      ON fanout_candidate.candidate_id = scope_row.candidate_id
    WHERE open_session.status = 'OPEN'
      AND open_session.discarded_at_utc IS NULL
  ),
  affected_scope AS (
    UPDATE public.banking_pay_workbench_session_scope AS scope_update
    SET status = 'SOURCE_BUILD_PENDING',
        dirty = true,
        error_json = NULL::jsonb,
        updated_at_utc = v_now
    FROM candidate_open_scope AS target_scope
    WHERE target_scope.session_id = scope_update.session_id
      AND target_scope.candidate_id = scope_update.candidate_id
      AND target_scope.pay_date = target_scope.latest_actor_open_pay_date
    RETURNING scope_update.session_id,
              scope_update.candidate_id
  )
  INSERT INTO pg_temp.pay_workbench_dirty_fanout_affected_scope (
    session_id,
    candidate_id
  )
  SELECT affected_scope.session_id,
         affected_scope.candidate_id
  FROM affected_scope
  ON CONFLICT (session_id, candidate_id) DO NOTHING;

  GET DIAGNOSTICS v_affected_scope_count = ROW_COUNT;

  WITH affected_session_summary AS (
    SELECT
      affected_scope.session_id,
      COUNT(*)::integer AS affected_candidate_count,
      (array_agg(
        affected_scope.candidate_id
        ORDER BY affected_scope.candidate_id DESC
      ))[1] AS last_candidate_id
    FROM pg_temp.pay_workbench_dirty_fanout_affected_scope AS affected_scope
    GROUP BY affected_scope.session_id
  ),
  updated_sessions AS (
    UPDATE public.banking_pay_workbench_sessions AS session_update
    SET progress_state = 'DIRTY',
        scope_pending_count = GREATEST(
          COALESCE(session_update.scope_pending_count, 0),
          1
        ),
        candidate_sample_rows_json = jsonb_build_array(
          jsonb_build_object(
            'candidate_id', affected_summary.last_candidate_id::text,
            'status', 'SOURCE_BUILD_PENDING',
            'reason', v_reason
          )
        ),
        progress_json = jsonb_strip_nulls(
          COALESCE(session_update.progress_json, '{}'::jsonb)
          || jsonb_build_object(
            'last_dirty_candidate_id', affected_summary.last_candidate_id::text,
            'last_dirty_reason', v_reason,
            'last_dirty_at_utc', v_now::text,
            'last_dirty_fanout_job_id', v_job_row.id::text,
            'last_dirty_fanout_scope_kind', v_scope_kind,
            'last_dirty_fanout_scope_id', v_scope_id::text,
            'last_dirty_fanout_candidate_count', affected_summary.affected_candidate_count
          )
        ),
        progress_counter_version = COALESCE(session_update.progress_counter_version, 0)
          + affected_summary.affected_candidate_count,
        progress_updated_at_utc = v_now,
        updated_at_utc = v_now
    FROM affected_session_summary AS affected_summary
    WHERE session_update.id = affected_summary.session_id
    RETURNING session_update.id
  )
  SELECT COUNT(*)::integer
  INTO v_affected_session_count
  FROM updated_sessions;

  WITH dirtied_source_rows AS (
    UPDATE public.banking_pay_workbench_candidate_source_lines AS source_line
    SET status = 'DIRTY',
        source_row_json = jsonb_strip_nulls(
          COALESCE(source_line.source_row_json, '{}'::jsonb)
          || jsonb_build_object(
            'dirty_reason', v_reason,
            'dirty_fanout_job_id', v_job_row.id::text,
            'dirty_fanout_scope_kind', v_scope_kind,
            'dirty_fanout_scope_id', v_scope_id::text,
            'dirty_trigger_table', v_trigger_table,
            'dirty_trigger_operation', v_trigger_op,
            'dirty_at_utc', v_now::text
          )
        ),
        updated_at_utc = v_now
    FROM pg_temp.pay_workbench_dirty_fanout_affected_scope AS affected_scope
    WHERE source_line.session_id = affected_scope.session_id
      AND source_line.candidate_id = affected_scope.candidate_id
      AND source_line.status = 'CURRENT'
    RETURNING source_line.id
  )
  SELECT COUNT(*)::integer
  INTO v_source_rows_marked_dirty_count
  FROM dirtied_source_rows;

  WITH upserted_jobs AS (
    INSERT INTO public.banking_pay_workbench_jobs AS refresh_job (
      job_type,
      status,
      priority,
      run_at_utc,
      attempt_count,
      max_attempts,
      dedupe_key,
      snapshot_run_id,
      session_id,
      candidate_id,
      payload_json,
      economic_build_id,
      private_stage,
      private_cursor_kind,
      private_cursor_json,
      private_stage_version,
      created_at_utc,
      updated_at_utc,
      started_at_utc,
      completed_at_utc,
      failed_at_utc,
      last_error_json
    )
    SELECT
      'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'QUEUED',
      44,
      v_now,
      0,
      8,
      'WORKBENCH_CANDIDATE_SOURCE_BUILD:'
        || open_session.id::text
        || ':'
        || affected_scope.candidate_id::text
        || ':v'
        || COALESCE(open_session.version, 0)::text
        || ':s'
        || COALESCE(fanout_candidate.source_change_seq, 0)::text
        || ':snapshot:'
        || open_session.source_snapshot_run_id::text
        || ':signature:'
        || md5(COALESCE(open_session.session_signature, ''))
        || ':source_build:'
        || source_build_identity.source_build_run_id::text
        || ':cursor:START',
      open_session.source_snapshot_run_id,
      open_session.id,
      affected_scope.candidate_id,
      jsonb_build_object(
        'trigger_table', v_trigger_table,
        'trigger_operation', v_trigger_op,
        'trigger_op', v_trigger_op,
        'scope_kind', 'CANDIDATE',
        'scope_id', affected_scope.candidate_id::text,
        'candidate_id', affected_scope.candidate_id::text,
        'reason', v_reason,
        'source_change_seq', fanout_candidate.source_change_seq,
        'source_change_sequence', fanout_candidate.source_change_seq,
        'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
        'candidate_serial_key', public._pay_workbench_candidate_serial_key(affected_scope.candidate_id),
        'candidate_serial_candidate_id', affected_scope.candidate_id::text,
        'candidate_serial_active_chain_id', COALESCE(NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'candidate_serial_active_chain_id', '')), ''), v_job_row.id::text),
        'candidate_serial_source_job_id', v_job_row.id::text,
        'candidate_serial_reason', 'CANDIDATE_SERIAL_FANOUT_SOURCE_BUILD_QUEUED'
      )
      || jsonb_build_object(
        'targeted_timesheet_ids', '[]'::jsonb,
        'linked_timesheet_ids', '[]'::jsonb,
        'session_id', open_session.id::text,
        'source_session_id', open_session.id::text,
        'session_version', COALESCE(open_session.version, 0),
        'session_signature', open_session.session_signature,
        'snapshot_run_id', open_session.source_snapshot_run_id::text,
        'source_snapshot_run_id', open_session.source_snapshot_run_id::text,
        'source_build_run_id', source_build_identity.source_build_run_id::text,
        'source_fanout_job_id', v_job_row.id::text
      )
      || jsonb_build_object(
        'fanout_scope_kind', v_scope_kind,
        'fanout_scope_id', v_scope_id::text,
        'job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'canonical_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'source_build_required', true,
        'line_work_required', true,
        'line_work_only', false,
        'source_build_action', 'BUILD_SOURCE',
        'line_work_action', 'SOURCE_BUILD',
        'pay_channel_scope', COALESCE(NULLIF(UPPER(BTRIM(COALESCE(open_session.filters_json->>'pay_channel_scope', open_session.filters_json#>>'{filters,pay_channel_scope}', ''))), ''), 'ALL'),
        'limit', v_limit,
        'source_build_limit', v_limit,
        'source_rows_marked_dirty_count', COALESCE(v_source_rows_marked_dirty_count, 0)
      ),
      NULL::uuid,
      'BUILD_INITIALISE',
      'BUILD_INITIALISE',
      '{}'::jsonb,
      1,
      v_now,
      v_now,
      NULL::timestamptz,
      NULL::timestamptz,
      NULL::timestamptz,
      NULL::jsonb
    FROM pg_temp.pay_workbench_dirty_fanout_affected_scope AS affected_scope
    JOIN public.banking_pay_workbench_sessions AS open_session
      ON open_session.id = affected_scope.session_id
     AND open_session.status = 'OPEN'
     AND open_session.discarded_at_utc IS NULL
    JOIN pg_temp.pay_workbench_dirty_fanout_candidates AS fanout_candidate
      ON fanout_candidate.candidate_id = affected_scope.candidate_id
    CROSS JOIN LATERAL (
      SELECT md5(concat_ws(':',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        open_session.source_snapshot_run_id::text,
        open_session.id::text,
        affected_scope.candidate_id::text,
        COALESCE(open_session.version, 0)::text,
        COALESCE(fanout_candidate.source_change_seq, 0)::text,
        'CANDIDATE_FULL_LIVE',
        v_scope_kind,
        v_scope_id::text,
        v_reason
      )) AS source_build_hash
    ) AS source_build_hash
    CROSS JOIN LATERAL (
      SELECT (
        substr(source_build_hash.source_build_hash, 1, 8) || '-' ||
        substr(source_build_hash.source_build_hash, 9, 4) || '-' ||
        substr(source_build_hash.source_build_hash, 13, 4) || '-' ||
        substr(source_build_hash.source_build_hash, 17, 4) || '-' ||
        substr(source_build_hash.source_build_hash, 21, 12)
      )::uuid AS source_build_run_id
    ) AS source_build_identity
    ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
    DO UPDATE
    SET priority = LEAST(refresh_job.priority, EXCLUDED.priority),
        run_at_utc = LEAST(refresh_job.run_at_utc, EXCLUDED.run_at_utc),
        payload_json = public._pay_workbench_merge_targeted_scope_payload(
          COALESCE(refresh_job.payload_json, '{}'::jsonb),
          COALESCE(EXCLUDED.payload_json, '{}'::jsonb)
        ),
        updated_at_utc = v_now
    RETURNING refresh_job.id
  )
  SELECT COUNT(*)::integer
  INTO v_jobs_queued_or_reused
  FROM upserted_jobs;

  RETURN jsonb_build_object(
      'ok', true,
      'job_id', v_job_row.id::text,
      'job_type', v_job_row.job_type,
      'scope_kind', v_scope_kind,
      'scope_id', v_scope_id::text,
      'reason', v_reason,
      'trigger_table', v_trigger_table,
      'trigger_op', v_trigger_op,
      'limit', v_limit,
      'cursor_json', v_cursor_json,
      'candidate_ids', v_candidate_ids_json,
      'candidate_count', COALESCE(v_candidate_count, 0),
      'processed_count', COALESCE(v_candidate_count, 0),
      'affected_scope_count', COALESCE(v_affected_scope_count, 0),
      'affected_session_count', COALESCE(v_affected_session_count, 0),
      'enqueued_count', COALESCE(v_jobs_queued_or_reused, 0),
      'jobs_queued_or_reused', COALESCE(v_jobs_queued_or_reused, 0),
      'source_rows_marked_dirty_count', COALESCE(v_source_rows_marked_dirty_count, 0),
      'first_stage_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    )
    || jsonb_build_object(
      'has_more', COALESCE(v_has_more, false),
      'candidate_serial_delayed', COALESCE(v_gate_blocked, false),
      'candidate_serial_blocked_candidate_id', CASE WHEN v_gate_blocked_candidate_id IS NULL THEN NULL::text ELSE v_gate_blocked_candidate_id::text END,
      'next_cursor', v_next_cursor_json,
      'next_cursor_json', v_next_cursor_json,
      'last_candidate_id', CASE
        WHEN v_last_candidate_id IS NULL THEN NULL::text
        ELSE v_last_candidate_id::text
      END,
      'candidate_line_calculation_performed', false,
      'session_created', false,
      'rpc_fanout_performed', false
    );
END;
$function$;

-- pay_workbench_contract_version_get_v1()
CREATE OR REPLACE FUNCTION public.pay_workbench_contract_version_get_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_projection_contract jsonb :=
    public._pay_workbench_candidate_projection_contract();
  v_selection_carry_table_oid oid :=
    to_regclass(
      'public.banking_pay_workbench_selection_carry_registrations'
    );
  v_canonical_contract_version text;
  v_targeted_family_materialisation_version text;
BEGIN
  v_canonical_contract_version := CASE
    WHEN v_selection_carry_table_oid IS NOT NULL
      AND to_regprocedure(
        'public.pay_workbench_session_carry_forward_preview_selections_v1(uuid,uuid,jsonb)'
      ) IS NOT NULL
      AND EXISTS (
        SELECT 1
        FROM pg_catalog.pg_trigger AS trigger_row
        WHERE trigger_row.tgrelid =
          'public.banking_pay_workbench_preview_rows'::regclass
          AND trigger_row.tgname =
            'trg_banking_pay_preview_selection_carry_apply'
          AND trigger_row.tgenabled <> 'D'
          AND trigger_row.tgisinternal IS FALSE
      )
      THEN v_projection_contract ->> 'canonical_correction_carrier_version'
    ELSE 'BANKING_PAY_CANONICAL_CORRECTION_CARRIER_INCOMPLETE'
  END;

  v_projection_contract := jsonb_set(
    v_projection_contract,
    '{canonical_correction_carrier_version}',
    to_jsonb(v_canonical_contract_version),
    true
  );

  v_targeted_family_materialisation_version := CASE
    WHEN to_regprocedure(
      'public._pay_workbench_refresh_dependency_closure_v1(uuid,uuid[],uuid[],uuid[],integer,integer)'
    ) IS NOT NULL
      THEN v_projection_contract ->> 'targeted_family_materialisation_version'
    ELSE 'BANKING_PAY_TARGETED_FAMILY_MATERIALISATION_INCOMPLETE'
  END;

  v_projection_contract := jsonb_set(
    v_projection_contract,
    '{targeted_family_materialisation_version}',
    to_jsonb(v_targeted_family_materialisation_version),
    true
  );

  RETURN jsonb_build_object(
    'ok', true,
    'contract_version', 'BANKING_PAY_WORKBENCH_DB_V1',
    'canonical_correction_carrier_version',
      v_canonical_contract_version,
    'targeted_family_materialisation_version',
      v_targeted_family_materialisation_version,
    'candidate_projection_contract', v_projection_contract
  );
END;
$function$;

-- pay_workbench_delta_refresh_classify_v1(uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_workbench_delta_refresh_classify_v1(p_session_id uuid, p_candidate_id uuid, p_payload_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payload_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope_row public.banking_pay_workbench_session_scope%ROWTYPE;
  v_settings_json jsonb := '{}'::jsonb;
  v_now timestamptz := now();
  v_trigger_table text := lower(BTRIM(COALESCE(v_payload_json->>'trigger_table', v_payload_json->>'table_name', '')));
  v_trigger_operation text := upper(BTRIM(COALESCE(v_payload_json->>'trigger_operation', v_payload_json->>'trigger_op', v_payload_json->>'operation', '')));
  v_dirty_reason text := NULLIF(BTRIM(COALESCE(v_payload_json->>'dirty_reason', v_payload_json->>'refresh_reason', v_payload_json->>'reason', '')), '');
  v_refresh_scope_kind text := upper(BTRIM(COALESCE(v_payload_json->>'refresh_scope_kind', v_payload_json->>'scope_kind', '')));
  v_pay_channel_scope text := upper(BTRIM(COALESCE(v_payload_json->>'pay_channel_scope', 'ALL')));
  v_operation_type text := upper(BTRIM(COALESCE(v_payload_json->>'operation_type', v_payload_json->>'mutation_type', '')));
  v_requested_projection_mode text := upper(BTRIM(COALESCE(v_payload_json->>'projection_mode', '')));
  v_old_row_json jsonb := CASE WHEN jsonb_typeof(v_payload_json->'old_row_json') = 'object' THEN COALESCE(v_payload_json->'old_row_json', '{}'::jsonb) ELSE '{}'::jsonb END;
  v_new_row_json jsonb := CASE WHEN jsonb_typeof(v_payload_json->'new_row_json') = 'object' THEN COALESCE(v_payload_json->'new_row_json', '{}'::jsonb) ELSE '{}'::jsonb END;
  v_targeted_json jsonb := COALESCE(v_payload_json->'targeted_timesheet_ids', v_payload_json->'changed_timesheet_ids', '[]'::jsonb);
  v_linked_json jsonb := COALESCE(v_payload_json->'linked_timesheet_ids', '[]'::jsonb);
  v_finance_case_json jsonb := COALESCE(v_payload_json->'finance_case_ids', '[]'::jsonb);
  v_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_payload_linked_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_resolved_family_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_linked_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_all_affected_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_finance_case_ids uuid[] := ARRAY[]::uuid[];
  v_invalid_targeted_uuid_count integer := 0;
  v_invalid_linked_uuid_count integer := 0;
  v_invalid_finance_case_uuid_count integer := 0;
  v_targeted_count integer := 0;
  v_valid_targeted_owner_count integer := 0;
  v_valid_linked_owner_count integer := 0;
  v_linked_count integer := 0;
  v_source_change_seq bigint := 0;
  v_payload_session_version bigint := NULL::bigint;
  v_session_version_mismatch boolean := false;
  v_source_snapshot_run_id uuid := NULL::uuid;
  v_source_snapshot_run_id_text text := NULL::text;
  v_pay_batch_id uuid := NULL::uuid;
  v_pay_batch_id_text text := NULL::text;
  v_force_legacy boolean := false;
  v_force_broad_legacy boolean := false;
  v_payload_shadow_mode boolean := false;
  v_delta_refresh_enabled boolean := false;
  v_delta_shadow_mode boolean := true;
  v_enable_normal_timesheet boolean := false;
  v_enable_readiness_only boolean := false;
  v_enable_reservation_only boolean := false;
  v_fallback_on_mismatch boolean := true;
  v_clone_rebase_enabled boolean := false;
  v_has_finance_case boolean := false;
  v_has_pay_advance boolean := false;
  v_has_timesheet_advance boolean := false;
  v_has_loan boolean := false;
  v_has_overpayment boolean := false;
  v_has_underpayment boolean := false;
  v_has_manual_debt_adjustment boolean := false;
  v_has_manual_credit_adjustment boolean := false;
  v_has_manual_debit boolean := false;
  v_has_repayment boolean := false;
  v_has_case_resolution boolean := false;
  v_has_one_off_bank_account boolean := false;
  v_ts_adjustment_as_advance boolean := false;
  v_ts_adjustment_credit boolean := false;
  v_ts_adjustment_debit boolean := false;
  v_has_pay_method_switch boolean := false;
  v_has_umbrella_entity_change boolean := false;
  v_has_bank_routing_change boolean := false;
  v_has_contract_client_dirty boolean := false;
  v_has_unknown_trigger boolean := false;
  v_candidate_pay_method text := NULL::text;
  v_candidate_umbrella_id uuid := NULL::uuid;
  v_candidate_bank_details_hash text := NULL::text;
  v_old_pay_method text := NULL::text;
  v_new_pay_method text := NULL::text;
  v_old_umbrella_id_text text := NULL::text;
  v_new_umbrella_id_text text := NULL::text;
  v_old_bank_details_hash text := NULL::text;
  v_new_bank_details_hash text := NULL::text;
  v_bank_routing_unchanged boolean := false;
  v_payee_route_unchanged boolean := false;
  v_existing_preview_key_count integer := 0;
  v_existing_preview_key_missing_count integer := 0;
  v_would_fast_path_allowed boolean := false;
  v_fast_path_allowed boolean := false;
  v_resolved_job_type text := 'WORKBENCH_CANDIDATE_SOURCE_BUILD';
  v_projection_mode text := 'LEGACY';
  v_projection_class text := 'UNKNOWN_TRIGGER';
  v_scope_status text := 'SOURCE_BUILD_PENDING';
  v_routing_decision text := 'LEGACY';
  v_fallback_required boolean := true;
  v_fallback_reason text := 'UNKNOWN_TRIGGER';
  v_complexity_flags jsonb := '{}'::jsonb;
  v_readiness_identity_checked boolean := false;
  v_resolved_mode text := 'LEGACY';
  v_no_dirty_event boolean := false;
  v_timesheet_authorise_boundary_changed boolean := false;
  v_timesheet_unauthorise_boundary_changed boolean := false;
  v_payload_authorise_boundary_changed boolean := false;
  v_payload_unauthorise_boundary_changed boolean := false;
  v_timesheet_archive_boundary_changed boolean := false;
  v_timesheet_unarchive_boundary_changed boolean := false;
  v_payload_archive_boundary_changed boolean := false;
  v_payload_unarchive_boundary_changed boolean := false;
  v_payload_ordinary_no_dirty boolean := false;
  v_payload_banking_pay_dirty_required boolean := false;
  v_explicit_banking_pay_action boolean := false;
  v_patch_after_batch_enabled boolean := true;
  v_timesheet_pay_state_settlement_changed boolean := false;
  v_timesheet_pay_state_summary_changed boolean := false;
  v_timesheet_pay_state_bookkeeping_ignored boolean := false;
  v_timesheet_pay_state_noop_ignored boolean := false;
  v_timesheet_pay_state_routing_reason text := NULL::text;
  v_lifecycle_event_class text := NULL::text;
  v_lifecycle_admission jsonb := '{}'::jsonb;
  v_enable_simple_authorise boolean := false;
  v_enable_simple_unauthorise boolean := false;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  v_trigger_table := lower(BTRIM(REPLACE(COALESCE(v_trigger_table, ''), '"', '')));
  IF POSITION('.' IN v_trigger_table) > 0 THEN
    v_trigger_table := regexp_replace(v_trigger_table, '^.*\.', '');
  END IF;

  IF p_session_id IS NULL OR p_candidate_id IS NULL THEN
    v_complexity_flags := jsonb_build_object(
      'missing_session_or_candidate_input', true,
      'checked_at_utc', v_now::text
    );

    RETURN jsonb_build_object(
      'ok', true,
      'fast_path_allowed', false,
      'would_fast_path_allowed', false,
      'resolved_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'projection_mode', 'LEGACY',
      'projection_class', 'TARGET_SCOPE_MISSING',
      'routing_decision', 'LEGACY',
      'resolved_mode', 'LEGACY',
      'scope_status', 'SOURCE_BUILD_PENDING',
      'targeted_timesheet_ids', '[]'::jsonb,
      'linked_timesheet_ids', '[]'::jsonb,
      'affected_timesheet_ids', '[]'::jsonb,
      'fallback_required', true,
      'no_op', false,
      'banking_pay_dirty_required', true,
      'fallback_reason', 'SESSION_OR_SCOPE_NOT_OPEN',
      'complexity_flags', v_complexity_flags
    );
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
    AND session_row.status = 'OPEN'
    AND session_row.discarded_at_utc IS NULL;

  SELECT scope_row.*
  INTO v_scope_row
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = p_candidate_id;

  IF v_session_row.id IS NULL OR v_scope_row.id IS NULL THEN
    v_complexity_flags := jsonb_build_object(
      'session_open', v_session_row.id IS NOT NULL,
      'candidate_in_scope', v_scope_row.id IS NOT NULL,
      'checked_at_utc', v_now::text
    );

    RETURN jsonb_build_object(
      'ok', true,
      'fast_path_allowed', false,
      'would_fast_path_allowed', false,
      'resolved_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'projection_mode', 'LEGACY',
      'projection_class', 'TARGET_SCOPE_MISSING',
      'routing_decision', 'LEGACY',
      'resolved_mode', 'LEGACY',
      'scope_status', 'SOURCE_BUILD_PENDING',
      'targeted_timesheet_ids', '[]'::jsonb,
      'linked_timesheet_ids', '[]'::jsonb,
      'affected_timesheet_ids', '[]'::jsonb,
      'fallback_required', true,
      'no_op', false,
      'banking_pay_dirty_required', true,
      'fallback_reason', 'SESSION_OR_SCOPE_NOT_OPEN',
      'complexity_flags', v_complexity_flags
    );
  END IF;

  SELECT COALESCE(to_jsonb(settings_row), '{}'::jsonb)
  INTO v_settings_json
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id = 1
  LIMIT 1;

  v_delta_refresh_enabled := lower(BTRIM(COALESCE(v_settings_json->>'banking_pay_workbench_delta_refresh_enabled', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_delta_shadow_mode := lower(BTRIM(COALESCE(v_settings_json->>'banking_pay_workbench_delta_shadow_mode', 'true'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_enable_normal_timesheet := lower(BTRIM(COALESCE(v_settings_json->>'banking_pay_workbench_delta_enable_normal_timesheet', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_enable_readiness_only := lower(BTRIM(COALESCE(v_settings_json->>'banking_pay_workbench_delta_enable_readiness_only', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_enable_reservation_only := lower(BTRIM(COALESCE(v_settings_json->>'banking_pay_workbench_delta_enable_reservation_only', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_fallback_on_mismatch := lower(BTRIM(COALESCE(v_settings_json->>'banking_pay_workbench_delta_fallback_on_mismatch', 'true'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_clone_rebase_enabled := lower(BTRIM(COALESCE(v_settings_json->>'banking_pay_workbench_clone_rebase_enabled', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_patch_after_batch_enabled := lower(BTRIM(COALESCE(v_settings_json->>'banking_pay_workbench_patch_after_batch_mutation_enabled', 'true'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_enable_simple_authorise := lower(BTRIM(COALESCE(v_settings_json->>'banking_pay_workbench_delta_enable_simple_authorise','false'))) IN ('true','t','1','yes','y','on');
  v_enable_simple_unauthorise := lower(BTRIM(COALESCE(v_settings_json->>'banking_pay_workbench_delta_enable_simple_unauthorise','false'))) IN ('true','t','1','yes','y','on');

  v_force_legacy := lower(BTRIM(COALESCE(v_payload_json->>'force_legacy', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_force_broad_legacy := lower(BTRIM(COALESCE(v_payload_json->>'force_broad_legacy', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_payload_shadow_mode := lower(BTRIM(COALESCE(v_payload_json->>'shadow_mode', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_bank_routing_unchanged := lower(BTRIM(COALESCE(v_payload_json->>'bank_routing_unchanged', v_payload_json->>'bank_details_unchanged', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_payee_route_unchanged := lower(BTRIM(COALESCE(v_payload_json->>'payee_route_unchanged', v_payload_json->>'payee_identity_unchanged', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_payload_banking_pay_dirty_required := lower(BTRIM(COALESCE(v_payload_json->>'banking_pay_dirty_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_payload_ordinary_no_dirty := lower(BTRIM(COALESCE(v_payload_json->>'ordinary_timesheet_edit_save_no_dirty', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF v_trigger_table = 'timesheet_pay_state' THEN
    v_timesheet_pay_state_settlement_changed := lower(BTRIM(COALESCE(
      v_payload_json->>'timesheet_pay_state_settlement_changed',
      v_payload_json->>'pay_state_settlement_changed',
      v_payload_json->>'settled_baseline_changed',
      'false'
    ))) IN ('true', 't', '1', 'yes', 'y', 'on');

    v_timesheet_pay_state_summary_changed := lower(BTRIM(COALESCE(
      v_payload_json->>'timesheet_pay_state_summary_changed',
      v_payload_json->>'pay_state_summary_changed',
      v_payload_json->>'summary_only_changed',
      'false'
    ))) IN ('true', 't', '1', 'yes', 'y', 'on');

    v_timesheet_pay_state_bookkeeping_ignored := lower(BTRIM(COALESCE(
      v_payload_json->>'timesheet_pay_state_bookkeeping_ignored',
      v_payload_json->>'pay_state_bookkeeping_ignored',
      'false'
    ))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR UPPER(BTRIM(COALESCE(v_payload_json->>'pay_state_dirty_routing_reason', ''))) = 'TIMESHEET_PAY_STATE_BOOKKEEPING_IGNORED';

    v_timesheet_pay_state_noop_ignored := lower(BTRIM(COALESCE(
      v_payload_json->>'timesheet_pay_state_noop_ignored',
      v_payload_json->>'pay_state_noop_ignored',
      'false'
    ))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR UPPER(BTRIM(COALESCE(v_payload_json->>'pay_state_dirty_routing_reason', ''))) = 'TIMESHEET_PAY_STATE_NOOP_IGNORED';
  END IF;

  v_explicit_banking_pay_action := lower(BTRIM(COALESCE(
    v_payload_json->>'explicit_banking_pay_action',
    v_payload_json->>'banking_pay_dirty_allowed',
    v_payload_json->>'banking_pay_refresh_intended',
    v_payload_json->>'banking_pay_dirty_required',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on')
  OR UPPER(BTRIM(COALESCE(v_payload_json->>'mutation_context', v_payload_json->>'lifecycle_mutation_context', v_payload_json->>'lifecycle_context', v_operation_type, v_dirty_reason, ''))) IN (
    'TIMESHEET_AUTHORISE',
    'TIMESHEET_UNAUTHORISE',
    'AUTHORISE_TIMESHEET',
    'UNAUTHORISE_TIMESHEET',
    'BANKING_PAY_EXPLICIT_ACTION',
    'BANKING_PAY_MANUAL_REFRESH',
    'BANKING_PAY_WORKBENCH_REFRESH',
    'BANKING_PAY_DECISION_OPERATION',
    'BANKING_PAY_CASE_RESOLUTION',
    'BANKING_PAY_TIMESHEET_ADVANCE',
    'BANKING_PAY_PATCH'
  );

  IF COALESCE(v_payload_json->>'source_change_seq', v_payload_json->>'source_change_sequence', '') ~ '^-?[0-9]{1,18}$' THEN
    v_source_change_seq := COALESCE(v_payload_json->>'source_change_seq', v_payload_json->>'source_change_sequence')::bigint;
  END IF;

  IF COALESCE(v_payload_json->>'session_version', '') ~ '^[0-9]{1,18}$' THEN
    v_payload_session_version := (v_payload_json->>'session_version')::bigint;
    v_session_version_mismatch := v_payload_session_version IS DISTINCT FROM v_session_row.version;
  END IF;

  v_source_snapshot_run_id_text := NULLIF(BTRIM(COALESCE(v_payload_json->>'source_snapshot_run_id', v_payload_json->>'snapshot_run_id', '')), '');
  IF v_source_snapshot_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_source_snapshot_run_id := v_source_snapshot_run_id_text::uuid;
  END IF;

  v_pay_batch_id_text := NULLIF(BTRIM(COALESCE(v_payload_json->>'pay_batch_id', v_payload_json#>>'{batch,pay_batch_id}', '')), '');
  IF v_pay_batch_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_pay_batch_id := v_pay_batch_id_text::uuid;
  END IF;

  IF jsonb_typeof(v_targeted_json) = 'array' THEN
    SELECT COALESCE(array_agg(DISTINCT targeted_values.timesheet_id_value ORDER BY targeted_values.timesheet_id_value), ARRAY[]::uuid[]),
           COALESCE(count(*) FILTER (WHERE targeted_values.raw_value IS NOT NULL AND targeted_values.timesheet_id_value IS NULL), 0)::integer
    INTO v_targeted_timesheet_ids,
         v_invalid_targeted_uuid_count
    FROM (
      SELECT targeted_element.value #>> '{}' AS raw_value,
             CASE
               WHEN BTRIM(targeted_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                 THEN BTRIM(targeted_element.value #>> '{}')::uuid
               ELSE NULL::uuid
             END AS timesheet_id_value
      FROM jsonb_array_elements(v_targeted_json) AS targeted_element(value)
    ) AS targeted_values
    WHERE targeted_values.raw_value IS NOT NULL;
  ELSE
    v_invalid_targeted_uuid_count := CASE WHEN v_targeted_json IS NULL THEN 0 ELSE 1 END;
  END IF;

  IF jsonb_typeof(v_linked_json) = 'array' THEN
    SELECT COALESCE(array_agg(DISTINCT linked_values.timesheet_id_value ORDER BY linked_values.timesheet_id_value), ARRAY[]::uuid[]),
           COALESCE(count(*) FILTER (WHERE linked_values.raw_value IS NOT NULL AND linked_values.timesheet_id_value IS NULL), 0)::integer
    INTO v_payload_linked_timesheet_ids,
         v_invalid_linked_uuid_count
    FROM (
      SELECT linked_element.value #>> '{}' AS raw_value,
             CASE
               WHEN BTRIM(linked_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                 THEN BTRIM(linked_element.value #>> '{}')::uuid
               ELSE NULL::uuid
             END AS timesheet_id_value
      FROM jsonb_array_elements(v_linked_json) AS linked_element(value)
    ) AS linked_values
    WHERE linked_values.raw_value IS NOT NULL;
  ELSE
    v_invalid_linked_uuid_count := CASE WHEN v_linked_json IS NULL THEN 0 ELSE 1 END;
  END IF;

  IF jsonb_typeof(v_finance_case_json) = 'array' THEN
    SELECT COALESCE(array_agg(DISTINCT finance_case_values.finance_case_id_value ORDER BY finance_case_values.finance_case_id_value), ARRAY[]::uuid[]),
           COALESCE(count(*) FILTER (WHERE finance_case_values.raw_value IS NOT NULL AND finance_case_values.finance_case_id_value IS NULL), 0)::integer
    INTO v_finance_case_ids,
         v_invalid_finance_case_uuid_count
    FROM (
      SELECT finance_case_element.value #>> '{}' AS raw_value,
             CASE
               WHEN BTRIM(finance_case_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                 THEN BTRIM(finance_case_element.value #>> '{}')::uuid
               ELSE NULL::uuid
             END AS finance_case_id_value
      FROM jsonb_array_elements(v_finance_case_json) AS finance_case_element(value)
    ) AS finance_case_values
    WHERE finance_case_values.raw_value IS NOT NULL;
  ELSE
    v_invalid_finance_case_uuid_count := CASE WHEN v_finance_case_json IS NULL THEN 0 ELSE 1 END;
  END IF;

  v_targeted_count := COALESCE(array_length(v_targeted_timesheet_ids, 1), 0);

  IF v_targeted_count > 0 THEN
    SELECT COALESCE(array_agg(DISTINCT rotation_scope.family_timesheet_id ORDER BY rotation_scope.family_timesheet_id), ARRAY[]::uuid[])
    INTO v_resolved_family_timesheet_ids
    FROM public._pay_timesheet_rotation_scope(v_targeted_timesheet_ids) AS rotation_scope
    WHERE rotation_scope.family_timesheet_id IS NOT NULL;
  END IF;

  SELECT COALESCE(array_agg(DISTINCT affected_timesheets.timesheet_id_value ORDER BY affected_timesheets.timesheet_id_value), ARRAY[]::uuid[])
  INTO v_all_affected_timesheet_ids
  FROM (
    SELECT unnest(COALESCE(v_targeted_timesheet_ids, ARRAY[]::uuid[])) AS timesheet_id_value
    UNION ALL
    SELECT unnest(COALESCE(v_payload_linked_timesheet_ids, ARRAY[]::uuid[])) AS timesheet_id_value
    UNION ALL
    SELECT unnest(COALESCE(v_resolved_family_timesheet_ids, ARRAY[]::uuid[])) AS timesheet_id_value
  ) AS affected_timesheets
  WHERE affected_timesheets.timesheet_id_value IS NOT NULL;

  SELECT COALESCE(array_agg(DISTINCT linked_timesheets.timesheet_id_value ORDER BY linked_timesheets.timesheet_id_value), ARRAY[]::uuid[])
  INTO v_linked_timesheet_ids
  FROM unnest(COALESCE(v_all_affected_timesheet_ids, ARRAY[]::uuid[])) AS linked_timesheets(timesheet_id_value)
  WHERE linked_timesheets.timesheet_id_value IS NOT NULL
    AND NOT (linked_timesheets.timesheet_id_value = ANY(COALESCE(v_targeted_timesheet_ids, ARRAY[]::uuid[])));

  v_linked_count := COALESCE(array_length(v_linked_timesheet_ids, 1), 0);

  IF v_targeted_count > 0 THEN
    SELECT count(DISTINCT targeted_owner.timesheet_id_value)::integer
    INTO v_valid_targeted_owner_count
    FROM unnest(v_targeted_timesheet_ids) AS targeted_owner(timesheet_id_value)
    JOIN public.timesheets AS timesheet_row
      ON timesheet_row.timesheet_id = targeted_owner.timesheet_id_value
    LEFT JOIN public.contracts AS contract_row
      ON contract_row.id = timesheet_row.contract_id
    WHERE contract_row.candidate_id = p_candidate_id
       OR EXISTS (
         SELECT 1
         FROM public.timesheets_financials AS tsfin_owner
         WHERE tsfin_owner.timesheet_id = targeted_owner.timesheet_id_value
           AND tsfin_owner.candidate_id = p_candidate_id
       );
  END IF;

  IF v_linked_count > 0 THEN
    SELECT count(DISTINCT linked_owner.timesheet_id_value)::integer
    INTO v_valid_linked_owner_count
    FROM unnest(v_linked_timesheet_ids) AS linked_owner(timesheet_id_value)
    JOIN public.timesheets AS timesheet_row
      ON timesheet_row.timesheet_id = linked_owner.timesheet_id_value
    LEFT JOIN public.contracts AS contract_row
      ON contract_row.id = timesheet_row.contract_id
    WHERE contract_row.candidate_id = p_candidate_id
       OR EXISTS (
         SELECT 1
         FROM public.timesheets_financials AS tsfin_owner
         WHERE tsfin_owner.timesheet_id = linked_owner.timesheet_id_value
           AND tsfin_owner.candidate_id = p_candidate_id
       );
  ELSE
    v_valid_linked_owner_count := 0;
  END IF;

  IF v_trigger_table = 'timesheets' AND v_trigger_operation = 'UPDATE' THEN
    v_timesheet_authorise_boundary_changed :=
      NULLIF(BTRIM(COALESCE(v_old_row_json->>'authorised_at_server', '')), '') IS NULL
      AND NULLIF(BTRIM(COALESCE(v_new_row_json->>'authorised_at_server', '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(v_new_row_json->>'revoked_at', '')), '') IS NULL;

    v_timesheet_unauthorise_boundary_changed :=
      NULLIF(BTRIM(COALESCE(v_old_row_json->>'revoked_at', '')), '') IS NULL
      AND NULLIF(BTRIM(COALESCE(v_new_row_json->>'revoked_at', '')), '') IS NOT NULL;

    v_timesheet_archive_boundary_changed :=
      NULLIF(BTRIM(COALESCE(v_old_row_json->>'archived_at_utc', '')), '') IS NULL
      AND NULLIF(BTRIM(COALESCE(v_new_row_json->>'archived_at_utc', '')), '') IS NOT NULL;

    v_timesheet_unarchive_boundary_changed :=
      NULLIF(BTRIM(COALESCE(v_old_row_json->>'archived_at_utc', '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(v_new_row_json->>'archived_at_utc', '')), '') IS NULL;
  ELSIF v_trigger_table = 'timesheets_financials' AND v_trigger_operation = 'UPDATE' THEN
    v_timesheet_authorise_boundary_changed :=
      NULLIF(BTRIM(COALESCE(v_old_row_json->>'authorised_at_utc', '')), '') IS NULL
      AND NULLIF(BTRIM(COALESCE(v_new_row_json->>'authorised_at_utc', '')), '') IS NOT NULL;

    v_timesheet_unauthorise_boundary_changed :=
      NULLIF(BTRIM(COALESCE(v_old_row_json->>'authorised_at_utc', '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(v_new_row_json->>'authorised_at_utc', '')), '') IS NULL;
  END IF;

  v_payload_authorise_boundary_changed := lower(BTRIM(COALESCE(
    v_payload_json->>'authorise_boundary_changed',
    v_payload_json->>'timesheet_authorise_boundary_changed',
    v_payload_json#>>'{complexity_flags,authorise_boundary_changed}',
    v_payload_json#>>'{classifier_result,complexity_flags,authorise_boundary_changed}',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_payload_unauthorise_boundary_changed := lower(BTRIM(COALESCE(
    v_payload_json->>'unauthorise_boundary_changed',
    v_payload_json->>'timesheet_unauthorise_boundary_changed',
    v_payload_json#>>'{complexity_flags,unauthorise_boundary_changed}',
    v_payload_json#>>'{classifier_result,complexity_flags,unauthorise_boundary_changed}',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_payload_archive_boundary_changed := lower(BTRIM(COALESCE(
    v_payload_json->>'archive_boundary_changed',
    v_payload_json->>'timesheet_archive_boundary_changed',
    v_payload_json#>>'{complexity_flags,archive_boundary_changed}',
    v_payload_json#>>'{classifier_result,complexity_flags,archive_boundary_changed}',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_payload_unarchive_boundary_changed := lower(BTRIM(COALESCE(
    v_payload_json->>'unarchive_boundary_changed',
    v_payload_json->>'timesheet_unarchive_boundary_changed',
    v_payload_json#>>'{complexity_flags,unarchive_boundary_changed}',
    v_payload_json#>>'{classifier_result,complexity_flags,unarchive_boundary_changed}',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_timesheet_authorise_boundary_changed := v_timesheet_authorise_boundary_changed
    OR v_payload_authorise_boundary_changed
    OR UPPER(BTRIM(COALESCE(v_payload_json->>'mutation_context', v_payload_json->>'lifecycle_mutation_context', v_payload_json->>'lifecycle_context', ''))) IN ('TIMESHEET_AUTHORISE', 'AUTHORISE_TIMESHEET');
  v_timesheet_unauthorise_boundary_changed := v_timesheet_unauthorise_boundary_changed
    OR v_payload_unauthorise_boundary_changed
    OR UPPER(BTRIM(COALESCE(v_payload_json->>'mutation_context', v_payload_json->>'lifecycle_mutation_context', v_payload_json->>'lifecycle_context', ''))) IN ('TIMESHEET_UNAUTHORISE', 'UNAUTHORISE_TIMESHEET');
  v_timesheet_archive_boundary_changed := v_timesheet_archive_boundary_changed
    OR v_payload_archive_boundary_changed
    OR UPPER(BTRIM(COALESCE(v_payload_json->>'mutation_context', v_payload_json->>'lifecycle_mutation_context', v_payload_json->>'lifecycle_context', ''))) IN ('TIMESHEET_ARCHIVE', 'ARCHIVE_TIMESHEET');
  v_timesheet_unarchive_boundary_changed := v_timesheet_unarchive_boundary_changed
    OR v_payload_unarchive_boundary_changed
    OR UPPER(BTRIM(COALESCE(v_payload_json->>'mutation_context', v_payload_json->>'lifecycle_mutation_context', v_payload_json->>'lifecycle_context', ''))) IN ('TIMESHEET_UNARCHIVE', 'UNARCHIVE_TIMESHEET');

  v_explicit_banking_pay_action := v_explicit_banking_pay_action
    OR v_timesheet_authorise_boundary_changed
    OR v_timesheet_unauthorise_boundary_changed
    OR v_timesheet_archive_boundary_changed
    OR v_timesheet_unarchive_boundary_changed;

  v_no_dirty_event := v_trigger_operation = 'UPDATE'
    AND v_trigger_table IN ('timesheets', 'timesheets_financials')
    AND v_explicit_banking_pay_action IS NOT TRUE
    AND v_payload_banking_pay_dirty_required IS NOT TRUE
    AND v_timesheet_authorise_boundary_changed IS NOT TRUE
    AND v_timesheet_unauthorise_boundary_changed IS NOT TRUE
    AND v_timesheet_archive_boundary_changed IS NOT TRUE
    AND v_timesheet_unarchive_boundary_changed IS NOT TRUE;

  IF v_no_dirty_event IS TRUE THEN
    RETURN jsonb_build_object(
      'ok', true,
      'fast_path_allowed', false,
      'would_fast_path_allowed', false,
      'resolved_mode', 'BLOCKED',
      'resolved_job_type', 'NOOP',
      'projection_mode', 'BLOCKED',
      'projection_class', 'ORDINARY_TIMESHEET_EDIT_SAVE',
      'routing_decision', 'BLOCKED',
      'scope_status', 'NOOP',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'source_change_seq', COALESCE(v_source_change_seq, 0),
      'session_version', v_session_row.version,
      'payload_session_version', v_payload_session_version,
      'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
      'targeted_timesheet_ids', COALESCE(to_jsonb(v_targeted_timesheet_ids), '[]'::jsonb),
      'linked_timesheet_ids', COALESCE(to_jsonb(v_linked_timesheet_ids), '[]'::jsonb),
      'affected_timesheet_ids', COALESCE(to_jsonb(v_all_affected_timesheet_ids), '[]'::jsonb),
      'fallback_required', false,
      'fallback_reason', 'ORDINARY_TIMESHEET_EDIT_SAVE_NO_BANKING_PAY_DIRTY',
      'no_op', true,
      'banking_pay_dirty_required', false,
      'complexity_flags', jsonb_build_object(
        'ordinary_timesheet_edit_save_no_dirty', true,
        'trigger_table', v_trigger_table,
        'trigger_operation', v_trigger_operation,
        'explicit_banking_pay_action', COALESCE(v_explicit_banking_pay_action, false),
        'banking_pay_dirty_required', COALESCE(v_payload_banking_pay_dirty_required, false),
        'ordinary_timesheet_edit_save_no_dirty', COALESCE(v_payload_ordinary_no_dirty, true),
        'authorise_boundary_changed', COALESCE(v_timesheet_authorise_boundary_changed, false),
        'unauthorise_boundary_changed', COALESCE(v_timesheet_unauthorise_boundary_changed, false),
        'targeted_timesheet_count', COALESCE(v_targeted_count, 0),
        'linked_timesheet_count', COALESCE(v_linked_count, 0),
        'checked_at_utc', v_now::text
      )
    );
  END IF;

  SELECT candidate_row.pay_method,
         candidate_row.umbrella_id,
         candidate_row.bank_details_hash
  INTO v_candidate_pay_method,
       v_candidate_umbrella_id,
       v_candidate_bank_details_hash
  FROM public.candidates AS candidate_row
  WHERE candidate_row.id = p_candidate_id;

  v_old_pay_method := upper(BTRIM(COALESCE(v_payload_json->>'old_pay_method', v_old_row_json->>'pay_method', v_payload_json#>>'{old,pay_method}', '')));
  v_new_pay_method := upper(BTRIM(COALESCE(v_payload_json->>'new_pay_method', v_new_row_json->>'pay_method', v_payload_json#>>'{new,pay_method}', '')));
  v_old_umbrella_id_text := NULLIF(BTRIM(COALESCE(v_payload_json->>'old_umbrella_id', v_old_row_json->>'umbrella_id', v_payload_json#>>'{old,umbrella_id}', '')), '');
  v_new_umbrella_id_text := NULLIF(BTRIM(COALESCE(v_payload_json->>'new_umbrella_id', v_new_row_json->>'umbrella_id', v_payload_json#>>'{new,umbrella_id}', '')), '');
  v_old_bank_details_hash := NULLIF(BTRIM(COALESCE(v_payload_json->>'old_bank_details_hash', v_old_row_json->>'bank_details_hash', v_payload_json#>>'{old,bank_details_hash}', '')), '');
  v_new_bank_details_hash := NULLIF(BTRIM(COALESCE(v_payload_json->>'new_bank_details_hash', v_new_row_json->>'bank_details_hash', v_payload_json#>>'{new,bank_details_hash}', '')), '');

  v_has_pay_method_switch := v_old_pay_method IN ('PAYE', 'UMBRELLA')
                             AND v_new_pay_method IN ('PAYE', 'UMBRELLA')
                             AND v_old_pay_method IS DISTINCT FROM v_new_pay_method;
  v_has_umbrella_entity_change := v_old_umbrella_id_text IS NOT NULL
                                  AND v_new_umbrella_id_text IS NOT NULL
                                  AND v_old_umbrella_id_text IS DISTINCT FROM v_new_umbrella_id_text;
  v_has_bank_routing_change := v_old_bank_details_hash IS NOT NULL
                               AND v_new_bank_details_hash IS NOT NULL
                               AND v_old_bank_details_hash IS DISTINCT FROM v_new_bank_details_hash;

  IF lower(BTRIM(COALESCE(v_payload_json->>'pay_method_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
    v_has_pay_method_switch := true;
  END IF;

  IF lower(BTRIM(COALESCE(v_payload_json->>'umbrella_entity_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
    v_has_umbrella_entity_change := true;
  END IF;

  IF lower(BTRIM(COALESCE(v_payload_json->>'bank_routing_changed', v_payload_json->>'bank_details_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
    v_has_bank_routing_change := true;
  END IF;

  v_has_contract_client_dirty := v_trigger_table IN ('contracts', 'clients', 'client_settings', 'contract_client_dirty')
                                 OR lower(BTRIM(COALESCE(v_payload_json->>'contract_client_dirty', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF v_trigger_table IN ('umbrellas', 'umbrella_companies') THEN
    v_has_umbrella_entity_change := true;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.pay_finance_case_components AS component_row
    WHERE component_row.candidate_id = p_candidate_id
      AND component_row.closed_at_utc IS NULL
      AND (
        COALESCE(array_length(v_all_affected_timesheet_ids, 1), 0) = 0
        OR component_row.linked_timesheet_id IS NULL
        OR component_row.linked_timesheet_id = ANY(v_all_affected_timesheet_ids)
      )
  )
  INTO v_has_finance_case;

  SELECT COALESCE(bool_or(upper(COALESCE(advance_row.case_type::text, advance_row.reason::text, advance_row.advance_kind::text, '')) = 'PAYMENT_ADVANCE'
                          OR upper(COALESCE(advance_row.reason::text, '')) IN ('MANUAL_ADVANCE', 'MISSING_SHIFT')
                          OR upper(COALESCE(advance_row.advance_kind::text, '')) = 'LEGACY_ADVANCE'), false),
         COALESCE(bool_or(upper(COALESCE(advance_row.reason::text, advance_row.advance_kind::text, '')) = 'LOAN'
                          OR upper(COALESCE(advance_row.advance_kind::text, '')) = 'LOAN'), false),
         COALESCE(bool_or(upper(COALESCE(advance_row.reason::text, advance_row.advance_kind::text, advance_row.case_type::text, '')) = 'OVERPAYMENT'
                          OR upper(COALESCE(advance_row.advance_kind::text, '')) = 'OVERPAYMENT'), false),
         COALESCE(bool_or(upper(COALESCE(advance_row.reason::text, advance_row.advance_kind::text, advance_row.case_type::text, '')) = 'UNDERPAYMENT'
                          OR upper(COALESCE(advance_row.advance_kind::text, '')) = 'UNDERPAYMENT'), false),
         COALESCE(bool_or(upper(COALESCE(advance_row.case_type::text, '')) = 'MANUAL_DEBT_ADJUSTMENT'), false),
         COALESCE(bool_or(upper(COALESCE(advance_row.case_type::text, '')) = 'MANUAL_CREDIT_ADJUSTMENT'), false),
         COALESCE(bool_or(COALESCE(advance_row.outstanding_amount, 0) <> 0
                          AND upper(COALESCE(advance_row.status::text, '')) IN ('ACTIVE', 'PAUSED')), false),
         COALESCE(bool_or(COALESCE(advance_row.oneoff_bank_details_required, false) = true
                          OR upper(COALESCE(advance_row.routing_kind::text, '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'), false)
  INTO v_has_pay_advance,
       v_has_loan,
       v_has_overpayment,
       v_has_underpayment,
       v_has_manual_debt_adjustment,
       v_has_manual_credit_adjustment,
       v_has_repayment,
       v_has_one_off_bank_account
  FROM public.pay_advances AS advance_row
  WHERE advance_row.candidate_id = p_candidate_id
    AND upper(COALESCE(advance_row.status::text, '')) IN ('ACTIVE', 'PAUSED')
    AND advance_row.cleared_at_utc IS NULL
    AND advance_row.written_off_at_utc IS NULL
    AND (
      COALESCE(array_length(v_all_affected_timesheet_ids, 1), 0) = 0
      OR advance_row.linked_timesheet_id IS NULL
      OR advance_row.linked_timesheet_id = ANY(v_all_affected_timesheet_ids)
    );

  SELECT EXISTS (
    SELECT 1
    FROM public.timesheet_payment_overrides AS override_row
    WHERE override_row.candidate_id = p_candidate_id
      AND override_row.override_type = 'ADVANCE_THIS_PAYMENT'
      AND override_row.consumed_at_utc IS NULL
      AND override_row.cleared_at_utc IS NULL
      AND (
        COALESCE(array_length(v_all_affected_timesheet_ids, 1), 0) = 0
        OR override_row.timesheet_id = ANY(v_all_affected_timesheet_ids)
      )
  )
  INTO v_has_timesheet_advance;

  SELECT COALESCE(bool_or(COALESCE(adjustment_row.as_advance, false) = true), false),
         COALESCE(bool_or(COALESCE(adjustment_row.delta_pay_ex_vat, 0) > 0), false),
         COALESCE(bool_or(COALESCE(adjustment_row.delta_pay_ex_vat, 0) < 0), false)
  INTO v_ts_adjustment_as_advance,
       v_ts_adjustment_credit,
       v_ts_adjustment_debit
  FROM public.ts_pay_adjustments AS adjustment_row
  WHERE adjustment_row.candidate_id = p_candidate_id
    AND adjustment_row.paid_at_utc IS NULL
    AND (
      COALESCE(array_length(v_all_affected_timesheet_ids, 1), 0) = 0
      OR adjustment_row.timesheet_id = ANY(v_all_affected_timesheet_ids)
    );

  SELECT EXISTS (
    SELECT 1
    FROM public.banking_pay_workbench_session_case_resolutions AS resolution_row
    WHERE resolution_row.session_id = p_session_id
      AND resolution_row.candidate_id = p_candidate_id
      AND (
        COALESCE(array_length(v_all_affected_timesheet_ids, 1), 0) = 0
        OR resolution_row.timesheet_id IS NULL
        OR resolution_row.timesheet_id = ANY(v_all_affected_timesheet_ids)
      )
  )
  INTO v_has_case_resolution;

  v_has_pay_advance := COALESCE(v_has_pay_advance, false) OR COALESCE(v_ts_adjustment_as_advance, false);
  v_has_manual_credit_adjustment := COALESCE(v_has_manual_credit_adjustment, false) OR COALESCE(v_ts_adjustment_credit, false);
  v_has_manual_debit := COALESCE(v_has_manual_debit, false) OR COALESCE(v_ts_adjustment_debit, false);

  IF v_trigger_table IN ('pay_finance_case_components', 'pay_finance_cases') OR COALESCE(array_length(v_finance_case_ids, 1), 0) > 0 THEN
    v_has_finance_case := true;
  END IF;

  IF v_trigger_table = 'pay_advances' THEN
    v_has_pay_advance := true;
  END IF;

  IF v_trigger_table = 'timesheet_payment_overrides' THEN
    v_has_timesheet_advance := true;
  END IF;

  IF v_trigger_table = 'ts_pay_adjustments' THEN
    v_has_manual_credit_adjustment := true;
  END IF;

  IF v_trigger_table IN ('banking_pay_workbench_session_case_resolutions', 'case_resolution', 'case_resolutions')
     OR v_operation_type IN ('CASE_RESOLUTION', 'APPLY_CASE_RESOLUTION', 'CLEAR_CASE_RESOLUTION') THEN
    v_has_case_resolution := true;
  END IF;

  v_complexity_flags := jsonb_build_object(
    'has_finance_case', COALESCE(v_has_finance_case, false),
    'has_pay_advance', COALESCE(v_has_pay_advance, false),
    'has_timesheet_advance', COALESCE(v_has_timesheet_advance, false),
    'has_loan', COALESCE(v_has_loan, false),
    'has_overpayment', COALESCE(v_has_overpayment, false),
    'has_underpayment', COALESCE(v_has_underpayment, false),
    'has_manual_debt_adjustment', COALESCE(v_has_manual_debt_adjustment, false),
    'has_manual_credit_adjustment', COALESCE(v_has_manual_credit_adjustment, false),
    'has_manual_debit', COALESCE(v_has_manual_debit, false),
    'has_repayment', COALESCE(v_has_repayment, false),
    'has_case_resolution', COALESCE(v_has_case_resolution, false),
    'has_paye_umbrella_switch', COALESCE(v_has_pay_method_switch, false),
    'has_umbrella_entity_change', COALESCE(v_has_umbrella_entity_change, false),
    'has_bank_routing_change', COALESCE(v_has_bank_routing_change, false),
    'has_one_off_bank_account', COALESCE(v_has_one_off_bank_account, false),
    'has_timesheet_pay_adjustment_as_advance', COALESCE(v_ts_adjustment_as_advance, false),
    'has_timesheet_pay_adjustment_credit', COALESCE(v_ts_adjustment_credit, false),
    'has_timesheet_pay_adjustment_debit', COALESCE(v_ts_adjustment_debit, false),
    'has_contract_client_dirty', COALESCE(v_has_contract_client_dirty, false),
    'timesheet_pay_state_event', v_trigger_table = 'timesheet_pay_state',
    'timesheet_pay_state_settlement_changed', COALESCE(v_timesheet_pay_state_settlement_changed, false),
    'timesheet_pay_state_summary_changed', COALESCE(v_timesheet_pay_state_summary_changed, false),
    'timesheet_pay_state_bookkeeping_ignored', COALESCE(v_timesheet_pay_state_bookkeeping_ignored, false),
    'timesheet_pay_state_noop_ignored', COALESCE(v_timesheet_pay_state_noop_ignored, false),
    'timesheet_pay_state_routing_reason', v_timesheet_pay_state_routing_reason,
    'authorise_boundary_changed', COALESCE(v_timesheet_authorise_boundary_changed, false),
    'unauthorise_boundary_changed', COALESCE(v_timesheet_unauthorise_boundary_changed, false),
    'archive_boundary_changed', COALESCE(v_timesheet_archive_boundary_changed, false),
    'unarchive_boundary_changed', COALESCE(v_timesheet_unarchive_boundary_changed, false),
    'invalid_targeted_uuid_count', COALESCE(v_invalid_targeted_uuid_count, 0),
    'invalid_linked_uuid_count', COALESCE(v_invalid_linked_uuid_count, 0),
    'invalid_finance_case_uuid_count', COALESCE(v_invalid_finance_case_uuid_count, 0),
    'targeted_timesheet_count', COALESCE(v_targeted_count, 0),
    'linked_timesheet_count', COALESCE(v_linked_count, 0),
    'session_version_mismatch', COALESCE(v_session_version_mismatch, false),
    'payload_session_version', v_payload_session_version,
    'current_session_version', v_session_row.version,
    'checked_at_utc', v_now::text
  );

  IF v_session_version_mismatch IS TRUE THEN
    v_projection_class := 'BROAD_SESSION_REFRESH';
    v_fallback_reason := 'SESSION_VERSION_MISMATCH';
  ELSIF v_source_snapshot_run_id IS NOT NULL AND v_source_snapshot_run_id IS DISTINCT FROM v_session_row.source_snapshot_run_id THEN
    v_projection_class := 'BROAD_SESSION_REFRESH';
    v_fallback_reason := 'SOURCE_SNAPSHOT_RUN_MISMATCH';
  ELSIF v_force_legacy IS TRUE THEN
    v_projection_class := 'UNKNOWN_TRIGGER';
    v_fallback_reason := 'FORCE_LEGACY';
  ELSIF v_force_broad_legacy IS TRUE THEN
    v_projection_class := 'BROAD_SESSION_REFRESH';
    v_fallback_reason := 'FORCE_BROAD_LEGACY';
  ELSIF v_invalid_targeted_uuid_count > 0 OR v_invalid_linked_uuid_count > 0 OR v_invalid_finance_case_uuid_count > 0 THEN
    v_projection_class := 'TARGET_SCOPE_MISSING';
    v_fallback_reason := 'INVALID_UUID_IN_TARGET_PAYLOAD';
  ELSIF lower(BTRIM(COALESCE(v_payload_json->>'new_scope_baseline_required','false'))) IN ('true','t','1','yes','y','on') THEN
    v_projection_class := 'NEW_SESSION_SCOPE_BASELINE';
    v_fallback_reason := 'BASELINE_NOT_ESTABLISHED_FOR_NEW_SCOPE';
  ELSIF v_timesheet_authorise_boundary_changed IS TRUE
        OR v_timesheet_unauthorise_boundary_changed IS TRUE
        OR v_timesheet_archive_boundary_changed IS TRUE
        OR v_timesheet_unarchive_boundary_changed IS TRUE THEN
    v_projection_class := 'TIMESHEET_LIFECYCLE';
    IF v_timesheet_archive_boundary_changed IS TRUE OR v_timesheet_unarchive_boundary_changed IS TRUE THEN
      v_fallback_reason := CASE WHEN v_timesheet_archive_boundary_changed
        THEN 'SOURCE_BUILD_REQUIRED_TIMESHEET_ARCHIVE'
        ELSE 'SOURCE_BUILD_REQUIRED_TIMESHEET_UNARCHIVE' END;
    ELSE
      v_lifecycle_event_class := CASE WHEN v_timesheet_unauthorise_boundary_changed
        THEN 'UNAUTHORISE' ELSE 'AUTHORISE' END;
      v_lifecycle_admission := private.pay_workbench_targeted_delta_admission_v1(
        p_session_id,p_candidate_id,NULL,v_lifecycle_event_class,
        v_targeted_timesheet_ids,v_payload_linked_timesheet_ids,v_source_change_seq
      );
      v_would_fast_path_allowed := COALESCE((v_lifecycle_admission->>'admitted')::boolean,false);
      IF v_would_fast_path_allowed THEN
        v_projection_mode := 'DELTA';
        v_routing_decision := 'DELTA';
        v_scope_status := 'DELTA_REFRESH_PENDING';
        v_fallback_reason := NULL;
      ELSE
        v_fallback_reason := COALESCE(v_lifecycle_admission->>'reason',
          CASE WHEN v_lifecycle_event_class='UNAUTHORISE'
            THEN 'SOURCE_BUILD_REQUIRED_TIMESHEET_UNAUTHORISE'
            ELSE 'SOURCE_BUILD_REQUIRED_TIMESHEET_AUTHORISE' END);
      END IF;
    END IF;
  ELSIF v_has_pay_method_switch IS TRUE THEN
    v_projection_class := 'PAYE_UMBRELLA_SWITCH';
    v_fallback_reason := 'PAYE_UMBRELLA_SWITCH';
  ELSIF v_has_umbrella_entity_change IS TRUE THEN
    v_projection_class := 'UMBRELLA_ENTITY_CHANGE';
    v_fallback_reason := 'UMBRELLA_ENTITY_CHANGE';
  ELSIF v_has_bank_routing_change IS TRUE THEN
    v_projection_class := 'BANK_ROUTING_CHANGE';
    v_fallback_reason := 'BANK_ROUTING_CHANGE';
  ELSIF v_has_one_off_bank_account IS TRUE THEN
    v_projection_class := 'ONE_OFF_BANK_ACCOUNT';
    v_fallback_reason := 'ONE_OFF_BANK_ACCOUNT';
  ELSIF v_has_contract_client_dirty IS TRUE THEN
    v_projection_class := 'CONTRACT_CLIENT_DIRTY';
    v_fallback_reason := 'CONTRACT_CLIENT_OR_CLIENT_SETTINGS_DIRTY';
  ELSIF v_has_case_resolution IS TRUE THEN
    v_projection_class := 'CASE_RESOLUTION';
    v_fallback_reason := 'CASE_RESOLUTION_PRESENT_OR_CHANGED';
  ELSIF v_has_timesheet_advance IS TRUE THEN
    v_projection_class := 'TIMESHEET_ADVANCE';
    v_fallback_reason := 'TIMESHEET_ADVANCE_PRESENT';
  ELSIF v_has_loan IS TRUE THEN
    v_projection_class := 'LOAN';
    v_fallback_reason := 'LOAN_OR_REPAYMENT_PRESENT';
  ELSIF v_has_overpayment IS TRUE THEN
    v_projection_class := 'OVERPAYMENT';
    v_fallback_reason := 'OVERPAYMENT_PRESENT';
  ELSIF v_has_underpayment IS TRUE THEN
    v_projection_class := 'UNDERPAYMENT';
    v_fallback_reason := 'UNDERPAYMENT_PRESENT';
  ELSIF v_has_manual_debt_adjustment IS TRUE THEN
    v_projection_class := 'MANUAL_DEBT_ADJUSTMENT';
    v_fallback_reason := 'MANUAL_DEBT_ADJUSTMENT_PRESENT';
  ELSIF v_has_manual_credit_adjustment IS TRUE THEN
    v_projection_class := 'MANUAL_CREDIT_ADJUSTMENT';
    v_fallback_reason := 'MANUAL_CREDIT_ADJUSTMENT_PRESENT';
  ELSIF v_has_manual_debit IS TRUE THEN
    v_projection_class := 'MANUAL_DEBIT';
    v_fallback_reason := 'MANUAL_DEBIT_PRESENT';
  ELSIF v_has_repayment IS TRUE THEN
    v_projection_class := 'REPAYMENT';
    v_fallback_reason := 'REPAYMENT_PRESENT';
  ELSIF v_has_pay_advance IS TRUE THEN
    v_projection_class := 'PAY_ADVANCE';
    v_fallback_reason := 'PAY_ADVANCE_PRESENT';
  ELSIF v_has_finance_case IS TRUE THEN
    v_projection_class := 'FINANCE_CASE';
    v_fallback_reason := 'FINANCE_CASE_COMPONENTS_PRESENT';
  ELSIF v_operation_type = 'CLONE_REBASE' OR v_requested_projection_mode = 'CLONE_REBASE' THEN
    v_projection_class := 'CLONE_REBASE';
    v_projection_mode := 'CLONE_REBASE';
    v_routing_decision := 'CLONE_REBASE';
    v_scope_status := 'CLONE_REBASE_PENDING';
    v_would_fast_path_allowed := true;
    v_fallback_reason := NULL::text;
  ELSIF v_operation_type IN ('DRAFT_CREATE', 'DRAFT_DELETE', 'DRAFT_CANCEL', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLE')
        OR v_requested_projection_mode IN ('RESERVATION_PATCH', 'POST_DRAFT_OVERLAY') THEN
    SELECT count(*)::integer
    INTO v_existing_preview_key_count
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id = p_session_id
      AND preview_row.candidate_id = p_candidate_id
      AND preview_row.status = 'READY'
      AND (
        COALESCE(array_length(v_all_affected_timesheet_ids, 1), 0) = 0
        OR preview_row.timesheet_id = ANY(v_all_affected_timesheet_ids)
      );

    v_projection_class := 'RESERVATION_ONLY';
    v_projection_mode := 'RESERVATION_PATCH';
    v_routing_decision := 'PATCH_ONLY';
    v_scope_status := 'DELTA_REFRESH_PENDING';
    v_would_fast_path_allowed := v_existing_preview_key_count > 0 OR v_pay_batch_id IS NOT NULL;
    v_fallback_reason := CASE WHEN v_would_fast_path_allowed THEN NULL::text ELSE 'RESERVATION_PATCH_TARGET_NOT_FOUND' END;
  ELSIF v_trigger_table IN ('bank_name_checks', 'bank_payee_map') THEN
    IF v_bank_routing_unchanged IS NOT TRUE AND v_old_bank_details_hash IS NOT NULL AND v_new_bank_details_hash IS NOT NULL AND v_old_bank_details_hash = v_new_bank_details_hash THEN
      v_bank_routing_unchanged := true;
    END IF;

    v_readiness_identity_checked := v_bank_routing_unchanged IS TRUE OR v_payee_route_unchanged IS TRUE;

    IF v_readiness_identity_checked IS TRUE THEN
      v_projection_class := 'READINESS_ONLY';
      v_projection_mode := 'READINESS_PATCH';
      v_routing_decision := 'PATCH_ONLY';
      v_scope_status := 'DELTA_REFRESH_PENDING';
      v_would_fast_path_allowed := true;
      v_fallback_reason := NULL::text;
    ELSE
      v_projection_class := 'BANK_ROUTING_CHANGE';
      v_fallback_reason := 'READINESS_CHANGE_WITH_UNVERIFIED_BANK_ROUTING_IDENTITY';
    END IF;
  ELSIF v_trigger_table = 'timesheet_pay_state' THEN
    IF v_timesheet_pay_state_bookkeeping_ignored IS TRUE OR v_timesheet_pay_state_noop_ignored IS TRUE THEN
      v_projection_class := 'TIMESHEET_PAY_STATE_BOOKKEEPING';
      v_projection_mode := 'BLOCKED';
      v_routing_decision := 'BLOCKED';
      v_scope_status := 'NOOP';
      v_resolved_mode := 'BLOCKED';
      v_would_fast_path_allowed := false;
      v_fallback_reason := CASE
        WHEN v_timesheet_pay_state_bookkeeping_ignored IS TRUE THEN 'TIMESHEET_PAY_STATE_BOOKKEEPING_IGNORED'
        ELSE 'TIMESHEET_PAY_STATE_NOOP_IGNORED'
      END;
      v_timesheet_pay_state_routing_reason := v_fallback_reason;
    ELSIF v_targeted_count = 0 THEN
      v_projection_class := 'TARGET_SCOPE_MISSING';
      v_fallback_reason := 'TARGETED_TIMESHEET_IDS_REQUIRED_FOR_PAY_STATE';
      v_timesheet_pay_state_routing_reason := v_fallback_reason;
    ELSIF v_valid_targeted_owner_count <> v_targeted_count THEN
      v_projection_class := 'TARGET_SCOPE_MISSING';
      v_fallback_reason := 'PAY_STATE_TARGETED_TIMESHEET_NOT_IN_CANDIDATE_SCOPE';
      v_timesheet_pay_state_routing_reason := v_fallback_reason;
    ELSIF v_linked_count > 0 AND v_valid_linked_owner_count <> v_linked_count THEN
      v_projection_class := 'TARGET_SCOPE_MISSING';
      v_fallback_reason := 'PAY_STATE_LINKED_TIMESHEET_NOT_IN_CANDIDATE_SCOPE';
      v_timesheet_pay_state_routing_reason := v_fallback_reason;
    ELSE
      v_projection_class := 'TIMESHEET_PAY_STATE';
      v_fallback_reason := CASE
        WHEN v_timesheet_pay_state_settlement_changed IS TRUE THEN 'SOURCE_BUILD_REQUIRED_PAY_STATE_SETTLED_BASELINE_CHANGE'
        ELSE 'SOURCE_BUILD_REQUIRED_PAY_STATE_UNCLASSIFIED_CHANGE'
      END;
      v_timesheet_pay_state_routing_reason := v_fallback_reason;
    END IF;
  ELSIF v_trigger_table IN ('timesheets', 'timesheets_financials') THEN
    IF v_targeted_count = 0 THEN
      v_projection_class := 'TARGET_SCOPE_MISSING';
      v_fallback_reason := 'TARGETED_TIMESHEET_IDS_REQUIRED';
    ELSIF v_valid_targeted_owner_count <> v_targeted_count THEN
      v_projection_class := 'TARGET_SCOPE_MISSING';
      v_fallback_reason := 'TARGETED_TIMESHEET_NOT_IN_CANDIDATE_SCOPE';
    ELSIF v_linked_count > 0 AND v_valid_linked_owner_count <> v_linked_count THEN
      v_projection_class := 'TARGET_SCOPE_MISSING';
      v_fallback_reason := 'LINKED_TIMESHEET_NOT_IN_CANDIDATE_SCOPE';
    ELSE
      v_projection_class := 'NORMAL_TIMESHEET';
      v_projection_mode := 'DELTA';
      v_routing_decision := 'DELTA';
      v_scope_status := 'DELTA_REFRESH_PENDING';
      v_would_fast_path_allowed := true;
      v_fallback_reason := NULL::text;
    END IF;
  ELSIF v_refresh_scope_kind IN ('CANDIDATE_FULL_LIVE', 'SESSION_FULL_LIVE', 'BROAD_SESSION_REFRESH') THEN
    v_projection_class := 'BROAD_SESSION_REFRESH';
    v_fallback_reason := 'BROAD_SESSION_REFRESH';
  ELSE
    v_has_unknown_trigger := true;
    v_projection_class := 'UNKNOWN_TRIGGER';
    v_fallback_reason := 'UNKNOWN_TRIGGER';
  END IF;

  v_complexity_flags := v_complexity_flags || jsonb_build_object(
    'has_unknown_trigger', COALESCE(v_has_unknown_trigger, false),
    'delta_refresh_enabled', COALESCE(v_delta_refresh_enabled, false),
    'delta_shadow_mode', COALESCE(v_delta_shadow_mode, true),
    'payload_shadow_mode', COALESCE(v_payload_shadow_mode, false),
    'enable_normal_timesheet', COALESCE(v_enable_normal_timesheet, false),
    'enable_readiness_only', COALESCE(v_enable_readiness_only, false),
    'enable_reservation_only', COALESCE(v_enable_reservation_only, false),
    'fallback_on_mismatch', COALESCE(v_fallback_on_mismatch, true),
    'clone_rebase_enabled', COALESCE(v_clone_rebase_enabled, false),
    'bank_routing_unchanged', COALESCE(v_bank_routing_unchanged, false),
    'payee_route_unchanged', COALESCE(v_payee_route_unchanged, false),
    'readiness_identity_checked', COALESCE(v_readiness_identity_checked, false),
    'explicit_banking_pay_action', COALESCE(v_explicit_banking_pay_action, false),
    'banking_pay_dirty_required', COALESCE(v_payload_banking_pay_dirty_required, v_explicit_banking_pay_action, false),
    'ordinary_timesheet_edit_save_no_dirty', COALESCE(v_payload_ordinary_no_dirty, false),
    'authorise_boundary_changed', COALESCE(v_timesheet_authorise_boundary_changed, false),
    'unauthorise_boundary_changed', COALESCE(v_timesheet_unauthorise_boundary_changed, false),
    'archive_boundary_changed', COALESCE(v_timesheet_archive_boundary_changed, false),
    'unarchive_boundary_changed', COALESCE(v_timesheet_unarchive_boundary_changed, false),
    'timesheet_pay_state_event', v_trigger_table = 'timesheet_pay_state',
    'timesheet_pay_state_settlement_changed', COALESCE(v_timesheet_pay_state_settlement_changed, false),
    'timesheet_pay_state_summary_changed', COALESCE(v_timesheet_pay_state_summary_changed, false),
    'timesheet_pay_state_bookkeeping_ignored', COALESCE(v_timesheet_pay_state_bookkeeping_ignored, false),
    'timesheet_pay_state_noop_ignored', COALESCE(v_timesheet_pay_state_noop_ignored, false),
    'timesheet_pay_state_routing_reason', v_timesheet_pay_state_routing_reason,
    'lifecycle_event_class', v_lifecycle_event_class,
    'lifecycle_admission_reason', v_lifecycle_admission->>'reason',
    'enable_simple_authorise', v_enable_simple_authorise,
    'enable_simple_unauthorise', v_enable_simple_unauthorise,
    'trigger_table', v_trigger_table,
    'trigger_operation', v_trigger_operation
  );

  IF v_would_fast_path_allowed IS TRUE THEN
    IF v_projection_class = 'NORMAL_TIMESHEET' THEN
      IF v_delta_refresh_enabled IS NOT TRUE THEN
        v_fallback_reason := 'DELTA_REFRESH_DISABLED';
      ELSIF v_delta_shadow_mode IS TRUE OR v_payload_shadow_mode IS TRUE THEN
        v_fallback_reason := CASE WHEN v_payload_shadow_mode IS TRUE THEN 'DELTA_PAYLOAD_SHADOW_MODE' ELSE 'DELTA_SHADOW_MODE' END;
      ELSIF v_enable_normal_timesheet IS NOT TRUE THEN
        v_fallback_reason := 'NORMAL_TIMESHEET_DELTA_DISABLED';
      ELSE
        v_resolved_mode := 'DELTA';
        v_fast_path_allowed := true;
      END IF;
    ELSIF v_projection_class = 'TIMESHEET_LIFECYCLE' THEN
      IF v_delta_refresh_enabled IS NOT TRUE THEN
        v_fallback_reason := 'DELTA_REFRESH_DISABLED';
      ELSIF v_delta_shadow_mode IS TRUE OR v_payload_shadow_mode IS TRUE THEN
        v_fallback_reason := CASE WHEN v_payload_shadow_mode THEN 'DELTA_PAYLOAD_SHADOW_MODE' ELSE 'DELTA_SHADOW_MODE' END;
      ELSIF v_lifecycle_event_class='AUTHORISE' AND v_enable_simple_authorise IS NOT TRUE THEN
        v_fallback_reason := 'SIMPLE_AUTHORISE_DELTA_DISABLED';
      ELSIF v_lifecycle_event_class='UNAUTHORISE' AND v_enable_simple_unauthorise IS NOT TRUE THEN
        v_fallback_reason := 'SIMPLE_UNAUTHORISE_DELTA_DISABLED';
      ELSE
        v_resolved_mode := 'DELTA';
        v_fast_path_allowed := true;
      END IF;
    ELSIF v_projection_class = 'READINESS_ONLY' THEN
      IF v_patch_after_batch_enabled IS NOT TRUE THEN
        v_resolved_mode := 'BLOCKED';
        v_fallback_reason := 'PATCH_AFTER_BATCH_MUTATION_DISABLED';
      ELSIF v_delta_refresh_enabled IS NOT TRUE THEN
        v_resolved_mode := 'BLOCKED';
        v_fallback_reason := 'DELTA_REFRESH_DISABLED_FOR_READINESS_PATCH';
      ELSIF v_delta_shadow_mode IS TRUE OR v_payload_shadow_mode IS TRUE THEN
        v_resolved_mode := 'BLOCKED';
        v_fallback_reason := CASE WHEN v_payload_shadow_mode IS TRUE THEN 'READINESS_PATCH_PAYLOAD_SHADOW_MODE' ELSE 'READINESS_PATCH_SHADOW_MODE' END;
      ELSIF v_enable_readiness_only IS NOT TRUE THEN
        v_resolved_mode := 'BLOCKED';
        v_fallback_reason := 'READINESS_ONLY_PATCH_DISABLED';
      ELSE
        v_resolved_mode := 'PATCH_ONLY';
        v_fast_path_allowed := true;
      END IF;
    ELSIF v_projection_class = 'RESERVATION_ONLY' THEN
      IF v_patch_after_batch_enabled IS NOT TRUE THEN
        v_resolved_mode := 'BLOCKED';
        v_fallback_reason := 'PATCH_AFTER_BATCH_MUTATION_DISABLED';
      ELSIF v_delta_refresh_enabled IS NOT TRUE THEN
        v_resolved_mode := 'BLOCKED';
        v_fallback_reason := 'DELTA_REFRESH_DISABLED_FOR_RESERVATION_PATCH';
      ELSIF v_delta_shadow_mode IS TRUE OR v_payload_shadow_mode IS TRUE THEN
        v_resolved_mode := 'BLOCKED';
        v_fallback_reason := CASE WHEN v_payload_shadow_mode IS TRUE THEN 'RESERVATION_PATCH_PAYLOAD_SHADOW_MODE' ELSE 'RESERVATION_PATCH_SHADOW_MODE' END;
      ELSIF v_enable_reservation_only IS NOT TRUE THEN
        v_resolved_mode := 'BLOCKED';
        v_fallback_reason := 'RESERVATION_ONLY_PATCH_DISABLED';
      ELSE
        v_resolved_mode := 'PATCH_ONLY';
        v_fast_path_allowed := true;
      END IF;
    ELSIF v_projection_class = 'CLONE_REBASE' THEN
      IF v_clone_rebase_enabled IS TRUE THEN
        v_resolved_mode := 'CLONE_REBASE';
        v_fast_path_allowed := true;
        v_fallback_reason := NULL::text;
      ELSE
        v_resolved_mode := 'BLOCKED';
        v_fallback_reason := 'CLONE_REBASE_DISABLED';
      END IF;
    ELSE
      v_fallback_reason := COALESCE(v_fallback_reason, 'LEGACY_REQUIRED');
    END IF;
  END IF;

  IF v_fast_path_allowed IS TRUE AND v_resolved_mode = 'DELTA' THEN
    v_resolved_job_type := 'WORKBENCH_CANDIDATE_DELTA_REFRESH';
    v_projection_mode := 'DELTA';
    v_routing_decision := 'DELTA';
    v_scope_status := 'DELTA_REFRESH_PENDING';
    v_fallback_required := false;
    v_fallback_reason := NULL::text;
  ELSIF v_fast_path_allowed IS TRUE AND v_resolved_mode = 'PATCH_ONLY' THEN
    v_resolved_job_type := 'PATCH_ONLY';
    v_routing_decision := 'PATCH_ONLY';
    v_scope_status := 'READY';
    v_fallback_required := false;
    v_fallback_reason := NULL::text;
  ELSIF v_fast_path_allowed IS TRUE AND v_resolved_mode = 'CLONE_REBASE' THEN
    v_resolved_job_type := 'WORKBENCH_SESSION_CLONE_REBASE';
    v_projection_mode := 'CLONE_REBASE';
    v_routing_decision := 'CLONE_REBASE';
    v_scope_status := 'CLONE_REBASING';
    v_fallback_required := false;
    v_fallback_reason := NULL::text;
  ELSIF v_resolved_mode = 'BLOCKED' THEN
    v_resolved_job_type := 'NOOP';
    v_projection_mode := 'BLOCKED';
    v_routing_decision := 'BLOCKED';
    v_scope_status := 'NOOP';
    v_fallback_required := false;
    IF v_fallback_reason IS NULL THEN
      v_fallback_reason := 'BLOCKED_BY_CLASSIFIER';
    END IF;
  ELSE
    v_resolved_mode := 'LEGACY';
    v_resolved_job_type := 'WORKBENCH_CANDIDATE_SOURCE_BUILD';
    v_projection_mode := 'LEGACY';
    v_scope_status := 'SOURCE_BUILD_PENDING';
    v_routing_decision := 'LEGACY';
    v_fallback_required := true;
    IF v_fallback_reason IS NULL THEN
      v_fallback_reason := 'LEGACY_REQUIRED';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'fast_path_allowed', COALESCE(v_fast_path_allowed, false),
    'would_fast_path_allowed', COALESCE(v_would_fast_path_allowed, false),
    'resolved_mode', v_resolved_mode,
    'resolved_job_type', v_resolved_job_type,
    'projection_mode', v_projection_mode,
    'projection_class', v_projection_class,
    'routing_decision', v_routing_decision,
    'scope_status', v_scope_status,
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'source_change_seq', COALESCE(v_source_change_seq, 0),
    'session_version', v_session_row.version,
    'payload_session_version', v_payload_session_version,
    'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
    'targeted_timesheet_ids', COALESCE(to_jsonb(v_targeted_timesheet_ids), '[]'::jsonb),
    'linked_timesheet_ids', COALESCE(to_jsonb(v_linked_timesheet_ids), '[]'::jsonb),
    'affected_timesheet_ids', COALESCE(to_jsonb(v_all_affected_timesheet_ids), '[]'::jsonb),
    'fallback_required', COALESCE(v_fallback_required, true),
    'no_op', v_resolved_mode = 'BLOCKED',
    'banking_pay_dirty_required', v_resolved_mode IN ('DELTA', 'PATCH_ONLY', 'LEGACY'),
    'fallback_reason', v_fallback_reason,
    'complexity_flags', COALESCE(v_complexity_flags, '{}'::jsonb)
  );
END;
$function$;

